create table "informix".si_actecon 
  (
    actividad char(3) not null ,
    casfim char(8),
    nombre char(40) not null ,
    user_insert char(30) 
        default user,
    fecha_insert date 
        default today,
    primary key (actividad) 
  ) extent size 32 next size 32 lock mode row;

revoke all on "informix".si_actecon from "public" as "informix";

