create procedure "informix".grabazonacallexasignar( pTipo smallint, pCiudad smallint, pClave integer,
                                                    pDesc char(30), pRumbo char(40) )
returning char(5);

------------------------------------------------------------------------
--Autor: Julio Cesar Polanco Inzunza
--Actividad: Graba en si_catzonas las zonas que tenian clave por asignar
--Graba en si_catcalles las calles que tenian clave por asignar
--Si el SP regresa 001 es que no tiene los parametros requeridos para grabar
------------------------------------------------------------------------

--Declaracion de variables
define chrcodret			char(5);

define intcodret            integer;
define intnumzona           integer;
define intnumcobranza       smallint;
define intcentro            integer;

--debug flag
--set debug file to "/tmp/grabazonacallexasignar.out";
--trace on;

begin

	on exception set intcodret
		if intcodret <> 0 then
			let chrcodret=intcodret;
			return chrcodret;
		end if;
    end exception;

    let chrcodret = '000';
    let intcodret = 0;
    let intnumzona = 0;
    let intnumcobranza = 0;
    let intcentro = 0;

    if pTipo = 1 then

        if pCiudad is not null and pClave is not null
           and pDesc is not null and pRumbo is not null then

            select nvl(numerocobranzas,0), nvl(centro,0) into intnumcobranza, intcentro
            from bdinteg: si_catzonas
            where numerociudad = pCiudad and numerocolonia =
            ( select min(numerocolonia) from bdinteg:si_catzonas
            where nvl(numerocobranzas, 0) > 0 and nvl(centro, 0) > 0 and nvl(jefegrupozona, 0) > 0
            and nvl(supervisorzona, 0) > 0 and numerociudad = pCiudad and numerocolonia <> 8000 );

            insert into si_catzonas ( numerociudad,numerocolonia,nombrezona,rumbozona,numerocobranzas,centro )
            values ( pCiudad,pClave,pDesc,pRumbo,intnumcobranza,intcentro );
        else
            let chrcodret = '001';
        end if;

    elif pTipo = 2 then

        if pClave is not null and pDesc is not null then
            insert into si_catcalles ( numerocalle,nombrecalle ) values ( pClave,pDesc );
        else
            let chrcodret = '001';
        end if;

    end if;

return chrcodret;
end;

end procedure;

create procedure "informix".consultarp(pempresa char(3),
					pnumcte char(20))

returning char(5),char(60),char(10),char(80),char(20),char(30);

define codret char(5);
define vparentesco           char(10);
define vnombre               char(60);
define vdireccion            char(80);
define vtelefono             char(20);
define vexiste               char(2);
define vnum_credito          char(20);
define vactividad            char(30);

define sql_err integer;
let sql_err = 0;
LET vparentesco = "";
LET vnombre     = "";
LET vdireccion  = "";
LET vtelefono   = "";
LET vexiste     = 0;
let vnum_credito = trim(pnumcte);
let vactividad = "";

set isolation to dirty read;
let codret = "000";
begin
   on exception set sql_err
      if sql_err <> 0 then
         let codret = sql_err;
        return codret,vnombre,vparentesco,vdireccion,
               vtelefono,vactividad;
      end if;
   end exception;




 select valor into vexiste from si_param
 where cod_param = "7";
 -- Saca el Cliente del Credito

 select numcte into pnumcte
 from bdicred:sd_maecred
 where num_credito = vnum_credito;
let vexiste = 0;
foreach
  select parentesco,nombre,direccion,telefono,actividad
   into vparentesco,vnombre,vdireccion,vtelefono,vactividad
   from si_refper
   where numcte = pnumcte
   order by 1
   if vparentesco is null then
      let vparentesco = 0;
   end if;
   if vnombre is null then
      let vnombre = " ";
   end if;
   if vdireccion is null then
      let vdireccion = " ";
   end if;
   if vtelefono is null then
      let vtelefono = " ";
   end if;
   return codret,vnombre,vparentesco,vdireccion,
               vtelefono,vactividad
          with resume;
end foreach;
end
end procedure;

CREATE PROCEDURE "informix".act_encab(pempresa        varchar ,
                            pusuario        varchar ,
                            pfecha_hoy      date    ,
                            pcontrol_poliza decimal )


RETURNING varchar(10),varchar(80);

-- ***************************************************************************
-- Declaracion de variables
-- ***************************************************************************

DEFINE v_moneda       varchar(2);
DEFINE v_descripcion  varchar(40);
DEFINE v_monto        decimal(18,2);
DEFINE v_naturaleza   varchar(1);
DEFINE p_cod_ret      varchar(8);
DEFINE p_mensaje      VARCHAR(80);

BEGIN
-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
    LET p_cod_ret = '00000';
    LET p_mensaje = 'movimiento de sucursal';
-- ***************************************************************************
-- Valida los parametros de entrada
-- ***************************************************************************
   IF pusuario    IS NULL OR
      pfecha_hoy  IS NULL THEN
      LET p_cod_ret = '110';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END IF;
   -- Extrae los montos capturados en la poliza

    FOREACH SELECT moneda,
                   naturaleza,
                   SUM(monto)
            INTO   v_moneda,
                   v_naturaleza,
                   v_monto
            FROM   bdicont:co_detpol
            WHERE  usuario = pusuario
            AND    fecha_captura=pfecha_hoy
            AND    control_poliza = pcontrol_poliza
            AND    empresa = pempresa
            GROUP BY moneda, naturaleza
            
            IF v_monto IS NULL THEN
               LET v_monto = 0;
            END IF;

            IF v_moneda IS NULL THEN
               LET v_moneda = '00';
            END IF;

            IF v_naturaleza = 'D' THEN
               UPDATE bdicont:co_poliza
               SET    cifra_control   = v_monto,
                      capturado_cargo = v_monto,
                      descripcion     = v_descripcion
               WHERE  empresa = pempresa
               AND    usuario = pusuario
               AND    control_poliza = pcontrol_poliza
               AND    fecha_captura = pfecha_hoy
               AND    moneda = v_moneda;
           END IF;
           
           IF v_naturaleza = 'C' THEN
              UPDATE bdicont:co_poliza
              SET cifra_control   = v_monto,
                  capturado_abono = v_monto,
                  descripcion     = v_descripcion
              WHERE  empresa        = pempresa
              AND    usuario        = pusuario
              AND    control_poliza = pcontrol_poliza
              AND    fecha_captura  = pfecha_hoy
              AND    moneda         = v_moneda;
           END IF;

   END FOREACH;

END;

   BEGIN

   ON EXCEPTION
           --SIPK_MENSAJES.SP_TRAE_MENSAJE (SQLCODE, SQLERRM, P_COD_RET, P_MENSAJE);
           RETURN p_cod_ret,p_mensaje;
   END EXCEPTION;

   END;
   
RETURN p_cod_ret,p_mensaje;

END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".actividad(p_actividad  varchar)
RETURNING  varchar,varchar,varchar;

--*****************************************************************************
--   DECLARACION DE VARIABLES
--*****************************************************************************

DEFINE  v_actividad varchar(3);
DEFINE  v_nombre    varchar(40);
DEFINE  p_cod_ret   varchar(8);
DEFINE  p_mensaje   varchar(80);

--*****************************************************************************

BEGIN

 LET p_cod_ret ='000';
 LET p_mensaje ='Proceso terminado exitosamente';

        SELECT actividad, nombre
        INTO   v_actividad,
               v_nombre
        FROM   si_actecon
        WHERE  actividad = p_actividad;

        BEGIN

        ON EXCEPTION in (100)
             LET v_nombre = NULL;
             LET p_cod_ret = '001';
             LET p_mensaje = 'Faltan parametros';
             RETURN v_nombre,p_cod_ret,p_mensaje;
        END EXCEPTION;
        
        END;
END;

RETURN v_nombre,p_cod_ret,p_mensaje;

END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".alta_nip( pcve_emp        varchar,
                           pcve_regional   varchar,
                           pcve_plaza      varchar,
                           pcve_suc        varchar,
                           pnumcte         varchar,
                           pnip            varchar,
                           pext_promotor   varchar,
                           pservicio       varchar,
                           pusuario        varchar)

RETURNING VARCHAR,VARCHAR;

   -- **************************************************************************
   --  variables
   -- **************************************************************************
DEFINE   vempresa         varchar(3);
DEFINE   vregional        varchar(3);
DEFINE   vplaza           varchar(3);
DEFINE   vsucursal        varchar(4);
DEFINE   vnumcte          varchar(20);
DEFINE   vservicio        varchar(3);
DEFINE   vusuario         varchar(8);
DEFINE   vfecha_alta      date;
DEFINE   vfecha_modIF     date;
DEFINE   vhora_modIF      datetime hour to second;
DEFINE   vstatus          varchar(1);
DEFINE   sql_err          integer;
DEFINE   ISam_err         integer;
DEFINE   p_cod_ret        varchar(8);
DEFINE   P_mensaje        varchar(80);

BEGIN
   -- **************************************************************************
   -- inicializa variables
   -- **************************************************************************
  LET vempresa     = '';
  LET vregional    = '';
  LET vplaza       = '';
  LET vsucursal    = '';
  LET vnumcte      = '';
  LET vservicio    = '';
  LET vusuario     = '';
  LET vfecha_alta  = '';
  LET vfecha_modIF = '';
  LET vhora_modIF  = '';
  LET vstatus      = 'A';
  LET sql_err      = 0;
  LET ISam_err     = 0;
  LET p_cod_ret    = '000';
         -- **************************************************************************
         -- verifica parametros de entrada
         -- **************************************************************************
   IF pcve_emp         IS null or
      pcve_regional    IS null or
      pcve_plaza       IS null or
      pcve_suc         IS null or
      pnumcte          IS null or
      pnip             IS null or
      pext_promotor    IS null or
      pservicio        IS null or
      pusuario         IS null THEN
      LET p_cod_ret = '110';
--      GOTO FIN;
   END IF;
   -- **************************************************************************
   -- valida la clave de la empresa
   -- **************************************************************************
   BEGIN
      SELECT empresa INTO vempresa
      FROM si_empresas
      WHERE empresa = pcve_emp;
      --EXCEPTION
      --WHEN no_data_found THEN
      --     null;
      --WHEN too_many_rows THEN
      --     null;
   END;

   IF vempresa IS null THEN
      LET p_cod_ret = '122';
--      GOTO FIN;
   END if;
   -- **************************************************************************
   -- valida la clave de la regional
   -- **************************************************************************
   BEGIN
      SELECT regional INTO vregional
      FROM   si_regional
      WHERE  regional = pcve_regional;
      --EXCEPTION
      --WHEN no_data_found THEN
       --    null;
      --WHEN too_many_rows THEN
      --     null;
   END;
   IF vregional IS NULL THEN
      LET p_cod_ret = '109';
--      GOTO FIN;
   END IF;
   -- **************************************************************************
   -- valida la clave de la plaza
   -- **************************************************************************
   BEGIN
      SELECT plaza INTO vplaza
      FROM si_plazas
      WHERE plaza=pcve_plaza
      AND regional = pcve_regional;
      --EXCEPTION
      --WHEN no_data_found THEN
      --     null;
      --WHEN too_many_rows THEN
      --     null;
   END;
   IF vplaza IS null THEN
      LET p_cod_ret = '003';
   --   GOTO FIN;
   END if;
   -- **************************************************************************
   -- valida la clave de la sucursal
   -- **************************************************************************
   BEGIN
      SELECT sucursal INTO vsucursal
      FROM si_sucursales
      WHERE sucursal = pcve_suc;
     -- EXCEPTION
      --WHEN no_data_found THEN
     --      null;
     -- WHEN too_many_rows THEN
      --     null;
   END;
   IF vsucursal IS null THEN
      LET p_cod_ret = '111';
--      GOTO FIN;
   END if;
   -- **************************************************************************
   -- valida el no. del cliente
   -- **************************************************************************
   BEGIN
      SELECT numcte INTO vnumcte
      FROM si_cliente
      WHERE numcte = pnumcte;
--      EXCEPTION
--      WHEN no_data_found THEN
--           null;
--      WHEN too_many_rows THEN
--           null;
   END;
   IF vnumcte IS null THEN
      LET p_cod_ret = '119';
    --  GOTO FIN;
   END if;
   -- **************************************************************************
   -- valida la clave del servicio
   -- **************************************************************************
   BEGIN
      SELECT cve_servicio INTO vservicio
      FROM si_servicios
      WHERE cve_servicio = pservicio;
--      EXCEPTION
--      WHEN no_data_found THEN
--           null;
--      WHEN too_many_rows THEN
--           null;
   END;
   IF vservicio IS null THEN
      LET p_cod_ret = '131';
--      GOTO FIN;
   END if;
   -- **************************************************************************
   -- valida la clave del usuario
   -- **************************************************************************
   --   SELECT ejecutivo INTO vusuario
   --   FROM si_ejecut
   --   WHERE ejecutivo = pusuario
   --   AND cod_emp = pcve_emp
   --   AND sucursal = pcve_suc;
   --   IF vusuario IS null THEN
   --      p_cod_ret:='002';
   --      RETURN p_cod_ret;
   --   END if;
   -- **************************************************************************
   -- da de alta el registro con los parametros proporcionados.
   -- **************************************************************************
   -- valida que no exista un registro previo con status de (a)ctivo o (i)nactivo.
   BEGIN
      SELECT numcte INTO vnumcte
      FROM si_servcte
      WHERE numcte = pnumcte
      AND cve_servicio = pservicio
      AND (status='A' OR status='I');
      --EXCEPTION
      --WHEN no_data_found THEN
      --     null;
      --WHEN too_many_rows THEN
      --     null;
   END;
   IF vnumcte IS NOT null THEN
      LET p_cod_ret = '136';
--      GOTO FIN;
   ELSE
      INSERT INTO si_servcte (
                  CVE_EMP                ,
                  NUMCTE                 ,
                  CVE_SERVICIO           ,
                  FECHA_ALTA             ,
                  REGIONAL               ,
                  PLAZA                  ,
                  SUCURSAL               ,
                  NIP                    ,
                  EXT_PROMOTOR           ,
                  FECHA_MODIFICACION     ,
                  HORA_MODIFICACION      ,
                  USUARIO                ,
                  STATUS                 )
      VALUES (pcve_emp, pnumcte,  pcve_regional, pcve_plaza,
             pcve_suc, pnip, pext_promotor,
             pservicio, vfecha_alta, vfecha_modif, vhora_modif,
             pusuario, vstatus);

   END if;
end;
--   <<FIN>>
--     NULL;
--
---   EXCEPTION
--   WHEN OTHERS THEN
---        SIPK_MENSAJES.SP_TRAE_MENSAJE (SQLCODE, SQLERRM, P_COD_RET, P_MENSAJE);


RETURN p_cod_ret,p_mensaje;
END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".cambio_nip( pcve_emp        varchar,
                             pcve_regional   varchar,
                             pcve_plaza      varchar,
                             pcve_suc        varchar,
                             pnumcte         varchar,
                             pnip_ant        varchar,
                             pnip_nvo        varchar,
                             pext_promotor   varchar,
                             pservicio       varchar,
                             pusuario        varchar)

RETURNING varchar,varchar;
   -- **************************************************************************
   --  variables
   -- **************************************************************************
DEFINE   vempresa         varchar(3);
DEFINE   vregional        varchar(3);
DEFINE   vplaza           varchar(3);
DEFINE   vsucursal        varchar(4);
DEFINE   vnumcte          varchar(20);
DEFINE   vservicio        varchar(3);
DEFINE   vusuario         varchar(8);
DEFINE   vfecha_alta      date;
DEFINE   vfecha_modIF     date;
DEFINE   vhora_modIF      date;      /*datetime hour to second;*/
DEFINE   vstatus          varchar(1);
DEFINE   vextension       varchar(4);
DEFINE   p_cod_ret        varchar(8);
DEFINE   p_mensaje        varchar(80);

BEGIN
   -- **************************************************************************
   -- inicializa variables
   -- **************************************************************************
  LET vempresa                 = '';
  LET vregional                = '';
  LET vplaza                   = '';
  LET vsucursal                = '';
  LET vnumcte                  = '';
  LET vservicio                = '';
  LET vusuario                 = '';
  LET vfecha_alta              = '';
  LET vfecha_modIF             = '';
  LET vhora_modIF              = '';
  LET vstatus                  = '';
  LET p_cod_ret                = '000';
  LET vextension               = '';
   -- **************************************************************************
   -- verifica parametros de entrada
   -- **************************************************************************
   IF pcve_emp         IS null or
      pcve_regional    IS null or
      pcve_plaza       IS null or
      pcve_suc         IS null or
      pnumcte          IS null or
      pnip_ant         IS null or
      pnip_nvo         IS null or
      pext_promotor    IS null or
      pservicio        IS null or
      pusuario         IS null THEN
      LET p_cod_ret = '110';
   END if;
   -- **************************************************************************
   -- valida la clave de la empresa
   -- **************************************************************************
   BEGIN
      SELECT empresa
      INTO vempresa
      FROM si_empresas
      WHERE empresa = pcve_emp;
   END;
   IF vempresa IS null THEN
      LET p_cod_ret = '122';
   END if;
   -- **************************************************************************
   -- valida la clave de la regional
   -- **************************************************************************
   BEGIN
      SELECT regional
      INTO vregional
      FROM si_regional
      WHERE regional = pcve_regional;
   END;
   
   IF vregional IS null THEN
      LET p_cod_ret ='109';
   END if;
   -- **************************************************************************
   -- valida la clave de la plaza
   -- **************************************************************************
   BEGIN
      SELECT plaza
      INTO vplaza
      FROM si_plazas
      WHERE plaza=pcve_plaza
      AND regional = pcve_regional;
   END;
   
   IF vplaza IS null THEN
      LET p_cod_ret ='003';
   END if;
   -- **************************************************************************
   -- valida la clave de la sucursal
   -- **************************************************************************
   BEGIN
      SELECT sucursal
      INTO vsucursal
      FROM si_sucursales
      WHERE sucursal = pcve_suc;
   END;
   
   IF vsucursal IS null THEN
      LET p_cod_ret ='111';
   END if;
   -- **************************************************************************
   -- valida el no. del cliente
   -- **************************************************************************
   BEGIN
      SELECT numcte
      INTO vnumcte
      FROM si_cliente
      WHERE numcte = pnumcte;
   END;
   
   IF vnumcte IS null THEN
      LET p_cod_ret ='119';
   END if;
   -- **************************************************************************
   -- valida el status del nip
   -- **************************************************************************
   --   SELECT status INTO vstatus
   --   FROM si_status_serv
   --   WHERE status = pstatus;
   --   IF vstatus IS null THEN
   --      p_cod_ret:='130';
   --      RETURN p_cod_ret;
   --   END if;
   -- **************************************************************************
   -- valida la clave del servicio
   -- **************************************************************************
   BEGIN
      SELECT cve_servicio
      INTO vservicio
      FROM si_servicios
      WHERE cve_servicio = pservicio;
   END;

   IF vservicio IS null THEN
      LET p_cod_ret ='131';
   END if;
   -- **************************************************************************
   -- valida la clave del usuario
   -- **************************************************************************
   BEGIN
      SELECT ejecutivo
      INTO vusuario
      FROM si_ejecut
      WHERE ejecutivo = pusuario
      AND empresa  = pcve_emp
      AND sucursal = pcve_suc;
   END;
   
   IF vusuario IS null THEN
      LET p_cod_ret ='002';
   END if;
   -- **************************************************************************
   -- valida el nip
   -- **************************************************************************
   EXECUTE PROCEDURE valida_nip(pcve_emp, pcve_suc, pnumcte, pnip_ant,
                                pservicio, pusuario,p_cod_ret,
                                p_mensaje ,vextension);

--   IF p_cod_ret <> '000' THEN
--      RETURN p_cod_ret;
--   END if;

   -- **************************************************************************
   -- cambiar el nip para el servicio dado.
   -- **************************************************************************
   --verifica que exista el registro que se va a actualizar y que tenga status de (a)ctivo.
   BEGIN
      SELECT numcte, status
      INTO vnumcte, vstatus
      FROM si_servcte
      WHERE numcte = pnumcte
      AND cve_servicio = pservicio;
   END;
   --   AND status='A';
   IF vnumcte IS null THEN
      LET p_cod_ret ='134';
   ELSE
      IF vstatus = 'A' THEN
         -- actualiza status del nip
         UPDATE si_servcte
         SET    nip  = pnip_nvo ,
                ext_promotor  = pext_promotor  ,
                fecha_modificacion  = vfecha_modIF ,
                hora_modificacion = vhora_modif
         WHERE numcte = pnumcte
         AND cve_servicio = pservicio;
--         GOTO FIN;
      ELSE
         IF vstatus = 'I' THEN
            LET p_cod_ret ='137';
--            GOTO FIN;
         ELSE
            LET p_cod_ret ='138';
--            GOTO FIN;
         END if;
      END if;
   END if;
--   <<FIN>>
--     NULL;
--   EXCEPTION
--   WHEN OTHERS THEN
--        SIPK_MENSAJES.SP_TRAE_MENSAJE (SQLCODE, SQLERRM, P_COD_RET, P_MENSAJE);
END;
RETURN p_cod_ret, p_mensaje;
END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".cambio_status_nip( pcve_emp        varchar,
                                    pcve_regional   varchar,
                                    pcve_plaza      varchar,
                                    pcve_suc        varchar,
                                    pnumcte         varchar,
                                    pstatus         varchar,
                                    pservicio       varchar,
                                    pusuario        varchar)

RETURNING varchar,varchar;

   -- **************************************************************************
   --  variables
   -- **************************************************************************
DEFINE   vempresa         varchar(3);
DEFINE   vregional        varchar(3);
DEFINE   vplaza           varchar(3);
DEFINE   vsucursal        varchar(4);
DEFINE   vnumcte          varchar(20);
DEFINE   vservicio        varchar(3);
DEFINE   vusuario         varchar(8);
DEFINE   vfecha_alta      date;
DEFINE   vfecha_modIF     date;
DEFINE   vhora_modIF      date;      /*datetime hour to second;*/
DEFINE   vstatus          varchar(1);
DEFINE   sql_err          integer;
DEFINE   ISam_err         integer;
DEFINE   p_cod_ret        varchar(8);
DEFINE   p_mensaje        varchar(80);

BEGIN
   -- **************************************************************************
   -- inicializa variables
   -- **************************************************************************
   LET   vempresa     = '';
   LET   vregional    = '';
   LET   vplaza       = '';
   LET   vsucursal    = '';
   LET   vnumcte      = '';
   LET   vservicio    = '';
   LET   vusuario     = '';
   LET   vfecha_alta  = '';
   LET   vfecha_modIF = '';
   LET   vhora_modIF  = '';
   LET   vstatus      = '';
   LET   p_mensaje    = '';
   LET   p_cod_ret    = '000';
   -- **************************************************************************
   -- verifica parametros de entrada
   -- **************************************************************************
   IF pcve_emp         IS null or
      pcve_regional    IS null or
      pcve_plaza       IS null or
      pcve_suc         IS null or
      pnumcte          IS null or
      pstatus          IS null or
      pservicio        IS null or
      pusuario         IS null THEN
      LET p_cod_ret = '110';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;

   -- **************************************************************************
   -- valida la clave de la empresa
   -- **************************************************************************
   BEGIN
      SELECT empresa
      INTO vempresa
      FROM si_empresas
      WHERE empresa = pcve_emp;
   END;
   
   IF vempresa IS null THEN
      LET p_cod_ret = '122';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida la clave de la regional
   -- **************************************************************************
   BEGIN
      SELECT regional
      INTO vregional
      FROM si_regional
      WHERE regional = pcve_regional;
   END;
   
   IF vregional IS null THEN
      LET p_cod_ret = '109';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida la clave de la plaza
   -- **************************************************************************
   BEGIN
      SELECT plaza
      INTO vplaza
      FROM   si_plazas
      WHERE  plaza    = pcve_plaza
      AND    regional = pcve_regional;
   END;
   
   IF vplaza IS null THEN
      LET p_cod_ret = '003';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida la clave de la sucursal
   -- **************************************************************************
   BEGIN
      SELECT sucursal
      INTO vsucursal
      FROM si_sucursales
      WHERE sucursal = pcve_suc;
   END;
   
   IF vsucursal IS null THEN
      LET p_cod_ret = '111';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida el no. del cliente
   -- **************************************************************************
   BEGIN
      SELECT numcte
      INTO vnumcte
      FROM si_cliente
      WHERE numcte = pnumcte;
   END;
   
   IF vnumcte IS null THEN
      LET p_cod_ret = '119';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida el status del nip
   -- **************************************************************************
   BEGIN
      SELECT status INTO vstatus
      FROM si_status_serv
      WHERE status = pstatus;
   END;
   
   IF vstatus IS null THEN
      LET p_cod_ret = '130';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida la clave del servicio
   -- **************************************************************************
   BEGIN
      SELECT cve_servicio
      INTO vservicio
      FROM si_servicios
      WHERE cve_servicio = pservicio;
   END;

   IF vservicio IS null THEN
      LET p_cod_ret = '131';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- valida la clave del usuario
   -- **************************************************************************
   BEGIN
      SELECT ejecutivo INTO vusuario
      FROM   si_ejecut
      WHERE  ejecutivo = pusuario
      AND    empresa   = pcve_emp
      AND    sucursal  = pcve_suc;
   END;

   IF vusuario IS null THEN
      LET p_cod_ret = '002';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   END if;
   -- **************************************************************************
   -- cambiar el status del nip para el servicio dado.
   -- **************************************************************************
   --verifica que exista el registro que se va a actualizar.
   BEGIN
      SELECT numcte, status INTO vnumcte, vstatus
      FROM si_servcte
      WHERE numcte = pnumcte
      AND cve_servicio = pservicio;
   END;

   IF vnumcte IS null THEN
      LET p_cod_ret = '134';
      LET p_mensaje = '';
      RETURN p_cod_ret,p_mensaje;
   ELSE
      IF vstatus != 'C' THEN
         -- actualiza status del nip
         UPDATE si_servcte
         SET    status = pstatus ,
                fecha_modificacion = vfecha_modIF ,
                hora_modificacion  = vhora_modif
         WHERE numcte = pnumcte
         AND cve_servicio = pservicio;
      ELSE
         LET p_cod_ret ='139';
      END if;
   END if;
--   <<FIN>>
--     NULL;
--   EXCEPTION
--   WHEN OTHERS THEN
--        SIPK_MENSAJES.SP_TRAE_MENSAJE (SQLCODE, SQLERRM, P_COD_RET, P_MENSAJE);
END;
RETURN p_cod_ret,p_mensaje;
END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".carga_div( num_movto integer)
RETURNING varchar,
          integer,
          integer,
          integer,
          integer,
          integer,
          integer;

DEFINE   v_ciclo    integer;
DEFINE   v_conta    integer;
DEFINE   v_codigo   varchar;
DEFINE   v_preco    integer;
DEFINE   v_preve    integer;
DEFINE   v_precoarr integer;
DEFINE   v_precoab  integer;
DEFINE   v_prevearr integer;
DEFINE   v_preveab  integer;
DEFINE   p_cod_ret  varchar(8);
DEFINE   p_mensaje  varchar(80);

BEGIN

   LET v_conta =0;
   LET v_ciclo =0;

   FOREACH  SELECT divisa, precio_compra, precio_venta, pc_arriba, pc_abajo, 0, pv_abajo
            INTO v_codigo, v_preco, v_preve, v_precoarr, v_precoab,v_prevearr, v_preveab
            FROM si_tpcambio
            WHERE clase_tpcambio = 'b'
            ORDER BY  divisa

            LET v_conta = v_conta+1;

   END FOREACH;

END;

RETURN v_codigo, v_preco, v_preve, v_precoarr, v_precoab,v_prevearr,v_preveab;

END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
