CREATE PROCEDURE "informix".codigo_ret(pcodigo VARCHAR,psistema VARCHAR)
RETURNING VARCHAR ,VARCHAR;

--***************************************************************************
--DECLARACION DE VARIABLES
--***************************************************************************

DEFINE vcodret       VARCHAR(5);
DEFINE vdescripcion  VARCHAR(50);
DEFINE sql_err       INTEGER;
DEFINE pvcodret      VARCHAR;
DEFINE pvdescripcion VARCHAR;

--***************************************************************************
--CUERPO DEL PROCEDIMIENTO codigo_ret
--***************************************************************************

BEGIN

   LET vcodret = '000';
   LET vdescripcion = '';

   SELECT descripcion
   INTO vdescripcion
   FROM si_codret
   WHERE sistema = psistema
   AND codigo_retorno = pcodigo;

   LET pvcodret      =  vcodret      ;
   LET pvdescripcion =  vdescripcion ;

END;

RETURN pvcodret, pvdescripcion;

END PROCEDURE
