CREATE PROCEDURE "informix".uniprod_qry(v_pais CHAR(3),
                             v_estado CHAR(2),
                             v_stsol  CHAR(1))
RETURNING CHAR(5);

DEFINE v_codret CHAR(5);

LET v_codret = "00000";

   IF v_estado <> "XX" THEN
        SELECT UNIQUE(b.numcte), "0" secuencia,pais, estado
          FROM ss_unidadprod a, ss_solicitudes b, ss_anexosol c
         WHERE b.status_solicitud[2,2] = v_stsol 
           AND a.numcte = b.numcte
           AND a.num_solicitud = b.num_solicitud
           AND a.pais = v_pais
           AND a.estado = v_estado 
           AND c.num_solicitud = b.num_solicitud
           AND c.id_unidad_prod = 0
          INTO TEMP axel;

        INSERT INTO axel
        SELECT a.numcte, secuencia, pais, estado
          FROM bdicred:sd_unidadprod a,  ss_solicitudes b, ss_anexosol c
         WHERE a.numcte = b.numcte
           AND a.pais = v_pais
           AND a.estado = v_estado
           AND b.status_solicitud[2,2] = v_stsol
           AND c.num_solicitud = b.num_solicitud
           AND c.id_unidad_prod > 0;
   ELSE

        SELECT UNIQUE(b.numcte), "0" secuencia,pais, estado
          FROM ss_unidadprod a, ss_solicitudes b, ss_anexosol c
         WHERE b.status_solicitud[2,2] = v_stsol 
           AND a.numcte = b.numcte
           AND a.num_solicitud = b.num_solicitud
           AND a.pais = v_pais
           AND c.num_solicitud = b.num_solicitud
           AND c.id_unidad_prod = 0
          INTO TEMP axel;

        INSERT INTO axel
        SELECT a.numcte, secuencia, pais, estado
          FROM bdicred:sd_unidadprod a,  ss_solicitudes b, ss_anexosol c
         WHERE a.numcte = b.numcte
           AND a.pais = v_pais
           AND b.status_solicitud[2,2] = v_stsol
           AND c.num_solicitud = b.num_solicitud
           AND c.id_unidad_prod > 0;
   END IF

RETURN v_codret;

END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".finmes_cal(p_fecha DATE, p_meses SMALLINT)

   RETURNING DATE;


-- ######################################################################
-- ##### finmes_cal.sql
-- ##### spl que calcula la fecha de fin de mes actual o a futuro
-- ##### ultimo dia del mes natural
-- ##### jcng al 12-dic-2000
-- ######################################################################

   DEFINE v_fecha_finmes  DATE;
   DEFINE v_dia           DATE;
   DEFINE v_mes           DATE;
   DEFINE v_ano           DATE;


   LET v_fecha_finmes = NULL;
   LET v_dia          = 0;
   LET v_mes          = 0;
   LET v_ano          = 0;

   BEGIN

   IF p_meses IS NULL OR p_meses < 0 THEN
     LET p_meses = 0;
   END IF;

      LET  p_meses = p_meses +  1;

      WHILE 1 = 1
         ON EXCEPTION IN (-1267)
            LET v_dia = v_dia + 1;
         END EXCEPTION;

         LET v_fecha_finmes = DATE(EXTEND(p_fecha, YEAR TO DAY)
                              - v_dia UNITS DAY
                              + p_meses UNITS MONTH);
            EXIT WHILE;
      END WHILE;
      LET v_mes = MONTH(v_fecha_finmes);
      LET v_ano = YEAR(v_fecha_finmes);
      LET v_fecha_finmes = MDY(v_mes,1,v_ano);
      LET v_fecha_finmes = v_fecha_finmes - 1 UNITS DAY;

      RETURN v_fecha_finmes;
   END;
END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".verifcte1(p_empresa     LIKE si_cliente.empresa,
                           p_numcte      LIKE si_cliente.numcte,
                           p_criterioant LIKE si_cliente.numcte,
                           p_cedant      LIKE si_cliente.numcte)
   RETURNING SMALLINT, CHAR(20), CHAR(20), CHAR(60), CHAR(5), CHAR(80);

   DEFINE cod_ret             CHAR(5);
   DEFINE sql_err             SMALLINT;
   DEFINE isam_err            SMALLINT;
   DEFINE error_info          CHAR(40);
   DEFINE p_mensaje           CHAR(80);
   DEFINE nrows               SMALLINT;

   DEFINE v_numcte            CHAR(20);
   DEFINE v_nomcte            CHAR(60);
   DEFINE v_cuantos           SMALLINT;
   

   ON EXCEPTION SET sql_err, isam_err, error_info
      SET DEBUG FILE TO "VerifCte1.err";
      TRACE sql_err||" * "||isam_err||" * "||error_info;
      LET cod_ret = sql_err;
      RETURN  v_cuantos, p_cedant, v_numcte, v_nomcte, cod_ret, p_mensaje;
   END EXCEPTION;

  
   LET cod_ret = '000';
   LET p_mensaje = "Operacion Realizada Exitosamente";
   LET v_cuantos = 0;
   LET p_cedant = '';
   LET v_numcte = '';
   LET v_nomcte = '';
   
   SELECT
      COUNT(*)
   INTO
      v_cuantos
   FROM
      si_cliente cli
   WHERE
      cli.empresa = p_empresa
   AND
      cli.numcte LIKE '%'||p_numcte
   AND
      cli.numcte NOT IN (SELECT
                            lne.numcte
                         FROM
                            sd_listanegra lne
                         WHERE
                            lne.empresa = p_empresa
                         AND
                            lne.numcte = cli.numcte);
   FOREACH
      SELECT
         cli.numcte,
         DECODE(NVL(cli.razon_social, 'AM'),
            'AM',
            NVL(cli.apell_paterno,' ')||' '||
            NVL(cli.apell_materno,' ')||' '||
            NVL(cli.nombre1,' ')||' '||
            NVL(cli.nombre2,' '),
            cli.razon_social) nomcte
         INTO
            v_numcte,
            v_nomcte
         FROM
            si_cliente cli
         WHERE
            cli.empresa = p_empresa
         AND
            cli.numcte LIKE '%'||p_numcte
         AND
            cli.numcte NOT IN (SELECT
                                  lne.numcte
                               FROM
                                  sd_listanegra lne
                               WHERE
                                  lne.empresa = p_empresa
                               AND
                                  lne.numcte = cli.numcte)
      ORDER BY cli.numcte

      RETURN  v_cuantos, p_cedant, v_numcte, v_nomcte, cod_ret, p_mensaje
              WITH RESUME;
      
   END FOREACH;
   RETURN  v_cuantos, p_cedant, v_numcte, v_nomcte, cod_ret, p_mensaje;
END PROCEDURE
DOCUMENT
'SPL migrado del PL del mismo nombre de fondafa',
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".conscedprin( pEmpresa CHAR(3),
	                      pNumCte  CHAR(20),
                              pNumCred CHAR(20),
