RETURNING VARCHAR(20),VARCHAR(6),VARCHAR(80);

DEFINE pCredito VARCHAR(20);
DEFINE pCodRet   VARCHAR(6);
DEFINE pMensaje  VARCHAR(80);

LET pCredito =" ";
LET pCodRet = " ";
LET pMensaje = " ";




     IF (pTp = 'S') THEN
        EXECUTE PROCEDURE ConsCedSol (pEmpresa,
                         pNumCte,
	                 pNumCred)
