CREATE PROCEDURE "informix".cargoref_tc_ofi(o_empresa  CHAR(3),
				 o_sucursal CHAR(4),
				 o_usuario  CHAR(8),
				 o_tarjeta  CHAR(20),
				 o_monto    DECIMAL(14,2),
				 o_folio    CHAR(16),
				 o_transuc  CHAR(4))

RETURNING CHAR(5),       -- Codigo Retorno
	  DECIMAL(14,2), -- Saldo Disponible 
          DECIMAL(14,2), -- Importe Cargado
	  DECIMAL(14,2); -- Importe Comision

-- **************************************************************************
-- *                      DEFINICION DE VARIABLES                           *
-- **************************************************************************
DEFINE cod_ret             CHAR(5);
DEFINE cod_ret2            CHAR(5);
DEFINE sql_err             SMALLINT;
DEFINE isam_err            SMALLINT;
DEFINE error_info          CHAR(40);
DEFINE Saldo               MONEY(14,2);
DEFINE SaldoCom            MONEY(14,2);
DEFINE v_monto		   MONEY(14,2);
DEFINE v_codparam	   CHAR(4);
DEFINE v_fecha             DATE;
DEFINE v_num_credito       CHAR(20);
DEFINE v_divisa		   CHAR(2);
DEFINE MtoCgo		   MONEY(14,2);
DEFINE MtoCom		   MONEY(12,2);
DEFINE v_faplica           CHAR(1);
DEFINE v_factor		   DECIMAL(9,6);


-- **************************************************************************
-- *                      CONTROL DE ERRORES                                *
-- **************************************************************************

ON EXCEPTION SET sql_err, isam_err, error_info
   SET DEBUG FILE TO "CargoLineaCredito.err";
--   TRACE sql_err||" * "||isam_err||" * "||error_info;
   LET cod_ret = sql_err;
   LET Saldo = 0;
   RETURN cod_ret, SaldoCom, MtoCgo, MtoCom;
END EXCEPTION;



-- **************************************************************************
-- *                      ASIGNACION DE VARIABLES                           *
-- **************************************************************************

LET cod_ret       = "000";
LET Saldo         = 0;
LET cod_ret2      = "000";
LET SaldoCom      = 0;
LET MtoCgo	  = 0;
LET MtoCom	  = 0;

-- ****************************************************************************
-- *                        PROGRAMA PRINCIPAL                                *
-- ****************************************************************************

	-- **************************
	-- **************************
	SELECT a.num_credito, b.divisa
	  INTO v_num_credito, v_divisa
	  FROM sd_tarjeta a, sd_maecred b
	 WHERE a.empresa = o_empresa
	   AND a.num_tarjeta = o_tarjeta
	   AND b.empresa = a.empresa
	   AND b.num_credito = a.num_credito;

	IF v_num_credito IS NULL THEN
		LET cod_ret = "008";
	        RETURN cod_ret, SaldoCom, MtoCgo, MtoCom;
	END IF



	-- ***********************************************
	-- Extrae Comision por disposicion en ventanilla *
	-- ***********************************************
	SELECT valor INTO v_codparam
	  FROM sd_param
	 WHERE empresa = o_empresa
	   AND cod_param = "334";


	SELECT form_aplica, monto, apli_factor
	  INTO v_faplica, v_monto, v_factor
	  FROM sd_tpcomis
	 WHERE empresa = o_empresa
	   AND cod_comis = v_codparam;

	IF v_faplica = 2 THEN
		LET v_monto = o_monto * v_factor;
	END IF

	EXECUTE PROCEDURE cargo_ref_cel(o_tarjeta, o_sucursal, o_usuario,
					o_transuc, o_transuc,  o_folio,
					v_num_credito, 1, o_monto, 0,
					" ", " ", v_divisa, "",  
					o_sucursal, o_usuario, v_codparam,
					v_codparam, o_folio, v_num_credito,
					1, v_monto, v_divisa, " ", "2",
					" ", " ", " ", 0, 0, " ", " ")
	INTO cod_ret, v_codparam, v_fecha, Saldo, MtoCgo, 
	     cod_ret2, v_codparam, v_fecha, SaldoCom, MtoCom;


   RETURN cod_ret, SaldoCom, MtoCgo, MtoCom;

END PROCEDURE
				 
;

CREATE PROCEDURE "informix".cons_sdos1(pempresa CHAR(3),
                            pcuenta  CHAR(20),
                            ptarjeta CHAR(16))

RETURNING CHAR(5),	-- Codigo de Retorno
	  CHAR(20),	-- Numero de Credito
 	  CHAR(20),	-- Numero de Tarjeta
 	  CHAR(20),	-- Numero de Cliente
	  DECIMAL(14,2),-- Saldo Disponible
	  CHAR(60);	-- Nombre Cliente

   DEFINE vCodRet             CHAR(5);
   DEFINE sql_err             INTEGER;
   DEFINE vNumCte             CHAR(20);
   DEFINE vNombreCte          CHAR(60);
   DEFINE vSdoDisponible      DECIMAL(14,2);



--- Inicializa Variables de Salida
    LET vCodRet        = "000";
    LET vSdoDisponible = 0;
    LET vNumCte        = " ";
    LET vNombreCte     = " ";
BEGIN
   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
         LET vCodRet = sql_err;
         RETURN vCodRet,pcuenta,ptarjeta,vNumCte,vSdoDisponible,
             vNombreCte;
      END IF;
   END EXCEPTION;

   IF pcuenta IS NULL OR LENGTH(pcuenta) = 0 THEN
	SELECT num_credito INTO pcuenta 
	  FROM sd_tarjeta
	 WHERE empresa = pempresa
	   AND num_tarjeta = ptarjeta
	   AND tipo_tarjeta = "T";
	IF pcuenta IS NULL THEN
	   LET vCodRet ="008";
           RETURN vCodRet,pcuenta,ptarjeta,vNumCte,vSdoDisponible,
                  vNombreCte;
	END IF
   ELSE
	SELECT num_tarjeta INTO ptarjeta
	  FROM sd_tarjeta
	 WHERE empresa = pempresa
	   AND num_credito = pcuenta
	   AND tipo_tarjeta ="T";
	IF ptarjeta IS NULL THEN
	   LET vCodRet ="008";
           RETURN vCodRet,pcuenta,ptarjeta,vNumCte,vSdoDisponible,
                  vNombreCte;
	END IF
   END IF


   SELECT a.num_credito, a.num_tarjeta, b.numcte,
	  c.monto_otorgado - (c.sdo_cap_insoluto + c.sdo_retenido),
	  TRIM(NVL(d.razon_social, ' ')) ||
	  TRIM(d.nombre1) || " " ||
	  TRIM(NVL(d.nombre2, ' ')) || " " ||
	  TRIM(d.apell_paterno) || " " ||
	  TRIM(d.apell_materno)
     INTO pcuenta, ptarjeta, vNumCte, vSdoDisponible, vNombreCte
     FROM sd_tarjeta a, sd_maecred b, sd_maesdos c, 
	  bdinteg:si_cliente d 
    WHERE a.empresa = pempresa
      AND a.num_credito = pcuenta
      AND a.tipo_tarjeta = "T"
      AND b.empresa = a.empresa
      AND b.num_credito = pcuenta
      AND c.empresa = b.empresa
      AND c.num_credito = b.num_credito
      AND d.numcte = b.numcte; 
         
        
    RETURN vCodRet, pcuenta, ptarjeta, vNumCte, vSdoDisponible,
           vNombreCte; 
END
END PROCEDURE;

create procedure "informix".sp_validaejecutivo(pnumejecutivo char(8))                           
       returning char(5), char (3), char (45), char(4), char(4),char (3),int, 
       date;

define vcodret char(5);
define vsqlerr integer;
define vempresa char(3);
define vnombre char(45);
define vdepartamento char(4);
define vsucursal char(4);
define vpuesto char(3);
define vperfil  int;
define vvigencia date;

let vcodret = "000";
let  vsqlerr = 0;
let vnombre = "";
let vdepartamento = "";
let vvigencia = "";
let vsucursal = "";
let vempresa = "";
let vpuesto = "";
let vperfil=0;



begin
   on exception set vsqlerr
      if vsqlerr <> 0 then
         let vcodret = vsqlerr;
         return vcodret, vempresa, vnombre, vdepartamento, vsucursal, vpuesto, vperfil, vvigencia;
     end if;
   end exception;

 if pnumejecutivo <> "" then 
        If exists(select ejecutivo from si_ejecut where ejecutivo=pnumejecutivo) then

            SELECT   empresa, nombre, sucursal, puesto, departamento, vigencia, perfil
            INTO  vempresa, vnombre, vsucursal, vpuesto, vdepartamento, vvigencia, vperfil   
            FROM bdinteg:si_ejecut
            WHERE ejecutivo = pnumejecutivo;
              if vvigencia is null then
                  let vcodret= '014';
              else
                 if vvigencia > today then
                    if cast(nvl(vdepartamento,0) as int)= 0 and cast(nvl(vsucursal,0) as int)=0 then
                        let vcodret = '011'; 
                    end if; 
                        if cast(nvl(vdepartamento,0) as int) > 0 then
                            if exists(select ejecutivo from si_macejecutivo where ejecutivo=pnumejecutivo) then
                                let vcodret = '012'; 
                            end if ;
                        else
                            if exists(select ejecutivo from si_macejecutivo where ejecutivo=pnumejecutivo) then
                               let vcodret = '013'; 
                            end if;
                        end if;
                 else
                    let vcodret = '010';
                 end if;
              end if; 
        else
          let vcodret = '009';
        end if;
end if;
     return vcodret, vempresa, vnombre, vdepartamento, vsucursal, vpuesto, vperfil, vvigencia;
end
end procedure;

create procedure "informix".sp_depurausuariomac()
        returning char(5)

    -- Realizo   : Alfredo Gpe. Avena Rocha
    -- Actividad : Depura la Tabla si_macejecutivo, donde los registros tengan status T y la vigencia vencida
    -- Solicitó  : Daniel Zambada
    -- Fecha     :  09/03/2007
       
       define vcodret	char(5);
       define sql_err	integer;
       define vEjecutivo         char(8);
       define vSucursal         char(4);
       define vDepartamento         char(3);
       define vPuesto         char(3);
       define vPerfil             int;
       define vMac                  char(12);
       define vStatus                 char(1);
       define vUser         char(8);

Let vcodret = '000';
Let vEjecutivo = "";
Let vSucursal = "";
Let vDepartamento = "";
Let vPuesto = "";
Let vPerfil = 0;
Let vMac = "";
Let vStatus = "";
Let vUser = "";


Begin
	
	on exception set sql_err
		if sql_err <> 0 then
			let vcodret = sql_err;
			return vcodret;
		end if;
	end exception;
	

        Foreach
                              
                Select mac.ejecutivo, eje.sucursal, eje.departamento, eje.puesto, eje.perfil, mac.mac, mac.status, mac.user_insert  
                Into vEjecutivo ,vSucursal ,vDepartamento,vPuesto,vPerfil,vMac,vStatus,vUser 
                from si_macejecutivo mac
                inner join si_ejecut eje
                on mac.ejecutivo = eje.ejecutivo
                where mac.status = 'T' or eje.vigencia < current

                Execute Procedure sp_manejamacejecutivo('001','2',vEjecutivo ,vSucursal ,vDepartamento,vPuesto,vPerfil,vMac,vStatus,vUser) into vcodret;

        End Foreach;

        Return vcodret; 

end;
End procedure
;

create procedure "informix".sp_actualizamacejecutivo()
        returning char(5)

    -- Realizo   : Alfredo Gpe. Avena Rocha
    -- Actividad : Actualiza la Tabla si_macejecutivo 
    -- Solicitó  : Daniel Zambada
    -- Fecha     :  09/03/2007
       
       define vcodret	char(5);
       define sql_err	integer;
       define vEjecutivo         char(8);
       define vSucursal         char(4);
       define vDepartamento         char(3);
       define vPuesto         char(3);
       define vPerfil             int;
       define vMac                  char(12);
       define vStatus                 char(1);
       define vUser         char(8);
       define vArea         char(2);
       define vAreaTmp         char(2);

Let vcodret = '000';
Let vEjecutivo = "";
Let vSucursal = "";
Let vDepartamento = "";
Let vPuesto = "";
Let vPerfil = 0;
Let vMac = "";
Let vStatus = "";
Let vUser = "";
Let vArea = "";
Let vAreaTmp = "";

Begin
	
	on exception set sql_err
		if sql_err <> 0 then
			let vcodret = sql_err;
			return vcodret;
		end if;
	end exception;
	

        Foreach
                              
                Select mac, sucursal, area 
                into vMac, vSucursal, vArea
                from si_sucursalesmaquina 
                where sucursal <> '0000'
                and mac Not in (Select mac From si_macejecutivo)

                Foreach
                        Select distinct mac.ejecutivo, eje.puesto, mac.status
                        into vEjecutivo, vPuesto, vStatus
                        from si_ejecut eje
                        inner join si_macejecutivo mac
                        on eje.ejecutivo = mac.ejecutivo
                        and eje.sucursal = vSucursal

                        Select area 
                        into vAreaTmp
                        From si_macarea 
                        where sucursal = vSucursal
                        and puesto = vPuesto;

                        if nvl(vAreaTmp,'0') <> '0' then
                            if vAreaTmp = vArea then
                                Insert into si_macejecutivo (empresa, mac, ejecutivo, status, user_insert, fecha_insert)
                                values('001',vMac, vEjecutivo, vStatus, 'Informix',current);
                            else
                                Let vcodret = '002';
                            end if;
                        else
                            Let vcodret = '001';
                        end if;
                        
                        
                end Foreach;


        End Foreach;

        Return vcodret; 

end;
End procedure
;

create procedure "informix".sp_validasucursal (pempresa char(3), psucursal char(4), pdepartamento char(3))

returning char(5), char (40);

define vcodret char(5);
define vsqlerr integer;

define vempresa char(3);
define vsucursal char(4);
define vdepartamento char (3);
define vdescripcion char (40);

let vcodret = "000";
let vsqlerr = 0;
let vdescripcion = "";

begin
on exception set vsqlerr
  if vsqlerr <> 0 then
     let vcodret = vsqlerr;
     return vcodret, vdescripcion;
 end if;
end exception;

if psucursal is null or pdepartamento is null then

let vcodret = "110";

else

if cast(nvl(psucursal, 0) as int) > 0  then

    if exists (select sucursal from bdinteg:si_sucursales where sucursal = psucursal) then

            --let vdescripcion = "prueba -" || psucursal;
           select nombre
           into vdescripcion
           from bdinteg:si_sucursales
           where sucursal = psucursal;

    else

        let vcodret = "111";

    end if;

else

    if cast(nvl(pdepartamento, 0)as int) > 0 then

        if exists (select departamento from bdinteg:si_departamentos where departamento = pdepartamento) then

                select descripcion
                into vdescripcion
                from bdinteg:si_departamentos
                where departamento = pdepartamento;

        else

            let vcodret = "222";

        end if;

    else

        let vcodret = "333";

    end if;

end if;

end if;

return vcodret, vdescripcion;
end
end procedure

DOCUMENT
"Validación de Sucursal y Departamentos",
"Autor : Frank Gaxiola"
;

create procedure "informix".verifcte(pempresa char(3),
			  pappat char(26),
                          pnombre1 char(26),
	                  prazon_soc char(60),
                          pnum_movto smallint)
       returning char(5),char(26),char(26),char(26),char(26),
		char(60),char(13),char(20);

define vpaterno,vmaterno,vnombre1,vnombre2 char(15);
define vciclo smallint;
define vcodret char(5);
define vrazon_soc char(60);
define vnumcte char(20);
define vrfc char(13);
define sql_err integer;

begin
   on exception set sql_err
      if sql_err <> 0 then
	 let vcodret = sql_err;
	 return vcodret,vpaterno,vmaterno,vnombre1,vnombre2,vrazon_soc,
                vrfc,vnumcte;
      end if
   end exception;


   set isolation to dirty read;

   let vnumcte=" ";
   let vpaterno=" ";
   let vmaterno=" ";
   let vnombre1=" ";
   let vnombre2=" ";
   let vrazon_soc=" ";
   let vrfc = " ";
   let vcodret="000";
   let vciclo = 0;

   if pappat is null and prazon_soc is null then
      let vcodret="110";
      return vcodret,vpaterno,vmaterno,vnombre1,vnombre2,vrazon_soc,
             vrfc,vnumcte;
   end if
   if prazon_soc is null or prazon_soc = " " then
     -- let pappat = trim(pappat) || "*";
     -- let pnombre1 = trim(pnombre1) || "*";
     -- Valida por RFC MEL 09/Mar/2007
      foreach
	 select apell_paterno,apell_materno,nombre1,nombre2,razon_social,
		rfc,si_cliente.numcte
	    into vpaterno,vmaterno,vnombre1,vnombre2,
		vrazon_soc,vrfc,vnumcte
	    from si_cliente
	    where rfc = pappat 
	  --  where apell_paterno matches pappat and
          --      nombre1 matches pnombre1
         let vciclo = vciclo+1;
         if vciclo <= pnum_movto then
            continue foreach;
         end if
	 if vpaterno is null then
	    let vcodret = "104";
	 end if
	 if vrfc is null then
	    let vrfc = " ";
	 end if
	 return vcodret,vpaterno,vmaterno,vnombre1,vnombre2,vrazon_soc,
                vrfc,vnumcte with resume;
      end foreach
   else
      foreach
	 select apell_paterno,apell_materno,nombre1,nombre2,razon_social,
		rfc,si_cliente.numcte
	    into vpaterno,vmaterno,vnombre1,vnombre2,vrazon_soc,
		vrfc,vnumcte
            from si_cliente
	    where rfc =  pappat
	    --where razon_social matches prazon_soc
            let vciclo = vciclo+1;
            if vciclo <= pnum_movto then
               continue foreach;
            end if
 	    if vrazon_soc is null then
	       let vcodret = "104";
	    end if
	    if vrfc is null then
	       let vrfc = " ";
	    end if
	    return vcodret,vpaterno,vmaterno,vnombre1,vnombre2,vrazon_soc,
                   vrfc,vnumcte with resume;
      end foreach
   end if;
end
end procedure
DOCUMENT
"Consulta de clientes por Apellidos o Razon Social",
"Autor : Procesamiento Interactivo S.A. de C.V.",
"MODIFICO : Manuel Hernandez",
"MODIFICO : Mario Escobar",
"FECHA : 12/Septiembre/2006",
"FECHA : 19/Diciembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".califica_scoring(o_empresa CHAR(3),
				  o_numsol   	CHAR(20),
				  o_referencia1 	CHAR(20),
				  o_referencia2 	CHAR(20),
				  o_ingreso     	MONEY(14,2),
			  	  o_conyuge     	CHAR(20),
                          o_nombreref_1 	CHAR(104),
                          o_nombreref_2 	CHAR(104),
                          o_parentesco_1  CHAR(2),
                          o_parentesco_2  CHAR(2),
                          o_telefono_1    CHAR(13),
                          o_telefono_2    CHAR(13))

RETURNING CHAR(5);


-- ****************************************************************************
-- *                        DEFINICION DE VARIABLES                           *
-- ****************************************************************************
DEFINE scod_ret     CHAR(5);
DEFINE vsqlerr      INTEGER;
DEFINE v_valor      DECIMAL(14,2);
DEFINE v_valor_1s   DECIMAL(14,2);
DEFINE v_valor_2s   DECIMAL(14,2);
DEFINE v_valor_im   DECIMAL(14,2);
DEFINE v_valor_ex   DECIMAL(14,2);
DEFINE v_paso       CHAR(1);
DEFINE v_cuantos    SMALLINT;
DEFINE v_seccion    SMALLINT;
DEFINE v_grupo      SMALLINT;
DEFINE v_tpsol      CHAR(1);
DEFINE v_hoy        DATE;
DEFINE v_cliente    CHAR(20);
DEFINE vCompromisos DECIMAL(14,2);
DEFINE vMensaje     VARCHAR(255);
DEFINE vedocivil    CHAR(1);
DEFINE vTpCiudad    CHAR(1);
DEFINE vCiudadCte   CHAR(3);
DEFINE vEstadoCte   CHAR(2);
-- ****************************************************************************
-- *                        ASIGNACION DE VARIABLES                           *
-- ****************************************************************************
LET scod_ret     = "000";
LET vsqlerr      = 0;
LET v_valor      = 0;
LET v_valor_1s   = 0;
LET v_valor_2s   = 0;
LET v_valor_im   = 0;
LET v_valor_ex   = 0;
LET v_paso       = "";
LET v_cuantos    = 0;
LET v_seccion    = 0;
LET v_grupo      = 0;
LET v_tpsol      = "";
SELECT fecha_hoy INTO v_hoy FROM bdicred:sd_fechas;
-- ****************************************************************************
-- *                        CONTROL DE ERRORES                                *
-- ****************************************************************************
BEGIN
ON EXCEPTION SET vsqlerr
   IF vsqlerr != 0 THEN
      LET scod_ret=vsqlerr;
      RETURN scod_ret;
   END IF;
END EXCEPTION;



-- ****************************************************************************
-- *                        PROGRAMA PRINCIPAL                                *
-- ****************************************************************************
	-- ********************************
	-- Inserta Referencias Personales *
	-- ********************************

	SELECT numcte INTO v_cliente
	  FROM ss_solicitudes
	 WHERE empresa = o_empresa
	   AND num_solicitud = o_numsol;

	SELECT estado_civil
          INTO vedocivil
          FROM bdinteg:si_ctepf
         WHERE empresa = o_empresa and numcte = v_cliente;


	let o_empresa = o_empresa;
	let o_numsol = o_numsol;
	let v_cliente = v_cliente;
	let o_referencia1 = o_referencia1;

         INSERT INTO ss_refpersonales
 	  (empresa, num_solicitud, numcte, numcte_ref, tipo_relacion, 
	   nombre_ref, parentesco, telefono_ref)
         VALUES
	  (o_empresa, o_numsol, v_cliente, o_referencia1, "01", 
	   o_nombreref_1 , o_parentesco_1, o_telefono_1);


--	IF NOT o_referencia2 IS NULL AND LENGTH(o_referencia2) > 0 THEN
--		INSERT INTO ss_refpersonales
--	 	  (empresa, num_solicitud, numcte, numcte_ref, tipo_relacion)
--		VALUES
--	 	  (o_empresa, o_numsol, v_cliente, o_referencia2, "01");
--	END IF


	let o_empresa = o_empresa;
	let o_numsol = o_numsol;
	let v_cliente = v_cliente;
	let o_referencia2 = o_referencia2;


	IF NOT o_nombreref_2 IS NULL AND LENGTH(o_nombreref_2) > 0 THEN
		INSERT INTO ss_refpersonales
	 	 (empresa, num_solicitud, numcte, numcte_ref, tipo_relacion, 
		  nombre_ref, parentesco, telefono_ref)
		VALUES
	 	 (o_empresa, o_numsol, v_cliente, o_referencia2, "01", 
		  o_nombreref_2 , o_parentesco_2, o_telefono_2);
	END IF


--	IF o_referencia1 = o_conyuge THEN
--		LET scod_ret = "088";
--                RETURN scod_ret;
--	END IF

--      IF vedocivil = "C" THEN
--         if not o_referencia2 is null AND LENGTH(o_referencia2) > 0 then
--            IF o_referencia2 = o_conyuge THEN
-- 	         LET scod_ret = "088";
--               RETURN scod_ret;
--   	      END IF
--         end if
--      END IF


	let o_empresa = o_empresa;
	let o_numsol = o_numsol;
	let v_cliente = v_cliente;
	let o_conyuge = o_conyuge;

	-- Registro que identificara el numero de cliente asignado al conyuge
	IF NOT o_conyuge IS NULL AND LENGTH(o_conyuge) > 0 THEN
		INSERT INTO ss_refpersonales
	 	 (empresa, num_solicitud, numcte, numcte_ref, parentesco)
		VALUES
	 	 (o_empresa, o_numsol, v_cliente, o_conyuge, "05");
	END IF

	-- ********************************
	-- Actualiza Ingresos del Cliente *
	-- ********************************
	UPDATE ss_resum_scor_fin SET ingreso_mensual = o_ingreso
	 WHERE empresa = o_empresa
	   AND num_solicitud = o_numsol;

	-- **********************************************************
	-- Incorpora Grupo 12 (ciudad) de acuerdo a dato del cliente*
	-- **********************************************************
	SELECT estado, ciudad
	  INTO vEstadoCte, vCiudadCte
	  FROM bdinteg:si_direcciones a, ss_solicitudes b
	 WHERE b.empresa = o_empresa
	   AND b.num_solicitud = o_numsol
	   AND a.numcte = b.numcte
	   AND a.secuencia = (SELECT MAX(secuencia) 
			        FROM bdinteg:si_direcciones c
			       WHERE c.numcte = a.numcte
				 AND c.tipo_dir ="1");

	SELECT tipo_ciudad
	  INTO vTpCiudad
	  FROM bdinteg:si_ciudades
	 WHERE estado = vEstadoCte
	   AND ciudad = vCiudadCte;

	IF vTpCiudad IS NULL THEN
		LET vTpCiudad = "0";
	END IF

        SELECT valor INTO v_valor
          FROM ss_scoring_pesos
         WHERE empresa = o_empresa
           AND tp_solicitud = "T"
           AND grupo = 12
           AND elemento = vTpCiudad
           AND seccion = 2
           AND tpo_persona = "01";

	IF v_valor IS NULL THEN
		LET v_valor = 0;
	END IF

        INSERT INTO ss_detalle_scoring
         (empresa, seccion, grupo, elemento, tpo_persona, num_solicitud, valor)
        VALUES
         (o_empresa, 2, 12, vTpCiudad, "01", o_numsol, v_valor);


        -- **************************************
        -- Inicia Proceso de Circulo de Credito *
        -- **************************************

       { EXECUTE PROCEDURE cal_circulocredito(o_empresa, v_cliente)
           INTO scod_ret, v_paso, vCompromisos, vMensaje;

        IF scod_ret <> "000" THEN
                RETURN scod_ret;
        END IF

        UPDATE ss_resum_scor_fin
           SET evalua_cc = v_paso,
               motivo_cc= vMensaje,
               pago_minimo = v_compromisos
         WHERE empresa = o_empresa
           AND num_solicitud = o_numsol;

        IF v_paso = "1" THEN

		UPDATE ss_solicitudes SET status_solicitud = "RT"
		 WHERE empresa = o_empresa
		   AND num_solicitud = o_numsol;

		INSERT INTO ss_autorizacion
		 (empresa, ejecutivo_auto, num_solicitud, status_solicitud,
		  comentario, fecha_entrada, fecha_salida)
		VALUES
		 (o_empresa, "sistema", o_numsol, "RT",
	 	  "Evaluacion en Circulo de Credito Negativa, " ||
		  "Solicitud No Aprobada", v_hoy, v_hoy);

                RETURN scod_ret;
        END IF}

        UPDATE ss_resum_scor_fin
           SET evalua_cc = "0",
               motivo_cc= "Prueba",
               pago_minimo = 0
         WHERE empresa = o_empresa
           AND num_solicitud = o_numsol;


	-- ********************************
	-- Inicia Proceso de Calificacion *
	-- ********************************

	SELECT tipo_solicitud INTO v_tpsol
	  FROM ss_solicitudes
	 WHERE empresa = o_empresa
	   AND num_solicitud = o_numsol;

	FOREACH SELECT a.seccion INTO v_seccion
		  FROM ss_scoring_solic a, ss_scoring_seccion b
		 WHERE a.empresa = o_empresa
		   AND a.tp_solicitud = v_tpsol
                   AND b.empresa = a.empresa
		   AND b.seccion = a.seccion
		   AND b.automatico = "0"

	   -- ************
	   -- Explicitos *
	   -- ************
	   FOREACH SELECT grupo INTO v_grupo
		     FROM ss_scoring_grupo
		    WHERE empresa = o_empresa
		      AND seccion  = v_seccion
		      AND implicito = "0"


		SELECT SUM(valor) INTO v_valor
		  FROM ss_detalle_scoring
		 WHERE empresa = o_empresa
		   AND seccion = v_seccion
		   AND grupo = v_grupo
	    	   AND num_solicitud = o_numsol;

		IF v_valor IS NULL THEN
			LET v_valor = 0;
		END IF

		LET v_valor_ex = v_valor_ex + v_valor;

	   END FOREACH

	   -- ************
	   -- Implicitos *
	   -- ************
           FOREACH SELECT agrupar, valor, COUNT(*)
                     INTO v_paso, v_valor, v_cuantos
                     FROM ss_scoring_grupo a, ss_detalle_scoring b
                    WHERE a.empresa = o_empresa
                      AND a.seccion  = v_seccion
                      AND a.implicito = "1"
		      AND b.empresa = a.empresa
		      AND b.seccion = a.seccion
		      AND b.grupo = a.grupo
		      AND b.elemento = 1
		      AND b.num_solicitud = o_numsol
		    GROUP BY 1,2

		IF v_cuantos > 0 THEN
			LET v_valor_im = v_valor_im + v_valor;
		END IF

           END FOREACH

	   LET v_valor_1s = v_valor_ex + v_valor_im;

	END FOREACH

	-- ********************************
	-- Califica Comportamiento Interno*
	-- ********************************

	SELECT puntuacion INTO v_valor_2s
	  FROM ss_scoring_financ a, ss_resum_scor_fin b
	 WHERE b.empresa = o_empresa
	   AND b.num_solicitud = o_numsol
	   AND a.empresa = a.empresa
	   AND a.tp_solicitud = v_tpsol
	   AND (b.meses_historia >= a.min_mes_hist
	   AND b.meses_historia <= a.max_mes_hist )
	   AND (b.situacion_pago >= a.min_porc_pago
	   AND b.situacion_pago <= a.max_porc_pago)
	   AND a.circulo_credito = (SELECT DECODE(r.evalua_cc,"0","0",
							      "2","1",
							      "3","1",
    							      "4","1","1")
				      FROM ss_resum_scor_fin r
				     WHERE empresa = o_empresa
				       AND num_solicitud = o_numsol);

	IF v_valor_2s IS NULL THEN
		LET v_valor_2s = 0;
	END IF

	-- *************************************
	-- Almacena Resultado de la Evaluacion *
	-- *************************************
	LET v_valor = v_valor_1s + v_valor_2s;
	INSERT INTO ss_resumen_scoring
	  (empresa, num_solicitud, seccion, evaluacion)
	VALUES
	  (o_empresa, o_numsol, v_seccion, v_valor);


	-- ************************************
	-- Valida Resultado de la  Evaluacion *
	-- ************************************
	SELECT COUNT(*) INTO v_cuantos
	  FROM ss_scoring_solic
	 WHERE empresa = o_empresa
	   AND tp_solicitud = v_tpsol
	   AND seccion = v_seccion
	   AND (v_valor >= evaluacion_min
	   AND  v_valor <= evaluacion_max);

	IF v_cuantos IS NULL OR v_cuantos = 0 THEN
		UPDATE ss_solicitudes SET status_solicitud = "RT"
		 WHERE empresa = o_empresa
		   AND num_solicitud = o_numsol;

		INSERT INTO ss_autorizacion
		 (empresa, ejecutivo_auto, num_solicitud, status_solicitud,
		  comentario, fecha_entrada, fecha_salida)
		VALUES
		 (o_empresa, "sistema", o_numsol, "RT",
		  "Puntos acumulados en Scoring fueron insuficientes para " ||
		  "su Aprobacion", v_hoy, v_hoy);

		RETURN scod_ret;
	END IF

	-- *******************************
	-- Evalua Antiguedad del Cliente *
	-- *******************************

	-- Extrae Valor de Parametro
	SELECT valor INTO v_cuantos
	  FROM ss_param
	 WHERE empresa = o_empresa
	   AND secuencia = 300;

	-- Extrae Valor del Cliente
	SELECT meses_historia INTO v_valor
	  FROM ss_resum_scor_fin
	 WHERE empresa = o_empresa
	   AND num_solicitud = o_numsol;

	-- Valida para generacion de Orden de Supervision
	LET v_paso = "0";
	IF v_valor <= v_cuantos THEN
		INSERT INTO ss_solicitud_os
		  (empresa, num_solicitud, fecha_solicitud, status,
		   usuario_solicita)
		VALUES
		  (o_empresa, o_numsol, v_hoy, "S", "sistema");

		--EXECUTE PROCEDURE sp_os_integracion(o_numsol, v_hoy)
		--   INTO scod_ret;

                INSERT INTO ss_autorizacion
                 (empresa, ejecutivo_auto, num_solicitud, status_solicitud,
                  comentario, fecha_entrada, fecha_salida)
                VALUES
                 (o_empresa, "sistema", o_numsol, "EE",
                  "Solicitud Enviada a Orden de Supervision ", v_hoy, v_hoy);

		UPDATE ss_solicitudes SET status_solicitud = "EE"
		 WHERE empresa = o_empresa
		   AND num_solicitud = o_numsol;

		LET v_paso = "1"; -- Asigna Bandera para nuevos
	END IF

	-- *************************
	-- Genera Linea de Credito *
	-- *************************
	EXECUTE PROCEDURE determina_lincred_tc(o_empresa,
				 	       o_numsol,
					       v_paso)
	INTO scod_ret, v_valor;

	IF v_paso = "0" THEN -- Bandera que indica que esta en O.S.
        	UPDATE ss_solicitudes
	   	   SET monto_solicitado = v_valor,
	   	       status_solicitud = "AT"
         	 WHERE empresa = o_empresa
           	   AND num_solicitud = o_numsol;

                INSERT INTO ss_autorizacion
                 (empresa, ejecutivo_auto, num_solicitud, status_solicitud,
                  comentario, fecha_entrada, fecha_salida)
                VALUES
                 (o_empresa, "sistema", o_numsol, "AT",
                  "Solicitud Autorizada", v_hoy, v_hoy);
	ELSE
        	UPDATE ss_solicitudes
	   	   SET monto_solicitado = v_valor
         	 WHERE empresa = o_empresa
           	   AND num_solicitud = o_numsol;
	END IF
END
	RETURN scod_ret;

END PROCEDURE
;

create procedure "informix".ingresos (pTipoOperacion char(1),
				pEmpresa char(3),
				pNumeroCliente char(20),
				pSecuencia smallint,
				pTipoIngreso char(1),
				pNombreEmpresa char(60),
				pNombrePuesto char(3),
				pAntiguedad char(2),
				pNombreDepto char(20),
				pJefeInmediato char(60),
				pIngresosMensuales money(14,2),
				pUsuarioInserta char(8),
				pFechaInserta date,
				pPuestoEsp char (2))
				returning char(5);


define vcodret char(5);
define iSecuencia integer;


let vcodret = "000";
let iSecuencia  = 0;



let pTipoOperacion = pTipoOperacion;
let pNombrePuesto = pnombrePuesto;
let pPuestoEsp = pPuestoEsp;
let pNumeroCliente = pNumeroCliente;
let pSecuencia = pSecuencia;

{    if pTipoOperacion = "C" then
       select max(secuencia) into iSecuencia
       from   si_ingresos
       where  numcte = pnumcte;
       if iSecuencia is null then
          let pTipoOperacion = "A"; 
       end if
    end if
}

begin

	if pTipoOperacion != 'A' and pTipoOperacion != 'C' then
			   let vcodret = "200";
			   return vcodret;
        end if

	IF pTipoOperacion = 'A' OR pTipoOperacion = 'C' THEN

		IF pTipoOperacion='A' THEN
			SELECT  MAX(sec_ingreso) INTO iSecuencia
			FROM si_ingresos
			WHERE empresa=pEmpresa AND numcte=pNumeroCliente;

				IF iSecuencia IS NULL THEN
					let iSecuencia = 1;
				ELSE
					let iSecuencia = iSecuencia + 1;
				END IF;


				INSERT INTO si_ingresos (empresa, numcte, sec_ingreso, tipo_ingreso, nombre_empresa, puesto, antiguedad, nombre_depto, jefe_inmediato, ingreso_mensual,puesto_esp, user_insert, fecha_insert)
					VALUES(pEmpresa, pNumeroCliente, iSecuencia, pTipoIngreso, pNombreEmpresa,
					       pNombrePuesto, pAntiguedad, pNombreDepto, pJefeInmediato, pIngresosMensuales,pPuestoEsp,
					       pUsuarioInserta, pFechaInserta);
		ELSE
                     

			UPDATE si_ingresos
					SET    empresa=pEmpresa, numcte=pNumeroCliente,
					       sec_ingreso=pSecuencia, tipo_ingreso=pTipoIngreso, nombre_empresa=pNombreEmpresa, puesto=pNombrePuesto,
					       antiguedad=pAntiguedad, nombre_depto=pNombreDepto, jefe_inmediato=pJefeInmediato, ingreso_mensual=pIngresosMensuales, puesto_esp = pPuestoEsp,
					       user_insert=pUsuarioInserta, fecha_insert=pFechaInserta
					WHERE numcte=pNumeroCliente  AND sec_ingreso=pSecuencia;
			END IF;
		END IF;



   return vcodret;

end;

end procedure;

create procedure "informix".altaejecutivos(pUsuario int8)
	returning char(3);

	define iEjecutivo int8;
	define cNombre char(45);
	define cSistema char(2);
	define cEmpresa char(3);
	define cSucursal char(4);
	define cPassword char(8);
	define cUsuario char(8);
	define dVigencia date;
	define iPerfil integer;
	define cRegreso char(3);

	let cEmpresa='001';
	let cSucursal='0001';
	let cPassword='informix';
	let cUsuario='informix';
	let dVigencia='12/31/2010'::date;
	let cRegreso='000';

	


	foreach	select ejecutivo, nombre, sistema
			into iEjecutivo, cNombre, cSistema
			from si_altasejecutivos
			where ejecutivo<>0

		if not exists(select ejecutivo from si_ejecut where ejecutivo=iEjecutivo::char(8)) then
			insert into si_ejecut(empresa, ejecutivo, nombre, password, vigencia, asistente, user_insert, fecha_insert)
			values(cEmpresa, iEjecutivo, cNombre, cPassword, dVigencia, cUsuario, pUsuario, current::date);
		end if;

		foreach	select distinct perfil
				into iPerfil
				from si_perfil_ejecut
				where sistema=cSistema

			if not exists(select ejecutivo from si_perfil_ejecut where ejecutivo=iEjecutivo::char(8) and perfil=iPerfil) then
				insert into si_perfil_ejecut(cod_emp, sistema, ejecutivo, perfil, user_insert, fecha_insert)
				values(cEmpresa, cSistema, iEjecutivo, iPerfil, pUsuario, current::date);
			end if;
		end foreach;
	end foreach;

	return cRegreso;
end procedure;

create procedure "informix".sp_insertaejecutivotemporal()
        returning char(5)

    -- Realizo   : Alfredo Gpe. Avena Rocha
    -- Actividad : Actualiza la tabla si_macejecutivo
    -- Solicitó  : Daniel Zambada
    -- Fecha     :  06/03/2007
       
       define vcodret	char(5);
       define sql_err	integer;
        define vEjecutivo         char(8);
       define vPuesto         char(3);
       define vUser         char(8);

Let vcodret = '000';
Let vEjecutivo = "";
Let vPuesto = "";
Let vUser = "";



Begin
	
	on exception set sql_err
		if sql_err <> 0 then
			let vcodret = sql_err;
			return vcodret;
		end if;
	end exception;
	
        Foreach
                Select distinct m.ejecutivo, e.puesto, e.user_insert 
                into vEjecutivo, vPuesto, vUser                
                from si_macejecutivo m
                inner join si_ejecut e 
                on m.ejecutivo=e.ejecutivo
                and m.ejecutivo <> '91443041'
