CREATE PROCEDURE "informix".sp_consulta_empleado_iccat(pEmpresa char (3), pNumEmp char(8))
	RETURNING char(5), char (45);

--Realizó: Javier A. Chávez Trujillo
--Fecha: 18/12/08
--Solicitó: Mauricio León
--Actividad: Retorna el nombre del empleado

--Define variables
define sql_err integer;
define cod_ret char (5);
define vNombre char(45);


--Inicializa variables
LET sql_err = '';
LET cod_ret = '000';
LET vNombre = '';


BEGIN

 ON EXCEPTION SET sql_err
          LET cod_ret = sql_err;
      RETURN  cod_ret, vNombre;
   END EXCEPTION;

   IF EXISTS(SELECT ejecutivo FROM bdinteg:si_ejecut WHERE empresa = pEmpresa AND ejecutivo = pNumEmp) THEN

			SELECT nombre INTO vNombre FROM bdinteg:si_ejecut WHERE empresa = pEmpresa AND ejecutivo = pNumEmp;

	ELSE
		LET cod_ret = '001'; -- El empleado No existe
	END IF;

	RETURN cod_ret, vNombre;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenercredito_iccat(pNumCliente char (9))
returning char(5), char (20), char (20);

   --Elaboró: Javier A. Chávez T.
   --Actividad: consulta el número de crédito y tarjeta de un cliente
   --Solicito: Mauricio León
   --Fecha: 05-05-09
   --Modificó: Pedro Enrique Zavala Valdez
   --Fecha: 06-05-09

DEFINE sql_error integer;
DEFINE cod_ret  char  (5);
DEFINE vCredito char (20);
DEFINE vTarjeta char (20);

LET cod_ret = '';
LET vCredito = '';
LET vTarjeta = '';

 BEGIN

 ON EXCEPTION SET sql_error
	IF sql_error <> 0 THEN
		LET cod_ret = sql_error;
		return cod_ret, vCredito, vTarjeta;
	END IF;
 END EXCEPTION;


	IF (pNumCliente = "") THEN
		LET cod_ret = '001'; -- El Cliente viene vacio
	ELSE
	   	IF EXISTS(SELECT numcte FROM bdicred:sd_maecred WHERE numcte = pNumCliente) THEN
				SELECT LIMIT 1 c.num_credito,t.num_tarjeta INTO vCredito,vTarjeta FROM bdicred:sd_maecred c 
				INNER JOIN bdicred:sd_tarjeta t ON c.num_credito = t.num_credito 
				WHERE c.numcte = pNumCliente;
				
				LET cod_ret = '000';
				
				IF (vCredito = '' OR vCredito IS NULL) THEN
					LET cod_ret = '003'; -- El crédito viene vacio
				ELIF (vTarjeta = '' OR vTarjeta IS NULL) THEN
					LET cod_ret = '004'; -- La tarjeta viene vacia
				END IF;
				
		ELSE
				LET cod_ret = '002'; -- No existe el número de cliente
		END IF;

	END IF;
	return cod_ret,vCredito,vTarjeta;

 END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacterelacionado (cTipo CHAR (1), cAux1 CHAR(10), cAux2 CHAR(10))

RETURNING CHAR(5), CHAR(20), CHAR(100), CHAR(11), CHAR(12), CHAR(1), CHAR(100);

-- DECLARACION DE  VARIABLES--
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cNumCte CHAR(20);
DEFINE cNombreCompleto CHAR(104);
DEFINE cNombre1 CHAR(26);
DEFINE cNombre2 CHAR(26);
DEFINE cApellidopaterno CHAR(26);
DEFINE cApellidoMaterno CHAR(26);
DEFINE cTipoCte CHAR(1);
DEFINE cDescripcionCorta CHAR(100);
DEFINE cCuentas CHAR(11);
DEFINE cCreditos CHAR(12);
DEFINE iNumCuentas INT;
DEFINE iNumCreditos INT;
DEFINE cContador INT;

--INICIALIZACION DE VARIABLES--
LET iSqlErr = 0;
LET cCodRet = '000';
LET cNumCte = '';
LET cNombreCompleto = '';
LET cNombre1 = '';
LET cNombre2 = '';
LET cApellidoPaterno = '';
LET cApellidoMaterno = '';
LET cTipoCte = '0';
LET cDescripcionCorta = '';
LET cCuentas = '';
LET cCreditos = '';
LET iNumCuentas = 0;
LET iNumCreditos = 0;
LET cContador = 0;

--SET DEBUG FILE TO "/tmp/sp_ConsultaCteRelacionado.out";
--TRACE ON;

BEGIN
    ON EXCEPTION SET iSqlErr
        IF iSqlErr !=0 THEN
            LET cCodRet = iSqlErr;
            IF EXISTS(SELECT 1 FROM tmp_siCliente) THEN
                DROP TABLE tmp_siCliente;
            END IF;
            IF EXISTS(SELECT 1 FROM tmp_Cuentas) THEN
                DROP TABLE tmp_Cuentas;
            END IF;
            IF EXISTS(SELECT 1 FROM tmp_Creditos) THEN
                DROP TABLE tmp_Creditos;
            END IF;
            IF EXISTS(SELECT 1 FROM tmp_siCteRelacionado) THEN
                DROP TABLE tmp_siCteRelacionado;
            END IF;
            IF EXISTS(SELECT 1 FROM tmpReporte) THEN
                DROP TABLE tmpReporte;
            END IF;
            RETURN cCodRet, cNumCte, cNombreCompleto, cCuentas, cCreditos, cTipoCte, cDescripcionCorta;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;

    IF cTipo = '1' THEN

        SELECT DISTINCT numcte
        FROM si_cte_bitacora
        WHERE fecha_insert BETWEEN cAux1 AND cAux2
        AND numeric2_nvo <> 0
        ORDER BY numcte
        INTO TEMP tmp_siCte
        WITH NO LOG;

        SELECT a.numcte, b.nombre1, b.nombre2, b.apell_paterno, b.apell_materno, b.numeric2
        FROM tmp_siCte a, si_cliente b
        WHERE a.numcte = b.numcte
        AND numeric2 <> 0
        ORDER BY a.numcte
        INTO TEMP tmp_siCliente
        WITH NO LOG;

        DROP TABLE tmp_siCte;

    ELIF cTipo = '2' THEN
        SELECT numcte, nombre1, nombre2, apell_paterno, apell_materno, numeric2
        FROM si_cliente
        WHERE numcte = cAux1
        AND numeric2 <> 0
        ORDER BY numcte
        INTO TEMP tmp_siCliente
        WITH NO LOG;

    ELIF cTipo = '3' THEN
        SELECT numcte, nombre1, nombre2, apell_paterno, apell_materno, numeric2
        FROM si_cliente
        WHERE  numeric2 = cAux1
        ORDER BY numcte
        INTO TEMP tmp_siCliente
        WITH NO LOG;
    END IF;

    CREATE INDEX idx_tmpnumcte ON tmp_siCliente(numcte);
    UPDATE statistics high FOR TABLE tmp_siCliente(numcte);

    SELECT b.num_cte, b.cuenta
    FROM tmp_siCliente a, bdicheq:sc_maechq b
    WHERE  a.numcte = b.num_cte
    ORDER BY cuenta
    INTO TEMP tmp_Cuentas
    WITH NO LOG;

    CREATE INDEX idx_tmpcuentas ON tmp_Cuentas(num_cte);
    UPDATE statistics high FOR TABLE tmp_Cuentas(num_cte);

    SELECT b.numcte, b.num_credito
    FROM tmp_siCliente a, bdicred:sd_maecred b
    WHERE  a.numcte = b.numcte
    ORDER BY num_credito
    INTO TEMP tmp_Creditos
    WITH NO LOG;

    CREATE INDEX idx_tmpcreditos ON tmp_Creditos(numcte);
    UPDATE statistics high FOR TABLE tmp_Creditos(numcte);

    SELECT clavetipo, descripcioncorta
    FROM si_catcterelacionado
    WHERE clavetipo <> 0
    INTO TEMP tmp_siCteRelacionado
    WITH NO LOG;

    CREATE INDEX idx_tmpcterelacionado ON tmp_siCteRelacionado(clavetipo);
    UPDATE statistics high FOR TABLE tmp_siCteRelacionado(clavetipo);

    CREATE TEMP TABLE tmpReporte
    (
    numcte CHAR(9),
    nomcte CHAR(104),
    cuentas CHAR(11),
    creditos CHAR(12),
    tipocte CHAR(1),
    desccorta CHAR(100),
    contador CHAR(5)
    );
				
    FOREACH

        SELECT numcte, nombre1, nombre2, apell_paterno, apell_materno
        INTO cNumCte, cNombre1, cNombre2, cApellidoPaterno, cApellidoMaterno
        FROM tmp_siCliente

        LET cNombreCompleto = TRIM(nvl(cNombre1,' ')) || ' ' ||
                                                        TRIM(nvl(cNombre2, ' ')) || ' ' ||
                                                        TRIM(nvl(cApellidoPaterno, ' ')) || ' ' ||
                                                        TRIM(nvl(cApellidoMaterno, ' '));

        SELECT a.numeric2, b.descripcioncorta
        INTO cTipoCte, cDescripcionCorta
        FROM  tmp_siCliente a, tmp_sicterelacionado b
        WHERE numcte = cNumCte
        AND a.numeric2 = b.clavetipo;
        
        SELECT COUNT(cuenta) INTO iNumCuentas FROM tmp_Cuentas WHERE num_cte = cNumCte;
        SELECT COUNT(num_credito) INTO iNumCreditos FROM tmp_Creditos WHERE numcte = cNumCte;

        IF iNumCuentas >= iNumCreditos THEN

            LET cContador = 0;

                IF iNumCuentas = 0 THEN
			
                    INSERT INTO tmpReporte(numcte, nomcte, cuentas, creditos, tipocte, desccorta, contador)
                    VALUES (cNumCte, cNombreCompleto, '', '', cTipoCte, cDescripcionCorta, cContador);
	
                ELSE

                    FOREACH
		
                        SELECT cuenta 
			INTO cCuentas 
			FROM tmp_Cuentas 
			WHERE num_cte = cNumCte 
			ORDER BY cuenta

			LET cContador = cContador + 1;

			INSERT INTO tmpReporte(numcte, nomcte, cuentas, creditos, tipocte, desccorta, contador)
			VALUES (cNumCte, cNombreCompleto, cCuentas, '', cTipoCte, cDescripcionCorta, cContador);
	
                    END FOREACH;
	
                END IF

                LET cContador = 0;

                FOREACH

                    SELECT num_credito
                    INTO cCreditos 
                    FROM tmp_Creditos 
                    WHERE numcte = cNumCte 
                    ORDER BY num_credito

                    LET cContador = cContador + 1;

                    UPDATE tmpReporte
                    SET creditos = cCreditos
                    WHERE contador = cContador;

                END FOREACH;

            ELSE

                LET cContador = 0;

                FOREACH

                SELECT num_credito
                INTO cCreditos 
                FROM tmp_Creditos 
                WHERE numcte = cNumCte 
                ORDER BY num_credito

		LET cContador = cContador + 1;

		INSERT INTO tmpReporte(numcte, nomcte, cuentas, creditos, tipocte, desccorta, contador)
		VALUES (cNumCte, cNombreCompleto, '', cCreditos, cTipoCte, cDescripcionCorta, cContador);
		
            END FOREACH;
	
            LET cContador = 0;

            FOREACH
             
                SELECT cuenta 
		INTO cCuentas 
		FROM tmp_Cuentas 
		WHERE num_cte = cNumCte 
		ORDER BY cuenta

                LET cContador = cContador + 1;

                UPDATE tmpReporte
                SET cuentas = cCuentas
		WHERE contador = cContador;

            END FOREACH;

        END IF;

    END FOREACH;

    FOREACH

        SELECT numcte, nomcte, cuentas, creditos, tipocte, desccorta
	INTO cNumCte, cNombreCompleto, cCuentas, cCreditos, cTipoCte, cDescripcionCorta
	FROM tmpReporte

        RETURN cCodRet, cNumCte, cNombreCompleto, cCuentas, cCreditos, cTipoCte, cDescripcionCorta WITH RESUME;

    END FOREACH;

    DROP TABLE tmp_siCliente;
    DROP TABLE tmp_Cuentas;
    DROP TABLE tmp_Creditos;
    DROP TABLE tmp_siCteRelacionado;
    DROP TABLE tmpReporte;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".valprospectoact(cEmpresa CHAR(4),
                                                     cNumcte  CHAR(20))
  RETURNING CHAR(5), CHAR(1);

   --DEFINICION DE VARIABLES
   DEFINE cCodret             CHAR(5);
   DEFINE cExiste			  CHAR(1);
   DEFINE iSqlErr             INTEGER;
   DEFINE cTipoCliente	      CHAR(1);

   --INCIALIZACION DE VARIABLES
   LET cCodret = '00000';
   LET cExiste = 0;
   LET cTipoCliente = "0";

   BEGIN

        ON EXCEPTION SET iSqlerr
            IF iSqlErr <> 0 THEN
                LET cCodret = iSqlErr;
                RETURN cCodret,cExiste ;
            END IF;
        END EXCEPTION;

  --SET DEBUG FILE TO '/tmp/ValProspectoAct.out';
  --TRACE ON;

  -- cExiste = 1 Cliente Titular
  -- cExiste = 2 Cliente Prospecto Activo
  -- cExiste = 3 Cliente Prospecto Inactivo
  -- cExiste = 4 Tipo de Cliente incorrecto

  SELECT tipo_cliente INTO cTipoCliente FROM si_cliente WHERE numcte = cNumcte;

	IF cTipoCliente = "1" THEN
		LET cExiste = 1;
	ELIF cTipoCliente = "2" THEN
		IF EXISTS (	select 1 from bdicred:sd_tarjeta tar, bdicred:sd_maecred cred
				where cred.numcte = cNumcte
				and cred.num_credito = tar.num_credito
				and tar.tipo_tarjeta = 'A'
				and tar.status_tar = 'A') THEN
			LET cExiste = 2;
		ELIF EXISTS (SELECT 1 FROM bdicheq:sc_firmantes WHERE numcte = cNumcte) THEN
			LET cExiste = 2;
		ELIF EXISTS(SELECT 1 FROM bdinvers:sv_cotitular WHERE numcte = cNumcte) THEN
			LET cExiste = 2;
		--ELIF EXISTS (SELECT 1 FROM bdinteg:si_adiccoppel WHERE numcte = cNumcte AND secuencia <> 1) THEN
			--LET cExiste = 2;
		ELSE
			LET cExiste = 3;
		END IF;
	ELSE
		LET cExiste = 4;
	END IF;

  RETURN  cCodret,cExiste;

  END
--*************************************************************************
--| Procedimiento   : sp_ValidaClienteProspectoSPL
--| Versión         : 1.0
--| Creado por      : Martha Aguirre
--| Fecha creacion  : Mayo de 2009
--| Descripción     : Realiza una busqueda para validar la existencia
--|                   de un cliente activo y adicional.
--| Modificado por: Martha Aguirre
--| Modificación: Se comenta la consulta a la tabla de adicionales coppel
--1 Fecha Modificación: 01 Abril de 2009
--*************************************************************************
END PROCEDURE                                              
;

CREATE PROCEDURE "informix".macteline(pempresa char(3), pnum_cliente CHAR(20),
                           pfecha_alta  DATE,
                           pmotivo      CHAR(100))
   RETURNING CHAR(5);

   --####################################################################
   --#####                    Define variables                      #####
   --####################################################################

   DEFINE i               SMALLINT;
   DEFINE text            CHAR(100);
   DEFINE sqlerr,isamerr  SMALLINT;
   DEFINE cod_ret         CHAR(5);
   DEFINE v_hay_cteln     SMALLINT;
   DEFINE v_num_credito   LIKE sd_maecred.num_credito;
   DEFINE v_num_cliente   char(20); --LIKE sd_listanegrabr.numcte;
   DEFINE v_cliente       char(20); --LIKE sd_listanegrabr.numcte;

-- ##########################################################################
-- #####                    Control de Errores
-- ##########################################################################

   ON EXCEPTION SET sqlerr, isamerr, text
      LET cod_ret = sqlerr;
      SET DEBUG FILE TO "macteline.err"; -- se guarda en /users/desarrollo
      TRACE sqlerr || " * " || isamerr || " * " || text;
      RETURN cod_ret;
   END EXCEPTION;

   SET ISOLATION TO DIRTY READ;
   SET LOCK MODE TO WAIT 3;



   --####################################################################
   --#####                 Inicializa Variables                     #####
   --####################################################################

   LET cod_ret       = "000";
   LET v_num_cliente = " ";

   --#####################################################################
   --######            Inicio de Transaccion                         #####
   --#####################################################################

   IF pnum_cliente IS NULL OR
      pnum_cliente = " " THEN
      LET cod_ret = "202"; -- CLIENTE NULO O BLANCO
      RETURN cod_ret;
   ELSE
      LET v_num_cliente = pnum_cliente;
   END IF;


   SELECT numcte INTO v_cliente
   FROM bdinteg:si_cliente
   WHERE numcte = v_num_cliente;
   IF v_cliente IS NULL OR
      v_cliente = " " THEN
      LET cod_ret = "238"; -- NO EXISTE EL CLIENTE EN CENTRAL
      RETURN cod_ret;
   END IF;


{
   SELECT COUNT(*) INTO v_hay_cteln
   FROM sd_listanegrabr
   WHERE numcte = v_cliente;

   IF v_hay_cteln > 0 THEN
      LET cod_ret = "252"; -- EL CLIENTE YA EXISTE EN sd_listanegrabr
      RETURN cod_ret;
   END IF;

   IF pfecha_alta IS NULL OR
      pfecha_alta = " " THEN
      LET cod_ret = "247"; -- FECHA NULA O EN BLANCO
      RETURN cod_ret;
   END IF;

   IF pmotivo IS NULL OR
      pmotivo = " " THEN
      LET cod_ret = "249"; -- MOTIVO NULO O EN BLANCO
      RETURN cod_ret;
   END IF;

   IF cod_ret != "000" THEN
      RETURN cod_ret;
   ELSE
      BEGIN
         INSERT INTO sd_listanegrabr VALUES (v_cliente,pfecha_alta,pmotivo,0);
      END;
   END IF;
}
RETURN cod_ret;
END PROCEDURE
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

create procedure "informix".pagoenviar1(pempresa char(3),
                                p_sucursal char(4),
                                p_usuario char(8),
                                p_tipomov char(1),
                                p_movspeua char(6),
                                p_folio_suc char(16),
                                p_plaza_orden char(5),
                                p_cta_propia char(20),
                                p_importe money(14,2),
                                p_comision money(10,2),
                                p_benef char(30),
                                p_banco_rec char(4),
                                p_plaza_rec char(5),
                                p_cta_banco char(20),
                                p_instrucciones char(210),
                                p_hora_local datetime hour to second,
                                p_sucbcodes char(4),
                                p_nomsucbcodes char(40))
                                returning char(5), char(60);

define v_codret char(5);
define v_fecha date;
define v_hora_limite datetime hour to second;
define v_comision money(10,2);
define v_us7 char(7);
define v_us6 char(6);
define v_us5 char(5);
define v_us4 char(4);
define v_us3 char(3);
define v_us2 char(2);
define v_iva decimal(9,6);
define v_ivacom money(10,2);
define v_plaza char(3);
define v_nombre char(60);
define v_materno, v_paterno, v_nombre1, v_nombre2 char(12);
define v_limaut money(16,2);
define v_razon_soc char(35);
define v_transpeua, v_trancheq, v_trancom, v_banco char(4);
define v_rastreo integer;
define v_minimo money(14,2);
define v_dia, v_mes char(2);
define v_year char(4);
define v_fecha_comp char(8);
define v_firmante char(20);
define v_firma_elect char(132);
define v_verif1, v_verif2 char(1);
define v_longitud,longitud,v_long_param_sc smallint;
define sql_err integer;



set lock mode to wait 3;

let v_verif1=" ";
let v_verif2=" ";
let v_codret="000";
let v_ivacom = 0;
begin
   on exception set sql_err
      if sql_err <> 0 then
         let v_codret = sql_err;
         return v_codret, p_folio_suc;
      end if
   end exception;

-- **** INICIO DE VALIDACIONES. ****

 return v_codret, p_folio_suc;  --Esta Linea se adiciono para hacer pruebas de Dlls

set isolation to dirty read;

-- Se valida plaza de envio y hora limite movimientos SPEUA.
let p_plaza_orden = p_plaza_orden;

select hora_limite into v_hora_limite
        from bdispeua:sp_plazasbanxico
        where plaza=p_plaza_orden;
if v_hora_limite is null then
        let v_codret="877";
        return v_codret, p_folio_suc;
end if;
if v_hora_limite < p_hora_local then
        let v_codret="877";
        return v_codret, p_folio_suc;
end if;

--Se valida plaza de Recepcion

select hora_limite into v_hora_limite
        from bdispeua:sp_plazasbanxico
        where plaza=p_plaza_rec;
if v_hora_limite is null then
        let v_codret="876";
        return v_codret, p_folio_suc;
end if;
if v_hora_limite <= current hour to minute then
        let v_codret="876";
        return v_codret, p_folio_suc;
end if;

-- Se valida sucursal

select nombre into v_nombre
        from bdinteg:si_sucursales
        where empresa = pempresa and sucursal=p_sucursal;

if v_nombre is null then
        let v_codret="102";
        return v_codret, p_folio_suc;
end if;

-- Se valida el Usuario

select limaut_mn into v_limaut
        from bdinteg:si_ejecut
        where ejecutivo=p_usuario;

if v_limaut is null then
        let v_codret="106";
        return v_codret, p_folio_suc;
end if;
if p_importe > v_limaut then
        let v_codret="881";
        return v_codret, p_folio_suc;
end if;

-- Se valida Tipo de Movimiento

select transacc_envio into v_transpeua
        from bdispeua:sp_operaciones
        where codigo=p_tipomov;

if v_transpeua is null then
        let v_codret="550";
        return v_codret, p_folio_suc;
end if;

-- Se valida Banco Receptor

select descripcion into v_nombre from bdinteg:si_bancos
        where banco=p_banco_rec;

if v_nombre is null then
        let v_codret="099";
        return v_codret, p_folio_suc;
end if;

let v_firmante=p_usuario;
let v_firma_elect = "0000000000";
select banco_speua, monto_minimo, tran_cargo, tran_comision, ult_cve_rastreo
        into v_banco, v_minimo, v_trancheq, v_trancom, v_rastreo
        from bdispeua:sp_param;

if v_banco is null then
        let v_codret="110";
        return v_codret, p_folio_suc;
end if;
if v_minimo > p_importe then
        let v_codret="875";
        return v_codret, p_folio_suc;
end if;

-- Se extrae la fecha del Movimiento

select fecha_hoy into v_fecha from bdinteg:si_fechas where empresa = pempresa;

-- Se realizan cargos a cheques
if p_cta_propia is not null and p_cta_propia!=" " then
-- Se extrae el nombre del Emisor

        select nombre1, nombre2, apell_paterno, apell_materno, razon_social
                into v_nombre1, v_nombre2, v_paterno, v_materno, v_razon_soc
                from bdinteg:si_cliente, sc_maechq
                where sc_maechq.num_cte=bdinteg:si_cliente.numcte
                and sc_maechq.empresa = pempresa and cuenta=p_cta_propia;

        if v_razon_soc is null or v_razon_soc = " " then
                let v_nombre=TRIM(v_nombre1)|| " " || TRIM(v_nombre2)|| " " ||
                              TRIM(v_paterno)|| " " || TRIM(v_materno);
        else
                let v_nombre=TRIM(v_razon_soc);
        end if;
        let v_longitud=length(p_cta_propia);
        if v_longitud=10 then
                let v_verif1=p_cta_propia[10, 10];
        elif v_longitud=9 then
                let v_verif1=p_cta_propia[9, 9];
        elif v_longitud=8 then
                let v_verif1=p_cta_propia[8, 8];
        end if;
        let v_longitud=length(p_cta_banco);
        if v_longitud=10 then
                let v_verif2=p_cta_banco[10, 10];
        elif v_longitud=9 then
                let v_verif2=p_cta_banco[9, 9];
        elif v_longitud=8 then
                let v_verif2=p_cta_banco[8, 8];
        elif v_longitud=7 then
                let v_verif2=p_cta_banco[7, 7];
        elif v_longitud=6 then
                let v_verif2=p_cta_banco[6, 6];
        elif v_longitud=5 then
                let v_verif2=p_cta_banco[5, 5];
        elif v_longitud=4 then
                let v_verif2=p_cta_banco[4, 4];
        elif v_longitud=3 then
                let v_verif2=p_cta_banco[3, 3];
        elif v_longitud=2 then
                let v_verif2=p_cta_banco[2, 2];
        end if;
else
        if p_comision=0 then
                let v_ivacom=0;
        else
                select plaza into v_plaza from bdinteg:si_sucursales
                        where empresa = pempresa and sucursal=p_sucursal;
                if v_plaza is null then
                        let v_iva=0;
                else
                        select iva into v_iva from bdinteg:si_plazas
                                where empresa = pempresa and plaza=v_plaza;
                        if v_iva is null then
                                let v_iva=0;
                        end if
                end if;
                let v_ivacom=p_comision*v_iva;
        end if;
        let v_nombre=" ";
        let p_cta_propia=" ";
end if;

let v_dia=day(v_fecha);
if length(v_dia) < 2 then
        let v_dia="0" || v_dia;
end if
let v_mes=month(v_fecha);
if length(v_mes) < 2 then
        let v_mes="0" || v_mes;
end if
let v_year=year(v_fecha);
let v_fecha_comp=v_dia || v_mes || v_year;
insert into bdispeua:sp_pagoenviar values(p_tipomov,
                                        p_movspeua,
                                        v_banco,
                                        p_plaza_orden,
                                        "CHQ",
                                        p_cta_propia,
                                        v_verif1,
                                        v_nombre,
                                        p_banco_rec,
                                        p_plaza_rec,
                                        "CHQ",
                                        p_cta_banco,
                                        v_verif2,
                                        p_benef,
                                        p_importe,
                                        p_comision,
                                        v_ivacom,
                                        p_folio_suc,
                                        v_fecha_comp,
                                        v_fecha_comp,
                                        p_instrucciones,
                                        "P",
                                        "",
                                        v_firmante,
                                        v_firma_elect,"");

return v_codret, p_folio_suc;
end
end procedure
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".sp_validapreedocta(cCuenta CHAR(20), dFechaMov DATE)

RETURNING
CHAR(5),
CHAR(5); --Codigo de Retorno

DEFINE iSqlErr      INTEGER;
DEFINE cCodRet      CHAR(5);
DEFINE iDia         INTEGER;
DEFINE iMes         INTEGER;
DEFINE iAnio        INTEGER;
DEFINE iFlag        INTEGER;

LET iDia   = day(dFechaMov);
LET iMes   = month(dFechaMov);
LET iAnio  = year(dFechaMov);
LET iFlag  = 0;
--SET LOCK MODE TO WAIT 10;

BEGIN

    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, cCodRet;
        END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/sp_validapreedocta.out";
    --TRACE ON;

    SELECT valor
    INTO iFlag
    FROM si_param
    WHERE cod_param = 99;

    IF iFlag = 1 THEN
        IF iDia < 21 THEN
            IF iMes = 1 Then
                IF EXISTS(SELECT 1 FROM bitacora_edocta WHERE num_credito = cCuenta AND fecha BETWEEN mdy(month(mdy(iMes, iDia, iAnio) - 1 units month)::date, day(mdy(1,21,1900)), year(mdy(iMes, iDia, iAnio-1))) AND mdy(iMes, iDia, iAnio)) THEN
                    LET cCodRet = '00002';
                ELSE
                    LET cCodRet = '00000';
                END IF;
            ELSE
                IF EXISTS(SELECT 1 FROM bitacora_edocta WHERE num_credito = cCuenta AND fecha BETWEEN mdy(month(mdy(iMes, iDia, iAnio) - 1 units month)::date, day(mdy(1,21,1900)), year(mdy(iMes, iDia, iAnio))) AND mdy(iMes, iDia, iAnio)) THEN
                    LET cCodRet ='00002';
                ELSE
                    LET cCodRet ='00000';
                END IF;
            END IF;
        ELSE
            IF EXISTS(SELECT 1 FROM bitacora_edocta WHERE num_credito = cCuenta AND fecha BETWEEN mdy(month(mdy(iMes, iDia, iAnio)), day(mdy(1,21,1900)), year(mdy(iMes, iDia, iAnio))) AND mdy(iMes, iDia, iAnio)) THEN
                LET cCodRet ='00002';
            ELSE
                LET cCodRet ='00000';
            END IF;
        END IF;
    ELSE
        LET cCodRet ='00001';
    END IF;

    RETURN '00000',cCodRet;

END;
END PROCEDURE
DOCUMENT
"Valida Datos Pregunta Estado de Cuenta",
"AUTOR: Saúl Ivanhoe Valdespino",
"FECHA: 08/05/2009",
"BD: bdinteg";

CREATE PROCEDURE "informix".sp_histrespcte(p_Tipo INTEGER, p_FechaIni DATE, p_FechaFin DATE)
RETURNING
    CHAR(5); ---cod_ret

    DEFINE v_cod_ret            CHAR(5);
    DEFINE iSqlErr              INTEGER;
    DEFINE iSamErr              INTEGER;
    DEFINE vDesErr              CHAR(60);
    DEFINE vDiaHoy              INTEGER;
    DEFINE vMesHoy              INTEGER;
    DEFINE vAnioHoy             INTEGER;
    DEFINE iFlag                INTEGER;
    DEFINE vFechaHoy            DATE;

     LET v_cod_ret  = '00009';
     LET iFlag  = 0;

    --SET LOCK MODE TO WAIT 10;

BEGIN

   ON EXCEPTION
        SET iSqlErr, iSamErr, vDesErr
        IF iSqlErr <> 0 THEN
                LET v_cod_ret = iSqlErr;
                --EXECUTE PROCEDURE bdinteg:sp_desc_ret(20, v_cod_ret)
                --INTO v_cod_ret, vDesErr;
        END IF;
        RETURN v_cod_ret;
    END EXCEPTION;

    ---SET DEBUG FILE TO "/tmp/sp_histrespcte.out";
    ---TRACE ON;

     SELECT fecha_hoy 
     INTO   vFechaHoy
     FROM   si_fechas;

     LET vDiaHoy   = Day(vFechaHoy);
     LET vMesHoy   = Month(vFechaHoy);
     LET vAnioHoy  = Year(vFechaHoy);

     IF p_FechaIni > vFechaHoy THEN
        LET v_cod_ret ='00001';
     ELSE
         IF p_FechaFin > vFechaHoy THEN
            LET v_cod_ret ='00002';
         ELSE
             IF p_FechaIni > p_FechaFin THEN
                LET v_cod_ret ='00003';
             END IF; 
         END IF;
     END IF;

     IF p_Tipo = 1 AND v_cod_ret ='00009' THEN    
         IF vDiaHoy < 21 THEN
            IF vMesHoy = 1 THEN
               IF p_FechaIni BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy) - 1 units  month)::date, day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy -1))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                  LET v_cod_ret ='00004';
               ELSE
                   IF p_FechaFin BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy) - 1 units  month)::date, day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy -1))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                      LET v_cod_ret ='00005';
                   ELSE
                        SELECT limit 1 1 
                        INTO   iFlag
                        FROM   bitacora_edocta 
                        WHERE  fecha BETWEEN p_FechaIni And p_FechaFin;
                        
                        IF iFlag = 1 THEN   
                           INSERT INTO bitacorahis_edocta(num_credito, sucursal, fecha, cajero, respuesta) 
                           SELECT num_credito, sucursal, fecha, cajero, respuesta
                           FROM   bitacora_edocta
                           WHERE  fecha BETWEEN p_FechaIni And p_FechaFin;

                           DELETE FROM bitacora_edocta Where fecha BETWEEN p_FechaIni And p_FechaFin;
                           LET v_cod_ret ='00000';
                        ELSE
                            LET v_cod_ret ='00006'; 
                        END IF; 
                   END IF;
               END IF;
            ELSE
                IF p_FechaIni BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy) - 1 units  month)::date, day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                   LET v_cod_ret ='00004';
                ELSE
                    IF p_FechaFin BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy) - 1 units  month)::date, day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                       LET v_cod_ret ='00005';
                    ELSE
                        SELECT limit 1 1 
                        INTO   iFlag
                        FROM   bitacora_edocta 
                        WHERE  fecha BETWEEN p_FechaIni And p_FechaFin;
                        
                        IF iFlag = 1 THEN   
                           INSERT INTO bitacorahis_edocta(num_credito, sucursal, fecha, cajero, respuesta) 
                           SELECT num_credito, sucursal, fecha, cajero, respuesta
                           FROM   bitacora_edocta
                           WHERE  fecha BETWEEN p_FechaIni And p_FechaFin;

                           DELETE FROM bitacora_edocta Where fecha BETWEEN p_FechaIni And p_FechaFin;
                           LET v_cod_ret ='00000';
                        ELSE
                            LET v_cod_ret ='00006'; 
                        END IF; 
                    END IF;
                END IF;
            END IF;
         ELSE                                          
             IF p_FechaIni BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy)), day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                LET v_cod_ret ='00004';
             ELSE
                 IF p_FechaFin BETWEEN mdy(month ( mdy(vMesHoy,vDiaHoy,vAnioHoy)), day(mdy(1,21,1900) ),year(mdy(vMesHoy,vDiaHoy,vAnioHoy))) And mdy(vMesHoy,20,vAnioHoy)  THEN
                    LET v_cod_ret ='00005';
                 ELSE
                     SELECT limit 1 1 
                     INTO   iFlag
                     FROM   bitacora_edocta 
                     WHERE  fecha Between p_FechaIni And p_FechaFin;
                        
                     IF iFlag = 1 THEN   
                        INSERT INTO bitacorahis_edocta(num_credito, sucursal, fecha, cajero, respuesta) 
                        SELECT num_credito, sucursal, fecha, cajero, respuesta
                        FROM   bitacora_edocta
                        WHERE  fecha BETWEEN p_FechaIni And p_FechaFin;

                        DELETE FROM bitacora_edocta Where fecha BETWEEN p_FechaIni And p_FechaFin;
                        LET v_cod_ret ='00000';
                     ELSE
                         LET v_cod_ret ='00006'; 
                     END IF; 
                 END IF;
             END IF;
         END IF;
    END IF;
 
    RETURN v_cod_ret;

END;
--******************************************************
--| Procedimiento : sp_histrespcte
--| Creado por    : Saúl Ivanhoe
--| Fecha         : 20 - Mayo - 2009
--| Descripción   : Historico Pregunta Edo. Cuenta 
--******************************************************
END PROCEDURE;

CREATE PROCEDURE "informix".sp_selcatcontable(p_sEmpresa CHAR(3))
	
    RETURNING CHAR(5) as codigo, 
            CHAR(4) as ccmayor, 
            CHAR(2) as ccsub, 
            CHAR(2) as ccsubsub, 
            CHAR(2) as ccssubsub, 
            CHAR(2) as ccsssubsub, 
            CHAR(2) as sector, 
            CHAR(50) as nombre, 
            CHAR(1) as naturaleza, 
            CHAR(1) as auxiliar, 
            CHAR(1) as tipo_cuenta;		  
	--DEFINICION DE VARIABLES
	DEFINE vCodret 				CHAR(5);
	DEFINE iSqlErr          	INTEGER;
	DEFINE v_sccmayor			CHAR(4);
	DEFINE v_sccsub				CHAR(2);
	DEFINE v_sccsubsub			CHAR(2);
	DEFINE v_sccssubsub			CHAR(2);
	DEFINE v_sccsssubsub		CHAR(2);
	DEFINE v_ssector			CHAR(2);
	DEFINE v_snombrecuenta		CHAR(50);
	DEFINE v_snaturaleza		CHAR(1);
	DEFINE v_sauxiliar			CHAR(1);
	DEFINE v_stipo_cuenta		CHAR(1);
	
	--+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	--CREADO POR: VLADIMIR FÉLIX GÁLVEZ 8/JULIO/2009
	--Sp que obtiene las cuentas contables que no manejan auxiliares
	--que sean cuentas de detalle
	--DEBUG DEL PROCEDURE
	--SET DEBUG FILE TO "/tmp/sp_consultarcatcontable.out";
	--TRACE ON;
	--+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	
	BEGIN
		ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET vCodret = iSqlErr;
                RETURN vCodret,'','','','','','','','','','';
            END IF;
        END EXCEPTION;
		
		IF (p_sEmpresa = '' OR p_sEmpresa IS NULL) THEN
			LET vCodret = '001';
			RETURN vCodret,'','','','','','','','','','';
		END IF;
		
		LET vCodret = '000';
		
		FOREACH
			SELECT ccmayor, ccsub, ccsubsub, ccssubsub, ccsssubsub, sector,nombre, naturaleza_cta, auxiliar, tipo_cuenta
			INTO v_sccmayor, v_sccsub, v_sccsubsub, v_sccssubsub, v_sccsssubsub, v_ssector, v_snombrecuenta, v_snaturaleza, v_sauxiliar, v_stipo_cuenta
			FROM bdinteg:"informix".si_catalog
			WHERE empresa = p_sEmpresa
			ORDER BY 1,2,3,4,5,6
			
			RETURN vCodret, v_sccmayor, v_sccsub, v_sccsubsub, v_sccssubsub, v_sccsssubsub, v_ssector, v_snombrecuenta, v_snaturaleza, v_sauxiliar, v_stipo_cuenta WITH RESUME;
			
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_selciudades(p_sEmpresa CHAR(3))
                
    RETURNING CHAR(5) as codigo, CHAR(3) as claveregion, CHAR(40) as nombreregion;
		    
	--DEFINICION DE VARIABLES
	DEFINE vCodret 				CHAR(5);
	DEFINE iSqlErr          	INTEGER;
	DEFINE v_sclaveregion		CHAR(3);
	DEFINE v_snombreregion		CHAR(40);
	
	--++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	--CREADO POR: VLADIMIR FÉLIX GÁLVEZ 8/JULIO/2009
	--Sp que obtiene las ciudades de la tabla si_regiones
	--DEBUG DEL PROCEDURE
	--SET DEBUG FILE TO "/tmp/sp_consultarcatciudades.out";
	--TRACE ON;
	--++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	
	BEGIN
		ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET vCodret = iSqlErr;
                RETURN vCodret,'','';
            END IF;
        END EXCEPTION;
		
		IF (p_sEmpresa = '' OR p_sEmpresa IS NULL) THEN
			LET vCodret = '001';
			RETURN vCodret,'','';
		END IF;
		
		LET vCodret = '000';
		
		FOREACH
			SELECT regional, nombre
			INTO v_sclaveregion, v_snombreregion
			FROM bdinteg:"informix".si_regional
			WHERE regional = regional
                AND empresa = p_sEmpresa
			ORDER BY regional
			
			RETURN vCodret, v_sclaveregion, v_snombreregion WITH RESUME;
			
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_selempresa(p_sEmpresa CHAR(3))
	
    RETURNING 	CHAR(50) AS razon_social,
				CHAR (13) AS rfc,
				CHAR (40) AS domicilio_fiscal,
				CHAR (5) AS codigo_postal;

	DEFINE v_sRazonSocial 		CHAR(50);
	DEFINE v_sRfc				CHAR(13);
	DEFINE v_sDomicilioFiscal	CHAR(40);
	DEFINE v_sCodigoPostal		CHAR(5);

	--------------------------------------------------------------------------
	-- Creado por Erick Zamora 08/01/2009
	--SET DEBUG FILE TO "/tmp/sp_consultarEmpresa.out
	--TRACE ON;
	--------------------------------------------------------------------------

	BEGIN
		IF p_sEmpresa = '' THEN
			RETURN '', '', '', '';
		END IF

		SELECT razon_social, rfc, domicilio_fiscal, codigo_postal
		INTO v_sRazonSocial, v_sRfc, v_sDomicilioFiscal, v_sCodigoPostal
		FROM bdinteg:"informix".si_empresas
		WHERE empresa = p_sEmpresa;

		RETURN v_sRazonSocial, v_sRfc, v_sDomicilioFiscal, v_sCodigoPostal;

	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_selmoneda(p_sEmpresa CHAR(3))
	
    RETURNING CHAR(5) AS codigo, 
            CHAR(2) AS divisa, 
            CHAR(4) AS sigla, 
            CHAR(3) AS cve_intl, 
            CHAR(3) AS cve_oficial, 
            CHAR(3) AS empresa, 
            CHAR(30) AS descripcion;		 
		  
	--DEFINICION DE VARIABLES
	DEFINE vCodret 				CHAR(5);
	DEFINE iSqlErr          	INTEGER;
	DEFINE v_sclavemoneda		CHAR(3);
	DEFINE v_snombremoneda		CHAR(40);
	DEFINE v_ssigla				CHAR(4);		
	DEFINE v_scve_intl			CHAR(3);
	DEFINE v_scve_oficial		CHAR(3);
	DEFINE v_sempresa			CHAR(3);
	
	--++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	--CREADO POR: VLADIMIR FÉLIX GÁLVEZ 8/JULIO/2009
	--Sp que obtiene las monedas de la tabla si_divisas
	--DEBUG DEL PROCEDURE
	--SET DEBUG FILE TO "/tmp/sp_consultarcatmonedas.out";
	--TRACE ON;
	--++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
	
	BEGIN
		ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET vCodret = iSqlErr;
                RETURN vCodret,'','','','','','';
            END IF;
        END EXCEPTION;
		
		IF (p_sEmpresa = '' OR p_sEmpresa IS NULL) THEN
			LET vCodret = '001';
			RETURN vCodret,'','','','','','';
		END IF;
		
		LET vCodret = '000';
		
		FOREACH
			SELECT divisa, sigla, cve_intl, cve_oficial, empresa, descripcion
			INTO v_sclavemoneda, v_ssigla, v_scve_intl, v_scve_oficial, v_sempresa, v_snombremoneda
			FROM bdinteg:"informix".si_divisas
			WHERE empresa = p_sEmpresa
                AND divisa = divisa
			ORDER BY divisa

			RETURN vCodret, v_sclavemoneda, v_ssigla, v_scve_intl, v_scve_oficial, v_sempresa, v_snombremoneda WITH RESUME;
			
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".consrecursos(pEmpresa char(3), pNumeroCuenta char(20))

-- DATOS A REGRESAR --
RETURNING char(5),     -- Codigo de retorno
          char(2),     -- Procedencia apertura
          char(2),     -- Procedencia mantener
          char(2),     -- Monto
          char(2),     -- Dep. Cantidad
          char(2),     -- Dep. Monto
          char(2),     -- Ret. Cantidad
          char(2),     -- Ret. Monto
          char(60),    -- Procedencia apertura descripcion
          char(60),    -- Procedencia mantener descripcion
          char(60),    -- Monto descripcion
          char(60),    -- Dep. Cantidad descripcion
          char(60),    -- Dep. Monto descripcion
          char(60),    -- Ret. Cantidad descripcion
          char(60),    -- Ret. Monto descripcion
          char(2),     -- Forma de Apertura
          money(14,2), -- Monto de Apertura
          CHAR(20)     -- Cuenta de Cargo

-- VARIABLES --
DEFINE vCodRet          char(5);
DEFINE vp_aper          char(2);
DEFINE vp_mant          char(2);
DEFINE vm_mensual       char(2);
DEFINE vd_cant          char(2);
DEFINE vd_monto         char(2);
DEFINE vr_cant          char(2);
DEFINE vr_monto         char(2);

DEFINE vp_aper_desc     char(60);
DEFINE vp_mant_desc     char(60);
DEFINE vm_mensual_desc  char(60);
DEFINE vd_cant_desc     char(60);
DEFINE vd_monto_desc    char(60);
DEFINE vr_cant_desc     char(60);
DEFINE vr_monto_desc    char(60);
DEFINE vforma_aper      char(2);
DEFINE vmonto_aper      money(14,2);
DEFINE vcta_cargo       char(20);
DEFINE vprodcrec        char(4);
DEFINE vprodcta     char(4);


-- INICIALIZACION DE VARIABLES --
LET vCodRet         ="000";
LET vp_aper         ="";
LET vp_mant         ="";
LET vm_mensual      ="";
LET vd_cant         ="";
LET vd_monto        ="";
LET vr_cant         ="";
LET vr_monto        ="";
LET vp_aper_desc    ="";
LET vp_mant_desc    ="";
LET vm_mensual_desc ="";
LET vd_cant_desc    ="";
LET vd_monto_desc   ="";
LET vr_cant_desc    ="";
LET vr_monto_desc   ="";
LET vforma_aper     = "";
LET vmonto_aper     = 0;
LET vcta_cargo      = "";
LET vprodcrec       = "";
LET vprodcta        = "";

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

SELECT valor 
  INTO vprodcrec
  FROM bdicheq:sc_param
 WHERE empresa = pEmpresa
   AND codparam = "PRODCREC";

if exists (select cuenta 
             from bdicheq:sc_maechq 
            where empresa = pEmpresa 
              and cuenta = pNumeroCuenta) Then
            
    SELECT producto 
      INTO vprodcta
      FROM bdicheq:sc_maechq
     WHERE empresa = pEmpresa
       AND cuenta = pNumeroCuenta;

    IF vprodcta = vprodcrec THEN

        SELECT proced_aperturacta, proced_mantenercta, monto_mensual, depositos_cantidad, 
               depositos_monto, retiros_cantidad, retiros_monto, imp_chq_rem, instrucc, cuentadep
          INTO vp_aper, vp_mant, vm_mensual, vd_cant, vd_monto,
               vr_cant, vr_monto, vmonto_aper, vforma_aper, vcta_cargo
          FROM bdicheq:sc_maechq a, bdicheq:sc_maeinstrucc b
         WHERE a.empresa =  pEmpresa 
           AND a.cuenta =  pNumeroCuenta
           AND b.empresa = a.empresa
           and b.cuenta = a.cuenta
           and b.capint = "R";
    ELSE
        SELECT proced_aperturacta, proced_mantenercta, monto_mensual,
               depositos_cantidad, depositos_monto,
               retiros_cantidad, retiros_monto, imp_chq_rem, "", ""
          INTO vp_aper, vp_mant, vm_mensual, vd_cant, vd_monto,
               vr_cant, vr_monto, vmonto_aper, vforma_aper, vcta_cargo
          FROM bdicheq:sc_maechq a
         WHERE a.empresa =  pEmpresa 
           AND a.cuenta =  pNumeroCuenta;
    END IF

    SELECT {+INDEX(si_tipo_procedencia idx_procedencia), +INDEX(si_tipo_montomes idx_montomes), +INDEX(si_tipo_nummov idx_nummov), +INDEX(si_tipo_montomov idx_montomov)} 
           a.descripcion, d.descripcion, b.descripcion, c.descripcion
      INTO vp_aper_desc, vm_mensual_desc, vd_cant_desc, vd_monto_desc
      FROM bdinteg:si_tipo_procedencia a,
           bdinteg:si_tipo_nummov b,
           bdinteg:si_tipo_montomov c,
           bdinteg:si_tipo_montomes d
     WHERE a.procedencia = vp_aper 
       and b.codnummo = vd_cant 
       and c.codnummonto = vd_monto 
       and d.codigo = vm_mensual;

    SELECT {+INDEX(si_tipo_procedencia idx_procedencia), +INDEX(si_tipo_nummov idx_nummov), +INDEX(si_tipo_montomov idx_montomov)} 
           a.descripcion, b.descripcion, c.descripcion
      INTO vp_mant_desc, vr_cant_desc, vr_monto_desc
      FROM bdinteg:si_tipo_procedencia a,
           bdinteg:si_tipo_nummov b,
           bdinteg:si_tipo_montomov c
     WHERE a.procedencia = vp_mant 
       and b.codnummo = vr_cant 
       and c.codnummonto = vr_monto;

    RETURN vCodRet, vp_aper, vp_mant, vm_mensual, vd_cant, vd_monto, vr_cant, vr_monto,vp_aper_desc, vp_mant_desc,
           vm_mensual_desc, vd_cant_desc, vd_monto_desc, vr_cant_desc, vr_monto_desc, vforma_aper,
           vmonto_aper, vcta_cargo;

end if;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerdialaborable(p_sEmpresa CHAR(3), p_dFecha DATE)
	RETURNING  CHAR(6) AS CodRet, DATE AS Dia;

	DEFINE v_inumdiahab INTEGER;
	DEFINE v_dfecha DATE;
	DEFINE iSqlErr INTEGER;
	DEFINE vCodRet CHAR(6);

--***********************************************************
-- Creado por Marcos Cuevas    27/feb/2009               --*
-- Debug del Procedure                                    --*
-- SET DEBUG FILE TO "/tmp/sp_ObtenerDiaLaborable.out";--*
-- TRACE ON;                                              --*
--***********************************************************

BEGIN

ON EXCEPTION
	SET iSqlErr
	IF iSqlErr <> 0 THEN
		LET vCodRet = iSqlErr;
		RETURN vCodRet,'01-01-1900';
	END IF;
END EXCEPTION;

	LET vCodRet = '000000';
	LET v_inumdiahab = 0;
	LET v_dfecha = p_dFecha;

	IF (p_sEmpresa is NULL) OR (p_sEmpresa = '') THEN
		LET vCodRet = '000001';
		LET v_dfecha = '01-01-1900';
	END IF;

	IF (p_dFecha is NULL) OR (p_dFecha = '') THEN
		LET vCodRet = '000001';
		LET v_dfecha = '01-01-1900';
	END IF;

	IF (vCodRet = '000000') THEN
		WHILE (v_inumdiahab = 0)
			IF NOT EXISTS (SELECT fecha FROM bdinteg:si_feriado WHERE fecha = v_dFecha AND laborable = 'N' AND empresa = p_sEmpresa) THEN
				LET v_inumdiahab = v_inumdiahab + 1;
			ELSE
				LET v_dfecha = v_dFecha + 1 UNITS DAY;
			END IF
		END WHILE;
	END IF;

	RETURN vCodRet,v_dfecha;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarcorreccionesdatoscte(pFechaInicial CHAR(10), pFechaFinal CHAR(10),p_NumCte CHAR(20), p_Tipo CHAR(1))
RETURNING
    CHAR (5)   AS  Cod_Ret,
	CHAR (26)  AS NumCte,
	CHAR (20)  AS Fecha,
	CHAR (13)  AS Rfc_Orig,
	CHAR (100) AS Nom_Ant,
	CHAR (13)  AS Rfc_Nvo,
	CHAR (100) AS Nom_Nvo,
	CHAR (8)   AS User_insert;

	--declaracion de variables
	DEFINE cCod_ret                 CHAR(5);
    DEFINE iSqlErr                  INTEGER;
    DEFINE iSamErr                  INTEGER;
	DEFINE cNumCte                  CHAR(20);
	DEFINE dFecha			        DATE;
	DEFINE cRfc_orig			    CHAR(13);
	DEFINE cNombre1_orig			CHAR(26);
	DEFINE cNombre2_orig			CHAR(26);
	DEFINE cApell_paterno_orig		CHAR(26);
	DEFINE cApell_materno_orig		CHAR(26);
	DEFINE cRfc_nvo			        CHAR(13);
	DEFINE cNombre1_nvo	            CHAR(26);
	DEFINE cNombre2_nvo		        CHAR(26);
	DEFINE cApell_paterno_nvo		CHAR(26);
	DEFINE cApell_materno_nvo		CHAR(26);
	DEFINE cNomCompletoAnterior     CHAR(100);
	DEFINE cNomCompletoActual 		CHAR(100);
	DEFINE cUser_insert				CHAR(8);

	--incilizacion de variables
	LET cNomCompletoAnterior        ="";
	LET cNomCompletoActual          = "";
	LET cCod_ret                    = '00000';
	LET cNumCte                     = "";
	LET dFecha				        = "";
	LET cRfc_orig	                = "";
	LET cNombre1_orig			    = "";
	LET cNombre2_orig			    = "";
	LET cApell_paterno_orig	        = "";
	LET cApell_materno_orig	        = "";
	LET cRfc_nvo				    = "";
	LET cNombre1_nvo			    = "";
	LET cNombre2_nvo			    = "";
	LET cApell_paterno_nvo	        = "";
	LET cApell_materno_nvo		    = "";
	LET cUser_insert				= "";

BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr
        IF iSqlErr <> 0 THEN
            LET cCod_ret = iSqlErr;
        END IF;
        RETURN cCod_ret, NULL, NULL, NULL, NULL, NULL, NULL, NULL;
    END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/sp_ConsultarCambiosNomCtasFechas.out";
    --TRACE ON;

	IF (p_Tipo="") OR (p_Tipo IS NULL) THEN
		RETURN '00001', NULL, NULL, NULL, NULL, NULL, NULL, NULL; --Faltan parametros
	END IF;
	IF p_Tipo=1 THEN

		IF (p_NumCte IS NULL) OR (p_NumCte = "") THEN --valida que el numero de cliente no sea nulo
	            RETURN '00001', NULL, NULL, NULL, NULL, NULL, NULL, NULL; --Faltan parametros
		ELSE
		    --Consulta las correcciones de los datos del numero de cliente ingresado como paramentro
	        SELECT numcte,fecha_insert, rfc_orig, nombre1_orig, nombre2_orig, apell_paterno_orig, apell_materno_orig, rfc_nvo,
		           nombre1_nvo, nombre2_nvo, apell_paterno_nvo, apell_materno_nvo,user_insert
		    INTO   cNumCte,dFecha,cRfc_orig, cNombre1_orig,cNombre2_orig, cApell_paterno_orig, cApell_materno_orig,cRfc_nvo,
			       cNombre1_nvo, cNombre2_nvo, cApell_paterno_nvo, cApell_materno_nvo, cUser_insert
	        FROM  bdinteg: si_cte_bitacora
		    WHERE  numcte = p_NumCte AND secuencia IN (SELECT MAX(secuencia) FROM bdinteg: si_cte_bitacora WHERE numcte = p_NumCte);

	        --Forma la cadena con los nombres y apellidos del cliente
		    LET cNomCompletoAnterior = TRIM(cNombre1_orig) || ' ' || TRIM(cNombre2_orig) || ' ' || TRIM (cApell_paterno_orig) || ' ' || TRIM(cApell_materno_orig);
		    LET cNomCompletoActual = TRIM(cNombre1_nvo) || ' ' || TRIM(cNombre2_nvo) || ' ' || TRIM (cApell_paterno_nvo) || ' ' || TRIM(cApell_materno_nvo);
		END IF;
		        --Regresa valores obtenidos
	            RETURN cCod_ret,cNumCte,dFecha,cRfc_orig, cNomCompletoAnterior,cRfc_nvo, cNomCompletoActual,cUser_insert WITH RESUME;
		END IF;

	IF p_Tipo= 2 THEN
		--Valida que las los parametros recibidos en fecha incial y fecha final, no sean nulos.
		IF (pFechaInicial IS NULL) OR (pFechaInicial = "") or (pFechaFinal IS NULL) OR (pFechaFinal="") THEN
		    RETURN '0001', NULL, NULL, NULL, NULL, NULL, NULL,NULL;
		ELSE
			FOREACH --Iicia un ciclo donde obtiene los datos de clientes  que se han corregido  durande el periodo de tiempo comprendido en el rango entre fecha unicial y fecha final
				 SELECT numcte, fecha_insert, rfc_orig, nombre1_orig, nombre2_orig, apell_paterno_orig, apell_materno_orig, rfc_nvo,
						nombre1_nvo, nombre2_nvo, apell_paterno_nvo, apell_materno_nvo,user_insert
				 INTO   cNumCte,dFecha,cRfc_orig, cNombre1_orig,cNombre2_orig, cApell_paterno_orig, cApell_materno_orig,cRfc_nvo,
						cNombre1_nvo, cNombre2_nvo, cApell_paterno_nvo, cApell_materno_nvo,cUser_insert
				 FROM   bdinteg: si_cte_bitacora
				 WHERE fecha_insert BETWEEN  pFechaInicial AND  pFechaFinal
				 ORDER BY fecha_insert, numcte, secuencia

				 --Forma la cadena con los nombres y apellidos del cliente

				 LET cNomCompletoAnterior = TRIM(cNombre1_orig) || ' ' || TRIM(cNombre2_orig) || ' ' || TRIM (cApell_paterno_orig) || ' ' || TRIM(cApell_materno_orig);
				 LET cNomCompletoActual = TRIM(cNombre1_nvo) || ' ' || TRIM(cNombre2_nvo) || ' ' || TRIM (cApell_paterno_nvo) || ' ' || TRIM(cApell_materno_nvo);
				 --regresa valores obtenidos
				 RETURN cCod_ret,cNumCte,dFecha,cRfc_orig, cNomCompletoAnterior,cRfc_nvo, cNomCompletoActual,cUser_insert WITH RESUME;
			END FOREACH;

		END IF;
	END IF;
END;
END PROCEDURE
DOCUMENT
    'DESCRIPCION: Realiza una consulta la tabla si_cte_bitacora, de los clientes a los que se les han actualizado sus datos durante un rango de fechas o la ultima corrección de los datos del cliente. ',
    'AUTOR: Cristian Valentina Aguilar',
    'FECHA: junio 2009',
    'VERSION: 20090626',
    'BD: BDINTEG',

	'CAMBIOS: Se modificaron las consultas, para que traigan tambien el user_insert, y lo regrese en los resultados',
	'MODIFICO: Cristian Valentina Aguilar',
	'FECHA: 20090818',
	'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_loginusuario_bpi (pEmpresa char(3), pUsuario char(50), pPass char(50))
   returning char(5), char (20), char(26), char(26), char(26), char(26), smallint, integer, char(19);

--Modificó: Ramon Romero
--Fecha: 05/08/09
--Solicitó: Mauricio León
--Modificación: Se le agrego un parametro para devolver la fecha de último acceso
--Modificó: Javier Calderón Zazueta
--Fecha: 18/02/09
--Solicitó: Mauricio León
--Actividad: Permite realizar el log in de los usuarios de BPI
   
-- ***************************************************************************
-- Define variables
-- ***************************************************************************
    DEFINE cod_ret char(5);
    DEFINE sql_err integer ;
    DEFINE sNumCliente char (20);
    DEFINE iIdStatus smallint ;
    DEFINE sNombre1, sNombre2, sApellPaterno, sApellMaterno char (26);
	DEFINE iIdStatusToken integer;
	DEFINE fecPrimAcceso date;
	DEFINE fecUltAcceso char(19);

-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
   LET cod_ret  = "000";
   LET sNumCliente  = '';
   LET iIdStatus = 0;
   LET sNombre1 = '';
   LET sNombre2  = '';
   LET sApellPaterno  = '';
   LET sApellMaterno  = '';
   LET iIdStatusToken = 0;
   LET fecUltAcceso = '';


  Set isolation to dirty read;

 --SET DEBUG FILE TO '/tmp/sp_loginusuario_bpi.out';
 --TRACE ON;


  BEGIN


   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret, sNumCliente, sNombre1, sNombre2, sApellPaterno, sApellMaterno, iIdStatus, iIdStatusToken, fecUltAcceso;
      END IF ;
   END EXCEPTION ;

        --Set explain file to '/tmp/bancaTiempo.out';
        IF EXISTS (SELECT numcte FROM bdinteg:si_bpiusuarios  WHERE empresa = pEmpresa AND usuario = pUsuario AND pass = pPass ) THEN

            SELECT usu.numcte, usu.id_status, si.nombre1, si.nombre2, si.apell_paterno, si.apell_materno, id_status_token, usu.fec_primer_acceso, 
			CASE WHEN usu.f_ultimo_acceso IS NULL THEN substring (current::varchar(23) from 1 for 19)
            ELSE substring (usu.f_ultimo_acceso::varchar(23)from 1 for 19)
            END f_ultimo_acceso
            INTO sNumCliente,  iIdStatus, sNombre1, sNombre2, sApellPaterno, sApellMaterno, iIdStatusToken, fecPrimAcceso, fecUltAcceso
			FROM bdinteg:si_bpiusuarios usu
            INNER JOIN bdinteg:si_cliente si ON si.numcte = usu.numcte
            AND usu.empresa = pEmpresa
            AND usu.usuario = pUsuario
            AND usu.pass = pPass
			LEFT JOIN bdinteg:si_bpitoken tk ON tk.num_cliente = usu.numcte
			AND tk.empresa = pEmpresa;

			--Modificó: Héctor Bojórquez
			--Fecha: 20/07/09
			--Solicitó: 
			--Se agregó validación del status de logueo para que se actualize la fecha del último acceso solamente cuando el proceso de logueo del usuario
			--se haya realizado correctamente, es decir, cuando el campo id_status de la tabla bdinteg:si_bpiusuarios sea igual a 30.
			
			IF iIdStatus = 30 THEN
				UPDATE bdinteg:si_bpiusuarios SET f_ultimo_acceso = CURRENT  WHERE numcte = sNumCliente;
			END IF;	
			
			IF fecPrimAcceso IS NULL THEN
				UPDATE bdinteg:si_bpiusuarios SET fec_primer_acceso = CURRENT  WHERE numcte = sNumCliente;
			END IF;
						
			--SELECT id_status_token INTO iIdStatusToken FROM si_bpitoken WHERE empresa = pEmpresa AND num_cliente = sNumCliente;

                LET cod_ret = '000';  -- Sesion iniciada

        ELSE

                LET cod_ret = '002';  -- Usuario y/o Contraseña incorrecta

        END IF ;

   RETURN cod_ret, sNumCliente, sNombre1, sNombre2, sApellPaterno, sApellMaterno, iIdStatus, iIdStatusToken, fecUltAcceso;

END

END PROCEDURE ;

CREATE PROCEDURE "informix".sp_st_participantes
(
psCveSorteo			CHAR(5),
piIdElemento		INTEGER,
piTipoParticipa		INTEGER,
piValMax			INT8,
piValMin			INT8,
pdFechaIni			DATE,
pdFechaFin			DATE
)

RETURNING CHAR(5);

--****************************************************************************************************
-- DESCRIPCION: Resgistra participantes para sorteo.
-- AUTOR : Rochin Rocha Edgar Ivan
-- FECHA : 3/11/2009
-- BD: Bdinteg
-- SISTEMA : Sorteo
--****************************************************************************************************

DEFINE viSqlErr			INTEGER;
DEFINE vsCodRet			CHAR(5);

LET viSqlErr = 0;
LET vsCodRet = "";

--ET DEBUG FILE TO "/tmp/sorteo/sp_st_Participantes.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET viSqlErr
	IF viSqlErr <> 0 THEN
		RETURN viSqlErr;
	END IF;
END EXCEPTION;

--Valida si no existe participante de sorteo.
IF NOT EXISTS(SELECT cve_sorteo, id_elemento, tipo_participa, val_max, val_min, f_ini, f_fin FROM bdinteg:si_participa 
			  WHERE cve_sorteo = psCveSorteo AND id_elemento = piIdElemento AND tipo_participa = piTipoParticipa)THEN
	--Inserta nuevo participante para sorteo correspondiente.
	INSERT INTO bdinteg:si_participa
	(
	cve_sorteo,
	id_elemento,
	tipo_participa,
	val_max,
	val_min,
	f_ini,
	f_fin
	)
	VALUES
	(
	psCveSorteo,
	piIdElemento,
	piTipoParticipa,
	piValMax,
	piValMin,
	pdFechaIni,
	pdFechaFin
	);
	--El participante ha sido registrado.
	LET vsCodRet = '00000';
--Valida si existe participante de sorteo.
ELSE
	--Actualiza participante modificado.
	UPDATE bdinteg:si_participa SET 
	cve_sorteo = psCveSorteo,
	id_elemento = piIdElemento,
	tipo_participa = piTipoParticipa,
	val_max = piValMax,
	val_min = piValMin,
	f_ini = pdFechaIni,
	f_fin = pdFechaFin 
	WHERE cve_sorteo = psCveSorteo AND id_elemento = piIdElemento AND tipo_participa = piTipoParticipa;
	--El participante ha sido modificado.
	LET vsCodRet = '00000';
END IF;

RETURN vsCodRet;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_st_registrasorteo
(
psCveSorteo			CHAR(5),
psDescripcion		CHAR(50),
pdFechaIni			DATE,
pdFechaFin			DATE,
psResponsableBC		CHAR(80),
psExtRespBC			CHAR(6),
psRespCoppel		CHAR(80),
psExtRespCoppel		CHAR(6),
piBoletoIni			INT8,
piBoletoFin			INT8,
piGeneraReporte		INTEGER,
psPeriodoReporte	CHAR(3),
psRutaReporte		CHAR(100),
psPartEmpleado		CHAR(1),
psUsrRegistro		CHAR(8)
)

RETURNING CHAR(5);

--****************************************************************************************************
-- DESCRIPCION: Resgistra sorteo nuevo o lo actualiza.
-- AUTOR : Rochin Rocha Edgar Ivan
-- FECHA : 9/10/2009
-- BD: Bdinteg
-- SISTEMA : Sorteo
--****************************************************************************************************

DEFINE viSqlErr INTEGER;
DEFINE vsCodRet CHAR(5);

LET viSqlErr = 0;
LET vsCodRet = "";

--SET DEBUG FILE TO "/tmp/sorteo/sp_st_registrasorteo.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET viSqlErr
	IF viSqlErr <> 0 THEN
		RETURN viSqlErr;
	END IF;
END EXCEPTION;

--Valida que la clave del sorteo sea diferente de blanco o nulo.
IF (psCveSorteo <> "")THEN	
	--Valida si el sorteo no existe en la tabla.
	IF NOT EXISTS(SELECT cve_sorteo FROM bdinteg:si_sorteo WHERE cve_sorteo = psCveSorteo)THEN
		--Valida si existe un sorteo con las fechas en las que se registrara uno nuevo.
		IF NOT EXISTS(SELECT cve_sorteo, f_ini, f_fin FROM bdinteg:si_sorteo WHERE pdFechaIni BETWEEN f_ini AND f_fin OR pdFechaFin BETWEEN f_ini AND f_fin)THEN
			--Guarda datos del sorteo en la tabla.
			INSERT INTO bdinteg:si_sorteo
			(
			cve_sorteo, descripcion, f_ini, f_fin, responsable, ext_respbc, resp_coppel, ext_respcp, boleto_ini, boleto_fin, genera_reporte, periodo_reporte,
			rutareporte, exento_empleado, usr_registro, f_registro, usr_modifica, f_modifica
			)
			VALUES
			(
			psCveSorteo, psDescripcion, pdFechaIni, pdFechaFin, psResponsableBC, psExtRespBC, psRespCoppel, psExtRespCoppel, piBoletoIni, piBoletoFin,
			piGeneraReporte, psPeriodoReporte, psRutaReporte, psPartEmpleado, psUsrRegistro, CURRENT, '', ''
			);
			--El sorteo ha sido registrado.
			LET vsCodRet = '00000';
		--Ya existe un sorteo con las fechas proporcionadas para este sorteo.
		ELSE
			LET vsCodRet = '00002';
		END IF;
	ELSE
		--Valida si existe un sorteo con las fechas en las que se registrara uno nuevo.
		IF NOT EXISTS(SELECT cve_sorteo, f_ini, f_fin FROM bdinteg:si_sorteo WHERE (pdFechaIni BETWEEN f_ini AND f_fin OR pdFechaFin BETWEEN f_ini AND f_fin) AND cve_sorteo <> psCveSorteo)THEN
			--Ya que la clave del sorteo existe se actualiza informacion.
			UPDATE bdinteg:si_sorteo SET
			cve_sorteo = psCveSorteo,
			descripcion = psDescripcion,
			f_ini = pdFechaIni,
			f_fin = pdFechaFin,
			responsable = psResponsableBC,
			ext_respbc = psExtRespBC,
			resp_coppel = psRespCoppel,
			ext_respcp =  psExtRespCoppel,
			boleto_ini = piBoletoIni,
			boleto_fin = piBoletoFin,
			genera_reporte = piGeneraReporte,
			periodo_reporte = psPeriodoReporte,
			rutareporte = psRutaReporte,
			exento_empleado = psPartEmpleado,
			usr_modifica = psUsrRegistro,
			f_modifica = CURRENT
			WHERE cve_sorteo = psCveSorteo;
			--El sorteo ha sido modificado.
			LET vsCodRet = '00000';
		--Ya existe un sorteo con las fechas proporcionadas para este sorteo.
		ELSE			
			LET vsCodRet = '00002';
		END IF;
	END IF;
--No se proporciono clave del sorteo para ser registrado.
ELSE
	LET vsCodRet = '00001';
END IF;

RETURN vsCodRet;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_reparte_boletos(p_cve_sorteo char(5),p_numcte char(9),p_sucursal char(4),p_area char(1),p_caja int,p_tipomov char(10),
p_foliosuc char(16),p_importe money(16,2),p_telefono char(10),p_fecha date,p_origen char(10),p_bolped int)
RETURNING VARCHAR(6),VARCHAR(80);

DEFINE  SQL_ERR          INTEGER;
DEFINE  ISAM_ERR         INTEGER;
DEFINE  ERROR_INFO       VARCHAR(80);
DEFINE  P_COD_RET        VARCHAR(6);
DEFINE  P_MENSAJE        VARCHAR(80);

DEFINE ciclo INTEGER;
DEFINE CodRet char(5);
DEFINE num1 integer;

let SQL_ERR          = 0;
let ISAM_ERR         = 0;
let ERROR_INFO       = '';
let P_COD_RET        = '';
let P_MENSAJE        = '';

let ciclo = 0;
let CodRet = '';
let num1 = 0;

BEGIN

 ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
      LET P_COD_RET    = SQL_ERR;
      LET P_MENSAJE  = ERROR_INFO;	  
      RETURN P_COD_RET, P_MENSAJE;
   END EXCEPTION;
   
   --Set debug file to "/home/informix/man/manuel.out";
   --Trace on;
   
   let ciclo = 1;

   LET P_COD_RET = '00000';
   LET P_MENSAJE = 'PROCESO EXITOSO';

   SET LOCK MODE TO WAIT 3;
   for ciclo = 1 to p_bolped
	insert into bdinteg:si_boleto values(p_cve_sorteo,sec_boleto.nextval ,CURRENT,p_numcte,'2',p_sucursal,p_area,p_caja,p_tipomov,
										 p_foliosuc,p_importe,p_telefono,'','',p_fecha,p_origen,ciclo);
   end for;

 RETURN P_COD_RET, P_MENSAJE;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_sorteobancoppelpba(p_canal int,p_tpoper int,p_producto int, p_numcte char(9),p_sucursal char(4),p_foliosuc char(16),p_importe money(16,2),p_fecha date)
RETURNING CHAR(6) as cod_Ret,CHAR(80) as mensaje,INTEGER as rango_ini,INTEGER as rango_fin;

DEFINE  SQL_ERR          INTEGER;
DEFINE  ISAM_ERR         INTEGER;
DEFINE  ERROR_INFO       VARCHAR(80);
DEFINE  P_COD_RET        VARCHAR(6);
DEFINE  P_MENSAJE        VARCHAR(80);
DEFINE  v_RangoIni       INTEGER;
DEFINE  v_RangoFin       INTEGER;
DEFINE  v_cvesorteo      VARCHAR(6);
DEFINE  v_part1          INTEGER;
DEFINE  v_part2          INTEGER;
DEFINE  v_part3          INTEGER;
DEFINE  v_part4          INTEGER;
DEFINE  v_numbol         INTEGER;
DEFINE  v_persona        INTEGER;


BEGIN

 ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
      LET P_COD_RET    = SQL_ERR;
      LET P_MENSAJE  = ERROR_INFO;
      RETURN P_COD_RET, P_MENSAJE,v_RangoIni,v_RangoFin;
   END EXCEPTION;

   --Set debug file to "/home/informix/man/manuel.out";
   --Trace on;

   LET P_COD_RET = '00000';
   LET P_MENSAJE = 'PROCESO EXITOSO';
   LET v_RangoIni = 0;
   LET v_RangoFin = 0;
   LET v_part1 = 0;
   LET v_part2 = 0;
   LET v_part3 = 0;
   LET v_part4 = 0;
   LET v_persona = 0;
   LET v_cvesorteo = '';


   LET SQL_ERR          = 0;
   LET ISAM_ERR         = 0;
   LET ERROR_INFO       = '';
   LET v_numbol         = 0;



SET LOCK MODE TO WAIT 3;
SET ISOLATION TO DIRTY READ;

	FOREACH
			SELECT cve_sorteo INTO v_cvesorteo  FROM bdinteg:si_sorteo WHERE  p_fecha  BETWEEN f_ini AND  f_fin
			IF p_tpoper = '12' THEN
				LET v_persona = 1;
				LET p_producto = 9999;
            ELSE
--                SET LOCK MODE TO WAIT 3;
--                SET ISOLATION TO DIRTY READ;
				SELECT tpo_persona INTO v_persona  FROM bdinteg:si_cliente WHERE  numcte = p_numcte  AND empresa = '001';
			END IF;

--            SET LOCK MODE TO WAIT 3;
--            SET ISOLATION TO DIRTY READ;
			SELECT
			sum(case when tipo_participa = '1' and id_elemento = p_producto then 1 else 0 end) prod,
			sum(case when tipo_participa = '2' and id_elemento = p_tpoper then 1 else 0 end) trans,
			sum(case when tipo_participa = '3' and id_elemento = p_canal then 1 else 0 end) canal,
			sum(case when tipo_participa = '4' and id_elemento = v_persona then 1 else 0 end) tpo_per,
			sum(case when tipo_participa = '2' and id_elemento = p_tpoper  then (p_importe / val_min)::int  else 0 end) numbol
			INTO v_part1,v_part2,v_part3,v_part4,v_numbol
			FROM bdinteg:si_participa
			WHERE cve_sorteo = v_cvesorteo;

			IF v_part1 = 1 AND v_part2 = 1 AND v_part3 = 1 AND v_part4 = 1 AND v_numbol > 0 THEN
				--PIDE BOLETOS
				EXECUTE PROCEDURE bdinteg:sp_reparte_boletos(v_cvesorteo,p_numcte,p_sucursal,'B','1',p_tpoper,
			    p_foliosuc,p_importe,'',p_fecha,'0200000',v_numbol) INTO P_COD_RET,P_MENSAJE;

--                SET LOCK MODE TO WAIT 3;
--                SET ISOLATION TO DIRTY READ;
				--CONSULTA BOLETOS ENTREGADOS
				SELECT sum(case when secuencia = '1' then  boleto end )rango_ini,
				       sum(case when secuencia = v_numbol then boleto end )rango_fin
				INTO v_RangoIni,v_RangoFin
				FROM bdinteg:si_boleto
				WHERE foliosuc = p_foliosuc
				AND cve_sorteo = v_cvesorteo and numcte = p_numcte and importe = p_importe
				and fecha = p_fecha;
			ELSE
			   LET v_RangoIni = 0;
			   LET v_RangoFin = 0;
			   LET P_MENSAJE = 'NO CUMPLE CON PARAMETROS';
			END IF;

			RETURN P_COD_RET, P_MENSAJE,v_RangoIni,v_RangoFin;

	END FOREACH;

	IF v_cvesorteo = '' or v_cvesorteo is NULL THEN
		LET P_COD_RET = '00000';
		LET P_MENSAJE = 'NO EXISTE SORTEOS ACTIVOS EN ESTA FECHA';
     RETURN P_COD_RET, P_MENSAJE,v_RangoIni,v_RangoFin;
	END IF
END;
END PROCEDURE;

