		SELECT {+  INDEX(bdinvers:sv_benefic ix118_5) } LIMIT 1 cuenta INTO v_cuenta FROM bdinvers:sv_benefic WHERE parentesco IN('P', 'M', 'J', 'H', 'A', 'E', 'T', 'B', 'O', 'U', 'C' , 'I', 'R', 'S', 'N', 'K');
		
		IF v_cuenta IS NULL THEN
		
			FOREACH
				SELECT {+  INDEX(bdinvers:sv_benefic ix118_5) } TRIM(numcte), TRIM(cuenta), TRIM(parentesco), numero INTO v_numcte, v_cuenta, v_parentesco, v_secuencia FROM bdinvers:sv_benefic WHERE parentesco <> ""
				
				IF v_parentesco = '01' THEN
