				IF v_parentesco = '12' THEN
					UPDATE {+  INDEX(bdinvers:sv_benefic inx_benefipagares) } bdinvers:sv_benefic SET parentesco = 'R' WHERE numcte = v_numcte AND cuenta = v_cuenta AND numero = v_secuencia AND parentesco = '12';
