				END IF;
				
				IF v_parentesco = '15' THEN
					UPDATE {+  INDEX(bdinvers:sv_benefic inx_benefipagares) } bdinvers:sv_benefic SET parentesco = 'K' WHERE numcte = v_numcte AND cuenta = v_cuenta AND numero = v_secuencia AND parentesco = '15';
				END IF;
			
			END FOREACH;
			
