	LET v_mensaje = "Migración de parentesco realizada con éxito";
	
		--SET DEBUG FILE TO '/tmp/sp_migracionRefPersonalesCred.out';
        --TRACE ON;
	
	BEGIN
		ON EXCEPTION SET vsqlerr
			IF vsqlerr <> 0 THEN
				let v_codigo_retorno = vsqlerr;
