		END EXCEPTION;
		
		SELECT {+  INDEX(bdisolic:ss_refpersonales inx_refcredito) } LIMIT 1 num_solicitud INTO v_cuenta FROM bdisolic:ss_refpersonales WHERE parentesco IN('P', 'M', 'J', 'H', 'A', 'E', 'T', 'B', 'O', 'U', 'C' , 'I', 'R', 'S', 'N', 'K');
		
