				END IF;
			
				IF v_parentesco = '06' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'T' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '06';
				END IF;
			
				IF v_parentesco = '07' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'B' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '07';
				END IF;
			
				IF v_parentesco = '08' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'O' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '08';
				END IF;
			
				IF v_parentesco = '09' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'U' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '09';
				END IF;
			
				IF v_parentesco = '10' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'C' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '10';
				END IF;
			
				IF v_parentesco = '11' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'I' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '11';
				END IF;
			
				IF v_parentesco = '12' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'R' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '12';
				END IF;
			
				IF v_parentesco = '13' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'S' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '13';
				END IF;	
			
				IF v_parentesco = '14' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'N' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '14';
				END IF;
			
				IF v_parentesco = '15' THEN
					UPDATE {+  INDEX(bdisolic:ss_refpersonales inx_refcreditos) } bdisolic:ss_refpersonales SET parentesco = 'K' WHERE numcte = v_numcte AND num_solicitud = v_cuenta AND parentesco = '15';
				END IF;
			
			END FOREACH;
			
		ELSE
			LET v_mensaje = "La migración de parentesco solo se realiza una vez";
		END IF;
		
		RETURN v_codigo_retorno, v_mensaje;
		
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_migraciontipocasactes()
	RETURNING CHAR(6) AS Codigo_retorno, CHAR(100) as Mensaje;
	
	DEFINE v_numcte 			CHAR(20);
	DEFINE v_tipocasa        	CHAR(3);
	DEFINE v_codigo_retorno		CHAR(3);
	DEFINE vsqlerr				INTEGER;
	DEFINE v_mensaje			CHAR(100);
	
	--*********************************************************--
	-- Creado por: Frank Gaxiola Gaxiola		
	--Fecha: 29/Enero/2009
	--Objetivo: Migración de tipo de casa de los clientes
	--Modificado: Frank Gaxiola Gaxiola		
	--Fecha: 20/Febrero/2009
	--Modificación: Se agrega validación para que solo se ejecute una vez el procedimiento
	--*********************************************************--
	
	LET vsqlerr = 0;
	LET v_codigo_retorno = "000";
	LET v_mensaje = "Migración de tipo de casa realizada con éxito";
	
		--SET DEBUG FILE TO '/tmp/sp_migracionTipoCasaCtes.out';
		--TRACE ON;
	
	BEGIN
		ON EXCEPTION SET vsqlerr
			IF vsqlerr <> 0 THEN
				let v_codigo_retorno = vsqlerr;
				RETURN v_codigo_retorno, v_mensaje;
			END IF;
		END EXCEPTION;
	
	SELECT {+  INDEX(bdinteg:si_ctepf inx_habitaen) } LIMIT 1 numcte INTO v_numcte FROM bdinteg:si_ctepf WHERE habita_en IN('P', 'R', 'F', 'H', 'G');
	
		IF v_numcte IS NULL THEN
		
			FOREACH
				SELECT {+  INDEX(bdinteg:si_ctepf inx_habitaen) } TRIM(numcte), TRIM(habita_en) INTO v_numcte, v_tipocasa FROM bdinteg:si_ctepf WHERE habita_en <> ""

				IF v_tipocasa = '01' THEN
					UPDATE bdinteg:si_ctepf SET habita_en = 'P' WHERE numcte = v_numcte;
				END IF;
				
				IF v_tipocasa = '02' THEN
					UPDATE bdinteg:si_ctepf SET habita_en = 'R' WHERE numcte = v_numcte;
				END IF;
				
				IF v_tipocasa = '03' THEN
					UPDATE bdinteg:si_ctepf SET habita_en = 'F' WHERE numcte = v_numcte;
				END IF;
				
				IF v_tipocasa = '04' THEN
					UPDATE bdinteg:si_ctepf SET habita_en = 'H' WHERE numcte = v_numcte;
				END IF;
				
				IF v_tipocasa = '05' THEN
					UPDATE bdinteg:si_ctepf SET habita_en = 'G' WHERE numcte = v_numcte;
				END IF;

			END FOREACH;
			
		ELSE
			LET v_mensaje = "La migración de tipo de casa solo se realiza una vez";
		END IF;
		
		RETURN v_codigo_retorno, v_mensaje;
		
	END;
END PROCEDURE;

create procedure "informix".sp_genarchivoboletossort2009 (psNumEmpleado CHAR(8),pdcve_sorteo char (5), pdFechaBusqueda DATE,pdrepositorio CHAR(100))

RETURNING CHAR(5) AS CodRetorno;

	-- Realizo   :Alejandro Osuna
	--Solicito : Hector Casanova
	-- Proyecto :  Sorteo
	-- Actividad : Manda llamar los sp secundarios
	-- Fecha     :25 de  Novimebre  de 2009
	DEFINE visqlerr INTEGER;
	DEFINE vsCodRetorno CHAR (5);
	DEFINE vscodret CHAR(5);
	DEFINE vsCve_Sorteo CHAR (5);
	DEFINE vsMensajeRetorno CHAR (100);
	
	LET vsCodRetorno = '';
	LET vscodret = '';
	LET vsCve_Sorteo = '';
	LET vsMensajeRetorno = '';


	--SET DEBUG FILE TO "/tmp/sp_genarchivoboletossort2009.out";
	--TRACE ON;


	BEGIN
		ON EXCEPTION SET visqlerr --Control de errores.
			LET vsCodRetorno =  visqlerr ;
			RETURN vsCodRetorno;
		END EXCEPTION;
		
		IF (psNumEmpleado = '') or (psNumEmpleado is null) THEN
			LET vsCodRetorno =  '10001' ;
			RETURN vsCodRetorno;
		END IF;		
		IF (pdcve_sorteo = '') or (pdcve_sorteo is null) THEN
			LET vsCodRetorno =  '10002' ;
			RETURN vsCodRetorno;
		END IF;
		IF (pdFechaBusqueda is null) THEN
			LET vsCodRetorno =  '10003' ;
			RETURN vsCodRetorno;
		END IF;
		IF (pdrepositorio = '') or (pdrepositorio is null) THEN
			LET vsCodRetorno =  '10004' ;
			RETURN vsCodRetorno;
		END IF;
		
		EXECUTE PROCEDURE bdinteg:sp_st_genarchbolparticipantes (psNumEmpleado,pdFechaBusqueda ) INTO vscodret, vsCve_Sorteo,vsMensajeRetorno;
		
		IF vscodret <> '00000' THEN
			LET vsCodRetorno =  vscodret ;
			RETURN vsCodRetorno;
		ELSE
			EXECUTE PROCEDURE bdinteg:sp_genarchivorepor(psNumEmpleado,pdcve_sorteo,pdFechaBusqueda,pdrepositorio ) INTO vscodret, vsCve_Sorteo,vsMensajeRetorno;
			IF vscodret <> '00000' THEN
				LET vsCodRetorno =  vscodret ;
				RETURN vsCodRetorno;
			END IF;			
		END IF;
		LET vsCodRetorno =  '00000' ;
		RETURN vsCodRetorno;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generarclientescoppel(p_dFechaInicial DATE, p_dFechaFinal DATE)
	RETURNING 		CHAR(6);
					
	DEFINE v_sValorRetorno					CHAR(6);
	DEFINE v_iSqlError						INTEGER;
	DEFINE v_sEmpresa						CHAR(3);
	DEFINE v_sNumClienteBancoppel			CHAR(20);
	DEFINE v_sNumClienteCoppel				CHAR(20);
	DEFINE v_sTipo							CHAR(2);
	DEFINE v_sStatus						CHAR(1);
	DEFINE v_dFechaInsert					DATE;
	DEFINE v_dFechaCambio					DATE;
	DEFINE v_sNumClienteCoppelConfirmado	CHAR(20);
	
	--------------------------------------------------------------------------
	-- Creado por Erick Zamora 19/02/2008
	--SET DEBUG FILE TO "/tmp/sp_generarclientescoppel.out";
	--TRACE ON;
	--------------------------------------------------------------------------
	
	LET v_sValorRetorno = '000';
	LET v_sEmpresa = '001';
	LET v_sTipo = '01';
	LET v_sStatus = 'A';
	LET v_dFechaInsert = CURRENT::DATE;
	LET v_dFechaCambio = v_dFechaInsert;
	LET v_sNumClienteCoppelConfirmado = '';
	
	BEGIN
	
		ON EXCEPTION SET v_iSqlError
			IF v_iSqlError <> 0 THEN
				RETURN v_iSqlError;
			END IF;
		END EXCEPTION;
			
			IF EXISTS(SELECT * FROM sysmaster:systabnames 
                                  WHERE partnum > 0 
                                  and dbsname = 'bdinteg' 
                                  AND tabname = 'tmp_si_clientecomparacionbanco') THEN
				DROP TABLE tmp_si_clientecomparacionbanco;
			END IF;
			
			SELECT numcte, referencia
			FROM bdinteg:si_clientecomparacionbanco
			WHERE fechamov BETWEEN p_dFechaInicial AND p_dFechaFinal
			INTO TEMP tmp_si_clientecomparacionbanco
			WITH NO LOG;
		
		FOREACH
			SELECT numcte, referencia
			INTO v_sNumClienteBancoppel, v_sNumClienteCoppel
			FROM tmp_si_clientecomparacionbanco
			/*
			SELECT numcte, referencia
			INTO v_sNumClienteBancoppel, v_sNumClienteCoppel
			FROM si_clientecomparacionbanco
			WHERE fechamov BETWEEN p_dFechaInicial AND p_dFechaFinal
			*/
			
			SELECT {+INDEX (si_clienteconfirmado idx_clienteconfirmado2)} TRIM(numctecoppel) 
			INTO v_sNumClienteCoppelConfirmado
			FROM bdinteg:si_clienteconfirmado WHERE empresa = v_sEmpresa AND numctebancoppel = v_sNumClienteBancoppel AND numctecoppel IS NOT NULL;
			
			--SI NO EXISTE
			IF v_sNumClienteCoppelConfirmado IS NULL THEN
			
				--INSERTAR
				INSERT INTO bdinteg:si_clienteconfirmado (empresa, numctebancoppel, numctebancoppelformat, numctecoppel, tipo, status, fechainsert, fechacambio)
				VALUES (v_sEmpresa, v_sNumClienteBancoppel, LPAD(TRIM(v_sNumClienteBancoppel), 9, '0'), v_sNumClienteCoppel, v_sTipo, v_sStatus, v_dFechaInsert, v_dFechaCambio);
				
			--SI EXISTE PERO LA REFERENCIA ES DISTINTA
			ELIF v_sNumClienteCoppel <> v_sNumClienteCoppelConfirmado THEN
			
				--ACTUALIZAR
				UPDATE {+INDEX (si_clienteconfirmado idx_clienteconfirmado2)} bdinteg:si_clienteconfirmado SET status = 'D', fechaCambio =  v_dFechaCambio
				WHERE empresa = v_sEmpresa AND numctebancoppel = v_sNumClienteBancoppel
				AND numctecoppel = v_sNumClienteCoppelConfirmado;
				
			END IF;
			
		END FOREACH;
		
		DROP TABLE tmp_si_clientecomparacionbanco;
		RETURN v_sValorRetorno;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerformapagoabonocoppel(p_cFolioSuc CHAR(16))
RETURNING CHAR(6), INTEGER;

	DEFINE iSqlErr 	INTEGER;
	DEFINE formapago INTEGER;
	DEFINE  cod_ret CHAR(6);
	
	ON EXCEPTION SET iSqlErr
		LET cod_ret = iSqlErr;
		LET formapago = 0;
		RETURN cod_ret, formapago;
	END EXCEPTION;
	
	LET cod_ret = '000000';
	LET formapago = 0;
	
	BEGIN
		SELECT NVL(SUM(CAST(forma_pago AS INTEGER)),0)
		INTO formapago
		FROM bdisac:sac_movimientos
		WHERE folio_suc = p_cFolioSuc;		
	END
	RETURN cod_ret, formapago;
END PROCEDURE
DOCUMENT
'AUTOR : José Angel López Adams',
'DESCRIPCION: Se encarga de obtener el tipo de pago de un abono coppel en la reimpresion de tickets de boletos',
'EJECUTADO O LLAMADO POR: CJ003002.EXE',
'FECHA : NOVIEMBRE/2009',
'VERSION: 200911',
'BD    : bdisac';

CREATE PROCEDURE "informix".sp_cambiarpass_bpi(pEmpresa char(3), pNumCte char(20), pPass char(50))
   returning char(5);

   --Creador: Javier Humberto Calderón Zazueta
   --Actividad: Actualiza el password del usuario de BPI
   --Solicito Mauricio León
   --Fecha 09-12-09


--
-- Define variables
--
    DEFINE cod_ret char(5);
    DEFINE sql_err integer ;

--
-- Inicializa variables
--
   LET cod_ret  = 000;

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF ;
   END EXCEPTION ;


   IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN
		IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte AND pass = pPass) THEN
			 LET cod_ret = '001';  -- Ya existe el pass
		ELSE
			IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte AND pass1 = pPass) THEN
				 LET cod_ret = '001';  -- Ya existe el pass
			ELSE
				IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte AND pass2 = pPass) THEN
					 LET cod_ret = '001';  -- Ya existe el pass
				ELSE
					IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte AND pass3 = pPass) THEN
						 LET cod_ret = '001';  -- Ya existe el pass
					ELSE
						UPDATE bdinteg:si_bpiusuarios SET pass3 = TRIM(pass2), f_pass3 = current WHERE empresa = pEmpresa AND numcte = pNumCte;
						UPDATE bdinteg:si_bpiusuarios SET pass2 = TRIM(pass1), f_pass2 = current WHERE empresa = pEmpresa AND numcte = pNumCte;
						UPDATE bdinteg:si_bpiusuarios SET pass1 = TRIM(pass), f_pass1 = current WHERE empresa = pEmpresa AND numcte = pNumCte;
						UPDATE bdinteg:si_bpiusuarios SET pass = TRIM(pPass), f_pass = current WHERE empresa = pEmpresa AND numcte = pNumCte;

						LET cod_ret = '000';  -- Pass modificado
					END IF;
				END IF;
			END IF;
		END IF;

   ELSE

        LET cod_ret = '002';  -- No existe el Cliente

   END IF ;

   RETURN cod_ret;

END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarnumtarjeta_bpi(pEmpresa char(3), pNumCte char(9), pNumTarjeta char(16))
   returning char(5);

--------------------------------------------------------------------------------------------
-- Realizó: Javier Calderón
-- Actividad: Valida el numero de cliente o tarjeta de debito o credito
-- Solicitó: Mauricio León
-- Fecha de Solicitud: 10/12/2009
---------------------------------------------------------------------------------------------

-- ***************************************************************************
-- Define variables
-- ***************************************************************************
   DEFINE cod_ret char(5);
   DEFINE sql_err integer;

-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
   LET cod_ret = "000";

--set debug file to "/tmp/sp_validarnumcteotarjeta_bpi.out";
--trace on;

BEGIN
   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF;
   END exception;

   SET ISOLATION DIRTY READ ;
   SET LOCK mode TO wait 3;   
	IF EXISTS(SELECT mc.num_credito
			  FROM bdicred:sd_maecred mc
			  JOIN bdicred:sd_tarjeta tr on (tr.empresa = pEmpresa and mc.num_credito = tr.num_credito and tipo_tarjeta = 'T' and secuencia = (select max(secuencia) from bdicred:sd_tarjeta where empresa = pEmpresa and mc.num_credito = num_credito and tipo_tarjeta = 'T'))
			  WHERE mc.numcte = pNumCte AND tr.num_tarjeta = pNumTarjeta) THEN				
		RETURN cod_ret;
	END IF;
			
	IF EXISTS(SELECT mc.cuenta
			  FROM bdicheq:sc_maechq mc
			  JOIN bdicheq:sc_tarjeta tr on (tr.empresa = pEmpresa and mc.cuenta = tr.cuenta and tipo_tarjeta = 'T' and secuencia = (select max(secuencia) from bdicheq:sc_tarjeta where empresa = pEmpresa and mc.cuenta = cuenta and tipo_tarjeta = 'T'))
			  WHERE mc.num_cte = pNumCte AND tr.num_tarjeta = pNumTarjeta) THEN
		RETURN cod_ret;
	END IF;
			
	LET cod_ret = '001'; --Numero de tarjeta invalido
	RETURN cod_ret;


END
END PROCEDURE ;

CREATE PROCEDURE "informix".sp_validarpassword_bpi(pEmpresa char(3), pUsuario char(50), pPass char(50))
   returning char(5);

--Creador: Javier Calderón Zazueta
--Fecha: 08/12/09
--Solicitó: Mauricio León
--Actividad: Permite validar si la contraseña del usuario es correcta

-- ***************************************************************************
-- Define variables
-- ***************************************************************************
    DEFINE cod_ret char(5);
    DEFINE sql_err integer ;

-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
   LET cod_ret  = "000";


  Set isolation to dirty read;

 --SET DEBUG FILE TO '/tmp/sp_loginusuario_bpi.out';
 --TRACE ON;


  BEGIN


   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF ;
   END EXCEPTION ;

        --Set explain file to '/tmp/bancaTiempo.out';
        IF EXISTS (SELECT numcte FROM bdinteg:si_bpiusuarios  WHERE empresa = pEmpresa AND usuario = pUsuario AND pass = pPass ) THEN

                LET cod_ret = '000';  -- Sesion iniciada

        ELSE

                LET cod_ret = '001';  -- Usuario y/o Contraseña incorrecta

        END IF ;

   RETURN cod_ret;

END

END PROCEDURE ;

CREATE PROCEDURE "informix".sp_reimprimeboleto(pfoliosuc CHAR (20))

RETURNING
 	CHAR(6) AS cCodret,
 	CHAR (4) AS cProducto,
	CHAR (4) AS cNumTran,
	MONEY(14,2) AS cMonto,
	CHAR (20) AS cNumCte,
	CHAR(50) AS cDescripcion,
	INTEGER  AS iNumBolMin,
	INTEGER AS iNumBolMax,
	INTEGER AS iNumerodeBoletos,
	CHAR(4) AS cSucursal;

--definicion de variables
	DEFINE sql_err 		INTEGER;
	DEFINE cCodret 		CHAR(6);
	DEFINE cProducto 	CHAR (4);
	DEFINE cNumTran		CHAR (4);
	DEFINE cMonto		MONEY(14,2);
	DEFINE cNumCte		CHAR (20);
	DEFINE cDescripcion CHAR(50);
	DEFINE iNumerodeBoletos SMALLINT;
	DEFINE cCuenta 		CHAR(20);
	DEFINE iNumBolMin   INTEGER;
	DEFINE iNumBolMax	INTEGER;
	DEFINE iTipoMovto	INTEGER;
	DEFINE cSucursal 	CHAR(4);
	DEFINE iMovtosCredito	INTEGER;
	DEFINE cCodFun		CHAR(3);
	DEFINE cCodRef		CHAR(4);
	DEFINE dFecha		DATE;


--Asignacion de variables
    LET  sql_err 	= 0;
	LET  cCodret	= '000000';
	LET  cProducto 	= '';
	LET  cNumTran	= '';
	LET  cCodFun = '';
	LET  cCodRef = '';
	LET  cNumCte	= '';
	LET  cDescripcion = '';
	LET  cSucursal  = '';
	LET  cMonto		= 0.00;
	LET  iNumerodeBoletos = 0;
	LET  cCuenta 	= '';
	LET  iNumBolMin = 0;
	LET  iNumBolMax = 0;
	LET  iTipoMovto = 0;
	LET  iMovtosCredito = 0;
	LET  dFecha = '01-01-1900';


	BEGIN
		--Manejo de excepciones (errores)
		ON EXCEPTION SET sql_err
			IF sql_err <> 0 THEN
				let cCodret = sql_err;
				RETURN cCodret,'','',0,00,'',0, 0, 0,'';
			END IF;
		END EXCEPTION;

		--SET DEBUG FILE TO "/tmp/sp_reimprimeboleto.out";
		--TRACE ON;
		SELECT fecha_hoy
		INTO dFecha
		FROM bdinteg:si_fechas;

		SET ISOLATION TO DIRTY READ;

		IF EXISTS (	SELECT transacc FROM bdicheq:sc_movdia WHERE empresa = '001'
					AND folio_suc = pfoliosuc  AND cancelad <> 'S' AND fech_val = dFecha) THEN
			LET iTipoMovto = 1; --DEBITO
		ELIF EXISTS (	SELECT transacc_suc FROM bdicred:sd_movdia WHERE folio_suc = pfoliosuc
						AND reversado <> 'S' AND fecha_mov = dFecha) THEN
			LET iTipoMovto = 2; --CREDITO
		END IF;

		IF iTipoMovto > 0 THEN

            SELECT {+INDEX(si_boleto inx3_si_boleto)}
                   NVL(COUNT(*),0) AS Numero, NVL(min(boleto),0), NVL(max(boleto),0)
            INTO iNumerodeBoletos, iNumBolMin, iNumBolMax
			FROM bdinteg:si_boleto
            WHERE cve_sorteo = '00001'
            AND fecha = dFecha
            AND foliosuc = pfoliosuc;

			IF iTipoMovto = 1 THEN
				IF iNumerodeBoletos = 0  THEN
					Let cCodret = '000002'; --No tiene boletos
				ELSE
					Let cCodret = '000001'; -- Tiene Boletos
				END IF;
				--Obtine los datos necesarios para imprimir los boletos
					SET ISOLATION TO DIRTY READ;

					SELECT a.producto, a.transacc_suc,a.monto_tot, b.num_cte ,a.sucursal
					INTO cProducto, cNumTran, cMonto, cNumCte, cSucursal
					FROM bdicheq:sc_movdia as a, bdicheq:sc_maechq  as b
					WHERe a.empresa = '001'
					AND a.folio_suc = pfoliosuc
					AND a.cancelad <> 'S'
					AND a.cuenta = b.cuenta	;

			ELIF iTipoMovto = 2 THEN
				IF iNumerodeBoletos = 0  THEN
					Let cCodret = '000002'; --No tiene boletos
				ELSE
					Let cCodret = '000001'; -- Tiene Boletos
				END IF;
				--Trae los datos necesarios para generar los boletos e imprimirlos
					SET ISOLATION TO DIRTY READ;

					SELECT COUNT(*)
					INTO iMovtosCredito
					FROM bdicred:sd_movdia
					WHERE folio_suc = pfoliosuc
					AND sucursal IS NOT NULL;
					IF iMovtosCredito > 1 THEN
						SELECT a.num_producto, a.transacc_suc,a.monto,b.numcte,a.sucursal
						INTO cProducto, cNumTran, cMonto, cNumCte,cSucursal
						FROM bdicred:sd_movdia as a, bdicred:sd_maecred  as b
						WHERE a.folio_suc = pfoliosuc
						AND a.reversado <> 'S'
						AND a.num_credito = b.num_credito
                        AND a.codigo_fun IN ('033','336')
                        AND a.codigo_ref = '1';
					ELIF iMovtosCredito = 1 THEN
						SELECT a.num_producto, a.transacc_suc,a.monto,b.numcte,a.sucursal, a.codigo_fun, codigo_ref
						INTO cProducto, cNumTran, cMonto, cNumCte,cSucursal, cCodFun, cCodRef
						FROM bdicred:sd_movdia as a, bdicred:sd_maecred  as b
						WHERE a.folio_suc = pfoliosuc
						AND a.reversado <> 'S'
						AND a.num_credito = b.num_credito;

						IF cCodFun = '336' AND cCodRef = '20' THEN
							LET cNumTran = '608';
						END IF;
					END IF;
			END IF;
		ELSE
			LET cCodret = '000100';
		END IF;
		RETURN cCodret,cProducto,cNumTran,cMonto,cNumCte,cDescripcion,iNumBolMin, iNumBolMax, iNumerodeBoletos,cSucursal WITH RESUME;
	END;
END PROCEDURE
DOCUMENT
'AUTOR      : Cristian Valentina Aguilar',
