CREATE PROCEDURE "informix".sp_consemp( pEmpresa char (3),pNumEmp char(8))
RETURNING char (5), char (5), char (45);

--Define variables
define sql_err integer;
define cod_ret char (5);
define cod_ret2 char (5);
define pNombre char(45);


--Inicializa variables
LET sql_err = 0;
LET cod_ret = '00000';
LET cod_ret2 = '00000';
LET pNombre = '';


BEGIN

 ON EXCEPTION SET sql_err
          LET cod_ret = sql_err;
      RETURN  cod_ret,cod_ret2,pNombre;
   END EXCEPTION;

   EXECUTE PROCEDURE sp_consulta_empleado_iccat(pEmpresa,pNumEmp)
	INTO cod_ret2, pNombre;

	RETURN cod_ret,cod_ret2,pNombre;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obt_coleccion_bancos()
RETURNING char(5), char(3), char(40);

	-- Realizo   : Javier Humberto Calderon Zazueta
	-- Actividad : Obetener coleccion de bancos
	-- Solicitó  : Mauricio Leon Ibarra
	-- Fecha     : 04/12/2008

	--Set debug file to '/tmp/ObtieneBancos.out';
	--trace on;


       	DEFINE vcodret   char(5);
       	DEFINE cveBanco  char(3);
       	DEFINE descBanco char(40);
	DEFINE sql_err   integer;

	ON EXCEPTION SET sql_err
       		IF sql_err <> 0 THEN
        		LET vcodret = sql_err;
			RETURN vcodret, cveBanco, descBanco;
	       	END IF;
	END EXCEPTION;

	LET vcodret = '000';
	LET cveBanco = '';
	LET descBanco = '';

set isolation to dirty read;

	BEGIN
		FOREACH
			SELECT banco, descripcion
			INTO cveBanco, descBanco
			FROM bdinteg:si_bancos
			ORDER BY descripcion

			RETURN vcodret, cveBanco, descBanco WITH RESUME;
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_insertactesitesp(pEmpresa char(3), pSucursal char(4), pOrigen smallint, pNumCliente char(20), pSituacion char(1), pCausa smallint, pusuarioalta char(8),
 pEmpleadoEfectuo char(8), pNombreEfectuo char(40))

    	RETURNING
    CHAR(6)   -- Codigo de Retorno

    --Elaboró : Diana Castellanos L.
    --Actividad : Inserta o actualiza el cambio de situacion esp
    -- en la tabla si_ctesitesp e inserta si_ctesitesphis

    DEFINE cVarDataErr      VARCHAR(64);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;

    DEFINE vCodRet                CHAR(6);
    --DEFINE pusuarioalta  CHAR(8);

BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
            LET vCodRet=iSqlErr;
            Rollback;
            RETURN vCodRet;
        END IF;
    END EXCEPTION;


--    SET DEBUG FILE TO "grabacompromisosacuerdos.out";
--    TRACE ON;

    --INICIALIZACION DE VARIABLES--
    LET vCodRet        = "000";

BEGIN WORK;

IF pEmpresa <> '' AND pSucursal <> '' AND pusuarioalta <> ''  AND pNumCliente <> ''
    AND pSituacion  <> ''  AND pEmpleadoEfectuo  <> ''  AND pNombreEfectuo <> '' AND pOrigen <> 0 THEN

       IF NOT EXISTS(select numcte from bdisitesp:se_ctessitespcte where numcte = pNumCliente) then

            insert into bdisitesp:se_ctessitespcte (empresa, numcte, situacion, causa, cvesitesporigen, sucursal, tipomovto, empleadoefectuo, 
	                                            nombreefectuo, fechamovto, usralta, fchalta, usrmodifica, fchmodifica)
            
	                values (pEmpresa, pNumCliente, pSituacion, pCausa, pOrigen, pSucursal, 'M', pEmpleadoEfectuo, pNombreEfectuo, current, pusuarioalta, TODAY, '', '');

             insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                         usralta, fchalta, usrmodifica, fchmodifica)
            values ('M', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

       ELSE

             IF pSituacion = 'C' THEN

                   Delete from bdisitesp:se_ctessitespcte  where numcte = pNumCliente;

                   insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                         usralta, fchalta, usrmodifica, fchmodifica)
            values ('E', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

            ELSE

                   Update bdisitesp:se_ctessitespcte
                    set empresa = pEmpresa, sucursal = pSucursal, cvesitesporigen = pOrigen, situacion = pSituacion, causa = pCausa, usralta = pusuarioalta,
                           empleadoefectuo = pEmpleadoEfectuo, nombreefectuo = pNombreEfectuo, fechamovto = current
                    where numcte = pNumCliente;

                   insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                               usralta, fchalta, usrmodifica, fchmodifica)
            values ('S', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

            END IF;

       END IF;
ELSE
    LET vCodRet        = "001";   --Falta algun parametro
END IF;

COMMIT WORK;

    RETURN vCodRet;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_conscteing(cEmpresa CHAR(3),
                               cNumCte CHAR(20),
                               iNumIng SMALLINT)
    RETURNING CHAR(5) AS CodRetorno, SMALLINT AS SecIngresos, CHAR(1) AS TipoIngreso, CHAR(60) AS NombreEmpresa, CHAR(3) AS Puesto, CHAR(2) AS PuestoEspecial,
              DECIMAL(4,2) AS Antiguedad, CHAR(40) AS NombreDepto, CHAR(60) AS Jefe, MONEY(14,2) AS IngresoMensual, INTEGER AS ClavePto,
	      INTEGER AS ClaveOpcPto, INTEGER AS ClaveSubOpPto, INTEGER AS SistCotiza, INTEGER AS NumEmpleados, INTEGER AS Pereosidad, INTEGER AS TipoIngExt;

DEFINE cCodRet 		CHAR(5);
DEFINE sCiclo 		SMALLINT;
DEFINE iSqlErr 		INTEGER;

DEFINE sSecIngreso 	SMALLINT;
DEFINE cTipoIngreso    CHAR(1);
DEFINE cNomEmpresa 	CHAR(60);
DEFINE cPuesto 		CHAR(3);
DEFINE cPuestoEsp 	CHAR(2);
DEFINE dcAntiguedad     DECIMAL(4,2);
DEFINE cNombreDepto     CHAR(40);
DEFINE cJefeInmedto     CHAR(60);
DEFINE mIngMensual 	MONEY(14,2);
DEFINE iCvePto		INTEGER;
DEFINE iCveOpcPto	INTEGER;
DEFINE iCveSubOpPto     INTEGER;
DEFINE iSistCotiza      INTEGER;
DEFINE iNumEmpLab       INTEGER;
DEFINE iPeriosidad      INTEGER;
DEFINE iTipoIngExt      INTEGER;

LET sCiclo = 0;
LET cCodRet = "000";
LET iSqlErr = 0;

LET sSecIngreso = 0;
LET cTipoIngreso = "";
LET cNomEmpresa = "";
LET cPuesto = "";
LET cPuestoEsp = "";
LET dcAntiguedad = 0;
LET cNombreDepto = "";
LET cJefeInmedto = "";
LET mIngMensual = 0;
LET iCvePto		= 0;
LET iCveOpcPto	= 0;
LET iCveSubOpPto = 0;
LET iSistCotiza  = 0;
LET iNumEmpLab   = 0;
LET iPeriosidad  = 0;
LET iTipoIngExt  = 0;

--SET DEBUG FILE TO '/tmp/sp_conscteing.out';
--TRACE ON;

BEGIN
    ON EXCEPTION SET iSqlErr
      IF iSqlErr <> 0 THEN
         LET cCodRet = iSqlErr;
         RETURN cCodRet, sSecIngreso, cTipoIngreso, cNomEmpresa, cPuesto, cPuestoEsp,
                dcAntiguedad, cNombreDepto, cJefeInmedto, mIngMensual, iCvePto, iCveOpcPto,
				iCveSubOpPto, iSistCotiza, iNumEmpLab, iPeriosidad, iTipoIngExt;
      END IF;
    END EXCEPTION;

    FOREACH

		SELECT sec_ingreso, tipo_ingreso, nombre_empresa, puesto, puesto_esp,
               antiguedad, nombre_depto, jefe_inmediato, ingreso_mensual, clavepuesto, claveopcionpuesto,
			   clavesubopcionpuesto, sis_cotiza, num_emp_lab, periosidad, tipo_ingreso_ext
        INTO   sSecIngreso, cTipoIngreso, cNomEmpresa, cPuesto, cPuestoEsp,
               dcAntiguedad, cNombreDepto, cJefeInmedto, mIngMensual, iCvePto, iCveOpcPto,
			   iCveSubOpPto, iSistCotiza, iNumEmpLab, iPeriosidad, iTipoIngExt
        FROM si_ingresos
        WHERE numcte = cNumCte
        ORDER BY sec_ingreso

		LET sCiclo = sCiclo+1;

		IF sCiclo <= iNumIng THEN
			CONTINUE FOREACH;
		END IF

         RETURN cCodRet, NVL(sSecIngreso, 0), NVL(cTipoIngreso, ''), NVL(cNomEmpresa, ''), NVL(cPuesto, ''), NVL(cPuestoEsp, ''),
                NVL(dcAntiguedad, 0), NVL(cNombreDepto, ''), NVL(cJefeInmedto, ''), NVL(mIngMensual, 0), NVL(iCvePto, 0), NVL(iCveOpcPto, 0),
				NVL(iCveSubOpPto, 0), NVL(iSistCotiza, 0), NVL(iNumEmpLab, 0), NVL(iPeriosidad, 0), NVL(iTipoIngExt, 0) WITH RESUME;

    END FOREACH;

END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaingresos(pEmpresa CHAR(3), pNumeroCliente CHAR(20))
                  returning CHAR(5);

---23/02/2009
--Tortolero Varela Rodolfo
--consulta si el cliente  existe en la tabla si_ingresos

-- Fecha: 09/10/2009
-- Modifico: Paul Ivan Quintero Varela
-- Observaciones: Se modifica para que el query de consulta solo verifique si el cliente ya cuenta con un 
--                registro en la tabla si_ingresos independientemente si el tipo ingreso es "T" (Trabajo) o
--                "E" (Extra) y para validar que se reciban parámetros validos.

--define variables
DEFINE iSqlErr INTEGER;
DEFINE vcodret CHAR(5);
DEFINE vNumCte CHAR(20);

--asigna variables
LET vcodret = "000";
LET vNumCte = "";

IF NVL(pEmpresa,'') = ''  OR  NVL(pNumeroCliente,'') = '' THEN
    LET vcodret = "002"; -- Se realizo la ejecucion del procedimiento de forma incorrecta.
    RETURN vcodret;
END IF;

BEGIN
    ON EXCEPTION
        SET iSqlErr
          IF iSqlErr <> 0 THEN
             LET vCodRet = iSqlErr;
             RETURN vcodret;
          END IF;
    END EXCEPTION;
		
    --SET DEBUG FILE TO "/tmp/sp_consultaingresos.out";
    --TRACE ON;

        SELECT LIMIT 1 numcte 
          INTO vNumCte
          FROM bdinteg:si_ingresos
         WHERE empresa = pEmpresa 
           AND numcte = pNumeroCliente;
       
        IF vNumCte = pNumeroCliente THEN
			LET vcodret = "001"; -- ya existe el cliente en la tabla, por lo tanto se hara un cambio de los ingresos.
		ELSE
			LET vcodret = "000"; --no existe el cliente en la tabla, por lo tanto se hara una alta de los ingresos.
        END IF;

        RETURN vcodret;
END;
END PROCEDURE;

create procedure "informix".sp_refdirecciones(pempresa char(3),
                             pfuncion char(1),
                             pnumcte char(20),
                             psecuencia integer,
                             ptipodir char(1),
                             pcalle char(40),
                             pcolonia char(60),
                             pmunicipio char(5),
                             pentre_calles char(40),
                             ppais char(3),
                             pentidad char(2),
                             plocalidad char(3),
                             pcodpostal char(5),
                             ptipotel1 char(1),
                             ptelefono1 char(13),
                             ptipotel2 char(1),
                             ptelefono2 char(13),
                             ptipotel3 char(1),
                             ptelefono3 char(13),
                             pextension char(5),
                             pestado_inegi char(2),
                             pmunicipio_inegi char(3),
                             plocalidad_inegi char(4),
                             pnociudad smallint,
                             pnoext char(10),
                             pnoint char(10),
                             pdepto char(6),
                             pnocalle integer,
                             pnocolonia integer,
                             ppuntocar char(1),
                             punihabi char(1),
                             pmanz smallint,
                             ppotros smallint,
                             pandador smallint,
                             petapa smallint,
                             plote smallint,
                             pedif smallint,
                             pentrada smallint,
                             pobserva char(80),
                             puser_insert char(8),
                             pfecha_insert date,
							 numcte_banco char(20))
 returning char(5);

define v_codret char(5);
define v_rowid integer;
define v_tipodir char(1);
define v_calle char(40);
define v_colonia char(60);
define v_delegacion char(20);
define v_entre_calles char(40);
define v_pais char(3);
define v_entidad char(2);
define v_localidad char(3);
define v_codpostal char(5);
define v_telefono1 char(20);
define v_telefono2 char(20);
define v_estado_inegi char(2);
define v_municipio_inegi char(3);
define v_localidad_inegi char(4);
define v_fax char(20);
define v_nombre char(40);
define v_longitud, v_longcte, v_secuencia smallint;
define v_numcte char(20);
define v_existe char(1);
define v_sqlerr, v_isamerr integer;

--DOCUMENTACION:
--Realizó: Martha Aguirre
--Fecha: 31/01/2009
--Funcionalidad: Inserta en la tabla si_refdirecciones las direcciones de las referencias de los clientes solicitantes de Crédito


   	--SET DEBUG FILE TO "/tmp/sp_refdirecciones.out";
    --TRACE ON;
	
	
begin
   on exception set v_sqlerr, v_isamerr
      if v_sqlerr != 0 then
         let v_codret=v_sqlerr;
         return v_codret;
      end if;
   end exception;

   let v_codret="000";

   select numcte into v_numcte from si_cliente
      where numcte = pnumcte;
   if v_numcte is null then
      let v_codret = "104";
      return v_codret;
   end if

   if pfuncion="A" then
      {
      select nombre into v_nombre
         from si_paises
         where pais = ppais;
      if v_nombre is null then
         let v_codret="121";
         return v_codret;
      end if;

      select nombre into v_nombre
         from si_estados
         where pais=ppais and estado=pentidad;

      if v_nombre is null then
         let v_codret="122";
         return v_codret;
      end if;

      select nombre into v_nombre
         from si_ciudades
         where pais=ppais and estado=pentidad and ciudad=plocalidad;
      if v_nombre is null then
         let v_codret="123";
         return v_codret;
      end if;
      }
         insert into si_refdirecciones
             (numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
	      pais,estado,ciudad,municipio,cod_postal,apart_postal,
	      tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
	      telefono3,extension ,estado_inegi,municipio_inegi,localidad_inegi,
	      numerociudad,numeroextcalle,numerointcalle,departamento,
	      numerocalle,numerocolonia,puntocardinal,unidadhabitac,
	      manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
	      user_insert,fecha_insert,numcte_banco)
           values
             (pnumcte, psecuencia, ptipodir, pcalle, pcolonia, pentre_calles,
              ppais,pentidad,plocalidad, pmunicipio, pcodpostal,"",
              ptipotel1,ptelefono1,ptipotel2,ptelefono2,ptipotel3,
              ptelefono3, pextension ,pestado_inegi,pmunicipio_inegi,plocalidad_inegi,
              pnociudad,pnoext,pnoint,pdepto,
              pnocalle,pnocolonia,ppuntocar,punihabi,
              pmanz,ppotros,pandador,petapa,plote,pedif,pentrada,pobserva,
              puser_insert,pfecha_insert,numcte_banco);

      return v_codret;
   end if;
end;
end procedure;

CREATE PROCEDURE "informix".spregresahuellactipo1( pfechaini DATE )

RETURNING INTEGER;

    define vcodret      INTEGER;
    define vexiste      CHAR(1);
    define vsqlerr      INTEGER;
    define visamerr     INTEGER;
    define vsql         char(600);
    define varchivo     char(60);

    -- SET DEBUG FILE TO "/tmp/spregresahuellactipo1.out";
    -- TRACE ON;

    BEGIN
    
    ON EXCEPTION SET vsqlerr,visamerr
        IF vsqlerr != 0 THEN
            LET vcodret=vsqlerr;
            RETURN vcodret;
        END IF;
    END EXCEPTION;

    LET vcodret = 1;
    LET vexiste = 0;
    LET vsql = '';
    LET varchivo = 'descarga.sql';

    set isolation to dirty read;

    -- // Verifica recepcion correcta de datos
    if pfechaini is null  then
        let vcodret = 120;
        return vcodret;
    end if;

    let vsql = 'echo " unload to /resplogifx/conciliachq/huellas'||lpad(month(pfechaini),2,"0")||lpad(day(pfechaini),2,"0")||'.unl'||" delimiter '|' "||'" > '||varchivo;
    system vsql;

    let vsql = 'echo "'||
    "select nvl(ch.numcte,''),nvl(ch.secuencia,0),nvl(ch.estado,''),nvl(ch.dmapa,''),"||
    "nvl(ch.imapa,''),nvl(ch.usuario,''),nvl(ch.sucursal,''),"||
    "nvl(ch.fecha_alta,mdy(1,1,1900)),nvl(ch.usuario_camb,''),"||
    "nvl(ch.fecha_camb,mdy(1,1,1900)),nvl(cp.sexo,''),nvl(trim(ct.numcte_ref),'0') "||
    "from si_cte_huella ch "||
    "left outer join si_cliente ct on (ct.numcte = ch.numcte) "||
    "left outer join si_ctepf cp on (cp.numcte = ch.numcte) "||
    "where ch.fecha_alta='" || pfechaini || '''" >> '||varchivo;
    system vsql;

    let vsql = "dbaccess bdinteg "||varchivo;
    system vsql;
    
    let vsql = '/usr/bin/chmod 664 /resplogifx/conciliachq/huellas'||lpad(month(pfechaini),2,"0")||lpad(day(pfechaini),2,"0")||'.unl';
    system vsql;
    
    let vsql = "rm descarga.sql";
    system vsql;

    return vcodret;

    END;
    
END PROCEDURE

DOCUMENT
"Proceso temporal para la replicacion de huellas de clientes",
"AUTOR : Julio Cesar Polanco  ",
"FECHA : 09/02/2010",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".ctemoralapoderados(
                                         eEmpresa      CHAR(3),
                                         eNumCte       CHAR(20),
                                         vSecuencia    INTEGER,
                                         vNumCteApode  CHAR(20),
                                         vNomApodera   CHAR(60),
                                         vUsuario     CHAR(20),
                                         vFecha        DATE)



RETURNING CHAR(5);

 DEFINE vcod_ret             CHAR(5);
 DEFINE vsqlerr              INTEGER;


 LET vcod_ret ='000';
 LET vsqlerr  = 0;


BEGIN
    ON EXCEPTION SET vsqlerr
      IF vsqlerr != 0 THEN
         LET vcod_ret=vsqlerr;
        RETURN vcod_ret;
      END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/home/informix/ash/cteapo.out";
    --TRACE ON;

    if exists(select numcteapoderado from si_apoderado where numcte = eNumCte) then
         UPDATE bdinteg:si_apoderado SET secuencia = vSecuencia,
                                         numcteapoderado = vNumCteApode,
                                         nombreapoderado = vNomApodera,
                                         user_insert     = vUsuario,
                                         fecha_insert    = vFecha
         WHERE empresa = eEmpresa AND numcte = eNumCte;
     else
	INSERT INTO bdinteg:si_apoderado (secuencia,numcteapoderado,nombreapoderado,empresa,numcte,user_insert,fecha_insert)
	VALUES     (vSecuencia,vNumCteApode,vNomApodera,eEmpresa,eNumCte,vUsuario,vFecha);
     end if;
END
  RETURN vcod_ret;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_concilia_ciudades_spmxbcppl ()
       RETURNING CHAR(5), CHAR(80);
       
DEFINE v_concepto         CHAR(3);
DEFINE vCodRet            CHAR(5);
DEFINE vMensaje           CHAR(80);
DEFINE SQL_ERR            INTEGER;
DEFINE ISAM_ERR           INTEGER;
DEFINE ERROR_INFO         VARCHAR(80);
DEFINE v_d_mnpio          CHAR(32);
DEFINE v_c_estado         INTEGER;
DEFINE v_ciudad         INTEGER;
DEFINE va_nombre          CHAR(50);
DEFINE va_ciudad          CHAR(50);
    
    --SET DEBUG FILE TO "/tmp/sp_concilia_ciudades_spmxbcppl.out";
    --TRACE ON; 
    
    LET vCodRet   = "00000";
    LET vMensaje  = "PROCESO EXITOSO";

BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET vCodRet   = SQL_ERR;
        LET vMensaje  = ERROR_INFO;
        RETURN vCodRet, vMensaje;
        END EXCEPTION;

		SET ISOLATION TO dirty READ;
        
        FOREACH        
            select a.estado,a.ciudad, nvl(trim(b.d_ciudad), trim(b.d_mnpio))
              into v_c_estado,v_d_mnpio, va_nombre
              from bdinteg:si_ciudades a, bdinteg:si_catsepomex b
             where b.c_estado = a.estado
               and trim(a.nombre) = nvl(trim(b.d_ciudad), trim(b.d_mnpio))
               and a.ciudad_Coppel>0 
             group by a.estado, a.ciudad,b.d_ciudad,b.d_mnpio
             order by a.estado
             --CODIGO DE COMPARACION, 1 = ES EXACTAMENTE IGUAL SEPOMEX, BANCOPPEL    
             --UPDATE bdinteg:si_ciudades set d_ciudad = va_nombre, nombre_sepomex =1 where estado = v_c_estado and ciudad = v_d_mnpio;                
             UPDATE bdinteg:si_ciudades set d_ciudad = va_nombre where estado = v_c_estado and ciudad = v_d_mnpio;                
                    
        END FOREACH;
        
END 

RETURN vCodRet, vMensaje;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_pay_clientes_his(pinicio DATE, pfin DATE)
RETURNING VARCHAR(10), varchar(255);


	DEFINE v_sql1        		VARCHAR(250);
	DEFINE v_sql2        		VARCHAR(250);
	DEFINE v_sql3        		VARCHAR(250);
	DEFINE v_sql4        		VARCHAR(250);
	DEFINE v_sql5        		VARCHAR(250);
	DEFINE v_sql6        		VARCHAR(250);
	DEFINE v_sql7        		VARCHAR(250);

	
	DEFINE v_comprime		    CHAR(200);
	
	DEFINE vcod_ret         	VARCHAR(10); 
	DEFINE sql_err          	INTEGER;
	DEFINE isam_err         	INTEGER;
	DEFINE error_info       	CHAR(40);
	
	DEFINE vfechaini			CHAR(8);
	DEFINE vfechafin			CHAR(8);
	
	DEFINE vfini				CHAR(10);
	DEFINE vffin				CHAR(10);
	
	
	


--Manejo del error
       ON EXCEPTION
		SET sql_err, isam_err, error_info
		
           IF sql_err <> 0 THEN
            LET vcod_ret=sql_err;
            RETURN vcod_ret, isam_err||' '||error_info;
			
           END IF;
       END EXCEPTION;   
	   

--set debug file to "/tmp/sp_pay_clientes_his.out";
--TRACE ON;		

	LET v_sql1 = ''; 
	LET v_sql2 = ''; 
	LET v_sql3 = ''; 
	LET v_sql4 = ''; 
	LET v_sql5 = '';
	LET v_sql6 = ''; 
	LET v_sql7 = ''; 
	LET v_comprime = '';

	LET vcod_ret = '000';          
	LET sql_err = 0;          
	LET isam_err = 0;        
	LET error_info = '';

	LET vfechaini = TO_CHAR(pinicio,'%Y%m%d') ;	
	LET vfechafin = TO_CHAR(pfin,'%Y%m%d');	
	
	LET vfini = TO_CHAR(pinicio,'%m-%d-%Y') ;	
	LET vffin = TO_CHAR(pfin,'%m-%d-%Y');	
	
	   
	 

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;	 



--Obtencion de info clientes 

LET v_sql1 = 'echo "SELECT  ''9911'' AS mti,' ||  
			'LPAD(TRIM(c.numcte),15,''0'') AS no_cliente,'||
			'CASE WHEN c.fecha_alta = c.fecha_insert THEN ''0'''||
				 'WHEN c.fecha_alta > c.fecha_insert THEN ''1'''||
			'END AS accion, '|| '"'||' > qrycli.sql';		
			
LET v_sql2 = 'echo "RPAD((TRIM(c.apell_paterno)||'' ''||TRIM(c.apell_materno)||'' ''||TRIM(c.nombre1)||'' ''||TRIM(c.nombre2)),40, '' '') AS 	nombre,'||
			'LPAD(c.rfc,20,0) AS rfc,'||
			'TRIM(f.sexo) AS sexo,'|| '"'||' >> qrycli.sql';
			
LET v_sql3 = 'echo "TO_CHAR(f.fecha_nac,''%Y%m%d'') AS fecha_nac,'||
			'SUBSTR(e.razon_social,1,25) AS compania,'||
			'LPAD( 0 , 15, ''0'') AS ingreso'|| '"'||' >> qrycli.sql';
			
LET v_sql4 = 'echo " FROM bdinteg:si_cliente c,'||
			'bdinteg:si_ctepf f,'||
			'bdinteg:si_empresas e'||
		' WHERE c.numcte = f.numcte'|| '"'||' >> qrycli.sql';
		
LET v_sql5 = 'echo " AND c.fecha_alta >='|| '''' ||vfini|| '''' ||
		  ' AND c.fecha_insert BETWEEN '|| ''''|| vfini || '''' ||' AND '''|| vffin ||''''||
		  ' AND f.empresa = e.empresa'||
		  ' AND e.empresa = c.empresa '||
' INTO TEMP tmp_clientes_his WITH NO LOG;'|| '"'||' >> qrycli.sql';
		


LET v_sql6 = 'echo " SELECT  LPAD(CHAR_LENGTH(mti||no_cliente||accion||nombre||rfc||sexo||fecha_nac||compania||ingreso),4,0)||mti||no_cliente||'||
			   'accion||nombre||rfc||sexo||fecha_nac||compania||ingreso AS trama'||	
	    ' FROM tmp_clientes_his'|| '"'||' >> qrycli.sql';
		
LET v_sql7 = 'echo " INTO TEMP tmp_fin_clientes_his WITH NO LOG;'||	
	     ' UNLOAD TO ''clientes_'||vfechaini||'_al_'||vfechafin||'.unl'''||
	     ' SELECT * FROM tmp_fin_clientes_his;'  || '"'||' >> qrycli.sql';

		
					
	SYSTEM v_sql1;
	SYSTEM v_sql2;
	SYSTEM v_sql3;
	SYSTEM v_sql4;
	SYSTEM v_sql5;
	SYSTEM v_sql6;
	SYSTEM v_sql7;
      LET v_sql1 = "dbaccess bdipayt qrycli.sql ";
    SYSTEM v_sql1;		
	
	
--Comprimir Archivo 		


SYSTEM v_comprime;
      LET v_comprime = "gzip -9 'clientes_'"||vfechaini||"_al_"||vfechafin||".unl";
SYSTEM v_comprime;	

		
    RETURN vcod_ret, 'PROCESO EXITOSO';
END PROCEDURE;

CREATE PROCEDURE "informix".sp_pay_direccion_his(pinicio DATE, pfin DATE)
