               SELECT  numerociudad,numerocolonia,nombrezona,poblacionzona,municipiozona,codigopostalzona,
                       supervisorzona,choferzona,jefegrupozona,gerentezona,abogadozona,centro,ciudadcobranzas,numerocobranzas,numerociudadcoppel,
                       numerocoloniacoppel,nombrezonacoppel                        
