                       vnumerocoloniacoppel,vnombrezonacoppel WITH RESUME;
                       
          END FOREACH;
          
              ELSE
              
                LET cCod_ret = '00001';
                LET cMensaje = 'El parametro es incorrecto';
                
               RETURN  cCod_ret, cMensaje, vnumerociudad,vnumerocolonia,vnombrezona,vpoblacionzona,vmunicipiozona,vcodigopostalzona,
                       vsupervisorzona,vchoferzona,vjefegrupozona,vgerentezona,vabogadozona,vcentro,vciudadcobranzas,vnumerocobranzas,vnumerociudadcoppel,
                       vnumerocoloniacoppel,vnombrezonacoppel; 
                       
              END IF;
              END;
              END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_empleado_admtoken(pEmpresa char (3), pNumEmp char(8))
	RETURNING char(5), char (45);

--Realizó: Javier Calderón
--Fecha: 07/05/2010
--Solicitó: Mauricio León
--Actividad: Retorna el nombre del empleado validando que este vigente

--Define variables
define sql_err integer;
define cod_ret char (5);
define vNombre char(45);


--Inicializa variables
LET sql_err = '';
LET cod_ret = '000';
LET vNombre = '';


BEGIN

 ON EXCEPTION SET sql_err
          LET cod_ret = sql_err;
      RETURN  cod_ret, vNombre;
   END EXCEPTION;

   IF EXISTS(SELECT ejecutivo FROM bdinteg:si_ejecut WHERE empresa = pEmpresa AND ejecutivo = pNumEmp AND current::date <= vigencia) THEN

			SELECT nombre INTO vNombre FROM bdinteg:si_ejecut WHERE empresa = pEmpresa AND ejecutivo = pNumEmp;

	ELSE
		LET cod_ret = '001'; -- El empleado No existe
	END IF;

	RETURN cod_ret, vNombre;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_dias_inhabiles()
returning char (5),DATE;

--Realizó : Javier A. Chávez Trujillo
--Actividad: Retorna las fechas inhabiles
--Fecha: 12/06/2009
--Solicitó: Mauricio León
--Modificó : Javier Calderón
--Modificación: Tomar las fechas de la tabla si_feriado_banca
--Fecha: 21/04/2010
--Solicitó: Daiana Castellanos


define sql_err integer;
define cod_ret char(5);
define fecha_inhabil DATE;

LET sql_err = 0;
LET cod_ret = '000';
LET fecha_inhabil = '01-01-1900';
BEGIN
	ON EXCEPTION SET sql_err
		LET cod_ret = sql_err;
		RETURN cod_ret,fecha_inhabil;
	END EXCEPTION;

		FOREACH
		 SELECT fecha INTO fecha_inhabil FROM bdinteg:si_feriado_banca
		 IF (fecha_inhabil <> '' OR fecha_inhabil IS NULL) THEN
			LET cod_ret = '001';
		 END IF;
		 RETURN cod_ret,fecha_inhabil WITH RESUME;
		END FOREACH;

END;
END PROCEDURE;

CREATE PROCEDURE "c92357113".sp_reporteconsolidadohuellastotal(v_pMes VARCHAR(2), v_pAnio CHAR(4))

	RETURNING INTEGER AS TotalCarga,  INTEGER AS Tipo1, INTEGER AS Tipo2, INTEGER AS Tipo3, INTEGER AS Tipo4, INTEGER AS Tipo5;

		---**********************************************************
	-- Realizo   :Alejandro Osuna
	--Solicito : Jorge Nuñez
	-- Proyecto : Reporte Consolidado de Huellas
	-- Actividad : Obtiene el total de cada tipo de operacion.
	-- Fecha     :30 de  Marzo  de 2009


	DEFINE v_sCodRet CHAR(5);
	DEFINE sql_err Integer;
	DEFINE v_iTotalCarga INTEGER;
	DEFINE v_iTipo1 INTEGER;
	DEFINE v_iTipo2 INTEGER;
	DEFINE v_iTipo3 INTEGER;
	DEFINE v_iTipo4 INTEGER;
	DEFINE v_iTipo5 INTEGER;

	LET v_sCodRet = '00000';

	BEGIN
		ON EXCEPTION SET  sql_err

			IF sql_err <> 0 THEN
				let v_sCodRet =  sql_err;
				RETURN v_iTotalCarga, v_iTipo1,v_iTipo2,v_iTipo3,v_iTipo4,v_iTipo5;
			END IF;
		END EXCEPTION;

		---Realiza el conteo total de carga
		SELECT COUNT(secuencia) INTO v_iTotalCarga FROM  bdinteg:si_clientecomparacioncoppel
		WHERE  YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;
		--Reliza el conteo de tipo1
		SELECT COUNT(secuencia) INTO v_iTipo1 FROM  bdinteg:si_clientecomparacioncoppel 
		WHERE tipo = 1 AND YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;
		--Reliza el conteo de tipo2
		SELECT COUNT(secuencia) INTO v_iTipo2 FROM  bdinteg:si_clientecomparacioncoppel 
		WHERE tipo = 2 AND YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;
		--Reliza el conteo de tipo3
		SELECT COUNT(secuencia) INTO v_iTipo3 FROM  bdinteg:si_clientecomparacioncoppel
		WHERE tipo = 3 AND YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;
		--Reliza el conteo de tipo4
		SELECT COUNT(secuencia) INTO v_iTipo4 FROM  bdinteg:si_clientecomparacioncoppel 
		WHERE tipo = 4 AND YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;
		--Reliza el conteo de tipo5
		SELECT COUNT(secuencia) INTO v_iTipo5 FROM  bdinteg:si_clientecomparacioncoppel 
		WHERE tipo = 5 AND YEAR(fechamov) = v_pAnio AND MONTH(fechamov) = v_pMes;

		RETURN v_iTotalCarga, v_iTipo1,v_iTipo2,v_iTipo3,v_iTipo4,v_iTipo5;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_eliminarregion (pIdRegion SMALLINT)
    RETURNING CHAR(6), CHAR(80);

    --pIdRegion : Id de la nueva región.
    --pNombreRegion : Nombre de la nueva región.
    --Autor: René Chiquete Elizalde
    --11-01-2010
    --Da de alta una nueva región.

    DEFINE sCodRet CHAR(6);			--CODIGO DE RETORNO PERSONALIZADO
    DEFINE iCodRet INTEGER ;			--CODIGO DE RETORNO INTERNO
    DEFINE sErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE cErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE iIsamErr smallint;                       --VARIABLE PARA CACHAR EL CODIGO DE ERROR
    DEFINE vContador smallint;
    DEFINE vIdRegion smallint;
    DEFINE vNombreRegion CHAR(30);
    DEFINE vFechaActual DATE;

    LET sCodRet = "000";
    LET cErrorInfo="REGION ELIMINADA EXITOSAMENTE";
    LET sErrorInfo="";
    LET	iCodRet=0;
    LET vContador  = 0;
    LET vIdRegion = 0;

--SET DEBUG FILE TO '/tmp/Rene/PRUEBA.out';
   --TRACE ON;

    BEGIN
        ON EXCEPTION SET iCodRet, iIsamErr, sErrorInfo
            LET sCodRet = iCodRet;
            LET cErrorInfo = sErrorInfo;
            RETURN sCodRet, cErrorInfo;
        END Exception;
        --Se valida el numero de region
        IF nvl(pIdRegion,'') = '' THEN
                LET sCodRet='001';
                LET cErrorInfo='NUMERO DE REGION NO VALIDO';
                RETURN sCodRet, cErrorInfo;
        END IF;
      
        --Se valida que el número de región recibida no se encuentre dada de alta
        SELECT numero_region
       INTO vIdRegion 
        FROM bdinteg:si_regiones
        WHERE numero_region = pIdRegion;

       --Si la consulta regresa algo, quiere decir que el nombre de region ya existe.
        IF nvl(vIdRegion,'') = '' THEN
                LET sCodRet='001';
                LET cErrorInfo='LA REGION INDICADA NO EXISTE';
                RETURN sCodRet, cErrorInfo;                                
        END IF;

       DELETE FROM si_regiones WHERE numero_region = pIdRegion;

        RETURN sCodRet, cErrorInfo;
                        
    END ;
    END PROCEDURE ;

CREATE PROCEDURE "informix".sp_grabarciudadregion (pIdCiudad SMALLINT, pIdRegion SMALLINT, pTipo SMALLINT)
    RETURNING CHAR(6), CHAR(80);

    --pIdCiudad : Id de Ciudad
    --pIdRegion : Id de region.
    -- pTipo: Accion a realizarse: 0 - Actualizar region de ciudad indicada a 0, 1 - Asignar region indicada a la ciudad recibida..
    --Autor: René Chiquete Elizalde
    --11-01-2010
    --Asigna o desasigna regiones a ciudades.

    DEFINE sCodRet CHAR(6);			--CODIGO DE RETORNO PERSONALIZADO
    DEFINE iCodRet INTEGER ;			--CODIGO DE RETORNO INTERNO
    DEFINE sErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE cErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE iIsamErr smallint;                       --VARIABLE PARA CACHAR EL CODIGO DE ERROR
    DEFINE vContador smallint;
    DEFINE vIdCiudad smallint;
    DEFINE vIdRegion smallint;

    LET sCodRet = "000";
    LET cErrorInfo="CIUDAD ASIGNADA A REGION CON EXITO";
    LET sErrorInfo="";
    LET	iCodRet=0;
    LET vContador  = 0;
    LET vIdCiudad = 0;
    LET vIdRegion = 0;
--SET DEBUG FILE TO '/tmp/Rene/PRUEBA.out';
   -- TRACE ON;

    BEGIN
        ON EXCEPTION SET iCodRet, iIsamErr, sErrorInfo
            LET sCodRet = iCodRet;
                    LET cErrorInfo = sErrorInfo;
            RETURN sCodRet, cErrorInfo;

        END Exception;

            --VALIDAMOS DATOS DE ENTRADA
            --Validamos la ciudad
            IF nvl(pIdCiudad,0)='' then
                    LET sCodRet='001';
                    LET cErrorInfo='CIUDAD NO VALIDA';
                    RETURN sCodRet, cErrorInfo;
            --Validamos la region
            ELIF nvl(pIdRegion,0)='' then
                    LET sCodRet='001';
                    LET cErrorInfo='REGION NO VALIDA';
                    RETURN sCodRet, cErrorInfo;
           --Validamos el tipo
           ELIF NOT( (nvl(pTipo,'')<>'') AND (pTipo = 0 OR pTipo = 1) ) then
                    LET sCodRet='001';
                    LET cErrorInfo='TIPO NO VALIDO';
                    RETURN sCodRet, cErrorInfo;
            ELSE
                    --Se verifica si la ciudad recibida existe en el catalogo.
                   
                            SELECT LIMIT 1{ + INDEX (si_catciudades numerociudad)}  numerociudad,numero_region
                            INTO vIdCiudad , vIdRegion
                            FROM bdinteg:si_catciudades 
                            WHERE numerociudad = pIdCiudad;
                          

                            IF (nvl(vIdCiudad,'') <> '') THEN
                                   --Se verifica si la region recibida existe en el catalogo.
                                    SELECT  count(*)
                                    INTO vContador 
                                    FROM bdinteg:si_regiones
                                    WHERE numero_region = pIdRegion;

                                    IF (vContador <> 0) THEN
                                            IF (pTipo = 0) THEN
                                                     --Se verifica si la region recibida como parametro es la misma que la que tiene actualmente la ciudad
                                                     IF (nvl(vIdRegion,0) <> pIdRegion) THEN
                                                            LET sCodRet='001';
                                                            LET cErrorInfo='REGION INDICADA NO COINCIDE CON REGION ASIGNADA';
                                                            RETURN sCodRet, cErrorInfo;
                                                    END IF;

                                                    update si_catciudades set numero_region = 0 where numerociudad = pIdCiudad; 

                                            ELIF (pTipo = 1) THEN
                                                    update si_catciudades set numero_region = pIdRegion where numerociudad = pIdCiudad; 
                                            END IF;
                                    ELSE
                                            LET sCodRet='001';
                                            LET cErrorInfo='REGION NO VALIDA';
                                            RETURN sCodRet, cErrorInfo;
                                    END IF;
                            ELSE
                                    LET sCodRet='001';
                                    LET cErrorInfo='CIUDAD NO VALIDA';
                                    RETURN sCodRet, cErrorInfo;
                            END IF;   
           
            END IF;
            RETURN sCodRet, cErrorInfo;
    END ;
    END PROCEDURE ;

CREATE PROCEDURE "informix".sp_grabarregion (pIdRegion SMALLINT, pNombreRegion CHAR(30), pUsuario CHAR(9))
    RETURNING CHAR(6), CHAR(80);

    --pIdRegion : Id de la nueva región.
    --pNombreRegion : Nombre de la nueva región.
    --Autor: René Chiquete Elizalde
    --11-01-2010
    --Da de alta una nueva región.

    DEFINE sCodRet CHAR(6);			--CODIGO DE RETORNO PERSONALIZADO
    DEFINE iCodRet INTEGER ;			--CODIGO DE RETORNO INTERNO
    DEFINE sErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE cErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE iIsamErr smallint;                       --VARIABLE PARA CACHAR EL CODIGO DE ERROR
    DEFINE vContador smallint;
    DEFINE vIdRegion smallint;
    DEFINE vNombreRegion CHAR(30);
    DEFINE vFechaActual DATE;

    LET sCodRet = "000";
    LET cErrorInfo="REGION AGREGADA EXITOSAMENTE";
    LET sErrorInfo="";
    LET	iCodRet=0;
    LET vContador  = 0;
    LET vIdRegion = 0;

--SET DEBUG FILE TO '/tmp/Rene/PRUEBA.out';
   --TRACE ON;

    BEGIN
        ON EXCEPTION SET iCodRet, iIsamErr, sErrorInfo
            LET sCodRet = iCodRet;
            LET cErrorInfo = sErrorInfo;
            RETURN sCodRet, cErrorInfo;
        END Exception;
        --Se valida el numero de region
        IF nvl(pIdRegion,'') = '' THEN
                LET sCodRet='001';
                LET cErrorInfo='NUMERO DE REGION NO VALIDO';
                RETURN sCodRet, cErrorInfo;
        END IF;
        --Se valida el nombre de region
        IF nvl(pNombreRegion,'') = '' THEN
                LET sCodRet='001';
                LET cErrorInfo='NOMBRE DE REGION NO VALIDO';
                RETURN sCodRet, cErrorInfo;
        END IF;

        --Se valida que el número de región recibida no se encuentre dada de alta
        SELECT numero_region
       INTO vIdRegion
        FROM bdinteg:si_regiones
        WHERE numero_region = pIdRegion;
       --Si la consulta regresa algo, quiere decir que la region ya existe.
        IF nvl(vIdRegion,'') <> '' THEN
                LET sCodRet='001';
                LET cErrorInfo='EL NUMERO DE REGION YA EXISTE';
                RETURN sCodRet, cErrorInfo;
        END IF;

        --Se valida el usuario
        IF nvl(pUsuario,'') = '' THEN
                LET sCodRet='001';
                LET cErrorInfo='USUARIO NO VALIDO';
                RETURN sCodRet, cErrorInfo;
        END IF;


         --Se valida que el nombre de región recibida no se encuentre dada de alta
        SELECT nombre_region
        INTO vNombreRegion
        FROM bdinteg:si_regiones
        WHERE TRIM(nombre_region) = Trim(pNombreRegion);
       --Si la consulta regresa algo, quiere decir que el nombre de region ya existe.
        IF nvl(vNombreRegion,'') <> '' THEN
                LET sCodRet='001';
                LET cErrorInfo='EL NOMBRE DE REGION YA EXISTE';
                RETURN sCodRet, cErrorInfo;
        END IF;

        INSERT INTO si_regiones (numero_region,nombre_region,fecha_alta,fecha_mod,usuario_alta, usuario_mod)
        VALUES(pIdRegion,TRIM(pNombreRegion),(SELECT fecha_hoy from si_fechas), (SELECT fecha_hoy from si_fechas),pUsuario, pUsuario ) ;

        RETURN sCodRet, cErrorInfo;

    END ;
    END PROCEDURE ;

CREATE PROCEDURE "informix".sp_obtenerciudadesregion (pIdRegion SMALLINT, pTipo SMALLINT,pCiudad integer)
    RETURNING CHAR(60), SMALLINT, CHAR(50);

    --pIdRegion : Id de region.
    -- Tipo de filtro que se aplicara: 0 - Traer las ciudades que no pertenecen a la region recibida, 1 - Traer ciudades que  si pertenecen a la region indicada.
    --Autor: René Chiquete Elizalde
    --07-01-2010
    --Obtiene las ciudades dadas de alta y si pertenecen o no a la región indicada en el parametro recibido.

    DEFINE sCodRet CHAR(6);			--CODIGO DE RETORNO PERSONALIZADO
    DEFINE iCodRet INTEGER ;			--CODIGO DE RETORNO INTERNO
    DEFINE sErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE cErrorInfo CHAR(80);			--MENSAJE DE CODIGO DE RETORNO
    DEFINE iIsamErr smallint;                       --VARIABLE PARA CACHAR EL CODIGO DE ERROR

    DEFINE vIdCiudad SMALLINT;                  --NUMERO DE IDENTIFICACION DE LA CIUDAD
    DEFINE vNombreIdIniciales CHAR(50);
	DEFINE iRegistros integer;

    LET sCodRet = "000";
    LET cErrorInfo="PROCESO EXITOSO";
    LET sErrorInfo="";
    LET	iCodRet=0;

    LET vIdCiudad = 0;
    LET vNombreIdIniciales  = "";
	LET iRegistros = 0;

--SET DEBUG FILE TO '/tmp/Rene/PRUEBA.out';
   -- TRACE ON;


    BEGIN
        ON EXCEPTION SET iCodRet, iIsamErr, sErrorInfo
            LET sCodRet = iCodRet;
                    LET cErrorInfo = sErrorInfo;
            RETURN sCodRet, vIdCiudad,vNombreIdIniciales;

        END Exception;

            --VALIDAMOS DATO DE ENTRADA
            IF nvl(pIdRegion,'')='' then
                    LET sCodRet='001';
                    LET cErrorInfo='DATO DE ENTRADA NO VALIDO';
                    RETURN sCodRet,vIdCiudad, vNombreIdIniciales;
            ELSE

                IF (pTipo = 0) THEN
                        FOREACH
                                SELECT { + INDEX (si_catciudades numerociudad)}  nvl(numerociudad,0) numero_ciudad, nvl(TRIM(nombreciudad),'') || ' - ' || nvl(numerociudad,0) || nvl(inicialciudad,'') nombre_id_inicial
                                INTO vIdCiudad, vNombreIdIniciales
                                FROM bdinteg:si_catciudades
                                WHERE nvl(numero_region,0) <> pIdRegion
                                AND numerociudad = CASE WHEN pCiudad = -1 THEN numerociudad ELSE pCiudad END
								--numerociudad = pCiudad
                                ORDER BY numerociudad

                                RETURN sCodRet,vIdCiudad, vNombreIdIniciales  WITH RESUME;
                        END FOREACH;
                ELIF (pTipo = 1) Then
                             FOREACH
                                    SELECT { + INDEX (si_catciudades numerociudad)}  nvl(numerociudad,0) numero_ciudad, nvl(TRIM(nombreciudad),'') || ' - ' || nvl(numerociudad,0) || nvl(inicialciudad,'') nombre_id_inicial
                                    INTO vIdCiudad, vNombreIdIniciales
                                    FROM bdinteg:si_catciudades
                                    WHERE nvl(numero_region,0) = pIdRegion
                                    --numerociudad = pCiudad
                                    ORDER BY numerociudad

                                    RETURN sCodRet,vIdCiudad, vNombreIdIniciales  WITH RESUME;
                            END FOREACH;
                END IF;
            END IF;
			LET iRegistros = DBINFO("sqlca.sqlerrd2");
			if iRegistros = 0 then
			 LET sCodRet='002';
                    LET cErrorInfo='NO HAY INFORMACION CON EL FILTRO INDICADO';
                    RETURN sCodRet,vIdCiudad, vNombreIdIniciales;
			END IF;
    END ;
END PROCEDURE
 DOCUMENT
