CREATE PROCEDURE "informix".sp_reporteconsolidadohuellasdataset(vpMes CHAR(2), vpAnio CHAR(4))

	RETURNING CHAR(16) AS Total_Carga,  CHAR(60) AS Descripcion, INTEGER AS Match_Ambos_dedos_Cliente;

		---**********************************************************
	-- Realizo   :Alejandro Osuna
	--Solicito : Jorge Nuñez
	-- Proyecto : Reporte Consolidado de Huellas
	-- Actividad : Obtiene el total de cada tipo de operacion.
	-- Fecha     :30 de  Marzo  de 2009
	-- Modificado: Edgar Ivan Rochin Rocha 28/05/2010
		---**********************************************************

	DEFINE v_sCodRet CHAR(5);
	DEFINE sql_err Integer;
	--DEFINE v_sTotalCarga CHAR(16);
	--DEFINE viTipo1 INTEGER;
	DEFINE v_sDescripcion CHAR(60);
	DEFINE v_sCiclo CHAR(1);

	DEFINE vdFechaIni DATETIME YEAR TO FRACTION(5);
	DEFINE vdFechaFin DATETIME YEAR TO FRACTION(5);
	DEFINE viTipo INTEGER;
	DEFINE vsTotalTipo INTEGER;

	DEFINE viTipo1 INTEGER;
	DEFINE viTipo2 INTEGER;
	DEFINE viTipo3 INTEGER;
	DEFINE viTipo4 INTEGER;
	DEFINE viTipo5 INTEGER;
	DEFINE viTipo8 INTEGER;
	DEFINE viTotalCarga INTEGER;
	DEFINE viTotReg INTEGER;

	DEFINE v_sDescripcion1 CHAR (60);
	DEFINE v_sDescripcion2 CHAR (60);
	DEFINE v_sDescripcion3 CHAR (60);
	DEFINE v_sDescripcion4 CHAR (60);
	DEFINE v_sDescripcion5 CHAR (60);
	DEFINE v_sDescripcion8 CHAR (60);

	LET v_sCodRet = '00000';
	LET v_sDescripcion = '';
	LET v_sCiclo = '1';

	--LET viTipo1 = 0;
	LET vdFechaIni = CURRENT;
	LET vdFechaFin = CURRENT;
	LET viTipo = 0;
	LET vsTotalTipo = 0;

	LET viTipo1 = 0;
	LET viTipo2 = 0;
	LET viTipo3 = 0;
	LET viTipo4 = 0;
	LET viTipo5 = 0;
	LET viTipo8 = 0;
	LET viTotalCarga = 0;
	LET viTotReg = 0;

	LET v_sDescripcion1 = '1.- Cte Banco vs MaeCoppel';
	LET v_sDescripcion2 = '2.- Cte Banco vs EmpCoppel';
	LET v_sDescripcion3 = '3.- Cte Banco vs MaeBanco';
	LET v_sDescripcion4 = '4.- Cte Banco vs EmpBanco';
	LET v_sDescripcion5 = '5.- Cte Banco Comparación Directa';
	LET v_sDescripcion8 = '8.- Cte No Match';

	BEGIN
		ON EXCEPTION SET  sql_err
			IF sql_err <> 0 THEN
				let v_sCodRet =  sql_err;
			RETURN viTotalCarga, v_sDescripcion,viTipo1;
			END IF;
		END EXCEPTION;

--		SET DEBUG FILE TO "/pisa/leo/tracehuellas.sql";
--		TRACE ON;
		
		
    	let vpMes = lpad(vpMes::char(2)::integer,2,0);

		LET vdFechaIni = vpAnio || '-' || vpMes || '-01 00:00:00';
		LET vdFechaFin = vdFechaIni + INTERVAL(1) MONTH TO MONTH;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		
		
		FOREACH
			SELECT coppel.tipo, COUNT(coppel.tipo)
			INTO viTipo, viTotReg
			FROM bdinteg:si_clientecomparacioncoppel AS coppel INNER JOIN  bdinteg:si_cliente AS cliente
			ON cliente.numcte = (LPAD(TRIM(coppel.numcte::CHAR(9)),9,'0'))
			WHERE coppel.tipo IS NOT NULL
			AND coppel.numcte IS NOT NULL
			AND coppel.fechamov BETWEEN vdFechaIni AND vdFechaFin
			GROUP BY coppel.tipo
			ORDER BY coppel.tipo

			IF (viTipo = 1) THEN
				LET viTipo1 = viTotReg;
			ELIF (viTipo = 2) THEN
				LET viTipo2 = viTotReg;
			ELIF (viTipo = 3) THEN
				LET viTipo3 = viTotReg;
			ELIF (viTipo = 4) THEN
				LET viTipo4 = viTotReg;
			ELIF (viTipo = 5) THEN
				LET viTipo5 = viTotReg;
			ELIF (viTipo = 8) THEN
				LET viTipo8 = viTotReg;
			END IF;
		END FOREACH;

		LET viTotalCarga = viTipo1 + viTipo2 + viTipo3 + viTipo4 + viTipo5 + viTipo8;

		RETURN viTotalCarga, v_sDescripcion1,viTipo1 WITH RESUME;
		RETURN '', v_sDescripcion2,viTipo2 WITH RESUME;
		RETURN '', v_sDescripcion3,viTipo3 WITH RESUME;
		RETURN '', v_sDescripcion4,viTipo4 WITH RESUME;
		RETURN '', v_sDescripcion5,viTipo5 WITH RESUME;
		RETURN '', v_sDescripcion8,viTipo8 WITH RESUME;

	END;
END PROCEDURE
DOCUMENT
'Modificado: Edgar Ivan Rochin Rocha',
'Proyecto: Reporte de Huellas',
'Solicito: ',
'Descripcion: Se modifico el tipo de consulta para que la ejecucion de este procedimiento sea mas rapido.',
'Fecha: 2010/05/28',
'Version: 20100528.1640',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_depura_limites_x(p_fecha_hoy  date)

    RETURNING CHAR(5)  AS Codigo_retorno, 
              CHAR(80) AS Mensaje,
              CHAR(1)  AS Reverso,
              CHAR(25) AS StorePro;


   DEFINE p_mensaje   varchar(80);  
   DEFINE isam_err    smallint;
   DEFINE error_info  char(40);  
 

   DEFINE v_f_respeta    DATE;
   DEFINE v_f_depura     DATE;   
   DEFINE vi_valor    INTEGER;

   DEFINE v_codigo_retorno  CHAR(5);
   DEFINE v_mensaje	    CHAR(80);
   DEFINE v_reverso         CHAR(1);
   DEFINE v_store_pro       CHAR(25);
  
   DEFINE vsqlerr      INTEGER;

   DEFINE vrowid       INTEGER;     
	
	--*********************************************************--
	-- Creado por: Francisco Martinez Viveros	
	--Fecha: 07/JULIO/2010
    --Modificacion: 21/JULIO/2010
	--Objetivo: Diariamente depure la tabla si_limite_diario, 
    --de modo que conserve únicamente los últimos 15 días de información 
    --(con base en el campo f_operacion). 
	--*********************************************************--
      
   --    SET debug file TO "/tmp/depura_limite_x.out";
   --    TRACE ON;
              
            LET v_codigo_retorno = "00000";
            LET v_mensaje = "Proceso Inicio Correctamente!";
            LET v_reverso = '0';
            LET v_store_pro = 'sp_depura_limites_x';

        SET ISOLATION TO dirty READ;
        SET LOCK MODE TO wait 3;

    BEGIN
       ON EXCEPTION SET vsqlerr        
          IF vsqlerr <> 0 THEN      
               LET v_codigo_retorno = "00030";
               LET v_mensaje = "Se Genero Error de Exceptio, Verifique Datos SQL!";
               LET v_reverso = '1';
               LET v_store_pro = 'sp_depura_limites_x';              
             RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;            
          END IF;
       END EXCEPTION;


         SELECT valor
           INTO vi_valor
           FROM si_param
           WHERE empresa = '001'
             AND cod_param = '111';
            IF NOT EXISTS (SELECT valor FROM si_param WHERE empresa = '001' AND cod_param = '111')
              THEN 
                    LET vi_valor = 15;
                    LET v_codigo_retorno = "00032";
                    LET v_mensaje = "Se Genero Error en si_param, No Existe Parametro 111!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_depura_limites_x';                 
            END IF;   


           LET vrowid      = 0;
           LET v_f_respeta = (p_fecha_hoy - vi_valor units day);
           LET v_f_depura  = (v_f_respeta);


          IF (p_fecha_hoy is null) then
                    LET v_codigo_retorno = "00030";
                    LET v_mensaje = "Se genero error de Ejecucion, Fecha Nula!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_depura_limites_x';
                RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
          END IF;

          IF (p_fecha_hoy <> today) then
                    LET v_codigo_retorno = "00031";
                    LET v_mensaje = "Se genero error de Ejecucion, Diferente de Hoy!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_depura_limites_x';
                RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
          END IF;

 
               FOREACH cursor_borra WITH HOLD FOR
                SELECT {+index (si_limite_diario idx_limite_ope)} rowid 
                  INTO vrowid  
                  FROM bdinteg:si_limite_diario
                 WHERE f_operacion <= v_f_depura  
                

                BEGIN WORK;
                   DELETE FROM {+index (si_limite_diario idx_limite_dia)}
                     bdinteg:si_limite_diario WHERE 
                    CURRENT OF cursor_borra;                                                                             
               COMMIT WORK;
             END FOREACH;  

                IF (v_reverso <> '0') THEN
                   RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
                 END IF;                 
               
                  LET v_codigo_retorno = "00000";
                  LET v_mensaje = "Proceso de Depuracion, Termino Correctamente!";
                  LET v_reverso = '0';
                  LET v_store_pro = 'sp_depura_limites_x';                                

    END;   --begin        
  RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_pase_msgs_x(p_fecha_pase   DATE)
    RETURNING CHAR(5)  AS Codigo_retorno, 
              CHAR(80) AS Mensaje,
              CHAR(1)  AS Reverso,
              CHAR(25) AS StorePro;              
               

    DEFINE vsqlerr               INTEGER; 

    DEFINE v_codigo_retorno	 CHAR(5);
    DEFINE v_mensaje	  	 CHAR(80);
    DEFINE v_reverso         CHAR(1);
    DEFINE v_store_pro       CHAR(25);

    DEFINE vrowid       INTEGER;
    DEFINE vd_valida       DATE;
    DEFINE vd_valida3      DATE;

    DEFINE v_f_depura     DATE;   --Variable para la depuracion del historico
    DEFINE v_f_respeta    DATE;
    DEFINE vi_valor    INTEGER;



          -- SET debug file TO "/tmp/pase_msgs.out";
          -- TRACE ON;

             LET v_codigo_retorno = "00000";
             LET v_mensaje = "Proceso Inicia Correctamente";
             LET v_reverso = '0';
             LET v_store_pro = 'sp_pase_msgs_x';


            SET ISOLATION TO dirty READ;
            SET LOCK MODE TO wait 3;

 BEGIN
   ON EXCEPTION SET vsqlerr          
        IF vsqlerr <> 0 THEN         
            LET v_codigo_retorno = "00030";
            LET v_mensaje = "Se Genero Error de Exceptio, Verifique Datos SQL!";
            LET v_reverso = '1';         
            LET v_store_pro = 'sp_pase_msgs_x';
         RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
        END IF;
   END EXCEPTION;


         SELECT valor
           INTO vi_valor
           FROM si_param
           WHERE empresa = '001'
             AND cod_param = '111';
            IF NOT EXISTS (SELECT valor FROM si_param WHERE empresa = '001' AND cod_param = '111')
              THEN 
                    LET vi_valor = 15;
                    LET v_codigo_retorno = "00032";
                    LET v_mensaje = "Se Genero Error en si_param, No Existe Parametro 111!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_pase_msgs_x';                 
            END IF;   



    LET vrowid      = 0;
    LET vd_valida   = (p_fecha_pase + 1 units day);
    LET vd_valida3  = p_fecha_pase;
 
    LET v_f_respeta = (p_fecha_pase - vi_valor units day);
    LET v_f_depura  = (v_f_respeta);


	--*********************************************************--
	-- Creado por: Francisco Martinez Viveros	
	--Fecha Creacion: 05/JULIO/2010
    --Fecha Modifica: 21/JULIO/2010
	--Objetivo: Traspasa los mensajes diarios enviados a la tabla historica.    
	--*********************************************************--

           IF (p_fecha_pase is null) THEN
                    LET v_codigo_retorno = "00030";
                    LET v_mensaje = "Se genero error de Ejecucion, Verifique Fecha Nula!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_pase_msgs_x';
                RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
           END IF;

           IF (p_fecha_pase > vd_valida) THEN
                    LET v_codigo_retorno = "00031";
                    LET v_mensaje = "Se genero error de Ejecucion, Verifique Fecha Mayor!";
                    LET v_reverso = '1';
                    LET v_store_pro = 'sp_pase_msgs_x';
                RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
           END IF;



           FOREACH cursor_inserta WITH HOLD FOR
                 SELECT  {+index (si_mensajes_enviar idx_msgs_envdos)}
                          rowid
                    INTO vrowid            
                   FROM bdinteg:"informix".si_mensajes_enviar
                  WHERE date(f_mensaje) < p_fecha_pase
                  --TO_CHAR(f_mensaje,'%Y-%m-%d') = TO_CHAR(p_fecha_pase,'%Y-%m-%d')
                    AND enviado = 'V'
                    AND numcte <> ''
             BEGIN WORK;
                   INSERT INTO {+index (si_mensajes_enviar_his idx_msgs_envhis)} 
                     bdinteg:"informix".si_mensajes_enviar_his 
                      SELECT {+index (si_mensajes_enviar idx_msgs_envdos)} 
                      * FROM bdinteg:"informix".si_mensajes_enviar
                       WHERE rowid = vrowid;
                                                                   
                    DELETE FROM {+index (si_mensajes_enviar idx_msgs_envdos)}
                       bdinteg:"informix".si_mensajes_enviar
                        WHERE CURRENT OF cursor_inserta;
             COMMIT WORK;                           
               
           END FOREACH;


      -- FOREACH 2 ELIMINA DATOS DE 15 DIAS ANTERIORES A LA FECHA HOY EN EL HISTORICO
               FOREACH cursor_borra WITH HOLD FOR
                SELECT {+index (si_mensajes_enviar_his idx_msgs_envhis)} rowid                     
                  INTO vrowid  
                  FROM bdinteg:"informix".si_mensajes_enviar_his 
                 WHERE date(f_mensaje) <= v_f_depura  
                
                BEGIN WORK;
                   DELETE FROM {+index (si_mensajes_enviar_his idx_msgs_envhis)}
                     bdinteg:"informix".si_mensajes_enviar_his WHERE 
                    CURRENT OF cursor_borra;                                                                             
               COMMIT WORK;
             END FOREACH;  




               IF (v_reverso <> '0') THEN        
                   RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
               END IF;
                     LET v_codigo_retorno = "00000";
                     LET v_mensaje = "Proceso Pase de Mensajes, Termino Correctamente!";
                     LET v_reverso = '0';         
                     LET v_store_pro = 'sp_pase_msgs_x';   

       
           
 END;   --begin        
      RETURN v_codigo_retorno, v_mensaje, v_reverso, v_store_pro;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtiene_udi(pFecha date)

 RETURNING CHAR(5) as Codigo, CHAR (300) as Mensaje, DATE as fecha_UDI;

    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE v_Codret1    CHAR(5);
    DEFINE v_Codret     CHAR(5);
    
    DEFINE pEmpresa         CHAR(3);
    DEFINE vPrecio_udi      DECIMAL(14,6);
    DEFINE vTope_udis       DECIMAL (16,0);
    DEFINE vId_canal        CHAR(2);
    DEFINE vMensaje         CHAR (300);
    DEFINE vLim_canal_udis  DECIMAL (16,0);
    
    DEFINE vFechaPaso	      DATE;
    DEFINE vRestriccion     CHAR (2);
    
    LET sql_err     = 0;
    LET isam_err    = 0;
    LET v_Codret1   = '00000';
    LET v_Codret    = '';
    LET vMensaje    = 'El proceso concluyó exitosamente';
    
    LET pEmpresa          = '001';
    LET vPrecio_udi       = 0.00; 
    LET vTope_udis        = 0.00; 
    LET vId_canal         = '';
    LET vLim_canal_udis   = 0; 
    
    LET vFechaPaso        = "";
    LET vRestriccion      = '';
     --**************************************************************
     -- Creado por Raúl Ramírez    01/Jul/2010         
     -- Obtinen la UDI vigente y Convierte el UDI al Maximo de Pesos
     --**************************************************************


BEGIN

   ON EXCEPTION SET sql_err
            --SET DEBUG FILE TO "/ids10_uc9/raul/capitulox/obtiene_udi.err";
            --TRACE ON;
      IF sql_err <> 0  THEN
         LET v_Codret1 = sql_err;
         LET v_Codret1 = v_Codret1;
        -- ROLLBACK WORK;
         --RETURN v_Codret;
      END IF
   END EXCEPTION;
               --SET DEBUG FILE TO "/ids10_uc9/raul/capitulox/obtiene_udi.out";
               --TRACE ON;


---  Obtiene la UDI reciente
          
        EXECUTE PROCEDURE intercard:"informix".sp_obtener_udi(pEmpresa, pFecha)
                     INTO v_Codret, vPrecio_udi, vFechaPaso;

---  Convierte las UDIS a Pesos Maximos
    FOREACH                            
        SELECT {+index (si_plimites idx_plimites)} tope_max_udis, id_canal, id_restriccion
          INTO vTope_udis, vId_canal, vRestriccion
          FROM bdinteg:si_plimites


	             IF vTope_udis = 0 OR vTope_udis is NULL THEN
		              CONTINUE FOREACH;		
	                ELSE
		                IF vTope_udis > 0 THEN

		                UPDATE {+index (si_plimites idx_plimites)} bdinteg:si_plimites
		                   SET tope_max_pesos = (vPrecio_udi * vTope_udis)
		                 WHERE id_canal = vId_canal
                       AND id_restriccion = vRestriccion;
		                END IF;
	              END IF;
    END FOREACH;
---  Actualiza las UDIS a la fecha más reciente
    FOREACH
        SELECT {+index (si_canales idx_canal)} limite_canal_udis, id_canal
          INTO vLim_canal_udis, vId_canal
          FROM bdinteg:si_canales

          
	             IF vLim_canal_udis = 0 OR vLim_canal_udis is NULL THEN
		              CONTINUE FOREACH;		
	                ELSE
		               IF vLim_canal_udis > 0 THEN

		               UPDATE {+index (si_canales idx_canal)} bdinteg:si_canales
		                  SET limite_canal_pesos = (vPrecio_udi * vLim_canal_udis)
		                WHERE id_canal = vId_canal;
		               END IF;
	             END IF;
    END FOREACH;

END
   RETURN v_Codret1, vMensaje, vFechaPaso;
   
END PROCEDURE;

CREATE PROCEDURE "informix".sp_reversa_acum_x( pfecha_oper  DATE,
					                 pnum_cliente CHAR(10), 
                                               pnum_cta     CHAR(16), 
                                               pid_opera    CHAR(2),
                                               pid_canal    CHAR(2),   -- 01:ATM, 03:PORTAL                                    
                                               pmonto_tran  money(16,2))

	RETURNING CHAR(5)  AS Codigo_retorno, 
              CHAR(80) AS Mensaje,
              CHAR(1)  AS Reverso;
	
    DEFINE v_numcte 	        CHAR(10);	
    DEFINE v_cuenta             CHAR(16);
    DEFINE v_idopera            CHAR(2);
    DEFINE v_idcanal            CHAR(2);
    DEFINE v_fopera             DATE;
    DEFINE v_monto_tran         DECIMAL(18,2);
    DEFINE v_importe_dia        money(16,2);
   
	DEFINE vsqlerr				INTEGER;
  
    DEFINE v_codigo_retorno		CHAR(5);
    DEFINE v_mensaje			CHAR(80);
    DEFINE v_reverso            CHAR(1);
	
	--*********************************************************--
	-- Creado por: Francisco Martinez Viveros	
	-- Fecha: 29/JUNIO/2010
      -- Modif: 23/JULIO/2010 Version sin Sequential-Scan
	-- Objetivo: Decrementa el campo importe_dia de la tabla si_limite_diario 
      -- restándole el monto a reversar, para el cliente  cuenta  canal especificado.
	--*********************************************************--
	
	--SET DEBUG FILE TO '/tmp/sp_sp_reversa_acum_x.out';
	--	TRACE ON;

            LET vsqlerr = 0;
            LET v_numcte  = pnum_cliente;
            LET v_codigo_retorno = "00000";
            LET v_mensaje = "";
            LET v_reverso = '0';

            
              IF 
                (pnum_cliente IS NULL OR pnum_cliente = '') OR 
                (pnum_cta     IS NULL OR pnum_cta     = '') OR  
                (pid_opera    IS NULL OR pid_opera    = ''  OR LENGTH(pid_opera) <> 2) OR
                (pid_canal    IS NULL OR pid_canal    = ''  OR pid_canal <='00' OR LENGTH(pid_canal) <> 2) OR
                (pfecha_oper  IS NULL OR pfecha_oper  = '') AND
                (pmonto_tran  IS NULL OR pmonto_tran <= 0.00) THEN   
                    LET v_codigo_retorno = "00036";
                    LET v_mensaje = "Se genero error de Ejecucion, Verifique Datos!";
                    LET v_reverso = '1';
                RETURN v_codigo_retorno, v_mensaje, v_reverso;
              END IF;

              BEGIN
                  ON EXCEPTION SET vsqlerr
                      IF vsqlerr <> 0 THEN                                        
                          LET v_codigo_retorno = "00030";
                          LET v_mensaje = "Se Genero Error de Exceptio, Verifique Datos SQL!";
                          LET v_reverso = '1';
                         RETURN v_codigo_retorno, v_mensaje, v_reverso;
                      END IF;
                    END EXCEPTION;

               SET ISOLATION TO DIRTY READ;
               SET LOCK MODE TO WAIT 3;

            IF pid_canal = '03' THEN
               LET v_idopera =  pid_opera;
            ELSE
               LET v_idopera = '00';
            END IF;

	
	       SELECT {+index (si_limite_diario idx_limite_dia)} 
                  numcte, cuenta, importe_dia 
                  INTO v_numcte, v_cuenta, v_importe_dia  
                  FROM bdinteg:si_limite_diario 
                 WHERE numcte = pnum_cliente
                   AND cuenta = pnum_cta
                   AND id_operacion = v_idopera
                   AND id_canal = pid_canal 
                   AND f_operacion = pfecha_oper;
                      

                 IF NOT EXISTS(SELECT {+index (si_limite_diario idx_limite_dia)} 
                                 numcte, cuenta, importe_dia 
                                 FROM bdinteg:si_limite_diario 
                                WHERE numcte = pnum_cliente
                                  AND cuenta = pnum_cta
                                  AND id_operacion = v_idopera
                                  AND id_canal = pid_canal 
                                  AND f_operacion = pfecha_oper) THEN                                   
                    LET v_codigo_retorno = "00037";
                    LET v_mensaje = "Registro a Reversar no existe!";
                    LET v_reverso = '1';
                	RETURN v_codigo_retorno, v_mensaje, v_reverso;              
                 END IF;    

                   LET v_fopera  = pfecha_oper; 
                   LET v_idcanal = pid_canal;
                   LET v_monto_tran = pmonto_tran;

				IF (pmonto_tran > 0 AND  pmonto_tran <= v_importe_dia) THEN
					UPDATE {+index (si_limite_diario idx_limite_dia)}
                           bdinteg:si_limite_diario                     
                       SET importe_dia = importe_dia - pmonto_tran 
                     WHERE numcte = pnum_cliente                           
                       AND cuenta = pnum_cta
                       AND id_operacion = v_idopera
                       AND id_canal = pid_canal 
                       AND f_operacion = pfecha_oper;
										
                        LET v_codigo_retorno = "00000";
                        LET v_mensaje = "Reverso Realizado con Exito";
                        LET v_reverso = '0';
                END IF;  -- IF pmonto_tran > 0 THEN    --pmonto_tran <= v_importe_dia

                IF (pmonto_tran > v_importe_dia) THEN
                    LET v_codigo_retorno = "00035";
                    LET v_mensaje = "El monto a reversar supera el limite diario registrado!";
                    LET v_reverso = '1';
                  RETURN v_codigo_retorno, v_mensaje, v_reverso;
                END IF;                
				
			RETURN v_codigo_retorno, v_mensaje, v_reverso;		
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarcatusuarios(p_sEmpresa CHAR(3), p_sSistema CHAR(2), p_sUsuario CHAR(10))
RETURNING CHAR(5) AS CodigoRetorno, CHAR(2) AS NumSistema, CHAR(10) AS Usuario, CHAR(20) AS Descripcion, CHAR(8) AS UsuarioInsert,
DATE AS FechaInsert;

        DEFINE iSqlErr                  INTEGER;
        DEFINE v_sCodRet                CHAR(5);

    DEFINE v_sSistema           CHAR(2);
    DEFINE v_sUsuario           CHAR(10);
    DEFINE v_sDescripcion       CHAR(20);
    DEFINE v_sUserInsert        CHAR(8);
    DEFINE v_dFechaInsert       DATE;

    BEGIN
        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                        LET v_sCodRet = iSqlErr;
                        RETURN v_sCodRet, '', '', '', '', '';
                END IF;
        END EXCEPTION;

	   --set debug file to "/tmp/sp_consultarcatusuarios.out";
	    --trace on;

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;

        IF NVL(p_sEmpresa, '') = '' THEN
                LET v_sCodRet = '00001';
                RETURN v_sCodRet, '', '', '', '', '';
        END IF;

        IF NVL(p_sSistema, '') = '' THEN
                LET p_sSistema = NULL;
        END IF;

        IF NVL(p_sUsuario, '') = '' THEN
                LET p_sUsuario = NULL;
        END IF;

        FOREACH
        SELECT sistema, usuario, descripcion, usuario_insert, fecha_insert
        INTO v_sSistema, v_sUsuario, v_sDescripcion, v_sUserInsert, v_dFechaInsert
        FROM bdinteg:si_usuarios
        WHERE empresa = p_sEmpresa AND sistema = NVL(p_sSistema,sistema) AND usuario = NVL(p_sUsuario,usuario)

                LET v_sCodRet = '00000';
                RETURN v_sCodRet, v_sSistema, v_sUsuario, v_sDescripcion, v_sUserInsert, v_dFechaInsert WITH RESUME;
        END FOREACH;
    END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validardiaferiado(p_sEmpresa CHAR(3), p_dFecha DATE)
RETURNING CHAR(5) AS CodigoRetorno, DATE AS DiaFeriado, CHAR(30) AS DescDiaFeriado, CHAR(1) AS LaborableSN;

	DEFINE iSqlErr			INTEGER;
	DEFINE v_sCodRet		CHAR(5);
	
	DEFINE v_dFecha			DATE;
	DEFINE v_sDescripcion	CHAR(30);
	DEFINE v_sLaborable		CHAR(1);

	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET v_sCodRet = iSqlErr;
				RETURN v_sCodRet, '', '', '';
			END IF;
		END EXCEPTION;

	   --set debug file to "/tmp/sp_validardiaferiado.out";
	    --trace on;

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;
		
		IF NVL(p_sEmpresa, '') = '' OR NVL(p_dFecha, '') = '' THEN
			LET v_sCodRet = '00001';
			RETURN v_sCodRet, '', '', '';
		END IF;	 

		SELECT fecha, descripcion, laborable INTO v_dFecha, v_sDescripcion, v_sLaborable FROM bdinteg:si_feriado 
		WHERE empresa = p_sEmpresa AND fecha = p_dFecha;
		
		IF v_dFecha IS NULL THEN
			LET v_sCodRet = '00000';			
			RETURN v_sCodRet, '', '', '';
		ELSE
			LET v_sCodRet = '00002';
			RETURN v_sCodRet, v_dFecha, v_sDescripcion, v_sLaborable;
		END IF		
	END
END PROCEDURE;

CREATE PROCEDURE "informix".constipydircliente(pEmpresa CHAR(3), pRFC CHAR(13), pOpcion INTEGER, cNumCliente CHAR(20))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5),  -- Codigo de Retorno
    CHAR(20); --Numero de Cliente

	--DEFINICION DE VARIABLES--
	DEFINE cCodRet		CHAR(5);
    DEFINE cTipCte      CHAR(1);
    DEFINE cDirExi      CHAR(1);
    DEFINE cNumCte      CHAR(20);
    DEFINE iSqlErr		INTEGER;
    
    LET iSqlErr         = 0;
    LET cNumCte         = "";
BEGIN
    ON EXCEPTION
        SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, cNumCte;
        END IF;
	END EXCEPTION;
    --Valida Direccion de los Beneficiarios
    IF pOpcion = 1 THEN
        IF cNumCliente = "" THEN
            SELECT numcte, tipo_cliente INTO cNumCte, cTipCte FROM bdinteg:si_cliente WHERE rfc = pRFC;
        ELSE
            SELECT tipo_cliente INTO cTipCte FROM bdinteg:si_cliente WHERE numcte = cNumCliente;
            LET cNumCte = cNumCliente;
        END IF
        SELECT NVL(COUNT(*),"0") INTO cDirExi FROM bdinteg:si_direcciones WHERE numcte = cNumCte;
        
        IF (cTipCte = "1") AND (cDirExi <> "0") OR (cTipCte = "2") AND (cDirExi <> "0") THEN 
            LET cCodRet = "000";
            RETURN cCodRet, cNumCte;
        ELSE
            IF cTipCte = 1 THEN
                LET cCodRet = "001";
                RETURN cCodRet, cNumCte;
            ELSE
                LET cCodRet = "002";
                RETURN cCodRet, cNumCte;
            END IF; 
        END IF;
    ELSE --Obiene Numero del Cliente
        SELECT numcte INTO cNumCte FROM bdinteg:si_cliente WHERE rfc = pRFC;
        LET cCodRet = "003";
        RETURN cCodRet, cNumCte;
    END IF
END
END PROCEDURE
DOCUMENT
'Modifico: Adrian Lara',
