CREATE PROCEDURE "informix".inserta_reg_expediente(
                       pempresa     char(3),
                       pcliente     char(20),
                       pcuenta      char(20),
                       pproducto    char(4),
                       pcod_docto   char(4),
                       psecuencia   smallint,
                       pprod_nombre char(40),
                       pdescrip2    char(30),
                       puser_insert char(8))
                       RETURNING    char(5);


   DEFINE sql_err,isam_err int;

   DEFINE v_tempo char(1);
   DEFINE v_codret char(5);
   DEFINE v_fecha date;
   DEFINE v_inst char(50);
   DEFINE v_inst2 char(50);


-- v1.1 validacion adicional para que no se dupliquen lalo oct09
-- v1   version inicial


-- Inicializa variables


   LET v_codret    = "000";
   LET v_fecha     = today;


--SET DEBUG FILE TO "/tmp/inserta_reg_expediente.out";
--TRACE ON;
BEGIN
   on exception set sql_err,isam_err
      if sql_err <> 0 or isam_err <> 0 then
         let v_codret = sql_err;
         return v_codret;
      end if;
   end exception;





-- Valida la informacion de entrada


    IF  pempresa        is null or
        pcliente        is null or
        pcuenta         is null or
        pproducto       is null or
        pcod_docto      is null or
        psecuencia      is null or
        pprod_nombre    is null or
        puser_insert    is null THEN

       -- datos de entrada incompletos

       LET v_codret = 110;
       RETURN v_codret;
    END IF;


   select trim(valor)||'dg_expediente' into v_inst from dg_params where cod_param=5;
   let v_inst2=trim(v_inst);
    -- validar duplicado
    select  "1"
    into    v_tempo
    from    v_inst2
    where   empresa     = pempresa
    and     cliente     = pcliente
    and     cuenta      = pcuenta
    and     producto    = pproducto
    and     cod_docto   = pcod_docto
    and     secuencia   = psecuencia;

    IF dbinfo("sqlca.sqlerrd2") <> 0 then
            -- ya existe, salir
            RETURN v_codret;
    END IF


    -- insertar registro en dg_expediente


    insert into v_inst2
                (empresa,cliente,cuenta,
                producto,cod_docto,secuencia,prod_nombre,descrip2,
                usuario_alta,fecha_alta)
    values      (pempresa,pcliente,pcuenta,pproducto,pcod_docto,
                psecuencia,pprod_nombre,pdescrip2,puser_insert,
                v_fecha);

END;

RETURN v_codret;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_asigna_boletos(p_cve_sorteo CHAR(5),p_bolped INT, p_fecha DATE)
RETURNING VARCHAR(6),VARCHAR(80), INTEGER, INTEGER;
DEFINE  SQL_ERR          INTEGER;
DEFINE  ISAM_ERR         INTEGER;
DEFINE  ERROR_INFO       VARCHAR(80);
DEFINE  P_COD_RET        VARCHAR(6);
DEFINE  P_MENSAJE        VARCHAR(80);
DEFINE  vboleto_inicial   INTEGER;
DEFINE wBegin              CHAR(1);
LET SQL_ERR          = 0;
LET ISAM_ERR         = 0;
LET ERROR_INFO       = '';
LET P_COD_RET        = '';
LET P_MENSAJE        = '';
LET vboleto_inicial = 0;
LET wBegin = "N";

BEGIN
 ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
      LET P_COD_RET    = SQL_ERR;
      LET P_MENSAJE  = ERROR_INFO;	  
      RETURN P_COD_RET, P_MENSAJE, 0, 0;
 END EXCEPTION;

 ON EXCEPTION IN (-535)
      LET wBegin = "S";
 END EXCEPTION WITH RESUME;

 
--Set debug file to "/tmp/asigna_boletos.out";
--Trace on;
   
   LET P_COD_RET = '00000';
   LET P_MENSAJE = 'PROCESO EXITOSO';
   SET LOCK MODE TO WAIT 3;
   
    BEGIN WORK;
        UPDATE {+index (si_sorteo idx_si_sorteo)} 
              bdinteg:si_sorteo
          SET max_boleto = max_boleto + p_bolped
        WHERE cve_sorteo = p_cve_sorteo;

            SELECT {+index (si_sorteo idx_si_sorteo_cve)}  --FMV: 10-SEP-10 OPTIMIZADO
         max_boleto INTO vboleto_inicial 
                 	FROM bdinteg:si_sorteo 
                   WHERE cve_sorteo = p_cve_sorteo ;
    COMMIT WORK;

    -- FMV 4-SEP-10 Para pruebas masivas SSH INFORMIX, q no sean de Caja anular linea BEGIN WORK.
    IF wBegin = "S" THEN    
        BEGIN WORK;
    END IF
                 LET vboleto_inicial = vboleto_inicial - p_bolped;
                 RETURN P_COD_RET, P_MENSAJE, vboleto_inicial + 1, vboleto_inicial + p_bolped;   


END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_insertarsucursalessorteo( )
RETURNING CHAR(5);

DEFINE  SQL_ERR                  INTEGER;
DEFINE  ISAM_ERR                 INTEGER;
DEFINE  ERROR_INFO           CHAR(80);
DEFINE  P_COD_RET             CHAR(5);
DEFINE  cSucursal                   CHAR(4);

LET SQL_ERR                 = 0;
LET ISAM_ERR                = 0;
LET ERROR_INFO          = '';
LET P_COD_RET            = '';
LET cSucursal                  = '';

BEGIN
 ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
      LET P_COD_RET    = SQL_ERR;
      RETURN P_COD_RET;
 END EXCEPTION;
 
 --Set debug file to "/respaldosbd/saul/sp_obtparamsorteo.out";
 --Trace on;
   
   LET P_COD_RET = '00000';

   SET LOCK MODE TO WAIT 3;
   SET ISOLATION TO DIRTY READ;

   FOREACH
              SELECT sucursal 
              INTO       cSucursal
              FROM     si_sucursales
              WHERE  tpo_sucursal ='S'  
              
              INSERT INTO si_sucursales_sorteo(empresa, sucursal, cve_sorteo_normal, cve_sorteo_inst, flag_sorteo_normal, flag_imprime_normal, flag_sorteo_inst, flag_imprime_inst,  fecha_insert, user_insert)
              VALUES('001', cSucursal,'00002','00003', 0, 0, 0, 0, CURRENT, USER);
 
   END FOREACH;

   RETURN P_COD_RET;   

END;
END PROCEDURE             
DOCUMENT
"Descripción: Procedimiento que Inserta en la tabla que contiene los parametros del sorteo",
"BD: bdinteg",
"Fecha: 19-Octubre-2010",
