CREATE PROCEDURE "informix".sp_seleccionsorteo( )

    RETURNING CHAR(5), CHAR(5), CHAR(50);

    -- DEFINICION DE VARIABLES --
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRet CHAR(5);
    DEFINE cCveSorteo CHAR(5);
    DEFINE cResultado CHAR(50);
	DEFINE v_param	  CHAR(5);
	

    -- INICIALIZACION DE VARIABLES --
    LET cCodRet = "00000";
    LET cCveSorteo = "00000";
    LET cResultado = "";

    --SET DEBUG FILE TO '/tmp/sp_seleccionsorteo.out';
    --TRACE ON;

    BEGIN
        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
                RETURN cCodRet, cCveSorteo, cResultado;
        END IF;
    END EXCEPTION;

	 SELECT valor INTO v_param
	FROM bdinteg:si_param
	WHERE cod_param = 118;

    SELECT cve_sorteo, descripcion INTO cCveSorteo, cResultado
    FROM si_sorteo WHERE cve_sorteo = v_param;

    RETURN cCodRet, cCveSorteo, cResultado;    

    END;
END PROCEDURE;

CREATE PROCEDURE "informix".spconsultarcatplazas (p_sEmpresa CHAR(3), p_sPlaza CHAR (3), p_sRegional CHAR (3))
RETURNING CHAR(5) AS CodigoRetorno, CHAR(3) AS empresa, CHAR (3) AS plaza, CHAR(40) AS nombre, CHAR (3) AS regional, DATE AS fecha_insert;
	
	DEFINE iSqlErr			INTEGER;
	
	DEFINE v_sCodRet       	CHAR(5);
	DEFINE v_sEmpresa 		CHAR(3);
	DEFINE v_sPlaza 		CHAR(3);
	DEFINE v_sregional      CHAR(3);
	DEFINE v_sNomPlaza  	CHAR(40);
	DEFINE v_dFecha			DATE;

	-----------------------------------------------------------
	--SET DEBUG FILE TO "/tmp/prisma/spconsultarcatplazas.out"; 
	--TRACE ON;
    -----------------------------------------------------------
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET v_sCodRet = iSqlErr;
				RETURN v_sCodRet,'','','','','';
			END IF;
		END EXCEPTION;
	
		LET v_dFecha = CURRENT::DATE;
	
		LET v_sCodRet = '00000';
		
		IF NVL(p_sEmpresa, '') = '' THEN
			LET v_sCodRet = '00001';
			RETURN v_sCodRet,'','','','','';
		END IF;
		
		IF p_sRegional = '' THEN
			LET p_sRegional = NULL;
		END IF;
		
		IF p_sPlaza = '' THEN
			LET p_sPlaza = NULL;
		END IF;
		
		FOREACH
			SELECT empresa, plaza, nombre, regional, fecha_insert
			INTO v_sEmpresa, v_sPlaza, v_sNomPlaza, v_sregional, v_dFecha
			FROM bdinteg:si_plazas
			WHERE empresa = p_sEmpresa AND plaza = NVL(p_sPlaza, plaza) AND regional = NVL(p_sRegional, regional)
			
			RETURN v_sCodRet, v_sEmpresa, v_sPlaza, v_sNomPlaza, v_sregional, v_dFecha WITH RESUME;
		END FOREACH
	END
END PROCEDURE
DOCUMENT
'CREADO:      Prisma Calderón',
'FECHA:       2 de febrero de 2010',
'CASO DE USO: Caso de uso asociado PCU-bdinteg\CU-0129-ConsultarCat-Plazas-SPL',
'DESCRIPCIÓN: Consultar el catalogo si_plazas ',
'Retorno: 00000  Consulta Exitosa';

CREATE PROCEDURE "informix".spconsultarcatregiones (p_sEmpresa CHAR(3), p_sRegional CHAR (3))
RETURNING CHAR(5) AS CodigoRetorno, CHAR(3) AS empresa, CHAR (3) AS regional, CHAR(40) AS nombre, DATE AS fecha_insert;
	
	DEFINE iSqlErr			INTEGER;

	DEFINE v_sCodRet       	CHAR(5);
	DEFINE v_sEmpresa 		CHAR(3);
	DEFINE v_sregional      CHAR(3);
	DEFINE v_sNomRegion  	CHAR(40);
	DEFINE v_dFecha			DATE;

	-----------------------------------------------------------
	--SET DEBUG FILE TO "/tmp/prisma/spconsultarcatregiones.out"; 
	--TRACE ON;
    -----------------------------------------------------------
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET v_sCodRet = iSqlErr;
				RETURN v_sCodRet,'','','','';
			END IF;
		END EXCEPTION;
	
		LET v_dFecha = current::DATE;
		
		LET v_sCodRet = '00000';
		
		IF NVL(p_sEmpresa, '') = '' THEN
			LET v_sCodRet = '00001';
			RETURN  v_sCodRet,'','','','';
		END IF;
		
		IF p_sRegional = '' THEN
			LET p_sRegional = NULL;
		END IF;
		
		FOREACH
			SELECT empresa, regional, nombre, fecha_insert
			INTO v_sEmpresa, v_sregional, v_sNomRegion, v_dFecha
			FROM bdinteg:si_regional
			WHERE empresa = p_sEmpresa AND regional = NVL(p_sRegional, regional)
			
			RETURN v_sCodRet, v_sEmpresa, v_sregional, v_sNomRegion, v_dFecha WITH RESUME;
		END FOREACH
	END
END PROCEDURE
DOCUMENT
'CREADO:      Prisma Calderón',
'FECHA:       2 de febrero de 2010',
'CASO DE USO: Caso de uso asociado PCU-bdinteg\CU-0128-ConsultarCatRegiones-SPL',
'DESCRIPCIÓN: Consultar el catalogo si_regional ',
'Retorno: 00000  Consulta Exitosa';

CREATE PROCEDURE "informix".validarclienteempleado(i16Tipo SMALLINT, cNumCliente CHAR(20))

	RETURNING CHAR(5) AS cod_ret;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNumCte INTEGER;
	
	LET cCodRet = '000';
	LET iSqlErr = 0;
	LET iNumCte = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;		
			END IF;
		END EXCEPTION;

		--SET DEBUG FILE TO "/tmp/validarclienteempleado.out";
		--TRACE ON;

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;

		IF cNumCliente IS NULL OR LENGTH(cNumCliente) = 0 THEN
			LET cCodRet = '001';
			RETURN cCodRet;	
		END IF;

		IF i16Tipo = 1 THEN
			SELECT {+INDEX (bdinteg:si_clientecomparacioncoppel idx_clientecomparacioncoppel)} -- BGM 09-Nov-2010: se coloca directiva
			numcte INTO iNumCte  
			FROM bdinteg:si_clientecomparacioncoppel
			WHERE numcte = cNumCliente::INT AND (tipo = 2 OR tipo= 4);

			IF iNumCte IS NULL THEN
				LET cCodRet = '002';
				RETURN cCodRet;
			END IF;
		END IF;
		
		RETURN cCodRet;
	END
END PROCEDURE
DOCUMENT
'Valida si el Cliente es Empleado',
'AUTOR: Iris Arias Zazueta',
'FECHA: 14/10/2009',
'BD: bdinteg';

create procedure "informix".consintegpba(pempresa     char(3),
                           pnum_cte     char(20),
			   psucursal    char(4),
			   pusuario     char(8),
			   prenglon     smallint)
   returning char(5),char(40),char(2),char(20),char(4),char(40),date,date,
	     money(14,2),money(14,2),char(40),char(40),char(20);

-- ************************************************************************
-- Define variables
-- ************************************************************************
   define cod_ret char(5);
   define v_sistema char(2);
   define v_sucursal char(4);
   define v_tpersona char(2);
   define v_numero char(20);
   define v_nombre1,v_materno,v_paterno char(12);
   define v_razon char(36);
   define v_completo char(36);
   define v_producto char(40);
   define v_cuenta char(20);
   define v_delega CHAR(20);
   define v_fecha_alta,v_fecha_venc date;
   define v_calle,v_colonia char(40);
   define v_monto1,v_monto2 money(14,2);
   define vc_sdo_actual,vc_sdo_retenido,vc_sdo_cong,vc_acum_sdo_pos,
	  v_sdo_prom,v_sdo_disp,vi_intereses,vi_isr,
	  vd_exig,vd_no_exig money(14,2);
   define vc_dia_sdo_pos,v_renglon,v_secuencia1,v_secuencia2 smallint;
   define longitud,v_long_cte smallint;
   define sql_err integer;
   define vnocalle  integer;
   define vnocolonia integer;
   define vnociudad integer;

-- ************************************************************************
-- Inicializa variables
-- ************************************************************************
   let cod_ret      = "000";
   let v_sucursal   = " ";
   let v_producto   = " ";
   let v_cuenta     = " ";
   let v_sistema    = " ";
   let v_fecha_alta = " ";
   let v_fecha_venc = " ";
   let v_monto1     = 0;
   let v_monto2     = 0;
   let v_renglon    = 0;
   let v_calle      = " ";
   let v_colonia    = " ";
   let v_completo   = " ";
   let v_delega     = " ";
   let vnocalle     = 0;
   let vnocolonia   = 0;
   let vnociudad    = 0;


begin
   on exception set sql_err
      if sql_err <> 0 then
	 let cod_ret = sql_err;
         return cod_ret,v_completo,v_sistema,v_cuenta,v_sucursal,
		v_producto,v_fecha_alta,v_fecha_venc,v_monto1,v_monto2,
		v_calle,v_colonia,v_delega;
      end if
   end exception;


   SET ISOLATION TO DIRTY READ;

-- ***********************************************************************
    select numcte,apell_paterno,apell_materno,
       nombre1,razon_social,tpo_persona
       into v_numero,v_paterno,v_materno,
       v_nombre1,v_razon,v_tpersona
       from si_cliente
	where numcte=pnum_cte;

	if v_numero is null then
	   let cod_ret = "137";
           return cod_ret,v_completo,v_sistema,v_cuenta,v_sucursal,
	          v_producto,v_fecha_alta,v_fecha_venc,v_monto1,v_monto2,
	          v_calle,v_colonia,v_delega;
	end if

       if (v_razon is null) or (trim(v_razon) = "") then
          let v_completo = trim(v_paterno)||" "||trim(v_materno)||
			   " "||trim(v_nombre1);
	else
          let v_completo = v_razon;
       end if

-- ***************************************************************************
-- Verifica si debe generar la tabla de consulta
-- ***************************************************************************
--   if prenglon = 0 then
      delete from si_consinteg
      where sucursal = psucursal and usuario = pusuario and
	    numcte  = pnum_cte;
      -- *********************************************************************
      -- Extrae la informacion del Sistema de Cheques
      -- *********************************************************************
      foreach
         select mc.cuenta,sucursal,mc.producto||" "||pr.nombre,fecha_alta,
	        dia_sdo_pos,acum_sdo_pos,sdo_actual,sdo_retenido,
	        sdo_cong,numerocalle,numerocolonia,numerociudad,
                CASE
                 WHEN status_cta = "1" and marca_ret ="0" then
                      "Sin Deposito Inicial"
                 WHEN status_cta ="1" and marca_ret ="1" then
                      "Activa"
                 WHEN status_cta ="2" then
                      "Cancelada"
                 WHEN status_cta = "3" then
                      "Bloqueada"
                END
           into v_cuenta,v_sucursal,v_producto,v_fecha_alta,
	        vc_dia_sdo_pos,vc_acum_sdo_pos,vc_sdo_actual,vc_sdo_retenido,
	        vc_sdo_cong,vnocalle,vnocolonia,vnociudad, v_delega
         from bdicheq:sc_maechq mc,bdicheq:sc_maenoc mn,
              bdicheq:sc_producto pr,outer si_direcciones di
         where num_cte = pnum_cte and
	       mc.cuenta = mn.cuenta and mc.producto = pr.producto and
	       numcte = num_cte and secuencia = direcc_envio
         order by mc.cuenta
         if vc_dia_sdo_pos > 0 then
            let v_sdo_prom = vc_acum_sdo_pos / vc_dia_sdo_pos;
         else
	    let v_sdo_prom = 0;
         end if
         let v_sdo_disp = vc_sdo_actual - vc_sdo_retenido - vc_sdo_cong;
         let v_monto1   = v_sdo_prom;
         let v_monto2   = v_sdo_disp;

	if v_monto2 is null then
		let v_monto2 = 0;
	end if

	if v_monto1 is null then
		let v_monto1 = 0;
	end if

        -- Extrae la Direccion Coppel
        select nvl(nombrecalle,"") into v_calle
        From si_catcalles where numerocalle = vnocalle;
        Select nvl(nombrezona,"")
        into v_colonia
        From si_catzonas
        where numerociudad = vnociudad and numerocolonia = vnocolonia;
        if v_colonia is null then
           let v_colonia = "";
        end if

         --Graba la informacion en la tabla temporal de consulta integral
         let v_renglon = v_renglon + 1;
         insert into si_consinteg
         values(psucursal,pusuario,v_renglon,pnum_cte,"01",v_cuenta,
	        v_sucursal,v_producto,v_fecha_alta,v_fecha_alta,
	        v_monto2,v_monto1,v_calle,v_colonia,v_delega);
      end foreach

      -- *********************************************************************
      -- Extrae la informacion del Sistema de Inversiones
      -- *********************************************************************
      foreach
        select cuenta,mv.sucursal,mv.cod_instrum||" "||pr.nombre,
               mv.fecha_alta,fecha_venc,capital,intereses,isr,mv.secuencia,
               mv.secuencia,calle,colonia,municipio,
	       DECODE(status_cta, "1","Activa","3","Bloqueada")
           into v_cuenta,v_sucursal,v_producto,v_fecha_alta,
	        v_fecha_venc,v_monto1,vi_intereses,vi_isr,v_secuencia1,
		v_secuencia2,vnocalle,vnocolonia,vnociudad, v_delega
         from bdinvers:sv_maeinv mv,
              bdinvers:sv_instrum pr,outer si_direcciones di
         where mv.num_cte = pnum_cte
	 and mv.status_cta="1" and mv.cod_instrum = pr.cod_instrum
	 and numcte = pnum_cte and di.secuencia = direcc_envio
         order by cuenta
         let v_monto2   = vi_intereses - vi_isr;

	if v_monto2 is null then
		let v_monto2 = 0;
	end if

	if v_monto1 is null then
		let v_monto1 = 0;
	end if

        -- Extrae la Direccion Coppel
        select nvl(nombrecalle,"") into v_calle
        From si_catcalles where numerocalle = vnocalle;
        Select nvl(nombrezona,"")
        into v_colonia
        From si_catzonas
        where numerociudad = vnociudad and numerocolonia = vnocolonia;
        if v_colonia is null then
           let v_colonia = "";
        end if
        if v_calle is null then
           let v_calle = "";
        end if

        --Graba la informacion en la tabla temporal de consulta integral
        let v_renglon = v_renglon + 1;
         insert into si_consinteg
        values(psucursal,pusuario,v_renglon,pnum_cte,"03",v_cuenta,
        v_sucursal,v_producto,v_fecha_alta,v_fecha_venc,
	        v_monto1,v_monto2,v_calle,v_colonia,v_delega);
    end foreach
      -- *********************************************************************
      -- Extrae la informacion del Sistema de Credito
      -- *********************************************************************

      foreach
         select mc.num_credito,sucursal,mc.num_producto||" "||pr.nombre_prod,
                fecha_apertura,
                fecha_vencim,sdo_cap_insoluto,sdo_no_exig,sdo_exig_int,
	        DECODE(status_cred,"AA","Activo", "BA","Suspendido",
				   "BT","Suspendido", "FF", "Liquidado",
				   "CC","Problematico","Convenio")
            into v_cuenta,v_sucursal,v_producto,v_fecha_alta,
	         v_fecha_venc,v_monto1,vd_no_exig,vd_exig, v_delega
            from bdicred:sd_maecred mc,bdicred:sd_maesdos ms,
                 bdicred:sd_definicion pr
            where numcte = pnum_cte and mc.num_credito = ms.num_credito and
                  mc.num_producto = pr.num_producto
            order by 1
	 let v_monto2 = vd_exig + vd_no_exig;
	 if v_monto2 is null then
	    let v_monto2 = 0;
	 end if
	 if v_monto1 is null then
	    let v_monto1 = 0;
	 end if

         --Graba la informacion en la tabla temporal de consulta integral
         let v_renglon = v_renglon + 1;
         insert into si_consinteg
            values(psucursal,pusuario,v_renglon,pnum_cte,"06",v_cuenta,
	           v_sucursal,v_producto,v_fecha_alta,v_fecha_venc,
	           v_monto1,v_monto2,v_calle,v_colonia,v_delega);
      end foreach
   -- ************************************************************************
   -- Verifica si existen renglones en la tabla
   -- ************************************************************************
   select count(*) into v_numero
   from si_consinteg
   where sucursal = psucursal and usuario = pusuario and
	 numcte  = pnum_cte;

   -- ***********************************************************************
   -- Regresa la informacion generada en la tabla a partir del num de renglon
   -- ***********************************************************************
   if v_numero <= 0 then
      let cod_ret = "127";
      if v_fecha_venc is null then
         let v_fecha_venc = today;
      end if
      return cod_ret,v_completo,v_sistema,v_cuenta,v_sucursal,
	     v_producto,v_fecha_alta,v_fecha_venc,v_monto1,v_monto2,
	     v_calle,v_colonia,v_delega;
   end if
   foreach
      select sistema,cuenta,sucursal_cta,producto,fecha_alta,
	     fecha_venc,importe_1,importe_2,calle,colonia,delegacion
	     into v_sistema,v_cuenta,v_sucursal,v_producto,v_fecha_alta,
	     v_fecha_venc,v_monto1,v_monto2,v_calle,v_colonia,v_delega
      from si_consinteg
      where sucursal = psucursal and
	    usuario  = pusuario  and
	    numcte  = pnum_cte  and
	    renglon  > prenglon
      if v_fecha_venc is null then
         let v_fecha_venc = today;
      end if
      return cod_ret,v_completo,v_sistema,v_cuenta,v_sucursal,
		v_producto,v_fecha_alta,v_fecha_venc,v_monto1,
		v_monto2,v_calle,v_colonia,v_delega WITH RESUME;
   end foreach
end
end procedure
DOCUMENT
"MODIFICO : Manuel Hern ndez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".sp_valida_reversada (pIdSucursal CHAR(4),
                                                 pFolioOperacion CHAR(16),
                                                 pTipoOperacion CHAR(2))
                                                 
RETURNING CHAR(5) AS cod_ret;

--- DECLARACION DE VARIABLES

	DEFINE vCodRet     CHAR(5);
	DEFINE iSqlErr     INTEGER;
      
  DEFINE vCiclo      CHAR(1);
    
			
--- INICIALIZACION DE VARIABLES


	LET vCodret       = '00000';
	LET iSqlErr       = '0';
      
  LET vCiclo        = '';
    
     --****************************************************************
     -- Creado por Raúl Ramírez    07/Septiembre/2010
     -- Proceso para validar transacciones reversadas para la traducción
     -- de boletos a un detalle de boletos
     --****************************************************************

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				 LET vCodRet = iSqlErr;
				RETURN vCodret;		
			END IF;
		END EXCEPTION;

       -- SET DEBUG FILE TO "/ids10_uc9/raul/sorteo/sp_valida_reversada.out";
       -- TRACE ON;


    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    

        IF pTipoOperacion = '10' THEN 
						--Para debito
						--IF EXISTS (SELECT {+INDEX (bdicheq:sc_movdia idx_movdia2a)} -- BGM 09-Nov-2010: se coloca directiva
						                 --empresa, cuenta, fech_alt, cancelad, transacc, folio_suc 
									     --FROM bdicheq:sc_movdia
									     --WHERE empresa is not null
										 --WHERE folio_suc  = pFolioOperacion     -- BGM 09-Nov-2010: se cambia condición
									     -- AND cuenta is not null    			-- BGM 09-Nov-2010: se comenta condición
									     --AND empresa = '001'
									     --AND fech_alt is not null   			-- BGM 09-Nov-2010: se comenta condición
									     --AND transacc is not null   			-- BGM 09-Nov-2010: se comenta condición
									     --AND cancelad = 'S') THEN
			IF EXISTS (SELECT {+INDEX (bdinteg:si_movreversados idx_si_movrever)} empresa, folio_suc 
				FROM bdinteg:si_movreversados
				WHERE empresa = '001'
				AND folio_suc  = pFolioOperacion     -- BGM 16-Nov-2010: se cambia tabla a si_movreversados
				AND tipo_mov = pTipoOperacion) THEN
				LET vCiclo = 'S';
						--ELSE
						--	    IF EXISTS (SELECT {+INDEX (bdicheq:sc_movdia idx_movdia2a)}  -- BGM 09-Nov-2010: se coloca directiva
						--		  empresa,folio_suc    
                        --    FROM bdicheq:sc_movdia
						--				         WHERE folio_suc  = pFolioOperacion
						--				         AND  empresa = '001'
						--				         AND cancelad = 'S') THEN
						--                
                        --     LET vCiclo = 'S';
						--	    END IF;	
			END IF;
        END IF;
        IF pTipoOperacion = '11' THEN
          	
						--IF vCiclo <> 'S' THEN
              --Para credito
							--IF EXISTS (SELECT {+INDEX (bdicred:sd_movdia mov2)}  -- BGM 09-Nov-2010: se coloca directiva
							 --folio_suc 
                        --FROM bdicred:sd_movdia
								        --WHERE sucursal = pIdSucursal
								        --AND  folio_suc = pFolioOperacion
								        --AND reversado = 'S') THEN
						            --LET vCiclo = 'S';								
						  --ELSE
						    	--IF EXISTS(SELECT {+INDEX (bdicred:sd_movdia mov2)}  -- BGM 09-Nov-2010: se coloca directiva
								   --folio_suc --, codigo_fun, codigo_ref             -- BGM 09-Nov-2010: se omiten datos que no se usan
                              --FROM bdicred:sd_movdia 
									   		--	    WHERE folio_suc = pFolioOperacion 
										    --		AND codigo_fun is not null
										    --		AND codigo_ref is not null
										  	--	    AND reversado = 'S') THEN
			IF EXISTS (SELECT {+INDEX (bdinteg:si_movreversados idx_si_movrever)} empresa, folio_suc 
				FROM bdinteg:si_movreversados
				WHERE empresa = '001'
				AND folio_suc  = pFolioOperacion     -- BGM 16-Nov-2010: se cambia tabla a si_movreversados
				AND tipo_mov = pTipoOperacion) THEN
				LET vCiclo = 'S'; 
				   
			END IF;
		END IF;	
		
          	
		IF vCiclo = 'S' THEN
             LET vCodRet = '00101';
             --LET vMensaje = 'Folio Reversado';
        END IF;
END
    RETURN vCodret; --, vMensaje;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_migrar_si_bpipprod(pPag INTEGER)
RETURNING CHAR (5), CHAR(12), CHAR(4);
	-- Creador: Javier Calderón
	-- Objetivo: Obtener registros a la tabla si_bpiprod, como proceso de la migrasion
	-- Solicitó: Diana Castellanos
	-- Fecha: 21/10/2010
	DEFINE sql_err int;
	DEFINE vCod_ret CHAR(5);
	DEFINE vProducto CHAR(4);
	DEFINE vId_oper CHAR(12);
	BEGIN
		ON EXCEPTION SET sql_err
		  IF sql_err <> 0 THEN
				let vCod_ret = sql_err;
				RETURN vCod_ret, vId_oper, vProducto;
		  END IF ;
		END EXCEPTION;
		
		LET vCod_ret = '00000';
		FOREACH
			SELECT SKIP pPag FIRST 10 id_oper, producto INTO vId_oper, vProducto FROM si_bpipprod ORDER BY id_oper
			
			RETURN vCod_ret, vId_oper, vProducto WITH RESUME;
		END FOREACH;
	END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerparametros(p_iCodParam INTEGER, p_sEmpresa CHAR(3))
RETURNING CHAR(50) AS descripcion,
          CHAR(100) AS valor;
        
    DEFINE v_sDescripcion 	CHAR(50);
    DEFINE v_sValor			CHAR(100);
    DEFINE vparam_min       SMALLINT;
    DEFINE vparam_max       SMALLINT;
    
    LET v_sDescripcion = '';
    LET v_sValor       = '';
    LET vparam_min     = 0;
    LET vparam_max     = 0;

    --- Creado por Erick Zamora 17/12/2008

    --- SET DEBUG FILE TO "/tmp/sp_obtenerParametros.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;

    BEGIN
    
    SELECT {+FULL} MIN(cod_param), MAX(cod_param)
      INTO vparam_min, vparam_max
      FROM bdinteg:si_param;
    
    IF p_iCodParam is null OR p_iCodParam = '' THEN
        FOREACH
            SELECT {+INDEX(bdinteg:si_param ix_si_param)} descripcion, valor
              INTO v_sDescripcion, v_sValor
              FROM bdinteg:si_param
             WHERE cod_param BETWEEN vparam_min AND vparam_max --- NVL(p_iCodParam,cod_param)
               AND empresa = p_sEmpresa

            RETURN v_sDescripcion, v_sValor WITH RESUME;
        END FOREACH;
    ELSE
        FOREACH
            SELECT {+INDEX(bdinteg:si_param ix_si_param)} descripcion, valor
              INTO v_sDescripcion, v_sValor
              FROM bdinteg:si_param
             WHERE cod_param = p_iCodParam --- NVL(p_iCodParam,cod_param)
               AND empresa = p_sEmpresa

            RETURN v_sDescripcion, v_sValor WITH RESUME;
        END FOREACH;
    END IF;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarproductopermitido(psEmpresa CHAR(3),psNumCte CHAR(20),psCveOperacion CHAR(12))
    RETURNING CHAR(6);

--Declaracion de variables

DEFINE vsCodRet CHAR(6);
DEFINE viSqlErr INTEGER;
DEFINE viNumProdPerm INTEGER;
DEFINE vsProdCte CHAR(4);

--SET DEBUG FILE TO "/tmp/sp_ValidarProductoPermitido.out";
--TRACE ON;

--Asignacion de variables

LET vsCodRet = '00000';
LET viSqlErr = 0;
LET viNumProdPerm = 0;
LET vsProdCte = '';

IF NVL(psEmpresa, '') = '' THEN --Valida que la empresa no sea nulo o espacio en blanco
	LET vsCodRet = '00002';
ELIF NVL(psNumCte, '') = '' THEN --Valida que el Numero de Cliente no sea nulo o espacio en blanco
	LET vsCodRet = '00003';
ELIF NVL(psCveOperacion, '') = '' THEN --Valida que el Numero de Operacion no sea nulo o espacio en blanco
	LET vsCodRet = '00004';
ELSE --Valida que el Numero de Cliente exista
	IF NOT EXISTS(SELECT numcte FROM bdinteg:si_cliente WHERE numcte = TRIM(psNumCte) AND empresa = TRIM(psEmpresa)) THEN
		LET vsCodRet = '00005';
	END IF;
END IF;

--Inicio del procedimiento

BEGIN

	ON EXCEPTION SET viSqlErr --Manejador de Errores
		IF viSqlErr <> 0 then
			LET vsCodRet = viSqlErr;
			RETURN vsCodRet;
		END IF;
	END EXCEPTION;

	IF vsCodRet = '00000' THEN
		FOREACH --Obtiene productos de captacion y valida si son permitidos
			SELECT {+INDEX(bdicheq:sc_maechq mae1)} producto INTO vsProdCte FROM bdicheq:sc_maechq WHERE num_cte = TRIM(psNumCte) AND empresa = TRIM(psEmpresa)

			IF EXISTS(SELECT {+INDEX(bdibpi:bpi_pprod ind_perfil)} producto FROM bdibpi:bpi_pprod WHERE id_oper = TRIM(psCveOperacion) AND producto = vsProdCte)THEN
				LET viNumProdPerm = viNumProdPerm + 1;
			ELSE
				CONTINUE FOREACH;
			END IF;
		END FOREACH;

		IF viNumProdPerm = 0 THEN
			FOREACH --Obtiene productos de credito y valida si son permitidos
				SELECT {+INDEX(bdicred:sd_maecred idx_11a)} num_producto INTO vsProdCte FROM bdicred:sd_maecred WHERE numcte = TRIM(psNumCte) AND empresa = TRIM(psEmpresa)

				IF EXISTS(SELECT {+INDEX(bdibpi:bpi_pprod ind_perfil)} producto FROM bdibpi:bpi_pprod WHERE id_oper = TRIM(psCveOperacion) AND producto = vsProdCte)THEN
					LET viNumProdPerm = viNumProdPerm + 1;
				ELSE
					CONTINUE FOREACH;
				END IF;
			END FOREACH;
		END IF;

		IF viNumProdPerm = 0 THEN --Valida que halla existido x lo menos 1 producto permitido
			LET vsCodRet = '00001';
		END IF;
	END IF;

	RETURN vsCodRet;

END
END PROCEDURE
DOCUMENT
"Valida si es un producto permitido",
"Autor : Marcos Cuevas",
"FECHA : 20/mayo/2009",
"Ver.  : 1.0",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".consnombrenumctenew(pEmpresa CHAR(3),
						pNombre1 CHAR(26),
						pNombre2 CHAR(26),
                        pPaterno CHAR(26),
                        pMaterno CHAR(26),
						pFechaNac DATE,
						pNo_Rfc CHAR(13),
						pRazon CHAR(60),
                        pSecuencia SMALLINT)

RETURNING CHAR(5),CHAR(60),CHAR(20),CHAR(13);

DEFINE sql_err 									  INTEGER;
DEFINE v_longitud,v_ciclo 					      SMALLINT;
DEFINE v_nombre_completo 						  CHAR(63);
DEFINE v_nombre1, v_nombre2, v_paterno, v_materno CHAR(26);
DEFINE v_numcte 								  CHAR(20);
DEFINE v_cod_ret 								  CHAR(5);
DEFINE v_razon_soc 								  CHAR(60);
DEFINE v_rfc 									  CHAR(13);

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

LET v_cod_ret = "00000";
LET v_ciclo = 0;
LET v_nombre_completo = "";
LET v_numcte = "0000000000";
LET v_rfc = "";

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
     END IF;
   END EXCEPTION;

IF NVL(pEmpresa,'') = ''  THEN
	LET v_cod_ret = "00001";
	LET v_nombre_completo = 'Parámetros incompletos';
	RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
END IF;

SET ISOLATION TO DIRTY READ;

IF pRazon IS NOT NULL AND pRazon !="" THEN
    FOREACH
        SELECT skip pSecuencia limit 21
             razon_social,numcte,rfc
 	    INTO v_razon_soc,v_numcte,v_rfc
        FROM si_cliente
        WHERE razon_social = prazon
           and apell_paterno = ''
	       and apell_materno = ''
        ORDER BY numcte
--        LET v_ciclo = v_ciclo+1;
--        IF v_ciclo <= psecuencia THEN
-- 	        CONTINUE FOREACH;
--        END IF;
        LET v_nombre_completo = v_razon_soc;
        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
    END FOREACH;
ELSE

    IF pNo_Rfc IS NOT NULL AND pNo_Rfc != "" THEN
        FOREACH
            SELECT skip pSecuencia limit 21 
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc
	        INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
      	    FROM si_ctepf pf, si_cliente cl
      	    WHERE rfc = pno_rfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte
--      	    LET v_ciclo = v_ciclo+1;
--      	    IF v_ciclo <= psecuencia THEN
--                 CONTINUE FOREACH;
--      	    END IF;
	        LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
             || " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
	        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS

--	IF NVL(pPaterno,'') = '' AND NVL(pMaterno,'') = '' THEN
	IF NVL(pPaterno,'') = ''  THEN
		LET v_cod_ret = "00002";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos apellidos';
		RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
--	ELIF NVL(pNombre1,'') = '' AND NVL(pNombre2,'') = '' THEN
	ELIF NVL(pNombre1,'') = '' THEN
		LET v_cod_ret = "00003";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos nombres';
		RETURN v_cod_ret, v_nombre_completo, v_numcte,v_rfc;
	ELSE
        if ( pPaterno is null or pPaterno = "" ) then
           let pPaterno = "";
        else
--           let pPaterno = trim(pPaterno)||"*";
           let pPaterno = trim(pPaterno);
        end if;  

        if ( pMaterno is null or pMaterno = "" ) then
           let pMaterno = "";
        else
--           let pMaterno = trim(pMaterno)||"*";
           let pMaterno = trim(pMaterno);
        end if;  

        if ( pNombre1 is null or pNombre1 = "" ) then
           let pNombre1 = "";
        else
           let pNombre1 = trim(pNombre1)||"*";
        end if;  

        if ( pNombre2 is null or pNombre2 = "" ) then
           let pNombre2 = "";
        else
           let pNombre2 = trim(pNombre2)||"*";
        end if;  

--		LET pPaterno = TRIM(pPaterno)||"*";
--		LET pMaterno = TRIM(pMaterno)||"*";
--		LET pNombre1 = TRIM(pNombre1)||"*";
--		LET pNombre2 = TRIM(pNombre2)||"*";

		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
				FROM si_ctepf pf, si_cliente cl
				WHERE cl.apell_paterno = ppaterno
				AND cl.apell_materno = pmaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo + 1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;

		ELSE

			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
				FROM si_cliente
				WHERE apell_paterno = ppaterno
				AND apell_materno = pmaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo+1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(UPPER(v_materno))
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE
DOCUMENT
'Consulta clientes por nombre(s) y apellido(s) y por fecha de nacimiento si asi se requiere',
'AUTOR : Dulce Ramirez',
'FECHA : 01/Junio/2009',
'Ver.  : 1.1',
'BD    : bdinteg',
'VER   : 1.1';

CREATE PROCEDURE "informix".sp_obtenernumproductonew(p_sEmpresa CHAR(3), p_sNumCuenta CHAR(20), p_sNumTarjeta CHAR(20))
RETURNING	 VARCHAR(6) as sNumProducto --numero de producto

	DEFINE iSqlErr				INTEGER;
	DEFINE v_sNumProducto 		CHAR(4);
	DEFINE v_sTipoCuenta		CHAR(2);
	-----------------------------------------------------------------------------------------------------
	-- AUTOR: Erick Zamora
	-- FECHA: 23-03-2009
	-- Obtiene el numero de producto al que hace referencia una cuenta 
	-- SET DEBUG FILE TO "/tmp/sp_obtenernumproducto.out";
	-- TRACE ON;
	------------------------------------------------------------------------------------------------------
	LET v_sNumProducto = "";
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr;
			END IF;
		END EXCEPTION;
		LET v_sNumProducto = "0000";
		--SE OBTIENE EL NUMERO DE CUENTA DE LA TARJETA DE DEBITO
		IF p_sNumCuenta = "" AND p_sNumTarjeta <> "" THEN
			SELECT prodtarjeta INTO v_sNumProducto FROM bdicheq:sc_tarjeta WHERE empresa = p_sEmpresa AND num_tarjeta = p_sNumTarjeta;
			RETURN v_sNumProducto;
		END IF
		
		LET v_sTipoCuenta = SUBSTR(p_sNumCuenta,1,2);
		
		IF v_sTipoCuenta IN('10','11','13','15','18','19') THEN	--CUENTAS DE DEBITO
			SELECT producto INTO v_sNumProducto FROM bdicheq:sc_maechq WHERE empresa = p_sEmpresa AND cuenta = p_sNumCuenta;
		
		ELIF v_sTipoCuenta IN ('60', '65','66') THEN				--TC COPPEL
			SELECT num_producto INTO v_sNumProducto FROM bdisolic:ss_solicitudes WHERE empresa = p_sEmpresa AND num_solicitud = p_sNumCuenta;
			IF v_sNumProducto IS NULL AND v_sTipoCuenta in ('60','66') THEN
				SELECT num_producto INTO v_sNumProducto FROM bdicred:sd_maecred WHERE empresa = p_sEmpresa AND num_credito = p_sNumCuenta;
			END IF
			
		ELIF v_sTipoCuenta in ('60','66') THEN						--CUENTAS DE CREDITO					
				SELECT num_producto INTO v_sNumProducto FROM bdicred:sd_maecred WHERE empresa = p_sEmpresa AND num_credito = p_sNumCuenta;
		
		ELIF v_sTipoCuenta = '30' THEN						--CUENTAS DE INVERSION
			SELECT cod_instrum INTO v_sNumProducto FROM bdinvers:sv_maeinv WHERE empresa = p_sEmpresa AND cuenta = p_sNumCuenta;
		
		END IF
		IF v_sNumProducto is null or v_sNumProducto = ""
		THEN
		   LET v_sNumProducto = "0000";
		END IF;
		RETURN v_sNumProducto;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_movtos_reversados (p_empresa CHAR(3))
RETURNING CHAR (5) AS Codigo;

DEFINE v_empresa char(3); 
DEFINE v_fecha_mov date ;
DEFINE v_sucursal char(4);
DEFINE v_transacc char(4);
DEFINE v_cuenta char(20);
DEFINE v_num_producto char(4);
DEFINE v_folio_suc char(16);
DEFINE v_monto decimal(18,2);
DEFINE v_tipo_mov char(2);
DEFINE v_sistema char(1);
DEFINE v_usuario char(8);
DEFINE vCodret CHAR(5);
DEFINE vFecha DATE;

LET vCodret = '00000';


	--*********************************************************--
    	-- Creado por: Francisco Martinez Viveros	
        --Fecha: 16/NOVIEMBRE/2010 
	     --Objetivo: Obtiene los movimientos reversados del dia y se graban
         --          en la tabla si_movreversados de bdinteg para agilizar el proceso batch
         --          el proceso batch del sorteo 2010.
	--*********************************************************--


BEGIN

-- Set debug file to "/tmp/sp_movtos_reversados.out";
-- Trace on;

SET LOCK MODE TO WAIT 3;
SET ISOLATION TO DIRTY READ;


    FOREACH cursor_filtra WITH HOLD FOR
                      SELECT DISTINCT {+index (bdicheq:sc_movdia idx_movdia2a)}
                             folio_suc, empresa, sucursal, usuario, fech_alt, transacc, cuenta, producto, monto_tot
                        INTO  v_folio_suc, v_empresa, v_sucursal, v_usuario, vFecha, v_transacc, v_cuenta, v_num_producto, v_monto
                        FROM bdicheq:sc_movdia
                       WHERE cancelad = 'S'
                         AND (transacc = "0250" OR transacc = "0202")
                         AND monto_tot > 0
                         --AND fech_alt = today

                     --BEGIN WORK;                  
                      INSERT INTO {+index (bdinteg:si_movreversados idx_si_movrever)}
                             bdinteg:"informix".si_movreversados VALUES 
                              (v_empresa,vFecha,v_sucursal, v_transacc,v_cuenta, v_num_producto, v_folio_suc, v_monto,'10','1', v_usuario);                        
                    --COMMIT WORK;                           
    END FOREACH;


 FOREACH cursor_filtra WITH HOLD FOR
                      SELECT DISTINCT {+index ( bdicred:sd_movdia idx_movdia2)}
                             empresa, fecha_mov, folio_suc, sucursal, usuario, transacc_suc, num_credito, num_producto, monto
                        INTO v_empresa, vFecha, v_folio_suc, v_sucursal, v_usuario, v_transacc, v_cuenta, v_num_producto, v_monto
                        FROM bdicred:sd_movdia 
                       WHERE empresa = '001'
                         AND fecha_mov = today
                         AND codigo_fun IN ("033", "336")
                         AND codigo_ref = 1
                         AND reversado = 'S'

                     --BEGIN WORK;                  
                      INSERT INTO {+index (bdinteg:si_movreversados idx_si_movrever)}
                             bdinteg:"informix".si_movreversados VALUES 
                              (v_empresa,vFecha,v_sucursal, v_transacc,v_cuenta, v_num_producto, v_folio_suc, v_monto,'11','6', v_usuario);                        
                    --COMMIT WORK;                           
    END FOREACH;


RETURN vCodret;

 
END;  --BEGIN
END PROCEDURE;

CREATE PROCEDURE "informix".actualiza_fecha_unicareg()

--RETURNING CHAR(5) as cod_ret,CHAR(60) as nombre_completo ,CHAR(20) as numcte,CHAR(13) as rfc,CHAR(2) as tipo_cte;
RETURNING CHAR(5) as cod_ret, INTEGER as r_actualizados;

DEFINE sql_err 			  INTEGER;
DEFINE v_cod_ret		CHAR (5);
DEFINE v_r_actualizado 		      INTEGER;
DEFINE v_empresa 		      CHAR(4);
DEFINE v_numcte 		      CHAR(9);
DEFINE v_id_status 		      CHAR(4);
DEFINE v_f_registro		DATETIME YEAR to SECOND;

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

LET v_cod_ret = "00000";
LET v_r_actualizado = 0;
LET v_empresa = '';
LET v_numcte = '';
LET v_id_status = '';
LET v_f_registro = CURRENT;

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_cod_ret,v_r_actualizado;
     END IF;
   END EXCEPTION;

--SET ISOLATION TO DIRTY READ;
set lock mode to wait 3; 

    FOREACH
        SELECT empresa,numcte,id_status,f_registro
 	    INTO v_empresa,v_numcte,v_id_status,v_f_registro
        FROM bdinteg:si_bpiusuarios
        WHERE empresa = '001'
        and numcte <> ''
        and id_status <> '99'
        and f_unico_reg IS NOT NULL
        ORDER BY numcte

	IF v_f_registro IS NOT NULL OR v_f_registro <> "" THEN
		LET v_r_actualizado = v_r_actualizado + 1;
			
		UPDATE bdinteg:si_bpiusuarios
		SET f_unico_reg = v_f_registro
		WHERE empresa = '001'
		AND numcte = v_numcte
		AND id_status = v_id_status;
		
	END IF;

    END FOREACH;

        RETURN v_cod_ret,v_r_actualizado;

END;
END PROCEDURE
DOCUMENT
'Registra la fecha unica de registro para el regulatorio',
'AUTOR : Ismael Hernandez',
'FECHA : 19/11/2010',
'BD    : bdinteg',
'VER   : 1.0';

CREATE PROCEDURE "informix".sp_asigna_premio (pClaveSort CHAR(5),
                                              pFechaActual DATE,
                                              pIdSucursal CHAR(4),
                                              pIdPremio CHAR(2),
                                              pFolioPremio CHAR(16),
                                              pTipoOperacion CHAR(2),
                                              pNumCliente CHAR(10),
                                              pFolioOperacion CHAR(16),
                                              pImporte MONEY,
                                              pUsuario CHAR(10),
							                                pEtapa CHAR(1))  -- BGM 3-Sep-2010: parámetro para confirmar impresión de ticket.

RETURNING CHAR (5) AS Codigo, CHAR(5) AS Clave_Sorteo, CHAR (80) AS Mensaje;

--- DECLARACION DE VARIABLES

    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE v_Codret         CHAR(5);
    DEFINE vRetorno         CHAR(5);
    DEFINE vMensaje         CHAR(80);
    DEFINE vEstatus         CHAR(1);
    DEFINE vId_sucursal     CHAR(4);
    DEFINE vId_premio       CHAR(2);
    DEFINE vFolio_premio    CHAR(16);
    DEFINE vNumeroCliente   CHAR(10);
    DEFINE vCve_sorteo      CHAR(5);
    DEFINE vTipo            SMALLINT;
    
    DEFINE vNcliente        INTEGER;
    
    DEFINE cCodRet          CHAR(3);
	DEFINE vFechaHoy		DATE;
	DEFINE vFechaPremio		DATE;

--- INICIALIZACION DE VARIABLES

    LET sql_err         = 0;
    LET isam_err        = 0;
    LET v_Codret        = '00000';
    LET vRetorno        = '00000';
    LET vMensaje        = 'El proceso concluyó exitosamente';
    LET vEstatus        = '';
    LET vId_sucursal    = '';
    LET vId_premio      = '';
    LET vFolio_premio   = '';
    LET vNumeroCliente  = '';
    LET vCve_sorteo     = '0';
    LET vTipo           = '';
    
    LET vNcliente       = 0;
    
    LET cCodRet         = '';

     --**************************************************************
     -- Creado por Raúl Ramírez    19/Agosto/2010
     -- Asignacion de Premio Sorteo Instantaneo
     --**************************************************************

BEGIN

    ON EXCEPTION SET sql_err

        IF sql_err <> 0  THEN
            LET v_Codret = sql_err;
            LET v_Codret = v_Codret;
            LET vRetorno = '117';
            LET vMensaje = 'ERROR EN LA EJECUCION';

            RETURN v_Codret, vRetorno, vMensaje;           -- Termina proceso del SP
        END IF;
    END EXCEPTION;

        --SET DEBUG FILE TO "/ids10_uc9/raul/sorteo/sp_asigna_premio.out";
        --TRACE ON;


    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    IF  (pClaveSort IS NULL OR pClaveSort = '' OR LENGTH(pClaveSort) <> 5) OR    -- OR LENGTH(pClaveSort) <> 5
        (pFechaActual IS NULL OR pFechaActual = '') OR
        (pIdSucursal IS NULL OR pIdSucursal = '') OR
        (pIdPremio IS NULL OR pIdPremio = '' OR pIdPremio = '00' OR LENGTH(pIdPremio) <> 2) OR
        (pFolioPremio IS NULL OR pFolioPremio = '' OR LENGTH(pFolioPremio) <> 12) OR
        (pTipoOperacion IS NULL OR pTipoOperacion = '') OR
        (pNumCliente IS NULL OR pNumCliente = '') OR
        (pFolioOperacion IS NULL OR pFolioOperacion = '' OR LENGTH(pFolioOperacion) <> 16) OR
        (pImporte IS NULL OR pImporte = '' OR pImporte <= 0.00) OR
        (pUsuario IS NULL OR pUsuario = '') OR 
	     	(pEtapa IS NULL OR pEtapa = '') THEN               -- BGM 3-Sep-2010: se valida parámetro de Etapa.

        LET v_Codret = '117';
        LET vMensaje = 'Se generó algún error de parametros en la ejecución';

        RETURN v_Codret, vRetorno, vMensaje;               -- Termina proceso del SP
    END IF;

	SELECT {+INDEX(si_fechas idx_si_fechas)} fecha_hoy INTO vFechaHoy
	FROM bdinteg:si_fechas
	WHERE empresa = '001';
	
	IF (NOT EXISTS (SELECT {+index (si_horario_premio idx_si_horario_premio2)} f_sorteo FROM si_horario_premio WHERE f_sorteo = today)) 
		OR (NOT EXISTS (SELECT {+index (si_horario_premio idx_si_horario_premio2)} f_sorteo FROM si_horario_premio WHERE f_sorteo = vFechaHoy))
		OR (vFechaHoy <> pFechaActual) THEN
			LET v_Codret = '118';
			LET vMensaje = 'ERROR DE DATOS';
			RETURN v_Codret, vRetorno, vMensaje;    -- Hoy no es día de entrega de premios
	END IF;
	
    IF pTipoOperacion = 11 OR pTipoOperacion = 10 THEN                           -- Validacion del tipo de Operacion
	
	    IF pEtapa = '1' THEN -- BGM 3-Sep-2010: se valida si es la etapa 1 de asignación de premio
	    
	            EXECUTE PROCEDURE "informix".validarclienteempleado(1, pNumCliente)
                           INTO cCodRet;
                       
          IF cCodRet = '000' THEN
			 LET v_Codret = '118';
			 LET vMensaje = 'EL CLIENTE ES EMPLEADO DE BANCO';
			 RETURN v_Codret, vRetorno, vMensaje;           -- Termina proceso del SP
		  END IF;
        END IF;  
          
          
              SELECT {+index (si_premios_suc idx_si_premiossuc)} cve_sorteo, estatus, id_sucursal, id_premio, folio_premio
              INTO vCve_sorteo, vEstatus, vId_sucursal, vId_premio, vfolio_premio
              FROM bdinteg:si_premios_suc
              WHERE cve_sorteo = pClaveSort
              AND id_sucursal = pIdSucursal
              AND id_premio = pIdPremio
              AND folio_premio = pFolioPremio;

              IF (vCve_sorteo IS NULL OR vCve_sorteo = '') OR
                 (vEstatus IS NULL OR vEstatus = '') OR
                 (vId_sucursal IS NULL OR vId_sucursal = '') OR
                 (vId_premio IS NULL OR  vId_premio = '') OR
                 (vFolio_premio IS NULL OR vFolio_premio = '') THEN         -- Validacion de datos
                   LET v_Codret = '117';
                   LET vMensaje = 'ERROR DE DATOS';
                   RETURN v_Codret, vRetorno, vMensaje;    -- Termina proceso del SP
              END IF;

		    IF vEstatus = '2' AND pEtapa = '1' THEN                             -- Validacion ya fue entregado el premio
               LET v_Codret = '119';
               LET vMensaje = 'EL PREMIO NO EXISTE O YA FUE ASIGNADO';
               RETURN v_Codret, vRetorno, vMensaje;           -- Termina proceso del SP
            END IF;
		
		IF vEstatus = '1' and pEtapa = '1' THEN  -- BGM 3-Sep-2010: se agrega validación de Etapa para confirmar asignación de premio
            UPDATE {+index (si_premios_suc idx_si_premiossuc)} bdinteg:si_premios_suc   -- Actualiza el estatus del premio como ya entregado
            SET estatus = '2', tipo_operacion = pTipoOperacion, Num_cte = pNumCliente,
                foliosuc = pFolioOperacion, Importe = pImporte, f_asignado = pFechaActual,
                usr_registro = pUsuario,impreso = '0'
            WHERE cve_sorteo = vCve_sorteo
            AND id_sucursal = pIdSucursal
            AND id_premio = pIdPremio
            AND folio_premio = pFolioPremio;
        END IF;
		
        IF vEstatus = '2' and pEtapa = '2' THEN  -- BGM 3-Sep-2010: se agrega validación de Etapa para confirmar impresión de ticket
            UPDATE {+index (si_premios_suc idx_si_premiossuc)} bdinteg:si_premios_suc   
            SET impreso = '1'
            WHERE cve_sorteo = vCve_sorteo
            AND id_sucursal = pIdSucursal
            AND id_premio = pIdPremio
            AND folio_premio = pFolioPremio;
        END IF;

        IF (vEstatus = '1') AND (pEtapa = '2') THEN
           LET v_Codret = '119';
            LET vMensaje = 'EL PREMIO NO EXISTE O YA FUE ASIGNADO';
            RETURN v_Codret, vRetorno, vMensaje;
        END IF;
		
	ELSE -- BGM 3-Sep-2010: si el tipo de operación no es 10 ni 11, hay un error en datos
        LET v_Codret = '117';
        LET vMensaje = 'ERROR DE DATOS';
        RETURN v_Codret, vRetorno, vMensaje;
    END IF;
	
END

    RETURN v_Codret, vRetorno, vMensaje;                   -- Termina proceso del SP

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actstatusmensajeenviar(pFecha datetime year to fraction,pNumCte char(10),pNumCta char(16),pEnviado char(1),pObservaciones varchar(80),pFecha_Envio datetime year to fraction)

	RETURNING  CHAR(5);
	--************************************
	--sp_actstatusmensajeenviar
	--Objetivo:Actualiza el estatus de los clientes a los que ya se les envió correo.
	--Autor: Francisco Rodriguez Ibarra
	--Fecha: 12/07/2010
	--Actualización:Se modificó para poder recibir la fecha en datetime y así realizar la busqueda
	--Fecha:15/07/2010
	--Autor:Francisco Rodriguez Ibarra
	--Actualización: Se agrego nuevo parámetro para guardar la fecha con hora del registro de envio del correo.
	--Fecha: 24/11/2010
	--Autor: Walber Castro	
	--****************************************
	
	--DEFINICION DE VARIABLES
	DEFINE vSqlErr          INTEGER;		--variable usada par obtener el numero de error de informix en caso de que ocurra un error interno de informix.
	DEFINE vsCodRet        	CHAR(5);		--variable para el codigo de retorno
	DEFINE v_sNumCte 		CHAR(10);
	
	--ASIGNACION DE VALORES A LAS VARIABLES
	LET vSqlErr =0;
	LET vsCodRet ="00000";
	LET v_sNumCte="";	
	
	BEGIN
		ON EXCEPTION
			SET vSqlErr
			IF vSqlErr <> 0 THEN
				LET vsCodRet = vSqlErr;
				RETURN vsCodRet;
			END IF;
		END EXCEPTION;

		IF ( NVL( pFecha, '' ) = '' ) OR ( NVL( pNumCte, '' ) = '' ) OR ( NVL( pNumCta, '' ) = '' ) THEN
			--Error en datos de parametros invalidos
			LET vsCodRet = '00001';
			
		ELSE

			SELECT LIMIT 1 numcte  INTO v_sNumCte
				FROM bdinteg:si_mensajes_enviar
				WHERE f_mensaje = pFecha
				AND enviado='F'
				AND numcte = TRIM(pNumCte)
				AND cuenta = TRIM(pNumCta);
			
			IF(v_sNumCte <>'' OR v_sNumCte IS NOT NULL) THEN
				UPDATE bdinteg:si_mensajes_enviar SET enviado=TRIM(pEnviado) , f_enviado=pFecha_Envio , observaciones=TRIM(pObservaciones)
					WHERE f_mensaje = pFecha
					AND enviado='F'
					AND numcte = TRIM(pNumCte)
					AND cuenta = TRIM(pNumCta);
					
			ELSE
				LET vsCodRet="00002";			END IF
		
		END IF;
		
		RETURN vsCodRet;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".spobtenercuentascontables (p_sEmpresa CHAR(3), p_sTransaccion CHAR(4), p_sSistema CHAR(2), p_sSecuencia INTEGER)
RETURNING 	CHAR(5) AS CodigoRetorno,
			CHAR(4) AS c_ccmayor,
			CHAR(2) AS c_ccsub,
			CHAR(2) AS c_ccsubsub,
			CHAR(2) AS c_ccsssub,
			CHAR(2) AS c_ccssssub,
			CHAR(2) AS c_sector,
			CHAR(4) AS a_ccmayor,
			CHAR(2) AS a_ccsub,
			CHAR(2) AS a_ccsubsub,
			CHAR(2) AS a_ccsssub,
			CHAR(2) AS a_ccssssub,
			CHAR(2) AS a_sector;
	
	DEFINE iSqlErr			INTEGER;
	DEFINE v_sCodRet       	CHAR(5);	
	DEFINE v_sC_ccmayor		CHAR(4);
	DEFINE v_sC_ccsub		CHAR(2);
	DEFINE v_sC_ccsubsub	CHAR(2);
	DEFINE v_sC_ccsssub		CHAR(2);
	DEFINE v_sC_ccssssub	CHAR(2);
	DEFINE v_sC_sector		CHAR(2);
	DEFINE v_sA_ccmayor		CHAR(4);
	DEFINE v_sA_ccsub		CHAR(2);
	DEFINE v_sA_ccsubsub	CHAR(2);
	DEFINE v_sA_ccsssub		CHAR(2);
	DEFINE v_sA_ccssssub	CHAR(2);
	DEFINE v_sA_sector		CHAR(2);
	-----------------------------------------------------------
	--SET DEBUG FILE TO "/tmp/prisma/sopbtenercuentascontables.out"; 
	--TRACE ON;
    -----------------------------------------------------------
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET v_sCodRet = iSqlErr;
				RETURN v_sCodRet, '', '', '', '', '', '', '', '', '', '', '', '';
			END IF;
		END EXCEPTION;
	
		LET v_sCodRet = '00001';
		
		IF NVL(p_sEmpresa, '') = '' OR NVL(p_sTransaccion, '') = '' OR NVL(p_sSistema, '') = '' THEN			
			RETURN v_sCodRet, '', '', '', '', '', '', '', '', '', '', '', '';
		END IF;	
		
		LET v_sCodRet = '00000';
				
		SELECT c_ccmayor, c_ccsub, c_ccsubsub, c_ccsssub, c_ccssssub, c_sector, 
		a_ccmayor, a_ccsub, a_ccsubsub, a_ccsssub, a_ccssssub, a_sector
		INTO v_sC_ccmayor, v_sC_ccsub, v_sC_ccsubsub, v_sC_ccsssub, v_sC_ccssssub, v_sC_sector, 
		v_sA_ccmayor, v_sA_ccsub, v_sA_ccsubsub, v_sA_ccsssub, v_sA_ccssssub, v_sA_sector
		FROM si_prodtran p WHERE p.empresa = p_sEmpresa AND p.transaccion = p_sTransaccion AND p.sistema = p_sSistema
		AND secuencia = p_sSecuencia;
			
		RETURN v_sCodRet, v_sC_ccmayor, v_sC_ccsub, v_sC_ccsubsub, v_sC_ccsssub, v_sC_ccssssub, v_sC_sector, 
		v_sA_ccmayor, v_sA_ccsub, v_sA_ccsubsub, v_sA_ccsssub, v_sA_ccssssub, v_sA_sector;		
		
	END
END PROCEDURE
DOCUMENT
'CREADO:      	Erick Zamora.',
'FECHA:       	7 de abril de 2010.',
'DESCRIPCIÓN: 	Obtiene las cuentas contables relacionadas a un sistema y un numero de transaccion.',
'CASO DE USO: 	Caso de uso asociado PCU-bdinteg\CU-0142-ObtenerCuentasContables-SPL.',
'MODIFICADO:	Fabiola Corrales Tapia (FCT) Se modifica para agregar la secuencia de la cuenta contable',
'Retorno: 		00000 Consulta Exitosa.',
'				00001 Error de parámetros.';

CREATE PROCEDURE "informix".sp_detalle_boletos_pba (pClaveSort CHAR(5),
                                                pFechaActual DATE)

RETURNING CHAR (5) AS Codigo, CHAR(5) AS Clave_Sorteo, CHAR (80) AS Mensaje;

--- DECLARACION DE VARIABLES

    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vCodret          CHAR(5);
    DEFINE vCveSorteo       CHAR(5);
    DEFINE vMensaje         CHAR(80);

    DEFINE vF_Proceso       DATE;
    DEFINE vEmpresa         CHAR(3);
    DEFINE vCve_Sorteo      CHAR(5);
    DEFINE vF_ini           DATE;
    DEFINE vF_Fin           DATE;

    DEFINE vNumcte          CHAR(10);
	  DEFINE iNumcte          INTEGER;

    DEFINE vCve_Sort        CHAR(5);
    DEFINE vBoleto_ini      INT8;
    DEFINE vBoleto_Fin      INT8;
    DEFINE vF_registro      DATETIME YEAR TO SECOND;
    DEFINE vNumCliente      CHAR(10);
    DEFINE vEstado          INTEGER;
    DEFINE vSucursal        CHAR(4);
    DEFINE vArea            CHAR(1);
    DEFINE vCaja            INTEGER;
    DEFINE vTipomov         CHAR(10);
    DEFINE vFoliosuc        CHAR(16);
    DEFINE vImporte         MONEY;
    DEFINE vTel1            CHAR(10);
    DEFINE vTel2            CHAR(13);
    DEFINE vNombre          CHAR(45);
    DEFINE vCiudad          CHAR(20);
    DEFINE vDomicilio       CHAR(50);
    DEFINE vFecha           DATE;
    DEFINE vOrigen          CHAR(10);
    DEFINE vSecuencia       INTEGER;
    DEFINE vLimite          INTEGER;
    DEFINE vContador        INTEGER;
    DEFINE vContSecuencia   INTEGER;

    DEFINE cCodRet          CHAR(3);
    DEFINE v_Valor          CHAR(5);
	  --DEFINE vrowid       	  INTEGER;
	  DEFINE vCuentaBoletos   INTEGER;
	  DEFINE vCuentaEmpleados INTEGER;


--- INICIALIZACION DE VARIABLES

    LET sql_err         = 0;
    LET isam_err        = 0;
    LET vCodret         = '00000';
    LET vCveSorteo      = pClaveSort;
    LET vMensaje        = 'El proceso concluyó exitosamente';

    LET vF_Proceso      = '';
    LET vEmpresa        = '001';
    LET vCve_Sorteo     = '0';
    LET vF_ini          = '';
    LET vF_Fin          = '';

    LET vNumcte         = '';

    LET vCve_Sort       = '';
    LET vBoleto_ini     = '';
    LET vBoleto_Fin     = '';
    LET vF_registro     = '';
    LET vNumCliente     = '';
    LET vEstado         = '';
    LET vSucursal       = '';
    LET vArea           = '';
    LET vCaja           = '';
    LET vTipomov        = '';
    LET vFoliosuc       = '';
    LET vImporte        = 0.00;
    LET vTel1           = '';
    LET vTel2           = '';
    LET vNombre         = '';
    LET vCiudad         = '';
    LET vDomicilio      = '';
    LET vFecha          = '';
    LET vOrigen         = '';
    LET vSecuencia      = '';
    LET vLimite         = 0;
    LET vContador       = 0;
    LET vContSecuencia  = 1;

    LET cCodRet          = '';
    LET v_Valor          = '';
	  --LET vrowid      	   = 0;
	  LET iNumcte      	   = 0;
	  LET vCuentaBoletos   = 0;
	  LET vCuentaEmpleados = 0;



     --****************************************************************
     -- Creado por Raúl Ramírez    01/Septiembre/2010
     -- Proceso para traducir rangos de boletos a un detalle de boletos
     --****************************************************************


BEGIN

    ON EXCEPTION SET sql_err

        IF sql_err <> 0  THEN
            LET vCodret   = sql_err;
            LET vCodret   = '00045';
            LET vMensaje  = 'ERROR EN LA EJECUCION';
            RETURN vCodret, vCveSorteo, vMensaje;        -- Termina proceso del SP
        END IF;
    END EXCEPTION;

        --SET DEBUG FILE TO "/ids10_uc9/raul/sorteo/sp_detalle_boletos.out";
        --TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    LET vF_Proceso = pFechaActual -1;

	SELECT {+INDEX(si_param ix_si_param)} valor
	INTO v_Valor
	FROM bdinteg:si_param
	WHERE empresa = vEmpresa
	AND cod_param = 118;

	SELECT {+INDEX (si_sorteo idx_si_sorteo2)} cve_sorteo, f_ini, f_fin
	INTO vCve_Sorteo, vF_ini, vF_Fin
	FROM bdinteg:si_sorteo
	WHERE cve_sorteo = v_Valor;


	IF (v_Valor IS NULL OR v_Valor = '') OR -- Valida clave sorteo vigente
	   (v_Valor <> pClaveSort) THEN
		 LET vCodret = '00040';
		 LET vMensaje = 'NO EXISTE SORTEO';
			RETURN vCodret, vCveSorteo, vMensaje;    -- Termina proceso del SP
	ELSE
		IF (vF_ini IS NULL OR vF_ini = '') OR      -- Valida fecha sorteo vigente
		   (vF_Fin IS NULL OR vF_Fin = '') OR
		   (vF_Proceso NOT BETWEEN vF_ini AND vF_Fin) THEN
			  LET vCodret = '00042';
			  LET vMensaje = 'SORTEO NO ESTA VIGENTE?';
			RETURN vCodret, vCveSorteo, vMensaje;    -- Termina proceso del SP
		END IF;
	END IF;

	-- BGM 11-Nov-2010: Se agrega depuración de tabla si_boleto_temp
	TRUNCATE si_boleto_temp;
	
	EXECUTE PROCEDURE "informix".sp_movtos_reversados ('001')
			INTO cCodRet;
	
    FOREACH

		---SELECT {+INDEX (si_movreversados idx_si_movrever)} empresa, fecha_mov, folio_suc
		SELECT {+FULL} empresa, fecha_mov, folio_suc
		INTO vEmpresa, vFecha, vFoliosuc
		FROM bdinteg:si_movreversados
		WHERE empresa = vEmpresa
		AND folio_suc <> ''
		
		IF EXISTS (SELECT {INDEX (bdinteg:si_boleto idx_si_boleto)} foliosuc 
		           FROM bdinteg:si_boleto 
			         WHERE cve_sorteo = vCve_Sorteo
               AND foliosuc = vFoliosuc
               AND fecha = vFecha) THEN
			
				UPDATE {+INDEX (si_boleto_hist idx_si_boleto_hist2)} bdinteg:si_boleto_hist
				SET estado = '101'
				WHERE cve_sorteo = vCveSorteo
				AND   foliosuc = vFoliosuc
				AND   fecha = vFecha;

				--DELETE {+INDEX (si_boleto idx_si_boleto)} FROM bdinteg:si_boleto
				--WHERE cve_sorteo = vCveSorteo
				--AND   foliosuc = vFoliosuc
				--AND   fecha = vFecha;
		END IF;
		
	END FOREACH;
	
	SELECT {+FULL} COUNT(*) into vCuentaBoletos FROM si_boleto;
	SELECT {+FULL} COUNT(*) into vCuentaEmpleados FROM si_syssorteo_emp;

	IF vCuentaBoletos <= vCuentaEmpleados THEN
	
		FOREACH
		
			SELECT {+FULL} numcte
			INTO iNumcte
			FROM bdinteg:si_boleto
			
			IF EXISTS (SELECT {+INDEX (si_syssorteo_emp idx_si_syssorteo_emp)} numcte
					FROM si_syssorteo_emp
					WHERE tipo IN (2 , 4) 
                                        AND status = 'A'
                                        AND numcte = iNumcte) THEN
					
					UPDATE {+INDEX (si_boleto_hist idx_si_boleto_hist4)} si_boleto_hist
					SET estado = '101'
					---WHERE numcte::INT = iNumcte;
					WHERE numcte = iNumcte;
			END IF;
		
		END FOREACH;
		
	ELIF vCuentaBoletos > vCuentaEmpleados THEN
	
		FOREACH
	
			SELECT {+FULL} numcte
			INTO iNumcte  
			FROM si_syssorteo_emp
			
			IF EXISTS (SELECT {INDEX (bdinteg:si_boleto idx_idx_si_boleto6)} numcte 
					FROM bdinteg:si_boleto 
					WHERE numcte::INT = iNumcte) THEN
				
					UPDATE {+INDEX (si_boleto_hist idx_si_boleto_hist4)} bdinteg:si_boleto_hist
					SET estado = '101'
					---WHERE numcte::INT = iNumcte;
					WHERE numcte = iNumcte;
			END IF;
				
		END FOREACH;
		
	END IF;
	
	FOREACH cursor_inserta WITH HOLD FOR
					
			SELECT {+INDEX (si_boleto_hist idx_si_boleto_hist2)}
					cve_sorteo, boleto_ini, boleto_fin, f_registro, numcte, estado, sucursal, area, caja, tipomov,
					foliosuc, importe, telefono1, telefono2, nombre, ciudad, domicilio, fecha, origen, secuencia
			INTO  vCve_Sort, vBoleto_Ini, vBoleto_Fin, vF_registro, vNumCliente, vEstado, vSucursal, vArea, vCaja, vTipomov,
              vFoliosuc, vImporte, vTel1, vTel2, vNombre, vCiudad, vDomicilio, vFecha, vOrigen, vSecuencia
			FROM bdinteg:si_boleto_hist
			WHERE cve_sorteo =  vCveSorteo
			AND foliosuc <> ''
			AND fecha = vF_Proceso
			AND estado = 2
			
			LET vLimite = vBoleto_Fin;
            BEGIN WORK;
                FOR vContador = vBoleto_Ini TO vLimite
					INSERT INTO si_boleto_temp(cve_sorteo, boleto, f_registro, numcte, estado, sucursal, area, caja, tipomov,
                                foliosuc, importe, telefono1, telefono2, nombre, ciudad, domicilio, fecha, origen, secuencia)
					VALUES (vCve_Sort, vContador, vF_registro, vNumCliente, vEstado, vSucursal, vArea, vCaja, vTipomov,
                            vFoliosuc, vImporte, vTel1, vTel2, vNombre, vCiudad, vDomicilio, vFecha, vOrigen, vContSecuencia);
					LET vContSecuencia = vContSecuencia + 1;
				END FOR

				LET vContSecuencia = 1;
            COMMIT WORK;                           
               
    END FOREACH;

  -- BGM 11-Nov-2010: Se agrega depuración de tabla si_boleto;
	TRUNCATE si_boleto;
	TRUNCATE si_movreversados;
		  
END
    RETURN vCodret, vCveSorteo, vMensaje;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_manejaclientecomparacionlinea (pTipo SMALLINT, pNumcte INTEGER, pSecuencia SMALLINT, pReferencia INTEGER, pComparacion SMALLINT)
RETURNING INTEGER;

DEFINE vCodret    CHAR(1);
DEFINE vKeyx      INTEGER;

BEGIN
    LET vCodret = '0';

set isolation to dirty read;
set lock mode to wait 3;

    IF pTipo = '1' THEN
        IF EXISTS (SELECT {+INDEX(si_clientecomparacionbanco idx_si_clientecomparacionbanco2)} numcte from si_clientecomparacionbanco where tipo = pComparacion AND numcte = pNumcte AND secuencia = pSecuencia AND referencia = pReferencia) THEN
            LET vCodret = '1';
        ELSE
            INSERT INTO si_clientecomparacionbanco
                (tipo, numcte, secuencia, status, referencia, fechamov, secuenciareferencia)
            VALUES
                (pComparacion, pNumcte, pSecuencia, "A", pReferencia, CURRENT, 0);
        END IF;
    END IF;

    IF pTipo = '2' THEN
        IF EXISTS (SELECT {+INDEX(si_clientecomparacionbanconomatch idx_si_clientecomparacionbanconomatch)} numcte from si_clientecomparacionbanconomatch where tipo = pComparacion AND numcte = pNumcte AND secuencia = pSecuencia AND referencia = pReferencia) THEN
            LET vCodret = '1';
        ELSE
            INSERT INTO si_clientecomparacionbanconomatch
                (tipo, numcte, secuencia, status, referencia, fechamov, secuenciareferencia)
            VALUES
                (pComparacion, pNumcte, pSecuencia, "A", pReferencia, CURRENT, 0);
        END IF;
    END IF;

    RETURN vCodret;
END;
END PROCEDURE
DOCUMENT
"Consulta de Huella de cliente ",
"AUTOR: Jesus Montoya",
"FECHA: 25/Enero/2008",
"BD   : bdinteg",
"VER  : 1.1";

CREATE PROCEDURE "informix".sp_dskrga_direcciones( )
RETURNING CHAR(5), CHAR(5);

    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE vcomienza1   SMALLINT;  
    DEFINE vcomienza2   SMALLINT;  
    DEFINE vcomienza3   SMALLINT;  
    DEFINE vcontador1   INTEGER;
    DEFINE vcontador2   INTEGER;
    
    DEFINE vctemin          CHAR(20);
    DEFINE vctemax          CHAR(20);
    DEFINE vnumcte          CHAR(20);
    DEFINE vsecuencia_max   SMALLINT;
    DEFINE vsql             CHAR(300);
    
    LET vcodret1    = '000';
    LET vcodret2    = '000';
    LET sql_err	    = 0;
    LET isam_err    = 0;
    LET vcomienza1  = -1;
    LET vcomienza2  = -1;
    LET vcomienza3  = -1;
    LET vcontador1  = 0;
    LET vcontador2  = 0;
    
    LET vctemin        = '';
    LET vctemax        = '';
    LET vnumcte        = '';
    LET vsecuencia_max = 0;
    LET vsql           = '';
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_dskrga_direcciones.err";
        --- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            RETURN vcodret1, vcodret2;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_dskrga_direcciones.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  
                WHERE partnum > 0 AND tabname = 'ultimas_direcciones') THEN
        DROP TABLE "informix".ultimas_direcciones;        
    END IF;
    
    CREATE RAW TABLE "informix".ultimas_direcciones(
        numcte               char(20),
        secuencia            integer,
        tipo_dir             char(1),
        calle                char(40),
        colonia              char(60),
        entre_calles         char(40),
        pais                 char(3),
        estado               char(2),
        ciudad               char(3),
        municipio            char(5),
        cod_postal           char(5),
        apart_postal         char(11),
        tipo_telef1          char(1),
        telefono1            char(13),
        tipo_telef2          char(1),
        telefono2            char(13),
        tipo_telef3          char(1),
        telefono3            char(13),
        extension            char(5),
        estado_inegi         char(2),
        municipio_inegi      char(3),
        localidad_inegi      char(4),
        numerociudad         smallint,
        numeroextcalle       char(10),
        numerointcalle       char(10),
        departamento         char(6),
        numerocalle          integer,
        numerocolonia        integer,
        puntocardinal        char(1),
        unidadhabitac        char(1),
        manzana              smallint,
        otros                smallint,
        andador              smallint,
        etapa                smallint,
        lote                 smallint,
        edificio             smallint,
        entrada              smallint,
        observaciones        char(80),
        user_insert          char(8),
        fecha_insert         date,
        ind_cofeteltel1      char(1),
        ind_cofeteltel2      char(1),
        ind_cofeteltel3      char(1)
    ) EXTENT SIZE 5815430 NEXT SIZE 581543 LOCK MODE ROW;
    UPDATE STATISTICS MEDIUM FOR TABLE ultimas_direcciones;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM si_direcciones
     WHERE numcte > '000000000';
    
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO vnumcte
          FROM si_direcciones
         WHERE numcte BETWEEN vctemin AND vctemax
           AND tipo_dir = '1'
          
        IF vcomienza1 = -1 THEN
            LET vcomienza1 = 0;
            BEGIN WORK;
        END IF;
        
        SELECT MAX(secuencia)
          INTO vsecuencia_max
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND tipo_dir = '1';
           
        INSERT INTO ultimas_direcciones
        SELECT *
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND secuencia = vsecuencia_max
           AND tipo_dir = '1';
           
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 = 7500 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vcontador2 >= 0 THEN
        LET vcontador2 = 0;
        COMMIT WORK;
    END IF;
    
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO vnumcte
          FROM si_direcciones
         WHERE numcte BETWEEN vctemin AND vctemax
           AND tipo_dir = '2'
          
        IF vcomienza2 = -1 THEN
            LET vcomienza2 = 0;
            BEGIN WORK;
        END IF;
        
        SELECT MAX(secuencia)
          INTO vsecuencia_max
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND tipo_dir = '2';
           
        INSERT INTO ultimas_direcciones
        SELECT *
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND secuencia = vsecuencia_max
           AND tipo_dir = '2';
           
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 = 7500 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vcontador2 >= 0 THEN
        LET vcontador2 = 0;
        COMMIT WORK;
    END IF;
    
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO vnumcte
          FROM si_direcciones
         WHERE numcte BETWEEN vctemin AND vctemax
           AND tipo_dir = '3'
          
        IF vcomienza3 = -1 THEN
            LET vcomienza3 = 0;
            BEGIN WORK;
        END IF;
        
        SELECT MAX(secuencia)
          INTO vsecuencia_max
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND tipo_dir = '3';
           
        INSERT INTO ultimas_direcciones
        SELECT *
          FROM si_direcciones
         WHERE numcte = vnumcte
           AND secuencia = vsecuencia_max
           AND tipo_dir = '3';
           
        LET vcontador1 = vcontador1 + 1;
        LET vcontador2 = vcontador2 + 1;
        
        IF vcontador2 = 7500 THEN
            LET vcontador2 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
    END FOREACH;
    
    IF vcontador2 >= 0 THEN
        LET vcontador2 = 0;
        COMMIT WORK;
    END IF;
              
    -- // DESCARGA ULTIMAS DIRECCIONES
    LET vsql = '';
    LET vsql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO /resplogifx/conciliachq/ultimas_direcciones.unl '||
               ' SELECT * FROM ultimas_direcciones;" > /resplogifx/conciliachq/dskrga_direcciones.sql';
    SYSTEM vsql;
    
    LET vsql = '';
    --- LET vsql = "dbaccess bdicheq /resplogifx/conciliachq/dskrga_direcciones.sql"; 
    LET vsql = "/ifxsif01/bin/dbaccess bdicheq /resplogifx/conciliachq/dskrga_direcciones.sql"; 
    SYSTEM vsql;
    
    END;

    RETURN vcodret1, vcodret2;

END PROCEDURE;

