                      ind_cofeteltel2  = vind_cofeteltel2,
                      ind_cofeteltel3  = vind_cofeteltel3
                WHERE numcte = vnumcte
                  AND tipo_dir = vtipo_dir;
        END IF;   
        
        LET vcontador = vcontador + 1;
        
        COMMIT WORK;
        BEGIN WORK;
        
        LET vnumcte = '';
        LET vtipo_dir = '';
        LET vsecuencia_tmp = 0;
        LET vsecuencia = 0;
        LET vcalle = '';
        LET vcolonia = '';
        LET ventre_calles = '';
