CREATE PROCEDURE "informix".sp_obtenerdigitoverificadorrfc(pEmpresa CHAR(3),rfc VARCHAR(12))
RETURNING CHAR(6)       AS retorno,
          VARCHAR(100)  AS mensaje,
          CHAR(1)       AS digito;

-- Variables de proceso
DEFINE cRfc             VARCHAR(12);
DEFINE cLetra           CHAR(1);
DEFINE iNom_numerico    INTEGER; 
DEFINE iTotal           INTEGER;
DEFINE I                INTEGER;
DEFINE cDigito          CHAR(1);
DEFINE iValor           INTEGER;


-- Control de errores
DEFINE iSqlErr      INTEGER;
DEFINE iIsamErr     INTEGER;
DEFINE vErrorInfo   VARCHAR(100);
DEFINE vCodRet      CHAR(6);
DEFINE cMensaje     VARCHAR(100);


-- Variables de proceso
LET cRfc            = "";
LET cLetra          = "";
LET iNom_numerico   = 0;
LET iTotal          = 0;
LET I               = 0;
LET cDigito         = "";
LET iValor          = 0;

-- Control de errores
LET iSqlErr         = 0;
LET iIsamErr        = 0;
LET vErrorInfo      = "";
LET vCodRet         = "000000";
LET cMensaje        = "El proceso se realizó con éxito.";


BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
   IF iSqlErr != 0 THEN
      LET vCodRet= iSqlErr;
      LET cMensaje= vErrorInfo;
      RETURN vCodRet, cMensaje,cDigito;
   END IF;
END EXCEPTION;

 -- SET DEBUG FILE TO "/home/sysifx/viridiana/sp_obtenerdigitoverificadorrfc.out";
 -- TRACE ON;

IF NVL(pEmpresa,"") = "" OR NVL(rfc,"") = "" THEN
   LET vCodRet = "000001";
   LET cMensaje = "Los datos no se proporcionaron correctamente.";
   RETURN vCodRet, cMensaje,cDigito;
END IF;

LET cRfc = TRIM(rfc);


FOR I = 1 TO LENGTH(cRfc)
    LET cLetra = SUBSTR(cRfc,I,1);

    SELECT verificador
      INTO iValor
      FROM bdinteg:si_digito_valor_rfc
     WHERE letra = cLetra
       AND empresa = pEmpresa;

       IF NVL(iValor,"") = "" THEN
           IF (cLetra BETWEEN "0" AND "9") THEN
               LET iValor = cLetra;
           ELIF cLetra = "" THEN
               LET iValor = 24;
           ELIF cLetra = " " THEN
               LET iValor = 37;
           ELSE
               LET iValor = 0;
           END IF;

       END IF;
      
       LET iNom_numerico = iNom_numerico + (iValor * (14-(i)));
END FOR

LET iTotal = MOD(iNom_numerico,11);

IF iTotal = 0 THEN
    LET cDigito = "0";
ELSE
    LET iNom_numerico = 11 - iTotal;

    IF iNom_numerico = 10 THEN
       LET cDigito = "A";
    ELSE
       LET cDigito = iNom_numerico;
    END IF;
END IF;

RETURN vCodRet, cMensaje,cDigito;
END;
END PROCEDURE
DOCUMENT
"Descripción: Se realiza procedimiento para realizar el cálculo de dígito ",
"verificador para un RFC",
"BD: bdinteg",
"Fecha: 06-Abril-2010",
"Autor: Viridiana Osobampo Aguilar";

CREATE PROCEDURE "informix".sp_obtenerhomoclaverfc(pEmpresa CHAR(3),pNombre VARCHAR(104))
RETURNING CHAR(6)       AS retorno,
          VARCHAR(100)  AS mensaje,
          CHAR(2)       AS homoclave;

-- Variables de proceso
DEFINE cHomoclave       CHAR(2);
DEFINE cNom_numerico    VARCHAR(208);
DEFINE I                INTEGER;
DEFINE iSuma            INTEGER;
DEFINE iTotal_1         INTEGER;
DEFINE iTotal_2         INTEGER;
DEFINE cDigito1         CHAR(1);
DEFINE cDigito2         CHAR(1);
DEFINE cCaracter        CHAR(1);
DEFINE cValor           CHAR(2);
DEFINE iValor1          INTEGER;
DEFINE iValor2          INTEGER;
DEFINE iTotal           INTEGER;
DEFINE cNombre          VARCHAR(104);

-- Control de errores
DEFINE iSqlErr      INTEGER;
DEFINE iIsamErr     INTEGER;
DEFINE vErrorInfo   VARCHAR(100);
DEFINE vCodRet      CHAR(6);
DEFINE cMensaje     VARCHAR(100);

-- Variables de proceso
LET cHomoclave      = "";
LET cNom_numerico   = "0";
LET I               = 0;
LET iSuma           = 0;
LET iTotal_1        = 0;
LET iTotal_2        = 0;
LET cDigito1        = "";
LET cDigito2        = "";
LET cCaracter       = "";
LET cValor          = "";
LET iValor1         = 0;
LET iValor2         = 0;
LET iTotal          = 0;
LET cNombre         = "";

-- Control de errores
LET iSqlErr         = 0;
LET iIsamErr        = 0;
LET vErrorInfo      = "";
LET vCodRet         = "000000";
LET cMensaje        = "El proceso se realizó con éxito.";

BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
   IF iSqlErr != 0 THEN
      LET vCodRet= iSqlErr;
      LET cMensaje= vErrorInfo;
      RETURN vCodRet, cMensaje,cHomoclave;
   END IF;
END EXCEPTION;

  --SET DEBUG FILE TO "/home/sysifx/viridiana/sp_obtenerhomoclaverfc.out";
  --TRACE ON;

   IF NVL(pEmpresa,"") = "" OR NVL(pNombre,"") = "" THEN
       LET vCodRet = "000001";
       LET cMensaje = "Los datos no se proporcionaron correctamente.";
       RETURN vCodRet, cMensaje,cHomoclave;
   END IF;

LET cNombre = TRIM(UPPER(pNombre));

    FOR I = 1 TO LENGTH(cNombre)
       LET cCaracter = SUBSTR(cNombre,I,1);
       
       SELECT homoclave
         INTO cValor
         FROM bdinteg:si_digito_valor_rfc
        WHERE letra = cCaracter
          AND empresa = pEmpresa;
          
       IF NVL(cValor,"") <> "" THEN
           LET cNom_numerico = TRIM(cNom_numerico) || TRIM(cValor);
       ELSE
           IF cCaracter IN ("Ñ","ñ","&") THEN
               LET cNom_numerico = cNom_numerico || "10";
           ELIF cCaracter = " " THEN
               LET cNom_numerico = cNom_numerico || "00";
           ELIF (cCaracter BETWEEN "0" AND "9") THEN
               LET cNom_numerico = cNom_numerico || "0" || cCaracter;
           END IF;
       END IF;
       
    END FOR;
   
   FOR I = 1 TO LENGTH(cNom_numerico)-1
       LET iValor1 = CAST(SUBSTR(cNom_numerico,I,2) AS INTEGER);
       LET iValor2 = CAST(SUBSTR(cNom_numerico,(I+1),1) AS INTEGER);
       LET iTotal = iTotal + (iValor1 * iValor2);
   END FOR;

   LET iTotal_1 = MOD(iTotal,1000);
   LET iTotal_2 = MOD(iTotal_1,34);
   LET iTotal_1 = (iTotal_1 - iTotal_2) / 34 ;

       SELECT homoclave
         INTO cDigito1
         FROM si_homoclave_rfc
        WHERE id_valor = (iTotal_1)
          AND empresa = pEmpresa;

       SELECT homoclave
         INTO cDigito2
         FROM si_homoclave_rfc
        WHERE id_valor = (iTotal_2)
          AND empresa = pEmpresa; 

       IF NVL(cDigito1,"") = "" OR  NVL(cDigito2,"") = "" THEN
           LET vCodRet = "000002";
           LET cMensaje = "Error al obtener el dígito de homoclave.";
           RETURN vCodRet, cMensaje,cHomoclave;
       END IF;

       LET cHomoclave = TRIM(cHomoclave) || TRIM(cDigito1) || TRIM(cDigito2);


RETURN vCodRet, cMensaje,cHomoclave;

END;
END PROCEDURE
DOCUMENT
"Descripción: Se crea procedimiento para generar los dígitos de homoclave para el RFC de un cliente",
"BD: bdinteg",
"Fecha: 07-Abril-2010",
"Autor: Viridiana Osobampo Aguilar";

