CREATE PROCEDURE "informix".sp_consultaprodactivossucur(p_sEmpresa CHAR(3), p_sSucursal CHAR(4))
    RETURNING       CHAR(6) AS retorno,
                    CHAR(5) AS producto;

    DEFINE iSqlErr          INTEGER;
    DEFINE cCodRet    		CHAR(5);
    DEFINE cNumProd         CHAR(4);
    

    LET cCodRet = '00000';
    LET cNumProd = "0000";

    BEGIN
        ON EXCEPTION SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET cCodRet = iSqlErr;
					RETURN cCodRet, cNumProd;
                END IF;
        END EXCEPTION;

		--set debug file to "/tmp/sp_consultaprodactivossucur.out";
		--trace on;
        
        IF p_sSucursal = "" THEN
            LET cCodRet = "00001";
        END IF;

        --DEBE PROPORCIONARSE LA EMPRESA
        FOREACH
            SELECT num_producto INTO cNumProd FROM bdinteg:si_prod_sucursal WHERE empresa = p_sEmpresa AND sucursal = p_sSucursal
            
            RETURN cCodRet, cNumProd WITH RESUME;
        END FOREACH
        
        IF cCodRet <> "00000" THEN
            RETURN cCodRet, cNumProd;
        END IF;
        
    END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaproductos(pEmpresa CHAR(3), pTipo CHAR(1), pPlaza CHAR(3))

RETURNING CHAR(5), -- Código de retorno 
		  CHAR(4), --Código de Producto
          CHAR(60),-- Descripción del producto 
		  CHAR(2); --Sistema

-- Declaración de variables
DEFINE cCodRet					CHAR(5);
DEFINE iSqlErr          		INTEGER;
DEFINE cProducto			    CHAR(60);
DEFINE cDescripcionProducto     CHAR(60);
DEFINE cSistema					CHAR(2);

-- Asignación variables
LET cCodRet        			= "00000";
LET iSqlErr          		= 0;
LET cProducto             	= "";
LET cDescripcionProducto	= "";
LET cSistema 				= "";

BEGIN

	ON EXCEPTION SET iSqlErr
		LET cCodRet = iSqlErr;
		RETURN cCodRet, cProducto, cDescripcionProducto, cSistema;
	END EXCEPTION;
   
	---SET DEBUG FILE TO "/tmp/sp_consultaproductos.out";
	---TRACE ON;
	
	IF pTipo = "1" THEN --Consulta por Region
		IF pPlaza IS NOT NULL OR pPlaza <> '' THEN
			FOREACH
				SELECT DISTINCT(Prod.producto), Prod.nombre, tram.sistema
				INTO cProducto, cDescripcionProducto, cSistema
				FROM bdicheq:sc_producto Prod, bdisolic:ss_tramite_productos_clasif tram,
				     bdinteg:si_sucursales sc, bdinteg:si_plazas sp
				WHERE Prod.empresa = pEmpresa
				AND Prod.empresa = tram.empresa
				AND Prod.producto = tram.prod_ofrecer
				AND sc.plaza=sp.plaza
				AND sc.plaza= pPlaza
				AND sc.tpo_sucursal='S'
				UNION
				SELECT DISTINCT(Def.num_producto), Def.nombre_prod, tram.sistema
				FROM bdicred:sd_definicion Def, bdisolic:ss_tramite_productos_clasif tram,
				     bdinteg:si_sucursales sc, bdinteg:si_plazas sp
				WHERE Def.empresa = pEmpresa
				AND Def.empresa = tram.empresa
				AND Def.num_producto = tram.prod_ofrecer
				AND sc.plaza=sp.plaza
				AND sc.plaza= pPlaza
				AND sc.tpo_sucursal='S'
				UNION
				SELECT DISTINCT(inst.cod_instrum), inst.nombre, tram.sistema 
				FROM bdinvers:sv_instrum inst, bdisolic:ss_tramite_productos_clasif tram,
				     bdinteg:si_sucursales sc, bdinteg:si_plazas sp
				WHERE inst.empresa = pEmpresa
				AND inst.empresa = tram.empresa
				AND inst.cod_instrum = tram.prod_ofrecer
				AND sc.plaza=sp.plaza
				AND sc.plaza= pPlaza
				AND sc.tpo_sucursal='S'

				RETURN cCodRet, cProducto, cDescripcionProducto, cSistema WITH resume;
			END FOREACH;
		ELSE
			LET cCodRet = '00001';
		END IF;
	
	ELIF pTipo = "2" THEN --Consulta por Sucursal
		FOREACH
			SELECT DISTINCT(Prod.producto), Prod.nombre, tram.sistema
			INTO cProducto, cDescripcionProducto, cSistema
			FROM bdicheq:sc_producto Prod, bdisolic:ss_tramite_productos_clasif tram
			WHERE Prod.empresa = pEmpresa
			AND Prod.empresa = tram.empresa
			AND Prod.producto = tram.prod_ofrecer
			UNION
			SELECT DISTINCT(Def.num_producto), Def.nombre_prod, tram.sistema
			FROM bdicred:sd_definicion Def, bdisolic:ss_tramite_productos_clasif tram
			WHERE Def.empresa = pEmpresa
			AND Def.empresa = tram.empresa
			AND Def.num_producto = tram.prod_ofrecer
			UNION
			SELECT DISTINCT(inst.cod_instrum), inst.nombre, tram.sistema 
			FROM bdinvers:sv_instrum inst, bdisolic:ss_tramite_productos_clasif tram
			WHERE inst.empresa = pEmpresa
			AND inst.empresa = tram.empresa
			AND inst.cod_instrum = tram.prod_ofrecer
			
			RETURN cCodRet, cProducto, cDescripcionProducto, cSistema WITH resume;
		END FOREACH;
	END IF;

   IF cCodRet <> '00000' THEN
       RETURN cCodRet, cProducto, cDescripcionProducto, cSistema;
   END IF;
   
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarcatplazas(pEmpresa CHAR(3), pPlaza CHAR(3))
    RETURNING   CHAR(5) AS retorno,
				CHAR(3) AS empresa,
				CHAR(3) AS plaza,
				CHAR(40) AS nombre,
				CHAR(3) AS regional;

    DEFINE iSqlErr          INTEGER;
    DEFINE cCodRet    		CHAR(5);
    DEFINE cEmpresa 	    CHAR(3);
    DEFINE cPlaza	        CHAR(3);
    DEFINE cNombre          CHAR(40);
    DEFINE cRegional        CHAR(3);

    LET cCodRet = '00000';
	LET cEmpresa = '';
	LET cPlaza = '';
	LET cNombre = '';
	LET cRegional = '';

    BEGIN
        ON EXCEPTION SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET cCodRet = iSqlErr;
					RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
                END IF;
        END EXCEPTION;

		--SET DEBUG FILE TO "/tmp/sp_consultarcatplazas.out";
		--TRACE ON;

        IF pPlaza = '' THEN
            LET pPlaza = NULL;
        END IF;

        FOREACH
            SELECT DISTINCT sSuc.empresa, sSuc.plaza, sPlas.nombre, sPlas.regional
            INTO cEmpresa, cPlaza, cNombre, cRegional
            FROM si_sucursales sSuc, si_plazas sPlas
            WHERE sSuc.plaza = NVL(pPlaza, sPlas.plaza)
            AND sSuc.tpo_sucursal = 'S'
            ORDER BY sPlas.nombre

			RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional WITH RESUME;
        END FOREACH;
    END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacuentacredito(pnumcuenta CHAR(12),pnumcliente CHAR(9),pnumtarjeta char(16),pfecini DATE,pfecfin DATE,ptipobusqueda smallint)
	RETURNING CHAR(5),CHAR(12),CHAR(9),CHAR(16),CHAR(40),CHAR(25),CHAR(25),CHAR(25),CHAR(25),char(30);

	--************************************
	--sp_consultacuentacredito
	--objetivo: Obtiene las cuentas de credito , ya sea por numcliente, por cuenta o por numtarjeta
	--Autor: Francisco Rodriguez Ibarra
	--Fecha: 30 Abril 2010
	--Modificacion: Se modifico SP para obtener correctament el status de la tarjeta.
	--Fecha:19-Mayo-2010
	--Autor: Francisco Rodriguez Ibarra
	--Modificó: Javier Chávez
	--Fecha: 01-junio-2010
	--Modificacion: se valida que sean tarjetas de credito con el bin
	--
	--Modificó: Ulises Rodríguez
	--Fecha: 01-junio-2010
	--Modificación: Se cambió la consulta del nombre del producto a la tabla sd_definicion, en lugar de sd_param
	--****************************************

	--Declaracion de Variables
	DEFINE vsCodRet 	CHAR(5);
	DEFINE vSqlErr		INTEGER;
	DEFINE vnumcuenta	CHAR(12);
	DEFINE vnumcliente  CHAR(9);
	DEFINE vnumtarjeta  CHAR(16);
	DEFINE vproducto   CHAR(11);
	DEFINE vnomproducto CHAR(40);
	DEFINE vquery		CHAR(50);
	DEFINE iCont		INTEGER;
	DEFINE vsecuencia   INTEGER;
	DEFINE vnombre1 CHAR(25);
	DEFINE vnombre2 CHAR(25);
	DEFINE vnombre3 CHAR(25);
	DEFINE vnombre4 CHAR(25);
	DEFINE vstatus   CHAR(30);
	DEFINE vTipo CHAR(1);
	
	
	--Asignacion de Valores a Variables
	LET vsCodRet = '00000';
	LET vSqlErr = 0;
	LET vnumcuenta="";
	LET vnumcliente="";
	LET vnumtarjeta="";
	LET vproducto="";
	LET vnomproducto="";
	LET vquery="";
	LET iCont=0;
	LET vnombre1 = "";
	LET vnombre2 = "";
	LET vnombre3 = "";
	LET vnombre4 = "";
	LET vsecuencia=0;
	LET vstatus="";
	LET vTipo = '';
	BEGIN
	
		ON EXCEPTION SET vSqlErr
	      IF vSqlErr <> 0 THEN
	            let vsCodRet = vSqlErr;
				--ROLLBACK WORK;
				
	            RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vnomproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus;
	      END IF;
		
		END EXCEPTION;
		
		SET ISOLATION DIRTY READ;
		
		--Busqueda por  numero de cuenta
		IF(ptipobusqueda = 1) THEN
			FOREACH
				select b.numcuenta as Num_credito,
						a.numtarjeta as Num_tarjeta,
						a.numcliente as Num_cliente,
						c.num_producto as Num_producto, d.nombre1, d.nombre2, d.apell_paterno, d.apell_materno,e.descstatustarjeta
				into vnumcuenta,vnumtarjeta,vnumcliente,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus
				from intercard:tarjeta a
				left outer join  intercard:tarjetacuenta b on (b.numtarjeta=a.numtarjeta)
				left outer join bdinteg:si_cliente d on (d.numcte=a.numcliente)
				left outer join bdicred:sd_maecred c on (c.num_credito=b.numcuenta)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
				where  b.numcuenta=trim(pnumcuenta)
				
				--obtener el nombre del producto
				select nombre_prod
				into vnomproducto
				from bdicred:sd_definicion 
				where num_producto=trim(vproducto);	
				
				SELECT creditodebito INTO vTipo FROM intercard:bines  where bin = substring(vnumtarjeta FROM 1 FOR 6);
				
				IF(vTipo = 'C') THEN
						LET iCont = iCont + 1;
						RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vnomproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus WITH RESUME;
				END IF;
			
			END FOREACH	
		END IF
		
		--Busqueda por numero de cliente
		IF (ptipobusqueda = 2) THEN
			FOREACH
				select b.numcuenta as Num_credito, 
					   a.numcliente as Num_cliente, 
					   a.numtarjeta as Num_tarjeta, 
					   c.num_producto as Num_producto, d.nombre1, d.nombre2, d.apell_paterno, d.apell_materno,e.descstatustarjeta
				into vnumcuenta,vnumcliente,vnumtarjeta,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus
				from intercard:tarjeta a
				left outer join  intercard:tarjetacuenta b on (a.numtarjeta = b.numtarjeta)
				left outer join bdicred:sd_maecred c on (b.numcuenta = c.num_credito)
				left outer join bdinteg:si_cliente d on (a.numcliente = d.numcte)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
				where  a.numcliente=trim(pnumcliente)
				
				--obtener el nombre del producto
				select nombre_prod
				into vnomproducto
				from bdicred:sd_definicion 
				where num_producto=trim(vproducto);								
				
				SELECT creditodebito INTO vTipo FROM intercard:bines  where bin = substring(vnumtarjeta FROM 1 FOR 6);
				
				IF(vTipo = 'C') THEN
						LET iCont = iCont + 1;
						RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vnomproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus WITH RESUME;
				END IF;
				
			
			END FOREACH	
			
		END IF
		
		--Busqueda  por numero de tarjeta
		IF (ptipobusqueda = 3) THEN
			FOREACH
				select a.numtarjeta as Num_tarjeta, 
						b.numcuenta as Num_credito, 
						a.numcliente as Num_cliente, 
					    c.num_producto as Num_producto, d.nombre1, d.nombre2, d.apell_paterno, d.apell_materno,
						e.descstatustarjeta
				into vnumtarjeta,vnumcuenta,vnumcliente,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus
				from intercard:tarjeta a 
				left outer join intercard:tarjetacuenta b on (a.numtarjeta = b.numtarjeta)
				left outer join bdinteg:si_cliente d on (d.numcte =a.numcliente)
				left outer join bdicred:sd_maecred c on (c.num_credito =b.numcuenta)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
				where  a.numtarjeta=trim(pnumtarjeta)
				
				--obtener el nombre del producto
				select nombre_prod
				into vnomproducto
				from bdicred:sd_definicion 
				where num_producto=trim(vproducto);	
								
				SELECT creditodebito INTO vTipo FROM intercard:bines  where bin = substring(vnumtarjeta FROM 1 FOR 6);
				
				IF(vTipo = 'C') THEN
						LET iCont = iCont + 1;
						RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vnomproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus WITH RESUME;
				END IF;
			
			END FOREACH	
			
		END IF
	
		IF ( iCont = 0 ) THEN
			LET vsCodRet = 101; --Cliente No tiene cuentas
			RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vnomproducto,vnombre1,vnombre2,vnombre3,vnombre4,vstatus ;
		END IF
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacuentadebito(pnumcuenta CHAR(12),pnumcliente CHAR(9),pnumtarjeta char(16),pfecini DATE,pfecfin DATE,ptipobusqueda smallint)
	RETURNING CHAR(5),CHAR(12),CHAR(9),CHAR(16),CHAR(40),CHAR(25),CHAR(25),CHAR(25),CHAR(25),INTEGER,CHAR(30);
	--************************************
	--sp_consultacuentadebito
	--objetivo: Obtiene las cuentas de debito , ya sea por numcliente, por cuenta o por numtarjeta
	--Autor: Francisco Rodriguez Ibarra
	--Fecha: 30 Abril 2010
	--****************************************
	--Declaracion de Variables
	DEFINE vsCodRet 	CHAR(5);
	DEFINE vSqlErr		INTEGER;
	DEFINE vnumcuenta	CHAR(12);
	DEFINE vnumcliente  CHAR(9);
	DEFINE vnumtarjeta  CHAR(16);
	DEFINE vproducto   CHAR(40);
	DEFINE vquery		CHAR(50);
	DEFINE iCont		INTEGER;
	DEFINE vsecuencia   INTEGER;
	DEFINE vnombre1 CHAR(25);
	DEFINE vnombre2 CHAR(25);
	DEFINE vnombre3 CHAR(25);
	DEFINE vnombre4 CHAR(25);
	DEFINE vstatus   CHAR(30);


	--Asignacion de Valores a Variables
	LET vsCodRet = '00000';
	LET vSqlErr = 0;
	LET vnumcuenta="";
	LET vnumcliente="";
	LET vnumtarjeta="";
	LET vproducto="";
	LET vquery="";
	LET iCont=0;
	LET vnombre1 = "";
	LET vnombre2 = "";
	LET vnombre3 = "";
	LET vnombre4 = "";
	LET vsecuencia=0;
	LET vstatus="";
	BEGIN

		ON EXCEPTION SET vSqlErr
	      IF vSqlErr <> 0 THEN
	            let vsCodRet = vSqlErr;
				--ROLLBACK WORK;

	            RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus;
	      END IF;

		END EXCEPTION;

		SET ISOLATION DIRTY READ;

		--Busqueda por  numero de cuenta
		IF(ptipobusqueda = 1) THEN
			FOREACH
				select b.cuenta, a.numcliente, a.numtarjeta, c.nombre as Producto,
						d.nombre1,d.nombre2, d.apell_paterno, d.apell_materno, b.secuencia,e.descstatustarjeta
						into vnumcuenta,vnumcliente,vnumtarjeta,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus
				from intercard:tarjeta a
				left outer join bdicheq:sc_tarjeta b on (a.numtarjeta = b.num_tarjeta)
				left outer join bdicheq:sc_producto c on (b.prodtarjeta = c.producto)
                left outer join bdinteg:si_cliente d on (a.numcliente = d.numcte)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
				where  b.cuenta=trim(pnumcuenta)

				LET iCont = iCont + 1;

				RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus WITH RESUME;

			END FOREACH
		END IF

		--Busqueda por numero de cliente
		IF (ptipobusqueda = 2) THEN
			FOREACH
				select  a.numcliente,b.cuenta, a.numtarjeta, c.nombre as Producto,
						d.nombre1,d.nombre2, d.apell_paterno, d.apell_materno, b.secuencia,e.descstatustarjeta
						into vnumcliente,vnumcuenta,vnumtarjeta,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus
				from intercard:tarjeta a
				left outer join bdicheq:sc_tarjeta b  on(a.numtarjeta= b.num_tarjeta)
				left outer join bdinteg:si_cliente d on(d.numcte = a.numcliente )
				left outer join bdicheq:sc_producto c on ( c.producto = b.prodtarjeta)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
               	where  b.numcte=trim(pnumcliente)

				LET iCont = iCont + 1;

				RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus WITH RESUME;

			END FOREACH

		END IF

		--Busqueda  por numero de tarjeta
		IF (ptipobusqueda = 3) THEN
			FOREACH
				select b.cuenta, a.numcliente, a.numtarjeta, c.nombre as Producto,
						d.nombre1,d.nombre2, d.apell_paterno, d.apell_materno, b.secuencia,e.descstatustarjeta
						into vnumcuenta,vnumcliente,vnumtarjeta,vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus
				from intercard:tarjeta a
				left outer join bdicheq:sc_tarjeta b on (a.numtarjeta=b.num_tarjeta)
				left outer join bdinteg:si_cliente d on (d.numcte = a.numcliente)
				left outer join bdicheq:sc_producto c on (c.producto = b.prodtarjeta)
				left outer join intercard:statustarjeta e on (a.codstatustarjeta = e.codstatustarjeta)
				where  b.num_tarjeta=trim(pnumtarjeta)

				LET iCont = iCont + 1;

				RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus WITH RESUME;

			END FOREACH

		END IF

		IF ( iCont = 0 ) THEN
			LET vsCodRet = 101; --Cliente No tiene cuentas
			RETURN vsCodRet,vnumcuenta, vnumcliente, vnumtarjeta, vproducto,vnombre1,vnombre2,vnombre3,vnombre4,vsecuencia,vstatus;
		END IF
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_homologa_email(pempresa CHAR(3))

    RETURNING CHAR(5), CHAR (80), INTEGER;

--Definicion de Variables
    DEFINE vcodret          CHAR (5);
    DEFINE sql_err          INTEGER;
    DEFINE vMensaje         CHAR (80);

    DEFINE vNumcliente      CHAR (20);
    DEFINE vE_mail          CHAR (80);
    DEFINE vNumcte          CHAR (20);
    DEFINE vEmail           CHAR (80);

    DEFINE vContador        INTEGER;

-- Inicializa variables
    LET vcodret         = '00000';
    LET sql_err         = 0;

    LET vNumcliente     = '';
    LET vE_mail         = '';
    LET vNumcte         = '';
    LET vEmail          = '';
    LET vContador       = 0;



BEGIN

    ON EXCEPTION SET sql_err

        IF sql_err <> 0  THEN
            LET vcodret = sql_err;
            LET vcodret = '00045';
            LET vMensaje = 'ERROR EN LA EJECUCION';
 
            RETURN vcodret, vMensaje, vContador;        -- Termina proceso del SP
        END IF;
    END EXCEPTION;

    --SET DEBUG file TO "/ids10_uc9/raul/capitulox/pba/homologa_email.out";
    --TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH

    SELECT numcliente,e_mail
      INTO vNumcliente,vE_mail
      FROM bdibpi:bpi_usuario
     WHERE id_usuario IS NOT NULL
       AND st_portal = 'activo'
       AND (e_mail <> '' OR e_mail IS NOT NULL)
    
      IF vNumcliente is null THEN  
        CONTINUE FOREACH;
      END IF;

    SELECT numcte,email
      INTO vNumcte,vEmail
      FROM bdinteg:si_ctepf
     WHERE numcte = vNumcliente;

      
      --IF NVL(vEmail,'') THEN
      --  UPDATE bdinteg:si_ctepf SET email = vE_mail WHERE numcte = vNumcliente;
      --END IF;
      IF vNumcliente = vNumcte AND vE_mail <> '' THEN
         UPDATE bdinteg:si_ctepf SET email = vE_mail WHERE numcte = vNumcliente;
         LET vContador = vContador + 1;
      END IF;
     
     END FOREACH;
END     
    LET vMensaje        = 'Actualización Exitosa';
    RETURN vcodret, vMensaje, vContador;

END PROCEDURE;

