CREATE PROCEDURE "informix".sp_consulta_empleado_corporativo(p_numeroEmpleado CHAR(10), p_nombreEmpleado CHAR(50), p_nEmpresa CHAR(4), p_skip INT)

     RETURNING	CHAR(50) AS nombre, CHAR(10) AS numero, CHAR(5) AS numeroSucursal, CHAR(40) AS nombreSucursal, CHAR(20) AS puesto, CHAR(40) AS password, DATE AS fechaBaja;

	--definicion de variables--	    
	DEFINE resultado_nombre             CHAR(50);
    	DEFINE resultado_numero             CHAR(10);
    	DEFINE resultado_numeroSucursal     CHAR(5);
    	DEFINE resultado_nombreSucursal     CHAR(40);
    	DEFINE resultado_puesto             CHAR(20);
    	DEFINE resultado_password           CHAR(40);
    	DEFINE resultado_fechaBaja          DATE;
    	DEFINE iSqlErr                      INTEGER;
		
     -- InicializaciÃ³n de las variables.
	LET resultado_nombre = '';
	LET resultado_numero = '';
    	LET resultado_numeroSucursal = '';
    	LET resultado_nombreSucursal = '';
    	LET resultado_puesto = '';
    	LET resultado_password = '';
    	LET resultado_fechaBaja = '';

    SET ISOLATION TO DIRTY READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_nombre = 'dd';
                    LET resultado_numero = '';
                    LET resultado_numeroSucursal = '';
                    LET resultado_nombreSucursal = '';
                    LET resultado_puesto = '';
                    LET resultado_password = '';
                    LET resultado_fechaBaja = '';
                    RETURN resultado_nombre, resultado_numero, resultado_numeroSucursal, resultado_nombreSucursal, resultado_puesto, resultado_password, resultado_fechaBaja;
                END IF;
        END EXCEPTION;

        IF p_nombreEmpleado IS NOT NULL AND p_nombreEmpleado <> '' THEN
            FOREACH
                SELECT SKIP p_skip DISTINCT si_ejecut.nombre, si_ejecut.ejecutivo, si_ejecut.sucursal, si_sucursales.nombre, si_ejecut.nombramiento, si_ejecut.password, si_ejecut.vigencia
                INTO resultado_nombre, resultado_numero, resultado_numeroSucursal, resultado_nombreSucursal, resultado_puesto, resultado_password, resultado_fechaBaja
                FROM bdinteg:si_ejecut
                    LEFT JOIN si_sucursales 
                        ON (si_sucursales.sucursal = si_ejecut.sucursal)
                WHERE si_sucursales.empresa = p_nEmpresa
                    AND si_ejecut.nombre LIKE ('%' || TRIM(p_nombreEmpleado) || '%')
                RETURN resultado_nombre, resultado_numero, resultado_numeroSucursal, resultado_nombreSucursal, resultado_puesto, resultado_password, resultado_fechaBaja WITH RESUME;
            END FOREACH;
        ELSE
            SELECT SKIP p_skip DISTINCT si_ejecut.nombre, si_ejecut.ejecutivo, si_ejecut.sucursal, si_sucursales.nombre, si_ejecut.nombramiento, si_ejecut.password, si_ejecut.vigencia
            INTO resultado_nombre, resultado_numero, resultado_numeroSucursal, resultado_nombreSucursal, resultado_puesto, resultado_password, resultado_fechaBaja
            FROM bdinteg:si_ejecut
                LEFT JOIN si_sucursales ON (si_sucursales.empresa = p_nEmpresa 
                            AND si_sucursales.sucursal = si_ejecut.sucursal)
            WHERE si_sucursales.empresa = p_nEmpresa
               AND si_ejecut.ejecutivo = p_numeroEmpleado;
            RETURN resultado_nombre, resultado_numero, resultado_numeroSucursal, resultado_nombreSucursal, resultado_puesto, resultado_password, resultado_fechaBaja;
        END IF;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_sucursal_numero (p_numeroSuc CHAR(4), p_sNumeroEmpresa CHAR(3))

     RETURNING	CHAR(30) AS numeroSucursal, CHAR(30) AS nombreSucursal;

	--definicion de variables--	    
	DEFINE resultado_numeroSucursal 	CHAR(30);
    DEFINE resultado_nombreSucursal		CHAR(30);
    DEFINE iSqlErr                     	INTEGER;
		
     -- InicializaciÃ³n de las variables.
	LET resultado_numeroSucursal = '';
	LET resultado_nombreSucursal = '';

    SET ISOLATION TO DIRTY READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_numeroSucursal = '';
                    LET resultado_nombreSucursal = '';
                    RETURN resultado_numeroSucursal, resultado_nombreSucursal;
                END IF;
        END EXCEPTION;
      
			SELECT DISTINCT sucursal, nombre
	        INTO resultado_numeroSucursal, resultado_nombreSucursal
	        FROM bdinteg:si_sucursales
            WHERE empresa = p_sNumeroEmpresa
                AND sucursal = p_numeroSuc;
	        RETURN resultado_numeroSucursal, resultado_nombreSucursal WITH RESUME;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultasucursales(p_skip INT, p_sNumeroEmpresa CHAR(3))

     RETURNING	CHAR(30) AS numeroSucursal, CHAR(30) AS nombreSucursal;

	--definicion de variables--	    
	DEFINE resultado_numeroSucursal 	CHAR(30);
    	DEFINE resultado_nombreSucursal		CHAR(30);
   	DEFINE iSqlErr                      	INTEGER;
		
     -- InicializaciÃ³n de las variables.
	LET resultado_numeroSucursal = '';
	LET resultado_nombreSucursal = '';

    SET ISOLATION TO dirty READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_numeroSucursal = '';
                    LET resultado_nombreSucursal = '';
                    RETURN resultado_numeroSucursal, resultado_nombreSucursal;
                END IF;
        END EXCEPTION;

		FOREACH       
	     	SELECT SKIP p_skip DISTINCT sucursal, nombre
	          INTO resultado_numeroSucursal, resultado_nombreSucursal
	          FROM bdinteg:si_sucursales
              WHERE bdinteg:si_sucursales.empresa = p_sNumeroEmpresa
              ORDER BY sucursal
	          RETURN resultado_numeroSucursal, resultado_nombreSucursal WITH RESUME;
		END FOREACH;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_extrae_acl_debito (p_sNumeroCuenta CHAR(30), p_sFechaInicial DATE, p_sFechaFinal DATE)

    RETURNING CHAR(11) AS folioCSUAC, DATE AS fechaAclaracion, DATE AS fechaMovimiento, CHAR(4) AS transaccion, money(16,2) AS montoAclaracion;

	--definicion de variables--	    
    	DEFINE resultado_folioCSUAC 		CHAR(11);	
  	DEFINE resultado_fechaAclaracion 	DATE;
   	DEFINE resultado_fechaMovimiento 	DATE;
    	DEFINE resultado_transaccion 		CHAR(4);
	DEFINE resultado_montoAclaracion	money(16,2);
    	DEFINE iSqlErr                      	INTEGER;
		
     -- InicializaciÃ³n de las variables.
	LET resultado_folioCSUAC  = '';	
    	LET resultado_fechaAclaracion = '';
    	LET resultado_fechaMovimiento = '';
    	LET resultado_transaccion = '';
	LET resultado_montoAclaracion = '';

    SET ISOLATION TO DIRTY READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_folioCSUAC = '';	
                    LET resultado_fechaAclaracion =	'';
                    LET resultado_fechaMovimiento =	'';
                    LET resultado_transaccion = '';
                    LET resultado_montoAclaracion = '';
                    RETURN resultado_folioCSUAC, resultado_fechaAclaracion, resultado_fechaMovimiento, resultado_transaccion, resultado_montoAclaracion;
                END IF;
        END EXCEPTION;
        

        FOREACH
            SELECT bdiaclaracion:acl_aclaracion.folio_csuac, bdiaclaracion:acl_aclaracion.fechacaptura, bdiaclaracion:acl_movimiento.fechahora,
                 bdiaclaracion:acl_tipo_movimiento.transaccion, bdiaclaracion:acl_aclaracion.importereclamado
            INTO resultado_folioCSUAC, resultado_fechaAclaracion, resultado_fechaMovimiento, resultado_transaccion, resultado_montoAclaracion
                FROM (bdiaclaracion:acl_aclaracion INNER JOIN
                    (bdiaclaracion:acl_movimiento INNER JOIN bdiaclaracion:acl_tipo_movimiento
                   ON bdiaclaracion:acl_tipo_movimiento.pky_tipo_movimiento = bdiaclaracion:acl_movimiento.fky_tipo_movimiento)
                        ON bdiaclaracion:acl_movimiento.fky_aclaracion = bdiaclaracion:acl_aclaracion.pky_aclaracion) INNER JOIN bdiaclaracion:acl_producto
                            ON bdiaclaracion:acl_producto.pky_producto = bdiaclaracion:acl_aclaracion.fky_producto
                            WHERE bdiaclaracion:acl_aclaracion.fky_estatus_aclaracion = 2 
                            AND bdiaclaracion:acl_aclaracion.fechacaptura BETWEEN p_sFechaInicial AND p_sFechaFinal
                            AND bdiaclaracion:acl_producto.numero_cuenta = p_sNumeroCuenta
                            RETURN resultado_folioCSUAC, resultado_fechaAclaracion, resultado_fechaMovimiento, resultado_transaccion, resultado_montoAclaracion WITH RESUME;
        END FOREACH;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_intento_mantenimiento_huella_corporativo(p_Empresa CHAR(5), p_sNumeroCliente CHAR(30), p_sNumeroCuenta CHAR(30), p_sNumeroTarjeta CHAR(30), 
				p_sPrimerNombre CHAR(30), p_sSegundoNombre CHAR(30), p_sPrimerApellido CHAR(30), p_sSegundoApellido CHAR(30), p_skip INTEGER)

     RETURNING	CHAR(20) AS numeroCliente, CHAR(30) AS primerApellido, CHAR(30) AS segundoApellido, CHAR(30) AS primerNombre, 
        CHAR(30) AS segundoNombre, CHAR(5) AS numeroMantenimiento, CHAR(1) AS estatus, CHAR(40) AS nombreSucursal, 
        CHAR(45) AS nombrePromotor, CHAR(8) AS numeroPromotor, DATE AS fechaAltaHuella;

	--definicion de variables--
	DEFINE resultado_numeroCliente          CHAR(20);
    	DEFINE resultado_primerApellido         CHAR(30);
	DEFINE resultado_segundoApellido        CHAR(30);
    	DEFINE resultado_primerNombre           CHAR(30);
    	DEFINE resultado_segundoNombre          CHAR(30);
    	DEFINE resultado_numeroMantenimiento    CHAR(5);
    	DEFINE resultado_estatus                CHAR(1);
    	DEFINE resultado_nombreSucursal         CHAR(40);
    	DEFINE resultado_nombrePromotor         CHAR(45);
    	DEFINE resultado_numeroPromotor         CHAR(8);
    	DEFINE resultado_fechaAltaHuella        DATE;
    	DEFINE cuenta_tarjeta                   CHAR(30);
    	DEFINE iSqlErr                          INTEGER;

     -- InicializaciÃ³n de las variables.
	LET resultado_numeroCliente = '';
	LET resultado_primerApellido = '';
	LET resultado_segundoApellido = '';
	LET resultado_primerNombre = '';
	LET resultado_segundoNombre = '';
   	LET resultado_numeroMantenimiento = '';
    LET resultado_estatus = '';
    LET resultado_nombreSucursal = '';
	LET resultado_nombrePromotor = '';
	LET resultado_numeroPromotor = '';
    LET resultado_fechaAltaHuella = '';

    SET ISOLATION TO DIRTY READ;

	BEGIN
        ON EXCEPTION
            SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET resultado_numeroCliente = '';
                LET resultado_primerApellido = '';
                LET resultado_segundoApellido = '';
                LET resultado_primerNombre = '';
                LET resultado_segundoNombre = '';
                LET resultado_numeroMantenimiento = '';
                LET resultado_estatus = '';
                LET resultado_nombreSucursal = '';
                LET resultado_nombrePromotor = '';
                LET resultado_numeroPromotor = '';
                LET resultado_fechaAltaHuella = '';
                RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                    resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                    resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor,resultado_fechaAltaHuella;
            END IF;
        END EXCEPTION;

        IF p_sNumeroCliente IS NOT NULL AND p_sNumeroCliente <> '' THEN
            FOREACH
                SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                    bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                    resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                    resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                FROM bdinteg:si_huella_temp 
                    LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                    LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                WHERE bdinteg:si_huella_temp.numcte = p_sNumeroCliente
                ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                SELECT nombre 
                INTO resultado_nombrePromotor
                FROM si_ejecut
                WHERE ejecutivo = resultado_numeroPromotor;

                RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
            END FOREACH;
        ELSE
            IF p_sNumeroCuenta IS NOT NULL AND p_sNumeroCuenta <> '' THEN
                FOREACH
                    SELECT num_cte
                    INTO resultado_numeroCliente
                    FROM bdicheq:sc_maechq
                    WHERE empresa = p_Empresa
                      AND cuenta = p_sNumeroCuenta
                    union
                    SELECT num_cte
                    FROM bdinvers:sv_maeinv
                    WHERE empresa = p_Empresa
                      AND cuenta = p_sNumeroCuenta
                    union
                    SELECT numcte
                    FROM bdicred:sd_maecred
                    WHERE empresa = p_Empresa
                      AND num_credito = p_sNumeroCuenta
                END FOREACH;
                IF (resultado_numeroCliente IS NOT NULL AND resultado_numeroCliente <> '') THEN
                    FOREACH
                        SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                            bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                        INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                            resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                            resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                        FROM bdinteg:si_huella_temp 
                            LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                        WHERE bdinteg:si_huella_temp.numcte = resultado_numeroCliente
                        ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                        SELECT nombre 
                        INTO resultado_nombrePromotor
                        FROM si_ejecut
                        WHERE ejecutivo = resultado_numeroPromotor;

                        RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                    END FOREACH;
                END IF;
            ELSE
                IF p_sNumeroTarjeta IS NOT NULL AND p_sNumeroTarjeta <> '' THEN

                    SELECT numcuenta
                    INTO cuenta_tarjeta
                    FROM intercard:tarjetacuenta
                    WHERE intercard:tarjetacuenta.numtarjeta = p_sNumeroTarjeta;

                    FOREACH
                        SELECT num_cte
                        into resultado_numeroCliente
                        FROM bdicheq:sc_maechq
                        WHERE empresa = p_Empresa
                          and cuenta = cuenta_tarjeta
                        union
                        SELECT num_cte
                        FROM bdinvers:sv_maeinv
                        WHERE empresa = p_Empresa
                          and cuenta = cuenta_tarjeta
                        union
                        SELECT numcte
                        FROM bdicred:sd_maecred
                        WHERE empresa = p_Empresa
                          and num_credito = cuenta_tarjeta
                    END FOREACH;

                    IF (resultado_numeroCliente IS NOT NULL AND resultado_numeroCliente <> '') THEN
                        FOREACH
                            SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                                bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                            INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                                resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                                resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                            FROM bdinteg:si_huella_temp 
                                LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                                LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                            WHERE bdinteg:si_huella_temp.numcte = resultado_numeroCliente
                            ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                            SELECT nombre 
                            INTO resultado_nombrePromotor
                            FROM si_ejecut
                            WHERE ejecutivo = resultado_numeroPromotor;

                            RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                        END FOREACH;
                    END IF;
                ELSE
                    IF(p_sSegundoNombre IS NULL OR p_sSegundoNombre = '') AND (p_sSegundoApellido IS NULL OR p_sSegundoApellido = '') THEN
                        FOREACH
                            SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                                bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                            INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                                resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                                resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                            FROM bdinteg:si_huella_temp 
                                LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                                LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                                WHERE nombre1 LIKE (p_sPrimerNombre || '%') 
                                    AND apell_paterno LIKE (p_sPrimerApellido || '%')
                            ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                            SELECT nombre 
                            INTO resultado_nombrePromotor
                            FROM si_ejecut
                            WHERE ejecutivo = resultado_numeroPromotor;

                            RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                        END FOREACH;
                    END IF;
                    IF(p_sSegundoNombre IS NULL OR p_sSegundoNombre = '') AND (p_sSegundoApellido IS NOT NULL AND p_sSegundoApellido <> '') THEN
                        FOREACH
                            SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                                bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                            INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                                resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                                resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                            FROM bdinteg:si_huella_temp 
                                LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                                LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                                WHERE nombre1 LIKE (p_sPrimerNombre || '%') 
                                    AND apell_paterno LIKE (p_sPrimerApellido || '%')  
                                    AND apell_materno LIKE (p_sSegundoApellido || '%')
                            ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                            SELECT nombre 
                            INTO resultado_nombrePromotor
                            FROM si_ejecut
                            WHERE ejecutivo = resultado_numeroPromotor;

                            RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                        END FOREACH;
                    END IF;
                    IF(p_sSegundoNombre IS NOT NULL AND p_sSegundoNombre <> '') AND (p_sSegundoApellido IS NULL OR p_sSegundoApellido = '') THEN
                        FOREACH
                            SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                                bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                            INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                                resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                                resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                            FROM bdinteg:si_huella_temp 
                                LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                                LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                            WHERE nombre1 LIKE (p_sPrimerNombre || '%') 
                                AND apell_paterno LIKE (p_sPrimerApellido || '%')  
                                AND nombre2 LIKE (p_sSegundoNombre || '%')
                            ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                            SELECT nombre 
                            INTO resultado_nombrePromotor
                            FROM si_ejecut
                            WHERE ejecutivo = resultado_numeroPromotor;

                            RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                        END FOREACH;
                    END IF;
                    IF(p_sSegundoNombre IS NOT NULL AND p_sSegundoNombre <> '') AND (p_sSegundoApellido IS NOT NULL AND p_sSegundoApellido <> '') THEN
                        FOREACH
                            SELECT SKIP p_skip DISTINCT bdinteg:si_huella_temp.numcte, apell_paterno, apell_materno, nombre1, nombre2, bdinteg:si_huella_temp.secuencia, 
                                bdinteg:si_huella_temp.status, si_sucursales.nombre, operador, si_huella_temp.fecha_alta
                            INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                                resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, 
                                resultado_nombreSucursal, resultado_numeroPromotor, resultado_fechaAltaHuella     
                            FROM bdinteg:si_huella_temp 
                                LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_huella_temp.numcte)
                                LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_huella_temp.sucursal)
                            WHERE nombre1 LIKE (p_sPrimerNombre || '%') 
                                AND apell_paterno LIKE (p_sPrimerApellido || '%')  
                                AND nombre2 LIKE (p_sSegundoNombre || '%') 
                                AND apell_materno LIKE (p_sSegundoApellido || '%')
                            ORDER BY si_huella_temp.numcte asC, bdinteg:si_huella_temp.secuencia asC

                            SELECT nombre 
                            INTO resultado_nombrePromotor
                            FROM si_ejecut
                            WHERE ejecutivo = resultado_numeroPromotor;

                            RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_fechaAltaHuella WITH RESUME;
                        END FOREACH;
                    END IF;
                END IF;
            END IF;
        END IF;
    END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_mantenimiento_huella_corporativo(p_Empresa CHAR(5), p_sNumeroCliente CHAR(30), p_sNumeroCuenta CHAR(30), p_sNumeroTarjeta CHAR(30), 
				p_sPrimerNombre CHAR(30), p_sSegundoNombre CHAR(30), p_sPrimerApellido CHAR(30), p_sSegundoApellido CHAR(30), p_skip INTEGER)

      RETURNING	CHAR(20) AS numeroCliente, CHAR(30) AS primerApellido, CHAR(30) AS segundoApellido, CHAR(30) AS primerNombre, 
        CHAR(30) AS segundoNombre, DATE AS fechaAlta, CHAR(5) AS numeroMantenimiento, CHAR(1) AS estatus, CHAR(40) AS nombreSucursal, 
        CHAR(45) AS nombrePromotor, CHAR(8) AS numeroPromotor, CHAR (45) AS nombreGerente, CHAR(8) AS numeroGerente, 
        CHAR(45) AS nombreCajero, CHAR(8) AS numeroCajero, DATE AS fechaAltaHuella, DATE AS fechaBajaHuella;

	--definicion de variables--
	DEFINE resultado_numeroCliente          CHAR(20);
   	DEFINE resultado_primerApellido         CHAR(30);
	DEFINE resultado_segundoApellido        CHAR(30);
   	DEFINE resultado_primerNombre           CHAR(30);
   	DEFINE resultado_segundoNombre          CHAR(30);
    	DEFINE resultado_fechaAlta              DATE;
    	DEFINE resultado_numeroMantenimiento    CHAR(5);
    	DEFINE resultado_estatus                CHAR(1);
    	DEFINE resultado_nombreSucursal         CHAR(40);
    	DEFINE resultado_nombrePromotor         CHAR(45);
    	DEFINE resultado_numeroPromotor         CHAR(8);
    	DEFINE resultado_nombreGerente          CHAR(45);
    	DEFINE resultado_numeroGerente          CHAR(8);
    	DEFINE resultado_numeroUsuario          CHAR(8);
    	DEFINE resultado_nombreCajero           CHAR(45);
    	DEFINE resultado_numeroCajero           CHAR(8);
    	DEFINE resultado_fechaAltaHuella        DATE;
    	DEFINE resultado_fechaBajaHuella        DATE;
    	DEFINE cuenta_tarjeta                   CHAR(30);
    	DEFINE iSqlErr                          INTEGER;

     -- InicializaciÃ³n de las variables.
	LET resultado_numeroCliente = '';
	LET resultado_primerApellido = '';
	LET resultado_segundoApellido = '';
	LET resultado_primerNombre = '';
	LET resultado_segundoNombre = '';
    LET resultado_fechaAlta = '';
    LET resultado_numeroMantenimiento = '';
    LET resultado_estatus = '';
    LET resultado_nombreSucursal = '';
	LET resultado_nombrePromotor = '';
	LET resultado_numeroPromotor = '';
	LET resultado_nombreGerente = '';
	LET resultado_numeroGerente = '';
    LET resultado_numeroUsuario =  '';
    LET resultado_nombreCajero = '';
    LET resultado_numeroCajero = '';
    LET resultado_fechaAltaHuella = '';
    LET resultado_fechaBajaHuella = '';

    SET ISOLATION TO DIRTY READ;

	BEGIN
        ON EXCEPTION
            SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET resultado_numeroCliente = '';
                LET resultado_primerApellido = '';
                LET resultado_segundoApellido = '';
                LET resultado_primerNombre = '';
                LET resultado_segundoNombre = '';
                LET resultado_fechaAlta = '';
                LET resultado_numeroMantenimiento = '';
                LET resultado_estatus = '';
                LET resultado_nombreSucursal = '';
                LET resultado_nombrePromotor = '';
                LET resultado_numeroPromotor = '';
                LET resultado_nombreGerente = '';
                LET resultado_numeroGerente = '';
		LET resultado_numeroUsuario =  '';
                LET resultado_nombreCajero = '';
                LET resultado_numeroCajero = '';
                LET resultado_fechaAltaHuella = '';
                LET resultado_fechaBajaHuella = '';
                RETURN 	resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
						resultado_segundoNombre, resultado_fechaAlta, resultado_numeroMantenimiento, resultado_estatus, 
						resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_nombreGerente, 
						resultado_numeroGerente, resultado_nombreCajero, resultado_numeroCajero, resultado_fechaAltaHuella, 
						resultado_fechaBajaHuella;
            END IF;
        END EXCEPTION;
        
        IF p_sNumeroCliente IS NOT NULL AND p_sNumeroCliente <> '' THEN
            FOREACH
                SELECT SKIP p_skip DISTINCT bdinteg:si_cte_huella.numcte, apell_paterno, apell_materno, nombre1, nombre2, si_cliente.fecha_alta, bdinteg:si_cte_huella.secuencia, 
                    bdinteg:si_cte_huella.estado, si_sucursales.nombre, operador, empleado, usuario3, si_cte_huella.fecha_alta, bdinteg:si_cte_huella.usuario
                INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                    resultado_segundoNombre, resultado_fechaAlta, resultado_numeroMantenimiento, resultado_estatus, 
                    resultado_nombreSucursal, resultado_numeroPromotor, resultado_numeroGerente, resultado_numeroCajero, 
                    resultado_fechaAltaHuella, resultado_numeroUsuario
                FROM bdinteg:si_cte_huella 
                    LEFT JOIN bdinteg:si_cliente 
                        ON (bdinteg:si_cliente.numcte = bdinteg:si_cte_huella.numcte)
                    LEFT JOIN bdinteg:si_sucursales 
                        ON (bdinteg:si_sucursales.empresa =  p_Empresa
                            AND bdinteg:si_sucursales.sucursal = bdinteg:si_cte_huella.sucursal)
                    LEFT JOIN bdinteg:si_huella_temp 
                        ON (bdinteg:si_cte_huella.numcte = bdinteg:si_huella_temp.numcte 
                            AND bdinteg:si_cte_huella.secuencia - 1 =  bdinteg:si_huella_temp.secuencia
                            AND bdinteg:si_cte_huella.fecha_alta = Date(bdinteg:si_huella_temp.fecha_alta)
	                    AND bdinteg:si_cte_huella.usuario = bdinteg:si_huella_temp.operador)
                WHERE bdinteg:si_cte_huella.numcte = p_sNumeroCliente
                ORDER BY si_cte_huella.numcte asC, bdinteg:si_cte_huella.secuencia asC

				IF resultado_numeroMantenimiento == 1 THEN
                   LET resultado_nombrePromotor = 'ALTA DE HUELLA';
                   LET resultado_numeroPromotor = resultado_numeroUsuario;
                ELSE
					SELECT nombre 
			        INTO resultado_nombrePromotor
			        FROM si_ejecut
			        WHERE ejecutivo = resultado_numeroPromotor;
				END IF;

                SELECT nombre 
                INTO resultado_nombreGerente
                FROM si_ejecut
                WHERE ejecutivo = resultado_numeroGerente;

                SELECT nombre 
                INTO resultado_nombreCajero
                FROM si_ejecut
                WHERE ejecutivo = resultado_numeroCajero;

                SELECT fecha_alta 
                INTO resultado_fechaBajaHuella
                FROM bdinteg:si_cte_huella
                WHERE secuencia = resultado_numeroMantenimiento + 1
                    AND numcte = resultado_numeroCliente;
                RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_fechaAlta, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_nombreGerente, resultado_numeroGerente, resultado_nombreCajero, resultado_numeroCajero, resultado_fechaAltaHuella, resultado_fechaBajaHuella WITH RESUME;
            END FOREACH;
        ELSE
            IF p_sNumeroCuenta IS NOT NULL AND p_sNumeroCuenta <> '' THEN
                FOREACH
                    SELECT num_cte
                    INTO resultado_numeroCliente
                    FROM bdicheq:sc_maechq
                    WHERE cuenta = p_sNumeroCuenta
                    union
                    SELECT num_cte
                    FROM bdinvers:sv_maeinv
                    WHERE empresa = p_Empresa
                      AND cuenta = p_sNumeroCuenta
                    union
                    SELECT numcte
                    FROM bdicred:sd_maecred
                    WHERE empresa = p_Empresa
                      AND num_credito = p_sNumeroCuenta
                END FOREACH;
                IF (resultado_numeroCliente IS NOT NULL AND resultado_numeroCliente <> '') THEN
                    FOREACH
                        SELECT SKIP p_skip DISTINCT bdinteg:si_cte_huella.numcte, apell_paterno, apell_materno, nombre1, nombre2, si_cliente.fecha_alta, bdinteg:si_cte_huella.secuencia, 
                            bdinteg:si_cte_huella.estado, si_sucursales.nombre, operador, empleado, usuario3, si_cte_huella.fecha_alta, bdinteg:si_cte_huella.usuario
                        INTO resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, 
                            resultado_segundoNombre, resultado_fechaAlta, resultado_numeroMantenimiento, resultado_estatus, 
                            resultado_nombreSucursal, resultado_numeroPromotor, resultado_numeroGerente, resultado_numeroCajero, 
                            resultado_fechaAltaHuella, resultado_numeroUsuario   
                        FROM bdinteg:si_cte_huella 
                            LEFT JOIN bdinteg:si_cliente ON (bdinteg:si_cliente.numcte = bdinteg:si_cte_huella.numcte)
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdinteg:si_cte_huella.sucursal)
                            LEFT JOIN bdinteg:si_huella_temp ON (bdinteg:si_cte_huella.numcte = bdinteg:si_huella_temp.numcte 
                                AND bdinteg:si_cte_huella.secuencia - 1 =  bdinteg:si_huella_temp.secuencia 
                                AND bdinteg:si_cte_huella.fecha_alta = Date(bdinteg:si_huella_temp.fecha_alta)
	                    AND bdinteg:si_cte_huella.usuario = bdinteg:si_huella_temp.operador)
                        WHERE bdinteg:si_cte_huella.numcte = resultado_numeroCliente
                        ORDER BY si_cte_huella.numcte asC, bdinteg:si_cte_huella.secuencia asC

						IF resultado_numeroMantenimiento == 1 THEN
		                   LET resultado_nombrePromotor = 'ALTA DE HUELLA';
		                   LET resultado_numeroPromotor = resultado_numeroUsuario;
		                ELSE
			                SELECT nombre 
			                INTO resultado_nombrePromotor
			                FROM si_ejecut
			                WHERE ejecutivo = resultado_numeroPromotor;
						END IF;

                        SELECT nombre 
                        INTO resultado_nombreGerente
                        FROM si_ejecut
                        WHERE ejecutivo = resultado_numeroGerente;

                        SELECT nombre 
                        INTO resultado_nombreCajero
                        FROM si_ejecut
                        WHERE ejecutivo = resultado_numeroCajero;

                        SELECT fecha_alta 
                        INTO resultado_fechaBajaHuella
                        FROM bdinteg:si_cte_huella
                        WHERE secuencia = resultado_numeroMantenimiento + 1
                            AND numcte = resultado_numeroCliente;
                        RETURN resultado_numeroCliente, resultado_primerApellido, resultado_segundoApellido, resultado_primerNombre, resultado_segundoNombre, resultado_fechaAlta, resultado_numeroMantenimiento, resultado_estatus, resultado_nombreSucursal, resultado_nombrePromotor, resultado_numeroPromotor, resultado_nombreGerente, resultado_numeroGerente, resultado_nombreCajero, resultado_numeroCajero, resultado_fechaAltaHuella, resultado_fechaBajaHuella WITH RESUME;
                    END FOREACH;
                END IF;
            ELSE
                IF p_sNumeroTarjeta IS NOT NULL AND p_sNumeroTarjeta <> '' THEN

                    SELECT numcuenta
                    INTO cuenta_tarjeta
                    FROM intercard:tarjetacuenta
                    WHERE intercard:tarjetacuenta.numtarjeta = p_sNumeroTarjeta;

                    FOREACH
                        SELECT num_cte
                        into resultado_numeroCliente
                        FROM bdicheq:sc_maechq
                        WHERE empresa = p_Empresa
                          AND cuenta = cuenta_tarjeta
                        union
                        SELECT num_cte
                        FROM bdinvers:sv_maeinv
