CREATE PROCEDURE "informix".sp_nombreempleado (p_sNumeroEmpleado CHAR(8))

     RETURNING	CHAR(45) AS nombreEmpleado;

	--definicion de variables--	    
	DEFINE resultado_nombreEmpleado 	CHAR(45);
	DEFINE iSqlErr                  	INTEGER;
	
     -- InicializaciÃ³n de las variables.
	LET resultado_nombreEmpleado = '';

    SET ISOLATION TO DIRTY READ;
			
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    	LET resultado_nombreEmpleado = '';
                    RETURN resultado_nombreEmpleado;
                END IF;
            END EXCEPTION;

		SELECT DISTINCT si_ejecut.nombre
		INTO resultado_nombreEmpleado
		FROM si_ejecut
		WHERE ejecutivo = p_sNumeroEmpleado;
		RETURN resultado_nombreEmpleado;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_estados(p_skip INT, p_Pais CHAR(3))

     RETURNING	CHAR(4) AS pais, CHAR(4) AS numeroEstado, CHAR(30) AS nombreEstado;

	--definicion de variables--	    
	DEFINE resultado_pais           CHAR(4);
    	DEFINE resultado_numeroEstado   CHAR(4);
    	DEFINE resultado_nombreEstado   CHAR(30);
    	DEFINE iSqlErr                  INTEGER;
		
     -- InicializaciÃ³n de las variables.
	LET resultado_pais = '';
	LET resultado_numeroEstado = '';
    LET resultado_nombreEstado = '';

    SET ISOLATION TO DIRTY READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_pais = '';
                    LET resultado_numeroEstado = '';
                    LET resultado_nombreEstado = '';
                    RETURN resultado_pais, resultado_numeroEstado, resultado_nombreEstado;
                END IF;
        END EXCEPTION;

		FOREACH       
	     	SELECT SKIP p_skip DISTINCT pais, estado, nombre
	          INTO resultado_pais, resultado_numeroEstado, resultado_nombreEstado
	          FROM bdinteg:si_estados 
              WHERE pais = p_Pais
              ORDER BY pais asC, nombre asC, estado asC
	          RETURN resultado_pais, resultado_numeroEstado, resultado_nombreEstado WITH RESUME;
		END FOREACH;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerparametros_altaunica(pEmpresa CHAR(3), pSucursal CHAR(4))
    RETURNING CHAR(5), CHAR(1), CHAR(1), CHAR(1), CHAR(15), CHAR(15), CHAR(3), CHAR(3), CHAR(3), CHAR(1);

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE sValor1 CHAR(100);
	DEFINE sValor2 CHAR(100);
	DEFINE sValor3 CHAR(100);
	DEFINE sValor4 CHAR(100);
	DEFINE sValor5 CHAR(100);
	DEFINE sValor6 CHAR(100);
	DEFINE sValor7 CHAR(100);
	DEFINE sValor8 CHAR(100);
	DEFINE sValor9 CHAR(100);

	LET cCodRet  = '000';
	LET iSqlErr = 0;
	LET sValor1 = "";
	LET sValor2 = "";
	LET sValor3 = "";
	LET sValor4 = "";
	LET sValor5 = "";
	LET sValor6 = "";
	LET sValor7 = "";
	LET sValor8 = "";
	LET sValor9 = "";

	--------------------------------------------------------------------------
	-- Creado por Rodolfo Tortolero Varela 08/12/2010
	--SET DEBUG FILE TO "/tmp/sp_obtenerparametros_altaunica.out";
	--TRACE ON;
	--------------------------------------------------------------------------
        SET ISOLATION TO DIRTY READ;
        
	BEGIN
		ON EXCEPTION SET iSqlErr
				IF iSqlErr !=0 THEN
						LET cCodRet = iSqlErr;
						RETURN cCodRet, sValor1, sValor2, sValor3, sValor4, sValor5, sValor6, sValor7, sValor8, sValor9;
				END IF;
		END EXCEPTION;
		
		SELECT valor INTO sValor1 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  70; --FlagBancoppel
		SELECT valor INTO sValor2 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  62; --FlagCoppel
		SELECT valor INTO sValor3 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  63; --FlagSolicitudes
		SELECT valor INTO sValor4 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  64; --IPConsultaCoppel
		SELECT valor INTO sValor5 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  65; --PuertoCoppel
		SELECT valor INTO sValor6 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  66; --OffsetCoppel
		SELECT valor INTO sValor7 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  67; --TotalRegisCoppel
		SELECT valor INTO sValor8 FROM bdinteg:si_param WHERE empresa = pEmpresa AND cod_param =  68; --TotalRegisPaginación

		SELECT {+INDEX(bditarjcop:sucursalescajaunica idx_sucursalescajaunica)} ostelefonica INTO sValor9 FROM bditarjcop:sucursalescajaunica WHERE empresa = pEmpresa AND cvesucursal = pSucursal; --OSTelActiva/Desactiva

		RETURN cCodRet, sValor1, sValor2, sValor3, sValor4, sValor5, sValor6, sValor7, sValor8, sValor9;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_tipored (
pempresa CHAR(3),
pnum_telefono CHAR(10)
)
RETURNING CHAR (6), CHAR(10), CHAR (3);

--Creado por: Enrique Lizárraga Lugo 28/oct/2010
--Función: Determina el tipo de red del número telefónico requerido así como el número de carrier que proporciona el servicio telefónico al cliente.

--Variables
DEFINE 	cCodRet CHAR(5);
DEFINE 	iSqlErr INTEGER;
DEFINE	vnir	CHAR(3);
DEFINE 	vserie	CHAR(4);
DEFINE 	vnumeracion CHAR(4);
DEFINE 	vtipored CHAR(10);
DEFINE	vnum_carrier_cat CHAR (3);

--Inicialización de variables
LET cCodret = '00000';
LET iSqlErr = 0;
LET vnir = '';
LET vserie = '';
LET vnumeracion = '';
LET vtipored = '';
LET vnum_carrier_cat = '';

BEGIN
    ON EXCEPTION SET iSqlErr
        IF iSqlErr !=0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, vtipored, vnum_carrier_cat;
        END IF;
    END EXCEPTION;
	
IF pnum_telefono <> '' THEN
	LET vnir = SUBSTR(pnum_telefono,1,2);
	IF vnir IN ('55','33','81') THEN
		LET vnir = SUBSTR(pnum_telefono,1,2);
		LET	vserie = SUBSTR(pnum_telefono,3,4);
		LET vnumeracion = SUBSTR(pnum_telefono,7,4)*1;
		IF EXISTS (SELECT 1 FROM bdinteg:si_catcofetel a WHERE a.nir = vnir AND a.serie = vserie AND vnumeracion >= a.numeracion_inicial AND vnumeracion <= a.numeracion_final) THEN
		SELECT limit 1 a.tipored, b.num_carrier_cat 
		INTO vtipored , vnum_carrier_cat FROM bdinteg:si_catcofetel a , bdinteg:si_catcarrier b
		WHERE a.nir = vnir AND a.serie = vserie AND trim(vnumeracion)*1 >= a.numeracion_inicial AND trim(vnumeracion)*1 <= a.numeracion_final AND a.razonsocial = b.nombre_carrier;
		RETURN cCodRet, vtipored, vnum_carrier_cat;
		END IF;
	ELSE
		LET vnir = SUBSTR(pnum_telefono,1,3);
		LET vserie = SUBSTR(pnum_telefono,4,3);
		LET vnumeracion = SUBSTR(pnum_telefono,7,4)*1;
		IF EXISTS (SELECT 1 FROM bdinteg:si_catcofetel a WHERE a.nir = vnir AND a.serie = vserie AND vnumeracion >= a.numeracion_inicial AND vnumeracion <= a.numeracion_final) THEN
		SELECT limit 1 a.tipored, b.num_carrier_cat 
		INTO vtipored , vnum_carrier_cat FROM bdinteg:si_catcofetel a , bdinteg:si_catcarrier b
		WHERE a.nir = vnir AND a.serie = vserie AND trim(vnumeracion)*1 >= a.numeracion_inicial AND trim(vnumeracion)*1 <= a.numeracion_final AND a.razonsocial = b.nombre_carrier;
		RETURN cCodRet, vtipored, vnum_carrier_cat;
		END IF;
	END IF;
ELSE
	RETURN '00001', vtipored, vnum_carrier_cat;
END IF;
--cCodRet = '00001' = Campo de número vacío

END;
END PROCEDURE;

CREATE PROCEDURE "informix".consnombrenumcte_amovil(pEmpresa CHAR(3),
						pNombre1 CHAR(26),
						pNombre2 CHAR(26),
                        pPaterno CHAR(26),
                        pMaterno CHAR(26),
						pFechaNac DATE,
						pNo_Rfc CHAR(13),
						pRazon CHAR(60),
                        pSecuencia SMALLINT)

--RETURNING CHAR(5) as cod_ret,CHAR(60) as nombre_completo ,CHAR(20) as numcte,CHAR(13) as rfc,CHAR(2) as tipo_cte;
RETURNING CHAR(5) as cod_ret, CHAR(60) as nombre_completo, CHAR(26) as Nombre1 ,CHAR(26) as Nombre2,CHAR(26) as Paterno,CHAR(26) as Materno,CHAR(20) as numcte,CHAR(13) as rfc,CHAR(2) as tipo_cte, DATE as fech_nac;

DEFINE sql_err 									  INTEGER;
DEFINE v_longitud,v_ciclo 					      SMALLINT;
DEFINE v_nombre_completo 						  CHAR(63);
DEFINE v_nombre1, v_nombre2, v_paterno, v_materno CHAR(26);
DEFINE v_numcte 								  CHAR(20);
DEFINE v_cod_ret 								  CHAR(5);
DEFINE v_razon_soc 								  CHAR(60);
DEFINE v_rfc 									  CHAR(13);
DEFINE v_tipocte 								  CHAR(2);
DEFINE v_f_nac                                    DATE;

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

LET v_cod_ret = "00000";
LET v_ciclo = 0;
LET v_nombre_completo = "";
LET v_numcte = "0000000000";
LET v_rfc = "";
LET v_tipocte = "";
LET v_nombre1 = "";
LET v_nombre2 = "";
LET v_paterno = "";
LET v_materno = "";
LET v_f_nac = "";

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_cod_ret,v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte, v_rfc,v_tipocte,v_f_nac;
     END IF;
   END EXCEPTION;

IF NVL(pEmpresa,'') = ''  THEN
	LET v_cod_ret = "00001";
	LET v_nombre_completo = 'Parámetros incompletos';
	RETURN v_cod_ret, v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte, v_rfc, v_tipocte, v_f_nac;
END IF;

SET ISOLATION TO DIRTY READ;

IF pRazon IS NOT NULL AND pRazon !="" THEN
    FOREACH
        SELECT skip pSecuencia limit 21
             cte.razon_social,cte.numcte,cte.rfc,cte.tipo_cliente,cpm.fecha_constitct
 	    INTO v_razon_soc,v_numcte,v_rfc,v_tipocte,v_f_nac
        FROM si_cliente as cte, si_ctepm as cpm 
        WHERE cte.razon_social = prazon
           and cte.apell_paterno = ''
	       and cte.apell_materno = ''
           and cte.numcte = cpm.numcte
        ORDER BY cte.numcte
--        LET v_ciclo = v_ciclo+1;
--        IF v_ciclo <= psecuencia THEN
-- 	        CONTINUE FOREACH;
--        END IF;
        LET v_nombre_completo = v_razon_soc;
        RETURN v_cod_ret,v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte,v_rfc,v_tipocte,v_f_nac WITH RESUME;
    END FOREACH;
ELSE

    IF pNo_Rfc IS NOT NULL AND pNo_Rfc != "" THEN
        FOREACH
            SELECT skip pSecuencia limit 21
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc,tipo_cliente,pf.fecha_nac
	        INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc,v_tipocte,v_f_nac
      	    FROM si_ctepf pf, si_cliente cl
      	    WHERE rfc = pno_rfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte
--      	    LET v_ciclo = v_ciclo+1;
--      	    IF v_ciclo <= psecuencia THEN
--                 CONTINUE FOREACH;
--      	    END IF;
	        LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
             || " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
	        RETURN v_cod_ret,v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte,v_rfc,v_tipocte,v_f_nac WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS

--	IF NVL(pPaterno,'') = '' AND NVL(pMaterno,'') = '' THEN
	IF NVL(pPaterno,'') = ''  THEN
		LET v_cod_ret = "00002";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos apellidos';
		RETURN v_cod_ret, v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte, v_rfc,v_tipocte,v_f_nac;
--	ELIF NVL(pNombre1,'') = '' AND NVL(pNombre2,'') = '' THEN
	ELIF NVL(pNombre1,'') = '' THEN
		LET v_cod_ret = "00003";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos nombres';
		RETURN v_cod_ret, v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte,v_rfc,v_tipocte,v_f_nac;
	ELSE
        if ( pPaterno is null or pPaterno = "" ) then
           let pPaterno = "";
        else
           let pPaterno = trim(pPaterno)||"*";
        end if;

        if ( pMaterno is null or pMaterno = "" ) then
           let pMaterno = "";
        else
           let pMaterno = trim(pMaterno)||"*";
        end if;

        if ( pNombre1 is null or pNombre1 = "" ) then
           let pNombre1 = "";
        else
           let pNombre1 = trim(pNombre1)||"*";
        end if;

        if ( pNombre2 is null or pNombre2 = "" ) then
           let pNombre2 = "";
        else
           let pNombre2 = trim(pNombre2)||"*";
        end if;

--		LET pPaterno = TRIM(pPaterno)||"*";
--		LET pMaterno = TRIM(pMaterno)||"*";
--		LET pNombre1 = TRIM(pNombre1)||"*";
--		LET pNombre2 = TRIM(pNombre2)||"*";

		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc,tipo_cliente,pf.fecha_nac
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc,v_tipocte,v_f_nac
				FROM si_ctepf pf, si_cliente cl
				WHERE cl.apell_paterno matches ppaterno
				AND cl.apell_materno matches pmaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo + 1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_cod_ret,v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte,v_rfc,v_tipocte,v_f_nac WITH RESUME;
			END FOREACH;

		ELSE

			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc,tipo_cliente
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc,v_tipocte
				FROM si_cliente cte, si_ctepf pf
				WHERE apell_paterno matches ppaterno
				AND apell_materno matches pmaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo+1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(UPPER(v_materno))
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_cod_ret,v_nombre_completo, v_nombre1, v_nombre2, v_paterno, v_materno, v_numcte,v_rfc,v_tipocte,v_f_nac WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE
DOCUMENT
'Consulta clientes por nombre(s) y apellido(s) y por fecha de nacimiento y regresa el tipo de cliente se usa en Apertura Movil',
'AUTOR : Ismael Hernandez',
'FECHA : 08/11/2010',
'BD    : bdinteg',
'VER   : 1.0';

create procedure "informix".sp_consejecutivomac(pejecutivo char(8), pmac char(12))
       returning char(5),char(1) ;

define vcodret char(5);
define vciclo smallint;
define vsqlerr integer;


define vmac char(12);
define vstatus char(1);
define vmach char(1) ;
define vsucursal char(4) ;
define vdepto char(3) ;
define vpuesto char(3) ;
define varea char(3) ;

let vmach="0" ;
let vciclo = 0;
let vcodret = "000";
let  vsqlerr = 0;

let vmac = "";
let vstatus = "";
let vsucursal = "";
let vdepto = "";
let vpuesto = "";
let varea = "";

set isolation to dirty read;
set lock mode to wait 3;

begin

   on exception set vsqlerr
      if vsqlerr <> 0 then
	 -- rollback work;
         let vcodret = vsqlerr;
         return vcodret,vmac ;
      end if;
   end exception;

-- Begin work;

        Select sucursal, departamento, puesto
        into vsucursal, vdepto, vpuesto
        from si_ejecut
        where ejecutivo = pejecutivo;

        if cast(nvl(vsucursal,'0') as int) > 0 and cast(nvl(vdepto,'0') as int) = 0 then

            Select {+INDEX(si_macarea idx_si_macarea)} area
            into varea
            From si_macarea
            where sucursal='0001' and puesto = vpuesto;

            if exists(Select ejecutivo From si_macejecutivo where ejecutivo = pejecutivo) then
                Foreach
                    Select mac, status
                    into vmac, vstatus
                    from si_macejecutivo
                    where ejecutivo = pejecutivo

                    if exists(Select {+INDEX(si_sucursalesmaquina idx_si_sucursalesmaquina)} mac From si_sucursalesmaquina where sucursal = trim(vmac) and area = varea and mac = upper(pmac)) then
                        if vstatus in ('A','T') then
                            let vmach='1';
                            exit Foreach;
                        else
                            let vmach='2';
                        end if;
                    else
                         let vmach='3';
                    end if;
                end Foreach;
            else
                let vmach='3';
            end if;

        else
            if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac)) then
                if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac) and me.status in ('A','T')  ) then
                    let vmach='1';
                else
                    let vmach='3';
                end if;
            else
                let vmach='2';
            end if;
        end if;

     return    vcodret,vmach ;

-- commit work;

end
end procedure
DOCUMENT
"regresa mac",
"Autor : Daniel Zambada, Modificó: Frank Gaxiola",
"FECHA : 30/octubre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".sp_conciliarcatalogocalles()

RETURNING CHAR(6), CHAR(80);

------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cMensaje                         CHAR(80);
DEFINE vnumerocalle                     INTEGER;
DEFINE vnombrecalle                     CHAR(30);
DEFINE v_numerocalle                    INTEGER;
DEFINE vfechahoy                        DATE;

DEFINE vdia                             DATE;
DEFINE vHora                            CHAR(8);
DEFINE vEmpresa                         CHAR(3);
DEFINE vProceso                         CHAR(30);
DEFINE vProcesoinicio                   CHAR(30);
------------------------------------------------------------
LET cCod_ret      = '00000';
LET sql_err       = 0;
LET cMensaje      = 'Proceso Exitoso';
LET vnumerocalle  = 0;
LET vnombrecalle  = '';
LET v_numerocalle = 0;

LET vEmpresa       = '001';
LET vProceso       = 'sp_conciliarcatalogocalles';
LET vProcesoinicio = 'PROCESO INICIALIZADO';
/*
Creado por José Almeida
Fecha de creacion 22 de octubre de 2009
Deberá instalarse en BDINTEG
Se creo para el conciliamiento de datos
de las calles que existen en el catalogo de coppel
con los de bancoopel, aquellas calles que existen en
coppel y no bancoppel seran insertadas en el catalogo
*/
      BEGIN
  
        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            
            SELECT DBINFO('utc_to_datetime', sh_curtime)::DATE  INTO vdia FROM sysmaster:sysshmvals;
            SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vHora FROM sysmaster:sysshmvals;
           
            INSERT INTO bdicobranza:cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc)
            VALUES (vProceso, cCod_ret, cMensaje, user, vdia, vHora, null); 

            
			RETURN cCod_ret, cMensaje;
	    END EXCEPTION;
	    
        SELECT DBINFO('utc_to_datetime', sh_curtime)::DATE  INTO vdia FROM sysmaster:sysshmvals;
        SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vHora FROM sysmaster:sysshmvals;
        
        INSERT INTO bdicobranza:cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc)
        VALUES (vProceso,'11111' , vProcesoinicio, user, vdia, vHora, null); 

	    
        ---------------Obtenemos la fecha de Hoy-----------------
        SELECT fecha_hoy 
        INTO   vfechahoy
        FROM   bdinteg:si_fechas;
        
        ---------------Borramos los datos de la tabla para insertar nuevos conciliados--------
        DELETE si_catcalles_bcpl_cpl;
        
        --------------Obtenemos los datos de las dos tablas y cuando no existan en bancoopel-----
        --------------se insertaran en el catalogo de bancoopel-----------------------------------
     FOREACH 
        SELECT a.numerocalle, a.nombrecalle, b.numerocalle
        INTO   vnumerocalle, vnombrecalle, v_numerocalle
        FROM   BDINTEG:si_catcalles_coppel a  
        LEFT OUTER JOIN BDINTEG:si_catcalles b ON (a.numerocalle = b.numerocalle)
        
                    IF ( v_numerocalle IS NULL )  THEN
                            
        INSERT INTO BDINTEG:si_catcalles_bcpl_cpl (numerocalle, fecha_conciliacion, tipo_actualizacion) 
                                   VALUES (vnumerocalle, vfechahoy, 'I');
        
                          ---Agregar que inserte directamente en si_catcalles
                          INSERT INTO bdinteg:si_catcalles (numerocalle, nombrecalle, f_inserta)
                                      VALUES(vnumerocalle, vnombrecalle, vfechahoy);
                                   
        UPDATE     BDINTEG:si_catcalles_coppel SET b_conciliado = 'V' WHERE numerocalle = vnumerocalle;             
                                   
                     END IF;
                     
      END FOREACH;
        
        SELECT DBINFO('utc_to_datetime', sh_curtime)::DATE  INTO vdia FROM sysmaster:sysshmvals;
        SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vHora FROM sysmaster:sysshmvals;
        
        INSERT INTO bdicobranza:cb_bitacora_cob (proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert, num_ult_reg_proc)
            VALUES (vProceso, cCod_ret, cMensaje, user, vdia, vHora, null); 

      
                 RETURN cCod_ret, cMensaje;
        END;
        END PROCEDURE;

CREATE PROCEDURE "informix".sp_conciliarcatalogociudades()
RETURNING CHAR(6), CHAR(80);
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cMensaje                         CHAR(80);

DEFINE vfechahoy                        DATE;
-----------------------------------------------------------
DEFINE vnumerociudad                    INTEGER;
DEFINE vnombreciudad                   CHAR(30);
DEFINE vinicialciudad                  CHAR(4);
DEFINE vnumeroestado                   INTEGER;
DEFINE vinicialestado                  CHAR(4);
DEFINE vsalariominimo                  INTEGER;
DEFINE vivaciudad                      INTEGER;
DEFINE vantiguedadciudad               DATE;
DEFINE vgerentezona                    INTEGER;
DEFINE vregioncobranzas                INTEGER;
DEFINE vunificaciudadescobranzas       INTEGER;
DEFINE vgerentecobranzas               INTEGER;
DEFINE vregionestadodecuenta           CHAR(1);
DEFINE vtipo_ciudad                    CHAR(1);
DEFINE vnumerociudadcoppel             INTEGER;
DEFINE vnombreciudadcoppel             CHAR(30);

DEFINE v_numerociudad                    INTEGER;
DEFINE v_nombreciudad                   CHAR(30);
DEFINE v_inicialciudad                  CHAR(4);
DEFINE v_numeroestado                   INTEGER;
DEFINE v_inicialestado                  CHAR(4);
DEFINE v_salariominimo                  INTEGER;
DEFINE v_ivaciudad                      INTEGER;
DEFINE v_antiguedadciudad               DATE;
DEFINE v_gerentezona                    INTEGER;
DEFINE v_regioncobranzas                INTEGER;
DEFINE v_unificaciudadescobranzas       INTEGER;
DEFINE v_gerentecobranzas               INTEGER;
DEFINE v_regionestadodecuenta           CHAR(1);
DEFINE v_tipo_ciudad                    CHAR(1);
DEFINE v_numerociudadcoppel             INTEGER;
DEFINE v_nombreciudadcoppel             CHAR(30);
DEFINE vEmpresa                         CHAR(3);
DEFINE vProceso                         CHAR(30);
DEFINE vProcesoinicio                   CHAR(30);


---------------------------------------------------------
LET vnumerociudad                    = 0;
LET vnombreciudad                   = '';
LET vinicialciudad                  = '';
LET vnumeroestado                   = 0;
LET vinicialestado                  = '';
LET vsalariominimo                  = 0;
LET vivaciudad                      = 0;
LET vantiguedadciudad               = '';
LET vgerentezona                    = 0;
LET vregioncobranzas                = 0;
LET vunificaciudadescobranzas       = 0;
LET vgerentecobranzas               = 0;
LET vregionestadodecuenta           = '';
LET vtipo_ciudad                    = '';
LET vnumerociudadcoppel             = 0;
LET vnombreciudadcoppel             = '';

LET v_numerociudad                    = 0;
LET v_nombreciudad                   = '';
LET v_inicialciudad                  = '';
LET v_numeroestado                   = 0;
LET v_inicialestado                  = '';
LET v_salariominimo                  = 0;
LET v_ivaciudad                      = 0;
LET v_antiguedadciudad               = '';
LET v_gerentezona                    = 0;
LET v_regioncobranzas                = 0;
LET v_unificaciudadescobranzas       = 0;
LET v_gerentecobranzas               = 0;
LET v_regionestadodecuenta           = '';
LET v_tipo_ciudad                    = '';
LET v_numerociudadcoppel             = 0;
LET v_nombreciudadcoppel             = '';
LET vEmpresa                         = '001';

------------------------------------------------------------
LET cCod_ret      = '00000';
LET sql_err       = 0;
LET cMensaje      = 'Proceso Exitoso';
LET vProceso      = '0200';
LET vProcesoinicio = 'PROCESO INICIALIZADO';

BEGIN

        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;

            CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, vproceso, '', '', '01') returning cCod_ret;
			    RETURN cCod_ret, cMensaje;
      --  RETURN cCod_ret;
        
	    END EXCEPTION;

/*
Creado por José Almeida
Fecha de creacion 22 de octubre de 2009
Deberá instalarse en BDINTEG
Se creo para el conciliamiento de datos
de las ciudades que existen en el catalogo de coppel
con los de bancoopel, aquellas ciudades que existen en
coppel y no bancoppel seran insertadas en el catalogo
y aquellas que tienen diferencia entre sus campos
*/
--Modificado por Marco A. Campos
--Fecha: 20100614
--Para que actualice en tabla si_catciudades


        --SET DEBUG FILE TO "/tmp/ALMEIDA/SP_ConciliarCatalogoCiudades.out";
        --TRACE ON;

        CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, vproceso, cCod_ret, vProcesoinicio, '02') returning cCod_ret;
		    --RETURN cCod_ret, cMensaje;

        ---------------Obtenemos la fecha de Hoy-----------------
        SELECT fecha_hoy
        INTO   vfechahoy
        FROM   bdinteg:si_fechas;

        ---------------Borramos los datos de la tabla para insertar nuevos conciliados--------
        DELETE si_catciudades_bcpl_cpl;

        --------------Obtenemos los datos de las dos tablas y cuando no existan en bancoopel-----
        --------------se insertaran en el catalogo de bancoopel-----------------------------------
     FOREACH
        SELECT a.numerociudad,      a.nombreciudad,     a.inicialciudad,    a.numeroestado,     a.inicialestado,
               a.salariominimo,     a.ivaciudad,        a.antiguedadciudad, a.gerentezona,      a.regioncobranzas,
               a.unificaciudadescobranzas, a.gerentecobranzas,              a.regionestadodecuenta, a.tipo_ciudad,
               a.numerociudadcoppel,a.nombreciudadcoppel,b.numerociudad,    b.nombreciudad ,    b.inicialciudad,
               b.numeroestado,      b.inicialestado,    b.salariominimo,    b.ivaciudad,        b.antiguedadciudad,
               b.gerentezona,       b.regioncobranzas,  b.unificaciudadescobranzas,             b.gerentecobranzas,
               b.regionestadodecuenta, b.tipo_ciudad,   b.numerociudadcoppel, b.nombreciudadcoppel
        INTO   vnumerociudad,       vnombreciudad ,     vinicialciudad,     vnumeroestado,      vinicialestado,
               vsalariominimo,      vivaciudad,         vantiguedadciudad,  vgerentezona,       vregioncobranzas,
               vunificaciudadescobranzas, vgerentecobranzas,                vregionestadodecuenta, vtipo_ciudad,
               vnumerociudadcoppel, vnombreciudadcoppel,v_numerociudad,     v_nombreciudad ,    v_inicialciudad,
               v_numeroestado,      v_inicialestado,    v_salariominimo,    v_ivaciudad,        v_antiguedadciudad,
               v_gerentezona,       v_regioncobranzas,  v_unificaciudadescobranzas,             v_gerentecobranzas,
               v_regionestadodecuenta, v_tipo_ciudad,   v_numerociudadcoppel,v_nombreciudadcoppel

        FROM   BDINTEG:si_catciudades_coppel a
        LEFT OUTER JOIN BDINTEG:si_catciudades b ON (a.numerociudad = b.numerociudad)

        IF ( v_numerociudad IS NULL )  THEN
            --- INSERTA CIUDADES NUEVAS
            INSERT INTO BDINTEG:si_catciudades_bcpl_cpl
                        --(numerociudad, fecha_conciliacion, nombreciudad , inicialciudad, numeroestado,tipo_actualizacion)
                        (numerociudad, fecha_conciliacion, nombreciudad , tipo_actualizacion)
                 VALUES (vnumerociudad, vfechahoy, vnombreciudad , 'I' );

            INSERT INTO BDINTEG:informix.si_catciudades
                        (numerociudad,  nombreciudad, inicialciudad, numeroestado, inicialestado, salariominimo,
                         gerentezona,  regioncobranzas, ivaciudad,  antiguedadciudad, unificaciudadescobranzas, gerentecobranzas,
                         regionestadodecuenta, tipo_ciudad, numerociudadcoppel, nombreciudadcoppel, f_inserta)
                 VALUES(vnumerociudad,  vnombreciudad, vinicialciudad, vnumeroestado,  vinicialestado, vsalariominimo,
                        vgerentezona,   vregioncobranzas, vivaciudad,  vantiguedadciudad,   vunificaciudadescobranzas, vgerentecobranzas,
                        vregionestadodecuenta, vtipo_ciudad, vnumerociudadcoppel, vnombreciudadcoppel, vfechahoy);


            UPDATE     BDINTEG:si_catciudades_coppel
               SET b_conciliado = 'V'
             WHERE numerociudad = vnumerociudad;

            CONTINUE FOREACH;

        --D
        ELSE
          IF  ( (vnumeroestado <> v_numeroestado)
                   OR (vsalariominimo <> v_salariominimo )
                   OR (vivaciudad <> v_ivaciudad)
                   OR (vgerentezona <> v_gerentezona)
                   OR (vregioncobranzas <> v_regioncobranzas)
                   OR (vunificaciudadescobranzas <> v_unificaciudadescobranzas)
                   OR (vgerentecobranzas <> v_gerentecobranzas)
                   OR (vnumerociudadcoppel <> v_numerociudadcoppel)
                   OR (vinicialciudad <> v_inicialciudad)
                   OR (vinicialestado <> v_inicialestado)
                   OR (vantiguedadciudad <> v_antiguedadciudad)
                   OR (vregionestadodecuenta <> v_regionestadodecuenta)
                   OR (vtipo_ciudad <> v_tipo_ciudad)
                   OR (vnombreciudadcoppel = '') ) THEN

            INSERT INTO BDINTEG:si_catciudades_bcpl_cpl
                        --(numerociudad, fecha_conciliacion, nombreciudad , inicialciudad, tipo_actualizacion)
                        (numerociudad, fecha_conciliacion, nombreciudad , tipo_actualizacion)
                 VALUES (vnumerociudad, vfechahoy, vnombreciudad , 'M');

            --Actualizar en si_catciudades los valores comparados en el if
            UPDATE BDINTEG:si_catciudades
               SET salariominimo = vsalariominimo,
                   gerentezona = vgerentezona,
                   regioncobranzas = vregioncobranzas,
                   ivaciudad = vivaciudad,
                   antiguedadciudad = vantiguedadciudad,
                   unificaciudadescobranzas = vunificaciudadescobranzas,
                   gerentecobranzas = vgerentecobranzas,
                   regionestadodecuenta = vregionestadodecuenta,
                   tipo_ciudad = vtipo_ciudad,
                   numerociudadcoppel = numerociudadcoppel,
                   nombreciudadcoppel = vnombreciudadcoppel,
                   fechaultimaactualizacion = vfechahoy
             WHERE numerociudad = vnumerociudad
               and numeroestado = vnumeroestado;

             UPDATE BDINTEG:si_catciudades_coppel SET b_conciliado = 'V' WHERE numerociudad = vnumerociudad;
          END IF;
        end if;
 
      END FOREACH;

    CALL bdicobranza:"informix".sp_inserta_bitacora_cob(vempresa, vproceso, '', '', '03') returning cCod_ret;
	  RETURN cCod_ret, cMensaje;
  --RETURN cCod_ret;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_exportarcatalogocalles(pCatalogo CHAR(1), pFechaAct DATE, pSeparador CHAR(1), pEjecucion CHAR(1))
RETURNING  CHAR(6), CHAR(80);
    
--Declaracion de variables
------------------------------------------------------------
DEFINE sql_err 			                INTEGER;
DEFINE isam_err 		                INTEGER;
DEFINE error_info		                CHAR(80);
DEFINE cCod_ret                         CHAR(6);
DEFINE cMensaje                         CHAR(80);
DEFINE cCadena                          CHAR (500);
DEFINE vFechaArch                       DATE;
DEFINE vNomArch                         CHAR(30);
DEFINE vNomArchAux                      CHAR(40);
DEFINE vPathOri                         CHAR(50);
DEFINE vPath                            CHAR(50);
------------------------------------------------------------

-- Creado: José de Jesús Almeida Inzunza
-- Fecha: 19 de octubre de 2009
-- Crear en BDINTEG
-- Se crea con el objetivo de obtener el total o una parcialidad de las calles del catalogo

-- Modificado por: MACF
-- Fecha: 03/06/2010
-- Agregar parámetro pEjecucion para determinar si es Automática o Manual

LET cCod_ret      = '00000';
LET sql_err       = 0;
LET cMensaje      = '';
LET cCadena       = '';
LET vNomArch      = 'si_catcalles_';
LET vNomArchAux      = 'si_catcalles_Aux';
LET vPathOri        = '';
LET vPath         = '';

      BEGIN
  
        ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
			RETURN cCod_ret, cMensaje;
	    END EXCEPTION;

--SET DEBUG FILE TO "/tmp/ALMEIDA/sp_ExportarCatalogoCalles.out";
  --SET DEBUG FILE TO "/ids10_uc9/macf/sp_ExportarCatalogoCalles.out";
  --TRACE ON;

    SELECT fecha_hoy
    INTO   vFechaArch
    FROM   bdinteg:si_fechas;
    
  --  LET vNomArch = TRIM(vNomArch) || TO_CHAR(vFechaArch,'%Y%m%d') || '.txt';
    
    if pEjecucion = 'A' then
          select valor into vPathOri 
          from bdinteg:si_param_dom 
          where cod_param = 11;
    end if;
    Let vPath = TRIM(vPathOri);
    
     LET vNomArchAux = TRIM(vNomArchAux) || TO_CHAR(vFechaArch,'%Y%m%d') || '.txt';    
    LET vNomArchAux = TRIM(vNomArchAux);
    LET vNomArch = TRIM(vNomArch) || TO_CHAR(vFechaArch,'%Y%m%d') || '.txt';    
    LET vNomArch = TRIM(vNomArch);    
    
IF (pCatalogo = 1) THEN

    if pEjecucion = 'A' then
        LET cCadena = 'echo "unload to ' || trim(vPath) ||   trim(vNomArchAux) ||  ' DELIMITER ''' || pSeparador || ''' SELECT numerocalle, nombrecalle FROM BDINTEG:si_catcalles" >' || trim(vPath) || 'corre_si_catcalles.sql';
        System cCadena;
        let cCadena = 'dbaccess bdinteg ' || trim(vPath) || 'corre_si_catcalles.sql';
        System cCadena;
        LET cCadena = "sed 's/"||pSeparador ||"$//g' "|| trim(vPath) || trim(vNomArchAux) || " >> " ||  trim(vPath) || trim(vNomArch);
        SYSTEM cCadena;
        let cCadena = 'rm ' || trim(vPath) || 'corre_si_catcalles.sql';
        System cCadena;   
        let cCadena = 'rm ' || trim(vPath) || trim(vNomArchAux );
        System cCadena; 
    else
 /*
    LET cCadena = 'echo "unload to ' || '''/tmp/' ||   SUBSTR(vNomArch,1,LENGTH(vNomArch)) || '''' || ' DELIMITER ''' || pSeparador || ''' SELECT numerocalle, nombrecalle FROM BDINTEG:si_catcalles" > /tmp/corre_si_catcalles.sql';
    System cCadena;

    let cCadena = 'dbaccess bdinteg /tmp/corre_si_catcalles.sql';
    System cCadena;
  */
    let cCadena = 'rm /tmp/corre_si_catcalles.sql';
 --   System cCadena;
    
    end if;    
    
ELIF (pCatalogo = 0) THEN
       if pEjecucion = 'A' then
      /*      LET cCadena = 'echo "unload to ' || SUBSTR(vPath,1,LENGTH(vPath)) || SUBSTR(vNomArch,1,LENGTH(vNomArch)) || '''' || ' DELIMITER ''' || pSeparador || ''' SELECT numerocalle, nombrecalle FROM BDINTEG:si_catcalles' 
               --  || ' WHERE f_ult_actualiza >= ''' || pFechaAct || '''" > /tmp/corre_si_catcalles.sql';
                   || '" > ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'corre_si_catcalles.sql';
            System cCadena;
            let cCadena = 'dbaccess bdinteg ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'corre_si_catcalles.sql';
            System cCadena; */
            let cCadena = 'rm ' || SUBSTR(vPath,1,LENGTH(vPath)) || 'corre_si_catcalles.sql';
            --System cCadena;
       else
     /*LET cCadena = 'echo "unload to ' || '''/tmp/' || SUBSTR(vNomArch,1,LENGTH(vNomArch)) || '''' || ' DELIMITER ''' || pSeparador || ''' SELECT numerocalle, nombrecalle FROM BDINTEG:si_catcalles' 
               --  || ' WHERE f_ult_actualiza >= ''' || pFechaAct || '''" > /tmp/corre_si_catcalles.sql';
                   || '" > /tmp/corre_si_catcalles.sql';
                 
    System cCadena;

    let cCadena = 'dbaccess bdinteg /tmp/corre_si_catcalles.sql';
    System cCadena;
*/
    let cCadena = 'rm /tmp/corre_si_catcalles.sql';
  --  System cCadena;    

    end if;
ELSE

    LET cCod_ret = '00001';
    LET cMensaje = 'Parámetro de Catálogo Invalido';    
    RETURN cCod_ret, cMensaje;
   
END IF;    

LET cMensaje = TRIM(vNomArch);
RETURN cCod_ret, cMensaje;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_pay_depuracion()
RETURNING VARCHAR(10), VARCHAR(255);


	DEFINE vcod_ret         		VARCHAR(10); 
	DEFINE sql_err          		INTEGER;
	DEFINE isam_err         		INTEGER;
	DEFINE error_info       		CHAR(40);
	
	DEFINE vdia_cte					INTEGER;
	DEFINE vdif_cte					INTEGER;
	DEFINE vfec_depuracion_cte		DATE;
	DEFINE vfecha_hoy				DATE;
	
	DEFINE vdia_dir					INTEGER;
	DEFINE vdif_dir					INTEGER;
	DEFINE vfec_depuracion_dir		DATE;

	DEFINE vdia_cta					INTEGER;
	DEFINE vdif_cta					INTEGER;
	DEFINE vfec_depuracion_cta		DATE;

	DEFINE vdia_tar					INTEGER;
	DEFINE vdif_tar					INTEGER;
	DEFINE vfec_depuracion_tar 		DATE;
	
	
	--Manejo del error
       ON EXCEPTION
		SET sql_err, isam_err, error_info
		
           IF sql_err <> 0 THEN
            LET vcod_ret=sql_err;
            RETURN vcod_ret, isam_err||' ' ||error_info;
			
           END IF;
       END EXCEPTION;
	   
	--set debug file to "/tmp/sp_pay_depuracion";
	--TRACE ON;	   
	 
	LET vcod_ret = '000';          
	LET sql_err = 0;          
	LET isam_err = 0;        
	LET error_info = '';
	
	
	LET vfecha_hoy = '';
	LET vdia_cte = 0;				
	LET vdif_cte = 0;				
	LET vfec_depuracion_cte = '';	
				
	
	LET vdia_dir = 0;				
	LET vdif_dir = 0;				
	LET vfec_depuracion_dir = '';	
	
	LET vdia_cta = 0;				
	LET vdif_cta = 0;				
	LET vfec_depuracion_cta = '';
	
	LET vdia_tar = 0;
	LET vdif_tar = 0;
	LET vfec_depuracion_tar = '';

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;	
	   
	SELECT fecha_depuracion, dia
		INTO vfec_depuracion_cte, vdia_cte
		FROM bdinteg:si_pyt_depuracion
		WHERE id_tabla = 1;
		
	SELECT fecha_depuracion, dia
		INTO vfec_depuracion_dir, vdia_dir
		FROM bdinteg:si_pyt_depuracion
		WHERE id_tabla = 2;

	SELECT fecha_depuracion, dia
		INTO vfec_depuracion_cta, vdia_cta
		FROM bdinteg:si_pyt_depuracion
		WHERE id_tabla = 3;	

	SELECT fecha_depuracion, dia
		INTO vfec_depuracion_tar, vdia_tar
		FROM bdinteg:si_pyt_depuracion
		WHERE id_tabla = 4;	

	LET vfecha_hoy = TODAY;
	
	LET vdif_cte = vfecha_hoy - vfec_depuracion_cte;
	LET vdif_dir = vfecha_hoy - vfec_depuracion_dir;
	LET vdif_cta = vfecha_hoy - vfec_depuracion_cta;
	LET vdif_tar = vfecha_hoy - vfec_depuracion_tar;
	
	-- Depuracion de Cliente
	IF( vdif_cte = vdia_cte ) THEN
	
		TRUNCATE bdinteg:info_clientes_pyt;
		
		UPDATE bdinteg:si_pyt_depuracion 
		   SET (fecha_depuracion, ind_dep) = (TODAY, '1')
		  WHERE id_tabla = 1;
	ELSE 
		UPDATE bdinteg:si_pyt_depuracion 
		   SET ind_dep = '0'
		 WHERE id_tabla = 1;
	END IF			

	-- Depuracion de Direccion
	IF(vdif_dir = vdia_dir ) THEN
	
		TRUNCATE bdinteg:info_direccion_pyt;
	
		UPDATE bdinteg:si_pyt_depuracion 
		   SET (fecha_depuracion, ind_dep) = (TODAY, '1')
		  WHERE id_tabla = 2;
				
	ELSE 
			UPDATE bdinteg:si_pyt_depuracion 
			  SET ind_dep = '0'
			WHERE id_tabla = 2;
	END IF	
	
	--Depuracion de Cuenta
	IF(vdif_cta = vdia_cta) THEN

		TRUNCATE bdinteg:info_cuenta_pyt;
		
		UPDATE bdinteg:si_pyt_depuracion 
		   SET (fecha_depuracion, ind_dep) = (TODAY, '1')
		 WHERE id_tabla = 3;
				
	ELSE 
		UPDATE bdinteg:si_pyt_depuracion SET ind_dep = '0'
				WHERE id_tabla = 3;
				
	END IF

	-- Depuracion de Tarjeta
	IF( vdif_tar = vdia_tar ) THEN
		-- Pendiente
	END IF			
	
	RETURN vcod_ret, 'PROCESO EXITOSO';
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ejecuta_catbcpplcppl(p_proceso smallint, pcatalogo CHAR(1), pfecha Date,
                                                             pseparador CHAR(1), pejecucion CHAR(1), pnomarch CHAR(30))
       RETURNING char(6), char(80);
      

DEFINE vCodRet              CHAR(5);
DEFINE vMensaje             CHAR(80);
DEFINE SQL_ERR              INTEGER;
DEFINE ISAM_ERR             INTEGER;
DEFINE ERROR_INFO           VARCHAR(80);
DEFINE vvCodRet             char(5);
DEFINE vvMensaje            char(80);
DEFINE vv_codret            char(5);
DEFINE vv_mensaje           char(80);
DEFINE v_fch_inic           DATE;
DEFINE v_fch_fin            DATE;

    --SET DEBUG FILE TO "/tmp/sp_ejecuta_monitor.out";
    --TRACE ON; 

    LET vCodRet             =   "11111";
    LET vMensaje            =   "PROCESO INICIALIZADO";
  
BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET vCodRet  = SQL_ERR;
        LET vMensaje  = ERROR_INFO;        
        RETURN vCodRet, vMensaje;
    END EXCEPTION;
  
    IF (p_proceso = 1) THEN
       
        CALL bdinteg:SP_ConciliarCatalogoCalles()
        RETURNING vvCodRet, vvMensaje;

    ELIF (p_proceso = 2) THEN

        CALL bdinteg:SP_ConciliarCatalogoCiudades()
        RETURNING vvCodRet, vvMensaje;
        
    ELIF (p_proceso = 3) THEN

        CALL bdinteg:sp_conciliarcatalogozonas()
        RETURNING vvCodRet, vvMensaje;
       
    ELIF (p_proceso = 4) THEN
    
        CALL bdinteg:sp_ExportarCatalogoCalles(pCatalogo, pFecha, pSeparador , pEjecucion)
        RETURNING vvCodRet, vvMensaje;
        
    ELIF (p_proceso = 5) THEN

        CALL bdinteg:sp_ExportarCatalogoCiudades(pCatalogo, pFecha, pSeparador , pEjecucion)
        RETURNING vvCodRet, vvMensaje;

    ELIF (p_proceso = 6) THEN

        CALL bdinteg:sp_ExportarCatalogoZonas(pCatalogo, pFecha, pSeparador, pEjecucion)
        RETURNING vvCodRet, vvMensaje;

    ELIF (p_proceso = 7) THEN

        CALL bdinteg:SP_ImportarCatalogoCalles(pSeparador, pNomArch, pEjecucion )
        RETURNING vvCodRet, vvMensaje;

    ELIF (p_proceso = 8) THEN

        CALL bdinteg:SP_ImportarCatalogoCiudades(pSeparador, pNomArch, pEjecucion )
        RETURNING vvCodRet, vvMensaje;

    ELIF (p_proceso = 9) THEN

        CALL bdinteg:SP_ImportarCatalogoZonas(pSeparador, pNomArch, pEjecucion )
        RETURNING vvCodRet, vvMensaje;

    END IF

    LET vCodRet = '00000';
    LET vMensaje = 'PROCESO EXITOSO';

END

RETURN vCodRet, vMensaje;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultahuellactebcoenlinea (pTipo CHAR(1), pNumcte CHAR(20))
RETURNING CHAR(5), INTEGER, SMALLINT, CHAR(942), CHAR(942), INTEGER, INTEGER, SMALLINT, CHAR(1);

    DEFINE vCodret     CHAR(5);
    DEFINE vsqlerr     INTEGER;
    DEFINE visamerr    INTEGER;
    DEFINE vNumcte     INTEGER;
    DEFINE vSecuencia  SMALLINT;
    DEFINE vMapad      CHAR(942);
    DEFINE vMapai      CHAR(942);
    DEFINE vReferencia INTEGER;
    DEFINE vSucursal   INTEGER;
    DEFINE vNumciudad  SMALLINT;
    DEFINE vSexo       CHAR(1);

    LET vCodret = "000";
    LET vNumcte = 0;
    LET vSecuencia = 0;
    LET vMapad = "";
    LET vMapai = "";
    LET vReferencia = 0;
    LET vSucursal = 0;
    LET vNumciudad = 0;
    LET vSexo = "";

    BEGIN
    
    ON EXCEPTION SET vsqlerr,visamerr
        IF vsqlerr != 0 THEN
            LET vcodret = vsqlerr;
            RETURN vCodret, vNumcte, vSecuencia, vMapad, vMapai, vReferencia, vSucursal, vNumciudad, vSexo;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO '/tmp/huellas.out';
    --- TRACE ON;

    -- // Verifica Recepcion correcta de Parametro
    IF pNumcte IS NULL OR Trim(pNumcte) = "" THEN
        LET vCodret = "110";
        RETURN vCodret, vNumcte, vSecuencia, vMapad, vMapai, vReferencia, vSucursal, vNumciudad, vSexo;
    END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    IF pTipo = "1" THEN
        SELECT {+INDEX(si_cte_huella ix_huellanew), +INDEX(si_cliente idx_si_clientex), +INDEX(si_direcciones_actual idx_numcte)}
               ctehuella.numcte::INTEGER, ctehuella.secuencia, ctehuella.dmapa, ctehuella.imapa, 
               NVL(cte.numcte_ref::INTEGER, 0) AS numcte_ref, cte.sucursal::INTEGER, dir.numerociudad, pf.sexo
          INTO vNumcte, vSecuencia, vMapad, vMapai, vReferencia, vSucursal, vNumciudad, vSexo
          FROM si_cte_huella ctehuella, 
               si_cliente cte, 
               si_direcciones_actual dir, 
               si_ctepf pf
         WHERE ctehuella.numcte = TRIM(pNumcte)         
           AND cte.numcte = ctehuella.numcte
           AND dir.numcte = ctehuella.numcte
           AND pf.numcte = ctehuella.numcte
           AND ctehuella.estado = 'A'
       --- AND dir.secuencia = (SELECT {+INDEX(si_direcciones inx_direcciones)} MAX(secuencia) FROM si_direcciones WHERE numcte = TRIM(pNumcte) AND tipo_dir = 1);
           AND dir.tipo_dir = '1';
           
        IF vMapad IS NULL OR vMapai IS NULL THEN
            LET vCodret = "132";
            RETURN vCodret, vNumcte, vSecuencia, vMapad, vMapai, vReferencia, vSucursal, vNumciudad, vSexo;
        END IF;
    END IF;

    RETURN vCodret, vNumcte, vSecuencia, vMapad, vMapai, vReferencia, vSucursal, vNumciudad, vSexo;
    
    END;
    
END PROCEDURE

DOCUMENT
"Consulta de Huella de cliente ",
"AUTOR: Jesus Montoya",
