create procedure "informix".sp_validar_telefono(pTelefono char(20) )
 returning char(5);
 
 define v_codret char(5);
 --define v_cadena char(10);
 define i smallint;
 define v_long_word smallint;
 define v_caracter char(1);
 --define v_result char(1);
 
 let v_codret = '00000';
 --let v_cadena = '';
 let i = 0;
 let v_long_word = 0;
 let v_caracter = '';
 --let v_result = 'S';
 
 let v_long_word = length(pTelefono);
 
  BEGIN

    FOR i IN (0 TO v_long_word)
          let v_caracter = substr(pTelefono, i, 1);     
          IF ( v_caracter <> '0' and v_caracter <> '1' and v_caracter <> '2' and v_caracter <> '3' and v_caracter <> '4' and v_caracter <> '5' and
               v_caracter <> '6' and v_caracter <> '7' and v_caracter <> '8' and v_caracter <> '9')   THEN

               --let v_result = 'N';
               let v_codret = "00700";
               RETURN v_codret;
          END IF;
    END FOR;
   
    --let v_codret = "Telefono correcto!";
    RETURN v_codret;
    
  END;
end procedure;

CREATE PROCEDURE "informix".sp_consctastraspasadas(pNumCteTraspasar CHAR(20))
RETURNING
CHAR(4), CHAR(40), CHAR(20), CHAR(20), CHAR(2), DATE, MONEY(16,2);
--DECLARACION DE VARIABLES
DEFINE vc_producto      CHAR(4);
DEFINE vc_descproducto  CHAR(40);
DEFINE vc_cuenta        CHAR(20);
DEFINE vc_cliente       CHAR(20);
DEFINE vc_estatus       CHAR(2);
DEFINE vd_fechaalta     DATE;
DEFINE vm_saldo         MONEY(16,2);
DEFINE vi_sqlerr        INTEGER;
DEFINE vc_Empresa       CHAR(3);
DEFINE vtabla           INTEGER;
--INICIALIZACION DE VARIABLES
LET vc_producto = "";
LET vc_descproducto = "";
LET vc_cuenta = "";
LET vc_cliente = "";
LET vc_estatus = "";
LET vd_fechaalta = "";
LET vm_saldo = 0.00;
LET vi_sqlerr = 0;
LET vc_Empresa = '001';
LET vtabla=0;

BEGIN
    ON EXCEPTION SET vi_sqlerr
    IF vi_sqlerr <> 0 THEN
        LET vc_producto = vi_sqlerr;
        RETURN vc_producto, vc_descproducto, vc_cuenta, vc_cliente, vc_estatus, vd_fechaalta, vm_saldo;
    END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/ids10_uc9/VH/integ/sp_consctastraspasadas.out";
    --TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    
    DELETE {+INDEX (bdinteg:si_fuscuentas idxctecta)} FROM si_fuscuentas WHERE num_cte = pNumCteTraspasar;

    IF EXISTS(SELECT {+INDEX (bdinteg:si_fusmaechq pk_fusmacte)} num_cte FROM bdinteg:si_fusmaechq WHERE num_cte = pNumCteTraspasar) THEN              
        INSERT INTO si_fuscuentas
        SELECT {+INDEX (bdinteg:si_fusmaechq pk_fusmacte)} mae.producto as producto, prod.nombre as nombre, mae.cuenta as cuenta, mae.num_cte as num_cte,  nvl(mae.status_cta, "00") as status, noc.fecha_alta as fecha_alta, (mae.sdo_actual - mae.sdo_retenido - mae.sdo_cong -  mae.imp_chq_sbg) as saldo
        FROM bdinteg:si_fusmaechq mae, bdicheq:sc_maenoc noc, bdicheq:sc_producto prod
        WHERE mae.num_cte = pNumCteTraspasar AND noc.cuenta = mae.cuenta AND mae.producto = prod.producto;
    END IF;
    IF EXISTS(SELECT {+INDEX (bdinteg:si_fusmaecred pk_fcredcte)} numcte FROM bdinteg:si_fusmaecred WHERE numcte = pNumCteTraspasar) THEN
        INSERT INTO si_fuscuentas
        SELECT {+INDEX (bdinteg:si_fusmaecred pk_fcredcte)} cred.num_producto as producto, def.nombre_prod as nombre, cred.num_credito as cuenta, cred.numcte as num_cte, cred.status_cred as status, cred.fecha_apertura as fecha_alta, (dos.sdo_capital + dos.monto_vencido + dos.mto_venc_trasp + dos.cap_tras_no_venci)  as saldo
        FROM bdinteg:si_fusmaecred cred, bdicred:sd_maesdos dos, bdicred:sd_definicion def
        WHERE cred.numcte = pNumCteTraspasar AND dos.empresa = vc_Empresa AND dos.num_credito = cred.num_credito AND def.empresa = vc_Empresa AND def.num_producto = cred.num_producto;
    END IF;

    IF EXISTS (SELECT {+INDEX (bdinteg:si_fusmaeinv pk_invcte)} num_cte FROM bdinteg:si_fusmaeinv WHERE num_cte = pNumCteTraspasar) THEN
        INSERT INTO si_fuscuentas
        SELECT {+ INDEX (bdinteg:si_fusmaeinv pk_invcte)} inv.cod_instrum as producto, ins.nombre as nombre, inv.cuenta as cuenta, inv.num_cte as num_cte, inv.status_cta as status, inv.fecha_alta as fecha_alta, sdo_dia_ant as saldo
        FROM bdinteg:si_fusmaeinv inv, bdinvers:sv_instrum ins
        WHERE inv.num_cte = pNumCteTraspasar AND inv.cod_instrum = ins.cod_instrum; 
    END IF;
    IF EXISTS (SELECT {+INDEX (bdinteg:si_fussolicitudes pk_fussolicitudes)} numcte FROM bdinteg:si_fussolicitudes WHERE numcte = pNumCteTraspasar) THEN
        INSERT INTO si_fuscuentas
        SELECT {+INDEX (bdinteg:si_fussolicitudes pk_fussolicitudes)} "016" as producto, fun.desc_funcion as nombre, sol.num_solicitud as cuenta, sol.numcte as num_cte, sol.status_solicitud as status, sol.fecha_insert as fecha_alta, nvl(sol.monto_solicitado, 0.00) as saldo
        FROM bdinteg:si_fussolicitudes sol, bdisolic:ss_funcionalidad fun
        WHERE sol.numcte = pNumCteTraspasar AND fun.cod_funcion = "016";
    END IF;
        
    FOREACH
        SELECT {+INDEX (bdinteg:si_fuscuentas idxctecta)} producto, nombre, cuenta, num_cte, status, fecha_alta,  saldo
        INTO vc_producto, vc_descproducto, vc_cuenta, vc_cliente, vc_estatus, vd_fechaalta, vm_saldo
        FROM si_fuscuentas
        WHERE num_cte = pNumCteTraspasar
        ORDER BY producto
        RETURN vc_producto, vc_descproducto, vc_cuenta, vc_cliente, vc_estatus, vd_fechaalta, vm_saldo WITH RESUME;
    END FOREACH;
    DELETE {+INDEX (bdinteg:si_fuscuentas idxctecta)} FROM si_fuscuentas WHERE num_cte = pNumCteTraspasar;   
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtnombre_bpi(pEmpresa CHAR(3), pNumCte CHAR(9))
	returning CHAR(5), CHAR(26),CHAR(26), CHAR(26), CHAR(26);

	--Elaboró: Javier A. Chávez T.
	--Actividad: devuelve el nombre del cliente
	--Solicito: Mauricio León
	--Fecha: 17/04/09
	---*********************************************
	--Modifico: José de Jesús Nevarez
	--Actividad: Se modifica para que obtenga el nombre de Clientes de la EmpresaNet.
	--Solicito: Diana Castellanos
	--Fecha: 23/08/2011

	--DEFINE VARIABLES
	DEFINE vNombre1 CHAR (26);
	DEFINE vNombre2 CHAR (26);
	DEFINE vApell_pat CHAR (26);
	DEFINE vApell_mat CHAR (26);
	DEFINE vTpoPersona CHAR (2);
	DEFINE vRazonSocial CHAR (60);
	DEFINE iLongitud  INTEGER;
	DEFINE cod_ret CHAR(5);
    DEFINE sql_err INTEGER; 

	--Inicializa
	LET cod_ret ='000';
	LET vNombre1 = "";
	LET vNombre2 = "";
	LET vApell_pat = "";
	LET vApell_mat = "";
	LET vTpoPersona = "";
	LET vRazonSocial= "";
	LET iLongitud = 0;


 BEGIN
	ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret, vNombre1, vNombre2, vApell_pat, vApell_mat;
      END IF ;
	END EXCEPTION ;
   
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;

	IF(pNumCte <> '') THEN
	
		SELECT tpo_persona INTO vTpoPersona FROM  bdinteg:"informix".si_cliente WHERE numcte = pNumCte and empresa = pEmpresa;
		
		IF (vTpoPersona IS NOT NULL OR vTpoPersona <> '') THEN
			IF (vTpoPersona == '01') THEN
				SELECT nombre1, nombre2, apell_paterno, apell_materno INTO vNombre1, vNombre2, vApell_pat, vApell_mat
				FROM bdinteg:"informix".si_cliente WHERE numcte = pNumCte and empresa = pEmpresa;
			ELSE 
				SELECT razon_social INTO vRazonSocial FROM bdinteg:"informix".si_cliente WHERE numcte = pNumCte and empresa = pEmpresa;
			
				LET vRazonSocial = TRIM(vRazonSocial);
				LET iLongitud = LENGTH(vRazonSocial);
			
				IF (iLongitud <= 24) THEN
					LET vNombre1 = vRazonSocial;
					LET vApell_pat = vRazonSocial;
				ELSE 
					LET vNombre1 = SUBSTRING(vRazonSocial FROM 1 FOR 24);
					LET vApell_pat = SUBSTRING(vRazonSocial FROM 25 FOR (iLongitud));
				END IF;
			END IF;
		END IF;

		IF (vNombre1 = '' OR vNombre1 IS NULL) THEN
			LET cod_ret = '002';
		END IF;

	ELSE
		LET cod_ret = '001';
	END IF;

	RETURN cod_ret, vNombre1, vNombre2, vApell_pat, vApell_mat;
 END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_parametrosgralesintegral(pEmpresa CHAR(3),pNumEmpleado CHAR(8))
	RETURNING CHAR(5),CHAR(2),CHAR(2),CHAR(100),CHAR(45),CHAR(30),DATE,CHAR(2),CHAR(11),DATE,DATE,DATE,DATE,DATE,DATE;

	--Declaracion de variables	
    DEFINE cEmpresa		       CHAR(3);	
	DEFINE iSqlErr              INTEGER;
	DEFINE cCodRet              CHAR(5);
	DEFINE cLongitudCliente     CHAR(2);
	DEFINE cCodMonNac           CHAR(2);
	DEFINE cPathRep             CHAR(100);
	DEFINE cNombreUsuario       CHAR(45);
	DEFINE cNombreEmpresa       CHAR(30);
	DEFINE dFecha_Hoy           DATE;
	DEFINE cSistema             CHAR(2);
	DEFINE cLongCta             CHAR(11);
	DEFINE dFecha_ant           DATE;
	DEFINE dProx_fecha           DATE;
	DEFINE dPri_dia_mes          DATE;
	DEFINE dPri_hab_mes          DATE;
	DEFINE dUlt_dia_mes          DATE;
	DEFINE dUlt_hab_mes          DATE;

	--Crea el archivo de monitoreo del proceso
	--SET DEBUG FILE TO "/tmp/sp_ParametrosGralesIntegral.out";
	--TRACE ON;

	--inicializacion de  variables
    LET cEmpresa= '';	
	LET cCodRet= '00000';
	LET cLongitudCliente= '';
	LET cCodMonNac= '';
	LET cPathRep= '';
	LET cNombreUsuario= '';
	LET cNombreEmpresa = '';
	LET dFecha_Hoy = '';
	LET cSistema = '';
	
	LET cLongCta   = 0;
	LET dFecha_ant = '';
	LET dProx_fecha = '';
	LET dPri_dia_mes  = '';
	LET dPri_hab_mes  = '';
	LET dUlt_dia_mes ='';
	LET dUlt_hab_mes ='';
			

	BEGIN
	--Crea el control de errores
		ON EXCEPTION SET iSqlErr
			IF iSqlErr != 0 THEN
				LET cCodRet= iSqlErr;
				RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
			END IF;
		END EXCEPTION;
        
        set isolation to dirty read;
        set lock mode to wait 3;
		
        IF pEmpresa = '' THEN
            LET cCodRet = '00001'; -- PARAMETRO EMPRESA VACIO
           RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;

        IF pNumEmpleado = '' THEN
            LET cCodRet = '00002'; -- PARAMETRO NUMERO EMPLEADO VACIO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		 IF LENGTH(pNumEmpleado) <> 8 THEN		
            LET cCodRet = '00003'; -- PARAMETRO NUMERO DE EMPLEADO NO VALIDO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		SELECT empresa
		INTO cEmpresa
		FROM bdinteg:si_empresas
		WHERE empresa = pEmpresa;

        IF cEmpresa IS NULL OR cEmpresa = '' THEN
            LET cCodRet = '00004'; -- EMPRESA NO EXISTE EN CATALOGO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		--Obtengo el valor longitud del numero de cliente		
		SELECT Trim(valor)
		INTO cLongitudCliente 
		FROM bdinteg:si_param                 
		WHERE empresa = pEmpresa AND cod_param = 7; 

		--Obtengo el valor codigo de la moneda nacional
		SELECT Trim(valor)
		INTO cCodMonNac 
		FROM bdinteg:si_param 
		WHERE empresa = pEmpresa AND descripcion = ('codigo mn');
                

		--Obtengo el valor path de reportes   		
		SELECT Trim(valor) 
		INTO cPathRep               		
		FROM bdinteg:si_param 
		where empresa = pEmpresa and cod_param = 44;
               

		--Obtengo el nombre del usuario o ejecutivo
		SELECT nombre 
		INTO cNombreUsuario
		FROM bdinteg:si_ejecut
		WHERE ejecutivo = pNumEmpleado;
		 
		-- Obtengo el nombre de la empresa
		SELECT razon_social
		INTO cNombreEmpresa
		FROM bdinteg:si_empresas 
		WHERE empresa = pEmpresa;
		
		-- Obtengo la longitud de la Cuenta
		SELECT valor 
		INTO cLongCta
		FROM bdicheq:sc_param 
		WHERE codparam = 'longcta';
		
		-- Obtengo Fecha de integral para la Captura de Parametros	
		SELECT fecha_hoy,fecha_ant,prox_fecha,pri_dia_mes,pri_hab_mes,ult_dia_mes,ult_hab_mes  
		INTO dFecha_Hoy,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes
		FROM bdinteg:si_fechas;

		--Obtengo codigo del sistema
		SELECT sistema
		INTO cSistema
		FROM bdinteg:si_sistema 
		WHERE siglas = 'SI';
		
		
	   IF cNombreUsuario='' OR cNombreUsuario IS NULL THEN
			LET cCodRet = '00005';	   END IF;
		RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
					   
		
	END
	END PROCEDURE
	DOCUMENT
	'DESCRIPCION: Genera una consulta en las tablas si_param, si_ejecut,si_empresas,sc_fechas,si_sistema', 
	'tomando como parametro o dato de entrada, la empresa y el numero de empleado para obtener datos del empleado',	
	'AUTOR: Guadalupe Payan',
	'FECHA: Octubre 2010',
	'VERSION: 201010',	
	'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_obtienenaccte(pCodNac CHAR(3))

	-- DATOS A REGRESAR --
	RETURNING
	 CHAR(6) 	AS COD_RET,    		-- Codigo de retorno
	CHAR(60) 	AS MENSAJE_EJEC, 	-- Mensaje de Ejecucion
	 CHAR(3) 	AS COD_NAC, 		-- Clave del regimen
	CHAR(15) 	AS DESCRIPCION;   	-- Descripcion
	
	--	VARIABLES CONTROL DE ERRORES --
	DEFINE cCodRet  CHAR(5);
	DEFINE sql_err  INTEGER;
	
	-- VARIABLES --
	DEFINE cCodNac	CHAR(3);
	DEFINE cMens	CHAR(60);
	DEFINE cDesc	CHAR(15);
	DEFINE iBand	SMALLINT;
	

	-- INICIALIZACION DE VARIABLES --
	LET cCodRet = "000";
	LET cCodNac = "";
	LET cMens 	= "EJECUCION GENERADA CORRECTAMENTE";
	LET cDesc 	= "";
	LET iBand 	= 0;

	-- CONTROL DE ERRORES --	
BEGIN
	ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET cCodRet = sql_err;
            RETURN TRIM(cCodRet), TRIM(cMens), TRIM(cCodNac), TRIM(cDesc);
        END IF
	END EXCEPTION;

    set isolation to dirty read;
	SET LOCK MODE TO WAIT 3;
	
	--SET DEBUG FILE TO "/dbexport/victor/sp_obtienenaccte.out";
	--TRACE ON;	
		
	IF pCodNac = "" THEN
		LET pCodNac = NULL;
	END IF
	
	IF pCodNac IS NULL THEN		--SE REALIZA UNA CONSULTA COMPLETA Y REGRESA TODOS LOS REGISTROS		
		FOREACH
			SELECT nacion, descripcion
			INTO cCodNac, cDesc
			FROM Bdinteg:"informix".si_nacion
			ORDER BY nacion
			
			LET iBand = 1;
			
			RETURN TRIM(cCodRet), TRIM(cMens), TRIM(cCodNac), TRIM(cDesc) WITH RESUME;
			
		END FOREACH;
		
	ELSE							--SE REALIZA UNA CONSULTA PARA UN CODIGO DE NACION EN ESPECIFICO	
		SELECT nacion, descripcion
		INTO cCodNac, cDesc
		FROM Bdinteg:"informix".si_nacion
		WHERE nacion = pCodNac;
		
		IF cCodNac IS NULL THEN --NO EXISTE EL CODIGO DE LA NACION
			LET cCodRet = '100';
			LET cMens = 'NO EXISTE EL CODIGO DE LA NACION, VERIFIQUE';
		END IF;
		
		RETURN TRIM(cCodRet), TRIM(cMens), TRIM(cCodNac), TRIM(cDesc);
		
	END IF;
	
	IF iBand = 0 THEN --NO HAY DATOS EN LA TABLA-CATALOGO
		LET cCodRet = '200';
		LET cMens = 'NO EXISTEN DATOS EN EL CATALOGO, VERIFIQUE';
		RETURN TRIM(cCodRet), TRIM(cMens), TRIM(cCodNac), TRIM(cDesc);
	END IF
	
END
END PROCEDURE
DOCUMENT
'Versión         : 1.0',
'Creado por      : Clemente Angulo Ballardo',
'Fecha creacion  : 13 de Junio 2011',
'Descripcion     : Obtiene todas las naciones o la descripcion de una en especifico',
'Base de Datos	 : Bdinteg';

CREATE PROCEDURE "informix".sp_updcte_fus() 
RETURNING CHAR(5), CHAR(80);
--DEFINICION DE VARIABLES
DEFINE vc_CodRet        CHAR(5);
DEFINE vi_SqlErr        INTEGER;
DEFINE vi_iSAMErr        INTEGER;
DEFINE vi_iSAMData        CHAR(80);
DEFINE vc_Mensaje       CHAR(80);
DEFINE pClienteTitular        CHAR(20);
DEFINE pClienteTraspasaCtas        CHAR(20);
DEFINE vc_detalle_mov2   CHAR(200);
DEFINE vc_proceso       CHAR(50);
DEFINE vc_tabla         CHAR(30);
DEFINE vc_detalle_mov   CHAR(200);
DEFINE vc_Cuenta        CHAR(20);
DEFINE vc_Cuenta2        CHAR(20);
DEFINE vi_secuencia     INTEGER;
DEFINE vc_aniomes       CHAR(6);
DEFINE pCte        CHAR(20);
DEFINE vi_num_serial    INTEGER;
DEFINE vd_fecha_mov     DATE;
--INICIALIZACION DE VARIABLES
LET vc_CodRet = "00000";
LET vi_SqlErr = 0;
LET vi_iSAMErr=0;
LET vi_secuencia = 0;
LET vi_iSAMData="";
LET vc_Mensaje = "EL PROCESO SE EFECTUO CORRECTAMENTE";
LET pClienteTitular="";
LET pClienteTraspasaCtas="";
LET vc_detalle_mov2 = "";
LET vc_proceso = "FusionClientes";
LET vc_tabla = "";
LET vc_detalle_mov = "";
LET vc_Cuenta = "";
LET vc_aniomes="";
LET vc_Cuenta2="";
LET pCte="";
LET vi_num_serial=0;
LET vd_fecha_mov = "";




set isolation to dirty read;
set lock mode to wait 3;

    BEGIN

    ON EXCEPTION SET vi_SqlErr,vi_iSAMErr,vi_iSAMData
        IF vi_SqlErr <> 0 THEN
            LET vc_CodRet = vi_SqlErr;
            LET vc_Mensaje = "ERROR NO CONTROLADO";
            LET vc_detalle_mov2=vi_SqlErr||'|'||vi_iSAMErr||'|'||vi_iSAMData; 
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov2, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            RETURN vc_CodRet, vc_Mensaje;
        END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/ids10_uc9/VH/sp_updcte_fus.out";
    --TRACE ON;


SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} DISTINCT TRIM(cliente_tit),TRIM(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>''
    --******************INICIA TRASPASO DE SOBREGIROS ******************************************
    --******************************************************************************************    
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT {+INDEX (bdicheq:sc_histsbg ix173_1)} cuenta INTO vc_Cuenta FROM bdicheq:sc_histsbg WHERE empresa='001' AND num_cte = pClienteTraspasaCtas

            LET vc_proceso='SOBREGIROS';
            LET vc_tabla = "sc_histsbg";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fushistsbg 
            SELECT {+INDEX (bdicheq:sc_histsbg idx_histsbg1)} * FROM bdicheq:sc_histsbg WHERE empresa='001' AND cuenta = vc_Cuenta;     
		
            UPDATE {+INDEX (bdicheq:sc_histsbg idx_histsbg1)} bdicheq:sc_histsbg SET num_cte = pClienteTitular WHERE empresa='001' AND cuenta = vc_Cuenta; 
        END FOREACH;  
    --******************INICIA TRASPASO DE PROAC ***********************************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT cta_eje,cuenta,secuencia INTO vc_Cuenta,vc_Cuenta2,vi_secuencia FROM bdicheq:sc_proac WHERE num_cte = pClienteTraspasaCtas

            LET vc_proceso='PROAC';
            LET vc_tabla = "sc_proac";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(vc_Cuenta2)||'|'||vi_secuencia||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusproac 
            SELECT {+INDEX (bdicheq:sc_proac idxproac_13)} * FROM bdicheq:sc_proac WHERE cta_eje = vc_Cuenta AND num_cte = pClienteTraspasaCtas;     
		
            UPDATE {+INDEX (bdicheq:sc_proac idxproac_13)} bdicheq:sc_proac SET num_cte = pClienteTitular WHERE cta_eje = vc_Cuenta AND num_cte = pClienteTraspasaCtas;  
        END FOREACH;  
    --******************INICIA TRASPASO DE PORTABILIDAD NOMINA**********************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT cuenta INTO vc_Cuenta FROM bdicheq:sc_portabilidad WHERE numcte = pClienteTraspasaCtas AND empresa='001'

            LET vc_proceso='PORTABILIDAD NOMINA';
            LET vc_tabla = "sc_portabilidad";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusportabilidad 
            SELECT * FROM bdicheq:sc_portabilidad WHERE cuenta = vc_Cuenta AND empresa='001';     
		
            UPDATE bdicheq:sc_portabilidad SET numcte = pClienteTitular WHERE cuenta = vc_Cuenta AND empresa='001';
        END FOREACH;  
    --******************INICIA TRASPASO DE FACTURA ELECTRONICA**********************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT num_cuenta,idreg INTO vc_Cuenta,vi_secuencia FROM bdicheq:sc_encabezado_edocta_factelect WHERE num_cte = pClienteTraspasaCtas

            LET vc_proceso='FACTURA ELECTRONICA';
            LET vc_tabla = "sc_encabezado_edocta_factelect";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas)||'|'||vi_secuencia;   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusencabezado_edocta_factelect 
            SELECT * FROM bdicheq:sc_encabezado_edocta_factelect WHERE num_cuenta = vc_Cuenta AND idreg = vi_secuencia;     
		
            UPDATE bdicheq:sc_encabezado_edocta_factelect SET num_cte = pClienteTitular WHERE num_cuenta = vc_Cuenta AND idreg = vi_secuencia;  
        END FOREACH;  
    --******************INICIA TRASPASO DE BENEFICIARIOS INVERSION *****************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT cuenta INTO vc_Cuenta FROM bdinvers:sv_benefic WHERE numcte = pClienteTraspasaCtas AND empresa='001'

            LET vc_proceso='BENEFICIARIOS INVERSION';
            LET vc_tabla = "sv_benefic";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusbenefic_inv 
            SELECT * FROM bdinvers:sv_benefic WHERE cuenta = vc_Cuenta AND empresa='001';     
		
            UPDATE bdinvers:sv_benefic SET numcte = pClienteTitular WHERE cuenta = vc_Cuenta AND empresa='001';
        END FOREACH;  
    --******************INICIA TRASPASO DE AUTORIZADOS INVERSION *******************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT cuenta INTO vc_Cuenta FROM bdinvers:sv_cotitular WHERE numcte = pClienteTraspasaCtas AND empresa='001'

            LET vc_proceso='AUTORIZADOS INVERSION';
            LET vc_tabla = "sv_cotitular";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fuscotitular_inv 
            SELECT {+INDEX (bdinvers:sv_cotitular idx_cotit)} * FROM bdinvers:sv_cotitular WHERE empresa='001' AND cuenta = vc_Cuenta;     
		
            UPDATE {+INDEX (bdinvers:sv_cotitular idx_cotit)} bdinvers:sv_cotitular SET numcte = pClienteTitular WHERE empresa='001' AND cuenta = vc_Cuenta;
        END FOREACH;  
    --******************SD_ENCABEZADO_EDOCTACRD ************************************************
    --******************************************************************************************
    SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT {+INDEX (bdicred:sd_encabezado_edoctacrd id_encabezado_fecha_tarjeta)} num_credito,fecha_emision INTO vc_Cuenta,vd_fecha_mov FROM bdicred:sd_encabezado_edoctacrd WHERE numcte = pClienteTraspasaCtas

            LET vc_proceso='SD_ENCABEZADO_EDOCTACRD';
            LET vc_tabla = "sd_encabezado_edoctacrd";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTitular)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusencabezado_edoctacrd
            SELECT {+INDEX (bdicred:sd_encabezado_edoctacrd id_encabezado_fecha_tarjeta)} * FROM bdicred:sd_encabezado_edoctacrd WHERE num_credito= vc_Cuenta AND fecha_emision=vd_fecha_mov;

            UPDATE {+INDEX (bdicred:sd_encabezado_edoctacrd id_encabezado_fecha_tarjeta)} bdicred:sd_encabezado_edoctacrd SET numcte = pClienteTitular WHERE num_credito= vc_Cuenta AND fecha_emision=vd_fecha_mov;
        END FOREACH;  
    --******************INICIA TRASPASO DE ACLARACIONES ****************************************
    --******************************************************************************************
        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT {+INDEX (bdiaclaracion:acl_cliente 114_31)} pky_cliente INTO vi_secuencia FROM bdiaclaracion:acl_cliente WHERE numero=pClienteTraspasaCtas 

            LET vc_proceso='ACLARACIONES';
            LET vc_tabla = "acl_cliente";
            LET vc_detalle_mov = TRIM(pClienteTitular)||'|'||vi_secuencia||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusaclcliente
            SELECT {+INDEX (bdiaclaracion:acl_cliente 114_31)} * FROM bdiaclaracion:acl_cliente WHERE pky_cliente= vi_secuencia;

            UPDATE {+INDEX (bdiaclaracion:acl_cliente 114_31)} bdiaclaracion:acl_cliente SET numero = pClienteTitular WHERE pky_cliente= vi_secuencia; 
        END FOREACH;  
    --******************INICIA TRASPASO DE CASOS ESPECIALES ************************************
    --******************************************************************************************
        IF EXISTS (SELECT {+INDEX (bdinteg:si_ctessitesp marcamen)} keyx FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTitular) THEN
            SET ISOLATION TO DIRTY READ;
            FOREACH
                SELECT {+INDEX (bdinteg:si_ctessitesp marcamen)} keyx INTO vi_num_serial FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTraspasaCtas

                LET vc_proceso='RESPALDO CASOS ESPECIALES';
                LET vc_tabla = "si_ctessitesp";
                LET vc_detalle_mov = TRIM(pClienteTitular)||'|'||vi_num_serial||'|'||TRIM(pClienteTraspasaCtas);   
                INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

                INSERT INTO bdinteg:si_fusctessitesp 
                SELECT {+INDEX (bdinteg:si_ctessitesp marcamen)} * FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTraspasaCtas;

                DELETE {+INDEX (bdinteg:si_ctessitesp marcamen)} FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTraspasaCtas;
            END FOREACH;
        ELSE
            SET ISOLATION TO DIRTY READ;
            FOREACH
                SELECT {+INDEX (bdinteg:si_ctessitesp marcamen)} keyx INTO vi_num_serial FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTraspasaCtas

                LET vc_proceso='CASOS ESPECIALES';
                LET vc_tabla = "si_ctessitesp";
                LET vc_detalle_mov = TRIM(pClienteTitular)||'|'||vi_num_serial||'|'||TRIM(pClienteTraspasaCtas);   
                INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

                INSERT INTO bdinteg:si_fusctessitesp 
                SELECT {+INDEX (bdinteg:si_ctessitesp marcamen)} * FROM bdinteg:si_ctessitesp WHERE numcliente = pClienteTraspasaCtas;

                UPDATE {+INDEX (bdinteg:si_ctessitesp marcamen)} bdinteg:si_ctessitesp SET numcliente=pClienteTitular WHERE numcliente = pClienteTraspasaCtas;
            END FOREACH;    
        END IF;

END FOREACH;  


   --******************INICIA TRASPASO DE EDO CTA**********************************************
    --******************************************************************************************
SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} DISTINCT TRIM(cliente_tit),TRIM(cliente_tras),SUBSTR(detalle_mov,1,11) INTO pClienteTitular,pClienteTraspasaCtas,vc_Cuenta2 FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>'' and tabla='sc_maechq'

        SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT aniomes INTO vc_aniomes FROM bdicheq:sc_maehis WHERE cuenta = vc_Cuenta2 AND empresa='001'

            LET vc_proceso='ESTADO DE CUENTA';
            LET vc_tabla = "sc_maehis";
            LET vc_detalle_mov = TRIM(vc_Cuenta2)||'|'||vc_aniomes||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusmaehis 
            SELECT {+INDEX (bdicheq:sc_maehis idx_maehis1)} * FROM bdicheq:sc_maehis WHERE empresa='001' AND aniomes=vc_aniomes AND cuenta = vc_Cuenta2;     
		
            UPDATE {+INDEX (bdicheq:sc_maehis idx_maehis1)} bdicheq:sc_maehis SET num_cte = pClienteTitular WHERE empresa='001' AND aniomes=vc_aniomes AND cuenta = vc_Cuenta2;  
        END FOREACH;  
END FOREACH;
   --******************INICIA TRASPASO DE EDO CTA**********************************************
    --******************************************************************************************

SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} TRIM(cliente_tit),TRIM(cliente_tras),SUBSTR(detalle_mov,26,16)  INTO pClienteTitular,pClienteTraspasaCtas,vc_Cuenta2 FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>'' AND proceso='TARJETAS CREDITO'
    SET ISOLATION TO DIRTY READ;
        FOREACH
            SELECT {+INDEX (bdicred:sd_encabezado_edocta td_encabezado_tarjeta)} num_credito INTO vc_Cuenta FROM bdicred:sd_encabezado_edocta WHERE num_tarjeta=vc_Cuenta2

            LET vc_proceso='SD_ENCABEZADO_EDOCTA';
            LET vc_tabla = "sd_encabezado_edocta";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas)||'|'||TRIM(vc_Cuenta2);   
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fusencabezado_edocta
            SELECT {+INDEX (bdicred:sd_encabezado_edocta td_encabezado_tarjeta)} * FROM bdicred:sd_encabezado_edocta WHERE num_tarjeta=vc_Cuenta2;

            UPDATE {+INDEX (bdicred:sd_encabezado_edocta td_encabezado_tarjeta)} bdicred:sd_encabezado_edocta SET numcte = pClienteTitular WHERE num_tarjeta=vc_Cuenta2;
        END FOREACH;
END FOREACH;

    IF vc_CodRet = "00000" THEN
        RETURN vc_CodRet, vc_Mensaje;
    END IF;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_refdirecciones(
                                                            sNumCte       CHAR(20),
                                                            sSecuencia    INTEGER
                                                            )
               RETURNING CHAR(5), CHAR(20), INTEGER, CHAR(1), CHAR(40), CHAR(60), CHAR(40), CHAR(3), CHAR(2), CHAR(3), 
                                        CHAR(5), CHAR(5), CHAR(11), CHAR(1), CHAR(13), CHAR(1), CHAR(13), CHAR(1), CHAR(13), CHAR(5), 
                                        CHAR(2), CHAR(3), CHAR(4), INTEGER, CHAR(10), CHAR(10), CHAR(6), INTEGER, INTEGER, CHAR(1), 
                                        CHAR(1), INTEGER, INTEGER, INTEGER, INTEGER, INTEGER, INTEGER, INTEGER, CHAR(80), CHAR(20),
                                        CHAR(8), DATE, CHAR(1), CHAR(1), CHAR(1);

--DOCUMENTACION:
--Realizó: Daniela Ramírez
--Fecha: 02/06/2011
--Funcionalidad: Consulta la tabla si_refdirecciones la cual regresa los datos de la direccion de la referencia.

-- Se definen variables
DEFINE cCodRet     CHAR(5);
DEFINE iSqlErr     INTEGER;

--Se definen variables de la tabla si_refdirecciones
DEFINE cNumcte CHAR(20);
DEFINE iSecuencia INTEGER;
DEFINE cTipo_dir CHAR(1);
DEFINE cCalle CHAR(40);
DEFINE cColonia CHAR(60);
DEFINE cEntre_calles CHAR(40);
DEFINE cPais CHAR(3);
DEFINE cEstado CHAR(2);
DEFINE cCiudad CHAR(3);
DEFINE cMunicipio CHAR(5);
DEFINE cCod_postal CHAR(5);
DEFINE cApart_postal CHAR(11);
DEFINE cTipo_telef1 CHAR(1);
DEFINE cTelefono1 CHAR(13);
DEFINE cTipo_telef2 CHAR(1);
DEFINE cTelefono2 CHAR(13);
DEFINE cTipo_telef3 CHAR(1);
DEFINE cTelefono3 CHAR(13);
DEFINE cExtension CHAR(5);
DEFINE cEstado_inegi CHAR(2);
DEFINE cMunicipio_inegi CHAR(3);
DEFINE cLocalidad_inegi CHAR(4);
DEFINE iNumerociudad INTEGER;
DEFINE cNumeroextcalle CHAR(10);
DEFINE cNumerointcalle CHAR(10);
DEFINE cDepartamento CHAR(6);
DEFINE iNumerocalle INTEGER;
DEFINE iNumerocolonia INTEGER;
DEFINE cPuntocardinal CHAR(1);
DEFINE cUnidadhabitac CHAR(1);
DEFINE iManzana INTEGER;
DEFINE iOtros INTEGER;
DEFINE iAndador INTEGER;
DEFINE iEtapa INTEGER;
DEFINE iLote INTEGER;
DEFINE iEdificio INTEGER;
DEFINE iEntrada INTEGER;
DEFINE cObservaciones CHAR(80);
DEFINE cNumcte_banco CHAR(20);
DEFINE cUser_insert CHAR(8);
DEFINE cFecha_insert DATE;
DEFINE cInd_cofeteltel1 CHAR(1);
DEFINE cInd_cofeteltel2 CHAR(1);
DEFINE cInd_cofeteltel3 CHAR(1);


-- Se inicializan variables
LET cCodRet = "00000";
LET iSqlErr = 0;
-- Se inicializan variables tabla si_refdirecciones
LET cNumcte = ' ';
LET iSecuencia = 0;
LET cTipo_dir = ' ';
LET cCalle = ' ';
LET cColonia = ' ';
LET cEntre_calles = ' ';
LET cPais = ' ';
LET cEstado = ' ';
LET cCiudad = ' ';
LET cMunicipio = ' ';
LET cCod_postal = ' ';
LET cApart_postal = ' ';
LET cTipo_telef1 = ' ';
LET cTelefono1 = ' ';
LET cTipo_telef2 = ' ';
LET cTelefono2 = ' ';
LET cTipo_telef3 = ' ';
LET cTelefono3 = ' ';
LET cExtension = ' ';
LET cEstado_inegi = ' ';
LET cMunicipio_inegi = ' ';
LET cLocalidad_inegi = ' ';
LET iNumerociudad = 0;
LET cNumeroextcalle = ' ';
LET cNumerointcalle = ' ';
LET cDepartamento = ' ';
LET iNumerocalle = 0;
LET iNumerocolonia = 0;
LET cPuntocardinal = ' ';
LET cUnidadhabitac = ' ';
LET iManzana = 0;
LET iOtros = 0;
LET iAndador = 0;
LET iEtapa = 0;
LET iLote = 0;
LET iEdificio = 0;
LET iEntrada = 0;
LET cObservaciones = ' ';
LET cNumcte_banco = ' ';
LET cUser_insert  = ' ';
LET cFecha_insert = DATE(1);
LET cInd_cofeteltel1 = ' ';
LET cInd_cofeteltel2 = ' ';
LET cInd_cofeteltel3 = ' ';

--        SET DEBUG FILE TO "/respaldosbd/Daniela/sp_consulta_refdirecciones.out";
--        TRACE ON;
		
BEGIN

    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            RETURN cCodRet, cNumcte, iSecuencia, cTipo_dir, cCalle, cColonia, cEntre_calles, cPais, cEstado, cCiudad, cMunicipio, cCod_postal, 
                            cApart_postal, cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, cExtension, cEstado_inegi, 
                            cMunicipio_inegi, cLocalidad_inegi, iNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, iNumerocalle, 
                            iNumerocolonia, cPuntocardinal, cUnidadhabitac, iManzana, iOtros, iAndador, iEtapa, iLote,iEdificio, iEntrada, cObservaciones, 
                            cNumcte_banco, cUser_insert, cFecha_insert , cInd_cofeteltel1, cInd_cofeteltel2, cInd_cofeteltel3;
        END IF;
    END EXCEPTION;

    SET LOCK MODE TO WAIT 3;

    IF (sNumCte <> ' ' AND sNumCte IS NOT NULL) THEN

            SELECT numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, tipo_telef1, 
                           telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, 
                           numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, otros, 
                           andador, etapa, lote, edificio, entrada, observaciones, numcte_banco, user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, 
                           ind_cofeteltel3
                 INTO cNumcte, iSecuencia, cTipo_dir, cCalle, cColonia, cEntre_calles, cPais, cEstado, cCiudad, cMunicipio, cCod_postal, cApart_postal, 
                           cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, cExtension, cEstado_inegi, cMunicipio_inegi, 
                           cLocalidad_inegi, iNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, iNumerocalle, iNumerocolonia, 
                           cPuntocardinal, cUnidadhabitac, iManzana, iOtros, iAndador, iEtapa, iLote, iEdificio, iEntrada, cObservaciones, cNumcte_banco,
                           cUser_insert, cFecha_insert , cInd_cofeteltel1, cInd_cofeteltel2, cInd_cofeteltel3
               FROM bdinteg:"informix".si_refdirecciones
            WHERE numcte = sNumCte 
                 AND  secuencia = sSecuencia;

           LET cCodRet = "00000"; -- Realiza consulta

   ELSE

            LET cCodRet = "00001";  -- Los parametros que se mandaron son incorrectos

   END IF;

        RETURN cCodRet, cNumcte, iSecuencia, cTipo_dir, cCalle, cColonia, cEntre_calles, cPais, cEstado, cCiudad, cMunicipio, cCod_postal, 
                        cApart_postal, cTipo_telef1, cTelefono1, cTipo_telef2, cTelefono2, cTipo_telef3, cTelefono3, cExtension, cEstado_inegi, 
                        cMunicipio_inegi, cLocalidad_inegi, iNumerociudad, cNumeroextcalle, cNumerointcalle, cDepartamento, iNumerocalle, 
                        iNumerocolonia, cPuntocardinal, cUnidadhabitac, iManzana, iOtros, iAndador, iEtapa, iLote,iEdificio, iEntrada, cObservaciones, 
                        cNumcte_banco, cUser_insert, cFecha_insert , cInd_cofeteltel1, cInd_cofeteltel2, cInd_cofeteltel3;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generaarchivoconsultarespuestaburo(p_Empresa CHAR(3), p_TipoMov1 CHAR(2), p_TipoMov2 CHAR(2))
RETURNING
     CHAR(5); ---cod_ret

    DEFINE v_cod_ret            CHAR(5);
    DEFINE iSqlErr              INTEGER;
    DEFINE iSamErr              INTEGER;
	DEFINE vDesErr              CHAR(60);

	DEFINE v_Sucursal		    CHAR(4);
	DEFINE sTiendaFolio			SMALLINT;
	DEFINE v_CteNomUno		    CHAR(26);
	DEFINE v_CteNomDos		    CHAR(26);
	DEFINE v_CteApePat		    CHAR(26);
	DEFINE v_CteApeMat		    CHAR(26);
	DEFINE v_CteBancoppel		CHAR(20);
	DEFINE v_Consulta			LVARCHAR (32000);
	DEFINE v_Idburo				CHAR(1);
	DEFINE v_FechaConsulta		DATE;
	DEFINE v_Trama				LVARCHAR (32000);
	DEFINE v_Respuesta			LVARCHAR(4005);
	DEFINE vFecha_Hoy 			DATE;
	DEFINE vnumcte 				CHAR(20);
	DEFINE v_NumSol				CHAR(20);
	DEFINE iSecuencia			INTEGER;
	DEFINE cFec_Consult			CHAR(10);

	LET v_Sucursal		    = '';
	LET sTiendaFolio		= 0 ;
	LET v_CteNomUno		    = '';
	LET v_CteNomDos		    = '';
	LET v_CteApePat		    = '';
	LET v_CteApeMat		    = '';
	LET v_CteBancoppel		= '';
	LET v_Consulta			= '';
	LET v_Idburo			= '';
	LET v_FechaConsulta		= DATE(1);
	LET v_Trama				= '';
	LET v_Respuesta			= '';
	LET vFecha_Hoy 			= DATE(1);
	LET vnumcte				= '';
	LET v_NumSol 			= '';
	LET cFec_Consult		= '19000101';
	
	SET LOCK MODE TO WAIT 10;

BEGIN

    ON EXCEPTION
        SET iSqlErr, iSamErr
        IF iSqlErr <> 0 THEN
                LET v_cod_ret = iSqlErr;
                EXECUTE PROCEDURE bdinteg:"informix".sp_desc_ret(20, v_cod_ret)
                INTO v_cod_ret, vDesErr;
        END IF;
        RETURN v_cod_ret;
    END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;
	
	--SET DEBUG FILE TO "/tmp/sp_GeneraArchivoConsultaRespuestaBuro.out";
    --TRACE ON;

	LET v_cod_ret = '00000';
	LET vDesErr = '';
	
	SELECT fecha_hoy INTO vFecha_Hoy FROM bdinteg:"informix".si_fechas;

	IF (p_Empresa IS NULL OR p_Empresa = '')  THEN 
		RETURN '00001';
	ELSE
	
		IF(p_TipoMov1 IS NOT NULL AND p_TipoMov1 <> '')  THEN 
			---BURO CONSULTA - BC
			FOREACH
				SELECT {+INDEX(bdinteg:"informix".si_adiccoppel idx_adiccoppel)} a.numcte--, TRIM(ss.sucursal), ss.num_solicitud 
				INTO vnumcte--, v_Sucursal, v_NumSol
				FROM bdinteg:"informix".si_cliente a, bdinteg:"informix".si_adiccoppel b--, bdisolic:"informix".ss_solicitudes ss
				WHERE a.fecha_insert = vFecha_Hoy 
				AND a.numcte_ref = b.numctecoppel AND a.numcte = b.numcte AND a.empresa = b.empresa
				AND b.empresa = p_Empresa AND b.secuencia = 1 AND b.numcte = b.numcte AND b.sucursal = b.sucursal 
				
				SELECT ss.sucursal,ss.sucursal::SMALLINT, ss.num_solicitud 
				INTO v_Sucursal, sTiendaFolio, v_NumSol
				FROM bdisolic:"informix".ss_solicitudes ss
				WHERE ss.numcte = vnumcte AND ss.status_solicitud = 'BC';
				
				IF NVL(v_NumSol, '') <> '' THEN 
					
					SELECT TRIM(numcte), TRIM(nombre1), TRIM(nombre2) , TRIM(apell_paterno) , TRIM(apell_materno)
					INTO  v_CteBancoppel, v_CteNomUno, v_CteNomDos, v_CteApePat, v_CteApeMat
					FROM bdinteg:"informix".si_cliente
					WHERE empresa = p_Empresa AND numcte = vnumcte;
					
					SELECT (envio||envio1||envio2),'1', fecha_insert
					INTO v_Consulta,v_Idburo, v_FechaConsulta
					FROM bdiburo:"informix".br_traslado
					WHERE num_solicitud = v_NumSol AND (envio IS NOT NULL OR envio <> "") 
					AND (envio1 IS NOT NULL OR envio1 <> "") AND (envio2 IS NOT NULL OR envio2 <> "");
					
					LET cFec_Consult = YEAR(v_FechaConsulta)||""||LPAD(MONTH(v_FechaConsulta),2,0)||""||LPAD(DAY(v_FechaConsulta),2,0);
													
					IF EXISTS (SELECT 1 FROM bdinteg:"informix".si_archivoscoppelhistorial WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
						IF EXISTS (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} 1 FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
							LET iSecuencia = (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} MAX(secuencia) + 1  FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						ELSE
							LET iSecuencia = (SELECT NVL(MAX(secuencia), 0) + 1  FROM bdinteg:"informix".si_archivoscoppelhistorial WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						END IF;
					ELSE
						IF EXISTS (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} 1 FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
							LET iSecuencia = (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} MAX(secuencia) + 1  FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						ELSE
							LET iSecuencia = 1;
						END IF;
					END IF;
					
					LET v_Trama = sTiendaFolio|| " 	 "||v_CteNomUno|| " 	 "||v_CteNomDos|| " 	 "||v_CteApePat|| " 	 "||v_CteApeMat|| " 	 "||v_CteBancoppel|| " 	 "||v_Consulta|| " 	 "||v_Idburo|| " 	 "||TRIM(NVL(cFec_Consult, '19000101'));
					LET v_Trama =  NVL(v_Trama,'');
					
					INSERT  INTO  bdinteg:"informix". si_archivoscoppeldiario  (empresa,secuencia,sucursal,trama,tipomovto,fecha_insert)
					VALUES (p_Empresa,iSecuencia,v_Sucursal,v_Trama,p_TipoMov1,current);
				END IF;
			END FOREACH
		ELSE
			RETURN '00001';
		END IF

		IF (p_TipoMov2 IS NOT NULL AND p_TipoMov2 <> '')  THEN 
			---BURO RESPUESTA - BR    
			FOREACH
				SELECT {+INDEX(bdinteg:"informix".si_adiccoppel idx_adiccoppel)} a.numcte--, TRIM(ss.sucursal), ss.num_solicitud 
				INTO vnumcte--, v_Sucursal, v_NumSol
				FROM bdinteg:"informix".si_cliente a, bdinteg:"informix".si_adiccoppel b--, bdisolic:"informix".ss_solicitudes ss
				WHERE a.fecha_insert = vFecha_Hoy 
				AND a.numcte_ref = b.numctecoppel AND a.numcte = b.numcte AND a.empresa = b.empresa
				AND b.empresa = p_Empresa AND b.secuencia = 1 AND b.numcte = b.numcte AND b.sucursal = b.sucursal 

				SELECT TRIM(ss.sucursal), ss.sucursal::SMALLINT, ss.num_solicitud 
				INTO v_Sucursal, sTiendaFolio, v_NumSol
				FROM bdisolic:"informix".ss_solicitudes ss
				WHERE ss.numcte = vnumcte AND ss.status_solicitud IN ('RT', 'AT', 'EE', 'CC', 'AP');
				
				IF NVL(v_NumSol, '') <> '' THEN 			

					SELECT TRIM(numcte), TRIM(nombre1), TRIM(nombre2) , TRIM(apell_paterno) , TRIM(apell_materno)
					INTO v_CteBancoppel, v_CteNomUno, v_CteNomDos, v_CteApePat, v_CteApeMat
					FROM bdinteg:"informix".si_cliente
					WHERE empresa = p_Empresa AND numcte = vnumcte;
					
					SELECT regreso, '1'
					INTO  v_Respuesta, v_Idburo
					FROM  bdiburo:"informix".sb_regreso 
					WHERE  num_solicitud = v_NumSol;
					
					LET v_FechaConsulta = CURRENT;
					
					LET cFec_Consult = YEAR(v_FechaConsulta)||""||LPAD(MONTH(v_FechaConsulta),2,0)||""||LPAD(DAY(v_FechaConsulta),2,0);
					
					IF EXISTS (SELECT 1 FROM bdinteg:"informix".si_archivoscoppelhistorial WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
						IF EXISTS (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} 1 FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
							LET iSecuencia = (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} MAX(secuencia) + 1  FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						ELSE
							LET iSecuencia = (SELECT NVL(MAX(secuencia), 0) + 1  FROM bdinteg:"informix".si_archivoscoppelhistorial WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						END IF;
					ELSE
						IF EXISTS (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} 1 FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO') THEN
							LET iSecuencia = (SELECT {+INDEX(bdinteg:"informix".si_archivoscoppeldiario idxr_archcoptipmovto)} MAX(secuencia) + 1  FROM bdinteg:"informix".si_archivoscoppeldiario WHERE empresa = p_Empresa AND tipomovto <> 'TO');
						ELSE
							LET iSecuencia = 1;
						END IF;
					END IF;
					
					LET v_Trama = sTiendaFolio|| " 	 "||v_CteNomUno|| " 	 "||v_CteNomDos|| " 	 "||v_CteApePat|| " 	 "||v_CteApeMat|| " 	 "||v_CteBancoppel|| " 	 "||""|| " 	 "||v_Respuesta|| " 	 "||v_Idburo|| " 	 "||TRIM(NVL(cFec_Consult, '19000101'));
					LET v_Trama =  NVL(v_Trama,'');
					
					INSERT INTO bdinteg:"informix".si_archivoscoppeldiario  (empresa,secuencia,sucursal,trama,tipomovto,fecha_insert)
					VALUES (p_Empresa,iSecuencia,v_Sucursal,v_Trama,p_TipoMov2,current);
				END IF;	
			END FOREACH
		ELSE
			RETURN '00001';
		END IF
	END IF
	
	RETURN v_cod_ret;

END;
--##############################################################################
--## Procedimiento  : "informix".sp_GeneraArchivoConsultaRespuestaBuro
--## Version        : 1.0
--## Creado por     : Mohamed Carreón
--## Fecha creacion : Diciembre de 2008
--##Descripcion 	: Realiza la extraccion de datos para la Consulta y Respuesta del buro.
--##############################################################################
--##Modificado por  : Adrian Lara
--##Fecha Modifica  : Junio de 2011
--##Descripción     : Se generan archivos, se agreagan nuevas consultas y correcciones en la trama de datos.
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtieneescolaridad(cnumcte CHAR(20),cStatusSolicitud CHAR(2))
		RETURNING CHAR(6),CHAR(1);
	
--DEFINICION DE VARIABLES 
DEFINE  cCodRet 					CHAR(5);
DEFINE  iSqlErr 					INTEGER;
DEFINE  cNumerosolicituddecredito 	CHAR(20);
DEFINE  iElementoScoring 			INTEGER;
DEFINE  cDescripElemento 			CHAR(50);
DEFINE  cEscolaridad 				CHAR(1);

--INICIALIZACION DE VARIABLES
LET cCodRet = '000000';
LET cNumerosolicituddecredito = '';
LET iElementoScoring = 0;
LET cDescripElemento = '';
LET cEscolaridad = '';
	
--SET DEBUG FILE TO "/tmp/sp_ObtieneEscolaridad.out";
--TRACE ON;
BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet,'';
		END IF;
	END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;
	
	IF cnumcte IS NOT NULL OR cnumcte <> "" THEN
		--OBTENER FECHA Y NUMERO DE SOLICITUD
		SELECT	num_solicitud
		INTO	cNumerosolicituddecredito
		FROM	bdisolic:"informix".ss_solicitudes
		WHERE	numcte = cnumcte AND num_producto = '6500';
		
		--Para obtener elemento
		SELECT	elemento  
		INTO	iElementoScoring 
		FROM	bdisolic:"informix".ss_detalle_scoring 
		WHERE	grupo = '21' AND num_solicitud = cNumerosolicituddecredito;
		
		--Para buscar descripcion de elemento 
		SELECT	descripcion
		INTO	cDescripElemento  
		FROM	bdisolic:"informix".ss_scoring_element 
		WHERE	elemento = iElementoScoring AND	grupo = '21' AND activa = 1;
		
		IF cDescripElemento = "No Estudió" THEN
			LET cEscolaridad = '1';
		END IF;
		
		IF cDescripElemento = "Primaria" THEN
			LET  cEscolaridad = '2';
		END IF;
		
		IF cDescripElemento = "Secundaria" THEN
			LET cEscolaridad = '3';
		END IF;
		
		IF cDescripElemento = "Carrera Técnica" THEN
			LET cEscolaridad = '4';
		END IF;
		
		IF cDescripElemento = "Preparatoria" THEN
			LET cEscolaridad = '5';
		END IF;
		
		IF cDescripElemento = "Licenciatura o Superior" THEN
			LET cEscolaridad = '6'; 
		END IF;
	ELSE
		RETURN '000001',NVL(cEscolaridad,'2');
	END IF;
	RETURN cCodRet, NVL(cEscolaridad,'2');
END;
--*************************************************************************
--| Procedimiento   : sp_ObtieneEscolaridad
--| Versión         : 1.0
--| Creado por      : Martha Aguirre
--| Fecha creacion  : Noviembre de 2008
--| Descripción     : Obtiene la escolaridad del cliente 
--*************************************************************************
--| Modificado por  : Adrian Lara
--| Fecha creacion  : Octubre de 2011
--| Descripción     : Se quita la contulsa de la solicitud de credito por el estatus.
--*************************************************************************
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscactecoppel(p_sNumCteCoppel CHAR(20), p_Tipo CHAR(1))

RETURNING CHAR(5), INTEGER;

DEFINE viSqlErr INTEGER;
DEFINE vsCodRet CHAR(5);
DEFINE v_iSecuencia INTEGER;

--****************************************************************************************************
-- DESCRIPCION: Busca Clientes Coppel.
-- AUTOR : Marcos Cuevas
-- FECHA : 09/03/2009
-- SISTEMA : Caja Unica
--****************************************************************************************************

LET viSqlErr = 0;
LET vsCodRet = '00000';
LET v_iSecuencia = 0;


--set debug file to "/tmp/sp_BuscaCteCoppel.out";
--Trace on;

SET LOCK MODE TO WAIT 3;

BEGIN

ON EXCEPTION SET viSqlErr   --cacha el error en caso de que exista y regresa un valor predeterminado
    IF viSqlErr <> 0 THEN
	RETURN viSqlErr,0;
	END IF;
END EXCEPTION;

--Valida que el cliente exista, si existe consulta los datos requeridos sino manda el codigo de retorno 1

	IF p_Tipo = 1 THEN
		IF EXISTS ( SELECT 1 FROM bdinteg:"informix".si_adiccoppel WHERE numcte = p_sNumCteCoppel AND SECUENCIA = 1) THEN
			LET v_iSecuencia = 1;
		ELSE
			LET vsCodRet = '00001';
		END IF;
	ELIF p_Tipo = 2 THEN
		IF EXISTS ( SELECT 1 FROM bdinteg:"informix".si_adiccoppel WHERE numcte = p_sNumCteCoppel AND SECUENCIA > 1) THEN
			LET v_iSecuencia = 2;
		ELSE
			LET vsCodRet = '00002';
		END IF
    ELSE
		
	END IF;

RETURN vsCodRet, v_iSecuencia;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_huellatitularadicionalcoppel(cEmpresa CHAR(3), cNumCte CHAR(20))
RETURNING
  CHAR(5)

    DEFINE cCodRet            CHAR(5);
    DEFINE iSqlErr            INTEGER;

	LET cCodRet = '000';
	LET iSqlErr = 0;
	
	SET LOCK MODE TO WAIT 3;

BEGIN
	ON EXCEPTION
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
        END IF;
        RETURN cCodRet;
    END EXCEPTION;

	--SET DEBUG FILE TO "/tmp/sp_CteTitularAdicionalCoppel.out";
    --TRACE ON;

	IF EXISTS(SELECT numcte FROM bdinteg:"informix".si_adiccoppel WHERE numcte = cNumCte AND secuencia = '1')  THEN
		LET cCodRet = '001';
	ELIF EXISTS(SELECT numcte FROM bdinteg:"informix".si_adiccoppel WHERE numcte = cNumCte AND secuencia > '1') THEN
		LET cCodRet = '002';
	END IF;

END;
--##############################################################################
--## Procedimiento   : sp_HuellaTitularAdicionalCoppel
--## Base de Datos   : bdinteg
--## Version         : 1.0
--## Creado por      : Frank Gaxiola
--## Fecha creacion  : Febrero de 2009
--##Descripcion      : Identifica si el cliente es titular o adicional de crédito coppel
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_insertavalidaadiccop(pEmpresa CHAR(3), pNumCteCop CHAR(20), pNumCteAdic CHAR(20), pParentesco CHAR(1), pTipo CHAR(1), pUserInsert CHAR(8))
RETURNING CHAR(6), SMALLINT;
--------------------------------------------------------------------------------------------------------------------------------
--30/12/2008
--Rodolfo Tortolero Varela
--Inserta y valida adicionales coppel
--------------------------------------------------------------------------------------------------------------------------------
--27/09/2011
--Rodolfo Tortolero Varela
--Valida cuantos adiccionales tiene el cliente, se agrega un parametro mas de salida para obtener el dato.
--------------------------------------------------------------------------------------------------------------------------------

--DEFINICION DE VARIABLES--
DEFINE iSqlErr INTEGER;
DEFINE vCodRet CHAR(6);
DEFINE dFechaMov DATE;
DEFINE iSecuencia SMALLINT;
DEFINE iTotalAdic SMALLINT;
DEFINE iSecuAdic SMALLINT;
DEFINE cSucursal CHAR(4);

--INICIALIZACION DE VARIABLES--
LET vCodRet = '003';
LET iSecuencia = 0;
LET iTotalAdic = 0;
LET iSecuAdic = 0;
LET cSucursal = '';

--SET debug FILE TO '/tmp/sp_InsertaValidaAdicCop.out';
--TRACE ON;

SET LOCK MODE TO WAIT 10;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET vCodRet = iSqlErr;
			RETURN vCodRet, iSecuAdic;
		END IF;
	END EXCEPTION;
	
	--SELECCIONA EL NUMERO DE ADICIONALES PERMITIDOS
	SELECT totadicional 
	INTO iTotalAdic 
	FROM "informix".si_catvalidaprod 
	WHERE producto = '6500';
	
	--SELECCIONA LA SECUENCIA MAXIMA DE ADICIONALES PERMITIDOS
	SELECT NVL(MAX(secuencia),0) 
	INTO iSecuencia
	FROM "informix".si_adiccoppel 
	WHERE numctecoppel = pNumCteCop; 
	
	-- SELECCIONA LA FECHA HOY
	SELECT fecha_hoy 
	INTO dFechaMov 
	FROM "informix".si_fechas;
	
	--Obtiene la Sucursal
	SELECT sucursal
	INTO cSucursal
	FROM bdinteg:"informix".si_adiccoppel
	WHERE numctecoppel = pNumCteCop 
	AND secuencia = 1;
	
	SELECT COUNT(*) INTO iSecuAdic FROM "informix".si_adiccoppel WHERE numctecoppel = pNumCteCop AND tipotar <> 1;
	
	IF pTipo = 1 THEN
		IF EXISTS (SELECT 1 FROM "informix".si_adiccoppel WHERE numctecoppel = pNumCteCop AND numcte = pNumCteAdic AND secuencia <> 1) THEN 
			LET vCodRet = '001';	--"El cliente ya existe como adicional de la cuenta"
		ELSE
			IF iSecuencia >= iTotalAdic THEN
				LET vCodRet = '002';	--"La cuenta ya cuenta con los adicionales permitidos"
			END IF;
		END IF;
	ELIF pTipo = 2 THEN
		LET iSecuencia = iSecuencia + 1; 
		INSERT INTO "informix".si_adiccoppel (empresa, numctecoppel, secuencia, sucursal, numtarcoppel, numcte, tipotar, status, parentesco, fechamov, user_insert)
		VALUES (pEmpresa, pNumCteCop, iSecuencia, cSucursal, pNumCteCop, pNumCteAdic, "2", "S", pParentesco, dFechaMov, pUserInsert);
		LET vCodRet = '000';
	END IF;
	
	RETURN vCodRet, iSecuAdic;
END;

END PROCEDURE;

