CREATE PROCEDURE "informix".sp_cancelartokensbloqueados(pNumCte CHAR(10),pNsToken CHAR(11),pStatus CHAR(3),pUsuario CHAR(10),pCanal CHAR(2))
   returning char(5);
   
    DEFINE vCod_ret char(5);
    DEFINE sql_err integer ;
	DEFINE vSolicitud CHAR(10);
	
	
    LET vCod_ret  = "00000";
    

	--****************************************************************************************************
	-- DESCRIPCION:  CANCELA LOS TOKEN CON ESTATUS 152 EN LA SI_BPITOKEN, ASI COMO ACTUALIZA TABLAS TKN_SERIES,Y BPI_TOKENSOLICITUD
	-- AUTOR : Francisco Rodríguez Ibarra
	-- FECHA : 06/09/2011
	-- BD: bdinteg
	-- SOLICITO :Mauricio León
	--***************************************************************************************************
	-- MODIFICACIÓN:  ACTUALIZA EL CAMPO TIPO = 5 EN LA TABLA bdibpi:"informix".bpi_tokensolicitud.
	-- AUTOR : José de Jesús Nevarez
	-- FECHA : 13/10/2011
	-- BD: bdinteg
	-- SOLICITO :Mauricio León
	--***************************************************************************************************
	-- MODIFICACIÓN:  ACTUALIZA EL CAMPO id_status_token = '199' EN LA TABLA bdinteg:"informix".si_bpitoken 
	-- AUTOR : José de Jesús Nevarez
	-- FECHA : 20/10/2011
	-- BD: bdinteg
	-- SOLICITO :Mauricio León
	--***************************************************************************************************

	
	--set debug file to "sp_cancelartokensbloqueados.out";
	--trace on;
   BEGIN
	

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let vCod_ret = sql_err;
            RETURN vCod_ret;
      END IF ;
   END EXCEPTION ;
		SET LOCK MODE TO WAIT ;
		SET ISOLATION DIRTY READ ;
		
		LET vCod_ret  = "00001";
		
		UPDATE bdinteg:"informix".si_bpitoken SET id_status_token = pStatus, f_status=current WHERE num_cliente = pNumCte;
		
		INSERT INTO  bdinteg:"informix".si_bpitokenhis(empresa, num_cliente, ns_token, suc_registro, folio_token, id_status_token, f_status, f_registro)
			SELECT empresa, num_cliente, ns_token, suc_registro, folio_token, id_status_token, f_status, f_registro
				FROM bdinteg:"informix".si_bpitoken 
				WHERE num_cliente = pNumCte AND ns_token=pNsToken;
		
		LET vCod_ret  = "00002";
		DELETE 	FROM  bdinteg:"informix".si_bpitoken WHERE num_cliente = pNumCte AND ns_token=pNsToken;
		
		LET vCod_ret  = "00003";
		UPDATE bdibpi:"informix".bpi_tokensolicitud SET id_status = pStatus, f_atencion=CURRENT, tipo='5' WHERE numcte=pNumCte AND ns_token=pNsToken;
		
				
		LET vCod_ret  = "00004";
		SELECT solicitud  INTO vSolicitud  FROM bdibpi:"informix".bpi_tokensolicitud WHERE numcte=pNumCte AND ns_token=pNsToken;
		INSERT INTO bdibpi:"informix".tkn_stasolicitud (solicitud, anterior, actual, f_registro) VALUES (vSolicitud, '152', pStatus, CURRENT);

		UPDATE bdibpi:"informix".tkn_envios SET id_status = pStatus ,comentarios="El token ha sido cancelado por presentar 5 días hábiles bloqueado" WHERE solicitud=vSolicitud;
		
		LET vCod_ret  = "00005";
		UPDATE bdibpi:"informix".tkn_nseries SET id_status = pStatus ,f_status=CURRENT WHERE ns_token=pNsToken;
		
		LET vCod_ret  = "00006";
		INSERT INTO bdibpi:"informix".tkn_status_token (ns_token, actual, anterior, f_cambio_status, usr_cambio_status, canal) 
		VALUES (pNsToken, pStatus, '152',CURRENT, pUsuario, pCanal);
		
		LET vCod_ret  = "00007";
		
		RETURN vCod_ret;
	END;
END PROCEDURE
;

CREATE PROCEDURE "informix".sp_consulta_cat_ciudades(pEstado CHAR(2), pNombre CHAR(30))
RETURNING 	CHAR(6)   AS CodRetorno,
			      CHAR(3)   AS NumEdo,
			      CHAR(60)	AS NomEdo;

--Declaración de variables
DEFINE isqlerr    INTEGER;
DEFINE cCodRet    CHAR(6); 
DEFINE cNumCd			CHAR(3);
DEFINE cNombreCd	CHAR(60);
DEFINE iRegistro	INTEGER; 

--Asinación de valores
LET isqlerr     = 0;
LET cCodRet     = '000000';
LET cNumCd			= '';
LET cNombreCd		= '';
LET iRegistro		= 0;

--SET DEBUG FILE TO '/tmp/sp_consulta_cat_ciudades.out';
--TRACE ON;

BEGIN
--Control de errores
	ON EXCEPTION SET iSqlErr
	      LET cCodRet= iSqlErr;
	      RETURN cCodRet, cNumCd, cNombreCd;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;	
	
	IF pNombre = '' OR pNombre IS NULL THEN
	
		--Consulta TODOS LOS ESTADOS
		FOREACH 			
			
			SELECT ciudad, TRIM(nombre)
			INTO cNumCd, cNombreCd
			FROM bdinteg:"informix".si_ciudades
			WHERE estado= estado
			AND ciudad = ciudad
			AND estado = CASE WHEN pEstado = "" THEN estado  ELSE pEstado END
			ORDER BY nombre
			
			RETURN cCodRet, cNumCd, cNombreCd WITH RESUME;
			
		END FOREACH
		LET iRegistro = dbinfo("sqlca.sqlerrd2");		
		
	ELSE
		--Consulta POR NOMBRE DE ESTADOS
		FOREACH
		
			SELECT ciudad, TRIM(nombre)
			INTO cNumCd, cNombreCd
			FROM bdinteg:"informix".si_ciudades
			WHERE pais= '001'
			AND estado = pEstado
			AND ciudad = ciudad
			AND UPPER(TRIM(nombre)) LIKE CASE when pNombre = '' THEN UPPER(nombre) 
				   ELSE '%'||UPPER(TRIM(pNombre))||'%' END   
			ORDER BY nombre
						
			RETURN cCodRet, cNumCd, cNombreCd WITH RESUME;
			
		END FOREACH
		
		LET iRegistro = dbinfo("sqlca.sqlerrd2");				
	END IF		
	
	--Valida si se encontro información
	IF iRegistro = 0 THEN
		LET cCodRet = '000002'; --No hay información 
		RETURN cCodRet, cNumCd, cNombreCd;
	END IF;	
	
END;

END PROCEDURE
DOCUMENT
'Descripcion:  Consulta las ciudades del catalogo de ciudades',
'AUTOR :Abigail Vasavilbazo Cañedo',
'FECHA :Agosto/2011',
'BD    : BDINTEG',
'Version: 20110826.0958';

CREATE PROCEDURE "informix".sp_consulta_cat_estados(pNombre CHAR(30))
RETURNING 	CHAR(6)   AS CodRetorno,
			CHAR(2)  AS NumEdo,
			CHAR(30)	AS NomEdo;

--Declaración de variables
DEFINE isqlerr      	INTEGER;
DEFINE cCodRet     		CHAR(6); 
DEFINE cNumEstado		  CHAR(2);
DEFINE cNombreEdo		  CHAR(30);
DEFINE iRegistro		  INTEGER; 

--Asinación de valores
LET isqlerr     		= 0;
LET cCodRet     		= '000000';
LET cNumEstado			= '';
LET cNombreEdo			= '';
LET iRegistro			  = 0;

--SET DEBUG FILE TO '/tmp/sp_consulta_cat_estados.out';
--TRACE ON;

BEGIN
--Control de errores
	ON EXCEPTION SET iSqlErr
	      LET cCodRet= iSqlErr;
	      RETURN cCodRet, cNumEstado, cNombreEdo;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
  SET LOCK MODE TO WAIT 3;	
	
	IF pNombre = '' OR pNombre IS NULL THEN
	
		--Consulta TODOS LOS ESTADOS
		FOREACH 			
			
			SELECT estado, TRIM(nombre)
			INTO cNumEstado, cNombreEdo
			FROM bdinteg:"informix".si_estados
			ORDER BY estado
			
			RETURN cCodRet, cNumEstado, cNombreEdo WITH RESUME;
			
		END FOREACH
		LET iRegistro = dbinfo("sqlca.sqlerrd2");		
		
	ELSE
		--Consulta POR NOMBRE DE ESTADOS
		FOREACH
		
			SELECT estado, TRIM(nombre)
			INTO cNumEstado, cNombreEdo
			FROM bdinteg:"informix".si_estados
			WHERE  UPPER(TRIM(nombre)) LIKE CASE when pNombre = '' THEN UPPER(nombre) 
						ELSE '%'||UPPER(TRIM(pNombre))||'%' END   
			ORDER BY estado
						
			RETURN cCodRet, cNumEstado, cNombreEdo WITH RESUME;
			
		END FOREACH
		
		LET iRegistro = dbinfo("sqlca.sqlerrd2");				
	END IF		
	
	--Valida si se encontro información
	IF iRegistro = 0 THEN
		LET cCodRet = '000002'; --No hay información 
		RETURN cCodRet, cNumEstado, cNombreEdo;
	END IF;	
	
END;

END PROCEDURE
DOCUMENT
'Descripcion:  Consulta los estados del catalogo de estados',
'AUTOR :Abigail Vasavilbazo Cañedo',
'FECHA :Agosto/2011',
'BD    : BDINTEG',
'Version: 20110826.0959';

CREATE PROCEDURE "informix".sp_consulta_cat_zonas(pEstado CHAR(2), pCiudad CHAR(3), pNombre CHAR(32))
RETURNING 	CHAR(6)  AS CodRetorno,
			      INTEGER  AS NumZona,
			      CHAR(32) AS NomZona,
			      CHAR(5)	 AS CP;

--Declaración de variables
DEFINE isqlerr      	INTEGER;
DEFINE cCodRet     		CHAR(6); 
DEFINE iNumColonia		INTEGER;
DEFINE cNombreCol		  CHAR(32);
DEFINE cCP				    CHAR(5);
DEFINE iCiudadCoppel 	INTEGER; 
DEFINE iRegistro		  INTEGER; 

--Asinación de valores
LET isqlerr     		= 0;
LET cCodRet     		= '000000';
LET iNumColonia			= 0;
LET cNombreCol			= '';
LET cCP					    = '';
LET iCiudadCoppel		= 0;
LET iRegistro			  = 0;

--SET DEBUG FILE TO '/tmp/sp_consulta_cat_zonas.out';
--TRACE ON;

BEGIN
--Control de errores
	ON EXCEPTION SET iSqlErr
	      LET cCodRet= iSqlErr;
	      RETURN cCodRet, iNumColonia, cNombreCol, cCP;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
  SET LOCK MODE TO WAIT 3;	
	
	
	IF pEstado IS NULL OR pEstado= '' OR pCiudad IS NULL OR pCiudad= '' THEN
		LET cCodRet = '000001';
		RETURN cCodRet, iNumColonia, cNombreCol, cCP;
	END IF 		
	
	SELECT ciudad_coppel
	INTO iCiudadCoppel
	FROM bdinteg:"informix".si_ciudades
	WHERE estado=pEstado
	AND ciudad= pCiudad;	
	
	IF pNombre = '' OR pNombre IS NULL THEN
	
		--Consulta Colonias x Estado Y Ciudad
		FOREACH 			
			
			SELECT numerocolonia, TRIM(nombrezona), codigopostalzona
			INTO iNumColonia, cNombreCol, cCP
			FROM bdinteg:"informix".si_catzonas
			WHERE numerociudad= iCiudadCoppel
			ORDER BY nombrezona
			
			RETURN cCodRet, iNumColonia, cNombreCol, cCP WITH RESUME;
			
		END FOREACH
		LET iRegistro = dbinfo("sqlca.sqlerrd2");		
		
	ELSE
		--Consulta Colonias x Estado Y Ciudad y Nombre
		FOREACH
		
			SELECT numerocolonia, TRIM(nombrezona), codigopostalzona
			INTO iNumColonia, cNombreCol, cCP
			FROM bdinteg:"informix".si_catzonas
			WHERE numerociudad= iCiudadCoppel
			AND UPPER(TRIM(nombrezona)) LIKE CASE when pNombre = '' THEN UPPER(nombrezona)   ELSE '%'||UPPER(TRIM(pNombre))||'%' END   
			ORDER BY nombrezona
			
			RETURN cCodRet, iNumColonia, cNombreCol, cCP WITH RESUME;
			
		END FOREACH
		
		LET iRegistro = dbinfo("sqlca.sqlerrd2");				
	END IF		
	
	--Valida si se encontro información
	IF iRegistro = 0 THEN
		LET cCodRet = '000002'; --No hay información 
		RETURN cCodRet, iNumColonia, cNombreCol, cCP;
	END IF;	
	
END;

END PROCEDURE
DOCUMENT
'Descripcion:  Consulta las colonias por estado/ciudad',
'AUTOR :Abigail Vasavilbazo Cañedo',
'FECHA :Agosto/2011',
'BD    : BDINTEG',
'Version: 20110826.0959';

CREATE PROCEDURE "informix".sp_mail_enviavencidos(pempresa CHAR(3))
RETURNING CHAR(6);
--   execute PROCEDURE bdinteg:"informix".sp_mail_enviavencidos('001')

--Declaracion de variables
DEFINE sql_err				INTEGER;
DEFINE isam_err				INTEGER;
DEFINE error_info			CHAR(80);
DEFINE cMensaje				CHAR(80);
DEFINE cCod_ret				CHAR(6);
DEFINE cErrorInfo           CHAR(80);
DEFINE vempresa				CHAR(3);
DEFINE vproceso				CHAR(30);
DEFINE pusuario             CHAR(8);
DEFINE cruta                CHAR(100);
DEFINE cnombre				CHAR(100);
DEFINE cnomarchivo          CHAR(100);
DEFINE cnumcte              CHAR(20);
DEFINE cSQL                 CHAR(2204);
DEFINE cSQL1                CHAR(200);
DEFINE cSQL2                CHAR(2004);
DEFINE cSQL3                CHAR(2004);
DEFINE cSQL4                CHAR(100);
DEFINE cempresa             CHAR(3);
DEFINE vdia				    DATE;
DEFINE vhora				CHAR(8);
DEFINE ctipocampania        CHAR(1);
DEFINE cCod_RetIB           CHAR(6);
DEFINE vnumparametro        SMALLINT;
define cfor smallint;
define i integer;
define contar smallint;

    -- SET DEBUG FILE TO "/home/informix/Elizabeth/enviomail.out";
    --TRACE ON; 

--Inicialización de variables

LET sql_err                 = 0;
LET isam_err                = 0;
LET error_info              = "";
LET cCod_Ret                = "000000";
LET cMensaje                = 'PROCESO EXITOSO';
LET vproceso				= '2033';
LET vempresa				= '001';
LET pusuario                = USER;
LET cruta                   = "";
LET cnombre					= "";
LET cnomarchivo             = "";
LET cnumcte                 = "";
LET cSQL                    = "";
LET cSQL1                   = "";
LET cSQL2                   = "";
LET cSQL4                   = "";
LET cSQL3                   = "";
LET cempresa                = "001";
LET vdia				    = DATE(1);
LET vhora				    = "";
LET ctipocampania           = "";
LET cCod_RetIB              = "000000";
let contar = 0;


BEGIN
    ON EXCEPTION SET sql_err, isam_err, error_info
	        LET cCod_ret = sql_err;
            LET cMensaje = error_info;
            CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '02');
        RETURN cCod_ret;
	END EXCEPTION;

	--Directiva para lectura de tablas bloqueadas.
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
    CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');
	
	-- Validacion de parámetros de entrada  
	IF NVL(pEmpresa,"") = "" THEN
        LET cCod_Ret= "104001";
        SELECT descripcion
        INTO cMensaje
        FROM bdicobranza:"informix".cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret; 
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;

	
	IF NVL (pempresa, '') = '' THEN
        LET cCod_Ret= '104002';
        SELECT descripcion
        INTO cMensaje
        FROM bdicobranza:cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	
	--Obtener ruta del archivo
	SELECT TRIM(valor_alfabetico)
	INTO cruta
	FROM bdicobranza:cb_param_campania
	WHERE empresa = cempresa
	AND tipo_campania = 1
	AND grupo_parametro = 'ARCHIVOS'
	AND num_parametro = 38;	
	--Valida que exista la carpeta
	IF NVL (cruta,'') = '' THEN
        LET cCod_Ret= '104005';
        SELECT descripcion
        INTO cMensaje
        FROM bdicobranza:cb_errores
        WHERE origen = 3
        AND codigo_error = cCod_Ret;
	
        IF cMensaje IS NULL THEN 
            LET cMensaje = ""; 
        END IF;

        CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '01');
        Return cCod_Ret;
	END IF;
	
	execute PROCEDURE bdicobranza:"informix".sp_mail_cte_mora() into cCod_ret;
	
	FOR cfor IN (1 TO 5)
	
	select count(*) into contar from bdicobranza:cb_mail_cliente where tipo_mensaje = 1 and pagos_vencidos = cfor;
	if (contar <= 1000) then
		LET contar = 1;
	else
		LET contar = contar / 1000;
		let contar = (substr(contar, 0,1))+1;
	end if;
	
	FOR i in (1 to contar)
		
    LET cSQL1 = "echo '#!/bin/sh  \n" ;
	LET cSQL2 = "(sleep 1 \n" ||
                'echo "ehlo msgbancoppel.com" \n' ||
                "sleep 1 \n"||
                'echo "mail from:<cobranzabancoppel@msgbancoppel.com>" \n'||
                "sleep 1 \n"	||
                "while read line  \n"||
			    "do  \n"	||
			    'echo  " $line" \n' ||
			    "done < correos_mora"||cfor||i||".txt \n"||
                "sleep 1 \n"	||
                'echo "data" \n'||
                "sleep 1 \n" ||
                'echo "subject:Aviso Bancoppel" \n'||
				"sleep 1 \n"||
				"while read line \n"||
				"do \n"||
				'echo  "$line" \n'||
				"done < mora"||cfor||".txt \n"||
				"sleep 1 \n"|| 
                'echo "." \n'||
                "sleep 1 \n"|| 
                'echo "QUIT" \n'||
                ')|telnet 10.36.176.16 25 \n';
				
    
	LET cSQL3 = "'>"||TRIM(cRuta)||'Ejecuta_Shell'||cfor||i||'.sh';
	LET cSQL = trim(cSQL1) || trim(cSQL2) || trim(cSQL3);
  --insert into cb_bitacora (mensaje ) values ( cSQL);
	System cSQL;

    LET cSQL='chmod +x Ejecuta_Shell'||cfor||i||'.sh'; 
	System cSQL;
    let cSQL = './Ejecuta_Shell'||cfor||i||'.sh';
	System cSQL;
	
	--BORRA ARCHIVOS CORREOS_MORA  Y ARCHIVOS SHELL
	LET cSQL = '';
	LET cSQL = 'rm ' || TRIM(cruta) || 'Ejecuta_Shell'||cfor||i||'.sh';
	SYSTEM cSQL;
		
	LET cSQL = '';
	LET cSQL = 'rm ' || TRIM(cruta) || 'correos_mora'||cfor||i||'.txt';
	SYSTEM cSQL; 
	
	end for;
	
	END FOR;
	
	CALL bdicobranza:"informix".inserta_bitacora_cob(vempresa, vproceso, cCod_ret, cMensaje, '03');
	RETURN cCod_ret;
	
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generaboletoshistorico	(cEmpresa CHAR(3),
											cCve_Sorteo CHAR(5),
											iTipoOperacion CHAR(1),
											cFolioSucursal CHAR(16),
											dFechaMovimiento DATE,
											cNumCuenta CHAR(12),
											cNumCliente CHAR(9),
											cTipoSistema CHAR(1),
											siRegistros SMALLINT)
	RETURNING
	CHAR(5) AS CodRetorno, INTEGER AS Boleto, DATE AS Fecha, CHAR(9) AS NumCliente, CHAR(16) AS FolioSuc, INTEGER AS Importe;

--Definicion de Variables
DEFINE cCodRet    CHAR(5);
DEFINE cInfoErr   CHAR(200);
DEFINE cFolioSuc  CHAR(16);
DEFINE cNumCte    CHAR(9);
DEFINE dFecha_hoy DATE;
DEFINE dFecha_Reg DATE;
DEFINE iTipoOper  INTEGER;
DEFINE iSqlErr    INTEGER;
DEFINE iIsamErr   INTEGER;
DEFINE iMonto     INTEGER;
DEFINE siCiclo    SMALLINT;
DEFINE iBoletos_ini INTEGER;
DEFINE iBoletos_fin INTEGER;
DEFINE bFlag CHAR(1);
DEFINE dtFechaIni DATE;
DEFINE dtFechaFin DATE;
DEFINE sCve_Sorteo CHAR(5);
DEFINE dtFechaAux DATE;
DEFINE sCodRetAux CHAR(3);

DEFINE dtfecha_mov DATE;
DEFINE csucursal CHAR(4);
DEFINE mmonto DECIMAL (16,2);
DEFINE cfolio_suc CHAR(16);
DEFINE cnum_producto CHAR(4);

DEFINE cCodRet2 CHAR(5);
DEFINE cMensaje CHAR(80);
DEFINE iRangoIni INTEGER;
DEFINE iRangoFin INTEGER;



-- Inicializa variables
LET cCodRet = "00000";
LET cInfoErr = "";
LET cFolioSuc = "";
LET cNumCte = "";
LET dFecha_hoy = '01-01-1900';
LET dFecha_Reg = '01-01-1900';
LET iTipoOper = 0;
LET iSqlErr = 0;
LET iIsamErr = 0;
LET iMonto = 0;
LET siCiclo = 0;
LET iBoletos_ini = 0;
LET iBoletos_fin = 0;
LET bFlag = 'F';
LET dtFechaIni = CURRENT;
LET dtFechaFin = CURRENT;
LET sCve_Sorteo = '';
LET dtFechaAux = CURRENT;
LET sCodRetAux = '';

LET dtfecha_mov = '01/01/1900';
LET csucursal = '';
LET mmonto = 0.0;
LET cfolio_suc = '';
LET cnum_producto = '';

LET cCodRet2 = '';
LET cMensaje = '';
LET iRangoIni = 0;
LET iRangoFin = 0;


	--SET DEBUG FILE TO "/tmp/sp_GeneraBoletosHistorico.out";
	--TRACE ON;
	
	--Optimización al proceso de Reimpresión de Boletos se elimina la busqueda
	--en tablas de movimientos al dia(sc_movdia y sd_movdia), así como la
	--busqueda a la tabla si_boleto.   Raúl Ramírez

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;

	BEGIN
		ON EXCEPTION SET iSqlErr, iIsamErr, cInfoErr
			IF iSqlErr <> 0 THEN

				LET cCodRet = iSqlErr;
				-- verifica que tablas temporales se crearon para borrarlas
				IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames WHERE tabname = 'si_dispercionboletostmp') THEN
					DROP TABLE BdInteg:si_dispercionboletostmp;
				END IF;

				RETURN cCodRet, 0, '01/01/1900', '', '', 0;

			END IF;
		END EXCEPTION;

		IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames WHERE tabname = 'si_dispercionboletostmp') THEN
			DROP TABLE BdInteg:si_dispercionboletostmp;
		END IF;

		--CREA TABLA DE TRABAJO PARA LA DISPERCION DE LOS BOLETOS.
		CREATE TABLE BdInteg:si_dispercionboletostmp(
			Boleto INT8,
			F_Registro DATE,
			Numcte CHAR(9),
			FolioSuc CHAR(16),
			Importe MONEY(16,2));

		--OBTIENE LA FECHA DEL SISTEMA
		SELECT FIRST 1 fecha_hoy
          INTO dFecha_hoy
          FROM bdinteg:si_fechas;

		--OBTIENE LA FECHA DEL SORTEO REGISTRADO CON FECHA MAS RECIENTE DE INICIO
		SELECT FIRST 1 F_Ini::DATE, F_Fin::DATE, Cve_Sorteo
		  INTO dtFechaIni, dtFechaFin, sCve_Sorteo
		  FROM BdInteg:Si_Sorteo
		 WHERE Cve_Sorteo = cCve_Sorteo;

			IF (iTipoOperacion = '1') THEN -- FOLIO SUCURSAL

            --OBTIENE LOS REGISTROS DE LOS BOLETOS.
            FOREACH

				SELECT {INDEX (BdInteg:si_boleto_hist_index3)} boleto_ini, boleto_fin, f_registro::DATE, numcte,
                       foliosuc, importe
				  INTO iBoletos_ini, iBoletos_fin, dFecha_Reg, cNumCte, cFolioSuc, iMonto
				  FROM BdInteg:si_boleto_hist
				 WHERE cve_sorteo = sCve_Sorteo -- AND f_registro::DATE = dFechaMovimiento
				   AND numcte = cNumCliente AND estado = 2 AND foliosuc = cFolioSucursal
				ORDER BY boleto_ini

					WHILE (iBoletos_ini <= iBoletos_fin)
						--INSERTA BOLETO DISPERSADO
						INSERT INTO BdInteg:si_dispercionboletostmp (boleto, f_registro, numcte, foliosuc, importe)
							VALUES (iBoletos_ini, dFecha_Reg, cNumCte, cFolioSuc, iMonto);

						LET iBoletos_ini = iBoletos_ini + 1;
						LET bFlag = 'V';
					END WHILE;

			END FOREACH;

			ELIF (iTipoOperacion = '2') THEN -- NUM CUENTA / CREDITO

				IF (cTipoSistema = 'D') THEN --DEBITO
					SELECT FIRST 1 Num_Cte
                      INTO cNumCliente
                      FROM BdiCheq:SC_Maechq
                     WHERE Cuenta = cNumCuenta;
				ELIF (cTipoSistema = 'C') THEN --CREDITO
					SELECT FIRST 1 NumCte 
                      INTO cNumCliente 
                      FROM BdiCred:Sd_Maecred  
                     WHERE num_credito = cNumCuenta;
				END IF;

				LET dtFechaIni = NVL (dFechaMovimiento, dtFechaIni);

				--OBTIENE LOS REGISTROS DE LOS BOLETOS.
				FOREACH

    				SELECT {INDEX (BdInteg:si_boleto_hist_index3)} boleto_ini, boleto_fin, f_registro::DATE,
                            numcte, foliosuc, importe
				      INTO iBoletos_ini, iBoletos_fin, dFecha_Reg, cNumCte, cFolioSuc, iMonto
					  FROM BdInteg:si_boleto_hist
					 WHERE cve_sorteo = sCve_Sorteo -- AND f_registro::DATE = dtFechaIni
					   AND numcte = cNumCliente AND estado = 2 AND foliosuc <> ''
				     ORDER BY boleto_ini

					WHILE (iBoletos_ini <= iBoletos_fin)
						--INSERTA BOLETO DISPERSADO
						INSERT INTO BdInteg:si_dispercionboletostmp (boleto, f_registro, numcte, foliosuc, importe)
							VALUES (iBoletos_ini, dFecha_Reg, cNumCte, cFolioSuc, iMonto);

						LET iBoletos_ini = iBoletos_ini + 1;
						LET bFlag = 'V';
					END WHILE;

				END FOREACH;
			END IF;

			IF (bFlag = 'V') THEN --VALIDA KE LA TABLA CONTENGA REGISTROS DE BOLETOS

				--SKIP
				FOREACH SELECT boleto, f_registro, numcte, foliosuc, importe
					      INTO iBoletos_ini, dFecha_Reg, cNumCte, cFolioSuc, iMonto
                          FROM BdInteg:si_dispercionboletostmp
					     WHERE boleto >= 0 AND foliosuc > 0
					     ORDER BY boleto

					LET siCiclo = siCiclo + 1;
					IF siCiclo <= siRegistros THEN
						CONTINUE FOREACH;
					END IF;

					RETURN cCodRet, iBoletos_ini, dFecha_Reg, cNumCte, cFolioSuc, iMonto WITH RESUME;

				END FOREACH;

			ELIF (bFlag = 'F') THEN -- NO EXISTEN REG PARA LA CONSULTA
				RETURN '00004', 0, '01/01/1900', '', '', 0 WITH RESUME;
			END IF;

		-- BORRA LA TABLA DE TRABAJO
		IF EXISTS (SELECT dbsname, tabname FROM sysmaster:systabnames WHERE tabname = 'si_dispercionboletostmp') THEN
			DROP TABLE BdInteg:si_dispercionboletostmp;
		END IF;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_activausuario_bei(pEmpresa char(3), pNumCte char(20), pUsuario char(50), pPass char(50), pStatus integer,pIp char (15), pSuc char (4), pUsuCambio char (8))
   returning char(5);

	-- Creador: Manuel Ramos Figueroa
	-- Objetivo: Activa el usuario y registra el cambio de status
	-- Fecha: 22/07/2011

	DEFINE sql_err integer ;
	DEFINE cCod_ret char(5);
	DEFINE iCont smallint ;
	DEFINE iStatus integer;

	LET cCod_ret  = '00000';
	LET iCont = 0;
	LET iStatus = 0;

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            LET cCod_ret = sql_err;
            RETURN cCod_ret;
      END IF ;
   END EXCEPTION ;

    SET LOCK MODE TO WAIT ;
	SET ISOLATION DIRTY READ ;
   
   IF EXISTS ( SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa AND num_cliente = pNumCte ) THEN

		SELECT id_status INTO iStatus FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa and num_cliente = pNumCte;

		INSERT INTO bdinteg:"informix".si_cambiostctepm (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  VALUES (pNumCte,iStatus,pStatus,pIp,current,pSuc,pUsuCambio);

        UPDATE bdinteg:"informix".si_bpiusuariospm SET usuario = pUsuario, pass = TRIM(pPass), f_pass = current, id_status = pStatus  WHERE num_cliente = pNumCte;

        LET cCod_ret = '000';  -- Usuario activado
   ELSE
        LET cCod_ret = '002';  -- No existe el Cliente
   END IF ;
   RETURN cCod_ret;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizapass_bei(pEmpresa char(3), pNumCte char(20), pPass char(50), pIp char (15), pSucVirtual char (4), pUsuVirtual char(8))
   returning char(5);

   --Modificó: Manuel Ramos Figueroa
   --Actividad: activa el usuario y registra el cambio de status
   --Fecha: 26-07-2011

    DEFINE cCod_ret char(5);
    DEFINE sql_err integer ;
    DEFINE iStatus smallint ;

   LET cCod_ret  = "000";
   LET iStatus = 0;

	BEGIN
		ON EXCEPTION SET sql_err
			IF sql_err <> 0 THEN
				LET cCod_ret = sql_err;
				RETURN cCod_ret;
			END IF ;
		END EXCEPTION ;

		IF EXISTS ( SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa AND num_cliente = pNumCte ) THEN
		
			SET LOCK MODE TO WAIT ;
			UPDATE bdinteg:"informix".si_bpiusuariospm SET pass3 = pass2, pass2 = pass1, pass1 = pass, f_pass3 = f_pass2,
							f_pass2 = f_pass1, f_pass1 = f_pass, pass = pPass, f_pass = current, f_actualizacion = current
							 WHERE  empresa = pEmpresa AND num_cliente = pNumCte;

			SET LOCK MODE TO WAIT ;
			SET ISOLATION DIRTY READ ;
							 
			SELECT id_status INTO iStatus FROM bdinteg:"informix".si_bpiusuariospm  WHERE empresa = pEmpresa AND num_cliente = pNumCte;

			IF iStatus = 40 OR  iStatus = 90 THEN
				INSERT INTO bdinteg:"informix".si_cambiostctepm  (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  VALUES (pNumCte,iStatus,30,pIp ,current, pSucVirtual, pUsuVirtual);
				UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = 30, f_status = current WHERE empresa = pEmpresa AND num_cliente = pNumCte;
			END IF ;
			
			INSERT INTO bdinteg:"informix".si_cambiostctepm (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio) VALUES (pNumCte,35,iStatus,pIp,current,pSucVirtual,pUsuVirtual);
		ELSE
			LET cCod_ret = '001';  -- No existe el Cliente
		END IF ;

		RETURN cCod_ret;
	END
END PROCEDURE ;

CREATE PROCEDURE "informix".sp_agregarbitacora_bei(pFechaOper datetime year to second, pNumTrans char(4),pNumSuc char(4),pIdUsuario integer,pIpUsuario char(15),pFechaApli date,pCtaOrigen char(12),pCtaDesti char(12),pMonto money,pSecTrans char(16),pCgen1 char(40),pCgen2 char(40),pCgen3 char(40),pCgen4 char(40))
 returning char(5);

