                          cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, 
                          extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, 
                          numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, 
                          otros, andador, etapa, lote, edificio, entrada, observaciones, user_insert, fecha_insert )  
                        values 
                        ( v_numcte, v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, 
                          v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, v_tipo_telef1_r, 
                          v_telefono1_r, 'P', v_telefono, v_tipo_telef3_r, v_telefono3_r, v_extension_r, 
                          v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, 
                          v_numerointcalle_r, v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, 
                          v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r, v_lote_r, v_edificio_r, 
                          v_entrada_r, v_observaciones_r, v_user_insert_r, today );
                    else
                        insert into bdinteg:si_direcciones
                        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio,
                          cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, 
                          extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, 
                          numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, 
                          otros, andador, etapa, lote, edificio, entrada, observaciones, user_insert, fecha_insert )  
                        values 
                        ( v_numcte, v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, 
                          v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, v_tipo_telef1_r, 
                          v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, 'P', v_telefono, v_extension_r, 
                          v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, 
                          v_numerointcalle_r, v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, 
                          v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r, v_lote_r, v_edificio_r, 
                          v_entrada_r, v_observaciones_r, v_user_insert_r, today );
                    end if
                end if
            end if
        elif v_tipo_telef = 'T' then
            --if v_telefono is not null then
            if nvl(v_telefono, '') <> '' then
                select {+INDEX(bdinteg:si_direcciones_actual idx_diract_cte)} 
                       max(secuencia) 
                  into v_secuencia
                  from bdinteg:si_direcciones_actual
                 where numcte = v_numcte;

                select {+INDEX(bdinteg:si_direcciones_actual idx_diract_ctetpo)} 
                       d.tipo_dir, d.calle, d.colonia, d.entre_calles, 
                       d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, d.tipo_telef1, d.telefono1, 
                       d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, d.extension, d.estado_inegi, d.municipio_inegi,
                       d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, d.departamento, d.numerocalle,
                       d.numerocolonia, d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, d.etapa, d.lote,
                       d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert
                  into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r,
                       v_municipio_r, v_cod_postal_r, v_apart_postal_r, v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r,
                       v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, v_estado_inegi_r, v_municipio_inegi_r,
                       v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, 
                       v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, 
                       v_andador_r, v_etapa_r, v_lote_r, v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, 
                       v_fecha_insert_r
                  from bdinteg:si_direcciones_actual d
                 where d.numcte =  v_numcte
                   and d.tipo_dir = '2';

                --if (v_tipo_dir_r is not null and v_pais_r is not null and v_estado_r is not null) then
                if nvl(v_tipo_dir_r,'') <> '' and nvl(v_pais_r,'') <> '' and nvl(v_estado_r, '') <> '' then
                    let v_max_secuencia = v_secuencia + 1;

                    insert into bdinteg:si_direcciones
                    ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio,
                      cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, 
                      extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, 
                      numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, 
                      otros, andador, etapa, lote, edificio, entrada, observaciones, user_insert, fecha_insert )
                    values 
                    ( v_numcte, v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, 
                      v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, v_tipo_telef1_r, 
                      v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, 'O', v_telefono, v_extension, 
                      v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, 
                      v_numerointcalle_r, v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, 
                      v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r, v_lote_r, v_edificio_r, 
                      v_entrada_r, v_observaciones_r, v_user_insert_r, today );
                end if
            end if
        end if
    
    end foreach;
      
    INSERT INTO bdinteg:si_bitacora_dom(proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert)
    VALUES('sp_actualiza_telefonos.sql', cod_ret, 'PROCESO FINALIZADO', 0, 'informix', today, (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
    
    end

    return cod_ret;
    
END PROCEDURE;

CREATE PROCEDURE "informix".val_num(nnumero char(15))
RETURNING BOOLEAN;

-- DEFINE VARIABLES
DEFINE wnumeroi int8;
DEFINE vsqlerr INTEGER;

-- ASIGNA VALORES
LET wnumeroi = 0;
LET vsqlerr = 0;

-- CONTROL DE ERRORES
BEGIN

    ON EXCEPTION SET vsqlerr
          RETURN 'f';
    END EXCEPTION;

    LET nnumero = replace(nnumero,'.','');
    LET nnumero = replace(nnumero,',','');
    LET nnumero = replace(nnumero,'-','');
    LET wnumeroi = nnumero;

END

RETURN 't';
END PROCEDURE;

CREATE PROCEDURE "informix".sp_asigna_fecha_unica(f_inicio  CHAR(10))
RETURNING CHAR (5),INT; --código de error y #registros procesados
	
	-- Ismael Hernández, Alejandro Vázquez
	-- Objetivo: Se asigna fecha al campo f_unico_reg para que todos los usuarios registrados tengan fecha inicial
	-- Fecha: 23/11/2011

	DEFINE iSql_err int;
	DEFINE cCod_ret CHAR (5);
	DEFINE registros INT;
    DEFINE numCte CHAR(9);
    DEFINE idStatus CHAR(4);
    DEFINE fRegistro DATETIME YEAR TO SECOND;
    DEFINE fMvto DATETIME YEAR TO SECOND;
    DEFINE fUnicoReg DATETIME YEAR TO SECOND;


	LET cCod_ret = '00000';
	LET registros = 0;

    LET numCte = '';
    LET idStatus = '';


	--SET DEBUG FILE TO "sp_asigna_fecha_unica_aw.out";
	--TRACE ON;

	BEGIN
		ON EXCEPTION SET iSql_err
		  IF iSql_err <> 0 THEN
				LET cCod_ret = iSql_err;
				RETURN cCod_ret, registros;
		  END IF;
		END EXCEPTION;

		SET LOCK MODE TO WAIT 3;
		FOREACH
			SELECT numcte,id_status,f_registro, fecha_movto, f_unico_reg 
            INTO numCte, idStatus, fRegistro, fMvto, fUnicoReg
            FROM bdinteg:si_bpiusuarios
            WHERE --numcte <> '' 
				id_status NOT IN ('0','99') 				
				AND ( year(f_registro) >= 2009 )
				AND (f_unico_reg is null or year(f_unico_reg) = 1900)				
			ORDER BY f_registro
			
            LET registros =  registros + 1;
				IF NVL(extend(fMvto, year to day),'1900-01-01') = '1900-01-01' THEN
					UPDATE bdinteg:si_bpiusuarios SET fecha_movto = fRegistro, f_unico_reg = fRegistro
					WHERE empresa='001' AND numcte = numCte AND id_status=idStatus AND f_registro=fRegistro;
				ELSE 
				   UPDATE bdinteg:si_bpiusuarios SET f_unico_reg = fMvto
				   WHERE empresa='001' AND numcte = numCte AND id_status=idStatus AND f_registro=fRegistro;
				END IF;
			
		END FOREACH;
        
		RETURN cCod_ret, registros;
		
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_envia_sms_bm() 
RETURNING CHAR(3)   AS vCodRet1,     --- Codigo de Retorno
          CHAR(60)  AS vEmail,       --- Email Banco
          CHAR(70)  AS vClave,       --- Password Banco
          CHAR(5)   AS vCliente,     --- Cliente Banco
          CHAR(3)   AS vTipoMensaje, --- Tipo de Mensaje
          CHAR(16)  AS vFechaHora,   --- Fecha y hora del envío
          CHAR(10)  AS vTelefono,    --- Telefono Cliente
          CHAR(160) AS vMensaje,     --- Informacion General
          CHAR(1)   AS vRestanSolic; --- Solicitudes Pendientes  
    
    DEFINE Sql_Err              INTEGER;
    DEFINE Isam_Err             INTEGER;
    DEFINE Desc_Err             CHAR(50);
    DEFINE vCodRet1             CHAR(5);
    DEFINE vCodRet2             CHAR(5);
    DEFINE vCodRet3             CHAR(50);
    
    DEFINE vCliente             CHAR(5);
    DEFINE vClave               CHAR(70);
    DEFINE vEmail               CHAR(60);
    DEFINE vTelefono            CHAR(10);
    DEFINE vTipoMensaje         CHAR(3);
    DEFINE vMensaje             CHAR(160);
    DEFINE vRestanSolic         CHAR(1);
    DEFINE vStatus              CHAR(2);
    DEFINE vStatusNvo           CHAR(2);
    DEFINE vNumCte              CHAR(20);
    DEFINE vexiste_solicitudes  SMALLINT;
    DEFINE vFecha               CHAR(10);
    DEFINE vHora                CHAR(5);
    DEFINE vFechaHora           CHAR(16);
        
    LET Sql_Err	 = 0;
    LET Isam_Err = 0;
    LET Desc_Err = '';
    LET vCodRet1 = '000';
    LET vCodRet2 = '000';
    LET vCodRet3 = '';
    
    LET vCliente = '';
    LET vClave = '';
    LET vEmail = '';
    LET vTelefono = '';
    LET vTipoMensaje = '';
    LET vMensaje = '';
    LET vRestanSolic = '0';
    LET vStatus = '';
    LET vStatusNvo = '';
    LET vNumCte = '';
    LET vexiste_solicitudes = 0;
    LET vFecha = '';
    LET vHora = '';
    LET vFechaHora = '';
    
    BEGIN
    
    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_envia_sms_bm.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            RETURN vCodRet1, vEmail, vClave, vCliente, vTipoMensaje, vFechaHora, vTelefono, vMensaje, vRestanSolic;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_envia_sms_bm.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE PARAMETROS PARA ENVIO    
    SELECT valor 
      INTO vCliente --- CLIENTE BANCOPPEL
      FROM bdinteg:"informix".si_param
     WHERE cod_param = 80
       AND empresa = '001';
     
    SELECT valor 
      INTO vClave --- CLAVE BANCOPPEL 
      FROM bdinteg:"informix".si_param
     WHERE cod_param = 81
       AND empresa = '001';
     
    SELECT valor 
      INTO vEmail --- EMAIL BANCOPPEL
      FROM bdinteg:"informix".si_param
     WHERE cod_param = 82
       AND empresa = '001';
     
    SELECT valor 
      INTO vTipoMensaje --- TIPO DE MENSAJE
      FROM bdinteg:"informix".si_param
     WHERE cod_param = 83
       AND empresa = '001';
     
    SELECT valor 
      INTO vMensaje --- MENSAJE
      FROM bdinteg:"informix".si_param
     WHERE cod_param = 84
       AND empresa = '001';
     
    -- // VALIDA PARAMETROS DE ENVIO
    IF (vCliente is null OR vCliente = '') OR
       (vClave is null OR vClave = '') OR
       (vEmail is null OR vEmail = '') OR
       (vTipoMensaje is null OR vTipoMensaje = '') OR
       (vMensaje is null OR vMensaje = '') THEN
        LET vCodRet1 = '111';
        LET vEmail = '';
        LET vClave = '';
        LET vCliente = '';
        LET vTipoMensaje = '';
        LET vFechaHora = '';
        LET vTelefono = '';
        LET vMensaje = '';
        LET vRestanSolic = '0';
        RETURN vCodRet1, vEmail, vClave, vCliente, vTipoMensaje, vFechaHora, vTelefono, vMensaje, vRestanSolic;
    END IF;
    
    -- // OBTENE LA FECHA Y HORA DEL ENVÍO
    LET vFecha = CURRENT::DATE;
    LET vHora  = CURRENT HOUR TO MINUTE;
    LET vFechaHora = SUBSTR(vFecha,4,2)||'/'||SUBSTR(vFecha,1,2)||'/'||SUBSTR(vFecha,7,4)||'/'||SUBSTR(vHora,1,2)||'/'||SUBSTR(vHora,4,2);
    
    -- // VALIDA SI EXISTEN SOLICITUDES POR ENVIAR
    SELECT COUNT(*)
      INTO vexiste_solicitudes
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE id_status IN('10','15');
     
    IF vexiste_solicitudes > 0 THEN
        -- // OBTIENE DATOS DEL USUARIO
        SELECT LIMIT 1 numcel, id_status, numcte
          INTO vTelefono, vStatus, vNumCte
          FROM bdinteg:"informix".si_bm_usuarios
         WHERE id_status IN('10','15');
         
        IF vStatus = '10' THEN
            LET vStatusNvo = '20';
        ELIF vStatus = '15' THEN
            LET vStatusNvo = '30';
        END IF;
        
        -- // ACTUALIZA STATUS DEL USUARIO
        UPDATE bdinteg:"informix".si_bm_usuarios
           SET id_status = vStatusNvo
         WHERE numcel = vTelefono;
         
        -- // REGISTRA CAMBIO DE STATUS
        INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
        VALUES(vNumCte, vStatus, vStatusNvo, vTelefono, current, '5002', 'informix');
        
        -- // ELIMINA SOLICITUD DE ENVIO DE MENSAJE
        DELETE FROM bdinteg:"informix".si_bm_envsolmsn
         WHERE numcel = vTelefono;
        
        IF vexiste_solicitudes > 1 THEN
            LET vRestanSolic = '1';
        END IF;
    ELSE
        LET vCodRet1 = '999';
    END IF;
    
    END;
    
    RETURN vCodRet1, vEmail, vClave, vCliente, vTipoMensaje, vFechaHora, vTelefono, vMensaje, vRestanSolic;
    
END PROCEDURE;

CREATE PROCEDURE "informix".bm_inicializa_diario( pEmpresa CHAR(3) ) --- Empresa
RETURNING CHAR(5) AS vCodRet1; --- Codigo de Retorno
    
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vctemin          CHAR(20);
    DEFINE vctemax          CHAR(20);
    
    LET Sql_Err	 = 0;
    LET Isam_Err = 0;
    LET Desc_Err = '';
    LET vCodRet1 = '00000';
    LET vCodRet2 = '00000';
    LET vCodRet3 = '';
    LET vctemin  = '';
    LET vctemax  = '';
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_inicializa_diario.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            RETURN vCodRet1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_inicializa_diario.out";
    --- TRACE ON;
    
    IF pEmpresa is null OR pEmpresa = '' THEN
        LET vCodRet1 = '11111';
        RETURN vCodRet1;
    END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM bdinteg:"informix".si_bm_usuarios;
    
    -- // INICIAIZA LOS ACCESOS DE LOS CLIENTES
    UPDATE bdinteg:"informix".si_bm_usuarios
       SET numaccesos = 0
     WHERE numcte BETWEEN vctemin AND vctemax;
     
    -- // MUEVE BITACORA DEL DIA A BIATCORA HISTORICA
    INSERT INTO bdinteg:"informix".si_bm_bitacorahist
    SELECT * FROM bdinteg:"informix".si_bm_bitacora;
    
    -- // ELIMIA REGISTROS DE BITACORA DEL DIA
    TRUNCATE TABLE bdinteg:"informix".si_bm_bitacora;
    
    -- // INICIALIZA SESSION TOKEN
    UPDATE bdibpi:"informix".tkn_parametros
       SET valor = 0
     WHERE id_param = '52';
    
    END; 

    RETURN vCodRet1;

END PROCEDURE;

create procedure "informix".sp_ctes_sincol_catzonas_debito()
returning char(20);

    ---V1 20100210 Crear SP
    define cod_ret char(20);
    define sql_err integer;
    define v_numcte char(9);
    define v_numerociudad smallint;
    define v_numerocolonia integer;
    define v_msj char(50);
    define v_count integer;

    --SET DEBUG FILE TO "/ids10_uc9/sp_ctes_sincol_catzonas_debito.out";
    --TRACE ON;
    
    let cod_ret = "000";
    let v_numcte = "";
    let v_numerociudad = 0;
    let v_numerocolonia = 0;
    let v_msj = '';
    let v_count = 0;
    
    BEGIN

    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            SYSTEM 'echo ---- Error :  --------> ' || cod_ret || '>> ' || 'sp_ctes_sincol_catzonas_debito.log';
            let v_msj = 'Error: ' || cod_ret;
            insert into bdinteg:si_bitacora_dom (proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert) 
            values('ctes_sincol_catzonas_debito.sql',cod_ret,  v_msj, 0, '92920268',today,(SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
            return cod_ret;
        end if
    end exception;

    SYSTEM 'echo ---- Inicia proceso --------- ' || '> ' || 'sp_ctes_sincol_catzonas_debito.log';

    foreach
        SELECT numerociudad, numerocolonia 
          INTO v_numerociudad, v_numerocolonia
          FROM bdinteg:si_catzonas_ctesin

        foreach  
            SELECT {+ INDEX (bdinteg:si_direcciones idx_numcolonia)} d.numcte 
              into v_numcte
              FROM bdinteg:si_direcciones d, bdicheq:sc_maechq b 
             WHERE b.empresa = '001' 
               AND b.status_cta in ('1','3','4','5')
               AND b.producto in ('1100','1200','1300','1400','1500','1600','1700','1800','2000','9900','9901')
               AND b.num_cte = d.numcte
               AND d.tipo_dir = '1'
               AND d.secuencia = (SELECT MAX(e.secuencia)
                                    FROM bdinteg:si_direcciones e
                                   WHERE e.numcte = d.numcte
                                     AND e.tipo_dir = '1')
               AND d.numerociudad = v_numerociudad
               AND d.numerocolonia = v_numerocolonia
            
            if v_numcte is null then
                SYSTEM 'echo Cliente no encontrado en si_direcciones ' || '>> ' || 'sp_ctes_sincol_catzonas_debito.log';
                CONTINUE FOREACH;
            end if
            
            let v_count = v_count + 1;
            
            INSERT INTO bdinteg:si_por_asignar (numcte,estado) VALUES (v_count, v_numcte);
        end foreach;
    end foreach;

    end
    
    let cod_ret = "Termina proceso";
    
    insert into bdinteg:si_bitacora_dom (proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert) 
    values('obtener_cte_sincol_catzonas.sql','00000',  cod_ret, 0, '92920268',today,(SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));

    SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'obtener_cte_sincolonia_catzonas.log';
    
    return cod_ret;
    
end procedure;

CREATE PROCEDURE "informix".sp_obtener_status_cierre_cuentas(pNumEmpresa  CHAR(3),
															 pDescProceso VARCHAR(20),
															 pFechaCierre DATE)
RETURNING
    CHAR(5),
    CHAR(1);

--Creado por: Javier Calderon
--Actividad:  Obtener el Status del cierre de cuentas
--Solicito:   Mauricio Leon
--Fecha:      16/02/2010

DEFINE cCodRet          CHAR(5);
DEFINE vValorStatus     CHAR(1);
DEFINE iSqlErr			INTEGER;

LET cCodRet = '000';
LET vValorStatus = '';

--SET DEBUG FILE TO "sp_obtener_status_cierre_cuentas.out";
--TRACE ON;


BEGIN
    ON EXCEPTION
        SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodret = iSqlErr;
            RETURN cCodret, vValorStatus;
        END IF;
    END EXCEPTION;

    IF (month(pFechaCierre) = '12' and day(pFechaCierre)= '25') OR (month(pFechaCierre) = '01' and day(pFechaCierre)= '01') THEN
        LET pFechaCierre = pFechaCierre - 1;
    END IF;
    
	IF EXISTS (SELECT status_proc FROM sx_contproc WHERE empresa = pNumEmpresa AND proceso = pDescProceso AND fecha = pFechaCierre) THEN
		SELECT status_proc INTO vValorStatus FROM sx_contproc WHERE empresa = pNumEmpresa AND proceso = pDescProceso AND fecha = pFechaCierre;
	ELSE
		LET cCodRet = '001';
	END IF;
	RETURN cCodRet, vValorStatus;
END
END PROCEDURE
;

CREATE PROCEDURE "informix".sp_registra_reenviosol_ctebm(pNumCliente CHAR(9),pNumCelular CHAR(15), pIdOper CHAR(4), pTipo CHAR (3), pFolio CHAR (40),pCorreo CHAR(70))
RETURNING CHAR(5);
	
	--***************************************************************************
	-- FUNCIONALIDAD: Registra el reenvìo de solicitud de banca móvil
	-- Autor: Francisco Rodrìguez
	-- Solicito: José de Jesús Nevarez
	-- Fecha: 13/09/2011
	--***************************************************************************
	
	--DECLARACION DE VARIABLES

	DEFINE vsCodRet  	 	CHAR(5);
	DEFINE vSqlErr   	 	INTEGER;
	DEFINE vTexto	 		VARCHAR(255);
	DEFINE vRegAfectados 	SMALLINT;
	DEFINE vFolioContrato 	CHAR (12);
	DEFINE dFecha			DATETIME YEAR TO FRACTION(3);
	DEFINE iMaxSession       INTEGER;

	--Asignacion de variables
	LET vsCodRet = '00000';
	LET vSqlErr = 0;
	LET vRegAfectados = 0;
	LET vFolioContrato = '';
	LET dFecha 	 =  CURRENT;
	LET iMaxSession = 0;

	
	BEGIN
		ON EXCEPTION SET vSqlErr
	      IF vSqlErr <> 0 THEN
	            let vsCodRet = vSqlErr;
	            RETURN vsCodRet;
	      END IF;
		END EXCEPTION;
		
		 --SET DEBUG FILE TO "/tmp/reenviabm.out";
		 --TRACE ON;
		
		
		IF (pNumCliente <> '' AND pNumCliente IS NOT NULL) THEN
		
		
			SET LOCK MODE TO WAIT 3;
			SELECT descripcion INTO vTexto FROM bdibpi:"informix".tkn_parametros WHERE id_param=43;
			SELECT folio_contrato INTO vFolioContrato FROM bdinteg:"informix".si_bm_usuarios WHERE numcte = pNumCliente;
		
			IF EXISTS(Select numcte from bdinteg:"informix".si_bm_envsolmsn WHERE numcte = pNumCliente)  THEN			
				UPDATE bdinteg:"informix".si_bm_envsolmsn SET
				numcel = pNumCelular, texto = vTexto, tipo = pTipo, folio_contrato = vFolioContrato
				WHERE numcte = pNumCliente;
			ELSE
				INSERT INTO bdinteg:"informix".si_bm_envsolmsn (numcte, numcel, texto, tipo, folio_contrato) 
				VALUES (pNumCliente, pNumCelular, vTexto, pTipo, vFolioContrato);
			END IF

			LET vRegAfectados = dbinfo("sqlca.sqlerrd2");

			IF vRegAfectados <= 0 THEN
				LET vsCodRet = '00002'; --No se inserto el registro de reenvío.
			
			ELSE --Inserta en bitácora.
				UPDATE bdinteg:"informix".si_bm_usuarios SET e_mail = TRIM(pCorreo) WHERE numcte = pNumCliente;
				
				SELECT MAX(id_session) INTO iMaxSession FROM bdinteg:"informix".si_bm_bitacora;
				
				IF (iMaxSession = 0 OR iMaxSession IS NULL) THEN
					LET iMaxSession = 1;
				ELSE
					LET iMaxSession = iMaxSession + 1;
				END IF;
				
				INSERT INTO bdinteg:"informix".si_bm_bitacora (id_session,fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
				VALUES (iMaxSession,dFecha,pNumCliente,'0',pIdOper,pNumCelular,NULL,pFolio);
			END IF;

		ELSE
			LET vsCodRet = '00001';  --Parametro cliente vacio.
		END IF;
	
		RETURN vsCodRet;
	
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaporasignar(pEmpresa char(3), pConsulta smallint, pParametro char(50), pValidacion smallint, pOrden smallint)
  RETURNING char(5),char(20),char(50),char(50),char(50),char(50),char(50),char(15),char(15),char(50),char(1),char(40);

define vcodret CHAR(5);
define vParam1 CHAR(20);
define vParam2 CHAR(50);
define vParam3 CHAR(50);
define vParam4 CHAR(50);
define vParam5 CHAR(50);
define vParam6 CHAR(50);
define vParam7 CHAR(15);
define vParam8 CHAR(15);
define vParam9 CHAR(50);
define vParam10 CHAR(1);
define vParam11 CHAR(40);
define vParamX CHAR(40);
define vsqlerr integer ;
define visamerr integer ;

LET vcodret = "000";
LET vParam1 ="";
LET vParam2 ="";
LET vParam3 ="";
LET vParam4 ="";
LET vParam5 ="";
LET vParam6 ="";
LET vParam7 ="";
LET vParam8 ="";
