LET vParam10 ="";
LET vParam11 ="";
LET vParamX = "";
LET vsqlerr = 0 ;
LET visamerr = 0 ;

BEGIN
ON EXCEPTION SET vsqlerr,visamerr
   IF vsqlerr != 0 THEN
      LET vcodret=vsqlerr;
      RETURN vcodret,vParam1,vParam2,vParam3,vParam4,vParam5,vParam6,vParam7,vParam8,vParam9,vParam10,vParam11;
   END IF;
