CREATE PROCEDURE "informix".sp_validaproducto(pEmpresa CHAR(3), pNumCuenta CHAR(20), pTipo CHAR(1))

RETURNING CHAR(6), CHAR(1), CHAR(1), SMALLINT;

--28/11/2008
--Rodolfo Tortolero Varela
--Valida que el nùmero de cuenta se le pueda asignar una tarjeta adicional

--02/12/2008
--Rodolfo Tortolero Varela
--Se modifico para tambien recibir tarjetas de crédito.

--14/10/2009
--Rodolfo Tortolero Varela
--Se agrega validación para cuando la consulta de producto se haga por número de tarjeta

--DEFINICION DE VARIABLES--
	DEFINE iSqlErr INTEGER;
	DEFINE vCodRet CHAR(6);
	DEFINE vProducto CHAR(4);
	DEFINE vFlagAdic CHAR(1);
	DEFINE vFlagTar CHAR(1);
	DEFINE vTotAdic SMALLINT;
	DEFINE vProd CHAR(4);

--Set debug file to '/tmp/sp_consultacuentas.out';
--trace on;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET vCodRet = iSqlErr;
				RETURN vCodRet, vFlagAdic, vFlagTar, vTotAdic;
			END IF;
		END EXCEPTION;
	
--INICIALIZACION DE VARIABLES--
	LET iSqlErr = 0;
	LET vCodRet = '000';	--Si Existe el tipo de producto
	LET vProducto = "";
	LEt vFlagAdic = "";
	LET vFlagTar = "";
	LEt vTotAdic = 0;
	LEt vProd = "";
		
	IF pNumCuenta = "" THEN
		LET vCodRet = '999'; --Falta el parametro nùmero de cuenta
			LET vFlagAdic = NULL;
			LET vFlagTar = NULL;
			LET vTotAdic = NULL;
		RETURN vCodRet, vFlagAdic, vFlagTar, vTotAdic;
	END IF;
	
	--Se selecciona el producto de la cuenta
	IF pTipo = "1" THEN --Productos de Débito
		IF LENGTH(pNumCuenta) = 11 THEN
			SELECT producto INTO vProd FROM bdicheq:sc_maechq 
			 WHERE cuenta = pNumCuenta;
		ELSE
			SELECT b.producto INTO vProd FROM bdicheq:sc_tarjeta a, bdicheq:sc_maechq b
			WHERE a.empresa = pEmpresa 
			  AND a.num_tarjeta = pNumCuenta 
			  AND a.cuenta = b.cuenta;
		END IF;
	ELIF pTipo = "2" THEN --Productos de Inversión
		SELECT cod_instrum INTO vProd FROM bdinvers:sv_maeinv WHERE cuenta = pNumCuenta;
	ELIF pTipo = "3" THEN --Productos de Crédito Bancoppel
		SELECT b.num_producto INTO vProd FROM bdicred:sd_tarjeta a, bdicred:sd_maecred b
		WHERE a.empresa = pEmpresa 
		  AND a.num_tarjeta = pNumCuenta 
		  AND a.empresa = b.empresa
		  AND a.num_credito = b.num_credito;
	ELIF pTipo = "4" THEN --Producto de Crédito Coppel
		LET vProd = "6500";
	END IF;
	
	SELECT producto, flagadicional, flagtarjeta, totadicional
	INTO vProducto, vFlagAdic, vFlagTar, vTotAdic
	FROM si_catvalidaprod
	WHERE empresa = pEmpresa
	AND producto = vProd;
        
	IF vFlagAdic = '0'  THEN
		LET vFlagTar = '0';
		LET vTotAdic = '0';
	END IF;        
        
	IF vProducto IS NULL THEN
		LET  vCodRet = '001'; --No Existe el producto en la tabla si_catvalidaprod
	END IF;
		
	RETURN vCodRet, vFlagAdic, vFlagTar, vTotAdic;

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtctemensajeenviar(pRegistro smallint)

	RETURNING  CHAR(5) ,DATETIME year to fraction,CHAR(10),CHAR(16), CHAR(16), CHAR(1), CHAR(80), CHAR(80), MONEY(16,2), CHAR(2), 
				CHAR(60), CHAR(60), CHAR(40), CHAR(100), CHAR(40);

	--************************************
	--sp_obtctemensajeenviar
	--Objetivo: Obtener los clientes a los que se les enviarán los correos de manera dinámica.
	--Autor: Francisco Rodriguez Ibarra
	--Fecha: 12/07/2010
	--************************************************************
	--Actualización:Se modificó para poder retornar la fecha en datetime
	--Fecha:15/07/2010
	--Autor:Francisco Rodriguez Ibarra
	--**************************************************************
	--Actualización:Se agrega el order by por linea
	--Fecha:22/07/2010
	--Autor:Walber Castro
	--********************************************************************
	--Actualización:Se modifica para enviar el dato de inicio y fin de lineas del mensaje asi como suprimir información que no se necesita del query.
	--Fecha:12/01/2011
	--Autor:Walber Castro
	--*******************************************************************
	--Actualización:Se modifica para retornar el número y tipo de tarjeta.
	--Fecha:19/10/2011
	--Autor:Manuel Ramos Figueroa
	--****************************************

	--DEFINICION DE VARIABLES
	DEFINE iSqlErr		INTEGER;					--variable usada par obtener el numero de error de informix en caso de que ocurra un error interno de informix.
	DEFINE cCodRet		CHAR(5);					--variable para el codigo de retorno
	DEFINE dFecMensaje	DATETIME year to fraction;	--variable para obtener la fecha en que se envia el mensaje
	DEFINE cNumCte		CHAR(10);					--variable para obtener el numero de cliente
	DEFINE cNumCta		CHAR(16);					--variable para obtener la cuenta del cliente
	DEFINE cNumTar		CHAR(16);					--variable para obtener el numero de tarejta del cliente
	DEFINE cTipoTar		CHAR(1);					--variable para obtener el tipo de tarjeta del cliente
	DEFINE vNomCte		VARCHAR(80);				--variable para obtener el nombre del cliente
	DEFINE vCorreo		VARCHAR(80);				--variable para obtener el correo
	DEFINE mMonto		money(16,2);				--variible para obtener el monto
	DEFINE cIdTipoMen	CHAR(2);					--id tipo de transanccion
	DEFINE iCont		INTEGER;					--variable usada para detectar si hay o no clientes con mensajes pendientes
	DEFINE iAux			INTEGER;
	DEFINE vLinea		VARCHAR(60);
	DEFINE vAsunto		VARCHAR(60);
	DEFINE vEncabezado	VARCHAR(40);
	DEFINE vDetalle		VARCHAR(100);
	DEFINE vPie			VARCHAR(40);
	DEFINE vMaxLinea	VARCHAR(9);


	--ASIGNACION DE VALORES A LAS VARIABLES
	LET iSqlErr		= 0;
	LET cCodRet		= "00000";
	LET dFecMensaje	= null;
	LET cNumCte		= "";
	LET cNumCta		= "";
	LET cNumTar		= "";
	LET cTipoTar	= "";
	LET vNomCte		= "";
	LET vCorreo		= "";
	LET mMonto		= "0.00";
	LET cIdTipoMen	= "";
	LET vLinea		= "";
	LET vAsunto		= "";
	LET vEncabezado	= "";
	LET vDetalle	= "";
	LET vPie		= "" ;
	LET iCont		= 0;
	LET iAux		= 0;
	
	--set debug file to "sp_obtctemensajeenviar.out";
	--trace on;

	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, "", "", "", "", "", "","", "", "" ,"", "","", "", "";
			END IF;
		END EXCEPTION;

		IF NVL( pRegistro, '' ) = '' THEN
			--Error en datos de parametros invalidos
			LET cCodRet = '00001';
			RETURN cCodRet, "", "", "", "", "", "","", "", "" ,"", "","", "", "";
		END IF;
		
		SET LOCK MODE TO WAIT 3;
		SET ISOLATION DIRTY READ;
		FOREACH
				SELECT {+ INDEX (bdinteg:"informix".si_mensajes_enviar "informix".idx_msgs_envdos), +INDEX (bdinteg:"informix".si_tipo_mensaje "informix".idx_tipo_msg)} SKIP pRegistro FIRST 10
				    a.f_mensaje, a.numcte, a.cuenta, a.num_tarjeta, a.tipo_tarjeta, a.nombre_cliente, a.correo_cliente, a.monto_reportar, a.id_tipo_mensaje,
					b.linea,b.asunto,b.encabezado,b.detalle,b.pie
				INTO dFecMensaje, cNumCte, cNumCta, cNumTar, cTipoTar, vNomCte, vCorreo, mMonto, cIdTipoMen, 
				    vLinea, vAsunto, vEncabezado, vDetalle, vPie
				FROM bdinteg:"informix".si_mensajes_enviar as a, bdinteg:"informix".si_tipo_mensaje  as b
				WHERE extend(a.f_mensaje, year to day) >= "2010-07-01"
				AND a.enviado='F'
				AND a.id_tipo_mensaje = b.id_tipo_mensaje
				AND b.id_tipo_mensaje <> '00'
				AND b.linea > 0
				ORDER BY f_mensaje, a.numcte, a.cuenta, a.id_tipo_mensaje, b.linea

				SELECT MAX(linea)
				INTO vMaxLinea
				FROM bdinteg:"informix".si_tipo_mensaje
				WHERE id_tipo_mensaje = cIdTipoMen;

				IF ( vMaxLinea = vLinea ) THEN
					LET vLinea = "FIN";
				END IF;

					LET iCont = iCont + 1;
					LET iAux  = iAux + 1;

				IF ( vLinea = '1' ) THEN
					LET vNomCte = "INICIO";
				ELSE
					LET vNomCte    = "";
					LET vCorreo    = "";
					LET mMonto     = "";
					LET cIdTipoMen = "";
					LET vAsunto    = "";
				END IF;

				RETURN cCodRet,dFecMensaje,cNumCte,cNumCta,cNumTar,cTipoTar,vNomCte,vCorreo,mMonto,cIdTipoMen , 
					vLinea , vAsunto , vEncabezado , vDetalle ,vPie WITH RESUME;
		END FOREACH

		IF ( iCont = 0 ) THEN
			LET cCodRet = '00002'; ---no hay mensajes pendientes de enviar
			RETURN cCodRet, "", "", "", "", "", "","", "", "" ,"", "","", "", "";
		END IF

	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_inserta_tarjeta_vencida(pempresa CHAR(3), pnumcte CHAR(20), ptarjeta_ant CHAR(20), ptarjeta_new CHAR(20), pTipoRep CHAR(5))
   returning char(5);

DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cNumCte CHAR(20);
DEFINE cProdIntC CHAR(5);
DEFINE cProdCred CHAR(5);

LET iSqlErr = 0;
LET cCodRet = "00000";
LET cNumCte = '';

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

BEGIN

    ON EXCEPTION SET iSqlErr   --cacha el error en caso de que exista y regresa un valor predeterminado
        IF iSqlErr <> 0 THEN
            RETURN iSqlErr;
        END IF;
    END EXCEPTION;

    IF pempresa = '' OR pempresa IS NULL THEN
       LET cCodRet = '00001';
       RETURN cCodRet;
    END IF;

    IF pnumcte = '' OR pnumcte IS NULL THEN
       LET cCodRet = '00001';
       RETURN cCodRet;
    END IF;

    IF ptarjeta_ant = '' OR ptarjeta_ant IS NULL THEN
       LET cCodRet = '00001';
       RETURN cCodRet;
    END IF;

    IF pTipoRep='05' THEN
        INSERT INTO si_tarjeta_vencimiento(empresa,numcte,num_tarjeta_ant, num_tarjeta_new, fecha_rep)
        VALUES (pempresa,pnumcte,ptarjeta_ant,ptarjeta_new,current);
    END IF;

    IF ptarjeta_new<>'' THEN
          SELECT codproductotarjeta 
            INTO cProdIntC
             FROM intercard:tarjeta WHERE numtarjeta=ptarjeta_ant;

          UPDATE intercard:tarjeta  SET  codproductotarjeta= cProdIntC WHERE numtarjeta=ptarjeta_new;
          
    END IF;

RETURN cCodRet;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizatitular(
cEmpresa CHAR(3),
cNumCteTitular CHAR(9)
)

RETURNING CHAR(5) AS codret;

--****************************************************************************************************
-- DESCRIPCION: Confirma el alta del Cliente Titular.
-- AUTOR : Héctor Manuel Bojórquez Ruelas
-- FECHA : 03/04/2009
-- BD: bdinteg
-- SISTEMA : Caja Unica
--****************************************************************************************************

DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cNumCte CHAR(20);
DEFINE cNumHab CHAR(60);
DEFINE cCodIden CHAR(2);
DEFINE cNumIden CHAR(30);
DEFINE cHabitaEn CHAR(2);

LET iSqlErr = 0;
LET cCodRet = '';
LET cNumCte = '';
LET cNumHab = '';
LET cCodIden = '';
LET cNumIden = '';
LET cHabitaEn = '';

--SET DEBUG FILE TO "/tmp/sp_ActualizaTitular.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET iSqlErr   --cacha el error en caso de que exista y regresa un valor predeterminado
    IF iSqlErr <> 0 THEN
    RETURN iSqlErr;
    END IF;
END EXCEPTION;

IF EXISTS (SELECT numcte
			FROM bdinteg:si_cliente
			WHERE empresa = cEmpresa AND numcte = cNumCteTitular
			AND numcte = (SELECT numcte FROM si_ctepf WHERE numcte = cNumCteTitular)
			AND numcte = (SELECT numcte FROM si_direcciones_actual WHERE numcte = cNumCteTitular AND tipo_dir='1')-- secuencia = (SELECT MAX(secuencia) FROM si_direcciones WHERE numcte = cNumCteTitular AND tipo_dir = '1'))
			AND numcte = (SELECT numcte FROM si_cte_huella WHERE numcte = cNumCteTitular AND estado = 'A')) THEN

                    SELECT a.string2, b.codidentifi, b.numidentifi, b.habita_en
                    INTO cNumHab, cCodIden, cNumIden, cHabitaEn
                    FROM bdinteg:si_cliente a, bdinteg:si_ctepf b
                    WHERE a.empresa = '001' AND a.numcte = cNumCteTitular  AND a.numcte = b.numcte;

                    IF NVL(cNumHab, '')  <> '' AND NVL(cCodIden, '') <> '' AND NVL(cNumIden, '') <> '' AND NVL(cHabitaEn, '') <> '' THEN
                                UPDATE bdinteg:si_cliente SET tipo_cliente = "1" WHERE empresa = cEmpresa AND numcte = cNumCteTitular;
                                --La operación se realizo de manera exitosa.
                                LET cCodRet = '00000';
                     ELSE
                                --El cliente buscado no fue encontrado.
                                LET cCodRet = '00001';
                    END IF;                    
 ELSE
            --El cliente buscado no fue encontrado.
            LET cCodRet = '00001';
END IF;

RETURN cCodRet;

END
END PROCEDURE;

create procedure "informix".sp_obtener_cte_sincol_catzonas()

   returning char(20);
---V1 20100202 Crear SP
   define cod_ret char(20);
   define sql_err integer;
   define v_numcte char(9);
   define v_numerociudad smallint;
   define v_numerocolonia integer;
   define v_msj char(50);

--SET DEBUG FILE TO "/informix/prueba/obtener_cte_sincolonia_catzonas.out";
--TRACE ON;
   let cod_ret = "000";
   let v_numcte = "";
   let v_numerociudad = 0;
   let v_numerocolonia = 0;

BEGIN

   on exception set sql_err
      if sql_err <> 0 then
            let cod_ret = sql_err;
            SYSTEM 'echo ---- Error :  --------> ' || cod_ret || '>> ' || 'obtener_cte_sincolonia_catzonas.log';
            let v_msj = 'Error ' || cod_ret;
            insert into bdinteg:si_bitacora_dom (proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert) 
                 values('obtener_cte_sincolonia_catzonas.sql',cod_ret,  v_msj, 0, '92920268',today,
                    (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
            return cod_ret;
      end if
   end exception;

 SYSTEM 'echo ---- Inicia proceso --------- ' || '> ' || 'obtener_cte_sincol_catzonas.log';

 foreach

    SELECT numerociudad, numerocolonia INTO v_numerociudad, v_numerocolonia
      FROM bdinteg:si_catzonas_ctesin
      
    foreach  
        SELECT  /*{+ INDEX (bdinteg:si_direcciones idx_numcolonia)}*/ d.numcte into v_numcte
        FROM bdinteg:si_direcciones_actual d, bdicred:sd_maecred n
        WHERE d.numcte = n.numcte
        AND n.empresa = '001'
        AND n.status_cred not in ('FF', 'FC', 'CV')
        AND d.tipo_dir = '1'
        /*AND d.secuencia = (
                            SELECT MAX(e.secuencia)
                              FROM bdinteg:si_direcciones e
                             WHERE e.numcte = d.numcte
                              AND e.tipo_dir = '1' )*/
        AND d.numerociudad = v_numerociudad
        AND d.numerocolonia = v_numerocolonia

    
        if v_numcte is null then
            SYSTEM 'echo Cliente no encontrado en si_direcciones_actual ' || '>> ' || 'obtener_cte_sincol_catzonas.log';
            CONTINUE FOREACH;
        end if

        INSERT INTO bdinteg:si_por_asignar (numcte) VALUES (v_numcte);
    end foreach;
 end foreach;

end
let cod_ret = "Termina proceso";
 insert into bdinteg:si_bitacora_dom (proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert) 
  values('obtener_cte_sincol_catzonas.sql','00000',  cod_ret, 0, '92920268',today,
 (SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));

SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'obtener_cte_sincol_catzonas.log';
return cod_ret;
end procedure;

create procedure "informix".sp_os_llenazonasporreplicar(empresa char(3))
returning char (5);

--Juan Andrés Coronel Morán
--08-08-2007
--llena tabla con zonas y calles dadas de alta e bancoppel, que son requeridas en coppel para imprimir OS

    define sNombreZona  char(32);   --like bdinteg:si_catzonas.nombrezona
    define sNombreCalle char(40);   --like bdinteg:si_catcalles.nombrecalle;
    define iCiudad     integer;
    define iColonia    integer;
    define iCalle      integer;
    --define iNumCte     char(20);
    define iNumeroCobranzas integer;
    define iCuantos     integer;
    DEFINE SQL_ERR          INTEGER;
    DEFINE ISAM_ERR         INTEGER;
    DEFINE ERROR_INFO       VARCHAR(80);
    DEFINE P_COD_RET        VARCHAR(5);
    DEFINE P_MENSAJE        VARCHAR(80);
    DEFINE pUsuario           CHAR(8);
    DEFINE vdia				  DATE;
    DEFINE vhora			  DATETIME YEAR to FRACTION(5);

    --Set debug file to '/pisa/pisabanco/pisa_ftes/credito/coronel/sp_os_llenazonasporreplicar.out';
    --trace on;

BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
        LET P_COD_RET = SQL_ERR;
        LET P_MENSAJE = ERROR_INFO;
        ROLLBACK WORK;
        RETURN P_COD_RET;
    END EXCEPTION;

    LET pUsuario      = 'SYSCOBRA';

    INSERT INTO bdisolic:ss_bitacora_os(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert)
    VALUES('sp_os_llenazonasporreplicar', '11111', 'PROCESO INICIALIZADO', pUsuario, CURRENT::DATE, CURRENT::DATETIME HOUR TO SECOND);

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 2;

    Begin Work;
    Let P_cod_ret = "00000";
    ForEach

    select nvl(a.numerociudad,0) as numerociudad, nvl(a.numerocolonia,0) as numerocolonia, nvl(a.numerocalle,0) as numerocalle
    Into iCiudad, iColonia, iCalle
    from bdinteg:si_direcciones a
         ,bdisolic:ss_solicitudes e
    where e.numcte = a.numcte
    and e.empresa = empresa
    and a.tipo_dir in (1,2)
    /*and a.secuencia = (
        select max(secuencia)
        from bdinteg:si_direcciones b
        where b.numcte = a.NumCte
        and b.tipo_dir = a.tipo_dir)*/
    and a.numerociudad > 0
    and
        (
            (a.numerocolonia >= 8001 and a.numerocolonia <= 8900)
            or
            (a.numerocalle >= 800001 and a.numerocalle <= 899999)
        )
    and e.status_solicitud in ('EE','CE')


        --la calle se debe enviar a cada region donde se requiera, puede enviarse a muchas zonas
        Let sNombreCalle = ' ';
        if iCalle < 800001 or iCalle > 899999 then
            --Si la calle no es por asignar se envía en ceros
            Let iCalle = 0;
        end if;

        Select count(*)
        Into iCuantos
        From bdinteg:si_replicazonasasignar
        Where numerociudad = iCiudad
        and numerocolonia = iColonia
        and numerocalle = iCalle;

        If iCuantos = 0 then  --Si no ha sido replicada esta combinación, o para este cliente

            --If nvl(v_colonia, 0) >= 8001 and nvl(v_colonia, 0) <= 8900 then
            Select nombrezona
            Into sNombreZona
            from bdinteg:si_catzonas
            where numerociudad = iCiudad
            and numerocolonia = iColonia;
            --end if;

            If length(trim(nvl(sNombreZona, ' '))) = 0 then
                continue foreach;
            end if;

            Let sNombreCalle = '';
            if iCalle > 0 then
                Select nvl(nombrecalle, ' ')
                Into sNombreCalle
                from bdinteg:si_catcalles
                where numerocalle = iCalle;

                If sNombreCalle is null then
                    continue foreach;
                End if;

                if length(trim(nvl(sNombreCalle, ' '))) = 0 then
                    continue foreach;
                end if;
            end if;

            --obtener numerocobranzas

            select numerocobranzas
            Into iNumeroCobranzas
            from bdinteg:si_catzonas
            where numerociudad = iCiudad
            and numerocolonia  =
            (
                select min (numerocolonia)
                from bdinteg:si_catzonas
                where numerociudad = iCiudad
                and  numerocobranzas > 0 AND CENTRO>0 AND jefegrupozona > 0 and supervisorzona > 0
            )
            and  numerocobranzas > 0;

            If iNumeroCobranzas is Null then
                Continue foreach;
            End if;

            Insert into bdinteg:si_replicazonasasignar (numerociudad, numerocolonia, nombrezona, numerocalle, nombrecalle, numerocobranzas, fechaactualizacion)
            Values (iCiudad, iColonia, sNombreZona, iCalle, sNombreCalle, iNumeroCobranzas, current);
            --commit;

        End if;
    End ForEach;

    IF P_cod_ret = "00000" THEN --no hubo errores
        COMMIT WORK;
    ELSE
        ROLLBACK WORK;
    END IF;

    SELECT DBINFO('utc_to_datetime', sh_curtime)::DATE  INTO vdia from sysmaster:sysshmvals;
	  SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND INTO vhora from sysmaster:sysshmvals;

    INSERT INTO bdisolic:ss_bitacora_os(proceso, cod_ret, mensaje, user_insert, fecha_insert, hora_insert)
    VALUES('sp_os_llenazonasporreplicar', P_COD_RET, 'PROCESO FINALIZADO', pUsuario, vdia,  vhora);

    RETURN P_COD_RET;


end;
end procedure;

CREATE PROCEDURE "informix".bm_cambio_password( pUsuario     CHAR(10),  --- Usuario
                                                pPasswordAnt CHAR(50),  --- Contraseña Anterior
                                                pPasswordNvo CHAR(50) ) --- Contraseña Nueva
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          INTEGER  AS vSesionToken, --- Session Token
          CHAR(35) AS vGeneralInfo; --- Informacion General
     
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vSesionToken     INTEGER;
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vnumcte          CHAR(20);
    DEFINE vnumcel          CHAR(15);
    DEFINE vsecmax          INTEGER;
    DEFINE vexiste_usuario  SMALLINT;
    DEFINE vnumintacce      SMALLINT;
    DEFINE vid_oper         CHAR(4);
    DEFINE vtoken           INTEGER;
    DEFINE vtransaccion     INTEGER;
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vSesionToken = 0;
    LET vGeneralInfo = '';
    
    LET vnumcte = '';
    LET vnumcel = '';
    LET vsecmax = 0;
    LET vexiste_usuario = 0;
    LET vnumintacce = 0;
    LET vid_oper = '';
    LET vtoken = 0;
    LET vtransaccion = 0;    
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_cambio_password.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_cambio_password.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pUsuario is null OR pUsuario = '') OR 
       (pPasswordAnt is null OR pPasswordAnt = '') OR 
       (pPasswordNvo is null OR pPasswordNvo = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH (pUsuario) <> 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE EL NUMERO DE CLIENTE
    SELECT numcte, numcel
      INTO vnumcte, vnumcel
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario;
    
    -- // VALIDA SI EL USUARIO Y PASSWORD EXISTEN
    SELECT COUNT(*)
      INTO vexiste_usuario
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario
       AND numcte = vnumcte
       AND numcel = vnumcel
       AND password = pPasswordAnt;
     
    IF vexiste_usuario = 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Contrasena incorrecta, verifique.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Contrasena incorrecta, verifique.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = vnumcel;
       
    IF vsecmax is null THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    SELECT id_oper, id_session
      INTO vid_oper, vSesionToken
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = vnumcel
       AND secuencia = vsecmax;
       
    IF vid_oper is null OR vid_oper = '' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF vid_oper = '1001' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF vid_oper IN('1000', '1002', '1003', '1004', '1005') THEN
        -- // ACTUALIZA PASSWORDS
        UPDATE bdinteg:"informix".si_bm_usuarios
           SET password = pPasswordNvo,
               fech_pass = current,
               password1 = password,
               fech_pass1 = fech_pass,
               password2 = password1,
               fech_pass2 = fech_pass1,
               password3 = password2,
               fech_pass3 = fech_pass2
         WHERE usuario = pUsuario
           AND numcte = vnumcte
           AND numcel = vnumcel;
           
        IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
            LET vCodRet1 = '11111';
            LET vStatus = '';
            LET vStatusDesc = 'Error en aplicativo.';
            LET vSesionToken = 0;
            LET vGeneralInfo = 'Error en aplicativo.';
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
        
        INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
        VALUES(vnumcte, '30', '35', vnumcel, current, '5002', 'informix');
    ELSE
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".bm_logout( pSessionToken INTEGER ) --- Session Token
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc;  --- Descripcion del Status
    
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vnumcte          CHAR(20);
    DEFINE vnumcel          CHAR(15);
    DEFINE vsecmax          INTEGER;
    DEFINE vid_oper         CHAR(4);
    DEFINE vtransaccion     INTEGER;
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vnumcte = '';
    LET vnumcel = '';
    LET vsecmax = 0;
    LET vid_oper = '';
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_logout.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_logout.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    IF pSessionToken is null OR pSessionToken = 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc;
    END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND id_session = pSessionToken;
       
    IF vsecmax is null THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc;
    END IF;
    
    SELECT id_oper, numcte, numcel
      INTO vid_oper, vnumcte, vnumcel
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND id_session = pSessionToken
       AND secuencia = vsecmax;
    
    IF vid_oper is null OR vid_oper = '' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc;
    END IF;
    
    IF vid_oper = '1001' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc;
    END IF;
    
    IF vid_oper IN('1000', '1002', '1003', '1004', '1005') THEN
        -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
        LET vsecmax = vsecmax + 1;
        
        INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
        VALUES(pSessionToken, current, vnumcte, vsecmax, '1001', vnumcel, null, null);
        
        IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
            LET vCodRet1 = '11111';
            LET vStatus = '';
            LET vStatusDesc = 'Error en aplicativo.';
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc;
        END IF;
    ELSE
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc;
    END IF;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;
    
    RETURN vCodRet1, vStatus, vStatusDesc;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".bm_nuevo_usuario( pUsuario  CHAR(10),  --- Usuario
                                              pFolio    CHAR(12),  --- Folio 
                                              pCelular  DECIMAL(10,0),   --- No. Celular
                                              pPassword CHAR(50) ) --- Contraseña
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          INTEGER  AS vSesionToken, --- Session Token
          CHAR(35) AS vGeneralInfo; --- Informacion General
    
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vSesionToken     INTEGER;
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vexiste_usuario  SMALLINT;
    DEFINE vnumcte          CHAR(20);
    DEFINE vfolio_contrato  CHAR(12);
    DEFINE vnumcel          DECIMAL(10,0);
    DEFINE vid_status       CHAR(2);    
    DEFINE vtoken           INTEGER;
    DEFINE vtransaccion     INTEGER;
    
    LET Sql_Err	 = 0;
    LET Isam_Err = 0;
    LET Desc_Err = '';
    LET vCodRet1 = '00000';
    LET vCodRet2 = '00000';
    LET vCodRet3 = '';
    LET vStatus  = '00';
    LET vStatusDesc = '';
    LET vSesionToken = 0;
    LET vGeneralInfo = '';
    
    LET vexiste_usuario = 0;
    LET vnumcte = '';
    LET vfolio_contrato = '';
    LET vnumcel = 0;
    LET vid_status = '';    
    LET vtoken = 0;
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_nuevo_usuario.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_nuevo_usuario.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;

    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pUsuario is null OR pUsuario = '') OR
       (pFolio is null OR pFolio = '') OR
       (pCelular is null OR pCelular = 0) OR
       (pPassword is null OR pPassword = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pUsuario) != 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pCelular::CHAR(10)) < 10 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Celular incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Celular incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
        
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA QUE EL USUARIO NO EXISTA
    SELECT COUNT(*)
      INTO vexiste_usuario
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario;
     
    IF vexiste_usuario > 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario ya existe.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario ya existe.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // OBTIENE EL NUMERO DE CLIENTE Y EL STATUS DE LA SOLICITUD
    SELECT numcte, folio_contrato, numcel, id_status
      INTO vnumcte, vfolio_contrato, vnumcel, vid_status
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE folio_contrato = pFolio
       AND numcel = pCelular;
       
    IF (vnumcte is null OR vnumcte = '') OR
       (vfolio_contrato is null OR vfolio_contrato = '' OR vfolio_contrato <> pFolio) OR
       (vnumcel is null OR vnumcel = '' OR vnumcel <> pCelular) OR 
       (vid_status <> '20') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Datos incorrectos, verifique.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Datos incorrectos, verifique.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // GENERA EL NUMERO DE SESSION 
    SELECT valor::int
      INTO vtoken
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '52';
     
    IF vtoken is null THEN
        LET vtoken = 1;
    ELSE
        LET vtoken = vtoken + 1;
    END IF;
    
    UPDATE bdibpi:"informix".tkn_parametros
       SET valor = vtoken
     WHERE id_param = '52';
     
    LET vSesionToken = vtoken;
    
    -- // ACTUALIZA USUARIO
    UPDATE bdinteg:"informix".si_bm_usuarios
       SET usuario = pUsuario,
           password = pPassword,
           fech_pass = current,
           id_status = '30',
           fech_registro = current
     WHERE numcte = vnumcte
       AND folio_contrato = pFolio
       AND numcel = pCelular;
       
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
    VALUES(vnumcte, vid_status, '30', pCelular, current, '5002', 'informix');
    
    LET vStatusDesc = 'Usted se ha dado de alta correctamente.';
    LET vGeneralInfo = 'Usted se ha dado de alta correctamente.';
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;
    
    RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    
    END;
    
END PROCEDURE;

