    LET vTipoMov4    = '';
    LET vMontoMov4   = 0.00;
    LET vDescMov4    = '';
    
    LET vFechaMov5   = '';
    LET vTipoMov5    = '';
    LET vMontoMov5   = 0.00;
    LET vDescMov5    = '';
    
    LET vFechaMov6   = '';
    LET vTipoMov6    = '';
    LET vMontoMov6   = 0.00;
    LET vDescMov6    = '';
    
    LET vFechaMov7   = '';
    LET vTipoMov7    = '';
    LET vMontoMov7   = 0.00;
    LET vDescMov7    = '';
    
    LET vFechaMov8   = '';
    LET vTipoMov8    = '';
    LET vMontoMov8   = 0.00;
    LET vDescMov8    = '';
    
    LET vFechaMov9   = '';
    LET vTipoMov9    = '';
    LET vMontoMov9   = 0.00;
    LET vDescMov9    = '';
    
    LET vFechaMov10  = '';
    LET vTipoMov10   = '';
    LET vMontoMov10  = 0.00;
    LET vDescMov10   = '';
    
    LET vnumcte = '';
    LET vnumcel = '';
    LET vsecmax = 0;
    LET vid_oper = '';
    LET vfechconmovhis = '';
    LET vfechconmovhisold = '';
    LET vcont = 0;
    LET vfecha_alt = '';
    LET vserial = 0;
    LET vnaturaleza = '';
    LET vmonto = 0.00;
    LET vreferencia = '';
    LET vtipo_mov = '';
    LET vhora = '';
    
    LET vcodret_mov     = '';
    LET vfecha_mov      = '';
    LET vdesc_transacc  = '';
    LET vmonto_transacc = 0.00;
    LET vpagominimo     = 0.00;
    LET vsdodeudor      = 0.00;
    LET vintmora        = 0.00;
    LET vivaintmora     = 0.00;
    LET vdescripcion    = '';
    LET vtransacc       = '';
    LET vfechaconv      = '';
    LET vtransaccion    = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_obten_movimientos.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, 
                   vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
                   vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
                   vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
                   vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
                   vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
                   vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
                   vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
                   vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
                   vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
                   vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
                
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_obten_movimientos.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    IF (pSessionToken is null OR pSessionToken = 0) OR
       (pCuenta is null OR pCuenta = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, 
               vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
               vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
               vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
               vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
               vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
               vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
               vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
               vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
               vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
               vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
    END IF;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND id_session = pSessionToken;
       
    IF vsecmax is null THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, 
               vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
               vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
               vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
               vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
               vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
               vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
               vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
               vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
               vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
               vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
    END IF;
       
    SELECT id_oper, numcte, numcel
      INTO vid_oper, vnumcte, vnumcel
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND id_session = pSessionToken
       AND secuencia = vsecmax;
       
    IF vid_oper is null OR vid_oper = '' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, 
               vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
               vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
               vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
               vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
               vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
               vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
               vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
               vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
               vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
               vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
    END IF;
    
    IF vid_oper = '1001' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, 
               vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
               vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
               vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
               vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
               vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
               vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
               vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
               vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
               vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
               vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
    END IF;
    
    IF vid_oper IN('1000', '1002', '1003', '1004', '1005') THEN
    
        IF LENGTH(pCuenta) = 11 THEN
        
            SELECT valor
              INTO vfechconmovhis
              FROM bdicheq:"informix".sc_param
             WHERE empresa = '001'
               AND codparam = 'fechcon_movhis';
               
            SELECT valor
              INTO vfechconmovhisold
              FROM bdicheq:"informix".sc_param
             WHERE empresa = '001'
               AND codparam = 'FechIniCon_movhis_ol';
        
            LET vcont = 1;
            
            FOREACH
                SELECT mov.fech_alt, mov.num_serial, trx.naturaleza, mov.monto_tot, trx.descripcion
                  INTO vfecha_alt, vserial, vnaturaleza, vmonto, vreferencia
                  FROM bdicheq:"informix".sc_movdia mov,
                       bdinteg:"informix".si_transacc trx
                 WHERE mov.empresa = '001'
                   AND mov.cuenta = pCuenta
                   AND mov.cancelad <> 'S'
                   AND trx.numero = mov.transacc
                   AND trx.se_emite_edocta = 'S'
                UNION ALL
                SELECT mov.fech_alt, mov.num_serial, trx.naturaleza, mov.monto_tot, trx.descripcion
                  FROM bdicheq:"informix".sc_movhis mov,
                       bdinteg:"informix".si_transacc trx
                 WHERE mov.fech_alt >= vfechconmovhis
                   AND mov.cuenta = pCuenta
                   AND mov.cancelad <> 'S'
                   AND trx.numero = mov.transacc
                   AND trx.se_emite_edocta = 'S'
                UNION ALL
                SELECT mov.fech_alt, mov.num_serial, trx.naturaleza, mov.monto_tot, trx.descripcion
                  FROM bdicheq:"informix".sc_movhis_old mov,
                       bdinteg:"informix".si_transacc trx
                 WHERE mov.fech_alt >= vfechconmovhisold
                   AND mov.fech_alt < vfechconmovhis
                   AND mov.cuenta = pCuenta
                   AND mov.cancelad <> 'S'
                   AND trx.numero = mov.transacc
                   AND trx.se_emite_edocta = 'S'
                 ORDER BY mov.fech_alt DESC, mov.num_serial DESC
                 
                IF vnaturaleza = 'C' THEN
                    LET vtipo_mov = 'CARGO';
                ELIF vnaturaleza = 'A' THEN
                    LET vtipo_mov = 'ABONO';
                END IF;
                
                LET vfechaconv = TO_CHAR(vfecha_alt, '%d/%m/%Y');
                 
                IF vcont = 1 THEN
                    LET vFechaMov1   = vfechaconv;
                    LET vTipoMov1    = vtipo_mov;
                    LET vMontoMov1   = vmonto;
                    LET vDescMov1    = vreferencia;
                ELIF vcont = 2 THEN
                    LET vFechaMov2   = vfechaconv;
                    LET vTipoMov2    = vtipo_mov;
                    LET vMontoMov2   = vmonto;
                    LET vDescMov2    = vreferencia;
                ELIF vcont = 3 THEN
                    LET vFechaMov3   = vfechaconv;
                    LET vTipoMov3    = vtipo_mov;
                    LET vMontoMov3   = vmonto;
                    LET vDescMov3    = vreferencia;
                ELIF vcont = 4 THEN
                    LET vFechaMov4   = vfechaconv;
                    LET vTipoMov4    = vtipo_mov;
                    LET vMontoMov4   = vmonto;
                    LET vDescMov4    = vreferencia;
                ELIF vcont = 5 THEN
                    LET vFechaMov5   = vfechaconv;
                    LET vTipoMov5    = vtipo_mov;
                    LET vMontoMov5   = vmonto;
                    LET vDescMov5    = vreferencia;
                ELIF vcont = 6 THEN
                    LET vFechaMov6   = vfechaconv;
                    LET vTipoMov6    = vtipo_mov;
                    LET vMontoMov6   = vmonto;
                    LET vDescMov6    = vreferencia;
                ELIF vcont = 7 THEN
                    LET vFechaMov7   = vfechaconv;
                    LET vTipoMov7    = vtipo_mov;
                    LET vMontoMov7   = vmonto;
                    LET vDescMov7    = vreferencia;
                ELIF vcont = 8 THEN
                    LET vFechaMov8   = vfechaconv;
                    LET vTipoMov8    = vtipo_mov;
                    LET vMontoMov8   = vmonto;
                    LET vDescMov8    = vreferencia;
                ELIF vcont = 9 THEN
                    LET vFechaMov9   = vfechaconv;
                    LET vTipoMov9    = vtipo_mov;
                    LET vMontoMov9   = vmonto;
                    LET vDescMov9    = vreferencia;
                ELIF vcont = 10 THEN
                    LET vFechaMov10   = vfechaconv;
                    LET vTipoMov10    = vtipo_mov;
                    LET vMontoMov10   = vmonto;
                    LET vDescMov10    = vreferencia;
                END IF;
                
                LET vcont = vcont + 1;
                
                IF vcont > 10 THEN
                    EXIT FOREACH;
                END IF;
                
                LET vfecha_alt = '';
                LET vserial = 0;
                LET vnaturaleza = '';
                LET vmonto = 0.00;
                LET vreferencia = '';
                LET vtipo_mov = '';
            END FOREACH;
            
            -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
            SELECT MAX(secuencia)
              INTO vsecmax
              FROM bdinteg:"informix".si_bm_bitacora
             WHERE DATE(fech_oper) = CURRENT::DATE
               AND id_session = pSessionToken;
               
            LET vsecmax = vsecmax + 1;
       
            INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
            VALUES(pSessionToken, current, vnumcte, vsecmax, '1004', vnumcel, null, null);
            
            IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                LET vCodRet1 = '11111';
                LET vStatus = '';
                LET vStatusDesc = 'Error en aplicativo.';
                IF vtransaccion = 1 THEN
                    ROLLBACK WORK;
                    BEGIN WORK;
                ELSE
                    ROLLBACK WORK;
                END IF;
                RETURN vCodRet1, vStatus, vStatusDesc, 
                       vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
                       vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
                       vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
                       vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
                       vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
                       vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
                       vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
                       vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
                       vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
                       vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
            END IF;
            
        ELSE
            
            IF LENGTH(pCuenta) = 16 THEN  
            
                SELECT num_credito
                  INTO pCuenta
                  FROM bdicred:sd_tarjeta
                 WHERE num_tarjeta = pCuenta
                   AND status_tar = 'A'
                   AND tipo_tarjeta = 'T';
                
                LET vcont = 1;
            
                FOREACH
                    EXECUTE PROCEDURE bdicred:"informix".consultmovs('001', pCuenta, 10)
                    INTO vcodret_mov, vfecha_mov, vdesc_transacc, vmonto_transacc, vpagominimo, vsdodeudor, vintmora, vivaintmora
                    
                    LET vfecha_alt = vfecha_mov;
                    LET vtransacc = SUBSTR(vdesc_transacc,1,4);
                    
                    SELECT naturaleza, descripcion
                      INTO vnaturaleza, vdescripcion
                      FROM bdinteg:"informix".si_transacc
                     WHERE numero = vtransacc;
                    
                    IF vnaturaleza = 'C' THEN
                        LET vtipo_mov = 'CARGO';
                        IF vmonto_transacc < 0.00 THEN
                            LET vmonto_transacc = vmonto_transacc * -1;
                        END IF;
                    ELIF vnaturaleza = 'A' THEN
                        LET vtipo_mov = 'ABONO';
                    END IF;
                    
                    LET vmonto = vmonto_transacc;
                    LET vfechaconv = TO_CHAR(vfecha_alt, '%d/%m/%Y');
                     
                    IF vcont = 1 THEN
                        LET vFechaMov1   = vfechaconv;
                        LET vTipoMov1    = vtipo_mov;
                        LET vMontoMov1   = vmonto;
                        LET vDescMov1    = TRIM(vdescripcion);
                    ELIF vcont = 2 THEN
                        LET vFechaMov2   = vfechaconv;
                        LET vTipoMov2    = vtipo_mov;
                        LET vMontoMov2   = vmonto;
                        LET vDescMov2    = TRIM(vdescripcion);
                    ELIF vcont = 3 THEN
                        LET vFechaMov3   = vfechaconv;
                        LET vTipoMov3    = vtipo_mov;
                        LET vMontoMov3   = vmonto;
                        LET vDescMov3    = TRIM(vdescripcion);
                    ELIF vcont = 4 THEN
                        LET vFechaMov4   = vfechaconv;
                        LET vTipoMov4    = vtipo_mov;
                        LET vMontoMov4   = vmonto;
                        LET vDescMov4    = TRIM(vdescripcion);
                    ELIF vcont = 5 THEN
                        LET vFechaMov5   = vfechaconv;
                        LET vTipoMov5    = vtipo_mov;
                        LET vMontoMov5   = vmonto;
                        LET vDescMov5    = TRIM(vdescripcion);
                    ELIF vcont = 6 THEN
                        LET vFechaMov6   = vfechaconv;
                        LET vTipoMov6    = vtipo_mov;
                        LET vMontoMov6   = vmonto;
                        LET vDescMov6    = TRIM(vdescripcion);
                    ELIF vcont = 7 THEN
                        LET vFechaMov7   = vfechaconv;
                        LET vTipoMov7    = vtipo_mov;
                        LET vMontoMov7   = vmonto;
                        LET vDescMov7    = TRIM(vdescripcion);
                    ELIF vcont = 8 THEN
                        LET vFechaMov8   = vfechaconv;
                        LET vTipoMov8    = vtipo_mov;
                        LET vMontoMov8   = vmonto;
                        LET vDescMov8    = TRIM(vdescripcion);
                    ELIF vcont = 9 THEN
                        LET vFechaMov9   = vfechaconv;
                        LET vTipoMov9    = vtipo_mov;
                        LET vMontoMov9   = vmonto;
                        LET vDescMov9    = TRIM(vdescripcion);
                    ELIF vcont = 10 THEN
                        LET vFechaMov10   = vfechaconv;
                        LET vTipoMov10    = vtipo_mov;
                        LET vMontoMov10   = vmonto;
                        LET vDescMov10    = TRIM(vdescripcion);
                    END IF;
                    
                    LET vcont = vcont + 1;
                    
                    IF vcont > 10 THEN
                        EXIT FOREACH;
                    END IF;
                    
                    LET vfecha_alt = '';
                    LET vhora = '';
                    LET vnaturaleza = '';
                    LET vmonto = 0;
                    LET vreferencia = '';
                    LET vtipo_mov = '';
                    LET vcodret_mov     = '';
                    LET vfecha_mov      = '';
                    LET vdesc_transacc  = '';
                    LET vmonto_transacc = 0.00;
                    LET vpagominimo     = 0.00;
                    LET vsdodeudor      = 0.00;
                    LET vintmora        = 0.00;
                    LET vivaintmora     = 0.00;
                    LET vdescripcion    = '';
                END FOREACH;
                
            ELSE
            
                LET vcont = 1;
            
                FOREACH
                    EXECUTE PROCEDURE bdicred:"informix".sp_consultmovscrd('001', pCuenta, 10)
                    INTO vcodret_mov, vfecha_mov, vdesc_transacc, vmonto_transacc, vpagominimo, vsdodeudor, vintmora, vivaintmora
                    
                    LET vfecha_alt = vfecha_mov;
                    LET vtransacc = SUBSTR(vdesc_transacc,1,4);
                    
                    SELECT naturaleza, descripcion
                      INTO vnaturaleza, vdescripcion
                      FROM bdinteg:"informix".si_transacc
                     WHERE numero = vtransacc;
                    
                    IF vnaturaleza = 'C' THEN
                        LET vtipo_mov = 'CARGO';
                        IF vmonto_transacc < 0.00 THEN
                            LET vmonto_transacc = vmonto_transacc * -1;
                        END IF;
                    ELIF vnaturaleza = 'A' THEN
                        LET vtipo_mov = 'ABONO';
                    END IF;
                    
                    LET vmonto = vmonto_transacc;
                    LET vfechaconv = TO_CHAR(vfecha_alt, '%d/%m/%Y');
                     
                    IF vcont = 1 THEN
                        LET vFechaMov1   = vfechaconv;
                        LET vTipoMov1    = vtipo_mov;
                        LET vMontoMov1   = vmonto;
                        LET vDescMov1    = TRIM(vdescripcion);
                    ELIF vcont = 2 THEN
                        LET vFechaMov2   = vfechaconv;
                        LET vTipoMov2    = vtipo_mov;
                        LET vMontoMov2   = vmonto;
                        LET vDescMov2    = TRIM(vdescripcion);
                    ELIF vcont = 3 THEN
                        LET vFechaMov3   = vfechaconv;
                        LET vTipoMov3    = vtipo_mov;
                        LET vMontoMov3   = vmonto;
                        LET vDescMov3    = TRIM(vdescripcion);
                    ELIF vcont = 4 THEN
                        LET vFechaMov4   = vfechaconv;
                        LET vTipoMov4    = vtipo_mov;
                        LET vMontoMov4   = vmonto;
                        LET vDescMov4    = TRIM(vdescripcion);
                    ELIF vcont = 5 THEN
                        LET vFechaMov5   = vfechaconv;
                        LET vTipoMov5    = vtipo_mov;
                        LET vMontoMov5   = vmonto;
                        LET vDescMov5    = TRIM(vdescripcion);
                    ELIF vcont = 6 THEN
                        LET vFechaMov6   = vfechaconv;
                        LET vTipoMov6    = vtipo_mov;
                        LET vMontoMov6   = vmonto;
                        LET vDescMov6    = TRIM(vdescripcion);
                    ELIF vcont = 7 THEN
                        LET vFechaMov7   = vfechaconv;
                        LET vTipoMov7    = vtipo_mov;
                        LET vMontoMov7   = vmonto;
                        LET vDescMov7    = TRIM(vdescripcion);
                    ELIF vcont = 8 THEN
                        LET vFechaMov8   = vfechaconv;
                        LET vTipoMov8    = vtipo_mov;
                        LET vMontoMov8   = vmonto;
                        LET vDescMov8    = TRIM(vdescripcion);
                    ELIF vcont = 9 THEN
                        LET vFechaMov9   = vfechaconv;
                        LET vTipoMov9    = vtipo_mov;
                        LET vMontoMov9   = vmonto;
                        LET vDescMov9    = TRIM(vdescripcion);
                    ELIF vcont = 10 THEN
                        LET vFechaMov10   = vfechaconv;
                        LET vTipoMov10    = vtipo_mov;
                        LET vMontoMov10   = vmonto;
                        LET vDescMov10    = TRIM(vdescripcion);
                    END IF;
                    
                    LET vcont = vcont + 1;
                    
                    IF vcont > 10 THEN
                        EXIT FOREACH;
                    END IF;
                    
                    LET vfecha_alt = '';
                    LET vhora = '';
                    LET vnaturaleza = '';
                    LET vmonto = 0;
                    LET vreferencia = '';
                    LET vtipo_mov = '';
                    LET vcodret_mov     = '';
                    LET vfecha_mov      = '';
                    LET vdesc_transacc  = '';
                    LET vmonto_transacc = 0.00;
                    LET vpagominimo     = 0.00;
                    LET vsdodeudor      = 0.00;
                    LET vintmora        = 0.00;
                    LET vivaintmora     = 0.00;
                    LET vdescripcion    = '';
                END FOREACH;
            
            END IF;
            
            -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
            SELECT MAX(secuencia)
              INTO vsecmax
              FROM bdinteg:"informix".si_bm_bitacora
             WHERE DATE(fech_oper) = CURRENT::DATE
               AND id_session = pSessionToken;
               
            LET vsecmax = vsecmax + 1;
            
            INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
            VALUES(pSessionToken, current, vnumcte, vsecmax, '1005', vnumcel, null, null);
            
            IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
                LET vCodRet1 = '11111';
                LET vStatus = '';
                LET vStatusDesc = 'Error en aplicativo.';
                IF vtransaccion = 1 THEN
                    ROLLBACK WORK;
                    BEGIN WORK;
                ELSE
                    ROLLBACK WORK;
                END IF;
                RETURN vCodRet1, vStatus, vStatusDesc, 
                       vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
                       vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
                       vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
                       vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
                       vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
                       vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
                       vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
                       vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
                       vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
                       vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
            END IF;
            
        END IF;
        
    ELSE
    
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, 
               vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
               vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
               vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
               vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
               vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
               vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
               vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
               vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
               vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
               vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
    
    END IF;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    RETURN vCodRet1, vStatus, vStatusDesc, 
           vFechaMov1, vTipoMov1, vMontoMov1, vDescMov1,
           vFechaMov2, vTipoMov2, vMontoMov2, vDescMov2,
           vFechaMov3, vTipoMov3, vMontoMov3, vDescMov3,
           vFechaMov4, vTipoMov4, vMontoMov4, vDescMov4,
           vFechaMov5, vTipoMov5, vMontoMov5, vDescMov5,
           vFechaMov6, vTipoMov6, vMontoMov6, vDescMov6,
           vFechaMov7, vTipoMov7, vMontoMov7, vDescMov7,
           vFechaMov8, vTipoMov8, vMontoMov8, vDescMov8,
           vFechaMov9, vTipoMov9, vMontoMov9, vDescMov9,
           vFechaMov10, vTipoMov10, vMontoMov10, vDescMov10;
           
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".bm_recordar_password( pUsuario     CHAR(10),  --- Usuario
                                                  pFolio       CHAR(12),  --- Folio
                                                  pCelular     DECIMAL(10,0),   --- No. Celular
                                                  pPasswordNvo CHAR(50) ) --- Contraseña Nueva
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          INTEGER  AS vSesionToken, --- Session Token
          CHAR(35) AS vGeneralInfo; --- Informacion General
     
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vSesionToken     INTEGER;
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vpassword        CHAR(50);
    DEFINE vnumcte          CHAR(20);
    DEFINE vfolio_contrato  CHAR(12);
    DEFINE vnumcel          DECIMAL(10,0);
    DEFINE vexiste_usuario  SMALLINT;
    DEFINE vsecmax          INTEGER;
    DEFINE vtoken           INTEGER;
    DEFINE vid_oper         CHAR(4);
    DEFINE vtransaccion     INTEGER;
     
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vSesionToken = 1234567890;
    LET vGeneralInfo = '';
    
    LET vpassword = '';
    LET vnumcte = '';
    LET vfolio_contrato = '';
    LET vnumcel = 0;
    LET vexiste_usuario = 0;
    LET vsecmax = 0;
    LET vtoken = 0;
    LET vid_oper = '';
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_recordar_password.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_recordar_password.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pUsuario is null OR pUsuario = '') OR 
       (pFolio is null OR pFolio = '') OR 
       (pCelular is null OR pCelular = 0) OR
       (pPasswordNvo is null OR pPasswordNvo = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pUsuario) <> 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pCelular::CHAR(10)) < 10 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Celular incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Celular incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE EL NUMERO DE CLIENTE
    SELECT numcte, folio_contrato, numcel
      INTO vnumcte, vfolio_contrato, vnumcel
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario
       AND folio_contrato = pFolio
       AND numcel = pCelular;
     
    IF (vnumcte is null OR vnumcte = '') OR
       (vfolio_contrato is null OR vfolio_contrato = '' OR vfolio_contrato <> pFolio) OR
       (vnumcel is null OR vnumcel = '' OR vnumcel <> pCelular) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Datos incorrectos, verifique.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Datos incorrectos, verifique.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
     
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte;
       
    IF vsecmax is null THEN
        LET vsecmax = 0;
    END IF;
    
    IF vsecmax > 0 THEN
        SELECT id_oper
          INTO vid_oper
          FROM bdinteg:"informix".si_bm_bitacora
         WHERE DATE(fech_oper) = CURRENT::DATE
           AND numcte = vnumcte
           AND numcel = pCelular
           AND secuencia = vsecmax;
           
        IF vid_oper IN('2201', '1000', '1002', '1003', '1004', '1005') THEN
            LET vCodRet1 = '11111';
            LET vStatus = '';
            LET vStatusDesc = 'Acceso denegado, usuario activo.';
            LET vSesionToken = 0;
            LET vGeneralInfo = 'Acceso denegado, usuario activo.';
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
        END IF;
    END IF;
    
    -- // GENERA EL NUMERO DE SESSION 
    SELECT valor::int
      INTO vtoken
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '52';
     
    IF vtoken is null THEN
        LET vtoken = 1;
    ELSE
        LET vtoken = vtoken + 1;
    END IF;
    
    UPDATE bdibpi:"informix".tkn_parametros
       SET valor = vtoken
     WHERE id_param = '52';
     
    LET vSesionToken = vtoken;
    
    -- // ACTUALIZA REGISTRO DEL USUARIO
    UPDATE bdinteg:"informix".si_bm_usuarios
       SET password = pPasswordNvo,
           fech_pass = current,
           password1 = password,
           fech_pass1 = fech_pass,
           password2 = password1,
           fech_pass2 = fech_pass1,
           password3 = password2,
           fech_pass3 = fech_pass2,
           numaccesos = numaccesos + 1,
           fech_ultacces = current
     WHERE numcte = vnumcte
       AND usuario = pUsuario
       AND folio_contrato = pFolio
       AND numcel = pCelular;
       
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    END IF;
    
    -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
    LET vsecmax = vsecmax + 1;
    
    INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
    VALUES(vSesionToken, current, vnumcte, vsecmax, '1000', pCelular, null, null);
    
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    END IF;
    
    INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
    VALUES(vnumcte, '30', '35', pCelular, current, '5002', 'informix');
    
    LET vStatusDesc = 'Usted ha cambiado su contrasena.';
    LET vGeneralInfo = 'Usted ha cambiado su contrasena.';
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".bm_recordar_usuario( pPassword   CHAR(50),  --- Contraseña
                                                 pFolio      CHAR(12),  --- Folio
                                                 pCelular    DECIMAL(10,0),   --- No. Celular
                                                 pUsuarioNvo CHAR(10) ) --- Usuario Nuevo
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          INTEGER  AS vSesionToken, --- Session Token
          CHAR(35) AS vGeneralInfo; --- Informacion General
    
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vSesionToken     INTEGER;
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vexiste_usuario  SMALLINT;
    DEFINE vusuario         CHAR(50);
    DEFINE vnumcte          CHAR(20);
    DEFINE vexiste_passwd   SMALLINT;
    DEFINE vnumintacce      SMALLINT;
    DEFINE vsecmax          INTEGER;
    DEFINE vtoken           INTEGER;
    DEFINE vid_oper         CHAR(4);
    DEFINE vmaxaccesos      INTEGER;
    DEFINE vnumaccesos      INTEGER;
    DEFINE vtransaccion     INTEGER;
     
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vSesionToken = 0;
    LET vGeneralInfo = '';
    
    LET vexiste_usuario = 0;
    LET vusuario = '';
    LET vnumcte = '';
    LET vexiste_passwd = 0;
    LET vnumintacce = 0;
    LET vsecmax = 0;
    LET vtoken = 0;
    LET vid_oper = '';
    LET vmaxaccesos = 0;
    LET vnumaccesos = 0;
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_recordar_usuario.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_recordar_usuario.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pPassword is null OR pPassword = '') OR 
       (pFolio is null OR pFolio = '') OR 
       (pCelular is null OR pCelular = 0) OR
       (pUsuarioNvo is null OR pUsuarioNvo = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pUsuarioNvo) <> 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pCelular::CHAR(10)) < 10 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Celular incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Celular incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA QUE EL NUEVO USUARIO NO EXISTA
    SELECT COUNT(*)
      INTO vexiste_usuario
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuarioNvo;
     
    IF vexiste_usuario > 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario ya existe.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario ya existe.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
     
    -- // OBTIENE EL NUMERO DE CLIENTE
    SELECT usuario, numcte
      INTO vusuario, vnumcte
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE folio_contrato = pFolio
       AND numcel = pCelular;
    
    -- // VALIDA EL PASSWORD
    SELECT COUNT(*)
      INTO vexiste_passwd
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = vusuario
       AND folio_contrato = pFolio
       AND numcte = vnumcte
       AND numcel = pCelular
       AND password = pPassword;
     
    IF vexiste_passwd = 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vSesionToken = 0;
        
        SELECT numintacce
          INTO vnumintacce
          FROM bdinteg:"informix".si_bm_usuarios
         WHERE usuario = vusuario;
         
        LET vnumintacce = vnumintacce + 1;
         
        IF vnumintacce = 1 THEN
            LET vStatusDesc = 'Contrasena incorrecta, verifique.';
            LET vGeneralInfo = 'Contrasena incorrecta, verifique.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = vusuario;
        ELIF vnumintacce = 2 THEN
            LET vStatusDesc = 'Contrasena incorrecta, verifique o entre a Olvide mi contrasena.';
            LET vGeneralInfo = 'Contrasena incorrecta, verifique o entre a Olvide mi contrasena.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = vusuario;
        ELIF vnumintacce >= 3 THEN
            LET vStatusDesc = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
            LET vGeneralInfo = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = vusuario;
        END IF;
        
        IF vtransaccion = 1 THEN
            COMMIT WORK;
            BEGIN WORK;
        ELSE
            COMMIT WORK;
        END IF;
        
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // VALIDA SI EL USUARIO ESTA BLOQUEADO
    SELECT numintacce
      INTO vnumintacce
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE numcte = vnumcte
       AND numcel = pCelular;
       
    IF vnumintacce >= 3 THEN
        LET vStatusDesc = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
        LET vGeneralInfo = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    ELSE
        IF vnumintacce > 0 THEN
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = 0
             WHERE numcte = vnumcte
               AND numcel = pCelular;
        END IF;
    END IF;
    
    -- // OBTIENE NUMERO DE ACCESOS PERMITIDOS AL DIA
    SELECT valor::int
      INTO vmaxaccesos
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '51';
     
    IF vnumaccesos > vmaxaccesos THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Accesos del dia agotados.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Accesos del dia agotados.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = pCelular;
       
    IF vsecmax is null THEN
        LET vsecmax = 0;
    END IF;
    
    IF vsecmax > 0 THEN
        SELECT id_oper
          INTO vid_oper
          FROM bdinteg:"informix".si_bm_bitacora
         WHERE DATE(fech_oper) = CURRENT::DATE
           AND numcte = vnumcte
           AND numcel = pCelular
           AND secuencia = vsecmax;
           
        IF vid_oper IN('2201', '1000', '1002', '1003', '1004', '1005') THEN
            LET vCodRet1 = '11111';
            LET vStatus = '';
            LET vStatusDesc = 'Acceso denegado, usuario activo.';
            LET vSesionToken = 0;
            LET vGeneralInfo = 'Acceso denegado, usuario activo.';
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
        END IF;
    END IF;
    
    -- // GENERA EL NUMERO DE SESSION 
    SELECT valor::int
      INTO vtoken
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '52';
     
    IF vtoken is null THEN
        LET vtoken = 1;
    ELSE
        LET vtoken = vtoken + 1;
    END IF;
    
    UPDATE bdibpi:"informix".tkn_parametros
       SET valor = vtoken
     WHERE id_param = '52';
     
    LET vSesionToken = vtoken;
    
    -- // ACTUALIZA REGISTRO DEL USUARIO
    UPDATE bdinteg:"informix".si_bm_usuarios
       SET usuario = pUsuarioNvo,
           numaccesos = numaccesos + 1,
           fech_ultacces = current
     WHERE folio_contrato = pFolio
       AND usuario = vusuario
       AND numcte = vnumcte
       AND numcel = pCelular
       AND password = pPassword;
       
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '00110';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    END IF;
    
    -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
    LET vsecmax = vsecmax + 1;
    
    INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
    VALUES(vSesionToken, current, vnumcte, vsecmax, '1000', pCelular, null, null);
    
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    END IF;
    
    INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
    VALUES(vnumcte, '30', '95', pCelular, current, '5002', 'informix');
    
    LET vStatusDesc = 'Usted ha cambiado su usuario.';
    LET vGeneralInfo = 'Usted ha cambiado su usuario.';
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".bm_valida_usuario( pUsuario CHAR(10) ) --- Usuario
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          CHAR(35) AS vGeneralInfo; --- Informacion General
     
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vusuario         CHAR(20);
    DEFINE vid_status       CHAR(2);
    DEFINE vnumcte          CHAR(20);
    DEFINE vnumcel          CHAR(15);
    DEFINE vsecmax          INTEGER;
    DEFINE vid_oper         CHAR(4);
    DEFINE vtoken           INTEGER;
    DEFINE vSesionToken     INTEGER;
    DEFINE vtransaccion     INTEGER;
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vGeneralInfo = '';
    
    LET vusuario = '';
    LET vid_status = '';
    LET vnumcte = '';
    LET vnumcel = '';
    LET vsecmax = 0;
    LET vid_oper = '';
    LET vtoken = 0;
    LET vSesionToken = 0;
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_valida_usuario.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/informix/jivan/bancamovil/bm_valida_usuario.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF pUsuario is null OR pUsuario = '' THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pUsuario) != 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE DATOS DEL USUARIO
    SELECT usuario, id_status, numcte, numcel
      INTO vusuario, vid_status, vnumcte, vnumcel
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario;
     
    IF (vusuario is null OR vusuario = '' OR vusuario <> pUsuario) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
    END IF;
    
    IF (vid_status <> '30') OR 
       (vnumcte is null OR vnumcte = '' ) OR 
       (vnumcel is null OR vnumcel = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Datos incorrectos, verifique.';
        LET vGeneralInfo = 'Datos incorrectos, verifique.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
    END IF;
    
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = vnumcel;
       
    IF vsecmax is null THEN
        LET vsecmax = 0;
    END IF;
       
    -- // VALIDA QUE EL ULTIMO REGISTRO EN BITACORA SEA FIN DE SESION
    IF vsecmax > 0 THEN
        SELECT id_oper
          INTO vid_oper
          FROM bdinteg:"informix".si_bm_bitacora
         WHERE DATE(fech_oper) = CURRENT::DATE
           AND numcte = vnumcte
           AND numcel = vnumcel
           AND secuencia = vsecmax;
           
        IF vid_oper <> '1001' THEN
            LET vCodRet1 = '11111';
            LET vStatus = '';
            LET vStatusDesc = 'Error en aplicativo.';
            LET vGeneralInfo = 'Error en aplicativo.';
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
        END IF;
    END IF;
    
    -- // GENERA EL NUMERO DE SESSION 
    SELECT valor::int
      INTO vtoken
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '52';
     
    IF vtoken is null THEN
        LET vtoken = 1;
    ELSE
        LET vtoken = vtoken + 1;
    END IF;
    
    UPDATE bdibpi:"informix".tkn_parametros
       SET valor = vtoken
     WHERE id_param = '52';
     
    LET vSesionToken = vtoken;
    LET vsecmax = vsecmax + 1;
       
    -- // GENERA REGISTRO EN BITACORA COMO LOGIN-USUARIO
    INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
    VALUES(vSesionToken, current, vnumcte, vsecmax, '2201', vnumcel, null, null);
    
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo; 
    END IF;
    
    -- // OBTIENE EL NOMBRE CORTO DEL CLIENTE
    SELECT TRIM(nombre1)||' '||TRIM(apell_paterno)
      INTO vGeneralInfo
      FROM bdinteg:"informix".si_cliente
     WHERE numcte = vnumcte;
     
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;

    RETURN vCodRet1, vStatus, vStatusDesc, vGeneralInfo;
    
    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtienedircta(pEmpresa CHAR(3), pCliente CHAR(20), pCuenta CHAR(20))

RETURNING 
	CHAR(6)   AS CodRet,
	CHAR(20)  AS Cuenta,
	CHAR(20)  AS Cliente,
	CHAR(4)   AS Producto,
	CHAR(2)   AS Status,
	integer   AS UltChq,
	smallint  AS ChqExpMes,
	SMALLINT  AS DireccEnvio;

DEFINE vCodRet      CHAR(6);
DEFINE vCodRet1      CHAR(6);
DEFINE vCodRet2      CHAR(60);
DEFINE cCuenta      CHAR(20);
DEFINE cCliente		CHAR(20);
DEFINE cProducto	CHAR(4);
DEFINE cStatus      CHAR(2);
DEFINE cUltChq	    integer;
DEFINE cChqExpMes   SMALLINT;
DEFINE cDireccEnvio	SMALLINT;
DEFINE cContador    SMALLINT;

DEFINE sql_err, isam_err  INT;  
DEFINE desc_err      CHAR(60); 
	
-- ****************************************************************************
-- Inicializar variables
-- ****************************************************************************
	
LET vCodRet        = "000";
LET vCodRet1        = "000";
LET vCodRet2        = "";
LET cCuenta        = "";
LET cCliente       = "";
LET cProducto      = "";
LET cStatus        = "0";
LET cUltChq        = 0;
LET cChqExpMes     = 0;
LET cDireccEnvio   = 0;
LET cContador      = 0;

SET ISOLATION DIRTY READ ;
SET LOCK MODE TO WAIT 3;

 --SET DEBUG FILE TO "/informix/lflores/sp_obtienedircta.out";
 --TRACE ON;

BEGIN

	ON EXCEPTION SET sql_err,isam_err,desc_err
	    SET DEBUG FILE TO "/resplogifx/conciliachq/sp_obtienedircta.err";
		TRACE ON;
		IF sql_err <> 0 OR isam_err <> 0 THEN
			LET vCodRet = sql_err;
			LET vCodRet1 = isam_err;
			LET vCodRet2 = desc_err;
			
			RETURN vCodRet, cCuenta, cCliente, cProducto, cStatus, cUltChq, cChqExpMes, cDireccEnvio;
		END IF;
	END EXCEPTION;
	
	IF pCliente = '' THEN
	   LET pCliente = NULL;
	END IF;
	
	IF pCuenta = '' THEN
	   LET pCuenta = NULL;
	END IF;
	
-- ****************************************************************************
-- Valida la informacion de entrada
-- ****************************************************************************
    IF pCliente IS NULL AND pCuenta IS NULL THEN
    -- Deve mandar al menos un parametro.	   
		LET vCodRet = '001'; 
		RETURN vCodRet, cCuenta, cCliente, cProducto, cStatus, cUltChq, cChqExpMes, cDireccEnvio;
	END IF;
	
    IF pCliente IS NOT NULL AND pCuenta IS NOT NULL THEN
	 -- Solamente deve se mandar solamente un parametro pCuenta o pCliente.	
		LET vCodRet = '002'; 
		RETURN vCodRet, cCuenta, cCliente, cProducto, cStatus, cUltChq, cChqExpMes, cDireccEnvio;
	END IF;
	
-- ****************************************************************************
-- Obtener registros
-- ****************************************************************************
IF pCliente IS NULL OR pCliente = '' THEN
   
	SELECT cuenta, num_cte, producto, status_cta, ult_chq, chq_exp_mes, direcc_envio
	INTO cCuenta, cCliente , cProducto ,cStatus ,cUltChq ,cChqExpMes ,cDireccEnvio
	FROM bdicheq:"informix".sc_maechq
	WHERE empresa = pEmpresa
	AND cuenta = pCuenta;
    
    IF cCuenta IS NULL THEN
	 -- No se encuentran registros de la cuenta.
		LET vCodRet = '004'; 
		RETURN vCodRet, NVL(cCuenta,''), NVL(cCliente,''), NVL(cProducto,''), NVL(cStatus,0), cUltChq, cChqExpMes, NVL(cDireccEnvio,0);
	END IF;
	
	RETURN vCodRet, cCuenta, cCliente, cProducto, cStatus, cUltChq, cChqExpMes, cDireccEnvio;

ELSE
	
	LET cContador = 0;
	
	FOREACH
	
	  --Direcciones completas del cliente
		SELECT cuenta, num_cte, producto, status_cta, ult_chq, chq_exp_mes, direcc_envio
		INTO cCuenta , cCliente ,cProducto ,cStatus ,cUltChq ,cChqExpMes ,cDireccEnvio
		FROM bdicheq:"informix".sc_maechq
		WHERE empresa = pEmpresa
		  AND num_cte = pCliente
		ORDER BY cuenta
		
		LET cContador = cContador + 1;
		
		RETURN vCodRet, NVL(cCuenta,''), NVL(cCliente,''), NVL(cProducto,''), NVL(cStatus,0), cUltChq, cChqExpMes, NVL(cDireccEnvio,0) WITH RESUME;
	
	END FOREACH		
	
    IF cContador = 0 THEN
	 -- El cliente no tiene cuentas.
		LET vCodRet = '004'; 
		RETURN vCodRet, NVL(cCuenta,''), NVL(cCliente,''), NVL(cProducto,''), NVL(cStatus,0), cUltChq, cChqExpMes, NVL(cDireccEnvio,0);
	END IF;
	
END IF;

END;    
END PROCEDURE
DOCUMENT
'MODIFICO: Valentin Lopez',
'FECHA: 13 de Junio del 2011',
'DESCRIPCION: Consulta las direcciones de la cuenta o el cliente.',
'VERSION: 20110613.1529',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_obtieneinfouh(pCiudad smallint, pColonia smallint , pCveDom smallint, pRegistros INTEGER)
RETURNING CHAR(5)  AS Codigo_Retorno,
		  SMALLINT AS CveDomicilio,
          CHAR(30) AS NombreDomicilio;          
          
DEFINE cCodRet          CHAR(5); 
DEFINE iSqlErr      	INTEGER;
DEFINE cDomicilio		CHAR(30);
DEFINE cCveDomicilio    SMALLINT;
DEFINE vCont			INTEGER;
DEFINE iValor			INTEGER;

LET iSqlErr          = 0;
LET cCodRet			 = '00000';
LET cDomicilio 		 = '';
LET cCveDomicilio     =0;
LET vCont 			 =0;
LET iValor 			 =0;

BEGIN
ON EXCEPTION SET iSqlErr
   IF iSqlErr != 0 THEN
      LET cCodRet= iSqlErr;
      RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
   END IF;
END EXCEPTION;

--Set debug file to '/tmp/sp_ObtieneInfoUH.out';
--trace on;

--Validación de parametros
	IF pCiudad IS NULL OR pCiudad = 0 THEN
		LET cCodRet  = '00001';
		RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
	END IF;

	IF (pColonia IS NULL) OR (pColonia = 0) THEN
		LET cCodRet  = '00001';
		RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
	END IF;

	IF pCveDom IS NULL OR pCveDom = 0 THEN
		LET cCodRet  = '00001';
		RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
	END IF;

--obtencion del valor  para realizar la paginacion
		SELECT valor::integer 
			INTO iValor
		FROM bdicobranza:cb_param 
		WHERE empresa = '001' 
		AND cod_param = '32';
	--validacion de los parametros.
	IF iValor IS NULL OR  iValor = "" THEN
		LET cCodRet = '00002';
		RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
	END IF;
	
--clave domicilio= 1 manzana, 2 otros, 3 andador, 4 etapa, 5 edificio, 6 entrada, 7 lote

	FOREACH
		SELECT SKIP pRegistros FIRST iValor complementoclave,nombredomicilio
		INTO cCveDomicilio,cDomicilio
		FROM bdinteg:si_catdomicilios			
		WHERE clavedomicilio= pCveDom
		AND numerociudad=pCiudad
		AND numerocolonia= pColonia
		ORDER BY nombredomicilio		

		RETURN cCodRet, cCveDomicilio, trim(cDomicilio) WITH RESUME;		
	END FOREACH;
	
	LET vCont = dbinfo("sqlca.sqlerrd2");
	IF vCont = 0 THEN
		LET cCodRet = '00003';
		RETURN cCodRet, cCveDomicilio, trim(cDomicilio);
	END IF;
	
END
END PROCEDURE
DOCUMENT 
'DESCRIPCION: Se obtienen manzana,otros, andador, etapa, edificio, entrada, lote de una colonia con Unidad Habitacional',
'AUTOR : Abigail Vasavilbazo Cañedo',
'FECHA : Feb2011',
'BD    : BDINTEG',
'VERSION: 20110204.1358',
'MODIFICACION: Se modifica para que se obtenga tambien clave y descripcion de manzana, otros, andador, etapa, edificio, entrada y lote de una colonia con una ',
'Unidad Habitacional, ya que anteriormente solo devolvía la descripción.',
'AUTOR : Maria Elena Angulo Aispuro',
'FECHA : Feb2011',
'VERSION: 20110216.1635';

CREATE PROCEDURE "informix".sp_obtienepuntoscardinales()
RETURNING CHAR(5)  AS Codigo_Retorno,
          CHAR(100) AS Valor,
		  CHAR(50) AS Descripcion;          
          
DEFINE cCodRet          CHAR(5); 
DEFINE iSqlErr      	INTEGER;
DEFINE cValor			CHAR(100);
DEFINE cDescripcion		CHAR(50);

LET iSqlErr          = 0;
LET cCodRet			 = '00000';
LET cValor 			 = '';
LET cDescripcion	 = '';

BEGIN
ON EXCEPTION SET iSqlErr
   IF iSqlErr != 0 THEN
      LET cCodRet= iSqlErr;
      RETURN cCodRet, cValor, cDescripcion;
   END IF;
END EXCEPTION;

--Set debug file to '/tmp/sp_ObtienePuntosCardinales.out';
--trace on;

--se obtienen puntos cardinales
	FOREACH
		SELECT valor, descripcion
		INTO cValor, cDescripcion
		FROM bdinteg:si_param_dom			
		WHERE cod_param in ('20', '21', '22', '23')
		ORDER BY cod_param

		RETURN cCodRet, trim(cValor), trim(cDescripcion) WITH RESUME;
		
	END FOREACH;
	
END
END PROCEDURE
DOCUMENT 
'DESCRIPCION: Se obtienen los puntos cardinales',
'AUTOR : Abigail Vasavilbazo Cañedo',
'FECHA : Feb2011',
'BD    : BDINTEG',
'VERSION: 20110203.1338';

CREATE PROCEDURE "informix".sp_actnomcterfcalterno(pEmpresa CHAR(3), pNumcte CHAR (20), pRFC CHAR (13), pTipo CHAR(1))
RETURNING CHAR(5) AS retorno;
			
    -- // DEFINICION DE VARIABLES
    DEFINE iSqlErr			INTEGER;
    DEFINE cValRetorno	    CHAR(5);
    DEFINE cNumCte		    CHAR(20);
    DEFINE cApellPaterno	CHAR(26);
    DEFINE cApellMaterno	CHAR(26);
    DEFINE cNombre1		    CHAR(26);
    DEFINE cNombre2			CHAR(26);
    DEFINE cRfc				CHAR(13);
    DEFINE cRfcAlt			CHAR(13);
    DEFINE iRFCCont			INTEGER;
    DEFINE vexiste          INTEGER;

    -- // INICIALIZACION DE VARIABLES
    LET cValRetorno 	= '00001';
    LET cNumCte			= "";
    LET cApellPaterno 	= "";
    LET cApellMaterno	= "";
    LET cNombre1		= "";
    LET cNombre2		= "";
    LET cRfc			= "";
    LET cRfcAlt			= "";
    LET iRFCCont 		= 0;
    LET vexiste         = 0;
    
    --- SET DEBUG FILE TO "/tmp/sp_actnomcterfcalterno.out"; 
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO wait 3;

    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            RETURN iSqlErr;
        END IF;
    END EXCEPTION;

    IF NVL(pEmpresa,'') = '' OR NVL(pNumcte,'') = '' OR NVL(pRFC,'') = '' OR NVL(pTipo,'') = '' THEN

        LET cValRetorno = '00002';
        LET pNumcte = LPAD(TRIM(pNumcte),9,'0');
        LET pRFC = LPAD(TRIM(pRFC),13,'0');

    ELIF pTipo = 1 OR pTipo = 2 THEN

        Update bdinteg:"informix".si_cliente 
           SET rfc_alterno = pRFC
         WHERE numcte = pNumcte;
         
        LET cValRetorno = '00000';

    ElIf pTipo = 3 OR pTipo = 4  THEN

        SELECT COUNT(*)
          INTO vexiste
          FROM bdilide:"informix".sl_consat 
         Where num_cte = pNumcte;
         
        IF vexiste = 0 THEN
        --- IF NOT EXISTS (SELECT num_cte FROM bdilide:"informix".sl_consat Where num_cte = pNumcte) THEN
            SELECT nombre1 
              INTO cNombre1 
              FROM bdinteg:"informix".si_cliente
             WHERE numcte = pNumcte;

            -- // SE ELIMINA ESTE UPDATE A SOLICITUD DE ENRIQUE PEREZ  14-11-2011 MLFLORES
            Update bdinteg:"informix".si_cliente 
               SET rfc_alterno = pRFC 
               --- (nombre1 = TRIM (cNombre1)||'X',) 
             WHERE numcte = pNumcte;
               
            LET cValRetorno = '00000';
        ElSE
            Update bdinteg:"informix".si_cliente 
               SET rfc_alterno = pRFC
             WHERE numcte = pNumcte;
               
            LET cValRetorno = '00000';

        END IF;

    END IF;

    RETURN cValRetorno;

    END
    
END PROCEDURE

DOCUMENT
'Creado: Martin Miranda',
'Fecha: 04/03/2011',
'Descripcion: Se crea para actaulizar el campo rfc_alterno, al igual que el nombre del cliente si existe mas de 1 cliente con el mismo rfc',
'Modifico: Martin Miranda',
'Fecha: 07/06/2011',
'Descripcion: Modifica para tomar pTipo con valor 4 en el Update del Cliente''Modificado: Martin Miranda',
'Fecha: 14/06/2011',
'Descripcion: Se agrega validación para que no añada la letra "X" al campo nombre1 de la tabla si_cliente cuando exista un registro para',
'             ese cliente en la tabla sl_consat de la base de datos bdilide.';

CREATE PROCEDURE "informix".sp_consultanombrerfcalterno(pEmpresa CHAR(3), pNumcte CHAR(20), pRFC CHAR (13))
RETURNING 	CHAR(5) AS retorno,
			CHAR(20) AS numcta, 
			CHAR (20) AS numcte,
			CHAR(26) AS apell_paterno, 
			CHAR(26) AS apell_materno,
			CHAR(26) AS nombre1, 
			CHAR(26) AS nombre2, 
			CHAR(13) AS rfc;
	
    -- DEFINICION DE VARIABLES
    DEFINE iSqlErr			INTEGER;
    DEFINE cValRetorno		CHAR(5);
    DEFINE cNumCte			CHAR(20);
    DEFINE cApellPaterno	CHAR(26);
    DEFINE cApellMaterno	CHAR(26);
    DEFINE cNombre1			CHAR(26);
    DEFINE cNombre2			CHAR(26);
    DEFINE cRfc				CHAR(13);

    --INICIALIZACION DE VARIABLES
    LET cValRetorno     = '00001';
    LET cNumCte			= "";
    LET cApellPaterno 	= "";
    LET cApellMaterno	= "";
    LET cNombre1		= "";
    LET cNombre2		= "";
    LET cRfc			= "";

    --- SET DEBUG FILE TO "/tmp/sp_consultanombrerfcalterno.out"; 
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO wait 3;

    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            RETURN iSqlErr,'','','','','','','';
        END IF;
    END EXCEPTION;

    IF NVL(pEmpresa,'') = '' OR NVL(pNumcte,'') = '' THEN
        LET cValRetorno = '00001';
    ELSE
        LET pNumcte = LPAD(TRIM(pNumcte),9,'0');
        LET pRFC = LPAD(TRIM(pRFC),13,'0');

        IF (Select rfc_alterno FROM bdinteg:"informix".si_cliente WHERE empresa = pEmpresa AND numcte = pNumcte) <> "" THEN
            SELECT numcte, apell_paterno, apell_materno, nombre1, nombre2,  rfc_alterno 
              INTO cNumCte, cApellPaterno, cApellMaterno, cNombre1,cNombre2, cRfc
              FROM bdinteg:"informix".si_cliente
             WHERE empresa = pEmpresa AND numcte = pNumcte;	
        ELSE
            SELECT numcte, apell_paterno, apell_materno, nombre1, nombre2,  rfc
              INTO cNumCte, cApellPaterno, cApellMaterno, cNombre1,cNombre2, cRfc
              FROM bdinteg:"informix".si_cliente
             WHERE empresa = pEmpresa AND numcte = pNumcte;
        END IF;

        LET cValRetorno = '00000';
    END IF;
    
    RETURN cValRetorno,'', cNumCte, cApellPaterno, cApellMaterno, cNombre1,cNombre2, cRfc;	
    
    END
    
END PROCEDURE             
DOCUMENT
'Creado: Martin Miranda',
'Fecha: 04/03/2011',
'Descripcion: Se crea para obtener los datos del cliente seleccionado';

CREATE PROCEDURE "informix".sp_consultacalles(pCalle INTEGER ,pNombre char(30),pRegistros INTEGER)
RETURNING CHAR(6)  AS Codigo_Retorno,
          CHAR(80) AS Mensaje_Retorno,
		  INTEGER  AS Calle,
		  CHAR(30) AS Nombre;          
          
DEFINE cCodRet           CHAR(6); 
DEFINE cMensajeRet       CHAR(80);
DEFINE cComentario       CHAR(80);
DEFINE iSqlErr      	 INTEGER;
DEFINE iIsamErr          INTEGER;
DEFINE cErrorInfo        CHAR(80);
DEFINE vCont 			 INTEGER;
DEFINE iValor 			 INTEGER;
DEFINE iCalle   		 INTEGER; 
DEFINE cNombre     		 CHAR(30); 

BEGIN


ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
   IF iSqlErr != 0 THEN
      LET cCodRet= iSqlErr;
      LET cMensajeRet= cErrorInfo;
      RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'');
   END IF;
END EXCEPTION;

LET iSqlErr                  = 0;
LET iIsamErr                 = 0;
LET cErrorInfo               = '';
LET cCodRet                  = '000000';
LET cMensajeRet              = 'Se realizó la consulta correctamente';
LET vCont 					 = 0;
LET iValor 					 = 0;
LET iCalle                  = 0;
LET cNombre                  = '';

--Set debug file to '/home/sysifx/Antonio/sp_ConsultaCallesCP.out';
--trace on;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

--obtencion del valor  para realizar la paginacion.
	SELECT valor::integer 
		INTO iValor
	FROM bdicobranza:cb_param 
	WHERE empresa = '001' 
	AND cod_param = '32';
--validacion de los parametros.
IF iValor IS NULL OR  iValor = "" THEN
    LET cCodRet                  = '000002';
	LET cMensajeRet              = 'Error al obtener el parámetro del máximo numero de registros';
	RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'');
END IF;
--se obtiene la informacion del numero de calle proporcionado en el parametro de entrada
IF pCalle > 0 THEN
	SELECT numerocalle,nombrecalle
	INTO iCalle,cNombre
	FROM bdinteg:si_catcalles				
	WHERE numerocalle = pCalle;
	
	LET vCont = dbinfo("sqlca.sqlerrd2");
		IF vCont = 0 THEN
			LET cCodRet = '000003';
			LET cMensajeRet = 'No se encontraron registros';
			RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'');
		END IF;
		
	RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'');
END IF;

--se obtienen los registros  indicados en el parametro obtenido con anterioridad que tengan similitud a la consulta
	FOREACH WITH HOLD
	
		SELECT  SKIP pRegistros FIRST iValor numerocalle,nombrecalle
		INTO iCalle,cNombre
		FROM bdinteg:si_catcalles				
		WHERE UPPER(TRIM(nombrecalle)) LIKE CASE when pNombre = '' THEN UPPER(nombrecalle)   ELSE '%'||UPPER(TRIM(pNombre))||'%' END
		ORDER BY nombrecalle	
			
			RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'') WITH RESUME;
	END FOREACH;
	
		LET vCont = dbinfo("sqlca.sqlerrd2");
		IF vCont = 0 THEN
			LET cCodRet = '000003';
			LET cMensajeRet = 'No se encontraron registros';
			RETURN cCodRet, cMensajeRet,iCalle,NVL(cNombre,'');
		END IF;
END
END PROCEDURE
DOCUMENT 
'Se realiza procedimiento para Obtener el listado de calles existentes y/o obtener coincidencias por descripcion de calle ',
'AUTOR : Jesús Manuel Aguilar Heredia',
'FECHA : 08/SEPTIEMBRE/2010',
'Se elimina el forzado del índice.',
'AUTOR : Jesús Antonio Bastidas López',
'FECHA : 08/02/2011',
'Version: 20110208.1241',
'BD    : BDINTEG',
'MODIFICACION: Cambiar condición en consulta por nombrecalle, quitar por numerocalle para bajar el costeo y eliminar sequential scan.',
'AUTOR: Marco A. Campos  2012-02-21';

CREATE PROCEDURE  "informix".cons_tarjetas_cte_pba(pempresa     CHAR(3),
                                              pnumcte      CHAR(20),
                                              pregistros   SMALLINT)

RETURNING CHAR(5),       -- Codigo de Retorno
          CHAR(20),      -- Nro de Cliente
          CHAR(26),      -- Nombre1
	    CHAR(26),      -- Nombre2
	    CHAR(26),      -- Apellido Paterno
          CHAR(26),      -- Apellido Materno
          DATE,  	       -- Fecha Nacimiento
	    CHAR(13),      -- RFC
	    CHAR(20),      -- CUENTA
	    CHAR(20),      -- TARJETA
	    CHAR(1),       -- STATUS APLICATIVO
	    SMALLINT,      -- SISTEMA
          CHAR(50),      -- PRODUCTO
          CHAR(50),      -- DIVISA
          CHAR (3);    --STATUS DE INTERCARD

-- ****************************************************************************
-- *                        DEFINICION DE VARIABLES                           *
-- ****************************************************************************
DEFINE scod_ret        CHAR(5);
DEFINE vsqlerr         INTEGER;
DEFINE s_numcte        CHAR(20);
DEFINE s_nombre1       CHAR(26);
DEFINE s_nombre2       CHAR(26);
DEFINE s_paterno       CHAR(26);
DEFINE s_materno       CHAR(26);
DEFINE s_fechanac      DATE;
DEFINE s_rfc           CHAR(13);
DEFINE s_cuenta        CHAR(20);
DEFINE s_tarjeta       CHAR(20);
DEFINE v_cuantos       SMALLINT;
DEFINE s_status        CHAR(1);
DEFINE s_sistema       SMALLINT;
DEFINE s_status_cta    CHAR(1);
DEFINE s_producto      CHAR(50);
DEFINE s_divisa        CHAR(50);
DEFINE s_codstatustarjeta CHAR(3);

-- ****************************************************************************
-- *                        ASIGNACION DE VARIABLES                           *
-- ****************************************************************************
LET scod_ret      = "000";
LET vsqlerr       = 0;
LET v_cuantos     = 0;
LET s_numcte      = "";
LET s_nombre1	= "";
LET s_nombre2	= "";
LET s_paterno	= "";
LET s_materno	= "";
LET s_fechanac	= "";
LET s_rfc	      = "";
LET s_cuenta	= "";
LET s_tarjeta	= "";
LET s_status      = "";
LET s_sistema     = 0;
LET s_status_cta  = "";
LET s_producto    = "";
LET s_divisa      = "";
LET s_codstatustarjeta = "";

--scod_ret,s_numcte,s_nombre1,s_nombre2,s_paterno,s_materno,s_fechanac,s_rfc,s_cuenta,s_tarjeta,s_status,s_sistema,s_producto,s_divisa;


-- ****************************************************************************
-- *                        CONTROL DE ERRORES                                *
-- ****************************************************************************
BEGIN
ON EXCEPTION SET vsqlerr
   IF vsqlerr != 0 THEN
      LET scod_ret=vsqlerr;
      RETURN scod_ret,s_numcte,s_nombre1,s_nombre2,s_paterno,s_materno,s_fechanac,s_rfc,s_cuenta,s_tarjeta,s_status,s_sistema,s_producto,s_divisa,s_codstatustarjeta;
   END IF;
END EXCEPTION;

--SET DEBUG FILE TO "/pisa/pisabanco/pisa_ftes/integral/cons_tarjetas_cte.out";
--TRACE ON;

-- ****************************************************************************
-- *                        PROGRAMA PRINCIPAL                                *
-- ****************************************************************************

   LET pempresa = pempresa;
   LET pnumcte = pnumcte;


  -- Valida Parametros de Entrada

  IF pempresa = "" or
     pnumcte = ""  then
     LET scod_ret = "110";
     RETURN scod_ret,s_numcte,s_nombre1,s_nombre2,s_paterno,s_materno,s_fechanac,s_rfc,s_cuenta,s_tarjeta,s_status,s_sistema,s_producto,s_divisa,s_codstatustarjeta;
  END IF




  -- Extrae las Tarjeta de Cheques
  FOREACH
     SELECT a.cuenta, a.num_tarjeta, a.numcte, a.status_tar, e.producto || " " || e.nombre,f.divisa || " " || f.descripcion,
            b.nombre1, b.nombre2, b.apell_paterno, b.apell_materno, b.rfc,
            c.fecha_nac, tar.codstatustarjeta
       INTO s_cuenta, s_tarjeta, s_numcte,s_status, s_producto, s_divisa,
            s_nombre1,s_nombre2,s_paterno,s_materno,s_rfc,
            s_fechanac, s_codstatustarjeta
       FROM bdicheq:sc_tarjeta a,
            bdinteg:si_cliente b,
            bdinteg:si_ctepf c,
            bdicheq:sc_maechq d,
            bdicheq:sc_producto e,
            bdinteg:si_divisas f,
            intercard:tarjeta tar
      WHERE a.empresa = b.empresa
            AND a.numcte = b.numcte
            AND a.empresa = c.empresa
            AND a.numcte = c.numcte
            AND a.empresa = d.empresa
            AND a.cuenta = d.cuenta
            AND e.empresa = a.empresa
            AND e.producto = a.prodtarjeta
            AND f.empresa = a.empresa
            AND f.divisa = e.divisa
            AND (a.num_tarjeta = tar.numtarjeta)

            AND ((a.empresa=pempresa)
--            AND (a.tipo_tarjeta='T')
            AND (d.status_cta = "1")
            AND (a.numcte=pnumcte)) order by a.num_tarjeta

     LET s_sistema = 1;

     LET v_cuantos = v_cuantos + 1;
     IF v_cuantos <= pregistros THEN
        CONTINUE FOREACH;
     END IF

     RETURN scod_ret,s_numcte,s_nombre1,s_nombre2,s_paterno,s_materno,s_fechanac,s_rfc,s_cuenta,s_tarjeta,s_status,s_sistema,s_producto,s_divisa,s_codstatustarjeta
            WITH RESUME;


  END FOREACH

  -- Extrae las Tarjeta de Credito
  FOREACH
SELECT {+INDEX(bdicred:sd_maecred idx_maecreda), +INDEX(bdicred:sd_tarjeta idx_tarjeta1),  +INDEX(bdinteg:si_cliente idx_si_cliente5)}
            a.num_credito, a.num_tarjeta, a.numcte, a.status_tar,  e.num_producto || " " || e.nombre_prod, f.divisa || " " || f.descripcion,
            b.nombre1, b.nombre2, b.apell_paterno, b.apell_materno, b.rfc,
            c.fecha_nac, tar.codstatustarjeta
       INTO s_cuenta,  s_tarjeta, s_numcte,  s_status, s_producto, s_divisa,
            s_nombre1, s_nombre2, s_paterno, s_materno, s_rfc,
            s_fechanac, s_codstatustarjeta
       FROM bdicred:sd_maecred d,
            bdicred:sd_tarjeta a,
            bdinteg:si_cliente b,
            bdinteg:si_ctepf c,
            bdicred:sd_definicion e,
            bdinteg:si_divisas f,
            intercard:tarjeta tar
      WHERE d.empresa= pempresa
            and d.numcte=pnumcte
            and b.empresa = pempresa
            and d.numcte = b.numcte
            AND d.numcte = c.numcte
            and a.empresa = d.empresa
            and a.num_credito = d.num_credito
            AND e.empresa = d.empresa
            AND e.num_producto = d.num_producto
            and f.empresa=pempresa
            AND f.divisa = d.divisa
            AND a.num_tarjeta = tar.numtarjeta
            AND d.status_cred <> "FF"
	ORDER BY a.num_tarjeta

     LET s_sistema = 6;

     LET v_cuantos = v_cuantos + 1;
     IF v_cuantos <= pregistros THEN
        CONTINUE FOREACH;
     END IF

     RETURN scod_ret,s_numcte,s_nombre1,s_nombre2,s_paterno,s_materno,s_fechanac,s_rfc,s_cuenta,s_tarjeta,s_status,s_sistema,s_producto,s_divisa,s_codstatustarjeta
            WITH RESUME;


  END FOREACH

END

END PROCEDURE

