CREATE PROCEDURE "informix".sp_cargaservicios(pEmpresa CHAR(3), pTipo CHAR(1), pUsuario CHAR(8),
											  pIP CHAR(16), pClaveip CHAR(20),
											  pPuerto CHAR(6), pClavepuerto CHAR(20),
											  pMensaje CHAR(10), pClavemsg CHAR(20),
											  pSubmensaje CHAR(10), pClavesubmsg CHAR(20))
	RETURNING CHAR(5);
	
	DEFINE vCodret	CHAR(5);
	DEFINE vsqlerr	INTEGER;
	DEFINE visamerr	INTEGER;
	DEFINE vSucursal CHAR(4);

	LET vCodret = "000";
	LET vSucursal = "";
	
	SET ISOLATION TO DIRTY READ;
	
	BEGIN
		ON EXCEPTION SET vsqlerr, visamerr
		   IF vsqlerr != 0 THEN
				LET vCodret = vsqlerr;
				RETURN vCodret;
		   END IF;
		END EXCEPTION;

		IF pTipo = "1" THEN	--si tipo = 1 inserta 4 registros en la tabla.
			FOREACH

				SELECT 	sucursal
				INTO 	vSucursal
				FROM   	bdinteg:"informix".si_sucursales
				WHERE  	empresa = pEmpresa
				AND		tpo_sucursal = 'S'
				ORDER BY sucursal
				
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClavemsg, pMensaje, '1', pUsuario, CURRENT);
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClavesubmsg, pSubmensaje, '1', pUsuario, CURRENT);
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClaveip, pIP, '1', pUsuario, CURRENT);
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClavepuerto, pPuerto, '1', pUsuario, CURRENT);
				
			END FOREACH
			
		ELIF pTipo = "2" THEN -- si tipo = 2 inserta 3 registros en la tabla.
			FOREACH

				SELECT 	sucursal
				INTO 	vSucursal
				FROM   	bdinteg:"informix".si_sucursales
				WHERE  	empresa = pEmpresa
				AND		tpo_sucursal = 'S'
				ORDER BY sucursal
				
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClavemsg, pMensaje, '1', pUsuario, CURRENT);
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClaveip, pIP, '1', pUsuario, CURRENT);
				INSERT INTO bdinteg:"informix".si_sucservicios (empresa, sucursal, cod_servicio, valor, flag_servicio, user_insert, fecha_insert) VALUES(pEmpresa, vSucursal, pClavepuerto, pPuerto, '1', pUsuario, CURRENT);
				
			END FOREACH
		
		END IF;

		RETURN vCodret;
	END;
END PROCEDURE
DOCUMENT
"Consulta ",
"Autor : Rodolfo Javier Tortolero Varela",
"FECHA : 17/Febrero/2012",
"Ver.  : 1.1",
"BD    : bdinteg";

CREATE PROCEDURE "informix".sp_cortesig(pFecha date, pMeses integer)
RETURNING char(6), date;

    DEFINE vccodret             char(6);
    DEFINE vccodret2            char(6);
    DEFINE vccodret3            char(60);
    DEFINE vsqlerr              integer;
    DEFINE visamerr             integer;
    DEFINE vdescerr             char(60);
    DEFINE vCodret              char(6);
    DEFINE dDiaPrimero          date;
    DEFINE dDiaUltimo           date;
    DEFINE dFechaMesResultante  date;
    DEFINE dDiaUltimoResultante date;
    
    LET vccodret  = '000';
    LET vccodret2 = '000';
    LET vccodret3 = '';
    LET vsqlerr   = 0;
    LET visamerr  = 0;
    LET vdescerr  = '';
    LET vCodret   = '';
    LET dDiaPrimero = '';
    LET dDiaUltimo  = '';
    LET dFechaMesResultante = '';
    LET dDiaUltimoResultante = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, visamerr, vdescerr
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_cortesig.err';
        TRACE ON;
        IF vsqlerr <> 0  THEN
            LET vcCodRet  = vsqlerr;
            LET vccodret2 = visamerr;
            LET vccodret3 = vdescerr;
            RETURN vcCodRet, pFecha;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_cortesig.out';
    --- TRACE ON;

    IF day(pfecha) >= 29 THEN
        -- // TOMAR EL DÍA 1  Y HACER SUMA DE MESES
        EXECUTE PROCEDURE bdinteg:"informix".sp_diaprimeroultimomesanio(lpad(month(pFecha), 2, '0'), year(pFecha)) 
        INTO vCodret, dDiaPrimero, dDiaUltimo;

        LET dFechaMesResultante = dDiaPrimero + pMeses units month;

        -- // OBTENER DIA ULTIMO DEL MES DE LA FECHA RESULTANTE
        EXECUTE PROCEDURE bdinteg:"informix".sp_diaprimeroultimomesanio(lpad(month(dFechaMesResultante), 2, '0'), year(dFechaMesResultante)) 
        INTO vCodret, dDiaPrimero, dDiaUltimoResultante;

        -- // VALIDAR SI EL DIA DE MESIVERSARIO EXISTE EN EL MES DE FECHA RESULTANTE
        IF day(pFecha) > Day(dDiaUltimoResultante) THEN
            -- // NO EXISTE EL DÍA, TOMAR EL DÍA ULTIMO DE ESE MES
            RETURN '00', dDiaUltimoResultante;
        ELSE
            -- // DIA SI EXISTE, SUMA DE MESES NORMAL
            RETURN '00', pFecha + pMeses units month;
        END IF;
    ELSE
        RETURN '00', pFecha + pMeses units month;
    END IF;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_diaprimeroultimomesanio(pMes char(2), pAnio char(4))
RETURNING char(6), date, date;

    -- // Sp para devolver el día primero y ultimo de un mes-año
    -- // Para compilarse en la base de datos integral
    -- // Juan Andres Coronel Junio 2008

    DEFINE vcCodRet     char(6);
    DEFINE vccodret2    char(6);
    DEFINE vccodret3    char(60);
    DEFINE vsqlerr      integer;
    DEFINE visamerr     integer;
    DEFINE vdescerr     char(60);
    DEFINE sAuxFecha    Char(10);
    DEFINE sAuxMes      Char(2);
    DEFINE sAuxAnio     Char(4);
    DEFINE dDiaprimero  date;
    DEFINE dDiaUltimo   date;
    
    LET vcCodRet    = '000000';
    LET vccodret2   = '000000';
    LET vccodret3   = '';
    LET vsqlerr     = 0;
    LET visamerr    = 0;
    LET vdescerr    = '';
    LET sAuxFecha   = '';
    LET sAuxMes     = '';
    LET sAuxAnio    = '';
    LET dDiaprimero = '';
    LET dDiaUltimo  = '';

    BEGIN

    ON EXCEPTION SET vsqlerr, visamerr, vdescerr
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_diaprimeroultimomesanio.err';
        TRACE ON;
        IF vsqlerr <> 0  THEN
            LET vcCodRet  = vsqlerr;
            LET vccodret2 = visamerr;
            LET vccodret3 = vdescerr;
            RETURN vcCodRet, date(1), date(1);
        END IF;
    END  EXCEPTION
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_diaprimeroultimomesanio.out';
    --- TRACE ON;
    
    LET sAuxFecha   = lpad(trim(pMes), 2, '0') || '-01-' || pAnio ;
    LET dDiaprimero = sAuxFecha::Date;

    IF pMes = '12' THEN
        Let sAuxMes = '01';
        Let sAuxAnio = pAnio + 1 ;
    ELSE
        Let sAuxMes = pMes + 1;
        Let sAuxMes = lpad(trim(sAuxMes), 2, '0');
        Let sAuxAnio = pAnio;
    END IF;

    LET sAuxFecha  = sAuxMes || '-01-' || sAuxAnio ;
    LET dDiaUltimo = sAuxFecha::date - 1;

    END;

    RETURN vcCodRet , dDiaprimero, dDiaUltimo;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_concurso_renueva2012(p_canal INT,p_tpoper INT,p_producto INT, p_numcte CHAR(9),p_sucursal CHAR(4),p_foliosuc CHAR(16),p_importe MONEY(16,2),p_fecha DATE)

RETURNING CHAR(6) AS cCod_Ret,CHAR(16) AS cFolio, CHAR(20) AS cFolio_cupon, CHAR(2) AS cTicket;

--Declaracion de variables

DEFINE cError_Info		VARCHAR(80); 

DEFINE iSql_Err			INTEGER;
DEFINE iIsam_Err		INTEGER;
DEFINE cCod_Ret			VARCHAR(6);
DEFINE cFolio 			CHAR(16);
DEFINE cFolio_cupon		CHAR(20);
DEFINE cTicket			CHAR(2);
DEFINE iNumbol			INTEGER;
DEFINE iNumBolFin		INTEGER;

DEFINE cCvesorteo		VARCHAR(6);
DEFINE cParam			CHAR(5);
DEFINE iPart1			INTEGER;
DEFINE iPart2			INTEGER;
DEFINE iPart3			INTEGER;
DEFINE iPart4			INTEGER;
DEFINE cComienza		CHAR(1);

--Asignacion de variables
LET cError_Info		='';

LET iSql_Err		=0;
LET iIsam_Err		=0;
LET cCod_Ret		='000000'; --todo correcto
LET cFolio 			='';
LET cFolio_cupon	='';
LET cTicket			='';
LET iNumbol			=0;
LET iNumBolFin		=0;

LET cCvesorteo		='';
LET cParam			='';
LET iPart1			=0;
LET iPart2			=0;
LET iPart3			=0;
LET iPart4			=0;
LET cComienza		='N';

BEGIN

	ON EXCEPTION SET iSql_Err, iIsam_Err, cError_Info
		LET cCod_Ret    = iSql_Err;
		RETURN cCod_Ret, cFolio,cFolio_cupon,cTicket;
	END EXCEPTION;
	
	ON EXCEPTION IN (-535)
		LET cComienza = "S";
	END EXCEPTION WITH RESUME;
	
	--SET DEBUG FILE TO "/tmp/sp_consurso_renueva2012.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
	--Verificar si esta activado el sorteo instantaneo
	SELECT valor INTO cParam
	FROM bdinteg:"informix".si_param
	WHERE cod_param = 117;
	
	IF cParam = '1' THEN
		--Verificar la clave del sorteo de las madres
		SELECT valor INTO cParam
		FROM bdinteg:"informix".si_param
		WHERE cod_param = 136; 
		
		--Verificar la fecha se encuentre dentro del rango del sorteo 20 abril al 21 de mayo y que sea el sorteo indicado
		SELECT {+INDEX (si_sorteo idx_si_sorteo)}
		cve_sorteo
		INTO cCvesorteo
		FROM bdinteg:"informix".si_sorteo
		WHERE  p_fecha  BETWEEN f_ini AND f_fin
		AND cve_sorteo = cParam;
		
		IF cCvesorteo = '' OR cCvesorteo IS NULL THEN
			--'NO EXISTE SORTEOS ACTIVOS EN ESTA FECHA';
		ELSE
			--Verificar que la persona no es persona fisica y se encuentra dentro del catalogo de personas morales
			IF EXISTS (SELECT {+INDEX (si_cltenoparticipa idx_si_cltenoparticipa)}numcte, tpo_persona
				FROM bdinteg:"informix".si_cltenoparticipa
				WHERE numcte = p_numcte) THEN
				--'LA PERSONA ES MORAL NO PARTICIPA'
			ELSE
				--Verificar que cumpla con el perfil establecido
				SELECT {+INDEX (si_participa idx_si_participa)}
				SUM(CASE WHEN tipo_participa = '1' AND id_elemento = p_producto THEN 1 ELSE 0 END) prod, --tipo de producto
				SUM(CASE WHEN tipo_participa = '2' AND id_elemento = p_tpoper THEN 1 ELSE 0 END) trans, --tipo de operacion 
				SUM(CASE WHEN tipo_participa = '3' AND id_elemento = p_canal THEN 1 ELSE 0 END) canal, --tipo de canal
				SUM(CASE WHEN tipo_participa = '4' AND id_elemento = 1 THEN 1 ELSE 0 END) tpo_per, --tipo de persona
				SUM(CASE WHEN tipo_participa = '2' AND id_elemento = p_tpoper AND p_importe >= val_min THEN 1 ELSE 0 END) numbol --cumple con el minimo para entregarle boleto
				INTO iPart1,iPart2,iPart3,iPart4,iNumbol
				FROM bdinteg:"informix".si_participa
				WHERE cve_sorteo = cCvesorteo;
				
				--Si se cumple con el perfil comprobar que no sea empleado
				IF iPart1 = 1 AND iPart2 = 1 AND iPart3 = 1 AND iPart4 = 1 AND iNumbol = 1 THEN
					IF EXISTS(SELECT producto FROM bdicheq:"informix".sc_maechq 
					WHERE num_cte = p_numcte AND producto = '1300' AND empresa = '001') THEN
						--'ES EMPLEADO';
					ELSE
						--Obtener el boleto 
						BEGIN WORK;
							SELECT  {+INDEX (si_sorteo idx_si_sorteo_cve)} max_boleto, boleto_ini, boleto_fin INTO cFolio, iNumbol, iNumBolFin
							FROM bdinteg:"informix".si_sorteo 
							WHERE cve_sorteo = cCvesorteo;
							
							--Si aun no se ha registrado ningun boleto se asigna el primer boleto
							IF cFolio = '' OR cFolio IS NULL OR cFolio = '0' THEN
								LET cFolio = iNumbol - 1;
								UPDATE {+INDEX (si_sorteo idx_si_sorteo)} bdinteg:"informix".si_sorteo
								SET max_boleto = cFolio
								WHERE cve_sorteo = cCvesorteo;
							END IF;
							
							--Si el boleto actual es menor al boleto maximo
							IF cFolio <= iNumBolFin THEN
								UPDATE {+INDEX (si_sorteo idx_si_sorteo)} bdinteg:"informix".si_sorteo
								SET max_boleto = max_boleto + 1
								WHERE cve_sorteo = cCvesorteo;
								
								SELECT {+INDEX (si_sorteo idx_si_sorteo_cve)} max_boleto INTO cFolio 
								FROM bdinteg:"informix".si_sorteo 
								WHERE cve_sorteo = cCvesorteo ;
							ELSE
								LET cTicket = 3;
							END IF;
							
						COMMIT WORK;
						
						IF cComienza = "S" THEN
							BEGIN WORK;
						END IF;
						
						IF cTicket = '' THEN
							--Selecciona y obtiene la informacion del folio
							SELECT {+INDEX (si_premios_renueva2012 idx_premios_renueva2012)} folio, folio_cupon, ticket INTO cFolio, cFolio_cupon, cTicket 
							FROM bdinteg:"informix".si_premios_renueva2012
							WHERE folio = cFolio;
						END IF;
						
						IF cFolio_cupon IS NULL THEN
							LET cFolio_cupon = '';
						END IF;
						
						--Actualiza el folio como otorgado
						UPDATE {+INDEX (si_premios_renueva2012 idx_premios_renueva2012)} bdinteg:"informix".si_premios_renueva2012 SET estatus = '2', sucursal = p_sucursal, foliosuc = p_foliosuc, 
						tipo_operacion = p_tpoper, importe = p_importe, f_asignado = p_fecha WHERE folio = cFolio;
						
					END IF;
				ELSE 
					--'NO CUMPLE CON PARAMETROS';
				END IF;
			END IF;
		END IF
	ELSE
		--'NO ACTIVADO EL SORTEO INSTANTANEO';
	END IF;
	
	RETURN cCod_Ret, cFolio,cFolio_cupon,cTicket;
END;
END PROCEDURE
DOCUMENT
'AUTOR: Victor Hugo Nuñez',
'FECHA: 14/04/2012',
'BD: bdinteg',
'Objetivo: Sorteo renueva tu hogar 2012';

CREATE PROCEDURE "informix".sp_cnsif_actbloqueo(cNUMERO_EMPLEADO CHAR(8),iUSU_BLOQUEO INTEGER)
 
    RETURNING CHAR(5);
													
	DEFINE iexiste INT;
	DEFINE cCodRet CHAR(5);
	DEFINE iSql_err INT;
	
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
		
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;
		--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_actbloqueo.out";
		--	TRACE ON;
		
		IF 	cNUMERO_EMPLEADO = ''	OR 
			iUSU_BLOQUEO IS NULL	THEN
			LET cCodRet = "00003";
			 RETURN cCodRet;
		END IF;
		SELECT nvl(Count(id_usuario),0) INTO iexiste  FROM si_seg_usuarios where id_usuario = cNUMERO_EMPLEADO;
		IF iexiste = 0 THEN
			LET cCodRet = "00001";
			RETURN cCodRet;		
		END IF;
		UPDATE si_seg_usuarios 
		SET	usu_bloqueo = iUSU_BLOQUEO 
		WHERE id_usuario = cNUMERO_EMPLEADO;
		RETURN cCodRet;
    END
END PROCEDURE
DOCUMENT
"AutOR : Antonio Flores",
"FUNCIONAMIENTO: Este SP servira para modificar la tabla de si_seg_usuario, modificar el campo de usu_bloqueo segun el id_usuario que se envie", 
"SPademas de los datos que ayudaran a identificar quien realizo dichos cambios como el Id_usuario la ip y macaddrees del usuario que esta modificando",
"FECHA : 28-12-2011",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_actualizamodulo(cID_USUARIOC char(8),cID_FUNCIONC char(10),cID_MODULO char(6),  
                                                      cD_MODULO char(20),cSTATUS char(1),dFECHA_MODIFICACION date,
                                                      cID_USUARIO_MODIFICACION char(8),cMAC_ADDRESS_MODIFICACION char(18),
                                                      cIP_MODIFICACION varchar(16))
 
    RETURNING CHAR(5);
													
	DEFINE iexiste INT;
	DEFINE cCodRet CHAR(5);
	DEFINE iSql_err INT;
	
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
	
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;
		--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_actualizamodulo_2.out";
		--	TRACE ON;
		
		IF 	cID_MODULO ='' OR 
			cD_MODULO  ='' OR 
			cSTATUS ='' OR
			dFECHA_MODIFICACION = '' OR
			cID_USUARIO_MODIFICACION = '' OR 
			cMAC_ADDRESS_MODIFICACION = '' OR
			cIP_MODIFICACION  = ''  THEN
			 LET cCodRet = "00003";
			 RETURN cCodRet;
		END IF;
		
		EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
		INTO cCodRet;
		  
		IF cCodRet = '00028' THEN 
			RETURN cCodRet;
		END IF;
		
		SELECT {+INDEX (bdinteg:si_seg_modulos idxidmodulo)} nvl(Count(id_modulo),0) INTO iexiste  FROM si_seg_modulos where id_modulo = cID_MODULO;
		IF iexiste = 0 THEN
			LET cCodRet = "00001";
		END IF;
		IF iexiste = 1 THEN
			UPDATE {+INDEX (bdinteg:si_seg_modulos idxidmodulo)} si_seg_modulos
			SET d_modulo = cD_MODULO,status = cSTATUS, fecha_modificacion = dFECHA_MODIFICACION,
				Id_usuario_modificacion = cID_USUARIO_MODIFICACION, mac_adress_modificacion = cMAC_ADDRESS_MODIFICACION,
				ip_modificacion = cIP_MODIFICACION
			WHERE id_modulo = cID_MODULO;
		END IF;
        
    RETURN cCodRet;
    END
END PROCEDURE		
DOCUMENT			
"AutOR : Antonio Flores",
"FUNCIONAMIENTO: Este SP servira para actualizar los datos de la tabla modulos, se actualizaran datos como  la descripcion del modulo, su status",
"asi como datos que ayudaran a identificar quien realizo dichos cambios como el Id_usuario la ip y macaddrees del modulo que se esta modificando",
"FECHA : 20-12-2011",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_actualizaperfil(cID_USUARIOC char(8),cID_FUNCIONC char(10),cID_PERFIL char(10),cD_PERFIL char(100),
														cSTATUS CHAR(1), dFECHA date,cID_USUARIO char(8),cMAC_ADDRESS char(18),
                                                      cIP varchar(16),iTIPO INTEGER)
 
    RETURNING CHAR(5);
													
	DEFINE iexiste INT;
	DEFINE cCodRet CHAR(5);
	DEFINE iSql_err INT;
	
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
		
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;
		--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_actualizaperfil_2.out";
		--	TRACE ON;
		
		IF 	cID_USUARIOC = ''	OR 
			cID_FUNCIONC =''	OR 
			cID_PERFIL = '' 	OR 
			cD_PERFIL = ''		OR
			cSTATUS = '' 		OR
			dFECHA = ''			OR
			cID_USUARIO = ''	OR
			cMAC_ADDRESS = ''	OR
			cIP = ''		 	OR
			iTIPO  = 0			THEN
			LET cCodRet = "00003";
			 RETURN cCodRet;
		END IF;
		
		EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
		INTO cCodRet;
		  
		IF cCodRet = '00028' THEN 
			RETURN cCodRet;
		END IF;
		IF iTIPO <> 1 AND iTIPO <> 2 THEN
			LET cCodRet = "00005";
			RETURN cCodRet;
		END IF;
		IF iTIPO = 1 THEN 
			SELECT {+INDEX (bdinteg:si_seg_perfiles idxidperseg)} nvl(Count(id_perfil),0) INTO iexiste  FROM si_seg_perfiles where id_perfil = cID_PERFIL;
			IF iexiste = 1 THEN
				LET cCodRet = "00004";
				RETURN cCodRet;		
			END IF;
			IF iexiste = 0 THEN
				INSERT INTO si_seg_perfiles(id_perfil,d_perfil,status,fecha_alta,id_usuario_alta,mac_adress_alta,ip_alta)
				VALUES(cID_PERFIL,cD_PERFIL,cSTATUS,dFECHA,cID_USUARIO,cMAC_ADDRESS,cIP);				
			END IF;
		END IF;
		
		IF iTIPO = 2 THEN
			SELECT {+INDEX (bdinteg:si_seg_perfiles idxidperseg)} nvl(Count(id_perfil),0) INTO iexiste  FROM si_seg_perfiles where id_perfil = cID_PERFIL;
			IF iexiste = 0 THEN
				LET cCodRet = "00001";
				RETURN cCodRet;		
			END IF;
			IF iexiste = 1 THEN
				UPDATE {+INDEX (bdinteg:si_seg_perfiles idxidperseg)} si_seg_perfiles 
				SET d_perfil = cD_PERFIL,status=cSTATUS,fecha_modificacion=dFECHA,id_usuario_modificacion=cID_USUARIO,
				mac_adress_modificacion =cMAC_ADDRESS,ip_modificacion =cIP
				WHERE id_perfil = cID_PERFIL;
			END IF; 
		END IF;		
    RETURN cCodRet;
    END
END PROCEDURE
DOCUMENT
"AutOR : Antonio Flores",
"FUNCIONAMIENTO: Este SP servira para mmodificar la tabla de perfiles si_seg_perfiles, dependiendo del id_perfil que se le indique al SP ",
"se modificaran datos como la descripcion de perfil, el status asi como los campos para saber quien y cuando se modifico",
"FECHA : 23-12-2011",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_actualizaperfilfuncion(cID_USUARIOC char(8),cID_FUNCIONC char(10),cID_PERFIL CHAR(10),cID_FUNCION CHAR(250),
														cSTATUS CHAR(25), dFECHA date,cID_USUARIO_2 char(8),cMAC_ADDRESS char(18),
                                                      cIP varchar(16),iTIPO INTEGER	)
 
    RETURNING CHAR(5);
													
	DEFINE iexiste INT;
	DEFINE cCodRet CHAR(5);
	DEFINE iSql_err INT;
    DEFINE I,J,H,A      INTEGER;
    DEFINE CADENA  CHAR (10);
    DEFINE CADENA2  CHAR (1);
	
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
    LET I=1;
    LET J=1;
    LET H=1;
    LET A=1;
    LET CADENA="";
    LET CADENA2="";
		
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;
		--SET DEBUG FILE TO "/informix/VH/sp_cnsif_actualizaperfilfuncion_2.out";
		--TRACE ON;
		
		IF 	cID_USUARIOC = ''			OR 
			cID_FUNCIONC =''			OR 
			cID_PERFIL = '' 			OR 
			cID_FUNCION = ''			OR
			cSTATUS = ''				OR
			dFECHA = ''					OR
			cID_USUARIO_2	= ''		OR
			cMAC_ADDRESS = ''			OR
			cIP = ''		 			OR
			iTIPO = 0					THEN
			LET cCodRet = "00003";
			 RETURN cCodRet;
		END IF;
		
		EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
	    INTO cCodRet;
	  
	    IF cCodRet = '00028' THEN 
			RETURN cCodRet;
	    END IF;
		
		IF iTIPO <> 1 AND iTIPO <> 2 THEN
			LET cCodRet = "00005";
			RETURN cCodRet;
		END IF;
		IF iTIPO = 1 THEN 
            FOR I=1 TO LENGTH(cID_FUNCION) STEP 10
                LET CADENA=TRIM(SUBSTR(cID_FUNCION,I,10));
                SELECT {+INDEX (bdinteg:si_seg_perfiles_funciones idxsegperfun)} nvl(Count(id_perfil),0) INTO iexiste  FROM si_seg_perfiles_funciones  WHERE id_perfil = cID_PERFIL AND id_funcion = CADENA;
                    IF iexiste = 1 THEN
                        LET cCodRet = "00004";
                        RETURN cCodRet;	
                    ELSE
                        LET CADENA2=SUBSTR(TRIM(cSTATUS),A,1);
                        INSERT INTO si_seg_perfiles_funciones (id_perfil,id_funcion,status,fecha_alta,id_usuario_alta,mac_adress_alta,ip_alta)
                        VALUES(cID_PERFIL,CADENA,CADENA2,dFECHA,cID_USUARIO_2,cMAC_ADDRESS,cIP);
                        LET CADENA="";	
                        LET A=A+1;
                    END IF;
            END FOR
         ELIF iTIPO = 2 THEN
            FOR I=1 TO LENGTH(cID_FUNCION) STEP 10
                LET CADENA=TRIM(SUBSTR(cID_FUNCION,I,10));
                SELECT {+INDEX (bdinteg:si_seg_perfiles_funciones idxsegperfun)} nvl(Count(id_perfil),0) INTO iexiste  FROM si_seg_perfiles_funciones  WHERE id_perfil = cID_PERFIL AND id_funcion = CADENA;
                    IF iexiste = 0 THEN
                        LET cCodRet = "00001";
                        RETURN cCodRet;	
                    ELSE
                        LET CADENA2=SUBSTR(TRIM(cSTATUS),A,1);
                        UPDATE {+INDEX (bdinteg:si_seg_perfiles_funciones idxsegperfun)} si_seg_perfiles_funciones
                        SET status=CADENA2,fecha_modificacion=dFECHA,
                        id_usuario_modificacion=cID_USUARIO_2,mac_adress_modificacion =cMAC_ADDRESS,ip_modificacion =cIP
                        WHERE id_perfil = cID_PERFIL AND id_funcion = CADENA;
                        LET CADENA="";	
                        LET A=A+1;
                    END IF;
            END FOR
         END IF;

    RETURN cCodRet;
    END
END PROCEDURE
DOCUMENT
"AUTOR : Victor Hugo Sánchez",
"FUNCIONAMIENTO: Este SP sirve para modificar e insertar perfiles. parametro tipo = 1 inserta un nuevo registro,parametro tipo = 2 actualiza el registro ",
"FECHA : 24-01-2012",
