CREATE PROCEDURE "informix".sp_cnsif_validaipmacejecutivo(cIDUSUARIO CHAR(8),cIP CHAR(16), cMAC CHAR(18))
							
				returning CHAR(5)  AS Cod_Retorno,
						  CHAR(8)  AS Numero_Empleado,
						  CHAR(45) AS Nombre;
				
							
DEFINE iexiste 			INT;
DEFINE cCodRet 		CHAR(5);
DEFINE iSql_err 		INT;							
-- VARIABLES
DEFINE cNumeroEmpleado   	CHAR(8);
DEFINE cNombre	   		    CHAR(45);

--inicializando variables
LET  iexiste 			 = 0;
LET cCodRet 	   = "00000";
LET iSql_err 			= 0 ;	

LET cNumeroEmpleado	 	= "";
LET cNombre		        =  "";

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN 
			cCodRet, cNumeroEmpleado, cNombre;
		END IF;
	END EXCEPTION;
	--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_validaipmacejecutivo.out";
	--	TRACE ON;
	IF 	cIDUSUARIO   = ''   OR
		cIP          = ''   OR
		cMAC         = '' THEN 
		LET cCodRet = "00003";
		RETURN
			cCodRet, cNumeroEmpleado, cNombre;
	END IF;	

		SELECT NVL(COUNT(ejecutivo),0) into iexiste FROM si_ejecut WHERE ejecutivo  = cIDUSUARIO;
		IF iexiste  = 0 THEN 
			LET cCodRet = "00025";
			RETURN 
			cCodRet, cNumeroEmpleado, cNombre;
		END IF;
		SELECT NVL(COUNT(mac),0) into iexiste FROM si_macejecutivo WHERE mac  = cMAC;
		IF iexiste  = 0 THEN 
			LET cCodRet = "00026";
			RETURN 
			cCodRet, cNumeroEmpleado, cNombre;
		END IF;
		SELECT NVL(COUNT(ipmaquina),0) into iexiste FROM si_sucursalesmaquina WHERE ipmaquina  = cIP;
		IF iexiste  = 0 THEN 
			LET cCodRet = "00027";
			RETURN 
			cCodRet, cNumeroEmpleado, cNombre;
		END IF;
		set isolation to dirty read;
		FOREACH 			
			SELECT si.ejecutivo,si.nombre
			INTO 
			cNumeroEmpleado, cNombre
			FROM si_ejecut si
			LEFT JOIN si_macejecutivo mac
			ON si.ejecutivo = mac.ejecutivo
			LEFT JOIN si_sucursalesmaquina sm
			ON mac.mac = sm.mac
			WHERE si.ejecutivo = cIDUSUARIO
			AND mac.mac = cMAC
			AND sm.ipmaquina = cIP
			
			
			RETURN 
			cCodRet, cNumeroEmpleado, cNombre with resume;
			
		END FOREACH;
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Realizar la validación de los Ejecutivos BanCoppel existentes en la Base de Datos central de Informix.",
"FECHA : 08-03-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_actualizastatususuario_bei(pEmpresa char(3), pNumCliente char(20), pUsuario char(50), 
pStatus integer, pIp char (15),pSuc char (4), pUsuCambio char (8))
   returning char(5);

   --Modificó: Manuel Ramos Figueroa
   --Actividad: actualiza el status en del usuario y registra ese cambio
   --Fecha: 01-09-2011
--
   --Modificó: Ing. Alfonso Cruz
   --Actividad: INSERTA EL CAMBIO DEL ESTATUS DEL CLIENTE EN bdinteg:si_cambiostctepm
   --Fecha: 01-09-2011
   
   DEFINE cCod_ret char(5);
   DEFINE sql_err integer;
   DEFINE iStatus integer;

   LET cCod_ret       = "000";
   LET iStatus = "0";

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            LET cCod_ret = sql_err;
            RETURN cCod_ret;
      END IF ;
   END EXCEPTION ;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
    IF pNumCliente <> "" THEN

        IF EXISTS ( SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa AND num_cliente = pNumCliente ) THEN

			SELECT id_status INTO iStatus FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa and num_cliente = pNumCliente;
				
				
				INSERT INTO bdinteg:"informix".si_cambiostctepm (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  
				VALUES (pNumCliente, iStatus, pStatus, pIp, current, pSuc, pUsuCambio);

				UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = pStatus, f_status = current  WHERE empresa = pEmpresa AND num_cliente = pNumCliente;

				LET cCod_ret = '000';  -- Usuario bloqueado
        ELSE

            LET cCod_ret = '001';  -- No existe el Cliente
        END IF ;

    ELSE

        IF EXISTS ( SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa AND usuario = pUsuario ) THEN

			SELECT id_status INTO iStatus FROM bdinteg:"informix".si_bpiusuariospm WHERE empresa = pEmpresa and usuario = pUsuario;

				INSERT INTO bdinteg:"informix".si_cambiostctepm (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  
				VALUES (pNumCliente, iStatus, pStatus, pIp, current, pSuc, pUsuCambio);

				 UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = pStatus, f_status = current  WHERE empresa = pEmpresa AND usuario = pUsuario;

				LET cCod_ret = '000';  -- Usuario bloqueado
        ELSE

            LET cCod_ret = '002';  -- No existe el Usuario
        END IF ;
    END IF ;

    RETURN cCod_ret;

END

END PROCEDURE ;

CREATE PROCEDURE "informix".sp_cnsif_validaejecutivo(cNUMEMPLEADO CHAR(8),cCONTRASENA VARCHAR(40,1),cIP CHAR(16),cMAC CHAR(12))

    RETURNING CHAR(5),CHAR(8),CHAR(1),CHAR(45);
													
	--DEFINICION DE VARIABLES 
	
	DEFINE iexiste 				INT;
	DEFINE cCodRet 				CHAR(5);
	DEFINE iSql_err 			INT;
	DEFINE cNumero_empeleado	CHAR(8);
	DEFINE cUsu_estado	 		CHAR(1);
	DEFINE cNombre				CHAR(45);
	
	
	
	--inicializando variables en comun
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
	LET cNumero_empeleado	="";
	LET cUsu_estado	 		="";
	LET cNombre				="";
	
	BEGIN
	
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN 
				cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            END IF;
        END EXCEPTION;
		--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_validaejecutivo.out";
		--TRACE ON;
		IF 	cNUMEMPLEADO = '' OR
			cMAC		 = '' THEN
			LET cCodRet = "00003";
			RETURN 
				cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF;
		IF (SELECT COUNT(ejecutivo) FROM si_ejecut where ejecutivo =cNUMEMPLEADO) = 0 THEN 
			LET cCodRet = "00002";
			RETURN 
				cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF;	
		IF (SELECT COUNT(ejecutivo) FROM si_ejecut where ejecutivo =cNUMEMPLEADO) = 1 THEN
            IF (SELECT COUNT(ejecutivo) FROM si_macejecutivo WHERE ejecutivo  = cNUMEMPLEADO and mac = cMAC) = 1 THEN 
                SELECT EJ.ejecutivo,MA.status,EJ.nombre 
                INTO cNumero_empeleado,cUsu_estado,cNombre
                FROM si_ejecut EJ
                LEFT JOIN si_macejecutivo MA
                ON MA.ejecutivo = EJ.ejecutivo
                WHERE EJ.ejecutivo = cNUMEMPLEADO AND MA.mac=cMAC;
                RETURN cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            ELSE 
                LET cCodRet = "00006";
                RETURN 
                cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            END IF	
		ELSE 
			LET cCodRet = "00006";
			RETURN 
			cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF	
	END
END PROCEDURE
DOCUMENT		
"AutOR : Antonio Flores",
"FUNCIONAMIENTO:Este sp evaluara si existe el usuario dentro de la base de datos, verificando el numero de empleado, contraseña  la ip y la macaddress de la maquina",
"FECHA : 10-01-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_comprobantepp(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCLIENTE CHAR(20),cCVEPROGRAMACION CHAR(10))
							
				returning CHAR(5)             AS Cod_Retorno,
						  CHAR(20)            AS Numero_Cliente,
						  CHAR(70)            AS Nombre,
						  CHAR(20)            AS Concepto,
						  DATE                AS Fecha_Programacion,
						  CHAR(08)            AS Hora_Programacion,
						  CHAR(30)            AS Canal_Programacion,
						  CHAR(40)            AS Cuenta_Origen,
						  CHAR(30)            AS Tipo_Cuenta_Origen,
						  CHAR(60)            AS Nombre_Beneficiario,
						  CHAR(40)            AS Banco_Receptor,
                          CHAR(20)            AS Cuenta_Destino,
						  CHAR(60)            AS Concepto_Pago,
						  MONEY(16,2)         AS Monto,
						  CHAR(40)            AS Referencia_1,
                          CHAR(20)            AS Referencia_2,
						  CHAR(70)            AS Tipo_Pago,
						  CHAR(61)            AS Notifica_Cliente_Recep,
						  CHAR(10)            AS Frecuencia,
                          CHAR(30)            AS Estado,
                          CHAR(07)            AS Porcentaje;
						  
						  
						  
DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;							
----VARIABLES STORE
DEFINE v_NumCte             CHAR(20);
DEFINE v_NomCte             CHAR(70);
DEFINE v_Descripcion        CHAR(20);
DEFINE v_FechaProg          DATE;
DEFINE v_HoraProg           CHAR(8);
DEFINE v_Canal              CHAR(30);
DEFINE v_CtaOrigen          CHAR(40);
DEFINE v_TipoCtaOrigen      CHAR(30);
DEFINE v_NomBeneficiario    CHAR(60);
DEFINE v_BancoReceptor      CHAR(40);
DEFINE v_CtaDestino         CHAR(20);
DEFINE v_ConceptoPago       CHAR(60);
DEFINE v_Importe            MONEY(16,2);
DEFINE v_ImporteIva         MONEY(16,2);
DEFINE v_Referencia1        CHAR(40);
DEFINE v_Referencia2        CHAR(20);
DEFINE v_FechaPagoProg      DATE;
DEFINE v_TipoPago           CHAR(70);
DEFINE v_Notificacion       CHAR(30);
DEFINE v_Notificacion2      CHAR(30);
DEFINE v_Estado             CHAR(30);
DEFINE v_FechaCanc          DATE;
DEFINE v_HoraPago           CHAR(04);

DEFINE cFrecuencia          CHAR(10);
DEFINE cPorcentajeAux       CHAR(07);
DEFINE cCvePorcentaje       CHAR(02);
DEFINE iTipoSpei            INTEGER;
DEFINE dHora		DATETIME HOUR to FRACTION(3);

--inicializando variables
LET  iexiste 		 = 0;
LET cCodRet 		 = "00000";
LET iSql_err 		 = 0 ;	

LET v_NumCte             = "";
LET v_NomCte             = "";
LET v_Descripcion        = "";
LET v_FechaProg          = "";
LET v_HoraProg           = "00:00:00";
LET v_Canal              = "";
LET v_CtaOrigen          = "";
LET v_TipoCtaOrigen      = "";
LET v_NomBeneficiario    = "";
LET v_BancoReceptor      = "";
LET v_CtaDestino         = "";
LET v_ConceptoPago       = "";
LET v_Importe            = 0;
LET v_ImporteIva         = 0;
LET v_Referencia1        = "";
LET v_Referencia2        = "";
LET v_FechaPagoProg      = "";
LET v_TipoPago           = "";
LET v_Notificacion       = "";
LET v_Notificacion2      = "";
LET v_Estado             = "";
LET v_FechaCanc          = "";

LET cFrecuencia          = '';
LET cPorcentajeAux       = '';
LET cCvePorcentaje       = '';
LET iTipoSpei            = 0;

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
			       v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
			       v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux;
		END IF;
	END EXCEPTION;
	
	--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_comprobantepp.out";
	--	TRACE ON;

	
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMCLIENTE   = ''	OR 
		cCVEPROGRAMACION = '' THEN 
		LET cCodRet = "00067";
		RETURN cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
			   v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
			   v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux;
	END IF 	   
		
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCLIENTE,'26','2')
	INTO
	cCodRet;

	IF (cCodRet != '00000')  THEN
	 RETURN cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
		   v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
		   v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux;
	END IF;
	
	SET ISOLATION TO DIRTY READ;
	
   EXECUTE PROCEDURE bdiprog:sp_encabezadoreportetransaccionesprogramadas(cNUMCLIENTE, cCVEPROGRAMACION, 2)
   INTO
	cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
	v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_ImporteIva,v_Referencia1,v_Referencia2,v_FechaPagoProg,
	v_TipoPago,v_Notificacion,v_Notificacion2 ,v_Estado,v_FechaCanc,v_HoraPago;
	
	IF cCodRet = '10142' THEN
		LET cCodRet = '00086';
		RETURN cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
			   v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
			   v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux;
	END IF
	
	IF cCodRet != '00000' THEN
		RETURN cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
			   v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
			   v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux;
	END IF

	SELECT 
	CASE
	WHEN cve_programa = '01' THEN 'DIARIA'
	WHEN cve_programa = '02' THEN 'SEMANAL'
	WHEN cve_programa = '03' THEN 'MENSUAL'
	WHEN cve_programa = '04' THEN 'UNICA' END AS Frecuencia,tipo_spei
	INTO
	cFrecuencia,iTipoSpei
	FROM  bdiprog:pp_pagoprog
	WHERE num_cte = cNUMCLIENTE
	AND cve_pagoprog = cCVEPROGRAMACION;
	
	LET  cCvePorcentaje = SUBSTR(cCVEPROGRAMACION,1,2);
	
	IF cCvePorcentaje = '05' AND iTipoSpei = 3 THEN
		LET cPorcentajeAux = v_Importe ||' %';
		LET cPorcentajeAux = REPLACE(cPorcentajeAux,'$','');
		LET cPorcentajeAux = REPLACE(cPorcentajeAux,'.00','');
		LET cPorcentajeAux = TRIM(cPorcentajeAux) ||' %';
		LET v_Importe = 0.00;
	ELSE
		--  LET cPorcentajeAux = TO_CHAR(v_Importe);
        LET cPorcentajeAux = '';
	END IF

    LET dHora = current;
    LET v_HoraProg= SUBSTR(TO_CHAR(dHora),12,8);
	
	RETURN  cCodRet,v_NumCte,v_NomCte,v_Descripcion,v_FechaProg,v_HoraProg,v_Canal,v_CtaOrigen,v_TipoCtaOrigen,v_NomBeneficiario,  
			v_BancoReceptor,v_CtaDestino,v_ConceptoPago,v_Importe,v_Referencia1,v_Referencia2,
			v_TipoPago,v_Notificacion2 ||'/' || v_Notificacion,cFrecuencia,v_Estado,cPorcentajeAux; 

END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información para generar el Comprobante de Transacciones Programadas. ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Número de Cliente, Programación  y Tipo Pago.",
"FECHA : 27-02-2012",
