--## Descripcion     : Se cambia el nombre al archivo que se genera y se agrega sentencia para limpiar el archivo.
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaafores (sCodigoAfore CHAR(5))
	RETURNING	CHAR(3) AS codigo,
				CHAR(40) AS nombre,
				CHAR(3) AS prevalece;

	DEFINE sCodigo			CHAR(3);
	DEFINE sNombre			CHAR(40);
	DEFINE sPrevalece		CHAR(3);

--SET DEBUG FILE TO "/dbexport/TEF/trace/sp_tef_procesararchivo62_out.sql";
--TRACE ON;

	BEGIN

		SELECT codigo,nombre, cod_prevalece
		INTO sCodigo, sNombre, sPrevalece
		FROM bdinteg:"informix".si_catalogo_afores
		WHERE codigo = sCodigoAfore;
		
		IF sCodigo = "" OR sCodigo IS NULL THEN
			SELECT codigo,nombre, cod_prevalece
			INTO sCodigo, sNombre, sPrevalece
			FROM bdinteg:"informix".si_catalogo_afores
			WHERE codigo = '000';
		END IF;
		
		RETURN sCodigo, sNombre, sPrevalece;

	END
END PROCEDURE
DOCUMENT
'Autor: Victor Hugo Nuñez',
'Proyecto: PL004022',
'Solicito: Jose Luis Bueno',
