'Descripcion: Se consulta la afore de acuerdo a su codigo',
'Fecha: 06/07/2012',
'Version: 20120706.0847';

CREATE procedure "informix".sp_consejecutivomac(pejecutivo char(8), pmac char(12), p_sTipo char(1))
    returning char(5),char(1) ;

define vcodret char(5);
define vciclo smallint;
define vsqlerr integer;
define vmac char(12);
define vstatus char(1);
define vmach char(3) ;
define vsucursal char(4) ;
define msucursal char(4) ;
define vdepto char(3) ;
define vpuesto char(3) ;
define varea char(3) ;
define vsuc char(4) ;
define vtejecut char(2);

let vmach="0" ;
let vciclo = 0;
let vcodret = "000";
let  vsqlerr = 0;

let vmac = "";
let vstatus = "";
let vsucursal = "";
let vdepto = "";
let vpuesto = "";
let varea = "";
let vsuc = "";
let msucursal = "";
let vtejecut = "";



--SET DEBUG FILE TO "/tmp/sp_consejecutivomac.sql";
--TRACE ON;

begin

   on exception set vsqlerr
      if vsqlerr <> 0 then
	 -- rollback work;
         let vcodret = vsqlerr;
         return vcodret,vmac ;
      end if;
   end exception;

        Select sucursal, departamento, puesto
        into vsucursal, vdepto, vpuesto
        from si_ejecut
        where ejecutivo = pejecutivo;

        SELECT sucursal
        INTO msucursal
        FROM si_sucursalesmaquina
        WHERE mac = trim(upper(pmac));

        select tipo_maquina 
        INTO vtejecut        
        from si_equiv_ejecut 
        where tipo_ejecut=p_sTipo;

 --Begin work;

        IF vsucursal = msucursal THEN

          if cast(nvl(vsucursal,'0') as int) > 0 and cast(nvl(vdepto,'0') as int) = 0 then

            Select area
            into varea
            From si_macarea
            where sucursal='0001' and puesto = vpuesto;

            if exists(Select ejecutivo From si_macejecutivo where ejecutivo = pejecutivo) then
                Foreach

                    Select status
                    into vstatus
                    from si_macejecutivo
                    where ejecutivo = pejecutivo

                    Select distinct sucursal
                    into vsuc
                    From si_sucursalesmaquina where mac = trim(upper(pmac));

					IF p_sTipo = 'A' THEN
						if not vsuc = '' then
                            if exists(Select ejecutivo from si_macejecutivo where ejecutivo = pejecutivo and mac = vsuc) then
                                Select status
                                into vstatus
                                from si_macejecutivo
                                where ejecutivo = pejecutivo and mac = vsuc;

                                if vstatus in ('A','T') then
                                    let vmach='1';
                                    exit Foreach;
                                else
                                    let vmach='2';
                                end if;
                            else
                                let vmach='3';
                            end if;
                        else
                             let vmach='3';
                        end if;
					ELSE
                        if exists(Select mac From si_sucursalesmaquina where mac = trim(upper(pmac)) and sucursal = vsuc and area = varea) then
                            if exists(Select mac from si_sucursalesmaquina where sucursal=vsuc and area=varea and departamento=vdepto and vtejecut=varea) then
                                if vstatus in ('A','T') then
                                    let vmach='1';
                                    exit Foreach;
                                else
                                    let vmach='2';
                                end if;
                            else
                                let vmach='3';
                            end if;
                        else
                            let vmach='3';
                        end if;
					END IF;
                end Foreach;
            else
                let vmach='3';
            end if;

        else
            if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac)) then
                if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac) and me.status in ('A','T')) then
                    let vmach='1';
                else
                    let vmach='3';
                end if;
            else
                let vmach='2';
            end if;
        end if;

        ELSE
            let vmach='3';
        END IF;

    return    vcodret,vmach ;

-- commit work;
end
end procedure;

CREATE PROCEDURE "informix".sp_obtienedatostransacc (pTransacc CHAR(4))
	RETURNING
		CHAR(6)				AS COD_RET,
		CHAR(60)			AS MENS_RET,
		CHAR(2)				AS SISTEMA,
		CHAR(50)			AS DESCRIPCION,
		CHAR(20)			AS ABREVIATURA,
		CHAR(1)				AS NATURALEZA,
		CHAR(2)				AS TIPO_TRANSACCION,
		CHAR(4)				AS TRANSACCION_RELAC,
		CHAR(1)				AS REALIZADA_POR,
		DECIMAL(14,2)		AS MONTO,
		CHAR(8)				AS TASA,
		CHAR(4)				AS TRAN_LIB_PROT, 
		CHAR(1)				AS VALIDA_DOCTO,
		CHAR(1)				AS VALORIZA,
		INT					AS DIAS_RETRASO, 
		CHAR(1)				AS SE_CONTABILIZA,
		CHAR(1)				AS SOBRE_GIRA,
		CHAR(1)				AS EDO_CTA,
		CHAR(2)				AS TP_CHEQ,
		CHAR(4)				AS TRANCIVA, 
		CHAR(1)				AS REVERSABLE,
		CHAR(30)			AS USUARIO_INSERT,
		DATE				AS FECHA_INSERT;

	--DECLARACIONES
	DEFINE cCodRet		CHAR(6);
	DEFINE cMensajeRet	CHAR(80);
	DEFINE cSis			CHAR(2);
	DEFINE cDescTrans	CHAR(50);
	DEFINE cAbrev		CHAR(20);
	DEFINE cNaturaleza	CHAR(1);
	DEFINE cTpoTran		CHAR(2);
	DEFINE cTranRelac	CHAR(4);
	DEFINE cRealizada	CHAR(1);
	DEFINE dMonto		DECIMAL(14,2);
	DEFINE cTasa		CHAR(8);
	DEFINE cTranLibProt	CHAR(4);
	DEFINE cValDocto	CHAR(1);
	DEFINE cValoriza	CHAR(1);
	DEFINE inDiasRet		INT;
	DEFINE cCont		CHAR(1);
	DEFINE cSobGira		CHAR(1);
	DEFINE cEdoCta		CHAR(1);
	DEFINE cTpCheq		CHAR(2);
	DEFINE cTranCiva	CHAR(4);
	DEFINE cRever		CHAR(1);
	DEFINE cUser		CHAR(30);
	DEFINE dtFecha		DATE;
	DEFINE iSqlErr		INTEGER;
	DEFINE iIsamErr		INTEGER;
	DEFINE cErrorInfo	CHAR(80);
	
	--INICIALIZACIONES	
	LET cCodRet			= "000000";
	LET cMensajeRet		= "PROCESO EXITOSO";
	LET cSis			= "";
	LET cDescTrans		= "";
	LET cAbrev			= "";
	LET cNaturaleza		= "";
	LET cTpoTran		= "";
	LET cTranRelac		= "";
	LET cRealizada		= "";
	LET dMonto			= 0.00;
	LET cTasa			= "";
	LET cTranLibProt	= "";
	LET cValDocto		= "";
	LET cValoriza		= "";
	LET inDiasRet		= 0;
	LET cCont			= "";
	LET cSobGira		= "";
	LET cEdoCta			= "";
	LET cTpCheq			= "";
	LET cTranCiva		= "";
	LET cRever			= "";
	LET cUser			= "";
	LET dtFecha			= DATE(1);
	LET iSqlErr      	= 0;
	LET iIsamErr     	= 0;
	LET cErrorInfo   	= "";

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;
				LET cMensajeRet = cErrorInfo;
				RETURN TRIM(cCodRet), TRIM(cMensajeRet), NVL(cSis,''), NVL(cDescTrans,''), NVL(cAbrev,''), NVL(cNaturaleza,''), NVL(cTpoTran,''), NVL(cTranRelac,''), NVL(cRealizada,''), NVL(dMonto,0), NVL(cTasa,''), NVL(cTranLibProt,''), NVL(cValDocto,''), NVL(cValoriza,''), NVL(inDiasRet,0), NVL(cCont,''), NVL(cSobGira,''), NVL(cEdoCta,''), NVL(cTpCheq,''), NVL(cTranCiva,''), NVL(cRever,''), NVL(cUser,''), NVL(dtFecha,DATE(1));
			END IF;
		END EXCEPTION;

		--SET DEBUG FILE TO "/home/sysifx/armandomorales/sp_mspei_consultatotales.out";
		--TRACE ON;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--VALIDA EL PARAMETRO
		IF NVL(pTransacc,'') = '' THEN
			LET cCodRet = "000001";
			LET cMensajeRet = "PARAMETRO INVALIDO";
			
			RETURN TRIM(cCodRet), TRIM(cMensajeRet), NVL(cSis,''), NVL(cDescTrans,''), NVL(cAbrev,''), NVL(cNaturaleza,''), NVL(cTpoTran,''), NVL(cTranRelac,''), NVL(cRealizada,''), NVL(dMonto,0), NVL(cTasa,''), NVL(cTranLibProt,''), NVL(cValDocto,''), NVL(cValoriza,''), NVL(inDiasRet,0), NVL(cCont,''), NVL(cSobGira,''), NVL(cEdoCta,''), NVL(cTpCheq,''), NVL(cTranCiva,''), NVL(cRever,''), NVL(cUser,''), NVL(dtFecha,DATE(1));
		END IF;
		
		--CONSULTA Y OBTIENE EL NUMERO DE TRANSACCION 
		SELECT sistema, descripcion, abreviatura, naturaleza, tipo_tran, tran_relac, realizada_por, monto_fijo, tasa_aplicada, tranlibprot,valida_docto, valoriza, dias_ret, se_contabiliza, sobregira, se_emite_edocta, tpcheque, trancivaesp, reversable, user_insert, fecha_insert
		INTO cSis, cDescTrans, cAbrev, cNaturaleza, cTpoTran, cTranRelac, cRealizada, dMonto, cTasa, cTranLibProt, cValDocto, cValoriza, inDiasRet, cCont, cSobGira, cEdoCta, cTpCheq, cTranCiva, cRever, cUser, dtFecha
		FROM bdinteg:"informix".si_transacc
		WHERE numero = pTransacc;
		
		--VERIFICA SI TRAE DATOS LA CONSULTA SINO MANDA MENSAJE
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet = '000002';
			LET cMensajeRet = "NO HAY REGISTROS CON EL NUMERO DE TRANSACCION INGRESADO";
		END IF;	
		
		--RETORNO EXITOSO.
		RETURN TRIM(cCodRet), TRIM(cMensajeRet), NVL(cSis,''), NVL(cDescTrans,''), NVL(cAbrev,''), NVL(cNaturaleza,''), NVL(cTpoTran,''), NVL(cTranRelac,''), NVL(cRealizada,''), NVL(dMonto,0), NVL(cTasa,''), NVL(cTranLibProt,''), NVL(cValDocto,''), NVL(cValoriza,''), NVL(inDiasRet,0), NVL(cCont,''), NVL(cSobGira,''), NVL(cEdoCta,''), NVL(cTpCheq,''), NVL(cTranCiva,''), NVL(cRever,''), NVL(cUser,''), NVL(dtFecha,DATE(1));
				
	END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene la informacion de una transaccion en especifico que se recibe como parametro',
'AUTOR: Armando Morales',
'FECHA DE CREACION: 20 de Abril de 2012',
'VERSION: 20120420.1800',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_consadictecop(pEmpresa CHAR(3), pNumCteCop CHAR(20), pTipo CHAR(1))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5),  -- Codigo de Retorno
	CHAR(20), -- Numero de cliente
	CHAR(26), -- Apellido Paterno
	CHAR(26), -- Apellido Materno
	CHAR(26), -- Nombre1
	CHAR(26), -- Nombre2
	CHAR(13); -- RFC

	--Rodolfo Tortolero Varela
	--19/12/2008
	--Consulta la tabla si_cliente para consultar los datos por número de cliente coppel

	--DEFINICION DE VARIABLES--
	DEFINE vCodRet		CHAR(5);
	DEFINE vNumCliente	CHAR(20);
	DEFINE vApePat		CHAR(26);
	DEFINE vApeMat		CHAR(26);
	DEFINE vNombre1		CHAR(26);
	DEFINE vNombre2		CHAR(26);
	DEFINE vRFC			CHAR(13);
	DEFINE vRFC_alterno CHAR(13);

	--INICIALIZACION DE VARIABLES--
	LET vCodRet		= "000";
	LET vNumCliente = "";
	LET vApePat		= "";
	LET vApeMat		= "";
	LET vNombre1	= "";
	LET vNombre2	= "";
	LET vRFC		= "";
	LET vRFC_alterno = "";

	SELECT
		numcte
	INTO
		vNumCliente
	FROM
		bdinteg:si_adiccoppel
	WHERE
		numctecoppel = pNumCteCop
	AND
		secuencia = 1;

    IF vNumCliente IS NOT NULL THEN
		IF pTipo = '1' THEN
			SELECT
				numcte, apell_paterno, apell_materno, nombre1, nombre2, rfc, rfc_alterno
			INTO
				vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vRFC_alterno
			FROM
				bdinteg:si_cliente
			WHERE
				numcte = vNumCliente AND
				empresa = pEmpresa AND
				tpo_persona = "01";
			
			IF vRFC_alterno is not null and vRFC_alterno <> "" THEN
               LET vRFC = vRFC_alterno;
            END IF;	

			RETURN vCodRet, vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC;
		END IF;

		IF pTipo = '2' THEN
			FOREACH
				SELECT
					numcte
				INTO
					vNumCliente
				FROM
					bdinteg:si_adiccoppel
				WHERE
					numctecoppel = pNumCteCop
				AND
					secuencia > 1

				SELECT
					a.numcte, a.apell_paterno, a.apell_materno, a.nombre1, a.nombre2, a.rfc, a.rfc_alterno
				INTO
					vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC, vRFC_alterno
				FROM
					bdinteg:si_cliente a, bdinteg:si_adiccoppel b
				WHERE
					a.numcte = vNumCliente AND
					a.empresa = pEmpresa AND
					a.numcte = b.numcte AND
					a.tpo_persona = "01";

				IF vRFC_alterno is not null and vRFC_alterno <> "" THEN
                   LET vRFC = vRFC_alterno;
                END IF;		
					
					RETURN vCodRet, vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC WITH RESUME;

			END FOREACH;
		END IF;
	ELSE
		LET vCodRet = '001';
	END IF;

	IF vCodRet <> '000' THEN
		RETURN vCodRet, vNumCliente, vApePat, vApeMat, vNombre1, vNombre2, vRFC;
	END IF;
--##############################################################################
--## Procedimiento   : sp_ConsAdiCteCop
--## Base de Datos   : bdinteg
--## Version         : 1.0
--## Creado por      : Rodolfo Tortolero
--## Fecha creacion  : Febrero de 2009
--##Descripcion :  Consulta el Titular y los Adicionales de Clientes Coppel
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_updcte_ide() 
RETURNING CHAR(5), CHAR(80);
--DEFINICION DE VARIABLES
DEFINE vc_CodRet        CHAR(5);
DEFINE vi_SqlErr        INTEGER;
DEFINE vi_iSAMErr        INTEGER;
DEFINE vi_iSAMData        CHAR(80);
DEFINE vc_Mensaje       CHAR(80);
DEFINE pClienteTitular        CHAR(20);
DEFINE pClienteTraspasaCtas        CHAR(20);
DEFINE vc_detalle_mov2   CHAR(200);
DEFINE vc_proceso       CHAR(50);
DEFINE vc_tabla         CHAR(30);
DEFINE vc_detalle_mov   CHAR(200);
DEFINE vc_Cuenta        CHAR(20);
DEFINE vc_Cuenta2        CHAR(20);
DEFINE vi_secuencia     INTEGER;
DEFINE vc_aniomes       CHAR(6);
DEFINE pCte        CHAR(20);
DEFINE vi_num_serial    INTEGER;
DEFINE vc_rfc           CHAR(13);
DEFINE vc_ref_ret       CHAR(20);
DEFINE vc_tipo_cta      CHAR(1);
DEFINE vc_sucursal      CHAR(4);
DEFINE vc_num_cta       CHAR(20);
DEFINE vd_fecha_mov     DATE;
DEFINE vm_imp_tot_dep   MONEY(10,2);
DEFINE vm_imp_ide       MONEY(10,2);
DEFINE vc_user_insert   CHAR(8);
DEFINE vd_fecha_insert  DATE;
DEFINE cAniomes     CHAR (4);
DEFINE vc_rfc_ori       CHAR(13);
--INICIALIZACION DE VARIABLES
LET vc_CodRet = "00000";
LET vi_SqlErr = 0;
LET vi_iSAMErr=0;
LET vi_secuencia = 0;
LET vi_iSAMData="";
LET vc_Mensaje = "EL PROCESO SE EFECTUO CORRECTAMENTE";
LET pClienteTitular="";
LET pClienteTraspasaCtas="";
LET vc_detalle_mov2 = "";
LET vc_proceso = "FusionClientes";
LET vc_tabla = "";
LET vc_detalle_mov = "";
LET vc_Cuenta = "";
LET vc_aniomes="";
LET vc_Cuenta2="";
LET pCte="";
LET vi_num_serial=0;
LET vc_rfc = "";
LET vc_ref_ret = "";
LET vc_tipo_cta = "";
LET vc_sucursal = "";
LET vc_num_cta = "";
LET vd_fecha_mov = "";
LET vm_imp_tot_dep = 0;
LET vm_imp_ide = 0;
LET vc_user_insert = "";
LET vd_fecha_insert = "";
LET cAniomes="";
LET vc_rfc_ori = "";





set isolation to dirty read;
set lock mode to wait 10;

    BEGIN

    ON EXCEPTION SET vi_SqlErr,vi_iSAMErr,vi_iSAMData
        IF vi_SqlErr <> 0 THEN
            LET vc_CodRet = vi_SqlErr;
            LET vc_Mensaje = "ERROR NO CONTROLADO";
            LET vc_detalle_mov2=vi_SqlErr||'|'||vi_iSAMErr||'|'||vi_iSAMData; 
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov2, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            RETURN vc_CodRet, vc_Mensaje;
        END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/informix/VH/decli/sp_updcte_ide.out";
    --TRACE ON;

        SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:si_fusclientes_ide idxtraside)} trim(cliente_tit),trim(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM si_fusclientes_ide
        SET ISOLATION TO DIRTY READ;
        FOREACH

            SELECT NVL(aniomes,"") INTO vc_AnioMes FROM bdilide:sl_movefec WHERE aniomes >='201201' AND num_cte =pClienteTraspasaCtas
                SELECT rfc INTO vc_rfc FROM bdinteg:si_cliente WHERE numcte = pClienteTitular;
                SET ISOLATION TO DIRTY READ;
                FOREACH         
                    SELECT num_serial, rfc, ref_ret, tipo_cta, sucursal, num_cta, fecha_mov, imp_tot_dep, imp_ide, user_insert, fecha_insert
                    INTO   vi_num_serial, vc_rfc_ori, vc_ref_ret, vc_tipo_cta, vc_sucursal, vc_num_cta, vd_fecha_mov, vm_imp_tot_dep, vm_imp_ide, vc_user_insert, vd_fecha_insert
                    FROM bdilide:sl_movefec
                    WHERE aniomes = vc_AnioMes AND num_cte = pClienteTraspasaCtas

                    LET vc_tabla = "sl_movefec";
                    LET vc_detalle_mov = TRIM(vc_AnioMes)||'|'||TRIM(pClienteTraspasaCtas)||'|'||TRIM(vc_rfc_ori)||'|'||TRIM(vc_ref_ret)||'|'||TRIM(vc_num_cta)||'|'||vd_fecha_mov||'|'||vm_imp_tot_dep;
                    LET vc_proceso='INFORMACION IDE';           

                    INSERT INTO bdinteg:si_fusmovefec
                    SELECT * FROM bdilide:sl_movefec WHERE aniomes = vc_AnioMes AND num_cte = pClienteTraspasaCtas;

                    INSERT INTO bdilide:sl_movefec(aniomes, num_cte,num_serial,rfc,ref_ret,tipo_cta,sucursal,num_cta,fecha_mov,imp_tot_dep,imp_ide,user_insert,fecha_insert)
                    VALUES (vc_AnioMes, pClienteTitular,vi_num_serial, vc_rfc, vc_ref_ret, vc_tipo_cta, vc_sucursal, vc_num_cta, vd_fecha_mov, vm_imp_tot_dep, vm_imp_ide, vc_user_insert, vd_fecha_insert);

                    INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                    VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);


                   DELETE FROM bdilide:sl_movefec WHERE aniomes = vc_AnioMes AND num_cte = pClienteTraspasaCtas;

                END FOREACH;

        END FOREACH;  



    SET ISOLATION TO DIRTY READ;
    FOREACH
        SELECT {+INDEX (bdinteg:si_fusclientes_ide idxtraside)} trim(cliente_tit),trim(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM si_fusclientes_ide

          SET ISOLATION TO DIRTY READ;
          SELECT rfc INTO vc_rfc FROM bdinteg:si_cliente WHERE numcte = pClienteTitular;

           INSERT INTO bdinteg:si_fusdetlide
           SELECT * FROM bdilide:sl_detlide WHERE aniomes>='201201' AND num_cte = pClienteTraspasaCtas;

           UPDATE bdilide:sl_detlide SET num_cte = pClienteTitular,rfc=vc_rfc
           WHERE aniomes>='201201' AND num_cte=pClienteTraspasaCtas;

           INSERT INTO bdinteg:si_fusretlide
           SELECT * FROM bdilide:sl_retlide WHERE aniomes>='201201' AND num_cte = pClienteTraspasaCtas;

           UPDATE bdilide:sl_retlide SET num_cte = pClienteTitular,rfc=vc_rfc
           WHERE aniomes>='201201' AND num_cte=pClienteTraspasaCtas;

    END FOREACH;  


END FOREACH;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cnsif_altanivelcte(cID_USUARIOC CHAR(8),cID_FUNCIONC CHAR(10),cNoCliente CHAR(20),iNivel INTEGER,cStatus CHAR(1),dFecha DATE, cUser CHAR(8),cMac CHAR(18),cIp CHAR(16),iTipo INTEGER)
							
				returning CHAR(5)  AS Cod_Retorno;
										
DEFINE iexiste 			INT;
DEFINE cCodRet          CHAR(5);
DEFINE iSql_err 		INT;							
--inicializando variables
LET iexiste 			 = 0;
LET cCodRet 	   = "00000";
LET iSql_err 			= 0 ;	


BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	--  SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_catnivelcte.out";
	--  TRACE ON;
    IF iTipo NOT IN (1,2) THEN
        LET cCodRet = "00102";
        RETURN cCodRet;
    END IF;
    IF 	cID_USUARIOC = '' 	OR
        cID_FUNCIONC = '' 	OR
        cNoCliente   = ''   OR
        (iNivel=0 OR iNivel IS NULL) OR
        cStatus      = ''   OR
        dFecha   IS NULL    OR
        cUser        = ''   OR
        cMac         = ''   OR
        cIp          = ''   OR
        iTipo=0 OR iTipo IS NULL THEN 
            LET cCodRet = "00054";
            RETURN cCodRet;
    END IF;	


	EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
	INTO cCodRet;

	IF cCodRet = '00028' THEN 
		RETURN cCodRet;
	END IF;			
	
	SELECT NVL(COUNT(numcte),0) into iexiste FROM si_cliente_nivel WHERE numcte=cNoCliente;
	IF iTipo=1 AND iexiste=1 THEN
        LET cCodRet = "00103";
 		RETURN cCodRet;   
    ELIF iTipo=2 AND (iexiste=0 OR iexiste IS NULL) THEN
        LET cCodRet = "00104";
		RETURN cCodRet;
    END IF;
		
    IF iTipo=1 THEN
        INSERT INTO si_cliente_nivel (numcte,nivel,status,fecha_alta,id_usuario_alta,mac_address_alta,ip_alta)
        VALUES (cNoCliente,iNivel,cStatus,dFecha,cUser,cMac,cIp);
    ELSE
        UPDATE si_cliente_nivel set nivel=iNivel,status=cStatus,fecha_modifcacion=dFecha,id_usuario_modificacion=cUser,
        mac_address_modificacion=cMac,ip_modificacion=cIp WHERE numcte=cNoCliente; 
    END IF;

    RETURN cCodRet;
END

END PROCEDURE
DOCUMENT
"Autor :Victor Hugo Sánchez Mendoza",
"FUNCIONAMIENTO:Alta y Actualizacion de clientes restringidos CNSIFWEB",
"FECHA : 04-07-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_catnivelcte(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10))
							
				returning CHAR(5)  AS Cod_Retorno,
						  INTEGER  AS Nivel,
						  CHAR(60) AS Descripcion_Nivel;
										
DEFINE iexiste 			INT;
DEFINE cCodRet          CHAR(5);
DEFINE iSql_err 		INT;							
--CLIENTES VARIABLES
DEFINE iNivel              INTEGER;
DEFINE cDescripcion        CHAR(60);

--inicializando variables
LET iexiste 			 = 0;
LET cCodRet 	   = "00000";
LET iSql_err 			= 0 ;	
LET iNivel              = 0 ;
LET cDescripcion		= "";


BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,iNivel,cDescripcion;
		END IF;
	END EXCEPTION;
	--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_catnivelcte.out";
	--TRACE ON;
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	THEN 
		LET cCodRet = "00054";
		RETURN cCodRet,iNivel,cDescripcion;
	END IF;	

	EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
	INTO cCodRet;

	IF cCodRet = '00028' THEN 
		RETURN cCodRet,iNivel,cDescripcion;
	END IF;			
	
	SELECT {+INDEX (bdinteg:si_seg_nivel_consulta idxnivc)} NVL(COUNT(id_nivel_consulta),0) into iexiste FROM si_seg_nivel_consulta;
	
	IF iexiste  = 0 THEN 
		LET cCodRet = "00101";
		RETURN cCodRet,iNivel,cDescripcion;
	END IF;
		
    FOREACH
        SELECT {+INDEX (bdinteg:si_seg_nivel_consulta idxnivc)} id_nivel_consulta,d_nivel_consulta INTO iNivel,cDescripcion 
        FROM si_seg_nivel_consulta

        RETURN cCodRet,iNivel,cDescripcion WITH RESUME;
    END FOREACH;
	


END

END PROCEDURE
DOCUMENT
"Autor :Victor Hugo Sánchez Mendoza",
"FUNCIONAMIENTO:Consulta nivel y descripcion para catalogo de niveles CNSIFWEB",
"FECHA : 04-07-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_totalessucursales(cID_USUARIOC CHAR(8),cID_FUNCIONC CHAR(10))
							
				returning CHAR(5)  AS Cod_Retorno,
				          INTEGER AS Total,
                          INTEGER AS Sucursales_abrieron,
						  INTEGER AS Abiertas,
						  INTEGER AS Cerradas;
										
DEFINE cCodRet          CHAR(5);
DEFINE iSql_err 		INT;	
DEFINE TotalSucs 		INT;
DEFINE SucsAbrieron		INT;
DEFINE SucsAbiertas		INT;
DEFINE SucsCerradas		INT;
DEFINE fechadia			DATE;

	--  SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_totalessucursales.out";
	--  TRACE ON;

--inicializando variables
LET cCodRet 	   = "00000";
LET iSql_err 	   =  0;
LET TotalSucs 	   =  0;
LET SucsAbrieron   =  0;
LET SucsAbiertas   =  0;
LET SucsCerradas   =  0;
LET fechadia	   = '01-01-1900';

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet, TotalSucs, SucsAbrieron, SucsAbiertas, SucsCerradas;
		END IF;
	END EXCEPTION;
	--  SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_totalessucursales.out";
	--  TRACE ON;
    IF 	cID_USUARIOC = '' 	OR
        cID_FUNCIONC = '' 	THEN 
            LET cCodRet = "00054";
            RETURN cCodRet, TotalSucs, SucsAbrieron, SucsAbiertas, SucsCerradas;
    END IF;	


 	EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
	INTO cCodRet;

	IF cCodRet = "00028" THEN 
		RETURN cCodRet, TotalSucs, SucsAbrieron, SucsAbiertas, SucsCerradas;
	END IF;		
	
	select fecha_hoy 
		into fechadia
	from bdinteg:"informix".si_fechas;
	
    SELECT count (*) 
		INTO TotalSucs
		FROM bdinteg:"informix".si_sucursales where tpo_sucursal='S';

		
	SELECT count (*) 
		INTO SucsAbrieron
	FROM bdisuc:"informix".ss_pase_sucursal
	where 
	fecha_pase = fechadia and
	suc_abrio = '1';
		

	SELECT count (*) 
		INTO SucsAbiertas
	FROM bdisuc:"informix".ss_pase_sucursal
	where 
	fecha_pase = fechadia and
	suc_abrio = '1' and suc_cerro = '0';
		

	SELECT count (*) 
		INTO SucsCerradas
	FROM bdisuc:"informix".ss_pase_sucursal
	where 
	fecha_pase = fechadia and
	suc_abrio = '1' and suc_cerro = '1';
		

    RETURN cCodRet, TotalSucs, SucsAbrieron, SucsAbiertas, SucsCerradas;
END

END PROCEDURE
DOCUMENT
"Autor: frg",
"FUNCIONAMIENTO: Consulta Total Sucursales (Total, Abiertas en el dia, Abiertas al momento, Cerradas al momento)",
"FECHA : 17-07-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_validaejecutivo2(cNUMEMPLEADO CHAR(8),cTIPO_LOGIN CHAR (1),cCONTRASENA CHAR(20),cIP CHAR(16),cMAC CHAR(12))

    RETURNING CHAR(5),CHAR(8),CHAR(1),CHAR(45);
													
	--DEFINICION DE VARIABLES 
	
	DEFINE iexiste 				INT;
	DEFINE cCodRet 				CHAR(5);
	DEFINE iSql_err 			INT;
	DEFINE cNumero_empeleado	CHAR(8);
	DEFINE cUsu_estado	 		CHAR(1);
	DEFINE cNombre				CHAR(45);
	
	
	
	--inicializando variables en comun
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
	LET cNumero_empeleado	="";
	LET cUsu_estado	 		="";
	LET cNombre				="";
	
	BEGIN
	
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN 
				cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            END IF;
        END EXCEPTION;
		--	SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_validaejecutivo.out";
		--	TRACE ON;
		IF 	cNUMEMPLEADO = '' OR
			cTIPO_LOGIN	 = '' OR
            cIP          = '' OR
            cMAC         = ''  THEN   
                LET cCodRet = "00003";
                RETURN 
                    cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF;
        IF cTIPO_LOGIN='1' THEN
            IF 	cCONTRASENA=''  THEN   
                    LET cCodRet = "00003";
                    RETURN 
                        cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            END IF;
        END IF;

		IF (SELECT COUNT(ejecutivo) FROM si_ejecut where ejecutivo =cNUMEMPLEADO) = 0 THEN 
			LET cCodRet = "00002";
			RETURN 
				cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF;	


		IF (SELECT COUNT(ejecutivo) FROM si_ejecut where ejecutivo =cNUMEMPLEADO) = 1 THEN
            IF (SELECT COUNT(ejecutivo) FROM si_macejecutivo WHERE ejecutivo  = cNUMEMPLEADO and mac = cMAC) = 1 THEN 
                SELECT EJ.ejecutivo,MA.status,EJ.nombre 
                INTO cNumero_empeleado,cUsu_estado,cNombre
                FROM si_ejecut EJ
                LEFT JOIN si_macejecutivo MA
                ON MA.ejecutivo = EJ.ejecutivo
                WHERE EJ.ejecutivo = cNUMEMPLEADO AND MA.mac=cMAC;

                IF cTIPO_LOGIN='1' THEN
                    SELECT NVL(COUNT(id_usuario),0) INTO iexiste FROM si_seg_usuarios where id_usuario =cNUMEMPLEADO AND password=cCONTRASENA;
                    IF iexiste=0 OR iexiste IS NULL THEN
                        LET cCodRet = "00106";
                        RETURN 
                            cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
                    END IF;	 
                END IF;    

               RETURN cCodRet,cNumero_empeleado,cUsu_estado,cNombre;

            ELSE 
                LET cCodRet = "00006";
                RETURN 
                cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
            END IF	
		ELSE 
			LET cCodRet = "00006";
			RETURN 
			cCodRet,cNumero_empeleado,cUsu_estado,cNombre;
		END IF	
	END
END PROCEDURE
DOCUMENT		
"AutOR : Antonio Flores",
"FUNCIONAMIENTO:Este sp evaluara si existe el usuario dentro de la base de datos, verificando el numero de empleado, contraseña  la ip y la macaddress de la maquina",
"Autor : Victor H. Sanchez",
"FUNCIONAMIENTO:Mantenimiento para direccionar la contraseña a ña tabla de usuarios.",

"FECHA : 10-01-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_concurso_regreso2012(p_canal INT,p_tpoper INT,p_producto INT, p_numcte CHAR(9),p_sucursal CHAR(4),p_foliosuc CHAR(16),p_importe MONEY(16,2),p_fecha DATE)

RETURNING CHAR(6) AS cCod_Ret,CHAR(16) AS cFolio, CHAR(20) AS cFolio_cupon, CHAR(2) AS cTicket;

--Declaracion de variables

DEFINE cError_Info		VARCHAR(80); 

DEFINE iSql_Err			INTEGER;
DEFINE iIsam_Err		INTEGER;
DEFINE cCod_Ret			VARCHAR(6);
DEFINE cFolio 			CHAR(16);
DEFINE cFolio_cupon		CHAR(20);
DEFINE cTicket			CHAR(2);
DEFINE iNumbol			INTEGER;
DEFINE iNumBolFin		INTEGER;

DEFINE cCvesorteo		VARCHAR(6);
DEFINE cParam			CHAR(5);
DEFINE iPart1			INTEGER;
DEFINE iPart2			INTEGER;
DEFINE iPart3			INTEGER;
DEFINE iPart4			INTEGER;
DEFINE cComienza		CHAR(1);
DEFINE cStatus			CHAR(1);

--Asignacion de variables
LET cError_Info		='';

LET iSql_Err		=0;
LET iIsam_Err		=0;
LET cCod_Ret		='000000'; --todo correcto
LET cFolio 			='';
LET cFolio_cupon	='';
LET cTicket			='';
LET iNumbol			=0;
LET iNumBolFin		=0;

LET cCvesorteo		='';
LET cParam			='';
LET iPart1			=0;
LET iPart2			=0;
LET iPart3			=0;
LET iPart4			=0;
LET cComienza		='N';
LET cStatus			='0';

BEGIN

	ON EXCEPTION SET iSql_Err, iIsam_Err, cError_Info
		LET cCod_Ret    = iSql_Err;
		RETURN cCod_Ret, cFolio,cFolio_cupon,cTicket;
	END EXCEPTION;
	
	ON EXCEPTION IN (-535)
		LET cComienza = "S";
	END EXCEPTION WITH RESUME;
	
	--SET DEBUG FILE TO "/tmp/sp_concurso_regreso2012.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
	--Verificar si esta activado el sorteo instantaneo
	SELECT valor INTO cParam
	FROM bdinteg:"informix".si_param
	WHERE cod_param = 117;
	
	IF cParam = '1' THEN
		--Verificar la clave del sorteo de las madres
		SELECT valor INTO cParam
		FROM bdinteg:"informix".si_param
		WHERE cod_param = 136; 
		
		--Verificar la fecha se encuentre dentro del rango del sorteo 04 Agosto al 02 de Septiembre y que sea el sorteo indicado
		SELECT {+INDEX (bdinteg:"informix".si_sorteo idx_si_sorteo)}
		cve_sorteo
		INTO cCvesorteo
		FROM bdinteg:"informix".si_sorteo
		WHERE  p_fecha  BETWEEN f_ini AND f_fin
		AND cve_sorteo = cParam;
		
		IF cCvesorteo = '' OR cCvesorteo IS NULL THEN
			--'NO EXISTE SORTEOS ACTIVOS EN ESTA FECHA';
		ELSE
			--Verificar que la persona no es persona fisica y se encuentra dentro del catalogo de personas morales
			IF EXISTS (SELECT {+INDEX (bdinteg:"informix".si_cltenoparticipa idx_si_cltenoparticipa)}numcte, tpo_persona
				FROM bdinteg:"informix".si_cltenoparticipa
				WHERE numcte = p_numcte) THEN
				--'LA PERSONA ES MORAL NO PARTICIPA'
			ELSE
				--Verificar que cumpla con el perfil establecido
				SELECT {+INDEX (bdinteg:"informix".si_participa idx_si_participa)}
				SUM(CASE WHEN tipo_participa = '1' AND id_elemento = p_producto THEN 1 ELSE 0 END) prod, --tipo de producto
				SUM(CASE WHEN tipo_participa = '2' AND id_elemento = p_tpoper THEN 1 ELSE 0 END) trans, --tipo de operacion 
				SUM(CASE WHEN tipo_participa = '3' AND id_elemento = p_canal THEN 1 ELSE 0 END) canal, --tipo de canal
				SUM(CASE WHEN tipo_participa = '4' AND id_elemento = 1 THEN 1 ELSE 0 END) tpo_per, --tipo de persona
				SUM(CASE WHEN tipo_participa = '2' AND id_elemento = p_tpoper AND p_importe >= val_min THEN 1 ELSE 0 END) numbol --cumple con el minimo para entregarle boleto
				INTO iPart1,iPart2,iPart3,iPart4,iNumbol
				FROM bdinteg:"informix".si_participa
				WHERE cve_sorteo = cCvesorteo;
				
				--Si se cumple con el perfil comprobar que no sea empleado
				IF iPart1 = 1 AND iPart2 = 1 AND iPart3 = 1 AND iPart4 = 1 AND iNumbol = 1 THEN
					IF EXISTS(SELECT producto FROM bdicheq:"informix".sc_maechq 
					WHERE num_cte = p_numcte AND producto = '1300' AND empresa = '001') THEN
						--'ES EMPLEADO';
					ELSE
						--Obtener el boleto 
						BEGIN WORK;
							SELECT  {+INDEX (bdinteg:"informix".si_sorteo idx_si_sorteo_cve)} max_boleto, boleto_ini, boleto_fin INTO cFolio, iNumbol, iNumBolFin
							FROM bdinteg:"informix".si_sorteo 
							WHERE cve_sorteo = cCvesorteo;
							
							--Si aun no se ha registrado ningun boleto se asigna el primer boleto
							IF cFolio = '' OR cFolio IS NULL OR cFolio = '0' THEN
								LET cFolio = iNumbol - 1;
								UPDATE {+INDEX (bdinteg:"informix".si_sorteo idx_si_sorteo)} bdinteg:"informix".si_sorteo
								SET max_boleto = cFolio
								WHERE cve_sorteo = cCvesorteo;
							END IF;
							
							--Si el boleto actual es menor al boleto maximo
							IF cFolio <= iNumBolFin THEN
								UPDATE {+INDEX (bdinteg:"informix".si_sorteo idx_si_sorteo)} bdinteg:"informix".si_sorteo
								SET max_boleto = max_boleto + 1
								WHERE cve_sorteo = cCvesorteo;
								
								SELECT {+INDEX (bdinteg:"informix".si_sorteo idx_si_sorteo_cve)} max_boleto INTO cFolio 
								FROM bdinteg:"informix".si_sorteo 
								WHERE cve_sorteo = cCvesorteo ;
							ELSE
								LET cTicket = 3;
							END IF;
							
						COMMIT WORK;
						
						IF cComienza = "S" THEN
							BEGIN WORK;
						END IF;
						
						IF cTicket = '' THEN
							--Selecciona y obtiene la informacion del folio
							SELECT {+INDEX (bdinteg:"informix".si_premios_regreso2012 idx_premios_regreso2012)} folio, folio_cupon, ticket, estatus 
							INTO cFolio, cFolio_cupon, cTicket, cStatus
							FROM bdinteg:"informix".si_premios_regreso2012
							WHERE folio = cFolio;
						END IF;
						
						IF cFolio_cupon IS NULL THEN
							LET cFolio_cupon = '';
						END IF;
						
						IF cTicket = '4' AND p_importe >= 651 AND cStatus = 1 THEN
						
							UPDATE {+INDEX (bdinteg:"informix".si_premios_regreso2012 idx_premios_regreso2012)} bdinteg:"informix".si_premios_regreso2012 
							SET estatus = '2'
							WHERE ticket = '4';
						ELIF cTicket = '4' AND p_importe >= 651 AND cStatus = 2 THEN
						
							LET cTicket = '2';
							
						ELIF cTicket = '4' AND (p_importe >= 650 AND p_importe < 651)	THEN
							UPDATE {+INDEX (bdinteg:"informix".si_premios_regreso2012 idx_premios_regreso2012)} bdinteg:"informix".si_premios_regreso2012 
							SET estatus = '2', foliosuc = p_foliosuc, f_asignado = p_fecha 
							WHERE ticket = '4' AND Folio = cFolio;
							LET cTicket = '2';
							LET cStatus = 2;
						END IF;
						
						IF cStatus = 1 THEN						
							UPDATE {+INDEX (bdinteg:"informix".si_premios_regreso2012 idx_premios_regreso2012)} bdinteg:"informix".si_premios_regreso2012 
							SET estatus = '2', sucursal = p_sucursal,numcte = p_numcte, foliosuc = p_foliosuc, 
							tipo_operacion = p_tpoper, importe = p_importe, f_asignado = p_fecha WHERE folio = cFolio;						
						END IF
					END IF;
				ELSE 
					--'NO CUMPLE CON PARAMETROS';
				END IF;
			END IF;
		END IF;
	ELSE
		--'NO ACTIVADO EL SORTEO INSTANTANEO';
	END IF;
	
	RETURN cCod_Ret, cFolio,cFolio_cupon,cTicket;
END;
END PROCEDURE
DOCUMENT
'AUTOR: Josue Zepeda',
'FECHA: 06/07/2012',
'BD: bdinteg',
'Objetivo: Sorteo Regreso a clases 2012';

CREATE PROCEDURE "informix".sp_cnsif_consulta_saldos_general(cID_USUARIOC char(08),cID_FUNCIONC CHAR(10),cNUMCUENTA CHAR(20))
							
				returning CHAR(5)       AS Codigo_Retorno,
						  DATE          AS fecha_origen,
						  DATE          AS fecha_prox_pago,
						  DECIMAL(18,2) AS pago_minimo,
						  DATE          AS fecha_ult_pago,
						  INTEGER       AS plazo,
						  INTEGER       AS pagos_realizados,
						  DECIMAL(18,2) AS linea_otorgada,
						  DECIMAL(9,6)  AS tasa_interes,
						  DECIMAL(9,6)  AS tasa_moratorios,
						  DECIMAL(14,2) AS monto_sbc,
						  DECIMAL(18,2) AS cap_vig,
						  DECIMAL(18,2) AS cap_trans,
						  DECIMAL(18,2) AS cap_vdo_exig,
						  DECIMAL(18,2) AS cap_vdo_no_exig,
						  DECIMAL(18,2) AS sdo_act_total_cap,
						  DECIMAL(18,2) AS int_vig,
						  DECIMAL(18,2) AS int_vdo,
						  DECIMAL(18,2) AS int_moratorios,
						  DECIMAL(18,2) AS int_mes,
						  DECIMAL(18,2) AS sdo_act_total_int,
						  DECIMAL(18,2) AS iva_int_vig,
						  DECIMAL(18,2) AS iva_int_vdo,
						  DECIMAL(18,2) AS iva_int_moratorios,
						  DECIMAL(18,2) AS iva_int_mes,
						  DECIMAL(18,2) AS sdo_act_total_iva,
						  DECIMAL(18,2) AS com_pend,
						  DECIMAL(18,2) AS iva_com,
						  DECIMAL(18,2) AS sdo_retenido,
						  DECIMAL(18,2) AS total_liquidacion,
						  DECIMAL(18,2) AS int_devengado,
						  DECIMAL(18,2) AS iva_int_devengado,
						  DECIMAL(18,2) AS linea_disponible,
						  DECIMAL(18,2) AS pagos_vdos,
						  DECIMAL(18,2) AS pago_inmediato;
						  
							
DEFINE iexiste 			INT;
DEFINE cCodRet 		CHAR(5);
DEFINE iSql_err 		INT;

--VARIABLES PARA EL STORE
DEFINE 	codigo_retorno   	  CHAR(6);
DEFINE 	mensaje_retorno  	  CHAR(80);
DEFINE 	numero_credito   	  CHAR(20);
DEFINE 	codigo_tipcred   	  CHAR(2);         
DEFINE 	fecha_origen     	  DATE;
DEFINE 	fecha_prox_pago  	  DATE;
DEFINE 	pago_minimo      	  DECIMAL(18,2);
DEFINE 	fecha_ult_pago   	  DATE;
DEFINE 	plazo            	  INTEGER;
DEFINE 	pagos_realizados 	  INTEGER;
DEFINE 	linea_otorgada   	  DECIMAL(18,2);
DEFINE 	tasa_interes     	  DECIMAL(9,6);
DEFINE 	tasa_moratorios       DECIMAL(9,6);
DEFINE 	monto_sbc        	  DECIMAL(14,2);
DEFINE 	cap_vig          	  DECIMAL(18,2);
DEFINE 	cap_trans        	  DECIMAL(18,2);
DEFINE 	cap_vdo_exig	 	  DECIMAL(18,2);
DEFINE 	cap_vdo_no_exig  	  DECIMAL(18,2);
DEFINE 	sdo_act_total_cap 	  DECIMAL(18,2);
DEFINE 	int_vig          	  DECIMAL(18,2);
DEFINE 	int_vdo               DECIMAL(18,2);
DEFINE 	int_moratorios   	  DECIMAL(18,2);
DEFINE 	int_mes          	  DECIMAL(18,2);
DEFINE 	sdo_act_total_int 	  DECIMAL(18,2);
DEFINE 	iva_int_vig      	  DECIMAL(18,2);
DEFINE 	iva_int_vdo      	  DECIMAL(18,2);
DEFINE 	iva_int_moratorios 	  DECIMAL(18,2);
DEFINE 	iva_int_mes      	  DECIMAL(18,2);
DEFINE 	sdo_act_total_iva 	  DECIMAL(18,2);
DEFINE 	com_pend              DECIMAL(18,2);
DEFINE 	iva_com          	  DECIMAL(18,2);
DEFINE 	sdo_retenido     	  DECIMAL(18,2);
DEFINE 	total_liquidacion 	  DECIMAL(18,2);
DEFINE 	int_devengado    	  DECIMAL(18,2);
DEFINE 	iva_int_devengado 	  DECIMAL(18,2);
DEFINE 	linea_disponible  	  DECIMAL(18,2);
DEFINE 	pagos_vdos       	  DECIMAL(18,2);
DEFINE 	desc_status_cred	  CHAR(60);
DEFINE 	id_bloqueo_cred  	  INTEGER;
DEFINE 	bloqueo_cta           CHAR(60);
DEFINE 	id_causa_bloqueo_cred CHAR(3);
DEFINE 	causa_bloqueo_cta     CHAR(50);
DEFINE 	id_sit_esp_cte    	  CHAR(1);
DEFINE 	id_causa_esp_cte      INTEGER;
DEFINE 	sit_esp_cte           CHAR(75);
DEFINE 	id_sit_esp_cred       CHAR(1);
DEFINE 	id_causa_esp_cred     INTEGER;
DEFINE 	sit_esp_cred          CHAR(75);

--VARIABLES EXTRAS
DEFINE decPagoInmediato      DECIMAL(18,2);

--inicializando variables
LET  iexiste 			 = 0;
LET cCodRet 	   = "00000";
LET iSql_err 			= 0 ;	

--INICIALIZA VARIABLES STORE
LET codigo_retorno   	  = "";
LET mensaje_retorno  	  = "";
LET numero_credito   	  = "";
LET codigo_tipcred   	  = "";
LET fecha_origen     	  = "";
LET fecha_prox_pago  	  = "";
LET pago_minimo      	  = 0;
LET fecha_ult_pago   	  = "";
LET plazo            	  = 0;
LET pagos_realizados 	  = 0;
LET linea_otorgada   	  = 0;
LET tasa_interes     	  = 0;
LET tasa_moratorios       = 0;
LET monto_sbc        	  = 0;
LET cap_vig          	  = 0;
LET cap_trans        	  = 0;
LET cap_vdo_exig	 	  = 0;
LET cap_vdo_no_exig  	  = 0;
LET sdo_act_total_cap 	  = 0;
LET int_vig          	  = 0;
LET int_vdo               = 0;
LET int_moratorios   	  = 0;
LET int_mes          	  = 0;
LET sdo_act_total_int 	  = 0;
LET iva_int_vig      	  = 0;
LET iva_int_vdo      	  = 0;
LET iva_int_moratorios 	  = 0;
LET iva_int_mes      	  = 0;
LET sdo_act_total_iva 	  = 0;
LET com_pend              = 0;
LET iva_com          	  = 0;
LET sdo_retenido     	  = 0;
LET total_liquidacion 	  = 0;
LET int_devengado    	  = 0;
LET iva_int_devengado 	  = 0;
LET linea_disponible  	  = 0;
LET pagos_vdos       	  = 0;
LET desc_status_cred	  = "";
LET id_bloqueo_cred  	  = 0;
LET bloqueo_cta           = "";
LET id_causa_bloqueo_cred = "";
LET causa_bloqueo_cta     = "";
LET id_sit_esp_cte    	  = "";
LET id_causa_esp_cte      = 0;
LET sit_esp_cte           = "";
LET id_sit_esp_cred       = "";
LET id_causa_esp_cred     = 0;
LET sit_esp_cred          = "";

LET decPagoInmediato     = 0;

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN 
			cCodRet, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
			tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
			sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
			iva_int_devengado, linea_disponible, pagos_vdos, decPagoInmediato;
		END IF;
	END EXCEPTION;
	--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_consulta_saldos_general.out";
	--TRACE ON;
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMCUENTA  = ''	THEN 
		LET cCodRet = "00045";
		RETURN
			cCodRet, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
			tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
			sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
			iva_int_devengado, linea_disponible, pagos_vdos, decPagoInmediato;
	END IF;	

	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'06','1')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
		RETURN  
				cCodRet, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
				tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
				sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
				iva_int_devengado, linea_disponible, pagos_vdos, decPagoInmediato;
	END IF;
	-- TERMINA VALIDACION	
        FOREACH
            SELECT LIMIT 1 NVL(COUNT(num_credito),0) AS CONT INTO iexiste FROM bdicred:sd_maecred WHERE num_credito  = cNUMCUENTA
            UNION
            SELECT NVL(COUNT(num_credito),0) AS CONT FROM bdicred:sd_maecredcrd WHERE num_credito  = cNUMCUENTA ORDER BY CONT DESC
        END FOREACH;
		IF iexiste  = 0 THEN 
			LET cCodRet = "00046";
			RETURN 
			cCodRet, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
			tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
			sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
			iva_int_devengado, linea_disponible, pagos_vdos, decPagoInmediato;
		END IF;
		set isolation to dirty read;
		
		EXECUTE PROCEDURE bdicred:sp_consulta_saldos_general('001',cNUMCUENTA)
		INTO
		codigo_retorno, mensaje_retorno, numero_credito, codigo_tipcred, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
		tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
		sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
		iva_int_devengado, linea_disponible, pagos_vdos, desc_status_cred, id_bloqueo_cred, bloqueo_cta, id_causa_bloqueo_cred, causa_bloqueo_cta, id_sit_esp_cte, 
		id_causa_esp_cte, sit_esp_cte, id_sit_esp_cred, id_causa_esp_cred, sit_esp_cred;          
		
		--LET decPagoInmediato = cap_trans + cap_vdo_exig + int_vdo +	int_moratorios + iva_int_vdo + iva_int_moratorios;
		LET decPagoInmediato = pago_minimo + int_vdo +	int_moratorios + iva_int_vdo + iva_int_moratorios;

		LET cCodRet = SUBSTR(codigo_retorno,2,6);
        IF cCodRet='00001' THEN
            LET cCodRet ='00047';
        ELIF cCodRet='00002' THEN    
            LET cCodRet ='00017';
        END IF;
		RETURN 
		    cCodRet, fecha_origen, fecha_prox_pago, pago_minimo, fecha_ult_pago, plazo, pagos_realizados, linea_otorgada, 
			tasa_interes, tasa_moratorios, monto_sbc, cap_vig, cap_trans, cap_vdo_exig, cap_vdo_no_exig, sdo_act_total_cap, int_vig, int_vdo, int_moratorios, int_mes, 
			sdo_act_total_int, iva_int_vig, iva_int_vdo, iva_int_moratorios, iva_int_mes, sdo_act_total_iva, com_pend, iva_com, sdo_retenido, total_liquidacion, int_devengado, 
			iva_int_devengado, linea_disponible, pagos_vdos, decPagoInmediato;

END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información de la Cuenta de Crédito de una Cliente respecto a:  Capital, Interés, IVA, Devengado, Saldos, Otros y Pago Inmediato. ",
"El SP extraerá la información de la Base de Datos central de Informix, enviando como parámetro el  No. de Cuenta.",
"FECHA : 05-03-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_consulta_telefonos(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCTE CHAR(20),pNumRegistro INTEGER,pRecuperacion INTEGER)
RETURNING CHAR(5),CHAR(20),SMALLINT,CHAR(13),CHAR(5);
          
    DEFINE iexiste 			INT;
    DEFINE cCodRet 			CHAR(5);
    DEFINE iSql_err 		INT;	
 
    DEFINE cTipoTel         CHAR(20);   
    DEFINE sSecuencia       SMALLINT;
    DEFINE vTelefono        CHAR(13);
    DEFINE vExtension       CHAR(5);
    DEFINE iCont INTEGER;

    LET  iexiste = 0;
    LET cCodRet = "00000";
    LET iSql_err = 0 ;	
    LET cTipoTel       = '';
    LET sSecuencia        =0;
    LET vTelefono         = '';
    LET vExtension      = '';
    LET iCont=0;
    
    BEGIN

	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
		END IF;
	END EXCEPTION;
    
    --- SET DEBUG FILE TO "/informix/VH/sp_consulta_telefonos.out";
    --- TRACE ON;

    -- // VALIDA PARAMETROS DE ENTRADA
	IF 	cID_USUARIOC = '' OR
		cID_FUNCIONC = '' OR
		cNUMCTE  = ''     THEN 
        LET cCodRet = "00054";
        RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
	END IF;	

    IF pNumRegistro<0 THEN
        LET cCodRet='00098';
        RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
    ELSE
        IF pRecuperacion<=0 THEN
            LET cCodRet='00098';
            RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
        END IF;
    END IF;  
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCTE,'11','2')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
	    RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
	END IF;
	-- TERMINA VALIDACION
    SELECT NVL(COUNT(numcte),0)  INTO iexiste FROM si_telefonos WHERE numcte = cNUMCTE;
    IF iexiste = 0 THEN 
        LET cCodRet = "00096";
        RETURN cCodRet, cTipoTel, sSecuencia, vTelefono, vExtension;
    END IF;	    
    SET ISOLATION TO DIRTY READ;
    
        FOREACH
            SELECT SKIP pNumRegistro FIRST pRecuperacion 
			   CASE
			   WHEN tipo_tel = 1 THEN 
				'TEL. PARTICULAR'
			   WHEN tipo_tel = 2 THEN 
				'TEL. MOVIL'
			   WHEN tipo_tel = 3 THEN 
				'TEL. TRABAJO'
			   WHEN tipo_tel = 4 THEN 
				'OTRO'
			   ELSE 
				' '
			   END AS tipo_TEL,secuencia,telefono, extension
              INTO cTipoTel, sSecuencia, vTelefono, vExtension
              FROM si_telefonos
             WHERE numcte = cNUMCTE
             ORDER BY secuencia DESC
             
            LET iCont=iCont+1;  
            RETURN cCodRet,cTipoTel, sSecuencia, vTelefono, vExtension WITH RESUME;
        END FOREACH;
        IF iCont = 0 THEN
            LET cCodRet = '1001'; 
            RETURN cCodRet,cTipoTel, sSecuencia, vTelefono, vExtension;
        END IF 	
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarstatusbm(cEmpresa CHAR(3),cNumCte CHAR(20))

    RETURNING
	CHAR(5), -- Código de Retorno
	INTEGER, --Id Status
	CHAR(60);

	--Declaracion de variables
	DEFINE vsCodRet CHAR(5);
	DEFINE vsEdoRet SMALLINT;
	DEFINE vsMensajeRet CHAR(60);
	DEFINE vsEdoCte SMALLINT;
	DEFINE vsEdoCambiar SMALLINT;
	DEFINE vsDescEdoCambiar CHAR(60);
	DEFINE viSqlErr INTEGER;

	--SET DEBUG FILE TO "/home/informix/ivonne/sp_consultarstatusbm.out";
	--TRACE ON;

	--Asignacion de variables
	LET vsCodRet = '00000';
	LET vsEdoRet = 0;
	LET vsMensajeRet = '';
	LET vsEdoCte = 0;
	LET vsEdoCambiar = 0;
	LET vsDescEdoCambiar = '';
	LET viSqlErr = 0;

	BEGIN

		ON EXCEPTION SET viSqlErr --Manejador de Errores
			IF viSqlErr <> 0 then
				LET vsCodRet = viSqlErr;
				RETURN vsCodRet,vsEdoRet,vsMensajeRet;
			END IF;
		END EXCEPTION;

		SET LOCK MODE TO WAIT 3;

		--Validación de datos de entrada
		IF NVL(cNumCte, '') = '' THEN --Valida que el Numero de Cliente nosea nulo o espacio en blanco
			LET vsCodRet = '00001';
			LET vsEdoRet = '';
			LET vsMensajeRet = 'El Numero de Cliente es Requerido.';
		ELIF NVL(cEmpresa, '') = '' THEN --Valida que el Numero de Cliente nosea nulo o espacio en blanco
				LET vsCodRet = '00002';
				LET vsEdoRet = '';
				LET vsMensajeRet = 'La Empresa es Requerida.';
		ELSE
			IF NOT EXISTS(SELECT numcte FROM bdinteg:"informix".si_cliente WHERE numcte = TRIM(cNumCte)
				AND empresa = TRIM(cEmpresa)) THEN  --Valida que el Número de Cliente exista
				LET vsCodRet = '00003';
				LET vsEdoRet = '';
				LET vsMensajeRet = 'El Numero de Cliente No Existe.';
			END IF;
		END IF;

		IF vsCodRet = '00000' THEN --Obtiene el estado del Cliente y alos estados que puede cambiar

			SELECT id_status
			INTO vsEdoCte
			FROM bdinteg:"informix".si_bm_usuarios
			WHERE numcte = TRIM(cNumCte) AND empresa = TRIM(cEmpresa);

			IF EXISTS (SELECT status_destino FROM bdinteg:"informix".si_bmcatcambiostatus WHERE status_origen = vsEdoCte AND proceso = '02') THEN
						
				FOREACH

					SELECT status_destino
					INTO vsEdoCambiar
					FROM bdinteg:"informix".si_bmcatcambiostatus
					WHERE status_origen = vsEdoCte AND proceso = '02' ORDER BY status_destino

					SELECT desc_status
					INTO vsDescEdoCambiar
					FROM bdinteg:"informix".si_bpistatus
					WHERE id_status = vsEdoCambiar;

					LET vsEdoRet = vsEdoCambiar;
					LET vsMensajeRet = TRIM(vsDescEdoCambiar);

					RETURN vsCodRet,vsEdoRet,vsMensajeRet WITH RESUME;
					
				END FOREACH;
				
			ELSE
				LET vsCodRet = '00004';
				LET vsEdoRet = '';
				LET vsMensajeRet = 'El estatus del servicio no permite realizar ningún cambio';
				RETURN vsCodRet,vsEdoRet,vsMensajeRet WITH RESUME;
				
			END IF
					
		ELSE
			RETURN vsCodRet,vsEdoRet,vsMensajeRet;
		END IF

	END

END PROCEDURE

DOCUMENT
"Consulta el estatus del cliente en Banca Móvil",
"y muestra estatus posibles a cambiar",
"Autor : Martha Aguirre",
"FECHA : 2011/09/13",
"BD    : bdinteg",
"VER   : 1.0",
"Modificación: 07-08-2012 Bibiana Gaxiola V.",
"Se envía mensaje en pantalla para aquellos estatus que no permiten cambio";

CREATE PROCEDURE "informix".sp_cnsif_actualizafuncion(cID_USUARIOC char(8),cID_FUNCIONC char(10),cID_FUNCION char(10),cID_MODULO char(6),
														iID_SUBMODULO INTEGER, cD_FUNCION_LINK char(60),cD_FUNCION char(100),cSTATUS char(1),
                                                      dFECHA_MODIFICACION date,cID_USUARIO_MODIFICACION char(8),cMAC_ADDRESS_MODIFICACION char(18),
                                                      cIP_MODIFICACION varchar(16))
 
    RETURNING CHAR(5);
													
	DEFINE iexiste INT;
	DEFINE cCodRet CHAR(5);
	DEFINE iSql_err INT;
	
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
		
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;
		--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_actualizafuncion.out";
		--TRACE ON;
		
		IF 	cID_USUARIOC = '' OR 
			cID_FUNCIONC ='' OR 
			cID_FUNCION = '' OR
			cID_MODULO = '' OR 
			iID_SUBMODULO = '' OR 
			cD_FUNCION_LINK = '' OR
			cD_FUNCION = '' OR 
			cSTATUS = '' OR
			dFECHA_MODIFICACION = '' OR
			cID_USUARIO_MODIFICACION = '' OR 
			cMAC_ADDRESS_MODIFICACION = ''	OR
            cIP_MODIFICACION = '' THEN
			LET cCodRet = "00003";
			 RETURN cCodRet;
		END IF;
        IF cID_FUNCION='SEG010' THEN
            LET cCodRet='00107';
			RETURN cCodRet;
		END IF;		
		
		EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
		INTO cCodRet;
		  
		IF cCodRet = '00028' THEN 
			RETURN cCodRet;
		END IF;		
		
		SELECT nvl(Count(id_funcion),0) INTO iexiste  FROM si_seg_funciones where id_funcion = cID_FUNCION;
		IF iexiste = 0 THEN
			LET cCodRet = "00001";
		END IF;
		IF iexiste = 1 THEN
			UPDATE si_seg_funciones
			SET id_modulo=cID_MODULO,id_submodulo=iID_SUBMODULO,d_funcion_link = cD_FUNCION_LINK,d_funcion = cD_FUNCION,status = cSTATUS, 
				fecha_modificacion = dFECHA_MODIFICACION,Id_usuario_modificacion = cID_USUARIO_MODIFICACION, 
				mac_adress_modificacion = cMAC_ADDRESS_MODIFICACION,ip_modificacion = cIP_MODIFICACION
			where id_funcion = cID_FUNCION;
		END IF;   
    RETURN cCodRet;
    END
END PROCEDURE
DOCUMENT
"AutOR : Antonio Flores",
"FUNCIONAMIENTO: Este SP servira para actualizar los datos de la tabla funciones, se actualizaran datos como funcion_link, status, asi como datos que ayudaran a", 
"identificar quien realizo dichos cambios como el Id_usuario la ip y macaddrees del usuario que esta modificando",
"FECHA : 21-12-2011",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cierra_sesiones_bm() 
RETURNING CHAR(5) AS vCodRet1;
        
    DEFINE Sql_Err              INTEGER;
    DEFINE Isam_Err             INTEGER;
    DEFINE Desc_Err             CHAR(50);
    DEFINE vCodRet1             CHAR(5);
    DEFINE vCodRet2             CHAR(5);
    DEFINE vCodRet3             CHAR(50);
        
    DEFINE vnumcel              CHAR(15);
    DEFINE vsecmax              INTEGER;
    DEFINE vid_session          INTEGER;
    DEFINE vnumcte              CHAR(20);
    DEFINE vid_oper             CHAR(4);
            
    LET Sql_Err	 = 0;
    LET Isam_Err = 0;
    LET Desc_Err = '';
    LET vCodRet1 = '000';
    LET vCodRet2 = '000';
    LET vCodRet3 = '';
        
    LET vnumcel     = '';
    LET vsecmax     = 0;
    LET vid_session = 0;
    LET vnumcte     = '';
    LET vid_oper    = '';
        
    BEGIN
        
    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cierra_sesiones_bm.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            RETURN vCodRet1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cierra_sesiones_bm.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    FOREACH
        SELECT UNIQUE numcel
          INTO vnumcel
          FROM bdinteg:"informix".si_bm_bitacora
         WHERE DATE(fech_oper) = CURRENT::DATE
         
        SELECT MAX(secuencia)
          INTO vsecmax
          FROM bdinteg:"informix".si_bm_bitacora
         WHERE DATE(fech_oper) = CURRENT::DATE
           AND numcel = vnumcel;
           
        IF vsecmax is null OR vsecmax = 0 THEN
            CONTINUE FOREACH;
        END IF;
         
        FOREACH
            SELECT id_session, numcte, id_oper
              INTO vid_session, vnumcte, vid_oper
              FROM bdinteg:"informix".si_bm_bitacora
             WHERE DATE(fech_oper) = CURRENT::DATE
               AND numcel = vnumcel
               AND secuencia = vsecmax
                    
            IF vid_oper <> '1001' THEN
                IF ( SELECT CURRENT HOUR TO SECOND - EXTEND(fech_oper, HOUR TO SECOND)
                       FROM bdinteg:"informix".si_bm_bitacora
                      WHERE DATE(fech_oper) = CURRENT::DATE
                        AND numcel = vnumcel
                        AND secuencia = vsecmax ) > '00:05:00' THEN
                      
                    LET vsecmax = vsecmax + 1;
                    
                    INSERT INTO bdinteg:"informix".si_bm_bitacora( id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol )
                    VALUES( vid_session, CURRENT, vnumcte, vsecmax, '1001', vnumcel, null, null );
                END IF;
            END IF;
            
            LET vid_session = 0;
            LET vnumcte     = '';
            LET vid_oper    = '';
        END FOREACH;
        
        LET vnumcel     = '';
        LET vsecmax     = 0;
    END FOREACH;
    
    END;
    
    RETURN vCodRet1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cnsif_consultadescripcionprogramacion(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCLIENTE CHAR(20),pNumRegistro INTEGER,pRecuperacion INTEGER)
							
			returning   CHAR(5)         AS Cod_Retorno,
						CHAR(10)        AS Clave_Pago_Programacion,	      
						CHAR(20)        AS Programacion,          
						CHAR(02)        AS Clave_Tipo_Pago;	      

							
DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;							
--VARIABLES
DEFINE v_cod_ret            CHAR(5);
DEFINE v_CvePagoProg        CHAR(10);
DEFINE v_Descripcion        CHAR(20);
DEFINE v_CvePago            CHAR(2);

--PARA PAGINACION
DEFINE iCont                INTEGER;

LET  v_cod_ret              = "00000";
LET v_CvePagoProg           = "";
LET v_Descripcion           = "";
LET v_CvePago               = "";
   
--inicializando variables
LET  iexiste 		 = 0;
LET cCodRet 		 = "00000";
LET iSql_err 		 = 0 ;

LET iCont            = 0;
                              

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;						
		END IF;
	END EXCEPTION;
	
	--  SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_consultadescripcionprogramacion.out";
	--  TRACE ON;
		
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMCLIENTE   = ''	THEN 
		LET cCodRet = "00067";
		RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
	END IF;	

    IF pNumRegistro<0 THEN
        LET cCodRet='00098';
        RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
    ELSE
        IF pRecuperacion<=0 THEN
            LET cCodRet='00098';
            RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
        END IF;
    END IF;   
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCLIENTE,'26','2')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
		RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;										
	END IF;
	-- TERMINA VALIDACION		

	SELECT NVL(COUNT(num_cte),0) INTO iexiste FROM  bdiprog:pp_pagoprog WHERE num_cte  = cNUMCLIENTE;
	IF iexiste  = 0 THEN 
		LET cCodRet = "00068";
		RETURN cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
	END IF;

	IF pNumRegistro = 0 THEN
		DELETE {+INDEX (bdinteg:si_tempodescprog idx_tempocteprog)} FROM si_tempodescprog WHERE num_cte = cNUMCLIENTE AND ejecutivosif= cID_USUARIOC;	

		SET ISOLATION TO DIRTY READ;
		FOREACH
			EXECUTE PROCEDURE bdiprog:sp_consultadescripcionprogramacion(cNUMCLIENTE, 1, '')
			INTO 		
			v_cod_ret, v_CvePagoProg, v_Descripcion, v_CvePago          

            IF v_cod_ret !='00000' THEN
				IF v_cod_ret='99999' THEN
					LET  cCodRet ='00068';
				END IF;
                RETURN 	cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
            END IF;
			-- INSERTAMOS EN TABLA  
			INSERT INTO si_tempodescprog(cod_ret,CvePagoProg,Programacion,CveTipoPago,num_cte,ejecutivosif)
			VALUES(v_cod_ret, v_CvePagoProg, v_Descripcion, v_CvePago,cNUMCLIENTE,cID_USUARIOC);
		END FOREACH
    END IF;
	
	SET ISOLATION TO DIRTY READ;
		
	FOREACH
	
		SELECT {+INDEX (bdinteg:si_tempodescprog idx_tempocteprog)} SKIP pNumRegistro FIRST pRecuperacion
		cod_ret,CvePagoProg,Programacion,CveTipoPago
		INTO
		v_cod_ret, v_CvePagoProg,v_Descripcion,v_CvePago
		FROM si_tempodescprog
		WHERE num_cte = cNUMCLIENTE AND ejecutivosif= cID_USUARIOC ORDER BY CvePagoProg
		
		IF LENGTH(v_cod_ret) = 3 THEN
			LET  cCodRet = '00' || v_cod_ret;
		ELIF LENGTH(v_cod_ret) = 5 THEN
			LET  cCodRet = v_cod_ret;
		END IF
		
		IF cCodRet !='00000' THEN
			RETURN 	cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
		END IF;
		
		LET iCont=iCont + 1;
		
		RETURN 	cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago WITH Resume;
			
	END FOREACH
	
	IF iCont = 0 THEN
		DELETE {+INDEX (bdinteg:si_tempodescprog idx_tempocteprog)} FROM si_tempodescprog WHERE num_cte = cNUMCLIENTE AND ejecutivosif= cID_USUARIOC;
		LET cCodRet = 1001; 
		RETURN 	cCodRet,v_CvePagoProg,v_Descripcion,v_CvePago;
	END IF; 
	
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información de las Instrucciones a ejecutar al vencimiento de una Cuenta de Inversión. ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Número de cuenta.",
"FECHA : 15-03-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_consedoxdigitos(pPais CHAR(3), pCodEstado CHAR(2), pNombre CHAR(30))

RETURNING
	CHAR(6)  		AS  COD_RET,
	VARCHAR(80) 	AS  MENS_RET,
	CHAR(2)  		AS  ESTADO,
	CHAR(30) 		AS  NOMESTADO,
	CHAR(4) 		AS  SIGLAS;
	
	--DECLARACIONES
    DEFINE iSqlErr         	INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet         	CHAR(6);
    DEFINE vMensajeRet      VARCHAR(40);
	DEFINE cEdo          	CHAR(2);
	DEFINE cNomEdo     		CHAR(30);
	DEFINE cSiglas     		CHAR(4);
	
	--INICIALIZACIONES
    LET iSqlErr            = 0;
    LET iIsamErr           = 0;
    LET cErrorInfo         = "";
    LET cCodRet            = "000000";
    LET vMensajeRet        = "SE REALIZO LA CONSULTA CORRECTAMENTE";
	LET cEdo               = "";
	LET cNomEdo		       = "";
	LET cSiglas		       = "";
	
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;
				LET vMensajeRet = cErrorInfo;
				RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, ''));
			END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		--SET DEBUG FILE TO '/home/sysifx/armandomorales/sp_considentificacion.out';
		--TRACE ON;

		--VALIDANDO LOS PARAMETROS.
		IF TRIM(NVL(pPais, '')) = '' THEN
			LET cCodRet = "000001";
			LET vMensajeRet = "ERROR, EN LOS PARAMETROS";
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, ''));
		END IF;
		
		--VALIDA SI VIENE ESTADO VACIO Y CONSULTA TODA LA TABLA
		IF pCodEstado <> "" THEN			
			SELECT estado, nombre, siglas
			INTO cEdo, cNomEdo, cSiglas
			FROM bdinteg:"informix".si_estados
			WHERE pais = pPais
			AND estado = pCodEstado;

			IF dbinfo("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet= "000002";
				LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";
			END IF;			
			
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, ''));
		
		--SI NOMBRE VIENE VACIO CONSULTA TODA LA TABLA 
		ELIF pNombre = "" THEN
			FOREACH
				SELECT estado, nombre, siglas
				INTO cEdo, cNomEdo, cSiglas
				FROM bdinteg:"informix".si_estados 
				WHERE pais = pPais
				ORDER BY estado			
				
				RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, '')) WITH RESUME;
			END FOREACH		
		
		--VALIDA QUE NO VENGA VACIO
		ELIF pNombre <> "" THEN
			LET pNombre = UPPER(pNombre);
				FOREACH
					--CONSULTA NUMERO DE ESTADO, NOMBRE Y SIGLAS VALIDANDO PAIS Y NOMBRE CON UN "LIKE"
					SELECT estado, nombre, siglas
					INTO cEdo, cNomEdo, cSiglas
					FROM bdinteg:"informix".si_estados 
					WHERE pais = pPais
					AND nombre LIKE '%'|| TRIM(pNombre) ||'%'
					ORDER BY estado				
					
					RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, '')) WITH RESUME;
				END FOREACH
		END IF;
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet= "000002";
			LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cEdo, '')), TRIM(NVL(cNomEdo, '')), TRIM(NVL(cSiglas, ''));
		END IF;
	END
END PROCEDURE
DOCUMENT 
'DESCRIPCION : Se realiza procedimiento para Obtener el listado de Estados',
'AUTOR : Armando Morales Barraza',
'FECHA : 13/MARZO/2012',
'BD    : BDINTEG';

CREATE PROCEDURE "informix".sp_considentificacion (pEmpresa VARCHAR(3), pCodigo VARCHAR(2))

	RETURNING
	VARCHAR(6)		AS COD_RET,
	VARCHAR(80) 	AS MENS_RET,
	VARCHAR(2)		AS CODIGO,	
	VARCHAR(50)		AS DESCRIPCION;
	
	--DECLARACIONES
	
	DEFINE vCodRet			VARCHAR(6);
	DEFINE vMensajeRet		VARCHAR(80);
	DEFINE iSqlErr 			INTEGER;
	DEFINE iIsamErr         INTEGER;
	DEFINE cErrorInfo       CHAR(80);
	DEFINE vCodIdent		VARCHAR(2);
	DEFINE vDescripcion		VARCHAR(50);
	
	LET iSqlErr                  = 0;
	LET iIsamErr                 = 0;
	LET cErrorInfo               = "";
	LET vCodRet                  = "000000";
	LET vMensajeRet              = "SE REALIZÓ LA CONSULTA CORRECTAMENTE";
	LET vCodIdent				 = "";
	LET vDescripcion			 = "";
	
	BEGIN
		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
		   IF iSqlErr != 0 THEN
			  LET vCodRet = iSqlErr;
			  LET vMensajeRet = cErrorInfo;
			  RETURN TRIM(vCodRet), TRIM(vMensajeRet), NVL(vCodIdent, ''), NVL(vDescripcion, '');
		   END IF;
		END EXCEPTION;
	
	--SET DEBUG FILE TO '/home/sysifx/armandomorales/sp_considentificacion.out';
	--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--CONSULTA LOS PARAMETROS.
		IF TRIM(NVL(pCodigo, '')) = '' AND TRIM(NVL(pEmpresa, '')) = '' THEN
			LET vCodRet = "000001";
			LET vMensajeRet = "ERROR, EN LOS PARAMETROS";
			RETURN vCodRet, TRIM(vMensajeRet), NVL(vCodIdent, ''), NVL(vDescripcion, '');
		END IF;
		
		--SI VIENE CODIGO VACIO, SE CONSULTA TODA LA TABLA.
		IF TRIM(NVL(pCodigo, '')) = '' THEN 
			FOREACH
				SELECT codigo, descripcion
				INTO vCodIdent, vDescripcion
				FROM bdinteg:"informix".si_tipoidentifpm
				WHERE empresa = pEmpresa
				
				RETURN vCodRet, TRIM(vMensajeRet), TRIM(NVL(vCodIdent, '')), TRIM(NVL(vDescripcion, '')) WITH RESUME;
			
			END FOREACH;
		
		--CONSULTA CODIGO Y DESCRIPCION VALIDANDO LA EMPRESA Y CONVIERTE EL CODIGO A MAYUSCULA SI ESTE ENTRA EN MINUSCULA.
		ELSE 
			SELECT codigo, descripcion
			INTO vCodIdent, vDescripcion
			FROM bdinteg:"informix".si_tipoidentifpm
			WHERE empresa = pEmpresa
			AND codigo = UPPER(pCodigo);
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN
				LET vCodRet = "000002";
				LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";
			END IF;
			
			--SE RETORNA INFORMACION.
			RETURN vCodRet, TRIM(vMensajeRet), TRIM(NVL(vCodIdent, '')), TRIM(NVL(vDescripcion, ''));
			
		END IF;
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET vCodRet= "000002";
			LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";
			RETURN vCodRet, TRIM(vMensajeRet), TRIM(NVL(vCodIdent, '')), TRIM(NVL(vDescripcion, ''));
		END IF;
		
	END
END PROCEDURE
DOCUMENT 
'DESCRIPCION : Se realiza procedimiento para Obtener el listado de tipo de identificacion',
'AUTOR : Armando Morales Barraza',
'FECHA : 09/MARZO/2012',
'BD    : BDINTEG';

CREATE PROCEDURE "informix".sp_consucursaltpo(pEmpresa CHAR(3) ,pNumSuc CHAR(4), pRegistro SMALLINT)

RETURNING
	CHAR(6)  		AS  COD_RET,
	VARCHAR(80) 	AS  MENS_RET,
	CHAR(4)  		AS  SUCURSAL,
	CHAR(40) 		AS  NOMSUCURSAL,
	DECIMAL(18,2) 	AS 	PAG;
	
	--DECLARACIONES
    DEFINE iSqlErr         	INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
    DEFINE cCodRet         	CHAR(6);
    DEFINE vMensajeRet      VARCHAR(40);
	DEFINE cNumSuc          CHAR(4);
	DEFINE cNomSucursal     CHAR(40);
	DEFINE iTotSuc			INTEGER;
	DEFINE dPag				DECIMAL(18,2);
	
	
	--INICIALIZACIONES
    LET iSqlErr            = 0;
    LET iIsamErr           = 0;
    LET cErrorInfo         = "";
    LET cCodRet            = "000000";
    LET vMensajeRet        = "SE REALIZO LA CONSULTA CORRECTAMENTE";
	LET cNumSuc            = "";
	LET cNomSucursal       = "";
	LET iTotSuc			   = 0;
	LET dPag			   = 0;
	
	
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
			IF iSqlErr != 0 THEN
				LET cCodRet = iSqlErr;
				LET vMensajeRet = cErrorInfo;
				RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cNumSuc, '')), TRIM(NVL(cNomSucursal, '')), NVL(dPag, 0);
			END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		--SET DEBUG FILE TO '/home/sysifx/armandomorales/sp_considentificacion.out';
		--TRACE ON;
		
		--VALIDANDO LOS PARAMETROS.
		IF TRIM(NVL(pEmpresa, '')) = '' AND TRIM(NVL(pNumSuc, '')) = '' THEN
			LET cCodRet = "000001";
			LET vMensajeRet = "ERROR, EN LOS PARAMETROS";
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cNumSuc, '')), TRIM(NVL(cNomSucursal, '')), NVL(dPag, 0);
		END IF;		
		
		--VALIDA SI VIENE SUCURSAL VACIA
		IF pNumSuc = "" THEN
			--OBTIENE EL NUMERO DE REGISTROS DE LA TABLA Y LOS DIVIDE ENTRE 10 PARA OBTENER EL NUMERO DE PAGINACION
			
			
			SELECT COUNT(sucursal) 
			INTO iTotSuc
			FROM bdinteg:"informix".si_sucursales
			WHERE sucursal = sucursal
			AND empresa = pEmpresa;
			
			LET dPag = iTotSuc/10;
				
			--CONSULTA LOS PRIMEROS 10 REGISTROS DEPENDIENDO DEL "SALTO" QUE SE LE INDIQUE
			FOREACH	
				SELECT SKIP pRegistro LIMIT 10 sucursal, nombre
				INTO cNumSuc, cNomSucursal
				FROM bdinteg:"informix".si_sucursales
				WHERE sucursal = sucursal
				AND empresa = pEmpresa
				ORDER BY sucursal
				
				RETURN cCodRet, TRIM(vMensajeRet), TRIM(cNumSuc), TRIM(cNomSucursal),dPag WITH RESUME;
			END FOREACH;			
		ELSE
			--CONSULTA NUMERO DE SUCURSAL Y NOMBRE VALIDANDO EMPRESA 
			SELECT sucursal, nombre
			INTO cNumSuc, cNomSucursal
			FROM bdinteg:"informix".si_sucursales 
			WHERE sucursal = pNumSuc
			AND empresa = pEmpresa;
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet= "000002";
				LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";				
			END IF;
			
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cNumSuc, '')), TRIM(NVL(cNomSucursal, '')), NVL(dPag, 0);
		END IF;
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet= "000002";
			LET vMensajeRet = "ERROR, NO SE ENCONTRO INFORMACION";
			RETURN TRIM(cCodRet), TRIM(vMensajeRet), TRIM(NVL(cNumSuc, '')), TRIM(NVL(cNomSucursal, '')), NVL(dPag, 0);
		END IF;
	END
END PROCEDURE
DOCUMENT 
'DESCRIPCION : Se realiza procedimiento para Obtener el listado de Sucursales',
'AUTOR : Armando Morales Barraza',
'FECHA : 18/ABRIL/2012',
'BD    : BDINTEG';

CREATE PROCEDURE "informix".sp_consultarctemoral(pNumcte CHAR(20))

	RETURNING
		CHAR(6) 		AS COD_RET,	
		CHAR(13) 		AS RFC,
		CHAR(26) 		AS APELL_PATER_REP_LEG,
		CHAR(26) 		AS APELL_MATER_REP_LEG,
		CHAR(26) 		AS NOMB1_REP_LEG,
		CHAR(26) 		AS NOMB2_REP_LEG,		
		CHAR(40)   		AS CALLE_FISCAL,
		CHAR(10)   		AS NUM_EXT_CALLE_FISCAL,
		CHAR(60)   		AS COL_FISCAL,
		VARCHAR(60,1)  	AS NOM_CIUD_FISCAL,
		CHAR(3)   		AS COD_MUN_FISCAL,
		CHAR(30)    	AS NOM_ESTADO_FISCAL,
		CHAR(20) 		AS NUM_CTE,
		CHAR(30) 		AS NOM_CORTO,
		CHAR(30) 		AS PAG_INTERNET,
		CHAR(25) 		AS SAT_FEA,
		CHAR(15) 		AS TEL_CONTACTO,
		CHAR(20) 		AS GIRO,
		CHAR(40) 		AS NOM_GIRO,
		CHAR(3) 		AS ACT_SOCIAL,
		CHAR(30) 		AS DES_ACT_OBJ,
		CHAR(50) 		AS USUARIO_AUT,		
		CHAR(12) 		AS FOL_CONTRATO,
		CHAR(2) 		AS RESP_STATUS,								
		CHAR(26) 		AS APELL_PATER_FIRMANTES,					
		CHAR(26) 		AS APELL_MATER_FIRMANTES,
		CHAR(26) 		AS NOMB1_FIRMANTES, 		
		CHAR(26) 		AS NOMB2_FIRMANTES,
		CHAR(30)		AS NO_IDENT;
			
		---DECLARACIONES
		DEFINE iSqlErr						INTEGER;    		
		DEFINE cCodRet         				CHAR(6);				
		DEFINE cRFC         				CHAR(13);				
		DEFINE cApellPaterContactoRepLeg 	CHAR(26);				
		DEFINE cApellMaterContactoRepLeg	CHAR(26);				
		DEFINE cNomb1ContactoRepLeg         CHAR(26);				
		DEFINE cNomb2ContactoRepLeg     	CHAR(26);				
		DEFINE cCalleFiscal					CHAR(40);				
		DEFINE cNumExtCalleFiscal       	CHAR(10);				
		DEFINE cColFiscal         			CHAR(60);				
		DEFINE vNomCiudFiscal         		VARCHAR(60,1);			
		DEFINE cCodMunFiscal        		CHAR(3);				
		DEFINE cNomEstadoFiscal        		CHAR(30);				
		DEFINE cNumcte         				CHAR(20);				
		DEFINE cNomCorto        			CHAR(30);				
		DEFINE cPagInternet        			CHAR(30);				
		DEFINE cSatFea        				CHAR(25);				
		DEFINE cTelContacto    				CHAR(15);				
		DEFINE cGiro      					CHAR(20);				
		DEFINE cNomGiro    					CHAR(40);				
		DEFINE cActSocial 					CHAR(3);				
		DEFINE cDesActObj  					CHAR(30);				
		DEFINE cUsuarioAut    				CHAR(50);						
		DEFINE cFolContrato   				CHAR(12);				
		DEFINE cStatusAlta 					CHAR(1);				
		DEFINE cRespStatus 					CHAR(2);				
		DEFINE cApellPaterFirmantes 		CHAR(26);				
		DEFINE cApellMaterFirmantes 		CHAR(26);				
		DEFINE cNomb1Firmantes 				CHAR(26);				
		DEFINE cNomb2Firmantes 				CHAR(26);				
		DEFINE cCuentaNomina 				CHAR(20);
		DEFINE cNumIdent					CHAR(30);
			
		---INICIALIZACIONES
		LET iSqlErr						= 0;    		
		LET cCodRet         			= '000000';				
		LET cRFC         				= '';
		LET cApellPaterContactoRepLeg   = '';
		LET cApellMaterContactoRepLeg 	= '';
		LET cNomb1ContactoRepLeg        = '';
		LET cNomb2ContactoRepLeg     	= '';
		LET cCalleFiscal				= '';
		LET cNumExtCalleFiscal       	= '';
		LET cColFiscal         			= '';
		LET vNomCiudFiscal         		= '';
		LET cCodMunFiscal        		= '';
		LET cNomEstadoFiscal        	= '';
		LET cNumcte         			= '';
		LET cNomCorto        			= '';
		LET cPagInternet        		= '';
		LET cSatFea        				= '';
		LET cTelContacto    			= '';
		LET cGiro      					= '';
		LET cNomGiro    				= '';
		LET cActSocial 					= '';
		LET cDesActObj  				= '';
		LET cUsuarioAut    				= '';		
		LET cFolContrato   				= '';
		LET cStatusAlta 				= '';
		LET cRespStatus 				= '';
		LET cApellPaterFirmantes 		= '';
		LET cApellMaterFirmantes 		= '';
		LET cNomb1Firmantes 			= '';
		LET cNomb2Firmantes 			= '';			
		LET cCuentaNomina	 			= '';
		LET cNumIdent					='';
				
	BEGIN
		
		ON EXCEPTION SET iSqlErr
		   IF iSqlErr != 0 THEN
			  LET cCodRet = iSqlErr;
			  RETURN 	cCodRet,NVL(cRFC,''),NVL(cApellPaterContactoRepLeg,''),NVL(cApellMaterContactoRepLeg,''),NVL(cNomb1ContactoRepLeg,''),
						NVL(cNomb2ContactoRepLeg,''),NVL(cCalleFiscal,''),NVL(cNumExtCalleFiscal,''),NVL(cColFiscal,''),
						NVL(vNomCiudFiscal,''),NVL(cCodMunFiscal,''),NVL(cNomEstadoFiscal,''),NVL(cNumcte,''),
						NVL(cNomCorto,''),NVL(cPagInternet,''),NVL(cSatFea,''),NVL(cTelContacto,''),NVL(cGiro,''),
						NVL(cNomGiro,''),NVL(cActSocial,''),NVL(cDesActObj,''),NVL(cUsuarioAut,''),
						NVL(cFolContrato,''),NVL(cRespStatus,''),NVL(cApellPaterFirmantes,''),NVL(cApellMaterFirmantes,''),
						NVL(cNomb1Firmantes,''),NVL(cNomb2Firmantes,''), NVL(cNumIdent,'');
		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--SET DEBUG FILE TO '/home/sysifx/SPsPAYAN/sp_consultarctemoral.out';
		--TRACE ON;
		
		IF TRIM(NVL(pNumcte,'')) = '' THEN
			LET cCodRet = '000001';
			RETURN 	cCodRet,NVL(cRFC,''),NVL(cApellPaterContactoRepLeg,''),NVL(cApellMaterContactoRepLeg,''),NVL(cNomb1ContactoRepLeg,''),
					NVL(cNomb2ContactoRepLeg,''),NVL(cCalleFiscal,''),NVL(cNumExtCalleFiscal,''),NVL(cColFiscal,''),
					NVL(vNomCiudFiscal,''),NVL(cCodMunFiscal,''),NVL(cNomEstadoFiscal,''),NVL(cNumcte,''),
					NVL(cNomCorto,''),NVL(cPagInternet,''),NVL(cSatFea,''),NVL(cTelContacto,''),NVL(cGiro,''),
					NVL(cNomGiro,''),NVL(cActSocial,''),NVL(cDesActObj,''),NVL(cUsuarioAut,''),
					NVL(cFolContrato,''),NVL(cRespStatus,''),NVL(cApellPaterFirmantes,''),NVL(cApellMaterFirmantes,''),
					NVL(cNomb1Firmantes,''),NVL(cNomb2Firmantes,''),NVL(cNumIdent,'');
		END IF;
		
		--SE OBTIENE DENOMINACIÓN O RAZÓN SOCIAL, NÚMERO DE LA FIRMA ELECTRÓNICA AVANZADA Y TELÉFONO DEL CONTACTO.
		SELECT TRIM(NVL(a.numcte,'')),TRIM(NVL(a.nombre_corto,'')),TRIM(NVL(a.pagina_internet,'')),TRIM(NVL(a.sat_fea,'')),TRIM(NVL(a.telefono_contacto,''))
		INTO cNumcte,cNomCorto,cPagInternet,cSatFea,cTelContacto
		FROM bdinteg:"informix".si_ctepm a, bdinteg:"informix".si_cliente b 
		WHERE a.numcte = pNumcte
		AND b.empresa = '001'
		AND b.numcte = pNumcte
		AND b.tpo_persona = '02';
					
		IF NVL(CNumcte,'') = '' THEN 
		   LET cCodRet = '000002';
		   RETURN 	cCodRet,NVL(cRFC,''),NVL(cApellPaterContactoRepLeg,''),NVL(cApellMaterContactoRepLeg,''),NVL(cNomb1ContactoRepLeg,''),
					NVL(cNomb2ContactoRepLeg,''),NVL(cCalleFiscal,''),NVL(cNumExtCalleFiscal,''),NVL(cColFiscal,''),
					NVL(vNomCiudFiscal,''),NVL(cCodMunFiscal,''),NVL(cNomEstadoFiscal,''),NVL(cNumcte,''),
					NVL(cNomCorto,''),NVL(cPagInternet,''),NVL(cSatFea,''),NVL(cTelContacto,''),NVL(cGiro,''),
					NVL(cNomGiro,''),NVL(cActSocial,''),NVL(cDesActObj,''),NVL(cUsuarioAut,''),
					NVL(cFolContrato,''),NVL(cRespStatus,''),NVL(cApellPaterFirmantes,''),NVL(cApellMaterFirmantes,''),
					NVL(cNomb1Firmantes,''),NVL(cNomb2Firmantes,''), NVL(cNumIdent,'');
		END IF;
		
		--SE OBTIENE LA CUENTA Y EL ESTATUS DE LA EMPRESA CON EL SERVICIO DE NOMINA
		SELECT TRIM(NVL(cuenta,'')), TRIM(NVL(status_alta,''))
		INTO cCuentaNomina, cStatusAlta
		FROM bdicheq:"informix".sc_nominaempresas
		WHERE numcte = pNumcte;
		
		IF TRIM(NVL(cStatusAlta,'')) = '3' THEN
		   LET cRespStatus = 'Si';
		ELSE
		   LET cRespStatus = 'No';
		END IF;		
						
		--SE OBTIENE NOMBRE DEL REPRESENTANTE LEGAL Y RFC.
		SELECT TRIM(NVL(c.rfc,'')),TRIM(NVL(b.apell_paterno,'')),TRIM(NVL(b.apell_materno,'')),
			   TRIM(NVL(b.nombre1,'')),TRIM(NVL(b.nombre2,'')) 
		INTO cRFC,cApellPaterContactoRepLeg,cApellMaterContactoRepLeg,cNomb1ContactoRepLeg,cNomb2ContactoRepLeg
		FROM bdinteg:"informix".si_ctepm a 
		INNER JOIN bdinteg:"informix".si_cliente b ON (a.nombre_contacto = b.numcte)
		INNER JOIN bdinteg:"informix".si_cliente c ON (c.numcte = pNumcte)
		WHERE a.numcte = pNumcte
		AND b.empresa = '001'
		AND b.numcte = a.nombre_contacto 
		AND c.empresa = '001'
		AND c.numcte = pNumcte;
							
		--SE OBTIENE DOMICILIO FISCAL.			
		SELECT 	TRIM(NVL(e.nombrecalle,'')),TRIM(NVL(a.numeroextcalle,'')),TRIM(NVL(f.nombrezona,'')),
				TRIM(NVL(g.nombre,'')),TRIM(NVL(c.municipio,'')),TRIM(NVL(b.nombre,''))			
		INTO cCalleFiscal,cNumExtCalleFiscal,cColFiscal,vNomCiudFiscal,cCodMunFiscal,cNomEstadoFiscal
		FROM bdinteg:"informix".si_direcciones_actual a 
			 LEFT OUTER JOIN bdinteg:"informix".si_estados 	   b ON (a.estado = b.estado)
			 LEFT OUTER JOIN bdinteg:"informix".si_municipios  c ON (a.municipio = c.municipio AND a.estado = c.estado AND a.ciudad = c.ciudad AND a.pais = c.pais)
			 LEFT OUTER JOIN bdinteg:"informix".si_catcalles   e ON (a.numerocalle = e.numerocalle)
			 LEFT OUTER JOIN bdinteg:"informix".si_catzonas    f ON (a.numerociudad = f.numerociudad and a.numerocolonia = f.numerocolonia)
			 LEFT OUTER JOIN bdinteg:"informix".si_ciudades    g ON (a.estado = g.estado AND a.ciudad = g.ciudad)		 
		WHERE a.numcte = pNumcte
		AND a.tipo_dir = 1;
		
		--SE OBTIENE GIRO MERCANTIL.
		SELECT TRIM(NVL(a.giro,'')),TRIM(NVL(b.nombre,'')) 
		INTO cGiro,cNomGiro
		FROM bdinteg:"informix".si_ctepm a INNER JOIN bdinteg:"informix".si_actecon b ON(TRIM(LPAD(a.giro,3,'0')) = TRIM(b.actividad))
		WHERE a.numcte = pNumcte;
										
		--SE OBTIENE ACTIVIDAD U OBJETO SOCIAL.
		SELECT TRIM(NVL(a.actividadsocial,'')),TRIM(NVL(b.descripcion,'')) 
		INTO cActSocial,cDesActObj
		FROM bdinteg:"informix".si_ctepm a INNER JOIN bdinteg:"informix".si_actividadsocial b ON (TRIM(a.actividadsocial) = TRIM(b.codigo))
		WHERE numcte = pNumcte;		
						
		--SE OBTIENE USUARIO AUTORIZADO Y SU NUMERO DE IDENTIFICACION.
		SELECT TRIM(NVL(usuario_aut,'')), TRIM(NVL(no_identificacion_oficial, ''))
		INTO cUsuarioAut, cNumIdent
		FROM bdinteg:"informix".si_bpiusuariospm 
		WHERE empresa = '001'
		AND num_cliente = pNumcte;
	
		--SE OBTIENE FOLIO DE ACTIVACIÓN DEL TOKEN:		
		SELECT TRIM(NVL(a.folio_contrato,''))
		INTO cFolContrato
		FROM bdinteg:"informix".si_bpiusuariospm a
		INNER JOIN bdinteg:"informix".si_bpitokenpm b ON (a.num_cliente = b.num_cliente)
		WHERE a.num_cliente = pNumcte
		AND b.folio_token = a.folio_contrato
		AND a.id_status >= 10;
		
		IF TRIM(NVL(cFolContrato,'')) = '' THEN
			LET cFolContrato = 'Sin Activar';
		END IF;
		
		--SE OBTIENE EL AUTORIZADO PARA MANEJAR LAS CUENTAS DE REGISTRO FIRMAS:
		SELECT TRIM(NVL(apell_paterno,'')),TRIM(NVL(apell_materno,'')),TRIM(NVL(nombre1,'')),TRIM(NVL(nombre2,''))		
		INTO cApellPaterFirmantes,cApellMaterFirmantes,cNomb1Firmantes,cNomb2Firmantes
		FROM bdicheq:"informix".sc_firmantes a INNER JOIN bdinteg:"informix".si_cliente b ON(a.numcte = b.numcte)
		WHERE a.empresa = '001'
		AND a.cuenta = cCuentaNomina
		AND a.secuencia = 1;
	
		--SE RETORNA INFORMACION.
		RETURN 	cCodRet,NVL(cRFC,''),NVL(cApellPaterContactoRepLeg,''),NVL(cApellMaterContactoRepLeg,''),NVL(cNomb1ContactoRepLeg,''),
				NVL(cNomb2ContactoRepLeg,''),NVL(cCalleFiscal,''),NVL(cNumExtCalleFiscal,''),NVL(cColFiscal,''),
				NVL(vNomCiudFiscal,''),NVL(cCodMunFiscal,''),NVL(cNomEstadoFiscal,''),NVL(cNumcte,''),
				NVL(cNomCorto,''),NVL(cPagInternet,''),NVL(cSatFea,''),NVL(cTelContacto,''),NVL(cGiro,''),
				NVL(cNomGiro,''),NVL(cActSocial,''),NVL(cDesActObj,''),NVL(cUsuarioAut,''),
				NVL(cFolContrato,''),NVL(cRespStatus,''),NVL(cApellPaterFirmantes,''),NVL(cApellMaterFirmantes,''),
				NVL(cNomb1Firmantes,''),NVL(cNomb2Firmantes,''), NVL(cNumIdent,'');
		
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene la informacion de cliente moral', 
'AUTOR: Guadalupe Payan ',
'VERSION: 20110928.1152',
'FECHA: Septiembre 2011',
'BD: bdinteg',
'MODIFICACION: Se agrega procedimiento para que obtenga el numero de identificacion autorizado.', 
'AUTOR: Armando Morales ',
'VERSION: 20120302.1152',
'FECHA: Marzo 2012',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_senet_actualizaestatusctepm( pEmpresa CHAR(3), pNumCte CHAR(20) , pEstatus CHAR(3), pFolioToken CHAR(12), pUsuarioAutoriza CHAR(50), pCodIdentif CHAR(2), pNumIdentOficial CHAR(30), pUsuario CHAR(8) ,pIP CHAR(15))
	RETURNING CHAR(6) AS cCodRet,
		      SMALLINT AS Estatus,
			  CHAR(100) AS Mensaje;
    
  -- DEFINICIONES
	DEFINE cCodRet           CHAR(6);
	DEFINE iSql_Err          INTEGER;
	DEFINE cMensaje          CHAR(100);
	DEFINE sEstatusAnterior  SMALLINT;
	DEFINE sEstatus          SMALLINT;
	DEFINE cNumCte           CHAR(20);
	DEFINE cFolioToken       CHAR(12);
    DEFINE dtFechaHoy        DATE;
	
	-- INICIALIZACIONES
	LET cCodRet           	= '000';
	LET iSql_Err          	= 0;
	LET cMensaje          	= '';
	LET sEstatusAnterior  	= 0;
	LET sEstatus          	= 0;
	LET cNumCte           	= '';
	LET cFolioToken       	= '';
	LET dtFechaHoy         	= '01-01-2000';
    	
	BEGIN
		
		ON EXCEPTION SET iSql_Err
			LET cCodRet = iSql_Err;
			LET cMensaje = '';
			LET sEstatus = '0';
			RETURN cCodRet, sEstatus, cMensaje;
		END EXCEPTION;
		
		-- SET DEBUG FILE TO "/respaldosbd/Guadalupe/sp_senet_actualizaestatusctepm.out";
		-- TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
	  --Valida los parametros de entrada.
		IF (pEmpresa = '' OR pEmpresa IS NULL) OR (pNumCte = '' OR pNumCte IS NULL) OR pEstatus IS NULL OR pUsuarioAutoriza IS NULL OR (pNumIdentOficial = '' OR pNumIdentOficial IS NULL) OR (pUsuario = '' OR pUsuario IS NULL) OR TRIM(NVL(pCodIdentif,'')) = '' THEN
		   LET cCodRet = '001';
		   LET cMensaje = 'FALTAN PARAMETROS PARA SU EJECUCIÓN';
		   LET sEstatus = '0';
		   RETURN cCodRet, sEstatus, cMensaje;
		END IF
		
	  -- Consultamos la fecha actual
		SELECT fecha_hoy INTO dtFechaHoy
		FROM bdicheq:"informix".sc_fechas;
		
	  --Valida si el estatus viene vacio inserta un registro en la tabla.
		IF pEstatus = '' THEN
		   
		  LET sEstatus = 0;
		  LET cFolioToken = pFolioToken;
		   
		 -- Inserta un registro en las tablas.
		   INSERT INTO bdinteg:"informix".si_bpiusuariospm (empresa, num_cliente, id_status, folio_contrato, usuario_aut    , codidentif , no_identificacion_oficial, rep_legal, pass, f_pass, pass1, f_pass1, pass2, f_pass2, pass3, f_pass3, f_status, f_ultimo_acceso, f_actualizacion, f_registro, fec_primer_acceso, num_empleado, fecha_movto, f_unico_reg, usuario,suc_registro)
           VALUES                                         (pEmpresa, pNumCte   , sEstatus , cFolioToken   , pUsuarioAutoriza, pCodIdentif, pNumIdentOficial        ,''        ,''   ,''     ,''    ,''      , ''   , ''     , ''   , ''     , ''      , ''             , ''             , ''        , ''               , pUsuario    , ''         , dtFechaHoy , '','5001');
		   
	       INSERT INTO bdinteg:"informix".si_cambiostctepm ( numcliente, id_statusanterior, id_statusactual  , ipusuario, fecha_cambio, suc_cambio, usuario_cambio )
           VALUES                                         ( pNumCte   , sEstatus         , sEstatus         , pIP      , dtFechaHoy    , '5001'    , pUsuario);
		   
		  LET cCodRet = '000';
		  LET cMensaje = 'INSERTO CORRECTAMENTE';
		   
		   RETURN cCodRet, sEstatus, cMensaje;
		   
		ELSE
			
            LET sEstatusAnterior = pEstatus::SMALLINT;		
			
		  -- Valida el estatus que se va actualizar
			IF pEstatus = '0' THEN
			  LET sEstatus = 1;
			  LET cFolioToken = pFolioToken;
			  
			  UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = sEstatus , folio_contrato = cFolioToken 
			  WHERE empresa = pEmpresa AND num_cliente =pNumCte;
			  
			ELIF pEstatus = '1' THEN
			  LET sEstatus = 2;
			  LET cFolioToken = pFolioToken;
			  
			  UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = sEstatus , folio_contrato = cFolioToken 
			  WHERE empresa = pEmpresa AND num_cliente =pNumCte;
			ELIF pEstatus = '2' THEN
			  LET sEstatus = 10;
			  LET cFolioToken = pFolioToken;
			  
			  UPDATE bdinteg:"informix".si_bpiusuariospm SET id_status = sEstatus , folio_contrato = cFolioToken , f_registro = dtFechaHoy
			  WHERE empresa = pEmpresa AND num_cliente =pNumCte;
			END IF 
			
		  -- Inserta en la tabla un registro del historial del estatus que lleva el cliente.
	        INSERT INTO bdinteg:"informix".si_cambiostctepm ( numcliente, id_statusanterior, id_statusactual  , ipusuario, fecha_cambio, suc_cambio, usuario_cambio )
            VALUES                                         ( pNumCte   , sEstatusAnterior , sEstatus         , pIP       , dtFechaHoy  ,  '5001'    , pUsuario);
		    
		    LET cCodRet = '000';
		    LET cMensaje = 'ACTUALIZO CORRECTAMENTE';
			
			RETURN cCodRet, sEstatus, cMensaje;
			
		END IF
        
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Actualiza e Inserta registros en la tabla si_bpiusuariospm en caso de que el estatus se encuentre vacio ',
'             y actualiza la tabla en el estatus que le sigue en el proceso',
'AUTOR:  Valentin Lopez',
'FECHA DE CREACION: 27 de Septiembre del 2011',
'DESCRIPCION MODIFICACION: Se modifico el número de identificación a char(30) y recibir como parametro el típo de identificación para su registro y',
'							se cambiaron todos los mensajes a mayuscula',
'FECHA MODIFICACION: 13 de Marzo del 2012',
'AUTOR MODIFICACION: Guadalupe Payan',
'VERSION: 20120313.1204',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_senet_altaservicioctepmempresanet( pNumCte CHAR(20), pUsuario CHAR(8) )
	RETURNING CHAR(6) AS cCodRet,
			  CHAR(40) AS Mensaje;
    
  -- DEFINICIONES
  	DEFINE iSql_Err         INTEGER;
	DEFINE cCodRet          CHAR(6);
	DEFINE cMensaje         CHAR(40);
	DEFINE cFolioToken      CHAR(12);
	DEFINE dtFechaHoy       DATE;
	DEFINE sEstatus         SMALLINT;
	DEFINE sEstatusAnt      SMALLINT;
	DEFINE sSecuencia       SMALLINT;
	DEFINE cSolicitud       CHAR(10);
	DEFINE cFolioSucursal   CHAR(16);
	DEFINE cRandon1         CHAR(6);
	DEFINE cRandon2         CHAR(2);
	
	-- INICIALIZACIONES
	LET iSql_Err           	= 0;
	LET cCodRet           	= '000000';
	LET cMensaje          	= 'SE GENERO EL ALTA EXISTOSAMENTE';
	LET cFolioToken       	= '';
	LET dtFechaHoy         	= '01-01-2000';
	LET sEstatus          	= 0;
	LET sEstatusAnt       	= 0;
	LET sSecuencia        	= 0;
	LET cSolicitud        	= '';
	LET cFolioSucursal    	= '';
	LET cRandon1          	= '';
	LET cRandon2         	= '';
		
	BEGIN
	
		ON EXCEPTION SET iSql_Err
			LET cCodRet = iSql_Err;
			LET cMensaje = '';
			RETURN cCodRet, cMensaje;
		END EXCEPTION;
		
		-- SET DEBUG FILE TO "/respaldosbd/Guadalupe/sp_senet_altaservicioctepmempresanet.out";
		-- TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		 
	  --Valida los parametros de entrada.
		IF (pNumCte = '' OR pNumCte IS NULL) OR (pUsuario = '' OR pUsuario IS NULL) THEN
		   LET cCodRet = '000001';
		   LET cMensaje = 'FALTAN PARAMETROS PARA SU EJECUCIÓN';
		   RETURN cCodRet, cMensaje;
		END IF
		 
  	  -- Consultamos la fecha actual
		SELECT fecha_hoy INTO dtFechaHoy
		FROM bdicheq:"informix".sc_fechas;
		 
      -- Consultamos la maxima secuencia del domicilio del cliente.
		SELECT secuencia INTO sSecuencia
		FROM bdinteg:"informix".si_direcciones_actual 
		WHERE numcte = pNumCte
			AND tipo_dir = 1;
		 
	    IF sSecuencia IS NULL THEN
		  SELECT MAX(secuencia) INTO sSecuencia 
		  FROM bdinteg:"informix".si_direcciones
		  WHERE numcte = pNumCte
			AND tipo_dir = 1;
		END IF
		 
      -- Consulta el maximo regitro + 1
  	    SELECT (NVL(MAX(solicitud),'0')::INTEGER + 1) INTO cSolicitud
		FROM bdibpi:"informix".bpi_tokensolicitud;
		
		IF cSolicitud IS NULL THEN
			LET cSolicitud = '1';
		END IF;
		
		LET cSolicitud = LPAD(TRIM(cSolicitud), 10, '0');	
		
	  -- Consultamos el FolioToken
		SELECT folio_contrato, id_status INTO cFolioToken, sEstatus
		FROM bdinteg:"informix".si_bpiusuariospm 
		WHERE num_cliente = pNumCte;
		
	  -- Consultamos la hora para generar el folio.
		SELECT SUBSTR(DBINFO('utc_to_datetime', sh_curtime),12,2) || SUBSTR(DBINFO('utc_to_datetime', sh_curtime),15,2) || SUBSTR(DBINFO('utc_to_datetime', sh_curtime),18,2)
		INTO cRandon1
		FROM sysmaster:sysshmvals;
		
	 -- Generamos un Randon para completar el valor del folio.
	   EXECUTE PROCEDURE bdicheq:"informix".sp_random()
	   INTO cRandon2;
		
		LET cFolioSucursal = 'SINCOMIS'||cRandon1||LPAD(TRIM(cRandon2), 2, '0');
		
	  --Valida el estatus anterior.
	    IF sEstatus = 0 THEN
		  LET sEstatusAnt = 0;
		ELIF sEstatus = 1 THEN
		  LET sEstatusAnt = 0;
		ELIF sEstatus = 2 THEN
		  LET sEstatusAnt = 1;
		ELIF sEstatus = 10 THEN
		  LET sEstatusAnt = 2;
		ELSE
		  LET cCodRet = '000002';
		  LET cMensaje = 'ESTATUS NO VALIDO PARA EL PROCESO DE ALTA DE EMPRESA NET';
		  RETURN cCodRet, cMensaje;
		END IF 
		
	 --  Inserta los registros de la alta definitiva del servicio de EmpresaNet.
		INSERT INTO bdinteg:"informix".si_bpitokenpm ( empresa, num_cliente, ns_token, suc_registro, folio_token, id_status_token, f_status  , f_registro )
		VALUES                                       ( '001'  , pNumCte    , ''      , '5001'      , cFolioToken, 0              , dtFechaHoy , dtFechaHoy );
	    
		INSERT INTO bdibpi:"informix".bpi_tokensolicitud ( solicitud, numcte , id_status, sucursal, f_solicitud, sec_domicilio, f_atencion, comentarios, usr_solicita, usr_atiende, empresa, ns_token, tipo, folio_suc )
		VALUES                                          ( cSolicitud, pNumCte, '100'    , '5001'  , dtFechaHoy  , sSecuencia   , dtFechaHoy , ''         , pUsuario    , ''         , '001'  , ''      , 3   , cFolioSucursal);
	    		
		RETURN cCodRet, cMensaje;
        
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Realiza un alta definitiva del servicio de EmpresaNet',
'AUTOR:  Valentin Lopez',
'FECHA DE CREACION: 28 de Septiembre del 2011',
'DESCRIPCION MODIFICACION: Se agrego el filtro de tipo_dir = 2 para la tabla de direcciones y', 
'							se cambiaron todos los mensajes a mayuscula',
'FECHA MODIFICACION: 13 de Marzo del 2012',
'AUTOR MODIFICACION: Guadalupe Payan',
'VERSION: 20120313.1426',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_senet_consultaestatusctepm( pNumCte CHAR(20) , pCuenta CHAR(20) )
	
	RETURNING CHAR(6) 		AS CodRet,
		      CHAR(100) 	AS Mensaje,
			  CHAR(3) 		AS Estatus,			  
			  CHAR(50) 		AS UsuarioAutorizado,
			  CHAR(2) 		AS CodIdentif,
			  CHAR(50) 		AS DescripIdenfOficial,
			  CHAR(30) 		AS Identificacion,
			  CHAR(12) 		AS FoliosolicitudToken;
    
	--DEFINICIONES DE VARIABLES.
	DEFINE cCodRet         			CHAR(6);
	DEFINE iSqlErr        			INTEGER;
	DEFINE iIsamErr        			INTEGER;
	DEFINE cDescErr        			CHAR(100);
	DEFINE cMensaje        			CHAR(100);
	DEFINE cEstatus        			CHAR(3);
	DEFINE cNumCte	       			CHAR(20);
	DEFINE cUsuarioAut	   			CHAR(50);
	DEFINE cDescripIdenfOficial  	CHAR(55);
	DEFINE cCodIdentif  			CHAR(2);
	DEFINE cIdentificacion 			CHAR(30);
	DEFINE cFolioSolToken  			CHAR(12);
	    	
	--INICIALIZACIONES DE VARIABLES.
	LET cCodRet         			= '000';
	LET iSqlErr         			= 0;
	LET iIsamErr         			= 0;
	LET cDescErr        			= '';
	LET cMensaje        			= 'VALIDACION TERMINADA';
	LET cEstatus        			= '';
	LET cNumCte         			= '';
	LET cUsuarioAut     			= '';	
	LET cCodIdentif  				= '';
	LET cDescripIdenfOficial		= '';
	LET cIdentificacion 			= '';
	LET cFolioSolToken  			= '';		
	  
	BEGIN
		ON EXCEPTION SET iSqlErr,iIsamErr,cDescErr
			LET cCodRet = iSqlErr;
			LET cMensaje = cDescErr;
			RETURN cCodRet,TRIM(cMensaje),TRIM(NVL(cEstatus,'')),TRIM(NVL(cUsuarioAut,'')),TRIM(NVL(cCodIdentif,'')),TRIM(NVL(cDescripIdenfOficial,'')),TRIM(NVL(cIdentificacion,'')),TRIM(NVL(cFolioSolToken,''));
		END EXCEPTION;

		-- SET DEBUG FILE TO "/respaldosbd/Guadalupe/sp_senet_consultaestatusctepm.out";
		-- TRACE ON;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
	  --Valida los parametros de entrada.		
		IF NVL(pNumCte, '') = '' AND NVL(pCuenta, '') = '' THEN
		   LET cCodRet = '002';
		   LET cMensaje = 'FALTAN PARAMETROS PARA SU EJECUCIÓN';
		   RETURN cCodRet,cMensaje,TRIM(cEstatus),TRIM(cUsuarioAut),TRIM(cCodIdentif),TRIM(cDescripIdenfOficial),TRIM(cIdentificacion),TRIM(cFolioSolToken);
		   
		ELIF NVL(pNumCte,'' ) <> '' AND NVL(pCuenta,'') <> '' THEN		
		   LET cCodRet = '003';
		   LET cMensaje = 'SOLAMENTE DEBE INGRESAR UN PARAMETRO';
		   RETURN cCodRet,cMensaje,TRIM(cEstatus),TRIM(cUsuarioAut),TRIM(cCodIdentif),TRIM(cDescripIdenfOficial),TRIM(cIdentificacion),TRIM(cFolioSolToken);
		   
		END IF
		
	  --Si el cliente viene vacio consulta el cliente por el numero de cuenta		
		IF NVL(pNumCte,'') = '' THEN
		  SELECT num_cte 
		  INTO cNumCte
		  FROM bdicheq: "informix".sc_maechq
		  WHERE empresa = '001'
		    AND cuenta = pCuenta;
		  		  
		  IF NVL(cNumCte,'') = ''THEN            
			LET cCodRet = '004';
		    LET cMensaje = 'NO EXISTE LA CUENTA EN LA BASE DE DATOS';
		    RETURN cCodRet,cMensaje,TRIM(cEstatus),TRIM(cUsuarioAut),TRIM(cCodIdentif),TRIM(cDescripIdenfOficial),TRIM(cIdentificacion),TRIM(cFolioSolToken);
			
		  END IF
		  
		  LET pNumCte = cNumCte;
		   
		END IF
		
	  -- Consulta el estatus que tiene asignado el cliente.
		SELECT id_status,usuario_aut,codidentif,no_identificacion_oficial,folio_contrato 
		INTO cEstatus,cUsuarioAut,cCodIdentif,cIdentificacion,cFolioSolToken
		FROM bdinteg: "informix".si_bpiusuariospm 
		WHERE empresa = '001'
		  AND num_cliente = pNumCte;
		
	  -- Valida si el estatus es NULL o Vacio.		
		IF NVL(cEstatus,'') = '' THEN
		   LET cCodRet = '000';
		   LET cEstatus = '';
		   LET cMensaje = 'EMPRESA NO A SIDO DADA DE ALTA EN EL SERVICIO DE EMPRESA NET';		   
		   RETURN cCodRet,cMensaje,TRIM(cEstatus),TRIM(NVL(cUsuarioAut,'')),TRIM(NVL(cCodIdentif,'')),TRIM(cDescripIdenfOficial),TRIM(NVL(cIdentificacion,'')),TRIM(NVL(cFolioSolToken,''));
		   
		END IF
						
		--Consulta la descripcion y el codigo identificacion oficial.
		SELECT TRIM(descripcion)
		INTO cDescripIdenfOficial
		FROM bdinteg: "informix".si_tipoidentifpm
		WHERE empresa = '001'
		  AND codigo = TRIM(cCodIdentif);		
		
	  -- Valida el estatus obtenido en la consulta.
		IF cEstatus = '0' THEN
  		  LET cCodRet = '000';
 		  LET cMensaje = 'EL PROCESO DE ALTA SE DETUVO EN LA GENERACIÓN DEL CODIGO DE SOLICITUD DEL TOKEN';
		ELIF cEstatus = '1' THEN
	      LET cCodRet = '000';
		  LET cMensaje = 'EL PROCESO DE ALTA SE DETUVO POR PROBLEMAS EN LA DIGITALIZACIÓN';
		ELIF cEstatus = '2' THEN
		  LET cCodRet = '000';
		  LET cMensaje = 'EL PROCESO DE ALTA SE DETUVO POR PROBLEMAS EN LAS AFECTACIONES A TABLAS';
		ELIF cEstatus = '10' THEN		
		  LET cCodRet = '000';
		  LET cMensaje = 'EL CLIENTE MORAL YA CUENTA CON EL SERVICIO DE EMPRESANET ACTIVO EN CENTRAL';
		ELIF cEstatus = '30' THEN
		  LET cCodRet = '000';
		  LET cMensaje = 'EL CLIENTE MORAL YA CUENTA CON EL SERVICIO DE EMPRESANET ACTIVO EN EL PORTAL';
		ELSE
		  LET cCodRet = '001';
		  LET cMensaje = 'ESTATUS NO VALIDO PARA EL PROCESO DE ALTA DE EMPRESA NET';
		END IF 
		
		RETURN cCodRet,cMensaje,TRIM(cEstatus),TRIM(NVL(cUsuarioAut,'')),TRIM(NVL(cCodIdentif,'')),TRIM(NVL(cDescripIdenfOficial,'')),TRIM(NVL(cIdentificacion,'')),TRIM(NVL(cFolioSolToken,''));
	END;
	
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene el estatus del cliente en cuestion al servicio de EmpresaNet.',
'AUTOR:  Valentin Lopez',
'FECHA DE CREACION: 27 de Septiembre del 2011',
'DESCRIPCION MODIFICACION: Cambiar el tamaño de la variable cIdentificacion a char(30) ya que cambio en el tamaño de la tabla y', 
'						   se cambiaron todos los mensajes a mayuscula,se agrego consulta para obtener cDescripIdenfOficial, se',
'						   agrego validacion para el estatus 30, se cambio el orden de retorno para que fuera primero cMensaje y',
'						   despues cEstatus',
'FECHA MODIFICACION: 13 de Marzo del 2012',
'AUTOR MODIFICACION: Guadalupe Payan',
'VERSION: 20120313.1626',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_cnsif_edoctacap(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCUENTA CHAR(20),cANIOMES CHAR(6), cNUMEMP CHAR(20))
							
				returning CHAR(5)  AS Cod_Retorno,
						  CHAR(6)  AS Anio_Mes,
						  CHAR(107) AS Nombre_Cliente,
						  CHAR(30) AS Calle,
						  CHAR(10) AS Numero_Exterior,
