CREATE PROCEDURE "informix".sp_actvalidacioncofetel_pba ( cEmpresa CHAR(3),cNumCte CHAR(9), cFlagTelefonoCasa CHAR(1), cFlagTelefonoCelular CHAR(1),
                                                     cflagTelefonoOficina CHAR(1), cTipoDireccion CHAR(1), cTipo CHAR(1))
    RETURNING
    CHAR(5);
	
    -- Definicion de Variables
    DEFINE cCodRet CHAR(5);
    DEFINE iSql_err INT;
    DEFINE iMaxSecuencia INT;
    DEFINE iMaxSecuencia_actual INT;
	
    -- Inicializa variables
    LET cCodRet = "00000";
    LET iSql_err = 0;
    LET iMaxSecuencia = 0;
    LET iMaxSecuencia_actual = 0;
	
    -----------------------------------------
	--CREACION: Hector Bojorquez
	--FECHA: 2009-02-18
	--FUNCIONALIDAD: Actualiza un registro en la bdinteg:"informix".si_direcciones si el teléfono 
	--                            proporcionado por el cliente en alta de la dirección fue 
	--                            validado por la COFETEL
	----------------------------------------
	--MODIFICACIÓN: Rodolfo Tortolero Varela
	--FECHA: 2011-09-28
	--FUNCIONALIDAD: Se agrega para que tambien actualize en la tabla bdinteg:"informix".si_direcciones_actual.
	----------------------------------------

    --SET DEBUG FILE TO "/tmp/Sp_ActValidacionCofetel.out";
    --TARCE ON;
	SET LOCK MODE TO WAIT 10;
	
    BEGIN
        ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;

        IF ctipo = "1" THEN
			SELECT max(secuencia) INTO iMaxSecuencia  from bdinteg:"informix".si_direcciones  WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion;
			SELECT max(secuencia) INTO iMaxSecuencia_actual  from bdinteg:"informix".si_direcciones_actual  WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion;

			 IF cFlagTelefonoCasa = "1" and cTipoDireccion = "1" THEN
				UPDATE bdinteg:"informix".si_direcciones SET ind_COFETELtel1 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				UPDATE bdinteg:"informix".si_direcciones_actual SET ind_COFETELtel1 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia_actual;
			END IF

			IF cFlagTelefonoCelular = "1" and cTipoDireccion = "1" THEN
				UPDATE bdinteg:"informix".si_direcciones SET ind_COFETELtel2 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				UPDATE bdinteg:"informix".si_direcciones_actual SET ind_COFETELtel2 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia_actual;
			END IF

			IF cFlagTelefonoOficina = "1" and cTipoDireccion = "2" THEN
				UPDATE bdinteg:"informix".si_direcciones SET ind_COFETELtel3 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				UPDATE bdinteg:"informix".si_direcciones_actual SET ind_COFETELtel3 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia_actual;
			END IF
		ELIF ctipo = "0" THEN
			LET iMaxSecuencia = 0;
				SELECT max(secuencia) INTO iMaxSecuencia  from bdinteg:"informix".si_refdirecciones  WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion;
				IF cFlagTelefonoCasa = "1" and cTipoDireccion = "1" THEN
					UPDATE bdinteg:"informix".si_refdirecciones SET ind_COFETELtel1 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				END IF

				IF cFlagTelefonoCelular = "1"and cTipoDireccion = "1" THEN
					UPDATE bdinteg:"informix".si_refdirecciones SET ind_COFETELtel2 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				END IF

				IF cFlagTelefonoOficina = "1" and cTipoDireccion = "1" THEN
					UPDATE bdinteg:"informix".si_refdirecciones SET ind_COFETELtel3 = "V" WHERE  numcte = cNumCte and tipo_dir = cTipoDireccion and secuencia = iMaxSecuencia;
				END IF
		END IF
		
		RETURN cCodRet;
    END;
END PROCEDURE;

create procedure "informix".sp_consejecutivomac_pba(pejecutivo char(8), pmac char(12))
       returning char(5),char(1) ;

define vcodret char(5);
define vciclo smallint;
define vsqlerr integer;


define vmac char(12);
define vstatus char(1);
define vmach char(1) ;
define vsucursal char(4) ;
define vdepto char(3) ;
define vpuesto char(3) ;
define varea char(3) ;

let vmach="0" ;
let vciclo = 0;
let vcodret = "000";
let  vsqlerr = 0;

let vmac = "";
let vstatus = "";
let vsucursal = "";
let vdepto = "";
let vpuesto = "";
let varea = "";

set isolation to dirty read;
set lock mode to wait 3;

begin

   on exception set vsqlerr
      if vsqlerr <> 0 then
	 -- rollback work;
         let vcodret = vsqlerr;
         return vcodret,vmac ;
      end if;
   end exception;

-- Begin work;

        Select sucursal, departamento, puesto
        into vsucursal, vdepto, vpuesto
        from si_ejecut
        where ejecutivo = pejecutivo;

        if cast(nvl(vsucursal,'0') as int) > 0 and cast(nvl(vdepto,'0') as int) = 0 then

            Select {+INDEX(si_macarea idx_si_macarea)} area
            into varea
            From si_macarea
            where sucursal='0001' and puesto = vpuesto;

            if exists(Select ejecutivo From si_macejecutivo where ejecutivo = pejecutivo) then
                Foreach
                    Select mac, status
                    into vmac, vstatus
                    from si_macejecutivo
                    where ejecutivo = pejecutivo

                    if exists(Select {+INDEX(si_sucursalesmaquina idx_si_sucursalesmaquina)} mac From si_sucursalesmaquina where sucursal = trim(vmac) and area = varea and mac = upper(pmac)) then
                        if vstatus in ('A','T') then
                            let vmach='1';
                            exit Foreach;
                        else
                            let vmach='2';
                        end if;
                    else
                         let vmach='3';
                    end if;
                end Foreach;
            else
                let vmach='3';
            end if;

        else
            if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac)) then
                if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac) and me.status in ('A','T')  ) then
                    let vmach='1';
                else
                    let vmach='3';
                end if;
            else
                let vmach='2';
            end if;
        end if;

     return    vcodret,vmach ;

-- commit work;

end
end procedure
DOCUMENT
"regresa mac",
"Autor : Daniel Zambada, Modificó: Frank Gaxiola",
"FECHA : 30/octubre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE procedure "informix".sp_consejecutivomac_pba(pejecutivo char(8), pmac char(12), p_sTipo char(1))
    returning char(5),char(1) ;

define vcodret char(5);
define vciclo smallint;
define vsqlerr integer;
define vmac char(12);
define vstatus char(1);
define vmach char(3) ;
define vsucursal char(4) ;
define msucursal char(4) ;
define vdepto char(3) ;
define vpuesto char(3) ;
define varea char(3) ;
define vsuc char(4) ;
define vtejecut char(2);

let vmach="0" ;
let vciclo = 0;
let vcodret = "000";
let  vsqlerr = 0;

let vmac = "";
let vstatus = "";
let vsucursal = "";
let vdepto = "";
let vpuesto = "";
let varea = "";
let vsuc = "";
let msucursal = "";
let vtejecut = "";



--SET DEBUG FILE TO "/tmp/sp_consejecutivomac.sql";
--TRACE ON;

begin

   on exception set vsqlerr
      if vsqlerr <> 0 then
	 -- rollback work;
         let vcodret = vsqlerr;
         return vcodret,vmac ;
      end if;
   end exception;

        Select sucursal, departamento, puesto
        into vsucursal, vdepto, vpuesto
        from si_ejecut
        where ejecutivo = pejecutivo;

        SELECT sucursal
        INTO msucursal
        FROM si_sucursalesmaquina
        WHERE mac = trim(upper(pmac));

        select tipo_maquina 
        INTO vtejecut        
        from si_equiv_ejecut 
        where tipo_ejecut=p_sTipo;

 --Begin work;

        IF vsucursal = msucursal THEN

          if cast(nvl(vsucursal,'0') as int) > 0 and cast(nvl(vdepto,'0') as int) = 0 then

            Select area
            into varea
            From si_macarea
            where sucursal='0001' and puesto = vpuesto;

            if exists(Select ejecutivo From si_macejecutivo where ejecutivo = pejecutivo) then
                Foreach

                    Select status
                    into vstatus
                    from si_macejecutivo
                    where ejecutivo = pejecutivo

                    Select distinct sucursal
                    into vsuc
                    From si_sucursalesmaquina where mac = trim(upper(pmac));

					IF p_sTipo = 'A' THEN
						if not vsuc = '' then
                            if exists(Select ejecutivo from si_macejecutivo where ejecutivo = pejecutivo and mac = vsuc) then
                                Select status
                                into vstatus
                                from si_macejecutivo
                                where ejecutivo = pejecutivo and mac = vsuc;

                                if vstatus in ('A','T') then
                                    let vmach='1';
                                    exit Foreach;
                                else
                                    let vmach='2';
                                end if;
                            else
                                let vmach='3';
                            end if;
                        else
                             let vmach='3';
                        end if;
					ELSE
                        if exists(Select mac From si_sucursalesmaquina where mac = trim(upper(pmac)) and sucursal = vsuc and area = varea) then
                            if exists(Select mac from si_sucursalesmaquina where sucursal=vsuc and area=varea and departamento=vdepto and vtejecut=varea) then
                                if vstatus in ('A','T') then
                                    let vmach='1';
                                    exit Foreach;
                                else
                                    let vmach='2';
                                end if;
                            else
                                let vmach='3';
                            end if;
                        else
                            let vmach='3';
                        end if;
					END IF;
                end Foreach;
            else
                let vmach='3';
            end if;

        else
            if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac)) then
                if exists(select me.mac from si_macejecutivo me where me.ejecutivo = pejecutivo and me.mac = upper(pmac) and me.status in ('A','T')) then
                    let vmach='1';
                else
                    let vmach='3';
                end if;
            else
                let vmach='2';
            end if;
        end if;

        ELSE
            let vmach='3';
        END IF;

    return    vcodret,vmach ;

-- commit work;
end
end procedure;

CREATE PROCEDURE "informix".sp_buscar_detalle_tarjeta_adicional(p_skip INT, p_numeroTarjeta CHAR(16))
		
    RETURNING CHAR(1) AS titularTarjeta, CHAR(16) AS numeroTarjeta, 
              CHAR(3) AS estatusTarjeta, CHAR(104) AS nombreTarjeta, 
              CHAR(3) AS tipoProducto, CHAR(30) AS descProducto;

	--definicion de variables--	    
	DEFINE resultado_titularTarjeta 	CHAR(1);
    	DEFINE resultado_numeroTarjeta		CHAR(16);
	DEFINE resultado_estatusTarjeta		CHAR(3);
	DEFINE resultado_nombreTarjeta		CHAR(104);
    	DEFINE resultado_tipoProducto 		CHAR(3);
    	DEFINE resultado_descProducto           CHAR(30);
    	DEFINE cuenta_temp			CHAR(20);
   	DEFINE iSqlErr                      	INTEGER;
		
     -- InicializaciÃÂ³n de las variables.
	LET resultado_titularTarjeta = '';
	LET resultado_numeroTarjeta = '';
	LET resultado_estatusTarjeta = '';
	LET resultado_nombreTarjeta = '';
	LET resultado_tipoProducto = '';
    LET resultado_descProducto = '';
	
    SET ISOLATION TO dirty READ;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_titularTarjeta = '';
					LET resultado_numeroTarjeta = '';
					LET resultado_estatusTarjeta = '';
					LET resultado_nombreTarjeta = '';
					LET resultado_tipoProducto = '';
                    LET resultado_descProducto = '';    
                    RETURN resultado_titularTarjeta, resultado_numeroTarjeta,resultado_estatusTarjeta,resultado_nombreTarjeta,resultado_tipoProducto,resultado_descProducto;
                END IF;
        END EXCEPTION;
        
        SELECT numcuenta
        	INTO cuenta_temp
			FROM intercard:tarjetacuenta 
			WHERE intercard:tarjetacuenta.numtarjeta = p_numeroTarjeta;
        
		FOREACH       
	     	SELECT SKIP p_skip DISTINCT titular,numtarjeta,codstatustarjeta,nombre,intercard:tarjeta.codproductotarjeta,descproducto
	          INTO resultado_titularTarjeta, resultado_numeroTarjeta,resultado_estatusTarjeta,resultado_nombreTarjeta,resultado_tipoProducto,resultado_descProducto
	          FROM intercard:tarjeta
                LEFT JOIN intercard:productotarjeta ON (intercard:productotarjeta.codproductotarjeta = intercard:tarjeta.codproductotarjeta)
              WHERE numtarjeta in (select numtarjeta from intercard:tarjetacuenta where numcuenta = cuenta_temp)
	          RETURN resultado_titularTarjeta, resultado_numeroTarjeta,resultado_estatusTarjeta,resultado_nombreTarjeta,resultado_tipoProducto,resultado_descProducto WITH RESUME;
		END FOREACH;
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consctemttorfcalterno(pEmpresa CHAR(4),
													 pNumCte  CHAR(20),
													 pTarjeta CHAR(20),
													 pCuenta  CHAR(20))
RETURNING CHAR(5)   AS CodRetorno,
		  CHAR(20)  AS NumCte,
		  CHAR(26)  AS Nombre1,
		  CHAR(26)  AS Nombre2,
		  CHAR(26)  AS ApPaterno,
		  CHAR(26)  AS ApMaterno,
		  CHAR(13)  AS RFC,
		  CHAR(13)  AS RFC_Alterno,
		  INTEGER   AS iNumeric,
		  CHAR(100) AS Descripcion,
		  DATE      AS Fecha_Nac,
		  SMALLINT  AS Dependientes;

--Definicion de Variables
DEFINE iSqlErr 	     INTEGER;
DEFINE cCodRet		 CHAR(5);
DEFINE cNumCte		 CHAR(20);
DEFINE cNombre1		 CHAR(26);
DEFINE cNombre2 	 CHAR(26);
DEFINE cApPaterno 	 CHAR(26);
DEFINE cApMaterno 	 CHAR(26);
DEFINE cRFC 		 CHAR(13);
DEFINE cRFCAlt 		 CHAR(13);
DEFINE cCuenta       CHAR(20);
DEFINE cBin          CHAR(6);
DEFINE cCredDeb      CHAR(1);
DEFINE cStatus       CHAR(2);
DEFINE cDescripcion  CHAR(100);
DEFINE dFechNacm     DATE;
DEFINE sDependientes SMALLINT;
DEFINE iNumeric      INTEGER;

--Inicializacion de Variables
LET iSqlErr 		= 0;
LET cCodRet 		= '00000';
LET cNumCte 		= '';
LET cNombre1 		= '';
LET cNombre2 		= '';
LET cApPaterno 		= '';
LET cApMaterno 		= '';
LET cRFC 			= '';
LET cRFCAlt 		= '';
LET cCuenta         = '';
LET cBin         	= '';
LET cCredDeb     	= '';
LET cStatus         = '';
LET cDescripcion 	= '';
LET dFechNacm 		= DATE(1);
LET sDependientes   = '0';
LET iNumeric 		= 0;


--SET DEBUG FILE TO '/tmp/sp_consctemttorfcalterno.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet,'','','','','','','','','','','';
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') = '' THEN
			LET cCodRet = '372';
			RETURN cCodRet,'','','','','','','','','','','';
	ELIF NVL(pNumCte,'') = '' AND (NVL(pCuenta,'') = '' AND NVL(pTarjeta,'') = '') THEN
		LET cCodRet = '372';
		RETURN cCodRet,'','','','','','','','','','','';		
	ELSE
		IF pCuenta <> '' THEN
			SELECT num_cte,cuenta 
			INTO cNumCte,cCuenta 
			FROM bdicheq:"informix".sc_maechq 
			WHERE cuenta = pCuenta
			AND status_cta  = '1';
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
				SELECT numcte,num_credito,status_cred 
				INTO cNumCte,cCuenta,cStatus 
				FROM bdicred:"informix".sd_maecred 
				WHERE num_credito = pCuenta;
				
				IF dbinfo("sqlca.sqlerrd2") = 0 THEN
					SELECT numcte,num_credito,status_cred 
					INTO cNumCte,cCuenta,cStatus 
					FROM bdicred:"informix".sd_maecredcrd 
					WHERE num_credito = pCuenta;
					
					IF dbinfo("sqlca.sqlerrd2") = 0 THEN
						LET cCodRet = '00346';
						RETURN cCodRet,'','','','','','','','','','','';
					ELSE
						IF cStatus IN ('CV', 'FF', 'FC') THEN
							LET cCodRet = '00346';
							RETURN cCodRet,'','','','','','','','','','','';
						END IF;
					END IF;
				ELSE
					IF cStatus IN ('CV', 'FF', 'FC') THEN
						LET cCodRet = '00346';
						RETURN cCodRet,'','','','','','','','','','','';
					END IF;
				END IF;
			END IF;
			
		ELIF pTarjeta <> '' THEN
			LET cBin = SUBSTR(pTarjeta,0,6);
			
			SELECT creditodebito 
			INTO cCredDeb
			FROM intercard:"informix".bines 
			WHERE bin = cBin;
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
				LET cCodRet = '00347';
				RETURN cCodRet,'','','','','','','','','','','';
			ELSE
				IF cCredDeb = "C" THEN
					SELECT numcte,num_credito 
					INTO cNumCte,cCuenta 
					FROM bdicred:"informix".sd_tarjeta 
					WHERE num_tarjeta = pTarjeta;
					
					IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
						LET cCodRet = '00347';
						RETURN cCodRet,'','','','','','','','','','','';
					END IF;
				ELIF  cCredDeb = "D" THEN
					SELECT numcte,cuenta
					INTO cNumCte,cCuenta 
					FROM bdicheq:"informix".sc_tarjeta 
					WHERE empresa = "001"
					AND num_tarjeta = pTarjeta;
					
					IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
						LET cCodRet = '00347';
						RETURN cCodRet,'','','','','','','','','','','';
					END IF;
				END IF;
			END IF;
		ELIF pNumCte <> '' THEN
			LET cNumCte = pNumCte;
		END IF;
			SELECT a.numcte,a.nombre1,a.nombre2,a.apell_paterno,a.apell_materno,a.rfc,a.rfc_alterno,a.numeric2,b.descripcioncorta,c.fecha_nac,c.dependientes
			INTO cNumCte, cNombre1,cNombre2,cApPaterno,cApMaterno,cRFC,cRFCAlt,iNumeric,cDescripcion,dFechNacm,sDependientes
			FROM bdinteg:"informix".si_cliente a, bdinteg:"informix".si_catcterelacionado b, bdinteg:"informix".si_ctepf c
			WHERE a.numcte = cNumCte
			AND b.clavetipo = a.numeric2
			AND c.numcte = a.numcte;
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
				LET cCodRet = '00345';
				RETURN cCodRet,'','','','','','','','','','','';
			END IF;
			RETURN cCodRet,cNumCte,cNombre1,cNombre2,cApPaterno,cApMaterno,cRFC,NVL(cRFCAlt,''),iNumeric,cDescripcion,dFechNacm,sDependientes;	
	END IF;	
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Se crea Procedimiento Almacenado para la Consulta del RFC Alterno en Sucursal ',
'AUTOR : Martín Eduardo Miranda',
'FECHA : 02 Agosto 2012',
'VERSION: 20120802.01',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_grabarfcalternobitacoramtto(pEmpresa CHAR(4),
														   pNumCte  CHAR(20),
														   pRFCAnt  CHAR(13),
														   pRFCAlt  CHAR(13),
														   pUserInsert CHAR(8))
RETURNING CHAR(5)  AS CodRetorno;

--Definicion de Variables
DEFINE iSqlErr 	     INTEGER;
DEFINE cCodRet		 CHAR(5);
DEFINE sSecuencia    SMALLINT;
DEFINE dFechaHoy     DATE;

--Inicializacion de Variables
LET iSqlErr 		= 0;
LET cCodRet 		= '00000';
LET sSecuencia      = '0';
LET dFechaHoy 		= DATE(1);


--SET DEBUG FILE TO '/tmp/sp_grabarfcalternobitacoramtto.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;

	IF NVL(pEmpresa,'') = '' THEN
			LET cCodRet = '373';
			RETURN cCodRet;
	ELIF NVL(pRFCAlt,'') = '' THEN
		LET cCodRet = '373';
		RETURN cCodRet;
	ELIF NVL(pUserInsert,'')=''THEN
		LET cCodRet = '373';
		RETURN cCodRet;	
	ELSE
		UPDATE bdinteg:"informix".si_cliente 
		SET rfc_alterno= pRFCAlt
		WHERE empresa = pEmpresa 
		AND numcte = pNumCte;
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
			LET cCodRet = '373';
			RETURN cCodRet;
		ELSE
			SELECT fecha_hoy 
			INTO dFechaHoy
			FROM bdinteg:"informix".si_fechas
			WHERE empresa = pEmpresa;
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
				LET cCodRet = '373';
				RETURN cCodRet;
			ELSE
				SELECT NVL(MAX(Secuencia),'0')
				INTO sSecuencia
				FROM bdinteg:"informix".si_bitacora_rfcalterno 
				WHERE empresa = pEmpresa 
				AND numcte = pNumCte;

				LET sSecuencia = sSecuencia + 1;
				
				INSERT INTO bdinteg:"informix".si_bitacora_rfcalterno (empresa,numcte,secuencia,rfcalt_org,rfcalt_nvo,usert_insert,fecha_insert) 
				VALUES (pEmpresa,pNumCte,sSecuencia,pRFCAnt,pRFCAlt,pUserInsert,dFechaHoy);
				
				IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
					LET cCodRet = '373';
					RETURN cCodRet;
				ELSE
					RETURN cCodRet;
				END IF;
			END IF;
		END IF;
	END IF;	
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Se crea Procedimiento Almacenado para grabar el RFC Alterno en una bitacora, además de actualizarlo en la tabla si_cliente',
'AUTOR : Martín Eduardo Miranda',
'FECHA : 02 Agosto 2012',
'VERSION: 20120802.01',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_obteneredadpersona(pdFechaActual DATE, pdFechaNacimiento DATE)
RETURNING CHAR(5), -- Codigo Retorno
		  CHAR(5); -- Edad

	/*Define iAnios	INTEGER;
	Define iMeses	INTEGER;
	LET iAnios = 0;
	LET iMeses = 0;*/
	
	--DEFINICION DE VARIABLES--
	DEFINE cResultado CHAR(5);

    --INICIALIZACION DE VARIABLES-- 	
	LET cResultado = '';

	--SET DEBUG FILE TO "/respaldosbd/Daniela/sp_obteneredadpersona.out";
	--TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	BEGIN

		--Validacion de los Parametros
		IF (pdFechaActual = '') OR (pdFechaActual IS NULL) THEN
			RETURN '001', ''; 
		ELIF (pdFechaNacimiento = '') OR (pdFechaNacimiento IS NULL) THEN
			RETURN '002', '';
		END IF

		/*LET iAnios = YEAR(pdFechaActual) - YEAR(pdFechaNacimiento);

		IF ( MONTH(pdFechaActual) > MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) > DAY(pdFechaNacimiento) ) OR
		   ( MONTH(pdFechaActual) > MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) = DAY(pdFechaNacimiento) ) THEN
			LET iMeses = MONTH(pdFechaActual) - MONTH(pdFechaNacimiento);
		Elif MONTH(pdFechaActual) > MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) < DAY(pdFechaNacimiento) THEN
			LET iMeses = (MONTH(pdFechaActual) - MONTH(pdFechaNacimiento)) - 1;
		Elif MONTH(pdFechaActual) = MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) = DAY(pdFechaNacimiento) THEN
			LET iMeses = 0;
		Elif MONTH(pdFechaActual) = MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) < DAY(pdFechaNacimiento) THEN
			LET iAnios = iAnios - 1;
			LET iMeses = ((12 - MONTH(pdFechaNacimiento)) + MONTH(pdFechaActual)) - 1;
		Elif MONTH(pdFechaActual) < MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) < DAY(pdFechaNacimiento) THEN
			LET iAnios = 0;
			LET iAnios = (YEAR(pdFechaActual) - YEAR(pdFechaNacimiento)) - 1;
			LET iMeses = ((12 - MONTH(pdFechaNacimiento)) + MONTH(pdFechaActual)) - 1;
		Elif ( MONTH(pdFechaActual) < MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) > DAY(pdFechaNacimiento) ) OR
			 ( MONTH(pdFechaActual) < MONTH(pdFechaNacimiento) AND DAY(pdFechaActual) = DAY(pdFechaNacimiento) ) THEN
			LET iAnios = 0;
			LET iAnios = (YEAR(pdFechaActual) - YEAR(pdFechaNacimiento)) - 1;
			LET iMeses = (12 - MONTH(pdFechaNacimiento)) + MONTH(pdFechaActual);
		End If

		LET cResultado = LPAD(iAnios, 2, '0') ||'.'|| LPAD(iMeses, 2, '0');*/


		SELECT LIMIT 1 CASE WHEN MONTH(pdFechaNacimiento) < MONTH(pdFechaActual)
			THEN YEAR(pdFechaActual) - YEAR(pdFechaNacimiento)
			ELSE CASE WHEN MONTH(pdFechaNacimiento) = MONTH(pdFechaActual) AND DAY(pdFechaNacimiento) <= DAY(pdFechaActual) 
				THEN YEAR(pdFechaActual) - YEAR(pdFechaNacimiento)
				ELSE YEAR(pdFechaActual) - YEAR(pdFechaNacimiento) - 1 
				END 
			END edad
		INTO cResultado
		FROM bdinteg:"informix".si_parentesco;
		
		IF LENGTH(TRIM(cResultado)) = 1 THEN
			LET cResultado = '0' || cResultado; 
		END IF;

		RETURN '000', cResultado;

	END

END PROCEDURE

DOCUMENT
'AUTOR(es):   Martín Valenzuela Ojeda, Vladimir Félix',
'DESCRIPCION: Genera el Tiempo de Vida en Anios y Meses de una Persona.',
'PARAMETROS:  pdFechaActual = Es la Fecha Actual y pdFechaNacimiento = Es la Fecha de Nacimiento de la Persona',
'FECHA :      Julio de 2009',
'VERSION:     20090701',

'MODIFICO:    Daniela Ramírez',
'DESCRIPCION: Optimización del calculo de la edad exacta de una persona',
'FECHA :      Agosto de 2012',
'VERSION:     20120809';

CREATE PROCEDURE "informix".sp_consulsolicporenviar(pEmpresa CHAR(3))

	RETURNING CHAR(5),    --Código Retorno
	          CHAR(20),   --Número de Cliente 
              CHAR(20),   --Número de Solicitud
              CHAR(1050); --Trama de envió de cliente 
	
	--Declaracion de variables
	DEFINE iSqlErr          INTEGER;
	DEFINE vCodRet          CHAR(5);    --Código Retorno
	DEFINE vNumCte          CHAR(20);   --Número Cliente
	DEFINE vNumSolicitud    CHAR(20);   --Número Solicitud
	DEFINE vTrama           CHAR(1050); --Trama Alta Cliente
	DEFINE vCodRet2         CHAR(5);    --Código Retorno 2
	DEFINE iClave       	SMALLINT;   --Clave
	DEFINE cSubClave    	CHAR(5);    --SubClave
	DEFINE cIP          	CHAR(1);    --IP
	DEFINE cMac    	        CHAR(1);    --MAC
	DEFINE cOperador  	    CHAR(8);    --Operador
	
	--Inicializacion de variables
	LET vCodRet         = '00000'; --CONSULTA REGISTROS POR ENVIAR.
	LET vNumCte         = '';
	LET vNumSolicitud   = '';
	LET vTrama          = '';
	LET vCodRet2        = '00000';
	LET iClave          = 90;
	LET cSubClave       = "0015";
	LET cIP    	        = " ";
	LET cMac            = " ";
	LET cOperador       = "informix";
	
	SET ISOLATION TO DIRTY READ;
	
	--SET debug FILE TO '/tmp/sp_consulsolicporenviar.out';
	--TRACE ON;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
		   IF iSqlErr != 0 THEN
				LET vCodret = iSqlErr;
				RETURN vCodret, vNumCte, vNumSolicitud, vTrama;
		   END IF;
		END EXCEPTION;
		
		IF pEmpresa = '' OR pEmpresa IS NULL THEN
			LET vCodRet = '00001'; --PARAMETRO DE ENTRADA VACIO.
			RETURN vCodret, vNumCte, vNumSolicitud, vTrama;
		ELSE
			IF EXISTS (SELECT 1 FROM bdinteg: "informix".si_clientescoppelporenviar WHERE empresa = pEmpresa AND status = 0) THEN
				FOREACH
					
					SELECT	numcte, num_solicitud 
					INTO	vNumCte, vNumSolicitud
					FROM	bdinteg: "informix".si_clientescoppelporenviar
					WHERE	empresa = pEmpresa
					AND		status = 0
					
					EXECUTE PROCEDURE "informix".sp_altactecoppelnuevoparametrico(pEmpresa, vNumCte, vNumSolicitud)
					INTO vCodRet2, vTrama;
					
					LET vCodRet = '00000';
					
					IF vCodRet2 <> '00000' THEN
						LET vCodRet = '00003'; --ERROR EN EL TRAMA DE ENVIO DEL CLIENTE.
					END IF;
					
					LET vTrama = iClave ||"|"|| TRIM(cSubClave) ||"|"|| TRIM(vTrama) ||"|"|| cIP ||"|"|| cMac ||"|"|| cOperador ||"|";
					
					RETURN vCodret, vNumCte, vNumSolicitud, vTrama WITH RESUME;
					
				END FOREACH;
			ELSE
				LET vCodRet = '00002'; --NO HAY REGISTROS PARA ENVIAR A COPPEL.
				RETURN vCodret, vNumCte, vNumSolicitud, vTrama;
			END IF;
		END IF;
	END;
END PROCEDURE
DOCUMENT
"CREO  : Rodolfo Tortolero Varela",
"FECHA : 05/Septiembre/2012",
"Ver.  : 1.1",
"BD    : bdinteg";

CREATE PROCEDURE "informix".bm_valida_password( pUsuario  CHAR(10),  --- Usuario
                                                pPassword CHAR(50) ) --- Contraseña
RETURNING CHAR(5)  AS vCodRet1,     --- Codigo de Retorno
          CHAR(2)  AS vStatus,      --- Status
          CHAR(25) AS vStatusDesc,  --- Descripcion del Status
          INTEGER  AS vSesionToken, --- Session Token
          CHAR(35) AS vGeneralInfo; --- Informacion General
    
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vStatus          CHAR(2);
    DEFINE vStatusDesc      CHAR(25);
    DEFINE vSesionToken     INTEGER;
    DEFINE vGeneralInfo     CHAR(35);
    
    DEFINE vnumcte          CHAR(20);
    DEFINE vnumcel          CHAR(15);
    DEFINE vnumaccesos      INTEGER;
    DEFINE vid_status       CHAR(2);
    DEFINE vexiste_passwd   SMALLINT;
    DEFINE vnumintacce      SMALLINT;
    DEFINE vmaxaccesos      INTEGER;
    DEFINE vsecmax          INTEGER;
    DEFINE vid_oper         CHAR(4);
    DEFINE vid              CHAR(4);
    DEFINE vdesc            CHAR(50);
    DEFINE vfech_ult_ope    datetime year to second;
    DEFINE vmaxfechoper     datetime year to second;
    DEFINE vmaxsecuencia    SMALLINT;    
    DEFINE vfech_ult_ope2   CHAR(19);
    DEFINE vtransaccion     INTEGER;
    
    LET Sql_Err	     = 0;
    LET Isam_Err     = 0;
    LET Desc_Err     = '';
    LET vCodRet1     = '00000';
    LET vCodRet2     = '00000';
    LET vCodRet3     = '';
    LET vStatus      = '00';
    LET vStatusDesc  = '';
    LET vSesionToken = 0;
    LET vGeneralInfo = '';
    
    LET vnumcte = '';
    LET vnumcel = '';
    LET vnumaccesos = 0;
    LET vid_status = '';
    LET vexiste_passwd = 0;
    LET vnumintacce = 0;
    LET vmaxaccesos = 0;
    LET vsecmax = 0;
    LET vid_oper = '';
    LET vid = '';
    LET vdesc = '';
    LET vfech_ult_ope = '';
    LET vmaxfechoper = '';
    LET vmaxsecuencia = 0;
    LET vfech_ult_ope2 = '';
    LET vtransaccion = 0;
    
    BEGIN

    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_valida_password.err";
        --- TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vtransaccion = 1 THEN
                ROLLBACK WORK;
                BEGIN WORK;
            ELSE
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET vtransaccion = 1;
    END EXCEPTION WITH RESUME;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/bm_valida_password.out";
    --- TRACE ON;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        BEGIN WORK;
    END IF;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pUsuario is null OR pUsuario = '') OR 
       (pPassword is null OR pPassword = '') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF LENGTH(pUsuario) <> 8 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario incorrecto, intente de nuevo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario incorrecto, intente de nuevo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // OBTIENE DATOS DEL USUARIO
    SELECT numcte, numcel, numaccesos, id_status
      INTO vnumcte, vnumcel, vnumaccesos, vid_status
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE usuario = pUsuario;
       
    -- // VALIDA EL PASSWORD DEL USUARIO
    SELECT COUNT(*)
      INTO vexiste_passwd
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE numcte = vnumcte
       AND numcel = vnumcel
       AND usuario = pUsuario
       AND password = pPassword;
       
    IF vexiste_passwd = 0 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vSesionToken = 0;
        
        SELECT numintacce
          INTO vnumintacce
          FROM bdinteg:"informix".si_bm_usuarios
         WHERE usuario = pUsuario;
         
        LET vnumintacce = vnumintacce + 1;
         
        IF vnumintacce = 1 THEN
            LET vStatusDesc = 'Contrasena incorrecta, verifique.';
            LET vGeneralInfo = 'Contrasena incorrecta, verifique.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = pUsuario;
        ELIF vnumintacce = 2 THEN
            LET vStatusDesc = 'Contrasena incorrecta, verifique o entre a Olvide mi contrasena.';
            LET vGeneralInfo = 'Contrasena incorrecta, verifique o entre a Olvide mi contrasena.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = pUsuario;
        ELIF vnumintacce >= 3 THEN
            LET vStatusDesc = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
            LET vGeneralInfo = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
            
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = vnumintacce
             WHERE usuario = pUsuario;
        END IF;
        
        IF vtransaccion = 1 THEN
            COMMIT WORK;
            BEGIN WORK;
        ELSE
            COMMIT WORK;
        END IF;
        
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // VALIDA SI EL USUARIO ESTA BLOQUEADO
    SELECT numintacce
      INTO vnumintacce
      FROM bdinteg:"informix".si_bm_usuarios
     WHERE numcte = vnumcte
       AND numcel = vnumcel
       AND usuario = pUsuario;
       
    IF vnumintacce >= 3 THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Bloqueo por seguridad, acuda a sucursal o ingrese al servicio avanzado de bancoppel.com.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    ELSE
        IF vnumintacce > 0 THEN
            UPDATE bdinteg:"informix".si_bm_usuarios
               SET numintacce = 0
             WHERE numcte = vnumcte
               AND numcel = vnumcel
               AND usuario = pUsuario;
        END IF;
    END IF;
     
    -- // OBTIENE NUMERO DE ACCESOS PERMITIDOS AL DIA
    SELECT valor::int
      INTO vmaxaccesos
      FROM bdibpi:"informix".tkn_parametros
     WHERE id_param = '51';
     
    IF vnumaccesos > vmaxaccesos THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Accesos del dia agotados.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Accesos del dia agotados.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
     
    -- // OBTIENE MAXIMA SECUENCIA DEL CLIENTE EN LA BITACORA
    SELECT MAX(secuencia)
      INTO vsecmax
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = vnumcel;
       
    IF vsecmax is null THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
       
    SELECT id_oper, id_session
      INTO vid_oper, vSesionToken
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE DATE(fech_oper) = CURRENT::DATE
       AND numcte = vnumcte
       AND numcel = vnumcel
       AND secuencia = vsecmax;
       
    IF (vid_oper is null OR vid_oper = '') OR (vid_oper <> '2201') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Usuario no firmado.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Usuario no firmado.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF vid_oper IN('1000', '1002', '1003', '1004', '1005') THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Acceso denegado, usuario activo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Acceso denegado, usuario activo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // BUSCA ULTIMA TRANSACCION
    SELECT MAX(fech_oper)
      INTO vmaxfechoper
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE numcte = vnumcte
       AND numcel = vnumcel
       AND id_oper NOT IN('2201','1001');
       
    SELECT MAX(secuencia)
      INTO vmaxsecuencia
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE numcte = vnumcte
       AND numcel = vnumcel
       AND id_oper NOT IN('2201','1001')
       AND fech_oper = vmaxfechoper;
    
    SELECT fech_oper
      INTO vfech_ult_ope
      FROM bdinteg:"informix".si_bm_bitacora
     WHERE numcte = vnumcte
       AND numcel = vnumcel
       AND fech_oper = vmaxfechoper
       AND secuencia = vmaxsecuencia;
       
    --- LET vGeneralInfo = vfech_ult_ope;
    LET vfech_ult_ope2 = vfech_ult_ope;
    LET vGeneralInfo = SUBSTR(vfech_ult_ope2,9,2)||'/'||SUBSTR(vfech_ult_ope2,6,2)||'/'||SUBSTR(vfech_ult_ope2,1,4)||' '||SUBSTR(vfech_ult_ope2,12,8);
    
    LET vsecmax = vsecmax + 1;
    
    -- // GENERA REGISTRO EN BITACORA COMO PASSWORD-USUARIO
    INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
    VALUES(vSesionToken, current, vnumcte, vsecmax, '1000', vnumcel, null, null);
    
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    -- // ACTUALIZA USUARIO 
    UPDATE bdinteg:"informix".si_bm_usuarios
       SET numaccesos = numaccesos + 1,
           fech_ultacces = current
     WHERE usuario = pUsuario
       AND numcte = vnumcte
       AND numcel = vnumcel;
       
    IF ( dbinfo('sqlca.sqlerrd2') = 0 ) THEN
        LET vCodRet1 = '11111';
        LET vStatus = '';
        LET vStatusDesc = 'Error en aplicativo.';
        LET vSesionToken = 0;
        LET vGeneralInfo = 'Error en aplicativo.';
        IF vtransaccion = 1 THEN
            ROLLBACK WORK;
            BEGIN WORK;
        ELSE
            ROLLBACK WORK;
        END IF;
        RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo; 
    END IF;
    
    IF vtransaccion = 1 THEN
        COMMIT WORK;
        BEGIN WORK;
    ELSE
        COMMIT WORK;
    END IF;
    
    RETURN vCodRet1, vStatus, vStatusDesc, vSesionToken, vGeneralInfo;
    
    END;
    
END PROCEDURE;

create procedure "informix".sp_insertadireccioncajera(
                             pModo smallint,--1:GRABA DIRECCION PERSONAL,2:GRABA DIRECCION TRABAJO
                             pempresa char(3),
                             pnumcte char(20),
                             pentre_calles char(40),
                             pestado char(2),
                             pciudad char(3),
                             pcodpostal char(5),
                             ptipotel1 char(1),  
                             ptelefono1 char(13),--9  PARTICULAR
                             ptipotel2 char(1),  
                             ptelefono2 char(13),--11 CELULAR
                             ptipotel3 char(1),  
                             ptelefono3 char(13),--13 REFERENCIA
                             ptelefono4 char(13),--14 TRABAJO
                             pextension char(5),
                             pnoext char(10),
                             pnoint char(10),
                             pdepto char(6),
                             pnocalle integer,
                             pnocolonia integer,
                             ppuntocar char(1),
                             punihabi char(1),
                             pmanz smallint,
                             ppotros smallint,
                             pandador smallint,
                             petapa smallint,
                             plote smallint,
                             pedif smallint,
                             pentrada smallint,
                             pobserva char(80),
                             puser_insert char(8),
                             plugartrabajo char(60),
                             pTienda char(5),
                             pEmpleado char(20))
 returning char(5);

define v_codret char(5);
define v_pais char(3);
define v_ciudadcoppel smallint;
define v_municipio char(3);
define v_secuencia integer;
define v_secuencia2 integer;
define v_sqlerr, v_isamerr integer;
define v_cambio smallint;
define v_teltrabajo char(13);
define v_extension char(5);
--DSB 12/04/2011
DEFINE siOrigen SMALLINT;
--MACF 2011-09-05
define v_codret_tel char(5);

let v_pais = "000";
let v_secuencia = 0;
let v_secuencia2 = 0;
let v_ciudadcoppel = 0;
let v_municipio = "000";
let v_sqlerr = 0;
let v_isamerr = 0;
let v_codret = "000";
let v_cambio = 0;
let v_teltrabajo = "";
let v_extension = "";
--DSB 12/04/2011
LET siOrigen = 0;
--MACF 2011-09-05
let v_codret_tel = '00000';


--SET DEBUG FILE TO "/informix/macf/sp_insertadireccioncajera.trc";
--TRACE ON;

begin
   on exception set v_sqlerr, v_isamerr
      if v_sqlerr != 0 then
         let v_codret=v_sqlerr;
         ROLLBACK WORK;
         return v_codret;
      end if;
   end exception;

BEGIN WORK;

	-- DSB 12/04/2011
	-- Se llena variable con el tipo de origen -> 1 = Tienda, 2 = Sucursal, 3 = CAT
	LET siOrigen = 1;

--TOMA EL PAIS Y LA CIUDAD COPPEL DE CATALOGO DE CIUDADES DEL BANCO PARA SU INSERCION EN EL SI_DIRECCIONES
        select pais,ciudad_coppel
        into v_pais,v_ciudadcoppel
        from bdinteg:si_ciudades
        where ciudad = pciudad and estado = pestado;
--SE TOMA EL TELEFONO DEL TRABAJO Y LA EXTENSION ACTUAL SI ES CAMBIO DE DOMICILIO DEL CTE 
--O LOS NUEVOS PARAMETROS SI ES CAMBIO DE DOMICILIO DEL TRABAJO
        if pModo = 1 then
            --select max(secuencia)
            --into v_secuencia
            --from bdinteg:si_direcciones
            --where numcte = pnumcte and tipo_dir = 2;
            
            --select telefono3,extension
            --into v_teltrabajo,v_extension
            --from bdinteg:si_direcciones
            --where numcte = pnumcte and tipo_dir = 2 and secuencia = v_secuencia;
            
            --tomar directamente el dato de direcciones_actual
            --select telefono3, extension
            --into v_teltrabajo, v_extension
            --from bdinteg:si_direcciones_actual
            --where numcte = pnumcte and tipo_dir = 2;
            
            SELECT telefono, extension INTO v_teltrabajo, v_extension  --2012/09/25 MACF
              FROM bdinteg:si_telefonos_actual
             WHERE numcte = pnumcte AND tipo_tel = 3;
            
        else
            let v_teltrabajo = ptelefono4;
            let v_extension = pextension;
        end if;

        --select max(secuencia)
        --into v_secuencia
        --from bdinteg:si_direcciones
        --where numcte = pnumcte;        
        
        select max(secuencia)
        into v_secuencia
        from bdinteg:si_direcciones_actual
        where numcte = pnumcte;
       
        --Validar que los teléfonos no tengan caractéres diferentes a números. MACF
  
        IF nvl(ptelefono1, '') <> '' THEN
            CALL bdinteg:"informix".sp_validar_telefono(ptelefono1) RETURNING v_codret_tel;
            IF v_codret_tel <> '00000' THEN let ptelefono1 = '';  END IF;
        END IF;
        
        IF nvl(ptelefono2, '') <> '' THEN
            CALL bdinteg:"informix".sp_validar_telefono(ptelefono2) RETURNING v_codret_tel;
            IF v_codret_tel <> '00000' THEN let ptelefono2 = '';  END IF;
        END IF;

        IF nvl(ptelefono3, '') <> '' THEN
            CALL bdinteg:"informix".sp_validar_telefono(ptelefono3) RETURNING v_codret_tel;
            IF v_codret_tel <> '00000' THEN let ptelefono3 = ''; END IF;
        END IF;

        IF pModo <> 1 THEN
            IF nvl(ptelefono4,'') <> '' THEN       
              CALL bdinteg:"informix".sp_validar_telefono(v_teltrabajo) RETURNING v_codret_tel;
              IF v_codret_tel <> '00000' THEN let v_teltrabajo = ''; END IF;
            END IF;
        END IF;
        --Validar que los teléfonos no tengan caractéres diferentes a números. MACF
               
        if pModo = 1 then

            if v_secuencia is null then
                let v_secuencia = 1;
            else
                let v_secuencia = v_secuencia + 1;
            end if;


/*
            insert into bdinteg:si_direcciones
                (numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
                pais,estado,ciudad,municipio,cod_postal,apart_postal,
                tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
                telefono3,extension,estado_inegi,municipio_inegi,localidad_inegi,
                numerociudad,numeroextcalle,numerointcalle,departamento,
                numerocalle,numerocolonia,puntocardinal,unidadhabitac,
                manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
                user_insert,fecha_insert)
            values
                (pnumcte, v_secuencia, "1", "", "", pentre_calles,
                v_pais,pestado,pciudad, v_municipio, pcodpostal,"",
                ptipotel1,ptelefono1,ptipotel2,ptelefono2,ptipotel3,
                v_teltrabajo, v_extension ,"","","",
                v_ciudadcoppel,pnoext,pnoint,pdepto,
                pnocalle,pnocolonia,ppuntocar,punihabi,
                pmanz,ppotros,pandador,petapa,plote,pedif,pentrada,pobserva,
                puser_insert,current); */
				
			 call "informix".direcciones( pEmpresa, 'A', 	pNumCte ,v_secuencia,  	1,		  "",         "",       v_municipio, pentre_calles,
                                     v_pais,   pestado, pciudad, pcodpostal,	ptipotel1,ptelefono1, ptipotel2,ptelefono2,  ptipotel3,
								     v_teltrabajo, 		v_extension, "",        "",       "",		  v_ciudadcoppel,pnoext,pnoint,
									 pdepto,   pnocalle,pnocolonia,ppuntocar,	punihabi, pmanz,	  ppotros,	pandador,	petapa,
									 plote,    pedif,	pentrada,	pobserva,	puser_insert, current, substr(pTienda,1,4), 1)
             returning v_codret;                                                                     
                                         				
				
-- DSB 11/04/2011
-- Se comenta código debido a que no se insertará el nuevo domicilio en la tabla
-- cb_cambiosdomicilio, en lugar de ésto se mandará llamar el sp_registramodifdomicilio
-- que insertará en la tabla si_bitacora_cambiosdom						
--SE GRABA LA MISMA INFORMACION EN LA NUEVA TABLA CB_CAMBIOSDOMICILIO
--            insert into bdicobranza:cb_cambiosdomicilio
--                (numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
--                pais,estado,ciudad,municipio,cod_postal,apart_postal,
--                tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
--                telefono3,extension,estado_inegi,municipio_inegi,localidad_inegi,
--                numerociudad,numeroextcalle,numerointcalle,departamento,
--                numerocalle,numerocolonia,puntocardinal,unidadhabitac,
--                manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
--                user_insert,fecha_insert,tienda,empleado)
--            values
--                (pnumcte, v_secuencia, "1", "", "", pentre_calles,
--                v_pais,pestado,pciudad, v_municipio, pcodpostal,"",
--               ptipotel1,ptelefono1,ptipotel2,ptelefono2,ptipotel3,
--                v_teltrabajo, v_extension ,"","","",
--                v_ciudadcoppel,pnoext,pnoint,pdepto,
--                pnocalle,pnocolonia,ppuntocar,punihabi,
--                pmanz,ppotros,pandador,petapa,plote,pedif,pentrada,pobserva,
--                puser_insert,current,pTienda,pEmpleado);

			EXECUTE PROCEDURE "informix".sp_registramodifdomicilio(pnumcte, siOrigen, pModo, v_secuencia, pTienda, 
														           current, puser_insert, pEmpleado)
						 INTO v_codret;
														
        end if;
        
--SI ES CAMBIO DE DOMICILIO DEL TRABAJO (pModo = 2) ENTONCES

        if pModo = 2 then           

           if v_secuencia is null then
               let v_secuencia = 1;
           else
               let v_secuencia = v_secuencia + 1;
           end if;

        /*
           insert into bdinteg:si_direcciones
             (numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
	      pais,estado,ciudad,municipio,cod_postal,apart_postal,
	      tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
	      telefono3,extension,estado_inegi,municipio_inegi,localidad_inegi,
