            COMMIT WORK;
      else
            ROLLBACK WORK;
      end if;

      return v_codret;
end;
end procedure;

CREATE PROCEDURE "informix".sp_obtienebancos_pba(pBanco CHAR(3))
RETURNING CHAR(6)     AS cCodRet,
		  CHAR(3)     AS CveBanco,
		  CHAR(40)    AS Descripcion,
		  CHAR(1)     AS TipoBanco,
		  INTEGER     AS CveSIF, 
		  VARCHAR(20) AS NombreCorto,
		  CHAR(1)     AS FlagDomiR,
		  CHAR(1)     AS FlagDomiP;		  		  

    DEFINE cCodRet             CHAR(6);
    DEFINE iSql_Err            INTEGER;
    DEFINE iSam_Err            INTEGER;
    DEFINE cCveBanco           CHAR(3);  
    DEFINE cDescripcion        CHAR(40);
    DEFINE cTipoBanco		   CHAR(1);
    DEFINE iCvecesif           INTEGER;
    DEFINE vNombreCorto		   VARCHAR(20);
    DEFINE cFlgdomiR	       CHAR(1);
    DEFINE cFlgdomiP		   CHAR(1);

    LET cCodRet         = '000000';
    LET iSql_Err        = 0;
    LET iSam_Err        = 0;
    LET cCveBanco       = '';
    LET cDescripcion    = '';
    LET cTipoBanco      = ''; 
    LET iCvecesif       = 0;
    LET vNombreCorto    = '';
    LET cFlgdomiR       = '';
    LET cFlgdomiP       = '';

    SET ISOLATION DIRTY READ ;
    SET LOCK MODE TO WAIT 3;

    --- SET DEBUG FILE TO "/home/sysifx/vlv/sp_obtienebancos.out";
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET iSql_Err, iSam_Err
        IF iSql_Err <> 0 OR iSam_Err <> 0 THEN
            LET cCodRet = iSql_Err;
            RETURN cCodRet, cCveBanco, cDescripcion, cTipoBanco, iCvecesif, vNombreCorto, cFlgdomiR, cFlgdomiP;
        END IF;
    END EXCEPTION;

    -- // SE OBTIENE INFORMACION BASICA DEL BANCO.	
    FOREACH 
        SELECT {+INDEX(bdinteg:si_bancos idx_banco)} banco, descripcion, tp_banco, cvecesif, vchrnombrecorto, flg_domi_r, flg_domi_p
          INTO cCveBanco, cDescripcion, cTipoBanco, iCvecesif, vNombreCorto, cFlgdomiR, cFlgdomiP
          FROM bdinteg:"informix".si_bancos
         WHERE banco = CASE WHEN pBanco <> ''  THEN pBanco  ELSE banco END
         ORDER BY banco::INTEGER

        RETURN cCodRet, cCveBanco, cDescripcion, cTipoBanco, iCvecesif, vNombreCorto, cFlgdomiR, cFlgdomiP WITH RESUME;
    END FOREACH;

    -- // SE VERIFICA SI LA CONSULTA REGRESO INFORMACION.
    IF DBINFO("sqlca.sqlerrd2") = 0 THEN
        LET cCodRet = '000002';
        LET cDescripcion = 'No Existe Banco con esa Clave.';
        RETURN cCodRet, cCveBanco, cDescripcion, cTipoBanco, iCvecesif, vNombreCorto, cFlgdomiR, cFlgdomiP;
    END IF;

    END;
    
END PROCEDURE

DOCUMENT
'AUTOR: Valentin Lopez Valenzuela',
'FECHA CREACION: 15 de Julio del 2011',
'DESCRIPCION: Regresa todos los bancos por su clave de banco.',
'MODIFICO: Guadalupe Payan',
'FECHA MODIFICACION: 15 de Agosto del 2011',
'DESCRIPCION: Se eliminaron dos campos que no se encontraban en la tabla', 
'si_bancos productiva y se elimino la variable bandera iCont,se sustituyo por el comando: DBINFO',
'VERSION: 20110815.1046',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_buscararchivo(cEmpresa CHAR(3))
RETURNING

CHAR(5) AS cCodRet,
CHAR(1) AS cBandera;


--DEFINICION DE VARIABLES--
DEFINE cCodRet        CHAR(5);
DEFINE iSqlErr        INTEGER;
DEFINE vNombreArchivo VARCHAR (100);
DEFINE vRuta          VARCHAR (100);

DEFINE cBandera		  CHAR(1);
DEFINE lCadSql	      LVARCHAR(500);
DEFINE vLinea	      VARCHAR(50);

--INICIALIZACION DE VARIABLES--
LET   lCadSql	      = '';
LET   cBandera	      = 'F';
LET   vLinea		  = '';
LET   vNombreArchivo  = '';
LET   vRuta           = '';
LET   cCodRet         = '00000';
LET   iSqlErr         = 0;

BEGIN

	ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
        END IF;

        RETURN cCodRet,'';

    END EXCEPTION;

	SET LOCK MODE TO WAIT 3;

--	SET DEBUG FILE TO "/tmp/sp_buscararchivo.out";
--	TRACE ON;

	IF NVL(cEmpresa, '') = '' THEN
		LET cCodRet = '00001';	--Faltan Parámetros
		RETURN cCodRet, cBandera;
	END IF;

	SELECT valor
	INTO   vRuta
	FROM   bdinteg:"informix".si_param
	WHERE  cod_param = '137';

	IF NVL(vRuta,'') = '' THEN
		LET cCodRet = '00002';	--No existe el Parámetro
		RETURN cCodRet, cBandera;
	END IF;

	SELECT valor
	INTO   vNombreArchivo
	FROM   bdinteg:"informix".si_param
	WHERE  cod_param = '138';

	IF NVL(vNombreArchivo,'') = '' THEN
		LET cCodRet = '00002';	--No existe el Parámetro
		RETURN cCodRet, cBandera;
	END IF;

		--- BORRA LA TABLA TEMPORAL EN CASO DE QUE EXISTA
		IF EXISTS (SELECT tabname FROM systables WHERE tabname = 'tme_busca_archivo') THEN
			DROP TABLE tme_busca_archivo;
		END IF

		--- CREA LA TABLA
		CREATE TABLE tme_busca_archivo
		(linea LVARCHAR(50));

		--- CORRE EL COMANDO LS PARA OBTENER LOS NOMBRES QUE EXISTEN EN LAS CARPETAS Y METERLOS EN EL ARCHIVO buscar.bus
		LET lCadSql = 'ls ' || TRIM(vRuta) || ' > ' || TRIM(vRuta) || 'buscar.bus';
		SYSTEM lCadSql;

		--- GUARDA EL QUERY DEL LOAD EN EL ARCHIVO  *.SQL
		LET lCadSql = 'echo "LOAD FROM ' || TRIM(vRuta) || 'buscar.bus' || ' INSERT INTO tme_busca_archivo" > '|| TRIM(vRuta) || 'EjecutaBusqueda_sp_BuscarArchivo.sql';
		SYSTEM lCadSql;

		--- EJECUTA LAS INSTRUCCIONES QUE ESTAN DENTRO DEL ARCHIVO  *.SQL
		LET lCadSql = 'dbaccess bdinteg ' || TRIM(vRuta) || 'EjecutaBusqueda_sp_BuscarArchivo.sql';
		SYSTEM lCadSql;


		SET ISOLATION TO DIRTY READ;
		--- CICLO PARA BARRER  LA TABLA DE TRABAJO Y BUSCAR EL NOMBRE DEL ARCHIVO
		FOREACH
			SELECT linea
			INTO vLinea
			FROM tme_busca_archivo

			IF vLinea = vNombreArchivo THEN
				LET cBandera = "V";
				EXIT FOREACH;
			END IF

		END FOREACH

		DROP TABLE tme_busca_archivo;

	RETURN cCodRet, cBandera;

END;
END PROCEDURE
DOCUMENT
"Autor : Martha Aguirre",
"FECHA : 30/04/2012",
"Descripcion: Consulta la existencia de un archivo en determinada ruta",
"Si existe regresa 'V' y si no existe regresa 'F' ",
"Ver.  : 1.0",
"BD    : bdinteg";

CREATE PROCEDURE "informix".sp_campaniamensajeporlinea(sIdMensaje SMALLINT, sOrden SMALLINT)

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Consulta el mensaje asignado a una campaña y lo retorna renglón por renglón
--Realizó: Nancy Sevilla Camacho
--Fecha: 19/04/2012
--BD: BDINTEG
--------------------------------------------------------------------
-- MODIFICACIÓN
--Se limpian variables dentro del WHILE
--Modificó: Nancy Sevilla Camacho
--Fecha: 27/06/2012
--BD: BDINTEG
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5)  AS codigo_retorno,
CHAR(55) AS mensaje;

--DEFINICION DE VARIABLES--
DEFINE iSqlErr     INTEGER;
DEFINE cCodRet     CHAR(5);
DEFINE iRows       INTEGER; --27/06/2012
DEFINE cMensaje    CHAR(55);
DEFINE cMensajeInc CHAR(55);
DEFINE cVariable   CHAR(20);
DEFINE cValorVar   CHAR(10);
DEFINE i           INTEGER;

--INICIALIZACION DE VARIABLES--
LET iSqlErr     = 0;
LET cCodRet     = '00000';
LET iRows        = 0;  --27/06/2012
LET cMensaje    = '';
LET cMensajeInc = '';
LET cVariable   = '';
LET cValorVar   = '';
LET i           = 0;

	--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_campaniamensajeporlinea.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cMensaje;
			END IF;
		END EXCEPTION;

		--Valida parámetros de entrada
		IF sIdMensaje IS NOT NULL AND sOrden IS NOT NULL THEN

		-- Se obtiene el mensaje de la campaña
			SELECT mensaje
			  INTO cMensajeInc
			  FROM bdinteg:"informix".si_detcamp
			 WHERE	empresa = '001'
				AND idmensaje = sIdMensaje
               			AND orden = sOrden;

			LET i = 1;
			LET cVariable = "";
			LET cMensaje = "";

			WHILE i <= LENGTH(cMensajeInc)
				IF SUBSTR(cMensajeInc,i,1) = "<" THEN
					LET i = i + 1;
					WHILE SUBSTR(cMensajeInc,i,1) != ">"
						--27/06/2012
					   IF SUBSTR(cMensajeInc,i,1) <> " " tHEN
							LET cVariable = Trim(cVariable) || SUBSTR(cMensajeInc,i,1);
					   ELSE
							LET cVariable = Trim(cVariable) || "|";
					   END IF;
						LET i = i + 1;
                    END WHILE;

					--27/06/2012
					--Se reemplaza caracter para respetar el espacio en blanco
					LET cVariable =  REPLACE(cVariable, "|" ," ");

					IF TRIM(cVariable) <> "" THEN
						-- Se obtiene el valor de la variable
						SELECT valor
						  INTO cValorVar
						  FROM bdinteg:"informix".si_cat_variables
						 WHERE nomvar = cVariable;

						--27/06/2012
						LET iRows = DBINFO("sqlca.sqlerrd2");
						IF iRows = 0 THEN
						   -- No se encontraron registros para ese Id de Mensaje
						   LET cCodRet = '00002';
							RETURN cCodRet,
								   cMensaje;
						END IF;

						--IF cValorVar <> "" THEN  --27/06/2012
							LET cMensaje =  REPLACE(cMensajeInc,"<" || TRIM(cVariable) || ">" ,TRIM(cValorVar));
							--27/06/2012
							LET cVariable = "";
							LET cMensajeInc = cMensaje;
							LET i = 1;
						--27/06/2012
						/*ELSE
						    LET cMensaje =  cMensajeInc;
						END IF;*/
					END IF;
				END IF;
				LET i = i + 1;
			END WHILE;

			--Si no encuentra variables en el texto se asigna el texto original
			IF TRIM(cMensaje) = "" THEN
			    LET cMensaje =  cMensajeInc;
			END IF;

			RETURN cCodRet,
				   cMensaje;
		ELSE

			--Párametros de entrada vacíos
			LET cCodRet = '00001';

			RETURN cCodRet,
				   cMensaje;

		END IF;

	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_campania(iTipoBusqueda INTEGER, cId CHAR(5))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se obtienen los datos de las campañas por Zona y Sucursal
--Realizó: Nancy Sevilla Camacho
--Fecha: 09/03/2012  
--BD: BDINTEG                    
--------------------------------------------------------------------
-- MODIFICACIÓN 
--Se agrega condición en la consulta de la tabla si_maecamp
--Modificó: Nancy Sevilla Camacho
--Fecha: 28/06/2012 
--BD: BDINTEG     
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5),   -- Código_retorno
SMALLINT,  -- Número de transacción
CHAR(50),  -- Descripción de la transacción
CHAR(5),   -- Número de producto
CHAR(50),  -- Descripción del producto
CHAR(1),   -- Código Estatus
CHAR(20),  -- Estatus Cta/Tar
SMALLINT,  -- Id Campaña
SMALLINT,  -- Id Jerarquía
SMALLINT,  -- Código Activa                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
CHAR(2),   -- Activa
CHAR(55),  -- Mensaje con variables
CHAR(2),   -- Sistema
SMALLINT,  -- Combinable
CHAR(55),  -- Mensaje1 con valores
SMALLINT,  -- Act_Zona        --28/06/2012	
CHAR(5);   -- Sucursal        --28/06/2012
 
		
--DEFINICION DE VARIABLES--
DEFINE iSqlErr      INTEGER;
DEFINE cCodRet      CHAR(5);
DEFINE cCodRet2     CHAR(5);
DEFINE iRows        INTEGER;
---------------------------	
DEFINE cNumProducto CHAR(5);
DEFINE cSistema     CHAR(2);
DEFINE cEstatus     CHAR(1);
DEFINE cEstatusDesc CHAR(20);
DEFINE sIdCampania  SMALLINT;
DEFINE sIdJerarquia SMALLINT;
DEFINE sIdZona      SMALLINT;
DEFINE cActivaDesc  CHAR(2);
DEFINE sAct_Zona    SMALLINT;
DEFINE cMensajeVar  CHAR(55);
DEFINE sTransaccion SMALLINT;
DEFINE cDescTransac CHAR(50);
DEFINE cNumProd     CHAR(4);
DEFINE cProducto    CHAR(50);
DEFINE sOrden       SMALLINT;
DEFINE sCombinable  SMALLINT;
DEFINE cMensajeVal  CHAR(55);
DEFINE sIdMensaje   SMALLINT;
DEFINE sActiva      SMALLINT;  --28/06/2012
DEFINE cPlaza       CHAR(3);   --28/06/2012
DEFINE sSucursal    CHAR(5);   --28/06/2012

--INICIALIZACION DE VARIABLES--
LET iSqlErr       = 0;
LET cCodRet       = '00000';
LET cCodRet2      = '00000';
LET iRows         = 0;
LET cNumProducto  = "";
LET cSistema      = "";
LET cEstatus      = "";
LET cEstatusDesc  = "";
LET sIdCampania   = 0;
LET sIdJerarquia  = 0;
LET sIdZona       = 0;
LET sActiva       = "";
LET cActivaDesc   = 0;
LET cMensajeVar   = "";
LET sTransaccion  = 0;
LET cDescTransac  = "";
LET cNumProd      = "";
LET cProducto     = "";
LET sOrden        = 0;
LET sCombinable	  = 0;
LET cMensajeVal   = "";
LET sIdMensaje    = 0;
LET sAct_Zona     = 0;   --28/06/2012
LET cPlaza        = '';  --28/06/2012
LET sSucursal     = '';  --28/06/2012

	--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_consulta_campania.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,
					   sTransaccion,
					   cDescTransac,
					   cNumProd,					   
					   cProducto,
					   cEstatus,					   
				       cEstatusDesc,
					   sIdCampania,
					   sIdJerarquia,
					   sActiva,					   
					   cActivaDesc,					   
					   cMensajeVar,
					   cSistema,
					   sCombinable,
					   cMensajeVal,
					   sAct_Zona,   --28/06/2012
					   sSucursal;	--28/06/2012	 			   
			END IF;
		END EXCEPTION;	
		
		IF iTipoBusqueda IS NOT NULL OR cId <> "" THEN
		
			IF iTipoBusqueda = 0 THEN
			
				FOREACH

				-- Se obtienen los datos de las campañas
					SELECT num_producto, 
						   sistema, 
						   estatus, 
						   DECODE(estatus,'N','NORMAL','A','ATRASO','V','POR VENCER','T','TODOS'),
						   idcamp, 
						   idJerarquia, 
						   idZona,
						   activa, 
						   DECODE(activa,'1','SI','0','NO'), 
						   combinable,
						   idmensaje,
						   tran_nro,
						   act_zona,  --28/06/2012 						   
						   sucursal   --28/06/2012 
					  INTO cNumProducto, 
						   cSistema, 
						   cEstatus, 
						   cEstatusDesc, 
						   sIdCampania, 
						   sIdJerarquia,
						   sIdZona,
						   sActiva, 
						   cActivaDesc,				   
						   sCombinable,
						   sIdMensaje,
						   sTransaccion,
						   sAct_Zona,	--28/06/2012	
                           sSucursal	--28/06/2012					   
					  FROM bdinteg:"informix".si_maecamp
					 WHERE (empresa='001' and sucursal = cId)
						OR (empresa='001' and sucursal = "T")  --28/06/2012 
					 
					IF cNumProducto IS NULL OR cSistema IS NULL OR cEstatus IS NULL OR sIdCampania IS NULL OR sIdJerarquia IS NULL OR sActiva IS NULL THEN
						-- No se encontraron datos de las campañas.
						LET cCodRet = '00005';	
					
						RETURN cCodRet,
							   sTransaccion,
							   cDescTransac,
							   cNumProd,					   
							   cProducto,
							   cEstatus,					   
							   cEstatusDesc,
							   sIdCampania,
							   sIdJerarquia,
							   sActiva,					   
							   cActivaDesc,
							   cMensajeVar,
							   cSistema,
							   sCombinable,
							   cMensajeVal,
							   sAct_Zona,  --28/06/2012	
 							   sSucursal   --28/06/2012	
						  WITH RESUME;		
						 
					END IF;	
							
					LET cMensajeVar = "";
					LET sOrden = 0;
					
					FOREACH
						
						SELECT mensaje, 
							   orden
						  INTO cMensajeVar, 
							   sOrden
						  FROM bdinteg:"informix".si_detcamp
						 WHERE empresa='001' and idmensaje = sIdMensaje
						 ORDER BY orden
						   
						EXECUTE PROCEDURE bdinteg:"informix".sp_campaniamensajeporlinea(sIdMensaje,sOrden) 
									 INTO cCodRet2, cMensajeVal;
									 
						IF cNumProducto = 'T' THEN
						
							LET cNumProd = 'T';
							LET cProducto = 'TODOS';
						
						ELSE									 
						
							IF cSistema = 'SC' THEN
							 
							-- Se obtiene la descripción del producto en Captación
								SELECT producto, 
									   nombre 
								  INTO cNumProd,
									   cProducto
								  FROM bdicheq:"informix".sc_producto
								 WHERE producto = cNumProducto;	
							 
							ELIF cSistema = 'SD' THEN
							 
							-- Se obtiene la descripción del producto en Crédito
								SELECT num_producto, 
									   nombre_prod
								  INTO cNumProd, 
									   cProducto
								  FROM bdicred:"informix".sd_definicion
								 WHERE num_producto = cNumProducto;								 
							 
							END IF;
							
						END IF;							
						
						IF sTransaccion IS NULL OR sOrden IS NULL OR sOrden = 0 THEN
							-- No se encontraron datos de la tabla detalle de las campañas.
							LET cCodRet = '00002';
						END IF;
					
						IF sTransaccion = 0 THEN
							LET cDescTransac = "TODAS LAS TRANSACCIONES";
						ELSE
							-- Se obtiene la descripción de la transacción
							SELECT descripcion
							  INTO cDescTransac
							  FROM bdinteg:"informix".itran
							 WHERE empresa = '001'
							   AND numero = sTransaccion;

							IF cDescTransac IS NULL OR cDescTransac = "" THEN
							-- No se encontró la descripción de la transacción.
								LET cCodRet = '00004';
							END IF;	
						END IF;		

						RETURN cCodRet,
							   sTransaccion,
							   cDescTransac,
							   cNumProd,					   
							   cProducto,
							   cEstatus,					   
							   cEstatusDesc,
							   sIdCampania,
							   sIdJerarquia,
							   sActiva,					   
							   cActivaDesc,
							   cMensajeVar,
							   cSistema,
							   sCombinable,
							   cMensajeVal,
							   sAct_Zona,  --28/06/2012	
							   sSucursal   --28/06/2012	
						  WITH RESUME;		
						
					END FOREACH;	
						
				END FOREACH;
				
				-- 28/06/2012 
				-- Se consulta si la sucursal pertenece a una zona con campaña activa
				SELECT plaza
				  INTO cPlaza
				  FROM bdinteg:"informix".si_sucursales
				 WHERE sucursal = cId;			
			
				IF EXISTS (SELECT 1 FROM bdinteg:"informix".si_maecamp WHERE idzona = cPlaza) THEN
				
					FOREACH				

							SELECT num_producto, 
								   sistema, 
								   estatus, 
								   DECODE(estatus,'N','NORMAL','A','ATRASO','V','POR VENCER','T','TODOS'),
								   idcamp, 
								   idJerarquia, 
								   idZona,
								   activa, 
								   DECODE(activa,'1','SI','0','NO'), 
								   combinable,
								   idmensaje,
								   tran_nro,
								   act_zona,
								   sucursal
							  INTO cNumProducto, 
								   cSistema, 
								   cEstatus, 
								   cEstatusDesc, 
								   sIdCampania, 
								   sIdJerarquia,
								   sIdZona,
								   sActiva, 
								   cActivaDesc,				   
								   sCombinable,
								   sIdMensaje,
								   sTransaccion,
								   sAct_Zona,
								   sSucursal
							   FROM bdinteg:"informix".si_maecamp
							  WHERE idzona = cPlaza

						IF cNumProducto <> "" OR cSistema <> "" OR cEstatus <> "" OR sIdCampania <> "" OR sIdJerarquia <> "" OR sActiva <> "" THEN
						
							LET cMensajeVar = "";
							LET sOrden = 0;
							
							FOREACH
								
								SELECT mensaje, 
									   orden
								  INTO cMensajeVar, 
									   sOrden
								  FROM bdinteg:"informix".si_detcamp
								 WHERE empresa='001' and idmensaje = sIdMensaje
								 ORDER BY orden
								   
								EXECUTE PROCEDURE bdinteg:"informix".sp_campaniamensajeporlinea(sIdMensaje,sOrden) 
											 INTO cCodRet2, cMensajeVal;
											 
								IF cNumProducto = 'T' THEN
								
									LET cNumProd = 'T';
									LET cProducto = 'TODOS';
								
								ELSE									 
								
									IF cSistema = 'SC' THEN
									 
									-- Se obtiene la descripción del producto en Captación
										SELECT producto, 
											   nombre 
										  INTO cNumProd,
											   cProducto
										  FROM bdicheq:"informix".sc_producto
										 WHERE producto = cNumProducto;	
									 
									ELIF cSistema = 'SD' THEN
									 
									-- Se obtiene la descripción del producto en Crédito
										SELECT num_producto, 
											   nombre_prod
										  INTO cNumProd, 
											   cProducto
										  FROM bdicred:"informix".sd_definicion
										 WHERE num_producto = cNumProducto;								 
									 
									END IF;
									
								END IF;							
								
								IF sTransaccion IS NULL OR sOrden IS NULL OR sOrden = 0 THEN
									-- No se encontraron datos de la tabla detalle de las campañas.
									LET cCodRet = '00002';
								END IF;
							
								IF sTransaccion = 0 THEN
									LET cDescTransac = "TODAS LAS TRANSACCIONES";
								ELSE
									-- Se obtiene la descripción de la transacción
									SELECT descripcion
									  INTO cDescTransac
									  FROM bdinteg:"informix".itran
									 WHERE empresa = '001'
									   AND numero = sTransaccion;

									IF cDescTransac IS NULL OR cDescTransac = "" THEN
									-- No se encontró la descripción de la transacción.
										LET cCodRet = '00004';
									END IF;	
								END IF;								
						
								RETURN cCodRet,
									   sTransaccion,
									   cDescTransac,
									   cNumProd,					   
									   cProducto,
									   cEstatus,					   
									   cEstatusDesc,
									   sIdCampania,
									   sIdJerarquia,
									   sActiva,					   
									   cActivaDesc,
									   cMensajeVar,
									   cSistema,
									   sCombinable,
									   cMensajeVal,
									   sAct_Zona,  --28/06/2012									   
									   sSucursal   --28/06/2012
								  WITH RESUME;	
								  
							END FOREACH;								  
							 
						END IF;									

					END FOREACH;

				END IF;
				--
			
			ELSE
			
				FOREACH

				-- Se obtienen los datos de las campañas
					SELECT num_producto,
						   sistema,
						   estatus,
						   DECODE(estatus,'N','NORMAL','A','ATRASO','V','POR VENCER','T','TODOS'),
						   idcamp,
						   idJerarquia,
						   activa,				   
						   DECODE(activa,'1','SI','0','NO'),
						   combinable,
						   idmensaje,
						   tran_nro,
						   act_zona,  --28/06/2012
						   sucursal   --28/06/2012
					  INTO cNumProducto,
						   cSistema,
						   cEstatus,
						   cEstatusDesc,
						   sIdCampania,
						   sIdJerarquia,
						   sActiva,
						   cActivaDesc,
						   sCombinable,
						   sIdMensaje,
						   sTransaccion,
						   sAct_zona,  --28/06/2012
						   sSucursal   --28/06/2012
					  FROM bdinteg:"informix".si_maecamp
					 WHERE IdZona = cId	
					 
					IF cNumProducto IS NULL OR cSistema IS NULL OR cEstatus IS NULL OR sIdCampania IS NULL OR sIdJerarquia IS NULL OR sActiva IS NULL THEN
						-- No se encontraron datos de las campañas.
						LET cCodRet = '00005';	
					
						RETURN cCodRet,
							   sTransaccion,
							   cDescTransac,
							   cNumProd,					   
							   cProducto,
							   cEstatus,					   
							   cEstatusDesc,
							   sIdCampania,
							   sIdJerarquia,
							   sActiva,					   
							   cActivaDesc,
							   cMensajeVar,
							   cSistema,
							   sCombinable,
							   cMensajeVal,
							   sAct_Zona,  --28/06/2012
							   sSucursal   --28/06/2012
						  WITH RESUME;		
						 
					END IF;						 

					LET cMensajeVar = "";
					LET sOrden = 0;
					
					FOREACH
						
						SELECT mensaje, 
							   orden
						  INTO cMensajeVar, 
							   sOrden
						  FROM bdinteg:"informix".si_detcamp
						 WHERE empresa='001' and idmensaje = sIdMensaje
						   
						EXECUTE PROCEDURE bdinteg:"informix".sp_campaniamensajeporlinea(sIdMensaje,sOrden) 
									 INTO cCodRet2, cMensajeVal;					   

						IF cNumProducto = 'T' THEN
						
							LET cNumProd = 'T';						
							LET cProducto = 'TODOS';
						
						ELSE
						
							IF cSistema = 'SC' THEN
							 
							-- Se obtiene la descripción del producto en Captación
								SELECT producto,
									   nombre
								  INTO cNumProd,
									   cProducto
								  FROM bdicheq:"informix".sc_producto
								 WHERE producto = cNumProducto;	
							 
							ELIF cSistema = 'SD' THEN
							 
							-- Se obtiene la descripción del producto en Crédito
								SELECT num_producto,
									   nombre_prod
								  INTO cNumProd,
									   cProducto
								  FROM bdicred:"informix".sd_definicion
								 WHERE num_producto = cNumProducto;			
							 
							END IF;
							
						END IF;		

						IF sTransaccion IS NULL OR sOrden IS NULL OR sOrden = 0 THEN
							-- No se encontraron datos de la tabla detalle de las campañas.
							LET cCodRet = '00002';
						END IF;
						
						IF sTransaccion = 0 THEN
							LET cDescTransac = "TODAS LAS TRANSACCIONES";
						ELSE
							-- Se obtiene la descripción de la transacción
							SELECT descripcion
							  INTO cDescTransac
							  FROM bdinteg:"informix".itran
							 WHERE empresa = '001'
							   AND numero = sTransaccion;

							IF cDescTransac IS NULL OR cDescTransac = "" THEN
							-- No se encontró la descripción de la transacción.
								LET cCodRet = '00004';
							END IF;	
						END IF;								
					
						RETURN cCodRet,
							   sTransaccion,
							   cDescTransac,
							   cNumProd,					   
							   cProducto,
							   cEstatus,					   
							   cEstatusDesc,
							   sIdCampania,
							   sIdJerarquia,
							   sActiva,					   
							   cActivaDesc,
							   cMensajeVar,
							   cSistema,
							   sCombinable,
							   cMensajeVal,
							   sAct_Zona,   --28/06/2012
						       sSucursal    --28/06/2012							   
						  WITH RESUME;	
					  
					END FOREACH;				  
						
				END FOREACH;				 
			
			END IF;

		ELSE 
		
			-- Parámetros de entrada vacíos
			LET cCodRet = '00001';

		END IF;				
		
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_variables()

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se consulta las variables de la tabla si_cat_variables
--Realizó: Nancy Sevilla Camacho
--Fecha: 08/03/2012                    
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5)  AS codigo_retorno,
INTEGER  AS id_variable,
CHAR(15) AS nomvar,
CHAR(10) AS valor;
		
--DEFINICION DE VARIABLES--
DEFINE iSqlErr     INTEGER;
DEFINE cCodRet     CHAR(5);	
DEFINE iVariableId INTEGER;
DEFINE cNomVar     CHAR(15);
DEFINE cValor      CHAR(10);

--INICIALIZACION DE VARIABLES--
LET iSqlErr     = 0;
LET cCodRet     = '00000';
LET iVariableId = 0;
LET cNomVar     = "";
LET cValor     = "";
	
	--SET DEBUG FILE TO "/home/informix/sp_consulta_variables.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,iVariableId,cNomVar,cValor;
			END IF;
		END EXCEPTION;	
		
		FOREACH
			
		-- Se obtienen los datos de las variables
			SELECT id_variable,
				   nomvar,
				   valor
			  INTO iVariableId,
				   cNomVar,
				   cValor
			  FROM bdinteg:"informix".si_cat_variables
			  where id_variable>0	  

			  RETURN cCodRet,
					 iVariableId,
					 cNomVar,
					 cValor
				WITH RESUME;	

		END FOREACH;	
		
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacampaniajerarquia_max(cEmpresa CHAR(3),sIdCampania SMALLINT, sIdEjecucion SMALLINT)

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se consulta el valor máximo de la campaña y jerarquía
--Realizó: Nancy Sevilla Camacho
--Fecha: 04/04/2012                    
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5)  AS codigo_retorno,
INTEGER  AS idCampania,
INTEGER  AS idJerarq;
		
--DEFINICION DE VARIABLES--
DEFINE iSqlErr     INTEGER;
DEFINE cCodRet     CHAR(5);	
DEFINE idCampania  INTEGER;
DEFINE idJerarq    INTEGER;

--INICIALIZACION DE VARIABLES--
LET iSqlErr     = 0;
LET cCodRet     = '00000';
LET idCampania  = 0;
LET idJerarq    = 0;
	
	--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_consultacampaniajerarquia_max.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,idCampania,idJerarq;
			END IF;
		END EXCEPTION;	
		
	-- Se valida que los parámetros de entrada no vengan vacíos		
		IF NVL(cEmpresa,"") = "" THEN
			-- Parámetros de entrada vacíos
			LET cCodRet = "00001";	
			RETURN cCodRet,
			       idCampania,
				   idJerarq;
		END IF
				
		IF sIdEjecucion = 1 THEN    -- MAXIMA CAMPAÑA
				
			-- Se obtiene el valor max del idCampaña
			SELECT MAX(idcamp)
			  INTO idCampania
			  FROM bdinteg:"informix".si_maecamp
			  Where empresa='001' and idcamp>0;

			IF NVL(idCampania,0) = "" OR idCampania IS NULL THEN
			    LET idCampania = 0;
			END IF;

		ELIF sIdEjecucion = 2 THEN	 -- MAXIMA JERARQUIA

			-- Se obtiene el valor max del idJerarquia
			SELECT MAX(idjerarquia)
			  INTO idJerarq
			  FROM bdinteg:"informix".si_maecamp
			 WHERE empresa = cEmpresa
			   AND idcamp = sIdCampania;
		
			IF NVL(idJerarq,0) = "" OR idJerarq IS NULL THEN
				LET idJerarq = 0;
			END IF;
		
		END IF;		

		  RETURN cCodRet,
				 idCampania,
				 idJerarq;
					  
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarcatzonas(cEmpresa CHAR(3), cPlaza CHAR(3))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se obtiene el catálogo de zonas
--Realizó: Nancy Sevilla Camacho
--Fecha: 24/05/2012                    
--------------------------------------------------------------------

    --DATOS A REGRESAR---	
    RETURNING   CHAR(5) AS retorno,
				CHAR(3) AS empresa,
				CHAR(3) AS plaza,
				CHAR(40) AS nombre,
				CHAR(3) AS regional;

	--DEFINICION DE VARIABLES--					
    DEFINE iSqlErr          INTEGER;
    DEFINE cCodRet    		CHAR(5);
    ---------------------------	
    DEFINE cEmpresa 	    CHAR(3);
    DEFINE cPlaza	        CHAR(3);
    DEFINE cNombre          CHAR(40);
    DEFINE cRegional        CHAR(3);

	--INICIALIZACION DE VARIABLES--	
    LET cCodRet = '00000';
	LET cEmpresa = '';
	LET cPlaza = '';
	LET cNombre = '';
	LET cRegional = '';
	
	--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_consultarcatzonas.out";
	--TRACE ON;	
	
	SET LOCK MODE TO WAIT 3;		

	-- INICIO DEL PROCEDIMIENTO		
    BEGIN
	-- MANEJADOR DE ERRORES		
        ON EXCEPTION SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET cCodRet = iSqlErr;
					RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
                END IF;
        END EXCEPTION;

        IF cPlaza = '' THEN
            LET cPlaza = NULL;
        END IF;

        FOREACH

            SELECT DISTINCT sSuc.empresa, sSuc.plaza, sPlas.nombre, sPlas.regional
              INTO cEmpresa, cPlaza, cNombre, cRegional
              FROM bdinteg:"informix".si_sucursales sSuc, bdinteg:"informix".si_plazas sPlas
             WHERE sSuc.empresa='001' and sSuc.plaza = NVL(cPlaza, sPlas.plaza) 
               AND sSuc.tpo_sucursal = 'S'
             ORDER BY sSuc.plaza

			RETURN cCodRet, 
				   cEmpresa, 
				   cPlaza, 
				   cNombre, 
				   cRegional 
			  WITH RESUME;
			
		END FOREACH;
		
    END;
	
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultatransacciones(cEmpresa CHAR(3), cSistema CHAR(2))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se obtiene el catálogo de transacciones por sistema
--Realizó: Nancy Sevilla Camacho
--Fecha: 30/03/2012                    
--------------------------------------------------------------------												
		
    --DATOS A REGRESAR---		
	RETURNING CHAR(5),	-- Código de retorno
			  SMALLINT, -- Número de transacción
			  CHAR(50);	-- Nombre del producto

	--DEFINICION DE VARIABLES--
	DEFINE cCodRet      CHAR(5);
	DEFINE iSqlErr      INTEGER;
    ---------------------------
	DEFINE sNumTransac  SMALLINT;
	DEFINE cDescTransac CHAR(50);	
	
	--INICIALIZACION DE VARIABLES--
	LET cCodRet = '00000';
	LET iSqlErr = 0;

	LET sNumTransac = 0;
	LET cDescTransac = '';

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, 
			       sNumTransac, 
				   cDescTransac;
		END EXCEPTION;

		--SET DEBUG FILE TO "/home/sysifx/Nancy/sp_consultatransacciones.out";
		--TRACE ON;
		
		--Valida parámetros de entrada
		IF cEmpresa <> '' OR cSistema <> '' THEN			

			FOREACH	 
				-- Se obtiene la descripción de la transacción
				SELECT numero,
					   descripcion
				  INTO sNumTransac,
					   cDescTransac
				  FROM bdinteg:"informix".itran
				 WHERE empresa = cEmpresa
				   AND sistema = cSistema	
				 ORDER BY descripcion		   

				RETURN cCodRet, 
					   sNumTransac, 
					   cDescTransac		   
				  WITH RESUME;
			END FOREACH;
			
		ELSE
		
			--Parámetro de entrada vacío
			LET cCodRet = '00001';
			
			RETURN cCodRet, 
				   sNumTransac, 
				   cDescTransac		   
			  WITH RESUME;			
			
		END IF;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultavalorvariable (cNombre CHAR(15))

--DATOS A REGRESAR---
RETURNING
CHAR (5)   AS cCodRet,
CHAR (100) AS cDescrip;


--DEFINICION DE VARIABLES--
DEFINE iSql_err     INT;
DEFINE cCodRet      CHAR(5);
DEFINE cDescrip     CHAR(10);


--INICIALIZACION DE VARIABLES--
LET iSql_err      = 0;
LET cCodRet      = '00000';
LET cDescrip     = '';

   --SET DEBUG FILE TO "/respaldosbd/Martha/sp_consultavalorvariable.out";
   --TRACE ON;
  
BEGIN

	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet, cDescrip;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF NVL(cNombre, '') = '' THEN
		
		LET cCodRet = '00002';
				
	ELSE
	
		SELECT TRIM(valor) 
		INTO cDescrip 
		FROM bdinteg:"informix".si_cat_variables 
		WHERE nomvar = cNombre
		AND id_variable > 0;
	
		IF DBINFO("sqlca.sqlerrd2") = 0 THEN
		
			LET cCodRet = '00001';
				
		END IF;
		
	END IF;
	
	RETURN cCodRet,NVL(cDescrip,'');
	
END
END PROCEDURE

DOCUMENT
"Autor : Martha Aguirre",
"FECHA : 23/04/2012",
"Descripcion: Consulta si existe el registro en la tabla si_cat_variables",
"Ver.  : 1.0",
"BD    : bdinteg";

CREATE PROCEDURE "informix".sp_vistapreviaticket (cEmpresa CHAR(3), sTran SMALLINT)

--DATOS A REGRESAR---
RETURNING
CHAR(5)   AS cCodRet, 
INTEGER   AS iSecTicket,
INTEGER   AS iPosDesc,
CHAR(100) AS cDescrip,
INTEGER   AS iPosCampo,
CHAR(20)  AS cCampo,
CHAR(1)   AS Estatus;

--DEFINICION DE VARIABLES--
DEFINE iSql_err     INT;
DEFINE cCodRet      CHAR(5);
DEFINE sFormatCert  SMALLINT;
DEFINE iSec         INTEGER;
DEFINE iCont        INTEGER;
DEFINE iCont2       INTEGER;

--VARIABLES PARA TICKET--
DEFINE iSecTicket   INTEGER; 
DEFINE iPosDesc     INTEGER;
DEFINE cDescrip     CHAR(100);
DEFINE cDescrip2    CHAR(100);
DEFINE iPosCampo    INTEGER;
DEFINE iPosCampo2   INTEGER;
DEFINE cCampo       CHAR(20);
DEFINE cEstatus     CHAR(1);
DEFINE cEstatus2    CHAR(1);

--INICIALIZACION DE VARIABLES--
LET iSql_err      = 0;
LET cCodRet      = '00000';
LET sFormatCert  = 0;
LET iSec         = 0;
LET iCont        = 1;
LET iCont2       = 0;

--VARIABLES PARA TICKET--
LET iSecTicket   = 0;
LET iPosDesc     = 0;
LET cDescrip     = '';
LET cDescrip2    = '';
LET iPosCampo    = 0;
LET iPosCampo2   = 0;
LET cCampo       = '';
LET cEstatus     = '';
LET cEstatus2    = '';

   --SET DEBUG FILE TO "/respaldosbd/Martha/sp_vistapreviaticket.out";
   --TRACE ON;
  
BEGIN

	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet, iSecTicket, iPosDesc, cDescrip, iPosCampo, cCampo, cEstatus;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF NVL(cEmpresa, '') = '' OR NVL(sTran, 0) = 0 THEN
		
		LET cCodRet = '00001';
		RETURN cCodRet, iSecTicket, iPosDesc, cDescrip, iPosCampo, cCampo, cEstatus;
		
	ELSE
				
		SELECT formato_certifica INTO sFormatCert FROM bdinteg:"informix".itran WHERE numero = sTran AND empresa = cEmpresa;
		
		IF DBINFO("sqlca.sqlerrd2") > 0 THEN
				
			SELECT MAX (secuencia) INTO iSec FROM bdinteg:"informix".vcertif_det WHERE cod_documento = sFormatCert AND empresa = cEmpresa;

			IF DBINFO("sqlca.sqlerrd2") > 0 THEN
			
				WHILE iCont <= iSec 
																					
					SELECT secuencia,posdesc,descripcion,poscampo,campo,estatus
					INTO   iSecTicket,iPosDesc,cDescrip,iPosCampo,cCampo,cEstatus
					FROM   bdinteg:"informix".vcertif_det 
					WHERE  cod_documento = sFormatCert
					AND    secuencia = iCont
					AND    empresa = cEmpresa;
																	
					IF DBINFO("sqlca.sqlerrd2") > 0 THEN
					
							IF iPosDesc > 0 THEN
								FOR iCont2 = 1 TO iPosDesc
									LET cDescrip = ' ' || cDescrip ;
								END FOR
							END IF;
							
							IF cCampo = "" THEN
								LET cDescrip = "";
							END IF;

							SELECT estatus, descripcion, poscampo
							INTO   cEstatus2,cDescrip2,iPosCampo2
							FROM   bdinteg:"informix".vcertif_det 
							WHERE  cod_documento = sFormatCert
							AND    secuencia = iCont + 1 
							AND    empresa = cEmpresa;
							
							IF TRIM(cEstatus2) = 'M' THEN
								FOR iCont2 = 1 TO iPosCampo2
									LET cDescrip2 = ' ' || cDescrip2 ;
								END FOR
								LET cDescrip = cDescrip || cDescrip2;
								LET iCont = iCont + 1;
							END IF;
							
							RETURN cCodRet, iSecTicket, iPosDesc, cDescrip, iPosCampo, cCampo, cEstatus WITH RESUME;
										
					END IF;
					
						LET iCont = iCont + 1;	
					
				END WHILE;
			
			ELSE
			
				LET cCodRet = '00003';
				RETURN cCodRet, iSecTicket, iPosDesc, cDescrip, iPosCampo, cCampo, cEstatus;
				
			END IF;
			
		ELSE
		
			LET cCodRet = '00002';
			RETURN cCodRet, iSecTicket, iPosDesc, cDescrip, iPosCampo, cCampo, cEstatus;
			
		END IF;
		
	END IF;

END
END PROCEDURE

DOCUMENT
"Autor : Martha Aguirre",
"FECHA : 23/04/2012",
"Descripcion: Consulta datos para la vista previa del ticket inteligente",
"Ver.  : 1.0",
"BD    : bdinteg";

CREATE PROCEDURE "informix".sp_validaestatuspersonal (pEmpresa CHAR(3),pSucursal CHAR(4),pCodUsuario CHAR(8))

--DATOS A REGRESAR---
RETURNING
CHAR    (5)   AS cCodRet,
CHAR    (6)   AS sEstatus;


--DEFINICION DE VARIABLES--
DEFINE iSql_err       INTEGER;
DEFINE cCodRet        CHAR(5);
DEFINE cEmpleado      CHAR(8);
DEFINE vPassword      VARCHAR (200);
DEFINE cSucursal      CHAR(4);
DEFINE cStatus        CHAR(6);

--INICIALIZACION DE VARIABLES--
LET iSql_err           = 0;
LET cCodRet           = '00000';
LET cEmpleado         = '';
LET vPassword         = '';
LET cSucursal         = '';
LET cStatus           = '';

   --SET DEBUG FILE TO "/respaldosbd/Martha/sp_validaestatuspersonal.out";
   --TRACE ON;
  
BEGIN

	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,cStatus;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF NVL(pEmpresa, '') = '' OR NVL(pSucursal, '') = '' OR NVL(pCodUsuario,'') = '' THEN
		
		LET cCodRet = '00001';
		
	ELSE

		SELECT ejecutivo, password, sucursal 
		INTO cEmpleado, vPassword, cSucursal
		FROM bdinteg:"informix".si_ejecut 
		WHERE empresa = pEmpresa
		AND ejecutivo = pCodUsuario;
					
		IF DBINFO("sqlca.sqlerrd2") > 0 THEN
		
			IF TRIM (UPPER(vPassword)) <> "BAJA" THEN
				IF cSucursal = pSucursal THEN
					LET cStatus = 'ACTIVO'; 
				ELSE
					LET cStatus = 'CAMBIO';
				END IF;
			ELSE
				LET cStatus = 'BAJA';
			END IF;
		
		ELSE
			LET cStatus = 'BAJA';
		END IF;
		
	END IF;

	RETURN cCodRet,cStatus;
	
END
END PROCEDURE

DOCUMENT
"Autor : Martha Aguirre",
"FECHA : 07/09/2012",
"Descripcion: Realiza consulta para validar que el usuario",
"se encuentre activo en la sucursal",
"Ver.  : 1.0",
