--LET vTipo_Dir = '';
LET vFecha_Hoy = DATE(1);
LET vNombre = '';
--LET vEdad = 0;
LET vsSQL = "";
LET vCodRetorno = '000000';
LET dFechaAlta = DATE(1);
--LET cValor = '';
--LET iIngreso = 0;
