CREATE PROCEDURE "informix".sp_constelefonofechaact(pEmpresa CHAR(3), pNumcte CHAR(20))
	RETURNING 	CHAR(5) AS retorno;
	
	-- DEFINICION DE VARIABLES
	DEFINE iSqlErr			INTEGER;
	DEFINE cCodRet  		CHAR(5);
	DEFINE cFechaHr         CHAR(23);
	DEFINE dFechaHoy        DATE;
	
	--INICIALIZACION DE VARIABLES       
	LET cCodRet         = '00001';
	LET iSqlErr         = 0;
	LET cFechaHr        = '';
    LET dFechaHoy       =CURRENT;
	
	--SET DEBUG FILE TO "/respaldosbd/jasmin/sp_constelefonofechaact.out"; 
	--TRACE ON;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO wait 3;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
			    LET cCodRet =  iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		
		IF NVL(pEmpresa,'') <> '' AND NVL(pNumcte,'') <>'' THEN
		
			IF EXISTS (SELECT numcte FROM "informix".si_telefonos WHERE empresa = pEmpresa AND numcte =pNumCte)THEN
				 SELECT MAX(fecha_hora) 
				 INTO cFechaHr 
				 FROM "informix".si_telefonos 
				 WHERE empresa = pEmpresa 
				 AND numcte = pNumCte;
				 
				LET cFechaHr = SUBSTRING(cFechaHr FROM 6 FOR 2) || "/" || SUBSTRING(cFechaHr FROM 9 FOR 2) || "/" || SUBSTRING(cFechaHr FROM 1 FOR 4);
				
				SELECT fecha_hoy 
				INTO dFechaHoy
				FROM "informix".si_fechas 
				WHERE empresa = pEmpresa;
				
				
			   IF dFechaHoy = cFechaHr THEN
					LET cCodRet = '00002';
			   ELSE 
					LET cCodRet = '00000';
				
			   END IF;
			ELSE
			  LET cCodRet = '00000';	
			END IF;
		
		END IF;
		
		RETURN cCodRet;
	END
END PROCEDURE             
DOCUMENT
'Creado: Jasmin Soto F.',
'Fecha: 13/11/2012',
'Descripcion: Se crea para capturar numero de telefono del cliente seleccionado',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_guarda_telefonos(pEmpresa CHAR(3), 
													    pNumcte CHAR (20), 
													    pTelcasa CHAR (10), 
													    pTelcelular CHAR (10), 
													    pTeloficina CHAR (10),
													    pTelotro CHAR (10),
													    pCarrier SMALLINT,
													    pExtension CHAR(5),
													    pUserInsert  CHAR(8))
	RETURNING CHAR(5) AS CodRetorno;

--Definicion de Variables
DEFINE iSqlErr 		   INTEGER;
DEFINE cCodRet 		   CHAR(5);

--Inicializacion de Variables
LET iSqlErr 		= 0;
LET cCodRet 		= '00000';

	--SET DEBUG FILE TO "/respaldosbd/jasmin/sp_guarda_telefonos.out"; 
	--TRACE ON; 

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		
	IF NVL(pEmpresa,'') <> '' AND NVL(pNumcte,'') <> '' AND (NVL(pTelcasa, '') <> '' OR NVL(pTelcelular, '') <> '' OR NVL(pTeloficina, '') <> '' OR NVL(pTelotro, '') <> '') THEN
		
		IF pTelcasa <> '' THEN
			
			EXECUTE PROCEDURE "informix".sp_registra_telefonos (pEmpresa, pNumcte, pTelcasa, 1, '', 0, 1, pUserInsert) INTO cCodRet;
		
		END IF;
		IF cCodRet::INT = 0 OR cCodRet= '999' THEN
		
			IF pTelcelular <> '' THEN 
				
				EXECUTE PROCEDURE "informix".sp_registra_telefonos (pEmpresa, pNumcte, pTelcelular, 2, '', pCarrier, 1, pUserInsert) INTO cCodRet;
			
			END IF;
			IF cCodRet::INT = 0 OR cCodRet= '999' THEN
			 
				IF pTeloficina <> '' THEN
			
					EXECUTE PROCEDURE "informix".sp_registra_telefonos (pEmpresa, pNumcte, pTeloficina, 3, pExtension, 0, 1, pUserInsert) INTO cCodRet;
			
				END IF;
				
				IF cCodRet::INT = 0 OR cCodRet= '999' THEN
					IF pTelotro <> '' THEN 
						EXECUTE PROCEDURE "informix".sp_registra_telefonos (pEmpresa, pNumcte, pTelotro, 4, '', 0, 1, pUserInsert) INTO cCodRet;
			
					END IF;	
				END IF;
				 
			END IF;
		END IF;
	ELSE 
		LET cCodRet = '00001';	
	END IF;
	
RETURN cCodRet;

END;
END PROCEDURE

DOCUMENT
'DESCRIPCION: Se crea SP para registrar cada telefono del cliente',
'AUTOR : Jasmin Soto F. ',
'FECHA : 20/11/2012',
'VERSION: 1.0',
'BD: bdinteg';

create procedure "informix".cons_dir_cte_esp( pcliente char(20), pnum_regs smallint )
RETURNING char(5), char(50), char(10), char(10), char(10), char(30), char(60), char(30), 
          char(80), char(40), char(100), char(100), char(13), char(13), char(10), char(10), char(10);
    
    DEFINE v_codret      char(5);
    DEFINE v_calle		 char(30);
    DEFINE v_numext	     char(10);
    DEFINE v_numint      char(10);
    DEFINE v_depto	     char(6);
    DEFINE v_colonia     char(30);
    DEFINE v_ciudad	     char(60);
    DEFINE v_estado      char(30);
    DEFINE v_obs         char(80);   
    DEFINE v_entrecalles char(40);   
    DEFINE v_cp          char(5);   
    DEFINE v_tel1   	 char(13);   
    DEFINE v_tel2   	 char(13);   
    DEFINE v_tel3   	 char(13);   
    DEFINE v_ext 	  	 char(10);
    DEFINE v_tpdir 	  	 char(1);
    DEFINE v_tipodir  	 char(10);
    DEFINE v_fechacap  	 char(10);
    DEFINE v_contador    smallint;
    DEFINE sql_err       int;
    DEFINE isam_err      int;   
    
    LET v_codret = "000";
    
    BEGIN
    
    on exception set sql_err,isam_err
        if sql_err <> 0 or isam_err <> 0 then
            let v_codret = sql_err;
            RETURN v_codret, v_calle, v_numext, v_numint, v_depto, v_colonia, v_ciudad, v_estado, 
                   v_obs, v_entrecalles, v_cp, v_tel1, v_tel2, v_tel3, v_ext, v_fechacap, v_tipodir;
        end if;
    end exception;
    
    -- ****************************************************************************
    -- Valida la informacion de entrada
    -- ****************************************************************************
    IF pcliente is null then
        LET v_codret = 110;  -- datos de entrada incompletos	   
        RETURN v_codret, v_calle, v_numext, v_numint, v_depto, v_colonia, v_ciudad, v_estado,
               v_obs, v_entrecalles, v_cp, v_tel1, v_tel2, v_tel3, v_ext, v_fechacap, v_tipodir;
    END IF;
    
    -- ****************************************************************************
    -- Inicializar variables
    -- ****************************************************************************
    let v_contador = 0;
    let v_ciudad   = " ";
    
    -- ****************************************************************************
    -- obtener registros
    -- ****************************************************************************
    FOREACH  -- direcciones completas del cliente
        select cal.nombrecalle as calle, dir.numeroextcalle, dir.numerointcalle, dir.departamento,
               zon.nombrezona as colonia, nvl(cds.nombre," ") as cd, edo.nombre as edo, dir.cod_postal, dir.observaciones, dir.entre_calles,
               tel1.telefono, tel2.telefono, tel3.telefono, tel3.extension, decode(tel1.tipo_tel,'1','Particular'), dir.fecha_insert
          into v_calle, v_numext, v_numint, v_depto, v_colonia, v_ciudad, v_estado,
               v_cp, v_obs, v_entrecalles, v_tel1, v_tel2, v_tel3, v_ext, v_tipodir, v_fechacap
          from bdinteg:si_direcciones dir
          left outer join bdinteg:si_estados edo on(edo.estado = dir.estado)
          left outer join bdinteg:si_ciudades cds on(cds.ciudad = dir.ciudad and cds.estado = dir.estado and cds.pais = 1)
          left outer join bdinteg:si_catzonas zon on (zon.numerociudad = dir.numerociudad and zon.numerocolonia = dir.numerocolonia)
          left outer join bdinteg:si_catcalles cal on(cal.numerocalle = dir.numerocalle)
          left outer join bdinteg:si_telefonos_actual tel1 on (tel1.numcte = dir.numcte and tel1.tipo_tel = 1)
          left outer join bdinteg:si_telefonos_actual tel2 on (tel2.numcte = dir.numcte and tel2.tipo_tel = 2)
          left outer join bdinteg:si_telefonos_actual tel3 on (tel3.numcte = dir.numcte and tel3.tipo_tel = 3)
         where dir.numcte = pcliente
         order by dir.secuencia
         
    LET v_contador = v_contador +1;
    
    IF v_contador < pnum_regs then
        CONTINUE FOREACH;
    END IF;    
    
    RETURN v_codret, v_calle, v_numext, v_numint, v_depto, v_colonia, v_ciudad, v_estado,
           v_cp, v_obs, v_entrecalles, v_tel1, v_tel2, v_tel3, v_ext, v_tipodir, v_fechacap WITH resume;
    
    END FOREACH		
    
    END;    
    
END PROCEDURE;

CREATE PROCEDURE "informix".consdirec_cjunk( pempresa char(3), pnumcte char(20), pnum_direc smallint )
returning char(5),int,char(1),char(40),char(60),char(40),
          char(3),char(2),char(3),char(5),char(5),char(11),char(1),
          char(13),char(1),char(13),char(1),char(13),char(5),char(2),char(3),
          char(4),smallint,char(10),char(10),char(6),int,int,char(1),
          char(1),smallint,smallint,smallint,smallint,smallint,smallint,
          smallint,char(80), char(1), char(1), char(1);

    define vcodret char(5);
    define vciclo smallint;
    define vsqlerr integer;

    define vsecuencia int ;
    define vtipo_dir char(1);
    define vcalle char(40);
    define vcolonia char(60);
    define ventre_calles char(40);
    define vpais char(3);
    define vestado char(2);
    define vciudad char(3);
    define vmunicipio char(5);
    define vcod_postal char(5);
    define vapart_postal char(11);
    define vtipo_telef1  char(1);
    define vtelefono1 char(13);
    define vtipo_telef2  char(1);
    define vtelefono2  char(13);
    define vtipo_telef3  char(1);
    define vtelefono3  char(13);
    define vextension char(5);
    define vestado_inegi  char(2);
    define vmunicipio_inegi char(3);
    define vlocalidad_inegi  char(4);
    define vnumerociudad smallint ;
    define vnumeroextcalle  char(10);
    define vnumerointcalle  char(10);
    define vdepartamento  char(6);
    define vnumerocalle int ;
    define vnumerocolonia int ;
    define vpuntocardinal  char(1);
    define vunidadhabitac  char(1);
    define vmanzana smallint ;
    define votros  smallint ;
    define vandador smallint ;
    define vetapa smallint ;
    define vlote  smallint ;
    define vedificio  smallint ;
    define ventrada  smallint ;
    define vobservaciones char(80);
    define vind_cofeteltel1 char(1);
    define vind_cofeteltel2 char(1);
    define vind_cofeteltel3 char(1);
    --modificacion 
    define vlimite_inicia int;
    define vlimite_final  int;
    define vnum_row       int;
    
    let vciclo = 0;
    let vcodret = "000";
    let  vsqlerr = 0;

    let vsecuencia = 0;
    let vtipo_dir = "";
    let vcalle = "";
    let vcolonia = "";
    let ventre_calles = "";
    let vpais = "";
    let vestado = "";
    let vciudad = "";
    let vmunicipio = "";
    let vcod_postal = "";
    let vapart_postal = "";
    let vtipo_telef1 = "";
    let vtelefono1 = "";
    let vtipo_telef2 = "";
    let vtelefono2 = "";
    let vtipo_telef3 = "";
    let vtelefono3 = "";
    let vextension = "";
    let vestado_inegi = "";
    let vmunicipio_inegi = "";
    let vlocalidad_inegi = "";
    let vnumerociudad = 0;
    let vnumeroextcalle = "";
    let vnumerointcalle = "";
    let vdepartamento = "";
    let vnumerocalle = 0;
    let vnumerocolonia = 0;
    let vpuntocardinal = "";
    let vunidadhabitac = "";
    let vmanzana = 0;
    let votros  = 0;
    let vandador  = 0;
    let vetapa = 0;
    let vlote = 0;
    let vedificio  = 0;
    let ventrada = 0;
    let vobservaciones = "";
    let vind_cofeteltel1 = "F";
    let vind_cofeteltel2 = "F";
    let vind_cofeteltel3 = "F";
    --
    let vlimite_inicia = 0;
    let vlimite_final  = 0; 
    let vnum_row       = 0;
    
    begin
    
    on exception set vsqlerr
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            return  vcodret, vsecuencia, vtipo_dir, vcalle, vcolonia, ventre_calles, vpais, vestado, vciudad,
                    vmunicipio, vcod_postal, vapart_postal, vtipo_telef1, vtelefono1, vtipo_telef2, vtelefono2,
                    vtipo_telef3, vtelefono3, vextension, vestado_inegi, vmunicipio_inegi, vlocalidad_inegi,
                    vnumerociudad, vnumeroextcalle, vnumerointcalle, vdepartamento, vnumerocalle,
                    vnumerocolonia, vpuntocardinal, vunidadhabitac, vmanzana, votros, vandador, vetapa,
                    vlote, vedificio, ventrada, vobservaciones, vind_cofeteltel1, vind_cofeteltel2, vind_cofeteltel3;
        end if;
    end exception;

    -- BLOQUE DE MODIFICACION 
    select max(secuencia) 
      into vnum_row 
      from "informix".si_direcciones 
     where numcte = pnumcte;

    IF vnum_row > 40 THEN 
        LET vlimite_inicia = vnum_row - 20;
        LET vlimite_final  = vnum_row; 
    ELSE 
        LET vlimite_inicia = 1;
        LET vlimite_final  = vnum_row;
    END IF;
    -- FIN DEL BLOQUE DE MODIFICACION 
    
    foreach
        SELECT dir.secuencia, dir.tipo_dir, dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
               tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, trim(tel2.telefono), tel3.tipo_tel, tel3.telefono, tel3.extension,
               dir.estado_inegi, dir.municipio_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle,
               dir.departamento, dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, dir.otros,
               dir.andador, dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones, dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3
          INTO vsecuencia, vtipo_dir, vcalle, vcolonia, ventre_calles, vpais,vestado, vciudad, vmunicipio, vcod_postal,
               vapart_postal, vtipo_telef1, vtelefono1, vtipo_telef2, vtelefono2, vtipo_telef3, vtelefono3, vextension,
               vestado_inegi, vmunicipio_inegi, vlocalidad_inegi, vnumerociudad, vnumeroextcalle, vnumerointcalle,
               vdepartamento, vnumerocalle, vnumerocolonia, vpuntocardinal, vunidadhabitac, vmanzana, votros, vandador,
               vetapa, vlote, vedificio, ventrada, vobservaciones, vind_cofeteltel1, vind_cofeteltel2, vind_cofeteltel3
          FROM "informix".si_direcciones dir
          LEFT OUTER JOIN si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = pnumcte
           AND dir.secuencia >= vlimite_inicia
           AND dir.secuencia <= vlimite_final
         ORDER BY dir.secuencia

        let vciclo = vciclo+1;
        
        if vciclo <= pnum_direc then
            continue foreach;
        end if

        IF LENGTH(vtelefono2) = 13 THEN
            LET vtelefono2 = SUBSTRING(vtelefono2 FROM 4 FOR 13);
        ELIF LENGTH(vtelefono2) = 12 THEN
            LET vtelefono2 = SUBSTRING(vtelefono2 FROM 3 FOR 12);
        ELIF LENGTH(vtelefono2) = 11 THEN
            LET vtelefono2 = SUBSTRING(vtelefono2 FROM 2 FOR 11);
        END IF;

        return  vcodret, vsecuencia, vtipo_dir, vcalle, vcolonia, ventre_calles, vpais, vestado, vciudad,
                vmunicipio, vcod_postal, vapart_postal, vtipo_telef1, vtelefono1, vtipo_telef2, vtelefono2,
                vtipo_telef3, vtelefono3, vextension, vestado_inegi, vmunicipio_inegi, vlocalidad_inegi,
                vnumerociudad, vnumeroextcalle, vnumerointcalle, vdepartamento, vnumerocalle,
                vnumerocolonia, vpuntocardinal, vunidadhabitac, vmanzana, votros, vandador, vetapa,
                vlote, vedificio, ventrada, vobservaciones, vind_cofeteltel1, vind_cofeteltel2, vind_cofeteltel3 with resume;
    end foreach;
    
    end
    
end procedure

DOCUMENT
"Consulta de direcciones del cliente",
"Autor : Procesamiento Interactivo S.A. de C.V.",
"MODIFICO : Daniel Zambada",
"FECHA : 30/octubre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1",
"MODIFICO : Rodolfo Tortolero Varela",
"FECHA : 12/Abril/2010",
"MODIFICACION : Se agregan los campos de cofetel";

CREATE PROCEDURE "informix".consdirec_n(pnumcte CHAR(20), pconsulta INTEGER, ptipo_dir INTEGER, pnum_direc SMALLINT)
       RETURNING CHAR(5), -- Codigo Retorno
				CHAR(20), -- numcte
				INTEGER, -- secuencia
                                CHAR(1), -- tipo_dir
                                CHAR(40), -- calle
                                CHAR(60), -- colonia
                                CHAR(40), -- entre_calles
                                CHAR(3), -- pais
                                CHAR(2), -- estado
                                CHAR(3), -- ciudad
                                CHAR(5), -- municipio
                                CHAR(5), -- cod_postal
                                CHAR(11), -- apart_postal
                                CHAR(1), -- tipo_telef1
                                CHAR(13), -- telefono1
                                CHAR(1), -- tipo_telef2
                                CHAR(13), -- telefono2
                                CHAR(1), -- tipo_telef3
                                CHAR(13), -- telefono3
                                CHAR(5), -- extension
                                CHAR(2), -- estado_inegi
                                CHAR(3), -- municipio_inegi
                                CHAR(4),-- localidad_inegi
                                SMALLINT, --numerocuidad
                                CHAR(10), -- numextcalle
                                CHAR(10), -- numintcalle
                                CHAR(6), -- departamento
                                INTEGER, -- numerocalle
                                INTEGER, -- numerocolonia
                                CHAR(1), -- puntocardinal
                                CHAR(1), -- unidadhabitac
                                SMALLINT, -- manzana
                                SMALLINT, -- otros
                                SMALLINT, -- andador
                                SMALLINT, -- etapa
                                SMALLINT, -- lote
                                SMALLINT, -- edificio
                                SMALLINT, -- entrada
                                CHAR(80), -- observaciones
                                CHAR(8), -- user_insert
                                DATE, -- fecha_insert
                                CHAR(1), -- ind_cofeteltel1
                                CHAR(1), -- ind_cofeteltel2
                                CHAR(1); -- ind_cofeteltel3

-- Define de Variables
DEFINE vcodret char(5);
DEFINE vciclo smallint;
DEFINE vsqlerr integer;

-- Define  variables de la tabla si_direcciones y si_direcciones_actual
DEFINE vnumcte CHAR(20);
DEFINE vsecuencia INTEGER;
DEFINE vtipo_dir CHAR(1);
DEFINE vcalle CHAR(40);
DEFINE vcolonia CHAR(60);
DEFINE ventre_calles CHAR(40);
DEFINE vpais CHAR(3);
DEFINE vestado CHAR(2);
DEFINE vciudad CHAR(3);
DEFINE vmunicipio CHAR(5);
DEFINE vcod_postal CHAR(5);
DEFINE vapart_postal CHAR(11);
DEFINE vtipo_telef1  CHAR(1);
DEFINE vtelefono1 CHAR(13);
DEFINE vtipo_telef2  CHAR(1);
DEFINE vtelefono2  CHAR(13);
DEFINE vtipo_telef3  CHAR(1);
DEFINE vtelefono3  CHAR(13);
DEFINE vextension CHAR(5);
DEFINE vestado_inegi  CHAR(2);
DEFINE vmunicipio_inegi CHAR(3);
DEFINE vlocalidad_inegi  CHAR(4);
DEFINE vnumerociudad SMALLINT;
DEFINE vnumeroextcalle  CHAR(10);
DEFINE vnumerointcalle  CHAR(10);
DEFINE vdepartamento  CHAR(6);
DEFINE vnumerocalle INTEGER;
DEFINE vnumerocolonia INTEGER;
DEFINE vpuntocardinal  CHAR(1);
DEFINE vunidadhabitac  CHAR(1);
DEFINE vmanzana SMALLINT;
DEFINE votros  SMALLINT;
DEFINE vandador SMALLINT;
DEFINE vetapa SMALLINT;
DEFINE vlote  SMALLINT;
DEFINE vedificio  SMALLINT;
DEFINE ventrada  SMALLINT;
DEFINE vobservaciones CHAR(80);
DEFINE vuser_insert CHAR(8);
DEFINE vfecha_insert DATE;
DEFINE vind_cofeteltel1 CHAR(1);
DEFINE vind_cofeteltel2 CHAR(1);
DEFINE vind_cofeteltel3 CHAR(1);

--Inicializa variables
LET vciclo = 0;
LET vcodret = "000";
LET  vsqlerr = 0;
-- Inicializa variables de la tabla si_direcciones y si_direcciones_actual
LET vnumcte = "";
LET vsecuencia = 0;
LET vtipo_dir = "";
LET vcalle = "";
LET vcolonia = "";
LET ventre_calles = "";
LET vpais = "";
LET vestado = "";
LET vciudad = "";
LET vmunicipio = "";
LET vcod_postal = "";
LET vapart_postal = "";
LET vtipo_telef1 = "";
LET vtelefono1 = "";
LET vtipo_telef2 = "";
LET vtelefono2 = "";
LET vtipo_telef3 = "";
LET vtelefono3 = "";
LET vextension = "";
LET vestado_inegi = "";
LET vmunicipio_inegi = "";
LET vlocalidad_inegi = "";
LET vnumerociudad = 0;
LET vnumeroextcalle = "";
LET vnumerointcalle = "";
LET vdepartamento = "";
LET vnumerocalle = 0;
LET vnumerocolonia = 0;
LET vpuntocardinal = "";
LET vunidadhabitac = "";
LET vmanzana = 0;
LET votros  = 0;
LET vandador  = 0;
LET vetapa = 0;
LET vlote = 0;
LET vedificio  = 0;
LET ventrada = 0;
LET vobservaciones = "";
LET vuser_insert = "";
LET vfecha_insert = "";
LET vind_cofeteltel1 = "";
LET vind_cofeteltel2 = "";
LET vind_cofeteltel3 = "";

    --SET DEBUG FILE TO "/respaldosbd/consdirec_n.out";
    --TRACE ON;

BEGIN
    ON EXCEPTION SET vsqlerr
      IF vsqlerr <> 0 THEN
         LET vcodret = vsqlerr;
         RETURN vcodret,vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,
                         vtipo_telef1,vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,
                         vnumerociudad,vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,
                         vmanzana,votros,vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,
                         vind_cofeteltel2,vind_cofeteltel3;
     END IF;
   END EXCEPTION;

   SET LOCK MODE TO WAIT 3;

   IF pconsulta = 1 THEN
        FOREACH
            SELECT  dir.numcte,dir.secuencia,dir.tipo_dir,dir.calle,dir.colonia,dir.entre_calles,dir.pais,dir.estado,dir.ciudad,dir.municipio,dir.cod_postal,dir.apart_postal,
                    tel1.tipo_tel,tel1.telefono,tel2.tipo_tel,tel2.telefono,tel3.tipo_tel,tel3.telefono,tel3.extension,
                    dir.estado_inegi,dir.municipio_inegi,dir.localidad_inegi,dir.numerociudad,dir.numeroextcalle,dir.numerointcalle,
                    dir.departamento,dir.numerocalle,dir.numerocolonia,dir.puntocardinal,dir.unidadhabitac,dir.manzana,dir.otros,dir.andador,dir.etapa,dir.lote,dir.edificio,
                    dir.entrada,dir.observaciones,dir.user_insert,dir.fecha_insert,dir.ind_cofeteltel1,dir.ind_cofeteltel2,dir.ind_cofeteltel3
            INTO    vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,vtipo_telef1,
                    vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad,
                    vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,vmanzana,votros,
                    vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,vind_cofeteltel2,vind_cofeteltel3
            FROM bdinteg:"informix".si_direcciones_actual dir
            LEFT OUTER JOIN si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
            LEFT OUTER JOIN si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
            LEFT OUTER JOIN si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
            WHERE dir.numcte = pnumcte
            ORDER BY dir.tipo_dir

            LET vciclo = vciclo+1;

            IF vciclo <= pnum_direc THEN
                CONTINUE FOREACH;
            END IF
	  
            RETURN vcodret,vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,
                            vtipo_telef1,vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,
                            vnumerociudad,vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,
                            vmanzana,votros,vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,
                            vind_cofeteltel2,vind_cofeteltel3  WITH RESUME;

        END FOREACH;
  END IF

  IF pconsulta = 2 THEN
        FOREACH
            SELECT dir.numcte,dir.secuencia,dir.tipo_dir,dir.calle,dir.colonia,dir.entre_calles,dir.pais,dir.estado,dir.ciudad,dir.municipio,dir.cod_postal,dir.apart_postal,
                   tel1.tipo_tel,tel1.telefono,tel2.tipo_tel,tel2.telefono,tel3.tipo_tel,tel3.telefono,tel3.extension,
                   dir.estado_inegi,dir.municipio_inegi,dir.localidad_inegi,dir.numerociudad,dir.numeroextcalle,dir.numerointcalle,dir.departamento,
                   dir.numerocalle,dir.numerocolonia,dir.puntocardinal,dir.unidadhabitac,dir.manzana,dir.otros,dir.andador,dir.etapa,dir.lote,dir.edificio,
                   dir.entrada,dir.observaciones,dir.user_insert,dir.fecha_insert,dir.ind_cofeteltel1,dir.ind_cofeteltel2,dir.ind_cofeteltel3
            INTO   vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,vtipo_telef1,
                   vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad,
                   vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,vmanzana,votros,
                   vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,vind_cofeteltel2,vind_cofeteltel3
            FROM bdinteg:"informix".si_direcciones dir
            LEFT OUTER JOIN si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
            LEFT OUTER JOIN si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
            LEFT OUTER JOIN si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
            WHERE dir.numcte = pnumcte
            ORDER BY dir.secuencia

            LET vciclo = vciclo+1;

            IF vciclo <= pnum_direc THEN
                CONTINUE FOREACH;
            END IF
	  
            RETURN vcodret,vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,
                            vtipo_telef1,vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,
                            vnumerociudad,vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,
                            vmanzana,votros,vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,
                            vind_cofeteltel2,vind_cofeteltel3  WITH RESUME;

        END FOREACH;
  END IF

  IF  pconsulta = 3 THEN
        FOREACH
            SELECT dir.numcte,dir.secuencia,dir.tipo_dir,dir.calle,dir.colonia,dir.entre_calles,dir.pais,dir.estado,dir.ciudad,dir.municipio,dir.cod_postal,dir.apart_postal,
                   tel1.tipo_tel,tel1.telefono,tel2.tipo_tel,tel2.telefono,tel3.tipo_tel,tel3.telefono,tel3.extension,
                   dir.estado_inegi,dir.municipio_inegi,dir.localidad_inegi,dir.numerociudad,dir.numeroextcalle,dir.numerointcalle,dir.departamento,
                   dir.numerocalle,dir.numerocolonia,dir.puntocardinal,dir.unidadhabitac,dir.manzana,dir.otros,dir.andador,dir.etapa,dir.lote,dir.edificio,
                   dir.entrada,dir.observaciones,dir.user_insert,dir.fecha_insert,dir.ind_cofeteltel1,dir.ind_cofeteltel2,dir.ind_cofeteltel3
            INTO   vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,vtipo_telef1,
                   vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad,
                   vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,vmanzana,votros,
                   vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,vind_cofeteltel2,vind_cofeteltel3
            FROM bdinteg:"informix".si_direcciones dir
            LEFT OUTER JOIN si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
            LEFT OUTER JOIN si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
            LEFT OUTER JOIN si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
            WHERE dir.numcte = pnumcte
            AND dir.tipo_dir = ptipo_dir
            ORDER BY dir.secuencia
            
            LET vciclo = vciclo+1;

            IF vciclo <= pnum_direc THEN
                CONTINUE FOREACH;
            END IF
	  
            RETURN vcodret,vnumcte,vsecuencia,vtipo_dir,vcalle,vcolonia,ventre_calles,vpais,vestado,vciudad,vmunicipio,vcod_postal,vapart_postal,
                            vtipo_telef1,vtelefono1,vtipo_telef2,vtelefono2,vtipo_telef3,vtelefono3,vextension,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,
                            vnumerociudad,vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia,vpuntocardinal,vunidadhabitac,
                            vmanzana,votros,vandador,vetapa,vlote,vedificio,ventrada,vobservaciones,vuser_insert,vfecha_insert,vind_cofeteltel1,
                            vind_cofeteltel2,vind_cofeteltel3  WITH RESUME;

        END FOREACH;

   END IF

END

END PROCEDURE
DOCUMENT
"Consulta de direcciones del cliente a la si_direcciones_actual y si_direcciones",
"Autor : Daniela Viridiana Ramirez Perez",
"FECHA : 13/07/2011",
"BD    : bdinteg";

CREATE PROCEDURE "informix".consultaguardaconyuge( cEmpresa CHAR(3), cNumCte CHAR(20), cNumCteConyuge CHAR(20), cUsuario CHAR(8) )
RETURNING char(5);
    
    DEFINE cCodRet char(5);
    DEFINE iSqlErr INTEGER;
    
    DEFINE sSucursal CHAR(4);
    DEFINE sApellPaterno CHAR(26);
    DEFINE sApellMaterno CHAR(26);
    DEFINE sNombre1 CHAR(26);
    DEFINE sNombre2 CHAR(26);
    DEFINE sRfc CHAR(13);
    DEFINE dFechaNac DATE;
    DEFINE sCurp CHAR(20);
    DEFINE sSexo CHAR(1);
    DEFINE sEstadoCivil CHAR(2);
    DEFINE sNacionalidad CHAR(3);
    DEFINE sNoFm CHAR(18);
    DEFINE sCodigoIden CHAR(2);
    DEFINE sPersDomicilio CHAR(2);
    DEFINE sEmail CHAR(60);
    DEFINE sParentesco CHAR(2);
    DEFINE sApellCasada CHAR(26);
    DEFINE sNumcteRef CHAR(20);
    
    DEFINE pcalle char(40);
    DEFINE pcolonia char(60);
    DEFINE pmunicipio char(5);
    DEFINE pentre_calles char(40);
    DEFINE ppais char(3);
    DEFINE pentidad char(2);
    DEFINE plocalidad char(3);
    DEFINE pcodpostal char(5);
    DEFINE ptipotel1 char(1);
    DEFINE ptelefono1 char(13);
    DEFINE ptipotel2 char(1);
    DEFINE ptelefono2 char(13);
    DEFINE ptipotel3 char(1);
    DEFINE ptelefono3 char(13);
    DEFINE pextension char(5);
    DEFINE pestado_inegi char(2);
    DEFINE pmunicipio_inegi char(3);
    DEFINE plocalidad_inegi char(4);
    DEFINE pnociudad smallint;
    DEFINE pnoext char(10);
    DEFINE pnoint char(10);
    DEFINE pdepto char(6);
    DEFINE pnocalle integer;
    DEFINE pnocolonia integer;
    DEFINE ppuntocar char(1);
    DEFINE punihabi char(1);
    DEFINE pmanz smallint;
    DEFINE ppotros smallint;
    DEFINE pandador smallint;
    DEFINE petapa smallint;
    DEFINE plote smallint;
    DEFINE pedif smallint;
    DEFINE pentrada smallint;
    DEFINE pobserva char(80);
    DEFINE iSecuencia integer;
    DEFINE pCofeteltel1 char(1);
    DEFINE pCofeteltel2 char(1);
    DEFINE pCofeteltel3 char(1);
    DEFINE pApart_postal char (11);
    DEFINE dFechaHoy DATE;
    DEFINE wBegin CHAR(1);
    
    LET cCodRet = "000";
    
    --- Set debug file to '/pisa/pisabanco/ConsultaGuardaConyuge.out';
    --- trace on;
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            ROLLBACK WORK;
            IF (wBegin = "S") THEN
                BEGIN WORK;
            END IF;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;
    
    ON EXCEPTION IN (-535)
        LET wBegin = "S";
        COMMIT WORK;
        BEGIN WORK;
    END EXCEPTION WITH RESUME;
    
    IF EXISTS( SELECT 1 
                 FROM si_refclientes a, si_refdirecciones b 
                WHERE a.empresa = cEmpresa 
                  AND a.numcte = cNumcte 
                  AND a.numcte = b.numcte 
                  AND a.secuencia = b.secuencia
                  AND a.numcte_banco = cNumCteConyuge
                  AND a.parentesco = 'E') THEN
        LET cCodRet = "001";
    ELSE
        LET wBegin = "N";
    
        begin work;
    
        update si_param 
           set valor = cast(valor as integer) + 1 
         where empresa = cEmpresa 
           and cod_param = 121;
            
        SELECT cast(valor as integer) 
          INTO iSecuencia 
          FROM bdinteg:si_param 
         where empresa = cEmpresa 
           and cod_param = 121;
    
        commit work;
    
        if wBegin = 'S' THEN
            begin work;
        end if;
        
        /* #########################
        SELECT MAX(secuencia) + 1 
          INTO iSecuencia 
          FROM si_refclientes;
        ######################### */

        SELECT fecha_hoy 
          INTO dFechaHoy 
          FROM si_fechas;

        SELECT a.sucursal, a.apell_paterno, a.apell_materno, a.nombre1, a.nombre2, a.rfc, a.string2, b.fecha_nac, 
               b.curp, b.sexo, b.estado_civil, b.nacionalidad, b.no_fm3, b.codidentifi, a.apell_casada, a.numcte_ref 
          INTO sSucursal, sApellPaterno, sApellMaterno, sNombre1, sNombre2, sRfc, sPersDomicilio, dFechaNac, 
               sCurp, sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sApellCasada, sNumcteRef
          FROM si_cliente a, 
               si_ctepf b
         WHERE a.numcte = b.numcte
           AND a.numcte = cNumCteConyuge;
           
        SELECT correo_elec
          INTO sEmail
          FROM si_correos
         WHERE numcte = cNumCteConyuge
           AND tipo_correo = 1
           AND status_correo = 'A';

        INSERT INTO si_refclientes VALUES
        ( cEmpresa, cNumCte ,sSucursal, iSecuencia, sApellPaterno, sApellMaterno, sNombre1, sNombre2,
          sRfc, dFechaNac, sCurp, sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sPersDomicilio, 
          sEmail, 'E', sApellCasada, sNumcteRef, cNumCteConyuge, cUsuario, dFechaHoy );

        SELECT dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
               tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension, 
               dir.estado_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle, dir.departamento, 
               dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, dir.otros, dir.andador,
               dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones, dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3
          INTO pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, pmunicipio, pcodpostal,  pApart_postal, 
               ptipotel1, ptelefono1, ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, 
               pestado_inegi, plocalidad_inegi, pnociudad, pnoext, 
               pnoint, pdepto, pnocalle, pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, 
               petapa, plote, pedif, pentrada, pobserva, pCofeteltel1, pCofeteltel2, pCofeteltel3
          FROM si_direcciones_actual dir
          LEFT OUTER JOIN si_telefonos_actual tel1 ON ( tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 )
          LEFT OUTER JOIN si_telefonos_actual tel2 ON ( tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 )
          LEFT OUTER JOIN si_telefonos_actual tel3 ON ( tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 )
         WHERE dir.numcte = cNumCteConyuge
           AND dir.tipo_dir = '1';

        INSERT INTO si_refdirecciones VALUES
        ( cNumCte , iSecuencia, '1', pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, pmunicipio, pcodpostal,  
          pApart_postal, ptipotel1, ptelefono1, ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, pestado_inegi,'', plocalidad_inegi, 
          pnociudad, pnoext, pnoint, pdepto, pnocalle, pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, 
          petapa, plote, pedif, pentrada, pobserva, cNumCteConyuge, cUsuario, dFechaHoy, pCofeteltel1, pCofeteltel2, pCofeteltel3 );
    END IF;
    
    RETURN cCodRet;

    END;
END PROCEDURE;

CREATE PROCEDURE "informix".consultaguardaconyuge_cjunk( cEmpresa CHAR(3),
                                                         cNumSolicitud CHAR(20),
                                                         cNumCte CHAR(20),
                                                         cNumCteConyuge CHAR(20),
                                                         cUsuario CHAR(8) )
RETURNING char(5);

    DEFINE cCodRet char(5);
    DEFINE iSqlErr INTEGER;

    DEFINE sSucursal CHAR(4);
    DEFINE sApellPaterno CHAR(26);
    DEFINE sApellMaterno CHAR(26);
    DEFINE sNombre1 CHAR(26);
    DEFINE sNombre2 CHAR(26);
    DEFINE sRfc CHAR(13);
    DEFINE dFechaNac DATE;
    DEFINE sCurp CHAR(20);
    DEFINE sSexo CHAR(1);
    DEFINE sEstadoCivil CHAR(2);
    DEFINE sNacionalidad CHAR(3);
    DEFINE sNoFm CHAR(18);
    DEFINE sCodigoIden CHAR(2);
    DEFINE sNumIdenti CHAR(30);
    DEFINE sPersDomicilio CHAR(2);
    DEFINE sEmail CHAR(60);
    DEFINE sParentesco CHAR(2);
    DEFINE sApellCasada CHAR(26);
    DEFINE sNumcteRef CHAR(20);

    DEFINE pcalle char(40);
    DEFINE pcolonia char(60);
    DEFINE pmunicipio char(5);
    DEFINE pentre_calles char(40);
    DEFINE ppais char(3);
    DEFINE pentidad char(2);
    DEFINE plocalidad char(3);
    DEFINE pcodpostal char(5);
    DEFINE ptipotel1 char(1);
    DEFINE ptelefono1 char(13);
    DEFINE ptipotel2 char(1);
    DEFINE ptelefono2 char(13);
    DEFINE ptipotel3 char(1);
    DEFINE ptelefono3 char(13);
    DEFINE pextension char(5);
    DEFINE pestado_inegi char(2);
    DEFINE pmunicipio_inegi char(3);
    DEFINE plocalidad_inegi char(4);
    DEFINE pnociudad smallint;
    DEFINE pnoext char(10);
    DEFINE pnoint char(10);
    DEFINE pdepto char(6);
    DEFINE pnocalle integer;
    DEFINE pnocolonia integer;
    DEFINE ppuntocar char(1);
    DEFINE punihabi char(1);
    DEFINE pmanz smallint;
    DEFINE ppotros smallint;
    DEFINE pandador smallint;
    DEFINE petapa smallint;
    DEFINE plote smallint;
    DEFINE pedif smallint;
    DEFINE pentrada smallint;
    DEFINE pobserva char(80);
    DEFINE iSecuencia integer;
    DEFINE pCofeteltel1 char(1);
    DEFINE pCofeteltel2 char(1);
    DEFINE pCofeteltel3 char(1);
    DEFINE pApart_postal char (11);
    DEFINE dFechaHoy DATE;
    DEFINE wBegin CHAR(1);
    
    LET cCodRet = "000";
    
    --Set debug file to '/pisa/pisabanco/ConsultaGuardaConyuge.out';
    --trace on;
    
    -----------------------------------------
    --CREADO: Rodolfo Tortolero Varela
    --FECHA: 2011-06-10
    --FUNCIONALIDAD: Guarda la información del conyuge como referencia agregandole el número de solicitud que va relacionado.
    ----------------------------------------

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 10;

    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            ROLLBACK WORK;
            IF (wBegin = "S") THEN
                BEGIN WORK;
            END IF;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    ON EXCEPTION IN (-535)
        LET wBegin = "S";
        COMMIT WORK;
        BEGIN WORK;
    END EXCEPTION WITH RESUME;

    IF EXISTS( SELECT 1 
                 FROM bdinteg:"informix".si_refclientes a, 
                      bdinteg:"informix".si_refdirecciones b
                WHERE a.empresa = cEmpresa
                  AND a.num_solicitud = cNumSolicitud
                  AND a.numcte = cNumcte
                  AND a.numcte = b.numcte
                  AND a.secuencia = b.secuencia
                  AND a.numcte_banco = cNumCteConyuge
                  AND a.parentesco = 'E') THEN
        
        LET cCodRet = "001";
        
    ELSE
        
        LET wBegin = "N";
        
        begin work;

        update bdinteg:"informix".si_param 
           set valor = cast(valor as integer) + 1 
         where empresa = cEmpresa 
           and cod_param = 121;
           
        SELECT cast(valor as integer) 
          INTO iSecuencia 
          FROM bdinteg:"informix".si_param 
         where empresa = cEmpresa 
           and cod_param = 121;

        commit work;

        if wBegin = 'S' THEN
            begin work;
        end if;

        --- SELECT MAX(secuencia) +1 INTO iSecuencia FROM si_refclientes;
        
        SELECT fecha_hoy 
          INTO dFechaHoy 
          FROM bdinteg:"informix".si_fechas;

        SELECT a.sucursal, a.apell_paterno, a.apell_materno, a.nombre1, a.nombre2, a.rfc, a.string2, b.fecha_nac, b.curp, 
               b.sexo, b.estado_civil, b.nacionalidad, b.no_fm3, b.codidentifi, b.numidentifi, a.apell_casada, a.numcte_ref 
          INTO sSucursal, sApellPaterno, sApellMaterno, sNombre1, sNombre2, sRfc, sPersDomicilio, dFechaNac, sCurp, 
               sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sNumIdenti, sApellCasada, sNumcteRef
          FROM bdinteg:"informix".si_cliente a, 
               bdinteg:"informix".si_ctepf b
         WHERE a.numcte = b.numcte
           AND a.numcte = cNumCteConyuge;
           
        SELECT correo_elec
          INTO sEmail
          FROM si_correos
         WHERE numcte = cNumCteConyuge
           AND tipo_correo = 1
           AND status_correo = 'A';

        INSERT INTO bdinteg:"informix".si_refclientes 
        ( empresa, num_solicitud, numcte, sucursal, secuencia, apell_paterno, apell_materno, 
          nombre1, nombre2, rfc, fecha_nac, curp, sexo, estado_civil, nacionalidad, no_fm3, codidentifi, numidentifi, pers_domicilio, 
          email, parentesco, apellido_cas, numcte_ref, numcte_banco, user_insert, fecha_insert )
        VALUES 
        ( cEmpresa, cNumSolicitud, cNumCte, sSucursal, iSecuencia, sApellPaterno, sApellMaterno, sNombre1, sNombre2,
          sRfc, dFechaNac, sCurp, sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sNumIdenti, sPersDomicilio, 
          sEmail, 'E', sApellCasada, sNumcteRef, cNumCteConyuge, cUsuario, dFechaHoy );

        SELECT dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
               tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension, 
               dir.estado_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle, dir.departamento, 
               dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, dir.otros, dir.andador,
               dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones, dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3
          INTO pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, pmunicipio, pcodpostal,  pApart_postal, ptipotel1, ptelefono1,
               ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, pestado_inegi, plocalidad_inegi, pnociudad, pnoext, 
               pnoint, pdepto, pnocalle, pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, 
               petapa, plote, pedif, pentrada, pobserva, pCofeteltel1, pCofeteltel2, pCofeteltel3
          FROM bdinteg:"informix".si_direcciones_actual dir
          LEFT OUTER JOIN si_telefonos_actual tel1 ON ( tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 )
          LEFT OUTER JOIN si_telefonos_actual tel2 ON ( tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 )
          LEFT OUTER JOIN si_telefonos_actual tel3 ON ( tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 )
         WHERE dir.numcte = cNumCteConyuge
        -- AND secuencia = (SELECT MAX(secuencia) FROM bdinteg:"informix".si_direcciones_actual WHERE numcte = cNumCteConyuge);
           AND dir.tipo_dir = '1';

        INSERT INTO bdinteg:"informix".si_refdirecciones
        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, 
          municipio, cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, 
          estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
          numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
          numcte_banco, user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
        VALUES	
        ( cNumCte, iSecuencia, '1', pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, 
          pmunicipio, pcodpostal, pApart_postal, ptipotel1, ptelefono1, ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, 
          pestado_inegi, '', plocalidad_inegi, pnociudad, pnoext, pnoint, pdepto, pnocalle, 
          pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, petapa, plote, pedif, pentrada, pobserva, 
          cNumCteConyuge, cUsuario, dFechaHoy, pCofeteltel1, pCofeteltel2, pCofeteltel3 );
        
    END IF;
    
    RETURN cCodRet;

    END;
    
END PROCEDURE;

create procedure "informix".sp_act_declidir()
RETURNING char(5),int,char(100);
    
    DEFINE vsCodRetorno          char(5);
    DEFINE sql_err,isam_err  int;
    DEFINE v_descripcion  char(100);
    DEFINE v_cte         char(9);
    DEFINE v_sec         char(2);
    
    LET vsCodRetorno     = "00000";
    LET isam_err="0";
    LET v_cte="";
    LET v_sec=""; 

    BEGIN
    
    on exception set sql_err,isam_err
        if sql_err <> 0 or isam_err <> 0 then
            let vsCodRetorno = sql_err;
            let v_descripcion="PROCESO NO EJECUTADO";
            RETURN vsCodRetorno,isam_err,v_descripcion;
        end if;
    end exception;

    --- SET DEBUG FILE TO "/ids10_uc9/VH/170611/act_dir.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    
    FOREACH 
        select numcte,secuencia 
          into v_cte,v_sec 
          from si_direcciones dir
         where numcte in ( select distinct trim(cliente_tit)
                             from log_fusionclientes where cliente_tit <> '' )
          and secuencia in ( select max(secuencia) 
                               from si_direcciones
                              where numcte = dir.numcte 
                                and tipo_dir = 1 )
        
        INSERT INTO bdinteg:si_direcciones_actual
        SELECT numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,  
               /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
               estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
               numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
               user_insert, fecha_insert, ind_cofeteltel1 as ind_cofeteltel1, ind_cofeteltel2 as ind_cofeteltel2, ind_cofeteltel3 as ind_cofeteltel3    
          FROM si_direcciones 
         where numcte = trim(v_cte) 
           and secuencia = trim(v_sec) 
           and tipo_dir = 1;
    END FOREACH;
    
    SET ISOLATION TO DIRTY READ;
    
    FOREACH 
        select numcte, secuencia 
          into v_cte, v_sec 
          from si_direcciones dir
         where numcte in ( select distinct trim(cliente_tit)
                             from log_fusionclientes 
                            where cliente_tit <> '' )
           and secuencia in ( select max(secuencia) 
                                from si_direcciones
                               where numcte = dir.numcte 
                                 and tipo_dir = 2 )
        
        INSERT INTO bdinteg:si_direcciones_actual
        SELECT numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,  
               /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
               estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
               numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
               user_insert, fecha_insert, ind_cofeteltel1 as ind_cofeteltel1, ind_cofeteltel2 as ind_cofeteltel2, ind_cofeteltel3 as ind_cofeteltel3    
          FROM si_direcciones 
         where numcte = trim(v_cte) 
           and secuencia = trim(v_sec) 
           and tipo_dir = 2;
    END FOREACH;
    
    SET ISOLATION TO DIRTY READ;
    
    FOREACH 
        select numcte,secuencia 
          into v_cte,v_sec 
          from si_direcciones dir
         where numcte in ( select distinct trim(cliente_tit)
                             from log_fusionclientes 
                            where cliente_tit <> '' )
           and secuencia in ( select max(secuencia) 
                                from si_direcciones
                               where numcte = dir.numcte 
                                 and tipo_dir = 3 )
        
        INSERT INTO bdinteg:si_direcciones_actual
        SELECT numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,  
               /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
               estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
               numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
               user_insert, fecha_insert, ind_cofeteltel1 as ind_cofeteltel1, ind_cofeteltel2 as ind_cofeteltel2, ind_cofeteltel3 as ind_cofeteltel3    
          FROM si_direcciones 
         where numcte = trim(v_cte) 
           and secuencia = trim(v_sec) 
           and tipo_dir = 3;
    END FOREACH;
    
    let v_descripcion = "PROCESO EJECUTADO CORRECTAMENTE";
    
    RETURN vsCodRetorno,isam_err,v_descripcion;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_activarserviciobm(pTipo CHAR(2), pEmpresa CHAR(3), pNumCte CHAR(20), pNumcel CHAR(15),
							pFolio_contrato CHAR(12), pEmail CHAR(70), pStatusAnt SMALLINT, pStatusActual SMALLINT,
							pSuc_registra CHAR(4), pReg_numemp CHAR(8), pServicio SMALLINT, pIcia_cel INTEGER)
	--DATOS A REGRESAR---
	RETURNING
	CHAR(5),  -- Codigo de Retorno
	CHAR(50); -- Mensaje

	--DEFINICION DE VARIABLES--
	DEFINE iSql_err		INTEGER;
	DEFINE cCodRet		CHAR(5);
	DEFINE cMensaje		CHAR(15);
	DEFINE cFolioBPI	CHAR(12);
	DEFINE cFolioBM		CHAR(12);
	DEFINE cTexto		CHAR(255);
	DEFINE cParam		CHAR(50);
	DEFINE iBandera     INTEGER;
	DEFINE iStatus		INTEGER;

    DEFINE v_codret1      CHAR(5);
    DEFINE v_codret2      CHAR(5);
    DEFINE v_TipoCorreo  SMALLINT;
    DEFINE v_Empresa     CHAR(3); 
    DEFINE v_TipoTel     SMALLINT;
    DEFINE v_Extension   CHAR(5); 
    DEFINE v_Canal       SMALLINT;
    DEFINE v_CiaCel      SMALLINT;

	--INICIALIZACION DE VARIABLES--
	LET iSql_err		= 0;
	LET cCodRet		= '00000';
	LET cMensaje	= '';
	LET cFolioBPI	= '';
	LET cFolioBM	= '';
	LET cTexto		= '';
	LET cParam		= '';
	LET iBandera	= 0;
	LET iStatus		= 0;

    LET v_codret1 = '00000';
    LET v_codret2 = '00000';
    LET v_TipoCorreo = 1; 
    LET v_TipoTel    = 3; 
    LET v_Extension  = ''; 
    LET v_Canal      = 3; 
    LET v_CiaCel = 1;

	-- pTipo = 11: Activación BM CON BIACTUSU
	-- pTipo = 12: Activación BM CON pl004027
	-- pTipo = 20: REENVIO SOLICITUD BM CON pl004027
	--SET DEBUG FILE TO "/home/informix/ivonne/sp_activarserviciobm.out";
	--TRACE ON;

	IF NVL(pEmpresa, '') = '' OR NVL(pNumCte, '') = '' OR NVL(pNumcel, '') = '' OR pStatusAnt IS NULL OR
	   pStatusActual IS NULL OR NVL(pSuc_registra, '') = '' OR NVL(pReg_numemp, '') = '' OR pServicio IS NULL THEN
		LET cCodRet = '00001';
		LET cMensaje = 'existen parametros nulos o en blanco';
	END IF;

	BEGIN
		ON EXCEPTION SET iSql_err
			IF iSql_err <> 0 THEN
				LET cCodRet = iSql_err;
				RETURN  cCodRet, cMensaje;
			END IF;
		END EXCEPTION;

		SET LOCK MODE TO WAIT 3;

		IF cCodRet = '00000' THEN
			IF pEmail <> '' THEN
				LET iBandera = 1;
			END IF;

			SELECT NVL(folio_contrato,'') INTO cFolioBPI
			FROM bdinteg:"informix".si_bpiusuarios
			WHERE empresa = pEmpresa AND numcte = pNumcte;
			
			--IF cFolioBPI = '' OR cFolioBPI IS NULL THEN
				--LET cFolioBPI = pFolio_contrato;
			--END IF

			SELECT  TRIM(valor) INTO cParam
			FROM bdibpi:"informix".tkn_parametros
			WHERE id_param = '50';

			SELECT TRIM(descripcion) --Se modificó para que se seleccione la descripción en vez del valor.
			INTO cTexto
			FROM bdibpi:"informix".tkn_parametros
			WHERE id_param = 42;

			LET cParam = cParam + 1;

			IF SUBSTR(pTipo,1,1) = "1" THEN
				IF (SELECT COUNT(numcte) FROM bdinteg:"informix".si_bm_usuarios WHERE numcte = pNumcte) = 0 THEN
					-- Registra activacion
					INSERT INTO bdinteg:"informix".si_bm_usuarios(empresa, numcte, numcel, folio_contrato, e_mail, id_status,
											fech_status, fech_registro, suc_registra, reg_numemp, servicio, numintacce, cia_cel)
						 VALUES(pEmpresa, pNumcte, pNumcel, cFolioBPI, pEmail, pStatusActual, CURRENT, CURRENT, pSuc_registra,
								pReg_numemp, pServicio, 0, pIcia_cel);

					-- Registra cambio status
                    --En los dos casos de activación pTipo = 11: Activación BM CON BIACTUSU y pTipo = 12: Activación BM CON pl004027
                    --se debe registrar el cambio de estatus en la tabla si_bm_camestcte
					INSERT INTO bdinteg:"informix".si_bm_camestcte(numcte, id_statant, id_statact, numcel,
									fecha_mod, suc_mod, user_mod)
						VALUES(pNumcte, pStatusAnt, pStatusActual, pNumcel, CURRENT, pSuc_registra, pReg_numemp);
				ELSE
					LET cCodRet = '00002';
					LET cMensaje = 'Ya existe un registro del cliente';
				END IF;

				IF (SELECT COUNT(numcte) FROM bdinteg:"informix".si_bm_usuarios WHERE empresa = pEmpresa AND numcte = pNumcte) <> 0 THEN

					SELECT folio_contrato
					INTO cFolioBM
					FROM bdinteg:"informix".si_bm_usuarios
					WHERE empresa = pEmpresa AND numcte = pNumcte;

					-- Registra solicitud de envio msn
					INSERT INTO bdinteg:"informix".si_bm_envsolmsn(numcte, numcel, texto, tipo, folio_contrato)
						 VALUES(pNumcte, pNumcel, cTexto, '001', cFolioBM);

					--Registra en bitácora
					--Se modificó el nombre del campo "foliosol" ya que antes tenía nombre "folio_sol" - 15/12/11
					INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper, numcel, cuenta, foliosol)
						VALUES(cParam,CURRENT,pNumcte,0,"4001",pNumcel,"",cFolioBM);

					--Actualiza datos de tkn_parametros
					UPDATE bdibpi:"informix".tkn_parametros SET valor = cParam WHERE id_param = '50';

					--Se agregó para que se actualice el numero celular y correo en la tabla bpi_usuario cuando el cliente realiza la activación
					--del servicio BM pero ya tiene (anteriormente) contratado el servicio BPI
					IF(SELECT COUNT(numcte) FROM bdinteg:"informix".si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumcte) <> 0 THEN

						--Actualiza datos de bpi_usuario
						IF iBandera = 1 THEN
							/*UPDATE bdibpi:"informix".bpi_usuario
						  	SET (tel_celular,e_mail,cia_cel) = (pNumcel,pEmail,pIcia_cel)   --DSB 12/Marzo/2012
						   	WHERE numcliente = pNumcte AND st_portal = "activo";  
							*/
							IF (pNumcel <> '') THEN
								IF (SELECT count (telefono) from bdinteg:"informix".si_telefonos_actual where numcte = pNumcte 
									and telefono = pNumcel and carrier = v_CiaCel and tipo_tel = v_TipoTel) = 0 THEN
								EXECUTE PROCEDURE bdinteg:sp_registra_telefonos(pEmpresa, pNumcte, pNumcel, v_TipoTel,v_Extension, v_CiaCel, v_Canal,pReg_numemp)
									INTO v_codret1;
								END IF;
							END IF;
							IF (pEmail <> '') THEN
								IF (SELECT count (correo_elec) from bdinteg:"informix".si_correos where numcte = pNumcte and correo_elec = pEmail and status_correo = 'A') = 0 THEN
								EXECUTE PROCEDURE bdinteg:sp_registra_correos(pEmpresa,pNumcte,pEmail,v_TipoCorreo,v_Canal,pReg_numemp)
									INTO v_codret2;
								END IF;
							END IF;	
						ELSE
							/*UPDATE bdibpi:"informix".bpi_usuario
						   	SET (tel_celular,cia_cel) = (pNumcel,pIcia_cel)    --DSB 12/Marzo/2012
						   	WHERE numcliente = pNumcte AND st_portal = "activo";
							*/
							IF (pNumcel <> '') THEN
								IF (SELECT count (telefono) from bdinteg:"informix".si_telefonos_actual where numcte = pNumcte 
									and telefono = pNumcel and carrier = v_CiaCel and tipo_tel = v_TipoTel) = 0 THEN
								EXECUTE PROCEDURE bdinteg:sp_registra_telefonos(pEmpresa, pNumcte, pNumcel, v_TipoTel,v_Extension, v_CiaCel, v_Canal,pReg_numemp)
									INTO v_codret1;
								END IF;
							END IF;	
						END IF;
					END IF;

					LET cCodRet = '00000';
					LET cMensaje = 'Exito';
				ELSE
					LET cCodRet = '00003';
					LET cMensaje = 'No existe solicitud de envio';
				END IF;

			ELIF SUBSTR(pTipo,1,1) = "2" THEN

				SELECT TRIM(descripcion) --Se modificó para que se seleccione la descripción en vez del valor.
				INTO cTexto
				FROM bdibpi:"informix".tkn_parametros
				WHERE id_param = 43;

				SELECT folio_contrato
				INTO cFolioBM
				FROM bdinteg:"informix".si_bm_usuarios
				WHERE empresa = pEmpresa AND numcte = pNumcte;

				--Actualiza activación
				IF iBandera = 1 THEN
					UPDATE bdinteg:"informix".si_bm_usuarios SET (numcel,e_mail,cia_cel) = (pNumcel,pEmail,pIcia_cel) WHERE numcte = pNumcte;
				ELSE
					UPDATE bdinteg:"informix".si_bm_usuarios SET (numcel,cia_cel) = (pNumcel,pIcia_cel) WHERE numcte = pNumcte;
				END IF;

                --Se agregó porque existirá un proceso batch que barrerá la tabla si_bm_envsolmsn y cuando se envien los mensajes a los clientes
                --con envíos registrados en esta tabla se borrará el registro, entonces cuando se realice un reenvío sino se encuentra un registro
                --del cliente en la tabla se deberá de insertar.
				IF(SELECT COUNT(numcte) FROM bdinteg:"informix".si_bm_envsolmsn WHERE numcte = pNumcte) <> 0 THEN
					-- Registra solicitud de envio msn
					UPDATE bdinteg:"informix".si_bm_envsolmsn
					SET (numcte, numcel, texto, tipo, folio_contrato) = (pNumcte, pNumcel, cTexto, '002', cFolioBM)
					WHERE numcte = pNumcte;
				ELSE
					-- Registra solicitud de envio msn
					INSERT INTO bdinteg:"informix".si_bm_envsolmsn(numcte, numcel, texto, tipo, folio_contrato)
						 VALUES(pNumcte, pNumcel, cTexto, '002', cFolioBM);
				END IF;

				--IF EXISTS (SELECT 1 FROM bdibpi:"informix".bpi_usuario WHERE numcliente = pNumcte AND st_portal = "activo") THEN
					--Actualiza datos de bpi_usuario
					IF iBandera = 1 THEN
						/*UPDATE bdibpi:"informix".bpi_usuario
						   SET (tel_celular,e_mail,cia_cel) = (pNumcel,pEmail,pIcia_cel)  --DSB 12/Marzo/2012
						   WHERE numcliente = pNumcte AND st_portal = "activo";
						   */
						IF (pNumcel <> '') THEN
							IF (SELECT count (telefono) from bdinteg:"informix".si_telefonos_actual where numcte = pNumcte 
								and telefono = pNumcel and carrier = v_CiaCel and tipo_tel = v_TipoTel) = 0 THEN
							EXECUTE PROCEDURE bdinteg:sp_registra_telefonos(pEmpresa, pNumcte, pNumcel, v_TipoTel,v_Extension, v_CiaCel, v_Canal,pReg_numemp)
								INTO v_codret1;
							END IF;
						END IF;
						IF (pEmail <> '') THEN
							IF (SELECT count (correo_elec) from bdinteg:"informix".si_correos where numcte = pNumcte and correo_elec = pEmail and status_correo = 'A') = 0 THEN
							EXECUTE PROCEDURE bdinteg:sp_registra_correos(pEmpresa,pNumcte,pEmail,v_TipoCorreo,v_Canal,pReg_numemp)
								INTO v_codret2;
							END IF;
						END IF;	  
					ELSE
						/*UPDATE bdibpi:"informix".bpi_usuario
						   SET (tel_celular,cia_cel) = (pNumcel,pIcia_cel)      --DSB 12/Marzo/2012
						   WHERE numcliente = pNumcte AND st_portal = "activo";
						   */
						IF (pNumcel <> '') THEN
							IF (SELECT count (telefono) from bdinteg:"informix".si_telefonos_actual where numcte = pNumcte 
								and telefono = pNumcel and carrier = v_CiaCel and tipo_tel = v_TipoTel) = 0 THEN
							EXECUTE PROCEDURE bdinteg:sp_registra_telefonos(pEmpresa, pNumcte, pNumcel, v_TipoTel,v_Extension, v_CiaCel, v_Canal,pReg_numemp)
								INTO v_codret1;
							END IF;
						END IF;  
					END IF;
				--END IF;

				--Registra en bitácora
				INSERT INTO bdinteg:"informix".si_bm_bitacora(id_session, fech_oper, numcte, secuencia, id_oper,
							numcel, cuenta, foliosol)
					VALUES(cParam,CURRENT,pNumcte,0,"4002",pNumcel,"",cFolioBM);

				--Actualiza datos de tkn_parametros
				UPDATE bdibpi:"informix".tkn_parametros SET valor = cParam WHERE id_param = '50';

				--Actualización tabla si_bm_usuario idstatus de 20 a 10 y de 30 a 15.
				IF (SELECT COUNT (numcte) FROM bdinteg:"informix".si_bm_usuarios WHERE numcte = pNumcte) <> 0 THEN

					SELECT id_status
					INTO iStatus
					FROM bdinteg:"informix".si_bm_usuarios
					WHERE empresa = pEmpresa AND numcte = pNumcte;

					IF iStatus = 20 THEN
						UPDATE bdinteg:"informix".si_bm_usuarios SET id_status = 10 WHERE numcte = pNumcte;
                        			INSERT INTO bdinteg:"informix".si_bm_camestcte VALUES (pNumcte,'20','10',pNumcel,CURRENT,pSuc_registra, pReg_numemp);
					ELIF iStatus = 30 THEN
						UPDATE bdinteg:"informix".si_bm_usuarios SET id_status = 15 WHERE numcte = pNumcte;
						INSERT INTO bdinteg:"informix".si_bm_camestcte VALUES (pNumcte,'30','15',pNumcel,CURRENT,pSuc_registra, pReg_numemp);
					END IF;
				END IF;

				LET cCodRet = '00000';
				LET cMensaje = 'Exito';

			END IF;
		END IF;

        --inserta registro de teléfono
        /*IF (pNumcel <> '') THEN
            EXECUTE PROCEDURE bdinteg:sp_registra_telefonos(pEmpresa, pNumcte, pNumcel, v_TipoTel,
                                                     v_Extension, v_CiaCel, v_Canal,pReg_numemp)
                             INTO v_codret1;
        END IF;
        IF (pEmail <> '') THEN
            EXECUTE PROCEDURE bdinteg:sp_registra_correos(pEmpresa,pNumcte,pEmail,v_TipoCorreo,v_Canal,pReg_numemp)
                            INTO v_codret2;
        END IF;
		*/

		RETURN  cCodRet, cMensaje;
	END
END PROCEDURE

DOCUMENT
'Activa el servicio BM',
'Autor :Daniela Ramírez',
'FECHA : 12/Septiembre/2011',
'BD: bdinteg',
'Se modifica por petición en RQM03104 donde se realiza una actualización',
'a la tabla si_bm_usuario idstatus de 20 a 10 y de 30 a 15 cuando se solicita',
'un cambio de Equipo/No. Celular',
'Autor :Daniela Ramírez',
'FECHA : 27/Diciembre/2011',
'BD: bdinteg',
'Autor: Jose Angel Gaxiola Gaxiola',
'Modificación: Se agrega parametro pIcia_cel para que inserte en la tabla si_bm_usuarios el codigo correspondiente a la compania celular ',
'Fecha de modificación: 23/Febrero/2012',
'BD: bdinteg',
'Autor: Josue Zepeda',
'Modificación: Se agrega al update parametro pIcia_cel para que actualice en la tabla si_bm_usuarios y bpi_usuario el codigo correspondiente a la compania celular',
'Fecha de modificación: 12/Marzo/2012';

create procedure "informix".sp_actualiza_calle( pNumeroCte char(20), pNumeroCalle integer )
returning char(20);

    --- V3 20100311 
    --- V2 20100125 Agregar log de error y conclusión a tabla
    --- V1 20100113 Crear SP
    
    define cod_ret char(20);
    define sql_err integer;
    define v_numcte char(20);
    define v_numerocalle integer;
    define v_numerociudad smallint;
    define v_max_secuencia integer;
    define v_secuencia_r integer;
    define v_tipo_dir_r char(1);
    define v_calle_r char(40);
    define v_colonia_r char(60);
    define v_entre_calles_r char(40);
    define v_pais_r char(3);
    define v_estado_r char(2);
    define v_ciudad_r char(3);
    define v_municipio_r char(5);
    define v_cod_postal_r char(5);
    define v_apart_postal_r char(11);
    define v_tipo_telef1_r char(1);
    define v_telefono1_r char(13);
    define v_tipo_telef2_r char(1);
    define v_telefono2_r  char(13);
    define v_tipo_telef3_r char(1);
    define v_telefono3_r char(13);
    define v_extension_r char(5);
    define v_estado_inegi_r char(2);
    define v_municipio_inegi_r char(3);
    define v_localidad_inegi_r char(4);
    define v_numerociudad_r smallint;
    define v_numeroextcalle_r char(10);
    define v_numerointcalle_r char(10);
    define v_departamento_r char(6);
    define v_numerocalle_r integer;
    define v_numerocolonia_r integer;
    define v_puntocardinal_r char(1);
    define v_unidadhabitac_r  char(1);
    define v_manzana_r smallint;
    define v_otros_r smallint;
    define v_andador_r smallint;
    define v_etapa_r smallint;
    define v_lote_r smallint;
    define v_edificio_r smallint;
    define v_entrada_r smallint;
    define v_observaciones_r char(80);
    define v_user_insert_r char(8);
    define v_fecha_insert_r date;
    define v_strlog char(100);
    define v_user_insert char(8);
    define v_pais char(3);
    define v_msj char(50);
    
    --- SET DEBUG FILE TO "/ids10_uc9/actualiza_calle.out";
    --- TRACE ON;
    
    let cod_ret = "00000";
    let v_numcte = "";
    let v_numerocalle = 0;
    let v_numerociudad = 0;
    let v_max_secuencia = 0;
    let v_strlog = "";
    let v_pais= '001';
    let v_secuencia_r = 0;

    BEGIN

    on exception set sql_err
        if sql_err <> 0 then
            LET cod_ret = sql_err;
            SYSTEM 'echo ---- Error en numcte -------- ' || v_numcte || '>> ' || 'actualiza_calle.log';
            LET v_msj = 'Error en numcte: ' || v_numcte;
            
            insert into bdinteg:si_bitacora_dom (proceso,cod_ret,mensaje,reg_insert,user_insert,fecha_insert,hora_insert) 
            values('sp_actualiza_calle.sql',cod_ret,v_msj,0,'XASIGN02',today,(SELECT DBINFO('utc_to_datetime',sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
            
            return cod_ret;
        end if
    end exception;
    
    set isolation to dirty read;
    set lock mode to wait 3;

    SYSTEM 'echo ---- Inicia proceso --------- ' || '> ' || 'actualiza_calle.log';
    
    if pNumeroCte = '000000000' then
        foreach
            select {+INDEX(bdinteg:si_por_asignar idx_numcd_numcol)} numcte, numerocalle
              into v_numcte, v_numerocalle
              from bdinteg:si_por_asignar

            --// Obtener secuencia máxima.
            select {+INDEX(bdinteg:si_direcciones_actual idx_diract_cte)} 
                   MAX(secuencia)
              into v_secuencia_r  
              from bdinteg:si_direcciones_actual
             where numcte = v_numcte;

            if v_secuencia_r is null or v_secuencia_r = 0 then
                SYSTEM 'echo Cliente no encontrado en si_direcciones : ' || v_numcte || '>> ' || 'actualiza_calle.log';
                LET v_msj = 'Error en numcte: ' || v_numcte;
                
                insert into bdinteg:si_bitacora_dom (proceso,cod_ret,mensaje,reg_insert,user_insert,fecha_insert,hora_insert) 
                values('sp_actualiza_calle.sql',cod_ret,v_msj,0,'XASIGN02',today,(SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
                
                CONTINUE FOREACH;
            end if

            -- // Selecc para cada cliente el registro que tiene la maxima secuencia dónde la dirección sea la de casa (tipo_dir = 1)
            select {+INDEX(bdinteg:si_direcciones_actual idx_diract_ctetpo)} 
                   d.tipo_dir, d.calle, d.colonia, d.entre_calles, d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, 
                   /* d.tipo_telef1, d.telefono1, d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, d.extension, */
                   d.estado_inegi, d.municipio_inegi, d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, d.departamento, 
                   d.numerocalle, d.numerocolonia, d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, d.etapa, d.lote,
                   d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert
              into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
                   /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
                   v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, 
                   v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r, v_lote_r, 
                   v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, v_fecha_insert_r
              from bdinteg:si_direcciones_actual d
             where d.numcte = v_numcte
               and d.tipo_dir = '1';

            -- // El registro obtenido guardarlo nuevamente con la secuencia + 1
            let v_max_secuencia = v_secuencia_r + 1;

            insert into bdinteg:si_direcciones
            ( numcte,secuencia,tipo_dir,calle,colonia,entre_calles,pais,estado,ciudad,municipio,cod_postal, apart_postal,
              /* tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,telefono3,extension, */
              estado_inegi,municipio_inegi,localidad_inegi,numerociudad,numeroextcalle,numerointcalle,departamento,numerocalle,numerocolonia,
              puntocardinal,unidadhabitac,manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,user_insert,fecha_insert )
            values  
            ( v_numcte,v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
              /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r,v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
              v_estado_inegi_r, v_municipio_inegi_r,v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, v_numerocalle, v_numerocolonia_r, 
              v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r,v_lote_r,v_edificio_r, v_entrada_r, v_observaciones_r, 'XASIGN02', today );
        end foreach;
    else
        -- // Obtener secuencia máxima.
        select max(secuencia) 
          into v_secuencia_r  
          from bdinteg:si_direcciones_actual
         where numcte = pNumeroCte;

        if v_secuencia_r is null or v_secuencia_r = 0 then
            SYSTEM 'echo Cliente no encontrado en si_direcciones : ' || v_numcte || '>> ' || 'actualiza_calle.log';
            LET v_msj = 'Error en numcte: ' || v_numcte;
            
            insert into bdinteg:si_bitacora_dom (proceso,cod_ret,mensaje,reg_insert,user_insert,fecha_insert,hora_insert) 
            values('sp_actualiza_calle.sql',cod_ret,v_msj,0,'XASIGN02',today,(SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));
        else
            select {+INDEX(bdinteg:si_direcciones_actual idx_diract_ctetpo)} 
                   d.tipo_dir, d.calle, d.colonia, d.entre_calles, d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, 
                   /* d.tipo_telef1, d.telefono1, d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, d.extension, */
                   d.estado_inegi, d.municipio_inegi, d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, d.departamento, 
                   d.numerocalle, d.numerocolonia, d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, d.etapa, d.lote,
                   d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert
              into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
                   v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, 
                   v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, 
                   v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r, v_lote_r, 
                   v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, v_fecha_insert_r
              from bdinteg:si_direcciones_actual d
             where d.numcte = pNumeroCte
               and d.tipo_dir = '1';

            let v_max_secuencia = v_secuencia_r + 1;

            insert into bdinteg:si_direcciones
            ( numcte,secuencia,tipo_dir,calle,colonia,entre_calles,pais,estado,ciudad,municipio,cod_postal,apart_postal,
              /* tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,telefono3,extension, */
              estado_inegi,municipio_inegi,localidad_inegi,numerociudad,numeroextcalle,numerointcalle,departamento,numerocalle,numerocolonia,
              puntocardinal,unidadhabitac,manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,user_insert,fecha_insert )
            values  
            ( pNumeroCte,v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
              /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r,v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
              v_estado_inegi_r, v_municipio_inegi_r,v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, pNumeroCalle,v_numerocolonia_r, 
              v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r,v_lote_r,v_edificio_r, v_entrada_r, v_observaciones_r, 'XASIGN02', today );
        end if
    end if

    end
    
    LET cod_ret = "Termina proceso";
    
    insert into bdinteg:si_bitacora_dom (proceso, cod_ret, mensaje, reg_insert, user_insert, fecha_insert, hora_insert) 
    values('sp_actualiza_calle.sql','00000',cod_ret,0,'XASIGN02',today,(SELECT DBINFO('utc_to_datetime', sh_curtime)::DATETIME HOUR TO SECOND from sysmaster:sysshmvals));

    SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'actualiza_calle.log';
    
    return cod_ret;
    
end procedure;

create procedure "informix".sp_actualiza_cp_buro()
returning char(30);

    -- V7 Modif select del reg a insertar que sea tipo_dir 1
    -- V6 Validar en caso de que numerociudad sea 0
    -- V2 20120525 Crear SP
    
    -- Define variables
    define cod_ret char(30);
    define sql_err integer;
    define v_numcte char(9);
    define v_numcalle integer;
    define v_numcolonia integer;
    define v_numerociudad integer;
    define v_estado char(5);
    define v_clave_estado char(2);
    define v_nombrecalle char(30);
    define v_conteocolonias smallint;
    define v_codpostal char(5);
    define v_ciudad char(4);
    define v_max_secuencia integer;
    define v_secuencia_r integer;
    define v_tipo_dir_r char(1);
    define v_calle_r char(40);
    define v_colonia_r char(60);
    define v_entre_calles_r char(40);
    define v_pais_r char(3);
    define v_estado_r char(2);
    define v_ciudad_r char(3);
    define v_municipio_r char(5);
    define v_cod_postal_r char(5);
    define v_apart_postal_r char(11);
    define v_tipo_telef1_r char(1);
    define v_telefono1_r char(13);
    define v_tipo_telef2_r char(1);
    define v_telefono2_r  char(13);
    define v_tipo_telef3_r char(1);
    define v_telefono3_r char(13);
    define v_extension_r char(5);
    define v_estado_inegi_r char(2);
    define v_municipio_inegi_r char(3);
    define v_localidad_inegi_r char(4);
    define v_numerociudad_r smallint;
    define v_numeroextcalle_r char(10);
    define v_numerointcalle_r char(10);
    define v_departamento_r char(6);
    define v_numerocalle_r integer;
    define v_numerocolonia_r integer;
    define v_puntocardinal_r char(1);
    define v_unidadhabitac_r  char(1);
    define v_manzana_r smallint;
    define v_otros_r smallint;
    define v_andador_r smallint;
    define v_etapa_r smallint;
    define v_lote_r smallint;
    define v_edificio_r smallint;
    define v_entrada_r smallint;
    define v_observaciones_r char(80);
    define v_user_insert_r char(8);
    define v_fecha_insert_r date;
    define v_strlog char(100);
    define v_user_insert char(8);
    define v_pais char(3);
    define pOrigen char(8);

    --- SET DEBUG FILE TO "/ids10_uc9/actualiza_domicilio.out";
    --- TRACE ON;
    
    -- Inicializa variables
    let cod_ret       = "000";
    let v_numcte      = "";
    let v_numcalle    = 0;
    let v_numcolonia  = 0;
    let v_numerociudad = 0;
    let v_estado = "";
    let v_clave_estado = "";
    let v_codpostal = "";
    let v_ciudad = "";
    let v_max_secuencia = 0;
    let v_nombrecalle = "";
    let v_conteocolonias = 0;
    let v_strlog = "";
    let v_user_insert = "";
    let v_pais= '001';
    let pOrigen ='1';	
    
    BEGIN

    on exception set sql_err
        SYSTEM 'echo ----eRROR-----' || v_numcte || 'actualiza_domicilio.log';
        if sql_err <> 0 then	  
            let cod_ret = sql_err;
            return cod_ret;
        end if
    end exception;

    --- SYSTEM 'echo ---- DATOS INCOMPLETOS DE CLIENTES ----- ' || v_numcte || '> ' || 'actualiza_domicilio.log';
    --- V4
    
    set lock mode to wait 3;

    foreach with hold
        select numcte, numerocalle, numerocolonia, numerociudad, estado, cod_postal ---Obtener cliente por cliente --numcte, cod_postal ---Obtener cliente por cliente	   
        --- into v_numcte, v_codpostal
          into v_numcte, v_numcalle, v_numcolonia, v_numerociudad, v_estado, v_codpostal	   
          from bdinteg:si_por_asignar
         where actualizacion_previa = 'N'
        
        --- SYSTEM 'echo Registro de , numcte: ' || v_numcte || '>> ' || 'actualiza_domicilio.log';
        
        -- Obtener secuencia máxima.
        select max(secuencia) 
          into v_secuencia_r
          from bdinteg:si_direcciones
         where numcte = v_numcte;
        --- and tipo_dir = '1';
        
        -- Selecc para cada cliente el registro que tiene la maxima secuencia
        select first 1 d.tipo_dir, d.calle, d.colonia, d.entre_calles, d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, 
               /* d.tipo_telef1, d.telefono1, d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, d.extension, */
               d.estado_inegi, d.municipio_inegi, d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, d.departamento, d.numerocalle, d.numerocolonia, 
               d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, d.etapa, d.lote, d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert
          into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
               /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
               v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, 
               v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, 
               v_andador_r, v_etapa_r, v_lote_r, v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, v_fecha_insert_r
          from bdinteg:si_direcciones_actual d
         where d.numcte =  v_numcte
           and d.tipo_dir = '1';

        if v_tipo_dir_r is null or v_secuencia_r is null then --  No existe el cliente
            let cod_ret = "Reg. de si_direcciones_actual incompleto";
            SYSTEM 'echo Registro de cliente en si_direcciones_actual esta incompleto, numcte: ' || v_numcte || '>> ' || 'actualiza_domicilio.log';
            -- return cod_ret;
            CONTINUE FOREACH;
        end if 

        -- El registro obtenido guardarlo nuevamente con la secuencia + 1
        let v_max_secuencia = v_secuencia_r + 1;
        let v_tipo_dir_r = '1';
        
        begin work;
        
        insert into bdinteg:si_direcciones
        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais,
          estado, ciudad, municipio, cod_postal, apart_postal,
          /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
          estado_inegi, municipio_inegi, localidad_inegi, numerociudad,
          numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia,
          puntocardinal, unidadhabitac, manzana, otros, andador, etapa,
          lote, edificio, entrada, observaciones, user_insert, fecha_insert )
        values  
        ( v_numcte,v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, 
          v_estado /* v_estado_r */, v_ciudad_r, v_municipio_r, v_codpostal /* v_cod_postal_r */, v_apart_postal_r, 
          /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r,v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
          v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad /* v_numerociudad_r */, 
          v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, /* v_numerocalle_r, v_numerocolonia_r */
          v_numcalle, v_numcolonia, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, v_etapa_r,
          v_lote_r, v_edificio_r, v_entrada_r, v_observaciones_r, /* v_user_insert_r */ pOrigen, today /* v_fecha_insert_r */ );

        update bdinteg:si_por_asignar
           set actualizacion_previa = 'S'
         where numcte = v_numcte;
         
        commit work;		
        -- Actualizar
    end foreach;

    end
    
    let cod_ret = "Termina proceso";
    
    SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'actualiza_domicilio.log';
    
    return cod_ret;
    
end procedure;

create procedure "informix".sp_actualiza_domicilio_cac(pNumerocd smallint, pNumerocol smallint, pNuevacd smallint, pNuevacol smallint )
returning char(20);

    ---V5 20100127 Agregar directiva en select a bdinteg:si_direcciones 
    ---V4 20091124 Modificar
    ---V1 20091022 Crear SP
    define cod_ret char(20);
    define sql_err integer;
    define v_numcte char(9);
    define v_numerociudad smallint;
    define v_max_secuencia integer;
    define v_secuencia_r integer;
    define v_tipo_dir_r char(1);
    define v_calle_r char(40);
    define v_colonia_r char(60);
    define v_entre_calles_r char(40);
    define v_pais_r char(3);
    define v_estado_r char(2);
    define v_ciudad_r char(3);
    define v_municipio_r char(5);
    define v_cod_postal_r char(5);
    define v_apart_postal_r char(11);
    define v_tipo_telef1_r char(1);
    define v_telefono1_r char(13);
    define v_tipo_telef2_r char(1);
    define v_telefono2_r  char(13);
    define v_tipo_telef3_r char(1);
    define v_telefono3_r char(13);
    define v_extension_r char(5);
    define v_estado_inegi_r char(2);
    define v_municipio_inegi_r char(3);
    define v_localidad_inegi_r char(4);
    define v_numerociudad_r smallint;
    define v_numeroextcalle_r char(10);
    define v_numerointcalle_r char(10);
    define v_departamento_r char(6);
    define v_numerocalle_r integer;
    define v_numerocolonia_r integer;
    define v_puntocardinal_r char(1);
    define v_unidadhabitac_r  char(1);
    define v_manzana_r smallint;
    define v_otros_r smallint;
    define v_andador_r smallint;
    define v_etapa_r smallint;
    define v_lote_r smallint;
    define v_edificio_r smallint;
    define v_entrada_r smallint;
    define v_observaciones_r char(80);
    define v_user_insert_r char(8);
    define v_fecha_insert_r date;
    define v_strlog char(100);
    define v_user_insert char(8);
    define v_pais char(3);

    --- SET DEBUG FILE TO "/ids10_uc9/actualiza_domicilio_cac.out";
    --- TRACE ON;

    let cod_ret       = "000";
    let v_numcte      = "";
    let v_numerociudad = 0;
    let v_max_secuencia = 0;
    let v_strlog = "";
    let v_pais= '001';

    BEGIN

    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret;
        end if
    end exception;

    SYSTEM 'echo ---- Inicia proceso --------- ' || '>> ' || 'actualiza_domicilio_cac.log';

    foreach
        /* ##########################################################################################
        select {+ INDEX (bdinteg:si_direcciones idx_numcolonia)} d.numcte into v_numcte
        from bdinteg:si_direcciones d
        where d.numerocolonia = pNumerocol
        and d.numerociudad = pNumerocd
        and d.tipo_dir = '1'
        and d.secuencia = ( select {+ INDEX (bdinteg:si_direcciones idx_numcte)} max(e.secuencia)
        from bdinteg:si_direcciones e
        where d.numcte = e.numcte
        and e.tipo_dir = '1')
        ########################################################################################## */
        SELECT d.numcte 
          INTO v_numcte
          from bdinteg:si_direcciones_actual d
         where d.numerocolonia = pNumerocol
           and d.numerociudad = pNumerocd
           and d.tipo_dir = '1'

        if v_numcte is null then
            SYSTEM 'echo Cliente no encontrado en si_direcciones ' || '>> ' || 'actualiza_domicilio_cac.log';
            CONTINUE FOREACH;
        end if

        -- Obtener secuencia máxima.
        select {+ INDEX (bdinteg:si_direcciones_actual idx_diract_cte /*idx_numcte*/)} 
               max(secuencia) 
          into v_secuencia_r
          from bdinteg:si_direcciones_actual
         where numcte = v_numcte;

        -- Selecc para cada cliente el registro que tiene la maxima secuencia
        select {+ INDEX (bdinteg:si_direcciones_actual idx_diract_ctetpo /*idx_numcte*/)} 
               d.tipo_dir, d.calle, d.colonia, d.entre_calles, d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, 
               /* d.tipo_telef1, d.telefono1, d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, d.extension, */
               d.estado_inegi, d.municipio_inegi, d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, 
               d.departamento, d.numerocalle, d.numerocolonia, d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, 
               d.etapa, d.lote, d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert
          into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
               /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
               v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, 
               v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, 
               v_etapa_r, v_lote_r, v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, v_fecha_insert_r
          from  bdinteg:si_direcciones_actual d
         where d.numcte =  v_numcte
           and d.tipo_dir = '1';
        /* ###########################################################################
           and d.secuencia = (select {+ INDEX (bdinteg:si_direcciones idx_numcte)} 
                                     max(f.secuencia)
                                from bdinteg:si_direcciones f		
                               where d.numcte = f.numcte
                                 and f.tipo_dir = '1');
        ########################################################################### */

        -- El registro obtenido guardarlo nuevamente con la secuencia + 1
        let v_max_secuencia = v_secuencia_r + 1;
        -- let v_tipo_dir_r = '1';

        insert into bdinteg:si_direcciones
        ( numcte,secuencia,tipo_dir,calle,colonia,entre_calles,pais,estado,ciudad,municipio,cod_postal, apart_postal,
          /* tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,telefono3,extension, */
          estado_inegi,municipio_inegi,localidad_inegi,numerociudad,numeroextcalle,numerointcalle,departamento,numerocalle,numerocolonia,
          puntocardinal,unidadhabitac,manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,user_insert,fecha_insert )
        values  
        ( v_numcte,v_max_secuencia, v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
          /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r,v_telefono2_r,v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
          v_estado_inegi_r, v_municipio_inegi_r,v_localidad_inegi_r, pNuevacd /*v_numerociudad_r*/, v_numeroextcalle_r, v_numerointcalle_r, 
          v_departamento_r, v_numerocalle_r,pNuevacol /*v_numerocolonia_r*/, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, 
          v_andador_r, v_etapa_r,v_lote_r,v_edificio_r, v_entrada_r, v_observaciones_r, 'SOLI_CAC' /*v_user_insert_r*/, v_fecha_insert_r );

        -- Actualizar
        -- EL ACTUALIZAR SE ELIMINA YA QUE SE AGREGAN LOS VALORES QUE SE ACTUALIZAN AL INSERT
        /* #####################################
        update bdinteg:si_direcciones    
           set numerociudad = pNuevacd,
               numerocolonia = pNuevacol,
               user_insert = 'SOLI_CAC'
         where numcte = v_numcte 
           and secuencia = v_max_secuencia;
        ##################################### */
    end foreach;

    end
    
    let cod_ret = "Termina proceso";
    
    SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'actualiza_domicilio_cac.log';
    
    return cod_ret;
    
end procedure;

