CREATE PROCEDURE "informix".sp_validapass_bei(pEmpresa CHAR(3), pNumCte CHAR(20))
RETURNING CHAR(5),CHAR(50),CHAR(50), CHAR(50),CHAR(50), CHAR(50), CHAR(26), CHAR(13), CHAR(13), DATE, DATE ;
    
    DEFINE cCod_ret CHAR(5);
    DEFINE sql_err INTEGER;
    DEFINE cUsuario, cPass, cPass1, cPass2, cPass3 CHAR(50);
    DEFINE cNombre CHAR(26);
    DEFINE cTelefono1, cTelefono2 CHAR(13);
    DEFINE dFecha_constitucion, dFecha_actual DATE;
    
    LET cCod_ret       = "000";
    LET cUsuario = "";
    LET cPass = "";
    LET cPass1 = "";
    LET cPass2 = "";
    LET cPass3 = "";
    LET cNombre = "";
    LET cTelefono1 = "";
    LET cTelefono2 = "";
    LET  dFecha_constitucion = '01-01-1900';
    LET  dFecha_actual = CURRENT ;
    
    --Realizó: Manuel Ramos Figueroa
    --Fecha: 05/08/2011
    --Actividad: Obtiene informacion del cliente de BEI
    
    BEGIN
    
    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET cCod_ret = sql_err;
            RETURN cCod_ret, cUsuario, cPass, cPass1, cPass2, cPass3, cNombre, cTelefono1, cTelefono2,  dFecha_constitucion, dFecha_actual;
        END IF
    END EXCEPTION;
    
    SET LOCK MODE TO WAIT ;
    SET ISOLATION DIRTY READ ;
    
    IF EXISTS ( SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm  WHERE empresa = pEmpresa AND num_cliente = pNumCte ) THEN
        SELECT LIMIT 1 usuario, pass, pass1, pass2, pass3 
          INTO cUsuario, cPass, cPass1, cPass2, cPass3 
          FROM bdinteg:"informix".si_bpiusuariospm 
         WHERE empresa = pEmpresa 
           AND num_cliente = pNumCte;
        
        SELECT LIMIT 1 nombre_corto, fecha_constitct 
          INTO cNombre, dFecha_constitucion 
          FROM bdinteg:"informix".si_ctepm
         WHERE empresa = pEmpresa
           AND numcte =  pNumCte;
        /*
        SELECT LIMIT 1 telefono1, telefono2 
          INTO cTelefono1, cTelefono2 
          FROM bdinteg:"informix".si_direcciones_actual 
         WHERE numcte = pNumCte;
        */
        
        SELECT telefono
          INTO cTelefono1
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        SELECT telefono
          INTO cTelefono2
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
    ELSE
        LET cCod_ret = '001';
    END IF;
    
    RETURN cCod_ret, NVL(cUsuario,''),NVL(cPass,''), NVL(cPass1,''), NVL(cPass2,''), NVL(cPass3,''), 
           cNombre, NVL(cTelefono1,''), NVL(cTelefono2,''),  dFecha_constitucion, dFecha_actual;
    
    END
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validapass_bpi(pEmpresa char(3), pNumCte char(20))
returning char(5),char(50),char(50), char(50),char(50), char(50), char(26),char(26),char(26),char(26), char(13), char(13), char(13), date, date;
    
    -- ***************************************************************************
    -- Define variables
    -- ***************************************************************************
    define cod_ret char(5);
    define sql_err integer;
    define v_usuario, v_pass, v_pass1, v_pass2, v_pass3 char(50);
    define v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno char(26);
    define v_rfc, v_telefono1, v_telefono2 char(13);
    define v_fecha_nac, v_fecha_actual DATE;
    
    -- ***************************************************************************
    -- Inicializa variables
    -- ***************************************************************************
    let cod_ret = "000";
    let v_usuario = "";
    let v_pass = "";
    let v_pass1 = "";
    let v_pass2 = "";
    let v_pass3 = "";
    let v_nombre1 = "";
    let v_nombre2 = "";
    let v_apell_paterno = "";
    let v_apell_materno = "";
    let v_rfc = "";
    let v_telefono1 = "";
    let v_telefono2 = "";
    let  v_fecha_nac = '01-01-1900';
    let  v_fecha_actual = CURRENT ;
    
    BEGIN
    
    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret, v_usuario, v_pass, v_pass1, v_pass2, v_pass3, v_nombre1, v_nombre2, 
                   v_apell_paterno, v_apell_materno, v_rfc, v_telefono1, v_telefono2,  v_fecha_nac, v_fecha_actual;
        end if
    end exception;
    
    IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios  WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN
        SELECT LIMIT 1 usuario, pass, pass1, pass2, pass3 
          INTO v_usuario, v_pass, v_pass1, v_pass2, v_pass3 
          FROM bdinteg:si_bpiusuarios 
         WHERE empresa = pEmpresa 
           AND numcte = pNumCte;
        
        SELECT LIMIT 1 nombre1, nombre2, apell_paterno, apell_materno,  rfc
          INTO  v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno, v_rfc
          FROM bdinteg:si_cliente
         WHERE empresa = pEmpresa
           AND numcte =  pNumCte;
        
        /*
        SELECT LIMIT 1 telefono1, telefono2 
          INTO v_telefono1, v_telefono2 
          FROM bdinteg:si_direcciones 
         WHERE numcte = pNumCte;
        */
        
        SELECT telefono
          INTO v_telefono1
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        SELECT telefono
          INTO v_telefono2
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
        
        SELECT LIMIT 1 fecha_nac 
          INTO v_fecha_nac 
          FROM bdinteg:si_ctepf 
         WHERE numcte = pNumCte;
    ELSE
        LET cod_ret = '001';
    END IF;
    
    return cod_ret, nvl(v_usuario,''),nvl(v_pass,''), nvl(v_pass1,''), nvl(v_pass2,''), nvl(v_pass3,''), 
           v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno, nvl(v_rfc,''), nvl(v_telefono1,''), nvl(v_telefono2,''),  v_fecha_nac, v_fecha_actual;
    
    END
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cons_tel_gral(pEmpresa  CHAR(3),pNumCte   CHAR(20))
RETURNING CHAR(15)  AS vtelefono,
          CHAR(2)   AS vtipotel,
          CHAR(2)   AS vstatustel,
          CHAR(2)   AS vsecuencia;

    DEFINE vtelefono  CHAR(15);
    DEFINE vtipotel   CHAR(2);
    DEFINE vstatustel CHAR(2);
    DEFINE vsecuencia CHAR(2);
    
    LET vtelefono = '';
    LET vtipotel = '';
    LET vstatustel = '';
    LET vsecuencia	 = '';
    
    foreach
        select telefono, tipo_tel, status_tel, secuencia 
        INTO vtelefono, vtipotel, vstatustel, vsecuencia
        from bdinteg:si_telefonos where empresa= pEmpresa and numcte= pNumCte
        order by tipo_tel, secuencia desc
       
        return vtelefono, vtipotel, vstatustel, vsecuencia with resume;
    end foreach;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_correos( pEmpresa    CHAR(3),
                                                 pNumCte     CHAR(20),
                                                 pTipoCorreo SMALLINT,
                                                 pConsulta   CHAR(1) )
RETURNING CHAR(5)   AS vcodret1,
          CHAR(100) AS vCorreoElec,
          SMALLINT  AS vTipoCorreo,
          CHAR(1)   AS vStatusCorreo;

    DEFINE vcodret1 CHAR(5);
    DEFINE vcodret2 CHAR(5);
    DEFINE vcodret3 CHAR(50);
    DEFINE sql_err  INTEGER;
    DEFINE isam_err INTEGER;
    DEFINE desc_err CHAR(50);

    DEFINE vExisteCte       INTEGER;
    DEFINE vfecha_insert    DATE;
    DEFINE vExisteCorreo    SMALLINT;
    DEFINE vMaxSec          SMALLINT;
    DEFINE vCorreoElec      CHAR(100);
    DEFINE vTipoCorreo      SMALLINT;
    DEFINE vStatusCorreo    CHAR(1);

    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';

    LET vExisteCte = 0;
    LET vfecha_insert = '';
    LET vExisteCorreo = 0;
    LET vMaxSec = 0;
    LET vCorreoElec = '';
    LET vTipoCorreo = 0;
    LET vStatusCorreo = '';

    BEGIN

    -- // MANEJO DE EXCEPCIONES
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/resplogifx/conciliachq/sp_consulta_correos.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_consulta_correos.out";
    --- TRACE ON;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- // VALIDA PARAMETROS DE ENTRADA
    IF (pEmpresa is null OR pEmpresa = '') OR
       (pNumCte is null OR pNumCte = '') OR
       (pTipoCorreo is null OR pTipoCorreo = 0) OR
       (pConsulta is null OR pConsulta = '') THEN
        LET vcodret1 = '110';
        RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo;
    END IF;

    -- // VERIFICA SI EXISTE EL NUMERO DE CLIENTE
    SELECT COUNT(*)
      INTO vExisteCte
      FROM bdinteg:"informix".si_cliente
     WHERE numcte = pNumCte;

    IF vExisteCte = 0 THEN
        LET vcodret1 = '104';
        RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo;
    END IF;

    -- // OBTIENE INFORMACION DE ACUERDO AL TIPO DE CONSULTA
    IF pConsulta = 0 THEN
        -- // CORREO MAS RECIENTE DEL TIPO ESPECIFICADO
        SELECT NVL(correo_elec, ' '), tipo_correo, status_correo
          INTO vCorreoElec, vTipoCorreo, vStatusCorreo
          FROM bdinteg:"informix".si_correos
         WHERE numcte = pNumCte
           AND tipo_correo = pTipoCorreo
           AND status_correo = 'A';

        RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo;
    ELIF pConsulta = 1 THEN
        -- // TODOS LOS CORREOS DEL TIPO ESPECIFICADO
        FOREACH
            SELECT NVL(correo_elec, ' '), tipo_correo, status_correo
              INTO vCorreoElec, vTipoCorreo, vStatusCorreo
              FROM bdinteg:"informix".si_correos
             WHERE numcte = pNumCte
               AND tipo_correo = pTipoCorreo
             ORDER BY secuencia DESC

            RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo WITH RESUME;
        END FOREACH;
    ELIF pConsulta = 2 THEN
        -- // TODOS LOS CORREOS
        FOREACH
            SELECT NVL(correo_elec, ' '), tipo_correo, status_correo
              INTO vCorreoElec, vTipoCorreo, vStatusCorreo
              FROM bdinteg:"informix".si_correos
             WHERE numcte = pNumCte
             ORDER BY secuencia DESC

            RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo WITH RESUME;
        END FOREACH;
    ELSE
        -- // TIPO DE CONSULTA INVALIDO
        LET vcodret1 = '109';
        RETURN vcodret1, vCorreoElec, vTipoCorreo, vStatusCorreo;
    END IF;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_infoctecancel(pEmpresa CHAR(3), pNumcte CHAR(10), pCuenta CHAR(20), pTarjeta CHAR(20))
RETURNING

CHAR(5) 	AS 	cCodRet,
CHAR(5) 	AS 	cCodRet2,
CHAR(80)	AS  cMensajeRet,
CHAR(20) 	AS 	NUMCTE,
CHAR(26)    AS  NOMCTE1,
CHAR(26)    AS  NOMCTE2,
CHAR(26)    AS  APELL_PAT,
CHAR(26)    AS  APELL_MAT,
CHAR(15)    AS  RFC,
CHAR(10)   	AS 	FECHA_NACIMIENTO,
CHAR(10)    AS 	FECHA_ALTA,
CHAR(4)		AS	SUCURSAL,
CHAR(20)	AS	CUENTA;


--DECLARACIONES
DEFINE cCodRet          CHAR(5);
DEFINE cCodRet2         CHAR(5);
DEFINE iSqlErr          INTEGER;
DEFINE iIsamErr         INTEGER;
DEFINE cErrorInfo		CHAR(80);
DEFINE cMensajeRet      CHAR(80);

DEFINE cNumcte			CHAR(20);
DEFINE cNomCte1			CHAR(26);
DEFINE cNomCte2			CHAR(26);
DEFINE cApellMat		CHAR(26);
DEFINE cApellPat		CHAR(26);
DEFINE cFechaNac		CHAR(10); 
DEFINE cFechaAlta		CHAR(10); 
DEFINE cRFC				CHAR(13);
DEFINE cSuc				CHAR(4);
DEFINE cCuenta			CHAR(20);
DEFINE cTpoPer          CHAR(2);
DEFINE sEntro           SMALLINT; 



--INICIALIZACIONES
LET cCodRet				= '00000';
LET cCodRet2			= '00000';
LET iSqlErr				= 0;
LET iIsamErr			= 0;
LET cErrorInfo			= '';
LET cMensajeRet			= 'PROCESO EXITOSO';

LET cNumcte				= '';
LET cNomCte1            = '';
LET cNomCte2            = '';
LET cApellMat           = '';
LET cApellPat           = '';
LET cFechaNac           = '';
LET cFechaAlta          = '';
LET cRFC                = '';
LET cSuc				= '';
LET cCuenta				= '';
LET cTpoPer             = '';	
LET sEntro              = 0; 
	
BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cCodRet2 = iSqlErr;
			LET cMensajeRet = cErrorInfo;
			RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));
		END IF;
    END EXCEPTION;

   /*SET DEBUG FILE TO "/resplogifx/conciliachq/sp_infoctecancel.out";
   TRACE ON;*/
	
	IF (NVL(pEmpresa,'') = '' AND NVL(pNumCte,'') = '') OR (NVL(pEmpresa,'') = '' AND NVL(pCuenta,'') = '') OR (NVL(pEmpresa,'') = '' AND NVL(pTarjeta,'') = '') OR (NVL(pEmpresa,'') <> '' AND NVL(pTarjeta,'') = '' AND NVL(pCuenta,'') = '' AND NVL(pNumCte,'') = '')  THEN
	
		SELECT descripcion
		INTO cMensajeRet
		FROM bdinteg:"informix".si_codret
		WHERE codigo_retorno = '050'
		AND sistema = '01';
		
		LET cCodRet = '050';
		LET cCodRet2 = '343';
		
		RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));
	ELSE
		IF NVL(pNumCte,'') <> '' THEN
			LET cNumcte = pNumCte;
		END IF;	
			
		IF NVL(pCuenta,'') <> '' THEN
		
			SELECT num_cte, cuenta
			INTO cNumcte, cCuenta
			FROM bdicheq:"informix".sc_maechq
			WHERE empresa = pEmpresa
			AND cuenta = pCuenta;
			
		
			IF NVL(cCuenta, '') = ''  THEN
				SELECT descripcion
				INTO cMensajeRet
				FROM bdinteg:"informix".si_codret
				WHERE codigo_retorno = '052'
				AND sistema = '01';
				
				LET cCodRet = '052';
				LET cCodRet2 = '322';
				
				RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));

			END IF;
				
		ELIF NVL(pTarjeta,'') <> '' THEN
		
	
			SELECT mat.numcte, mae.cuenta
			INTO cNumcte, cCuenta
			FROM bdicheq:"informix".sc_tarjeta mat,
				 bdicheq:"informix".sc_maechq mae
			WHERE mat.empresa = pEmpresa
			AND mat.num_tarjeta = pTarjeta
			AND mat.cuenta = mae.cuenta;

				IF cCuenta = '' OR cCuenta IS NULL THEN
					SELECT descripcion
					INTO cMensajeRet
					FROM bdinteg:"informix".si_codret
					WHERE codigo_retorno = '054'
					AND sistema = '01';
					
					LET cCodRet = '054';
					LET cCodRet2 = '324';

					RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));
					
				END IF;	
			
		END IF;
		
			--Se obtiene el nombre completo del cliente
			SELECT cte.tpo_persona, TRIM(cte.numcte) ,TRIM (NVL(cte.nombre1,' ')), TRIM (NVL(cte.nombre2,' ')), TRIM(NVL(cte.apell_paterno,' ')), TRIM (NVL(cte.apell_materno,' ')), TRIM(NVL(cte.rfc, ' ')), LPAD(DAY(cte.fecha_alta),2,"0") || "/" || LPAD(MONTH(cte.fecha_alta),2,"0")|| "/" || YEAR(cte.fecha_alta),cte.sucursal
			INTO  cTpoPer, cNumcte ,cNomCte1, cNomCte2, cApellMat, cApellPat, cRFC, cFechaAlta, cSuc
			FROM bdinteg:"informix".si_cliente cte
			WHERE cte.numcte = cNumcte;
			
			LET sEntro = dbinfo("sqlca.sqlerrd2");
						
			IF sEntro = 0 THEN
				SELECT descripcion
				INTO cMensajeRet
				FROM bdinteg:"informix".si_codret
				WHERE codigo_retorno = '051'
				AND sistema = '01';
			
				LET cCodRet = '051';
				LET cCodRet2 = '321';
			
				RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));
			
			ELSE
				IF cTpoPer IN ('01','03') THEN
				--Se valida si el cliente es persona Fisica y se obtiene la fecha de nacimiento 
				SELECT pf.numcte, LPAD(DAY(pf.fecha_nac),2,"0") || "/" || LPAD(MONTH(pf.fecha_nac),2,"0")|| "/" || YEAR(pf.fecha_nac)
				INTO  cNumcte, cFechaNac
				FROM bdinteg:"informix".si_ctepf pf,
					 bdinteg:"informix".si_tipper tip
				WHERE tip.tpo_persona = cTpoPer
				AND pf.numcte = cNumcte
				AND tip.es_fisica = 'S';
				
				ELSE
			
				SELECT pm.nombre_corto, su.descripcion
				INTO  cNomCte1, cNomCte2
				FROM bdinteg:"informix".si_ctepm pm,
				bdinteg:"informix".si_sufijos su
				WHERE pm.numcte = cNumcte
				AND su.codigo =pm.sufijo;
				--LET cNomCte2  = '';
				LET cApellMat = '';
				LET cApellPat = '';
				END IF
				/*
				LET sEntro = dbinfo("sqlca.sqlerrd2");
				
				IF sEntro =  0 THEN
					
					SELECT descripcion
					INTO cMensajeRet
					FROM bdinteg:"informix".si_codret
					WHERE codigo_retorno = '059'
					AND sistema = '01';
				
					LET cCodRet = '059';
					LET cCodRet2 = '335';
				
					RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));				
					
				END IF;
				*/
				
			END IF;
	END IF;
			RETURN TRIM(cCodRet), TRIM(cCodRet2), TRIM(cMensajeRet), TRIM(NVL(cNumcte,'')), TRIM(NVL(cNomCte1,'')), TRIM(NVL(cNomCte2,'')), TRIM(NVL(cApellMat,'')),TRIM(NVL(cApellPat,'')), TRIM(NVL(cRFC,'')), NVL(cFechaNac,''), NVL(cFechaAlta,''), TRIM(NVL(cSuc,'')), TRIM(NVL(cCuenta,''));
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Obtiene la información del cliente ya sea por número de cliente, cuenta o tarjeta, validado que sea persona moral.', 
'AUTOR: Armando Morales',
'FECHA: Julio 2012',
'VERSION: 20120802.1700',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_cnsif_ideconsultamovofi(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCLIENTE CHAR(20),cPERIODO CHAR(06),pNumRegistro INTEGER,pRecuperacion INTEGER)
							
			returning   CHAR(5)     AS Cod_Retorno,
						DATE        AS Fecha,	      
						CHAR(20)    AS Cuenta,          
						CHAR(04)    AS Sucursal,
						MONEY(16,2) AS Importe,
                        CHAR(2)     AS SistemaCuenta;	      

							
DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;		

DEFINE v_cod_ret    CHAR(5);
DEFINE dFecha       DATE;
DEFINE cNumCuenta   CHAR(20);
DEFINE cSucursal    CHAR(04);
DEFINE mImporte     MONEY(16,2);
DEFINE mTotal       MONEY(16,2);
DEFINE cSistemaC    CHAR(2);
--DEFINE mTotalAux    MONEY(16,2);

--PARA PAGINACION
DEFINE iCont                INTEGER;

LET  v_cod_ret    = "00000";
LET dFecha        = "";
LET cNumCuenta    = "";
LET cSucursal     = "";
LET mImporte      = 0;
LET mTotal        = 0;
--LET mTotalAux     = 0;

--inicializando variables
LET  iexiste 		 = 0;
LET cCodRet 		 = "00000";
LET iSql_err 		 = 0 ;

LET iCont            = 0;
LET cSistemaC        ='00';
                              

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;						
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_ideconsultamovofi_2.out";
	--TRACE ON;

	IF 	cID_USUARIOC  = '' 	OR
		cID_FUNCIONC  = '' 	OR
		cNUMCLIENTE   = ''	OR
		cPERIODO      = ''  THEN
		LET cCodRet = "00060";
		RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
	END IF;	

    IF pNumRegistro<0 THEN
        LET cCodRet='00098';
        RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;				
    ELSE
        IF pRecuperacion<=0 THEN
            LET cCodRet='00098';
            RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
        END IF;
    END IF;  
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCLIENTE,'23','2')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
	    RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
	END IF;
	-- TERMINA VALIDACION	
	FOREACH
		SELECT NVL(COUNT(num_cte),0) AS CONT INTO iexiste FROM bdilide:sl_movefec WHERE num_cte  = cNUMCLIENTE AND aniomes = cPERIODO
		UNION
		SELECT NVL(COUNT(num_cte),0) AS CONT FROM  bdilide:sl_movefec_his WHERE num_cte  = cNUMCLIENTE AND aniomes = cPERIODO ORDER BY CONT DESC
	END FOREACH;

	IF iexiste  = 0 THEN 
		LET cCodRet = "00061";
		RETURN cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
	END IF;
	
	IF pNumRegistro = 0 THEN
	
		DELETE {+INDEX (bdinteg:si_tempomovofi idx_tempopermovofi)} FROM si_tempomovofi WHERE num_cte  = cNUMCLIENTE AND aniomes = cPERIODO AND ejecutivosif= cID_USUARIOC;
		SET ISOLATION TO DIRTY READ;		
		FOREACH
		
		    EXECUTE PROCEDURE bdilide:sp_ideconsultamovofi (cNUMCLIENTE, cPERIODO,0)
			INTO
			v_cod_ret, dFecha,cNumCuenta,cSucursal,mImporte	
			
			IF LENGTH(v_cod_ret) = 3 THEN
				LET  cCodRet = '00' || v_cod_ret;
			ELIF LENGTH(v_cod_ret) = 5 THEN
				LET  cCodRet = v_cod_ret;
			END IF
			
			IF cCodRet != '00000' THEN
				RETURN 	cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
			END IF

			
			INSERT INTO si_tempomovofi(cod_ret,fecha,numcuenta,sucursal,importe,aniomes,num_cte, ejecutivosif)
			VALUES(v_cod_ret,dFecha,cNumCuenta,cSucursal,mImporte,cPERIODO,cNUMCLIENTE, cID_USUARIOC);		
			
		END FOREACH
		
	
	END IF
	
	SET ISOLATION TO DIRTY READ;
	
	FOREACH
	
		SELECT {+INDEX (bdinteg:si_tempomovofi idx_tempopermovofi)} SKIP pNumRegistro FIRST pRecuperacion
		cod_ret,fecha,numcuenta,sucursal,importe
		INTO
		v_cod_ret, dFecha,cNumCuenta,cSucursal,mImporte
		FROM si_tempomovofi
		WHERE num_cte  = cNUMCLIENTE
		AND aniomes = cPERIODO AND ejecutivosif= cID_USUARIOC ORDER BY fecha
		
		IF LENGTH(v_cod_ret) = 3 THEN
			LET  cCodRet = '00' || v_cod_ret;
		ELIF LENGTH(v_cod_ret) = 5 THEN
			LET  cCodRet = v_cod_ret;
		END IF
		
		LET iCont = iCont + 1;

        IF SUBSTR(cNumCuenta,1,1)='3' THEN
            LET cSistemaC='03';
        ELIF SUBSTR(cNumCuenta,1,1)='6' THEN
            LET cSistemaC='06';
        ELSE
            LET cSistemaC='01';
        END IF;
		
		RETURN 	cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC WITH Resume;
		
	END FOREACH
	
	IF iCont = 0 THEN
		DELETE {+INDEX (bdinteg:si_tempomovofi idx_tempopermovofi)} FROM si_tempomovofi WHERE num_cte = cNUMCLIENTE AND aniomes = cPERIODO AND ejecutivosif= cID_USUARIOC;
		LET cCodRet = 1001; 
		RETURN 	cCodRet,dFecha,cNumCuenta,cSucursal,mImporte,cSistemaC;
	END IF; 
	
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información del Detalle de Movimientos en Efectivo para la consulta de Recaudaciones LIDE. ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Número de Cliente.",
"FECHA : 16-03-2012",
