CREATE PROCEDURE "informix".sp_valida_servicio_ctebm(pNumCliente VARCHAR(9))
RETURNING CHAR (5), VARCHAR(15), SMALLINT;
	--*********************************************************************************************************************************
	-- Objetivo: Valida que el cliente disponga del servicio de banca móvil y obtiene los datos numero celular y estatus del sevicio. 
	-- Autor: Francisco Rodrìguez
	-- Solicito: José de Jesús Nevarez
	-- Fecha: 13/09/2011
	--------------------------------------------------------------------------------------------
	-- Se agrega la validación de los intentos de ingreso
	-- Bibiana Gaxiola Verdugo.
	-- 21/01/2013
	--**********************************************************************************************************************************
	DEFINE sql_err INT;
	DEFINE vCod_ret CHAR (5);
	DEFINE vNumCel VARCHAR (15);
	DEFINE vStatus SMALLINT;
	DEFINE vIntentos CHAR(3);
	
	BEGIN
		ON EXCEPTION SET sql_err
		  IF sql_err <> 0 THEN
				let vCod_ret = sql_err;
				RETURN vCod_ret, vNumCel, vStatus;
		  END IF ;
		END EXCEPTION ;
		
		--SET DEBUG FILE TO "/home/informix/bibiana/validabm.out";
		--TRACE ON;
		
		LET vCod_ret = '00000';
		LET vNumCel = '';
		LET vStatus= 0;
		LET vIntentos = '';
		
		SET LOCK MODE TO WAIT 3;
		
		IF  EXISTS (SELECT {+index (bdinteg:"informix"si_bm_usuarios "informix".idx_ctebmusuario)} numcte 
					FROM bdinteg:"informix".si_bm_usuarios WHERE numcte= pNumCliente) THEN
			SELECT numcel, id_status, numintacce INTO vNumCel,vStatus,vIntentos FROM bdinteg:"informix".si_bm_usuarios WHERE numcte= pNumCliente;
			LET vNumCel = TRIM(vNumCel);
			
			IF (vStatus = '30' AND vIntentos = '3') THEN
				LET vStatus = '50';
			END IF;
		ELSE
			LET vCod_ret = '00001'; -- Cliente no tiene el servicio de banca móvil.
		END IF;
		
		RETURN vCod_ret, vNumCel, vStatus;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_desbloquea_serviciobm(pNumCliente VARCHAR(9),pStatus SMALLINT, pSucursal CHAR (4), pUsuario CHAR (8))
RETURNING CHAR (5);
	--*****************************************************************
	-- Objetivo: Desbloquea el servicio de banca movil del cliente.
	-- Autor: Francisco Rodrìguez
	-- Solicito: José de Jesús Nevarez
	-- Fecha: 13/09/2011
	--------------------------------------------------------------------
	-- Se agrega el reinicio de intentos de bloqueo
	-- Bibiana Gaxiola Verdugo.
	-- 21/01/2013
	--******************************************************************
	DEFINE sql_err int;
	DEFINE vCod_ret   CHAR (5);
	DEFINE vStatusAnt SMALLINT;
	DEFINE vStatusNvo SMALLINT;
	DEFINE vNumCel    CHAR (15);
	DEFINE vIntentos CHAR (3);
	
	BEGIN
		ON EXCEPTION SET sql_err
		  IF sql_err <> 0 THEN
				let vCod_ret = sql_err;
				RETURN vCod_ret;
		  END IF ;
		END EXCEPTION ;
		
		--SET DEBUG FILE TO "/home/informix/bibiana/desbloqueabm.out";
		--TRACE ON;
		
		LET vCod_ret = '00000';
		LET vNumCel = ''; 
		LET vStatusAnt = 0;
		LET vStatusNvo = 0;
		LET vIntentos = '';
		
		SET LOCK MODE TO WAIT 3;
		
		SELECT id_status, numcel, numintacce INTO vStatusAnt, vNumCel, vIntentos FROM bdinteg:"informix".si_bm_usuarios WHERE numcte= pNumCliente;
		
		IF (vStatusAnt = '30') THEN
			
			LET vStatusNvo = '30';
			LET vIntentos = '0';
			
			UPDATE bdinteg:"informix".si_bm_usuarios SET numintacce = vIntentos WHERE numcte= pNumCliente;
			
			INSERT INTO bdinteg:"informix".si_bm_camestcte (numcte, id_statant, id_statact, numcel, fecha_mod, suc_mod, user_mod)
			VALUES (pNumCliente,vStatusAnt,vStatusNvo,vNumCel,current,pSucursal,pUsuario);
		ELSE
			LET vCod_ret = '00001'; -- Status seleccionado incorrecto.
		END IF;

		RETURN vCod_ret;
	END;
END PROCEDURE;

CREATE procedure "informix".sp_consul_direc(eEmpresa  CHAR(3),
                                            eNumCte   CHAR(20),
                                            eTpDirec  INTEGER)

returning char(5),int,char(1),char(40),char(60),char(40),
          char(3),char(2),char(3),char(5),char(5),char(11),char(1),
          char(13),char(1),char(13),char(1),char(13),char(5),char(2),char(3),
          char(4),smallint,char(10),char(10),char(6),int,int,char(1),
          char(1),smallint,smallint,smallint,smallint,smallint,smallint,
          smallint,char(80),char(30),char(30),char(30),char(30),char(30),
          char(30), char(30), char(30), char(30), char(30),char(30);

    DEFINE vsqlerr          integer;
    DEFINE vsecuencia       int ;
    DEFINE vnumerocalle     int ;
    DEFINE vnumerocolonia   int ;
    DEFINE vcodret          char(5);
    DEFINE vtipo_dir        char(1);
    DEFINE vcalle           char(40);
    DEFINE vcolonia         char(60);
    DEFINE ventre_calles    char(40);
    DEFINE vpais            char(3);
    DEFINE vestado          char(2);
    DEFINE vciudad          char(3);
    DEFINE vmunicipio       char(5);
    DEFINE vcod_postal      char(5);
    DEFINE vapart_postal    char(11);
    DEFINE vtipo_telef1     char(1);
    DEFINE vtelefono1       char(13);
    DEFINE vtipo_telef2     char(1);
    DEFINE vtelefono2       char(13);
    DEFINE vtipo_telef3     char(1);
    DEFINE vtelefono3       char(13);
    DEFINE vextension       char(5);
    DEFINE vestado_inegi    char(2);
    DEFINE vmunicipio_inegi char(3);
    DEFINE vlocalidad_inegi char(4);
    DEFINE vnumeroextcalle  char(10);
    DEFINE vnumerointcalle  char(10);
    DEFINE vdepartamento    char(6);
    DEFINE vpuntocardinal   char(1);
    DEFINE vunidadhabitac   char(1);
    DEFINE vobservaciones   char(80);
    DEFINE vNomEdo          char(30);
    DEFINE vNomCiudad       char(30);
    DEFINE vNomColonia      char(30);
    DEFINE vNomCalle        char(30);
    DEFINE vNomLote         char(30);
    DEFINE vNomEntrada      char(30);
    DEFINE vNomEdificio     char(30);
    DEFINE vNomEtapa        char(30);
    DEFINE vNomAndador      char(30);
    DEFINE vNomOtros        char(30);
    DEFINE vNomManzana      char(30);
    DEFINE vmanzana         smallint ;
    DEFINE vCiclo           smallint;
    DEFINE votros           smallint ;
    DEFINE vandador         smallint ;
    DEFINE vetapa           smallint ;
    DEFINE vlote            smallint ;
    DEFINE vnumerociudad    smallint ;
    DEFINE vedificio        smallint ;
    DEFINE ventrada         smallint ;
    DEFINE vCdCoppel        smallint;
    DEFINE vSec             int;

    LET vciclo             = 0;
    LET vcodret            = "000";
    LET  vsqlerr           = 0;
    LET vsecuencia         = 0;
    LET vtipo_dir          = "";
    LET vcalle             = "";
    LET vcolonia           = "";
    LET ventre_calles      = "";
    LET vpais              = "";
    LET vestado            = "";
    LET vciudad            = "";
    LET vmunicipio         = "";
    LET vcod_postal        = "";
    LET vapart_postal      = "";
    LET vtipo_telef1       = "";
    LET vtelefono1         = "";
    LET vtipo_telef2       = "";
    LET vtelefono2         = "";
    LET vtipo_telef3       = "";
    LET vtelefono3         = "";
    LET vextension         = "";
    LET vestado_inegi      = "";
    LET vmunicipio_inegi   = "";
    LET vlocalidad_inegi   = "";
    LET vnumerociudad      = 0;
    LET vnumeroextcalle    = "";
    LET vnumerointcalle    = "";
    LET vdepartamento      = "";
    LET vnumerocalle       = 0;
    LET vnumerocolonia     = 0;
    LET vpuntocardinal     = "";
    LET vunidadhabitac     = "";
    LET vmanzana           = 0;
    LET votros             = 0;
    LET vandador           = 0;
    LET vetapa             = 0;
    LET vlote              = 0;
    LET vedificio          = 0;
    LET ventrada           = 0;
    LET vobservaciones     = "";
    LET vNomEdo            = '';
    LET vNomCiudad         = '';
    LET vNomColonia        = '';
    LET vNomCalle          = '';
    LET vCdCoppel          = '';
    LET vNomLote           = '';
    LET vNomEntrada        = '';
    LET vNomEdificio       = '';
    LET vNomEtapa          = '';
    LET vNomAndador        = '';
    LET vNomOtros          = '';
    LET vNomManzana        = '';
    LET vSec                = 0;

    --- set debug file to "/home/informix/ash/direc.out";
    --- trace on;

    BEGIN
    
    ON EXCEPTION SET vsqlerr
        IF vsqlerr <> 0 THEN
            LET vcodret = vsqlerr;
            return  vcodret        ,vsecuencia   ,vtipo_dir      ,vcalle        ,vcolonia        ,ventre_calles   ,vpais        ,vestado        ,
                    vciudad        ,vmunicipio   ,vcod_postal    ,vapart_postal ,vtipo_telef1    ,vtelefono1      ,vtipo_telef2 ,vtelefono2     ,
                    vtipo_telef3   ,vtelefono3   ,vextension     ,vestado_inegi ,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad,vnumeroextcalle,
                    vnumerointcalle,vdepartamento,vnumerocalle   ,vnumerocolonia,vpuntocardinal  ,vunidadhabitac  ,vmanzana     ,votros         ,
                    vandador       ,vetapa       ,vlote          ,vedificio     ,ventrada        ,vobservaciones  ,vNomEdo      ,vNomCiudad     ,
                    vNomColonia    ,vNomCalle    , vNomLote      , vNomEntrada  ,vNomEdificio    ,vNomEtapa       ,vNomAndador  ,vNomOtros      ,
                    vNomManzana    ;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    /*SELECT MAX(secuencia) INTO vSec       FROM si_direcciones
    WHERE  numcte    = eNumCte
    AND  tipo_dir = eTpDirec;*/

    FOREACH
        SELECT  dir.secuencia     ,dir.tipo_dir      ,dir.calle       ,dir.colonia     ,dir.entre_calles    ,dir.pais,estado     , dir.ciudad      ,
                dir.municipio     ,dir.cod_postal    ,dir.apart_postal,tel1.tipo_tel ,tel1.telefono       ,tel2.tipo_tel     ,tel2.telefono    ,
                tel3.tipo_tel   ,tel3.telefono     ,tel3.extension   ,dir.estado_inegi,dir.municipio_inegi ,dir.localidad_inegi ,dir.numerociudad ,
                dir.numeroextcalle,dir.numerointcalle,dir.departamento, dir.numerocalle,dir.numerocolonia   ,dir.puntocardinal   ,dir.unidadhabitac,
                dir.manzana       ,dir.otros         ,dir.andador     ,dir.etapa       ,dir.lote            ,dir.edificio        ,dir.entrada       ,
                dir.observaciones
          INTO  vsecuencia   ,vtipo_dir     ,vcalle      ,vcolonia    ,ventre_calles   ,vpais          ,vestado       , vciudad,
                vmunicipio     ,vcod_postal   ,vapart_postal,vtipo_telef1 ,vtelefono1      ,vtipo_telef2    ,vtelefono2    ,
                vtipo_telef3   ,vtelefono3    ,vextension   ,vestado_inegi,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad ,
                vnumeroextcalle,vnumerointcalle,vdepartamento,vnumerocalle,vnumerocolonia  ,vpuntocardinal  ,vunidadhabitac,
                vmanzana       ,votros         ,vandador     ,vetapa      ,vlote           ,vedificio       ,ventrada      ,
                vobservaciones
          FROM si_direcciones_actual dir
          LEFT OUTER JOIN si_telefonos_actual tel1 ON ( tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 )
          LEFT OUTER JOIN si_telefonos_actual tel2 ON ( tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 )
          LEFT OUTER JOIN si_telefonos_actual tel3 ON ( tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 )
         WHERE dir.numcte    = eNumCte
           AND  dir.tipo_dir = eTpDirec
       --- AND secuencia = vSec
     --- ORDER BY secuencia

        SELECT TRIM(nombre) 
          INTO vNomEdo 
          FROM bdinteg:si_estados
         WHERE estado =vestado;

        SELECT TRIM(nombre),ciudad_coppel 
          INTO vNomCiudad,vCdCoppel 
          FROM bdinteg:si_ciudades
         WHERE estado = vestado 
           AND ciudad = vciudad;

        SELECT TRIM(nombrezona) 
          INTO vNomColonia 
          FROM bdinteg:si_catzonas
         WHERE numerociudad = vnumerociudad 
           and numerocolonia  = vnumerocolonia;

        SELECT TRIM(nombrecalle) 
          INTO  vNomCalle 
          FROM bdinteg:si_catcalles
         WHERE numerocalle = vnumerocalle;

        IF vlote > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomLote  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = vlote;
        END IF;

        IF vmanzana > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomManzana  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = vmanzana;
        END IF;

        IF votros > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomOtros  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = votros;
        END IF;

        IF vandador > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomAndador  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = vandador;
        END IF;

        IF vetapa > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomEtapa    
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = vetapa;
        END IF;

        IF vedificio > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomEdificio  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = vedificio;
        END IF;

        IF ventrada > 0 THEN
            SELECT TRIM(nombredomicilio) 
              INTO vNomEntrada  
              FROM bdinteg:si_catdomicilios
             WHERE numerociudad = vCdCoppel 
               AND numerocolonia = vnumerocolonia 
               AND clavedomicilio = ventrada;
        END IF;
        
        IF vsecuencia is null THEN LET vsecuencia = 0; END IF;
        IF vtipo_dir is null THEN LET vtipo_dir = ' '; END IF;
        IF vcalle is null THEN LET vcalle = ' '; END IF;
        IF vcolonia is null THEN LET vcolonia = ' '; END IF;
        IF ventre_calles is null THEN LET ventre_calles = ' '; END IF;
        IF vpais is null THEN LET vpais = ' '; END IF;
        IF vestado is null THEN LET vestado = ' '; END IF;
        IF vciudad is null THEN LET vciudad = ' '; END IF;
        IF vmunicipio is null THEN LET vmunicipio = ' '; END IF;
        IF vcod_postal is null THEN LET vcod_postal = ' '; END IF;
        IF vapart_postal is null THEN LET vapart_postal = ' '; END IF;
        IF vtipo_telef1 is null THEN LET vtipo_telef1 = ' '; END IF;
        IF vtelefono1 is null THEN LET vtelefono1 = ' '; END IF;
        IF vtipo_telef2 is null THEN LET vtipo_telef2 = ' '; END IF;
        IF vtelefono2 is null THEN LET vtelefono2 = ' '; END IF;
        IF vtipo_telef3 is null THEN LET vtipo_telef3 = ' '; END IF;
        IF vtelefono3 is null THEN LET vtelefono3 = ' '; END IF;
        IF vextension is null THEN LET vextension = ' '; END IF;
        IF vestado_inegi is null THEN LET vestado_inegi = ' '; END IF;
        IF vmunicipio_inegi is null THEN LET vmunicipio_inegi = ' '; END IF;
        IF vlocalidad_inegi is null THEN LET vlocalidad_inegi = ' '; END IF;
        IF vnumerociudad is null THEN LET vnumerociudad = 0; END IF;
        IF vnumeroextcalle is null THEN LET vnumeroextcalle = ' '; END IF;
        IF vnumerointcalle is null THEN LET vnumerointcalle = ' '; END IF;
        IF vdepartamento is null THEN LET vdepartamento = ' '; END IF;
        IF vnumerocalle is null THEN LET vnumerocalle = 0; END IF;
        IF vnumerocolonia is null THEN LET vnumerocolonia = 0; END IF;
        IF vpuntocardinal is null THEN LET vpuntocardinal = ' '; END IF;
        IF vunidadhabitac is null THEN LET vunidadhabitac = ' '; END IF;
        IF vmanzana is null THEN LET vmanzana = 0; END IF;
        IF votros is null THEN LET votros = 0; END IF;
        IF vandador is null THEN LET vandador = 0; END IF;
        IF vetapa is null THEN LET vetapa = 0; END IF;
        IF vlote is null THEN LET vlote = 0; END IF;
        IF vedificio is null THEN LET vedificio = 0; END IF;
        IF ventrada is null THEN LET ventrada = 0; END IF;
        IF vobservaciones is null THEN LET vobservaciones = ' '; END IF;
        IF vNomEdo is null THEN LET vNomEdo = ' '; END IF;
        IF vNomCiudad is null THEN LET vNomCiudad = ' '; END IF;
        IF vNomColonia is null THEN LET vNomColonia = ' '; END IF;
        IF vNomCalle is null THEN LET vNomCalle = ' '; END IF;
        IF vNomLote is null THEN LET vNomLote = ' '; END IF;        
        IF vNomEntrada is null THEN LET vNomEntrada = ' '; END IF;
        IF vNomEdificio is null THEN LET vNomEdificio = ' '; END IF;
        IF vNomEtapa is null THEN LET vNomEtapa = ' '; END IF;
        IF vNomAndador is null THEN LET vNomAndador = ' '; END IF;
        IF vNomOtros is null THEN LET vNomOtros = ' '; END IF;
        IF vNomManzana is null THEN LET vNomManzana = ' '; END IF;
        
        
        return  vcodret        ,vsecuencia   ,vtipo_dir      ,vcalle        ,vcolonia        ,ventre_calles   ,vpais        ,vestado        ,
                vciudad        ,vmunicipio   ,vcod_postal    ,vapart_postal ,vtipo_telef1    ,vtelefono1      ,vtipo_telef2 ,vtelefono2     ,
                vtipo_telef3   ,vtelefono3   ,vextension     ,vestado_inegi ,vmunicipio_inegi,vlocalidad_inegi,vnumerociudad,vnumeroextcalle,
                vnumerointcalle,vdepartamento,vnumerocalle   ,vnumerocolonia,vpuntocardinal  ,vunidadhabitac  ,vmanzana     ,votros         ,
                vandador       ,vetapa       ,vlote          ,vedificio     ,ventrada        ,vobservaciones  ,vNomEdo      ,vNomCiudad     ,
                vNomColonia    ,vNomCalle    , vNomLote      ,vNomEntrada   ,vNomEdificio    ,vNomEtapa       ,vNomAndador  ,vNomOtros      ,
                vNomManzana    ;
    END FOREACH;
    
    END
    
end procedure

DOCUMENT
"Consulta de direcciones del cliente",
"Autor : Procesamiento Interactivo S.A. de C.V.",
