CREATE PROCEDURE "informix".sp_depura_correos( pEmpresa CHAR(3) )
RETURNING CHAR(5), INTEGER;
    
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vEnTransacc  SMALLINT;
    DEFINE vContador    INTEGER;
    DEFINE vNumCte      CHAR(20);
    DEFINE vTipoCorreo  SMALLINT;
    DEFINE vCorreoElec  CHAR(100);
    
    LET vcodret1    = '000';
    LET vcodret2    = '000';
    LET vcodret3    = '';
    LET sql_err	    = 0;
    LET isam_err    = 0;
    LET desc_err    = '';
    LET vEnTransacc = 0;
    LET vContador   = 0;
    LET vNumCte     = '';
    LET vTipoCorreo = 0;
    LET vCorreoElec = '';
    
    BEGIN
    
    -- // MANEJO DE EXCEPCIONES
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_depura_correos.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF vEnTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_depura_correos.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    BEGIN WORK;
    
    DELETE FROM si_correos
     WHERE numcte IN('010756364','010013996')
       AND tipo_correo = 1
       AND secuencia = 2;
       
    COMMIT WORK;
    
    SELECT numcte, tipo_correo, correo_elec, COUNT(*) AS repeticiones
      FROM si_correos
     GROUP BY 1, 2, 3
    HAVING COUNT(*) > 1
    INTO TEMP tmp_duplicados WITH NO LOG;
    CREATE INDEX idxtmp_corrdupl ON tmp_duplicados(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE tmp_duplicados;
    
    FOREACH WITH HOLD
        SELECT numcte, tipo_correo, correo_elec
          INTO vNumCte, vTipoCorreo, vCorreoElec
          FROM tmp_duplicados
          
        BEGIN WORK;
        LET vEnTransacc = 1;
          
        DELETE FROM si_correos
         WHERE numcte = vNumCte
           AND tipo_correo = vTipoCorreo
           AND correo_elec = vCorreoElec
           AND secuencia < ( SELECT MAX(secuencia)
                               FROM si_correos
                              WHERE numcte = vNumCte
                                AND tipo_correo = vTipoCorreo
                                AND correo_elec = vCorreoElec );
           
        COMMIT WORK;
        LET vEnTransacc = 0;
        
        LET vContador = vContador +1;
        
        LET vNumCte     = '';
        LET vTipoCorreo = 0;
        LET vCorreoElec = '';
    END FOREACH;
    
    END;

    RETURN vcodret1, vContador;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizactesbcplcpl(pEmpresa CHAR(3))
RETURNING CHAR(5) AS CodigoRetorno;

DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cNumCteCoppel CHAR(20);
DEFINE cNumCte CHAR(20);

LET iSqlErr	= 0;
LET cCodRet = '00000';
LET cNumCteCoppel = '';
LET cNumCte	= '';

--SET DEBUG FILE TO "/tmp/sp_actualizactesbcplcpl.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
		
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		
	IF NVL(pEmpresa,'') = '' THEN
		LET cCodRet = '00001';
	ELSE
		FOREACH
			SELECT numctecoppel, numcte INTO cNumCteCoppel, cNumCte
			FROM "informix".si_adiccoppel
			WHERE tipotar = '1' 
			
			IF EXISTS(SELECT 1 FROM "informix".si_relacion_ctebcplcpl WHERE empresa = pEmpresa AND numcte_banco = cNumCte) THEN
				UPDATE "informix".si_relacion_ctebcplcpl SET cliente = cNumCteCoppel 
				WHERE empresa = pEmpresa AND numcte_banco = cNumCte;
			ELSE
				INSERT INTO "informix".si_relacion_ctebcplcpl
				(empresa,numcte_banco,cliente,numempleado,tipo_relacion,definicion,status,tipo_re_ini,fecha_insert)
				VALUES(pEmpresa,cNumCte,cNumCteCoppel,USER,1,'','1',0,TODAY);
			END IF;
			
			IF EXISTS(SELECT 1 FROM "informix".si_cliente WHERE empresa = pEmpresa AND numcte = cNumCte) THEN
				UPDATE "informix".si_cliente SET numcte_ref = cNumCteCoppel 
				WHERE empresa = pEmpresa AND numcte = cNumCte;
			END IF;
		END FOREACH;
	END IF;
	RETURN cCodRet;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualiza_status_bpi(pEmpresa char (3), pNumCte char(9), pStatus integer, pIpUsuario char(15), pSucursal char(4), pUsuario char(8))
	 RETURNING  CHAR(5);   -- Codigo de Retorno
	
	/*Realizó: Javier Calderon
	Fecha: 02/01/09
	Solicitó: Mauricio León
	Actividad: Actualiza el status y fecha de status del token asignado al cliente
	--
	Realizó: ING. ALFONSO CRUZ
	Fecha: 10/12/2012
	Solicitó: JOSÉ DE JESUS NEVAREZ
	Actividad: EVALÚA SI EL CLIENTE TIENE REGISTRADO EL CARGO DEL TOKEN PARA LA PREACTIVACIÓN*/
	
    --DEFINICION DE VARIABLES--
    DEFINE sql_err      INT;
    DEFINE vCodRet      CHAR(5);
    DEFINE vIdStatus    CHAR(4);
    DEFINE vServicio smallint;
    DEFINE vSolicitud CHAR(10);

    DEFINE vIdStaSol CHAR(4);
	DEFINE cSolicitud CHAR(10);
	DEFINE vToken CHAR(10);
	DEFINE vIdStaToken CHAR(3);
	DEFINE vSucRegistra CHAR(4);
	DEFINE vFolioToken CHAR(25);
	DEFINE vF_Status DATE;
	DEFINE vF_Registro DATE;
	DEFINE vIdStaTkn CHAR(4);
	DEFINE vNsTkn CHAR(10);

    --INICIALIZACION DE VARIABLES--
    LET sql_err = 0;
    LET vCodRet =   '000';
   -- LET vMensValid = '';
    LET vIdStatus = '';
    LET vServicio = 0;
    LET VSolicitud = '';

    LET vIdStaSol = '';
	LET vToken = '';
	LET vIdStaToken = '';
	LET vSucRegistra = '';
	LET vFolioToken = '';
	LET vF_Status = '01-01-1900';
	LET vF_Registro  = '01-01-1900';
	LET vIdStatKN = '';
	LET vNsTkn = '';

	--SET DEBUG FILE TO "/home/sysifx/soporte/iccat/sp_actualiza_status_bpi.out";
    --SET DEBUG FILE TO "/informix/viri/sp_actualiza_status_bpi.out";
	--TRACE ON;

BEGIN 
	
    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET vCodRet = sql_err;
            RETURN vCodRet;
        END IF;
    END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
    
		SELECT id_status,servicio 
		INTO vIdStatus,vServicio 
		FROM bdinteg:si_bpiusuarios 
		WHERE  empresa = pEmpresa AND numcte = pNumCte;
		
		IF pStatus ='10' AND  vServicio = 2 THEN
			--PREACTIVACION DEL SERVICIO BPI
			IF(NOT EXISTS(SELECT solicitud FROM bdibpi:"informix".bpi_tokensolicitud WHERE numcte = pNumCte AND id_status <>'199' )) THEN
				--EL CLIENTE NO TIENE REGISTRADO EL CARGO DEL TOKEN
				LET vCodRet =   '002';
			END IF;
		END IF;
	
        
	IF vCodRet = '000'  THEN
	
        UPDATE bdinteg:"informix".si_bpiusuarios 
		SET id_status = pStatus, f_status = CURRENT 
		WHERE numcte = pNumCte;

		INSERT INTO bdinteg:"informix".si_cambiostcte (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)
		VALUES (pNumCte, vIdStatus, pStatus, pIpUsuario, CURRENT, pSucursal, pUsuario);

        IF pStatus = '99' AND  vServicio = 2 THEN

            FOREACH
                SELECT solicitud, id_status, ns_token  
				INTO vSolicitud, vIdStaSol, vToken
                FROM bdibpi:"informix".bpi_tokensolicitud  
				WHERE empresa = TRIM(pEmpresa)  AND numcte = TRIM(pNumCte)

                EXECUTE PROCEDURE bdibpi:"informix".sp_set_solicitudstatus_admtoken(vSolicitud, pNumCte, pUsuario, vIdStaSol, '199') INTO vCodRet;

            END FOREACH;
                
				SELECT id_status_token, ns_token
				INTO vIdStaTkn, vNsTkn
				FROM bdinteg:si_bpitoken
				WHERE empresa = TRIM(pEmpresa)  AND num_cliente = TRIM(pNumCte);
				
                EXECUTE PROCEDURE bdibpi:"informix".sp_cancelartoken(pEmpresa, pNumCte, vNsTkn, pUsuario, vIdStaTkn, '199', '03') INTO vCodRet;
            	                               
        END IF;
          
     END IF;
	
    RETURN vCodRet;

END
END PROCEDURE
DOCUMENT
'Modificó: Berenice Noriega',
'Para actualizar que tambien actulizara el token',
'Fecha: 13/Febrero/2012',
'Modificó: ING. ALFONSO CRUZ',
'EVALÚA SI EL CLIENTE TIENE REGISTRADO EL CARGO DEL TOKEN PARA LA PREACTIVACIÓN',
'Fecha: 10/12/2012',
'Modificó Viridiana Rosas',
'Para que consulte el id_status del token y lo mande como paramentro al spl que actualiza la tabla tkn_series en el proceso de cancelación',
'Fecha 08/03/2013';

CREATE PROCEDURE "informix".sp_consultafoliocurp(cEmpresa CHAR(3),cTarjeta CHAR(20), cFechaExpTarj CHAR(4))

				
RETURNING 
CHAR(5),
CHAR (20),
CHAR(6);
					
-- DEFINICION DE VARIABLES
DEFINE cCodret         CHAR(5);
DEFINE cCodret2       CHAR(7);
DEFINE cCodret3		  CHAR(6);
DEFINE cNumCredito    CHAR(20);
DEFINE cNumTarjeta    CHAR(20);
DEFINE cNumCte        CHAR(20);
DEFINE cCurp          CHAR(20);
DEFINE iSqlErr 		  INTEGER;
DEFINE ivalor         INTEGER;
DEFINE cCodIsam 	  CHAR(5);

--INICIALIZACION DE VARIABLES
LET cCodret = '00000';
LET cCodret2 = '0000000';
LET cCodret3 = '      ';
LET cNumCredito = '';
LET cNumTarjeta = '';
LET cNumCte = '';
LET cCurp = '';
LET iSqlErr = 0;
LET ivalor = 0;
LET cCodIsam = '00000';

--SET DEBUG FILE TO '/home/sysifx/Nancy/sp_consultafoliocurp.out';
--TRACE ON;

	SET LOCK MODE TO WAIT 5;
	SET ISOLATION TO DIRTY READ;	

	BEGIN
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodret = iSqlErr;
				RETURN cCodret,cCurp,cCodret3;
			END IF;
		END EXCEPTION;
		
	IF TRIM(cEmpresa) = '' OR TRIM (cFechaExpTarj) = '' THEN
		LET cCodret = '00001'; --Faltan Parámetros 
		LET cCodret2 = 'MCE0005';
		LET cCurp = cCodret2; --Se asigna el código del error al campo de la CURP
	ELIF TRIM(cTarjeta) = '' THEN
		LET cCodret = '00001';
		LET cCodret2 = 'MPE0583';
		LET cCurp = cCodret2; --Se asigna el código del error al campo de la CURP
	ELSE

		EXECUTE PROCEDURE "informix".sp_validatarjetacurp (cEmpresa,cTarjeta,cFechaExpTarj) 
		INTO cCodret2,cCodIsam,cNumcte,cNumTarjeta;
		IF cCodret2 = 'MCA0010'  THEN	
			IF EXISTS (SELECT 1 FROM bdinteg:"informix".si_ctepf WHERE numcte = cNumcte) THEN
				SELECT curp INTO cCurp FROM bdinteg:"informix".si_ctepf WHERE numcte = cNumcte;
				IF cCurp <> "" AND cCurp IS NOT NULL AND LENGTH(cCurp) <> 0 THEN
					LET cCodret = '00000';
					UPDATE bdinteg:"informix".si_folioafore SET curP_resp = SUBSTR(cCurp,1,18) WHERE num_tarjeta = cTarjeta AND fecha_expira = cFechaExpTarj; -- DSB 21/03/2013 
					
					SELECT valor INTO ivalor FROM bdinteg:"informix".si_param WHERE cod_param = 124;
					LET ivalor = ivalor + 1;
					UPDATE si_param
                     SET (valor) = (ivalor)
                     WHERE cod_param = 124;
					 LET cCodret3 = LPAD(ivalor,6,'0');
				ELSE
					LET cCodret = '00004'; --El campo CURP viene vacío
					LET cCurp = 'MCE0002'; --Se asigna el código del error al campo de la CURP
				END IF;
			ELSE
				LET cCodret = '00003'; --No existe cte en si_ctepf.
				LET cCurp = 'MCE0002'; --Se asigna el código del error al campo de la CURP
			END IF;
		ELSE
			IF cCodret2[1] = 'M' THEN
				LET cCodret = '00002';
				LET cCurp = cCodret2; --Se asigna el código del error al campo de la CURP
			ELSE
				LET cCodret = cCodret2;
				LET cCurp = cCodret2; --Se asigna el código del error al campo de la CURP
				LET cCodret = cCodret;
			END IF;
		END IF;
	END IF;					
		RETURN cCodret,cCurp,cCodret3;
	END
	END PROCEDURE
DOCUMENT
' DESCRIPCION: Se modifica SP para que guarde el actualice el curp en la tabla  bdinteg:"informix".si_folioafore',  
' MODIFICO : Mario Gallardo Cardenas',			
' FECHA : 21/03/2013	',
'BD: bdinteg ';

CREATE PROCEDURE "informix".sp_parametrosgralesintegral_pba(pEmpresa CHAR(3),pNumEmpleado CHAR(8))
	RETURNING CHAR(5),CHAR(2),CHAR(2),CHAR(100),CHAR(45),CHAR(30),DATE,CHAR(2),CHAR(11),DATE,DATE,DATE,DATE,DATE,DATE;

	--Declaracion de variables	
    DEFINE cEmpresa		       CHAR(3);	
	DEFINE iSqlErr              INTEGER;
	DEFINE cCodRet              CHAR(5);
	DEFINE cLongitudCliente     CHAR(2);
	DEFINE cCodMonNac           CHAR(2);
	DEFINE cPathRep             CHAR(100);
	DEFINE cNombreUsuario       CHAR(45);
	DEFINE cNombreEmpresa       CHAR(30);
	DEFINE dFecha_Hoy           DATE;
	DEFINE cSistema             CHAR(2);
	DEFINE cLongCta             CHAR(11);
	DEFINE dFecha_ant           DATE;
	DEFINE dProx_fecha           DATE;
	DEFINE dPri_dia_mes          DATE;
	DEFINE dPri_hab_mes          DATE;
	DEFINE dUlt_dia_mes          DATE;
	DEFINE dUlt_hab_mes          DATE;

	--Crea el archivo de monitoreo del proceso
	--SET DEBUG FILE TO "/tmp/sp_ParametrosGralesIntegral.out";
	--TRACE ON;

	--inicializacion de  variables
    LET cEmpresa= '';	
	LET cCodRet= '00000';
	LET cLongitudCliente= '';
	LET cCodMonNac= '';
	LET cPathRep= '';
	LET cNombreUsuario= '';
	LET cNombreEmpresa = '';
	LET dFecha_Hoy = '';
	LET cSistema = '';
	
	LET cLongCta   = 0;
	LET dFecha_ant = '';
	LET dProx_fecha = '';
	LET dPri_dia_mes  = '';
	LET dPri_hab_mes  = '';
	LET dUlt_dia_mes ='';
	LET dUlt_hab_mes ='';
			

	BEGIN
	--Crea el control de errores
		ON EXCEPTION SET iSqlErr
			IF iSqlErr != 0 THEN
				LET cCodRet= iSqlErr;
				RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
			END IF;
		END EXCEPTION;
        
        set isolation to dirty read;
        set lock mode to wait 3;
		
        IF pEmpresa = '' THEN
            LET cCodRet = '00001'; -- PARAMETRO EMPRESA VACIO
           RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;

        IF pNumEmpleado = '' THEN
            LET cCodRet = '00002'; -- PARAMETRO NUMERO EMPLEADO VACIO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		 IF LENGTH(pNumEmpleado) <> 8 THEN		
            LET cCodRet = '00003'; -- PARAMETRO NUMERO DE EMPLEADO NO VALIDO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		SELECT empresa
		INTO cEmpresa
		FROM bdinteg:si_empresas
		WHERE empresa = pEmpresa;

        IF cEmpresa IS NULL OR cEmpresa = '' THEN
            LET cCodRet = '00004'; -- EMPRESA NO EXISTE EN CATALOGO
            RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
        END IF;
		
		--Obtengo el valor longitud del numero de cliente		
		SELECT Trim(valor)
		INTO cLongitudCliente 
		FROM bdinteg:si_param                 
		WHERE empresa = pEmpresa AND cod_param = 7; 

		--Obtengo el valor codigo de la moneda nacional
		SELECT Trim(valor)
		INTO cCodMonNac 
		FROM bdinteg:si_param 
		WHERE empresa = pEmpresa AND descripcion = ('codigo mn');
                

		--Obtengo el valor path de reportes   		
		SELECT Trim(valor) 
		INTO cPathRep               		
		FROM bdinteg:si_param 
		where empresa = pEmpresa and cod_param = 44;
               

		--Obtengo el nombre del usuario o ejecutivo
		SELECT nombre 
		INTO cNombreUsuario
		FROM bdinteg:si_ejecut
		WHERE ejecutivo = pNumEmpleado;
		 
		-- Obtengo el nombre de la empresa
		SELECT razon_social
		INTO cNombreEmpresa
		FROM bdinteg:si_empresas 
		WHERE empresa = pEmpresa;
		
		-- Obtengo la longitud de la Cuenta
		SELECT valor 
		INTO cLongCta
		FROM bdicheq:sc_param 
		WHERE codparam = 'longcta';
		
		-- Obtengo Fecha de integral para la Captura de Parametros	
		SELECT fecha_hoy,fecha_ant,prox_fecha,pri_dia_mes,pri_hab_mes,ult_dia_mes,ult_hab_mes  
		INTO dFecha_Hoy,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes
		FROM bdinteg:si_fechas;

		--Obtengo codigo del sistema
		SELECT sistema
		INTO cSistema
		FROM bdinteg:si_sistema 
		WHERE siglas = 'SI';
		
		
	   IF cNombreUsuario='' OR cNombreUsuario IS NULL THEN
			LET cCodRet = '00005';	   END IF;
		RETURN cCodRet,cLongitudCliente,cCodMonNac,cPathRep,cNombreUsuario,cNombreEmpresa,dFecha_Hoy,cSistema,
					   cLongCta,dFecha_ant,dProx_fecha,dPri_dia_mes,dPri_hab_mes,dUlt_dia_mes,dUlt_hab_mes;
					   
		
	END
	END PROCEDURE
	DOCUMENT
	'DESCRIPCION: Genera una consulta en las tablas si_param, si_ejecut,si_empresas,sc_fechas,si_sistema', 
	'tomando como parametro o dato de entrada, la empresa y el numero de empleado para obtener datos del empleado',	
	'AUTOR: Guadalupe Payan',
	'FECHA: Octubre 2010',
	'VERSION: 201010',	
	'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_repipab_parte1( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
    
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte1.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte1.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte < '002968196'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte < '002968196'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_1.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_11.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_11.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_1.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_12.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_12.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_1.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_13.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_13.sql';
    SYSTEM vstmt;
    */
    
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte10( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte10.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte10.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '023960105'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '023960105'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_10.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_101.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_101.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_10.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_102.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_102.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_10.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_103.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_103.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte2( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte2.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte2.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '002968196'
       AND mae.num_cte < '005997468'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '002968196'
       AND mae.num_cte < '005997468'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_2.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_21.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_21.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_2.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_22.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_22.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_2.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_23.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_23.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte3( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte3.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte3.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '005997468'
       AND mae.num_cte < '008983222'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '005997468'
       AND mae.num_cte < '008983222'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_3.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_31.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_31.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_3.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_32.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_32.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_3.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_33.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_33.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte4( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte4.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte4.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '008983222'
       AND mae.num_cte < '011310863'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '008983222'
       AND mae.num_cte < '011310863'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_4.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_41.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_41.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_4.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_42.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_42.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_4.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_43.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_43.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte5( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte5.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte5.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '011310863'
       AND mae.num_cte < '013632702'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '011310863'
       AND mae.num_cte < '013632702'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_5.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_51.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_51.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_5.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_52.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_52.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_5.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_53.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_53.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte6( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte6.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte6.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '013632702'
       AND mae.num_cte < '016058569'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '013632702'
       AND mae.num_cte < '016058569'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_6.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_61.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_61.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_6.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_62.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_62.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_6.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_63.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_63.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte7( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte7.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte7.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '016058569'
       AND mae.num_cte < '018518929'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '016058569'
       AND mae.num_cte < '018518929'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_7.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_71.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_71.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_7.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_72.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_72.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_7.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_73.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_73.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte8( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte8.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte8.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '018518929'
       AND mae.num_cte < '021145743'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '018518929'
       AND mae.num_cte < '021145743'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_8.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_81.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_81.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_8.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_82.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_82.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_8.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_83.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_83.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_parte9( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
     
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte9.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/ipab/sp_repipab_parte9.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    CREATE TEMP TABLE si_infpertit_tmp 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        Por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_infpattit_tmp 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) WITH NO LOG;
      
    CREATE TEMP TABLE si_ctaasotit_tmp
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) WITH NO LOG;
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '021145743'
       AND mae.num_cte < '023960105'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '021145743'
       AND mae.num_cte < '023960105'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
    
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
    
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT UNIQUE numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax

        BEGIN WORK;
        LET nComit = 1;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            LET nComit = 0;
            COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_tmp VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_tmp VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;

        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_tmp
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_tmp VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        
        LET nComit = 0;
        COMMIT WORK;
    END FOREACH;
    
    /*
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpertit_9.txt '||
               'SELECT * FROM si_infpertit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_91.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_91.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/infpattit_9.txt '||
               'SELECT * FROM si_infpattit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_92.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_92.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/jivan/ipab/ctaasotit_9.txt '||
               'SELECT * FROM si_ctaasotit_tmp;" > /resplogifx/conciliachq/jivan/ipab/desc_ipab_93.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/jivan/ipab/desc_ipab_93.sql';
    SYSTEM vstmt;
    */
     
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE';
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipabinver(pFechaIni DATE, pFechaFin DATE, pNumCliente CHAR(20), pPersona CHAR(2))
RETURNING CHAR(5);

    DEFINE cPfisica, cExento_isr, cRegFiscal, cTipoTasa, cOperArit, cSujRet CHAR(1);
    DEFINE cTpoCuenta, cDivisa CHAR(2);    
    DEFINE cPorcentaje, cInstbase, cSobretasa CHAR(3);   
    DEFINE cNumProducto, cSucursal CHAR(4);
    DEFINE dSdo_PromInv, cPlazo, P_COD_RET, P_COD_RET2 CHAR(5); 
    DEFINE cNumCuenta, cCtaInversion CHAR(20);           
    DEFINE cNomProducto, DESC_ERR, P_COD_RET3 CHAR(40);           
    DEFINE dFechaCorte, dFechaSigCorte, dFechaContratacion DATE;               
    DEFINE sAnio, sCauRev, vexcluido SMALLINT;           
    DEFINE iDias_Proy, iAniobase, SQL_ERR, ISAM_ERR, iDias_Ini INTEGER;
    DEFINE sResiduo DECIMAL(9,3);
    DEFINE dtasa, dPorRetencionSuj, dtasax2 DECIMAL(9,6); 
    DEFINE mISR_Proy, mInt_Proy, mSdo_Inv_Proy, mInt_al_Inicio, mCapital, mSdo_Ini, mSdo_Prom_Ini, dImp_Isr_Ini, mSdo_Prom_Fin MONEY(18,2);

    LET cPfisica           = "";            LET cExento_isr        = "";            LET cRegFiscal         = "N";
    LET cTipoTasa          = "1";           LET cOperArit          = NULL;          LET cSujRet            = "S";
    LET cTpoCuenta         = "CI";          LET cDivisa            = "";            LET cPorcentaje        = NULL;
    LET cInstbase          = NULL;          LET cSobretasa         = NULL;          LET cNumProducto       = "";            
    LET cSucursal          = "";            LET dSdo_PromInv       = NULL;          LET cPlazo             = "";            
    LET P_COD_RET          = "00000";       LET P_COD_RET2         = "00000";       LET cNumCuenta         = "";            
    LET cCtaInversion      = "";            LET cNomProducto       = "";            LET DESC_ERR           = "";            
    LET P_COD_RET3         = "";            LET dFechaCorte        = NULL;          LET dFechaSigCorte     = NULL;          
    LET dFechaContratacion = "01-01-1900";  LET sAnio              = 0;             LET sCauRev            = 0;             
    LET vexcluido          = 0;             LET iDias_Proy         = 0;             LET iAniobase          = 0;             
    LET SQL_ERR            = 0;             LET ISAM_ERR           = 0;             LET iDias_Ini 		   = 0;             
    LET sResiduo           = 0;             LET dtasa              = 0;             LET dPorRetencionSuj   = 0;      
    LET dtasax2            = 0;             LET mISR_Proy          = 0;             LET mInt_Proy          = 0;             
    LET mSdo_Inv_Proy      = 0;             LET mInt_al_Inicio 	   = 0;             LET mCapital           = 0.00;          
    LET mSdo_Ini 		   = 0;             LET mSdo_Prom_Ini 	   = 0;             LET dImp_Isr_Ini 	   = 0;             
    LET mSdo_Prom_Fin 	   = 0;
                      
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipabinver.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipabinver.err';
        TRACE ON;
        LET P_COD_RET = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        RETURN P_COD_RET;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;

    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = "I.S.R." 
       AND fecha = (SELECT max(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = "I.S.R.");

    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    LET dPorRetencionSuj = dPorRetencionSuj / 100;

    FOREACH
        SELECT nvl(cta_cheques, ''), nvl(cuenta, ''), nvl(capital , 0), nvl(cod_instrum, ''), 
               nvl(sucursal, ''), nvl(fecha_alta, '05/01/2007'), nvl(tasa, 0), nvl(plazo, 0)
          INTO cNumCuenta, cCtaInversion, mCapital, cNumProducto, cSucursal, dFechaContratacion, dtasa, cPlazo
          FROM bdinvers:sv_maeinv 
         WHERE num_cte = pNumCliente
           AND fecha_alta <= pFechaIni 
           AND fecha_venc > pFechaIni
           AND ( fec_cancelac > pFechaIni or fec_cancelac is null )
        
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = pPersona;

        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN                
            LET dPorRetencionSuj = 0;
        END IF;   

        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab 
         WHERE numcte = pNumCliente;

        IF vexcluido > 0 THEN
            LET sCauRev = 1;
        ELSE
            LET sCauRev = 0;
        END IF;
        
        LET dtasax2 = dtasa / 100;

        -- // OBTIENE EL NOMBRE DEL PRODUCTO Y LA MONEDA
        SELECT nombre, substring (nvl(moneda, ' ') from 2 for 1)
          INTO cNomProducto, cDivisa
          FROM bdinvers:sv_instrum
         WHERE cod_instrum  = cNumProducto;
        
        -- // OBTIENE SALDO PROYECTADO A AL FECHA FINAL DE LA PROYECCION
        LET mSdo_Prom_Fin = mCapital;
        LET iDias_Proy = (pFechaFin - dFechaContratacion) + 1;
        LET mInt_Proy = (mCapital * dtasax2 * iDias_Proy) / 360;
        
        IF dPorRetencionSuj <> 0 THEN
            LET mISR_Proy = (((mCapital * dPorRetencionSuj) * iDias_Proy) / iAniobase);
        ELSE
            LET mISR_Proy = 0;
        END IF;
        
        IF pFechaIni = pFechaFin THEN
            LET mSdo_Inv_Proy = mCapital + mInt_Proy;
        ELSE
            LET mSdo_Inv_Proy = ( mCapital + mInt_Proy ) - mISR_Proy;
        END IF;

        -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
        INSERT INTO si_infpattit_tmp VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion),  UPPER(cTpoCuenta), UPPER(cRegFiscal), cPorcentaje, 0, UPPER(cNomProducto), UPPER(cSucursal), 
          NVL(mSdo_Inv_Proy,0), UPPER(cDivisa), dFechaCorte, dFechaContratacion, cPlazo, cTipoTasa, NVL(dtasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigCorte, 
          dSdo_PromInv, iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDias_Proy, mCapital, mSdo_Prom_Fin, mInt_Proy, mISR_Proy );

        -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
        INSERT INTO si_ctaasotit_tmp VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion), UPPER(pNumCliente), 100.00 );
    END FOREACH;

    RETURN P_COD_RET;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_direc_pte1( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
    
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad, vcomienza SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia, vcont_commit INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;       LET vcomienza = -1;             LET vcont_commit = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipab_direc_pte1.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipab_direc_pte1.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpertit_pte1') THEN
        DROP TABLE si_infpertit_pte1;
    END IF;
    
    CREATE TABLE si_infpertit_pte1 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) 
    EXTENT SIZE 1500000 NEXT SIZE 150000 LOCK MODE ROW;
      
    /* ###############################################################################################################
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpattit_pte1') THEN
        DROP TABLE si_infpattit_pte1;
    END IF;
    
    CREATE TABLE si_infpattit_pte1 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) 
    EXTENT SIZE 1500000 NEXT SIZE 150000 LOCK MODE ROW;
    ############################################################################################################### */
      
    /* ###############################################################################################################
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_ctaasotit_pte1') THEN
        DROP TABLE si_ctaasotit_pte1;
    END IF;
    
    CREATE TABLE si_ctaasotit_pte1
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) 
    EXTENT SIZE 500000 NEXT SIZE 50000 LOCK MODE ROW;
    CREATE INDEX idx_ctaaso_1 ON si_ctaasotit_pte1 (cve_unica) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE si_ctaasotit_pte1;
    ############################################################################################################### */
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte < '008981511'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte < '008981511'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
     
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
     
    /* ###############################################################################################################################################################
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    ############################################################################################################################################################### */
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax
        
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET nComit = 1;
        END IF;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
            LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
            LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
        END IF;
        
        IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
            LET cColonia = TRIM(cNomCiudadCte);
        END IF;
        
        IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
            LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
        END IF;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
        
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
                LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
            END IF;
            
            IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
                LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
            END IF;
            
            IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
                LET cColonia = TRIM(cNomCiudadCte);
            END IF;
            
            IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
                LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
            END IF;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
               ( cColonia is null OR cColonia = '' ) OR 
               ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
               ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
               
                SELECT dir.numerocalle AS no_calle,
                       TRIM(dir.numeroextcalle) AS no_ext_calle,     
                       TRIM(dir.cod_postal) AS cod_postal,         
                       TRIM(tel1.telefono) AS tel_casa,       
                       TRIM(tel2.telefono) AS tel_casa2,      
                       TRIM(tel3.telefono) AS tel_casa3,
                       dir.numerociudad AS no_ciudad,
                       dir.numerocolonia AS no_colonia,
                       dir.estado AS no_estado,
                       dir.pais AS no_pais
                  INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa6, cTelefonoCasa7, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                  FROM bdinteg:si_direcciones_actual dir 
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                  LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                 WHERE dir.numcte = cNumCliente
                   AND dir.tipo_dir = '3';
                   
                IF iNumeroCalle = 644537 THEN
                    LET iNumeroCalle = 134176;
                END IF;
                
                SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                  INTO cNombreCalle
                  FROM bdinteg:si_catcalles calle
                 WHERE calle.numerocalle = iNumeroCalle;
                 
                SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                       CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                       zon.codigopostalzona AS cod_postal2
                  INTO cColonia, cDelegacionMunicipio, cCodPostal2
                  FROM bdinteg:si_catzonas zon 
                 WHERE zon.numerociudad = iNumCiudad
                   AND zon.numerocolonia = iNumColonia;
                   
                SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                  INTO cNomCiudadCte
                  FROM bdinteg:si_catciudades ciudad 
                 WHERE ciudad.numerociudad = iNumCiudad;
                 
                IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
                    LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
                END IF;
                
                IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
                    LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
                END IF;
                
                IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
                    LET cColonia = TRIM(cNomCiudadCte);
                END IF;
                
                IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
                    LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
                END IF;
                 
                SELECT TRIM(edo.siglas) AS estado
                  INTO cEstado
                  FROM bdinteg:si_estadosipab edo 
                 WHERE edo.estado = cNoEstado;
                 
                SELECT TRIM(pai.nombre) AS nom_pais
                  INTO cPais
                  FROM bdinteg:si_paises pai 
                 WHERE pai.pais = cNoPais;
                 
                IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
                   ( cColonia is null OR cColonia = '' ) OR 
                   ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
                   ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
                   
                    SELECT dir.numerocalle AS no_calle,
                           TRIM(dir.numeroextcalle) AS no_ext_calle,     
                           TRIM(dir.cod_postal) AS cod_postal,         
                           TRIM(tel1.telefono) AS tel_casa,       
                           TRIM(tel2.telefono) AS tel_casa2,      
                           TRIM(tel3.telefono) AS tel_casa3,
                           dir.numerociudad AS no_ciudad,
                           dir.numerocolonia AS no_colonia,
                           dir.estado AS no_estado,
                           dir.pais AS no_pais
                      INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
                      FROM bdinteg:si_direcciones_actual dir 
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                      LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
                     WHERE dir.numcte = cNumCliente
                       AND dir.tipo_dir = '1';
                       
                    IF iNumeroCalle = 644537 THEN
                        LET iNumeroCalle = 134176;
                    END IF;
                    
                    SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
                      INTO cNombreCalle
                      FROM bdinteg:si_catcalles calle
                     WHERE calle.numerocalle = iNumeroCalle;
                     
                    SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                           CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                           zon.codigopostalzona AS cod_postal2
                      INTO cColonia, cDelegacionMunicipio, cCodPostal2
                      FROM bdinteg:si_catzonas zon 
                     WHERE zon.numerociudad = iNumCiudad
                       AND zon.numerocolonia = iNumColonia;
                       
                    SELECT TRIM(ciudad.nombreciudad) AS nomciudad
                      INTO cNomCiudadCte
                      FROM bdinteg:si_catciudades ciudad 
                     WHERE ciudad.numerociudad = iNumCiudad;
                     
                    IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
                        LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
                    END IF;
                    
                    IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
                        LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
                    END IF;
                    
                    IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
                        LET cColonia = TRIM(cNomCiudadCte);
                    END IF;
                    
                    IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
                        LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
                    END IF;
                     
                    SELECT TRIM(edo.siglas) AS estado
                      INTO cEstado
                      FROM bdinteg:si_estadosipab edo 
                     WHERE edo.estado = cNoEstado;
                     
                    SELECT TRIM(pai.nombre) AS nom_pais
                      INTO cPais
                      FROM bdinteg:si_paises pai 
                     WHERE pai.pais = cNoPais;
                END IF;
            END IF;
        END IF;
        
        /* ###################################################################
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' THEN
            LET cDelegacionMunicipio = cColonia;
        END IF;
        ################################################################### */
                    
        SELECT COUNT(*) 
          INTO iExisteCodPos
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = cCodPostal;
         
        IF iExisteCodPos > 0 THEN
            LET cTipoCodPos = 'DIRECCION';
        ELSE
            SELECT COUNT(*) 
              INTO iExisteCodPos
              FROM bdinteg:si_catsepomex
             WHERE d_codigo = cCodPostal2;
             
            IF iExisteCodPos > 0 THEN
                LET cTipoCodPos = 'CATZONAS';
                LET cCodPostal = cCodPostal2;
            ELSE
                /* #################################
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM tmp_cuentas_ipab
                 WHERE num_cte = cNumCliente;
                ################################# */
                
                SELECT LIMIT 1 sucursal
                  INTO vSucCta
                  FROM bdicheq:sc_maechq
                 WHERE num_cte = cNumCliente
                   AND status_cta <> '2';
                 
                SELECT d_codigo
                  INTO cCodPostal
                  FROM bdinteg:si_sucursales
                 WHERE sucursal = vSucCta;
                 
                LET cTipoCodPos = 'SUCURSAL';
            END IF;
        END IF;
        
        -- // VALIDA SI SE OBTUVO EL TELEFONO DEL CLIENTE
        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
            LET cTelefonoCasa = cTelefonoCasa2;
            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                LET cTelefonoCasa = cTelefonoCasa3;
                IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                    LET cTelefonoCasa = cTelefonoCasa4;
                    IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                        LET cTelefonoCasa = cTelefonoCasa5;
                        IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                            LET cTelefonoCasa = cTelefonoCasa6;
                            IF cTelefonoCasa is null OR cTelefonoCasa = '' THEN
                                LET cTelefonoCasa = cTelefonoCasa7;
                                IF cTelefonoCasa = '' OR cTelefonoCasa is null THEN
                                    LET cTelefonoCasa = NULL;
                                END IF;
                            END IF;
                        END IF;
                    END IF;
                END IF;
            END IF;
        END IF;
        
        -- // OBTIENE EL TIPO DE CLIENTE
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = cPersona;

        IF cPfisica = 'S' THEN
            LET cTipoPersona = 'F';
        ELSE
            LET cTipoPersona = 'M';
            LET cApellido1 = NULL;
            LET cApellido2 = NULL;
        END IF;
        
        IF cTipoPersona IS NULL THEN
            --- LET nComit = 0;
            --- COMMIT WORK;
            CONTINUE FOREACH;
        END IF;

        -- // VALIDA SI ES EXENTO DE ISR
        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN
            LET dPorRetSuj = 0;
        ELSE
            LET dPorRetSuj = dPorRetencionSuj;
        END IF;
        
        -- // VALIDA DATOS
        IF cApellido2 = '' THEN
            LET cApellido2 = NULL;
        END IF;

        IF cCurp = '' OR LENGTH(cCurp) = 0 THEN
            LET cCurp = NULL;
        END IF;
        
        IF LENGTH(cCorreo) = 0 THEN
            LET cCorreo = NULL;
        END IF;

        -- // VALIDA SI EL CLIENTE ES EXCLUIDO DEL IPAB
        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab
         WHERE numcte = cNumCliente;

        IF vexcluido = 0 THEN
            LET sCauRev = 0;
        ELSE
            LET sCauRev = 1;
        END IF;
        
        /* ###############################################################################################################################################################
        -- // FOREACH CUENTAS POR CLIENTE
        FOREACH
            SELECT cuenta, producto, sucursal, fecha_alta, nombre_prod, moneda, tasa, paga_dividendo
              INTO cNumCuenta, cNumProducto, cSucursal, dFecAlta, cproducto, cMoneda, ctasa, vtasavar
              FROM tmp_cuentas_ipab
             WHERE num_cte = cNumCliente

            IF dFecAlta < pFechaIni THEN
                SELECT COUNT(*)
                  INTO vaniomes
                  FROM bdicheq:sc_maehis
                 WHERE empresa = '001'
                   AND cuenta = cNumCuenta
                   AND fechafin <= pFechaIni;

                IF vaniomes = 0 THEN
                    -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    LET iDias_Ini = (pFechaIni - dFecAlta);

                    -- // TIPO DE TASA DEL PRODUCTO
                    SELECT rangofecha
                      INTO vrangofecha
                      FROM bdinteg:si_tiptasa
                     WHERE empresa = '001'
                       AND tasa = ctasa;

                    -- // VALOR DE LA TASA
                    IF vtasavar = 'N' THEN
                        IF vrangofecha = 'F' THEN
                            SELECT NVL(valor,0)
                              INTO dTasa
                              FROM bdinteg:si_fechavalor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND fecha = ( SELECT max(fecha)
                                               FROM bdinteg:si_fechavalor
                                              WHERE empresa = '001'
                                                AND tasa = ctasa
                                                AND fecha <= pFechaIni );
                        ELIF vrangofecha = 'R' THEN
                            IF cTipoPersona = 'F' THEN
                                SELECT valorperfis, sobretasafis
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            ELSE
                                SELECT valorpermor, sobretasamor
                                  INTO porcentaje, puntos
                                  FROM bdinteg:si_tasavlor
                                 WHERE empresa = '001'
                                   AND tasa = ctasa
                                   AND rangomin <= mSdo_Ini
                                   AND rangomax >= mSdo_Ini;
                            END IF;
                            LET dTasa = porcentaje + puntos;
                        END IF;
                    ELSE
                        SELECT NVL(valor_tasa,0)
                          INTO dTasa
                          FROM bdinteg:si_tasa_mes
                         WHERE tasa = ctasa
                           AND mes = 1
                           AND tipo_tasa = 'M'
                           AND fecha = ( SELECT MAX(fecha)
                                           FROM bdinteg:si_tasa_mes
                                          WHERE tasa = ctasa
                                            AND mes = 1
                                            AND tipo_tasa = 'M'
                                            AND fecha <= pFechaIni );
                    END IF;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                        IF dPorRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    LET vFecAlta = dFecAlta - 1;
                    
                    EXECUTE PROCEDURE bdinteg:sp_cortesig(vFecAlta, 1) 
                    INTO cVar1,dFechaSigcorte;
                    
                    LET dFechaCorte = dFechaSigcorte;
                ELSE
                    -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                    SELECT NVL(his.tasabruta, 0), his.fechafin
                      INTO dTasa, dFechaCorte
                      FROM bdicheq:sc_maehis his
                     WHERE his.empresa = '001'
                       AND his.cuenta = cNumCuenta
                       AND his.aniomes = (SELECT MAX(aniomes)
                                            FROM bdicheq:sc_maehis
                                           WHERE empresa = '001'
                                             AND cuenta = cNumCuenta
                                             AND fechafin <= pFechaIni);
                                             
                    LET dTasa = dTasa * 100;
                    
                    LET iDias_Ini = (pFechaIni - dFechaCorte);

                    IF iDias_Ini > 0 THEN
                        -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                            LET vFechaCorte = dFechaCorte + 1;
                            LET mSdo_Prom_Ini = mSdo_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                            
                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    ELIF iDias_Ini = 0 THEN
                        -- // OBTIENE EL SALDO DE LA CUENTA
                        EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                        INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                        
                        IF mSdo_Ini >= 0 THEN
                            LET mSdo_Prom_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                            -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                            LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                            LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                            IF dPorRetSuj <> 0 THEN
                                IF cTipoPersona = 'F' THEN
                                    IF mBase_gravable > 0 THEN
                                        LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                    ELSE
                                        LET dImp_Isr_Fin = 0;
                                    END IF;
                                ELSE
                                    LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;

                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                        ELSE
                            LET mSdo_Prom_Ini = mSdo_Ini;
                            LET mInt_al_Inicio = 0.00;
                            LET dImp_Isr_Ini = 0.00;
                            LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                            LET mSdo_Prom_Fin = mSdo_Fin;
                            LET mInt_Proyec = 0.00;
                            LET dImp_Isr_Fin = 0.00;
                            LET mSdo_Promedio = mSdo_Prom_Fin;
                            LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                        END IF;
                    END IF;

                    -- // OBTIENE LA PROXIMA FECHA DE CORTE
                    EXECUTE PROCEDURE bdinteg:sp_CorteSig(dFechaCorte, 1) 
                    INTO cVar1, dFechaSigcorte;
                END IF;
            ELIF dFecAlta = pFechaIni THEN
                -- // OBTIENE EL SALDO DE LA CUENTA
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO vCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = 0;
                
                -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO vrangofecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // OBTIENE EL VALOR DE LA TASA
                IF vtasavar = 'N' THEN
                    IF vrangofecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha)
                                           FROM bdinteg:si_fechavalor
                                          WHERE empresa = '001'
                                            AND tasa = ctasa
                                            AND fecha <= pFechaIni );
                    ELIF vrangofecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO porcentaje, puntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = porcentaje + puntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha)
                                       FROM bdinteg:si_tasa_mes
                                      WHERE tasa = ctasa
                                        AND mes = 1
                                        AND tipo_tasa = 'M'
                                        AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = 0.00;
                    LET dImp_isr_ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini;
                    LET mSdo_Prom_Fin = mSdo_Fin;

                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - mbase_exenta;

                    IF dPorRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (dPorRetSuj/100)) * iDiasProyec / iAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET vFecAlta = dFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(vFecAlta, 1) 
                INTO cVar1, dFechaSigcorte;
                
                LET dFechaCorte = dFechaSigcorte;
            END IF;
            
            IF pFechaFin = pFechaIni THEN
                LET mSdo_Fin = 0.00;
                LET mSdo_Prom_Fin = 0.00;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
            END IF;
            
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_pte1 VALUES
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cTpoCuenta), 'N', cPorcentaje, '0', UPPER(cproducto), UPPER(cSucursal), NVL(mSdo_Proyec,0),
              UPPER(cMoneda), dFechaCorte, cFecAlt, cPlazo, sTipoTasa, NVL(dTasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigcorte, NVL(mSdo_Promedio,0),
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );

            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_pte1 VALUES 
            ( UPPER(cNumCuenta), iCtaInversion, UPPER(cNumCliente), '100.00' );
        END FOREACH;
        ############################################################################################################################################################### */
        
        /* ###############################################################################################################################################################
        -- // VERIFICA SI EL CLIENTE TIENE PAGARES PARA REPORTARLOS
        EXECUTE PROCEDURE bdinteg:sp_repipabinver(pFechaIni, pFechaFin, cNumCliente, cPersona) 
        INTO P_COD_RET;

        IF P_COD_RET <> '00000' THEN
            RETURN P_COD_RET,cNom1,cNom2,cNom3;
        END IF;
        ############################################################################################################################################################### */

        -- // INSERTA INFORMACION PERSONAL DEL CLIENTE
        /* ###############################################################################################################################################################
        SELECT COUNT(*)
          INTO vcve_unica
          FROM si_ctaasotit_pte1
         WHERE cve_unica = cNumCliente;
         
        IF dPorRetSuj = 0 THEN
            LET dPorRetSuj = NULL;
        END IF;

        IF vcve_unica > 0 THEN
            INSERT INTO si_infpertit_pte1 VALUES
            ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
              cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
        END IF;
        ############################################################################################################################################################### */
        
        INSERT INTO si_infpertit_pte1 VALUES
        ( cNumCliente, cTipoPersona, Trim(cNombre1), cApellido1, cApellido2, cNombreCalle, cColonia, cDelegacionMunicipio,
          cNomCiudadCte, cCodPostal, cTipoCodPos, cPais, cEstado, cSujRet, dPorRetSuj, sCauRev, cRfc, cCurp, cTelefonoCasa, cCorreo );
          
        LET vcont_commit = vcont_commit + 1;
        
        IF vcont_commit >= 5000 THEN
            LET vcont_commit = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        --- LET nComit = 0;
        --- COMMIT WORK;
    END FOREACH;
    
    IF nComit = 1 THEN
        LET nComit = 0;
        COMMIT WORK;
    END IF;
    
    CREATE INDEX idx_infpertit1_cve ON si_infpertit_pte1(cve_unica) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS MEDIUM FOR TABLE si_infpertit_pte1;
    
    -- // DESCARGA DE ARCHIVOS
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/infpertit_1.txt '||
               'SELECT * FROM si_infpertit_pte1;" > /resplogifx/conciliachq/desc_ipab_11.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/desc_ipab_11.sql';
    SYSTEM vstmt;
    
    /* ###############################################################################################################################################################
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/infpattit_1.txt '||
               'SELECT * FROM si_infpattit_pte1;" > /resplogifx/conciliachq/desc_ipab_12.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/desc_ipab_12.sql';
    SYSTEM vstmt;
    
    LET vsql = 'echo "UNLOAD TO /resplogifx/conciliachq/ctaasotit_1.txt '||
               'SELECT * FROM si_ctaasotit_pte1;" > /resplogifx/conciliachq/desc_ipab_13.sql';
    SYSTEM vsql;
    
    LET vstmt = 'dbaccess bdinteg /resplogifx/conciliachq/desc_ipab_13.sql';
    SYSTEM vstmt;
    ############################################################################################################################################################### */
    
    RETURN P_COD_RET, 'PROCESO', 'REALIZADO', 'CORRECTAMENTE'; 
    
    END; 
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repipab_direc_pte2( pFechaIni DATE, pFechaFin DATE ) 
RETURNING CHAR(5), CHAR(40), CHAR(40), CHAR(40);
    
    DEFINE cOperArit, cTipoPersona, cPfisica, cExento_isr, cSujRet, vtasavar, vrangofecha CHAR(1);          
    DEFINE cPersona, cTpoCuenta, cMoneda, cMes, cDia, canio, cVar1, cNoEstado CHAR(2);                                                 
    DEFINE cInstbase, cPorcentaje, cSobretasa, cNoPais CHAR(3);                                                                        
    DEFINE cNumProducto, cSucursal, vSucCta CHAR(4);                                                                                   
    DEFINE P_COD_RET, P_COD_RET2, cPlazo, cCodPostal, vCodRetSdos CHAR(5);                                                             
    DEFINE cCodPostal2 CHAR(6);                                                                                                         
    DEFINE cTasa, cFecAlt, cFechaNomArc, cTipoCodPos, cNumExtCalle CHAR(10);                                                            
    DEFINE cRfc, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, cTelefonoCasa4, cTelefonoCasa5, cTelefonoCasa6, cTelefonoCasa7 CHAR(13);
    DEFINE cCurp CHAR(18);                                                                                                              
    DEFINE cNumCuenta, cNumCliente, cPais, vctemin, vctemax CHAR(20);                                                                   
    DEFINE cDelegacionMunicipio, cEstado CHAR(25);                                                                                      
    DEFINE cNombre1, cApellido1, cApellido2 CHAR(26);                                                                                   
    DEFINE cNombreCalle, cColonia, cNomCiudadCte CHAR(30);                                                                              
    DEFINE cNom1, cNom2, cNom3 CHAR(40);                                                                                                
    DEFINE cProducto, cCorreo, P_COD_RET3, DESC_ERR CHAR(50);                                                                           
    DEFINE vstmt CHAR(100);                                                                                                             
    DEFINE vsql CHAR(200);                                                                                                              
    DEFINE dFechaCorte, dFechaSigcorte, dFecAlta, vFecAlta, vFechaCorte, vfecha_hoy DATE;                                               
    DEFINE sCauRev, sTipoTasa, dNumsmdf, sAnio, vcve_unica, vexcluido, vexiste, vaniomes, iExisteCodPos, iNumCiudad, vcomienza SMALLINT;           
    DEFINE iCtaInversion, iAniobase, nComit, SQL_ERR, ISAM_ERR, iDias_Ini, iDiasProyec, vcontador, vcontador2, iNumeroCalle, iNumColonia, vcont_commit INTEGER;
    DEFINE sResiduo DECIMAL(6,2);                                                                                                           
    DEFINE dPorRetencionSuj, dPorRetSuj, dTasa, dSmdf, porcentaje, puntos DECIMAL(9,6);                                                                       
    DEFINE dImp_isr DECIMAL(14,6);                                                                                                          
    DEFINE mInt_al_Inicio, mbase_gravable, mbase_exenta, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2);                                
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2);                              
    
    LET cOperArit = NULL;           LET cTipoPersona = '';          LET cPfisica = '';              LET cExento_isr = '';           LET cSujRet = 'S';  
    LET vtasavar  = '';             LET vrangofecha  = '';          LET cPersona = '';              LET cTpoCuenta = 'CI';          LET cMoneda = '';       
    LET cMes = '';                  LET cDia = '';                  LET canio = '';                 LET cVar1 =  '';                LET cInstbase = NULL;           
    LET cPorcentaje = NULL;         LET cSobretasa = NULL;          LET cNumProducto = '';          LET cSucursal = '';             LET vSucCta = '';
    LET P_COD_RET = '00000';        LET P_COD_RET2 = '00000';       LET cPlazo = NULL;              LET cCodPostal =  '';           LET cCodPostal2 = '';           
    LET cTasa = '';                 LET cFecAlt = NULL;             LET cFechaNomArc = '';          LET cTipoCodPos = '';           LET cNumExtCalle = '';          
    LET cRfc = '';                  LET cTelefonoCasa = '';         LET cTelefonoCasa2 = '';        LET cTelefonoCasa3 = '';        LET cTelefonoCasa4 = '';        
    LET cTelefonoCasa5 = '';        LET cTelefonoCasa6 = '';        LET cTelefonoCasa7 = '';        LET cCurp = '';                 LET cNumCuenta = '';            
    LET cNumCliente =  '';          LET cPais = '';                 LET vctemin = '';               LET vctemax = '';               LET cDelegacionMunicipio = '';  
    LET cEstado =  '';              LET cNombre1 =  '';             LET cApellido1 =  '';           LET cApellido2 =  '';           LET cNombreCalle =  '';         
    LET cColonia =  '';             LET cNomCiudadCte = '';         LET cnom1 = '';                 LET cnom2 = '';                 LET cnom3 = '';                 
    LET cProducto = '';             LET cCorreo = '';               LET P_COD_RET3 = '';            LET DESC_ERR = '';              LET vstmt = '';                 
    LET vsql = '';                  LET dFechaCorte = '';           LET dFechaSigcorte =  '';       LET dFecAlta = '';              LET vFecAlta = '';              
    LET vFechaCorte = '';           LET vfecha_hoy = '';            LET sCauRev = '';               LET sTipoTasa = 1;              LET dNumsmdf = 0;               
    LET sAnio = 0;                  LET vcve_unica = 0;             LET vexcluido = 0;              LET vexiste = 0;                LET vaniomes = 0;               
    LET iExisteCodPos = '';         LET iCtaInversion = 0;          LET iAniobase = 0;              LET nComit = 0;                 LET SQL_ERR = 0;                
    LET ISAM_ERR = 0;               LET iDias_Ini = 0;              LET iDiasProyec = 0;            LET vcontador = 0;              LET vcontador2 = 0;             
    LET iNumeroCalle = 0;           LET sResiduo = 0;               LET dPorRetSuj = 0;             LET dTasa = 0;                  LET dSmdf = 0;                  
    LET porcentaje = 0;             LET puntos = 0;                 LET dImp_isr = 0;               LET mInt_al_Inicio = 0;         LET mbase_gravable = 0;         
    LET mbase_exenta = 0;           LET mInt_Proyec = 0;            LET mSdo_Proyec = 0;            LET dImp_Isr_Ini = 0;           LET mSdo_Prom_Ini = 0;          
    LET mSdo_Fin = 0;               LET dImp_Isr_Fin = 0;           LET mSdo_Ini = 0;               LET mSdo_Prom_Fin = 0;	        LET mSdo_Promedio = 0;          
    LET mSdo_31 = 0.00;             LET mInt_31 = 0.00;             LET iNumCiudad = 0;             LET iNumColonia = 0;            LET cNoEstado = ''; 
    LET cNoPais = '';               LET vCodRetSdos = '';           LET dPorRetencionSuj = 0;       LET vcomienza = -1;             LET vcont_commit = 0;
        
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipab_direc_pte2.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/sp_repipab_direc_pte2.err';
        TRACE ON;
        LET P_COD_RET  = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        LET cNumCliente = cNumCliente;
        LET cNumCuenta = cNumCuenta;
        IF nComit = 1 THEN
            ROLLBACK WORK;
        END IF;
        RETURN P_COD_RET,cNom1,cNom2,cNom3;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA DATOS DE ENTRADA (DATOS INCOMPLETOS)
    IF (pFechaIni = '') OR (pFechaFin = '') THEN
        RETURN '110','Las fechas ','no pueden ','ser nulas ';
    END IF;

    -- // VALIDA DATOS DE ENTRADA (FECHAS INCORRECTAS)
    IF pFechaFin < pFechaIni THEN
        RETURN '100', 'Fecha Proyeccion ', 'menor a la ', 'fecha de inicio';
    END IF;
    
    -- // CREACION DE TABLAS TEMPORALES
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpertit_pte2') THEN
        DROP TABLE si_infpertit_pte2;
    END IF;
    
    CREATE TABLE si_infpertit_pte2 
      (
        cve_unica       CHAR(10),   
        persona         CHAR(1),    
        nombre          CHAR(100),  
        apell_paterno   CHAR(40),   
        apell_materno   CHAR(40),   	
        callenum        CHAR(75),   
        colonia         CHAR(30),   
        delmun          CHAR(30),   
        ciudad          CHAR(30),	
        cod_postal      CHAR(5),  
        tipo_codpos     CHAR(10),
        pais            CHAR(50),   
        estado          CHAR(4),    
        suj_retencion   CHAR(1),    
        por_retencion   CHAR(4),    
        causal_rev      SMALLINT,		
        rfc             CHAR(13),   
        curp            CHAR(18),   
        telefonos       CHAR(30),	
        correo          CHAR(50) 
      ) 
    EXTENT SIZE 1500000 NEXT SIZE 150000 LOCK MODE ROW;
      
    /* ###############################################################################################################
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpattit_pte2') THEN
        DROP TABLE si_infpattit_pte2;
    END IF;
    
    CREATE TABLE si_infpattit_pte2 
      (
        numcta		    CHAR(20),       
        num_inversion	CHAR(20),       
        tipo_cta		CHAR(2),		
        reg_fiscal		CHAR(1),        
        por_retencion   CHAR(3),        
        causal_rev      SMALLINT,		
        nomprod     	CHAR(50),   	
        cve_sucursal    CHAR(7),        
        sdo_cuenta      MONEY(14,2),	
        moneda          CHAR(2),        
        fecha_corte     DATE,       	
        fecha_contra    DATE,           
        plazo_opera     CHAR(5),        
        tipo_tasa       SMALLINT,       
        tasa        	DECIMAL(9,6),	
        inst_base       CHAR(3),        
        puntos_porc     CHAR(3),        
        operador        CHAR(1),		
        fecha_sigcorte  DATE,       	
        sdo_promdiario  MONEY(14,2),
        dias_ini	    INTEGER,        
        saldo_ini	    MONEY(14,2),    
        prom_ini	    MONEY(14,2),	
        intereses_ini   MONEY(14,2),    
        isr_ini		    MONEY(14,2),
        dias_fin        INTEGER,        
        saldo_fin       MONEY(14,2),	
        prom_fin	    MONEY(14,2),	
        intereses_fin   MONEY(14,2),    
        isr_fin         MONEY(14,2) 
      ) 
    EXTENT SIZE 1500000 NEXT SIZE 150000 LOCK MODE ROW;
    ############################################################################################################### */
      
    /* ###############################################################################################################
    IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_ctaasotit_pte2') THEN
        DROP TABLE si_ctaasotit_pte2;
    END IF;
    
    CREATE TABLE si_ctaasotit_pte2
      (
        numcta          CHAR(20),    
        num_inversion   CHAR(20),     
        cve_unica       CHAR(10),     
        porcentaje_tit  DECIMAL(6,2)
      ) 
    EXTENT SIZE 500000 NEXT SIZE 50000 LOCK MODE ROW;
    CREATE INDEX idx_ipab_ctaaso ON si_ctaasotit_pte2 (cve_unica) USING BTREE;
    UPDATE STATISTICS MEDIUM FOR TABLE si_ctaasotit_pte2;
    ############################################################################################################### */
    
    -- // FECHA DEL SISTEMA
    SELECT fecha_hoy
      INTO vfecha_hoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';

    -- // VALOR DEL ISR / 100 LISTO PARA CALCULOS
    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = 'I.S.R.'
       AND fecha = (SELECT MAX(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = 'I.S.R.');

    -- // CALCULO DE MONTO BASE EXENTO ISR
    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    -- // SALARIO MINIMO
    SELECT valor
      INTO dSmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'smdf';

    -- // NUMERO DE VECES PARA EL SALARIO MINIMO
    SELECT valor
      INTO dNumsmdf
      FROM bdicheq:sc_param
     WHERE empresa = '001'
       AND codparam = 'numsmdf';

    -- // BASE EXENTA DE IMPUESTO DE ISR PARA PF
    LET mBase_exenta = dSmdf * dNumsmdf * iAniobase;

    IF mBase_exenta IS NULL THEN
        LET mbase_exenta = 0;
    END IF;
    
    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);

    -- // TABLA TEMPORAL DE CLIENTES
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND mae.num_cte >= '008981511'
       AND mae.num_cte < '016061345'
     UNION ALL
    SELECT cte.numcte
      FROM bdinteg:si_cliente cte,
           bdicheq:sc_maechq mae
     WHERE cte.numcte = mae.num_cte
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND mae.producto = '1100'
       AND mae.fecultdep <= pFechaIni
       AND mae.num_cte >= '008981511'
       AND mae.num_cte < '016061345'
      INTO TEMP tmp_clientes WITH NO LOG;
    CREATE INDEX idxtmp_ctes ON tmp_clientes(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes;
     
    SELECT UNIQUE numcte
      FROM tmp_clientes
      INTO TEMP tmp_clientes_ipab WITH NO LOG;
    CREATE INDEX idxtmp_ctesipab ON tmp_clientes_ipab(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_clientes_ipab;
     
    /* ###############################################################################################################################################################
    -- // TABLA TEMPORAL DE CUENTAS
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(noc.fecha_alta,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_maenoc noc,
           bdicheq:sc_producto prod
     WHERE tmp.numcte = mae.num_cte
       AND mae.producto NOT IN('1100','2300','2800','9900','9901')
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6','8') )
       AND noc.empresa = mae.empresa
       AND noc.cuenta = mae.cuenta
       AND noc.fecha_alta <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
     UNION ALL
    SELECT tmp.numcte AS num_cte, mae.cuenta AS cuenta, mae.producto AS producto, mae.sucursal AS sucursal, 
           NVL(mae.fecultdep,'') fecha_alta, prod.nombre nombre_prod, SUBSTRING(nvl(prod.divisa, ' ') FROM 2 FOR 1) moneda, NVL(tasa, '') tasa, paga_dividendo
      FROM tmp_clientes_ipab tmp,
           bdicheq:sc_maechq mae,
           bdicheq:sc_producto prod
     WHERE tmp.numcte <> ''
       AND mae.num_cte = tmp.numcte
       AND mae.producto = '1100'
       AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('4','5','6') )
       AND mae.fecultdep <= pFechaIni
       AND prod.empresa = mae.empresa
       AND prod.producto = mae.producto
      INTO TEMP tmp_cuentas_ipab WITH NO LOG;
    CREATE INDEX idx_ctas ON tmp_cuentas_ipab(num_cte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_cuentas_ipab;
    ############################################################################################################################################################### */
    
    SELECT MIN(numcte), MAX(numcte)
      INTO vctemin, vctemax
      FROM tmp_clientes_ipab; 

    -- // FOREACH CLIENTES
    FOREACH WITH HOLD
        SELECT numcte
          INTO cNumCliente
          FROM tmp_clientes_ipab
         WHERE numcte BETWEEN vctemin AND vctemax
        
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            BEGIN WORK;
            LET nComit = 1;
        END IF;
        
        -- // OBTIENE DATOS PERSONALES DEL CLIENTE
        SELECT TRIM(cte.rfc) AS rfc,                                                          
               TRIM(cte.tpo_persona) AS personalidad,                                         
               TRIM(cte.nombre1)||' '||TRIM(cte.nombre2) || Trim(cte.razon_social) AS nombre, 
               TRIM(cte.apell_paterno) AS apellpaterno,                                       
               TRIM(cte.apell_materno) AS apellmaterno,                                       
               TRIM(ctepf.curp) AS curp                                                                       
          INTO cRfc, cPersona, cNombre1, cApellido1, cApellido2, cCurp
          FROM bdinteg:si_cliente cte
          LEFT OUTER JOIN bdinteg:si_ctepf ctepf ON (ctepf.numcte = cte.numcte)
         WHERE cte.numcte = cNumCliente;
         
        SELECT LIMIT 1 correo_elec AS correo_electronico
          INTO cCorreo  
          FROM bdinteg:si_correos
         WHERE numcte = cNumCliente
           AND tipo_correo = 1
           AND status_correo = 'A';
         
        -- // OBTIENE DIRECCIÓN DEL CLIENTE
        SELECT dir.numerocalle AS no_calle,
               TRIM(dir.numeroextcalle) AS no_ext_calle,     
               TRIM(dir.cod_postal) AS cod_postal,         
               TRIM(tel1.telefono) AS tel_casa,       
               TRIM(tel2.telefono) AS tel_casa2,      
               TRIM(tel3.telefono) AS tel_casa3,
               dir.numerociudad AS no_ciudad,
               dir.numerocolonia AS no_colonia,
               dir.estado AS no_estado,
               dir.pais AS no_pais
          INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa2, cTelefonoCasa3, iNumCiudad, iNumColonia, cNoEstado, cNoPais
          FROM bdinteg:si_direcciones_actual dir 
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
         WHERE dir.numcte = cNumCliente
           AND dir.tipo_dir = '1';
           
        IF iNumeroCalle = 644537 THEN
            LET iNumeroCalle = 134176;
        END IF;
        
        SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
          INTO cNombreCalle
          FROM bdinteg:si_catcalles calle
         WHERE calle.numerocalle = iNumeroCalle;
         
        SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
               CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
               zon.codigopostalzona AS cod_postal2
          INTO cColonia, cDelegacionMunicipio, cCodPostal2
          FROM bdinteg:si_catzonas zon 
         WHERE zon.numerociudad = iNumCiudad
           AND zon.numerocolonia = iNumColonia;
           
        SELECT TRIM(ciudad.nombreciudad) AS nomciudad
          INTO cNomCiudadCte
          FROM bdinteg:si_catciudades ciudad 
         WHERE ciudad.numerociudad = iNumCiudad;
         
        IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
            LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
        END IF;
        
        IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
            LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
        END IF;
        
        IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
            LET cColonia = TRIM(cNomCiudadCte);
        END IF;
        
        IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
            LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
        END IF;
         
        SELECT TRIM(edo.siglas) AS estado
          INTO cEstado
          FROM bdinteg:si_estadosipab edo 
         WHERE edo.estado = cNoEstado;
         
        SELECT TRIM(pai.nombre) AS nom_pais
          INTO cPais
          FROM bdinteg:si_paises pai 
         WHERE pai.pais = cNoPais;
         
        IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
           ( cColonia is null OR cColonia = '' ) OR 
           ( cDelegacionMunicipio is null OR cDelegacionMunicipio = '' ) OR 
           ( cNomCiudadCte is null OR cNomCiudadCte = '' ) THEN
         
            SELECT dir.numerocalle AS no_calle,
                   TRIM(dir.numeroextcalle) AS no_ext_calle,     
                   TRIM(dir.cod_postal) AS cod_postal,         
                   TRIM(tel1.telefono) AS tel_casa,       
                   TRIM(tel2.telefono) AS tel_casa2,      
                   TRIM(tel3.telefono) AS tel_casa3,
                   dir.numerociudad AS no_ciudad,
                   dir.numerocolonia AS no_colonia,
                   dir.estado AS no_estado,
                   dir.pais AS no_pais
              INTO iNumeroCalle, cNumExtCalle, cCodPostal, cTelefonoCasa, cTelefonoCasa4, cTelefonoCasa5, iNumCiudad, iNumColonia, cNoEstado, cNoPais
              FROM bdinteg:si_direcciones_actual dir 
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON (tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON (tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
              LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON (tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
             WHERE dir.numcte = cNumCliente
               AND dir.tipo_dir = '2';
               
            IF iNumeroCalle = 644537 THEN
                LET iNumeroCalle = 134176;
            END IF;
            
            SELECT TRIM(calle.nombrecalle)||' '||cNumExtCalle AS calle
              INTO cNombreCalle
              FROM bdinteg:si_catcalles calle
             WHERE calle.numerocalle = iNumeroCalle;
             
            SELECT TRIM(NVL(zon.nombrezona,'')) AS colonia, 
                   CASE WHEN (zon.numerocolonia = 8000) THEN 'POR ASIGNAR' ELSE TRIM(nvl(zon.municipiozona, '')) END AS municipio,   
                   zon.codigopostalzona AS cod_postal2
              INTO cColonia, cDelegacionMunicipio, cCodPostal2
              FROM bdinteg:si_catzonas zon 
             WHERE zon.numerociudad = iNumCiudad
               AND zon.numerocolonia = iNumColonia;
               
            SELECT TRIM(ciudad.nombreciudad) AS nomciudad
              INTO cNomCiudadCte
              FROM bdinteg:si_catciudades ciudad 
             WHERE ciudad.numerociudad = iNumCiudad;
             
            IF cNomCiudadCte is null OR cNomCiudadCte = '' OR cNomCiudadCte = ' ' THEN
                LET cNomCiudadCte = TRIM(cDelegacionMunicipio);
            END IF;
            
            IF cDelegacionMunicipio is null OR cDelegacionMunicipio = '' OR cDelegacionMunicipio = ' ' OR cDelegacionMunicipio = 'POR ASIGNAR' THEN
                LET cDelegacionMunicipio = TRIM(cNomCiudadCte);
            END IF;
            
            IF cColonia is null OR cColonia = '' OR cColonia = ' ' THEN
                LET cColonia = TRIM(cNomCiudadCte);
            END IF;
            
            IF cNombreCalle is null OR cNombreCalle = '' OR cNombreCalle = ' ' THEN
                LET cNombreCalle = TRIM(cColonia)||' '||cNumExtCalle;
            END IF;
             
            SELECT TRIM(edo.siglas) AS estado
              INTO cEstado
              FROM bdinteg:si_estadosipab edo 
             WHERE edo.estado = cNoEstado;
             
            SELECT TRIM(pai.nombre) AS nom_pais
              INTO cPais
              FROM bdinteg:si_paises pai 
             WHERE pai.pais = cNoPais;
             
            IF ( cNombreCalle is null OR cNombreCalle = '' ) OR 
