-- Variables para dirección oficina
DEFINE iSecuencia2O SMALLINT;
DEFINE cIndCofeteltel1O CHAR(1);
DEFINE cIndCofeteltel2O CHAR(1);
DEFINE cIndCofeteltel3O CHAR(1);
DEFINE cCofeteltel1O CHAR(1);
DEFINE cCofeteltel2O CHAR(1);
DEFINE cCofeteltel3O CHAR(1);
DEFINE sCambiaDireccionO SMALLINT;
    
LET cCodRet = "000";
LET cCodRet2 = "000";
LET iSqlErr = 0;

-- Inicilización de variables para la dirección
LET cTipo_Dir = "";
LET cCalle = "";
LET cColonia = "";
LET cEntreCalles = "";
LET cPais = "";
LET cEstado = "";
LET cCiudad = "";
LET cMunicipio = "";
LET cCodPostal = "";
LET cApartPostal = "";
LET cTipoTel1 = "";
LET cTelefono1 = "";
LET cTipoTel2 = "";
LET cTelefono2 = "";
LET cTipoTel3 = "";
LET cTelefono3 = "";
LET cExtension = "";
LET cEstadoInegi = "";
LET cMunicipioInegi = "";
LET cLocalidadInegi = "";
LET sNumeroCiudad = 0;
LET cNumeroExtCalle = "";
LET cNumerIntCalle = "";
LET cDepartamento = "";
LET iNumeroCalle = 0;
LET iNumeroColonia = 0;
LET cPuntoCardinal = "";
LET cUnidadHabitac = "";
LET sManzana = 0;
LET sOtros  = 0;
LET sAndador  = 0;
LET sEtapa = 0;
LET sLote = 0;
LET sEdificio  = 0;
LET sEntrada = 0;
LET cObservaciones = "";
LET cUserInsert = "";
LET dFechaInsert = "01-01-1900"; 

-- Inicialización de variables para dirección particular
LET iSecuencia1P = 0;
LET cIndCofeteltel1P = "";
LET cIndCofeteltel2P = "";
LET cIndCofeteltel3P = "";
LET cCofeteltel1P = "";
LET cCofeteltel2P = "";
LET cCofeteltel3P = "";
LET sCambiaDireccionP = 0;

-- Inicialización de variables para dirección oficina
LET iSecuencia2O = 0;
LET cIndCofeteltel1O = "";
LET cIndCofeteltel2O = "";
LET cIndCofeteltel3O = "";
LET cCofeteltel1O = "";
LET cCofeteltel2O = "";
LET cCofeteltel3O = "";
LET sCambiaDireccionO = 0;

--- SET DEBUG FILE TO "/home/sysifx/frank/sp_actualizadireccioncofetel.out";
--- TRACE ON;

BEGIN
    ON EXCEPTION SET iSqlErr
        IF iSqlErr != 0 THEN
            LET cCodRet=iSqlErr;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;
	
	IF cNumCte <> "" THEN
		
		/* SELECT secuencia 
		INTO iSecuencia1P
		FROM si_direcciones_actual	
		WHERE numcte = cNumCte 
		AND tipo_dir = "1";
		
		SELECT secuencia
		INTO iSecuencia2O
		FROM si_direcciones_actual	
		WHERE numcte = cNumCte 
		AND tipo_dir = "2";
			
		IF iSecuencia1P <> 0 OR iSecuencia1P IS NOT NULL THEN */
		
        SELECT fecha_insert,secuencia 
        INTO dFechaInsert, iSecuencia1P
        FROM si_direcciones_actual 	
        WHERE numcte = cNumCte 
        AND tipo_dir = "1";
        
        --- IF dFechaInsert is not NULL OR dFechaInsert<> ''THEN
        IF iSecuencia1P <> 0 OR iSecuencia1P IS NOT NULL THEN
			
			IF dFechaInsert <= "12-31-2009" THEN
			
				SELECT dir.tipo_dir, dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
                       /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                       tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension,
                       dir.estado_inegi, dir.municipio_inegi, dir.localidad_inegi, dir.numerociudad,
                       dir.numeroextcalle, dir.numerointcalle, dir.departamento, dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, 
                       dir.otros, dir.andador, dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones, dir.user_insert, dir.fecha_insert, 
                       dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3 
				INTO cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                     cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, 
                     cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad,
					 cNumeroExtCalle, cNumerIntCalle, cDepartamento, iNumeroCalle, iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros,
					 sAndador, sEtapa, sLote, sEdificio, sEntrada, cObservaciones, cUserInsert, dFechaInsert, cIndCofeteltel1P, cIndCofeteltel2P, cIndCofeteltel3P
				FROM si_direcciones_actual dir
                LEFT OUTER JOIN si_telefonos_actual tel1 ON(tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                LEFT OUTER JOIN si_telefonos_actual tel2 ON(tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                LEFT OUTER JOIN si_telefonos_actual tel3 ON(tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
				WHERE dir.numcte = cNumCte
				AND dir.tipo_dir = '1';
				--- AND secuencia = iSecuencia1P;
				
				IF LENGTH(cTelefono1) > 10 OR LENGTH(cTelefono2) > 10 OR LENGTH(cTelefono3) > 10 THEN

					IF LENGTH(cTelefono1) = 13 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono1) = 12 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono1) = 11 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 2 FOR 11);
					END IF;

					IF LENGTH(cTelefono2) = 13 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono2) = 12 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono2) = 11 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 2 FOR 11);
					END IF;

					IF LENGTH(cTelefono3) = 13 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono3) = 12 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono3) = 11 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 2 FOR 11);
					END IF;

					EXECUTE PROCEDURE sp_validatelefono ('001', cTelefono1, cTelefono2, cTelefono3)
					INTO cCodRet2, cCofeteltel1P, cCofeteltel2P, cCofeteltel3P;

					IF cCodRet2 = "000" THEN
						IF cCofeteltel1P = 1 THEN
							LET cIndCofeteltel1P = 'V';
						END IF;

						IF cCofeteltel2P = 1 THEN
							LET cIndCofeteltel2P = 'V';
						END IF;

						IF cCofeteltel3P = 1 THEN
							LET cIndCofeteltel3P = 'V';
						END IF;
					END IF;
					
					SELECT MAX(secuencia)
					INTO iSecuencia1P
					FROM si_direcciones_actual	
					WHERE numcte = cNumCte; 

					INSERT INTO si_direcciones 
                    ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, 
                      /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                      estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
                      numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
                      user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
					VALUES 
                    ( cNumcte, iSecuencia1P + 1, cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                      /* cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, */
                      cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad, cNumeroExtCalle, cNumerIntCalle, cDepartamento, iNumeroCalle, 
                      iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros, sAndador, sEtapa, sLote, sEdificio, sEntrada, cObservaciones, 
                      cUserInsert, dFechaInsert, cIndCofeteltel1P, cIndCofeteltel2P, cIndCofeteltel3P );
				
				ELIF LENGTH(cTelefono1) <= 10 OR LENGTH(cTelefono2) <= 10 OR LENGTH(cTelefono3) <= 10 THEN
			
					EXECUTE PROCEDURE sp_validatelefono ('001', cTelefono1, cTelefono2, cTelefono3)
					INTO cCodRet2, cCofeteltel1P, cCofeteltel2P, cCofeteltel3P;
					
					IF cCofeteltel1P = 1 THEN
						LET cCofeteltel1P = 'V';
					ELSE
						LET cCofeteltel1P = 'F';
					END IF;
					
					IF cCofeteltel2P = 1 THEN
						LET cCofeteltel2P = 'V';
					ELSE
						LET cCofeteltel2P = 'F';
					END IF;
					
					IF cCofeteltel3P = 1 THEN
						LET cCofeteltel3P = 'V';
					ELSE
						LET cCofeteltel3P = 'F';
					END IF;
					
					IF cCofeteltel1P <> cIndCofeteltel1P THEN
						LET sCambiaDireccionP = 1;
						LET cIndCofeteltel1P = cCofeteltel1P;
					END IF;
					
					IF cCofeteltel2P <> cIndCofeteltel2P THEN
						LET sCambiaDireccionP = 1;
						LET cIndCofeteltel2P = cCofeteltel2P;
					END IF;
					
					IF cCofeteltel3P <> cIndCofeteltel3P THEN
						LET sCambiaDireccionP = 1;
						LET cIndCofeteltel3P = cCofeteltel3P;
					END IF;
					
					IF sCambiaDireccionP = 1 THEN

						SELECT MAX(secuencia)
						INTO iSecuencia1P
						FROM si_direcciones_actual	
						WHERE numcte = cNumCte; 

						INSERT INTO si_direcciones
                        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, 
                          /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                          estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
                          numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
                          user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
						VALUES 
                        ( cNumcte, iSecuencia1P + 1, cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                          /* cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, */
                          cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad, cNumeroExtCalle, cNumerIntCalle, cDepartamento, iNumeroCalle, 
                          iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros, sAndador, sEtapa, sLote, sEdificio, sEntrada, cObservaciones, 
                          cUserInsert, dFechaInsert, cIndCofeteltel1P, cIndCofeteltel2P, cIndCofeteltel3P );

					END IF;
				
				END IF;
				
			END IF;	

		END IF;
		
        SELECT fecha_insert, secuencia 
        INTO dFechaInsert, iSecuencia2O
        FROM si_direcciones_actual 	
        WHERE numcte = cNumCte 
        --AND secuencia = iSecuencia2O
        AND tipo_dir = "2";
			
		IF iSecuencia2O <> 0 OR iSecuencia2O IS NOT NULL THEN	
		
			IF dFechaInsert <= "12-31-2009" THEN
			
				SELECT dir.tipo_dir, dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
                       /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                       tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension,
                       dir.estado_inegi, dir.municipio_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle, dir.departamento, 
                       dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, dir.otros, dir.andador, dir.etapa, dir.lote, dir.edificio, 
                       dir.entrada, dir.observaciones, dir.user_insert, dir.fecha_insert, dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3 
				INTO cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                     cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, 
                     cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad, cNumeroExtCalle, cNumerIntCalle, cDepartamento, 
                     iNumeroCalle, iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros, sAndador, sEtapa, sLote, sEdificio, 
                     sEntrada, cObservaciones, cUserInsert, dFechaInsert, cIndCofeteltel1O, cIndCofeteltel2O, cIndCofeteltel3O
				FROM si_direcciones_actual dir
                LEFT OUTER JOIN si_telefonos_actual tel1 ON(tel1.numcte = dir.numcte AND tel1.tipo_tel = 1)
                LEFT OUTER JOIN si_telefonos_actual tel2 ON(tel2.numcte = dir.numcte AND tel2.tipo_tel = 2)
                LEFT OUTER JOIN si_telefonos_actual tel3 ON(tel3.numcte = dir.numcte AND tel3.tipo_tel = 3)
				WHERE dir.numcte = cNumCte
				AND dir.tipo_dir = "2";
				--- AND secuencia = iSecuencia2O;
				
				IF LENGTH(cTelefono1) > 10 OR LENGTH(cTelefono2) > 10 OR LENGTH(cTelefono3) > 10 THEN

					IF LENGTH(cTelefono1) = 13 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono1) = 12 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono1) = 11 THEN
						LET cTelefono1 = SUBSTRING(cTelefono1 FROM 2 FOR 11);
					END IF;

					IF LENGTH(cTelefono2) = 13 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono2) = 12 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono2) = 11 THEN
						LET cTelefono2 = SUBSTRING(cTelefono2 FROM 2 FOR 11);
					END IF;

					IF LENGTH(cTelefono3) = 13 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 4 FOR 13);
					ELIF LENGTH(cTelefono3) = 12 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 3 FOR 12);
					ELIF LENGTH(cTelefono3) = 11 THEN
						LET cTelefono3 = SUBSTRING(cTelefono3 FROM 2 FOR 11);
					END IF;

					EXECUTE PROCEDURE sp_validatelefono ('001', cTelefono1, cTelefono2, cTelefono3)
					INTO cCodRet2, cCofeteltel1O, cCofeteltel2O, cCofeteltel3O;

					IF cCodRet2 = "000" THEN
						IF cCofeteltel1O = 1 THEN
							LET cIndCofeteltel1O = 'V';
						END IF;

						IF cCofeteltel2O = 1 THEN
							LET cIndCofeteltel2O = 'V';
						END IF;

						IF cCofeteltel3O = 1 THEN
							LET cIndCofeteltel3O = 'V';
						END IF;
					END IF;
					
					SELECT MAX(secuencia)
					INTO iSecuencia2O
					FROM si_direcciones_actual	
					WHERE numcte = cNumCte; 

					INSERT INTO si_direcciones 
                    ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, 
                      /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                      estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
                      numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
                      user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
					VALUES 
                    ( cNumcte, iSecuencia2O + 1, cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                      /* cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, */
                      cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad, cNumeroExtCalle, cNumerIntCalle, cDepartamento, iNumeroCalle, 
                      iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros, sAndador, sEtapa, sLote, sEdificio, sEntrada, cObservaciones, 
                      cUserInsert, dFechaInsert, cIndCofeteltel1O, cIndCofeteltel2O, cIndCofeteltel3O );
				
				ELIF LENGTH(cTelefono1) <= 10 OR LENGTH(cTelefono2) <= 10 OR LENGTH(cTelefono3) <= 10 THEN
			
					EXECUTE PROCEDURE sp_validatelefono ('001', cTelefono1, cTelefono2, cTelefono3)
					INTO cCodRet2, cCofeteltel1O, cCofeteltel2O, cCofeteltel3O;
					
					IF cCofeteltel1O = 1 THEN
						LET cCofeteltel1O = 'V';
					ELSE
						LET cCofeteltel1O = 'F';
					END IF;
					
					IF cCofeteltel2O = 1 THEN
						LET cCofeteltel2O = 'V';
					ELSE
						LET cCofeteltel2O = 'F';
					END IF;
					
					IF cCofeteltel3O = 1 THEN
						LET cCofeteltel3O = 'V';
					ELSE
						LET cCofeteltel3O = 'F';
					END IF;
					
					IF cCofeteltel1O <> cIndCofeteltel1O THEN
						LET sCambiaDireccionO = 1;
						LET cIndCofeteltel1O = cCofeteltel1O;
					END IF;
					
					IF cCofeteltel2O <> cIndCofeteltel2O THEN
						LET sCambiaDireccionO = 1;
						LET cIndCofeteltel2O = cCofeteltel2O;
					END IF;
					
					IF cCofeteltel3O <> cIndCofeteltel3O THEN
						LET sCambiaDireccionO = 1;
						LET cIndCofeteltel3O = cCofeteltel3O;
					END IF;
					
					IF sCambiaDireccionO = 1 THEN

						SELECT MAX(secuencia)
						INTO iSecuencia2O
						FROM si_direcciones_actual	
						WHERE numcte = cNumCte; 

						INSERT INTO si_direcciones
                        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, 
                          /* tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, */
                          estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
                          numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
                          user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
						VALUES 
                        ( cNumcte, iSecuencia2O + 1, cTipo_dir, cCalle, cColonia, cEntreCalles, cPais, cEstado, cCiudad, cMunicipio, cCodPostal, cApartPostal, 
                          /* cTipoTel1, cTelefono1, cTipoTel2, cTelefono2, cTipoTel3, cTelefono3, cExtension, */
                          cEstadoInegi, cMunicipioInegi, cLocalidadInegi, sNumeroCiudad, cNumeroExtCalle, cNumerIntCalle, cDepartamento, iNumeroCalle, 
                          iNumeroColonia, cPuntoCardinal, cUnidadHabitac, sManzana, sOtros, sAndador, sEtapa, sLote, sEdificio, sEntrada, cObservaciones, 
                          cUserInsert, dFechaInsert, cIndCofeteltel1O, cIndCofeteltel2O, cIndCofeteltel3O );

					END IF;
				
				END IF;
				
			END IF;	
        
		END IF;
		
	END IF;
	
	RETURN cCodRet;
    
    END;
    
END PROCEDURE

DOCUMENT
"AutOR : Frank Gaxiola",
"FECHA : 06-04-2010",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cargacliente(pEmpresa char(3),pNumCredito CHAR(20),pNumCliente CHAR(10), pOpcion CHAR(1))

RETURNING CHAR(5) AS cCodRet,DATE AS fechaAlta ,CHAR(30) AS Nombre1,CHAR(30) AS Nombre2,
CHAR(30) AS ApellPaterno,CHAR(30) AS ApellMaterno,CHAR(30) AS RazonSocial,CHAR(1) AS Codidentifi,
CHAR(30) AS Numidentifi,CHAR(15) AS Rfc,DATE AS Fecha_nac,CHAR(1) AS ExisteCred;

--Declaracion de variables
DEFINE cCodRet        CHAR(5);
DEFINE iSqlErr        INTEGER;
DEFINE dfechaAlta     DATE;
DEFINE cNombre1       CHAR(30);
DEFINE cNombre2       CHAR(30);
DEFINE cApellPaterno  CHAR(30);
DEFINE cApellMaterno  CHAR(30);
DEFINE cRazonSocial   CHAR(30);
DEFINE cCodidentifi   CHAR(1);
DEFINE iNumidentifi   CHAR(30);
DEFINE cRfc           CHAR(15);
DEFINE dFecha_nac     DATE;
DEFINE cCliente       CHAR(10);
DEFINE iExiste		  INTEGER;
 
--Asignacion de variables
LET cCodRet           = '00001';
LET iSqlErr           = 0;
LET dfechaAlta        = '';
LET cNombre1          = '';
LET cNombre2          = '';
LET cApellPaterno     = '';
LET cApellMaterno     = '';
LET cRazonSocial      = '';
LET cCodidentifi      = '';
LET iNumidentifi      = '';
LET cRfc              = '';
LET dFecha_nac        = '';
LET cCliente          = '';
LET iExiste           = 0;

BEGIN
	
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;		
			RETURN cCodRet,dfechaAlta,cNombre1,cNombre2,cApellPaterno,cApellMaterno,cRazonSocial,cCodidentifi,iNumidentifi,cRfc,dFecha_nac,iExiste;
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/sp_CargaCliente.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;	
	
	IF pOpcion = "1" THEN 
		IF pNumCliente != "" AND pEmpresa != "" THEN

			SELECT a.numcte,a.fecha_alta, a.nombre1, a.nombre2, a.apell_paterno,a.apell_materno, a.razon_social, b.codidentifi, b.numidentifi, a.rfc, b.fecha_nac 
			INTO cCliente,dfechaAlta,cNombre1,cNombre2,cApellPaterno,cApellMaterno,cRazonSocial,cCodidentifi,iNumidentifi,cRfc,dFecha_nac
			FROM bdinteg:"informix".si_cliente a, bdinteg:"informix".si_ctepf b 
			WHERE a.numcte = pNumCliente 
			AND a.empresa = pEmpresa 
			AND b.empresa = a.empresa 
			AND b.numcte = a.numcte;

			LET cCodRet  = '00000';
			
			IF cCliente IS NULL THEN 
				LET cCodRet  = '00001';
			END IF;
			
			RETURN cCodRet,dfechaAlta,cNombre1,cNombre2,cApellPaterno,cApellMaterno,cRazonSocial,cCodidentifi,iNumidentifi,cRfc,dFecha_nac,NVL(iExiste,'0');	
		ELSE
			LET cCodRet  = '00001';	
		END IF;
	
	
	ELIF pOpcion = "2" THEN 	
	
		SELECT 1 INTO iExiste
		FROM bdisolic:"informix".ss_solicitudes
		WHERE empresa = pempresa 
		AND num_solicitud = pNumCredito 
		AND numcte = pNumCliente;

		LET cCodRet  = '00000';
	
	    RETURN cCodRet,NVL(dfechaAlta,''),NVL(cNombre1,''),NVL(cNombre2,''),NVL(cApellPaterno,''),NVL(cApellMaterno,''),NVL(cRazonSocial,''),NVL(cCodidentifi,''),NVL(iNumidentifi,''),NVL(cRfc,''),NVL(dFecha_nac,''),NVL(iExiste,'0');
	END IF;
	
END;
END PROCEDURE
DOCUMENT
'AUTOR: Josue Zepeda',
'FECHA: 03/08/2012',
'BD: bdinteg',
'Objetivo: Carga los Datos del Cliente y verifica numero de credito';

CREATE PROCEDURE "informix".sp_depura_bitacorabpi_v2(fechmin CHAR(10), fechmax CHAR(10))
    RETURNING CHAR(5), integer, integer;  --Códigos de retorno

DEFINE cCodRet       CHAR(5);
DEFINE vid_operacion    CHAR (4);
DEFINE vtotregshist  integer;
DEFINE iSqlErr       integer;
DEFINE cont_borra    integer;
DEFINE cursor_borra  integer;

LET cCodRet        = '00000';
LET vid_operacion     = '0000';
LET vtotregshist   = 0;
LET iSqlErr        = 0;
LET cont_borra     = 0;
LET cursor_borra   = 0;

 --SET DEBUG FILE TO "/tmp/sp_depura_bitacorabpi_v2.out";
 --TRACE ON;

        SET LOCK MODE TO wait 5;
BEGIN

   ON EXCEPTION SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET cCodRet = iSqlErr;
                    RETURN cCodRet, vtotregshist, cont_borra;
                END IF;
    END EXCEPTION;

     SELECT  count(*) 
        INTO vtotregshist  
     FROM bdinteg:si_bpibitacora
     WHERE extend (fecha_oper, year to day) between fechmin and fechmax
     and NVL(id_operacion,'') <> '';
	
	FOREACH cursor_borra WITH HOLD FOR
		SELECT id_operacion
			INTO vid_operacion
			FROM bdinteg:si_bpibitacora
			WHERE extend (fecha_oper, year to day) between fechmin and fechmax
			and NVL(id_operacion,'') <> ''
   begin work;
		DELETE FROM bdinteg:si_bpibitacora
			WHERE CURRENT OF cursor_borra;
		commit work;
		

        LET cont_borra = cont_borra + 1;

    END FOREACH;

END;
RETURN cCodRet, vtotregshist, cont_borra;
END PROCEDURE



;

CREATE PROCEDURE "informix".sp_consultafechacancelacioncta(pCuenta CHAR(20), pSistemaCuenta CHAR(2))
	RETURNING 
		CHAR(5) AS codret,
		DATE AS fecha_cancelacion;
	
	DEFINE cCodRet CHAR(5);
	DEFINE dFechaCancelacion DATE;
	DEFINE iSqlErr INTEGER;
	
	LET cCodRet = '00000';
	LET dFechaCancelacion = '';
	LET iSqlErr = 0;
	
	BEGIN
		
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				
				LET cCodRet = iSqlErr;
				RETURN cCodRet, dFechaCancelacion;
			
			END IF;
		END EXCEPTION;
		
		IF pCuenta = '' OR pSistemaCuenta = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, dFechaCancelacion;
		END IF;
		
		IF pSistemaCuenta NOT IN ('01', '03', '06') THEN
			LET cCodRet = '00037';
			RETURN cCodRet, dFechaCancelacion;
		END IF;
		
		IF pSistemaCuenta = '01' THEN
			
			SET ISOLATION TO DIRTY READ;
			
			SELECT fec_cancelac 
			INTO dFechaCancelacion
			FROM bdicheq:sc_maechq 
			WHERE cuenta = pCuenta AND status_cta=2;
			
		ELIF pSistemaCuenta = '03' THEN
			
			SET ISOLATION TO DIRTY READ;
			
			SELECT FIRST 1 fec_cancelac 
			INTO dFechaCancelacion
			FROM bdinvers:sv_maeinv
			WHERE cuenta = pCuenta AND status_cta=2;
			
			--let dFechaCancelacion = NULL;
			
		ELIF pSistemaCuenta = '06' THEN
			
			SET ISOLATION TO DIRTY READ;
			
			SELECT MAX(fecha_proceso)
			INTO dFechaCancelacion
			FROM bdicred:sd_maecredanexo mca, bdicred:sd_maecred mc
			WHERE mc.num_credito = pCuenta
				AND mc.status_cred = 'FF'
				AND mca.num_credito = mc.num_credito;
			
		END IF;
		
		RETURN cCodRet, dFechaCancelacion;
	END;
	
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cnsif_consultasubmodulo(cID_USUARIOC CHAR(8),cID_FUNCIONC CHAR(10))
    RETURNING CHAR(5),INTEGER,CHAR(20),CHAR(10);												
	DEFINE iexiste 			INT;
	DEFINE cCodRet 			CHAR(5);
	DEFINE iSql_err 		INT;
	DEFINE cId_submodulo	INTEGER;
	DEFINE cD_submodulo		CHAR(20);
    DEFINE cIdModulo        CHAR(10);
	LET iexiste = 0;
	LET cCodRet = "00000";	
	LET iSql_err = 0;
	LET	cId_submodulo ="00";
	LET cD_submodulo = "00";
    LET cIdModulo='MOD000';
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet,cId_submodulo,cD_submodulo,cIdModulo;
            END IF;
        END EXCEPTION;
		/*SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_consultasubmodulo.out";
		TRACE ON;*/
		IF 	cID_USUARIOC ='' OR 
		cID_FUNCIONC = '' THEN
			LET cCodRet = "00003";
			RETURN cCodRet,cId_submodulo,cD_submodulo,cIdModulo;
		END IF;		
		
		EXECUTE FUNCTION bdinteg:sp_cnsif_confirmaejecutivo(cID_USUARIOC, cID_FUNCIONC)
		INTO cCodRet;
		  
		IF cCodRet = '00028' THEN 
			RETURN cCodRet,cId_submodulo,cD_submodulo,cIdModulo;
		END IF;		
		
		SELECT {+INDEX (bdinteg:si_seg_submodulo idxidsubm)} nvl(Count(id_submodulo),0) INTO iexiste  FROM bdinteg:"informix".si_seg_submodulo WHERE id_submodulo IS NOT NULL;
		
		IF iexiste = 0 THEN
			LET cCodRet = "00002";
			RETURN cCodRet,cId_submodulo,cD_submodulo,cIdModulo;
		END IF;
		set isolation to dirty read;
        FOREACH
			SELECT {+INDEX (bdinteg:si_seg_submodulo idxidsubm)} Id_submodulo, D_submodulo INTO cId_submodulo,cD_submodulo 
			FROM bdinteg:"informix".si_seg_submodulo WHERE id_submodulo is not null ORDER BY id_submodulo
			
			SELECT id_modulo
			INTO cIdModulo
			FROM bdinteg:"informix".si_seg_funciones 
			WHERE id_submodulo = cId_submodulo GROUP BY 1;

			RETURN cCodRet,cId_submodulo,cD_submodulo,cIdModulo WITH resume;
		END FOREACH;		
    END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_extrae_info_aud_cred()
RETURNING CHAR(40), CHAR(80);

DEFINE v_codret         	CHAR(40);
        DEFINE v_fec_ant        	DATE;
        DEFINE v_fec_nva        	DATE;
        DEFINE v_day1           	CHAR(2);
        DEFINE v_day2           	CHAR(2);
        DEFINE v_month1         	CHAR(2);
        DEFINE v_month2         	CHAR(2);
        DEFINE v_year1          	CHAR(4);
        DEFINE v_year2          	CHAR(4);
        DEFINE v_ruta_unl       	CHAR(50);
        DEFINE v_filename       	CHAR(75);
        DEFINE v_msj_ret        	CHAR(80);
        DEFINE v_sql            	CHAR(590);
		DEFINE v_sel            	CHAR(253);
        DEFINE v_fec_hoy        	DATE;
        DEFINE v_qry            	CHAR(58);
		DEFINE v_whr            	CHAR(145);
        DEFINE v_fecha_upd_com  	DATE;
		
        DEFINE sql_err          	INTEGER;
        DEFINE isam_err         	INTEGER;
        DEFINE error_info       	CHAR(80);
		

BEGIN		

	ON EXCEPTION SET sql_err, isam_err, error_info
	
		LET v_codret = 'sql_err: ' || sql_err || ' isam_err: ' ||isam_err;
		LET v_msj_ret = 'error_info: ' || error_info;

			--------------- >>>>>>>	Validación de espacio en disco 
		IF sql_err='-668' THEN
			IF isam_err='-255' THEN
            	LET v_codret    = '668';
                LET v_msj_ret   = 'Problemas con acceso a tabla';
			END IF;
		END IF;
			--------------- >>>>>>>	
		
		--SET DEBUG FILE TO "sp_extrae_info_aud_cred.err";
		
		--	TRACE sql_err||" * "||isam_err|| " * "||error_info;
			
		RETURN v_codret, v_msj_ret;
    
	END EXCEPTION;

-- SET DEBUG FILE TO "/informix/SD/ext_auditoria/extrae_inf_aud_cred.out";
--SET DEBUG FILE TO "/informix/BB/ext_auditoria/extrae_inf_aud_cred.out";
-- TRACE ON;


	SET ISOLATION TO DIRTY READ; 
	
    SELECT fecha_hoy INTO v_fec_hoy FROM bdinteg:"informix".si_fechas;
	

-- // -----------------------------------------------------------------> Descarga de información de "sd_movhis" - INICIO - 07 - Validación OK
	
	SELECT ruta_unl {+ INDEX( si_param_extr idx_param_extr )}  id_tabla, fecha_ant INTO v_ruta_unl, v_fec_ant
	FROM bdinteg:"informix".si_param_extr where fecha_ant = (SELECT MAX(fecha_ant) from bdinteg:"informix".si_param_extr where id_tabla = 'sd_movhis') and id_tabla = 'sd_movhis';

    LET v_qry = TRIM(v_ruta_unl) || "sd_movhis_query_aud_cred.sql";
	
	SELECT MAX (fecha_upd)--, id_tabla 
    INTO v_fecha_upd_com
    FROM bdinteg:"informix".si_param_extr 
    WHERE id_tabla = 'sd_movhis';

	IF v_fecha_upd_com = today THEN
	
        -- Código de Ejecución Exitosa
        LET v_codret    = '000';
        LET v_msj_ret   = 'Proceso Finalizado Correctamente';

    ELSE
	
		IF (v_fec_ant IS NOT NULL AND v_ruta_unl IS NOT NULL) THEN
			LET v_fec_ant    = v_fec_ant +1 UNITS DAY;
			LET v_fec_nva    = v_fec_hoy -2 UNITS DAY;
			IF DAY(v_fec_ant) < 10 THEN
				LET v_day1   = "0" || DAY(v_fec_ant);
			ELSE
				LET v_day1   = DAY(v_fec_ant);
			END IF;
			IF MONTH(v_fec_ant) < 10 THEN
				LET v_month1 = "0" || MONTH(v_fec_ant);
			ELSE
				LET v_month1 = MONTH(v_fec_ant);
			END IF;
			LET v_year1      = YEAR(v_fec_ant);
			IF DAY(v_fec_nva) < 10 THEN
				LET v_day2   = "0" || DAY(v_fec_nva);
			ELSE
				LET v_day2   = DAY(v_fec_nva);
			END IF;
			IF MONTH(v_fec_nva) < 10 THEN
				LET v_month2 = "0" || MONTH(v_fec_nva);
			ELSE
				LET v_month2 = MONTH(v_fec_nva);
			END IF;
			LET v_year2      = YEAR(v_fec_nva);

			-- 3.1 Extrae Movimientos Históricos Crédito
			LET v_filename = TRIM(v_ruta_unl) || 'sd_movhis' || v_day1 || v_month1 || v_year1 || '_' || v_day2 || v_month2 || v_year2 || '.txt';
			LET v_sel = TRIM(' SELECT {+ INDEX( sd_movhis inx_movhis4) } a.numcte, b.fecha_mov, b.hora_mov, b.sucursal, b.num_credito, b.transacc_suc, b.usuario, b.monto, b.reversado, b.folio_suc, b.suc_origen FROM bdicred:"informix".sd_maecred a, bdicred:"informix".sd_movhis b');
			LET v_whr = TRIM(' WHERE a.num_credito = b.num_credito AND b.empresa = '||''''||'001'||''''||' AND b.reversado=b.reversado AND b.fecha_mov BETWEEN ' || '''' || v_fec_ant || '''' || ' AND ' || '''' || v_fec_nva || '''');
			LET v_sql = 'echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || v_filename || v_sel || v_whr || '"' || ' >  ' ||v_qry;
			SYSTEM  v_sql;
			LET v_sql = '';
			LET v_sql = 'dbaccess bdicred ' || trim(v_ruta_unl) || 'sd_movhis_query_aud_cred.sql';
			SYSTEM  v_sql;

			-->> Compresión de archivos 
			SYSTEM  v_sql;
			LET v_sql = '';
			LET v_sql = 'gzip -9 ' || TRIM(v_ruta_unl) || 'sd_movhis' || v_day1 || v_month1 || v_year1 || '_' || v_day2 || v_month2 || v_year2 || '.txt ';			SYSTEM  v_sql;
			
			-->> Borrar de archivos sql
			LET v_sql = '';
			LET v_sql = 'rm ' || TRIM(v_ruta_unl) || 'sd_movhis_query_aud_cred.sql';
			SYSTEM  v_sql;
			
			INSERT INTO bdinteg:"informix".si_param_extr (empresa, fecha_ant, ruta_unl, id_tabla, usuario_upd, fecha_upd) VALUES('001', v_fec_nva, v_ruta_unl, 'sd_movhis', user, today);

			-- Código de Ejecución Exitosa
			LET v_codret    = '000';
			LET v_msj_ret   = 'Proceso Finalizado Correctamente';

		ELSE
			-- Código de Inexistencia de Parámetros de Extracción.
			LET v_codret    = '004';
			LET v_msj_ret   = 'No existen informacion en la tabla de Parametros ';

			END IF;
	END IF ;
	RETURN v_codret, v_msj_ret;
END		

END PROCEDURE;

CREATE PROCEDURE "informix".sp_extrae_info_aud_cheq()
		RETURNING CHAR(40), CHAR(80);

        DEFINE v_codret         	CHAR(40);
        DEFINE v_fec_ant        	DATE;
        DEFINE v_fec_nva        	DATE;
        DEFINE v_day1           	CHAR(2);
        DEFINE v_day2           	CHAR(2);
        DEFINE v_month1         	CHAR(2);
        DEFINE v_month2         	CHAR(2);
        DEFINE v_year1          	CHAR(4);
        DEFINE v_year2          	CHAR(4);
        DEFINE v_ruta_unl       	CHAR(50);
        DEFINE v_filename       	CHAR(75);
        DEFINE v_msj_ret        	CHAR(80);
        DEFINE v_sql            	CHAR(590);
        DEFINE v_fec_hoy        	DATE;
        DEFINE v_qry            	CHAR(58);

        DEFINE v_fecha_upd_com  	DATE;

        DEFINE sql_err          	INTEGER;
        DEFINE isam_err         	INTEGER;
        DEFINE error_info       	CHAR(80);

		--------------- >>>>>>>	Variables Validación de espacio en disco
		DEFINE v_fecha_upd			DATE;

BEGIN

	ON EXCEPTION SET sql_err, isam_err, error_info

		LET v_codret = 'sql_err: ' || sql_err || ' isam_err: ' ||isam_err;
		LET v_msj_ret = 'error_info: ' || error_info;

			--------------- >>>>>>>	Validación de espacio en disco
		IF sql_err='-668' THEN
			IF isam_err='-255' THEN
            	LET v_codret    = '668';
                LET v_msj_ret   = 'Problemas con acceso a tabla';
			END IF;
		END IF;
			--------------- >>>>>>>

		--SET DEBUG FILE TO "sp_extrae_info_aud.err";

			--TRACE sql_err||" * "||isam_err|| " * "||error_info;

		RETURN v_codret, v_msj_ret;

	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;

    SELECT fecha_hoy INTO v_fec_hoy FROM bdinteg:"informix".si_fechas;

	--LET v_fec_hoy = "02/20/2008";


-- // -----------------------------------------------------------------> Descarga de información de "sc_movhis" - INICIO - 01 - Validación OK

    -- Asignación de Inicio de proceso, sin Finalizar
    LET v_codret = '001';
    LET v_msj_ret = 'Inicio de proceso, sin Finalizar';

	SELECT ruta_unl {+ INDEX( si_param_extr idx_param_extr )}  id_tabla, fecha_ant INTO v_ruta_unl, v_fec_ant
	FROM bdinteg:"informix".si_param_extr where fecha_ant = (SELECT MAX(fecha_ant) from bdinteg:"informix".si_param_extr where id_tabla = 'sc_movhis') and id_tabla = 'sc_movhis';

    LET v_qry = TRIM(v_ruta_unl) || "sc_movhis_query_aud_cheq.sql";

    SELECT MAX (fecha_upd)--, id_tabla
    INTO v_fecha_upd_com
    FROM bdinteg:"informix".si_param_extr
    WHERE id_tabla = 'sc_movhis';

	IF v_fecha_upd_com = today THEN

        -- Código de Ejecución Exitosa
        LET v_codret    = '000';
        LET v_msj_ret   = 'Proceso Finalizado Correctamente';

    ELSE

		IF (v_fec_ant IS NOT NULL AND v_ruta_unl IS NOT NULL) THEN
			LET v_fec_ant    = v_fec_ant +1 UNITS DAY;
			LET v_fec_nva    = v_fec_hoy -2 UNITS DAY;
			IF DAY(v_fec_ant) < 10 THEN
				LET v_day1   = "0" || DAY(v_fec_ant);
			ELSE
				LET v_day1   = DAY(v_fec_ant);
			END IF;
			IF MONTH(v_fec_ant) < 10 THEN
				LET v_month1 = "0" || MONTH(v_fec_ant);
			ELSE
				LET v_month1 = MONTH(v_fec_ant);
			END IF;
			LET v_year1      = YEAR(v_fec_ant);
			IF DAY(v_fec_nva) < 10 THEN
				LET v_day2   = "0" || DAY(v_fec_nva);
			ELSE
				LET v_day2   = DAY(v_fec_nva);
			END IF;
			IF MONTH(v_fec_nva) < 10 THEN
				LET v_month2 = "0" || MONTH(v_fec_nva);
			ELSE
				LET v_month2 = MONTH(v_fec_nva);
			END IF;
			LET v_year2      = YEAR(v_fec_nva);

			-- 1. INFO CHEQUES
			-- 1.1 Extrae Movimientos Históricos Cheques -- P 01
			LET v_filename = TRIM(v_ruta_unl) || 'sc_movhis' || v_day1 || v_month1 || v_year1 || '_' || v_day2 || v_month2 || v_year2 || '.txt';
			LET v_sql = 'echo " SET ISOLATION TO DIRTY READ; UNLOAD TO ' || v_filename || ' SELECT {+ INDEX( sc_movhis idx_movhisnew1) } a.num_cte, b.folio_suc, b.sucursal, b.usuario, b.fech_val, b.fech_hor, b.transacc, b.cuenta, b.monto_tot, b.cancelad, b.sdo_cuenta, b.transacc_suc, b.referencia, b.num_tarjeta FROM  bdicheq:"informix".sc_maechq a, bdicheq:"informix".sc_movhis b' ||
						'  WHERE a.cuenta = b.cuenta AND b.empresa = '||''''||'001'||''''||' AND b.fech_alt BETWEEN ' || '''' || v_fec_ant || '''' || ' AND ' || '''' || v_fec_nva || '''' || '" > ' || v_qry;

			SYSTEM  v_sql;
			LET v_sql = '';
			LET v_sql = 'dbaccess bdicheq ' || trim(v_ruta_unl) || 'sc_movhis_query_aud_cheq.sql';
			SYSTEM  v_sql;

			-->> Compresión de archivos
			LET v_sql = '';
			LET v_sql = 'gzip -9 ' || TRIM(v_ruta_unl) || 'sc_movhis' || v_day1 || v_month1 || v_year1 || '_' || v_day2 || v_month2 || v_year2 || '.txt ';			SYSTEM  v_sql;
/*
			-->> Asignación de permisos
			LET v_sql = '';
			LET v_sql = 'chmod 777 ' || 'sc_movhis' || v_day1 || v_month1 || v_year1 || '_' || v_day2 || v_month2 || v_year2 || '.txt ';
			SYSTEM  v_sql;
*/
			-->> Borrar de archivos sql
			LET v_sql = '';
			LET v_sql = 'rm ' || TRIM(v_ruta_unl) || 'sc_movhis_query_aud_cheq.sql';
			SYSTEM  v_sql;

			INSERT INTO bdinteg:"informix".si_param_extr (empresa, fecha_ant, ruta_unl, id_tabla, usuario_upd, fecha_upd) VALUES('001', v_fec_nva, v_ruta_unl, 'sc_movhis', user, today);

			-- Código de Ejecución Exitosa
			LET v_codret    = '000';
			LET v_msj_ret   = 'Proceso Finalizado Correctamente';

		ELSE
			-- Código de Inexistencia de Parámetros de Extracción.
			LET v_codret    = '004';
			LET v_msj_ret   = 'No existen informacion en la tabla de Parametros ';

		END IF;
	END IF ;
RETURN v_codret, v_msj_ret;
END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_registramodifdomicilio(pCliente CHAR(20), 
                                                      pOrigen SMALLINT, 
													  pTipo_dir CHAR(1), 
													  pSecuencia INT,
                                                      pSucursal CHAR(4), 
													  pFecha DATE, 
													  pUsr_captura CHAR(8), 
													  pUsr_autoriza CHAR(8))

--DATOS A REGRESAR---
RETURNING
CHAR(5);      -- Código de Retorno
		
--DEFINICION DE VARIABLES--
DEFINE iSqlErr    INTEGER;
DEFINE cCodRet    CHAR(5);
---------------------------

--INICIALIZACION DE VARIABLES--
LET iSqlErr    = 0;
LET cCodRet    = '00000';
--------------------------

	--SET DEBUG FILE TO "/home/informix/sp_RegistraModifDomicilio.out";
	--TRACE ON;
	
	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr; 
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	
	--Valida si ha habido modificaicon a la direccion
	IF EXISTS(SELECT 1 FROM bdinteg:si_direcciones WHERE secuencia = pSecuencia AND numcte = pCliente) THEN
		-- Inserta en la tabla los datos que corresponden a la bitácora del registro que se está modificando
		INSERT INTO bdinteg:"informix".si_bitacora_cambiosdom
			(cliente, origen, tipo_dir, secuencia, sucursal, fecha, usr_captura, usr_autoriza)
		VALUES
			(pCliente, pOrigen, pTipo_dir, pSecuencia, pSucursal, pFecha, pUsr_captura, pUsr_autoriza);
	END IF;
	
	RETURN cCodRet;
	
	END
END PROCEDURE
DOCUMENT
'Actualización del domicilio del cliente a través de cualquier canal (Tienda, Sucursal, CAT)',
'se deberá de registrar en la tabla si_bitacora_cambiosdom para llevar un historial de los cambios',
'AUTOR: Nancy Sevilla Camacho',
'FECHA: 20/Abril/2011',
'BD   : bdinteg',
'VER  : 1.0',
'AUTOR: Victor Hugo Nunez',
'FECHA: 21/05/2012',
'Descripcion: Se agrega validacion antes de insertar en la bitacora';

CREATE PROCEDURE "informix".sp_consultarnombrecliente(p_sEmpresa CHAR(3), p_sNumcte CHAR(20))
	RETURNING 	CHAR(6) AS retorno,
				CHAR(3) AS empresa, 
				CHAR(20) AS numcte, 
				CHAR(2) AS status_cte, 
				CHAR(4) AS sucursal, 
				CHAR(2) AS tpo_persona,
				CHAR(1) AS tipo_cliente,
				CHAR(26) AS apell_paterno, 
				CHAR(26) AS apell_materno,
				CHAR(26) AS nombre1, 
				CHAR(26) AS nombre2, 
				CHAR(60) AS razon_social,
				CHAR(13) AS rfc,
				DATE AS fecha_alta,
				CHAR(20) AS numcte_ref;

	DEFINE iSqlErr			INTEGER;
	DEFINE v_sValRetorno	CHAR(6);
	DEFINE v_sEmpresa 		CHAR(3);
	DEFINE v_sNumCte		CHAR(20);
	DEFINE v_sStatusCte		CHAR(2);
	DEFINE v_sSucursal		CHAR(4);
	DEFINE v_sTipoPersona	CHAR(2);
	DEFINE v_sTipoCliente	CHAR(1);
	DEFINE v_sApellPaterno	CHAR(26);
	DEFINE v_sApellMaterno	CHAR(26);
	DEFINE v_sNombre1		CHAR(26);
	DEFINE v_sNombre2		CHAR(26);
	DEFINE v_sRazonSocial	CHAR(60);
	DEFINE v_sRfc			CHAR(13);
	DEFINE v_dFechaAlta		DATE;
	DEFINE v_sNumCteRef		CHAR(20);
	DEFINE v_sRfc_alterno   CHAR(13);
	DEFINE cSufijo          CHAR(60);	--DSB 21/05/2013
	
	------------------------------------------------------------------------------------------
	--Creado por Erick Zamora 03/Agosto/2009
	--Obtiene los datos del cliente especificado, o de todas los clientes del catalogo
	--Caso de uso asociado: PCU-bdinteg\CU-0104-ConsultarNombreCliente-SPL
	--SET DEBUG FILE TO "/tmp/sp_consultarNombreCliente.out"; 
	--TRACE ON;
	------------------------------------------------------------------------------------------	
	
	LET v_sValRetorno = '000001';
	--DSB 21/05/2013
	LET iSqlErr			    = 0;	
	LET v_sEmpresa 		    = '';
	LET v_sNumCte		    = '';
	LET v_sStatusCte		= '';
	LET v_sSucursal		    = '';
	LET v_sTipoPersona	    = '';
	LET v_sTipoCliente	    = '';
	LET v_sApellPaterno     = '';
	LET v_sApellMaterno	    = '';
	LET v_sNombre1		    = '';
	LET v_sNombre2		    = '';
	LET v_sRazonSocial	    = '';
	LET v_sRfc			    = '';
	LET v_dFechaAlta		= DATE(1);
	LET v_sNumCteRef		= '';
	LET v_sRfc_alterno      = '';
	LET cSufijo             = '';
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr,'','','','','','','','','','','','','','';
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO "/tmp/sp_consultarNombreCliente.out"; 
		--TRACE ON;
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--DEBE PROPORCIONARSE LA EMPRESA
		IF NVL(p_sEmpresa,'') = '' OR NVL(p_sNumcte,'') = '' THEN
			RETURN v_sValRetorno,'','','','','','','','','','','','','','';
		END IF;
		
		LET p_sNumcte = LPAD(TRIM(p_sNumcte),9,'0');
		
		FOREACH
			SELECT empresa, numcte, status_cte, sucursal, tpo_persona, tipo_cliente, apell_paterno,
			apell_materno, nombre1, nombre2, razon_social, rfc, fecha_alta, numcte_ref, rfc_alterno
			INTO v_sEmpresa, v_sNumCte, v_sStatusCte, v_sSucursal, v_sTipoPersona, v_sTipoCliente, v_sApellPaterno,
			v_sApellMaterno, v_sNombre1, v_sNombre2, v_sRazonSocial, v_sRfc, v_dFechaAlta, v_sNumCteRef, v_sRfc_alterno
			FROM bdinteg:"informix".si_cliente
			WHERE empresa = p_sEmpresa AND numcte = p_sNumcte
			
			--DSB 21/05/2013		
			SELECT NVL(descripcion, '')
			INTO cSufijo
			FROM bdinteg:"informix".si_sufijos suf,
			bdinteg:"informix".si_ctepm cte
			WHERE suf.codigo = cte.sufijo
			AND cte.numcte = p_sNumcte;
			LET v_sRazonSocial = TRIM(NVL(v_sRazonSocial,''))||" "||TRIM(NVL(cSufijo,''));

			IF v_sRfc_alterno IS NOT NULL AND v_sRfc_alterno <> "" THEN
               LET v_sRfc = v_sRfc_alterno;
            END IF;	
			
			LET v_sValRetorno = '000000';
			RETURN v_sValRetorno,v_sEmpresa, v_sNumCte, v_sStatusCte, v_sSucursal, v_sTipoPersona, v_sTipoCliente, v_sApellPaterno,
			v_sApellMaterno, v_sNombre1, v_sNombre2, v_sRazonSocial, v_sRfc, v_dFechaAlta, v_sNumCteRef WITH RESUME;
		END FOREACH;
	END
END PROCEDURE
DOCUMENT
'MODIFICO: Jose Luis Polanco B.',
'FECHA: DSB 21/05/2013',
'DESCRIPCION: Se agrega el "sufijo" a la variable de retorno "v_sRazonSocial" para que aparesca en la aplicacion',
'			  al igual ques e agregan la inicializaciones de variables que por regla deben de tener los procedimientos';

CREATE PROCEDURE "informix".sp_obtenerfechaaperturasucursal(p_cSucursal CHAR(4))
	RETURNING 	CHAR(6) AS retorno,
				DATE AS fecha_inicio;
				
				
	DEFINE iSqlErr			INTEGER;
	DEFINE cRetorno			CHAR(6);
	DEFINE dFecha_inicio	DATE;
				
	--SET DEBUG FILE TO "/tmp/sp_obtenerfechaaperturasucursal.out";
	--TRACE ON;
	
	LET isqlerr 	     = 0;
	LET cRetorno         = '000001';
	LET dFecha_inicio	 = '';
	
		BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr,'';
			END IF;
		END EXCEPTION;
		
		IF NVL(p_cSucursal,'') = '' THEN
			RETURN cRetorno,dFecha_inicio;
		END IF;
		
		 SET ISOLATION TO DIRTY READ;
		 SET LOCK MODE TO WAIT 3;
		 
		 --IF EXISTS (SELECT 1 FROM bdinteg:"informix".si_sucursales WHERE sucursal = p_cSucursal) THEN   
		--	SELECT fecha_insert INTO dFecha_inicio FROM bdinteg:"informix".si_sucursales WHERE sucursal = p_cSucursal;
		--	LET cRetorno = '000000';
		 --END IF;

			LET dFecha_inicio = mdy('05','20','2007');
			LET cRetorno = '000000';
		 
		 RETURN cRetorno, dFecha_inicio; 
 	END;
END PROCEDURE
DOCUMENT
'CREADO: Josue Zepeda',
'FECHA: 25/02/2013',
'DESCRIPCION: Para obtener fecha_inicio para Validación de Fechas (Paquetes Operativos y de Cheques)',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_obt_datosempresa_bei(pRfc char(15), pNumCte char(9), pCuenta char(20), pFechaEmpresa date, pIdUsuarioDesignado char(30))
	RETURNING char(5), char(13), char(41), char(2);
	
-- Realizó: Manuel Ramos Figueroa
-- Actividad: Obtiene los datos del cliente de BEI
-- Fecha de Creación: 20/07/2011

-- Se ajusto la longitud de pIdUsuarioDesignado de 13 a 30.
-- Fecha:02/Agosto/2012

--Ajustes para omitir el dato de la fecha de constitución.
--Fecha 30/Mayo/2013
--Berenice Noriega Guevara (BanCoppel).

	DEFINE sql_err integer;
	DEFINE cCod_ret char(5);
	DEFINE cRFC char(13);
	DEFINE cNombre char(41);
	DEFINE cIdStatus char(2);
	
	LET cCod_ret = '00000';
	LET cRFC = '';
	LET cNombre = '';
	LET cIdStatus = '';
	
	--SET debug FILE TO "/home/informix/ivonne/sp_obt_datosempresa_bei.out";
	--Trace ON;
	
	BEGIN
		ON EXCEPTION SET sql_err
			IF sql_err <> 0 THEN
				LET cCod_ret = sql_err;
				RETURN cCod_ret, cRFC, cNombre, cIdStatus;
			END IF
		END EXCEPTION;

		IF NVL(TRIM(pRfc), '') = '' AND NVL(TRIM(pNumCte), '') = '' AND NVL(TRIM(pCuenta), '') = '' AND NVL(pFechaEmpresa, '') = '' AND NVL(TRIM(pIdUsuarioDesignado), '') = '' THEN
			LET cCod_ret = '00001'; --datos incompletos
		ELSE
		
			SET LOCK MODE TO WAIT ;
			SET ISOLATION DIRTY READ ;
		
			SELECT rfc INTO cRFC FROM bdinteg:"informix".si_cliente WHERE rfc = pRfc AND numcte = pNumCte AND tpo_persona = '02' AND tipo_cliente = '1';
			IF NVL(cRFC, '') <> '' THEN
				SELECT a.id_status 
				INTO cIdStatus 
				FROM bdinteg:"informix".si_bpiusuariospm a, bdicheq:"informix".sc_maechq c 
				WHERE a.num_cliente = pNumCte 
				AND a.num_cliente = c.num_cte 
				AND a.no_identificacion_oficial = pIdUsuarioDesignado 
				AND c.cuenta = pCuenta;

				IF NVL(cIdStatus, '') = '' THEN
					LET cCod_ret = '00003'; --cliente no existe				
				ELSE
				
					SET LOCK MODE TO WAIT ;
					SET ISOLATION DIRTY READ ;
				
					SELECT nombre_corto 
					INTO cNombre  
					FROM bdinteg:"informix".si_ctepm 
					WHERE numcte = pNumCte; 
					--AND fecha_constitct = pFechaEmpresa;

					IF NVL(TRIM(cNombre), '') = '' THEN
						LET cCod_ret = '00004'; --fecha no existe
					END IF
				END IF
			ELSE
				LET cCod_ret = '00002'; --rfc no existe
			END IF
		END IF
		RETURN cCod_ret, cRFC, cNombre, cIdStatus;

	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generartraspasoinfo()
RETURNING
     CHAR(6), ---cod_ret
	 CHAR(60); --Descripcion de retorno

    DEFINE v_cod_ret            CHAR(6);
    DEFINE iSqlErr              INTEGER;
    DEFINE iSamErr              INTEGER;
	DEFINE vDesErr              CHAR(60);
	DEFINE error_info           CHAR(60);
	DEFINE vsSQL 				CHAR (1000);
	
	LET vsSQL = '' ;

	SET LOCK MODE TO WAIT 10;

BEGIN

   ON EXCEPTION
        SET iSqlErr, iSamErr, error_info
        IF iSqlErr <> 0 THEN
                LET v_cod_ret = iSqlErr;
				LET vDesErr = error_info;
        END IF;
        RETURN v_cod_ret,vDesErr;
    END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;

	--SET DEBUG FILE TO "/tmp/sp_generartraspasoinfo.out";
	--TRACE ON;

	LET v_cod_ret = '000000';
	LET vDesErr = 'PROCESO EXITOSO';
	
---	RESPALDA LOS DATOS DEL MOVIMIENTO A LA TABLA HISTORICA	
	  --DESCARGA DE INFORMACION DE LA TABLA DIARO DE LOS BATCH A UN ARCHIVO PLANO.
				LET vsSQL = ' echo "UNLOAD TO ' || '''/resplogifx/archivoscartera/altaunica/envios/infotraspaso_batch.unl''' || ' DELIMITER ' || '''|''' || 
							' SELECT empresa,secuencia,sucursal,trama,tipomovto,fecha_insert,fecha_insert'||
							' FROM "informix".si_archivoscopdiario '||
							' " > /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso_batch.sql';
				SYSTEM vsSQL;

				LET vsSQL = '';
				LET vsSQL = 'dbaccess bdinteg /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso_batch.sql';
				SYSTEM vsSQL;
				
	  --CARGA DE DATOS DEL ARCHIVO PLANO A LA TABLA HISTORIAL CON LA INFORMACION DE BATCH				
				
				LET vsSQL='';
				LET vsSQL = ' echo "LOAD FROM ' || '''/resplogifx/archivoscartera/altaunica/envios/infotraspaso_batch.unl''' || ' DELIMITER ' || '''|''' || 
				' INSERT INTO '||
				' "informix".si_archivoscophist; '||
				' " > /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso2_batch.sql';
				SYSTEM vsSQL;

				LET vsSQL = '';
				LET vsSQL = 'dbaccess bdinteg /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso2_batch.sql';
				SYSTEM vsSQL;			

				LET vsSQL = '';
				LET vsSQL =  "rm /resplogifx/archivoscartera/altaunica/envios/infotraspaso_batch.unl";
				SYSTEM vsSQL;
				
				LET vsSQL = '';
				LET vsSQL =  "rm /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso_batch.sql";
				SYSTEM vsSQL;					
				
				LET vsSQL = '';
				LET vsSQL =  "rm /resplogifx/archivoscartera/altaunica/envios/queryinfotraspaso2_batch.sql";
				SYSTEM vsSQL;				
				
				--BORRA LOS MOVIMIENTOS DE LA TABLA DIARIA
				DELETE FROM "informix".si_archivoscopdiario;							
				
	RETURN v_cod_ret,vDesErr;
END;
--##############################################################################
--## Procedimiento   : "informix".sp_generartraspasoinfo.sql
--## Version         : 1.0
--## Creado por      : Maria Elena Angulo
--## Fecha creacion  : Mayo de 2013
--## Descripcion     : Traspaso de información de archivos batch de la tabla diario a la historial.
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_depura_correos_dupli( pEmpresa CHAR(3) )
RETURNING CHAR(5), INTEGER;
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    DEFINE vEnTransacc      SMALLINT;
    DEFINE vContador        INTEGER;
    DEFINE vNumCte          CHAR(20);
    DEFINE vTipoCorreo      SMALLINT;
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET vcodret3      = '';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET desc_err      = '';
    LET vEnTransacc   = 0;
    LET vContador     = 0;
    LET vNumCte       = '';
    LET vTipoCorreo   = 0;
    
    BEGIN
    
    -- // MANEJO DE EXCEPCIONES
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_depura_correos_dupli.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF vEnTransacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vContador;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_depura_correos_dupli.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT numcte, tipo_correo, status_correo, COUNT(*) AS repeticiones
      FROM si_correos
     WHERE status_correo = 'A'
     GROUP BY 1, 2, 3
    HAVING COUNT(*) > 1
    INTO TEMP tmp_duplicados WITH NO LOG;
    CREATE INDEX idxtmp_corrdupl ON tmp_duplicados(numcte) USING BTREE FILLFACTOR 99;
    UPDATE STATISTICS HIGH FOR TABLE tmp_duplicados;
    
    FOREACH WITH HOLD
        SELECT numcte, tipo_correo
          INTO vNumCte, vTipoCorreo
          FROM tmp_duplicados
          
        BEGIN WORK;
        LET vEnTransacc = 1;
          
        UPDATE si_correos
           SET status_correo = 'C'
         WHERE numcte = vNumCte
           AND tipo_correo = vTipoCorreo
           AND secuencia < ( SELECT MAX(secuencia)
                               FROM si_correos
                              WHERE numcte = vNumCte
                                AND tipo_correo = vTipoCorreo );
           
        COMMIT WORK;
        LET vEnTransacc = 0;
        
        LET vContador = vContador +1;
        
        LET vNumCte     = '';
        LET vTipoCorreo = 0;
    END FOREACH;
    
    END;

    RETURN vcodret1, vContador;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_msjrepmttohuella(pNumErr CHAR(3),pSist CHAR(2))

RETURNING
--Datos a Regresar--
CHAR(5),    					--Codigo de Retorno
CHAR(50);						--Descripcion del Error

--DEFINICION DE VARIABLES--
DEFINE iSql_err 	INTEGER;
DEFINE cCodRet 		CHAR(5);
DEFINE cDescrip		CHAR(50);

--INICIACION DE VARIABLES--
LET iSql_err 	=	0;
LET cCodRet 	=	'0000';
LET cDescrip	=	'';


	--SET DEBUG FILE TO "/tmp/sp_msjrepmttohuella.out";
	--TRACE ON;
	
	BEGIN
	
		ON EXCEPTION SET iSql_err
			IF iSql_err <> 0 THEN
				LET cCodRet = iSql_err;
				RETURN  cCodRet, cDescrip;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT descripcion INTO cDescrip FROM bdinteg:"informix".si_codret WHERE codigo_retorno = pNumErr AND sistema = pSist;
		LET cCodRet = '0035';
				
		RETURN  cCodRet, TRIM(NVL(cDescrip, ''));

	END


END PROCEDURE
DOCUMENT
'Obtencion de descripcion de errores parametizados por codigo de error en la tabla si_codret',
'Autor : Jesus Horacio Lopez Gonzalez',
'FECHA : 07/06/2013',
'BD: bdinteg';

CREATE PROCEDURE "informix".consnombrenumcte_pba(pEmpresa CHAR(3),
						pNombre1 CHAR(26),
						pNombre2 CHAR(26),
                        pPaterno CHAR(26),
                        pMaterno CHAR(26),
						pFechaNac DATE,
						pNo_Rfc CHAR(13),
						pRazon CHAR(60),
                        pSecuencia SMALLINT)

RETURNING CHAR(5),CHAR(60),CHAR(20),CHAR(13);

DEFINE sql_err 									  INTEGER;
DEFINE v_longitud,v_ciclo 					      SMALLINT;
DEFINE v_nombre_completo 						  CHAR(63);
DEFINE v_nombre1, v_nombre2, v_paterno, v_materno CHAR(26);
DEFINE v_numcte 								  CHAR(20);
DEFINE v_cod_ret 								  CHAR(5);
DEFINE v_razon_soc 								  CHAR(60);
DEFINE v_rfc 									  CHAR(13);
DEFINE v_rfc_alterno                              CHAR(13);

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

LET v_cod_ret = "00000";
LET v_ciclo = 0;
LET v_nombre_completo = "";
LET v_numcte = "0000000000";
LET v_rfc = "";
LET v_rfc_alterno = "";

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
     END IF;
   END EXCEPTION;

IF NVL(pEmpresa,'') = ''  THEN
	LET v_cod_ret = "00001";
	LET v_nombre_completo = 'Parámetros incompletos';
	RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
END IF;

SET ISOLATION TO DIRTY READ;

IF pRazon IS NOT NULL AND pRazon !="" THEN
    FOREACH
        SELECT skip pSecuencia limit 21
             razon_social,numcte,rfc
 	    INTO v_razon_soc,v_numcte,v_rfc
        FROM si_cliente
        WHERE razon_social = prazon
           and apell_paterno = ''
	       and apell_materno = ''
        ORDER BY numcte
--        LET v_ciclo = v_ciclo+1;
--        IF v_ciclo <= psecuencia THEN
-- 	        CONTINUE FOREACH;
--        END IF;
        LET v_nombre_completo = v_razon_soc;
        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
    END FOREACH;
ELSE

    IF pNo_Rfc IS NOT NULL AND pNo_Rfc != "" THEN
        FOREACH
            SELECT skip pSecuencia limit 21 
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc, rfc_alterno
	        INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
      	    FROM si_ctepf pf, si_cliente cl
      	    WHERE rfc = pno_rfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte
--      	    LET v_ciclo = v_ciclo+1;
--      	    IF v_ciclo <= psecuencia THEN
--                 CONTINUE FOREACH;
--      	    END IF;
	        LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
             || " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
			 
			IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
               LET v_rfc = v_rfc_alterno;
            END IF;
			
	        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS

--	IF NVL(pPaterno,'') = '' AND NVL(pMaterno,'') = '' THEN
	IF NVL(pPaterno,'') = ''  THEN
		LET v_cod_ret = "00002";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos apellidos';
		RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
--	ELIF NVL(pNombre1,'') = '' AND NVL(pNombre2,'') = '' THEN
	ELIF NVL(pNombre1,'') = '' THEN
		LET v_cod_ret = "00003";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos nombres';
		RETURN v_cod_ret, v_nombre_completo, v_numcte,v_rfc;
	ELSE
        if ( pPaterno is null or pPaterno = "" ) then
           let pPaterno = "";
        else
            let pPaterno = trim(pPaterno)||"*";
           --- let pPaterno = trim(pPaterno);
        end if;  

        if ( pMaterno is null or pMaterno = "" ) then
           let pMaterno = "";
        else
           let pMaterno = trim(pMaterno)||"*";
           --- let pMaterno = trim(pMaterno);
        end if;  

        if ( pNombre1 is null or pNombre1 = "" ) then
           let pNombre1 = "";
        else
           let pNombre1 = trim(pNombre1)||"*";
        end if;  

        if ( pNombre2 is null or pNombre2 = "" ) then
           let pNombre2 = "";
        else
           let pNombre2 = trim(pNombre2)||"*";
        end if;  

--		LET pPaterno = TRIM(pPaterno)||"*";
--		LET pMaterno = TRIM(pMaterno)||"*";
--		LET pNombre1 = TRIM(pNombre1)||"*";
--		LET pNombre2 = TRIM(pNombre2)||"*";

		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc, rfc_alterno
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
				FROM si_ctepf pf, si_cliente cl
				WHERE cl.apell_paterno matches ppaterno
				AND cl.apell_materno matches pmaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo + 1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
						
				IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
                   LET v_rfc = v_rfc_alterno;
                END IF;
				
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;

		ELSE

			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc, rfc_alterno
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
				FROM si_cliente
				WHERE apell_paterno matches ppaterno
				AND apell_materno matches pmaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo+1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(UPPER(v_materno))
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
						
				IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
                   LET v_rfc = v_rfc_alterno;
                END IF;		
						
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE
DOCUMENT
'Consulta clientes por nombre(s) y apellido(s) y por fecha de nacimiento si asi se requiere',
'AUTOR : Dulce Ramirez',
'FECHA : 01/Junio/2009',
'Ver.  : 1.1',
'BD    : bdinteg',
'VER   : 1.1';

CREATE PROCEDURE "informix".consnombrenumcte(pEmpresa CHAR(3),
						pNombre1 CHAR(26),
						pNombre2 CHAR(26),
                        pPaterno CHAR(26),
                        pMaterno CHAR(26),
						pFechaNac DATE,
						pNo_Rfc CHAR(13),
						pRazon CHAR(60),
                        pSecuencia SMALLINT)

RETURNING CHAR(5),CHAR(60),CHAR(20),CHAR(13);

DEFINE sql_err 									  INTEGER;
DEFINE v_longitud,v_ciclo 					      SMALLINT;
DEFINE v_nombre_completo 						  CHAR(63);
DEFINE v_nombre1, v_nombre2, v_paterno, v_materno CHAR(26);
DEFINE v_numcte 								  CHAR(20);
DEFINE v_cod_ret 								  CHAR(5);
DEFINE v_razon_soc 								  CHAR(60);
DEFINE v_rfc 									  CHAR(13);
DEFINE v_rfc_alterno                              CHAR(13);

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

LET v_cod_ret = "00000";
LET v_ciclo = 0;
LET v_nombre_completo = "";
LET v_numcte = "0000000000";
LET v_rfc = "";
LET v_rfc_alterno = "";

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
     END IF;
   END EXCEPTION;

IF NVL(pEmpresa,'') = ''  THEN
	LET v_cod_ret = "00001";
	LET v_nombre_completo = 'Parámetros incompletos';
	RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
END IF;

SET ISOLATION TO DIRTY READ;

IF pRazon IS NOT NULL AND pRazon !="" THEN
    FOREACH
        SELECT skip pSecuencia limit 21
             razon_social,numcte,rfc
 	    INTO v_razon_soc,v_numcte,v_rfc
        FROM si_cliente
        WHERE razon_social = prazon
           and apell_paterno = ''
	       and apell_materno = ''
        ORDER BY numcte
--        LET v_ciclo = v_ciclo+1;
--        IF v_ciclo <= psecuencia THEN
-- 	        CONTINUE FOREACH;
--        END IF;
        LET v_nombre_completo = v_razon_soc;
        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
    END FOREACH;
ELSE

    IF pNo_Rfc IS NOT NULL AND pNo_Rfc != "" THEN
        FOREACH
            SELECT skip pSecuencia limit 21 
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc, rfc_alterno
	        INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
      	    FROM si_ctepf pf, si_cliente cl
      	    WHERE rfc = pno_rfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte
--      	    LET v_ciclo = v_ciclo+1;
--      	    IF v_ciclo <= psecuencia THEN
--                 CONTINUE FOREACH;
--      	    END IF;
	        LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
             || " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
			 
			IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
               LET v_rfc = v_rfc_alterno;
            END IF;
			
	        RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS

--	IF NVL(pPaterno,'') = '' AND NVL(pMaterno,'') = '' THEN
	IF NVL(pPaterno,'') = ''  THEN
		LET v_cod_ret = "00002";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos apellidos';
		RETURN v_cod_ret, v_nombre_completo, v_numcte, v_rfc;
--	ELIF NVL(pNombre1,'') = '' AND NVL(pNombre2,'') = '' THEN
	ELIF NVL(pNombre1,'') = '' THEN
		LET v_cod_ret = "00003";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos nombres';
		RETURN v_cod_ret, v_nombre_completo, v_numcte,v_rfc;
	ELSE
        if ( pPaterno is null or pPaterno = "" ) then
           let pPaterno = "";
        else
--           let pPaterno = trim(pPaterno)||"*";
           let pPaterno = trim(pPaterno);
        end if;  

        if ( pMaterno is null or pMaterno = "" ) then
           let pMaterno = "";
        else
--           let pMaterno = trim(pMaterno)||"*";
           let pMaterno = trim(pMaterno);
        end if;  

        if ( pNombre1 is null or pNombre1 = "" ) then
           let pNombre1 = "";
        else
           let pNombre1 = trim(pNombre1)||"*";
        end if;  

        if ( pNombre2 is null or pNombre2 = "" ) then
           let pNombre2 = "";
        else
           let pNombre2 = trim(pNombre2)||"*";
        end if;  

--		LET pPaterno = TRIM(pPaterno)||"*";
--		LET pMaterno = TRIM(pMaterno)||"*";
--		LET pNombre1 = TRIM(pNombre1)||"*";
--		LET pNombre2 = TRIM(pNombre2)||"*";

		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc, rfc_alterno
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
				FROM si_ctepf pf, si_cliente cl
				WHERE cl.apell_paterno = ppaterno
				AND cl.apell_materno = pmaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo + 1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
						
				IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
                   LET v_rfc = v_rfc_alterno;
                END IF;
				
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;

		ELSE

			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc, rfc_alterno
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc, v_rfc_alterno
				FROM si_cliente
				WHERE apell_paterno = ppaterno
				AND apell_materno = pmaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo+1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(UPPER(v_materno))
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
						
				IF v_rfc_alterno is not null and v_rfc_alterno <> "" THEN
                   LET v_rfc = v_rfc_alterno;
                END IF;		
						
				RETURN v_cod_ret,v_nombre_completo,v_numcte,v_rfc WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE
DOCUMENT
'Consulta clientes por nombre(s) y apellido(s) y por fecha de nacimiento si asi se requiere',
'AUTOR : Dulce Ramirez',
'FECHA : 01/Junio/2009',
'Ver.  : 1.1',
'BD    : bdinteg',
'VER   : 1.1';

CREATE PROCEDURE "informix".sp_actualizacurp(pEmpresa CHAR(3), pNumCte CHAR(20), pCURP CHAR(18))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Se actualiza CURP en los datos del cliente (si_ctepf)
--Realizó: Nancy Sevilla Camacho
--Fecha: 24/06/2011                    
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5);      -- Código de Retorno
		
--DEFINICION DE VARIABLES--
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);	
DEFINE cRfc CHAR(13);	

--INICIALIZACION DE VARIABLES--
LET iSqlErr = 0;
LET cCodRet = '00000';
LET cRfc = '';
	
	--SET DEBUG FILE TO "/tmp/sp_actualizacurp.out";
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;	
		
		-- Se valida que los parámetros de entrada no vengan vacíos
		IF pEmpresa IS NULL OR pEmpresa = '' OR pNumCte IS NULL OR pNumCte = '' OR 
		   pCURP IS NULL OR pCURP = '' THEN
		
			LET cCodRet = "100"; -- Parámetro de entrada vacío
			
		ELSE
			SELECT rfc 
			  INTO cRfc
			  FROM bdinteg:si_cliente
			 WHERE empresa = pEmpresa
			   AND numcte = pNumCte;
			   
			IF SUBSTRING(cRfc FROM 1 FOR 10) = SUBSTRING(pCURP FROM 1 FOR 10) THEN
			-- Se actualiza CURP
				UPDATE bdinteg:"informix".si_ctepf
				   SET curp = pCURP
				 WHERE empresa = pEmpresa
				   AND numcte = pNumCte;
			   
				INSERT INTO si_bitacora_cambio_curp (numcte,rfc,curp,resultado,fecha)
				VALUES(pNumCte, cRfc, pCURP, '01', CURRENT);
				
			ELIF SUBSTRING(pCURP FROM 2 FOR 1) = "X" THEN
				-- Se actualiza CURP con palabras altizonantes
				UPDATE bdinteg:"informix".si_ctepf
				SET curp = pCURP
				WHERE empresa = pEmpresa
				AND numcte = pNumCte;
			   
				INSERT INTO si_bitacora_cambio_curp (numcte,rfc,curp,resultado,fecha)
				VALUES(pNumCte, cRfc, pCURP, '01', CURRENT);
			ELSE
				INSERT INTO si_bitacora_cambio_curp (numcte,rfc,curp,resultado,fecha)
				VALUES(pNumCte, cRfc, pCURP, '02', CURRENT);
				
				LET cCodRet = "290";
			
			END IF;

		END IF;
		
	    RETURN cCodRet;			
		
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerfechahoy()
RETURNING CHAR(5) AS codret, CHAR(10) AS fechahoy;

DEFINE vsCodRet		CHAR(5);
DEFINE viSqlErr		INTEGER;
DEFINE vsFechaHoy	CHAR(10);

LET vsCodRet = "00000";
LET viSqlErr = 0;
LET vsFechaHoy = "";

BEGIN

ON EXCEPTION SET viSqlErr
	LET vsCodRet = viSqlErr;
	RETURN vsCodRet, vsFechaHoy;
END EXCEPTION;

SET LOCK MODE TO WAIT 3;
SET ISOLATION TO DIRTY READ;

SELECT fecha_hoy 
INTO vsFechaHoy 
FROM si_fechas
WHERE empresa = '001';

LET vsFechaHoy = SUBSTRING(vsFechaHoy FROM 7 FOR 4) || "/" || SUBSTRING(vsFechaHoy FROM 1 FOR 3) ||  SUBSTRING(vsFechaHoy FROM 4 FOR 2);

RETURN vsCodRet, vsFechaHoy;

END

END PROCEDURE
DOCUMENT
'AUTOR: EDGAR IVAN ROCHIN ROCHA',
'Descripción: Obtiene la fecha hoy de tabla fechas.',
'Fecha: 2012/11/01',
'Versión: 20121101.1800',
'BD: bdinteg';

CREATE PROCEDURE "informix".consultaguardaconyuge_cjunk( cEmpresa CHAR(3),
                                                         cNumSolicitud CHAR(20),
                                                         cNumCte CHAR(20),
                                                         cNumCteConyuge CHAR(20),
                                                         cUsuario CHAR(8),
                                                         cTipoDirCon CHAR(1))
RETURNING char(5);

    DEFINE cCodRet char(5);
    DEFINE iSqlErr INTEGER;

    DEFINE sSucursal CHAR(4);
    DEFINE sApellPaterno CHAR(26);
    DEFINE sApellMaterno CHAR(26);
    DEFINE sNombre1 CHAR(26);
    DEFINE sNombre2 CHAR(26);
    DEFINE sRfc CHAR(13);
    DEFINE dFechaNac DATE;
    DEFINE sCurp CHAR(20);
    DEFINE sSexo CHAR(1);
    DEFINE sEstadoCivil CHAR(2);
    DEFINE sNacionalidad CHAR(3);
    DEFINE sNoFm CHAR(18);
    DEFINE sCodigoIden CHAR(2);
    DEFINE sNumIdenti CHAR(30);
    DEFINE sPersDomicilio CHAR(2);
    DEFINE sEmail CHAR(60);
    DEFINE sParentesco CHAR(2);
    DEFINE sApellCasada CHAR(26);
    DEFINE sNumcteRef CHAR(20);

    DEFINE pcalle char(40);
    DEFINE pcolonia char(60);
    DEFINE pmunicipio char(5);
    DEFINE pentre_calles char(40);
    DEFINE ppais char(3);
    DEFINE pentidad char(2);
    DEFINE plocalidad char(3);
    DEFINE pcodpostal char(5);
    DEFINE ptipotel1 char(1);
    DEFINE ptelefono1 char(13);
    DEFINE ptipotel2 char(1);
    DEFINE ptelefono2 char(13);
    DEFINE ptipotel3 char(1);
    DEFINE ptelefono3 char(13);
    DEFINE pextension char(5);
    DEFINE pestado_inegi char(2);
    DEFINE pmunicipio_inegi char(3);
    DEFINE plocalidad_inegi char(4);
    DEFINE pnociudad smallint;
    DEFINE pnoext char(10);
    DEFINE pnoint char(10);
    DEFINE pdepto char(6);
    DEFINE pnocalle integer;
    DEFINE pnocolonia integer;
    DEFINE ppuntocar char(1);
    DEFINE punihabi char(1);
    DEFINE pmanz smallint;
    DEFINE ppotros smallint;
    DEFINE pandador smallint;
    DEFINE petapa smallint;
    DEFINE plote smallint;
    DEFINE pedif smallint;
    DEFINE pentrada smallint;
    DEFINE pobserva char(80);
    DEFINE iSecuencia integer;
    DEFINE pCofeteltel1 char(1);
    DEFINE pCofeteltel2 char(1);
    DEFINE pCofeteltel3 char(1);
    DEFINE pApart_postal char (11);
    DEFINE dFechaHoy DATE;
    DEFINE wBegin CHAR(1);
	
	DEFINE sCodretorno2 char(5);
    
    LET cCodRet = "000";
	
	LET sCodretorno2 = "00000";
    
	--Set debug file to '/tmp/actualizaguardaconyuge_cjunk.out';
    --trace on;
    
    -----------------------------------------
    --CREADO: Rodolfo Tortolero Varela
    --FECHA: 2011-06-10
    --FUNCIONALIDAD: Guarda la información del conyuge como referencia agregandole el número de solicitud que va relacionado.
    ----------------------------------------

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 10;

    BEGIN
    
    ON EXCEPTION SET iSqlErr
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            ROLLBACK WORK;
            IF (wBegin = "S") THEN
                BEGIN WORK;
            END IF;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    ON EXCEPTION IN (-535)
        LET wBegin = "S";
        COMMIT WORK;
        BEGIN WORK;
    END EXCEPTION WITH RESUME;

    IF EXISTS( SELECT 1 
                 FROM "informix".si_refclientes a, 
                      "informix".si_refdirecciones b
                WHERE a.empresa = cEmpresa
                  AND a.num_solicitud = cNumSolicitud
                  AND a.numcte = cNumcte
                  AND a.numcte = b.numcte
                  AND a.secuencia = b.secuencia
                  --AND a.numcte_banco = cNumCteConyuge
                  AND a.parentesco = 'E') THEN
        
        --BEGIN WORK;
        EXECUTE PROCEDURE "informix".actualizaguardaconyuge_cjunk( cEmpresa, cNumSolicitud , cNumCte , cNumCteConyuge , cUsuario , cTipoDirCon) INTO sCodretorno2;
		--COMMIT WORK;
        
        LET cCodRet = "001";        
        
    ELSE
        
        LET wBegin = "N";
        
        begin work;

        update "informix".si_param 
           set valor = cast(valor as integer) + 1 
         where empresa = cEmpresa 
           and cod_param = 121;
           
        SELECT cast(valor as integer) 
          INTO iSecuencia 
          FROM "informix".si_param 
         where empresa = cEmpresa 
           and cod_param = 121;

        commit work;

        if wBegin = 'S' THEN
            begin work;
        end if;

        --- SELECT MAX(secuencia) +1 INTO iSecuencia FROM si_refclientes;
        
        SELECT fecha_hoy 
          INTO dFechaHoy 
          FROM "informix".si_fechas;

        SELECT a.sucursal, a.apell_paterno, a.apell_materno, a.nombre1, a.nombre2, a.rfc, a.string2, b.fecha_nac, b.curp, 
               b.sexo, b.estado_civil, b.nacionalidad, b.no_fm3, b.codidentifi, b.numidentifi, a.apell_casada, a.numcte_ref 
          INTO sSucursal, sApellPaterno, sApellMaterno, sNombre1, sNombre2, sRfc, sPersDomicilio, dFechaNac, sCurp, 
               sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sNumIdenti, sApellCasada, sNumcteRef
          FROM "informix".si_cliente a, 
               "informix".si_ctepf b
         WHERE a.numcte = b.numcte
           AND a.numcte = cNumCteConyuge;
           
        SELECT correo_elec
          INTO sEmail
          FROM "informix".si_correos
         WHERE numcte = cNumCteConyuge
           AND tipo_correo = 1
           AND status_correo = 'A';

        INSERT INTO "informix".si_refclientes 
        ( empresa, num_solicitud, numcte, sucursal, secuencia, apell_paterno, apell_materno, 
          nombre1, nombre2, rfc, fecha_nac, curp, sexo, estado_civil, nacionalidad, no_fm3, codidentifi, numidentifi, pers_domicilio, 
          email, parentesco, apellido_cas, numcte_ref, numcte_banco, user_insert, fecha_insert )
        VALUES 
        ( cEmpresa, cNumSolicitud, cNumCte, sSucursal, iSecuencia, sApellPaterno, sApellMaterno, sNombre1, sNombre2,
          sRfc, dFechaNac, sCurp, sSexo, sEstadoCivil, sNacionalidad, sNoFm, sCodigoIden, sNumIdenti, sPersDomicilio, 
          sEmail, 'E', sApellCasada, sNumcteRef, cNumCteConyuge, cUsuario, dFechaHoy );
        
        SELECT dir.calle, dir.colonia, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.municipio, dir.cod_postal, dir.apart_postal, 
               tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension, 
               dir.estado_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle, dir.departamento, 
               dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana, dir.otros, dir.andador,
               dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones, dir.ind_cofeteltel1, dir.ind_cofeteltel2, dir.ind_cofeteltel3
          INTO pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, pmunicipio, pcodpostal,  pApart_postal, ptipotel1, ptelefono1,
               ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, pestado_inegi, plocalidad_inegi, pnociudad, pnoext, 
               pnoint, pdepto, pnocalle, pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, 
               petapa, plote, pedif, pentrada, pobserva, pCofeteltel1, pCofeteltel2, pCofeteltel3
          FROM "informix".si_direcciones_actual dir
          LEFT OUTER JOIN "informix".si_telefonos_actual tel1 ON ( tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 )
          LEFT OUTER JOIN "informix".si_telefonos_actual tel2 ON ( tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 )
          LEFT OUTER JOIN "informix".si_telefonos_actual tel3 ON ( tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 )
         WHERE dir.numcte = cNumCteConyuge
          -- AND secuencia = (SELECT MAX(secuencia) FROM bdinteg:"informix".si_direcciones_actual WHERE numcte = cNumCteConyuge);
           --AND dir.tipo_dir = '1';
           AND dir.tipo_dir = cTipoDirCon;
         
        IF cTipoDirCon = '1' THEN
            LET ptipotel3 = '';
            LET ptelefono3 = '';
            LET pextension = '';
        ELSE
            LET ptipotel1 = '';
            LET ptelefono1 = '';
            LET ptipotel2 = '';
            LET ptelefono2 = '';
        END IF;
        
        INSERT INTO "informix".si_refdirecciones
        ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, 
          municipio, cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, 
          estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, 
          numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones, 
          numcte_banco, user_insert, fecha_insert, ind_cofeteltel1, ind_cofeteltel2, ind_cofeteltel3 )
        VALUES 
          ( cNumCte, iSecuencia, cTipoDirCon, pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad, 
          pmunicipio, pcodpostal, pApart_postal, ptipotel1, ptelefono1, ptipotel2, ptelefono2, ptipotel3, ptelefono3, pextension, 
          pestado_inegi, '', plocalidad_inegi, pnociudad, pnoext, pnoint, pdepto, pnocalle, 
          pnocolonia, ppuntocar, punihabi, pmanz, ppotros, pandador, petapa, plote, pedif, pentrada, pobserva, 
          cNumCteConyuge, cUsuario, dFechaHoy, pCofeteltel1, pCofeteltel2, pCofeteltel3 );
          --( cNumCte, iSecuencia, '1', pcalle, pcolonia, pentre_calles, ppais, pentidad, plocalidad,         
    END IF;
    
    RETURN cCodRet;

    END;
    
END PROCEDURE
DOCUMENT
'DOCUMENTACION:',
' Modificación : Rodolfo Tortolero Varela',
'        Fecha : 19/06/2013',
'Funcionalidad : Se agrega parametro de entrada para identificar el tipo de dirección(Casa o Trabajo) del cliente conyuge.';

CREATE PROCEDURE "informix".sp_refdirecciones_cjunk(
                                     pEmpresa           CHAR(3),
                                     pTipo              CHAR (1),
                                     pFuncion           CHAR(1),
                                     pNumCte            CHAR(20),
                                     pSecuencia         INTEGER,
                                     pTiipoDir          CHAR(1),
                                     pCalle             CHAR(40),
                                     pColonia           CHAR(60),
                                     pMunicipio         CHAR(5),
                                     pEntreCalles       CHAR(40),
                                     pPais              CHAR(3),
                                     pEntidad           CHAR(2),
                                     pLocalidad         CHAR(3),
                                     pCodPostal         CHAR(5),
                                     pTipoTel1          CHAR(1),
                                     pTelefono1         CHAR(13),
                                     pTipoTel2          CHAR(1),
                                     pTelefono2         CHAR(13),
                                     pTipoTel3          CHAR(1),
                                     pTelefono3         CHAR(13),
                                     pExtension         CHAR(5),
                                     pEstadoInegi       CHAR(2),
                                     pMunicipioInegi    CHAR(3),
                                     pLocalidadInegi    CHAR(4),
                                     pNoCiudad          SMALLINT,
                                     pNoExt             CHAR(10),
                                     pNoInt             CHAR(10),
                                     pDepto             CHAR(6),
                                     pNoCalle           INTEGER,
                                     pNoColonia         INTEGER,
                                     pPuntocar          CHAR(1),
                                     pUniHabi           CHAR(1),
                                     pManz              SMALLINT,
                                     pPotros            SMALLINT,
                                     pAndador           SMALLINT,
                                     pEtapa             SMALLINT,
                                     pLote              SMALLINT,
                                     pEdif              SMALLINT,
                                     pEntrada           SMALLINT,
                                     pObserva           CHAR(80),
                                     pUserInsert        CHAR(8),
                                     pFechaInsert       DATE,
                                     pNumCteBanco       CHAR(20))
	 RETURNING CHAR(5);
	
	--DEFINICION DE VARIABLES
	
	DEFINE cCodRet          CHAR(40);
	DEFINE cNombre          CHAR(40);
	DEFINE cNumcte          CHAR(20);
	DEFINE iSqlErr          INTEGER;
	DEFINE cDescFijoMovil   CHAR(5);
	DEFINE cResulFijoMovil  CHAR(5);
	DEFINE iFijoMovil1      INTEGER;
	DEFINE iFijoMovil2      INTEGER;
	DEFINE iFijoMovil3      INTEGER;
	
	--INICILIZACION DE VARIABLES
	
	LET cCodRet         = '';
	LET cNombre         = '';
	LET cNumcte         = '';
	LET iSqlErr         = 0;
	LET cDescFijoMovil  = '';
	LET cResulFijoMovil = '';
	LET iFijoMovil1     = 0;
	LET iFijoMovil2     = 0;
	LET iFijoMovil3     = 0;
	
	--SET DEBUG FILE TO "/tmp/sp_refdirecciones_cjunk.out";
	--TRACE ON;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr != 0 THEN
				LET cCodRet=iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		LET cCodRet = "000";
		LET pTipo = pTipo;

		SELECT numcte INTO cNumcte 
		FROM "informix".si_cliente
		WHERE numcte = pNumCte;
		IF cNumcte IS NULL THEN
			LET cCodRet = "104";
			RETURN cCodRet;
		END IF

		IF pFuncion="A" THEN
		{
			SELECT nombre INTO cNombre
			FROM "informix".si_paises
			WHERE pais = pPais;
			IF cNombre IS NULL THEN
				LET cCodRet="121";
				RETURN cCodRet;
			END IF;

			SELECT nombre INTO cNombre
			FROM "informix".si_estados
			WHERE pais=pPais AND estado=pEntidad;

			IF cNombre IS NULL THEN
				LET cCodRet="122";
				RETURN cCodRet;
			END IF;

			SELECT nombre INTO cNombre
			FROM "informix".si_ciudades
			WHERE pais=pPais AND estado=pEntidad AND ciudad=pLocalidad;
			IF cNombre IS NULL THEN
				LET cCodRet="123";
				RETURN cCodRet;
			END IF;
		}
		 
			IF pTipo = '1' THEN 
				
				IF pTelefono1 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono1) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil1;
					LET pTipoTel1 = 'P';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil1 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil1 = 1;
					ELSE
						LET iFijoMovil1 = 0;
					END IF;
				END IF;
				
				IF pTelefono2 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono2) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil2;
					LET pTipoTel2 = 'C';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil2 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil2 = 1;
					ELSE
						LET iFijoMovil2 = 0;
					END IF;
				END IF;
				
				IF pTelefono3 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono3) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil3;
					LET pTipoTel3 = 'O';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil3 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil3 = 1;
					ELSE
						LET iFijoMovil3 = 0;
					END IF;
				END IF;
				
				UPDATE {+INDEX ("informix".si_refdirecciones idx_si_refdirecciones)} "informix".si_refdirecciones SET
					(calle,colonia,entre_calles,
					pais,estado,ciudad,municipio,cod_postal,apart_postal,
					estado_inegi,municipio_inegi,localidad_inegi,
					numerociudad,numeroextcalle,numerointcalle,departamento,
					numerocalle,numerocolonia,puntocardinal,unidadhabitac,
					manzana,otros,andador,etapa,lote,edIFicio,entrada,observaciones,
					user_insert,fecha_insert,numcte_banco,movil_fijo1,movil_fijo2,movil_fijo3) = 
					(NVL(pCalle,''), NVL(pColonia,''), NVL(pEntreCalles,''),
					NVL(pPais,''),NVL(pEntidad,''),NVL(pLocalidad,''), NVL(pMunicipio,''), NVL(pCodPostal,''),"",
					NVL(pEstadoInegi,''),NVL(pMunicipioInegi,''),NVL(pLocalidadInegi,''),
					NVL(pNoCiudad,0),NVL(pNoExt,''),NVL(pNoInt,''),NVL(pDepto,''),
					NVL(pNoCalle,0),NVL(pNoColonia,0),NVL(pPuntocar,''),NVL(pUniHabi,''),
					NVL(pManz,0),NVL(pPotros,0),NVL(pAndador,0),NVL(pEtapa,0),NVL(pLote,0),NVL(pEdif,0),NVL(pEntrada,0),NVL(pObserva,''),
					NVL(pUserInsert,''),pFechaInsert,NVL(pNumCteBanco,''),iFijoMovil1,iFijoMovil2,iFijoMovil3)
					WHERE numcte = pNumCte
					AND secuencia = pSecuencia;
				
			ELIF pTipo = '0' THEN 
				IF pTelefono1 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono1) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil1;
					LET pTipoTel1 = 'P';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil1 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil1 = 1;
					ELSE
						LET iFijoMovil1 = 0;
					END IF;
				END IF;

				IF pTelefono2 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono2) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil2;
					LET pTipoTel2 = 'C';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil2 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil2 = 1;
					ELSE
						LET iFijoMovil2 = 0;
					END IF;
				END IF;

				IF pTelefono3 <> '' THEN
					-- // VERIFICA SI ES MOVIL O FIJO   
					EXECUTE PROCEDURE "informix".sp_tipored (pEmpresa, pTelefono3) INTO cResulFijoMovil, cDescFijoMovil, iFijoMovil3;
					LET pTipoTel3 = 'O';
					IF cDescFijoMovil = 'FIJO' THEN
						LET iFijoMovil3 = 0;
					ELIF cDescFijoMovil = 'MOVIL' THEN
						LET iFijoMovil3 = 1;
					ELSE
						LET iFijoMovil3 = 0;
					END IF;
				END IF;

				--INSERT INTO bdinteg:"informix".si_refdirecciones
				--	(numcte,secuencia,tipo_dir,tipo_telef1,telefono1,tipo_telef2, telefono2,tipo_telef3, telefono3, extension)
				--VALUES
				--	(pNumCte,pSecuencia,pTiipoDir,pTipoTel1,pTelefono1,pTipoTel2,pTelefono2,pTipoTel3,pTelefono3,pExtension);				
				

				INSERT INTO "informix".si_refdirecciones
					(numcte, secuencia, tipo_dir, calle, colonia, entre_calles,
					pais, estado, ciudad, municipio, cod_postal, apart_postal,
					tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3,
					extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, 
					numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
					puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, 
					entrada, observaciones, numcte_banco, user_insert, fecha_insert, movil_fijo1, status_stel1, 
					movil_fijo2, status_stel2 , movil_fijo3, status_stel3 )
				VALUES
					(pNumCte, pSecuencia, pTiipoDir, NVL(pCalle,''), NVL(pColonia,''), NVL(pEntreCalles,''), 
					NVL(pPais,''), NVL(pEntidad,''), NVL(pLocalidad,''), NVL(pMunicipio,''), NVL(pCodPostal,''), "", 
					pTipoTel1, pTelefono1, pTipoTel2, pTelefono2, pTipoTel3, pTelefono3, 
					pExtension, NVL(pEstadoInegi,''), NVL(pMunicipioInegi,''), NVL(pLocalidadInegi,''), NVL(pNoCiudad,0), 
					NVL(pNoExt,''), NVL(pNoInt,''), NVL(pDepto,''), NVL(pNoCalle,0), NVL(pNoColonia,0), NVL(pPuntocar,''), 
					NVL(pUniHabi,''), NVL(pManz,0), NVL(pPotros,0), NVL(pAndador,0), NVL(pEtapa,0), NVL(pLote,0), NVL(pEdif,0), 
					NVL(pEntrada,0), NVL(pObserva,''), NVL(pNumCteBanco,''), NVL(pUserInsert,''), CURRENT, iFijoMovil1, '', iFijoMovil2 , '', iFijoMovil3, '');
				
			END IF;
			RETURN cCodRet;
		END IF;
	END;
END PROCEDURE
DOCUMENT
'DOCUMENTACION:',
'Realizó: Martha Aguirre',
'Fecha: 31/01/2009',
'Funcionalidad: Inserta en la tabla si_refdirecciones las direcciones de las referencias de los clientes solicitantes de Crédito',
'------------------------------------------------------------------------------------------------------------------------------------',
'Realizó: Rodolfo Tortolero Varela',
'Fecha: 28/09/2011',
'Funcionalidad: Cuando el pTipo = 0, Validar los campos para que no se inserten nulos',
'------------------------------------------------------------------------------------------------------------------------------------',
'Modifico: Claudio Almodovar',
'Fecha: 19/04/2013',
'BDD: bdinteg',
'Descripcion: Se modifica UPDATE E INSERT para agregar parametros iFijoMovil1, iFijoMovil2, iFijoMovil3',
'------------------------------------------------------------------------------------------------------------------------------------',
'Modifico: Rodolfo Tortolero Varela',
'Fecha: 10/06/2013',
'BDD: bdinteg',
'Descripcion: Se agrega validación para validar de acuerdo a la descripción obtenida: ',
'             Si cDescFijoMovil es "FIJO"  - iFijoMovil1, iFijoMovil2, iFijoMovil3 = 0 ',
'             Si cDescFijoMovil es "MOVIL" - iFijoMovil1, iFijoMovil2, iFijoMovil3 = 1 ';

CREATE PROCEDURE "informix".sp_compara_tel(pEmpresa CHAR(3), pNumCteTitular CHAR(20), pTelefono CHAR(13), pTipoTel INTEGER, pNumCteCompara CHAR(20), pFuncion CHAR(1))
RETURNING CHAR(5);

DEFINE cCodret            CHAR(5);
DEFINE iTipo_tel          INTEGER;
DEFINE cTelefono          CHAR(13);
DEFINE cTelefonoCompara   CHAR(13);
DEFINE iTipo_telCompara   INTEGER;
DEFINE iBand              INTEGER;
DEFINE iSql_err           INTEGER;
DEFINE cSecuencia         CHAR(20);


	--SET DEBUG FILE TO '/tmp/sp_compara_tel.out';
	--TRACE ON;

LET cCodret          = '00000';
LET cTelefono        = '';
LET cTelefonoCompara = '';
LET iTipo_tel        = 0;
LET iTipo_telCompara = 0;
LET iBand            = 0;
LET iSql_err         = 0;
LET cSecuencia       = '';


BEGIN

    ON EXCEPTION SET iSql_err
        LET cCodret = CAST(iSql_err AS CHAR);    
        RETURN cCodret;
    END EXCEPTION;	
		
SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

    IF TRIM(NVL(pEmpresa,'')) <> '' AND TRIM(NVL(pNumCteTitular,'')) <> '' AND TRIM(NVL(pFuncion,'')) <> '' THEN
	
        IF pFuncion = '1' THEN --validacion del telefono a guardar comparandolo los telefonos guardados previamente 
            IF NVL(pTipoTel,0) = 1 OR NVL(pTipoTel,0) = 2 OR NVL(pTipoTel,0) = 3 OR NVL(pTipoTel,0) = 4 THEN
		        FOREACH
                    SELECT telefono, tipo_tel 
                    INTO cTelefono, iTipo_tel
                    FROM "informix".si_telefonos_actual 
                    WHERE empresa = pEmpresa 
                    AND numcte  = pNumCteTitular 
                    AND status_tel = 'A'  
	 
                    IF TRIM(pTelefono) = TRIM(cTelefono) AND iTipo_tel <> pTipoTel THEN 
                        LET iBand = 1;
                    END IF;
	
                END FOREACH;
			ELSE
			    LET iBand = 3;
			END IF;
        ELIF pFuncion = '2' THEN --elimina telefono de la si_telefonos_actual y cansela los de la si_telefonos   
	        IF NVL(pTipoTel,0) = 1 OR NVL(pTipoTel,0) = 2 OR NVL(pTipoTel,0) = 3 OR NVL(pTipoTel,0) = 4 THEN
			
			    IF EXISTS(SELECT telefono FROM "informix".si_telefonos WHERE empresa = pEmpresa AND numcte  = pNumCteTitular 
                AND status_tel = 'A' AND tipo_tel = pTipoTel) THEN
                    UPDATE "informix".si_telefonos SET status_tel = 'C' WHERE empresa = pEmpresa AND numcte = pNumCteTitular AND tipo_tel = pTipoTel;
				END IF;
			    
				IF EXISTS(SELECT telefono FROM "informix".si_telefonos_actual WHERE empresa = pEmpresa AND numcte  = pNumCteTitular 
                AND status_tel = 'A' AND tipo_tel = pTipoTel) THEN
                    DELETE FROM "informix".si_telefonos_actual WHERE empresa = pEmpresa AND numcte = pNumCteTitular AND tipo_tel = pTipoTel;
			    END IF;
				
			ELSE
			    LET iBand = 3;	
		    END IF;
        ELIF pFuncion = '3' THEN -- verifica si el cliente tiene un telefono de trabajo
	
            IF NOT EXISTS(SELECT telefono FROM "informix".si_telefonos_actual WHERE empresa = pEmpresa AND numcte  = pNumCteTitular 
            AND status_tel = 'A' AND tipo_tel = 3) THEN
                LET iBand = 1;
		    END IF;
		ELIF pFuncion = '4' THEN  --se uso para compara el numero de una referencia con los numeros del cliente titular
			IF  TRIM(NVL(pNumCteCompara,'')) <> '' THEN 
			
			    FOREACH
			        SELECT telefono
                    INTO cTelefonoCompara
                    FROM "informix".si_telefonos_actual 
                    WHERE empresa = pEmpresa 
                    AND numcte  = pNumCteCompara 
                    AND status_tel = 'A'  
					
			        IF TRIM(pTelefono) = TRIM(cTelefonoCompara) THEN
				        LET iBand = 1;
					END IF;
				    
                END FOREACH; 
			ELSE
			    LET iBand = 3;
            END IF;
		END IF;	
	ELSE
	
		IF pFuncion = '4' THEN  --se uso para compara el numero de una referencia con los numeros del cliente titular
	
            IF TRIM(NVL(pEmpresa,'')) <> '' AND TRIM(NVL(pNumCteCompara,'')) <> '' THEN 	
                
                FOREACH
			        SELECT telefono
                    INTO cTelefonoCompara
                    FROM "informix".si_telefonos_actual 
                    WHERE empresa = pEmpresa 
                    AND numcte  = pNumCteCompara 
                    AND status_tel = 'A'  
					
			        IF TRIM(pTelefono) = TRIM(cTelefonoCompara) THEN
				        LET iBand = 1;
					END IF;
				    
                END FOREACH; 
			ELSE
			    LET iBand = 3;
            END IF;
		ELSE
			LET iBand = 2;
		END IF;
	    
    END IF;
	
    LET cCodret = '000' || pFuncion || CAST(iBand AS CHAR);
	
RETURN cCodret;	
	
END;

END PROCEDURE
DOCUMENT
'AUTOR         : Felipe Urias',
'DESCRIPCION   : Este sp cuenta con cuatro funcionalidades para la validacion y manejo de los numeros telefonicos de los clientes',
'BASE DE DATOS : Bdinteg ',
'FECHA         : 19/04/2013';

CREATE PROCEDURE "informix".sp_alteratipodatofustelefonos()
RETURNING CHAR(5) AS CodRet;

    -- // Definicion de Variables
    DEFINE iSqlErr      INTEGER;
    DEFINE iIsamErr     INTEGER;
    DEFINE cDescErr     CHAR(50);
    DEFINE cCodRet      CHAR(5);
    DEFINE cCodRet2     CHAR(5);
    DEFINE cCodRet3     CHAR(50);
    DEFINE vabierto     CHAR(1);
    DEFINE cNumCte      CHAR(20);
    DEFINE cTelefono    CHAR(13);
    DEFINE siTipoTel    SMALLINT;
    DEFINE siSecuencia  SMALLINT;
    DEFINE cFechaHora   CHAR(23);
    DEFINE vcomienza    SMALLINT;
    DEFINE vcontador    INTEGER;

    -- // Inicializacion de Variables
    LET iSqlErr     = 0;
    LET iIsamErr    = 0;
    LET cDescErr    = '';
    LET cCodRet     = '000';
    LET cCodRet2    = '';
    LET cCodRet3    = '';
    LET vabierto    = '0';
    LET cNumCte     = '';
    LET cTelefono   = '';
    LET siTipoTel   = 0;
    LET siSecuencia = 0;
    LET cFechaHora  = '';
    LET vcomienza   = -1;
    LET vcontador   = 0;

    --SET DEBUG FILE TO '/tmp/sp_alteratipodatofustelefonos.out';
    --TRACE ON;

    BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, cDescErr
        --SET DEBUG FILE TO '/tmp/sp_alteratipodatofustelefonos.err';
        --TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            LET cCodRet2 = iIsamErr;
            LET cCodRet3 = cDescErr;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    -- // MODIFICACION EN si_telefonos
    ALTER TABLE "informix".si_fustelefonos ADD fecha_completa DATETIME YEAR TO SECOND BEFORE user_insert;

    FOREACH WITH HOLD
        SELECT numcte, telefono, tipo_tel, secuencia, fecha_hora
          INTO cNumCte, cTelefono, siTipoTel, siSecuencia, cFechaHora
          FROM "informix".si_fustelefonos
         --WHERE tipo_tel IN(1, 2, 3, 4)
         
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET vabierto = '1';
            BEGIN WORK;
        END IF;

        IF LENGTH(cFechaHora) = "23" THEN
            LET cFechaHora = SUBSTR(cFechaHora,1,19);
        ELIF LENGTH(cFechaHora) = "10" THEN
            LET cFechaHora = SUBSTR(TRIM(cFechaHora),7,10) || "-" || SUBSTR(TRIM(cFechaHora),1,2) || "-" || SUBSTR(TRIM(cFechaHora),4,5);
            LET cFechaHora = SUBSTR(cFechaHora,1,10) || " 00:00:00";
        END IF;
        
        LET cFechaHora = TRIM(cFechaHora);

        UPDATE "informix".si_fustelefonos 
           SET fecha_completa = cFechaHora 
         WHERE numcte = cNumCte 
           AND telefono = cTelefono 
           AND tipo_tel = siTipoTel 
           AND secuencia = siSecuencia;
           
        LET vcontador = vcontador + 1;
           
        IF vcontador >= 10000 THEN
            LET vcontador = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
        LET cNumCte     = '';
        LET cTelefono   = '';
        LET siTipoTel   = 0;
        LET siSecuencia = 0;
        LET cFechaHora  = '';
    END FOREACH;
    
    IF vabierto = '1' THEN
        LET vabierto = '0';
        COMMIT WORK;
    END IF;
    
    /*LET vcomienza = -1;
    LET vcontador = 0;
    
    -- // MODIFICACION EN si_telefonos_actual
    ALTER TABLE "informix".si_telefonos_actual ADD fecha_completa DATETIME YEAR TO SECOND BEFORE user_insert;
    
    FOREACH WITH HOLD
        SELECT numcte, telefono, tipo_tel, secuencia, fecha_hora
