CREATE PROCEDURE "informix".sp_reporte_huellas_aut()
	RETURNING
		CHAR(6) 	AS 	COD_RET,
		CHAR(80) 	AS MENSAJE_RET;
		
		
	--DECLARACION DE VARIABLES
	DEFINE cCodret 		 	CHAR(6);
	DEFINE iSqlErr        	INTEGER;
	DEFINE cMensaje       	CHAR(80);
	DEFINE cNumCte1			CHAR(20);
	DEFINE cApellPat1		CHAR(26);
	DEFINE cApellMat1		CHAR(26);
	DEFINE cNom1			CHAR(26);
	DEFINE cNom2			CHAR(26);
	DEFINE cRFC1			CHAR(13);
	DEFINE dtFechaNac1		DATE;
	DEFINE cNumCte2			VARCHAR(9);
	DEFINE cApellPat2		CHAR(26);
	DEFINE cApellMat2		CHAR(26);
	DEFINE cNom1_2			CHAR(26);
	DEFINE cNom2_2			CHAR(26);
	DEFINE cRFC2			CHAR(13);
	DEFINE dtFechaNac2		DATE;
	DEFINE cTicket			CHAR(20);
	DEFINE dtFechaCons		DATE;
	DEFINE dPorce			DECIMAL;
	DEFINE dtFechaInsert	DATE;
	DEFINE iDia         	INTEGER;
	
	
	DEFINE dFechaIni	DATE;
	DEFINE dFechaFin	DATE;
	DEFINE dFechaAux	DATE;
	
	
	

	--INICIALIZACION DE VARIABLES
	LET cCodret			= '00000';
	LET iSqlErr 		= 0;
	LET cMensaje		= 'PROCESO EXITOSO';
	LET cNumCte1		= '';
	LET cApellPat1		= '';
	LET cApellMat1		= '';
	LET cNom1			= '';
	LET cNom2			= '';
	LET cRFC1			= '';
	LET dtFechaNac1		= DATE(1);
	LET cNumCte2		= '';
	LET cApellPat2		= '';
	LET cApellMat2		= '';
	LET cNom1_2			= '';
	LET cNom2_2			= '';
	LET cRFC2			= '';
	LET dtFechaNac2		= DATE(1);
	LET cTicket			= '';
	LET dtFechaCons		= DATE(1);
	LET dPorce			= 0.0;
	LET dtFechaInsert	= DATE(1);


BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET cMensaje = "ERROR NO CONTROLADO";
			RETURN cCodret, cMensaje;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	SELECT day(fecha_hoy)  INTO  iDia FROM bdinteg:si_fechas;
	
	IF (iDia) <= 15 THEN --Reporte del 16 al 30
		SELECT   date( month(fecha) || '/16/' || year(fecha) ),fecha    INTO dFechaIni,dFechaFin
		FROM TABLE (multiset(
			select date(pri_dia_mes - interval(1) DAY TO DAY) as fecha  from bdinteg:si_fechas));
			
	ELIF (iDia) > 15 THEN --Reporte del 01 al 15
		SELECT pri_dia_mes, date( month(pri_dia_mes) || '/15/' || year(pri_dia_mes) )   INTO dFechaIni,dFechaFin FROM bdinteg:si_fechas;
		
	END IF;	
	
	--SET DEBUG FILE TO "/informix/ArmandoM/sp_huella_linea.out";
	--TRACE ON;

		SELECT DISTINCT LPAD(TRIM(cliente::CHAR(9)), 9,'0') numcte2, a.ticket, a.fecha, cte1.apell_paterno apell_pat_2, cte1.apell_materno apell_mat_2, cte1.nombre1 nom1_2, cte1.nombre2 nom2_2, cte1.rfc rfc_2, pf.fecha_nac fecha_nac2
		FROM si_huella_linea_resultado a,  si_cliente cte1, si_ctepf pf
		WHERE fecha  between dFechaIni and dFechaFin    -- parametro de entrada
		AND num_mensaje = '602' AND cliente <> '0' AND a.empresa = '5' AND pf.fecha_nac <= '01-01-1995'
		AND LPAD(TRIM(cliente::CHAR(9)), 9,'0') = cte1.numcte AND LPAD(TRIM(cliente::CHAR(9)), 9,'0') = pf.numcte

		INTO temp clientes_bcpl_dupl_2 WITH NO LOG;

		SET ISOLATION TO DIRTY READ;
		SELECT a.numcte numcte1, a.fecha_consulta, a.ticket, cte1.apell_paterno apell_pat_1, cte1.apell_materno apell_mat_1, cte1.nombre1 nom1_1, cte1.nombre2 nom2_1, cte1.rfc rfc_1, pf.fecha_nac fecha_nac1
		FROM si_huella_linea a, si_cliente cte1, si_ctepf pf
		WHERE (fecha_consulta between dFechaIni and dFechaFin) AND ticket IN
		(SELECT ticket FROM clientes_bcpl_dupl_2) AND a.numcte = cte1.numcte  AND a.numcte = pf.numcte
		
		INTO temp clientes_bcpl_dupl_1 WITH NO LOG;

		INSERT INTO si_clientes_huellas_dupl(numcte1, apell_pat_1, apell_mat_1, nom1_1, nom2_1, rfc_1, fecha_nac1, numcte2, apell_pat_2, apell_mat_2, nom1_2, nom2_2, rfc_2, fecha_nac2, ticket, fecha_consulta, fecha_insert)
			SELECT a.numcte1, a.apell_pat_1, a.apell_mat_1, a.nom1_1, a.nom2_1, a.rfc_1, a.fecha_nac1, b.numcte2, b.apell_pat_2, b.apell_mat_2, b.nom1_2, b.nom2_2, b.rfc_2, b.fecha_nac2, a.ticket, a.fecha_consulta, CURRENT AS fecha_insert
			FROM clientes_bcpl_dupl_1 a, clientes_bcpl_dupl_2 b
			WHERE a.ticket = b.ticket 
			AND b.fecha = a.fecha_consulta;
			
			
		EXECUTE PROCEDURE "informix".sp_compara_nombres()
		INTO cCodret;
	
		RETURN cCodret, cMensaje;
	END;	
END PROCEDURE;

CREATE PROCEDURE "informix".sp_bithuellasfusion (pCteCorrecto CHAR(9), pCteIncorrecto CHAR(9), pMensaje CHAR(2), pEjecutivo CHAR(8))
    RETURNING CHAR(5);

  DEFINE iSqlErr        INTEGER;
  DEFINE cCodret 		CHAR(5);
  DEFINE cMensaje 		CHAR(100);

  LET cCodret   = "00000";
  LET cMensaje  = "";
	
  --SET DEBUG FILE TO '/tmp/sp_bithuellasfusion.out';
  --TRACE ON;

BEGIN
  --MANDAR EL ERROR AL MENSAJE  
  ON EXCEPTION SET iSqlErr
            LET cMensaje = iSqlErr;
  END EXCEPTION;
    
  IF pMensaje=1 THEN
    LET cMensaje  = "Huellas Correctas.";
  ELIF pMensaje=2 THEN
    LET cMensaje  = "Las Huellas De Los Clientes No Coinciden";
  ELIF pMensaje=-1 THEN
    LET cMensaje  = "Las Huellas De Los Clientes Están Incompletas";
  ELIF pMensaje=-2 THEN
    LET cMensaje  = "Las Huellas De Los Clientes Son Invalidas";
  END IF

  INSERT INTO "informix".si_bitacora_comctes(cte_correcto, cte_incorrecto, ejecutivo, mensaje, fecha) 
    VALUES(pCteCorrecto, pCteIncorrecto, pEjecutivo, cMensaje, CURRENT);
  
 RETURN cCodret;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultabitacoraencuesta(pEmpresa CHAR(3))
RETURNING CHAR(5);

DEFINE cCodret            CHAR(5);
DEFINE sql_err 			  INTEGER;
DEFINE cNombreArchivo	  CHAR(64);
DEFINE vsql 			  CHAR(1000);
DEFINE cRuta              CHAR(50);
DEFINE cEmpresa           CHAR(3);
DEFINE cNumCte            CHAR(20);
DEFINE cTipo_Producto     CHAR(4);
DEFINE cTipo_Rechazo      CHAR(4);
DEFINE cDescripcion       CHAR(40);
DEFINE cSucursal          CHAR(4);
DEFINE cEjecutivo         CHAR(8);
DEFINE cNombre            CHAR(45);
DEFINE cfecha_insert      CHAR(10);
DEFINE dfecha_hoy         DATE;
DEFINE cfecha_inicio      CHAR(10);
DEFINE cfecha_fin         CHAR(10);
DEFINE cMostrarFecha      CHAR(10);
DEFINE iDias              INTEGER;
DEFINE iMes               INTEGER;
DEFINE cMes               CHAR(2);
DEFINE cNombreMes         CHAR(3);
DEFINE iAnio              INTEGER;
DEFINE iBiciesto          INTEGER;

LET cCodret               = '00000';
LET sql_err               = 0;
LET cEmpresa              = '';
LET cNumCte               = '';
LET cTipo_Producto        = '';
LET cTipo_Rechazo         = '';
LET cDescripcion          = '';
LET cSucursal             = '';
LET cEjecutivo            = '';
LET cNombre               = '';
LET cfecha_insert         = '';
LET dfecha_hoy            = '';
LET cfecha_inicio         = '';
LET cfecha_fin            = '';
LET cMostrarFecha         = '';
LET iDias                 = 0;
LET iMes                  = 0;
LET cMes                  = '';
LET cNombreMes            = '';
LET iAnio                 = 0;
LET iBiciesto             = 0;

--SET DEBUG FILE TO '/tmp/sp_consultabitacoraencuesta.out';
--TRACE ON;

BEGIN

	ON EXCEPTION SET sql_err
	    LET cCodret = sql_err;    
        RETURN cCodret;
	END EXCEPTION;	
		
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;	
	
    SELECT fecha_hoy INTO dfecha_hoy
    FROM "informix".si_fechas WHERE empresa = pEmpresa;
	
	IF NVL(dfecha_hoy,'') <> '' THEN
		LET iMes  =  MONTH(dfecha_hoy);
		LET iAnio =  YEAR(dfecha_hoy);
		
		IF iMes = 1 THEN
			LET iMes = 12;
			LET iAnio = iAnio -1;
		ELSE
			LET iMes = iMes -1; 
		END IF;
		
		LET cMes = LPAD(iMes,2,'0');
		
		LET cfecha_inicio =  cMes ||'/01/' || TO_CHAR(iAnio); 
		
		LET iBiciesto= MOD(iAnio,4);
		
		IF iMes = 1 THEN
			LET cNombreMes= "Ene";
			LET iDias = 31;
		ELIF  iMes = 2 THEN
			LET cNombreMes= "Feb";    
			LET iDias = 28;
			IF iBiciesto = 0 THEN 
				LET iDias = iDias+1;
			END IF;
		ELIF  iMes = 3 THEN
			LET cNombreMes= "Mar";
			LET iDias = 31;
		ELIF  iMes = 4 THEN
			LET cNombreMes= "Abr";
			LET iDias = 30;
		ELIF  iMes = 5 THEN
			LET cNombreMes= "May";
			LET iDias = 31;
		ELIF  iMes = 6 THEN
			LET cNombreMes= "Jun";
			LET iDias = 30;
		ELIF  iMes = 7 THEN
			LET cNombreMes= "Jul";
			LET iDias = 31;
		ELIF  iMes = 8 THEN
			LET cNombreMes= "Ago";
			LET iDias = 31;
		ELIF  iMes = 9 THEN
			LET cNombreMes= "Sep";
			LET iDias = 30;
		ELIF  iMes = 10 THEN
			LET cNombreMes= "Oct";
			LET iDias = 31;
		ELIF  iMes = 11 THEN
			LET cNombreMes= "Nov";
			LET iDias = 30;
		ELIF  iMes = 12 THEN
			LET cNombreMes= "Dic";
			LET iDias = 31;
		END IF;
		
		LET cfecha_fin    =  cMes || "/" || TO_CHAR(iDias) || "/" || TO_CHAR(iAnio);
		
		LET cNombreArchivo = "Reporte_encuesta_" || cNombreMes || iAnio;
		
		SELECT valor INTO cRuta
		FROM bdicred:"informix".sd_param WHERE cod_param = '109';
		
		IF NVL(cRuta,'') <> '' THEN
		
            IF EXISTS(SELECT NumCte FROM "informix".si_encuesta_cte WHERE fecha_insert >= cfecha_inicio AND fecha_insert <= cfecha_fin) THEN
		
			    FOREACH
					SELECT Empresa, NumCte, Tipo_Producto, Tipo_Rechazo, Descripcion, Sucursal, Ejecutivo, Nombre, fecha_insert
					INTO cEmpresa, cNumCte, cTipo_Producto, cTipo_Rechazo, cDescripcion, cSucursal, cEjecutivo, cNombre, cfecha_insert
					FROM "informix".si_encuesta_cte
					WHERE  fecha_insert >= cfecha_inicio AND fecha_insert <= cfecha_fin
					ORDER BY NumCte, Tipo_Producto, Tipo_Rechazo
					
					
					INSERT INTO "informix".si_encuesta_cte_hist (Empresa, NumCte, Tipo_Producto, Tipo_Rechazo, Descripcion, Sucursal, Ejecutivo, Nombre, fecha_insert)
					VALUES ( cEmpresa, cNumCte, cTipo_Producto, cTipo_Rechazo, cDescripcion, cSucursal, cEjecutivo, cNombre, cfecha_insert);
						
					LET cMostrarFecha = SUBSTR(cfecha_insert,4,2) || "/" || SUBSTR(cfecha_insert,1,2) || "/" || SUBSTR(cfecha_insert,7,4);
						
					LET vsql = 'echo "' || TRIM(cEmpresa) || '|' || Trim(cNumCte) || '|' || Trim(cTipo_Producto) || '|' || TRIM(cTipo_Rechazo) || '|' || Trim(cDescripcion) || '|' || Trim(cSucursal) || '|' || Trim(cEjecutivo) || '|' || Trim(cNombre) || '|' || TRIM( cMostrarFecha) || '" >> ' || TRIM(cRuta) ||  trim(cNombreArchivo) || '.txt';
					SYSTEM vsql;
					
			    END FOREACH;
			
			    DELETE FROM "informix".si_encuesta_cte WHERE fecha_insert >= cfecha_inicio AND fecha_insert <= cfecha_fin;
			
			ELSE
			    LET vsql = 'echo "" >> ' || TRIM(cRuta) ||  trim(cNombreArchivo) || '.txt';
				SYSTEM vsql;
				
			END IF;
		ELSE		
			LET cCodret = "00001";
		END IF;
	ELSE
		LET cCodret = "00002";
	END IF;
	
	RETURN cCodret;	
	
END;
END PROCEDURE
DOCUMENT
'AUTOR         : Felipe Urias',
'DESCRIPCION   : traspasa datos de encuesta de tabla principal a historial y genera archivo ',
'BASE DE DATOS : BDINTEG ',
'FECHA         : 05/02/2013';

CREATE PROCEDURE "informix".sp_guardabitacoraencuesta(pEmpresa CHAR(3), pNumCte CHAR(20), pTipoProd CHAR(4), pTipoRechazo CHAR(1),
	pDescripcion CHAR(40), pSucursal CHAR(4), pEjecutivo CHAR(8), pNombre CHAR(45))

--DATOS A REGRESAR--
RETURNING CHAR(5) AS CodigoRetorno;

--DEFINICION DE VARIABLES--
DEFINE cCodRet CHAR(5);
DEFINE iSqlErr INTEGER;
DEFINE cFecha  CHAR(10);

--INICIALIZACION DE VARIABLES--
LET cCodRet = '00000';
LET iSqlErr = 0;
LET cFecha = '';

--SET DEBUG FILE TO "/tmp/sp_guardabitacoraencuesta.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	IF pEmpresa = '' OR pEmpresa IS NULL OR pNumCte = '' OR pNumCte IS NULL OR pTipoProd = '' OR pTipoProd IS NULL 
		OR pTipoRechazo = '' OR pTipoRechazo IS NULL OR pSucursal = '' OR pSucursal IS NULL OR pEjecutivo = '' 
		OR pEjecutivo IS NULL OR pNombre = '' OR pNombre IS NULL THEN

		LET cCodRet = '00001'; --PARAMETRO DE ENTRADA VACIO.
		RETURN cCodRet;
	ELSE
		SELECT fecha_hoy INTO cFecha FROM si_fechas;

		INSERT INTO "informix".si_encuesta_cte(empresa, numcte, tipo_producto, tipo_rechazo, descripcion, sucursal, ejecutivo, nombre, fecha_insert)
			VALUES(pEmpresa, pNumCte, pTipoProd, pTipoRechazo, pDescripcion, pSucursal, pEjecutivo, pNombre, cFecha::DATE);

		RETURN cCodRet;
	END IF;
END;
END PROCEDURE
DOCUMENT
"CREO  : Daniela Ramírez",
"FECHA : 31/Enero/2013",
"BD    : bdinteg";

create procedure "informix".obtenerconexion_pba(pEmpresa char(3), pDSN char(15), pUsuario char(8))
	returning	char(3) as regreso, char(15) as instancia, char(15) as ip, integer as puerto, 
				char(15) as protocolo, char(15) as usuario, char(32) as password, char(15) as db, char(15) as dsn;
	
	define cRegreso char(3);
	define cInstancia char(15);
	define cIP char(15);
	define iPuerto integer;
	define cProtocolo char(15);
	define cUsuario char(15);
	define cPassword char(32);
	define cDB char(15);
	define cDSN char(15);
		
	let cRegreso='000';
	let cInstancia='';
	let cIP='';
	let iPuerto=0;
	let cProtocolo='';
	let cUsuario='';
	let cPassword='';
	let cDB='';
	let cDSN='';
	
set lock mode to wait 3;
set pdqpriority 0;

	begin
		
		select {+INDEX(si_ejecut idx_si_ejecut), +INDEX(si_perfil_ejecut idx_si_perfil_ejecut), +INDEX(si_ejecutdb idx_si_ejecutdb)} first 1 db.instancia, db.ip, db.puerto, db.protocolo, eje.asistente, eje.password, db.bd, db.dsn
		into cInstancia, cIP, iPuerto, cProtocolo, cUsuario, cPassword, cDB, cDSN
		from si_ejecut eje, si_perfil_ejecut per, si_ejecutdb db
		where eje.empresa=pEmpresa
			and eje.ejecutivo=pUsuario
			and per.cod_emp=eje.empresa
			and per.ejecutivo=eje.ejecutivo 			
			and db.sistema=per.sistema
			and db.dsn=pDSN;
	
		if cDSN is null then
			let cRegreso='001';
		end if;
		
		return cRegreso, cInstancia, cIP, iPuerto, cProtocolo, cUsuario, cPassword, cDB, cDSN;
	end	
end procedure;

CREATE PROCEDURE "informix".sp_compara_nombres()
    RETURNING
    CHAR(5);

    --DEFINICION DE VARIABLES--
    DEFINE porcentaje, porcentaje2, dPorcentajeFinal  DECIMAL(6,1);
    DEFINE iSqlErr        	INTEGER;
    DEFINE cCodRet      CHAR(5);
	DEFINE vnumcte1, vapell_pat_1, vapell_mat_1, vnom1_1, vnom2_1, vrfc_1, vnumcte2, vapell_pat_2, vapell_mat_2, vnom1_2, vnom2_2, vrfc_2  CHAR(40);
	LET porcentaje = 0;
	LET porcentaje2 = 0;
	LET cCodRet = '00000';
	LET iSqlErr=0;
	LET dPorcentajeFinal = 0;
	
	--	SET DEBUG FILE TO "/tmp/sp_ValidaNomBenefBTS.out";
    --	TRACE ON;
	
		
BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodret = iSqlErr;
				RETURN cCodret;
			END IF;
		END EXCEPTION;
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT  numcte1, apell_pat_1, apell_mat_1, nom1_1, nom2_1, rfc_1, numcte2, apell_pat_2, apell_mat_2, nom1_2, nom2_2, rfc_2 
			INTO vnumcte1, vapell_pat_1, vapell_mat_1, vnom1_1, vnom2_1, vrfc_1, vnumcte2, vapell_pat_2, vapell_mat_2, vnom1_2, vnom2_2, vrfc_2
			FROM bdinteg:si_clientes_huellas_dupl 
			WHERE porce_simil IS NULL
			
			EXECUTE PROCEDURE  bdisac:"informix".sp_validanombenefbts(vnom1_1, vnom2_1, vapell_pat_1, vapell_mat_1,
                                       vnom1_2, vnom2_2, vapell_pat_2, vapell_mat_2)
			INTO cCodRet, porcentaje;
			
			EXECUTE PROCEDURE  bdisac:"informix".sp_validanombenefbts(vnom1_2, vnom2_2, vapell_pat_2, vapell_mat_2,
                                       vnom1_1, vnom2_1, vapell_pat_1, vapell_mat_1)
			INTO cCodRet, porcentaje2;			
			
			LET dPorcentajeFinal = (porcentaje+porcentaje2)/2;
			
			IF( dPorcentajeFinal > 100.00) THEN 
				LET dPorcentajeFinal = 100.00;
			END IF;	
			
			UPDATE si_clientes_huellas_dupl SET porce_simil = dPorcentajeFinal WHERE numcte1 = vnumcte1 AND numcte2 = vnumcte2; 
			
		END FOREACH;
		
    RETURN cCodRet;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_mc_obteninfocliente(pEmpresa CHAR(3),pNumSol CHAR(20),pNumcte CHAR(20))
RETURNING 
	CHAR(6)  AS codigo_retorno,
	CHAR(80) AS mensaje_retorno,
	CHAR(30) AS Estado,			
	CHAR(30) AS Ciudad,			
	CHAR(27) AS Municipio,
	CHAR(32) AS Colonia,
	CHAR(30) AS Calle,		    
	CHAR(10) AS NumExt,		   
	CHAR(10) AS NumInt,		    
	CHAR(5)  AS CodPostal,       
	SMALLINT AS Edificio,        
	CHAR(6)  AS Depto,	
	CHAR(13) AS TelCasa,	
	CHAR(13) AS TelCel,		
	CHAR(13) AS TelTrab,		
	CHAR(5)  AS Ext,		
	CHAR(80) AS Complemento,				    
	CHAR(60) AS LugarTrabajo ,
	CHAR(120) AS Actividad,    
	CHAR(120) AS SubActividad, 
	CHAR(104) AS NombreCong, 		
	CHAR(13)  AS TelCong, 		
	CHAR(104) AS NombreR1, 		 
	CHAR(13)  AS TelR1, 	
	CHAR(20)  AS ParentestoR1,   	
	CHAR(104) AS NombreR2, 	
	CHAR(13)  AS TelR2,	
	CHAR(20)  AS ParentestoR2;   		    
---DECLARACIONES
DEFINE cCodRet          CHAR(6); 
DEFINE cMensajeRet      CHAR(80);
DEFINE cComentario      CHAR(80);
DEFINE iSqlErr      	INTEGER;
DEFINE iIsamErr         INTEGER;
DEFINE cErrorInfo       CHAR(80);
DEFINE cEstado			CHAR(30);
DEFINE cCiudad			CHAR(30);
DEFINE cMunicipio		CHAR(27);
DEFINE cColonia		    CHAR(32);

DEFINE cCalle		    CHAR(30);
DEFINE cNumExt		    CHAR(10);
DEFINE cNumInt		    CHAR(10);
DEFINE cCodPostal       CHAR(5);
DEFINE cDepto        	 CHAR(6);
DEFINE sEdificio	    SMALLINT;
DEFINE sTipoTel		    SMALLINT;
DEFINE cComplemento		CHAR(80);
DEFINE cTelCasa		CHAR(13);
DEFINE cTelCel		CHAR(13);
DEFINE cTel			CHAR(13);
DEFINE cTelTrab		CHAR(13);
DEFINE cExt		    CHAR(5);
DEFINE cLugarTrabajo CHAR(60);
DEFINE iActividad    INTEGER;
DEFINE iSubActividad INTEGER;
DEFINE cActividad    CHAR(120);
DEFINE cSubActividad CHAR(120);
--referencias
DEFINE cNombre 		 CHAR(104);
DEFINE cParentesco   CHAR(2);
DEFINE cDescParentesco CHAR(20);
DEFINE cTelRef 		CHAR(13);
DEFINE cNumcteRef   CHAR(20);
DEFINE cNombreCong 		CHAR(104);
DEFINE cParentestoCong  CHAR(20);
DEFINE cTelCong 		CHAR(13);
DEFINE cNombreR1 		CHAR(104);
DEFINE cParentestoR1    CHAR(20);
DEFINE cTelR1 	     	CHAR(13);
DEFINE cNombreR2 		CHAR(104);
DEFINE cParentestoR2    CHAR(20);
DEFINE cTelR2 		    CHAR(13);


---INICIALIZACIONES
LET iSqlErr             = 0;
LET iIsamErr            = 0;
LET cErrorInfo          = "";
LET cCodRet             = "000000";
LET cMensajeRet         = "Se realizó la consulta correctamente";

LET cEstado			= "";
LET cCiudad			= "";
LET cMunicipio		= "";
LET cColonia		= "";

LET cCalle		    = "";
LET cNumExt		    = "";
LET cNumInt		    = "";
LET cCodPostal      = "";
LET sEdificio       = "";
LET cDepto		    = 0;
LET cComplemento	= "";
LET cTelCasa		= "";
LET cTelCel			= "";
LET cTel			= "";
LET cTelTrab		= "";
LET cExt		    = "";
LET cLugarTrabajo   = "";
LET iActividad      = 0;
LET iSubActividad   = 0;
LET cActividad      = "";
LET cSubActividad   = "";
--referencias
LET cNombre 		= "";
LET cParentesco     = "";
LET cDescParentesco = "";
LET cTelRef 		= "";
LET cNumcteRef      = "";
LET cNombreCong 	= "";
LET cParentestoCong = "";
LET cTelCong 		= "";
LET cNombreR1 		= "";
LET cParentestoR1   = "";
LET cTelR1 	     	= "";
LET cNombreR2 		= "";
LET cParentestoR2   = "";
LET cTelR2 		    = "";

       
BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo   
     LET cCodRet= iSqlErr;
     RETURN cCodRet, cErrorInfo,cEstado,cCiudad,cMunicipio,cColonia,cCalle,cNumExt,cNumInt,cCodPostal,sEdificio,cDepto,cTelCasa,cTelCel,cTelTrab,cExt,
            cComplemento,cLugarTrabajo,cActividad,cSubActividad,cNombreCong,cTelCong,cNombreR1,cTelR1,cParentestoR1,cNombreR2,cTelR2,cParentestoR2;
END EXCEPTION;

--SET DEBUG FILE TO '/informix/jesus/sp_mc_obteninfocliente.out';
--TRACE ON;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;


	  --CONTROL DE ERRORES POR PARAMETRO--
	 IF NVL(pEmpresa, '' ) = '' OR NVL(pNumSol,'')= '' OR  NVL(pNumcte, '') = '' THEN
		LET cCodret = '000001';
		LET cMensajeRet = 'PARAMETROS DE ENTRADA INVALIDOS'; 
		RETURN cCodRet, cMensajeRet,cEstado,cCiudad,cMunicipio,cColonia,cCalle,cNumExt,cNumInt,cCodPostal,sEdificio,cDepto,cTelCasa,cTelCel,cTelTrab,cExt,
            cComplemento,cLugarTrabajo,cActividad,cSubActividad,cNombreCong,cTelCong,cNombreR1,cTelR1,cParentestoR1,cNombreR2,cTelR2,cParentestoR2;
	 END IF;
	 

   SELECT  TRIM(NVL(edo1.nombre,'')),TRIM(NVL(ciudad1.nombreciudad,'')),
			NVL(zonas1.poblacionzona, '') ,	NVL(zonas1.NombreZona,'')  ,
			NVL(calle1.nombrecalle,'') , TRIM(dir1.numeroextcalle) ,
			TRIM(dir1.numerointcalle) ,	LPAD(TRIM(dir1.cod_postal),5,'0') ,
			LPAD(dir1.edificio,5,'0') ,	RPAD(TRIM(dir1.departamento),6,' ') ,
			RPAD(TRIM(dir1.observaciones),80,' ')
		INTO cEstado,cCiudad,cMunicipio,cColonia,cCalle,cNumExt,cNumInt,cCodPostal,sEdificio,cDepto,cComplemento
	FROM "informix".si_direcciones_actual dir1        
	LEFT OUTER JOIN "informix".si_estados     edo1    ON (edo1.estado = dir1.estado)
	LEFT OUTER JOIN "informix".si_catciudades ciudad1 ON (ciudad1.numerociudad = dir1.numerociudad)
	LEFT OUTER JOIN "informix".si_catzonas    zonas1  ON (dir1.numerociudad = zonas1.numerociudad and dir1.numerocolonia = zonas1.numerocolonia)
	LEFT OUTER JOIN "informix".si_catcalles   calle1  ON (dir1.numerocalle  = calle1.numerocalle) 
	WHERE dir1.numcte = pNumcte 
	AND   dir1.tipo_dir  = '1'
	AND NVL(dir1.secuencia,0) = (SELECT NVL(MAX(secuencia),0) 
							     FROM "informix".si_direcciones_actual dir 
								 WHERE dir.tipo_dir = dir1.tipo_dir AND dir.numcte = pNumcte);
	

	FOREACH 
		SELECT telefono,extension,tipo_tel
			INTO cTel,cExt,sTipoTel
		FROM "informix".si_telefonos_actual a	 
		WHERE a.empresa = '001' 
		AND a.numcte = pNumcte 
		AND a.tipo_tel IN (1,2,3)		
		AND a.status_tel = 'A'
		
		IF sTipoTel = 1 THEN
			LET cTelCasa =cTel;
			LET cExt = "";
		ELIF sTipoTel = 2 THEN
			LET cTelCel = cTel;
			LET cExt = "";
		ELIF sTipoTel = 3 THEN
			LET cTelTrab = cTel;
			LET cExt = cExt;
		END IF;
	
	END FOREACH;						 
		
		
		
		
	SELECT nombre_empresa,claveopcionpuesto ,clavesubopcionpuesto 	
		INTO cLugarTrabajo,iActividad,iSubActividad
	FROM "informix".si_ingresos 
	WHERE empresa = pEmpresa
	AND numcte = pNumcte
	AND tipo_ingreso='T'
	AND sec_ingreso= (SELECT MAX(sec_ingreso)
					FROM "informix".si_ingresos  
					WHERE empresa = pEmpresa 
					AND numcte = pNumcte
					AND tipo_ingreso='T');
		
	SELECT descrip 
	INTO cActividad
	FROM "informix".si_actsubact
	WHERE id_act =  iActividad AND id_subact = 0;

	SELECT descrip 
	INTO cSubActividad
	FROM  "informix".si_actsubact
	WHERE id_act =  iActividad AND id_subact = iSubActividad;
	  
	IF NVL(cActividad,"") = "" THEN
		LET cActividad = cSubActividad;
		LET cSubActividad ="";
	END IF;

	FOREACH
	
		SELECT NVL(refe.nombre_ref, "" ) , refe.parentesco,par.descripcion , NVL(refe.telefono_ref, "") ,refe.numcte_ref
			INTO cNombre,cParentesco, cDescParentesco,cTelRef,cNumcteRef
		FROM bdisolic:"informix".ss_refpersonales AS refe
		INNER JOIN "informix".si_parentesco AS par ON (refe.parentesco = par.parentesco) 
		WHERE refe.num_solicitud  = pNumSol		
		
		
		 IF cParentesco = "E" THEN
			LET cTelCong= cTelRef;
			SELECT TRIM(nombre1)||' '||TRIM(nombre2)||' '||TRIM(apell_paterno)||' '||TRIM(apell_materno)
				INTO cNombreCong
			FROM "informix".si_cliente
			WHERE empresa = '001'
			AND numcte = cNumcteRef;
			
			LET cNombreR2 = "";
			LET cParentestoR2 = "";
			LET cTelR2= "";
		 END IF;
		 IF cNumcteRef = "R1" AND  cParentesco <> "E" THEN
			LET cNombreR1 = cNombre;
			LET cParentestoR1= cDescParentesco;
			LET cTelR1= cTelRef;
		 ELIF cNumcteRef <> "R1" AND  cParentesco <> "E" THEN
			LET cNombreR2 = cNombre;
			LET cParentestoR2 = cDescParentesco;
			LET cTelR2= cTelRef;
		 END IF

	END FOREACH;     		  
	
	 
	RETURN cCodRet, cMensajeRet,cEstado,cCiudad,cMunicipio,cColonia,cCalle,cNumExt,cNumInt,cCodPostal,sEdificio,cDepto,cTelCasa,cTelCel,cTelTrab,cExt,
            cComplemento,cLugarTrabajo,cActividad,cSubActividad,cNombreCong,cTelCong,cNombreR1,cTelR1,cParentestoR1,cNombreR2,cTelR2,cParentestoR2;
	
END
END PROCEDURE
