LET mRetencionIsr = 0;
LET iDias = 0;
LET dTasaBruta = 0;
LET mAux1 = 0;
LET vsec_dir = 0;
LET iAnioMes = 0;
LET pcuenta = '';
LET mSaldoRet = '';
LET cTipoPersona = "";
LET mtotOtroscargos= 0;
LET mGat = 0;
LET mTotretirosefe = 0;
LET pSufijo="";

--INICIALIZA VARIABLES DE sp_ConsultaEdoCtaParam
LET cCodretEdoCta  = "000";
LET cNomFis        = '';
LET cNomNoFis      = '';
LET cDescripcion   = '';
LET cFechaGrafica  = '';
LET cGrafica       = '0';
LET cProac         = '0';

--INICIALIZA VARIABLES DE sp_ObtieneInfoCteChq
LET cCodRetInfCte   			= '00000';
--LET cNumCte	 					= '';
LET cCuenta	 					= '';
LET cStatus	 					= '';
LET cMotivo	 					= '';
LET cOpcion	 					= '';
LET mSdoDisponible				= 0.00;
LET mSdoRetenido				= 0.00;
LET mSdoCongelado				= 0.00;
LET mSdoActual					= 0.00;
LET cProductoCta				= '';
LET mSBC						= 0.00;
LET sDireccionEnvio				= 0;
LET dFechaUltimoMov				= '01/01/1900';
LET cStatusTarjeta				= '';
LET cTipoTarjeta				= '';
LET cProductoTarjeta			= '';
LET cNombreCteOEmpresa 			= '';
LET cFechaNacOConstitucion 		= '01/01/1900';
LET cFirmantes					= '';
LET cDescripcionProducto 		= '';
LET cFechaAltaCta				= '01/01/1900';
LET cDireccioEnvioMaenoc 		= '';
LET mSdoRetenidoMesAnterior 	= 0.00;
LET mSdoCongeladoMesAnterior 	= 0.00;
LET mSdoRetenidoActualHistorico = 0.00;
LET mSdoCongeladoActualHistorico  = 0.00;
LET mSdoSobreGiroHistorico 		= 0.00;
LET dFechaHoy					= '01/01/1900';
LET mSBCMaehis					= 0.00;

--INICIALIZA VARIABLES DE ENTRADA DE sp_RegistraEncabezadoEdoCta
LET  pEmpresa 			= '001';
LET  pUsuario 			= '';
LET  pCuenta			= '';
LET  pProducto			= '';
LET  pNumTarjeta		= '';
LET  pClabe				= '';
LET  pFechaIni			= '';
LET  pFechaFin			= '';
LET  pSaldoAnterior		= 0;
LET  pDepositos			= 0;
LET  pInteresesPagados	= 0;
LET  pRetiros			= 0;
LET  pOtrosCargos		= 0;
LET  pIvaOtrosCargos	= 0;
LET  pSaldoCorte		= 0;
LET  pSaldoPromedio		= 0;
LET  pRetencionISR		= 0;
LET  pInteresesNetos	= 0;
LET  pDias				= 0;
LET  pTasaBruta			= 0;
LET  pNumCte			= '';
LET  pNombreCte			= '';
LET  pNumExterior		= '';
LET  pNumInterior		= '';
LET  pCalle				= '';
LET  pColonia			= '';
LET  pCiudad			= '';
LET  pEstado			= '';
LET  pCodPostal			= '';
LET  pRFC				= '';
LET  pCURP				= '';
LET  pFechaAlta			= '';
LET  pSucursal			= '';
LET  pRetMesAnt			= 0;
LET  pCongMesAnt		= 0;
LET  pSaldoRetenido		= 0;
LET  pSaldoCongelado	= 0;
LET  pSobreGiro			= 0;
LET  ptotOtrosCargos	= 0;
LET  pGat 				= 0;
LET  pTotretirosefe		= 0;
LET iBandera=0;
LET cFechaI="";
LET cFechaF="";
LET mSaldo2=0;

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN
			cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
			TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
			pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
			pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
		END IF;
	END EXCEPTION;
	                  --SET DEBUG FILE TO "/tmp/sp_cnsif_edoctacap2.out";
	                  --TRACE ON;
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMCUENTA  = ''	OR
		cANIOMES   IS NULL OR
		cNUMEMP = '' THEN
		LET cCodRet = "00036";
		RETURN
		cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
		TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
		pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
		pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
	END IF;

	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'01','1')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
		RETURN  cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
				TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
				pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
				pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
	END IF;
	-- TERMINA VALIDACION

	SELECT NVL(COUNT(cuenta),0) into iexiste FROM bdicheq:sc_maechq WHERE cuenta  = cNUMCUENTA;
	IF iexiste  = 0 THEN
		LET cCodRet = "00009";
		RETURN
		cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
		TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
		pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
		pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
	END IF;



	SET ISOLATION TO DIRTY READ;

		EXECUTE PROCEDURE bdicheq:sp_edoctagenerales_central('001', cNUMCUENTA, cANIOMES, '0')
		INTO
		vcodret, cProducto, cNumProducto, cNumTarjeta, cClabe, dFechaIni, dFechaFin,
		mSaldoAnterior, mDepositos, mInteresesPagados, mRetiros, mOtrosCargos,
		mIvaOtrosCargos, mSaldoCorte, mSaldoPromedio, mRetencionIsr, mInteresesNetos,
		iDias, dTasaBruta, cNumCte, cNomcte, cNumExt,
		cNumInt, cNomCalle, cNomColonia, cNomCiudad, cNomEstado,
		cCodPostal, cRFC, cCurp, dFechaAlta, cNomSucursal, mSaldoRet,mtotOtroscargos, mGat, mTotretirosefe;

		IF vcodret  <> '000' THEN
            LET cCodRet = "00007"; --NUEVO ERROR
		RETURN
		cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
		TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
		pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
		pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
		END IF;

		IF cNumProducto <> '' THEN
			EXECUTE PROCEDURE bdicheq:sp_consultaedoctaparam (cNumProducto)
			INTO
			cCodretEdoCta, cNomFis, cNomNoFis, cDescripcion, cFechaGrafica, cGrafica, cProac;

			--LA COMPARACION ES CON 000
			IF cCodretEdoCta <> '000' THEN
				LET cCodRet = "00008";
				RETURN
				cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
				TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
				pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
				pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
			END IF;

			FOREACH
				EXECUTE PROCEDURE bdicheq:sp_obtieneinfoctechq (cNUMCUENTA,'','',cANIOMES)
				INTO
				cCodRetInfCte,cCuenta,cNumCte,cStatus,cMotivo,
				cOpcion,cDescripcionProducto,mSdoDisponible,
				mSdoRetenido,mSdoCongelado,mSdoActual,
				cProductoCta,mSBC,cClabe,sDireccionEnvio,dFechaUltimoMov,cNumTarjeta,
				cStatusTarjeta,cTipoTarjeta,cProductoTarjeta,cFechaAltaCta,cDireccioEnvioMaenoc,
				mSdoRetenidoMesAnterior,mSdoCongeladoMesAnterior,
				mSdoRetenidoActualHistorico,mSdoCongeladoActualHistorico,
				--mSdoSobreGiroHistorico,dFechaFin,cNombreCteOEmpresa,cRFC,cTipoPersona,
                mSdoSobreGiroHistorico,pFechaFin,cNombreCteOEmpresa,cRFC,cTipoPersona,
				cFechaNacOConstitucion,cFirmantes,mSBCMaehis
			END FOREACH;

			IF cCodRetInfCte <> '00000' THEN
				LET cCodRet = "00009";
				RETURN
				cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
				TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
				pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
				pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
			END IF;
		END IF;


        IF (cNumProducto='1200' OR cNumProducto='1600' OR cNumProducto='2200' OR cNumProducto='2600' OR cNumProducto='2800') THEN
            SELECT TRIM(descripcion) AS descrip INTO pSufijo FROM bdinteg:si_ctepm pm
                INNER JOIN bdinteg:si_sufijos suf
                    ON pm.sufijo=suf.codigo
                WHERE numcte=cNumCte;
			LET cNomCte=TRIM(cNomCte)|| " " ||pSufijo;
        END IF;

		--ASIGNA VALORES A INSERTAR
		LET  pUsuario 			= cNUMEMP;
		LET  pCuenta			= cNUMCUENTA;
		LET  pProducto			= cProducto;
		LET  pNumTarjeta		= cNumTarjeta;
		LET  pClabe				= cClabe;
		LET  pFechaIni			= dFechaIni;
		LET  pFechaFin			= dFechaFin;
		LET  pSaldoAnterior		= mSaldoAnterior;
		LET  pDepositos			= mDepositos;
		LET  pInteresesPagados	= mInteresesPagados;
		LET  pRetiros			= mRetiros;
		LET  pOtrosCargos		= mOtrosCargos;
		LET  pIvaOtrosCargos	= mIvaOtrosCargos;
		LET  pSaldoCorte		= mSaldoCorte;
		LET  pSaldoPromedio		= mSaldoPromedio;
		LET  pRetencionISR		= mRetencionIsr;
		LET  pInteresesNetos	= mInteresesNetos;
		LET  pDias				= iDias;
		LET  pTasaBruta			= dTasaBruta;
		LET  pNumCte			= cNumcte;
		LET  pNombreCte			= cNomCte;
		LET  pNumExterior		= cNumExt;
		LET  pNumInterior		= cNumInt;
		LET  pCalle				= cNomCalle;
		LET  pColonia			= cNomColonia;
		LET  pCiudad			= cNomCiudad;
		LET  pEstado			= cNomEstado;
		LET  pCodPostal			= cCodPostal;
		LET  pRFC				= cRFC;
		LET  pCURP				= cCurp;
		LET  pFechaAlta			= dFechaAlta;
		LET  pSucursal			= cNomSucursal;
		LET  pRetMesAnt			= mSdoRetenidoMesAnterior;
		LET  pCongMesAnt		= mSdoCongeladoMesAnterior;
		LET  pSaldoRetenido		= mSaldoRet;
		LET  pSaldoCongelado	= mSdoCongeladoActualHistorico;
		LET  pSobreGiro			= mSdoSobreGiroHistorico;
		LET  ptotOtrosCargos	= mtotOtroscargos;
		LET  pGat 				= mGat;
		LET  pTotretirosefe		= mTotretirosefe;
        LET  mSaldo2            = pSaldoCorte;

		EXECUTE PROCEDURE bdicheq:sp_registraencabezadoedocta (pEmpresa, pUsuario, pCuenta, pProducto, pNumTarjeta, pClabe, pFechaIni, pFechaFin, pSaldoAnterior, pDepositos,
		pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
		pDias, pTasaBruta, pNumCte, pNombreCte, pNumExterior, pNumInterior, pCalle, pColonia, pCiudad, pEstado, pCodPostal, pRFC,
		pCURP, pFechaAlta, pSucursal, pRetMesAnt, pCongMesAnt, pSaldoRetenido, pSaldoCongelado, pSobreGiro, ptotOtrosCargos, pGat,
		pTotretirosefe)
		INTO
		cCodRetEnca, iConsultaMaxima;

		IF cCodRetEnca <> '00000' THEN
			LET cCodRet = "00010"; --NUEVO ERROR
			RETURN
			cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
			TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
			pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
			pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
		END IF;

		IF iConsultaMaxima > 0 THEN
		    FOREACH
				EXECUTE PROCEDURE bdicheq:sp_edoctamovtos_central('001', cNUMCUENTA,dFechaIni, dFechaFin,0,cNUMEMP,iConsultaMaxima)
				INTO
				cCodRetEdoCtaMov, cFechaMovEdoCtaMovto, cReferenciaEdoCtaMovto, cDescripcionEdoCtaMovto, mRetiroEdoCtaMovto,
				mDepositoEdoCtaMovto, mSaldoEdoCtaMovto, cSucursalEdoCtaMovto, cTransaccEdoCtaMovto, cNumTarjetaEdoCtaMovto
                IF cCodRetEdoCtaMov <> '000' and cCodRetEdoCtaMov <> '100' THEN
                    LET cCodRet = "00011"; --NUEVO ERROR
                    RETURN
                    cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
                    TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
                    pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
                    pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
                END IF;
                IF cFechaMovEdoCtaMovto<>'' THEN
                    LET cFechaMovEdoCtaMovto = SUBSTR(cFechaMovEdoCtaMovto,6,2) || '/' || SUBSTR(cFechaMovEdoCtaMovto,9,2) || '/' || SUBSTR(cFechaMovEdoCtaMovto,1,4);
                    IF cCodRetEdoCtaMov = '000' THEN
                        IF cTransaccEdoCtaMovto NOT IN ('0250','0232') THEN
                            IF mRetiroEdoCtaMovto>0 THEN
                                LET mSaldo2= mSaldo2 + mRetiroEdoCtaMovto;
                            ELIF mDepositoEdoCtaMovto>0 THEN
                                LET mSaldo2= mSaldo2 - mDepositoEdoCtaMovto;
                            END IF;
                        ELSE
                            LET mSaldo2= mSaldo2;
                        END IF;
                        EXECUTE PROCEDURE bdicheq:sp_grabaedoctamov('001', cNUMEMP, cNUMCUENTA, cFechaMovEdoCtaMovto, '', '', mRetiroEdoCtaMovto,
                        mDepositoEdoCtaMovto, mSaldo2, cDescripcionEdoCtaMovto, cReferenciaEdoCtaMovto, cSucursalEdoCtaMovto, '', '', '',iConsultaMaxima)
                        INTO
                        cCodRetGrabaEdoCtaMov;
                    END IF;

                    IF cCodRetGrabaEdoCtaMov <> '000' THEN
                        LET  cCodRet = '00012';	--
                        RETURN
                        cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
                        TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
                        pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
                        pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;
                    END IF;
                END IF;

			END FOREACH;
		END IF;

		LET dFechaAuxiliar = CAST(cFechaMovEdoCtaMovto AS DATE);

		IF cProac <> '0' THEN
			EXECUTE PROCEDURE  bdicheq:sp_proac_edocta('C',cNUMEMP,'001', cNUMCUENTA, pFechaIni, pFechaFin,0, iConsultaMaxima)
			INTO
			vCodRetProac, pEmpresaProac,pUsuarioProac,vCicloProac,cCuentaPROAC,dFechaMov1Proac,mRedondeoProac,mSaldo1Proac,mPremioProac,
			mSaldo2Proac,mGranTotalProac,dFecha_cancProac;

            SELECT fecha_canc INTO dFecha_cancProac FROM bdicheq:sc_proac WHERE cta_eje = cNUMCUENTA
            AND secuencia = (SELECT Max(secuencia) FROM bdicheq:sc_proac WHERE cta_eje = cNUMCUENTA AND status_cta IN ('1','3'))
            And status_cta IN ('1','3');

		END IF;

		LET  pEmpresa 			= '001';
		LET  pUsuario 			= '';
		LET  pCuenta			= '';
		LET  pProducto			= '';
		LET  pNumTarjeta		= '';
		LET  pClabe				= '';
		LET  pFechaIni			= '';
		LET  pFechaFin			= '';
		LET  pSaldoAnterior		= 0;
		LET  pDepositos			= 0;
		LET  pInteresesPagados	= 0;
		LET  pRetiros			= 0;
		LET  pOtrosCargos		= 0;
		LET  pIvaOtrosCargos	= 0;
		LET  pSaldoCorte		= 0;
		LET  pSaldoPromedio		= 0;
		LET  pRetencionISR		= 0;
		LET  pInteresesNetos	= 0;
		LET  pDias				= 0;
		LET  pTasaBruta			= 0;
		LET  pNumCte			= '';
		LET  pNombreCte			= '';
		LET  pNumExterior		= '';
		LET  pNumInterior		= '';
		LET  pCalle				= '';
		LET  pColonia			= '';
		LET  pCiudad			= '';
		LET  pEstado			= '';
		LET  pCodPostal			= '';
		LET  pRFC				= '';
		LET  pCURP				= '';
		LET  pFechaAlta			= '';
		LET  pSucursal			= '';
		LET  pRetMesAnt			= 0;
		LET  pCongMesAnt		= 0;
		LET  pSaldoRetenido		= 0;
		LET  pSaldoCongelado	= 0;
		LET  pSobreGiro			= 0;
		LET  ptotOtrosCargos	= 0;
		LET  pGat 				= 0;
		LET  pTotretirosefe		= 0;

		--LA COMPARACION ES CON 000
	/*	IF vCodRetProac <> '000' THEN
			LET  cCodRet = '00013';
			RETURN
            cCodRet,cANIOMES, pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
            TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
            pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
            pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cProac,dFecha_cancProac;
		END IF; */

		SELECT {+INDEX (bdicheq:vedocta idx_usu1)} empresa, cod_usuario, cuenta, producto, tarjeta, clabe, fechaini, fechafin, saldoanterior, depositos,
		interesespagados, retiros, otroscargos, ivaotroscargos, saldocorte, saldopromedio, retencionisr, interesesnetos,
		dias, tasabruta, numerocliente, nombrecliente, numeroexterior, numerointerior, calle, colonia, ciudad, estado, codigopostal, rfc,
		curp, fechaalta, sucursal, ret_mes_ant, cong_mes_ant, sdo_retenido, sdo_cong, sobregiro, consulta, totretirosefec, tototroscargos,porcientogat
		INTO
		pEmpresa, pUsuario, pCuenta, pProducto, pNumTarjeta, pClabe, pFechaIni, pFechaFin, pSaldoAnterior, pDepositos,
		pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
		pDias, pTasaBruta, pNumCte, pNombreCte, pNumExterior, pNumInterior, pCalle, pColonia, pCiudad, pEstado, pCodPostal, pRFC,
		pCURP, pFechaAlta, pSucursal, pRetMesAnt, pCongMesAnt, pSaldoRetenido, pSaldoCongelado, pSobreGiro, iConsultaMaxima, pTotretirosefe, ptotOtrosCargos, pGat
		FROM bdicheq:vedocta
	    WHERE cod_usuario=cNUMEMP AND consulta = iConsultaMaxima;

       IF MONTH(dFechaIni) = 1 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'ENE' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 2 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'FEB' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 3 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'MAR' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 4 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'ABR' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 5 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'MAY' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 6 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'JUN' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 7 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'JUL' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 8 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'AGO' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 9 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'SEP' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 10 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'OCT' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 11 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'NOV' ||  '/' || YEAR(dFechaIni);
       ELIF MONTH(dFechaIni) = 12 THEN
        LET cFechaI=DAY(dFechaIni) ||  '/' ||  'DIC' ||  '/' || YEAR(dFechaIni);
       END IF;


       IF MONTH(dFechaFin) = 1 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'ENE' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 2 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'FEB' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 3 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'MAR' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 4 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'ABR' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 5 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'MAY' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 6 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'JUN' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 7 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'JUL' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 8 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'AGO' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 9 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'SEP' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 10 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'OCT' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 11 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'NOV' ||  '/' || YEAR(dFechaFin);
       ELIF MONTH(dFechaFin) = 12 THEN
        LET cFechaF=DAY(dFechaFin) ||  '/' ||  'DIC' ||  '/' || YEAR(dFechaFin);
       END IF;


		RETURN
			cCodRet,cANIOMES,pNombreCte, pCalle, pNumExterior, pNumInterior, pColonia, pCiudad, pEstado, pCodPostal,
			TODAY, pRFC, pCURP, pSucursal, pFechaAlta, pNumCte, pCuenta, pNumTarjeta, pClabe, pSaldoAnterior, pDepositos,
			pInteresesPagados, pRetiros, pOtrosCargos, pIvaOtrosCargos, pSaldoCorte, pSaldoPromedio, pRetencionISR, pInteresesNetos,
            --pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, mSdoActual,iConsultaMaxima,cFechaI,cFechaF;
            pDias, pTasaBruta, pFechaFin, pGat,  pInteresesPagados, pOtrosCargos, pSaldoCorte,iConsultaMaxima,cFechaI,cFechaF,cGrafica,cFechaGrafica,dFecha_cancProac,ptotOtrosCargos,pTotretirosefe;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_updcte_fus8() 
RETURNING CHAR(5), CHAR(80);
--DEFINICION DE VARIABLES
DEFINE vc_CodRet        CHAR(5);
DEFINE vi_SqlErr        INTEGER;
DEFINE vi_iSAMErr        INTEGER;
DEFINE vi_iSAMData        CHAR(80);
DEFINE vc_Mensaje       CHAR(80);
DEFINE pClienteTitular        CHAR(20);
DEFINE pClienteTraspasaCtas        CHAR(20);
DEFINE vc_detalle_mov2   CHAR(200);
DEFINE vc_proceso       CHAR(50);
DEFINE vc_tabla         CHAR(30);
DEFINE vc_detalle_mov   CHAR(200);
DEFINE vc_Cuenta        CHAR(20);
DEFINE vc_Cuenta2        CHAR(20);
DEFINE vi_secuencia     INTEGER;
DEFINE vc_aniomes       CHAR(6);
DEFINE pCte        CHAR(20);
DEFINE vi_num_serial    INTEGER;
DEFINE vd_fecha_mov     DATE;
DEFINE iExiste     INTEGER;
--INICIALIZACION DE VARIABLES
LET vc_CodRet = "00000";
LET vi_SqlErr = 0;
LET vi_iSAMErr=0;
LET vi_secuencia = 0;
LET vi_iSAMData="";
LET vc_Mensaje = "EL PROCESO SE EFECTUO CORRECTAMENTE";
LET pClienteTitular="";
LET pClienteTraspasaCtas="";
LET vc_detalle_mov2 = "";
LET vc_proceso = "FusionClientes";
LET vc_tabla = "";
LET vc_detalle_mov = "";
LET vc_Cuenta = "";
LET vc_aniomes="";
LET vc_Cuenta2="";
LET pCte="";
LET vi_num_serial=0;
LET vd_fecha_mov = "";
LET iExiste=0;




set isolation to dirty read;
set lock mode to wait 3;

    BEGIN

    ON EXCEPTION SET vi_SqlErr,vi_iSAMErr,vi_iSAMData
        IF vi_SqlErr <> 0 THEN
            LET vc_CodRet = vi_SqlErr;
            LET vc_Mensaje = "ERROR NO CONTROLADO";
            LET vc_detalle_mov2=vi_SqlErr||'|'||vi_iSAMErr||'|'||vi_iSAMData; 
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov2, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            RETURN vc_CodRet, vc_Mensaje;
        END IF;
    END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/sp_updcte_fus8.out";
    --TRACE ON;


SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} DISTINCT TRIM(cliente_tit),TRIM(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>''

--**************************************INICIA TRASPASO DE TABLA SS_SOLICITUDES_MC ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(num_solicitud) INTO iExiste FROM bdisolic:ss_solicitudes_mc WHERE numcte=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT num_solicitud INTO vc_Cuenta FROM bdisolic:ss_solicitudes_mc WHERE numcte=pClienteTraspasaCtas
            LET vc_proceso='SOLICITUDES_MC';
            LET vc_tabla = "ss_solicitudes_mc";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fussolicitudes_mc 
            SELECT * FROM bdisolic:ss_solicitudes_mc WHERE num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;

            UPDATE bdisolic:ss_solicitudes_mc SET numcte = pClienteTitular where num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;
    --**********************************************************************************************************

    --**************************************INICIA TRASPASO DE TABLA SS_SOLICITUDES_SIC ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(num_solicitud) INTO iExiste FROM bdisolic:ss_solicitudes_sic WHERE numcte=pClienteTraspasaCtas;
    IF iExiste>0 THEN
        FOREACH
            SELECT num_solicitud INTO vc_Cuenta FROM bdisolic:ss_solicitudes_sic WHERE numcte=pClienteTraspasaCtas
            LET vc_proceso='SOLICITUDES_SIC';
            LET vc_tabla = "ss_solicitudes_sic";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fussolicitudes_sic 
            SELECT * FROM bdisolic:ss_solicitudes_sic WHERE num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;

            UPDATE bdisolic:ss_solicitudes_sic SET numcte = pClienteTitular where num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;
        END FOREACH;  
    END IF;
    --**********************************************************************************************************

    --**************************************INICIA TRASPASO DE TABLA SS_SOLICITUDES_CAC ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(num_solicitud) INTO iExiste FROM bdisolic:ss_solicitudes_cac WHERE numcte=pClienteTraspasaCtas;
    IF iExiste>0 THEN
        FOREACH 
            SELECT num_solicitud INTO vc_Cuenta FROM bdisolic:ss_solicitudes_cac WHERE numcte=pClienteTraspasaCtas
            LET vc_proceso='SOLICITUDES_CAC';
            LET vc_tabla = "ss_solicitudes_cac";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            INSERT INTO bdinteg:si_fussolicitudes_cac 
            SELECT * FROM bdisolic:ss_solicitudes_cac WHERE num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;

            UPDATE bdisolic:ss_solicitudes_cac SET numcte = pClienteTitular where num_solicitud=vc_Cuenta AND numcte=pClienteTraspasaCtas;
        END FOREACH;  
    END IF;
    --**********************************************************************************************************

END FOREACH;  


    IF vc_CodRet = "00000" THEN
        RETURN vc_CodRet, vc_Mensaje;
    END IF;
END;
END PROCEDURE;

create procedure "informix".sp_actualiza_domicilio(pEstado char(6), pOrigen char(8))
returning char(30);

    -- V7 Modif select del reg a insertar que sea tipo_dir 1
    -- V6 Validar en caso de que numerociudad sea 0
    -- V5 20100325 Quitar validación pOrigen = 'XASIGNAR'
    -- V4 20090923 Verificar que el registro no haya sido modificado antes, que user_insert <> 'XASIGNAR'
    -- V3 20090917 Omitir validación de colonia si es 8000.
    -- V2 20090324 Crear SP
    
    -- Define variables
    define cod_ret char(30);
    define sql_err integer;
    define v_numcte char(9);
    define v_numcalle integer;
    define v_numcolonia integer;
    define v_numerociudad integer;
    define v_estado char(5);
    define v_clave_estado char(2);
    define v_nombrecalle char(30);
    define v_conteocolonias smallint;
    define v_codpostal char(5);
    define v_ciudad char(4);
    define v_max_secuencia integer;
    define v_secuencia_r integer;
    define v_tipo_dir_r char(1);
    define v_calle_r char(40);
    define v_colonia_r char(60);
    define v_entre_calles_r char(40);
    define v_pais_r char(3);
    define v_estado_r char(2);
    define v_ciudad_r char(3);
    define v_municipio_r char(5);
    define v_cod_postal_r char(5);
    define v_apart_postal_r char(11);
    define v_tipo_telef1_r char(1);
    define v_telefono1_r char(13);
    define v_tipo_telef2_r char(1);
    define v_telefono2_r  char(13);
    define v_tipo_telef3_r char(1);
    define v_telefono3_r char(13);
    define v_extension_r char(5);
    define v_estado_inegi_r char(2);
    define v_municipio_inegi_r char(3);
    define v_localidad_inegi_r char(4);
    define v_numerociudad_r smallint;
    define v_numeroextcalle_r char(10);
    define v_numerointcalle_r char(10);
    define v_departamento_r char(6);
    define v_numerocalle_r integer;
    define v_numerocolonia_r integer;
    define v_puntocardinal_r char(1);
    define v_unidadhabitac_r  char(1);
    define v_manzana_r smallint;
    define v_otros_r smallint;
    define v_andador_r smallint;
    define v_etapa_r smallint;
    define v_lote_r smallint;
    define v_edificio_r smallint;
    define v_entrada_r smallint;
    define v_observaciones_r char(80);
    define v_user_insert_r char(8);
    define v_fecha_insert_r date;
    define v_strlog char(100);
    define v_user_insert char(8);
    define v_pais char(3);
    define v_Sucursal_r char(4);
    
     --SET DEBUG FILE TO "/informix/favmartinez/actualiza.out";
     --TRACE ON;
    
    -- Inicializa variables
    let cod_ret       = "000";
    let v_numcte      = "";
    let v_numcalle    = 0;
    let v_numcolonia  = 0;
    let v_numerociudad = 0;
    let v_estado = "";
    let v_clave_estado = "";
    let v_codpostal = "";
    let v_ciudad = "";
    let v_max_secuencia = 0;
    let v_nombrecalle = "";
    let v_conteocolonias = 0;
    let v_strlog = "";
    let v_user_insert = "";
    let v_pais= '001';
    let v_Sucursal_r ="";

    BEGIN

    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret;
        end if
    end exception;

    --SYSTEM 'echo ---- DATOS INCOMPLETOS DE CLIENTES ----- ' || v_numcte || '> ' || 'actualiza_domicilio.log';
    -- V4
    set lock mode to wait 3;

    foreach with hold
        select numcte, numerocalle, numerocolonia, numerociudad, estado, cod_postal ---Obtener cliente por cliente
          into v_numcte, v_numcalle, v_numcolonia, v_numerociudad, v_estado, v_codpostal
          from bdinteg:si_por_asignar
       where actualizacion_previa = 'N'

        -- V2
        if v_numcte is null or v_numcalle is null or v_numcolonia is null or v_numerociudad is null or v_estado is null or v_codpostal is null then
            let cod_ret = "00001" ;
            --SYSTEM 'echo Falta algun dato en tbl bdinteg:si_por_asignar, numcte: ' || v_numcte || '>> ' || 'actualiza_domicilio.log';
            -- return cod_ret;
            CONTINUE FOREACH;
        end if

        -- Valida la existencia del estado
        if pEstado = 'numero' then
            select estado 
              into v_clave_estado
              from bdinteg:si_estados
             where pais = v_pais
               and estado = v_estado;
        elif pEstado = 'siglas' then
            select estado 
              into v_clave_estado
              from bdinteg:si_estados
             where pais = v_pais
               and siglas = v_estado;
        end if

        if v_clave_estado is null then
            let cod_ret = "Estado inválido";
            --SYSTEM 'echo En cliente: ' || v_numcte || ' -- No existe el Estado: ' || v_estado || '>> ' || 'actualiza_domicilio.log';
            --return cod_ret;
            CONTINUE FOREACH;
        end if

        -- SYSTEM 'echo estado: ' || v_clave_estado ||   '>> ' || 'actualiza_domicilio.log';

        -- Valida la existencia del numerociudad
        if v_numerociudad = 0 then
            CONTINUE FOREACH;
        end if

        select numerociudad 
          into v_ciudad
          from bdinteg:si_catciudades
         where numerociudad = v_numerociudad;

        -- SYSTEM 'echo ciudad: ' || v_ciudad ||  '>> ' || 'actualiza_domicilio.log';

        if v_ciudad is null then
            let cod_ret = "No existe la ciudad";
            --SYSTEM 'echo En cliente: ' || v_numcte || ' -- No existe la ciudad: ' || v_numerociudad  ||'>> ' || 'actualiza_domicilio.log';
            --return cod_ret;
            CONTINUE FOREACH;
        end if

        --- Validacion de calle
        select nombrecalle 
          into v_nombrecalle
          from bdinteg:si_catcalles
         where numerocalle = v_numcalle;

        if v_nombrecalle is null then
            let cod_ret = "Número de calle inexistente";
            --SYSTEM 'echo En cliente:  ' || v_numcte || ' -- No existe la calle: ' || v_numcalle ||'>> ' || 'actualiza_domicilio.log';
            --return cod_ret;
            CONTINUE FOREACH;
        end if

        -- V3
        /*if v_numcolonia <> 8000 then
            --- Validacion de colonia
            select count(numerocolonia) 
              into v_conteocolonias
              from bdinteg:si_catzonas
             where numerocolonia = v_numcolonia;

            if v_conteocolonias = 0 then
                let cod_ret = "Número de colonia inexistente";
                SYSTEM 'echo En cliente: ' || v_numcte || '-- No existe la colonia: ' || v_numcolonia ||'>> ' || 'actualiza_domicilio.log';
                --return cod_ret;
                CONTINUE FOREACH;
            end if
        end if

        -- Obtener secuencia máxima.
        select max(secuencia) 
          into v_secuencia_r
          from bdinteg:si_direcciones_actual
         where numcte = v_numcte;
        -- and tipo_dir = '1';
*/
        -- Selecc para cada cliente el registro que tiene la maxima secuencia


        select d.tipo_dir, d.calle, d.colonia, d.entre_calles, d.pais, d.estado, d.ciudad, d.municipio, d.cod_postal, d.apart_postal, 
               /* d.tipo_telef1, d.telefono1, d.tipo_telef2, d.telefono2, d.tipo_telef3, d.telefono3, */
               d.estado_inegi, d.municipio_inegi, d.localidad_inegi, d.numerociudad, d.numeroextcalle, d.numerointcalle, 
               d.departamento, d.numerocalle, d.numerocolonia, d.puntocardinal, d.unidadhabitac, d.manzana, d.otros, d.andador, 
               d.etapa, d.lote, d.edificio, d.entrada, d.observaciones, d.user_insert, d.fecha_insert--, Sucursal
          into v_tipo_dir_r, v_calle_r, v_colonia_r, v_entre_calles_r, v_pais_r, v_estado_r, v_ciudad_r, v_municipio_r, v_cod_postal_r, v_apart_postal_r, 
               /* v_tipo_telef1_r, v_telefono1_r, v_tipo_telef2_r, v_telefono2_r, v_tipo_telef3_r, v_telefono3_r, v_extension_r, */
               v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad_r, v_numeroextcalle_r, v_numerointcalle_r, 
               v_departamento_r, v_numerocalle_r, v_numerocolonia_r, v_puntocardinal_r, v_unidadhabitac_r, v_manzana_r, v_otros_r, v_andador_r, 
               v_etapa_r, v_lote_r, v_edificio_r, v_entrada_r, v_observaciones_r, v_user_insert_r, v_fecha_insert_r --, v_Sucursal_r
          from  bdinteg:si_direcciones_actual d
         where d.numcte =  v_numcte
           and d.tipo_dir = '1';


    execute PROCEDURE "informix".direcciones( 
                                 '001',  'A', v_numcte, 0, 1, v_calle_r , v_colonia_r,  v_municipio_r, v_entre_calles_r,
                                 v_pais_r, v_clave_estado, v_ciudad_r, v_cod_postal_r,'','','','','','','',
                                 v_estado_inegi_r, v_municipio_inegi_r, v_localidad_inegi_r, v_numerociudad,
                                 v_numeroextcalle_r, v_numerointcalle_r, v_departamento_r, v_numcalle,
                                 v_numcolonia, v_puntocardinal_r, v_unidadhabitac_r,
                                         v_manzana_r,
                                         v_otros_r,
                                         v_andador_r,
                                         v_etapa_r,
                                         v_lote_r,
                                         v_edificio_r,
                                         v_entrada_r,
                                         v_observaciones_r,
                                         user,
                                         today,
                                         v_Sucursal_r,
                                         0 ) into cod_ret;
        begin work;
           update bdinteg:si_por_asignar
              set actualizacion_previa = 'S'
          --select numcte, numerocalle, numerocolonia, numerociudad, estado, cod_postal ---Obtener cliente por cliente
          --into v_numcte, v_numcalle, v_numcolonia, v_numerociudad, v_estado, v_codpostal          
         where numcte =v_numcte;
       commit work;
    end foreach;

    end
    
  --  let cod_ret = "Termina proceso";
    
  --  SYSTEM 'echo ----Termina el proceso-----' || '>> ' || 'actualiza_domicilio.log';
    
    return cod_ret;
    
end procedure;

CREATE PROCEDURE "informix".sp_consultarcorreccionesdatoscte_pba(pFechaInicial CHAR(10), pFechaFinal CHAR(10),p_NumCte CHAR(20), p_Tipo CHAR(1))
RETURNING
    CHAR (5)   AS  Cod_Ret,
	CHAR (26)  AS NumCte,
	CHAR (20)  AS Fecha,
	CHAR (13)  AS Rfc_Orig,
	CHAR (100) AS Nom_Ant,
	CHAR (13)  AS Rfc_Nvo,
	CHAR (100) AS Nom_Nvo,
	CHAR (8)   AS User_insert;

	--declaracion de variables
	DEFINE cCod_ret                 CHAR(5);
    DEFINE iSqlErr                  INTEGER;
    DEFINE iSamErr                  INTEGER;
	DEFINE cNumCte                  CHAR(20);
	DEFINE dFecha			        DATE;
	DEFINE cRfc_orig			    CHAR(13);
	DEFINE cNombre1_orig			CHAR(26);
	DEFINE cNombre2_orig			CHAR(26);
	DEFINE cApell_paterno_orig		CHAR(26);
	DEFINE cApell_materno_orig		CHAR(26);
	DEFINE cRfc_nvo			        CHAR(13);
	DEFINE cNombre1_nvo	            CHAR(26);
	DEFINE cNombre2_nvo		        CHAR(26);
	DEFINE cApell_paterno_nvo		CHAR(26);
	DEFINE cApell_materno_nvo		CHAR(26);
	DEFINE cNomCompletoAnterior     CHAR(100);
	DEFINE cNomCompletoActual 		CHAR(100);
	DEFINE cUser_insert				CHAR(8);

	--incilizacion de variables
	LET cNomCompletoAnterior        ="";
	LET cNomCompletoActual          = "";
	LET cCod_ret                    = '00000';
	LET cNumCte                     = "";
	LET dFecha				        = "";
	LET cRfc_orig	                = "";
	LET cNombre1_orig			    = "";
	LET cNombre2_orig			    = "";
	LET cApell_paterno_orig	        = "";
	LET cApell_materno_orig	        = "";
	LET cRfc_nvo				    = "";
	LET cNombre1_nvo			    = "";
	LET cNombre2_nvo			    = "";
	LET cApell_paterno_nvo	        = "";
	LET cApell_materno_nvo		    = "";
	LET cUser_insert				= "";

BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr
        IF iSqlErr <> 0 THEN
            LET cCod_ret = iSqlErr;
        END IF;
        RETURN cCod_ret, NULL, NULL, NULL, NULL, NULL, NULL, NULL;
    END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/sp_ConsultarCambiosNomCtasFechas.out";
    --TRACE ON;

	IF (p_Tipo="") OR (p_Tipo IS NULL) THEN
		RETURN '00001', NULL, NULL, NULL, NULL, NULL, NULL, NULL; --Faltan parametros
	END IF;
	IF p_Tipo=1 THEN

		IF (p_NumCte IS NULL) OR (p_NumCte = "") THEN --valida que el numero de cliente no sea nulo
	            RETURN '00001', NULL, NULL, NULL, NULL, NULL, NULL, NULL; --Faltan parametros
		ELSE
		    --Consulta las correcciones de los datos del numero de cliente ingresado como paramentro
	        SELECT numcte,fecha_insert, rfc_orig, nombre1_orig, nombre2_orig, apell_paterno_orig, apell_materno_orig, rfc_nvo,
		           nombre1_nvo, nombre2_nvo, apell_paterno_nvo, apell_materno_nvo,user_insert
		    INTO   cNumCte,dFecha,cRfc_orig, cNombre1_orig,cNombre2_orig, cApell_paterno_orig, cApell_materno_orig,cRfc_nvo,
			       cNombre1_nvo, cNombre2_nvo, cApell_paterno_nvo, cApell_materno_nvo, cUser_insert
	        FROM  bdinteg: si_cte_bitacora
		    WHERE  numcte = p_NumCte AND secuencia IN (SELECT MAX(secuencia) FROM bdinteg: si_cte_bitacora WHERE numcte = p_NumCte);

	        --Forma la cadena con los nombres y apellidos del cliente
		    LET cNomCompletoAnterior = TRIM(cNombre1_orig) || ' ' || TRIM(cNombre2_orig) || ' ' || TRIM (cApell_paterno_orig) || ' ' || TRIM(cApell_materno_orig);
		    LET cNomCompletoActual = TRIM(cNombre1_nvo) || ' ' || TRIM(cNombre2_nvo) || ' ' || TRIM (cApell_paterno_nvo) || ' ' || TRIM(cApell_materno_nvo);
		END IF;
		        --Regresa valores obtenidos
	            RETURN cCod_ret,cNumCte,dFecha,cRfc_orig, cNomCompletoAnterior,cRfc_nvo, cNomCompletoActual,cUser_insert WITH RESUME;
		END IF;

	IF p_Tipo= 2 THEN
		--Valida que las los parametros recibidos en fecha incial y fecha final, no sean nulos.
		IF (pFechaInicial IS NULL) OR (pFechaInicial = "") or (pFechaFinal IS NULL) OR (pFechaFinal="") THEN
		    RETURN '0001', NULL, NULL, NULL, NULL, NULL, NULL,NULL;
		ELSE
			FOREACH --Iicia un ciclo donde obtiene los datos de clientes  que se han corregido  durande el periodo de tiempo comprendido en el rango entre fecha unicial y fecha final
				 SELECT numcte, fecha_insert, rfc_orig, nombre1_orig, nombre2_orig, apell_paterno_orig, apell_materno_orig, rfc_nvo,
						nombre1_nvo, nombre2_nvo, apell_paterno_nvo, apell_materno_nvo,user_insert
				 INTO   cNumCte,dFecha,cRfc_orig, cNombre1_orig,cNombre2_orig, cApell_paterno_orig, cApell_materno_orig,cRfc_nvo,
						cNombre1_nvo, cNombre2_nvo, cApell_paterno_nvo, cApell_materno_nvo,cUser_insert
				 FROM   bdinteg: si_cte_bitacora
				 WHERE fecha_insert BETWEEN  pFechaInicial AND  pFechaFinal
				 ORDER BY fecha_insert, numcte, secuencia

				 --Forma la cadena con los nombres y apellidos del cliente

				 LET cNomCompletoAnterior = TRIM(cNombre1_orig) || ' ' || TRIM(cNombre2_orig) || ' ' || TRIM (cApell_paterno_orig) || ' ' || TRIM(cApell_materno_orig);
				 LET cNomCompletoActual = TRIM(cNombre1_nvo) || ' ' || TRIM(cNombre2_nvo) || ' ' || TRIM (cApell_paterno_nvo) || ' ' || TRIM(cApell_materno_nvo);
				 --regresa valores obtenidos
				 RETURN cCod_ret,cNumCte,dFecha,cRfc_orig, cNomCompletoAnterior,cRfc_nvo, cNomCompletoActual,cUser_insert WITH RESUME;
			END FOREACH;

		END IF;
	END IF;
END;
END PROCEDURE
DOCUMENT
    'DESCRIPCION: Realiza una consulta la tabla si_cte_bitacora, de los clientes a los que se les han actualizado sus datos durante un rango de fechas o la ultima corrección de los datos del cliente. ',
    'AUTOR: Cristian Valentina Aguilar',
    'FECHA: junio 2009',
    'VERSION: 20090626',
    'BD: BDINTEG',

	'CAMBIOS: Se modificaron las consultas, para que traigan tambien el user_insert, y lo regrese en los resultados',
	'MODIFICO: Cristian Valentina Aguilar',
	'FECHA: 20090818',
	'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_reporte_huellas_aut_diario()
	RETURNING
		CHAR(6) 	AS 	COD_RET,
		CHAR(80) 	AS MENSAJE_RET;
		
	--DECLARACION DE VARIABLES
	DEFINE cCodret 		 	CHAR(6);
	DEFINE iSqlErr        	INTEGER;
	DEFINE cMensaje       	CHAR(80);
	DEFINE dFechaAdul		DATE;
	DEFINE dFechaPro		DATE;
	DEFINE cFechaArc		CHAR(8);
	DEFINE cRuta			CHAR(80);
	DEFINE cSelectQry		CHAR(1000);
	DEFINE cCmd1			CHAR(1000);
	
	--INICIALIZACION DE VARIABLES
	LET cCodret			= '00000';
	LET iSqlErr 		= 0;
	LET cMensaje		= 'PROCESO EXITOSO';
	LET dFechaAdul		= DATE(1);
	LET dFechaPro		= DATE(1);
	LET cRuta			= '';
	LET cSelectQry		= '';
	LET cCmd1			= '';
	LET cFechaArc		= '';

BEGIN
	-----Control de Errores de Informix
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET cMensaje = "ERROR NO CONTROLADO";
			RETURN cCodret, cMensaje;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	--Obtener la fecha a procesar y la fecha para la mayoria de edad
	SELECT fecha_ant, date(fecha_ant - interval(18) YEAR TO YEAR),TO_CHAR(fecha_ant, "%Y%m%d")
	INTO  dFechaPro,dFechaAdul,cFechaArc 
	FROM bdinteg:si_fechas
	WHERE empresa = '001';	
	
	--SET DEBUG FILE TO "/informix/cristol/sp_reporte_huellas_aut_diario.out";
	--TRACE ON;
	
	SET ISOLATION TO DIRTY READ;
	
	-- Se realiza optimizacion de consulta utilizando tablas temporales de paso
	SELECT DISTINCT LPAD(TRIM(cliente::CHAR(9)), 9,'0') numcte2,ticket, fecha
	FROM si_huella_linea_resultado
	WHERE fecha = dFechaPro   -- parametro de entrada
	AND num_mensaje = '602' AND cliente <> '0' AND empresa = '5'
	
	INTO temp huella_linea_resul WITH NO LOG;
	
	SELECT a.numcte2, a.ticket, a.fecha, cte1.apell_paterno apell_pat_2, cte1.apell_materno apell_mat_2, cte1.nombre1 nom1_2, cte1.nombre2 nom2_2, cte1.sucursal sucursal_2, cte1.ejecutivo ejecutivo_2,cte1.rfc rfc_2, pf.fecha_nac fecha_nac2
	FROM huella_linea_resul a,  si_cliente cte1, si_ctepf pf
	WHERE pf.fecha_nac <= dFechaAdul
	AND numcte2 = cte1.numcte AND numcte2 = pf.numcte

	INTO temp clientes_bcpl_dupl_2 WITH NO LOG;
	
	
	
	SET ISOLATION TO DIRTY READ;
	SELECT a.numcte numcte1, a.fecha_consulta, a.ticket, cte1.apell_paterno apell_pat_1, cte1.apell_materno apell_mat_1, cte1.nombre1 nom1_1, cte1.nombre2 nom2_1, cte1.sucursal sucursal_1, cte1.ejecutivo ejecutivo_1,cte1.rfc rfc_1, pf.fecha_nac fecha_nac1
	FROM si_huella_linea a, si_cliente cte1, si_ctepf pf
	WHERE fecha_consulta = dFechaPro  AND ticket IN
	(SELECT ticket FROM clientes_bcpl_dupl_2) AND a.numcte = cte1.numcte  AND a.numcte = pf.numcte
	
	INTO temp clientes_bcpl_dupl_1 WITH NO LOG;
	
	INSERT INTO si_clientes_huellas_dupl(numcte1, apell_pat_1, apell_mat_1, nom1_1, nom2_1,sucursal_1,ejecutivo_1, rfc_1, fecha_nac1, numcte2, apell_pat_2, apell_mat_2, nom1_2, nom2_2, sucursal_2, ejecutivo_2,rfc_2, fecha_nac2, ticket, fecha_consulta, fecha_insert)
		SELECT a.numcte1, a.apell_pat_1, a.apell_mat_1, a.nom1_1, a.nom2_1,a.sucursal_1,a.ejecutivo_1, a.rfc_1, a.fecha_nac1, b.numcte2, b.apell_pat_2, b.apell_mat_2, b.nom1_2, b.nom2_2,b.sucursal_2, b.ejecutivo_2,b.rfc_2, b.fecha_nac2, a.ticket, a.fecha_consulta, CURRENT AS fecha_insert
		FROM clientes_bcpl_dupl_1 a, clientes_bcpl_dupl_2 b
		WHERE a.ticket = b.ticket 
		AND b.fecha = a.fecha_consulta;
		
		
	EXECUTE PROCEDURE "informix".sp_compara_nombres()
	INTO cCodret;
	
	set isolation to dirty read;   
	set lock mode to wait 4;  
	
	-- Proceso para generar reporte de resultados diario en archivo plano
	SELECT LIMIT 1 TRIM(VALOR)
	INTO cRuta 
	FROM bdimnsj:"informix".mnsj_param
	WHERE cod_param = '3';
	
	
	LET cSelectQry = "select ""numcte1"",""apell_pat_1"",""apell_mat_1"",""nom1_1"",""nom2_1"",""sucursal_1"",""ejecutivo_1"",""rfc_1"",""fecha_nac1"","||
	" ""numcte2"",""apell_pat_2"",""apell_mat_2"",""nom1_2"",""nom2_2"",""sucursal_2"",""ejecutivo_2"",""rfc_2"",""fecha_nac2"",""fecha_consulta"","||
	" ""porce_simil"" from bdinteg:""informix"".si_fechas union all select * from table (multiset (select numcte1,apell_pat_1,apell_mat_1,nom1_1,nom2_1,sucursal_1,ejecutivo_1,rfc_1,"||
	" TRIM(fecha_nac1::CHAR(10)), numcte2,apell_pat_2, apell_mat_2, nom1_2, nom2_2, sucursal_2, ejecutivo_2, rfc_2, TRIM(fecha_nac2::CHAR(10)),"||
	" TRIM(fecha_consulta::CHAR(10)),TRIM(porce_simil::CHAR(6)) from bdinteg:""informix"".si_clientes_huellas_dupl where fecha_consulta = """||dFechaPro||""" and numcte1 <> numcte2  order by porce_simil desc, numcte1));";		
		
	LET cCmd1 = "echo 'UNLOAD TO """||TRIM(cRuta)||"/rephuella_"||cFechaArc||".txt"" "||TRIM(cSelectQry)||"'| dbaccess sysmaster > """||TRIM(cRuta)||"/rephuella_diario.log""  2>&1";
	SYSTEM TRIM(cCmd1);
	
	RETURN cCodret, cMensaje;
END
END PROCEDURE
DOCUMENT
'DESCRIPCIÃN: GENERA REPORTE DIARIO DE HUELLAS DUPLICADAS',
'FECHA DE CREACIÃN: 29-JULIO-2013',
'FECHA DE MODIFICACIÃN: 07-AGOSTO-2013',
'BASE DE DATOS: BDINTEG',
'VERSION: 20130807.1000';

CREATE PROCEDURE "informix".sp_buscar_movimientos_credito_dia_corporativo(p_sNumeroCuenta CHAR(30), p_sFechaInicial DATE, p_sFechaFinal DATE, p_numeroCliente CHAR(20), p_skip INT, p_sTarjeta CHAR(30), p_sEmpresa CHAR(4))

     RETURNING	DATE AS fechaMovimiento, DATETIME HOUR TO FRACTION(3) AS horaMovimiento , money(16,2) AS monto, 
                CHAR(30) AS folioSuc, CHAR(40) AS nombreSucursal, CHAR(40) AS tipo, CHAR(1) AS reversado, 
                CHAR(10) AS id, CHAR(20) AS cuenta, CHAR(1) AS naturaleza,CHAR(40) AS referencia,CHAR(20) AS tarjeta;

	--definicion de variables--	    
	DEFINE resultado_fechaMovimiento 	DATE;
	DEFINE resultado_monto			money(16,2);
	DEFINE resultado_horaMovimiento		DATETIME HOUR TO FRACTION(3);
	DEFINE resultado_folioSuc		CHAR(30);
    	DEFINE resultado_nombreSucursal 	CHAR(40);
	DEFINE resultado_tipo   		CHAR(40);
   	DEFINE resultado_reversado          CHAR(1);
   	DEFINE resultado_id                 CHAR(10);
    	DEFINE resultado_cuenta             CHAR(20);
    	DEFINE resultado_naturaleza         CHAR(1);
    	DEFINE resultado_referencia         CHAR(40);
   	DEFINE resultado_tarjeta            CHAR(20);
    	DEFINE cuenta_temp                  CHAR(20);
    	DEFINE iSqlErr                      INTEGER;
     
     -- InicializaciÃÂ³n de las variables.
	LET resultado_fechaMovimiento = '';
	LET resultado_monto = '';
	LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
	LET resultado_folioSuc = '';
    LET resultado_nombreSucursal = '';
	LET resultado_tipo = '';
    LET resultado_reversado = '';
    LET resultado_id = '';
    LET resultado_cuenta = '';
    LET resultado_naturaleza = '';
    LET resultado_referencia = '';
    LET resultado_tarjeta = '';

    SET ISOLATION TO DIRTY READ;

	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_fechaMovimiento = '';
                    LET resultado_monto = '';
                    LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
                    LET resultado_folioSuc = '';
                    LET resultado_nombreSucursal = '';
                    LET resultado_tipo = '';
                    LET resultado_reversado = '';
                    LET resultado_id = '';
                    LET resultado_cuenta = '';                    
                    LET resultado_naturaleza = '';
                    LET resultado_referencia = '';
                    LET resultado_tarjeta = '';
                    RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, 
                            resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, 
                            resultado_cuenta,resultado_naturaleza,resultado_referencia,resultado_tarjeta;
                END IF;
        END EXCEPTION;

            IF(p_sTarjeta IS NOT NULL AND p_sTarjeta <> '') THEN
                select distinct numcuenta
                    into cuenta_temp
                    from intercard:tarjetacuenta 
                    where numtarjeta = p_sTarjeta;

                    FOREACH       
                        SELECT SKIP p_skip DISTINCT fecha_mov, hora_mov, monto, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, reversado, transacc_suc, num_credito, bdinteg:si_transacc.naturaleza,referencia,nro_tarjeta
                          INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta
                          FROM bdicred:sd_movdia 
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicred:sd_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
                            LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicred:sd_movdia.transacc_suc AND bdinteg:si_transacc.empresa = p_sEmpresa)
                          WHERE fecha_mov <= p_sFechaFinal 
                            AND fecha_mov >= p_sFechaInicial 
                            AND nro_tarjeta = p_sTarjeta
                            AND bdicred:sd_movdia.empresa = p_sEmpresa
                            AND num_credito = cuenta_temp
                          ORDER BY folio_suc asC, fecha_mov asC
                          RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta WITH RESUME;
                    END FOREACH;
            ELSE
                IF (p_sNumeroCuenta IS NOT NULL AND p_sNumeroCuenta <> '') THEN
                    FOREACH       
                        SELECT SKIP p_skip DISTINCT fecha_mov, hora_mov, monto, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, reversado, transacc_suc, num_credito,bdinteg:si_transacc.naturaleza,referencia, nro_tarjeta
                          INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta
                          FROM bdicred:sd_movdia
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicred:sd_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
                            LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicred:sd_movdia.transacc_suc AND bdinteg:si_transacc.empresa = p_sEmpresa)
                          WHERE fecha_mov <= p_sFechaFinal 
                            AND fecha_mov >= p_sFechaInicial 
                            AND num_credito = p_sNumeroCuenta
                            AND bdicred:sd_movdia.empresa = p_sEmpresa
                          ORDER BY folio_suc asC, fecha_mov asC
                          RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza,resultado_referencia,resultado_tarjeta WITH RESUME;
                    END FOREACH;
                ELSE
                    FOREACH       
                        SELECT SKIP p_skip DISTINCT fecha_mov, hora_mov, monto, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, reversado, transacc_suc, bdicred:sd_movdia.num_credito,bdinteg:si_transacc.naturaleza,referencia, nro_tarjeta
                          INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta
                          FROM bdicred:sd_movdia 
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicred:sd_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
                            LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicred:sd_movdia.transacc_suc AND bdinteg:si_transacc.empresa = p_sEmpresa)
                            LEFT JOIN bdicred:sd_maecred ON (bdicred:sd_movdia.num_credito = bdicred:sd_maecred.num_credito AND bdicred:sd_maecred.empresa = p_sEmpresa)
                          WHERE fecha_mov <= p_sFechaFinal 
                            AND fecha_mov >= p_sFechaInicial 
                            AND numcte = p_numeroCliente
                            AND bdicred:sd_movdia.empresa = p_sEmpresa
                          ORDER BY folio_suc asC, fecha_mov asC
                          RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta WITH RESUME;
                    END FOREACH;
                END IF;
           END IF;
	END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscar_movimientos_credito_his_corporativo(p_sNumeroCuenta CHAR(30), p_sFechaInicial DATE, p_sFechaFinal DATE, p_numeroCliente CHAR(20), p_skip INT, p_sTarjeta CHAR(30), p_sEmpresa CHAR(4))

     RETURNING	DATE AS fechaMovimiento, DATETIME HOUR TO FRACTION(3) AS horaMovimiento , money(16,2) AS monto, 
                CHAR(30) AS folioSuc, CHAR(40) AS nombreSucursal, CHAR(40) AS tipo, CHAR(1) AS reversado, 
                CHAR(10) AS id, CHAR(20) AS cuenta,CHAR(1) AS naturaleza,CHAR(40) AS referencia, CHAR(20) AS tarjeta;

	--definicion de variables--	    
	DEFINE resultado_fechaMovimiento 	DATE;
