CREATE PROCEDURE "informix".sp_consulta_usuarios_bmovil_prosa( pRegistros INTEGER)

RETURNING CHAR(5)  AS vcodret1,
		  CHAR(20) AS vNumCte,
		  CHAR(30) AS vNombre1,
		  CHAR(30) AS vNombre2,
		  CHAR(30) AS vApellPat,
		  CHAR(30) AS vApellMat,
          CHAR(100) AS vCorreo, 
		  SMALLINT AS vIdStatus,
		  CHAR(10) AS vFechRegistro,
		  CHAR(15) AS vCelServicio,
          CHAR(13) AS vTelefono1,
		  CHAR(13) AS vTelefono2,
		  CHAR(13) AS vTelefono3,
		  CHAR(13) AS vTelefono4,
          CHAR(5)  AS vExtension;
         
    DEFINE vcodret1 CHAR(5);
    DEFINE vcodret2 CHAR(5);
    DEFINE vcodret3 CHAR(50);
    DEFINE sql_err  INTEGER;
    DEFINE isam_err INTEGER;
    DEFINE desc_err CHAR(50);
	DEFINE vNumCte	CHAR(20);
	DEFINE vCelServicio	CHAR(15);
	DEFINE vIdStatus	SMALLINT;
	DEFINE vFechRegistro	CHAR(10);
	DEFINE vCorreo		CHAR(100);
    DEFINE vExtension       CHAR(5);
	DEFINE vExtAux	CHAR(5);
	DEFINE vNombre1	CHAR(30);
	DEFINE vNombre2 CHAR(30);
	DEFINE vApellPat CHAR(30);
	DEFINE vApellMat CHAR(30);
	DEFINE vTelefono1 CHAR(13);
	DEFINE vTelefono2 CHAR(13);
	DEFINE vTelefono3 CHAR(13);
	DEFINE vTelefono4 CHAR(13);
	
    
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
	LET vNumCte = '';
	LET vCelServicio = '';
	LET vIdStatus = 0;
	LET vCorreo = '';
    LET vExtension  = '';
	LET vExtAux = '';
	LET vNombre1	='';
	LET vNombre2 	='';
	LET vApellPat 	='';
	LET vApellMat 	='';
	LET vTelefono1 	='';
	LET vTelefono2 	='';
	LET vTelefono3 	='';
	LET vTelefono4 	='';
	LET vFechRegistro = '';

    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_consulta_usuarios_sinavatar.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, vNumCte, vNombre1, vNombre2, vApellPat, vApellMat, vCorreo, vIdStatus, vFechRegistro, vCelServicio, vTelefono1, vTelefono2, vTelefono3, vTelefono4, vExtension;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_consulta_telefonos.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	FOREACH 
	  SELECT SKIP pRegistros FIRST 5000 numcte,TRIM(numcel),id_status, DAY(fech_registro)||"/"||MONTH(fech_registro)||"/"||YEAR(fech_registro)
	    INTO vNumCte, vCelServicio, vIdStatus, vFechRegistro
	  FROM bdinteg:"informix".si_bm_usuarios
	  
	  SELECT TRIM(apell_paterno), TRIM(apell_materno), TRIM(nombre1), TRIM(nombre2)
	    INTO vApellPat, vApellMat, vNombre1, vNombre2
	  FROM bdinteg:"informix".si_cliente
	  WHERE numcte = vNumCte;
	  
	  SELECT TRIM(NVL(correo_elec,'')) INTO vCorreo
	  FROM bdinteg:"informix".si_correos
	  WHERE numcte = vNumCte
	  AND status_correo = "A";
	  
	  SELECT TRIM(NVL(telefono,'')), TRIM(NVL(extension,'')) INTO vTelefono1, vExtAux
	  FROM bdinteg:"informix".si_telefonos_actual
	  WHERE numcte = vNumCte
	  AND tipo_tel = 1
	  AND status_tel = 'A';
	  
	  IF vExtension <> '' THEN
		LET vExtension = vExtAux;
	  END IF;
	  
	  SELECT TRIM(NVL(telefono,'')), TRIM(NVL(extension,'')) INTO vTelefono2, vExtAux
	  FROM bdinteg:"informix".si_telefonos_actual
	  WHERE numcte = vNumCte
	  AND tipo_tel = 2
	  AND status_tel = 'A';
	  
	  IF vExtension <> '' THEN
		LET vExtension = vExtAux;
	  END IF;
	  
	  SELECT TRIM(NVL(telefono,'')), TRIM(NVL(extension,'')) INTO vTelefono3, vExtAux
	  FROM bdinteg:"informix".si_telefonos_actual
	  WHERE numcte = vNumCte
	  AND tipo_tel = 3
	  AND status_tel = 'A';
	  
	  IF vExtension <> '' THEN
		LET vExtension = vExtAux;
	  END IF;
	  
	  SELECT TRIM(NVL(telefono,'')), TRIM(NVL(extension,'')) INTO vTelefono4, vExtAux
	  FROM bdinteg:"informix".si_telefonos_actual
	  WHERE numcte = vNumCte
	  AND tipo_tel = 4
	  AND status_tel = 'A';
	  
	  IF vExtension <> '' THEN
		LET vExtension = vExtAux;
	  END IF;
	  
	  RETURN vcodret1, vNumCte, vNombre1, vNombre2, vApellPat, vApellMat, vCorreo, vIdStatus, vFechRegistro, vCelServicio, vTelefono1, vTelefono2, vTelefono3, vTelefono4, vExtension WITH RESUME;
	  --CONTINUE FOREACH;
	  
	END FOREACH;
	
  END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualiza_mensajes_cel( pNumCte CHAR(20), -- NO. CLIENTE
                                                       pSmsCel CHAR(1) ) -- INDICADOR SMS
RETURNING CHAR(5); -- CODIGO DE RETORNO
    
    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE vcodret3         CHAR(50);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE desc_err         CHAR(50);
    
    DEFINE vExisteCte       INTEGER;
    DEFINE vcTipoMns        CHAR(1);
    DEFINE vcPlanMns        CHAR(10);
    DEFINE vcProcMns        CHAR(1);
    DEFINE vCodRetRegEven   CHAR(5);
    
    LET vcodret1 = '000';
    LET vcodret2 = '000';
    LET vcodret3 = '';
    LET sql_err	 = 0;
    LET isam_err = 0;
    LET desc_err = '';
    
    LET vExisteCte     = 0;
    LET vcTipoMns      = '';
    LET vcPlanMns      = '';
    LET vcProcMns      = '';
    LET vCodRetRegEven = '';
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actualiza_mensajes_cel.err";
        --- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_actualiza_mensajes_cel.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF ( pNumCte is null OR pNumCte = '' ) OR
       ( pSmsCel is null OR pSmsCel = '' ) THEN
        LET vcodret1 = '110'; --- DATOS INSUFICIENTES
        RETURN vcodret1;
    END IF;

    -- // VALIDA EXISTA NUMERO DE CLIENTE
    SELECT COUNT(*)
      INTO vExisteCte
      FROM bdinteg:"informix".si_ctepf
     WHERE numcte = pNumCte;

    IF vExisteCte = 0 THEN
        LET vcodret1 = '104'; --- NO DE CLIENTE NO EXISTE
        RETURN vcodret1;
    END IF;
    
    UPDATE si_ctepf
       SET sms_cel = pSmsCel
     WHERE numcte = pNumCte;
     
    IF ( ( dbinfo('sqlca.sqlerrd2') = 0 ) AND pSmsCel = 'S' ) THEN
        -- // OBTIENE PARAMETROS PARA MENSAJE DE LATINIA
        SELECT valor
          INTO vcTipoMns
          FROM bdinteg:"informix".si_param
         WHERE cod_param = 85;
        
        SELECT valor
          INTO vcPlanMns
          FROM bdinteg:"informix".si_param
         WHERE cod_param = 86;
           
        SELECT valor
          INTO vcProcMns
          FROM bdinteg:"informix".si_param
         WHERE cod_param = 87;
             
        EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento
        ( vcTipoMns, vcPlanMns, pNumCte, '', '', vcProcMns, '', CURRENT, '', '', '', '', '', '', '', '', '', '', 1, 0, 0, 0, 0, CURRENT, '' )
        INTO vCodRetRegEven;
    END IF;
    
    END;
    
    RETURN vcodret1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cte_ilocalilzable( pNumCte       CHAR(20),  -- NO. CLIENTE
                                                  pCanal        SMALLINT,  -- CANAL
                                                  pSucursal     CHAR(4),   -- SUCURSAL
                                                  pUserInsert   CHAR(8) )  -- USUARIO
RETURNING CHAR(5); -- CODIGO DE RETORNO
    
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vExisteCte   INTEGER;
    
    LET vcodret1   = '000';
    LET vcodret2   = '000';
    LET vcodret3   = '';
    LET sql_err	   = 0;
    LET isam_err   = 0;
    LET desc_err   = '';
    LET vExisteCte = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cte_ilocalilzable.err";
        --- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cte_ilocalilzable.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF ( pNumCte is null OR pNumCte = '' ) THEN
        LET vcodret1 = '110'; --- DATOS INSUFICIENTES
        RETURN vcodret1;
    END IF;

    -- // VALIDA EXISTA NUMERO DE CLIENTE
    SELECT COUNT(*)
      INTO vExisteCte
      FROM bdinteg:"informix".si_cliente
     WHERE numcte = pNumCte;

    IF vExisteCte = 0 THEN
        LET vcodret1 = '104'; --- NO DE CLIENTE NO EXISTE
        RETURN vcodret1;
    END IF;
    
    SELECT COUNT(*)
      INTO vExisteCte
      FROM bdinteg:"informix".si_bitacora_tel
     WHERE numcte = pNumCte;
     
    IF vExisteCte = 0 THEN
        INSERT INTO bdinteg:"informix".si_bitacora_tel
        ( numcte, ind_telefono, ind_correo, canal, sucursal, user_insert, fecha_oper )
        VALUES
        ( pNumCte, '9', '9', pCanal, pSucursal, pUserInsert, CURRENT );
    ELSE 
        UPDATE bdinteg:"informix".si_bitacora_tel
           SET ind_telefono = '9',
               ind_correo   = '9',
               canal        = pCanal,
               sucursal     = pSucursal,
               user_insert  = pUserInsert,
               fecha_oper   = CURRENT
         WHERE numcte = pNumCte;
    END IF;
    
    END;
    
    RETURN vcodret1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_permite_mensajes_cel( pNumCte CHAR(20) ) -- NO. CLIENTE
RETURNING CHAR(5), -- CODIGO DE RETORNO
          CHAR(1); -- INDICADOR DE MENSAJES
    
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    DEFINE vsms_cel     CHAR(1);
    DEFINE vExisteCte   INTEGER;
    
    LET vcodret1   = '000';
    LET vcodret2   = '000';
    LET vcodret3   = '';
    LET sql_err	   = 0;
    LET isam_err   = 0;
    LET desc_err   = '';
    LET vsms_cel   = '';
    LET vExisteCte = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_permite_mensajes_cel.err";
        --- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, vsms_cel;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_permite_mensajes_cel.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA PARAMETROS DE ENTRADA
    IF ( pNumCte is null OR pNumCte = '' ) THEN
        LET vcodret1 = '110'; --- DATOS INSUFICIENTES
        RETURN vcodret1, vsms_cel;
    END IF;

    -- // VALIDA EXISTA NUMERO DE CLIENTE
    SELECT COUNT(*)
      INTO vExisteCte
      FROM bdinteg:"informix".si_ctepf
     WHERE numcte = pNumCte;

    IF vExisteCte = 0 THEN
        LET vcodret1 = '104'; --- NO DE CLIENTE NO EXISTE
        RETURN vcodret1, vsms_cel;
    END IF;
    
    SELECT sms_cel
      INTO vsms_cel
      FROM bdinteg:"informix".si_ctepf
     WHERE numcte = pNumCte;
    
    IF vsms_cel is null OR vsms_cel = '' THEN
        LET vsms_cel = 'N';
    END IF;
    
    END; 
    
    RETURN vcodret1, vsms_cel;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_updcte_fus9() 
RETURNING CHAR(5), CHAR(80);
--DEFINICION DE VARIABLES
DEFINE vc_CodRet        CHAR(5);
DEFINE vi_SqlErr        INTEGER;
DEFINE vi_iSAMErr        INTEGER;
DEFINE vi_iSAMData        CHAR(80);
DEFINE vc_Mensaje       CHAR(80);
DEFINE pClienteTitular        CHAR(20);
DEFINE pClienteTraspasaCtas        CHAR(20);
DEFINE vc_detalle_mov2   CHAR(200);
DEFINE vc_proceso       CHAR(50);
DEFINE vc_tabla         CHAR(30);
DEFINE vc_detalle_mov   CHAR(200);
DEFINE vc_Cuenta        CHAR(20);
DEFINE vc_Cuenta2        CHAR(20);
DEFINE vi_secuencia     INTEGER;
DEFINE vc_aniomes       CHAR(6);
DEFINE pCte        CHAR(20);
DEFINE vi_num_serial    INTEGER;
DEFINE vd_fecha_mov     DATE;
DEFINE iExiste     INTEGER;
--INICIALIZACION DE VARIABLES
LET vc_CodRet = "00000";
LET vi_SqlErr = 0;
LET vi_iSAMErr=0;
LET vi_secuencia = 0;
LET vi_iSAMData="";
LET vc_Mensaje = "EL PROCESO SE EFECTUO CORRECTAMENTE";
LET pClienteTitular="";
LET pClienteTraspasaCtas="";
LET vc_detalle_mov2 = "";
LET vc_proceso = "FusionClientes";
LET vc_tabla = "";
LET vc_detalle_mov = "";
LET vc_Cuenta = "";
LET vc_aniomes="";
LET vc_Cuenta2="";
LET pCte="";
LET vi_num_serial=0;
LET vd_fecha_mov = "";
LET iExiste=0;


set isolation to dirty read;
set lock mode to wait 3;

    BEGIN

    ON EXCEPTION SET vi_SqlErr,vi_iSAMErr,vi_iSAMData
        IF vi_SqlErr <> 0 THEN
            LET vc_CodRet = vi_SqlErr;
            LET vc_Mensaje = "ERROR NO CONTROLADO";
            LET vc_detalle_mov2=vi_SqlErr||'|'||vi_iSAMErr||'|'||vi_iSAMData; 
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov2, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            RETURN vc_CodRet, vc_Mensaje;
        END IF;
    END EXCEPTION;

--    SET DEBUG FILE TO "/tmp/sp_updcte_fus9.out";
--    TRACE ON;


SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} DISTINCT TRIM(cliente_tit),TRIM(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>''

--**************************************INICIA TRASPASO DE TABLA CB_COMPAC ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(*) INTO iExiste FROM bdicobranza:cb_compac WHERE numcliente=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT numcuenta INTO vc_Cuenta FROM bdicobranza:cb_compac WHERE numcliente=pClienteTraspasaCtas
            LET vc_proceso='COMPAC COBRANZA';
            LET vc_tabla = "cb_compac";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            INSERT INTO bdinteg:si_fuscompac
            SELECT * FROM bdicobranza:cb_compac WHERE numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;

            UPDATE bdicobranza:cb_compac SET numcliente = pClienteTitular where numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;
--**********************************************************************************************************
	
--**************************************INICIA TRASPASO DE TABLA CB_COMPAC_HIS ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(*) INTO iExiste FROM bdicobranza:cb_compac_his WHERE numcliente=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT numcuenta INTO vc_Cuenta FROM bdicobranza:cb_compac_his WHERE numcliente=pClienteTraspasaCtas
            LET vc_proceso='COMPAC COBRANZA HIS';
            LET vc_tabla = "cb_compac_his";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            INSERT INTO bdinteg:si_fuscompac_his 
            SELECT * FROM bdicobranza:cb_compac_his WHERE numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;

            UPDATE bdicobranza:cb_compac_his SET numcliente = pClienteTitular where numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;

--**********************************************************************************************************

--**************************************INICIA TRASPASO DE TABLA CB_CAT_DIRECTORIO_CTE ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(*) INTO iExiste FROM bdicobranza:cb_cat_directorio_cte WHERE numcte=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT num_credito INTO vc_Cuenta FROM bdicobranza:cb_cat_directorio_cte WHERE numcte=pClienteTraspasaCtas
            LET vc_proceso='DIRECTORIO COBRANZA';
            LET vc_tabla = "cb_cat_directorio_cte";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            INSERT INTO bdinteg:si_fuscat_directorio_cte
            SELECT * FROM bdicobranza:cb_cat_directorio_cte WHERE num_credito=vc_Cuenta AND numcte=pClienteTraspasaCtas;

            UPDATE bdicobranza:cb_cat_directorio_cte SET numcte = pClienteTitular where num_credito=vc_Cuenta AND numcte=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;
--**********************************************************************************************************


--**************************************INICIA TRASPASO DE TABLA CB_CAT_DIRECTORIO_CTE_HIST ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT COUNT(*) INTO iExiste FROM bdicobranza:cb_cat_directorio_cte_his WHERE numcte=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT num_credito INTO vc_Cuenta FROM bdicobranza:cb_cat_directorio_cte_his WHERE numcte=pClienteTraspasaCtas
            LET vc_proceso='DIRECTORIO COBRANZA HIS';
            LET vc_tabla = "cb_cat_directorio_cte_his";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            INSERT INTO bdinteg:si_fuscat_directorio_cte_his
            SELECT * FROM bdicobranza:cb_cat_directorio_cte_his WHERE num_credito=vc_Cuenta AND numcte=pClienteTraspasaCtas;

            UPDATE bdicobranza:cb_cat_directorio_cte_his SET numcte = pClienteTitular where num_credito=vc_Cuenta AND numcte=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;
--**********************************************************************************************************
	
	
--**************************************INICIA TRASPASO DE TABLA CB_COMPAC_ERROR ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT {+INDEX (bdicobranza:cb_compac_error idx_cb_compac_error)} COUNT(*) INTO iExiste FROM bdicobranza:cb_compac_error WHERE numcliente=pClienteTraspasaCtas;
    IF iExiste>0 THEN

        FOREACH
            SELECT {+INDEX (bdicobranza:cb_compac_error idx_cb_compac_error)} numcuenta INTO vc_Cuenta FROM bdicobranza:cb_compac_error WHERE numcliente=pClienteTraspasaCtas
            LET vc_proceso='COMPAC COBRANZA ERROR';
            LET vc_tabla = "cb_compac_error";
            LET vc_detalle_mov = TRIM(vc_Cuenta)||'|'||TRIM(pClienteTraspasaCtas);   
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', '10/10/2010');

            INSERT INTO bdinteg:si_fuscompac_error
            SELECT {+INDEX (bdicobranza:cb_compac_error idx_cb_compac_error)}* FROM bdicobranza:cb_compac_error WHERE numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;

            UPDATE {+INDEX (bdicobranza:cb_compac_error idx_cb_compac_error)} bdicobranza:cb_compac_error SET numcliente = pClienteTitular where numcuenta=vc_Cuenta AND numcliente=pClienteTraspasaCtas;
        END FOREACH;  

    END IF;
--**********************************************************************************************************
	
END FOREACH;  

    IF vc_CodRet = "00000" THEN
        RETURN vc_CodRet, vc_Mensaje;
    END IF;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultar_folioafore(pNumTarje CHAR(16),pFechaTranIni CHAR(8),pFechaTranFin CHAR(8))
