		END IF;
*/
		RETURN cCodRet,cFolio,cAfore;
	END;
END PROCEDURE
DOCUMENT
'CREADO: Josue Zepeda',
'FECHA: 25/Abril/2013',
'BD: BDINTEG',
'DESCRIPCION: consulta el folio AFORE para el sistema PL004022';

CREATE PROCEDURE "informix".sp_updcte_fus10() 
RETURNING CHAR(5), CHAR(80);
--DEFINICION DE VARIABLES
DEFINE vc_CodRet        CHAR(5);
DEFINE vi_SqlErr        INTEGER;
DEFINE vi_iSAMErr        INTEGER;
DEFINE vi_iSAMData        CHAR(80);
DEFINE vc_Mensaje       CHAR(80);
DEFINE pClienteTitular        CHAR(20);
DEFINE pClienteTraspasaCtas        CHAR(20);
DEFINE vc_detalle_mov2   CHAR(200);
DEFINE vc_proceso       CHAR(50);
DEFINE vc_tabla         CHAR(30);
DEFINE vc_detalle_mov   CHAR(200);
DEFINE vc_numsolic        CHAR(20);
DEFINE vc_Cuenta2        CHAR(20);
DEFINE vi_secuencia     INTEGER;
DEFINE vc_aniomes       CHAR(6);
DEFINE pCte        CHAR(20);
DEFINE vi_num_serial    INTEGER;
DEFINE vd_fecha_mov     DATE;
DEFINE iExiste     INTEGER;
DEFINE vc_statusolic    CHAR(2);
DEFINE vd_FechaSolic    DATE;
--INICIALIZACION DE VARIABLES
LET vc_CodRet = "00000";
LET vi_SqlErr = 0;
LET vi_iSAMErr=0;
LET vi_secuencia = 0;
LET vi_iSAMData="";
LET vc_Mensaje = "EL PROCESO SE EFECTUO CORRECTAMENTE";
LET pClienteTitular="";
LET pClienteTraspasaCtas="";
LET vc_detalle_mov2 = "";
LET vc_proceso = "FusionClientes";
LET vc_tabla = "";
LET vc_detalle_mov = "";
LET vc_numsolic = "";
LET vc_aniomes="";
LET vc_Cuenta2="";
LET pCte="";
LET vi_num_serial=0;
LET vd_fecha_mov = "";
LET iExiste=0;
LET vc_statusolic = "";
LET vd_FechaSolic = "";


set isolation to dirty read;
set lock mode to wait 3;

    BEGIN

    ON EXCEPTION SET vi_SqlErr,vi_iSAMErr,vi_iSAMData
        IF vi_SqlErr <> 0 THEN
            LET vc_CodRet = vi_SqlErr;
            LET vc_Mensaje = "ERROR NO CONTROLADO";
            LET vc_detalle_mov2=vi_SqlErr||'|'||vi_iSAMErr||'|'||vi_iSAMData; 
            INSERT INTO log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov2, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

            RETURN vc_CodRet, vc_Mensaje;
        END IF;
    END EXCEPTION;

--    SET DEBUG FILE TO "/tmp/sp_updcte_fus10.out";
--    TRACE ON;


SET ISOLATION TO DIRTY READ;
FOREACH
    SELECT {+INDEX (bdinteg:log_fusionclientes pk_fusionclientes)} DISTINCT TRIM(cliente_tit),TRIM(cliente_tras) INTO pClienteTitular,pClienteTraspasaCtas FROM log_fusionclientes WHERE cliente_tit<>'' AND cliente_tras<>''

--**************************************INICIA TRASPASO DE TABLA SS SOLICITUDES ********************************************************************
    SET ISOLATION TO DIRTY READ; 
    SELECT {+INDEX (bdisolic:ss_solicitudes idx_numctempresa)} COUNT(num_solicitud) INTO iExiste FROM bdisolic:ss_solicitudes WHERE numcte=pClienteTraspasaCtas and empresa='001';
    IF iExiste>0 THEN

        FOREACH
            SELECT {+INDEX (bdisolic:ss_solicitudes idx_numctempresa)} num_solicitud, status_solicitud, fecha_insert INTO vc_numsolic, vc_statusolic, vd_FechaSolic FROM bdisolic:ss_solicitudes WHERE numcte=pClienteTraspasaCtas and empresa='001'
            LET vc_proceso='TRASPASO DE SOLICITUDES';
            LET vc_tabla = "ss_solicitudes";
            LET vc_detalle_mov = TRIM(pClienteTraspasaCtas)||'|'||TRIM(vc_numsolic)||'|'||TRIM(vc_statusolic)||'|'||vd_FechaSolic;
            INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
            VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', DATE("10/10/2010"));

            INSERT INTO bdinteg:si_fussolicitudes
            SELECT {+INDEX (bdisolic:ss_solicitudes idx_numctempresa)} * FROM bdisolic:ss_solicitudes WHERE num_solicitud=vc_numsolic AND numcte=pClienteTraspasaCtas and empresa='001';

            UPDATE {+INDEX (bdisolic:ss_solicitudes idx_numctempresa)} bdisolic:ss_solicitudes SET numcte = pClienteTitular where num_solicitud=vc_numsolic AND numcte=pClienteTraspasaCtas and empresa='001';
        END FOREACH;  

    END IF;
--**********************************************************************************************************
	
END FOREACH;  

    IF vc_CodRet = "00000" THEN
        RETURN vc_CodRet, vc_Mensaje;
    END IF;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_depura_ctehuella()
	RETURNING 
	CHAR(5) AS cCodRet,
	CHAR(100) AS cMensajeREt; 
	----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- -----
	--DECLARACIÓN DE VARIABLE
	DEFINE cCodRet		CHAR(5);
	DEFINE cMensajeREt	CHAR(100);
	DEFINE cSql         CHAR(6000);
	DEFINE Cnumcte		CHAR(20);
	DEFINE Cnumcred	CHAR(20);
	DEFINE Vexiste		INTEGER;
	DEFINE dAFecha		DATE;
	DEFINE iSqlErr      INTEGER;
	----- ----- -----
	--INICIALIZACIÓN DE VARIABLE
	LET cCodRet ='00000';
	LET cMensajeREt ='Proceso Exitoso';
	LET Cnumcte = '';
	LET Vexiste = 0;
	LET iSqlErr = 0;
	LET dAFecha ='';
	LET cSql = '';
	----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- ----- -----
	/*SET DEBUG FILE TO "/informix/c92962301/respaldo_caso1_depuracion.OUT";
	   TRACE ON;*/
	----- ----- ----- ----- ----- ----- ----- -----
	BEGIN
	----- ----- ----- ----- ----- ----- ----- -----
		ON EXCEPTION SET iSqlErr
			IF iSqlErr !=0 THEN
			  LET cCodRet = iSqlErr;
			  LET cMensajeRet = "Ocurrio un Error";
			ROLLBACK;
			  -- TRUNCATE TABLE  bdidigital:clientes_eliminacion; 
			  RETURN cCodRet,cMensajeRet;
			END IF;
		END EXCEPTION;
		----- ----- ----- ----- ----- ----- ----- -----
		SET ISOLATION TO DIRTY READ; -- Hace consultas "sucias"
		SET LOCK MODE TO WAIT 3; -- Espera 3 segundos si la tabla y/o el registro esta bloqueado
		----- ----- ----- ----- ----- ----- ----- -----
		    --SE VALIDA SI LA TABLA EXISTE Y SI SE ENCUENTRA VACIA--
		    IF EXISTS( SELECT dbsname, tabname FROM sysmASter:systabnames  WHERE tabname = 'cliente_paso_huellas' ) THEN
				----- ----- ----- ----- ----- ----- ----- -----
				select limit 1 numcte INTO Cnumcte from bdinteg:"informix".cliente_paso_huellas;
				----- ----- ----- ----- ----- ----- ----- -----
					IF dbinfo("sqlca.sqlerrd2") = 0 THEN				 
					    ----- ----- ----- -----
						  LET cSql = '';
						  LET cSql = 'echo "SET ISOLATION TO DIRTY READ;'|| ' '||
						  'set lock mode to wait 4;'||' '||
						  'load FROM /resplogifx/archivoscartera/si_cte_huella_aut.unl DELIMITER ''|'' '||' '||
						  'insert INTO cliente_paso_huellas;" > /resplogifx/archivoscartera/cargatemp.sql';											  
						  SYSTEM cSql;
						----- ----- ----- -----
						  LET cSql = '';
						  LET cSql  = "dbaccess bdinteg /resplogifx/archivoscartera/cargatemp.sql"; 
						  SYSTEM cSql;
						  LET cSql = '';
					end if;
			----- ----- ----- ----- ----- ----- ----- -----        
			ELSE     
			----- ----- ----- ----- ----- ----- ----- -----
				  --SE CREA LA TABLA DE PASO  
				  CREATE TABLE bdinteg:"informix".cliente_paso_huellas(numcte char(20));
				  create unique index inx_paso1_cli on cliente_paso_huellas(numcte);
				  update statistics medium for table cliente_paso_huellas;
				  ----- ----- ----- ----- 
				  LET cSql = '';
				  LET cSql = 'echo "SET ISOLATION TO DIRTY READ;'|| ' '||
				  'set lock mode to wait 4;'||' '||
				  'load FROM /resplogifx/archivoscartera/si_cte_huella_aut.unl DELIMITER ''|'' '||' '||
				  'insert INTO bdinteg:cliente_paso_huellas;" > /resplogifx/archivoscartera/cargatemp.sql';  
				  SYSTEM cSql;
				  ----- ----- ----- -----
				  LET cSql = '';
				  LET cSql  = "dbaccess bdinteg /resplogifx/archivoscartera/cargatemp.sql"; 
				  SYSTEM cSql;
				  --LET cSql = '';
				  ----- ----- ----- -----
			end if;
		----- ----- ----- ----- ----- ----- ----- -----
		FOREACH WITH HOLD
		----- ----- ----- ----- ----- ----- ----- -----
			--Se realiza la consulta en la tabla para validar solo clientes de  cuales tenemos respaldada la imagen
			SELECT numcte INTO Cnumcte FROM bdinteg:cliente_paso_huellas
			----- ----- ----- ----- ----- ----- ----- -----    
			 SELECT count(cli.numcte) into Vexiste FROM bdinteg:"informix".si_cliente cli
				INNER JOIN bdinteg:"informix".si_cte_huella hue on cli.numcte = hue.numcte
				LEFT JOIN bdinvers:"informix".sv_maeinv inv ON cli.empresa = inv.empresa AND cli.numcte = inv.num_cte
				LEFT JOIN bdicheq:"informix".sc_maechq che ON cli.empresa = che.empresa AND cli.numcte = che.num_cte
				LEFT JOIN bdicheq:"informix".sc_firmantes fir ON cli.empresa = fir.empresa AND cli.numcte = fir.numcte
				LEFT JOIN bdicheq:"informix".sc_beneficiario benf ON cli.empresa = benf.empresa AND cli.numcte = benf.numcte
				LEFT JOIN bdicred:"informix".sd_maecred maecred ON cli.empresa = maecred.empresa AND cli.numcte = maecred.numcte
				LEFT JOIN bdicred:"informix".sd_maecredcrd maecrd ON cli.empresa = maecrd.empresa AND cli.numcte = maecrd.numcte
				LEFT JOIN bdisolic:"informix".ss_solicitudes sol ON cli.empresa = sol.empresa AND cli.numcte = sol.numcte
				WHERE cli.tipo_cliente = '2'
				AND inv.num_cte is null
				AND che.num_cte is null
				AND fir.numcte is null
				AND benf.numcte is null
				AND maecred.numcte is null
				AND maecrd.numcte is null
				AND sol.numcte is null
				AND cli.numcte = Cnumcte;
			----- ----- ----- ----- ----- ----- ----- -----      
			IF Vexiste > 0 THEN  
				----- ----- -----
				BEGIN;	
				----- ----- -----
					 --Elimina el registro de la huella de la si_cte_huella
					 DELETE FROM bdinteg:"informix".si_cte_huella WHERE numcte = Cnumcte;					 
					----- ----- -----
					 --Se elimina de la tabla clientes_paso
					 DELETE FROM bdinteg:"informix".cliente_paso_huellas WHERE numcte = Cnumcte;
				----- ----- -----					   
			   COMMIT;
				----- ----- -----
			ELSE
				----- ----- -----
				 BEGIN; 
				----- ----- -----
				   DELETE FROM bdinteg:"informix".cliente_paso_huellas WHERE numcte = Cnumcte;
				----- ----- -----
				 COMMIT;
				----- ----- -----
			END IF;
			----- ----- -----     
		END FOREACH;
		----- ----- -----
			DROP TABLE  bdinteg:"informix".cliente_paso_huellas; 
			RETURN cCodRet,cMensajeRet;
			----- ----- -----    
END;
END PROCEDURE
;

