				END IF;
            FOREACH 
                SELECT {+INDEX (bdinteg:si_refdirecciones idx_si_refdirecciones)} secuencia, tipo_dir INTO vi_secuencia, vc_TipoDir
                FROM bdinteg:si_refdirecciones WHERE numcte=pClienteTraspasaCtas            

                LET vc_tabla = "si_refdirecciones";
                LET vc_detalle_mov = TRIM(pClienteTraspasaCtas)||'|'||vi_secuencia||'|'||TRIM(vc_TipoDir);
                LET vc_proceso='REFERENCIAS DIRECCIONES';

                INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

                INSERT INTO bdinteg:si_fusrefdirecciones
                SELECT {+INDEX (bdinteg:si_refdirecciones idx_si_refdirecciones)} * FROM bdinteg:si_refdirecciones where numcte=pClienteTraspasaCtas and secuencia = vi_secuencia;

				IF iExiste>0 THEN
					LET vi_MaxSec = vi_MaxSec + 1;

					SELECT {+INDEX (bdinteg:si_refdirecciones idx_si_refdirecciones)} tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio,
					cod_postal, apart_postal, tipo_telef1, telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, estado_inegi, municipio_inegi, localidad_inegi,
					numerociudad, numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote,
					edificio, entrada, observaciones, numcte_banco, user_insert, fecha_insert
					INTO vc_TipoDir, vc_calle, vc_colonia, vc_entre_calles, vc_pais, vc_estado, vc_ciudad, vc_municipio, vc_cod_postal, vc_apart_postal, 
					vc_tipo_telef1, vc_telefono1, vc_tipo_telef2, vc_telefono2, vc_tipo_telef3, vc_telefono3, vc_extension, vc_estado_inegi, vc_municipio_inegi, vc_localidad_inegi, 
					vc_numerociudad, vc_numeroextcalle, vc_numerointcalle, vc_departamento, vc_numerocalle, vc_numerocolonia, vc_puntocardinal, vc_unidadhabitac, vc_manzana, vc_otros, 
					vc_andador, vc_etapa, vc_lote, vc_edificio, vc_entrada, vc_observaciones, vc_ctebanco, vc_user_insert, vd_fecha_insert
					FROM bdinteg:si_refdirecciones                                                         
					WHERE numcte=pClienteTraspasaCtas and secuencia = vi_secuencia;
					
					INSERT INTO bdinteg:si_refdirecciones (numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal, tipo_telef1, 
					telefono1, tipo_telef2, telefono2, tipo_telef3, telefono3, extension, estado_inegi, municipio_inegi, localidad_inegi, numerociudad, 
					numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, otros, andador, etapa, 
					lote, edificio, entrada, observaciones, numcte_banco, user_insert, fecha_insert)
					VALUES (pClienteTitular, vi_MaxSec, vc_TipoDir, vc_calle, vc_colonia, vc_entre_calles, vc_pais, vc_estado, vc_ciudad, vc_municipio, vc_cod_postal, vc_apart_postal, 
					vc_tipo_telef1, vc_telefono1, vc_tipo_telef2, vc_telefono2, vc_tipo_telef3, vc_telefono3, vc_extension, vc_estado_inegi, vc_municipio_inegi, vc_localidad_inegi, 
					vc_numerociudad, vc_numeroextcalle, vc_numerointcalle, vc_departamento, vc_numerocalle, vc_numerocolonia, vc_puntocardinal, vc_unidadhabitac, vc_manzana, vc_otros, 
					vc_andador, vc_etapa, vc_lote, vc_edificio, vc_entrada, vc_observaciones, vc_ctebanco, vc_user_insert, vd_fecha_insert);
				ELSE 
					UPDATE {+INDEX (bdinteg:si_refdirecciones idx_si_refdirecciones)} bdinteg:si_refdirecciones SET numcte = pClienteTitular WHERE numcte=pClienteTraspasaCtas and secuencia = vi_secuencia; 
				END IF;
            END FOREACH;
			DELETE {+INDEX (bdinteg:si_refdirecciones idx_si_refdirecciones)} FROM bdinteg:si_refdirecciones WHERE numcte=pClienteTraspasaCtas;
        END IF;
--**********************************************************************************************************

--**************************************INICIA TRASPASO DE TABLA REFCLIENTES ********************************************************************
	SET ISOLATION TO DIRTY READ; 
	SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} FIRST 1 numcte INTO pCte FROM bdinteg:si_refclientes WHERE numcte=pClienteTraspasaCtas;
	LET iExiste = dbinfo("sqlca.sqlerrd2");
	    IF iExiste>0 THEN
			SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} COUNT(*) INTO iExiste FROM bdinteg:si_refclientes WHERE numcte=pClienteTitular;
				IF iExiste>0 THEN
					SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} MAX(secuencia) INTO vi_MaxSec FROM bdinteg:si_refclientes WHERE numcte=pClienteTitular;
				END IF;
            FOREACH				
                SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} secuencia, num_solicitud INTO vi_secuencia, vc_numsolic
                FROM bdinteg:si_refclientes WHERE numcte=pClienteTraspasaCtas
				
				LET vc_tabla = "si_refclientes";
                LET vc_detalle_mov = TRIM(pClienteTraspasaCtas)||'|'||vi_secuencia||'|'||TRIM(vc_numsolic);
                LET vc_proceso='REFERENCIAS CLIENTES';
				
				INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

				INSERT INTO bdinteg:si_fusrefclientes
				SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} * FROM bdinteg:si_refclientes where numcte=pClienteTraspasaCtas and secuencia = vi_secuencia and empresa='001';
				
				IF iExiste>0 THEN
					LET vi_MaxSec = vi_MaxSec + 1;

					SELECT {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)}empresa, sucursal, apell_paterno, apell_materno, nombre1, nombre2, rfc, fecha_nac, curp, sexo,
					estado_civil, nacionalidad, no_fm3, codidentifi, pers_domicilio, email, parentesco, apellido_cas, numcte_ref, numcte_banco, user_insert, fecha_insert
					INTO vc_empresa, vc_sucursal, vc_apellpat, vc_apellmat, vc_nombre1, vc_nombre2, vc_rfc, vc_fecnac, vc_curp, vc_sexo, vc_edocivil, vc_nacionalidad,
					vc_nofm3, vc_codident, vc_persdom, vc_email, vc_parentesco, vc_apellcas, vc_cteref, vc_ctebanco, vc_user_insert, vd_fecha_insert
					FROM bdinteg:si_refclientes
					WHERE numcte=pClienteTraspasaCtas and secuencia = vi_secuencia and empresa='001';
					
					INSERT INTO bdinteg:si_refclientes (empresa, numcte, sucursal, secuencia, apell_paterno, apell_materno, nombre1, nombre2, rfc, fecha_nac, curp, sexo,
					estado_civil, nacionalidad, no_fm3, codidentifi, pers_domicilio, email,	parentesco, apellido_cas, numcte_ref, numcte_banco, user_insert, fecha_insert)
					VALUES (vc_empresa, pClienteTitular, vc_sucursal, vi_MaxSec, vc_apellpat, vc_apellmat, vc_nombre1, vc_nombre2, vc_rfc, vc_fecnac, vc_curp, vc_sexo,
					vc_edocivil, vc_nacionalidad, vc_nofm3, vc_codident, vc_persdom, vc_email, vc_parentesco, vc_apellcas, vc_cteref, vc_ctebanco, vc_user_insert,
					vd_fecha_insert);
				ELSE 
					UPDATE {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} bdinteg:si_refclientes SET numcte = pClienteTitular WHERE numcte=pClienteTraspasaCtas and secuencia = vi_secuencia and empresa='001'; 
				END IF;
            END FOREACH;
			DELETE {+INDEX (bdinteg:si_refclientes idx_si_refclientes1)} FROM bdinteg:si_refclientes WHERE numcte=pClienteTraspasaCtas;
        END IF;
--********************************************************************************************************** 

--**************************************INICIA TRASPASO DE TABLA INGRESOS ********************************************************************
	SET ISOLATION TO DIRTY READ; 
	SELECT {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} FIRST 1 numcte INTO pCte FROM bdinteg:si_ingresos WHERE numcte=pClienteTraspasaCtas;
	LET iExiste = dbinfo("sqlca.sqlerrd2");
	    IF iExiste>0 THEN
			SELECT {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} COUNT(*) INTO iExiste FROM bdinteg:si_ingresos WHERE numcte=pClienteTitular;
            FOREACH 
                SELECT {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} sec_ingreso, tipo_ingreso INTO vi_secuencia, vc_TipoDir
                FROM bdinteg:si_ingresos WHERE numcte=pClienteTraspasaCtas            

                LET vc_tabla = "si_ingresos";
                LET vc_detalle_mov = TRIM(pClienteTraspasaCtas)||'|'||vi_secuencia||'|'||TRIM(vc_TipoDir);
                LET vc_proceso='INGRESOS';

                INSERT INTO bdinteg:log_fusionclientes(proceso, tabla, cliente_tit, cliente_tras, detalle_mov, fecha_hora, user_insert, fecha_insert)
                VALUES (vc_proceso, vc_tabla, pClienteTitular, pClienteTraspasaCtas, vc_detalle_mov, CURRENT HOUR TO FRACTION(4), 'informix', CURRENT);

                INSERT INTO bdinteg:si_fusingresos
                SELECT {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} * FROM bdinteg:si_ingresos where numcte=pClienteTraspasaCtas and sec_ingreso = vi_secuencia and empresa='001';
				
				IF iExiste=0 THEN
					UPDATE {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} bdinteg:si_ingresos SET numcte = pClienteTitular WHERE numcte=pClienteTraspasaCtas and sec_ingreso = vi_secuencia and empresa='001'; 
				ELSE
					DELETE {+INDEX (bdinteg:si_ingresos inx_ingresos_tipo1)} FROM bdinteg:si_ingresos WHERE numcte=pClienteTraspasaCtas and sec_ingreso = vi_secuencia and empresa='001'; 
				END IF;
				
            END FOREACH;
        END IF;			 
--********************************************************************************************************** 
END FOREACH;  
    IF vc_CodRet = "00000" THEN
        RETURN vc_CodRet, vc_Mensaje;
    END IF;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultabitacoracte_pba(pEmpresa CHAR(3), pNumCte CHAR(20), pTipoProd CHAR(4))
--DATOS A REGRESAR--
RETURNING 	CHAR(5) AS CodigoRetorno,
			CHAR(1) AS Exito;

--DEFINICION DE VARIABLES--
DEFINE cCodRet 	CHAR(5);
DEFINE iSqlErr 	INTEGER;
DEFINE cExito	CHAR(1);
DEFINE cFecha	CHAR(10);

--INICIALIZACION DE VARIABLES--
LET cCodRet = '00000';
LET iSqlErr = 0;
LET cExito 	= '';
LET cFecha 	= '';

--SET DEBUG FILE TO "/tmp/sp_consultabitacoracte.out";
--TRACE ON;

BEGIN

	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cExito;
		END IF;
	END EXCEPTION

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	IF pEmpresa = '' OR pEmpresa IS NULL OR pNumCte = '' OR pNumCte IS NULL OR pTipoProd = '' OR pTipoProd IS NULL THEN
		LET cCodRet = '00001'; --PARAMETRO DE ENTRADA VACIO.
		RETURN cCodRet, cExito;
	ELSE
		SELECT fecha_hoy INTO cFecha FROM si_fechas;

		IF EXISTS(SELECT {+INDEX(si_encuesta_cte idx_si_encuesta_cte)} numcte FROM "informix".si_encuesta_cte 
			WHERE empresa = pEmpresa AND numcte = pNumCte AND tipo_producto = pTipoProd AND fecha_insert = cFecha::DATE) THEN
			LET cExito = '0';
		ELSE
			LET cExito = '1';
		END IF;
		RETURN cCodRet, cExito;
	END IF;
END;
END PROCEDURE
DOCUMENT
"CREO  : Daniela Ramírez",
"FECHA : 01/02/2013",
"BD    : bdinteg";

CREATE PROCEDURE "informix".sp_genera_emp_gc()
				returning CHAR(5) AS Cod_Retorno;


DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;
--SISTEMA DE CUENTA 01 VARIABLES
DEFINE cTicket			CHAR(20);
DEFINE cEmpleado		CHAR(10);
DEFINE cEmpresa			CHAR(4);
DEFINE cNumcte			CHAR(20);
DEFINE cNumcte2			CHAR(20);
DEFINE cValidanumcte	CHAR(20);
DEFINE iNumRows			INTEGER;
DEFINE cNombreEm		CHAR(104);
DEFINE cNombreEm2		CHAR(104);
DEFINE cFnac			DATE;
DEFINE cNombre1			CHAR(26);
DEFINE cNombre2			CHAR(26);
DEFINE cPaterno			CHAR(26);
DEFINE cMaterno			CHAR(26);


--inicializando variables
LET  iexiste = 0;
LET cCodRet = "00000";
LET iSql_err = 0 ;
LET cTicket = "" ;
LET cEmpleado = "" ;
LET cEmpresa = "" ;
LET cNumcte="";
LET cValidanumcte="";
LET iNumRows=0;
LET cNombreEm="";
LET cNombreEm2="";
LET cNombre1="";
LET cNombre2="";
LET cPaterno="";
LET cMaterno="";
LET cNumcte2="";

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	  --SET DEBUG FILE TO "/informix/VH/huella/sp_genera_emp_gc.out";
	  --TRACE ON;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	FOREACH
		SELECT {+INDEX (bdinteg:si_huella_linea_resultado idx_huellalinea_res_mensaje)} DISTINCT ticket,cliente AS empleado,empresa INTO cTicket,cEmpleado,cEmpresa FROM si_huella_linea_resultado 
		WHERE num_mensaje=602 and empresa NOT IN (4,5) AND (ticket<>0 AND cliente<>0)

		SELECT {+INDEX (bdinteg:si_huella_linea idx_huellaline4)} FIRST 1 NVL(numcte,'') INTO cNumcte FROM si_huella_linea WHERE ticket=cTicket;

		INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
		VALUES (cNumcte,cEmpleado,1,cEmpresa,current year to fraction(3),current year to fraction(3),1);

	END FOREACH;

	SET ISOLATION TO DIRTY READ;
	FOREACH
		SELECT {+INDEX (bdicheq:sc_maechq mae1)} DISTINCT num_cte INTO cNumcte FROM bdicheq:sc_maechq
		WHERE num_cte in (SELECT {+INDEX (bdinteg:si_ctepf 225_483)} DISTINCT numcte FROM bdinteg:si_ctepf	WHERE numeric2::CHAR(8) IN (
		SELECT ejecutivo FROM bdinteg:si_ejecut WHERE password NOT IN ('BAJA','baja'))) and producto='1300' and status_cta in(1,3)

		SELECT {+INDEX (bdinteg:si_ctepf 225_483)} FIRST 1 numeric2::CHAR(8) AS empleado,numeric1::CHAR(4) as empresa INTO cEmpleado,cEmpresa FROM si_ctepf WHERE numcte=cNumcte;

		SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} FIRST 1 numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte AND empleado=cEmpleado;
		LET iexiste = dbinfo("sqlca.sqlerrd2");
		IF iexiste=0 THEN
			INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
			VALUES (cNumcte,cEmpleado,2,cEmpresa,current year to fraction(3),current year to fraction(3),1);
		END IF;
	END FOREACH;

	SET ISOLATION TO DIRTY READ;
	FOREACH
		SELECT DISTINCT num_cte INTO cNumcte FROM bdicheq:sc_maechq WHERE producto='1300' AND status_cta IN(1,3) 
		AND num_cte NOT IN (SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} numcte FROM bdinteg:si_empleado_cliente_coppel WHERE cve_proceso=2)

		SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} FIRST 1 numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte;
		LET iexiste = dbinfo("sqlca.sqlerrd2");
		IF iexiste=0 THEN
			INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
			VALUES (cNumcte,NULL,2,null,current year to fraction(3),current year to fraction(3),1);
		END IF;
	END FOREACH;

	SET ISOLATION TO DIRTY READ;
	FOREACH

		SELECT numcte INTO cNumcte FROM si_empleado_cliente_coppel WHERE cve_proceso=2 AND empleado IS NULL

		SELECT FIRST 1 emp INTO cEmpleado FROM si_funciones WHERE emp IN (SELECT {+INDEX (bdinteg:si_ctepf 225_483)} numeric2::char(8) FROM si_ctepf
		WHERE numcte IN (SELECT numcte FROM si_empleado_cliente_coppel WHERE cve_proceso=2 AND empleado IS NULL AND numcte=cNumcte ));

		UPDATE si_empleado_cliente_coppel SET empleado=cEmpleado WHERE numcte=cNumcte AND empleado IS NULL;
	END FOREACH;

/*
	SET ISOLATION TO DIRTY READ;
	FOREACH
		SELECT {+INDEX (bdinteg:si_funciones idx_si_funciones3)} emp,nombre,fnac INTO cEmpleado,cNombreEm,cFnac FROM si_funciones WHERE fnac IS NOT NULL

		FOREACH
			SELECT  {+INDEX (bdinteg:si_cliente idx_si_cliente5)} TRIM(a.nombre1),NVL(TRIM(a.nombre2),''),TRIM(a.apell_paterno),TRIM(a.apell_materno),b.fecha_nac,a.numcte 
			INTO cNombre1,cNombre2,cPaterno,cMaterno,cFnac,cNumcte FROM si_cliente a,si_ctepf b WHERE a.empresa IS NOT NULL AND a.numcte=b.numcte AND a.tipo_cliente=1 AND a.tpo_persona='01' AND b.fecha_nac=cFnac

			IF cNombre2<>'' THEN
				LET cNombreEm2=trim(cPaterno)||" "||trim(cMaterno)||" "||trim(cNombre1)||" "||trim(cNombre2);
				--SELECT {+INDEX (bdinteg:si_funciones idx_si_funciones)} FIRST 1 emp INTO cEmpleado FROM si_funciones WHERE TRIM(nombre)=cNombreEm AND fnac=cFnac;
			ELSE
				LET cNombreEm2=trim(cPaterno)||" "||trim(cMaterno)||" "||trim(cNombre1);
				--SELECT {+INDEX (bdinteg:si_funciones idx_si_funciones)} FIRST 1 emp INTO cEmpleado FROM si_funciones WHERE TRIM(nombre)=cNombreEm AND fnac=cFnac;
			END IF;
			IF TRIM(cNombreEm)=TRIM(cNombreEm2) THEN
				LET iexiste=1;
			ELSE
				LET iexiste=0;	
			END IF;

			--LET iexiste = dbinfo("sqlca.sqlerrd2");
			IF iexiste>0 THEN
				SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte AND empleado=cEmpleado;
				LET iexiste = dbinfo("sqlca.sqlerrd2");
					IF iexiste=0 THEN
						INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
						VALUES (cNumcte,cEmpleado,3,null,current year to fraction(3),current year to fraction(3),1);
					END IF;	
			END IF;
		END FOREACH;	

	END FOREACH;

	SET ISOLATION TO DIRTY READ;
	FOREACH
		SELECT  {+INDEX (bdinteg:si_cliente idx_si_cliente5)} TRIM(a.nombre1),NVL(TRIM(a.nombre2),''),TRIM(a.apell_paterno),TRIM(a.apell_materno),b.fecha_nac,a.numcte 
		INTO cNombre1,cNombre2,cPaterno,cMaterno,cFnac,cNumcte FROM si_cliente a,si_ctepf b WHERE a.empresa IS NOT NULL AND a.numcte=b.numcte AND a.tipo_cliente=1 AND a.tpo_persona='01'

		IF cNombre2<>'' THEN
			LET cNombreEm=trim(cPaterno)||" "||trim(cMaterno)||" "||trim(cNombre1)||" "||trim(cNombre2);
			SELECT {+INDEX (bdinteg:si_funciones idx_si_funciones)} FIRST 1 emp INTO cEmpleado FROM si_funciones WHERE TRIM(nombre)=cNombreEm AND fnac=cFnac;
		ELSE
			LET cNombreEm=trim(cPaterno)||" "||trim(cMaterno)||" "||trim(cNombre1);
			SELECT {+INDEX (bdinteg:si_funciones idx_si_funciones)} FIRST 1 emp INTO cEmpleado FROM si_funciones WHERE TRIM(nombre)=cNombreEm AND fnac=cFnac;
		END IF;
		
		LET iexiste = dbinfo("sqlca.sqlerrd2");
		IF iexiste>0 THEN
			SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte AND empleado=cEmpleado;
			LET iexiste = dbinfo("sqlca.sqlerrd2");
				IF iexiste=0 THEN
					INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
					VALUES (cNumcte,cEmpleado,3,null,current year to fraction(3),current year to fraction(3),1);
				END IF;	
		END IF;
	END FOREACH;
*/

	RETURN cCodRet;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consulta_actualiza_indicadortel
(
pEmpresa            CHAR(3),
pIndicador          INTEGER
)
RETURNING
	CHAR(6) 		AS cod_ret,
    CHAR(80) 		AS desc_ret,
	INTEGER			AS indicador

	---DECLARACIONES
    DEFINE iSqlErr			INTEGER;
    DEFINE iIsamErr			INTEGER;
    DEFINE cErrorInfo		CHAR(80);
    DEFINE cDescRet		    CHAR(80);
    DEFINE cCodRet			CHAR(6);

	DEFINE iIndicador		INTEGER;


	---INICIALIZACIONES
	LET iSqlErr				= 0;
	LET iIsamErr			= 0;
	LET cErrorInfo			= "";
    LET cDescRet		    = "PROCESO EXITOSO";
	LET cCodRet				= "000000";

	LET iIndicador			= 0;


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
            LET cDescRet = cErrorInfo;
			RETURN cCodRet,cDescRet,iIndicador;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/respaldosbd/has/sp_consulta_actualiza_indicadortel.out';
	--TRACE ON;

	IF NVL(pEmpresa,"") = "" OR pIndicador IS NULL THEN
        LET cCodRet = "000001";
        LET cDescRet = "FALTAN PARAMETROS DE ENTRADA";
	ELSE
		IF pIndicador = -1 THEN
			SELECT (TRIM(valor))::INTEGER
			INTO iIndicador
			FROM bdinteg: "informix".si_param 
			WHERE empresa = pEmpresa AND cod_param = "140";
			
			IF dbinfo("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = "000002";
				LET cDescRet = "NO EXISTE PARAMETRO DE INDICADOR PARA ACTUALIZACION DE TELS";
			END IF
		ELIF pIndicador > -1 THEN
			UPDATE bdinteg: "informix".si_param
			SET valor = pIndicador
			WHERE empresa = pEmpresa AND cod_param = "140";
		END IF
		
	END IF
    
    RETURN cCodRet,cDescRet,iIndicador;
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para consultar / actualizar el parametro de indicador para la actualizacion de telefonos', 
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Septiembre 2013';

CREATE PROCEDURE "informix".sp_genera_emp_gc2()
				returning CHAR(5) AS Cod_Retorno;


DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;
--SISTEMA DE CUENTA 01 VARIABLES
DEFINE cTicket			CHAR(20);
DEFINE cEmpleado		CHAR(10);
DEFINE cEmpresa			CHAR(4);
DEFINE cNumcte			CHAR(20);
DEFINE cNumcte2			CHAR(20);
DEFINE cValidanumcte	CHAR(20);
DEFINE iNumRows			INTEGER;
DEFINE cNombreEm		CHAR(104);
DEFINE cNombreEm2		CHAR(104);
DEFINE cFnac			DATE;
DEFINE cNombre1			CHAR(26);
DEFINE cNombre2			CHAR(26);
DEFINE cPaterno			CHAR(26);
DEFINE cMaterno			CHAR(26);
DEFINE cIniciaSql		CHAR(20);
DEFINE cTerminaSql		CHAR(20);
DEFINE c3uno			CHAR(3);
DEFINE c3dos			CHAR(3);

--inicializando variables
LET  iexiste = 0;
LET cCodRet = "00000";
LET iSql_err = 0 ;
LET cTicket = "" ;
LET cEmpleado = "" ;
LET cEmpresa = "" ;
LET cNumcte="";
LET cValidanumcte="";
LET iNumRows=0;
LET cNombreEm="";
LET cNombreEm2="";
LET cNombre1="";
LET cNombre2="";
LET cPaterno="";
LET cMaterno="";
LET cNumcte2="";
LET cIniciaSql="";
LET cTerminaSql="";
LET c3uno="";
LET c3dos="";


BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	  --SET DEBUG FILE TO "/informix/VH/cnsif/sp_genera_emp_gc.out";
	  --TRACE ON;
	SET ISOLATION TO dirty READ;
	SET LOCK MODE TO wait 3;

	FOREACH
		SELECT b.emp, a.numcte, TRIM(nombre1)|| ' ' ||TRIM(nombre2)|| ' '||TRIM(apell_paterno)|| ' ' ||TRIM(apell_materno) INTO cEmpleado,cNumcte,cNombreEm
		FROM si_funciones b, si_cliente a, si_ctepf c
		WHERE b.fnac=c.fecha_nac and a.nombre2<>''
		AND TRIM(b.nombre)=TRIM(apell_paterno)|| ' ' ||TRIM(apell_materno)|| ' ' ||TRIM(nombre1)|| ' ' ||TRIM(nombre2)
		AND a.numcte=c.numcte

		SET ISOLATION TO DIRTY READ;
		SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} FIRST 1 numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte;
		LET iexiste = dbinfo("sqlca.sqlerrd2");
		IF iexiste=0 THEN
			INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
			VALUES (cNumcte,cEmpleado,3,null,current year to fraction(3),current year to fraction(3),1);
		ELSE
			UPDATE {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} bdinteg:si_empleado_cliente_coppel SET empleado= cEmpleado WHERE numcte=cNumcte AND empleado IS NULL;
		END IF;	
	END FOREACH;	

	RETURN cCodRet;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtenerdomiciliocliente(pEmpresa CHAR(3), pNumCte CHAR(20), pNumCredito CHAR (20), pTipoDir CHAR(1))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5)    AS Cod_ret, 
	CHAR(20)   AS numeroCte, 
	CHAR(20)   AS numCredito, 
	CHAR(104)  AS nomCte, 
	CHAR(2)    AS estado, 
	CHAR(30)   AS nombreEstado, 
	CHAR(3)    AS ciudad, 
	SMALLINT   AS numeroCiudad, 
	CHAR(60)   AS nombreCiudad, 
	SMALLINT   AS ciudadCoppel, 
	INTEGER    AS numeroColonia, 
	CHAR(32)   AS nombrecolonia, 
	CHAR(27)   AS municipio, 
	INTEGER    AS numeroCalle, 
	CHAR(30)   AS nombreCalle, 
	SMALLINT   AS edificio, 
	CHAR(6)    AS departamento, 
	CHAR(5)    AS codigoPostal, 
	CHAR(80)   AS observaciones, 
	CHAR(10)   AS numeroExterior,
	CHAR(10)   AS numeroInterior, 
	CHAR(30)   AS nombreEdificio; 

	--DEFINICION DE VARIABLES--
	DEFINE iSqlErr             INTEGER;
	DEFINE cCodRet             CHAR(5);
	DEFINE cNumCte             CHAR(20);
	DEFINE cNombreCte          CHAR(104);
	DEFINE cNumCredito         CHAR(20);
	DEFINE cEstado             CHAR(2);
	DEFINE cCiudad             CHAR(3);
	DEFINE siNumCiudad         SMALLINT;
	DEFINE iNumCalle           INTEGER;
	DEFINE siEdificio          SMALLINT;
	DEFINE cDepartamento       CHAR(6);
	DEFINE cCodPostal          CHAR(5);
	DEFINE cObservaciones      CHAR(80);
	DEFINE cNumExt             CHAR(10);
	DEFINE cNumInt             CHAR(10);
	DEFINE cNomEstado          CHAR(30);
	DEFINE cNomCiudad          CHAR(60);
	DEFINE cCiudadCoppel       SMALLINT;
	DEFINE iNumColonia         INTEGER;
	DEFINE cNomColonia         CHAR(32);
	DEFINE cMunicipio          CHAR(27);
	DEFINE cNomCalle           CHAR(30);
	DEFINE cNombreEdificio     CHAR(30);

	--INICIALIZACION DE VARIABLES--
	LET iSqlErr                = 0;
	LET cCodRet                = '000';
	LET cNumCte                = '';
	LET cNombreCte             = '';
	LET cNumCredito            = '';
	LET cEstado                = '';
	LET cCiudad                = '';
	LET siNumCiudad            = 0;
	LET iNumCalle              = 0;
	LET siEdificio             = 0;
	LET cDepartamento          = '';
	LET cCodPostal             = '';
	LET cObservaciones         = '';
	LET cNumExt                = '';
	LET cNumInt                = '';
	LET cNomEstado             = '';
	LET cNomCiudad             = '';
	LET cCiudadCoppel          = 0;
	LET iNumColonia            = 0;
	LET cNomColonia            = '';
	LET cMunicipio             = '';
	LET cNomCalle              = '';
	LET cNombreEdificio        = '';

	--SET DEBUG FILE TO "/home/informix/sp_ObtenerDomicilioCliente.out";
	--TRACE ON;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
					cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
					cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
			END IF;
		END EXCEPTION;

		IF NVL(pNumCte, '') = '' AND NVL(pNumCredito, '') = '' THEN
			LET cCodRet = '001';
			RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
				cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
				cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
		END IF;

		IF NVL(pNumCte, '') <> '' THEN
			SELECT numcte, TRIM(nombre1) || ' ' || TRIM(nombre2) || ' ' || TRIM(apell_paterno) || ' ' || TRIM(apell_materno)
			INTO cNumCte, cNombreCte
			FROM "informix".si_cliente 
			WHERE empresa = pEmpresa 
			AND numcte = pNumCte;

			IF cNumCte IS NULL OR TRIM(cNumCte) = '' THEN
				LET cCodRet = '002';
				RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
					cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
					cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
			END IF;

			IF NVL(pNumCredito, '') <> '' THEN
				SELECT num_credito 
				INTO cNumCredito
				FROM bdicred:"informix".sd_maecred 
				WHERE empresa = pEmpresa 
				AND num_credito = pNumCredito;
			ELSE
				SELECT FIRST 1 num_credito 
				INTO cNumCredito
				FROM bdicred:"informix".sd_maecred 
				WHERE empresa = pEmpresa 
				AND numcte = pNumCte;
			END IF;

		ELIF NVL(pNumCredito, '') <> '' THEN
			SELECT num_credito, numcte 
			INTO cNumCredito, cNumCte
			FROM bdicred:"informix".sd_maecred 
			WHERE empresa = pEmpresa 
			AND num_credito = pNumCredito;

			IF cNumCredito IS NULL OR TRIM(cNumCredito) = '' THEN
				LET cCodRet = '003';
				RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
					cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
					cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
			END IF;

			SELECT TRIM(nombre1) || ' ' || TRIM(nombre2) || ' ' || TRIM(apell_paterno) || ' ' || TRIM(apell_materno)
			INTO cNombreCte
			FROM "informix".si_cliente 
			WHERE empresa = pEmpresa 
			AND numcte = cNumCte;
		END IF;

		SELECT numcte, estado, ciudad, numerociudad, numerocolonia, numerocalle, numeroextcalle, 
			numerointcalle, edificio, departamento, cod_postal, observaciones
		INTO cNumCte, cEstado, cCiudad, siNumCiudad, iNumColonia, iNumCalle, cNumExt, cNumInt, 
			siEdificio, cDepartamento, cCodPostal, cObservaciones
		FROM "informix".si_direcciones_actual
		WHERE numcte = cNumCte
		AND secuencia = (SELECT MAX(secuencia) FROM "informix".si_direcciones_actual WHERE numcte = cNumCte 					AND tipo_dir = pTipoDir);
		
		IF cNumCte IS NULL OR TRIM(cNumCte) = '' THEN
			LET cCodRet = '004';
			RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
				cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
				cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
		END IF;

		SELECT nombre INTO cNomEstado
		FROM "informix".si_estados WHERE estado = cEstado;

		SELECT nombre, ciudad_coppel 
		INTO cNomCiudad, cCiudadCoppel
		FROM "informix".si_ciudades 
		WHERE ciudad = cCiudad 
		AND estado = cEstado;

		SELECT nombrezona, municipiozona 
		INTO cNomColonia, cMunicipio
		FROM "informix".si_catzonas 
		WHERE numerociudad = siNumCiudad 
		AND numerocolonia = iNumColonia;

		SELECT nombrecalle 
		INTO cNomCalle 
		FROM "informix".si_catcalles 
		WHERE numerocalle = iNumCalle;
		
		--DSB 04/05/2011
		SELECT nombredomicilio 
		INTO cNombreEdificio
		FROM "informix".si_catdomicilios 
		WHERE numerociudad = siNumCiudad 
		AND numerocolonia = iNumColonia 
		AND clavedomicilio = 5
		AND complementoclave = siEdificio;

		RETURN cCodRet, cNumCte, cNumCredito, cNombreCte, cEstado, cNomEstado, cCiudad, siNumCiudad, cNomCiudad,
			cCiudadCoppel, iNumColonia, cNomColonia, cMunicipio, iNumCalle, cNomCalle, siEdificio, cDepartamento, 
			cCodPostal, cObservaciones, cNumExt, cNumInt, cNombreEdificio;
	END
END PROCEDURE
DOCUMENT
'Valida si el Cliente existe y consulta su domicilio de casa o trabajo',
'AUTOR: Iris Arias Zazueta',
'FECHA: 24/03/2011',
'DSB 04/05/2011 - Se modifica para obtener el nombre del edificio',
'MODIFICO: Iris Arias Zazueta',
'BD   : bdinteg',
'VER  : 1.0',
'MODIFICÓ: CARLOS OCHOA VALENZUELA',
'DESCRIPCIÓN: Se aplican reglas de informix, asi como se sustituye la obtención de datos',
'             de la si_direcciones, por si_direcciones_actual.';

CREATE PROCEDURE "informix".sp_elimina_campanias(pEmpresa CHAR(3), pIDCamp SMALLINT, pIDJerarquia SMALLINT)
RETURNING	CHAR(5) AS CodRet;	

	-- DEFINICION DE VARIABLES
    DEFINE	cCodRet			CHAR(5);
	DEFINE	iSqlErr			INTEGER;
	DEFINE	sIDMensaje 		SMALLINT;
		
	--INICIALIZACION DE VARIABLES--
    LET cCodRet			= "00000";
    LET iSqlErr			= 0;
	LET	sIDMensaje		= 0;
		
	--SET DEBUG FILE TO '/respaldosbd/obed/sp_elimina_campania.out';
	--TRACE ON;
	
    BEGIN

        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
				RETURN cCodRet;
            END IF;
        END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF LENGTH(TRIM(NVL(pEmpresa,""))) = 0 OR NVL(pIDCamp, 0) = 0 OR NVL(pIDJerarquia, 0) = 0  THEN
			--PARÁMETROS INCORRECTOS
			LET cCodRet = "00001";
			RETURN cCodRet;
		ELSE
			--SE OBTIENE EL ID DEL MENSAJE
			SELECT FIRST 1 idmensaje
			INTO sIDMensaje
			FROM bdinteg:"informix".si_maecamp
			WHERE idcamp = pIDCamp 
			AND idjerarquia = pIDJerarquia
			AND empresa = TRIM(pEmpresa);
			
			--SE BORRAN LAS CAMPAÑAS 
			DELETE FROM bdinteg:"informix".si_maecamp
			WHERE idcamp = pIDCamp 
			AND idjerarquia = pIDJerarquia
			AND empresa = TRIM(pEmpresa);
			
			--SE BORRA EL MENSAJE
			DELETE FROM bdinteg:"informix".si_detcamp
			WHERE empresa = TRIM(pEmpresa)
			AND  idmensaje = sIDMensaje
			AND orden <> 0 ;
			
			RETURN cCodRet;
		END IF;
	END;
END PROCEDURE
DOCUMENT
'AUTOR : Obed Vega',
'DESCRIPCION: Elimina una campaña existente',
'EJECUTADO O LLAMADO POR: Aplicativo it004006',
'BD: BDINTEG',
'FECHA : 13 de Septiembre 2013',
'VERSION: 20130913';

CREATE PROCEDURE "informix".sp_modificaguardacampania(cEmpresa CHAR(3), cSucursal CHAR(5), cZona CHAR(5), cSistema CHAR(2), cProducto CHAR(5), sTransaccion SMALLINT, cEstatus CHAR(1), sNivel SMALLINT, sActiva SMALLINT, sAct_Zona SMALLINT, sCombinable SMALLINT, sCampania SMALLINT, sJerarquia SMALLINT, cMensaje1 CHAR(55), cMensaje2 CHAR(55), cMensaje3 CHAR(55), cMensaje4 CHAR(55), cMensaje5 CHAR(55), cMensaje6 CHAR(55),cNomCamp CHAR(40), cCampNueva CHAR(1)) --DSB 20-08-2013 SE AGREGA EL PARAMETRO CNOMCAMP Y CCAMPNUEVA
--------------------------------------------------------------------
--DOCUMENTACIÓN
--Guarda o modifica la información de la campaña
--Realizó: Nancy Sevilla Camacho
 
--MODIFICACION: 
--DSB 20-08-2013
--DESCRIPCION: Se modifica para que inserte nombre de campaña y cree un solo mensaje por campaña
--MODIFICO: Obed Vega
--FECHA MODIFICACION: 20/Agosto/2013
--------------------------------------------------------------------

--DATOS A REGRESAR---
RETURNING
CHAR(5);   -- Código_retorno

--DEFINICION DE VARIABLES--
DEFINE iSqlErr      INTEGER;
DEFINE cCodRet      CHAR(5);

---------------------------	
DEFINE sIdMensajeMax SMALLINT;
DEFINE sIdMensaje SMALLINT;

--INICIALIZACION DE VARIABLES--
LET iSqlErr       = 0;
LET cCodRet       = '00000';
LET sIdMensajeMax = 0;
LET sIdMensaje    = 0;

	--SET DEBUG FILE TO "/respaldosbd/obed/sp_modificaguardacampania.out";
	--TRACE ON;
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	-- INICIO DEL PROCEDIMIENTO
	BEGIN
	-- MANEJADOR DE ERRORES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;	
		
		IF NVL(cEmpresa, '') = '' OR NVL(sCampania, 0) = '' OR NVL(sJerarquia, 0) = '' THEN
		
			LET cCodRet = '00002';
			RETURN cCodRet;	
		
		ELSE
				
			IF TRIM(cCampNueva) <> "1" THEN --SI NO ES UNA NUEVA CAMPAÑA
			
				IF TRIM(cProducto) = "0" THEN
					LET cProducto = "T";
				END IF;
	
				--ACTUALIZA EL REGISTRO EN LA TABLA SI_MAECAMP 
				UPDATE bdinteg:"informix".si_maecamp 
				   SET num_producto = TRIM(cProducto), 
					   sistema = cSistema, 
					   estatus = cEstatus, 
					   idnivel = sNivel,					   
					   activa = sActiva, 
					   combinable = sCombinable,
					   tran_nro = sTransaccion,
					   nombre = cNomCamp
				 WHERE idcamp = sCampania
				   AND idJerarquia = sJerarquia
				   AND empresa = cEmpresa
				   AND sucursal IS NOT NULL;			
				
				SELECT FIRST 1 idmensaje
				  INTO sIdMensaje
				  FROM bdinteg:"informix".si_maecamp
				 WHERE idcamp = sCampania
				   AND idJerarquia = sJerarquia
				   AND empresa = cEmpresa
				   AND sucursal IS NOT NULL;
				   
				-- ACTUALIZA EL MENSAJE EN LA TABLA SI_DETCAMP PARA LA CAMPAÑA QUE SE MODIFICA
				IF NVL(sIdMensaje,0) <> '' Or sIdMensaje IS NOT NULL THEN
					DELETE FROM bdinteg:"informix".si_detcamp 
					WHERE empresa = cEmpresa 
					AND idmensaje = sIdMensaje
					AND orden IS NOT NULL;
									
					IF TRIM(NVL(cMensaje1,'')) <> '' OR TRIM(NVL(cMensaje2,'')) <> '' OR TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' 
					   OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje1, 1);	
					END IF;
					
					IF TRIM(NVL(cMensaje2,'')) <> '' OR TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' 
					   OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje2, 2);	
					END IF;
					
					IF TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' OR  TRIM(NVL(cMensaje5,'')) <> '' 
					   OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje3, 3);	
					END IF;
					
					IF TRIM(NVL(cMensaje4,'')) <> '' OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje4, 4);	
					END IF;
					
					IF TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje5, 5);	
					END IF;
					
					IF TRIM(NVL(cMensaje6,'')) <> '' THEN						   			   

						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensaje, cMensaje6, 6);							   		   
					END IF;					   
					RETURN cCodRet;
				ELSE
					--NO SE ENCONTRÓ EL IDMENSAJE PARA ESA CAMPAÑA Y JERARQUÍA
					LET cCodRet = '00001';
					RETURN cCodRet;
				END IF;
			
			ELSE
				SELECT FIRST 1 idmensaje
				  INTO sIdMensaje
				  FROM bdinteg:"informix".si_maecamp
				 WHERE idcamp = sCampania
				   AND idJerarquia = sJerarquia
				   AND empresa = cEmpresa
				   AND sucursal IS NOT NULL;
				
				IF NVL(sIdMensaje,0) <> '' Or sIdMensaje IS NOT NULL THEN
					-- INSERTA EN LA TABLA SI_MAECAMP LOS DATOS QUE CORRESPONDEN A LA CAMPAÑA CREADA
					INSERT INTO bdinteg:"informix".si_maecamp
							   (empresa, sucursal, num_producto, sistema, estatus, idcamp, idjerarquia, idnivel, idzona, activa, act_zona, combinable, idmensaje, tran_nro, nombre)
						 VALUES
							   (cEmpresa, cSucursal, cProducto, cSistema, cEstatus, sCampania, sJerarquia, sNivel, cZona, sActiva, sAct_Zona, sCombinable, sIdMensaje, sTransaccion, cNomCamp);
				
				ELSE
					-- SE OBTIENE EL VALOR MÁXIMO DEL ID MENSAJE
					SELECT MAX(idmensaje)
					  INTO sIdMensajeMax
					  FROM bdinteg:"informix".si_maecamp;
									
					IF NVL(sIdMensajeMax,0) = "" OR sIdMensajeMax IS NULL THEN
						LET sIdMensajeMax = 1;			
					ELSE
						LET sIdMensajeMax = sIdMensajeMax + 1;
					END IF;
				
					-- INSERTA EN LA TABLA SI_MAECAMP LOS DATOS QUE CORRESPONDEN A LA CAMPAÑA CREADA
					INSERT INTO bdinteg:"informix".si_maecamp
							   (empresa, sucursal, num_producto, sistema, estatus, idcamp, idjerarquia, idnivel, idzona, activa, act_zona, combinable, idmensaje, tran_nro, nombre)
						 VALUES
							   (cEmpresa, cSucursal, cProducto, cSistema, cEstatus, sCampania, sJerarquia, sNivel, cZona, sActiva, sAct_Zona, sCombinable, sIdMensajeMax, sTransaccion, cNomCamp);   
				
					-- INSERTA EN LA TABLA SI_DETCAMP LOS DATOS QUE CORRESPONDEN A LA CAMPAÑA CREADA
					IF TRIM(NVL(cMensaje1,'')) <> '' OR TRIM(NVL(cMensaje2,'')) <> '' OR TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' 
					   OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje1, 1);	
					END IF;
					
					IF TRIM(NVL(cMensaje2,'')) <> '' OR TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' 
					   OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje2, 2);	
					END IF;
					
					IF TRIM(NVL(cMensaje3,'')) <> '' OR  TRIM(NVL(cMensaje4,'')) <> '' OR  TRIM(NVL(cMensaje5,'')) <> '' 
					   OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje3, 3);	
					END IF;
					
					IF TRIM(NVL(cMensaje4,'')) <> '' OR  TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje4, 4);	
					END IF;
					
					IF TRIM(NVL(cMensaje5,'')) <> '' OR TRIM(NVL(cMensaje6,'')) <> '' THEN
						
						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje5, 5);	
					END IF;
					
					IF TRIM(NVL(cMensaje6,'')) <> '' THEN						   			   

						INSERT INTO bdinteg:"informix".si_detcamp
								   (empresa, idmensaje, mensaje, orden)
							 VALUES
								   (cEmpresa, sIdMensajeMax, cMensaje6, 6);							   		   
					END IF;					   
				END IF;
				RETURN cCodRet;		
			END IF;
		END IF;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtiene_campanias(pEmpresa CHAR(3))
RETURNING	CHAR(5) AS CodRet,
			SMALLINT AS IDCamp,
			SMALLINT AS IDJerarquia,
			CHAR(49) AS Nombre,
			CHAR(5) AS Producto,
			CHAR(40) AS NomProducto,
			CHAR(5) AS Sistema,
			CHAR(1) AS Estatus,
			SMALLINT AS Estado,
			SMALLINT AS Combinable,
			CHAR(55) AS Mensaje,
			SMALLINT AS IDMesnaje,
			CHAR(30) AS Sucursales,	
			CHAR(40) AS DesTran;
			

	-- DEFINICION DE VARIABLES
    DEFINE	cCodRet			CHAR(5);
	DEFINE	iSqlErr			INTEGER;
	DEFINE	sIDCamp			SMALLINT;
	DEFINE	sIDJerarquia	SMALLINT;
	DEFINE	sPrimeraVez		SMALLINT;
	DEFINE	sIDCamp2		SMALLINT;
	DEFINE	sIDJerarquia2	SMALLINT;
	DEFINE	cNombre			CHAR(40);
	DEFINE	cProducto		CHAR(5);
	DEFINE	cSistema		CHAR(5);
	DEFINE	sEstado			SMALLINT;
	DEFINE	sIDMensaje		SMALLINT;
	DEFINE	cIDSucursal		CHAR(20);
	DEFINE	cIDZona			CHAR(5);
	DEFINE	sIDCampRet		SMALLINT;
	DEFINE	sIDJerarquiaRet	SMALLINT;
	DEFINE	cNombreRet		CHAR(40);
	DEFINE	cProductoRet	CHAR(5);
	DEFINE	cSistemaRet		CHAR(5);
	DEFINE	sEstadoRet		SMALLINT;
	DEFINE	sIDMensajeRet	SMALLINT;
	DEFINE	cIDSucursalRet	CHAR(30);
	DEFINE	cMensaje		CHAR(55);
	DEFINE	cMensajeRet		CHAR(55);
	DEFINE	iContadorSuc	INTEGER;
	DEFINE	iContadorZona	INTEGER;
	DEFINE	sCombinable		SMALLINT;
	DEFINE	sCombinableRet	SMALLINT;
	DEFINE	cEstatus		CHAR(1);
	DEFINE	cEstatusRet		CHAR(1);
	DEFINE	cNomProductoRet	CHAR(40);
	DEFINE	sTranNum		SMALLINT;
	DEFINE	cDesTranRet		CHAR(49);	
		
	
	--INICIALIZACION DE VARIABLES--
    LET cCodRet			= "00000";
    LET iSqlErr			= 0;
	LET	sIDCamp			= 0;
	LET	sIDJerarquia	= 0;
	LET	sPrimeraVez		= 0;
	LET	sIDCamp2		= 0;
	LET	sIDJerarquia2	= 0;
	LET	cNombre			= "";
	LET	cProducto		= "";
	LET	cSistema		= "";
	LET	sEstado			= 0;
	LET	sIDMensaje		= 0;
	LET	cIDSucursal		= "";
	LET	cIDZona			= "";
	LET	sIDCampRet		= 0;
	LET	sIDJerarquiaRet	= 0;
	LET	cNombreRet		= "";
	LET	cProductoRet	= "";
	LET	cSistemaRet		= "";
	LET	sEstadoRet		= 0;
	LET	sIDMensajeRet	= 0;
	LET	cIDSucursalRet	= "";
	LET	cMensaje		= "";
	LET cMensajeRet		= "";
	LET	iContadorSuc	= 0;
	LET	iContadorZona	= 0;
	LET	sCombinable		= 0;
	LET	sCombinableRet	= 0;
	LET	cEstatus		= "";
	LET	cEstatusRet		= "";
	LET	cNomProductoRet	= "";
	LET	sTranNum		= 0;
	LET	cDesTranRet		= "";		
	
		
	--SET DEBUG FILE TO '/respaldosbd/obed/sp_campanias.out';
	--TRACE ON;
	
    BEGIN

        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
				RETURN cCodRet, 0, 0, "", "", "", "", "", 0, 0, "", 0, "", "";
            END IF;
        END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF LENGTH(TRIM(NVL(pEmpresa,""))) = 0 THEN
			--PROPORCIONAR EMPRESA
			LET cCodRet = "00001";
			RETURN cCodRet, sIDCampRet, sIDJerarquia, cNombreRet, cProductoRet, cNomProductoRet, cSistemaRet, cEstatusRet, sEstadoRet, sCombinableRet, cMensajeRet, sIDMensajeRet, cIDSucursalRet, cDesTranRet;
		ELSE
			FOREACH
				--SE OBTIENEN EL TOTAL DE CAMPÑAS
				SELECT DISTINCT idcamp, idjerarquia
				INTO sIDCamp, sIDJerarquia
				FROM bdinteg:"informix".si_maecamp
				WHERE empresa = TRIM(pEmpresa)
				
				LET sPrimeraVez = 1;
				LET iContadorSuc = 1;
				FOREACH
					--SE OBTIENEN LAS PRIMERAS 5 SUCURSALES
					SELECT  
						idcamp, 
						idjerarquia, 
						nombre, 
						DECODE(num_producto, 'T','TODOS',num_producto), 
						DECODE(sistema,'T','TODOS',sistema), 
						estatus,
						activa, 
						combinable,
						idmensaje,
						DECODE(sucursal,'T','Todas las Sucursales',sucursal),
						idzona,
						tran_nro						
					INTO sIDCamp2, sIDJerarquia2,cNombre, cProducto, cSistema, cEstatus, sEstado, sCombinable, sIDMensaje, cIDSucursal, cIDZona, sTranNum 
					FROM bdinteg:"informix".si_maecamp
					WHERE empresa = TRIM(pEmpresa)
					AND idcamp = sIDCamp
					AND idjerarquia = sIDJerarquia
					
					IF sPrimeraVez = 1 THEN
						--SE GUARDA EL IDCAMPAÑA, IDJERARQUIA, NOMBRE CAMAPAÑA, PRODUCTO, SISTEMA, STATUS, SI ESTA ACTIVA, SI ES COMBINABLE Y EL IDMENSAJE LA CAMAPAÑA PARA DESPUES RETORNARLO
						LET sIDCampRet = sIDCamp2;
						LET sIDJerarquiaRet = sIDJerarquia2;
						LET cNombreRet = NVL(cNombre,"");
						LET cProductoRet = cProducto;
						LET cSistemaRet = cSistema;
						LET	cEstatusRet = NVL(cEstatus,"");
						LET sEstadoRet = sEstado;
						LET	sCombinableRet = sCombinable;
						LET sIDMensajeRet = sIDMensaje;
						
						
						--SE OBTIENE LA DESCRIPCION DEL PRODUCTO
						IF TRIM(cSistema)= 'SD' THEN
							IF TRIM(cProducto)<> 'TODOS' THEN
								SELECT nombre_prod
								INTO cNomProductoRet
								FROM bdicred:"informix".sd_definicion
								WHERE TRIM(num_producto) =  TRIM(cProducto)
								AND empresa = pEmpresa;
							ELSE	
								LET cNomProductoRet = "TODOS";
							END IF;
						ELIF TRIM(cSistema)= 'SC' THEN
							IF TRIM(cProducto)<> 'TODOS' THEN
								SELECT nombre
								INTO cNomProductoRet
								FROM bdicheq:"informix".sc_producto
								WHERE TRIM(producto) =  TRIM(cProducto)
								AND empresa = pEmpresa;
							ELSE	
								LET cNomProductoRet = "TODOS";
							END IF;
						END IF;
						
						--SE OBTIENE LA DESCRIPCIÓN DE LA TRANSACCION
						IF NVL(sTranNum,0) <> 0 THEN
							SELECT descripcion
							INTO cDesTranRet
							FROM bdinteg:"informix".itran
							WHERE numero =  sTranNum
							AND empresa = pEmpresa;
						ELSE	
							LET cDesTranRet = "TODOS";
						END IF;
						
						--SE VALIDA SI LA CAMPAÑA ES POR ZONA
						IF NVL(cIDZona,"")<> "" THEN 
							LET iContadorZona = 1;
							FOREACH
								SELECT 	sucursal 
								INTO cIDSucursal
								FROM bdinteg:"informix".si_sucursales 
								WHERE plaza = TRIM(cIDZona) AND tpo_sucursal = "S"
								
								IF sPrimeraVez = 1 THEN
									LET cIDSucursalRet = TRIM(cIDSucursal);
									LET sPrimeraVez = 0;
								ELSE
									LET cIDSucursalRet = TRIM(cIDSucursalRet) || "," || TRIM(cIDSucursal);
								END IF;
								
								IF iContadorZona = 5 THEN
									EXIT FOREACH;
								ELSE
									LET iContadorZona = iContadorZona + 1;
								END IF;
							END FOREACH;
						ELSE
							LET cIDSucursalRet = TRIM(cIDSucursal);
						END IF;
						
						--SE TRAE EL MENSAJE QUE COTRRESPODE A LA CAMPAÑA
						SELECT FIRST 1 mensaje
						INTO cMensaje
						FROM bdinteg:"informix".si_detcamp
						WHERE idmensaje = sIDMensaje
						AND NVL(mensaje,"") <> "";
						
						IF NVL(cMensaje,"") <> "" THEN
							LET cMensajeRet = cMensaje;
						ELSE
							LET cMensajeRet = "";
						END IF;
						LET sPrimeraVez = 0;
					ELSE
						LET cIDSucursalRet = TRIM(cIDSucursalRet) || "," || TRIM(cIDSucursal);
					END IF;
					
					IF iContadorSuc = 5 THEN
						EXIT FOREACH;
					ELSE
						LET iContadorSuc = iContadorSuc + 1;
					END IF;
					
				END FOREACH;
					
				RETURN cCodRet, sIDCampRet, sIDJerarquia, cNombreRet, cProductoRet, cNomProductoRet, cSistemaRet, cEstatusRet, sEstadoRet, sCombinableRet, cMensajeRet, sIDMensajeRet, cIDSucursalRet, cDesTranRet WITH RESUME;	
			END FOREACH;
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				--NO EXISTEN CAMPAÑAS
				LET cCodRet = "00002";
				RETURN cCodRet, sIDCampRet, sIDJerarquia, cNombreRet, cProductoRet, cNomProductoRet, cSistemaRet, cEstatusRet, sEstadoRet, sCombinableRet, cMensajeRet, sIDMensajeRet, cIDSucursalRet, cDesTranRet;
			END IF
			
		END IF;
	END;
END PROCEDURE
DOCUMENT
'AUTOR : Obed Vega',
'DESCRIPCION: Obtiene las campañas existentes',
'EJECUTADO O LLAMADO POR: Aplicativo it004006',
'BD: BDINTEG',
'FECHA : 12 de Septiembre 2013',
'VERSION: 20130912';

CREATE PROCEDURE "informix".sp_obtiene_msj_ticket(pEmpresa CHAR(3), pIDMesaje SMALLINT)
RETURNING	CHAR(5) AS CodRet,
			CHAR(55) AS Ren,
			SMALLINT AS Orden;


	-- DEFINICION DE VARIABLES
    DEFINE	cCodRet			CHAR(5);
	DEFINE	iSqlErr			INTEGER;
	DEFINE	cMensaje		CHAR(55);
	DEFINE	sOrden			SMALLINT;
		
	--INICIALIZACION DE VARIABLES--
    LET cCodRet			= "00000";
    LET iSqlErr			= 0;
	LET	cMensaje		= "";
	LET	sOrden			= 0;
		
	--SET DEBUG FILE TO '/respaldosbd/obed/sp_obtiene_msj_ticket.out';
	--TRACE ON;
	
    BEGIN

        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
				RETURN cCodRet,"",0;
            END IF;
        END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF LENGTH(TRIM(NVL(pEmpresa,""))) = 0 OR NVL(pIDMesaje, 0) = 0  THEN
			--PARAMETROS INCORRECTOS
			LET cCodRet = "00001";
			RETURN cCodRet, cMensaje, sOrden;
		ELSE
			--SE OBTIENE MENSAJE
			FOREACH
				SELECT mensaje, orden
				INTO cMensaje, sOrden
				FROM bdinteg:"informix".si_detcamp
				WHERE empresa = TRIM(pEmpresa)
				AND idmensaje = pIDMesaje
				ORDER BY orden ASC
				
				RETURN cCodRet, cMensaje, sOrden WITH RESUME;				
			END FOREACH;
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				--NO SE ENCONTRO EL MENSAJE
				LET cCodRet = "00002";
				RETURN cCodRet, cMensaje, sOrden;
			END IF
		END IF;
	END;
END PROCEDURE
DOCUMENT
'AUTOR : Obed Vega',
'DESCRIPCION: Consulta el mensaje de una campaña',
'EJECUTADO O LLAMADO POR: Aplicativo it004006',
'BD: BDINTEG',
'FECHA : 25 de Septiembre 2013',
'VERSION: 20130925';

CREATE PROCEDURE  "informix".sp_bloqueardesbloquearserviciobpi(pEmpresa CHAR(3), pNumCte CHAR(20), pStatus CHAR(2), pSucursal CHAR(4), pNumEmp CHAR(9), pIP  CHAR(15))

    --DATOS A REGRESAR---
    RETURNING
    CHAR(5),   -- Codigo de Retorno
    CHAR(250); -- Descrición Validación
	
    ------------------------------------------------------------------------------------------------------------------------------------
	-- Modifica: Jessica Gutíerrez
    --Actividad: Para la cancelacion, se modifica la consulta para que no consulte las solicitudes que ya estan canceladas.
    -- Fecha: 7-11-2013
  	------------------------------------------------------------------------------------------------------------------------------------
	
	
    --DEFINICION DE VARIABLES--
    DEFINE sql_err      INT;
    DEFINE vCodRet      CHAR(5);
    DEFINE vMensValid   CHAR(250);
    DEFINE vIdStatus    CHAR(4);
    DEFINE vServicio smallint;
    DEFINE vSolicitud CHAR(10);

    DEFINE vIdStaSol CHAR(4);
	DEFINE cSolicitud CHAR(10);
	DEFINE vToken CHAR(10);
	DEFINE vIdStaToken CHAR(3);
	DEFINE vSucRegistra CHAR(4);
	DEFINE vFolioToken CHAR(25);
	DEFINE vF_Status DATE;
	DEFINE vF_Registro DATE;



    --INICIALIZACION DE VARIABLES--
    LET sql_err = 0;
    LET vCodRet =   '000';
    LET vMensValid = '';
    LET vIdStatus = '';
    LET vServicio = 0;
    LET VSolicitud = '';

    LET vIdStaSol = '';
	LET vToken = '';
	LET vIdStaToken = '';
	LET vSucRegistra = '';
	LET vFolioToken = '';
	LET vF_Status = '01-01-1900';
	LET vF_Registro  = '01-01-1900';


   --SET DEBUG FILE TO "/home/informix/ivonne/sp_BloquearDebloquearServicioBPI.out";
   --TRACE ON;

BEGIN

    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET vCodRet = sql_err;
            RETURN vCodRet, vMensValid;
        END IF;
    END EXCEPTION;


    IF vCodRet = '000'  THEN

        SELECT id_status,servicio INTO vIdStatus,vServicio FROM bdinteg:si_bpiusuarios WHERE  empresa = pEmpresa AND numcte = pNumCte;

        UPDATE bdinteg:si_bpiusuarios SET id_status = pStatus, f_status = CURRENT WHERE numcte = pNumCte;

		INSERT INTO bdinteg:si_cambiostcte (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)
		VALUES (pNumCte, vIdStatus, pStatus, pIP, CURRENT, pSucursal, pNumEmp);

        IF pStatus = '99' AND  vServicio = 2 THEN

            FOREACH
                SELECT solicitud, id_status, ns_token   INTO vSolicitud, vIdStaSol, vToken
                FROM bdibpi:bpi_tokensolicitud  WHERE empresa = TRIM(pEmpresa)  AND numcte = TRIM(pNumCte) AND id_status not in (199)
				
                EXECUTE PROCEDURE bdibpi:sp_cancelartoken(pEmpresa, pNumCte, vToken, pNumEmp, vIdStaSol, '199', '01') INTO vCodRet;
				
                EXECUTE PROCEDURE bdibpi:sp_set_solicitudstatus_admtoken(vSolicitud, pNumCte, pNumEmp, vIdStaSol, '199') INTO vCodRet;

            END FOREACH;

                

        END IF;

        SELECT mensaje INTO vMensValid FROM bdinteg:si_bpicatmensajes  WHERE proceso = '2'
        AND operacion = '2'
        AND status_servicio = pStatus;


     ELSE
            LET vCodRet =   '001';
            LET vMensValid = 'No se pudo grabar el registro, favor de intentar más tarde';
     END IF;

    RETURN vCodRet, vMensValid;

END
END PROCEDURE
DOCUMENT
'Bloquea y desbloquea usuarios para la Banca por Internet y guarda registros en la si_cambiostct los cambios de status',
'Autor :' ,
'Modificó : Dulce Ramírez',
'FECHA : 25/Mayo/2009',
'Ver.  : 1.0',
'BD    : bdinteg',
'VER   : 1.0',
'Modificó: Berenice Noriega',
'Para actualizar la bdibpi:tkn_envios y bpi_tokensolicitud',
'Fecha: 13/Febrero/2012';

create procedure "informix".direcciones_ctemoral( pempresa char(3),
                                                  pfuncion char(1),
                                                  pnumcte char(20),
                                                  psecuencia smallint,
                                                  ptipodir char(1),
                                                  pcalle char(40),
                                                  pcolonia char(60),
                                                  pmunicipio char(5),
                                                  pentre_calles char(40),
                                                  ppais char(3),
                                                  pentidad char(2),
                                                  plocalidad char(3),
                                                  pcodpostal char(5),
                                                  ptipotel1 char(1),
                                                  ptelefono1 char(13),
                                                  ptipotel2 char(1),
                                                  ptelefono2 char(13),
                                                  ptipotel3 char(1),
                                                  ptelefono3 char(13),
                                                  pextension char(5),
                                                  pestado_inegi char(2),
                                                  pmunicipio_inegi char(3),
                                                  plocalidad_inegi char(4),
                                                  pnociudad smallint,
                                                  pnoext char(10),
                                                  pnoint char(10),
                                                  pdepto char(6),
                                                  pnocalle integer,
                                                  pnocolonia integer,
                                                  ppuntocar char(1),
                                                  punihabi char(1),
                                                  pmanz smallint,
                                                  ppotros smallint,
                                                  pandador smallint,
                                                  petapa smallint,
                                                  plote smallint,
                                                  pedif smallint,
                                                  pentrada smallint,
                                                  pobserva char(80),
                                                  puser_insert char(8),
                                                  pfecha_insert date,
                                                  pSucursal CHAR(4) )
 returning char(5);

    define v_codret char(5);
    define v_rowid integer;
    define v_tipodir char(1);
    define v_calle char(40);
    define v_colonia char(60);
    define v_delegacion char(20);
    define v_entre_calles char(40);
    define v_pais char(3);
    define v_entidad char(2);
    define v_localidad char(3);
    define v_codpostal char(5);
    define v_telefono1 char(20);
    define v_telefono2 char(20);
    define v_estado_inegi char(2);
    define v_municipio_inegi char(3);
    define v_localidad_inegi char(4);
    define v_fax char(20);
    define v_nombre char(40);
    define v_longitud, v_longcte, v_secuencia smallint;
    define v_numcte char(20);
    define v_existe char(1);
    define v_sqlerr, v_isamerr integer;
    DEFINE v_CodRetTel CHAR(5);

    --- SET DEBUG FILE TO "/tmp/direcciones_ctemoral.out";
    --- TRACE ON;

    begin
    
    on exception set v_sqlerr, v_isamerr
        if v_sqlerr != 0 then
            let v_codret=v_sqlerr;
            return v_codret;
        end if;
    end exception;
	
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    let v_codret = "000";
    LET v_CodRetTel = '';

    select numcte 
      into v_numcte 
      from si_cliente
     where numcte = pnumcte;

    if v_numcte is null then
        let v_codret = "104";
        return v_codret;
    end if

    if pfuncion = "C" then
        delete from si_direcciones
         where numcte = pnumcte 
           and secuencia = psecuencia;
           
        delete from si_direcciones_actual
         where numcte = pnumcte 
           and secuencia = psecuencia;
           
        let pfuncion = "A";
    end if

    if pfuncion = "A" then

        /* #########################
        select nombre 
          into v_nombre
          from si_paises
         where pais = ppais;
         
        if v_nombre is null then
            let v_codret="121";
            return v_codret;
        end if;

        select nombre 
          into v_nombre
          from si_estados
         where pais=ppais 
           and estado=pentidad;

        if v_nombre is null then
            let v_codret="122";
            return v_codret;
        end if;

        select nombre 
          into v_nombre
          from si_ciudades
         where pais=ppais 
           and estado=pentidad 
           and ciudad=plocalidad;
           
        if v_nombre is null then
            let v_codret="123";
            return v_codret;
        end if;
        ######################### */

        select max(secuencia) 
          into psecuencia
          from si_direcciones_actual
         where numcte = pnumcte;

        if psecuencia is null then
            let psecuencia = 1;
        else
            let psecuencia = psecuencia + 1;
        end if;
    
        insert into si_direcciones
        ( numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
          pais,estado,ciudad,municipio,cod_postal,apart_postal,
          /* tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,telefono3,extension, */
          estado_inegi,municipio_inegi,localidad_inegi,
          numerociudad,numeroextcalle,numerointcalle,departamento,
          numerocalle,numerocolonia,puntocardinal,unidadhabitac,
          manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
          user_insert,fecha_insert )
        values
        ( pnumcte, psecuencia, ptipodir, pcalle, pcolonia, pentre_calles,
          ppais,pentidad,plocalidad, pmunicipio, pcodpostal,"",
          /* ptipotel1,ptelefono1,ptipotel2,ptelefono2,ptipotel3,ptelefono3,pextension, */
          pestado_inegi,pmunicipio_inegi,plocalidad_inegi,
          pnociudad,pnoext,pnoint,pdepto,
          pnocalle,pnocolonia,ppuntocar,punihabi,
          pmanz,ppotros,pandador,petapa,plote,pedif,pentrada,pobserva,
          puser_insert,pfecha_insert );
          
        IF ( ( ptipotel1 is not null AND ptipotel1 <> '' ) AND ( ptelefono1 is not null AND ptelefono1 <> '' ) ) THEN
            CALL sp_registra_telefonos(pempresa, pnumcte, ptelefono1, 1, '', 0, 7, puser_insert)
            RETURNING v_CodRetTel;
        END IF;
        
        IF ( ( ptipotel2 is not null AND ptipotel2 <> '' ) AND ( ptelefono2 is not null AND ptelefono2 <> '' ) ) THEN
            CALL sp_registra_telefonos(pempresa, pnumcte, ptelefono2, 2, '', 0, 7, puser_insert)
            RETURNING v_CodRetTel;
        END IF;
        
        IF ( ( ptipotel3 is not null AND ptipotel3 <> '' ) AND ( ptelefono3 is not null AND ptelefono3 <> '' ) ) THEN
            CALL sp_registra_telefonos(pempresa, pnumcte, ptelefono3, 3, pextension, 0, 7, puser_insert)
            RETURNING v_CodRetTel;
        END IF;
          
        return v_codret;
        
    end if;
    
    end;
    
end procedure

DOCUMENT
"Alta de direcciones del cliente",
"Autor : Procesamiento Interactivo S.A. de C.V.",
"MODIFICO : Manuel Hernandez",
"FECHA : 12/Septiembre/2006",
"Ver.  : 1.1",
"BD    : bdinteg",
"VER   : 1.1";

CREATE PROCEDURE "informix".consnombrenumctepm(pEmpresa CHAR(3),
						pNombre1 CHAR(26),
						pNombre2 CHAR(26),
                        pApellPaterno CHAR(26),
                        pApellMaterno CHAR(26),
						pFechaNac DATE,
						pRfc CHAR(13),
						pRazonSocial CHAR(60),
                        pSecuencia SMALLINT)

RETURNING 
CHAR(5)  AS COD_RET,
CHAR(60) AS NOMBRE_COMPLETO,
CHAR(20) AS NUM_CTE,
CHAR(13) AS RFC;

--DECLARACIONES
DEFINE ISqlErr 				INTEGER;
DEFINE cRfc 				CHAR(13);
DEFINE cNombreCompleto 		CHAR(63);
DEFINE cNombre1             CHAR(26);
DEFINE cNombre2             CHAR(26); 
DEFINE cApellPaterno        CHAR(26);        
DEFINE cApellMaterno        CHAR(26);
DEFINE cNumcte 				CHAR(20);
DEFINE cCodRet 				CHAR(5);
DEFINE cRazonSocial 		CHAR(60);
DEFINE cRfcAlterno          CHAR(13);

--INICIALIZACIONES
LET ISqlErr                 = 0;
LET cCodRet                 = '00000';
LET cNombreCompleto         = '';
LET cNombre1                = '';
LET cNombre2                = '';
LET cApellPaterno           = '';
LET cApellMaterno           = '';
LET cNumcte                 = '0000000000';
LET cRfc                    = '';
LET cRazonSocial            = '';
LET cRfcAlterno             = '';

BEGIN
  ON EXCEPTION SET ISqlErr
     IF ISqlErr <> 0 THEN
   	     LET cCodRet = ISqlErr;
	     RETURN cCodRet, cNombreCompleto, cNumcte, cRfc;
     END IF;
   END EXCEPTION;

   SET ISOLATION TO DIRTY READ;
   SET LOCK MODE TO WAIT 3;   

   --SET DEBUG FILE TO '/home/tmp/MireyaR/sp_consultarctemoral_02.out';
   --TRACE ON;
   
IF NVL(pEmpresa,'') = ''  THEN
	LET cCodRet = '00001';
	LET cNombreCompleto = 'parametros incompletos';
	RETURN cCodRet, cNombreCompleto, cNumcte, cRfc;
END IF;


IF pRazonSocial IS NOT NULL AND pRazonSocial !="" THEN
    FOREACH
        SELECT skip pSecuencia LIMIT 21
             razon_social,numcte,rfc
 	    INTO cRazonSocial,cNumcte,cRfc
        FROM "informix".si_cliente
        WHERE razon_social = pRazonSocial
           AND apell_paterno = ''
	       AND apell_materno = ''
        ORDER BY numcte

        LET cNombreCompleto = cRazonSocial;
        RETURN cCodRet,cNombreCompleto,cNumcte,cRfc WITH RESUME;
    END FOREACH;
ELSE
    --REALIZA LA CONSULTA DE NOMBRE Y RFC DEL CLIENTE POR RFC
    IF pRfc IS NOT NULL AND pRfc != "" THEN
        FOREACH
            SELECT skip pSecuencia LIMIT 21 
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc, rfc_alterno
	        INTO cNombre1,cNombre2,cApellPaterno,cApellMaterno,cNumcte,cRfc, cRfcAlterno
      	    FROM "informix".si_ctepf pf, "informix".si_cliente cl
      	    WHERE rfc = pRfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte

	        LET cNombreCompleto = TRIM(cApellPaterno) || " " || TRIM(cApellMaterno)
             || " " || TRIM(cNombre1) || " " || TRIM(cNombre2);
			 
			IF cRfcAlterno IS NOT NULL AND cRfcAlterno <> "" THEN
               LET cRfc = cRfcAlterno;
            END IF;
			
	        RETURN cCodRet,cNombreCompleto,cNumcte,cRfc WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS
	IF NVL(pApellPaterno,'') = ''  THEN
		LET cCodRet = "00002";
		LET cNombreCompleto = 'Debe capturar al menos uno de los dos apellidos';
		RETURN cCodRet, cNombreCompleto, cNumcte, cRfc;

	ELIF NVL(pNombre1,'') = '' THEN
		LET cCodRet = "00003";
		LET cNombreCompleto = 'Debe capturar al menos uno de los dos nombres';
		RETURN cCodRet, cNombreCompleto, cNumcte,cRfc;
	ELSE
        IF ( pApellPaterno IS NULL OR pApellPaterno = "" ) THEN
           LET pApellPaterno = "";
        ELSE
            LET pApellPaterno = TRIM(pApellPaterno)||"*";

        END IF;  

        IF ( pApellMaterno IS NULL OR pApellMaterno = "" ) THEN
           LET pApellMaterno = "";
        ELSE
           LET pApellMaterno = TRIM(pApellMaterno)||"*";

        END IF;  

        IF ( pNombre1 IS NULL OR pNombre1 = "" ) THEN
           LET pNombre1 = "";
        ELSE
           LET pNombre1 = TRIM(pNombre1)||"*";
        END IF;  

        IF ( pNombre2 IS NULL OR pNombre2 = "" ) THEN
           LET pNombre2 = "";
        ELSE
           LET pNombre2 = TRIM(pNombre2)||"*";
        END IF;  

        --SE REALIZA UNA CONSULTA DEL NOMBRE Y RFC DEL CLIENTE POR FECHA DE NACIMIENTO
		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia LIMIT 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc, rfc_alterno
				INTO cNombre1,cNombre2,cApellPaterno,cApellMaterno,cNumcte,cRfc, cRfcAlterno
				FROM "informix".si_ctepf pf, "informix".si_cliente cl
				WHERE cl.apell_paterno matches pApellPaterno
				AND cl.apell_materno matches pApellMaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2


				LET cNombreCompleto = TRIM(cApellPaterno) || " " || TRIM(cApellMaterno)
						|| " " || TRIM(cNombre1) || " " || TRIM(cNombre2);
						
				IF cRfcAlterno IS NOT NULL AND cRfcAlterno <> "" THEN
                   LET cRfc = cRfcAlterno;
                END IF;
				
				RETURN cCodRet,cNombreCompleto,cNumcte,cRfc WITH RESUME;
			END FOREACH;

		ELSE
            --SE REALIZA LA CONSULTA DEL NOMBRE Y RFC
			FOREACH
				SELECT skip pSecuencia LIMIT 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc, rfc_alterno
				INTO cNombre1,cNombre2,cApellPaterno,cApellMaterno,cNumcte,cRfc, cRfcAlterno
				FROM "informix".si_cliente
				WHERE apell_paterno matches pApellPaterno
				AND apell_materno matches pApellMaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2


				LET cNombreCompleto = TRIM(cApellPaterno) || " " || TRIM(UPPER(cApellMaterno))
						|| " " || TRIM(cNombre1) || " " || TRIM(cNombre2);
						
				IF cRfcAlterno IS NOT NULL AND cRfcAlterno <> "" THEN
                   LET cRfc = cRfcAlterno;
                END IF;		
						
				RETURN cCodRet,cNombreCompleto,cNumcte,cRfc WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Consulta clientes por nombre(s) y apellido(s) y',
'por fecha de nacimiento si asi se requiere',
'AUTOR : Mireya Reyes',
'FECHA DE CREACION: 02/08/2013',
'VERSION: 20130802.0938',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_consultaactividadsocial(pEmpresa CHAR(3), pCodigo CHAR(3), pOrder SMALLINT)

	RETURNING

		CHAR(6)	AS CodRet,
		CHAR(80) AS MensajeErr,
		CHAR(3)	AS Actividadgiro,
		CHAR(40) AS DescActivgiro;
--------------------------DECLARACION DE VARIABLES
		DEFINE iSqlErr			INTEGER;
		DEFINE iSam_Err   		INTEGER;
		DEFINE cError_Info 		CHAR(200);
		DEFINE cCodRet         	CHAR(6);
		DEFINE cMensajeErr		CHAR(80);
		DEFINE cCodActiv		CHAR(3);
		DEFINE cDescActiv		CHAR(30);
		DEFINE sBandera			SMALLINT;
--------------------------INICIALIZACION DE VARIABLES
		LET iSqlErr				= 0;
		LET iSam_Err			= 0;
		LET cError_Info			= '';
		LET cCodRet         	= '000000';
		LET cMensajeErr			= 'PROCESO EXITOSO';
		LET cCodActiv			= '';
		LET cDescActiv			= '';
		LET sBandera			= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iSam_Err, cError_Info
		IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cMensajeErr = 'ERROR EN EL PROCEDIMIENTO PRINCIPAL';
			RETURN 	TRIM(NVL(cCodRet,'')),TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,''));

		END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

-------------SET DEBUG FILE TO '/dbexportb/Hugo/sp_consultaactividadsocial.out';
-------------TRACE ON;
		IF NVL(pEmpresa, '') = '' THEN  ----NO SE RECIBIO PARAMETRO DE EMPRESA
			LET cCodRet		= '000001';
			LET cMensajeErr	= 'ERROR EN EL PARAMETRO DE EMPRESA';

			RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,''));

		END IF

		IF  NVL(pCodigo, '') = '' THEN  ---CONSULTA GENERAL, REGRESA TODOS LOS REGISTROS

			IF pOrder = 0 THEN	--MUESTRA LOS REGISTROS ORDENADOS POR EL CODIGO

				FOREACH

					SELECT codigo, descripcion
					INTO cCodActiv, cDescActiv
					FROM "informix".si_actividadsocial
					WHERE empresa = pEmpresa
					ORDER BY codigo

					RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,'')) WITH RESUME;

				END FOREACH;

			ELIF pOrder = 1 THEN	--MUESTRA LOS REGISTROS ORDENADOS POR LA DESCRIPCION

				FOREACH

					SELECT codigo, descripcion
					INTO cCodActiv, cDescActiv
					FROM "informix".si_actividadsocial
					WHERE empresa = pEmpresa
					ORDER BY descripcion

					RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,'')) WITH RESUME;

				END FOREACH;

			ELSE
				LET cCodRet		= '000002';
				LET cMensajeErr    = 'ERROR EN EL PARAMETRO ORDENAR';

				RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,''));

			END IF

			IF DBINFO("sqlca.sqlerrd2") = 0 THEN	--NO EXISTEN DATOS EN LA TABLA
				LET cCodRet		= '000003';
				LET cMensajeErr    = 'ERROR NO HAY DATOS EN LA TABLA';

				RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,''));

			END IF

		ELSE  	 --CONSULTA CON UN CODIGO EN ESPECIFICO

			SELECT codigo, descripcion
			INTO cCodActiv, cDescActiv
			FROM "informix".si_actividadsocial
			WHERE empresa = pEmpresa
			AND codigo =  pCodigo;

			IF DBINFO("sqlca.sqlerrd2") = 0 THEN	 --NO HAY REGISTROS EN LA TABLA
				LET cCodRet		= '000004';
				LET cMensajeErr    = 'ERROR NO HAY REGISTROS EN LA TABLA';

			END IF

			RETURN TRIM(NVL(cCodRet,'')), TRIM(NVL(cMensajeErr,'')), TRIM(NVL(cCodActiv,'')), TRIM(NVL(cDescActiv,''));

		END IF

	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Consulta catalogo consultaactividadsocial',
'Modificó: Hugo Vazquez',
'FECHA: 16 Julio 2013',
'VERSION: 20130716.0120',
