let v_pais = "000";
let v_secuencia = 0;
let v_secuencia2 = 0;
let v_ciudadcoppel = 0;
let v_municipio = "000";
let v_sqlerr = 0;
let v_isamerr = 0;
let v_codret = "000";
let v_cambio = 0;
let v_teltrabajo = "";
let v_extension = "";
--DSB 12/04/2011
