            select secuencia
            into v_secuencia2
            from bdinteg:si_direcciones_actual
            where numcte = pnumcte and tipo_dir = 1;

            let v_cambio = 0;

            select 1 as sicambio
            into v_cambio 
            --from bdinteg:si_direcciones
            from bdinteg:si_direcciones_actual
            where numcte = pnumcte and secuencia = v_secuencia2 and ( trim(telefono3) != trim(v_teltrabajo) or trim(extension) != trim(v_extension) );

            if v_cambio = 1 then            

                if v_secuencia is null then
                    let v_secuencia = 1;
                else
                    let v_secuencia = v_secuencia + 1;
                end if;

                insert into bdinteg:si_direcciones(numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
                    pais,estado,ciudad,municipio,cod_postal,apart_postal,
                    tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
                    telefono3,extension,estado_inegi,municipio_inegi,localidad_inegi,
                    numerociudad,numeroextcalle,numerointcalle,departamento,
                    numerocalle,numerocolonia,puntocardinal,unidadhabitac,
                    manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
                    user_insert,fecha_insert)                
                select numcte,v_secuencia,tipo_dir,calle,colonia,entre_calles,
                    pais,estado,ciudad,municipio,cod_postal,apart_postal,
                    tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
                    v_teltrabajo,v_extension,estado_inegi,municipio_inegi,localidad_inegi,
                    numerociudad,numeroextcalle,numerointcalle,departamento,
                    numerocalle,numerocolonia,puntocardinal,unidadhabitac,
                    manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
                    puser_insert,current 
                from bdinteg:si_direcciones where numcte = pnumcte and secuencia = v_secuencia2 and tipo_dir = 1;
-- DSB 11/04/2011
-- Se comenta código debido a que no se insertará el nuevo domicilio en la tabla
-- cb_cambiosdomicilio, en lugar de ésto se mandará llamar el sp_registramodifdomicilio
-- que insertará en la tabla si_bitacora_cambiosdom						
--SE GRABA LA MISMA INFORMACION EN LA NUEVA TABLA CB_CAMBIOSDOMICILIO
--                insert into bdicobranza:cb_cambiosdomicilio(numcte,secuencia,tipo_dir,calle,colonia,entre_calles,
--                    pais,estado,ciudad,municipio,cod_postal,apart_postal,
--                    tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
--                    telefono3,extension,estado_inegi,municipio_inegi,localidad_inegi,
--                    numerociudad,numeroextcalle,numerointcalle,departamento,
--                    numerocalle,numerocolonia,puntocardinal,unidadhabitac,
--                    manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
--                   user_insert,fecha_insert,tienda,empleado)                
--                select numcte,v_secuencia,tipo_dir,calle,colonia,entre_calles,
--                    pais,estado,ciudad,municipio,cod_postal,apart_postal,
--                    tipo_telef1,telefono1,tipo_telef2,telefono2,tipo_telef3,
--                    v_teltrabajo,v_extension,estado_inegi,municipio_inegi,localidad_inegi,
--                    numerociudad,numeroextcalle,numerointcalle,departamento,
--                    numerocalle,numerocolonia,puntocardinal,unidadhabitac,
--                    manzana,otros,andador,etapa,lote,edificio,entrada,observaciones,
--                    puser_insert,current,pTienda,pEmpleado 
--                from bdinteg:si_direcciones where numcte = pnumcte and secuencia = v_secuencia2 and tipo_dir = 1;
														
			EXECUTE PROCEDURE "informix".sp_registramodifdomicilio(pnumcte, siOrigen, pModo, v_secuencia, pTienda, 
														           current, puser_insert, pEmpleado)
						 INTO v_codret;														
														
            end if;*/
--AQUI SE INSERTA EL NUEVO REGISTRO DE SI_INGRESOS POR EL CAMPO LUGAR DE TRABAJO (NOMBRE_EMPRESA) SI ES QUE HUBO ALGUN CAMBIO
            select max(sec_ingreso)
            into v_secuencia
            from bdinteg:si_ingresos
            where numcte = pnumcte and empresa = pempresa;

            if v_secuencia is null then
                let v_secuencia = 1;
            else
                let v_secuencia = v_secuencia + 1;
            end if;

            let v_cambio = 0;

            select 1 as sicambio
            into v_cambio 
            from bdinteg:si_ingresos 
            where numcte = pnumcte and empresa = pempresa and sec_ingreso = v_secuencia - 1 and trim(nombre_empresa) != trim(plugartrabajo);

            if v_cambio = 1 then               

                insert into bdinteg:si_ingresos(empresa,numcte,sec_ingreso,tipo_ingreso,nombre_empresa,puesto,puesto_esp,
                    antiguedad,nombre_depto,jefe_inmediato,ingreso_mensual,user_insert,fecha_insert)
                select empresa,numcte,v_secuencia,tipo_ingreso,plugartrabajo,puesto,puesto_esp,
                    antiguedad,nombre_depto,jefe_inmediato,ingreso_mensual,puser_insert,current 
                    from bdinteg:si_ingresos where numcte = pnumcte and empresa = pempresa and sec_ingreso = v_secuencia - 1;

            end if;
        end if;	

      if v_codret = "00000" then
            COMMIT WORK;
      else
            ROLLBACK WORK;
      end if;

      return v_codret;
end;
end procedure;

CREATE PROCEDURE "informix".sp_consultactesitesp_pba( pEmpresa char(3),
                                                  pSucursal char(4),
                                                  pOrigen smallint,
                                                  pNumCte char(20),
                                                  pApellidoPat char(26),
                                                  pApellidoMat char(26),
                                                  pNombreCte1 char(26),
                                                  pNombreCte2 char(26) )

RETURNING CHAR(6), CHAR(20), CHAR(26), CHAR(26), CHAR(26), CHAR(26), CHAR(1), SMALLINT, CHAR(13), DATE,CHAR(7);

    ----------------------------------------------------------------------
    --ACTIVIDAD: Consulta los clientes
    --Bencoppel con situacion especial.
    --Elaboró : Diana Castellanos L.
    ----------------------------------------------------------------------
    --Modificación: Cambiar Tabla si_direcciones por si_direcciones_actual
    --y eliminar la secuencia de las condiciones.
    --Fecha: 28-02-2011
    --Modifico: Sergio Fernandez Cordero
    ----------------------------------------------------------------------

    DEFINE chrcodret      CHAR(6);
    DEFINE chrnumcte      CHAR(50);
    DEFINE chrnombre1     CHAR(26);
    DEFINE chrnombre2     CHAR(26);
    DEFINE chrapell_pat   CHAR(26);
    DEFINE chrapell_mat   CHAR(26);
    DEFINE chrsituacion   CHAR(1);
    DEFINE chrtelefono    CHAR(13);
    DEFINE chrzona        CHAR(7);
    DEFINE intcausa       INTEGER;
    DEFINE intflag        SMALLINT;
    DEFINE intcodret      INT;
    DEFINE dtefecha       DATE;

    BEGIN

    ON EXCEPTION SET intcodret
        IF intcodret <> 0 THEN
            LET chrcodret = intcodret;
            RETURN chrcodret, pNumCte, pApellidoPat, pApellidoMat, pNombreCte1, pNombreCte2, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/tmp/consultasitesp.out";
    --- TRACE ON;

    LET chrcodret     = '000';
    LET chrnumcte     = '';
    LET chrnombre1    = '';
    LET chrnombre2    = '';
    LET chrapell_pat  = '';
    LET chrapell_mat  = '';
    LET chrsituacion  = '';
    LET chrtelefono   = '';
    LET chrzona       = '';
    LET intcausa      = 0;
    LET intflag       = 0;
    LET dtefecha      = '01-01-1900';

    set isolation to dirty read;
    set lock mode to wait 3;

    IF pNumCte <> '' THEN
        IF EXISTS ( SELECT numcte FROM bdinteg:si_cliente WHERE numcte = pNumCte ) THEN
            SELECT NVL(TRIM(a.nombre1),''),
                   NVL(TRIM(a.nombre2),''),
                   NVL(a.apell_paterno,''),
                   NVL(a.apell_materno,''),
                   NVL(b.situacion,'' ),
                   NVL(b.causa,0),
                   NVL(e.telefono,''),
                   d.fecha_nac,
                   trim(lpad(c.numerociudad,3,'0') ) || trim(lpad(c.numerocolonia,4,'0'))
              INTO chrnombre1, chrnombre2, chrapell_pat, chrapell_mat, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona
              FROM bdinteg:si_cliente a
             INNER JOIN bdinteg:si_direcciones_actual c ON ( a.numcte = c.numcte and tipo_dir = 1 )
              LEFT JOIN bdisitesp:se_ctessitespcte b ON ( a.numcte = b.numcte )
              LEFT JOIN bdinteg:si_ctepf d ON ( a.numcte = d.numcte )
              LEFT OUTER JOIN si_telefonos_actual e ON ( e.numcte = a.numcte AND e.tipo_tel = 1 )
            WHERE a.numcte = pNumCte;

            RETURN chrcodret, pNumCte, chrapell_pat, chrapell_mat, chrnombre1, chrnombre2, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona WITH RESUME;
        ELSE
            LET chrcodret = '001';  --- No existe numero de cliente
            RETURN chrcodret, pNumCte, chrapell_pat, chrapell_mat, chrnombre1, chrnombre2, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona WITH RESUME;
        END IF;
    ELSE
        FOREACH
            SELECT a.numcte,
                   NVL(TRIM(a.nombre1),''),
                   NVL(TRIM(a.nombre2),''),
                   NVL(a.apell_paterno,''),
                   NVL(a.apell_materno,''),
                   NVL(b.situacion,'' ),
                   NVL(b.causa,0),
                   NVL(e.telefono,''),
                   d.fecha_nac,
                   trim(lpad(c.numerociudad,3,'0') ) || trim(lpad(c.numerocolonia,4,'0'))
              INTO chrnumcte, chrnombre1, chrnombre2, chrapell_pat, chrapell_mat, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona
              FROM bdinteg:si_cliente a
             INNER JOIN bdinteg:si_direcciones_actual c ON a.numcte = c.numcte and c.tipo_dir = 1
             LEFT JOIN bdisitesp:se_ctessitespcte b ON a.numcte = b.numcte
             LEFT JOIN bdinteg:si_ctepf d ON a.numcte = d.numcte
             LEFT OUTER JOIN si_telefonos_actual e ON ( e.numcte = a.numcte AND e.tipo_tel = 1 )
             WHERE TRIM(a.nombre1) || ' ' || TRIM(a.nombre2) = TRIM(pNombreCte1)
               AND a.apell_paterno = pApellidoPat
               AND a.apell_materno = pApellidoMat

            LET intflag = 1;

            RETURN chrcodret, chrnumcte, chrapell_pat, chrapell_mat, chrnombre1, chrnombre2, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona WITH RESUME;
        END FOREACH;

        IF intflag = 0 THEN
            LET chrcodret = '002';  --- No existe nombre de cliente
            RETURN chrcodret, chrnumcte, chrapell_pat, chrapell_mat, chrnombre1, chrnombre2, chrsituacion, intcausa, chrtelefono, dtefecha, chrzona WITH RESUME;
        END IF;

    END IF;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_insertactesitesp_pba(pEmpresa char(3), pSucursal char(4), pOrigen smallint, pNumCliente char(20), pSituacion char(1), pCausa smallint, pusuarioalta char(8),
 pEmpleadoEfectuo char(8), pNombreEfectuo char(40))

    	RETURNING
    CHAR(6)   -- Codigo de Retorno

    --Elaboró : Diana Castellanos L.
    --Actividad : Inserta o actualiza el cambio de situacion esp
    -- en la tabla si_ctesitesp e inserta si_ctesitesphis

    DEFINE cVarDataErr      VARCHAR(64);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;

    DEFINE vCodRet                CHAR(6);
    --DEFINE pusuarioalta  CHAR(8);

BEGIN
    ON EXCEPTION
        SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
            LET vCodRet=iSqlErr;
            Rollback;
            RETURN vCodRet;
        END IF;
    END EXCEPTION;


--    SET DEBUG FILE TO "grabacompromisosacuerdos.out";
--    TRACE ON;

    --INICIALIZACION DE VARIABLES--
    LET vCodRet        = "000";

BEGIN WORK;

IF pEmpresa <> '' AND pSucursal <> '' AND pusuarioalta <> ''  AND pNumCliente <> ''
    AND pSituacion  <> ''  AND pEmpleadoEfectuo  <> ''  AND pNombreEfectuo <> '' AND pOrigen <> 0 THEN

       IF NOT EXISTS(select numcte from bdisitesp:se_ctessitespcte where numcte = pNumCliente) then

            insert into bdisitesp:se_ctessitespcte (empresa, numcte, situacion, causa, cvesitesporigen, sucursal, tipomovto, empleadoefectuo, 
	                                            nombreefectuo, fechamovto, usralta, fchalta, usrmodifica, fchmodifica)
            
	                values (pEmpresa, pNumCliente, pSituacion, pCausa, pOrigen, pSucursal, 'M', pEmpleadoEfectuo, pNombreEfectuo, current, pusuarioalta, TODAY, '', '');

             insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                         usralta, fchalta, usrmodifica, fchmodifica)
            values ('M', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

       ELSE

             IF pSituacion = 'C' THEN

                   Delete from bdisitesp:se_ctessitespcte  where numcte = pNumCliente;

                   insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                         usralta, fchalta, usrmodifica, fchmodifica)
            values ('E', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

            ELSE

                   Update bdisitesp:se_ctessitespcte
                    set empresa = pEmpresa, sucursal = pSucursal, cvesitesporigen = pOrigen, situacion = pSituacion, causa = pCausa, usralta = pusuarioalta,
                           empleadoefectuo = pEmpleadoEfectuo, nombreefectuo = pNombreEfectuo, fechamovto = current
                    where numcte = pNumCliente;

                   insert into bdisitesp:se_ctessitespcte_his (tipomovto, numcte, empresa, situacion, causa, cvesitesporigen, sucursal, empleadoefectuo,
                                                               usralta, fchalta, usrmodifica, fchmodifica)
            values ('S', pNumCliente, pEmpresa, pSituacion, pCausa, pOrigen, pSucursal, pEmpleadoEfectuo, pusuarioalta, current,'','');

            END IF;

       END IF;
ELSE
    LET vCodRet        = "001";   --Falta algun parametro
END IF;

COMMIT WORK;

    RETURN vCodRet;

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacatalogo_pba( pCatalogo smallint, pPais char(3), pNumeroEstado char(2), pNumeroCiudad char(3), pNombre char(100),  pNumeroCalle int, pNumeroColonia int, pClaveDomicilio int, pComplementoClave int, pMovimiento smallint, pRangoInicial char(20), pRangoFinal char(20), pTotalRegistros smallint )
RETURNING CHAR(6), CHAR(2), CHAR(3), CHAR(100), INT, INT, INT, INT ;
--pMovimiento = 1 - Avance Pagina
--              2 - Retroceso Pagina
--pTotalRegistros = Cantidad de Registros a mostrar por el query
--------------------------------------------------------------
--ACTIVIDAD: Consulta los Estados
--------------------------------------------------------------

--Definicion de variables
define v_codret        char(6) ;
define v_numeroestado  char(2) ;
define v_numerociudad  char(3) ;
define v_numerociudad_coppel  int ;
define v_nombre        char(100) ;
define v_numerocalle   int ;
define v_intcodret     int ;
define v_intflag       int ;
define v_iClaveDomicilio   int ;
define v_iComplementoClave int ;
define v_cuantos int;
define i int;

--SET DEBUG FILE TO "/tmp/consultacatalogo.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET v_intcodret
   IF v_intcodret <> 0 THEN
      LET v_codret = v_intcodret ;
      RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel ;
   END IF ;
END EXCEPTION ;

--Inicializacion de variables
let v_codret        = '000' ;
let v_numeroestado  = '' ;
let v_numerociudad  = '' ;
let v_numerociudad_coppel = 0 ;
let v_nombre        = '' ;
let v_numerocalle   = 0  ;
let v_intflag         = 0 ;
let v_iClaveDomicilio  = 0 ;
let v_iComplementoClave = 0 ;
let v_cuantos = 0;
let i=0;

let v_cuantos = pTotalRegistros;

IF v_cuantos > 50 THEN
    let v_cuantos = 50;
--SE TRUNCA A 50 PUESTO QUE LA ESTRUCTURA DEL INET ESTA DECLARADA CON MAXIMO DE 50, SINO SE VALIDARA EN ESTA PARTE, TRONARIA EL PROGRAMA.
END IF;

IF pCatalogo = 1 THEN

    IF pNumeroEstado != '' THEN
        IF EXISTS ( SELECT nombre FROM bdinteg:si_estados WHERE pais = pPais AND estado = pNumeroEstado ) THEN

                SELECT estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE pais = pPais AND estado = pNumeroEstado ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '001' ;  -- No existe el estado en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
    ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais
                AND estado < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais
                AND estado > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '002' ;  -- No existen Estados con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
ELSE
  IF pCatalogo = 2 THEN

    IF pNumeroCiudad != '' THEN
        IF EXISTS ( SELECT nombre FROM bdinteg:si_ciudades WHERE pais = pPais AND estado = pNumeroEstado AND ciudad = pNumeroCiudad ) THEN

                SELECT ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE pais = pPais AND estado = pNumeroEstado AND ciudad = pNumeroCiudad ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '003' ;  -- No existe la ciudad en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
    ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais AND estado = pNumeroEstado
                AND ciudad < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais AND estado = pNumeroEstado
                AND ciudad > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '004' ;  -- No existen Ciudades con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
  ELSE
   IF pCatalogo = 3 THEN

     IF pNumeroCalle != 0 THEN
        IF EXISTS ( SELECT nombrecalle FROM bdinteg:si_catcalles WHERE numerocalle = pNumeroCalle ) THEN

                SELECT numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE numerocalle = pNumeroCalle ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '005' ;  -- No existe la calle en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
     ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE TRIM(nombrecalle) LIKE '%' || TRIM(pNombre) || '%'
                AND numerocalle < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE TRIM(nombrecalle) LIKE '%' || TRIM(pNombre) || '%'
                AND numerocalle > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;
        IF v_intflag = 0 THEN

          LET v_codret = '006' ;  -- No existen Calles con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
     END IF ;
   ELSE
    IF pCatalogo = 4 THEN

      IF pClaveDomicilio != 0 AND pComplementoClave != 0 THEN
        IF EXISTS ( SELECT nombredomicilio FROM bdinteg:si_catdomicilios WHERE numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio AND complementoclave = pComplementoClave ) THEN

                SELECT clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO  v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio AND complementoclave = pComplementoClave ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '007' ;  -- No existe la Coordenada en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
      ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO   v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE TRIM(nombredomicilio) LIKE '%' || TRIM(pNombre) || '%' AND numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio
                AND clavedomicilio < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO   v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE TRIM(nombredomicilio) LIKE '%' || TRIM(pNombre) || '%' AND numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio
                AND clavedomicilio > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '008' ;  -- No existen Coordenadas con ese nombre
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
   END IF ;
   END IF;
  END IF;
END IF ;
END ;
END PROCEDURE ;

CREATE PROCEDURE "informix".sp_consultacatalogo( pCatalogo smallint, pPais char(3), pNumeroEstado char(2), pNumeroCiudad char(3), pNombre char(100),  pNumeroCalle int, pNumeroColonia int, pClaveDomicilio int, pComplementoClave int, pMovimiento smallint, pRangoInicial char(20), pRangoFinal char(20), pTotalRegistros smallint )
RETURNING CHAR(6), CHAR(2), CHAR(3), CHAR(100), INT, INT, INT, INT ;
--pMovimiento = 1 - Avance Pagina
--              2 - Retroceso Pagina
--pTotalRegistros = Cantidad de Registros a mostrar por el query
--------------------------------------------------------------
--ACTIVIDAD: Consulta los Estados
--------------------------------------------------------------

--Definicion de variables
define v_codret        char(6) ;
define v_numeroestado  char(2) ;
define v_numerociudad  char(3) ;
define v_numerociudad_coppel  int ;
define v_nombre        char(100) ;
define v_numerocalle   int ;
define v_intcodret     int ;
define v_intflag       int ;
define v_iClaveDomicilio   int ;
define v_iComplementoClave int ;
define v_cuantos int;
define i int;

--SET DEBUG FILE TO "/tmp/consultacatalogo.out";
--TRACE ON;

BEGIN

ON EXCEPTION SET v_intcodret
   IF v_intcodret <> 0 THEN
      LET v_codret = v_intcodret ;
      RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel ;
   END IF ;
END EXCEPTION ;

    set isolation to dirty read;
    set lock mode to wait 3;

--Inicializacion de variables
let v_codret        = '000' ;
let v_numeroestado  = '' ;
let v_numerociudad  = '' ;
let v_numerociudad_coppel = 0 ;
let v_nombre        = '' ;
let v_numerocalle   = 0  ;
let v_intflag         = 0 ;
let v_iClaveDomicilio  = 0 ;
let v_iComplementoClave = 0 ;
let v_cuantos = 0;
let i=0;

let v_cuantos = pTotalRegistros;

IF v_cuantos > 50 THEN
    let v_cuantos = 50;
--SE TRUNCA A 50 PUESTO QUE LA ESTRUCTURA DEL INET ESTA DECLARADA CON MAXIMO DE 50, SINO SE VALIDARA EN ESTA PARTE, TRONARIA EL PROGRAMA.
END IF;

IF pCatalogo = 1 THEN

    IF pNumeroEstado != '' THEN
        IF EXISTS ( SELECT nombre FROM bdinteg:si_estados WHERE pais = pPais AND estado = pNumeroEstado ) THEN

                SELECT estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE pais = pPais AND estado = pNumeroEstado ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '001' ;  -- No existe el estado en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
    ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais
                AND estado < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 estado,NVL(TRIM(nombre),'')
                INTO  v_numeroestado,v_nombre
                FROM bdinteg:si_estados
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais
                AND estado > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '002' ;  -- No existen Estados con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
ELSE
  IF pCatalogo = 2 THEN

    IF pNumeroCiudad != '' THEN
        IF EXISTS ( SELECT nombre FROM bdinteg:si_ciudades WHERE pais = pPais AND estado = pNumeroEstado AND ciudad = pNumeroCiudad ) THEN

                SELECT ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE pais = pPais AND estado = pNumeroEstado AND ciudad = pNumeroCiudad ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '003' ;  -- No existe la ciudad en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
    ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais AND estado = pNumeroEstado
                AND ciudad < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 ciudad,ciudad_coppel,NVL(TRIM(nombre),'')
                INTO  v_numerociudad,v_numerociudad_coppel,v_nombre
                FROM bdinteg:si_ciudades
                WHERE TRIM(nombre) LIKE '%' || TRIM(pNombre) || '%' AND pais = pPais AND estado = pNumeroEstado
                AND ciudad > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '004' ;  -- No existen Ciudades con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
  ELSE
   IF pCatalogo = 3 THEN

     IF pNumeroCalle != 0 THEN
        IF EXISTS ( SELECT nombrecalle FROM bdinteg:si_catcalles WHERE numerocalle = pNumeroCalle ) THEN

                SELECT numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE numerocalle = pNumeroCalle ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '005' ;  -- No existe la calle en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
     ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE TRIM(nombrecalle) LIKE '%' || TRIM(pNombre) || '%'
                AND numerocalle < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 numerocalle,NVL(TRIM(nombrecalle),'')
                INTO  v_numerocalle,v_nombre
                FROM bdinteg:si_catcalles
                WHERE TRIM(nombrecalle) LIKE '%' || TRIM(pNombre) || '%'
                AND numerocalle > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;
        IF v_intflag = 0 THEN

          LET v_codret = '006' ;  -- No existen Calles con ese criterio
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
     END IF ;
   ELSE
    IF pCatalogo = 4 THEN

      IF pClaveDomicilio != 0 AND pComplementoClave != 0 THEN
        IF EXISTS ( SELECT nombredomicilio FROM bdinteg:si_catdomicilios WHERE numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio AND complementoclave = pComplementoClave ) THEN

                SELECT clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO  v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio AND complementoclave = pComplementoClave ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        ELSE
                LET v_codret = '007' ;  -- No existe la Coordenada en el catalogo

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
        END IF;
      ELSE
        IF pMovimiento = 1 THEN
            FOREACH
                SELECT FIRST 50 clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO   v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE TRIM(nombredomicilio) LIKE '%' || TRIM(pNombre) || '%' AND numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio
                AND clavedomicilio < '' || TRIM(pRangoInicial) || '' ORDER BY 1 DESC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        ELSE
            FOREACH
                SELECT FIRST 50 clavedomicilio, complementoclave, NVL(TRIM(nombredomicilio),'')
                INTO   v_iClaveDomicilio,v_iComplementoClave,v_nombre
                FROM bdinteg:si_catdomicilios
                WHERE TRIM(nombredomicilio) LIKE '%' || TRIM(pNombre) || '%' AND numerociudad = pNumeroCiudad AND numerocolonia = pNumeroColonia AND clavedomicilio = pClaveDomicilio
                AND clavedomicilio > '' || TRIM(pRangoFinal) || '' ORDER BY 1 ASC

                LET v_intflag = 1 ;
                LET i = i + 1 ;

                RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;
                IF i = v_cuantos THEN
                    EXIT FOREACH;
                END IF;
            END FOREACH ;
        END IF;

        IF v_intflag = 0 THEN

          LET v_codret = '008' ;  -- No existen Coordenadas con ese nombre
          RETURN v_codret, v_numeroestado, v_numerociudad, v_nombre, v_numerocalle, v_iClaveDomicilio, v_iComplementoClave, v_numerociudad_coppel WITH RESUME ;

        END IF ;
    END IF ;
   END IF ;
   END IF;
  END IF;
END IF ;
END ;
END PROCEDURE ;

create procedure "informix".sp_validar_telefono_pba(pTelefono char(20) )
 returning char(5);
 
 define v_codret char(5);
 --define v_cadena char(10);
 define i smallint;
 define v_long_word smallint;
 define v_caracter char(1);
 --define v_result char(1);
 
 let v_codret = '00000';
 --let v_cadena = '';
 let i = 0;
 let v_long_word = 0;
 let v_caracter = '';
 --let v_result = 'S';
 
 let v_long_word = length(pTelefono);
 
  BEGIN

    FOR i IN (0 TO v_long_word)
          let v_caracter = substr(pTelefono, i, 1);     
          IF ( v_caracter <> '0' and v_caracter <> '1' and v_caracter <> '2' and v_caracter <> '3' and v_caracter <> '4' and v_caracter <> '5' and
               v_caracter <> '6' and v_caracter <> '7' and v_caracter <> '8' and v_caracter <> '9')   THEN

               --let v_result = 'N';
               let v_codret = "00700";
               RETURN v_codret;
          END IF;
    END FOR;
   
    --let v_codret = "Telefono correcto!";
    RETURN v_codret;
    
  END;
end procedure;

