CREATE PROCEDURE "informix".sp_valrevtelefonos( pNumCte CHAR(20) ) 
RETURNING CHAR(5), CHAR(1), CHAR(1); 
    
    DEFINE vcodret1     CHAR(5);
    DEFINE vcodret2     CHAR(5);
    DEFINE vcodret3     CHAR(50);
    DEFINE sql_err      INTEGER;
    DEFINE isam_err     INTEGER;
    DEFINE desc_err     CHAR(50);
    
    DEFINE vRevision    INTEGER;
    DEFINE vFechaHoy    DATE;
    DEFINE vFechaIniMes DATE;
    DEFINE vIndTelefono CHAR(1);
    DEFINE vIndCorreo   CHAR(1);
    DEFINE vTelefono1   CHAR(13);
    DEFINE vTelefono2   CHAR(13);
    DEFINE vTelefono3   CHAR(13);
    DEFINE vTelefono4   CHAR(13);
    DEFINE vExisteCte   SMALLINT;
    
    LET vcodret1     = '000';
    LET vcodret2     = '';
    LET vcodret3     = '';
    LET sql_err	     = 0;
    LET isam_err     = 0;
    LET desc_err     = '';
    
    LET vRevision    = 0;
    LET vFechaHoy    = '';
    LET vFechaIniMes = '';
    LET vIndTelefono = '0';
    LET vIndCorreo   = '0';
    LET vTelefono1   = '';
    LET vTelefono2   = '';
    LET vTelefono3   = '';
    LET vTelefono4   = '';
    LET vExisteCte   = 0;
    
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_valrevtelefonos.err";
        --- TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            RETURN vcodret1, vIndTelefono, vIndCorreo;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/sp_valrevtelefonos.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    -- // VALIDA PARAMETROS DE ENTRADA ( DATOS INSUFICIENTES )
    IF ( pNumCte is null OR pNumCte = '' ) THEN
        LET vcodret1 = '110'; 
        RETURN vcodret1, vIndTelefono, vIndCorreo;
    END IF;
    
    SELECT fecha_hoy, pri_dia_mes
      INTO vFechaHoy, vFechaIniMes
      FROM si_fechas
     WHERE empresa = '001';
     
    SELECT valor::INTEGER
      INTO vRevision
      FROM si_param
     WHERE cod_param = 140;
     
    IF vRevision is null OR vRevision = 0 THEN
        
        LET vIndTelefono = '0';
        LET vIndCorreo   = '0';
        RETURN vcodret1, vIndTelefono, vIndCorreo;
        
    ELIF vRevision = 1 THEN
        
        SELECT COUNT(*)
          INTO vExisteCte
          FROM si_bitacora_tel
         WHERE numcte = pNumCte;
         
        IF vExisteCte = 0 THEN
            INSERT INTO si_bitacora_tel( numcte, ind_telefono, ind_correo, canal, sucursal, user_insert, fecha_oper )
            VALUES( pNumCte, '1', '1', 0, '0000', 'informix', CURRENT );
        ELSE
            SELECT COUNT(*)
              INTO vExisteCte
              FROM si_bitacora_tel
             WHERE numcte = pNumCte
               --- AND fecha_oper::date >= vFechaIniMes
               AND fecha_oper::date >= '01/01/'||YEAR(vFechaHoy)
               AND ( ind_telefono = '0' OR ind_correo = '0' );
               
            IF vExisteCte > 0 THEN
                LET vIndTelefono = '0';
                LET vIndCorreo   = '0';
                RETURN vcodret1, vIndTelefono, vIndCorreo;
            END IF;
        END IF;
    
        SELECT NVL(telefono, '')
          INTO vTelefono1
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        SELECT NVL(telefono, '')
          INTO vTelefono2
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
           
        SELECT NVL(telefono, '')
          INTO vTelefono3
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 3;
           
        SELECT NVL(telefono, '')
          INTO vTelefono4
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 4;
        
        IF   ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '01' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '1' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '1' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '1' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '1' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '02' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '2' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '2' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '2' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '2' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '03' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '3' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '3' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '3' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '3' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '04' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '4' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '4' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '4' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '4' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '05' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '5' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '5' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '5' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '5' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '06' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '6' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '6' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '6' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '6' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '07' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '7' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '7' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '7' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '7' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '08' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '8' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '8' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '8' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '8' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '09' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '9' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '9' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '9' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '9' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') = '10' ) AND ( SUBSTR(vTelefono1,  LENGTH(vTelefono1)-0, 1) = '0' OR
                                                               SUBSTR(vTelefono2,  LENGTH(vTelefono2)-0, 1) = '0' OR
                                                               SUBSTR(vTelefono3,  LENGTH(vTelefono3)-0, 1) = '0' OR
                                                               SUBSTR(vTelefono4,  LENGTH(vTelefono4)-0, 1) = '0' ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        ELIF ( ( LPAD(MONTH(vFechaHoy), 2, '0') IN('11','12') ) AND ( (vTelefono1 is null OR vTelefono1 = '') OR
                                                                      (vTelefono2 is null OR vTelefono2 = '') OR
                                                                      (vTelefono3 is null OR vTelefono3 = '') OR
                                                                      (vTelefono4 is null OR vTelefono4 = '') ) ) THEN
            LET vIndTelefono = '1'; LET vIndCorreo = '1';
        END IF;
        
        UPDATE si_bitacora_tel
           SET ind_correo   = '0',
               ind_telefono = '0',
               fecha_oper   = CURRENT
         WHERE numcte = pNumCte;
    
    ELIF vRevision = 2 THEN
    
        SELECT COUNT(*)
          INTO vExisteCte
          FROM si_bitacora_tel
         WHERE numcte = pNumCte;
         
        IF vExisteCte = 0 THEN
            INSERT INTO si_bitacora_tel( numcte, ind_telefono, ind_correo, canal, sucursal, user_insert, fecha_oper )
            VALUES( pNumCte, '1', '1', 0, '0000', 'informix', CURRENT );
            
            LET vIndTelefono = '1';
            LET vIndCorreo   = '1';
        ELSE
            SELECT COUNT(*)
              INTO vExisteCte
              FROM si_bitacora_tel
             WHERE numcte = pNumCte
               --- AND fecha_oper::date >= vFechaIniMes
               AND fecha_oper::date >= '01/01/'||YEAR(vFechaHoy)
               AND ( ind_telefono = '0' OR ind_correo = '0' );
               
            IF vExisteCte > 0 THEN
                LET vIndTelefono = '0';
                LET vIndCorreo   = '0';
                RETURN vcodret1, vIndTelefono, vIndCorreo;
            ELSE
                LET vIndTelefono = '1';
                LET vIndCorreo   = '1';
            END IF;
        END IF;
        
        UPDATE si_bitacora_tel
           SET ind_correo   = '0',
               ind_telefono = '0',
               fecha_oper   = CURRENT
         WHERE numcte = pNumCte;
    
    END IF;
    
    END;
    
    RETURN vcodret1, vIndTelefono, vIndCorreo;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_valida_sucursal(pEmpresa CHAR(3), pSucursal CHAR(4))

RETURNING
CHAR(5) AS cCodret;

DEFINE cCodRet CHAR(5);
DEFINE iSqlErr INTEGER;
DEFINE cSucursal CHAR(4);

LET cCodRet = '00000';
LET iSqlErr = 0;
LET cSucursal = "";

BEGIN
	ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet; 
			END IF;
	END EXCEPTION;
	
--SET DEBUG FILE TO '/home/tmp/oscar/sp_valida_sucursal.out';
--TRACE ON;
	
	IF  (pEmpresa IS NULL OR pEmpresa = '')
	OR	(pSucursal IS NULL OR pSucursal = '' ) THEN
		LET cCodRet = '00001'; --Se introdujo un campo nulo o vacio
	ELIF  pSucursal = '0000'	THEN
		LET cCodRet = '00003'; --Se introdujo una sucursal 0000
	ELSE
		SELECT sucursal INTO cSucursal FROM bdinteg:"informix".si_sucursales WHERE empresa = pEmpresa AND sucursal = pSucursal;
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
			LET cCodRet = '00002'; --Error por si no existe la sucursal
		ELSE 
			LET cCodRet = '00000'; --Si existe la sucursal
		END IF;	
	END IF;
	RETURN cCodRet;
END;
END PROCEDURE
DOCUMENT
'FOLIO: 1559',
'AUTOR : 95584315',
'FECHA : 24-10-2013',
'MODIFICACIÓN: Se crea SP para validar sucursales',
'SUSTENTO: RQM 12 023 Consulta de Transacciones.doc No viene documentado en el RQM',
'SOLICITA: Norberto Corona Berruecos',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_consultahistoricotarjetas( psNumCuenta CHAR(12), psNumTarjeta CHAR(16), piTipoBusqueda SMALLINT, psEmpresa CHAR(3) )
	RETURNING
		CHAR(5) AS CodigoRetorno,
		CHAR(1) AS TipoCliente, CHAR(10) AS FechaStatusUltMod, CHAR(10) AS HoraStatusUltMod, CHAR(8) AS EmpleadoModifico, CHAR(100) AS NombreEmpMod,
		CHAR(10) AS FechaStatusAperturaCuenta, CHAR(4) AS SucursalAperturaCuenta, CHAR(8) AS EmpleadoAperturo, CHAR(100) AS NombreEmpAperturo,
		CHAR(10) AS FechaStatusEntrega,	CHAR(10) AS HoraStatusEntrega, CHAR(4) AS SucursalEntrega, CHAR(8) AS EmpleadoEntrega, CHAR(100) AS NombreEmpEntrego,
		CHAR(25) AS StatusTarjetaCancelada, CHAR(10) AS FechaStatusCancelada, CHAR(10) AS HoraStatusCancelada, SMALLINT AS Secuencia, CHAR(8) AS EmpleadoModificoCancelacion, CHAR(100) AS NombreEmpModCancelacion;

	--Declaración de variables.
	DEFINE sCodRet 		CHAR(5);	-- Código de retorno.
	DEFINE sSqlErr		INTEGER;	-- Código de error controlado por INFORMIX.

	--Datos generales de la tarjeta.
	DEFINE sTipo 	        	CHAR(1);	-- Tipo cliente tarjeta.
	DEFINE sFechaStatusUltMod	CHAR(10);	-- Fecha última modificación de la tarjeta.
	DEFINE sHoraStatusUltMod	CHAR(10);	-- Hora  última modificación de la tarjeta.
	DEFINE sEmpleadoModifico	CHAR(8);	-- Empleado que realizó la última modificación de la tarjeta.
	DEFINE sNombreEmpMod  		CHAR(100);	-- Nombre del empleado que realizó la última modificación de la tarjeta.

	--Datos de la apertura de la cuenta.
	DEFINE sFechaStatusAperturaCuenta	CHAR(10); 	-- Fecha de la apertura de la cuenta.
	DEFINE sSucursalAperturaCuenta 		CHAR(4);  	-- Número de la sucursal donde se realizó la apertura.
	DEFINE sEmpleadoAperturo 			CHAR(8);  	-- Empleado que realizó la apertura.
	DEFINE sNombreEmpAperturo 			CHAR(100);	-- Nombre del empleado que realizó la apertura.

	--Datos de la entrega  de la tarjeta.
	DEFINE sFechaStatusEntrega		CHAR(10); 	-- Fecha de entrega de tarjeta.
	DEFINE sHoraStatusEntrega		CHAR(10); 	-- Hora de entrega de tarjeta.
	DEFINE sSucursalEntrega			CHAR(4);	-- Número de la sucursal donde se realizó la entrega,
	DEFINE sEmpleadoEntrega			CHAR(8);	-- Empleado que realizó la entrega de la tarjeta.
	DEFINE sNombreEmpEntrego 		CHAR(100);	-- Nombre del empleado que realizó la entrega de la tarjeta.

	--Datos del histórico de la tarjeta.
	DEFINE sStatusTarjetaCancelada		CHAR(25);	-- Descripción del status de la tarjeta cancelada.
	DEFINE sFechaStatusCancelada 		CHAR(10);	-- Fecha de cancelación de la tarjeta.
	DEFINE sHoraStatusCancelada			CHAR(10);	-- Hora de cancelación de la tarjeta.
	DEFINE iSecuencia 					SMALLINT; 	-- Secuencia de la tarjeta.
	DEFINE sEmpleadoModificoCancelacion CHAR(8);  	-- Empleado que realizó la cancelación.
	DEFINE sNombreEmpModCancelacion		CHAR(100);	-- Nombre del empleado que realizó la cancelación.

	DEFINE sNumTarjeta      CHAR(16);
	DEFINE sNumCuenta		CHAR(12);

	--Asignación de valores a variables.
	LET sCodRet = '00000';
	LET sSqlErr = 0;

	LET sTipo = '';
	LET sFechaStatusUltMod = '';
	LET sHoraStatusUltMod = '';
	LET sEmpleadoModifico = '';
	LET sNombreEmpMod = '';

	LET sFechaStatusEntrega = '';
	LET sHoraStatusEntrega = '';
	LET sSucursalEntrega = '';
	LET sEmpleadoEntrega = '';
	LET sNombreEmpEntrego = '';

	LET sFechaStatusAperturaCuenta = '';
	LET sSucursalAperturaCuenta = '';
	LET sEmpleadoAperturo = '';
	LET sNombreEmpAperturo = '';

	LET sStatusTarjetaCancelada = '';
	LET sFechaStatusCancelada = '';
	LET sHoraStatusCancelada  = '';
	LET iSecuencia = 0;
	LET sEmpleadoModificoCancelacion = '';
	LET sNombreEmpModCancelacion = '';

	LET sNumTarjeta = '';
	LET sNumCuenta = '';

	--SET DEBUG FILE TO "/informix/SIA/sp_consultahistoricotarjetas.out";
	--TRACE ON;
	BEGIN

		ON EXCEPTION SET sSqlErr

	      IF sSqlErr <> 0 THEN

				LET sCodRet = sSqlErr;

				RETURN
					sCodRet,
					sTipo, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico, sNombreEmpMod,
					sFechaStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo, sNombreEmpAperturo,
					sFechaStatusEntrega, sHoraStatusEntrega, sSucursalEntrega, sEmpleadoEntrega, sNombreEmpEntrego,
					sStatusTarjetaCancelada, sFechaStatusCancelada, sHoraStatusCancelada, iSecuencia, sEmpleadoModificoCancelacion, sNombreEmpModCancelacion;

	      END IF;

		END EXCEPTION;

		--SET DEBUG FILE TO "/tmp/sp_consultahistoricotarjetas.out";
		--TRACE ON;

		SET ISOLATION DIRTY READ;

		IF ( NVL( psNumTarjeta, '' ) <> '' AND NVL( psNumCuenta, '' ) <> '' AND
			( NVL( piTipoBusqueda, 0 ) > 0 AND NVL( piTipoBusqueda, 0 ) < 3 ) AND
			NVL( psEmpresa, '' ) <> '' ) THEN

			LET psNumTarjeta = TRIM( psNumTarjeta );
			LET psNumCuenta = TRIM( psNumCuenta );

			-- Opción para obtener los datos de una tarjeta de CRÉDITO.
			IF ( piTipoBusqueda = 1 ) THEN

				-- Se obtienen los datos para la sección de "DATOS GENERALES DE LA TARJETA".
				SELECT b.numtarjeta, b.titular, TO_CHAR( b.fechaultmodif, '%Y-%m-%d' ), SUBSTR( b.fechaultmodif, 12, 8 ), NVL( b.usuarioultmodif, '' )
					INTO sNumTarjeta, sTipo, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico
				FROM intercard:tarjetacuenta a
					LEFT OUTER JOIN intercard:tarjeta b ON ( a.numtarjeta = b.numtarjeta )
				WHERE a.numcuenta = psNumCuenta AND a.numtarjeta = psNumTarjeta;

				-- Se obtiene nombre de ejecutivo.
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoModifico, sNombreEmpMod
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoModifico;

				IF( NVL( sEmpleadoModifico, '' ) = '' ) THEN

					LET sNumTarjeta = '';

				END IF;

				IF ( NVL( sNumTarjeta, '' ) <> '' ) THEN

					-- Se obtienen los datos para de la sección de "DATOS  DE  LA APERTURA  DE   LA  CUENTA".
					SELECT a.num_credito, TO_CHAR( a.fecha_apertura, '%Y-%m-%d' ), a.sucursal, b.ejecutivo_auto
						INTO sNumCuenta, sFechaStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo
					FROM bdicred:sd_maecred a
						LEFT OUTER JOIN bdisolic:ss_autorizacion b ON ( a.num_credito = b.num_solicitud AND a.empresa = b.empresa )
					WHERE b.empresa = psEmpresa AND b.num_solicitud = psNumCuenta
						AND b.status_solicitud = 'AP';

					-- Se obtiene nombre de ejecutivo.
					SELECT ejecutivo, UPPER( nombre )
						INTO sEmpleadoAperturo, sNombreEmpAperturo
					FROM bdinteg:si_ejecut
					WHERE ejecutivo = sEmpleadoAperturo;

					IF( NVL( sEmpleadoAperturo, '' ) = '' ) THEN

						LET sNumCuenta = '';

					END IF;

					IF ( NVL( sNumCuenta, '' ) <> '' ) THEN

						-- Se obtienen los datos para de la sección de "DATOS DE LA ENTREGA DE LA TARJETA".
						SELECT LIMIT 1 TRIM( a.numtarjeta ), SUBSTR( a.idterminal, 1, 4 ), NVL( SUBSTR( a.idterminal, 5, 8 ), '' ), TO_CHAR( a.fechahorainauth, '%Y-%m-%d' ),
								SUBSTR( a.fechahorainauth, 12, 8 )
							INTO sNumTarjeta, sSucursalEntrega, sEmpleadoEntrega, sFechaStatusEntrega, sHoraStatusEntrega
						FROM intercard:movimientohistorico a
						WHERE a.numtarjeta = psNumTarjeta -- Búsqueda por Tarjeta
							AND a.codtran = '95'
							AND a.prodind = '01' AND a.formato = '0200' AND a.codigoiso = '00';

						IF( NVL( sNumTarjeta, '' ) = '' ) THEN -- Si no hubo información en intercard:movimientohistorico, se consulta la intercard:movimiento.

							SELECT LIMIT 1 TRIM( a.numtarjeta ), SUBSTR( a.idterminal, 1, 4 ), NVL( SUBSTR( a.idterminal, 5, 8 ), '' ), TO_CHAR( a.fechahorainauth, '%Y-%m-%d' ),
									SUBSTR( a.fechahorainauth, 12, 8 )
								INTO sNumTarjeta, sSucursalEntrega, sEmpleadoEntrega, sFechaStatusEntrega, sHoraStatusEntrega
							FROM intercard:movimiento a
							WHERE a.numtarjeta = psNumTarjeta -- Búsqueda por Tarjeta
								AND a.codtran = '95'
								AND a.prodind = '01' AND a.formato = '0200' AND a.codigoiso = '00';

						END IF;

						-- Se obtiene la secuencia de la tarjeta.
						SELECT num_tarjeta, secuencia
							INTO sNumTarjeta, iSecuencia
						FROM bdicred:sd_tarjeta
						WHERE num_tarjeta = sNumTarjeta AND empresa = psEmpresa;

						-- Se obtiene nombre de ejecutivo.
						SELECT a.ejecutivo, UPPER( a.nombre )
							INTO sEmpleadoEntrega, sNombreEmpEntrego
						FROM bdinteg:si_ejecut a
						WHERE a.ejecutivo = sEmpleadoEntrega;

						IF( iSecuencia IS NULL OR
							NVL( sEmpleadoEntrega, '' ) = '' ) THEN

							LET sNumTarjeta = '';

						END IF;

						IF ( NVL( sNumTarjeta, '' ) <> '' ) THEN

							-- Se obtienen los datos para de la sección de "HISTÓRICO DE LA TARJETA".
							SELECT a.numtarjeta, UPPER( b.descstatustarjeta ), TO_CHAR( a.fechaultmodif, '%Y-%m-%d' ), SUBSTR( a.fechaultmodif, 12, 8 ), NVL( a.usuarioultmodif, '' )
								INTO sNumTarjeta, sStatusTarjetaCancelada, sFechaStatusCancelada, sHoraStatusCancelada, sEmpleadoModificoCancelacion
							FROM intercard:tarjeta a
								LEFT OUTER JOIN intercard:statustarjeta b ON ( a.codstatustarjeta = b.codstatustarjeta )
							WHERE a.numtarjeta = psNumTarjeta
								AND b.codstatustarjeta IN( 'BLO', 'CAN', 'DES', 'EXT', 'INA', 'ROB', 'FAL','DAN' );

							-- Se obtiene el nombre del ejecutivo.
							SELECT ejecutivo, UPPER( nombre )
								INTO sEmpleadoModificoCancelacion, sNombreEmpModCancelacion
							FROM bdinteg:si_ejecut
							WHERE ejecutivo = sEmpleadoModificoCancelacion;

							IF( NVL( sNumTarjeta, '' ) = '' OR NVL( sEmpleadoModificoCancelacion, '' ) = '' ) THEN

								LET sStatusTarjetaCancelada = '';
								LET sFechaStatusCancelada = '';
								LET sHoraStatusCancelada = '';
								LET sEmpleadoModificoCancelacion = '';
								LET sNombreEmpModCancelacion = '';

							END IF;

						ELSE

							LET sCodRet = '00004';

						END IF;
					ELSE

						LET sCodRet = '00003';

					END IF;
				ELSE

					LET sCodRet = '00002';

				END IF;
			ELSE -- Opción para obtener los datos de una tarjeta de DÉBITO.

				-- Se obtienen los datos para de la sección de "DATOS GENERALES DE LA TARJETA".
				SELECT a.numtarjeta, a.titular, TO_CHAR( a.fechaultmodif, '%Y-%m-%d' ), SUBSTR( a.fechaultmodif, 12, 8 ), NVL( a.usuarioultmodif, '' )
					INTO sNumTarjeta, sTipo, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico
				FROM intercard:tarjeta a
					LEFT OUTER JOIN intercard:tarjetacuenta b ON ( a.numtarjeta = b.numtarjeta )
				WHERE b.numcuenta = psNumCuenta AND b.numtarjeta = psNumTarjeta;

				-- Se obtiene nombre del ejecutivo.
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoModifico, sNombreEmpMod
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoModifico;

				-- Se valida la existencia del ejecutivo.
				IF ( NVL( sEmpleadoModifico, '' ) = '' ) THEN

					LET sNumTarjeta = '';

				END IF;

				IF ( NVL( sNumTarjeta, '' ) <> '' ) THEN

					-- Se obtienen los datos para de la sección de "DATOS  DE  LA APERTURA  DE  LA CUENTA".
					SELECT a.numtarjeta, TO_CHAR( c.fecha_alta, '%Y-%m-%d' ), b.sucursal, NVL( c.ejecutivo, '' )
						INTO sNumTarjeta, sFechaStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo
					FROM intercard:tarjetacuenta a
						JOIN bdicheq:sc_maechq b ON ( b.empresa = psEmpresa AND a.numcuenta = b.cuenta )
						JOIN bdicheq:sc_maenoc c ON ( c.empresa = psEmpresa AND a.numcuenta = c.cuenta )
					WHERE a.numcuenta = psNumCuenta AND a.numtarjeta = psNumTarjeta;

					-- Se obtienen nombre de empleado que aperturó la cuenta.
					SELECT ejecutivo, UPPER( nombre )
						INTO sEmpleadoAperturo, sNombreEmpAperturo
					FROM bdinteg:si_ejecut
					WHERE ejecutivo = sEmpleadoAperturo;

					IF ( NVL( sEmpleadoAperturo, '' ) = '' ) THEN

						LET sNumTarjeta = '';

					END IF;

					IF ( NVL( sNumTarjeta, '' ) <> '' ) THEN

						-- Se obtienen los datos para de la sección de "DATOS DE LA ENTREGA DE LA TARJETA".
						SELECT LIMIT 1 TRIM( a.numtarjeta ), SUBSTR( a.idterminal, 1, 4 ), NVL( SUBSTR( a.idterminal, 5, 8 ), '' ), TO_CHAR( a.fechahorainauth, '%Y-%m-%d' ),
								SUBSTR( a.fechahorainauth, 12, 8 )
							INTO sNumTarjeta, sSucursalEntrega, sEmpleadoEntrega, sFechaStatusEntrega, sHoraStatusEntrega
						FROM intercard:movimientohistorico a
						WHERE a.numtarjeta = psNumTarjeta -- Búsqueda por Tarjeta
							AND a.codtran = '95'
							AND a.prodind = '01' AND a.formato = '0200' AND a.codigoiso = '00';

						IF( NVL( sNumTarjeta, '' ) = '' ) THEN -- Si no hubo información en intercard:movimientohistorico, se consulta la intercard:movimiento.

							SELECT LIMIT 1 TRIM( a.numtarjeta ), SUBSTR( a.idterminal, 1, 4 ), NVL( SUBSTR( a.idterminal, 5, 8 ), '' ), TO_CHAR( a.fechahorainauth, '%Y-%m-%d' ),
									SUBSTR( a.fechahorainauth, 12, 8 )
								INTO sNumTarjeta, sSucursalEntrega, sEmpleadoEntrega, sFechaStatusEntrega, sHoraStatusEntrega
							FROM intercard:movimiento a
							WHERE a.numtarjeta = psNumTarjeta -- Búsqueda por Tarjeta
								AND a.codtran = '95'
								AND a.prodind = '01' AND a.formato = '0200' AND a.codigoiso = '00';

						END IF;

						-- Se obtiene la secuencia de la tarjeta.
						SELECT num_tarjeta, secuencia
							INTO sNumTarjeta, iSecuencia
						FROM bdicheq:sc_tarjeta
						WHERE num_tarjeta = sNumTarjeta AND empresa = psEmpresa;

						-- Se obtiene nombre de ejecutivo.
						SELECT ejecutivo, UPPER( nombre )
							INTO sEmpleadoEntrega, sNombreEmpEntrego
						FROM bdinteg:si_ejecut
						WHERE ejecutivo = sEmpleadoEntrega;

						IF( iSecuencia IS NULL OR
							NVL( sEmpleadoEntrega, '' ) = '' ) THEN

							LET sNumTarjeta = '';

						END IF;

						IF ( NVL( sNumTarjeta, '' ) <> '' ) THEN

							-- Se obtienen los datos para de la sección de "HISTÓRICO DE LA TARJETA".
							SELECT a.numtarjeta, UPPER( b.descstatustarjeta ), TO_CHAR( a.fechaultmodif, '%Y-%m-%d' ), SUBSTR( a.fechaultmodif, 12, 8 ), a.usuarioultmodif
								INTO sNumTarjeta, sStatusTarjetaCancelada, sFechaStatusCancelada, sHoraStatusCancelada, sEmpleadoModificoCancelacion
							FROM intercard:tarjeta a
								LEFT OUTER JOIN intercard:statustarjeta b ON ( a.codstatustarjeta = b.codstatustarjeta )
							WHERE a.numtarjeta = psNumTarjeta
								AND b.codstatustarjeta IN( 'BLO', 'CAN', 'DES', 'EXT', 'INA', 'ROB', 'FAL','DAN' );

							SELECT ejecutivo, UPPER( nombre )
								INTO sEmpleadoModificoCancelacion, sNombreEmpModCancelacion
							FROM bdinteg:si_ejecut
							WHERE ejecutivo = sEmpleadoModificoCancelacion;

							IF( NVL( sNumTarjeta, '' ) = '' OR NVL( sEmpleadoModificoCancelacion, '' ) = '' ) THEN

								LET sStatusTarjetaCancelada = '';
								LET sFechaStatusCancelada = '';
								LET sHoraStatusCancelada = '';
								LET sEmpleadoModificoCancelacion = '';
								LET sNombreEmpModCancelacion = '';

							END IF;
						ELSE

							LET sCodRet = '00004';

						END IF;
					ELSE

						LET sCodRet = '00003';

					END IF;
				ELSE

					LET sCodRet = '00002';

				END IF;
			END IF;
		ELSE

			LET sCodRet = '00001';

		END IF;

		RETURN
			sCodRet,
			sTipo, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico, sNombreEmpMod,
			sFechaStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo, sNombreEmpAperturo,
			sFechaStatusEntrega, sHoraStatusEntrega, sSucursalEntrega, sEmpleadoEntrega, sNombreEmpEntrego,
			sStatusTarjetaCancelada, sFechaStatusCancelada, sHoraStatusCancelada, iSecuencia, sEmpleadoModificoCancelacion, sNombreEmpModCancelacion;

	END;
END PROCEDURE
DOCUMENT
'CREADO: 		Francisco Rodríguez Ibarra',
'FECHA: 		30 /Abril/ 2010',
'DESCRIPCIÓN: 	Consulta los datos de la Tarjeta, además que trae el histórico.',

'MODIFICÓ: 		Francisco Rodríguez Ibarra',
'FECHA:			19-Mayo-2010',
'MODIFICACIÓN: 	Se modificó SP para que obtener correctamente la secuencia.',

'MODIFICÓ: 		Arturo Méndez Cárdenas',
'FECHA: 		23/11/2010',
'MODIFICACIÓN: 	Obtener el valor de la hora en el segmento del HISTÓRICO DE LA TARJETA.',

'MODIFICÓ: 		Ulises Rodríguez Márquez',
'FECHA: 		28/12/2010',
'MODIFICACIÓN: 	Se optimizan las consultas de datos generales de tarjeta, apertura de cuenta,',
'				entrega de tarjeta e histórico de tarjeta. Costo total 375.',

'MODIFICÓ: 		Bernardo Beltrán Herrera',
'FECHA: 		24/10/2012',
'MODIFICACIÓN: 	Se agrega búsqueda a tabla intercard:movimientohistorico_old.',

'MODIFICÓ: 		Bernardo Beltrán Herrera',
'FECHA: 		23/01/2014',
'MODIFICACIÓN: 	Se elimina referencia a tabla intercard:movimientohistorico_old.'

;

CREATE PROCEDURE "informix".sp_consultahistoricocuentas( psNumCuenta CHAR(12), psNumTarjeta CHAR(16), piTipoBusqueda SMALLINT, psEmpresa CHAR(3) )
	RETURNING 
		CHAR(5) AS CodigoRetorno, 
		CHAR(25) AS Estatus, CHAR(10) AS FechaStatus, CHAR(10) AS HoraStatus, CHAR(4) AS Sucursal, CHAR(8) AS Empleado, CHAR(100) AS NombreEmpleado;
	
	--Declaración de variables.
	DEFINE sCodigoRetorno 	CHAR(5);	-- Código de retorno.
	DEFINE sSqlErr			INTEGER;	-- Código de error controlado por INFORMIX.	
	DEFINE iCont			INTEGER;
	
	--Datos generales de la cuenta.
	DEFINE sProducto			CHAR(25);	-- Nombre del producto al cual pertenece la cuenta.
	DEFINE sFechaStatusUltMod	CHAR(10);	-- Fecha de la última modificación de la cuenta.
	DEFINE sHoraStatusUltMod  	CHAR(10); 	-- Hora de la última modificación de la cuenta.
	DEFINE sEmpleadoModifico	CHAR(8);	-- Empleado que realizó la última modificación.
	DEFINE sNombreEmpMod 		CHAR(100);	-- Nombre del empleado que realizó la última modificación.
		
	--Datos de la apertura de la cuenta.
	DEFINE sFechaStatusAperturaCuenta	CHAR(10); 	-- Fecha de la apertura de la cuenta.
	DEFINE sHoraStatusAperturaCuenta	CHAR(10); 	-- Hora de la apertura de la cuenta.
	DEFINE sSucursalAperturaCuenta 		CHAR(4);  	-- Número de la sucursal donde se realizó la apertura.
	DEFINE sEmpleadoAperturo 			CHAR(8);  	-- Empleado que realizó la apertura.
	DEFINE sNombreEmpAperturo 			CHAR(100);	-- Nombre del empleado que realizó la apertura.
		
	--Datos histórico de la cuenta.
	DEFINE sEstatusHistorico 		CHAR(25);	-- Estatus de histórico de la cuenta.
	DEFINE sFechaEstatusHistorico 	CHAR(10);	-- Fecha del estatus de histórico de la cuenta.
	DEFINE sHoraStatusHistorico 	CHAR(10);	-- Hora del estatus de histórico de la cuenta
	DEFINE sEmpleadoHistorico 		CHAR(8);	-- Empleado histórico de la cuenta.
	DEFINE sNombreEmpleadoHistorico	CHAR(100);	-- Nombre de empleado de histórico de la cuenta.
		
	DEFINE sNumTarjeta		CHAR(16);
	DEFINE sNumCuenta		CHAR(12);
    DEFINE sCuentaPagare    CHAR(12);    
    DEFINE sCuentaInversion CHAR(12);
	
	DEFINE vDia INTEGER;
	DEFINE vMes INTEGER;
	DEFINE vAnio INTEGER;
	DEFINE  vfechamttoaux DATE;
	
	LET vDia = 0;
	LET vMes = 0;
	LET vAnio = 0;
	LET vfechamttoaux = MDY( 1,1,1900);
	-- Asignación de valores por defecto a variables.
	LET sCodigoRetorno = '00000';
	LET sSqlErr = 0;
	LET iCont = 0;	
	
	LET sFechaStatusUltMod = '';
	LET sHoraStatusUltMod = '';	
	LET sEmpleadoModifico = '';
	LET sNombreEmpMod = '';
	
	LET sFechaStatusAperturaCuenta = '';
	LET sHoraStatusAperturaCuenta = '';
	LET sSucursalAperturaCuenta = '';
	LET sEmpleadoAperturo = '';
	LET sNombreEmpAperturo = '';
	
	LET sEstatusHistorico = '';
	LET sFechaEstatusHistorico = '';
	LET sHoraStatusHistorico = '';
	LET sEmpleadoHistorico = '';
	LET sNombreEmpleadoHistorico = '';
    
	LET sNumTarjeta = '';
	LET sNumCuenta = '';		
    LET sCuentaPagare = '';
    LET sCuentaInversion = '';	
	
	---SET DEBUG FILE TO "/informix/SIA/sp_consultahistoricocuentas.out";
	---TRACE ON;
	
	BEGIN
	
		ON EXCEPTION SET sSqlErr
		
	      IF sSqlErr <> 0 THEN

	            LET sCodigoRetorno = sSqlErr;
				
	            RETURN sCodigoRetorno, 
					NULL, NULL, NULL, NULL, NULL, NULL;
				
	      END IF;
		
		END EXCEPTION;
	
		SET ISOLATION DIRTY READ;
		
		IF ( NVL( psNumCuenta, '' ) <> '' AND 
			( NVL( piTipoBusqueda, 0 ) > 0 AND NVL( piTipoBusqueda, 0 ) < 10 ) AND 
			NVL( psEmpresa, '' ) <> '' ) THEN

			-- Datos generales para la cuenta de crédito.
			IF ( piTipoBusqueda = 1 ) THEN
			
				SELECT a.numtarjeta, TO_CHAR( a.fechaultmodif, '%d/%m/%Y' ), SUBSTR( a.fechaultmodif, 12, 8 ), a.usuarioultmodif, e.nombre_prod
					INTO sNumTarjeta, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico, sProducto
				FROM intercard:tarjeta a
					LEFT OUTER JOIN intercard:tarjetacuenta b ON ( a.numtarjeta = b.numtarjeta )
					LEFT OUTER JOIN bdicred:sd_maecred c ON ( c.num_credito = b.numcuenta )
					JOIN bdicred:sd_definicion e ON ( e.num_producto = c.num_producto )
				WHERE c.num_credito = psNumCuenta
					AND b.numtarjeta = psNumTarjeta;
					
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoModifico, sNombreEmpMod
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoModifico;
				
				IF ( NVL( sNumTarjeta, '' ) = '' OR NVL( sEmpleadoModifico, '' ) = '' OR NVL( sNombreEmpMod, '' ) = '' ) THEN

					LET sCodigoRetorno = '00001'; -- Error al tratar de obtener los datos generales de la cuenta de crédito.

				END IF;
				
				RETURN sCodigoRetorno, 
					sProducto, sFechaStatusUltMod, sHoraStatusUltMod, NULL, sEmpleadoModifico, sNombreEmpMod;
			
			-- Histórico de la cuenta de crédito, apertura de cuenta.
			ELIF ( piTipoBusqueda = 8 ) THEN
				
				SELECT a.num_credito, TO_CHAR( a.fecha_apertura, '%d/%m/%Y' ), a.sucursal, b.ejecutivo_auto
					INTO sNumCuenta, sFechaStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo
				FROM bdicred:sd_maecred a
					LEFT OUTER JOIN bdisolic:ss_autorizacion b ON ( a.num_credito = b.num_solicitud AND a.empresa = b.empresa )
				WHERE b.empresa = psEmpresa AND b.num_solicitud = psNumCuenta
					AND b.status_solicitud = 'AP';
				
				-- Se obtiene nombre de ejecutivo.
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoAperturo, sNombreEmpAperturo
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoAperturo;
				
				IF ( NVL( sNumCuenta, '' ) <> '' AND NVL( sEmpleadoAperturo, '' ) <> '' ) THEN 
				
					SELECT num_credito, hora_mov::DATETIME HOUR TO SECOND
						INTO sNumCuenta, sHoraStatusAperturaCuenta
					FROM bdicred:sd_movhis
					WHERE empresa = psEmpresa AND num_credito = psNumCuenta AND codigo_fun = '001' AND codigo_ref = 1 AND reversado = 'N';
					
					IF ( sNumCuenta IS NULL ) THEN
					
						SELECT num_credito, hora_mov::DATETIME HOUR TO SECOND
							INTO sNumCuenta, sHoraStatusAperturaCuenta
						FROM bdicred:sd_movdia
						WHERE num_credito = psNumCuenta AND codigo_fun = '001' AND codigo_ref = 1 AND reversado = 'N';
					
					END IF;
										
				END IF;
				
				IF ( sNumCuenta IS NULL ) THEN 
						
					LET sCodigoRetorno = '00002'; -- Error al tratar de obtener los datos de Cuenta Crédito.
						
				END IF;
				
				RETURN sCodigoRetorno, 
					NULL, sFechaStatusAperturaCuenta, sHoraStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo, sNombreEmpAperturo;
			
			--Histórico de las cuentas de crédito, Cancelación de crédito.
			ELIF ( piTipoBusqueda = 9 ) THEN
				
				SELECT a.num_credito, a.status_cred, TO_CHAR( b.fecha_ult_mov, '%d/%m/%Y' )
					INTO sNumCuenta, sEstatusHistorico, sFechaEstatusHistorico
				FROM bdicred:sd_maecred a 
					LEFT OUTER JOIN bdicred:sd_maesdos b ON ( b.num_credito = a.num_credito )
					LEFT OUTER JOIN bdicred:sd_tipocartera c ON ( c.status_cred = a.status_cred AND c.empresa = psEmpresa )
				WHERE b.empresa = psEmpresa AND b.num_credito = psNumCuenta
					AND c.status_cred IN ( 'FF', 'FC', 'CV', 'CE' );
					
				IF ( NVL( sNumCuenta, '' ) = '' ) THEN 
				
					LET sCodigoRetorno = '00009'; -- No tiene cancelación.
					
				END IF;
				
				RETURN sCodigoRetorno, 
					sEstatusHistorico, sFechaEstatusHistorico, NULL, NULL, NULL, NULL;			

			-- Datos generales para la cuentas de débito.
			ELIF ( piTipoBusqueda = 2 ) THEN
			
				LET psNumCuenta = TRIM( psNumCuenta );
			
				-- Se busca la cuenta en el maestro de cheques.
				SELECT a.cuenta, c.nombre
					INTO sNumCuenta, sProducto
				FROM bdicheq:sc_maechq a
					JOIN bdicheq:sc_maenoc b ON ( a.cuenta = b.cuenta )
					JOIN bdicheq:sc_producto c ON ( a.producto = c.producto )				
				WHERE a.cuenta = psNumCuenta;
								
				IF ( NVL( sNumCuenta , '' ) <> '' ) THEN				

					SELECT a.numtarjeta, TO_CHAR( a.fechaultmodif, '%d/%m/%Y' ), a.fechaultmodif::DATETIME HOUR TO SECOND, NVL( a.usuarioultmodif, '' )
						INTO sNumTarjeta, sFechaStatusUltMod, sHoraStatusUltMod, sEmpleadoModifico
					FROM intercard:tarjeta a
						JOIN intercard:tarjetacuenta b ON ( a.numtarjeta = b.numtarjeta )
					WHERE a.numtarjeta = psNumTarjeta;

				ELSE
				
					-- Se busca la cuenta en el maestro de pagarés.
					SELECT NVL( a.cuenta, '' ), b.nombre, a.promotor
						INTO sNumCuenta, sProducto, sEmpleadoModifico
					FROM bdinvers:sv_maeinv a
						LEFT OUTER JOIN bdinvers:sv_instrum b ON ( b.cod_instrum = a.cod_instrum )
					WHERE a.empresa = psEmpresa AND a.cuenta = psNumCuenta 
						AND a.secuencia = ( 
							SELECT MAX( secuencia )
							FROM bdinvers:sv_maeinv
							WHERE empresa = psEmpresa AND cuenta = psNumCuenta );
							
					IF ( sNumCuenta <> '' ) THEN
					
						SELECT NVL( cuenta, '' ), TO_CHAR( fech_alt, '%d/%m/%Y' ), fech_hor::DATETIME HOUR TO SECOND
							INTO sNumCuenta, sFechaStatusUltMod, sHoraStatusUltMod
						FROM bdinvers:sv_movdia
						WHERE cuenta = psNumCuenta AND num_serial = (
							SELECT MAX( num_serial ) 
							FROM bdinvers:sv_movdia
							WHERE cuenta = psNumCuenta );
					
					END IF;
				END IF;
				
				-- Se obtiene nombre de ejecutivo.
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoModifico, sNombreEmpMod
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoModifico;
				
				IF ( NVL( sNumCuenta, '' ) = '' OR NVL( sProducto, '' ) = '' OR NVL( sNombreEmpMod, '' ) = '' ) THEN

					LET sCodigoRetorno = '00004'; -- Error al tratar de obtener los datos generales de la cuenta de débito.

				END IF;
				
				RETURN sCodigoRetorno, 
					sProducto, sFechaStatusUltMod, sHoraStatusUltMod, NULL, sEmpleadoModifico, sNombreEmpMod;
						
			-- Datos de la apertura de la cuenta de débito.
			ELIF ( piTipoBusqueda = 3 ) THEN
			
				SELECT a.cuenta, TO_CHAR( b.fecha_alta, '%d/%m/%Y' ), a.sucursal
					INTO sNumCuenta, sFechaStatusAperturaCuenta, sSucursalAperturaCuenta
				FROM bdicheq:sc_maechq a    
					INNER JOIN bdicheq:sc_maenoc b ON ( a.cuenta = b.cuenta )
				WHERE b.empresa = psEmpresa
					AND b.cuenta = psNumCuenta;
				
				IF ( NVL( sNumCuenta, '' ) <> '' ) THEN					
					
					SELECT LIMIT 1 numtarjeta, fechahorainauth::DATETIME HOUR TO SECOND, SUBSTR( idterminal, 5, 8 )
						INTO sNumTarjeta, sHoraStatusAperturaCuenta, sEmpleadoAperturo
					FROM intercard:movimientohistorico 
					WHERE codtran = 95 AND numtarjeta = psNumTarjeta;
					
										
									
						IF ( sNumTarjeta IS NULL ) THEN
					
							SELECT LIMIT 1 numtarjeta, fechahorainauth::DATETIME HOUR TO SECOND, NVL( SUBSTR( idterminal, 5, 8 ), '' )
							INTO sNumTarjeta, sHoraStatusAperturaCuenta, sEmpleadoAperturo
							FROM intercard:movimiento
							WHERE codtran = 95 AND numtarjeta = psNumTarjeta;
					
						END IF;	
				
				ELSE	

					SELECT a.cuenta, TO_CHAR( a.fech_alt, '%d/%m/%Y' ), a.fech_hor::DATETIME HOUR TO SECOND, a.sucursal, a.usuario
						INTO sNumCuenta, sFechaStatusAperturaCuenta, sHoraStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo
					FROM bdinvers:sv_movhis a
					WHERE a.transacc = '0500' AND a.cuenta = psNumCuenta;
					
					IF ( NVL( sNumCuenta, '' ) = '' ) THEN
					
						SELECT a.cuenta, TO_CHAR( a.fech_alt, '%d/%m/%Y' ), a.fech_hor::DATETIME HOUR TO SECOND, a.sucursal, a.usuario
							INTO sNumCuenta, sFechaStatusAperturaCuenta, sHoraStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo
						FROM bdinvers:sv_movdia a
						WHERE a.transacc = '0500' AND a.cuenta = psNumCuenta;
						
					END IF;
				END IF;
				
				-- Se obtiene nombre de ejecutivo.
				SELECT ejecutivo, UPPER( nombre )
					INTO sEmpleadoAperturo, sNombreEmpAperturo
				FROM bdinteg:si_ejecut
				WHERE ejecutivo = sEmpleadoAperturo;
				
				IF ( NVL( sNombreEmpAperturo, '' ) = '' OR NVL( sNumCuenta, '' ) = '' ) THEN
				
					LET sCodigoRetorno = '00005'; --Error al tratar de obtener los datos de la apertura de la cuenta de débito.
					
				END IF;
				
				RETURN sCodigoRetorno, 
					NULL, sFechaStatusAperturaCuenta, sHoraStatusAperturaCuenta, sSucursalAperturaCuenta, sEmpleadoAperturo, sNombreEmpAperturo;			
			
			--Histórico de las cuentas, opción pagarés.
			/*ELIF ( piTipoBusqueda = 4 ) THEN
			
                FOREACH
                    SELECT b.cuenta 
						INTO sCuentaPagare 
                    FROM bdicheq:sc_maechq a 
						LEFT OUTER JOIN bdinvers:sv_maeinv b ON ( a.empresa = b.empresa AND a.cuenta = b.cta_cheques )
                    WHERE a.empresa = psEmpresa AND b.cta_cheques = psNumCuenta

                    IF ( sCuentaPagare <> "" OR sCuentaPagare IS NOT NULL ) THEN

                        FOREACH
                            SELECT a.cuenta, a.status_cta, b.fech_alt, SUBSTR( b.fech_hor, 1, 8 ) AS hora, a.promotor, c.nombre
								INTO sNumCuenta, sEstatusHistorico, vfechamttoaux, sHoraStatusHistorico, sEmpleadoHistorico, sNombreEmpleadoHistorico
                            FROM bdinvers:sv_maeinv a
                                LEFT OUTER JOIN bdinvers:sv_movdia b ON ( b.cuenta = a.cuenta )
                                LEFT OUTER JOIN bdinteg:si_ejecut c ON ( c.ejecutivo = a.promotor )
                            WHERE a.cuenta = sCuentaPagare 
                                AND ( b.transacc = '0500' OR a.status_cta = 4 OR a.status_cta = 2 )

                            LET sFechaEstatusHistorico = '1900-01-01';

                            IF ( vfechamttoaux IS NOT NULL ) THEN

                                LET vDia = LPAD( DAY( vfechamttoaux ), 2, '0' );
                                LET vMes = LPAD( MONTH( vfechamttoaux ), 2, '0' );
                                LET vAnio = YEAR( vfechamttoaux );
                                LET sFechaEstatusHistorico = vAnio || '-' || vMes || '-' || vDia;

                            END IF                                

                            RETURN sCodigoRetorno, 
								sEstatusHistorico, sFechaEstatusHistorico, sHoraStatusHistorico, NULL, sEmpleadoHistorico, sNombreEmpleadoHistorico WITH RESUME;
								
                        END FOREACH
                    END IF;
                END FOREACH;		
						
			--Histórico de las cuentas, opción inversión.
			ELIF ( piTipoBusqueda = 5 ) THEN          
			
                FOREACH
                    SELECT b.cuenta 
						INTO sCuentaInversion 
                    FROM bdicheq:sc_maechq a 
                        LEFT OUTER JOIN bdicheq:sc_maeinstrucc b ON ( a.cuenta = b.cuentadep )                         
                    WHERE a.empresa = psEmpresa AND a.cuenta = psNumCuenta

                    IF ( sCuentaInversion <> "" OR sCuentaInversion IS NOT NULL ) THEN
                        FOREACH
                            SELECT a.cuenta, a.status_cta AS estatus, a.fecha_proceso AS fecha_estatus_can,
                                SUBSTR( a.fecha_proceso, 11, 9 ) AS hora_status_can, a.num_cte, b.nombre 
								INTO sNumCuenta, sEstatusHistorico, vfechamttoaux, sHoraStatusHistorico, sEmpleadoHistorico, sNombreEmpleadoHistorico
                            FROM bdicheq:sc_maechq a 
                                LEFT OUTER JOIN bdicheq:sc_producto b on ( a.producto = b.producto )							
                            WHERE a.empresa = psEmpresa
                                AND a.cuenta  = sCuentaInversion
                                AND ( a.status_cta = 2 OR a.status_cta = 3 )

                            IF ( vfechamttoaux IS NOT NULL ) THEN
							
								LET vDia = LPAD( DAY(vfechamttoaux ), 2, '0' );
                                LET vMes = LPAD( MONTH(vfechamttoaux ), 2, '0' );
								LET vAnio = YEAR( vfechamttoaux );
								LET sFechaEstatusHistorico = vAnio || '-' || vMes || '-' || vDia;

                            END IF;     

                           RETURN sCodigoRetorno, 
							sEstatusHistorico, sFechaEstatusHistorico, sHoraStatusHistorico, NULL, sEmpleadoHistorico, sNombreEmpleadoHistorico WITH RESUME;
							
                        END FOREACH;						
                    END IF;
               END FOREACH;*/
						
			-- Histórico de las cuentas, Cancelación de cuentas débito.
			ELIF ( piTipoBusqueda = 7 ) THEN
			
				SELECT a.cuenta, a.status_cta, TO_CHAR( a.fec_cancelac, '%d/%m/%Y' )
					INTO sNumCuenta, sEstatusHistorico, sFechaEstatusHistorico
				FROM bdicheq:sc_maechq a 
					LEFT OUTER JOIN bdicheq:sc_producto b ON (a.producto = b.producto)
				WHERE status_cta = 3 AND a.cuenta = psNumCuenta;
				
				IF ( sNumCuenta IS NULL ) THEN
				
					FOREACH
						SELECT cuenta, status_cta, TO_CHAR( fec_cancelac, '%d/%m/%Y' )
							INTO sNumCuenta, sEstatusHistorico, sFechaEstatusHistorico
						FROM bdinvers:sv_maeinv
						WHERE cuenta = psNumCuenta AND status_cta IN ( 2, 4 )
						
						RETURN sCodigoRetorno, 
							sEstatusHistorico, sFechaEstatusHistorico, NULL, NULL, NULL, NULL;
							
					END FOREACH;
				
				ELSE
					
					RETURN sCodigoRetorno, 
						sEstatusHistorico, sFechaEstatusHistorico, NULL, NULL, NULL, NULL;
					
				END IF;
				
				IF ( NVL( sFechaEstatusHistorico, '' ) = '' ) THEN
					
					LET sCodigoRetorno = '00007'; -- No tiene cancelación.
					
					RETURN sCodigoRetorno, 
						NULL, NULL, NULL, NULL, NULL, NULL;
				
				END IF;				
						
			END IF;
		ELSE
		
			LET sCodigoRetorno = '00010'; --Error en parámetros de entrada.
			
			RETURN sCodigoRetorno, 
				NULL, NULL, NULL, NULL, NULL, NULL;
			
		END IF;		
	END;
END PROCEDURE
DOCUMENT
'CREADO:		Francisco Rodríguez Ibarra.',
'FECHA:			30 de abril de 2010.',
'DESCRIPCIÓN:	Consulta los datos de la cuenta, ademas que trae el histórico',

'MODIFICÓ:		Ulises Rodríguez Márquez.',
'FECHA:			Lunes, 03 de Enero de 2011.',
'MODIFICACIÓN:	Se reestructuran y optimizan las búsquedas para consultar cuentas de crédito, cheques, inversiones y pagarés.',

'MODIFICÓ:		Ulises Rodríguez Márquez.',
'FECHA:			Miércoles, 26 de Enero de 2011.',
'MODIFICACIÓN:	condición de cuenta existente en la consulta de apertura de cuenta de crédito y agregar filtro de empresa ', 
'				en la consulta de horastatus sobre la tabla bdicred:sd_movhis./mod',

'MODIFICÓ: 		Bernardo Beltrán Herrera',
'FECHA: 		23/01/2014',
'MODIFICACIÓN: 	Se elimina referencia a tabla intercard:movimientohistorico_old.'

;

CREATE PROCEDURE "informix".spconsultarmvtosnip( psEmpresa CHAR(3), psNumTarjeta CHAR(16) )

	RETURNING CHAR(5) AS CodigoRetorno, 
		CHAR(10) AS Fecha, CHAR(9) AS Hora, CHAR(4) AS Sucursal, CHAR(8) AS Empleado, CHAR(45) AS Nombre;

	DEFINE iSqlErr          	INTEGER;
	DEFINE sCodigoRetorno        CHAR(5);
	
	DEFINE sFecha		CHAR(10);
	DEFINE sHora		CHAR(9);
	DEFINE sSucursal	CHAR(4);
	DEFINE sEmpleado	CHAR(8);
	DEFINE sNombre		CHAR(45);
	
	--SET DEBUG FILE TO  "/respaldosbd/ulises/spConsultarMvtosNIP.out";
	--TRACE ON;

	BEGIN
		ON EXCEPTION
			SET iSqlErr
			
			IF iSqlErr <> 0 THEN
			
				LET sCodigoRetorno = iSqlErr;
				
				RETURN sCodigoRetorno, NULL, NULL, NULL, NULL, NULL;
				
			END IF;
		END EXCEPTION;

		--VALIDA PARÁMETROS DE ENTRADA.
		IF ( NVL( psEmpresa, '' ) = '' AND NVL( psNumTarjeta, '' ) ) THEN

			LET sCodigoRetorno = '00001';
			
			RETURN sCodigoRetorno, NULL, NULL, NULL, NULL, NULL;

		END IF;

		LET sFecha 		= '';
		LET sHora 		= '';
		LET sSucursal	= '';
		LET sEmpleado  	= '';
		LET sNombre   	= '';

		FOREACH
			SELECT TO_CHAR( a.fechahorainauth, '%d/%m/%Y' ), a.fechahorainauth::DATETIME HOUR TO SECOND, SUBSTR( a.idterminal, 1, 4 ), 
					SUBSTR( a.idterminal, 5, 8 ), b.nombre
				INTO sFecha, sHora, sSucursal, sEmpleado, sNombre
			FROM intercard:movimientohistorico a
				LEFT OUTER JOIN bdinteg:si_ejecut b ON ( SUBSTR( a.idterminal, 5, 8 ) = b.ejecutivo )
			WHERE a.codtran = 95 AND empresa = psEmpresa AND a.numtarjeta = psNumTarjeta

			LET sCodigoRetorno = '00000';			

			RETURN sCodigoRetorno, sFecha, sHora, sSucursal, sEmpleado, sNombre WITH RESUME;

		END FOREACH;

		FOREACH
			SELECT TO_CHAR( a.fechahorainauth, '%d/%m/%Y' ), a.fechahorainauth::DATETIME HOUR TO SECOND, SUBSTR( a.idterminal, 1, 4 ), SUBSTR( a.idterminal, 5, 8 ), b.nombre
				INTO sFecha, sHora, sSucursal, sEmpleado, sNombre
			FROM intercard:movimiento a
				LEFT OUTER JOIN bdinteg:si_ejecut b ON ( SUBSTR( a.idterminal, 5, 8 ) = b.ejecutivo )
			WHERE a.codtran = 95 AND empresa = psEmpresa AND a.numtarjeta = psNumTarjeta

			LET sCodigoRetorno = '00000';			

			RETURN sCodigoRetorno, sFecha, sHora, sSucursal, sEmpleado, sNombre WITH RESUME;

		END FOREACH;
		
	END
END PROCEDURE
DOCUMENT
'CREADO:		Ulises Rodríguez Márquez.',
'FECHA:			05 de Mayo de 2010.',
'DESCRIPCIÓN:	Consulta los movimientos del mantenimiento de NIP de una tarjeta.',
'RETORNO:		00000 Datos obtenidos satisfactoriamente',
'				00001 Parametros insuficientes.',

'MODIFICÓ: 		Ulises Rodríguez Márquez',
'FECHA: 		06/01/2011',
'MODIFICACIÓN: 	Se agrega la búsqueda sobre la intercard:movimiento.',

'MODIFICÓ: 		Bernardo Beltrán Herrera',
'FECHA: 		24/10/2012',
'MODIFICACIÓN: 	Se agrega la búsqueda sobre la intercard:movimientohistorico_old.',

'MODIFICÓ: 		Bernardo Beltrán Herrera',
'FECHA: 		23/01/2014',
'MODIFICACIÓN: 	Se elimina referencia a la tabla intercard:movimientohistorico_old.'

;

CREATE PROCEDURE "informix".sp_actualiza_gerentes( pEmpresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER; 
    
    DEFINE vcCodRet1    CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE viTrxAbierta SMALLINT;
    DEFINE viContador   INTEGER;
    DEFINE vdFechaHoy   DATE;
    DEFINE vcSucAnt     CHAR(4);
    DEFINE vcSucursal   CHAR(4);
    DEFINE vcEjecutivo  CHAR(8);
    DEFINE vcNombreGte  CHAR(45);
    DEFINE vdFechaIns   DATE;
    
    LET vcCodRet1    = '000';
    LET vcCodRet2    = '000';
    LET vcCodRet3    = 'PROCESO REALIZADO CORRECTAMENTE';
    LET viSqlErr     = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET viTrxAbierta = 0;
    LET viContador   = 0;    
    LET vdFechaHoy   = '';
    LET vcSucAnt     = '';
    LET vcSucursal   = '';
    LET vcEjecutivo  = '';
    LET vcNombreGte  = '';
    LET vdFechaIns   = '';
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/tmp/sp_actualiza_gerentes.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet1 = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            IF viTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcCodRet1, vcCodRet2, vcCodRet3, viContador;
        END IF;
    END EXCEPTION;  
    
    --- SET DEBUG FILE TO "/tmp/sp_actualiza_gerentes.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM si_fechas
     WHERE empresa = pEmpresa;
     
    LET vcSucAnt = '0000';
    
    FOREACH WITH HOLD
        SELECT sucursal, ejecutivo, nombre, fecha_insert
          INTO vcSucursal, vcEjecutivo, vcNombreGte, vdFechaIns
          FROM si_ejecut 
         WHERE sucursal IN ( SELECT sucursal FROM si_sucursales WHERE tpo_sucursal = 'S' )
           AND ejecutivo LIKE '9%'
           AND password NOT IN('BAJA', 'baja')
           AND vigencia > vdFechaHoy
           AND puesto = '001'
         ORDER BY sucursal, fecha_insert
           
        BEGIN WORK;
        LET viTrxAbierta = 1;
        
        IF vcSucursal <> vcSucAnt THEN
            UPDATE si_sucursales
               SET gerente = vcNombreGte
             WHERE sucursal = vcSucursal;
        END IF;
        
        LET vcSucAnt = vcSucursal;
        
        LET viContador = viContador + 1;        
        
        COMMIT WORK;
        LET viTrxAbierta = 0;
        
        LET vcSucursal  = '';
        LET vcEjecutivo = '';
        LET vcNombreGte = '';
        LET vdFechaIns  = '';
    END FOREACH;
    
    END;
    
    RETURN vcCodRet1, vcCodRet2, vcCodRet3, viContador;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_verifica_gerentes( pEmpresa CHAR(3) )
RETURNING CHAR(5), CHAR(5), CHAR(50), INTEGER, INTEGER; 
    
    DEFINE vcCodRet1    CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE viTrxAbierta SMALLINT;
    DEFINE viContador1  INTEGER;
    DEFINE viContador2  INTEGER;
    DEFINE vdFechaHoy   DATE;
    DEFINE vcSucursal   CHAR(4);
    DEFINE vcNombreGte  CHAR(45);
    DEFINE vcPasswd     CHAR(40);
    DEFINE vdVigencia   DATE;
    DEFINE vcNuevoGte   CHAR(45);
    DEFINE vdFechaIns   DATE;
    
    LET vcCodRet1    = '000';
    LET vcCodRet2    = '000';
    LET vcCodRet3    = 'PROCESO REALIZADO CORRECTAMENTE';
    LET viSqlErr	 = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET viTrxAbierta = 0;
    LET viContador1  = 0;
    LET viContador2  = 0;    
    LET vdFechaHoy   = '';
    LET vcSucursal   = '';
    LET vcNombreGte  = '';
    LET vcPasswd     = '';
    LET vdVigencia   = '';
    LET vcNuevoGte   = '';
    LET vdFechaIns   = '';
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/tmp/sp_verifica_gerentes.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet1 = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            IF viTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcCodRet1, vcCodRet2, vcCodRet3, viContador1, viContador2;
        END IF;
    END EXCEPTION;  
    
    --- SET DEBUG FILE TO "/tmp/sp_verifica_gerentes.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM si_fechas
     WHERE empresa = pEmpresa;
     
    FOREACH WITH HOLD
        SELECT sucursal, gerente
          INTO vcSucursal, vcNombreGte
          FROM si_sucursales 
         WHERE sucursal > '0000'
           AND empresa = pEmpresa
           AND tpo_sucursal = 'S'
           
        BEGIN WORK;
        LET viTrxAbierta = 1;
        
        SELECT password, vigencia
          INTO vcPasswd, vdVigencia
          FROM si_ejecut
         WHERE sucursal = vcSucursal
           AND nombre = vcNombreGte;
        
        IF ( vcPasswd IN('BAJA','baja') OR vdVigencia <= vdFechaHoy ) THEN
            FOREACH
                SELECT nombre, fecha_insert
                  INTO vcNuevoGte, vdFechaIns
                  FROM si_ejecut
                 WHERE sucursal = vcSucursal
                   AND puesto = '001'
                   AND ejecutivo LIKE '9%'
                   AND vigencia > vdFechaHoy
                   AND password NOT IN('BAJA', 'baja')
                 ORDER BY fecha_insert
                 
                IF vcNuevoGte is not null OR vcNuevoGte <> '' THEN
                    UPDATE si_sucursales
                       SET gerente = vcNuevoGte
                     WHERE sucursal = vcSucursal;
                     
                    LET viContador2 = viContador2 + 1;   
                    
                    EXIT FOREACH;
                END IF;
            END FOREACH;
        END IF
        
        LET viContador1 = viContador1 + 1;        
        
        COMMIT WORK;
        LET viTrxAbierta = 0;
        
        LET vcSucursal   = '';
        LET vcNombreGte  = '';
        LET vcPasswd     = '';
        LET vdVigencia   = '';
        LET vcNuevoGte   = '';
        LET vdFechaIns   = '';
    END FOREACH;
    
    END;
    
    RETURN vcCodRet1, vcCodRet2, vcCodRet3, viContador1, viContador2;
    
END PROCEDURE;

CREATE PROCEDURE "informix".direcciones( pEmpresa         CHAR(3),
                                         pFuncion         CHAR(1),
                                         pNumCte          CHAR(20),
                                         pSecuencia       SMALLINT,
                                         pTipoDir         CHAR(1),
                                         pCalle           CHAR(40),
                                         pColonia         CHAR(60),
                                         pMunicipio       CHAR(5),
                                         pEntre_Calles    CHAR(40),
                                         pPais            CHAR(3),
                                         pEntidad         CHAR(2),
                                         pLocalidad       CHAR(3),
                                         pCodPostal       CHAR(5),
                                         pTipoTel1        CHAR(1),
                                         pTelefono1       CHAR(13),
                                         pTipoTel2        CHAR(1),
                                         pTelefono2       CHAR(13),
                                         pTipoTel3        CHAR(1),
                                         pTelefono3       CHAR(13),
                                         pExtension       CHAR(5),
                                         pEstado_Inegi    CHAR(2),
                                         pMunicipio_Inegi CHAR(3),
                                         pLocalidad_Inegi CHAR(4),
                                         pNoCiudad        SMALLINT,
                                         pNoExt           CHAR(10),
                                         pNoInt           CHAR(10),
                                         pDepto           CHAR(6),
                                         pNoCalle         INTEGER,
                                         pNoColonia       INTEGER,
                                         pPuntoCar        CHAR(1),
                                         pUniHabi         CHAR(1),
                                         pManz            SMALLINT,
                                         pPOtros          SMALLINT,
                                         pAndador         SMALLINT,
                                         pEtapa           SMALLINT,
                                         pLote            SMALLINT,
                                         pEdif            SMALLINT,
                                         pEntrada         SMALLINT,
                                         pObserva         CHAR(80),
                                         pUser_Insert     CHAR(8),
                                         pFecha_Insert    DATE,
                                         cSucursal        CHAR(4),
                                         pCarrier         SMALLINT )
RETURNING CHAR(5);
    
    DEFINE v_CodRet             CHAR(5);
    DEFINE v_CodRet2            CHAR(5);
    DEFINE v_CodRet3            CHAR(50);
    DEFINE v_SqlErr             INTEGER;
    DEFINE v_IsamErr            INTEGER;
    DEFINE v_DescErr            CHAR(50);
    DEFINE v_NumCte             CHAR(20);
    DEFINE pcoincide_dir        SMALLINT;
    DEFINE o_tipo_dir       	CHAR(1);
    DEFINE o_calle          	CHAR(40);
    DEFINE o_colonia        	CHAR(60);
    DEFINE o_entre_calles   	CHAR(40);
    DEFINE o_pais           	CHAR(3);
    DEFINE o_estado         	CHAR(2);
    DEFINE o_ciudad         	CHAR(3);
    DEFINE o_municipio      	CHAR(5);
    DEFINE o_cod_postal     	CHAR(5);
    DEFINE o_apart_postal   	CHAR(11);
    DEFINE o_telefono1      	CHAR(13);
    DEFINE o_telefono2      	CHAR(13);
    DEFINE o_telefono3      	CHAR(13);
    DEFINE o_extension      	CHAR(5);
    DEFINE o_estado_inegi   	CHAR(2);
    DEFINE o_municipio_inegi	CHAR(3);
    DEFINE o_localidad_inegi    CHAR(4);
    DEFINE o_numerociudad   	SMALLINT;
    DEFINE o_numeroextcalle 	CHAR(10);
    DEFINE o_numerointcalle 	CHAR(10);
    DEFINE o_departamento   	CHAR(6);
    DEFINE o_numerocalle    	INTEGER;
    DEFINE o_numerocolonia  	INTEGER;
    DEFINE o_puntocardinal  	CHAR(1);
    DEFINE o_unidadhabitac  	CHAR(1);
    DEFINE o_manzana        	SMALLINT;
    DEFINE o_otros          	SMALLINT;
    DEFINE o_andador        	SMALLINT;
    DEFINE o_etapa          	SMALLINT;
    DEFINE o_lote           	SMALLINT;
    DEFINE o_edificio       	SMALLINT;
    DEFINE o_entrada        	SMALLINT;
    DEFINE o_observaciones  	CHAR(80);
    DEFINE v_CodRetTel          CHAR(5);
    DEFINE vTipoTel             SMALLINT;
    DEFINE vCanal               SMALLINT;
    DEFINE cSituacionEsp        CHAR(1);  --- VARIABLE DE SITUACIÓN ESPECIAL
    DEFINE iCausa               INTEGER;  --- VARIABLE DE SITUACIÓN ESPECIAL
    
    LET v_CodRet          = '';
    LET v_CodRet2         = '';
    LET v_CodRet3         = '';
    LET v_SqlErr          = 0;
    LET v_IsamErr         = 0;
    LET v_DescErr         = '';
    LET v_NumCte          = '';
    LET pcoincide_dir     = 0;
    LET o_tipo_dir        = '';
    LET o_calle           = '';
    LET o_colonia         = '';
    LET o_entre_calles    = '';
    LET o_pais            = '';
    LET o_estado          = '';
    LET o_ciudad          = '';
    LET o_municipio       = '';
    LET o_cod_postal      = '';
    LET o_apart_postal    = '';
    LET o_telefono1       = '';
    LET o_telefono2       = '';
    LET o_telefono3       = '';
    LET o_extension       = '';
    LET o_estado_inegi    = '';
    LET o_municipio_inegi = '';
    LET o_localidad_inegi = '';
    LET o_numerociudad    = 0;
    LET o_numeroextcalle  = '';
    LET o_numerointcalle  = '';
    LET o_departamento    = '';
    LET o_numerocalle     = 0;
    LET o_numerocolonia   = 0;
    LET o_puntocardinal   = '';
    LET o_unidadhabitac   = '';
    LET o_manzana         = 0;
    LET o_otros           = 0;
    LET o_andador         = 0;
    LET o_etapa           = 0;
    LET o_lote            = 0;
    LET o_edificio        = 0;
    LET o_entrada         = 0;
    LET o_observaciones   = '';
    LET v_CodRetTel       = '';
    LET vTipoTel          = 0;
    LET vCanal            = 1;
    LET cSituacionEsp     = 'N'; --- VARIABLE DE SITUACIÓN ESPECIAL
    LET iCausa            = 0;   --- VARIABLE DE SITUACIÓN ESPECIAL
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/direcciones_carrier.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET v_SqlErr, v_IsamErr, v_DescErr
        SET DEBUG FILE TO "/tmp/direcciones_carrier.err";
        TRACE ON;
        IF v_SqlErr != 0 THEN
            LET v_CodRet = v_SqlErr;
            LET v_CodRet2 = v_IsamErr;
            LET v_CodRet3 = v_DescErr;
            RETURN v_CodRet;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    LET v_CodRet = "000";
    LET pEntidad = CAST( LPAD (TRIM(pEntidad), 2 ,  "0") AS CHAR(2));

    SELECT numcte 
      INTO v_NumCte 
      FROM "informix".si_cliente
     WHERE numcte = pNumCte;
     
    IF v_NumCte IS NULL THEN
        LET v_CodRet = "104";
        RETURN v_CodRet;
    END IF

    IF pFuncion = "C" THEN
        DELETE FROM "informix".si_direcciones
         WHERE numcte = pNumCte 
           AND secuencia = pSecuencia;
           
        DELETE FROM "informix".si_direcciones_actual
         WHERE numcte = pNumCte 
           AND secuencia = pSecuencia;
           
        LET pFuncion = "A";
    END IF

    IF pFuncion = "A" THEN
		-- // CGP SE TOMA LA SECUENCIA DE LA TABLA MAESTRA si_direcciones
        SELECT MAX(secuencia) 
          INTO pSecuencia
          FROM "informix".si_direcciones 
         WHERE numcte = pNumCte;
         
        IF pSecuencia IS NULL THEN
            LET pSecuencia = 1;
        ELSE
            LET pSecuencia = pSecuencia + 1;
            LET cSituacionEsp = 'S';
        END IF;
        
        -- // SE AGREGA VALIDACIÓN PARA SI LA CLAVE DEL MUNICIPIO VIENE VACIO, LE ASIGNE  "00000".
        IF pMunicipio = "" OR pMunicipio is null THEN
            LET pMunicipio = LPAD(TRIM(NVL(pMunicipio,"00000")),5,"0");
        END IF;
        
        -- // VALIDA LA INFORMACION DE LA DIRECCION DEL CLIENTE
        SELECT tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,
               estado_inegi, municipio_inegi, localidad_inegi, numerociudad, 
               numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
               puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones
          INTO o_tipo_dir, o_calle, o_colonia, o_entre_calles, o_pais, o_estado, o_ciudad, o_municipio, o_cod_postal, o_apart_postal,
               o_estado_inegi, o_municipio_inegi, o_localidad_inegi, o_numerociudad, 
               o_numeroextcalle, o_numerointcalle, o_departamento, o_numerocalle, o_numerocolonia, 
               o_puntocardinal, o_unidadhabitac, o_manzana, o_otros, o_andador, o_etapa, o_lote, o_edificio, o_entrada, o_observaciones
          FROM "informix".si_direcciones_actual
         WHERE numcte = pNumCte
           AND tipo_dir = pTipoDir;
           
        IF ( o_tipo_dir is not null 
             AND o_calle = pCalle 
             AND o_colonia = pColonia 
             AND o_entre_calles = pEntre_Calles 
             AND o_pais = pPais 
             AND o_estado = pEntidad  
             AND o_ciudad = pLocalidad  
             AND o_municipio = pMunicipio  
             AND o_cod_postal = pCodPostal 
             AND o_estado_inegi = pEstado_Inegi
             AND o_municipio_inegi = pMunicipio_Inegi
             AND o_localidad_inegi = pLocalidad_Inegi
             AND o_numerociudad = pNoCiudad
             AND o_numeroextcalle = pNoExt
             AND o_numerointcalle = pNoInt
             AND o_departamento = pDepto
             AND o_numerocalle = pNoCalle
             AND o_numerocolonia = pNoColonia
             AND o_puntocardinal = pPuntoCar
             AND o_unidadhabitac = pUniHabi
             AND o_manzana = pManz
             AND o_otros = pPOtros
             AND o_andador  = pAndador
             AND o_etapa = pEtapa
             AND o_lote = pLote
             AND o_edificio = pEdif
             AND o_entrada = pEntrada
             AND o_observaciones = pObserva ) THEN
            LET pcoincide_dir = 1;
        ELSE
            LET pcoincide_dir = 0;
        END IF;

        IF ( pcoincide_dir <= 0 ) THEN
            INSERT INTO "informix".si_direcciones
            ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,
              estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, 
              departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, otros, 
              andador, etapa, lote, edificio, entrada, observaciones, user_insert, fecha_insert )
            VALUES
            ( pNumCte, pSecuencia, pTipoDir, pCalle, pColonia, pEntre_Calles, pPais, pEntidad, pLocalidad, pMunicipio, pCodPostal, "",
              pEstado_Inegi, pMunicipio_Inegi, pLocalidad_Inegi, pNoCiudad, pNoExt, pNoInt,
              pDepto, pNoCalle, pNoColonia, pPuntoCar, pUniHabi, pManz, pPOtros,
              pAndador, pEtapa, pLote, pEdif, pEntrada, pObserva, pUser_Insert, pFecha_Insert );
        END IF;
        
        -- // VALIDA LA INFORMACIÓN DE LOS TELEFONOS DEL CLIENTE
        SELECT telefono
          INTO o_telefono1
          FROM "informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        IF o_telefono1 is null THEN
            LET o_telefono1 = ' ';
        END IF;
           
        IF o_telefono1 <> pTelefono1 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel1 is not null AND pTipoTel1 <> '' ) AND ( pTelefono1 is not null AND pTelefono1 <> '' ) ) THEN
                LET vTipoTel = 1;
                CALL "informix".sp_registra_telefonos(pEmpresa, pNumCte, pTelefono1, vTipoTel, '', 0, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
           
        SELECT telefono
          INTO o_telefono2
          FROM "informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
           
        IF o_telefono2 is null THEN
            LET o_telefono2 = ' ';
        END IF;
           
        IF o_telefono2 <> pTelefono2 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel2 is not null AND pTipoTel2 <> '' ) AND ( pTelefono2 is not null AND pTelefono2 <> '' ) ) THEN
                LET vTipoTel = 2;
                CALL "informix".sp_registra_telefonos(pEmpresa, pNumCte, pTelefono2, vTipoTel, '', pCarrier, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
           
        SELECT telefono, extension
          INTO o_telefono3, o_extension
          FROM "informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 3;
           
        IF o_telefono3 is null THEN
            LET o_telefono3 = ' ';
        END IF;
           
        IF o_telefono3 <> pTelefono3 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel3 is not null AND pTipoTel3 <> '' ) AND ( pTelefono3 is not null AND pTelefono3 <> '' ) ) THEN
                LET vTipoTel = 3;
                CALL "informix".sp_registra_telefonos(pEmpresa, pNumCte, pTelefono3, vTipoTel, pExtension, 0, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
        
        -- // VALIDACIÓN DE SITUACIÓN ESPECIAL
        IF pTipoDir = '1' AND cSituacionEsp = 'S' THEN
            SELECT LIMIT 1 NVL(situacion,''), causa
              INTO cSituacionEsp, iCausa
              FROM bdisitesp:"informix".se_ctessitespcte
             WHERE numcte = pNumCte;

            IF cSituacionEsp = 'L' THEN
                DELETE FROM bdisitesp:"informix".se_ctessitespcte 
                 WHERE numcte = pNumCte 
                   AND situacion = 'L';

                INSERT INTO bdisitesp:"informix".se_ctessitespcte_his
                (empresa, sucursal, numcte, situacion, causa, tipomovto, empleadoefectuo, usralta, fchmodifica)
                VALUES
                (pEmpresa, cSucursal, pNumCte, cSituacionEsp, iCausa, 'B', pUser_Insert, pUser_Insert, pFecha_Insert);
            END IF;
        END IF;

        RETURN v_CodRet;
    END IF;
    
    END;
    
END PROCEDURE

