CREATE PROCEDURE "informix".actualiza_indicadores( pIndCierreChq CHAR(1), 
                                                   pIndDispChq   CHAR(1), 
                                                   pIndCierreCrd CHAR(1), 
                                                   pIndDispCrd   CHAR(1),
                                                   pIndCierreInv CHAR(1), 
                                                   pIndDispInv   CHAR(1),
                                                   pIndCierreSer CHAR(1), 
                                                   pMotivo       CHAR(50),
                                                   pUsuario      CHAR(8) )
RETURNING CHAR(5);  --- CODIGO DE RETORNO
       
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    
    DEFINE vcCierreCred CHAR(1);
    DEFINE vcDisponCred CHAR(1);
    DEFINE vcCierreCheq CHAR(1);
    DEFINE vcDisponCheq CHAR(1);
    DEFINE vcCierreInv  CHAR(1);
    DEFINE vcDisponInv  CHAR(1);
    DEFINE vcCierreServ CHAR(1);
    
    LET viSqlErr     = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET vcCodRet     = '000';
    LET vcCodRet2    = '';
    LET vcCodRet3    = '';
    
    LET vcCierreCred = '';
    LET vcDisponCred = '';
    LET vcCierreCheq = '';
    LET vcDisponCheq = '';
    LET vcCierreInv  = '';
    LET vcDisponInv  = '';
    LET vcCierreServ = '';
    
    --- SET DEBUG FILE TO "/tmp/actualiza_indicadores.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/tmp/actualiza_indicadores.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF ( pIndCierreChq is null OR pIndCierreChq = '' ) OR 
       ( pIndDispChq is null OR pIndDispChq = '' ) OR
       ( pIndCierreCrd is null OR pIndCierreCrd = '' ) OR
       ( pIndDispCrd is null OR pIndDispCrd = '' ) OR
       ( pIndCierreInv is null OR pIndCierreInv = '' ) OR
       ( pIndDispInv is null OR pIndDispInv = '' ) OR
       ( pIndCierreSer is null OR pIndCierreSer = '' ) OR
       ( pMotivo is null OR pMotivo = '' ) OR
       ( pUsuario is null OR pUsuario = '' ) THEN
        LET vcCodRet = '110';
        RETURN vcCodRet;
    END IF;
    
    -- // OBTIENE LOS INDICADORES
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreCheq, vcDisponCheq
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
     
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreCred, vcDisponCred
      FROM bdicred:sd_fechas
     WHERE empresa = '001';
       
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreInv, vcDisponInv
      FROM bdinvers:sv_fechas
     WHERE empresa = '001';
     
    SELECT NVL(ind_cierre, '0')
      INTO vcCierreServ
      FROM bdisac:sac_fechas
     WHERE empresa = '001';
    
    -- // ACTUALIZA LOS INDICADORES
    UPDATE bdicheq:sc_fechas
       SET ind_cierre = pIndCierreChq,
           ind_disponible = pIndDispChq
     WHERE empresa = '001';
    
    UPDATE bdicred:sd_fechas
       SET ind_cierre = pIndCierreCrd,
           ind_disponible = pIndDispCrd
     WHERE empresa = '001';
     
    UPDATE bdinvers:sv_fechas
       SET ind_cierre = pIndCierreInv,
           ind_disponible = pIndDispInv
     WHERE empresa = '001';
     
    UPDATE bdisac:sac_fechas
       SET ind_cierre = pIndCierreSer
     WHERE empresa = '001';
     
    -- // GUARDA REGISTRO EN LA BITACORA
    INSERT INTO si_bitacora_cierre VALUES
    ( '001', vcCierreCheq, vcDisponCheq, pIndCierreChq, pIndDispChq,
      vcCierreCred, vcDisponCred, pIndCierreCrd, pIndDispCrd,
      vcCierreInv, vcDisponInv, pIndCierreInv, pIndDispInv,
      vcCierreServ, pIndCierreSer, CURRENT, pUsuario, pMotivo );
    
    RETURN vcCodRet;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".consulta_indicadores()
RETURNING CHAR(5),   --- CODIGO DE RETORNO
          CHAR(40),  --- EMPRESA
          DATE,      --- FECHA
          CHAR(1),   --- INDICADOR CIERRE CHEQUES
          CHAR(1),   --- INDICADOR DISPONIBILIDAD CHEQUES
          CHAR(1),   --- INDICADOR CIERRE CREDITO
          CHAR(1),   --- INDICADOR DISPONIBILIDAD CREDITO
          CHAR(1),   --- INDICADOR CIERRE INVERSIONES
          CHAR(1),   --- INDICADOR DISPONIBILIDAD INVERSIONES
          CHAR(1),   --- INDICADOR CIERRE SERVICIOS
          CHAR(20),  --- FECHA HORA
          CHAR(50);  --- DESCRIPCION CAMBIO
       
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    
    DEFINE vcEmpresa    CHAR(40);
    DEFINE vdFechaHoy   DATE;
    DEFINE vcCierreCred CHAR(1);
    DEFINE vcDisponCred CHAR(1);
    DEFINE vcCierreCheq CHAR(1);
    DEFINE vcDisponCheq CHAR(1);
    DEFINE vcCierreInv  CHAR(1);
    DEFINE vcDisponInv  CHAR(1);
    DEFINE vcCierreServ CHAR(1);
    DEFINE vcFechaHora  CHAR(20);
    DEFINE vcDescMotivo CHAR(50);
    
    LET viSqlErr     = 0;
    LET viIsamErr    = 0;
    LET vcDescErr    = '';
    LET vcCodRet     = '000';
    LET vcCodRet2    = '';
    LET vcCodRet3    = '';
    
    LET vcEmpresa    = '';
    LET vdFechaHoy   = '';
    LET vcCierreCred = '';
    LET vcDisponCred = '';
    LET vcCierreCheq = '';
    LET vcDisponCheq = '';
    LET vcCierreInv  = '';
    LET vcDisponInv  = '';
    LET vcCierreServ = '';
    LET vcFechaHora  = '';
    LET vcDescMotivo = '';
    
    --- SET DEBUG FILE TO "/tmp/consulta_indicadores.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/tmp/consulta_indicadores.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet, vcEmpresa, vdFechaHoy, vcCierreCheq, vcDisponCheq, vcCierreCred, vcDisponCred, vcCierreInv, vcDisponInv, vcCierreServ, vcFechaHora, vcDescMotivo;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    SELECT TRIM(empresa)||' '||TRIM(razon_social)
      INTO vcEmpresa
      FROM si_empresas
     WHERE empresa = '001';
     
    SELECT fecha_hoy, fecha_insert
      INTO vdFechaHoy, vcFechaHora
      FROM si_fechas
     WHERE empresa = '001';
    
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreCheq, vcDisponCheq
      FROM bdicheq:sc_fechas
     WHERE empresa = '001';
     
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreCred, vcDisponCred
      FROM bdicred:sd_fechas
     WHERE empresa = '001';
     
    SELECT NVL(ind_cierre, '0'), NVL(ind_disponible, '0')
      INTO vcCierreInv, vcDisponInv
      FROM bdinvers:sv_fechas
     WHERE empresa = '001';
     
    SELECT NVL(ind_cierre, '0')
      INTO vcCierreServ
      FROM bdisac:sac_fechas
     WHERE empresa = '001';
     
    SELECT motivo_cambio
      INTO vcDescMotivo
      FROM si_bitacora_cierre
     WHERE fecha_cambio::date = vdFechaHoy
       AND fecha_cambio = ( SELECT MAX(fecha_cambio) FROM si_bitacora_cierre WHERE fecha_cambio::date = vdFechaHoy );
    
    RETURN vcCodRet, vcEmpresa, vdFechaHoy, vcCierreCheq, vcDisponCheq, vcCierreCred, vcDisponCred, vcCierreInv, vcDisponInv, vcCierreServ, vcFechaHora, vcDescMotivo;

    END;

END PROCEDURE;

create procedure "informix".fechas( pempresa char(3) )
returning char(5);

    define vcodret      char(5);
    define vcodret2     char(5);
    define vcodret3     char(50);
    define vsqlerr      integer;
    define visamerr     integer;
    define vdescerr     char(50);
    
    let vcodret     = '000';
    let vcodret2    = '';
    let vcodret3    = '';
    let vsqlerr     = 0;
    let visamerr    = 0;
    let vdescerr    = '';

    begin
    
    on exception set vsqlerr, visamerr, vdescerr
        set debug file to "/tmp/fechas_int.out";
        trace on;
        if vsqlerr <> 0 then
            let vcodret = vsqlerr;
            let vcodret2 = visamerr;
            let vcodret3 = vdescerr;
            return vcodret;
        end if;
    end exception;

    --- set debug file to "/resplogifx/conciliachq/fechasinv.out";
    --- trace on;
    
    set isolation to dirty read;
    set lock mode to wait 3;
    
    -- // ACTUALIZA INDICADOR DE CIERRE FINALIZADO
    update si_fechas
       set fecha_insert = current
     where empresa = pempresa;
    
    return vcodret;
    
    end;
    
end procedure;

CREATE PROCEDURE "informix".verifica_sistemas()
RETURNING CHAR(5),  --- CODIGO DE RETORNO
          CHAR(1),  --- INDICADOR CIERRE CREDITO
