     WHERE empresa = '001';
    
    RETURN vcCodRet, vcCierreCred, vcDisponCred, vcCierreCheq, vcDisponCheq, vcCierreInv, vcDisponInv, vcCierreServ;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarcte_monitor(pEmpresa char (3), pNumero char(16), pTipo integer)
	returning char (5), char (9), char (26), char (26), char (26), char (26),char (16), char (16);

   --Elaboró: Javier A. Chávez T.
   --Actividad: consulta los datos de un cliente
   --Solicito: Mauricio León
   --Fecha: 25-03-09
   --BD:bdinteg
   ---------------------------------------------
   --Modificado: Manuel Osuna Valencia
   --Actividad: Presentar la ultima tarjeta del Titular
   --Solicito: Ismael Hernandez
   --Fecha: 15-07-2009
   --BD:bdinteg
   ---------------------------------------------
   --Modificado: Jose Ruben Lopez
   --Actividad: Buscar por num credito que no tenga tarjeta
   --Solicito: Jose de Jesus Nevarez
   --Fecha:24-09-2013
   --BD:bdinteg
   ---------------------------------------------
   --Modificado: José de Jesús Nevarez
   --Actividad: Se agrega búsqueda por número de cliente para los créditos que no tienen tarjeta.
   --Solicito: Abrham Lopez.
   --Fecha:17-02-2014
   --BD:bdinteg
   
   --DEFINE
    DEFINE cod_ret char(5);
    DEFINE sql_err integer ;
	DEFINE vNomCte1 char (26);
	DEFINE vNomCte2 char (26);
	DEFINE vApe_pat char (26);
	DEFINE vApe_mat char (26);
	DEFINE vNumCte char(9);
	DEFINE vNumTarjeta char (16);
	DEFINE vNumCredito char (16);

	--Inicializa
	LET cod_ret  = "004";
	LET vNomCte1 = "";
	LET vNumCte = "0";
	LET vNumTarjeta = "0";
	LET vNumCredito = "0";
	LET vNomCte2 = "";
	LET vApe_pat = "";
	LET vApe_mat = "";

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret, vNumcte, vNomCte1, vNomCte2, vApe_pat, vApe_mat, vNumCredito, vNumTarjeta;
      END IF ;
   END EXCEPTION ;
   
   --SET DEBUG FILE TO "/tmp/sp_consultarcte_monitor.out";                      --*
   --TRACE ON;       

    SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ ;

	IF (TRIM(pNumero) <> "" and pTipo = 1) THEN  --Por Número de Cliente
			IF EXISTS (SELECT numcte FROM bdinteg:"informix".si_cliente WHERE numcte = pNumero and empresa = pEmpresa)THEN
				SELECT a.nombre1, a.nombre2, a.apell_paterno, a.apell_materno, ta.num_credito, ta.num_tarjeta	
				INTO vNomCte1, vNomCte2, vApe_pat, vApe_mat,vNumCredito,vNumTarjeta
				FROM bdinteg:"informix".si_cliente a,
					 table( multiset( select num_tarjeta,num_credito from bdicred:"informix".sd_tarjeta where  numcte = pNumero and empresa = pEmpresa 
									  and  tipo_tarjeta = 'T' and secuencia = (select max(secuencia) from bdicred:"informix".sd_tarjeta  
						              where numcte = pNumero and  tipo_tarjeta = 'T' and empresa = pEmpresa )
					               )) as  ta
                WHERE a.numcte = pNumero AND a.empresa = pEmpresa;

				
				IF(vNomCte1 <> "") THEN
					LET vNumCte = pNumero;
					LET cod_ret = "000";

				ELIF EXISTS (SELECT num_credito FROM bdicred:"informix".sd_maecredcrd WHERE numcte=pNumero)THEN
						SELECT a.nombre1, a.nombre2, a.apell_paterno, a.apell_materno, ta.num_credito,ta.numcte	
						INTO vNomCte1, vNomCte2, vApe_pat, vApe_mat,vNumCredito,vNumCte				
						FROM bdinteg:"informix".si_cliente a INNER JOIN bdicred:"informix".sd_maecredcrd ta ON a.numcte = ta.numcte
						WHERE ta.numcte =pNumero AND a.empresa = pEmpresa;
						
						IF(vNomCte1 <> "") THEN
							LET vNumCte = pNumero;
							LET cod_ret = "000";
						ELSE
							LET cod_ret = '004';
						END IF;
				END IF;
			
			ELSE
				LET cod_ret = "001"; -- No existe el cliente

			END IF;

	ELIF (TRIM(pNumero) <> "" AND pTipo = 2) THEN --Por Número de Crédito
			IF EXISTS (SELECT num_credito FROM bdicred:"informix".sd_tarjeta WHERE num_credito = pNumero and empresa = pEmpresa) THEN				
				SELECT a.nombre1, a.nombre2, a.apell_paterno, a.apell_materno, ta.num_credito, ta.num_tarjeta,ta.numcte	
				INTO vNomCte1, vNomCte2, vApe_pat, vApe_mat,vNumCredito,vNumTarjeta,vNumCte				
				FROM bdinteg:"informix".si_cliente a,
					table( multiset( select num_tarjeta,num_credito,numcte  from bdicred:"informix".sd_tarjeta where  num_credito =  pNumero 
									 and empresa = pEmpresa and  tipo_tarjeta = 'T'
			                         and secuencia = (select max(secuencia) from bdicred:"informix".sd_tarjeta  where num_credito =  pNumero 
									 and  tipo_tarjeta = 'T' and empresa = pEmpresa )
								   )) as  ta
			    WHERE a.numcte = ta.numcte AND a.empresa = '001';

				IF(vNomCte1 <> "") THEN
					LET vNumCredito = pNumero;
					LET cod_ret = "000";
				ELSE
					LET cod_ret = '004';
				END IF;

			ELSE
				IF EXISTS (SELECT num_credito FROM bdicred:"informix".sd_maecredcrd WHERE num_credito=pNumero)THEN
					SELECT a.nombre1, a.nombre2, a.apell_paterno, a.apell_materno, ta.num_credito,ta.numcte	
					INTO vNomCte1, vNomCte2, vApe_pat, vApe_mat,vNumCredito,vNumCte				
					FROM bdinteg:"informix".si_cliente a INNER JOIN bdicred:"informix".sd_maecredcrd ta ON a.numcte = ta.numcte
					WHERE ta.num_credito =pNumero AND a.empresa = '001';
					
					IF(vNomCte1 <> "") THEN
						LET vNumCredito = pNumero;
						LET cod_ret = "000";
					ELSE
						LET cod_ret = '004';
					END IF;
				ELSE
					LET cod_ret = "002";	
				END IF;
			END IF;
	ELIF (TRIM(pNumero) <> "" AND pTipo = 3) THEN --  --Por Número de Tarjeta
			IF EXISTS (SELECT num_tarjeta FROM bdicred:"informix".sd_tarjeta WHERE num_tarjeta = pNumero and empresa = pEmpresa) THEN
				SELECT numcte,num_credito INTO vNumCte, vNumCredito FROM bdicred:"informix".sd_tarjeta where num_tarjeta = pNumero and empresa = pEmpresa;
				select nombre1, nombre2, apell_paterno, apell_materno INTO vNomCte1, vNomCte2, vApe_pat, vApe_mat
				from  bdinteg:"informix".si_cliente where numcte = vNumCte and empresa = pEmpresa;

				IF(vNomCte1 <> "") THEN
					LET vNumTarjeta = pNumero;
					LET cod_ret = "000";
				ELSE
					LET cod_ret = '004';
				END IF

			ELSE
				LET cod_ret = "003";
			END IF
	ELIF (TRIM(pNumero) == "")THEN
				LET cod_ret = "005";
	END IF;
  
   RETURN cod_ret, vNumcte, vNomCte1, vNomCte2, vApe_pat, vApe_mat, vNumCredito, vNumTarjeta;
   
END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualiza_status_token_bei(pEmpresa char (3), pNumCte char(9), pStatus char(3), pNSToken char(10))
	RETURNING char (5), integer;

--Realizó: Manuel Ramos Figueroa
--Fecha: 26/08/2011
--Actividad: Actualiza el status y fecha de status del token asignado al cliente
--Realizó: Jose Ruben Lopez Hernandez
--Fecha: 26/03/2013
--Actividad: Se agrego la ejecucion del sp sp_set_statustoken_admtoken

DEFINE sql_err integer;
DEFINE cCod_ret char (5);
DEFINE statusAntToken char(3);
LET sql_err = '';
LET cCod_ret = '000';

BEGIN

 ON EXCEPTION SET sql_err
          LET cCod_ret = sql_err;
      RETURN  cCod_ret, 0;
   END EXCEPTION;

	SET LOCK MODE TO WAIT 3 ;
	SET ISOLATION DIRTY READ ;
	--Se obtiene estatus viejo del token a actualizar
	SELECT id_status_token
	INTO statusAntToken
	FROM bdinteg:"informix".si_bpitokenpm WHERE num_cliente = pNumCte AND ns_token = pNSToken; 
	
	
   IF EXISTS(SELECT num_cliente FROM bdinteg:"informix".si_bpiusuariospm WHERE num_cliente = pNumcte AND empresa = pEmpresa) THEN
			EXECUTE PROCEDURE bdibpi:"informix".sp_set_statustoken_admtoken(pNSToken,statusAntToken, pStatus,'transBEI','03') 
			into cCod_ret;
			if cCod_ret<>'001' THEN
				UPDATE bdinteg:"informix".si_bpitokenpm SET id_status_token = pStatus, f_status = CURRENT 
				WHERE empresa = pEmpresa AND num_cliente = pNumCte AND ns_token = pNSToken;
			ELSE
			LET	cCod_ret='002';			END IF;
			
	ELSE
		LET cCod_ret = '001'; -- El cliente No existe
	END IF;
	
	RETURN cCod_ret, pStatus;

END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_validanombrefechanac(pNombre1Cte CHAR(40), 
													pNombre2Cte CHAR(40),
													pApePatCte CHAR(40),  
													pApeMatCte CHAR(40), 
													pFechaNacCte CHAR(10), 
													pNombre1Comparar CHAR(40),
													pNombre2Comparar CHAR(40),
													pApePatComparar CHAR(40),
													pApeMatComparar CHAR(40),
													pFechaNacComparar CHAR(10))
RETURNING CHAR(5) 		As CodRet,  
		  DECIMAL(6,0)  AS Porcentaje;

--DEFINICION DE VARIABLES--
DEFINE iSql_err      		INT;
DEFINE cCodRet      		CHAR(5);
DEFINE iCoicidencia 		INTEGER;
DEFINE iCantidad    		INTEGER;
DEFINE iSuma        		INTEGER;
DEFINE cAnioCte				CHAR(4);
DEFINE cMesCte				CHAR(2);
DEFINE cDiaCte				CHAR(2);
DEFINE cAnioCteComp			CHAR(4);
DEFINE cMesCteComp			CHAR(2);
DEFINE cDiaCteComp			CHAR(2);
DEFINE cFechaNacCte			CHAR(8);
DEFINE cFechaNacComparar	CHAR(8);
DEFINE cNomCompCte   		CHAR(169);
DEFINE cNomCompComparar     CHAR(169);
DEFINE dPorcentaje  		DECIMAL(6,0);
DEFINE dPorcentaje2  		DECIMAL(6,0);
DEFINE dPorcMax      		DECIMAL(6,0);	
DEFINE dPorciento    		DECIMAL(6,0);

--INICIALIZACION DE VARIABLES--
LET iSql_err 			= 0;
LET cCodRet 			= '00000';
LET dPorcentaje 		= 0;
LET dPorcentaje2 		= 0; 
LET iCoicidencia 		= 0;
LET iCantidad 			= 0;
LET cDiaCte  			= SUBSTRING(pFechaNacCte FROM 1 FOR 2);
LET cMesCte  			= SUBSTRING(pFechaNacCte FROM 4 FOR 2);
LET cAnioCte 			= SUBSTRING(pFechaNacCte FROM 7 FOR 4);
LET cDiaCteComp 		= SUBSTRING(pFechaNacComparar FROM 1 FOR 2);
LET cMesCteComp 		= SUBSTRING(pFechaNacComparar FROM 4 FOR 2);
LET cAnioCteComp 		= SUBSTRING(pFechaNacComparar FROM 7 FOR 4);
LET cFechaNacCte		= '';
LET cFechaNacComparar	= '';
LET cNomCompCte			= '';
LET dPorcMax 			= 0;
LET dPorciento 			= 0;
LET iSuma 				= 0;

BEGIN

    ON EXCEPTION SET iSql_err
        IF iSql_err <> 0 THEN
            LET cCodRet = iSql_err;
            RETURN cCodRet, dPorcentaje;
        END IF;
    END EXCEPTION;
	
	--SET DEBUG FILE TO "/home/tmp/leonardo/sp_validanombrefechanac.out";
	--TRACE ON;


	IF  NVL(pNombre1Cte,'') = '' OR NVL(pApePatCte,'') = '' OR NVL(pFechaNacCte,'') = '' OR NVL(pNombre1Comparar,'') = '' OR NVL(pApePatComparar,'') = '' OR NVL(pFechaNacComparar,'') = '' THEN
		LET cCodRet =   '00001'; --Faltan parámetros
		RETURN cCodRet, dPorcentaje;
	END IF;
	
	LET cFechaNacCte = cDiaCte || cMesCte || cAnioCte;
	LET cFechaNacComparar = cDiaCteComp || cMesCteComp || cAnioCteComp;
	
	--Validamos el primer nombre
	EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres (TRIM(pNombre1Cte),TRIM(pNombre1Comparar))  
	INTO cCodRet, iCoicidencia;
	IF cCodRet = '00000' THEN
		LET iSuma = iSuma + iCoicidencia;
		LET iCantidad  =  iCantidad + LENGTH(TRIM(pNombre1Cte));
	ELSE
		RETURN cCodRet, dPorcentaje;
	END IF;	
	
	--Validamos el segundo nombre y validamos ya que no esobligatorio
	IF NVL(pNombre2Cte,'') <> '' AND NVL(pNombre2Comparar,'') <> '' THEN
		EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres (TRIM(pNombre2Cte), TRIM(pNombre2Comparar)) 
		INTO cCodRet, iCoicidencia;
		IF cCodRet = '00000' THEN
			LET iSuma = iSuma + iCoicidencia;
			LET iCantidad  =  iCantidad + LENGTH(TRIM(pNombre2Cte));
		ELSE
			RETURN cCodRet, dPorcentaje;
		END IF;
	ELSE
   	    LET iCoicidencia = 0;
		LET iSuma = iSuma + iCoicidencia;
		LET iCantidad  =  iCantidad + LENGTH(TRIM(pNombre2Cte));
	END IF;

	EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres (TRIM(pApePatCte), TRIM(pApePatComparar))  
	INTO cCodRet, iCoicidencia;
	IF cCodRet = '00000' THEN
		LET iSuma = iSuma + iCoicidencia;
		LET iCantidad  =  iCantidad + LENGTH(TRIM(pApePatCte));
	ELSE
		RETURN cCodRet, dPorcentaje;
	END IF;	
	
	IF NVL(pApeMatCte,'') <> '' AND NVL(pApeMatComparar,'') <> '' THEN
		EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres (TRIM(pApeMatCte), TRIM(pApeMatComparar)) 
		INTO cCodRet, iCoicidencia;
		IF cCodRet = '00000' THEN
			LET iSuma = iSuma + iCoicidencia;
			LET iCantidad  =  iCantidad + LENGTH(TRIM(pApeMatCte));
		ELSE
			RETURN cCodRet, dPorcentaje;
		END IF;		
	ELSE
   	    LET iCoicidencia = 0;
		LET iSuma = iSuma + iCoicidencia;
		LET iCantidad  =  iCantidad + LENGTH(TRIM(pApeMatCte));
	END IF;

	EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres (TRIM(cFechaNacCte), TRIM(cFechaNacComparar))  
	INTO cCodRet, iCoicidencia;
	IF cCodRet = '00000' THEN
		LET iSuma = iSuma + iCoicidencia;
		LET iCantidad  =  iCantidad + LENGTH(TRIM(cFechaNacCte));
	ELSE
		RETURN cCodRet, dPorcentaje;
	END IF;	

	LET dPorcentaje = CAST(iSuma / iCantidad * 100 AS DECIMAL(6,0));
	LET dPorcMax = dPorcentaje;
	LET iSuma = 0;
	LET iCantidad  =  0;

	-- Concatenación del Nombre Completo
	LET cNomCompCte = TRIM(pNombre1Cte);
	LET cNomCompCte = TRIM(cNomCompCte)||' '||TRIM(pNombre2Cte);
	LET cNomCompCte = TRIM(cNomCompCte)||' '||TRIM(pApePatCte);
	LET cNomCompCte = TRIM(cNomCompCte)||' '||TRIM(pApeMatCte);
	LET cNomCompCte = TRIM(cNomCompCte)||' '||TRIM(cFechaNacCte);
	LET cNomCompComparar = TRIM(pNombre1Comparar);
	LET cNomCompComparar = TRIM(cNomCompComparar)||' '||TRIM(pNombre2Comparar);
	LET cNomCompComparar = TRIM(cNomCompComparar)||' '||TRIM(pApePatComparar);
	LET cNomCompComparar = TRIM(cNomCompComparar)||' '||TRIM(pApeMatComparar);
	LET cNomCompComparar = TRIM(cNomCompComparar)||' '||TRIM(cFechaNacComparar);	
	
	LET cNomCompCte = TRIM(cNomCompCte);
	LET cNomCompComparar = TRIM(cNomCompComparar);
	
	EXECUTE PROCEDURE bdinteg:"informix".sp_comparacaracteres(TRIM(cNomCompCte ), TRIM(cNomCompComparar))  --VALIDAR NOMBRE COMPLETO CARACTER POR CARACTER
	INTO cCodRet, iCoicidencia;
	
	IF cCodRet = '00000' THEN
		LET iSuma = iCoicidencia;
		LET iCantidad = LENGTH(TRIM(cNomCompCte));
	ELSE
        RETURN cCodRet, dPorciento;	
	END IF;

	LET dPorcentaje2 =  CAST(iSuma / iCantidad * 100 AS DECIMAL(6,0));
	
	IF dPorcentaje2 > dPorcMax THEN
		LET dPorcMax = dPorcentaje2;
	END IF;	
	
    LET dPorciento = dPorcMax;
	
	RETURN cCodRet, dPorciento;
END
END PROCEDURE
DOCUMENT
'Realiza la compracion de nombres completos y fecha de nacimiento de clientes y se obtiene el porcentaje de coincidencias',
'AUTOR : Eduardo Lopez ',
'FECHA : 10/09/2013',
'BD    : bdinteg';

CREATE PROCEDURE "informix".sp_comparacaracteres(pCadenaOrig CHAR(40), pCadenaComparar CHAR(40))
--DATOS A REGRESAR---
RETURNING CHAR(5) AS CodRet, 
		  CHAR(2) AS Coincidencias;

--DEFINICION DE VARIABLES--
DEFINE sql_err      INTEGER;
DEFINE cCodRet      CHAR(5);
DEFINE iIndex       INTEGER;
DEFINE iContador    INTEGER;
DEFINE iCoicidencia INTEGER;
DEFINE cCarOriginal CHAR(1);
DEFINE cCarComparar CHAR(1);

--INICIALIZACION DE VARIABLES--
LET sql_err 		= 0;
LET cCodRet 		= '00000';
LET iIndex 			= 0;
LET iContador 		= 1;
LET iCoicidencia 	= 0;
LET cCarOriginal	= '';
LET cCarComparar 	= '';
	
    --SET DEBUG FILE TO "/tmp/sp_comparacaracteres.out";
    --TRACE ON;

BEGIN

    ON EXCEPTION SET sql_err
        IF sql_err <> 0 THEN
            LET cCodRet = sql_err;
            RETURN cCodRet, iCoicidencia;
        END IF;
    END EXCEPTION;

	--VALIDAR PRIMER NOMBRE CARACTER POR CARACTER
	
	 FOR iIndex = 1 TO LENGTH(pCadenaOrig)
	 
		LET cCarOriginal = UPPER(SUBSTRING(pCadenaOrig FROM iIndex FOR 1));
		LET cCarComparar = UPPER(SUBSTRING(pCadenaComparar FROM iContador FOR 1));
		
		IF cCarOriginal IN ('á','Á') THEN
			LET cCarOriginal = 'A';
		ELIF cCarOriginal IN ('é','É') THEN
			LET cCarOriginal = 'E';
		ELIF cCarOriginal IN ('í','Í') THEN
			LET cCarOriginal = 'I';                      
		ELIF cCarOriginal IN ('ó','Ó') THEN  
		    LET cCarOriginal = 'O';                   
		ELIF cCarOriginal IN ('ú','Ú') THEN
		    LET cCarOriginal = 'U';
		END IF;
		
		IF cCarComparar IN ('á','Á') THEN
			LET cCarComparar = 'A';
		ELIF cCarComparar IN ('é','É') THEN
			LET cCarComparar = 'E';
		ELIF cCarComparar IN ('í','Í') THEN
			LET cCarComparar = 'I';
		ELIF cCarComparar IN ('ó','Ó') THEN
		    LET cCarComparar = 'O';
		ELIF cCarComparar IN ('ú','Ú') THEN
		    LET cCarComparar = 'U';
		END IF;
		
		IF cCarOriginal = cCarComparar THEN
			LET iCoicidencia = iCoicidencia + 1;			
		END IF;
		LET iContador =  iContador + 1;
	END FOR
	
    RETURN cCodRet, iCoicidencia;
	
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Realiza la comparacion caracter por caracter entre 2 cadenas para obtener el número de coincidencias',
'AUTOR : Eduardo Lopez',
'FECHA : 10/09/2013',
'BD    : bdinteg';

CREATE PROCEDURE "informix".sp_bit_ctes_rel (pNumCte CHAR(20), 
											 pNumCteRef CHAR (20), 
											 pNumCteRefCoinc CHAR (20), 
											 pSucursal CHAR(4),
											 pNumEmp CHAR(8))
RETURNING CHAR(5) AS CodRetorno;

--Definicion de Variables 
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);


--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '00000';

--SET DEBUG FILE TO '/tmp/sp_bit_ctes_rel.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF (pNumCte IS NULL OR pNumCte  = '') 
		OR (pSucursal IS NULL OR pSucursal= '') 
		OR (pNumEmp IS NULL OR pNumEmp = '') THEN
		LET cCodRet = '00001';
	ELSE
	
		INSERT INTO bdinteg:"informix".si_bitacora_ctes_rel  
		(numcte, numcte_ref, numcte_ref_coinc, sucursal, numemp,fecha_insert)
		VALUES( pNumCte, pNumCteRef, pNumCteRefCoinc, pSucursal, pNumEmp, CURRENT);
	END IF	
	RETURN cCodRet;
		
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION:Se crea procedimiento almacenado para llamar sp_bit_ctes_rel el cual guardarà una bitacora de las coincidencias para su posterior procesamiento. ',
'AUTOR : Leonardo Alfonso Plata Garcia',
'FECHA : 06/09/2013',
'VERSION:20130906 ',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_bit_comparaciones (pNumcte CHAR(20), 
											      pOrigen CHAR (1), 
												  pSucursal CHAR (4), 
												  pNum_huellas SMALLINT,
												  pNumEmp CHAR(8),
												  pStatus_alerta CHAR(1))
RETURNING CHAR(5) AS CodRetorno;

--Definicion de Variables
DEFINE iSqlErr INTEGER; 
DEFINE cCodRet CHAR(5);

--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '00000';


--SET DEBUG FILE TO '/tmp/sp_bit_comparaciones.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF (pNumcte IS NULL OR pNumcte  = '') OR (pOrigen IS NULL OR pOrigen  = '')
		OR (pSucursal  IS NULL OR pSucursal  = '') OR (pNumEmp IS NULL OR pNumEmp = '') 
		OR (pNum_huellas IS NULL OR pNum_huellas = '') OR (pStatus_alerta IS NULL OR pStatus_alerta = '') THEN
		LET cCodRet = '00001';
	ELSE
	
		INSERT INTO bdinteg:"informix".si_bitacora_comparaciones  
		(numcte, origen, sucursal, numemp, Num_huellas, status_alerta,fecha_insert)
		VALUES( pNumcte, pOrigen, pSucursal, pNumEmp, pNum_huellas, pStatus_alerta, CURRENT);
	END IF	
	RETURN cCodRet;
		
END;

END PROCEDURE
