CREATE PROCEDURE "informix".sp_valida_ejecucion_reporte_regulatorio(pEmpresa CHAR(3),pAutoridad CHAR(8),pCves_reportes CHAR(50))
RETURNING CHAR(5),CHAR(80);
--DECLARACION DE VARIABLES
DEFINE iError_sql INTEGER;
DEFINE cCod_retorno CHAR(5);
DEFINE cMensaje CHAR(80);
DEFINE iNumero_registros INTEGER;
DEFINE miVariable CHAR(50);

--INICIALIZACION DE VARIABLES
LET iError_sql = 0;
LET cCod_retorno = '00000'; 
LET cMensaje = 'Validacion de proceso correcta';
LET iNumero_registros = 0;
LET miVariable = '';

--SET DEBUG FILE TO '/informix/cristobalhdez/rqi15010/reporte_regulatorio.out';
--TRACE ON;
	

BEGIN
/*Por el momento se solicita que la clave del reporte sea: R24B2423
posibliemente a futuro pudiera ser algun otro, es por ello que se pide como parametro
parametro la clave del proeceso*/
	ON EXCEPTION
		SET iError_sql
		IF iError_sql <> 0 THEN
			LET cCod_retorno = iError_sql;
			LET cMensaje = 'Ocurrio un error al validar el proceso';
			RETURN cCod_retorno, cMensaje;
		END IF;
	END EXCEPTION;
	IF NVL(pEmpresa,'') = '' OR NVL(pAutoridad,'') = '' OR NVL(pCves_reportes,'') = '' THEN
		LET cCod_retorno = '00001'; --Parametro vacio
		LET cMensaje = 'Parametros incorrectos';
	ELSE
		SET LOCK MODE TO WAIT 3;
		LET miVariable = pCves_reportes;
		--Consultamos si el proceso de generacion de reportes se esta ejecutado
		SELECT COUNT(*) INTO iNumero_registros FROM bdirepaut@coppelcont_tcp:"informix".sp_controlproceso
		WHERE identautoridad = pAutoridad AND empresa = pEmpresa AND clavereporte = pCves_reportes AND statusproceso <> 'S';
		IF iNumero_registros > 0 THEN
			LET cCod_retorno = '00002';
			LET cMensaje = 'Generando proceso regulatorio';
		END IF;
	END IF;
	RETURN cCod_retorno, cMensaje;

END

END PROCEDURE
DOCUMENT
'Folio:XX',
'AUTOR :Jose Cristobal Hernandez Fierro',
'FECHA :05/06/2014',
'MODIFICACIÓN:Se crea sp para la finalidad de fusionar los clientes de manera automatica.',
'SUSTENTO:RQI 15 010 Validacion de bandera antes de la ejecución de la fusión de clientes',
'SOLICITA:Jose Angel Lopez Adams',
'BD:bdirepaut';

CREATE PROCEDURE "informix".sp_verifica_telefonos()
	RETURNING	CHAR(5)	AS cCodRet,
				CHAR(10) AS cRegOnlineHis,
				CHAR(10) AS cRegOnline,
				CHAR(10) AS cRegTel;
    
	--DEFINICION DE VARIABLES
    DEFINE cCodRet		 CHAR(5);
    DEFINE iSqlErr  	 INTEGER;
    DEFINE cTelefono	 CHAR(10);
	DEFINE cRegOnlineHis INTEGER;
	DEFINE cRegOnline    INTEGER;
    DEFINE cRegTel       INTEGER;
	DEFINE vsCont 		 INTEGER;
	
	
	
	
	LET cCodRet			= '00000';
    LET iSqlErr			= 0;
    LET cTelefono		= 0;
	LET cRegOnlineHis 	= 0;
	LET cRegOnline    	= 0;
	LET cRegTel       	= 0;
	LET vsCont 			= 0;
	
	--SET DEBUG FILE TO "/tmp/sp_registra_telefonos.out";
	--TRACE ON;
	
    BEGIN
		-- // MANEJO DE EXCEPCIONES
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cRegOnlineHis,cRegOnline,cRegTel;
			END IF;
		END EXCEPTION;
    
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		BEGIN WORK;
		
			IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames  WHERE tabname = 'si_tmptelefonos_cel') THEN
				DROP TABLE  "informix".si_tmptelefonos_cel;            
			END IF;
			
			-- Se crea tabla temporal de trabajo
			CREATE TABLE "informix".si_tmptelefonos_cel( telefono	CHAR(13));
		 
			--Conteo de telefonos en tabla historica
			SELECT {+INDEX(bdimnsj:"informix".mnsjr_trx_online_his inx_hora_registro_his)} COUNT(*) INTO cRegOnlineHis FROM
			bdimnsj:"informix".mnsjr_trx_online_his
			WHERE id_mensaje = 'OFI_AVSMS' AND estatus = '1' AND fecha_hora_registro = fecha_hora_registro;
			
			--Conteo de telefonos en tabla online
			SELECT {+INDEX(bdimnsj:"informix".mnsjr_trx_online inx_hora_registro)} COUNT(*) INTO cRegOnline FROM
			bdimnsj:"informix".mnsjr_trx_online
			WHERE id_mensaje = 'OFI_AVSMS' AND estatus = '1' AND fecha_hora_registro = fecha_hora_registro;
			
			
			FOREACH 
				SELECT {+INDEX(bdimnsj:"informix".mnsjr_trx_online_his inx_hora_registro_his)} DISTINCT(celular_alterno) INTO cTelefono 
				FROM bdimnsj:"informix".mnsjr_trx_online_his
				WHERE id_mensaje = 'OFI_AVSMS'
				AND estatus = '1'
				AND fecha_hora_registro = fecha_hora_registro
				
				INSERT INTO "informix".si_tmptelefonos_cel(telefono) VALUES(cTelefono);
				
				LET vsCont = vsCont + 1;
				
				IF vsCont = 1000 THEN
					COMMIT WORK;
					LET vsCont = 0;
					BEGIN WORK;
				END IF;
				
			END FOREACH;
		
			IF vsCont < 1000 and vsCont > 0 THEN
				COMMIT WORK;
				LET vsCont = 0;
				BEGIN WORK;
			END IF;
			
			FOREACH
				SELECT {+INDEX(bdimnsj:"informix".mnsjr_trx_online inx_hora_registro)} DISTINCT(celular_alterno) INTO cTelefono 
				FROM bdimnsj:"informix".mnsjr_trx_online
				WHERE id_mensaje = 'OFI_AVSMS'
				AND estatus = '1'
				AND fecha_hora_registro = fecha_hora_registro
				
				INSERT INTO "informix".si_tmptelefonos_cel(telefono) VALUES(cTelefono);
				
				LET vsCont = vsCont + 1;
				
				IF vsCont = 1000 THEN
					COMMIT WORK;
					LET vsCont = 0;
					BEGIN WORK;
				END IF;
				
			END FOREACH;
		
			IF vsCont < 1000 and vsCont > 0 THEN
				COMMIT WORK;
				LET vsCont = 0;
				BEGIN WORK;
			END IF;
			
			
			FOREACH
				
				SELECT DISTINCT(telefono) INTO cTelefono
				FROM "informix".si_tmptelefonos_cel
				
				UPDATE bdinteg:si_telefonos SET verificado = 'V',fecha_actualiza=current
				WHERE tipo_tel = '2'
				AND cofetel = 'V'
				AND telefono = cTelefono;
				
				LET vsCont = vsCont + 1;
				LET cRegTel = cRegTel + 1;
				
				IF vsCont = 1000 THEN
					COMMIT WORK;
					LET vsCont = 0;
					BEGIN WORK;
				END IF;
				
			END FOREACH;
		
			IF vsCont < 1000 and vsCont > 0 THEN
				COMMIT WORK;
			END IF;

							
			DROP TABLE "informix".si_tmptelefonos_cel;
			
			RETURN cCodRet,cRegOnlineHis,cRegOnline,cRegTel;
		
	END;
END PROCEDURE
;

CREATE PROCEDURE "informix".sp_repinveripab(pFechaIni DATE, pFechaFin DATE, pNumCliente CHAR(20), pPersona CHAR(2))
RETURNING CHAR(5);
    
    DEFINE cPfisica, cExento_isr, cRegFiscal, cTipoTasa, cOperArit, cSujRet CHAR(1);
    DEFINE cTpoCuenta, cDivisa CHAR(2);    
    DEFINE cPorcentaje, cInstbase, cSobretasa CHAR(3);   
    DEFINE cNumProducto, cSucursal CHAR(4);
    DEFINE dSdo_PromInv, cPlazo, P_COD_RET, P_COD_RET2 CHAR(5); 
    DEFINE cNumCuenta, cCtaInversion CHAR(20);           
    DEFINE cNomProducto, DESC_ERR, P_COD_RET3 CHAR(40);           
    DEFINE dFechaCorte, dFechaSigCorte, dFechaContratacion DATE;               
    DEFINE sAnio, sCauRev, vexcluido SMALLINT;           
    DEFINE iDias_Proy, iAniobase, SQL_ERR, ISAM_ERR, iDias_Ini INTEGER;
    DEFINE sResiduo DECIMAL(9,3);
    DEFINE dtasa, dPorRetencionSuj, dtasax2 DECIMAL(9,6); 
    DEFINE mISR_Proy, mInt_Proy, mSdo_Inv_Proy, mInt_al_Inicio, mCapital, mSdo_Ini, mSdo_Prom_Ini, dImp_Isr_Ini, mSdo_Prom_Fin MONEY(18,2);

    LET cPfisica           = "";            LET cExento_isr        = "";            LET cRegFiscal         = "N";
    LET cTipoTasa          = "1";           LET cOperArit          = NULL;          LET cSujRet            = "S";
    LET cTpoCuenta         = "CI";          LET cDivisa            = "";            LET cPorcentaje        = NULL;
    LET cInstbase          = NULL;          LET cSobretasa         = NULL;          LET cNumProducto       = "";            
    LET cSucursal          = "";            LET dSdo_PromInv       = NULL;          LET cPlazo             = "";            
    LET P_COD_RET          = "00000";       LET P_COD_RET2         = "00000";       LET cNumCuenta         = "";            
    LET cCtaInversion      = "";            LET cNomProducto       = "";            LET DESC_ERR           = "";            
    LET P_COD_RET3         = "";            LET dFechaCorte        = NULL;          LET dFechaSigCorte     = NULL;          
    LET dFechaContratacion = "01-01-1900";  LET sAnio              = 0;             LET sCauRev            = 0;             
    LET vexcluido          = 0;             LET iDias_Proy         = 0;             LET iAniobase          = 0;             
    LET SQL_ERR            = 0;             LET ISAM_ERR           = 0;             LET iDias_Ini 		   = 0;             
    LET sResiduo           = 0;             LET dtasa              = 0;             LET dPorRetencionSuj   = 0;      
    LET dtasax2            = 0;             LET mISR_Proy          = 0;             LET mInt_Proy          = 0;             
    LET mSdo_Inv_Proy      = 0;             LET mInt_al_Inicio 	   = 0;             LET mCapital           = 0.00;          
    LET mSdo_Ini 		   = 0;             LET mSdo_Prom_Ini 	   = 0;             LET dImp_Isr_Ini 	   = 0;             
    LET mSdo_Prom_Fin 	   = 0;
                      
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/sp_repinveripab.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/sp_repinveripab.err';
        TRACE ON;
        LET P_COD_RET = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        RETURN P_COD_RET;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;

    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = "I.S.R." 
       AND fecha = (SELECT max(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = "I.S.R.");

    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    LET dPorRetencionSuj = dPorRetencionSuj / 100;

    FOREACH
        SELECT nvl(cta_cheques, ''), nvl(cuenta, ''), nvl(capital , 0), nvl(cod_instrum, ''), 
               nvl(sucursal, ''), nvl(fecha_alta, '05/01/2007'), nvl(tasa, 0), nvl(plazo, 0)
          INTO cNumCuenta, cCtaInversion, mCapital, cNumProducto, cSucursal, dFechaContratacion, dtasa, cPlazo
          FROM bdinvers:sv_maeinv 
         WHERE num_cte = pNumCliente
           AND fecha_alta <= pFechaIni 
           AND fecha_venc > pFechaIni
           AND ( fec_cancelac > pFechaIni or fec_cancelac is null )
        
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = pPersona;

        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN                
            LET dPorRetencionSuj = 0;
        END IF;   

        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab 
         WHERE numcte = pNumCliente;

        IF vexcluido > 0 THEN
            LET sCauRev = 1;
        ELSE
            LET sCauRev = 0;
        END IF;
        
        LET dtasax2 = dtasa / 100;

        -- // OBTIENE EL NOMBRE DEL PRODUCTO Y LA MONEDA
        SELECT nombre, substring (nvl(moneda, ' ') from 2 for 1)
          INTO cNomProducto, cDivisa
          FROM bdinvers:sv_instrum
         WHERE cod_instrum  = cNumProducto;
        
        -- // OBTIENE SALDO PROYECTADO A AL FECHA FINAL DE LA PROYECCION
        LET mSdo_Prom_Fin = mCapital;
        LET iDias_Proy = (pFechaFin - dFechaContratacion) + 1;
        LET mInt_Proy = (mCapital * dtasax2 * iDias_Proy) / 360;
        
        IF dPorRetencionSuj <> 0 THEN
            LET mISR_Proy = (((mCapital * dPorRetencionSuj) * iDias_Proy) / iAniobase);
        ELSE
            LET mISR_Proy = 0;
        END IF;
        
        IF pFechaIni = pFechaFin THEN
            LET mSdo_Inv_Proy = mCapital + mInt_Proy;
        ELSE
            LET mSdo_Inv_Proy = ( mCapital + mInt_Proy ) - mISR_Proy;
        END IF;

        -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
        INSERT INTO si_infpattit_tmp VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion),  UPPER(cTpoCuenta), UPPER(cRegFiscal), cPorcentaje, NVL(sCauRev, 0), UPPER(cNomProducto), UPPER(cSucursal), 
          NVL(mSdo_Inv_Proy,0), UPPER(cDivisa), dFechaCorte, dFechaContratacion, cPlazo, cTipoTasa, NVL(dtasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigCorte, 
          dSdo_PromInv, iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDias_Proy, mCapital, mSdo_Prom_Fin, mInt_Proy, mISR_Proy );

        -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
        INSERT INTO si_ctaasotit_tmp VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion), UPPER(pNumCliente), 100.00 );
    END FOREACH;

    RETURN P_COD_RET;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_intr_obt_sucpanamericano(pcPlaza CHAR(3))
	RETURNING CHAR(6) AS CodRetorno,CHAR(4) AS NumeroSucursal,CHAR(40) AS Sucursal;

--Definicion de Variables
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(6);
DEFINE cNumSucursal CHAR(4);
DEFINE cSucursal CHAR(40);

--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '000000';
LET cNumSucursal = '0000';
LET cSucursal = '';

--SET DEBUG FILE TO '/tmp/JLPolancko0/sp_intr_obt_sucpanamericano.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cNumSucursal,cSucursal;
		END IF;
	END EXCEPTION;
		
	IF NVL(pcPlaza,'') = '' THEN
		LET cCodRet = '000001'; --Parametros incorrectos
		RETURN cCodRet,cNumSucursal,cSucursal;
	END IF;
	
	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
	FOREACH SELECT suc.sucursal, suc.nombre INTO cNumSucursal,cSucursal
		FROM bdinteg:si_sucursales suc, bdinteg:si_plazas_cajagen plaz 
		WHERE suc.empresa = plaz.empresa AND suc.tpo_sucursal ='S' AND suc.plaza_cajagen = plaz.codigo_plaza 
		AND suc.plaza_cajagen = pcPlaza ORDER BY suc.nombre
		
		RETURN cCodRet,cNumSucursal,cSucursal WITH RESUME;
	END FOREACH;
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION: Se crea SP para extraer los nombres y el numero de las sucursales de alguna region en especifico',
'AUTOR : Jose Luis Polanco B.',
'FECHA : 01/11/2013',
'VERSION: 1.0',
'BD: BDINTEG',
'SISTEMA : INTRANET';

CREATE PROCEDURE "informix".sp_status_sol_audexcel(pempresa CHAR(3),psucursal CHAR(4),pfechaini CHAR(10),pfechafin CHAR(10),pstatus CHAR(2))
RETURNING CHAR(5),       -- Codigo de Retorno
		  CHAR(80),      -- Mensaje de Retorno
          CHAR(20),      -- Nro de Solicitud
		  CHAR(20),      -- Nro de Cliente
		  DATE,          -- Fecha Alta
          CHAR(104),     -- Nombre del Cliente
          CHAR(2),       -- Status Solicitud
          MONEY(14,2),   -- Monto Solicitud
		  MONEY(14,2),   -- Monto otorgado
          DATE,          -- Fecha Cambio Status
		  CHAR(45),      -- Nombre del promotor
          CHAR(13),      -- Telefono Particular
		  CHAR(13),      -- Telefono Celular
		  CHAR(13),      -- Telefono Oficina
		  CHAR (4),		 -- Sucursal 
		  CHAR(104),     -- Nombre de la primer referencia
		  CHAR(13),      -- Telefono Particular
		  CHAR(13),      -- Telefono Celular
		  CHAR(13),      -- Telefono Oficina
		  CHAR(104),     -- Nombre de la segunda referencia
		  CHAR(13),      -- Telefono Particular
		  CHAR(13),      -- Telefono Celular
		  CHAR(13);      -- Telefono Oficina

		  
--*************************************************************************
--                         DEFINICION DE VARIABLES
--*************************************************************************
DEFINE cCod_ret CHAR(5);
DEFINE cMen_ret CHAR(80);
DEFINE iSqlerr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE cNumSol CHAR(20);
DEFINE cNumcte CHAR(20);
DEFINE cStatus CHAR(2);
DEFINE mMonto MONEY(14,2);
DEFINE mMonto_aut     MONEY(14,2);
