CREATE PROCEDURE "informix".sp_graba_logdesfusion(cProceso CHAR(50), cTabla CHAR(30),cClienteTit CHAR(20),cClienteTras CHAR(20),cDetalle_mov CHAR(200),cUsuario_insert CHAR(8))
RETURNING CHAR(6);

DEFINE iSql_err			INTEGER;
DEFINE cRetorno	CHAR(6);
LET cRetorno = '000000';
BEGIN
	--CONTROL DE ERRORES--
	ON EXCEPTION SET iSql_err 
		IF iSql_err <> 0 THEN
			LET cRetorno = iSql_err;
			RETURN cRetorno;
		END IF;
	END EXCEPTION;
	
	INSERT INTO "informix".si_logdesfusion(proceso,tabla,cliente_tit,cliente_tras,detalle_mov,fecha_hora,user_insert,fecha_insert)
	VALUES (cProceso,cTabla,cClienteTit,cClienteTras,cDetalle_mov,CURRENT HOUR TO FRACTION(4),cUsuario_insert,CURRENT::DATE);
	
	RETURN cRetorno;
END
END PROCEDURE;

create procedure "informix".sp_rcda_integra()
	RETURNING CHAR (005) as cod_ret,
			  char (180) as mensaje;

	--Declaracion de variables
				  
	--variables de control de errores			  
	DEFINE  SQL_ERR          INTEGER;
	DEFINE  ISAM_ERR         INTEGER;
	DEFINE  ERROR_INFO       VARCHAR(80);
	DEFINE  P_COD_RET        VARCHAR(6);
	DEFINE  P_MENSAJE        VARCHAR(80);
	DEFINE  dFecha           Date;
	DEFINE  dFechafto        char(10);
	DEFINE  dFechaCorte      Date;
	DEFINE  dFechaAnt        Date;
	DEFINE  dFechahoy        Date;
	DEFINE  dult_dia_mes     Date;
	DEFINE  dfechaantier     Date;
	DEFINE  iDiasMes         INTEGER;
	DEFINE  vpaso			 integer;
	DEFINE  vaniomes		 char(06);
	DEFINE  iVal             INTEGER;
	DEFINE  iVal2            INTEGER;
	DEFINE  iPorCap          decimal;
	DEFINE  iPorSdo          decimal;
	DEFINE  iPorCol          decimal;
	DEFINE  iPorTdc          decimal;
	
BEGIN
   ON EXCEPTION SET SQL_ERR, ISAM_ERR, ERROR_INFO
      LET P_COD_RET    = SQL_ERR;
      LET P_MENSAJE  = ERROR_INFO || ' sp_rcda_integra en paso ' || vpaso;
	  insert into mi_rcda_cierresucerror (fecha_cierre,estatus_ejec,codigo_error,desc_error )
	  select fecha_ant,'F',P_COD_RET, P_MENSAJE  from bdmis:mi_fechas;
      RETURN P_COD_RET, P_MENSAJE;
   END EXCEPTION;
   
   set isolation to dirty read;
   
   --inicializacion
	let P_COD_RET = '00000';
	let P_MENSAJE ='PROCESO EXITOSO';
   
     let vpaso = 0;
   --se obtienen las fechas de proceso   
	   set isolation to dirty read;
	   select fecha_ant,day(ult_dia_mes)::int, (fecha_ant-1), fecha_hoy, ult_dia_mes 
	   into dFecha,iDiasMes, dfechaantier, dFechahoy, dult_dia_mes 
	   from bdmis:mi_fechas;
	   
			if (SELECT count(codigo_error) FROM mi_rcda_cierresucerror where fecha_cierre = dfecha and codigo_error = 001) > 0 then
			   return '001','fecha ya procesada';
			end if	   
	   
	   let vaniomes = year(dFecha)|| lpad(month(dFecha),2,'0');
   
   	
		set isolation to dirty read;
		 let vpaso = 1;
		 truncate TABLE mi_aperturas;
		 		
			--extraccion de metas de productos
			select mp.aniomes,suc.num_sucursal as sucursal,suc.tipo_suc, mp.producto ,mp.metanum 
			from  mi_metasprod mp, mi_sucursalesinfo suc where mp.aniomes = vaniomes and mp.id_tiposuc = suc.tipo_suc
			into temp tmp_mp;

			--	llenado de tabla de aperturas, cuentas de captación
			insert into mi_aperturas (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,capcuentas, capmeta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('2000','1100','1200','1300','1400','1500','1600','1800','1700','9901','2300','2500','1900')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;
		 
		 let vpaso = 2;
		 --llenado de tabla de aperturas, solicitudes de credito
		 	insert into mi_aperturas (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,colsolcred, colsolmeta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('6001')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;
					
		 let vpaso = 3;
		 --llenado de tabla de aperturas, tarjeta de credito entregada
		 	insert into mi_aperturas (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,colentrcred, colentrmeta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('6666')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;
					
		 let vpaso = 4;
		--llenado de tabla de aperturas, solicitudes de tarjeta de credito coppel
		 insert into mi_aperturas  (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,copsoltdc,copsolmeta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('6500')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;
					
		let vpaso = 5;			
		--llenado de tabla de aperturas, tarjeta de credito coppel entregadas
			insert into mi_aperturas (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,copentrtdc, copentrmeta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('6566')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;
			
		let vpaso = 6;		
		--	--llenado de tabla de aperturas, contratos de banca electronica
			insert into mi_aperturas (fecha,sucursal, tpo_reg,ejecutivo,nombre ,producto,be_totcontr, be_meta)
			SELECT  dfecha,tmp.sucursal, 1,tmp.ejecutivo, eje.nombre, tmp.producto, tmp.num_ctasdia ,mp.metanum
			FROM    mi_rcda_suc tmp, tmp_mp mp, bdinteg:si_ejecut eje
			where   tmp.producto in ('5003')  and
					tmp.sucursal = mp.sucursal and tmp.producto = mp.producto and aniomes = vaniomes and 
					tmp.ejecutivo = eje.ejecutivo ;		
		
		
		
		--paso a tablas de acumulado mensual
		set isolation to dirty read;		
		let vpaso = 7;
		-- paso de productividad de sucursales a acumulado mensual
			
			insert into mi_acumps_mes ( fecha, sucursal, ejecutivo, nombre,producto,capcuentas,capmeta,colsolcred,colsolmeta,colentrcred,
							colentrmeta,copsoltdc,copsolmeta,copentrtdc,copentrmeta,num_comp_mismomes,meta_comp_mismomes,clubncandidatos,
							clubncompraron,be_totcontr,be_meta)
			SELECT fecha, sucursal, ejecutivo, nombre,producto,capcuentas,capmeta,colsolcred,colsolmeta,colentrcred,
							colentrmeta,copsoltdc,copsolmeta,copentrtdc,copentrmeta,num_comp_mismomes,meta_comp_mismomes,clubncandidatos,
							clubncompraron,be_totcontr,be_meta FROM mi_aperturas;

		let vpaso = 8;
		--paso de cobranza a acumulado mensual
			INSERT INTO bdmis:mi_acumcb_mes ( fecha, sucursal, cajero, nombre, num_ctes_cvdo, num_conv, tot_mont_conv, 
			tot_mont_pag, pag_min_a_recup, pag_min_recup, num_pm, num_sin_pm, venc_a_recup, venc_recup, num_vencidos, num_sin_vencidos )
			SELECT fecha, sucursal, cajero, nombre, num_ctes_cvdo, num_conv, tot_mont_conv, 
			tot_mont_pag, pag_min_a_recup, pag_min_recup, num_pm, num_sin_pm, venc_a_recup, venc_recup, num_vencidos, num_sin_vencidos  FROM bdmis:mi_cobranza ;
		
		let vpaso = 9;
		 --paso de operaciones en ventanilla a acumulado mensual
			INSERT INTO bdmis:mi_acumopven_mes(fecha, sucursal, cajero, nombre, num_depcap, mont_depcap, num_retcap, mont_retcap, 
			num_pagcred, mont_pagcred, num_dispcred, mont_dispcred, num_pagserv, mont_pagserv)
			SELECT fecha, sucursal, cajero, nombre, num_depcap, mont_depcap, num_retcap, mont_retcap, 
			num_pagcred, mont_pagcred, num_dispcred, mont_dispcred, num_pagserv, mont_pagserv FROM  bdmis:mi_opventanilla;
		
		
		--integracion de de valores acumulados del mes
		let vpaso = 10;
		 --acumulado de Productividad en Sucursales
			--acumulado para productos de captacion
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, capcuentas, capmeta)
			select dfecha,sucursal,2,ejecutivo,nombre,producto,sum(nvl(capcuentas,0)),sum(nvl(capmeta,0))
			from  mi_acumps_mes 
			where producto in ('2000','1100','1200','1300','1400','1500','1600','1800','1700','9901','2300','2500','1900')
					and (year(fecha) = year (dfecha) )
			group by 2,4,5,6;
		
		let vpaso = 11;
		 --acumulado solicitudes de tdc bancoppel
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, colsolcred, colsolmeta)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(colsolcred,0)),  ((nvl(colsolmeta,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '6001' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
		
		let vpaso = 12;	
		 --acumulado de tarjetas de credito entregdas 
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, colentrcred, colentrmeta)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(colentrcred,0)),  ((nvl(colentrmeta,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '6666' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
		  
		let vpaso = 13;  
		 -- acumulado solicitud de tarjeta de credito coppel  
		 
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, copsoltdc, copsolmeta)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(copsoltdc,0)),  ((nvl(copsolmeta,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '6500' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
		
		let vpaso = 14;	
		 -- acumulado tarjetas coppel entregadas
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, copentrtdc, copentrmeta)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(copentrtdc,0)),  ((nvl(copentrmeta,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '6566' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
		 
		 let vpaso = 15;
		 -- acumulado  club de proteccion 
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto,clubncandidatos, clubncompraron )
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(clubncandidatos,0)), sum(nvl(clubncompraron,0))
			from  mi_acumps_mes where producto = '7777' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5;
			
		let vpaso = 16;	
		 --  acumulado club de proteccion  
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, be_totcontr, be_meta)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(be_totcontr,0)),  ((nvl(be_meta,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '5003' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
		 
		let vpaso = 17;
		 -- acumulado clientes que compraron el mismo mes 
			insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, num_comp_mismomes, meta_comp_mismomes)
			select fecha,sucursal,ejecutivo,nombre,producto, sum(nvl(num_comp_mismomes,0)),  ((nvl(meta_comp_mismomes,0) * 24) / 30) * day (dfecha) 
			from  mi_acumps_mes where producto = '6111' and (year(fecha) = year (dfecha) ) and  (month(fecha) = month (dfecha) )
			group by 1,2,3,4,5,7;
			
		  
		 /*
		  insert into mi_aperturas 	(fecha,sucursal, tpo_reg,ejecutivo, nombre, producto, capcuentas, capmeta, colsolcred, colsolmeta, colentrcred, colentrmeta,
									 copsoltdc, copsolmeta, copentrtdc, copentrmeta, clubncandidatos, clubncompraron, be_totcontr, be_meta)		
		  SELECT dfecha,sucursal, 2 ,ejecutivo, nombre, producto, sum(nvl(capcuentas,0)), ((nvl(capmeta,0) * 24) / 30) * day (dfecha), sum(nvl(colsolcred,0)),
				((nvl(colsolmeta,0) * 24) / 30) * day (dfecha), sum(nvl(colentrcred,0)), ((nvl(colentrmeta,0) * 24) / 30) * day (dfecha), sum(nvl(copsoltdc,0)),
				((nvl(copsolmeta,0) * 24) / 30) * day (dfecha), sum(nvl(copentrtdc,0)), ((nvl(copentrmeta,0) * 24) / 30) * day (dfecha), sum(nvl(clubncandidatos,0)),
				sum(nvl(clubncompraron,0)), sum(nvl(be_totcontr,0)), ((nvl(be_meta,0) * 24) / 30) * day (dfecha)
			FROM bdmis:mi_acumps_mes where year(fecha) = year (dfecha) 
			group by 1,2,3,4,5,6,8,10,12,14,16,20 ;
			*/
		
		let vpaso = 18;
		 -- acumulado de cobranza 
			INSERT into bdmis:mi_cobranza ( fecha, sucursal,tpo_reg , cajero, nombre, num_ctes_cvdo, num_conv, tot_mont_conv, 
											tot_mont_pag, pag_min_a_recup, pag_min_recup,num_pm, num_sin_pm, venc_a_recup, venc_recup, num_vencidos, num_sin_vencidos  )
		 select   dfecha, sucursal,2 ,cajero, nombre, sum(nvl(num_ctes_cvdo,0)), sum(nvl(num_conv,0)),
         sum(nvl(tot_mont_conv,0)), sum(nvl(tot_mont_pag,0)), sum(nvl(pag_min_a_recup,0)),
         sum(nvl( pag_min_recup,0)), sum(nvl(num_pm,0)), sum(nvl(num_sin_pm,0)), 
		 sum(nvl(venc_a_recup,0)), sum(nvl(venc_recup,0)), 
		 sum(nvl(num_vencidos,0)), sum(nvl(num_sin_vencidos,0)) 
		 from bdmis:mi_acumcb_mes where year(fecha) = year (dfecha)and month(fecha) = month(dfecha)
		 group by 1,2,3,4,5;
		
		
		let vpaso = 19;
		 -- acumulado de opereaciones en ventanilla
		 insert into mi_opventanilla (fecha, sucursal, tpo_reg ,cajero, nombre, num_depcap, mont_depcap, num_retcap, mont_retcap, 
									  num_pagcred, mont_pagcred, num_dispcred, mont_dispcred, num_pagserv, mont_pagserv)
		 SELECT dfecha, sucursal, 2,cajero, nombre, sum(nvl(num_depcap,0)), sum(nvl(mont_depcap,0)), sum(nvl(num_retcap,0)),
			    sum(nvl(mont_retcap,0)), sum(nvl(num_pagcred,0)), sum(nvl(mont_pagcred,0)), sum(nvl(num_dispcred,0)),
				sum(nvl(mont_dispcred,0)), sum(nvl(num_pagserv,0)), sum(nvl(mont_pagserv,0)) 
		FROM bdmis:mi_acumopven_mes where year(fecha) = year (dfecha)and month(fecha) = month(dfecha)
		group by 1,2,3,4,5;
		 
		 
		 
		
		/* fecha,sucursal, tpo_reg,ejecutivo,nombre,producto,capcuentas,capmeta,colsolcred,colsolmeta,colentrcred,
		colentrmeta,copsoltdc,copsolmeta,copentrtdc,copentrmeta,clubncandidatos,clubncompraron,be_totcontr,be_meta */
			
		--
		

		let vpaso = 20;
		IF (SELECT COUNT(*) FROM mi_rptcierresucestatus WHERE fecha_rptcierre = dFecha ) = 0 THEN
		
			TRUNCATE table bdmis:mi_rptcierresucestatus;
			insert into mi_rptcierresucestatus(sucursal,fecha_rptcierre) select num_sucursal,dFecha  from bdmis:mi_sucursalesinfo where num_sucursal < 2000;
		
		END IF	
		
		let vpaso = 21;
		
	    insert into mi_rcda_cierresucerror values (dFecha,'V',P_COD_RET,P_MENSAJE );

			
		let vpaso = 22;
		
		
        EXECUTE PROCEDURE "informix".sp_rcda_promotorvirtual()
            INTO P_COD_RET, P_MENSAJE;
        IF P_COD_RET <> '000' THEN
            RETURN P_COD_RET, P_MENSAJE;
        END IF;
		
		let vpaso = 23;
		EXECUTE PROCEDURE "informix".sp_rcda_rellenaprod()
            INTO P_COD_RET, P_MENSAJE;
        IF P_COD_RET <> '000000' THEN
            RETURN P_COD_RET, P_MENSAJE;
        END IF;
		
		let vpaso = 24;
		UPDATE mi_aperturas SET capmeta = 0, colsolmeta = 0,colentrmeta = 0, copsolmeta = 0,copentrmeta = 0,be_meta = 0, meta_comp_mismomes = 0
		WHERE nombre = 'PROMOTOR VIRTUAL';
		
		
		let vpaso = 25;
		UPDATE mi_aperturas set capmeta = 0, colsolmeta = 0,colentrmeta = 0, copsolmeta = 0,copentrmeta = 0,be_meta = 0, meta_comp_mismomes = 0
		WHERE ejecutivo IN (SELECT ejecutivo FROM bdinteg:si_ejecut WHERE puesto = '001');
		
		let vpaso = 26;
		EXECUTE PROCEDURE "informix".sp_paso_his()
		            INTO P_COD_RET, P_MENSAJE;
        IF P_COD_RET <> '000' THEN
            RETURN P_COD_RET, P_MENSAJE;
        END IF;		
				
				
		let vpaso = 27;			
			begin work;
				UPDATE bdmis:mi_param SET estatus = 'V' WHERE descripcion = 'FLAG RPT CIERRE';	
			commit work;
			
	RETURN P_COD_RET, P_MENSAJE;
END;
end procedure;

CREATE PROCEDURE "informix".mod_intereses_pagare(pempresa CHAR(3))
RETURNING CHAR(5), CHAR(5), INTEGER, INTEGER, INTEGER;

    DEFINE vcodret1         CHAR(5);
    DEFINE vcodret2         CHAR(5);
    DEFINE sql_err          INTEGER;
    DEFINE isam_err         INTEGER;
    DEFINE vcontador1       INTEGER;
    DEFINE vcontador2       INTEGER;
    DEFINE vcontador3       INTEGER;
    DEFINE vcomienza        SMALLINT;
    DEFINE ven_transacc     SMALLINT;
    DEFINE vcodret_abono    CHAR(5);
    
    DEFINE vsql             CHAR(500);
    DEFINE vstmt            CHAR(250);
    DEFINE vhora            CHAR(15);
    DEFINE vfolio           CHAR(16);
    DEFINE vcuenta          CHAR(20);
    DEFINE vmonto           MONEY(14,2);
    DEFINE vintprov         MONEY(14,2);    
    DEFINE vtransacc        CHAR(4);
    DEFINE vdescripcion     CHAR(40);
    DEFINE vsucursal        CHAR(4);  
    DEFINE vusuario         CHAR(8);
    DEFINE vmoneda          CHAR(2);
    DEFINE vmincta, vmaxcta CHAR(20);
    DEFINE vctachq          CHAR(20);
    DEFINE vsaldo_fin       DECIMAL(18,2);
    DEFINE vintereses_fin   DECIMAL(18,2);
    DEFINE vsdo_cuenta      DECIMAL(18,2);
    
    LET vcodret1      = '000';
    LET vcodret2      = '000';
    LET sql_err	      = 0;
    LET isam_err      = 0;
    LET vcontador1    = 0;
    LET vcontador2    = 0;
    LET vcontador3    = 0;
    LET vcomienza     = -1;
    LET ven_transacc  = 0;
    LET vcodret_abono = '';
    
    LET vsql           = '';
    LET vstmt          = '';
    LET vhora          = '';
    LET vfolio         = '';
    LET vcuenta        = '';
    LET vmonto         = 0.00;
    LET vtransacc      = '';
    LET vdescripcion   = '';
    LET vsucursal      = '';
    LET vusuario       = 'informix';
    LET vmoneda        = '01';
	LET vintprov       = 0.00;
    LET vctachq        = '';
    LET vsaldo_fin     = 0.00;
    LET vintereses_fin = 0.00;
    LET vsdo_cuenta    = 0.00;
    
    BEGIN

    ON EXCEPTION SET sql_err, isam_err
        SET DEBUG FILE TO "/tmp/mod_intereses_pagare.err";
        TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
    IF EXISTS( SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'pagaresxcorregir') THEN
        DROP TABLE "informix".pagaresxcorregir;
    END IF;
    
    CREATE TABLE "informix".pagaresxcorregir
      (
        cuenta      char(20)    not null,
        monto       money(18,2) not null
      )
    EXTENT SIZE 32 NEXT SIZE 32 LOCK MODE ROW;
    CREATE INDEX "informix".idx_pagxcorr ON "informix".pagaresxcorregir(cuenta) USING BTREE FILLFACTOR 99;
      
    LET vsql = 'echo "LOAD FROM /resplogifx/conciliachq/pagares_ipab_2014.unl DELIMITER ''","'' INSERT INTO pagaresxcorregir" > /resplogifx/conciliachq/pagaresxcorr.sql';
    SYSTEM vsql;
    LET vsql = '';
    
    LET vstmt = '/ifxsif01/bin/dbaccess bdinteg /resplogifx/conciliachq/pagaresxcorr.sql';
    SYSTEM vstmt;
    LET vstmt = '';
    
    UPDATE STATISTICS MEDIUM FOR TABLE pagaresxcorregir;
    
    FOREACH WITH HOLD
        SELECT cuenta, monto
          INTO vcuenta, vmonto
          FROM pagaresxcorregir
		  
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1;
            BEGIN WORK;
        END IF;
        
        SELECT numcta
          INTO vctachq
          FROM bdinteg:si_infpattit
         WHERE num_inversion = vcuenta;
        
        SELECT intereses_fin 
		  INTO vintprov
		  FROM bdinteg:si_infpattit
         WHERE num_inversion = vcuenta
           and numcta = vctachq;

        IF vintprov <> vmonto THEN
           UPDATE bdinteg:si_infpattit 
              SET intereses_fin = vmonto
            WHERE num_inversion = vcuenta
              and numcta = vctachq;            
              
		   LET vcontador2 = vcontador2 + 1;	  
	    END IF;
        
        SELECT saldo_fin, intereses_fin, sdo_cuenta
          INTO vsaldo_fin, vintereses_fin, vsdo_cuenta
          FROM bdinteg:si_infpattit
         WHERE num_inversion = vcuenta
           AND numcta = vctachq; 
           
        IF vsdo_cuenta <> ( vsaldo_fin + vintereses_fin ) THEN
            UPDATE bdinteg:si_infpattit 
               SET sdo_cuenta = vsaldo_fin + vintereses_fin
             WHERE num_inversion = vcuenta
               AND numcta = vctachq;    
            
            LET vcontador3 = vcontador3 + 1;	
        END IF;

		COMMIT WORK;
		BEGIN WORK;   
		   
        LET vcontador1 = vcontador1 + 1;
        
        LET vcuenta        = '';
        LET vmonto         = 0.00;
		LET vintprov       = 0.00;
        LET vctachq        = '';
        LET vsaldo_fin     = 0.00;
        LET vintereses_fin = 0.00;
        LET vsdo_cuenta    = 0.00;
     END FOREACH;
    
    END;
    
    IF ven_transacc = 1 THEN
        COMMIT WORK;
    END IF;

    RETURN vcodret1, vcodret2, vcontador1, vcontador2, vcontador3;

END PROCEDURE;

CREATE PROCEDURE "informix".direccionespba( pEmpresa         CHAR(3),  
                                         pFuncion         CHAR(1),   
                                         pNumCte          CHAR(20), 
                                         pSecuencia       SMALLINT, 
                                         pTipoDir         CHAR(1), 
                                         pCalle           CHAR(40),
                                         pColonia         CHAR(60), 
                                         pMunicipio       CHAR(5), 
                                         pEntre_Calles    CHAR(40),
                                         pPais            CHAR(3),
                                         pEntidad         CHAR(2),
                                         pLocalidad       CHAR(3),
                                         pCodPostal       CHAR(5),
                                         pTipoTel1        CHAR(1),
                                         pTelefono1       CHAR(13),
                                         pTipoTel2        CHAR(1),
                                         pTelefono2       CHAR(13),
                                         pTipoTel3        CHAR(1),
                                         pTelefono3       CHAR(13),
                                         pExtension       CHAR(5),
                                         pEstado_Inegi    CHAR(2),
                                         pMunicipio_Inegi CHAR(3),
                                         pLocalidad_Inegi CHAR(4),
                                         pNoCiudad        SMALLINT,
                                         pNoExt           CHAR(10),
                                         pNoInt           CHAR(10),
                                         pDepto           CHAR(6),
                                         pNoCalle         INTEGER,
                                         pNoColonia       INTEGER,
                                         pPuntoCar        CHAR(1),
                                         pUniHabi         CHAR(1),
                                         pManz            SMALLINT,
                                         pPOtros          SMALLINT,
                                         pAndador         SMALLINT,
                                         pEtapa           SMALLINT,
                                         pLote            SMALLINT,
                                         pEdif            SMALLINT,
                                         pEntrada         SMALLINT,
                                         pObserva         CHAR(80),
                                         pUser_Insert     CHAR(8),
                                         pFecha_Insert    DATE,
                                         cSucursal        CHAR(4) )
RETURNING CHAR(5);

    DEFINE v_CodRet             CHAR(5);
    DEFINE v_CodRet2            CHAR(5);
    DEFINE v_CodRet3            CHAR(50);
    DEFINE v_SqlErr             INTEGER;
    DEFINE v_IsamErr            INTEGER;
    DEFINE v_DescErr            CHAR(50);
    DEFINE v_NumCte             CHAR(20);
    DEFINE pcoincide_dir        SMALLINT;
    DEFINE o_tipo_dir       	CHAR(1);
    DEFINE o_calle          	CHAR(40);
    DEFINE o_colonia        	CHAR(60);
    DEFINE o_entre_calles   	CHAR(40);
    DEFINE o_pais           	CHAR(3);
    DEFINE o_estado         	CHAR(2);
    DEFINE o_ciudad         	CHAR(3);
    DEFINE o_municipio      	CHAR(5);
    DEFINE o_cod_postal     	CHAR(5);
    DEFINE o_apart_postal   	CHAR(11);
    DEFINE o_telefono1      	CHAR(13);
    DEFINE o_telefono2      	CHAR(13);
    DEFINE o_telefono3      	CHAR(13);
    DEFINE o_extension      	CHAR(5);
    DEFINE o_estado_inegi   	CHAR(2);
    DEFINE o_municipio_inegi	CHAR(3);
    DEFINE o_localidad_inegi    CHAR(4);
    DEFINE o_numerociudad   	SMALLINT;
    DEFINE o_numeroextcalle 	CHAR(10);
    DEFINE o_numerointcalle 	CHAR(10);
    DEFINE o_departamento   	CHAR(6);
    DEFINE o_numerocalle    	INTEGER;
    DEFINE o_numerocolonia  	INTEGER;
    DEFINE o_puntocardinal  	CHAR(1);
    DEFINE o_unidadhabitac  	CHAR(1);
    DEFINE o_manzana        	SMALLINT;
    DEFINE o_otros          	SMALLINT;
    DEFINE o_andador        	SMALLINT;
    DEFINE o_etapa          	SMALLINT;
    DEFINE o_lote           	SMALLINT;
    DEFINE o_edificio       	SMALLINT;
    DEFINE o_entrada        	SMALLINT;
    DEFINE o_observaciones  	CHAR(80);
    DEFINE v_CodRetTel          CHAR(5);
    DEFINE vTipoTel             SMALLINT;
    DEFINE vCanal               SMALLINT;
    DEFINE cSituacionEsp        CHAR(1);  --- VARIABLE DE SITUACIÓN ESPECIAL
    DEFINE iCausa               INTEGER;  --- VARIABLE DE SITUACIÓN ESPECIAL

    LET v_CodRet          = '';
    LET v_CodRet2         = '';
    LET v_CodRet3         = '';
    LET v_SqlErr          = 0;
    LET v_IsamErr         = 0;
    LET v_DescErr         = '';
    LET v_NumCte          = '';
    LET pcoincide_dir     = 0;
    LET o_tipo_dir        = '';
    LET o_calle           = '';
    LET o_colonia         = '';
    LET o_entre_calles    = '';
    LET o_pais            = '';
    LET o_estado          = '';
    LET o_ciudad          = '';
    LET o_municipio       = '';
    LET o_cod_postal      = '';
    LET o_apart_postal    = '';
    LET o_telefono1       = '';
    LET o_telefono2       = '';
    LET o_telefono3       = '';
    LET o_extension       = '';
    LET o_estado_inegi    = '';
    LET o_municipio_inegi = '';
    LET o_localidad_inegi = '';
    LET o_numerociudad    = 0;
    LET o_numeroextcalle  = '';
    LET o_numerointcalle  = '';
    LET o_departamento    = '';
    LET o_numerocalle     = 0;
    LET o_numerocolonia   = 0;
    LET o_puntocardinal   = '';
    LET o_unidadhabitac   = '';
    LET o_manzana         = 0;
    LET o_otros           = 0;
    LET o_andador         = 0;
    LET o_etapa           = 0;
    LET o_lote            = 0;
    LET o_edificio        = 0;
    LET o_entrada         = 0;
    LET o_observaciones   = '';
    LET v_CodRetTel       = '';
    LET vTipoTel          = 0;
    LET vCanal            = 1;
    LET cSituacionEsp     = 'N'; --- VARIABLE DE SITUACIÓN ESPECIAL
    LET iCausa            = 0;   --- VARIABLE DE SITUACIÓN ESPECIAL

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/direcciones.out";
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET v_SqlErr, v_IsamErr, v_DescErr
        SET DEBUG FILE TO "/tmp/direcciones.err";
        TRACE ON;
        IF v_SqlErr != 0 THEN
            LET v_CodRet = v_SqlErr;
            LET v_CodRet2 = v_IsamErr;
            LET v_CodRet3 = v_DescErr;
            RETURN v_CodRet;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    LET v_CodRet = "000";
    LET pEntidad = CAST( LPAD (TRIM(pEntidad), 2 ,  "0") AS CHAR(2));

    SELECT numcte 
      INTO v_NumCte 
      FROM si_cliente
     WHERE numcte = pNumCte;
     
    IF v_NumCte IS NULL THEN
        LET v_CodRet = "104";
        RETURN v_CodRet;
    END IF

    IF pFuncion = "C" THEN
        DELETE FROM si_direcciones
         WHERE numcte = pNumCte 
           AND secuencia = pSecuencia;
           
        DELETE FROM si_direcciones_actual
         WHERE numcte = pNumCte 
           AND secuencia = pSecuencia;
           
        LET pFuncion = "A";
    END IF

    IF pFuncion = "A" THEN
        SELECT MAX(secuencia) 
          INTO pSecuencia
          FROM si_direcciones_actual
         WHERE numcte = pNumCte;
         
        IF pSecuencia IS NULL THEN
            LET pSecuencia = 1;
        ELSE
            LET pSecuencia = pSecuencia + 1;
            LET cSituacionEsp = 'S';
        END IF;

        -- // SE AGREGA VALIDACIÓN PARA SI LA CLAVE DEL MUNICIPIO VIENE VACIO, LE ASIGNE  "00000".
        IF pMunicipio = "" OR pMunicipio is null  THEN
            LET pMunicipio = LPAD(TRIM(NVL(pMunicipio,"00000")),5,"0");
        END IF;
        
        -- // VALIDA LA INFORMACION DE LA DIRECCION DEL CLIENTE
        SELECT tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,
               estado_inegi, municipio_inegi, localidad_inegi, numerociudad, 
               numeroextcalle, numerointcalle, departamento, numerocalle, numerocolonia, 
               puntocardinal, unidadhabitac, manzana, otros, andador, etapa, lote, edificio, entrada, observaciones
          INTO o_tipo_dir, o_calle, o_colonia, o_entre_calles, o_pais, o_estado, o_ciudad, o_municipio, o_cod_postal, o_apart_postal,
               o_estado_inegi, o_municipio_inegi, o_localidad_inegi, o_numerociudad, 
               o_numeroextcalle, o_numerointcalle, o_departamento, o_numerocalle, o_numerocolonia, 
               o_puntocardinal, o_unidadhabitac, o_manzana, o_otros, o_andador, o_etapa, o_lote, o_edificio, o_entrada, o_observaciones
          FROM si_direcciones_actual
         WHERE numcte = pNumCte
           AND tipo_dir = pTipoDir;
        
        IF ( o_tipo_dir is not null               
             AND o_calle = pCalle                     
             AND o_colonia = pColonia                 
             AND o_entre_calles = pEntre_Calles       
             AND o_pais = pPais                       
             AND o_estado = pEntidad                  
             AND o_ciudad = pLocalidad                
             AND o_municipio = pMunicipio             
             AND o_cod_postal = pCodPostal            
             AND o_estado_inegi = pEstado_Inegi       
             AND o_municipio_inegi = pMunicipio_Inegi 
             AND o_localidad_inegi = pLocalidad_Inegi 
             AND o_numerociudad = pNoCiudad           
             AND o_numeroextcalle = pNoExt            
             AND o_numerointcalle = pNoInt            
             AND o_departamento = pDepto              
             AND o_numerocalle = pNoCalle             
             AND o_numerocolonia = pNoColonia         
             AND o_puntocardinal = pPuntoCar          
             AND o_unidadhabitac = pUniHabi           
             AND o_manzana = pManz                    
             AND o_otros = pPOtros                    
             AND o_andador  = pAndador                
             AND o_etapa = pEtapa                     
             AND o_lote = pLote                       
             AND o_edificio = pEdif                   
             AND o_entrada = pEntrada                 
             AND o_observaciones = pObserva ) THEN
            LET pcoincide_dir = 1;
        ELSE
            LET pcoincide_dir = 0;
        END IF;
        
        IF ( pcoincide_dir <= 0 ) THEN
			INSERT INTO si_direcciones
            ( numcte, secuencia, tipo_dir, calle, colonia, entre_calles, pais, estado, ciudad, municipio, cod_postal, apart_postal,
              estado_inegi, municipio_inegi, localidad_inegi, numerociudad, numeroextcalle, numerointcalle, 
              departamento, numerocalle, numerocolonia, puntocardinal, unidadhabitac, manzana, otros, 
              andador, etapa, lote, edificio, entrada, observaciones, user_insert, fecha_insert )
            VALUES
            ( pNumCte, pSecuencia, pTipoDir, pCalle, pColonia, pEntre_Calles, pPais, pEntidad, pLocalidad, pMunicipio, pCodPostal, "",
              pEstado_Inegi, pMunicipio_Inegi, pLocalidad_Inegi, pNoCiudad, pNoExt, pNoInt,
              pDepto, pNoCalle, pNoColonia, pPuntoCar, pUniHabi, pManz, pPOtros,
              pAndador, pEtapa, pLote, pEdif, pEntrada, pObserva, pUser_Insert, pFecha_Insert );
        END IF;
        
        -- // VALIDA LA INFORMACIÓN DE LOS TELEFONOS DEL CLIENTE
        SELECT telefono
          INTO o_telefono1
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        IF o_telefono1 is null THEN
            LET o_telefono1 = ' ';
        END IF;
           
        IF o_telefono1 <> pTelefono1 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel1 is not null AND pTipoTel1 <> '' ) AND ( pTelefono1 is not null AND pTelefono1 <> '' ) ) THEN
                LET vTipoTel = 1;
                CALL sp_registra_telefonos(pEmpresa, pNumCte, pTelefono1, vTipoTel, '', 0, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
           
        SELECT telefono
          INTO o_telefono2
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
           
        IF o_telefono2 is null THEN
            LET o_telefono2 = ' ';
        END IF;
           
        IF o_telefono2 <> pTelefono2 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel2 is not null AND pTipoTel2 <> '' ) AND ( pTelefono2 is not null AND pTelefono2 <> '' ) ) THEN
                LET vTipoTel = 2;
                CALL sp_registra_telefonos(pEmpresa, pNumCte, pTelefono2, vTipoTel, '', 0, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
           
        SELECT telefono, extension
          INTO o_telefono3, o_extension
          FROM si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 3;
           
        IF o_telefono3 is null THEN
            LET o_telefono3 = ' ';
        END IF;
           
        IF o_telefono3 <> pTelefono3 THEN
            IF cSucursal = '5002' THEN
                LET vCanal = 12;
            END IF;
              
            IF ( ( pTipoTel3 is not null AND pTipoTel3 <> '' ) AND ( pTelefono3 is not null AND pTelefono3 <> '' ) ) THEN
                LET vTipoTel = 3;
                CALL sp_registra_telefonos(pEmpresa, pNumCte, pTelefono3, vTipoTel, pExtension, 0, vCanal, pUser_Insert)
                RETURNING v_CodRetTel;
            END IF;
        END IF;
        
        -- // VALIDACIÓN DE SITUACIÓN ESPECIAL
        IF pTipoDir = '1' AND cSituacionEsp = 'S' THEN
            SELECT LIMIT 1 NVL(situacion,''), causa
              INTO cSituacionEsp, iCausa
              FROM bdisitesp:se_ctessitespcte
             WHERE numcte = pNumCte;
			
            IF cSituacionEsp = 'L' THEN			 
                DELETE FROM bdisitesp:se_ctessitespcte 
                 WHERE numcte = pNumCte 
                   AND situacion = 'L';
            
                INSERT INTO bdisitesp:se_ctessitespcte_his
                (empresa, sucursal, numcte, situacion, causa, tipomovto, empleadoefectuo, usralta, fchmodifica)
                VALUES
                (pEmpresa, cSucursal, pNumCte, cSituacionEsp, iCausa, 'B', pUser_Insert, pUser_Insert, pFecha_Insert);
            END IF;
        END IF;
        
        RETURN v_CodRet;
    END IF;
    
    END;
    
END PROCEDURE

