CREATE PROCEDURE "informix".sp_ipab_pagare(pFechaIni DATE, pFechaFin DATE, pNumCliente CHAR(20), pPersona CHAR(2))
RETURNING CHAR(5);
    
    DEFINE cPfisica, cExento_isr, cRegFiscal, cTipoTasa, cOperArit, cSujRet CHAR(1);
    DEFINE cTpoCuenta, cDivisa CHAR(2);    
    DEFINE cPorcentaje, cInstbase, cSobretasa CHAR(3);   
    DEFINE cNumProducto, cSucursal CHAR(4);
    DEFINE dSdo_PromInv, cPlazo, P_COD_RET, P_COD_RET2 CHAR(5); 
    DEFINE cNumCuenta, cCtaInversion CHAR(20);           
    DEFINE cNomProducto, DESC_ERR, P_COD_RET3 CHAR(40);           
    DEFINE dFechaCorte, dFechaSigCorte, dFechaContratacion DATE;               
    DEFINE sAnio, sCauRev, vexcluido SMALLINT;           
    DEFINE iDias_Proy, iAniobase, SQL_ERR, ISAM_ERR, iDias_Ini INTEGER;
    DEFINE sResiduo DECIMAL(9,3);
    DEFINE dtasa, dPorRetencionSuj, dtasax2 DECIMAL(9,6); 
    DEFINE mISR_Proy, mInt_Proy, mSdo_Inv_Proy, mInt_al_Inicio, mCapital, mSdo_Ini, mSdo_Prom_Ini, dImp_Isr_Ini, mSdo_Prom_Fin MONEY(18,2);

    LET cPfisica           = "";            LET cExento_isr        = "";            LET cRegFiscal         = "N";
    LET cTipoTasa          = "1";           LET cOperArit          = NULL;          LET cSujRet            = "S";
    LET cTpoCuenta         = "CI";          LET cDivisa            = "";            LET cPorcentaje        = NULL;
    LET cInstbase          = NULL;          LET cSobretasa         = NULL;          LET cNumProducto       = "";            
    LET cSucursal          = "";            LET dSdo_PromInv       = NULL;          LET cPlazo             = "";            
    LET P_COD_RET          = "00000";       LET P_COD_RET2         = "00000";       LET cNumCuenta         = "";            
    LET cCtaInversion      = "";            LET cNomProducto       = "";            LET DESC_ERR           = "";            
    LET P_COD_RET3         = "";            LET dFechaCorte        = NULL;          LET dFechaSigCorte     = NULL;          
    LET dFechaContratacion = "01-01-1900";  LET sAnio              = 0;             LET sCauRev            = 0;             
    LET vexcluido          = 0;             LET iDias_Proy         = 0;             LET iAniobase          = 0;             
    LET SQL_ERR            = 0;             LET ISAM_ERR           = 0;             LET iDias_Ini 		   = 0;             
    LET sResiduo           = 0;             LET dtasa              = 0;             LET dPorRetencionSuj   = 0;      
    LET dtasax2            = 0;             LET mISR_Proy          = 0;             LET mInt_Proy          = 0;             
    LET mSdo_Inv_Proy      = 0;             LET mInt_al_Inicio 	   = 0;             LET mCapital           = 0.00;          
    LET mSdo_Ini 		   = 0;             LET mSdo_Prom_Ini 	   = 0;             LET dImp_Isr_Ini 	   = 0;             
    LET mSdo_Prom_Fin 	   = 0;
                      
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_pagare.out';
    --- TRACE ON;

    BEGIN

    ON EXCEPTION SET SQL_ERR, ISAM_ERR, DESC_ERR
        SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_pagare.err';
        TRACE ON;
        LET P_COD_RET = SQL_ERR;
        LET P_COD_RET2 = ISAM_ERR;
        LET P_COD_RET3 = DESC_ERR;
        RETURN P_COD_RET;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;

    SELECT valor
      INTO dPorRetencionSuj
      FROM bdinteg:si_fechavalor
     WHERE tasa = "I.S.R." 
       AND fecha = (SELECT max(fecha)
                      FROM bdinteg:si_fechavalor
                     WHERE tasa = "I.S.R.");

    LET sAnio = year(pFechaFin);
    LET sResiduo = mod(sAnio, 4);

    IF sResiduo = 0 THEN
        LET iAniobase = 366;
    ELSE
        LET iAniobase = 365;
    END IF;

    LET dPorRetencionSuj = dPorRetencionSuj / 100;

    FOREACH
        SELECT nvl(cta_cheques, ''), nvl(cuenta, ''), nvl(capital , 0), nvl(cod_instrum, ''), 
               nvl(sucursal, ''), nvl(fecha_alta, '05/01/2007'), nvl(tasa, 0), nvl(plazo, 0)
          INTO cNumCuenta, cCtaInversion, mCapital, cNumProducto, cSucursal, dFechaContratacion, dtasa, cPlazo
          FROM bdinvers:sv_maeinv 
         WHERE num_cte = pNumCliente
           AND fecha_alta <= pFechaIni 
           AND fecha_venc > pFechaIni
           AND ( fec_cancelac > pFechaIni or fec_cancelac is null )
        
        SELECT es_fisica, exento_isr
          INTO cPfisica, cExento_isr
          FROM bdinteg:si_tipper
         WHERE tpo_persona = pPersona;

        IF cExento_isr = 'N' THEN
            LET cSujRet = 'S';
        ELSE
            LET cSujRet = 'N';
        END IF;

        IF cSujRet <> 'S' THEN                
            LET dPorRetencionSuj = 0;
        END IF;   

        SELECT COUNT(*)
          INTO vexcluido
          FROM bdinteg:si_excluidosipab 
         WHERE numcte = pNumCliente;

        IF vexcluido > 0 THEN
            LET sCauRev = 1;
        ELSE
            LET sCauRev = 0;
        END IF;
        
        LET dtasax2 = dtasa / 100;

        -- // OBTIENE EL NOMBRE DEL PRODUCTO Y LA MONEDA
        SELECT nombre, substring (nvl(moneda, ' ') from 2 for 1)
          INTO cNomProducto, cDivisa
          FROM bdinvers:sv_instrum
         WHERE cod_instrum  = cNumProducto;
        
        -- // OBTIENE SALDO PROYECTADO A AL FECHA FINAL DE LA PROYECCION
        LET mSdo_Prom_Fin = mCapital;
        LET iDias_Proy = (pFechaFin - dFechaContratacion) + 1;
        LET mInt_Proy = (mCapital * dtasax2 * iDias_Proy) / 360;
        
        IF dPorRetencionSuj <> 0 THEN
            LET mISR_Proy = (((mCapital * dPorRetencionSuj) * iDias_Proy) / iAniobase);
        ELSE
            LET mISR_Proy = 0;
        END IF;
        
        IF pFechaIni = pFechaFin THEN
            LET mSdo_Inv_Proy = mCapital + mInt_Proy;
        ELSE
            LET mSdo_Inv_Proy = ( mCapital + mInt_Proy ) - mISR_Proy;
        END IF;

        -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
        INSERT INTO si_infpattit_ipab VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion),  UPPER(cTpoCuenta), UPPER(cRegFiscal), cPorcentaje, NVL(sCauRev, 0), UPPER(cNomProducto), UPPER(cSucursal), 
          NVL(mSdo_Inv_Proy,0), UPPER(cDivisa), dFechaCorte, dFechaContratacion, cPlazo, cTipoTasa, NVL(dtasa,0), cInstbase, cSobretasa, cOperArit, dFechaSigCorte, 
          dSdo_PromInv, iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDias_Proy, mCapital, mSdo_Prom_Fin, mInt_Proy, mISR_Proy );

        -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
        INSERT INTO si_ctaasotit_ipab VALUES
        ( UPPER(cNumCuenta), UPPER(cCtaInversion), UPPER(pNumCliente), 100.00 );
    END FOREACH;

    RETURN P_COD_RET;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_ht_detalle_ctrl_tels
(
pArchivo	CHAR(13),
pValido		CHAR(1), 
pSalto		INTEGER
)
RETURNING
	CHAR(6) 		AS cod_ret,
	CHAR(14)		AS folio_archivo,
	CHAR(20)		AS num_cte,
	CHAR(10)		AS fecha_cte,
	VARCHAR(107)	AS nombre,
	CHAR(13)		AS telefono,
	SMALLINT		AS tipo_tel,
	CHAR(1)			AS tipo_prod,
	CHAR(1)			AS valido
	

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cCodRet			CHAR(6);
	
	DEFINE cFolioArchivo	CHAR(13);
	DEFINE cNumCte			CHAR(20);
	DEFINE cFechaCte		CHAR(10);
	DEFINE cNombre			VARCHAR(107);
	DEFINE cTelefono		CHAR(13);
	DEFINE iTipoTel			SMALLINT;
	DEFINE cTipoProd		CHAR(1);
	DEFINE cValido			CHAR(1);
	DEFINE iTotCtes			INT8;
	DEFINE iTelsEnviados	INT8;
	DEFINE iTelsValidos		INT8;
	DEFINE iTelsInvalidos	INT8;

	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cCodRet             = "000000";
	
	LET cFolioArchivo		= "";
	LET cNumCte				= "";
	LET cFechaCte			= "";
	LET cNombre				= "";
	LET cTelefono			= "";
	LET iTipoTel			= 0;
	LET cTipoProd			= "";
	LET cValido				= "";
	LET iTotCtes			= 0;
	LET iTelsEnviados		= 0;
	LET iTelsValidos		= 0;
	LET iTelsInvalidos		= 0;
	

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cFolioArchivo, cNumCte, cFechaCte, cNombre, cTelefono, iTipoTel, cTipoProd, cValido;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_cons_detalle_ctrl_tels.out';
	--TRACE ON;
	
	IF pArchivo IS NULL OR pValido IS NULL THEN  --// VALIDA QUE SI ES NULO	
		LET cCodRet = "000001";	
	ELSE --// ES UN FOLIO EN ESPECIFICO
		FOREACH
			SELECT SKIP pSalto LIMIT 5000 folio_archivo,num_cte,fecha_cte,TRIM(nombre1) || " " || TRIM(nombre2) || " " || TRIM(apell_paterno) || " " || TRIM(apell_materno),telefono,tipo_tel,tipo_prod,valido
			INTO cFolioArchivo, cNumCte, cFechaCte, cNombre, cTelefono, iTipoTel, cTipoProd, cValido
			FROM "informix".si_ht_detalle_ctrl_tels
			WHERE folio_archivo = DECODE(pArchivo,"",folio_archivo,pArchivo)
			AND valido = DECODE(pValido,"",valido,pValido)
			
			RETURN cCodRet, cFolioArchivo, cNumCte, cFechaCte, cNombre, cTelefono, iTipoTel, cTipoProd, cValido WITH RESUME;
		END FOREACH
		--// NO EXISTEN DATOS
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet = "000002";
			RETURN cCodRet, cFolioArchivo, cNumCte, cFechaCte, cNombre, cTelefono, iTipoTel, cTipoProd, cValido;
		END IF
	END IF
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para consultar los teléfonos enviados a marcatel',
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Junio 2014';

CREATE PROCEDURE "informix".sp_generaarchivodiarioclientecoppel( pdFecha DATE )
RETURNING CHAR(5) AS CodRetorno;

    -- ****************************************************************************************************
    -- DESCRIPCION: Genera un archivo de intercambio que contiene  el número de tarjeta Bancoppel, 
    --              número de cliente Coppel, número de cliente Bancoppel,
    --			    fecha de generación del dato y estatus de la tarjeta bancoppel de las tarjetas bancoppel
    --			    cuyo estatus fue modificado en el periodo de fechas indicado.
    -- AUTOR : Casanova Edeza Hector Juan
    -- FECHA : 18/02/2009
    -- BD: BdInteg
    -- SISTEMA : Inventario de Tarjetas Caja Unica.
    -- ****************************************************************************************************
    
    DEFINE vsRepositorio CHAR (200);
    DEFINE viDiasposteriores INTEGER;
    DEFINE vdtFechaIni DATETIME YEAR TO FRACTION(5);
    DEFINE vdtFechaFin DATETIME YEAR TO FRACTION(5);
    DEFINE vsNumTarjetaBanco CHAR (25);
    DEFINE vsNumClienteCoppel CHAR (20);
    DEFINE vsNumClienteBanco CHAR (20);
    DEFINE vsEstatusTarjeta CHAR (1);
    DEFINE vdFecha DATE;
    DEFINE vsNomArchivo CHAR (25);
    DEFINE vsNomArchivoF CHAR (25);
    DEFINE vsSQL CHAR (1050) ;
    DEFINE vsSQL1 CHAR (150);
    DEFINE vsSQL2 CHAR (750) ;
    DEFINE vsSQL3 CHAR (150) ;
    DEFINE vsFlagSystem CHAR (1);
    DEFINE viContadorRegistros INTEGER;
    DEFINE vsFlagEnTransaccion CHAR (1);
    DEFINE vsCodRetorno CHAR (5);
    DEFINE viSqlError INTEGER;

    LET vsRepositorio = '';
    LET viDiasposteriores = 0;
    LET vdtFechaIni = CURRENT;
    LET vdtFechaFin = CURRENT;
    LET vsNumTarjetaBanco = '';
    LET vsNumClienteCoppel = '';
    LET vsNumClienteBanco = '';
    LET vsEstatusTarjeta = '';
    LET vdFecha = CURRENT;
    LET vsNomArchivo = '';
    LET vsNomArchivoF = '';
    LET vsSQL = '' ;
    LET vsSQL1 = '' ;
    LET vsSQL2 = '' ;
    LET vsSQL3 = '' ;
    LET vsFlagSystem = '';
    LET viContadorRegistros = 0;
    LET vsFlagEnTransaccion = 'F';
    LET vsCodRetorno = '00000';
    LET viSqlError = 0;

    --- SET DEBUG FILE TO '/tmp/sp_GeneraArchivoDiarioClienteCoppel.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET viSqlError    --cacha el error en caso de que exista y regresa un valor predeterminado
        -- TERMINA EL ULTIMO BLEQUE DE TRANSACCION PENDIENTE.
        IF ((viContadorRegistros > 0) OR (vsFlagEnTransaccion = 'V')) THEN --VERIFICA SI EXISTE UN BLOQUE DE TRANSACCION PENDIENTE
            ROLLBACK WORK;
            LET vsFlagEnTransaccion = 'F';
        END IF;

        -- ELIMINA LA TABLA TEMPORAL DE REPORTE
        SET ISOLATION TO DIRTY READ;
        IF EXISTS ( SELECT dbsname, tabname 
                      FROM sysmaster:SysTabNames  
                     WHERE partnum > 0 
                       and tabname = 'tmpreportearchclientecoppel' 
                       AND dbsname= 'bdinteg') THEN
            DROP TABLE BdInteg:TmpReporteArchClienteCoppel;
        END IF;

        LET vsCodRetorno = viSqlError;

        IF (vsFlagSystem = '1') THEN -- ERROR DE GENERACION DEL ARCHIVO
            LET vsCodRetorno = '00105';
        END IF;

        RETURN vsCodRetorno ;
    END EXCEPTION;

    -- SET DEBUG FILE TO "/tmp/conciliacion/trace.txt";
    -- TRACE ON;

    IF ( pdFecha IS NULL ) THEN -- // LA FECHA ES NULO
        LET vsCodRetorno = '00100';
    ELIF NOT EXISTS (SELECT Comentario FROM BdInteg:si_vbParam WHERE Desc_Campo = "ruta_archivo" ) THEN -- // NO EXISTE EL PARAMETRO DEL REPOSITORIO DEL ARCHIVO DE INTERCAMBIO
        LET vsCodRetorno = '00101';
    ELIF NOT EXISTS (SELECT Valor FROM BdInteg:si_vbParam WHERE Desc_Campo = "dias_archivo" ) THEN -- // NO EXISTE EL PARAMETRO DEL ALCANCE EN DIAS DE LA CONSULTA
        LET vsCodRetorno = '00102';
    ELSE
        -- // OBTIENE LA RUTA DEL REPOSITORIO DONDE SE DEJA EL ARCHIVO DE INTERCAMBIO.
        SET ISOLATION TO DIRTY READ;
        SELECT FIRST 1 Comentario 
          INTO vsRepositorio 
          FROM BdInteg:si_vbParam 
         WHERE Desc_Campo = "ruta_archivo";

        -- // OBTIENE EL NUMERO DE DIAS CON EL QUE SE GENERA EL ARCHIVO
        SET ISOLATION TO DIRTY READ;
        SELECT FIRST 1 Valor 
          INTO viDiasposteriores 
          FROM BdInteg:si_vbParam 
         WHERE Desc_Campo = "dias_archivo";

        -- // ESTABLECE EL RANGO DE FECHA DE LA BUSQUEDA DE REGISTROS.
        LET vdtFechaFin = YEAR (pdFecha) || '-' || MONTH (pdFecha) || '-' || DAY (pdFecha) || ' 23:59:59';
        LET vdtFechaIni = YEAR (pdFecha - viDiasposteriores) || '-' || MONTH (pdFecha - viDiasposteriores) || '-' || DAY (pdFecha - viDiasposteriores) || ' 00:00:00';


        -- // VALIDA SI EXISTE LA TABLA DEL REPORTE
        SET ISOLATION TO DIRTY READ;
        IF EXISTS ( SELECT dbsname, tabname 
                      FROM sysmaster:SysTabNames  
                     WHERE partnum > 0
                       and tabname = 'tmpreportearchclientecoppel' 
                       AND dbsname= 'bdinteg') THEN
            DROP TABLE BdInteg:TmpReporteArchClienteCoppel;
        END IF;

        -- // CREA LA TABLA DEL REPORTE
        CREATE TABLE TmpReporteArchClienteCoppel
        (
            NumTarjetaBanco CHAR (25),
            NumClienteCoppel CHAR (20),
            NumClienteBanco CHAR (20),
            EstatusTarjeta CHAR (1),
            Fecha DATE
        );

        -- // OBTIENE LOS DATOS DE LAS TARJETAS CUYO ESTATUS FUE MODIFICADO DENTRO DEL RANGO DE FECHAS INDICADO.
        SET ISOLATION TO DIRTY READ;
        FOREACH WITH HOLD 
            SELECT {+INDEX (bdinteg:si_clienteconfirmado idx_clienteconfirmado)}
                   LPAD(TRIM(CteCon.NumCteBanCoppel), 9, '0'), 
                   CteCon.NumCteCoppel, Tar.NumTarjeta, Tar.FechaUltModif, 
                   DECODE (Tar.CodStatusTarjeta,'ACT','A','I') AS EstatusTarjeta
              INTO vsNumClienteBanco, vsNumClienteCoppel, vsNumTarjetaBanco, vdFecha, vsEstatusTarjeta
              FROM BdInteg:Si_ClienteConfirmado AS CteCon, 
                   Intercard:Tarjeta AS Tar
             WHERE CteCon.NumCteBanCoppelformat = Tar.NumCliente 
               AND Tar.FechaUltModif BETWEEN vdtFechaIni AND vdtFechaFin

            -- // ACTIVA EL BLOQUE DE REGISTROS POR TRANSACCION
            IF (vsFlagEnTransaccion = 'F') THEN
                BEGIN WORK;
                LET vsFlagEnTransaccion = 'V';
            END IF;

            INSERT INTO BdInteg:TmpReporteArchClienteCoppel ( NumTarjetaBanco, NumClienteCoppel, NumClienteBanco, EstatusTarjeta, Fecha)
            VALUES (vsNumTarjetaBanco, vsNumClienteCoppel, vsNumClienteBanco, vsEstatusTarjeta, vdFecha);

            LET viContadorRegistros = viContadorRegistros + 1;

            -- // TERMINA EL BLOQUE DE REGISTROS POR TRANSACCION
            IF (viContadorRegistros = 100) THEN -- // VERIFICA SI ALCANSO EL MAXIMO DE TRANSACCIONES POR BLOQUE
                COMMIT WORK;
                LET vsFlagEnTransaccion = 'F';
                LET viContadorRegistros = 0;
                CONTINUE FOREACH;
            END IF;
        END FOREACH ;

        -- // TERMINA EL ULTIMO BLEQUE DE TRANSACCION PENDIENTE.
        IF ((viContadorRegistros > 0) OR (vsFlagEnTransaccion = 'V')) THEN -- // VERIFICA SI EXISTE UN BLOQUE DE TRANSACCION PENDIENTE
            COMMIT WORK;
            LET vsFlagEnTransaccion = 'F';
        END IF;

        LET viContadorRegistros = 0;

        -- // GENERA EL NOMBRE DEL ARCHIVO DE INTERCAMBIO  CLICOPBANAAAAMMDD##.DAT
        LET vsNomArchivo = 'CLICOPBAN' || REPLACE (SUBSTRING (CURRENT FROM 1 FOR 10), '-', '' ) || '.txt';
        LET vsNomArchivoF = 'CLICOPBAN' || REPLACE (SUBSTRING (CURRENT FROM 1 FOR 10), '-', '' ) || '.dat';

        LET vsSQL1 = 'echo "UNLOAD TO ' || TRIM(vsRepositorio) || '/originales/' || TRIM (vsNomArchivo) || ' DELIMITER ' || '''|''';
        LET vsSQL2 = "SELECT NumTarjetaBanco, NumClienteCoppel, NumClienteBanco, EstatusTarjeta, Fecha FROM BdInteg:TmpReporteArchClienteCoppel;" ;
        LET vsSQL3 = ' " > '|| TRIM(vsRepositorio) || '/originales/control_reporte.sql';

        LET vsSQL1 = TRIM(vsSQL1);
        LET vsSQL3 = TRIM(vsSQL3);
        LET vsSQL = vsSQL1 || vsSQL2 || vsSQL3;

        -- // CHECA QUE NO ESTE VACIA LA CONSULTA
        IF ( vsSQL <> '' ) THEN
            LET vsFlagSystem = '1';

            -- // CREA ARCHIVO DE CONTROL
            SYSTEM vsSQL ;

            let vsSQL = '' ;
            LET vsSQL = 'dbaccess BdInteg ' || TRIM(vsRepositorio) || '/originales/control_reporte.sql' ;
            SYSTEM vsSQL ;

            LET vsSQL = "sed 's/|$//g' "|| TRIM(vsRepositorio) ||'/originales/'|| TRIM (vsNomArchivo) || " > " || TRIM(vsRepositorio) ||'/originales/'|| TRIM (vsNomArchivoF);
            SYSTEM vsSQL;

            LET vsSQL = 'rm ' || TRIM(vsRepositorio) ||'/originales/'|| TRIM (vsNomArchivo)  ;
            SYSTEM vsSQL ;
            
            -- // BORRA EL ARCHIVO DE CONTROL
            let vsSQL = '' ;
            LET vsSQL = 'rm ' || TRIM(vsRepositorio) || '/originales/control_reporte.sql' ;
            SYSTEM vsSQL ;

            LET vsFlagSystem = '';
        ELSE 
            -- // CONSULTA VACIA
            LET vsCodRetorno = '00104';
        END IF ;

        -- // ELIMINA LA TABLA TEMPORAL DE REPORTE
        SET ISOLATION TO DIRTY READ;
        IF EXISTS ( SELECT dbsname, tabname 
                      FROM sysmaster:SysTabNames  
                     WHERE partnum > 0 
                       and tabname = 'tmpreportearchclientecoppel' 
                       AND dbsname= 'bdinteg') THEN
            DROP TABLE BdInteg:TmpReporteArchClienteCoppel;
        END IF;

    END IF;

    RETURN vsCodRetorno ;

    END

END PROCEDURE;

CREATE PROCEDURE "informix".sp_actstatuscomphuella(pNumCte CHAR(20),pTicket CHAR(20))

	--DATOS A REGRESAR---
	RETURNING
	CHAR(5) AS codigoretorno;
	
	--DEFINICION DE VARIABLES--
	DEFINE iSql_err INTEGER;
	DEFINE cCodRet 	CHAR(5);
	
	--INICIALIZACION DE VARIABLES--
	LET iSql_err = 0;
	LET cCodRet  = '00000';

	--SET DEBUG FILE TO "/respaldosbd/sp_actstatuscomphuella.out";
	--TRACE ON;

	BEGIN

		ON EXCEPTION SET iSql_err
			IF iSql_err <> 0 THEN
				LET cCodRet = iSql_err;
				RETURN  cCodRet;
			END IF;
		END EXCEPTION;

		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;
		
		IF EXISTS(SELECT numcte FROM bdinteg:"informix".si_huella_linea WHERE numcte = pNumCte AND status_consulta IN ('0','3','9') AND ticket <=0 ) THEN
		
			IF pTicket = '0' THEN
				LET pTicket = '';
			END IF;
			
			IF SUBSTR(pTicket,1,1) <> "-" AND NVL(pTicket, '') <> '' THEN
				--No ocurrieron errores en el servicio
				UPDATE bdinteg:"informix".si_huella_linea
				SET ticket = pTicket, status_consulta = "1"
				WHERE numcte = pNumCte;
			ELSE
				--ocurrieron errores en el servicio
				UPDATE bdinteg:"informix".si_huella_linea
				SET status_consulta = "9"
				WHERE numcte = pNumCte;
			END IF;
			
		ELSE
			LET cCodRet = '00001'; --No existe cliente en si_huella_linea
		END IF;
		
		RETURN cCodRet;
	END
END PROCEDURE
DOCUMENT
'Se actualiza bdinteg:si_huella_linea los campos ticket',
'estatus consulta de 0(Por enviar) a 1(Enviada) Si no ocurrio algun error en el servicio',
'estatus consulta de 0(Por enviar) a 3(Consultada) Si ocurrio algun error en el servicio',
'Autor :Josue Zepeda',
'FECHA : 01/agosto/2013',
'BD: bdinteg',
'ASUNTO:		Modificación',
'ELABORÓ: 		95579737 - José Ernesto Raygoza Villa',
'DESCRIPCIÓN: 	Se le cambio la condición de status_consulta de (0,9) a (1,9)',
'FECHA: 		09/11/2013',
'Folio:1354',
'Autor:92802036 - Josue Zepeda',
'Fecha:27/11/2013',
'Modificación: Se Agrega status_consulta =  3 para que tambien los tome y se actualice.',
'Sustento: Se definio por Telefono Con Manuel Osuna y Sonia Guzman, y se acepto por correo',
'se encuentra plasmado el cambio en el cuerpo del correo del día 27/11/2013',
'Solicita:Manuel Osuna',
'BD:BDINTEG';

CREATE PROCEDURE "informix".sp_ht_gen_archivo_tels
(
)
RETURNING
	CHAR(6),
	CHAR(80)
---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);

	DEFINE cRuta			CHAR(100);
	DEFINE iStatus			SMALLINT;
	DEFINE v_sql        	CHAR(1000);
	DEFINE iTelsEnviados	INT8;
	DEFINE cArchivo			CHAR(13);
	


	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";

	LET cRuta				= "";
	LET iStatus				= 0;
	LET v_sql  				= "";
	LET iTelsEnviados		= 0;
	LET cArchivo			= "";



BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_ht_gen_archivo_tels.out';
	--TRACE ON;
	
	/*
	--// OBTENER LA RUTA DEL ARCHIVO
	SELECT TRIM(valor)
	INTO cRuta
	FROM "informix".si_param
	WHERE empresa = "001" 
	AND cod_param = 999;
	*/
	
	LET cRuta = "/resplogifx/marcatel/descarga/";
	
	SELECT MAX(folio_archivo)
	INTO cArchivo
	FROM "informix".si_ht_resumen_ctrl_tels;
	
	IF cArchivo IS NULL THEN
		LET cCodRet = "000002";
		LET cDescRet = "NO HAY ARCHIVO";
	ELSE
		--// HACE LA DESCARGA DEL ARCHIVO
		LET v_sql = 'echo "UNLOAD TO ' || TRIM(cRuta) || cArchivo || '.unl' || 
			' SELECT  num_serial, folio_archivo, num_cte, fecha_cte, nombre1, nombre2, apell_paterno, apell_materno, nombre_edo, nombre_ciudad, tipo_tel, carrier, telefono ' ||
			' FROM "informix".si_ht_detalle_ctrl_tels ' ||
			' WHERE folio_archivo =''' || cArchivo || ''' AND sec_cte = 1; "'||
			' > query_descarga_archivo_marcatel.sql';
		LET v_sql = TRIM(v_sql);
		SYSTEM v_sql;
		LET v_sql = "dbaccess bdinteg query_descarga_archivo_marcatel.sql";
		SYSTEM v_sql;			

		SELECT COUNT(telefono)
		INTO iTelsEnviados 
		FROM "informix".si_ht_detalle_ctrl_tels
		WHERE folio_archivo = cArchivo
		AND sec_cte = 1;
	 
		--// ACTUALIZA EL STATUS DEL ARCHIVO
		UPDATE "informix".si_ht_resumen_ctrl_tels
		SET status = 1, tels_enviados = iTelsEnviados
		WHERE folio_archivo = cArchivo;
	END IF
		
	RETURN cCodRet, cDescRet;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para extraer los archivos con los teléfonos válidos y generarlos en unl para su envío a marcatel',
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Julio 2014';

CREATE PROCEDURE "informix".sp_recalcula_estadisticafusion()
RETURNING CHAR(6);

	DEFINE iProcesados			INTEGER;
	DEFINE iFusionados			INTEGER;
	DEFINE iNo_fusionados		INTEGER;
	DEFINE iCantResultado		INTEGER;
	DEFINE iSqlErr				INTEGER;

	DEFINE cResultado			CHAR(5);
	DEFINE cRetorno				CHAR(6);
	
	DEFINE dFechaProceso 		DATE;
	
	LET iProcesados			= 0;
	LET iFusionados			= 0;
	LET iNo_fusionados		= 0;
	LET iCantResultado		= 0;	
	LET cRetorno 			= '000000';

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cRetorno = iSqlErr;
			ROLLBACK WORK;			
			RETURN cRetorno;
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO '/informix/sp_recalcula_estadisticafusion.out';
	--TRACE ON;
		
	BEGIN WORK;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	FOREACH 
		SELECT DISTINCT fecha_proceso
		INTO dFechaProceso
		FROM si_fusionaut
		WHERE fecha_proceso IS NOT NULL
		ORDER BY fecha_proceso ASC

		SELECT NVL(SUM(procesados),0) AS procesados, NVL(SUM(fusionados),0) AS fusionados, NVL(SUM(no_fusionados),0) AS no_fusionados
		INTO iProcesados, iFusionados, iNo_fusionados
		FROM (TABLE(MULTISET(SELECT {+INDEX (bdinteg:"informix".si_fusionaut idx_fusfp_estatus)} 
								CASE WHEN estatus IS NOT NULL THEN NVL(COUNT(cliente_tit),0) END AS procesados,
								CASE WHEN estatus = '1' THEN NVL(COUNT(cliente_tit),0) END AS fusionados,
								CASE WHEN estatus >= '2' THEN NVL(COUNT(cliente_tit),0) END AS no_fusionados
							FROM bdinteg:si_fusionaut
							WHERE fecha_proceso = dFechaProceso::DATE
							AND canal = '1'
							AND fecha_insert = '05-13-2014'
							GROUP BY estatus)));

		IF EXISTS (SELECT fecha_proceso FROM bdinteg:si_estadistica_fusiones WHERE fecha_proceso = dFechaProceso::DATE AND tipo_fusion = '1') THEN
			UPDATE bdinteg:si_estadistica_fusiones 
			SET procesados = iProcesados, fusionados = iFusionados, no_fusionados = iNo_fusionados 
			WHERE fecha_proceso = dFechaProceso::DATE 
			AND tipo_fusion = '1';
		ELSE
			INSERT INTO bdinteg:si_estadistica_fusiones (fecha_proceso, tipo_fusion, procesados, fusionados, no_fusionados, user_proceso, user_insert, fecha_insert)
			VALUES (dFechaProceso::DATE, '1', iProcesados, iFusionados, iNo_fusionados, 'infoaut', USER, CURRENT);
		END IF;

		FOREACH 
			SELECT DISTINCT cod_retorno, COUNT(*)
			INTO cResultado, iCantResultado
			FROM bdinteg:si_fusionaut 
			WHERE fecha_proceso = dFechaProceso::DATE
			AND canal = '1'
			AND fecha_insert = '05-13-2014'
			GROUP BY cod_retorno

			IF EXISTS (SELECT fecha_proceso FROM bdinteg:si_estadistica_fusiones_det WHERE fecha_proceso = dFechaProceso AND tipo_fusion = '1' AND cod_retorno = cResultado) THEN
				UPDATE bdinteg:si_estadistica_fusiones_det 
				SET cantidad = iCantResultado
				WHERE fecha_proceso = dFechaProceso 
				AND tipo_fusion = '1' 
				AND cod_retorno = cResultado;
			ELSE
				INSERT INTO bdinteg:si_estadistica_fusiones_det (fecha_proceso, tipo_fusion, cod_retorno, cantidad, user_proceso, user_insert, fecha_insert)
				VALUES (dFechaProceso::DATE, '1', cResultado, iCantResultado, 'infoaut', USER, CURRENT);
			END IF;
		END FOREACH;
	END FOREACH;

	COMMIT WORK;
	RETURN cRetorno;
END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_upd_emp_gc_2()
				returning CHAR(5) AS Cod_Retorno;


DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;
--SISTEMA DE CUENTA 01 VARIABLES
DEFINE cTicket			CHAR(20);
DEFINE cEmpleado		CHAR(10);
DEFINE cEmpresa			CHAR(4);
DEFINE cNumcte			CHAR(20);
DEFINE cNumcte2			CHAR(20);
DEFINE cValidanumcte	CHAR(20);
DEFINE iNumRows			INTEGER;
DEFINE cNombreEm		CHAR(104);
DEFINE cNombreEm2		CHAR(104);
DEFINE cFnac			DATE;
DEFINE cNombre1			CHAR(26);
DEFINE cNombre2			CHAR(26);
DEFINE cPaterno			CHAR(26);
DEFINE cMaterno			CHAR(26);
DEFINE cFecha			DATE;
DEFINE cParam			CHAR(50);


--inicializando variables
LET  iexiste = 0;
LET cCodRet = "00000";
LET iSql_err = 0 ;
LET cTicket = "" ;
LET cEmpleado = "" ;
LET cEmpresa = "" ;
LET cNumcte="";
LET cValidanumcte="";
LET iNumRows=0;
LET cNombreEm="";
LET cNombreEm2="";
LET cNombre1="";
LET cNombre2="";
LET cPaterno="";
LET cMaterno="";
LET cNumcte2="";
LET cParam = "" ;

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/informix/ArmandoM/sp_upd_emp_gc_2.out";
	--TRACE ON;

	SELECT valor INTO cParam
	FROM si_param
	WHERE cod_param = 308;

	SET ISOLATION TO DIRTY READ;
	FOREACH
		SELECT  b.emp, a.numcte, TRIM(nombre1)|| ' ' ||TRIM(nombre2)|| ' '||TRIM(apell_paterno)|| ' ' ||TRIM(apell_materno) INTO cEmpleado,cNumcte,cNombreEm
		FROM si_funciones b, si_cliente a, si_ctepf c
		WHERE b.fnac=c.fecha_nac
		AND TRIM(b.nombre)=TRIM(apell_paterno)|| ' ' ||TRIM(apell_materno)|| ' ' ||TRIM(nombre1)|| ' ' ||TRIM(nombre2)
		AND a.numcte=c.numcte
		AND b.emp NOT IN (SELECT {+INDEX (bdinteg:si_ejecut idx_si_ejecut)} ejecutivo FROM bdinteg:si_ejecut WHERE password NOT IN ('BAJA','baja'))
		AND a.tipo_cliente = '1'
		AND a.fecha_alta >= cParam
		
		SELECT {+INDEX (bdinteg:si_empleado_cliente_coppel idx_cte_emp2)} FIRST 1 numcte INTO cNumcte2 FROM bdinteg:si_empleado_cliente_coppel WHERE numcte=cNumcte;
		LET iexiste = dbinfo("sqlca.sqlerrd2");
		IF iexiste=0 THEN
			INSERT INTO "informix".si_empleado_cliente_coppel (numcte,empleado,cve_proceso,empresa,fecha,hora,status) 
			VALUES (cNumcte,cEmpleado,3,null,current year to fraction(3),current year to fraction(3),1);
		ELSE
			UPDATE bdinteg:si_empleado_cliente_coppel SET empleado= cEmpleado WHERE numcte=cNumcte AND empleado IS NULL;
		END IF;	
	END FOREACH;
	
	UPDATE si_param set valor = TODAY WHERE cod_param = 308;
	
	RETURN cCodRet;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_borrar_folioarchivo()
RETURNING
	CHAR(6) 	AS cod_ret,
	CHAR(80)	AS desc_ret

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);
	DEFINE vabierto     	CHAR(1);
	DEFINE vcontador3   	INTEGER;
	

	DEFINE iNumSerial		INT8;



	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";
	LET vabierto   			= '0';
	LET vcontador3 			= 0;


	LET iNumSerial			= 0;
	


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
            IF vabierto = '1' THEN
                ROLLBACK WORK;
            END IF;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_borrar_folioarchivo.out';
	--TRACE ON;

	
	FOREACH WITH HOLD
		SELECT num_serial
		INTO iNumSerial
		FROM "informix".si_ht_detalle_ctrl_tels
		WHERE folio_archivo = "1371406260121" AND num_serial = num_serial

		IF vcontador3 = 0 THEN
			BEGIN WORK;
			LET vabierto = '1'; 
		END IF	

		DELETE "informix".si_ht_detalle_ctrl_tels
		WHERE folio_archivo = "1371406260121" AND num_serial = iNumSerial;
		
		LET iNumSerial = 0;
		
		LET vcontador3 = vcontador3 + 1;
		
		IF vcontador3 = 1000 THEN
			LET vabierto = '0';
			LET vcontador3 = 0;
			COMMIT WORK;
		END IF
	END FOREACH	
	
	DELETE "informix".si_ht_resumen_ctrl_tels
	WHERE folio_archivo = "1371406260121";

	IF vcontador3 > 0 THEN
		COMMIT WORK;
	END IF	
	
	RETURN cCodRet, cDescRet;
    	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para',
'BD: bdicheq', 
'AUTOR: Mohamed Carreón ',
'FECHA: Junio 2014';

CREATE PROCEDURE "informix".sp_consultadireccionactual(pConsulta INTEGER, pEmpresa CHAR(3), pNumcte CHAR(20), pSecuencia INTEGER, pTipoDir CHAR(1) )
     RETURNING CHAR(5), INTEGER, CHAR(1), CHAR(30), CHAR(60), CHAR(30), CHAR(32), CHAR(30), CHAR(10), CHAR(10), CHAR(6), CHAR(5), CHAR(1),
                          CHAR(13), CHAR(13), CHAR(13), CHAR(5), CHAR(5), CHAR(5), CHAR(5), CHAR(5), CHAR(5), CHAR(5);

-- Creado: Daniela Ramirez Perez
-- Fecha: 25/03/2011
-- Actividad: Consulta direccion actual del cliente

-- Modificado: Jessica Gutiérrez
-- Fecha: 17/05/2014
-- Descripción: Se modifican las consultas para mostrar todas las direcciones del cliente, ordenadas en forma descendente.
--              Mostrando la direccion mas actual en primer lugar y asi sucesivamente.

-- Se definen variables
        DEFINE cCodRet CHAR(5);
        DEFINE iSqlErr INTEGER;

        DEFINE iRegistroActual INTEGER;
        DEFINE iRegistroDir INTEGER;
        DEFINE cTipo_dir CHAR(1);
        DEFINE cEstado CHAR(30);
        DEFINE cCiudad CHAR(60);
        DEFINE cMunicipio CHAR(30);
        DEFINE cNombreZona CHAR(32);
        DEFINE cNombreCalle CHAR(30);
        DEFINE cNumExtCalle CHAR(10);
        DEFINE cNumIntCalle CHAR(10);
        DEFINE cDepto CHAR(6);
        DEFINE cCod_postal CHAR(5);
        DEFINE cPuntoCardinal CHAR(1);
        DEFINE cTelefono1 CHAR(13);
        DEFINE cTelefono2 CHAR(13);
        DEFINE cTelefono3 CHAR(13);
        DEFINE cExtension CHAR(5);
        DEFINE iManzana CHAR(5);
        DEFINE iOtros CHAR(5);
        DEFINE iAndador CHAR(5);
        DEFINE iEtapa CHAR(5);
        DEFINE iEdificio CHAR(5);
        DEFINE iEntrada CHAR(5);
        DEFINE cEmpresa CHAR(3);
        DEFINE cNumCte CHAR(20);

-- Se inicializan variables
        LET cCodRet = "00000";
        LET iSqlErr = 0;

        LET iRegistroActual = 0;
        LET iRegistroDir = 0;
        LET cTipo_dir = " ";
        LET cEstado = " ";
        LET cCiudad = " ";
        LET cMunicipio = " ";
        LET cNombreZona = " ";
        LET cNombreCalle = " ";
        LET cNumExtCalle = " ";
        LET cNumIntCalle = " ";
        LET cDepto = " ";
        LET cCod_postal = " ";
        LET cPuntoCardinal = " ";
        LET cTelefono1 = " ";
        LET cTelefono2 = " ";
        LET cTelefono3 = " ";
        LET cExtension = " ";
        LET iManzana = " ";
        LET iOtros = " ";
        LET iAndador = " ";
        LET iEtapa = " ";
        LET iEdificio = " ";
        LET iEntrada = " ";
        LET cEmpresa = " ";
        LET cNumCte = " ";

--        SET DEBUG FILE TO "/respaldosbd/Daniela/sp_consultadireccionactual.out";
--        TRACE ON;

        BEGIN
                ON EXCEPTION SET iSqlErr
                        IF iSqlErr !=0 THEN
                                LET cCodRet = iSqlErr;
                                RETURN cCodRet, iRegistroActual, cTipo_dir, cEstado, cCiudad, cMunicipio, cNombreZona, cNombreCalle, cNumExtCalle, cNumIntCalle, cDepto, cCod_postal,
                                              cPuntoCardinal, cTelefono1, cTelefono2, cTelefono3, cExtension, iManzana, iOtros, iAndador, iEtapa, iEdificio, iEntrada;
                        END IF;
                END EXCEPTION;

                IF pConsulta = 1 THEN --Regresa el número de registros

                        SELECT COUNT(distinct dir.secuencia)
						INTO iRegistroActual
						FROM bdinteg:"informix".si_cliente AS cte
						LEFT JOIN bdinteg:"informix".si_direcciones_actual dir ON (dir.numcte=cte.numcte)
						WHERE cte.empresa = pEmpresa AND cte.numcte = pNumcte;
						
                                RETURN  cCodRet, iRegistroActual, cTipo_dir, cEstado, cCiudad, cMunicipio, cNombreZona, cNombreCalle, cNumExtCalle, cNumIntCalle, cDepto, cCod_postal,
                                                  cPuntoCardinal, cTelefono1, cTelefono2, cTelefono3, cExtension, iManzana, iOtros, iAndador, iEtapa, iEdificio, iEntrada;

              ELIF pConsulta = 2 THEN --Regresa secuencia con tipo de direccion

                    SELECT  {+INDEX (bdinteg:"informix".si_cliente idx_si_cliente5)} empresa, numcte
                    INTO cEmpresa, cNumCte
                    FROM bdinteg:"informix".si_cliente
                    WHERE empresa = pEmpresa AND numcte = pNumcte;

                         FOREACH

                                    SELECT {+INDEX (bdinteg:si_direcciones_actual idx_diract_ctetpo)} dir.secuencia, dir.tipo_dir
									INTO iRegistroActual, cTipo_dir
									FROM bdinteg:si_direcciones_actual AS dir
									WHERE dir.numcte = cNumCte --AND (dir.tipo_dir = 1 OR dir.tipo_dir = 2)
									order by secuencia desc

                                    RETURN  cCodRet, iRegistroActual, cTipo_dir, cEstado, cCiudad, cMunicipio, cNombreZona, cNombreCalle, cNumExtCalle, cNumIntCalle, cDepto, cCod_postal,
                                                     cPuntoCardinal, cTelefono1, cTelefono2, cTelefono3, cExtension, iManzana, iOtros, iAndador, iEtapa, iEdificio, iEntrada WITH RESUME;

                         END FOREACH;

              ELIF pConsulta = 3 THEN --Regresa direccion

                    SELECT  {+INDEX (bdinteg:"informix".si_cliente idx_si_cliente5)} empresa, numcte
                    INTO cEmpresa, cNumCte
                    FROM bdinteg:"informix".si_cliente
                    WHERE empresa = pEmpresa AND numcte = pNumcte;

                            SELECT  {+INDEX (bdinteg:si_direcciones inx_direcciones)}
                                          dir.secuencia, dir.tipo_dir, edo.nombre AS estado, ciu.nombre AS ciudad, mun.nombre AS municipio, zon.nombrezona, cal.nombrecalle,
                                          dir.numeroextcalle, dir.numerointcalle, dir.departamento, dir.cod_postal, dir.puntocardinal,
                                          dir.manzana, dir.otros, dir.andador, dir.etapa, dir.edificio, dir.entrada
                            INTO iRegistroActual, cTipo_dir, cEstado, cCiudad, cMunicipio, cNombreZona, cNombreCalle, cNumExtCalle, cNumIntCalle, cDepto, cCod_postal,
                                     cPuntoCardinal, iManzana, iOtros, iAndador, iEtapa, iEdificio, iEntrada
                            FROM bdinteg:si_direcciones AS dir
                            LEFT JOIN si_estados AS edo ON (edo.estado = dir.estado)
                            LEFT JOIN si_ciudades AS ciu ON (ciu.ciudad = dir.ciudad AND ciu.estado = dir.estado AND ciu.pais = '001')
                            LEFT JOIN si_catzonas AS zon ON (zon.numerociudad = dir.numerociudad AND zon.numerocolonia = dir.numerocolonia )
                            LEFT JOIN si_catcalles AS cal ON (cal.numerocalle = dir.numerocalle)
                            LEFT JOIN si_municipios AS mun ON (mun.municipio = dir.municipio AND mun.pais = '001' AND mun.ciudad = dir.ciudad AND mun.estado = dir.estado)
                            WHERE dir.numcte = cNumCte AND dir.secuencia = pSecuencia;

					
                    --CONSULTA LOS NUEVOS TELEFONOS
                    LET cTelefono1 = '';
                    LET cTelefono2 = '';
                    LET cTelefono3 = '';
                    LET cExtension = '';

                    SELECT telefono INTO cTelefono1 ---TELEFONO PARTICULAR
                    from si_telefonos_actual
                    where numcte = pNumcte and tipo_tel = 1;

                    SELECT telefono,extension INTO cTelefono2,cExtension  ---TELEFONO TRABAJO
                    from si_telefonos_actual
                    where numcte = pNumcte and tipo_tel = 2;

                    SELECT telefono  INTO cTelefono3 ---TELEFONO CELULAR
                    from si_telefonos_actual
                    where numcte = pNumcte and tipo_tel = 3;

                            RETURN  cCodRet, iRegistroActual, cTipo_dir, cEstado, cCiudad, cMunicipio, cNombreZona, cNombreCalle, cNumExtCalle, cNumIntCalle, cDepto, cCod_postal,
                                             cPuntoCardinal, cTelefono1, cTelefono2, cTelefono3, cExtension, iManzana, iOtros, iAndador, iEtapa, iEdificio, iEntrada;
            END IF;

       END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultadomiciliocajera( pModo SMALLINT, pCliente CHAR(20) )
	--- pModo = 1 - Consulta de Domicilio Personal
	--- pModo = 2 - Consulta de Domicilio del Trabajo
	RETURNING CHAR(6) AS cCodRet ,CHAR(26) AS cApellidoPaterno,CHAR(26) AS cApellidoMaterno,CHAR(26) AS cNombre1,
		CHAR(26) AS cNombre2,CHAR(15) AS cNombreCiudad,CHAR(30) AS cNombreZona,CHAR(10) AS cNumeroExterior,CHAR(10) AS cNumeroInterior,
		CHAR(6) AS cDepto,CHAR(1) AS cRumbo,CHAR(30) AS cNombreCalle,CHAR(5) AS cCodigoPostal,CHAR(80) AS cObservaciones,CHAR(13) AS cTelefonoParticular,
		CHAR(13)AS cTelefonoCelular,CHAR(13) AS cTelefonoTrabajo,CHAR(13) AS cTelefonoReferencia,CHAR(40) AS cEntreCalles,CHAR(2) AS cEstado,
		CHAR(30) AS cNombreEstado,CHAR(60) AS cLugarTrabajo,CHAR(2) AS cUnidad,CHAR(3) AS cCiudad,INTEGER AS iColonia,INTEGER AS iCalle,INTEGER AS iManzana,
		INTEGER AS iOtros,INTEGER AS iAndador,INTEGER AS iEtapa,INTEGER AS iLote,INTEGER AS iEdificio,INTEGER AS iEntrada,INTEGER AS iCiudadCoppel, CHAR(100) AS cEmail;
			  
			  
		DEFINE isqlerr INTEGER;
		DEFINE cCodRet CHAR(6);
		DEFINE cApellidoPaterno CHAR(26);
		DEFINE cApellidoMaterno CHAR(26);
		DEFINE cNombre1 CHAR(26);
		DEFINE cNombre2 CHAR(26);
		DEFINE cNombreCiudad CHAR(15);
		DEFINE cNombreZona CHAR(30);
		DEFINE cNumeroExterior CHAR(10);
		DEFINE cNumeroInterior CHAR(10);
		DEFINE cDepto CHAR(6);
		DEFINE cRumbo CHAR(1);
		DEFINE cNombreCalle CHAR(30);
		DEFINE cCodigoPostal CHAR(5);
		DEFINE cObservaciones CHAR(80);
		DEFINE cTelefonoParticular CHAR(13);
		DEFINE cTelefonoCelular CHAR(13);
		DEFINE cTelefonoReferencia CHAR(13);
		DEFINE cTelefonoTrabajo CHAR(13);
		DEFINE cEntreCalles CHAR(40);
		DEFINE cCiudad CHAR(3);
		DEFINE iColonia INTEGER ;
		DEFINE iCalle INTEGER ;
		DEFINE cUnidad CHAR(2);
		DEFINE iManzana INTEGER ;
		DEFINE iOtros INTEGER ;
		DEFINE iAndador INTEGER ;
		DEFINE iEtapa INTEGER ;
		DEFINE iLote INTEGER ;
		DEFINE iEdificio INTEGER ;
		DEFINE iEntrada INTEGER ;
		DEFINE cEstado CHAR(2);
		DEFINE cNombreEstado CHAR(30);
		DEFINE cLugarTrabajo CHAR(60);
		DEFINE iCiudadCoppel INTEGER ;
		DEFINE cEmail CHAR(100);
		
		DEFINE cNumSolicitud CHAR(20);
		DEFINE cNumSolicitud2 CHAR(20);
		DEFINE dFecha1 DATE;
		DEFINE dFecha2 DATE;
		DEFINE cProducto CHAR(4);

		LET isqlerr = 0;
		LET cCodRet = "";
		LET cApellidoPaterno = " ";
		LET cApellidoMaterno = " ";
		LET cNombre1 = " ";
		LET cNombre2 = " ";
		LET cNombreCiudad = " ";
		LET cNombreZona = " ";
		LET cNumeroExterior = " ";
		LET cNumeroInterior = " ";
		LET cDepto = " ";
		LET cRumbo = " ";
		LET cNombreCalle = " ";
		LET cCodigoPostal = " ";
		LET cObservaciones = " ";
		LET cTelefonoParticular = " ";
		LET cTelefonoCelular = " ";
		LET cTelefonoReferencia = " ";
		LET cTelefonoTrabajo = " ";
		LET cEntreCalles = " ";
		LET cCiudad = "";
		LET iColonia = 0;
		LET iCalle = 0;
		LET cUnidad= "N";
		LET iManzana = 0;
		LET iOtros = 0;
		LET iAndador = 0;
		LET iEtapa = 0;
		LET iLote = 0;
		LET iEdificio = 0;
		LET iEntrada = 0;
		LET cEstado = " ";
		LET cNombreEstado = " ";
		LET cLugarTrabajo = " ";
		LET iCiudadCoppel = 0;
		LET cEmail = " ";

		LET cNumSolicitud = '';
		LET cNumSolicitud2 = '';
		LET dFecha1 = '01/01/1900';
		LET dFecha2 = '01/01/1900';
		LET cProducto = '';

		--SET DEBUG FILE TO "/respaldosbd/AnahiLeyva/sp_consultadomiciliocajera.out";
		--TRACE ON;
		
		BEGIN

		ON EXCEPTION SET isqlerr
			IF isqlerr <> 0 THEN
				LET cCodRet = isqlerr;
				RETURN cCodRet,cApellidoPaterno,cApellidoMaterno,cNombre1,cNombre2,cNombreCiudad,cNombreZona,cNumeroExterior,cNumeroInterior,cDepto,cRumbo,
						cNombreCalle,cCodigoPostal,cObservaciones,cTelefonoParticular,cTelefonoCelular,cTelefonoTrabajo,cTelefonoReferencia,cEntreCalles,
						cEstado,cNombreEstado,cLugarTrabajo,cUnidad,cCiudad,iColonia,iCalle,iManzana,iOtros,iAndador,iEtapa,iLote,iEdificio,iEntrada,iCiudadCoppel,cEmail;
			END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;   
		
		--Se obtiene numero de solicitud
			SELECT limit 1 fecha_apertura, num_credito 		
			INTO dFecha1, cNumsolicitud
			FROM bdicred:"informix".sd_maecred 
			WHERE numcte   =  pCliente 
			AND fecha_apertura = (SELECT MAX(fecha_apertura)
								FROM bdicred:"informix".sd_maecred 
								WHERE numcte   =  pCliente );
			
			SELECT  limit 1 fecha_apertura, num_credito, num_producto 
			INTO dFecha2, cNumsolicitud2, cProducto
			FROM bdicred:"informix".sd_maecredcrd
			WHERE numcte = pCliente
			AND  fecha_apertura = (SELECT MAX (fecha_apertura) 
								FROM bdicred:"informix".sd_maecredcrd
								WHERE numcte   =  pCliente );
		
		IF dFecha1 IS NULL OR dFecha1 = "" THEN
			LET dFecha1 = '01/01/1900';
		END IF;
		
		IF dFecha2 IS NULL OR dFecha2 = ""  THEN
			LET dFecha2 = '01/01/1900';
		END IF;
		
		IF dfecha1 < dFecha2 THEN		
			IF cProducto = '6011' THEN
				SELECT num_credito 		
				INTO cNumsolicitud
				FROM bdicred:"informix".sd_maecred 
				WHERE credito_externo =  cNumsolicitud2;
			ELSE
				LET cNumsolicitud = cNumsolicitud2;
			END IF;
		END IF;		
			
		IF NVL(cNumSolicitud, '') <> '' THEN
			--Obtener el numero de telefono		
			SELECT telefono_ref 
			INTO cTelefonoReferencia  
			FROM bdisolic:"informix".ss_refpersonales 
			WHERE numcte = pCliente AND num_solicitud = cNumSolicitud
			AND numcte_ref = 'R1';

			IF NVL(cTelefonoReferencia,'') = '' THEN
				SELECT  first 1 b.telefono1 
				INTO  cTelefonoReferencia 
				FROM bdinteg:"informix".si_refclientes a, bdinteg:"informix".si_refdirecciones b
				WHERE a.empresa = '001'
				  and a.num_solicitud = cNumSolicitud
				  and a.numcte = pCliente
				  AND a.numcte = b.numcte 
				  AND a.secuencia = b.secuencia ;
			END IF;
			let cTelefonoReferencia = nvl(cTelefonoReferencia,'');
			--IF NVL(cTelefonoReferencia,'') <> '' THEN
				SELECT '000',NVL(t1.apell_paterno,''), NVL(t1.apell_materno,''), NVL(t1.nombre1,''), NVL(t1.nombre2,''), 
				NVL(t2.ciudad,0), NVL(t2.numerocolonia,0), NVL(t2.numeroextcalle,''), NVL(t2.numerointcalle,''),NVL(t2.departamento,''), 
				NVL(t2.puntocardinal,''), NVL(t2.numerocalle,0), NVL(t2.cod_postal,''), NVL(t2.observaciones,''), NVL(t2.manzana,0)::INTEGER, 
				NVL(t2.otros,0)::INTEGER, NVL(t2.andador,0)::INTEGER, NVL(t2.etapa,0)::INTEGER, NVL(t2.lote,0)::INTEGER, NVL(t2.edificio,0)::INTEGER,
				NVL(t2.entrada,0)::INTEGER, NVL(t9.telefono,''), NVL(t92.telefono,''), NVL(t93.telefono,''),
				--t7.telefono_ref as referencia, 
				NVL(t3.nombre,''), NVL(t4.nombrecalle,''), NVL(t5.nombrezona,''), NVL(t2.entre_calles,''), NVL(t2.estado,''), NVL(t6.nombre,''),--<--si_estados
				NVL((SELECT nombre_empresa
							FROM "informix".SI_INGRESOS ING1 
							WHERE ING1.tipo_ingreso = 'T'
							AND ING1.sec_ingreso = ( SELECT MAX(ING2.sec_ingreso)
														FROM "informix".si_ingresos ING2 
														WHERE t1.EMPRESA = ING2.EMPRESA 
														AND t1.NUMCTE = ING2.NUMCTE 
														AND ING2.tipo_ingreso = 'T') 
							AND t1.EMPRESA = ING1.EMPRESA 
							AND t1.NUMCTE = ING1.NUMCTE),''),
							NVL(t2.unidadhabitac,'N'), NVL(t3.ciudad_coppel,0)::INTEGER, NVL(t10.correo_elec,'')
				INTO cCodRet ,cApellidoPaterno, cApellidoMaterno, cNombre1, cNombre2, 
				cCiudad, iColonia, cNumeroExterior, cNumeroInterior, cDepto, 
				cRumbo, iCalle, cCodigoPostal, cObservaciones, iManzana, 
				iOtros, iAndador, iEtapa, iLote, iEdificio,
				iEntrada, cTelefonoParticular, cTelefonoCelular, cTelefonoTrabajo, 
				--cTelefonoReferencia, 
				cNombreCiudad, cNombreCalle, cNombreZona, cEntreCalles, cEstado, cNombreEstado, 
				cLugarTrabajo, 
				cUnidad, iCiudadCoppel, cEmail
				FROM "informix".si_cliente t1
				LEFT JOIN "informix".si_direcciones_actual t2 ON (t1.numcte = t2.numcte AND t2.tipo_dir = pModo) --- AND t2.secuencia = (SELECT MAX(t6.secuencia) FROM bdinteg:si_direcciones t6 WHERE t6.numcte = t1.numcte AND t6.tipo_dir = t2.tipo_dir )) 
				LEFT JOIN "informix".si_ciudades t3 ON t2.ciudad = t3.ciudad AND t2.estado = t3.estado
				LEFT JOIN "informix".si_catcalles t4 ON t2.numerocalle = t4.numerocalle
				LEFT JOIN "informix".si_catzonas t5 ON t2.numerociudad = t5.numerociudad AND t2.numerocolonia = t5.numerocolonia
				LEFT JOIN "informix".si_estados t6 ON t2.estado = t6.estado
				--2014/06/09
				--LEFT JOIN bdisolic:"informix".ss_refpersonales t7 ON (t1.numcte = t7.numcte AND t7.numcte_ref = 'R1')
				--JOIN bdicred:"informix".sd_maecred t8 ON (t1.numcte = t8.numcte AND t7.num_solicitud = t8.num_credito)
				LEFT OUTER JOIN "informix".si_telefonos_actual t9 ON ( t9.numcte = t1.numcte AND t9.tipo_tel = 1 )
				LEFT OUTER JOIN "informix".si_telefonos_actual t92 ON ( t92.numcte = t1.numcte AND t92.tipo_tel = 2 )
				LEFT OUTER JOIN "informix".si_telefonos_actual t93 ON ( t93.numcte = t1.numcte AND t93.tipo_tel = 3 )
				LEFT JOIN "informix".si_correos t10 ON ( t10.numcte = t1.numcte 
				AND t10.secuencia = (SELECT MAX(secuencia)
									FROM "informix".si_correos
									WHERE numcte = pCliente
									AND tipo_correo = pModo ))
				WHERE t1.numcte = pCliente;
			--ELSE
				--LET cCodRet = '002' ;  --- No existe el cliente en el catalogo de telefonos
			--END IF;
		ELSE
			LET cCodRet = '001' ;  --- No existe el cliente en el catalogo
		END IF ;
		RETURN cCodRet,cApellidoPaterno,cApellidoMaterno,cNombre1,cNombre2,cNombreCiudad,cNombreZona,cNumeroExterior,cNumeroInterior,cDepto,cRumbo,
			   cNombreCalle,cCodigoPostal,cObservaciones,cTelefonoParticular,cTelefonoCelular,cTelefonoTrabajo,cTelefonoReferencia,cEntreCalles,
			   cEstado,cNombreEstado,cLugarTrabajo,cUnidad,cCiudad,iColonia,iCalle,iManzana,iOtros,iAndador,iEtapa,iLote,iEdificio,iEntrada,iCiudadCoppel, cEmail with resume;
		END
	END PROCEDURE
	DOCUMENT
	'06/Febrero/2008',
	'Walber Castro',
	'Obtiene los datos del domicilio del cliente',
	'*********************************************',
	'17/Junio/2008',
	'Walber Castro',
	'Se corrige como toma el nombre de la empresa por el maximo de secuencia de la si_ingresos.',
	'*********************************************',
	'11/Julio/2008',
