CREATE PROCEDURE "informix".sp_generaarchivocifras_club_1()
--DATOS A REGRESAR--
RETURNING CHAR(6) AS CodigoRetorno;

--DEFINICION DE VARIABLES--
DEFINE cCodret CHAR(6);
DEFINE vMensajeRet VARCHAR(80);
DEFINE iSqlErr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE vErrorInfo VARCHAR(80);
DEFINE vProceso VARCHAR(30);
DEFINE cSql CHAR(1024);
DEFINE dFechaHoy DATE;
DEFINE cRuta CHAR(100);
DEFINE cFechaArchivo CHAR(8);
DEFINE cSucursal CHAR(4);
DEFINE iCantMovtos INTEGER;
DEFINE iImporte INTEGER;
DEFINE cTipoMovtos CHAR(1);
DEFINE dFecha DATE;
DEFINE dtFechaHora DATETIME YEAR TO SECOND;

--INICIALIZACION DE VARIABLES--
LET cCodret = '000000';
LET vMensajeRet = '';
LET iSqlErr = 0;
LET iIsamErr = 0;
LET vErrorInfo = '';
LET vProceso = 'sp_generaarchivocifras_club';
LET cSql = '';
LET dFechaHoy = '';
LET cRuta = '';
LET cFechaArchivo = '';
LET cSucursal = '';
LET iCantMovtos = 0;
LET iImporte = 0;
LET cTipoMovtos = '';
LET dFecha = '';
LET dtFechaHora = '';

--SET DEBUG FILE TO "/informix/IrisA/sp_generaarchivocifras_club.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
		IF iSqlErr <> 0 OR iIsamErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET vMensajeRet = vErrorInfo;
			INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
				VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
			RETURN cCodret;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 5;

	SELECT fecha_hoy INTO dFechaHoy 
	FROM "informix".si_fechas WHERE empresa = '001';

	IF TRIM(NVL(dFechaHoy,'')) <> '' THEN

		SELECT valor INTO cRuta 
		FROM "informix".si_param 
		WHERE empresa = '001' AND cod_param = 319;

		IF TRIM(NVL(cRuta,'')) <> '' THEN

			LET cFechaArchivo = YEAR(dFechaHoy) || LPAD(MONTH(dFechaHoy),2,'0') || LPAD(DAY(dFechaHoy),2,'0');

			TRUNCATE TABLE "informix".si_club_cifrastotales;

			FOREACH
				-- SUCURSAL
				SELECT sucursal INTO cSucursal 
				FROM "informix".si_sucursales 
				WHERE empresa = '001' AND tpo_sucursal = 'S'
				ORDER BY sucursal

				-- VENTA
				SELECT COUNT(num_poliza), SUM(monto_pagar::INT) INTO iCantMovtos, iImporte
				FROM "informix".si_club_proteccion 
				WHERE fecha_alta = today-1 AND suc_alta = cSucursal AND aceptada = '1';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('A', iCantMovtos, cSucursal, iImporte, today-1 );
				END IF;

				-- ABONO
				SELECT COUNT(a.referencia1), SUM(a.importe_pago::INT) INTO iCantMovtos, iImporte
				FROM bdisac:sac_movimientoshistorial a, bdisac:"informix".sac_abono_seg b
				WHERE a.referencia1 = b.numcliente AND a.referencia2 = b.recibo AND a.fecha_pago = today-1  
				AND a.fecha_pago = DATE(b.fecha_insert) AND a.id_sucursal = cSucursal 
				AND a.transacc_suc = '8102' AND a.status_cancelado = 'N';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('B', iCantMovtos, cSucursal, iImporte, today-1 );
				END IF;

				-- PAGO DE VENTA
				SELECT COUNT(a.referencia1), SUM(a.importe_pago::INT) INTO iCantMovtos, iImporte
				FROM bdisac:sac_movimientoshistorial a, bdisac:"informix".sac_vta_cambio_seg b
				WHERE a.referencia1 = b.numcliente AND a.referencia2 = b.recibo AND a.fecha_pago = today-1  
				AND a.fecha_pago = DATE(b.fecha_insert) AND a.id_sucursal = cSucursal
				AND a.transacc_suc = '8102' AND a.status_cancelado = 'N' AND b.tipomovimiento = 'C';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('C', iCantMovtos, cSucursal, iImporte, today-1 );
				END IF;

				-- PAGO DE CAMBIO DE PLAN
				SELECT COUNT(a.referencia1), SUM(a.importe_pago::INT) INTO iCantMovtos, iImporte
				FROM bdisac:sac_movimientoshistorial a, bdisac:"informix".sac_vta_cambio_seg b
				WHERE a.referencia1 = b.numcliente AND a.referencia2 = b.recibo AND a.fecha_pago = today-1  
				AND a.fecha_pago = DATE(b.fecha_insert) AND a.id_sucursal = cSucursal
				AND a.transacc_suc = '8102' AND a.status_cancelado = 'N' AND b.tipomovimiento = 'K';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('K', iCantMovtos, cSucursal, iImporte, today-1 );
				END IF;

				-- CAMBIO DE BENEFICIARIO
				SELECT COUNT(DISTINCT numcte) INTO iCantMovtos 
				FROM "informix".si_club_beneficiario 
				WHERE tipo_mov = 'C' AND fecha_modificacion = today-1  AND suc_cambio = cSucursal;

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('D', iCantMovtos, cSucursal, 0, today-1 );
				END IF;

				-- CAMBIO DE PLAN
				SELECT COUNT(num_poliza), SUM(monto_pagar::INT) INTO iCantMovtos, iImporte
				FROM "informix".si_club_proteccion 
				WHERE tipo_mov = 'C' AND fecha_cambio = today-1  AND suc_cambio = cSucursal;

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('H', iCantMovtos, cSucursal, iImporte, today-1 );
				END IF;

			END FOREACH;

			UPDATE statistics medium FOR TABLE "informix".si_club_cifrastotales;

			LET cSql = '';
            LET cSql = 'echo "UNLOAD TO ' || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt' || ' DELIMITER ' || '''|''' ||
                        ' SELECT tipomovimiento, cantidadmovtos, sucursal, importe, fecha' ||
                        ' FROM si_club_cifrastotales ' || ';' ||
                        ' " > cifrasclub.sql';
            SYSTEM cSql; 

            LET cSql = '';
            LET cSql = 'dbaccess bdinteg cifrasclub.sql';
            SYSTEM cSql;

			LET cSql = '';
            LET cSql = "sed 's/|$//g' " || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt' || " > " || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = "sed 's/$'/`echo \\\r`/ " || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt' || " > " || TRIM(cRuta) || 'cifrasclub' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql;

            LET cSql = '';
            LET cSql = 'rm cifrasclub.sql';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = 'rm ' || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = 'rm ' || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			FOREACH
				SELECT tipomovimiento, cantidadmovtos, sucursal, importe, fecha, fecha_hora
				INTO cTipoMovtos, iCantMovtos, cSucursal, iImporte, dFecha, dtFechaHora
				FROM "informix".si_club_cifrastotales

				INSERT INTO "informix".si_club_cifrastotales_hist(tipomovimiento, cantidadmovtos, sucursal, importe, fecha, fecha_hora)
					VALUES(cTipoMovtos, iCantMovtos, cSucursal, iImporte, dFecha, dtFechaHora);
			END FOREACH;

		ELSE
			LET cCodret = '002';
			LET vMensajeRet = 'No Existe Ruta';
		END IF;
	ELSE
		LET cCodret = '001';
		LET vMensajeRet = 'No Existe Fecha';
	END IF;

	IF cCodret <> '000000' THEN
		INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
			VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
	END IF;

	RETURN cCodret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_generaarchivocifras_club()
--DATOS A REGRESAR--
RETURNING CHAR(6) AS CodigoRetorno;

--DEFINICION DE VARIABLES--
DEFINE cCodret CHAR(6);
DEFINE vMensajeRet VARCHAR(80);
DEFINE iSqlErr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE vErrorInfo VARCHAR(80);
DEFINE vProceso VARCHAR(30);
DEFINE cSql CHAR(1024);
DEFINE dFechaHoy DATE;
DEFINE cRuta CHAR(100);
DEFINE cFechaArchivo CHAR(8);
DEFINE cSucursal CHAR(4);
DEFINE iCantMovtos INTEGER;
DEFINE iImporte INTEGER;
DEFINE cTipoMovtos CHAR(1);
DEFINE dFecha DATE;
DEFINE dtFechaHora DATETIME YEAR TO SECOND;
DEFINE cFolioSuc CHAR(16);
DEFINE cTransacc CHAR(4);
DEFINE mMontoTot MONEY(14,2);
DEFINE cNumCliente CHAR(40);
DEFINE cRecibo CHAR(40);
DEFINE cEstatusCancelado CHAR(1);
DEFINE iCantMovtosAbono INTEGER;
DEFINE iImporteAbono INTEGER;
DEFINE iCantMovtosVenta INTEGER;
DEFINE iImporteVenta INTEGER;
DEFINE iCantMovtosCambio INTEGER;
DEFINE iImporteCambio INTEGER;

--INICIALIZACION DE VARIABLES--
LET cCodret = '000000';
LET vMensajeRet = '';
LET iSqlErr = 0;
LET iIsamErr = 0;
LET vErrorInfo = '';
LET vProceso = 'sp_generaarchivocifras_club';
LET cSql = '';
LET dFechaHoy = '';
LET cRuta = '';
LET cFechaArchivo = '';
LET cSucursal = '';
LET iCantMovtos = 0;
LET iImporte = 0;
LET cTipoMovtos = '';
LET dFecha = '';
LET dtFechaHora = '';
LET cFolioSuc = '';
LET cTransacc = '';
LET mMontoTot = 0;
LET cNumCliente = '';
LET cEstatusCancelado = '';
LET iCantMovtosAbono = 0;
LET iImporteAbono = 0;
LET iCantMovtosVenta = 0;
LET iImporteVenta = 0;
LET iCantMovtosCambio = 0;
LET iImporteCambio = 0;

--SET DEBUG FILE TO "/informix/IrisA/sp_generaarchivocifras_club.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
		IF iSqlErr <> 0 OR iIsamErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET vMensajeRet = vErrorInfo;
			INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
				VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
			RETURN cCodret;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 5;

	SELECT fecha_hoy INTO dFechaHoy 
	FROM "informix".si_fechas WHERE empresa = '001';

	IF TRIM(NVL(dFechaHoy,'')) <> '' THEN

		SELECT valor INTO cRuta 
		FROM "informix".si_param 
		WHERE empresa = '001' AND cod_param = 319;

		IF TRIM(NVL(cRuta,'')) <> '' THEN

			LET cFechaArchivo = YEAR(dFechaHoy) || LPAD(MONTH(dFechaHoy),2,'0') || LPAD(DAY(dFechaHoy),2,'0');

			TRUNCATE TABLE "informix".si_club_cifrastotales;

			FOREACH
				-- SUCURSAL
				SELECT sucursal INTO cSucursal 
				FROM "informix".si_sucursales 
				WHERE empresa = '001' AND tpo_sucursal = 'S'
				ORDER BY sucursal

				-- VENTA
				SELECT COUNT(num_poliza), SUM(monto_pagar::INT) INTO iCantMovtos, iImporte
				FROM "informix".si_club_proteccion 
				WHERE fecha_alta = dFechaHoy AND suc_alta = cSucursal AND aceptada = '1';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('A', iCantMovtos, cSucursal, iImporte, dFechaHoy);
				END IF;

				LET iCantMovtosAbono = 0;
				LET iImporteAbono = 0;
				LET iCantMovtosVenta = 0;
				LET iImporteVenta = 0;
				LET iCantMovtosCambio = 0;
				LET iImporteCambio = 0;

				FOREACH
					SELECT folio_suc, transacc, monto_tot INTO cFolioSuc, cTransacc, mMontoTot
					FROM bdicheq:"informix".sc_movdia
					WHERE fech_alt = dFechaHoy AND transacc IN('1303','1363','1393') 
					AND empresa = '001' AND cancelad <> 'S' AND sucursal = cSucursal

					SELECT referencia1, referencia2, status_cancelado INTO cNumCliente, cRecibo, cEstatusCancelado
					FROM bdisac:"informix".sac_movimientos
					WHERE fecha_pago = dFechaHoy AND id_sucursal = cSucursal AND folio_suc = cFolioSuc;

					IF NVL(cNumCliente,'') <> '' THEN
						-- ABONO
						IF EXISTS(SELECT 1 FROM bdisac:"informix".sac_abono_seg WHERE sucursal = cSucursal AND numcliente = cNumCliente 
							AND recibo = cRecibo) THEN
							LET iCantMovtosAbono = iCantMovtosAbono + 1;
							LET iImporteAbono = iImporteAbono + mMontoTot::INT; 

						-- PAGO DE VENTA
						ELIF EXISTS(SELECT 1 FROM bdisac:"informix".sac_vta_cambio_seg WHERE sucursal = cSucursal AND numcliente = cNumCliente 
							AND recibo = cRecibo AND tipomovimiento = 'C') THEN
							LET iCantMovtosVenta = iCantMovtosVenta + 1;
							LET iImporteVenta = iImporteVenta + mMontoTot::INT; 
						
						-- PAGO DE CAMBIO DE PLAN
						ELIF EXISTS(SELECT 1 FROM bdisac:"informix".sac_vta_cambio_seg WHERE sucursal = cSucursal AND numcliente = cNumCliente 
							AND recibo = cRecibo AND tipomovimiento = 'K') THEN
							LET iCantMovtosCambio = iCantMovtosCambio + 1;
							LET iImporteCambio = iImporteCambio + mMontoTot::INT;
							
						ELSE
							INSERT INTO "informix".si_club_movimientosfaltantes(sucursal, folio_suc, transacc, monto_tot, status_cancelado, fecha_insert)
								VALUES(cSucursal, cFolioSuc, cTransacc, mMontoTot, cEstatusCancelado, dFechaHoy);

							LET iCantMovtosVenta = iCantMovtosVenta + 1;
							LET iImporteVenta = iImporteVenta + mMontoTot::INT;
						END IF;
					ELSE
						INSERT INTO "informix".si_club_movimientosfaltantes(sucursal, folio_suc, transacc, monto_tot, status_cancelado, fecha_insert)
							VALUES(cSucursal, cFolioSuc, cTransacc, mMontoTot, cEstatusCancelado, dFechaHoy);

						LET iCantMovtosVenta = iCantMovtosVenta + 1;
						LET iImporteVenta = iImporteVenta + mMontoTot::INT;
					END IF;
				END FOREACH;
					
				IF NVL(iCantMovtosAbono,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('B', iCantMovtosAbono, cSucursal, iImporteAbono, dFechaHoy);
				END IF;

				IF NVL(iCantMovtosVenta,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('C', iCantMovtosVenta, cSucursal, iImporteVenta, dFechaHoy);
				END IF;

				IF NVL(iCantMovtosCambio,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('K', iCantMovtosVenta, cSucursal, iImporteCambio, dFechaHoy);
				END IF;

				-- CAMBIO DE BENEFICIARIO
				SELECT COUNT(DISTINCT numcte) INTO iCantMovtos 
				FROM "informix".si_club_beneficiario 
				WHERE fecha_modificacion = dFechaHoy AND suc_cambio = cSucursal AND tipo_mov = 'C';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('D', iCantMovtos, cSucursal, 0, dFechaHoy);
				END IF;

				-- CAMBIO DE PLAN
				SELECT COUNT(num_poliza), SUM(monto_pagar::INT) INTO iCantMovtos, iImporte
				FROM "informix".si_club_proteccion 
				WHERE fecha_cambio = dFechaHoy AND suc_cambio = cSucursal AND tipo_mov = 'C';

				IF NVL(iCantMovtos,0) <> 0 THEN
					INSERT INTO "informix".si_club_cifrastotales(tipomovimiento, cantidadmovtos, sucursal, importe, fecha)
						VALUES('H', iCantMovtos, cSucursal, iImporte, dFechaHoy);
				END IF;

			END FOREACH;

			UPDATE statistics medium FOR TABLE "informix".si_club_cifrastotales;

			LET cSql = '';
            LET cSql = 'echo "UNLOAD TO ' || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt' || ' DELIMITER ' || '''|''' ||
                        ' SELECT tipomovimiento, cantidadmovtos, sucursal, importe, fecha' ||
                        ' FROM si_club_cifrastotales ' || ';' ||
                        ' " > cifrasclub.sql';
            SYSTEM cSql; 

            LET cSql = '';
            LET cSql = 'dbaccess bdinteg cifrasclub.sql';
            SYSTEM cSql;

			LET cSql = '';
            LET cSql = "sed 's/|$//g' " || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt' || " > " || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = "sed 's/$'/`echo \\\r`/ " || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt' || " > " || TRIM(cRuta) || 'cifrasclub' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql;

            LET cSql = '';
            LET cSql = 'rm cifrasclub.sql';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = 'rm ' || TRIM(cRuta) || 'cifrasclub1' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			LET cSql = '';
            LET cSql = 'rm ' || TRIM(cRuta) || 'cifrasclub2' || TRIM(cFechaArchivo) || '.txt';
            SYSTEM cSql; 

			FOREACH
				SELECT tipomovimiento, cantidadmovtos, sucursal, importe, fecha, fecha_hora
				INTO cTipoMovtos, iCantMovtos, cSucursal, iImporte, dFecha, dtFechaHora
				FROM "informix".si_club_cifrastotales

				INSERT INTO "informix".si_club_cifrastotales_hist(tipomovimiento, cantidadmovtos, sucursal, importe, fecha, fecha_hora)
					VALUES(cTipoMovtos, iCantMovtos, cSucursal, iImporte, dFecha, dtFechaHora);
			END FOREACH;

		ELSE
			LET cCodret = '002';
			LET vMensajeRet = 'No Existe Ruta';
		END IF;
	ELSE
		LET cCodret = '001';
		LET vMensajeRet = 'No Existe Fecha';
	END IF;

	IF cCodret <> '000000' THEN
		INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
			VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
	END IF;

	RETURN cCodret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizarfc_nuevo()
RETURNING CHAR(5) as codret, CHAR(5) as codret2, CHAR(5) as mensaje;

DEFINE vcodret1         char(5); 
DEFINE vcodret2         char(5);
DEFINE vcodret3         char(50);
DEFINE sql_err          integer;
DEFINE isam_err         integer;
DEFINE desc_err         char(50);
DEFINE vnumcte          char(10);
DEFINE vrfc_calculado   char(13);
DEFINE vcomienza        smallint;
DEFINE ven_transacc     smallint;
DEFINE vcontador1       integer;

LET vcodret1            ='00000';
LET vcodret2            ='0000';
LET vcodret3            ='PROCESO CONCLUIDO SATISFACTORIAMENTE';
LET sql_err             =0;
LET isam_err            =0;
LET desc_err            ='';
LET vcomienza           =-1;
LET ven_transacc        = 0;  
LET vnumcte             ='';
LET vrfc_calculado      ='';
LET vcontador1          =0;



BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/arch_sp_actualizarfc.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;

            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH WITH HOLD
        select  numcte, rfc_calculado INTO vnumcte,  vrfc_calculado from resultadosrfc where rfc_duplicado=0
    
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        UPDATE si_cliente set rfc=vrfc_calculado where numcte=vnumcte;

        LET vcontador1 = vcontador1 + 1;
        

        IF (vcontador1 >= 5000) THEN
            LET vcontador1 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
     END FOREACH;

     IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
     END IF;

END;
RETURN vcodret1, vcodret2, vcodret3; 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_esapellido_valido(pApellido CHAR(26))
	RETURNING BOOLEAN AS es_apellido_valido;
	
	DEFINE bEsApellidoValido BOOLEAN;
	DEFINE cApellido CHAR(26);
	
	LET bEsApellidoValido = 't';
	LET pApellido = UPPER(pApellido);
	LET cApellido = '';
	
	BEGIN
		
		SELECT apellido_novalido
		INTO cApellido
		FROM bdinteg:"informix".apellidos_novalidos
		WHERE apellido_novalido = pApellido;
		
		IF cApellido IS NOT NULL THEN
			LET bEsApellidoValido = 'f';
		END IF;
		
		RETURN bEsApellidoValido;
		
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si el parametro de entrada es un apellido valido, deveulve un booleano";

CREATE PROCEDURE "informix".sp_validarfc()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(9);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='316';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='316';

        set isolation to dirty read;
        FOREACH  
                SELECT a.numcte, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
                INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
                    FROM bdinteg:si_cliente a
                        INNER JOIN bdinteg:si_ctepf b
                            ON a.numcte=b.numcte
                    WHERE a.empresa='001' AND a.tipo_cliente='1'
                        AND rfc_alterno IS NULL and length(a.apell_paterno)>2
                        AND a.numcte>=vNumCteIni--'000971137'
                    --where length(T1.apell_paterno)<=2
                    --AND a.numcte NOT IN('000006241', '000013393', '000013398', '000001343', '000001802', '000004723', '000006248', '000006250')
                    ORDER BY a.numcte
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                ELSE
                --NO SE ENCONTRARON REGISTROS CON EL MISMO RFC EN RECALCULADOS, SE BUSCA EN si_cliente
                    SELECT count(*) INTO iTotDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo;
                    LET iNumRows = dbinfo("sqlca.sqlerrd2");
                    IF iNumRows>0 AND iTotDupRec>0 THEN
                    --SE ENCONTRARON REGISTROS DUPLICADOS EN si_cliente
                        IF iTotDupRec=1 THEN
                           SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo; 
                        ELSE
                            FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo
                                LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                            END FOREACH;
                        END IF;

                        INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    ELSE--CUANDO NO SE ENCUENTREN EN LA TABLA DE RECALCULADOS NI EN LA SI_CLIENTES
                        INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    END IF;
                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_calcularfc(pEmpresa CHAR(3), 
                                          pApePat VARCHAR(26), 
                                          pApeMat VARCHAR(26), 
                                          pNombre1 VARCHAR(26),  
                                          pNombre2 VARCHAR(26), 
                                          pFechaNac DATE) 

RETURNING CHAR(6)       AS retorno, 
          VARCHAR(100)  AS mensaje, 
          VARCHAR(13)   AS rfc; 

-- Variables del proceso
DEFINE vNombre      VARCHAR(53);
DEFINE vApell_Pat   VARCHAR(26);
DEFINE vApell_Mat   VARCHAR(26);
DEFINE cLetraApePat CHAR(1);
DEFINE cVocalApePat CHAR(1);
DEFINE cLetraapeMat CHAR(1);
DEFINE cLetraNombre CHAR(1);
DEFINE cDia         CHAR(2);
DEFINE cMes         CHAR(2);
DEFINE cAnio        CHAR(2);
DEFINE i,a          INTEGER;
DEFINE cLetra       CHAR(1);
DEFINE cCaracter    CHAR(1);
DEFINE cRfc         VARCHAR(13);
DEFINE cPalabra     VARCHAR(26);
DEFINE cFechaNac    VARCHAR(10);
DEFINE cHomoclave   CHAR(2);
DEFINE cDigito      CHAR(1);

-- Control de errores
DEFINE iSqlErr      INTEGER;
DEFINE iIsamErr     INTEGER;
DEFINE vErrorInfo   VARCHAR(100);
DEFINE vCodRet      CHAR(6);
DEFINE cMensaje     VARCHAR(100);

-- Variables del proceso
LET vNombre         = "";
LET vApell_Pat      = TRIM(UPPER(pApePat));
LET vApell_Mat      = TRIM(UPPER(pApeMat));
LET cLetraApePat    = "";
LET cVocalApePat    = "";
LET cLetraapeMat    = "";
LET cLetraNombre    = "";
LET cDia            = "";
LET cMes            = "";
LET cAnio           = "";
LET i               = 0;
LET a               = 0;
LET cLetra          = "";
LET cCaracter       = "";
LET cRfc            = "";
LET cPalabra        = "";
LET cFechaNac       = pFechaNac;
LET cHomoclave      = "";
LET cDigito         = "";


-- Control de errores
LET iSqlErr         = 0;
LET iIsamErr        = 0;
LET vErrorInfo      = "";
LET vCodRet         = "000000";
LET cMensaje        = "El proceso se realizó con éxito.";

BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
   IF iSqlErr != 0 THEN
      LET vCodRet= iSqlErr;
      LET cMensaje= vErrorInfo;
      RETURN vCodRet, cMensaje,cRfc;
   END IF;
END EXCEPTION; 

  --SET DEBUG FILE TO "/home/sysifx/viridiana/sp_calcularfc.out";
  --TRACE ON;

   IF NVL(pEmpresa,"") = "" THEN
       LET vCodRet = "000001";
       LET cMensaje = "La información de la empresa no es correcta.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   IF NVL(pApePat,"") = "" AND NVL(pApeMat,"") = "" THEN
       LET vCodRet = "000002";
       LET cMensaje = "Es necesario proporcionar al menos un apellido del cliente.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   IF NVL(pNombre1,"") = "" AND NVL(pNombre2,"") = "" THEN
       LET vCodRet = "000003";
       LET cMensaje = "Es necesario proporcionar al menos un nombre del cliente.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   LET cFechaNac = LPAD(YEAR(pFechaNac),4,0) ||"/" || LPAD(MONTH(pFechaNac),2,0) || "/" || LPAD(DAY(pFechaNac),2,0);

   IF NVL(cFechaNac,"") <> "" AND (LENGTH(cFechaNac) = 10) AND SUBSTR(cFechaNac,1,1) <> "0" THEN    

           LET cAnio = SUBSTR(cFechaNac,3,2);
           LET cMes  = SUBSTR(cFechaNac,6,2);
           LET cDia  = SUBSTR(cFechaNac,9,2);       
                 
   ELSE
       LET vCodRet = "000005";
       LET cMensaje = "La fecha de nacimiento del proporcionada no es válida.";
       RETURN vCodRet, cMensaje,cRfc;     
   
   END IF   

   IF  NVL(pApePat,"") = ""  AND NVL(pApeMat,"") <> "" THEN
       LET vApell_Pat = TRIM(UPPER(pApeMat));
       LET vApell_Mat = "";
   END IF; 


   LET vNombre = UPPER(TRIM(pNombre1) ||" "|| TRIM(pNombre2));
   
   EXECUTE PROCEDURE bdinteg:sp_calcularrfc(vApell_Pat, vApell_Mat, vNombre, pFechaNac)
            INTO vCodRet, cRfc;
   
IF vCodRet <> "00000" THEN
    LET vCodRet = "000017";
    LET cMensaje = "Ocurrió un error al calcular el dígito verificador para el RFC.";
    RETURN vCodRet, cMensaje,cRfc;
ELSE
    LET vCodRet = "000000";
END IF;


RETURN vCodRet, cMensaje,cRfc;
END 
END PROCEDURE
DOCUMENT
"Descripción: Procedimiento que realiza el cálculo del RFC de un cliente.",
"BD: bdinteg",
"Fecha: 06-Abril-2010",
"Autor: Viridiana Osobampo Aguilar";

CREATE PROCEDURE "informix".sp_actualizarfc_prosp()
RETURNING CHAR(5) as codret, CHAR(5) as codret2, CHAR(5) as mensaje;

DEFINE vcodret1         char(5); 
DEFINE vcodret2         char(5);
DEFINE vcodret3         char(50);
DEFINE sql_err          integer;
DEFINE isam_err         integer;
DEFINE desc_err         char(50);
DEFINE vnumcte          char(10);
DEFINE vrfc_calculado   char(13);
DEFINE vcomienza        smallint;
DEFINE ven_transacc     smallint;
DEFINE vcontador1       integer;

LET vcodret1            ='00000';
LET vcodret2            ='0000';
LET vcodret3            ='PROCESO CONCLUIDO SATISFACTORIAMENTE';
LET sql_err             =0;
LET isam_err            =0;
LET desc_err            ='';
LET vcomienza           =-1;
LET ven_transacc        = 0;  
LET vnumcte             ='';
LET vrfc_calculado      ='';
LET vcontador1          =0;



BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/arch_sp_actualizarfc.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;

            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH WITH HOLD
        select  numcte, rfc_calculado INTO vnumcte,  vrfc_calculado from resultadosrfc_prosp where rfc_duplicado=0
    
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        UPDATE si_cliente set rfc=vrfc_calculado where numcte=vnumcte;

        LET vcontador1 = vcontador1 + 1;
        

        IF (vcontador1 >= 5000) THEN
            LET vcontador1 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
     END FOREACH;

     IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
     END IF;

END;
RETURN vcodret1, vcodret2, vcodret3; 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarfc_prosp()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(9);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='330';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='330';

        set isolation to dirty read;
        FOREACH  
                SELECT a.numcte, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
                INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
                    FROM bdinteg:si_cliente a
                        INNER JOIN bdinteg:si_ctepf b
                            ON a.numcte=b.numcte
                    WHERE a.empresa='001' AND a.tipo_cliente='2'
                        AND rfc_alterno IS NULL and length(a.apell_paterno)>2
                        AND a.numcte>=vNumCteIni--'000971137'
                    --where length(T1.apell_paterno)<=2
                    --AND a.numcte NOT IN('000006241', '000013393', '000013398', '000001343', '000001802', '000004723', '000006248', '000006250')
                    ORDER BY a.numcte
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc_prosp WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_prosp WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_prosp WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc_prosp (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                ELSE
                --NO SE ENCONTRARON REGISTROS CON EL MISMO RFC EN RECALCULADOS, SE BUSCA EN si_cliente
                    SELECT count(*) INTO iTotDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo;
                    LET iNumRows = dbinfo("sqlca.sqlerrd2");
                    IF iNumRows>0 AND iTotDupRec>0 THEN
                    --SE ENCONTRARON REGISTROS DUPLICADOS EN si_cliente
                        IF iTotDupRec=1 THEN
                           SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo; 
                        ELSE
                            FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo
                                LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                            END FOREACH;
                        END IF;

                        INSERT INTO bdinteg:resultadosrfc_prosp (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    ELSE--CUANDO NO SE ENCUENTREN EN LA TABLA DE RECALCULADOS NI EN LA SI_CLIENTES
                        INSERT INTO bdinteg:resultadosrfc_prosp (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    END IF;
                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_altamasivaempnet_busca()
RETURNING CHAR(5);
    
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    
    DEFINE vcCodEmpresa     CHAR(3);
    DEFINE vcNombreArchivo  CHAR(30);
    DEFINE vcNumCte         CHAR(9);
    DEFINE vcCodRetAlta     CHAR(5);
    
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET vcDescErr   = '';
    LET vcCodRet    = '000';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    
    LET vcCodEmpresa    = '';
    LET vcNombreArchivo = '';
    LET vcNumCte        = '';
    LET vcCodRetAlta    = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_busca.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_busca.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // PROCESA LOS ARCHIVOS QUE ESTEN PENDIENTES
    FOREACH WITH HOLD 
        SELECT alta.cod_empresa, alta.nombre_archivo, emp.numcte
          INTO vcCodEmpresa, vcNombreArchivo, vcNumCte
          FROM bdinteg:si_altamasivaempnet_ctrl alta,
               bdicheq:sc_nominaempresas emp
         WHERE alta.cod_empresa = emp.codigo
           AND alta.status = '0'
           
        CALL sp_altamasivaempnet_procesa( vcCodEmpresa, vcNumCte, vcNombreArchivo )
        RETURNING vcCodRetAlta;
    END FOREACH;
    
    RETURN vcCodRet;
    
    END;
    
END PROCEDURE;

