CREATE PROCEDURE "informix".sp_validarfc_alterno()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(9);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='331';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='331';

        set isolation to dirty read;
        FOREACH  
				
                SELECT a.numcte, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
                INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
                    FROM bdinteg:si_cliente a
                        INNER JOIN bdinteg:si_ctepf b
                            ON a.numcte=b.numcte
                    WHERE a.empresa='001' AND a.tpo_persona='01'
                        AND rfc_alterno<>'' --and length(a.apell_paterno)>2
                        AND a.numcte>=vNumCteIni--'000971137'
                    --where length(T1.apell_paterno)<=2
                    --AND a.numcte NOT IN('000006241', '000013393', '000013398', '000001343', '000001802', '000004723', '000006248', '000006250')
                    ORDER BY a.numcte
				
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc_alterno WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_alterno WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_alterno WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc_alterno (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                ELSE
                --NO SE ENCONTRARON REGISTROS CON EL MISMO RFC EN RECALCULADOS, SE BUSCA EN si_cliente
                    SELECT count(*) INTO iTotDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo;
                    LET iNumRows = dbinfo("sqlca.sqlerrd2");
                    IF iNumRows>0 AND iTotDupRec>0 THEN
                    --SE ENCONTRARON REGISTROS DUPLICADOS EN si_cliente
                        IF iTotDupRec=1 THEN
                           SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo; 
                        ELSE
                            FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo
                                LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                            END FOREACH;
                        END IF;

                        INSERT INTO bdinteg:resultadosrfc_alterno (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    ELSE--CUANDO NO SE ENCUENTREN EN LA TABLA DE RECALCULADOS NI EN LA SI_CLIENTES
                        INSERT INTO bdinteg:resultadosrfc_alterno (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                    END IF;
                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_dias_inhabiles(pRegistro SMALLINT)
	returning char (5), DATE;

	--Realizó : Manuel Ramos
	--Actividad: Se sobreescribe sp_dias_inhabiles agregandole un parametro para consultar los días feriados de 10 en 10.
	--Fecha: 24/09/2014
	--Solicitó: Walber Castro

	DEFINE sql_err integer;
	DEFINE cod_ret char(5);
	DEFINE fecha_inhabil DATE;

	LET sql_err = 0;
	LET cod_ret = '000';
	LET fecha_inhabil = '01-01-1900';

	BEGIN
		ON EXCEPTION SET sql_err
			LET cod_ret = sql_err;
			RETURN cod_ret,fecha_inhabil;
		END EXCEPTION;

		--SET DEBUG File To '/home/sp_dias_inhabiles.out';
		--TRACE ON;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		FOREACH
			SELECT SKIP pRegistro FIRST 10 
			fecha INTO fecha_inhabil FROM bdinteg:"informix".si_feriado_banca
			IF (fecha_inhabil <> '' OR fecha_inhabil IS NULL) THEN
				LET cod_ret = '001';
			END IF;
			RETURN cod_ret,fecha_inhabil WITH RESUME;
		END FOREACH;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_obtiene_param(pEmpresa CHAR(3), pCodParam CHAR(3))
RETURNING	CHAR(6),	-- Codigo de Retorno
			CHAR(100);	-- Valor Consecutivo.

--DEFINICION DE VARIABLES
DEFINE	iSqlErr INTEGER;
DEFINE	cCodRet CHAR(6);
DEFINE	cValor	CHAR(100);

--INICIALIZACION DE VARIABLES
LET iSqlErr	= 0;
LET cCodRet	= '000000';
LET	cValor	= "";

	--SET DEBUG FILE TO '/respaldosbd/claudio/sp_obtiene_param.out';
	--TRACE ON;
BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
           RETURN cCodRet,NVL(cValor,'');
		END IF
	END EXCEPTION;
    SET ISOLATION to DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	IF NVL(pEmpresa,'') <> '' AND  NVL(pCodParam,'') <> '' THEN
		SELECT valor INTO cValor FROM bdinteg:"informix".si_param WHERE cod_param = pCodParam AND empresa = pEmpresa;
		IF cValor IS NULL THEN
			LET cCodRet = '000002'; --No Existe Codigo
		END IF
	ELSE
		LET cCodRet = '000001'; --Parametros Vacios
	END IF
	RETURN cCodRet,NVL(cValor,'');
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Verifica que existe el codigo y obtiene el valor',
'REALIZO: Claudio Almodovar',
