CREATE PROCEDURE "informix".sp_consultarctemoral_02(pNumcte CHAR(20))


	RETURNING
	CHAR(6) 		AS COD_RET,
	CHAR(13) 		AS RFC,
	CHAR(26) 		AS APELL_PATER_REP_LEG,
	CHAR(26) 		AS APELL_MATER_REP_LEG,
	CHAR(26) 		AS NOMB1_REP_LEG,
	CHAR(26) 		AS NOMB2_REP_LEG,
	CHAR(40)   		AS CALLE_FISCAL,
	CHAR(10)   		AS NUM_EXT_CALLE_FISCAL,
	CHAR(60)   		AS COL_FISCAL,
	VARCHAR(60,1)  	AS NOM_CIUD_FISCAL,
	CHAR(3)   		AS COD_MUN_FISCAL,
	CHAR(30)    	AS NOM_ESTADO_FISCAL,
	CHAR(20) 		AS NUM_CTE,
	CHAR(30) 		AS NOM_CORTO,
	CHAR(30) 		AS PAG_INTERNET,
	CHAR(25) 		AS SAT_FEA,
	CHAR(15) 		AS TEL_CONTACTO,
	CHAR(20) 		AS GIRO,
	CHAR(40) 		AS NOM_GIRO,
	CHAR(3)         AS ACTIVIDAD_SOC,
	CHAR(30) 		AS DES_ACT_OBJ,
	CHAR(2) 		AS RESP_STATUS,
	CHAR(26) 		AS APELL_PATER_FIRMANTES,
	CHAR(26) 		AS APELL_MATER_FIRMANTES,
	CHAR(26) 		AS NOMB1_FIRMANTES,
	CHAR(26) 		AS NOMB2_FIRMANTES,
	CHAR(20)        AS DES_PODER,
	CHAR(20)        AS DES_ADMIN,
	CHAR(40)        AS DES_ORG,
	DATE            AS FECHA_INS,
	DATE            AS FECHA_CONS,
	CHAR(3)         AS NACIONALIDAD,
	CHAR(15)        AS DESC_NACIONALIDAD,
	CHAR(48)        AS NOMBRE_CONTACTO,
	CHAR(2)         AS SUFIJO,
	CHAR(60)        AS DES_SUFIJO,
	CHAR(30)        AS ESCRITURA,
	CHAR(30)        AS NOMBRE_NOT,
	CHAR(5)         AS NUM_NOT,
	CHAR(30)        AS CDNOTARIO_OCT,
	CHAR(30)        AS DES_NOTARIOCT,
	CHAR(30)        AS ESCRITURA_POD,
	CHAR(30)        AS NOMNOTARIO_PD,
	CHAR(5)         AS NUMNOTARIO_PD,
	CHAR(30)        AS CDNOTARIO_PD,
	CHAR(30)        AS DESC_CDNOTARIOPD,
	CHAR(50)        AS NOMBRESOC,
	DATE            AS FECHAINS_PD,
	CHAR(60)        AS EMAIL_PM,
	CHAR(30)        AS FOLIO_MERCAN,
	CHAR(30)        AS CD_FOLIOMERCA,
	INTEGER         AS ESTATUS_CTE,
	CHAR(1)         AS AUXILIAR1,
	CHAR(1) 		AS AUXILIAR2,
	CHAR(1) 		AS AUXILIAR3,
    CHAR(1)         AS AUXILIAR4,
	CHAR(1)         AS AUXILIAR5,
    CHAR(1)         AS AUXILIAR6,
    CHAR(1)         AS AUXILIAR7,
	CHAR(1)         AS AUXILIAR8,
	CHAR(1)         AS AUXILIAR9,
	CHAR(1)         AS AUXILIAR10,
	CHAR(02)        AS TIPO_PERSONA,
	CHAR(20)        AS NUMCTE_APODERADO,
	CHAR(60)        AS NOMCTE_APODERADO,
	CHAR(100)       AS DESC_DOCONSTITUCION,
	CHAR(4)         AS SUCURSAL,
	DATE            AS FECHA_ALTA,
	CHAR(1)         AS AUXILIAR11,
	CHAR(3)         AS TIPO_PODER,
	CHAR(3)         AS TIPO_ADMON,
	CHAR(3)         AS TIPO_ORGANIZACION,
	CHAR(40)        AS NOMBRE_SUCURSAL,
	CHAR(1)         AS VALORPARAM_MORALGOB;


	--****************************************************************************************************
	-- MODIFICACION: Cuando el servicio del cliente esta cancelado 99 se pasa toda la información a tablas
	--		 historicas y se cambia los id de imagenes, para proceder con una RE-contratación.
	-- MOD. POR: David Picos Carrasco - BanCoppel.
	-- FECHA MOD: 23 Octubre 2014
	--***************************************************************************************************



	---DECLARACIONES
	DEFINE iSqlErr						INTEGER;
	DEFINE cCodRet         				CHAR(6);
	DEFINE cRFC         				CHAR(13);
    DEFINE cSucursal                    CHAR(4);
	DEFINE cApellPaterContactoRepLeg 	CHAR(26);
	DEFINE cApellMaterContactoRepLeg	CHAR(26);
	DEFINE cNomb1ContactoRepLeg         CHAR(26);
	DEFINE cNomb2ContactoRepLeg     	CHAR(26);
	DEFINE cCalleFiscal					CHAR(40);
	DEFINE cNumExtCalleFiscal       	CHAR(10);
	DEFINE cColFiscal         			CHAR(60);
	DEFINE vNomCiudFiscal         		VARCHAR(60,1);
	DEFINE cCodMunFiscal        		CHAR(3);
	DEFINE cNomEstadoFiscal        		CHAR(30);
	DEFINE cNumcte         				CHAR(20);
	DEFINE cNomCorto        			CHAR(30);
	DEFINE cPagInternet        			CHAR(30);
	DEFINE cSatFea        				CHAR(25);
	DEFINE cTelContacto    				CHAR(15);
	DEFINE cGiro      					CHAR(20);
	DEFINE cNomGiro    					CHAR(40);
	DEFINE cActividadSoc                CHAR(3);
	DEFINE cDesActObj  					CHAR(30);
	DEFINE cUsuarioAut    				CHAR(200);
	DEFINE cStatusAlta 					CHAR(1);
	DEFINE cRespStatus 					CHAR(2);
	DEFINE cApellPaterFirmantes 		CHAR(26);
	DEFINE cApellMaterFirmantes 		CHAR(26);
	DEFINE cNomb1Firmantes 				CHAR(26);
	DEFINE cNomb2Firmantes 				CHAR(26);
	DEFINE cCuentaNomina 				CHAR(20);
	DEFINE cPoder                       CHAR(3);
	DEFINE cAdmin                       CHAR(3);
	DEFINE cOrg                         CHAR(3);
	DEFINE cDesPoder                    CHAR(20);
	DEFINE cDesAdmin                    CHAR(20);
	DEFINE cDesOrg                      CHAR(40);
	DEFINE cTpoPersona                  CHAR(2);
	DEFINE dFechaIns                    DATE;
	DEFINE dFechaCons                   DATE;
	DEFINE iNac                         INTEGER;
	DEFINE cNomContacto                 CHAR(48);
	DEFINE cSufijo                      CHAR(2);
	DEFINE cDescSufi                    CHAR(60);
	DEFINE cEscritura                   CHAR(30);
	DEFINE cNombreNot                   CHAR(30);
	DEFINE cNumNot                      CHAR(5);
	DEFINE cCdNotarioct                 CHAR(60);
	DEFINE cDesCdNot                    CHAR(30);
	DEFINE cEscrituraPod                CHAR(30);
	DEFINE cNomNotariopd                CHAR (30);
	DEFINE cNumNotariopd                CHAR(5);
	DEFINE cCdNotariopd                 CHAR(30);
	DEFINE cDesCdNotpd                  CHAR(30);
	DEFINE cNombreSoc                   CHAR(50);
	DEFINE dFechaInspd                  DATE;
	DEFINE cEmailpm                     CHAR(60);
	DEFINE cEsFisica                    CHAR(1);
	DEFINE cNumfoliomerct               CHAR(30);
	DEFINE cCdfoliomerct                CHAR(30);
	DEFINE cAuxiliar1                   CHAR(1);
	DEFINE cAuxiliar2                   CHAR(1);
	DEFINE cAuxiliar3                   CHAR(1);
	DEFINE cAuxiliar4   				CHAR(1);
	DEFINE cAuxiliar5   				CHAR(1);
	DEFINE cAuxiliar6                   CHAR(1);
	DEFINE cAuxiliar7                   CHAR(1);
	DEFINE cAuxiliar8                   CHAR(1);
	DEFINE cAuxiliar9                   CHAR(1);
	DEFINE cAuxiliar10                  CHAR(1);
	DEFINE cAuxiliar11                  CHAR(1);
	DEFINE cNumcteapoder                CHAR(20);
	DEFINE cNomapoder                   CHAR(60);
	DEFINE cDocConst                    CHAR(100);
	DEFINE cDesNacion                   CHAR(15);
	DEFINE cNac                         CHAR(3);
	DEFINE dFechaAlta                   DATE;
	DEFINE cNombreSucursal              CHAR(40);
	DEFINE cPrmTpopersonaGob               CHAR(5);
	DEFINE cValorTpopersonaGop             CHAR(1);
	DEFINE iEstatusCteEmpNet            INTEGER;

	---INICIALIZACIONES
	LET iSqlErr						= 0;
	LET cCodRet         			= '000000';
	LET cRFC         				= '';
	LET cApellPaterContactoRepLeg   = '';
	LET cApellMaterContactoRepLeg 	= '';
	LET cNomb1ContactoRepLeg        = '';
	LET cNomb2ContactoRepLeg     	= '';
	LET cCalleFiscal				= '';
	LET cNumExtCalleFiscal       	= '';
	LET cColFiscal         			= '';
	LET vNomCiudFiscal         		= '';
	LET cCodMunFiscal        		= '';
	LET cNomEstadoFiscal        	= '';
	LET cNumcte         			= '';
	LET cNomCorto        			= '';
	LET cPagInternet        		= '';
	LET cSatFea        				= '';
	LET cTelContacto    			= '';
	LET cGiro      					= '';
	LET cNomGiro    				= '';
	LET cDesActObj  				= '';
	LET cUsuarioAut    				= '';
	LET cStatusAlta 				= '';
	LET cRespStatus 				= '';
	LET cApellPaterFirmantes 		= '';
	LET cApellMaterFirmantes 		= '';
	LET cNomb1Firmantes 			= '';
	LET cNomb2Firmantes 			= '';
	LET cCuentaNomina	 			= '';
	LET cPoder                      = '';
	LET cAdmin                      = '';
	LET cOrg                        = '';
	LET cDesPoder                   = '';
	LET cDesAdmin                   = '';
	LET cDesOrg                     = '';
	LET cTpoPersona                 = '';
	LET dFechaIns                   = DATE(1);
	LET dFechaCons                  = DATE(1);
	LET iNac                        = 0;
	LET cNomContacto                = '';
	LET cSufijo                     = '';
	LET cDescSufi                   = '';
	LET cActividadSoc               = '';
	LET cEscritura                  = '';
	LET cNombreNot                  = '';
	LET cNumNot                     = '';
	LET cCdNotarioct                = '';
	LET cDesCdNot                   = '';
	LET cEscrituraPod               = '';
	LET cNomNotariopd               = '';
	LET cNumNotariopd               = '';
	LET cCdNotariopd                = '';
	LET cDesCdNotpd                 = '';
	LET cNombreSoc                  = '';
	LET dFechaInspd                 = DATE(1);
	LET cEmailpm                    = '';
	LET cEsFisica                   = '';
	LET cCdfoliomerct               = '';
	LET cNumfoliomerct              = '';
	LET cAuxiliar1                  = '';
	LET cAuxiliar2                  = '';
	LET cAuxiliar3                  = '';
	LET cAuxiliar4                  = '';
	LET cAuxiliar5                  = '';
	LET cAuxiliar6                  = '';
	LET cAuxiliar7                  = '';
	LET cAuxiliar8                  = '';
	LET cAuxiliar9                  = '';
	LET cAuxiliar10                 = '';
	LET cAuxiliar11                 = '';
	LET cNumcteapoder               = '';
	LET cNomapoder                  = '';
	LET cDocConst                   = '';
	LET cDesNacion                  = '';
	LET cNac                        = '';
	LET cSucursal                   = '';
	LET dFechaAlta                  = DATE(1);
	LET cNombreSucursal             = '';
	LET cPrmTpopersonaGob              = '';
	LET cValorTpopersonaGop            = '';
	LET iEstatusCteEmpNet           = 0;

	
	BEGIN

		ON EXCEPTION SET iSqlErr
		   IF iSqlErr != 0 THEN
			
			  LET cCodRet = iSqlErr;
			  RETURN 	cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));

		   END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		

		IF TRIM(NVL(pNumcte,'')) = '' THEN
			LET cCodRet = '000001'; --PARÁMETRO VACIO

		 	RETURN cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));
		END IF;
		--SE CONSULTA EL TIPO PERSONA, RFC Y SUCURSAL REFERENTE AL CLIENTE
		SELECT tpo_persona, rfc, sucursal
		INTO cTpoPersona, cRFC, cSucursal
		FROM "informix".si_cliente
		WHERE numcte = TRIM(pNumcte)
		AND empresa = '001';


		IF DBINFO("sqlca.sqlerrd2") = 0 THEN
		   LET cCodRet = '000002'; --CONSULTA SIN RESULTADOS, AL CONSULTAR PARAMETRO INVÁLIDO

		   RETURN 	cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));
		END IF;

		--CONSULTA es_fisica OBTENIENDO 'S'= PERSONA FÍSICA, 'N'=PERSONA MORAL
		SELECT es_fisica
		INTO cEsFisica
        FROM "informix".si_tipper
		WHERE tpo_persona = TRIM(cTpoPersona);

		IF cEsFisica = 'S' THEN
		   LET cCodRet = '000003'; --PERSONA FÍSICA
		   LET cRFC = '';

		   RETURN 	cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));

		END IF;

		--SE OBTIENEN LOS DATOS DE CLIENTE MORAL DE LA TABLA si_ctepm
		SELECT TRIM(NVL(numcte,'')),NVL(nombre_corto,''),NVL(pagina_internet,''),TRIM(NVL(sat_fea,'')),
			   TRIM(NVL(telefono_contacto,'')), TRIM(NVL(giro, '')),TRIM(NVL(tipo_poder,'')),TRIM(NVL(tipo_admon,'')),
			   TRIM(NVL(tipo_org,'')),fecha_inscrip,fecha_constitct,fecha_alta,nacionalidad,TRIM(NVL(nombre_contacto,'')),
			   TRIM(NVL(sufijo,'')),TRIM(NVL(actividadsocial,'')),NVL(escritura_constitutiva,''),
			   TRIM(NVL(nombre_notarioct,'')),TRIM(NVL(numero_notarioct,'')),TRIM(NVL(ciudad_notarioct,'')),
			   TRIM(NVL(numero_foliomercantilct,'')),TRIM(NVL(ciudad_foliomercantilct,'')),TRIM(NVL(escritura_poderes,'')),
			   TRIM(NVL(nombre_notariopd,'')),TRIM(NVL(numero_notariopd,'')), TRIM(NVL(ciudad_notariopd,'')),
			   TRIM(NVL(nombre_sociedad,'')),fecha_inscrippd, TRIM(NVL(emailpm,'')), TRIM(NVL(doc_constitucion,''))
		INTO cNumcte, cNomCorto, cPagInternet, cSatFea,
		     cTelContacto, cGiro, cPoder, cAdmin,
			 cOrg, dFechaIns, dFechaCons,dFechaAlta,iNac, cNomContacto,
			 cSufijo, cActividadSoc, cEscritura,
			 cNombreNot, cNumNot, cCdNotarioct,
			 cNumfoliomerct, cCdfoliomerct, cEscrituraPod,
			 cNomNotariopd, cNumNotariopd, cCdNotariopd,
			 cNombreSoc, dFechaInspd, cEmailpm,cDocConst
		FROM "informix".si_ctepm
		WHERE numcte = TRIM(pNumcte)
		AND empresa = '001';


	    LET cNac = LPAD(iNac, 3,'0');

		--SE OBTIENE LA DESCRIPCION DE LA NACIONALIDAD
	    SELECT descripcion
		INTO cDesNacion
		FROM "informix".si_nacion
		WHERE nacion = cNac;

		--SE OBTIENE LA DESCRIPCION DEL SUFIJO
		SELECT descripcion
		INTO cDescSufi
		FROM "informix".si_sufijos
		WHERE empresa = '001'
		AND codigo = TRIM(cSufijo);

		--SE OBTIENE LA DESCRIPCION DEL ESTADO DE cCdNotarioct

		SELECT nombre
		INTO cDesCdNot
		FROM "informix".si_estados
		WHERE estado = TRIM(cCdNotarioct);

		-- SE OBTIENE LA DESCRIPCION DEL ESTADO DE cCdNotariopd

		SELECT nombre
		INTO cDesCdNotpd
		FROM "informix".si_estados
		WHERE estado = TRIM(cCdNotariopd);

		LET cPrmTpopersonaGob = 'tpo'||TRIM(cTpoPersona);		                                              --el parámetro en la tabla sc_param.

		SELECT TRIM(valor)
		INTO cValorTpopersonaGop
		FROM bdicheq:"informix".sc_param
		WHERE empresa = '001'
		AND codparam = TRIM(cPrmTpopersonaGob);

		--SE OBTIENE LA DESCRIPCION DE DATOS DE PERSONAS DE GOBIERNO tpo_persona = '05'*
		IF cValorTpopersonaGop = 'S' THEN

			SELECT descripcion
			INTO cDesPoder
			FROM "informix".si_tipo_poder_pm
			WHERE empresa = '001'
			AND codigo = TRIM(cPoder);

			SELECT descripcion
			INTO cDesAdmin
			FROM "informix".si_tipo_admin_pm
			WHERE empresa = '001'
			AND codigo = TRIM(cAdmin);

			SELECT descripcion
			INTO cDesOrg
			FROM "informix".si_tipo_org_pm
			WHERE empresa = '001'
			AND codigo = TRIM(cOrg);

		ELSE

		   LET cDesPoder = "";
		   LET cDesAdmin = "";
		   LET cDesOrg = "";

		END IF;


		--SE OBTIENE LA CUENTA Y EL ESTATUS DE LA EMPRESA CON EL SERVICIO DE NOMINA
		SELECT TRIM(NVL(cuenta,'')), TRIM(NVL(status_alta,''))
		INTO cCuentaNomina, cStatusAlta
		FROM bdicheq:"informix".sc_nominaempresas
		WHERE numcte = TRIM(pNumcte);

		IF TRIM(NVL(cStatusAlta,'')) = '3' THEN
		   LET cRespStatus = 'Si';
		ELSE
		   LET cRespStatus = 'No';
		END IF;

		--SE OBTIENE NOMBRE DEL REPRESENTANTE LEGAL Y RFC.
		SELECT TRIM(NVL(apell_paterno,'')),TRIM(NVL(apell_materno,'')),
	    TRIM(NVL(nombre1,'')),TRIM(NVL(nombre2,''))
		INTO cApellPaterContactoRepLeg,cApellMaterContactoRepLeg,cNomb1ContactoRepLeg,cNomb2ContactoRepLeg
		FROM "informix".si_cliente
		WHERE numcte = TRIM(cNomContacto)
		AND empresa = '001';


		--SE OBTIENE DOMICILIO FISCAL.
		SELECT 	TRIM(NVL(e.nombrecalle,'')),TRIM(NVL(a.numeroextcalle,'')),TRIM(NVL(f.nombrezona,'')),
				TRIM(NVL(g.nombre,'')),TRIM(NVL(c.municipio,'')),TRIM(NVL(b.nombre,''))
		INTO cCalleFiscal,cNumExtCalleFiscal,cColFiscal,vNomCiudFiscal,cCodMunFiscal,cNomEstadoFiscal
		FROM "informix".si_direcciones_actual a
			 LEFT OUTER JOIN "informix".si_estados 	   b ON (a.estado = b.estado)
			 LEFT OUTER JOIN "informix".si_municipios  c ON (a.municipio = c.municipio AND a.estado = c.estado AND a.ciudad = c.ciudad AND a.pais = c.pais)
			 LEFT OUTER JOIN "informix".si_catcalles   e ON (a.numerocalle = e.numerocalle)
			 LEFT OUTER JOIN "informix".si_catzonas    f ON (a.numerociudad = f.numerociudad AND a.numerocolonia = f.numerocolonia)
			 LEFT OUTER JOIN "informix".si_ciudades    g ON (a.estado = g.estado AND a.ciudad = g.ciudad)
		WHERE a.numcte = TRIM(pNumcte)
		AND a.tipo_dir = 1;

		--SE OBTIENE GIRO MERCANTIL.
		SELECT TRIM(NVL(nombre,''))
		INTO cNomGiro
		FROM "informix".si_actecon
		WHERE actividad = TRIM(cGiro);

		--SE OBTIENE ACTIVIDAD U OBJETO SOCIAL.
		SELECT TRIM(NVL(descripcion,''))
		INTO cDesActObj
		FROM "informix".si_actividadsocial
		WHERE codigo = TRIM(cActividadSoc);

	    --SE OBTIENE EL ESTATUS DEL SERVICIO DE EMPRESANET DEL CLIENTE
	    SELECT MAX (NVL(status_contrato, 0))
		INTO iEstatusCteEmpNet
		FROM bdibei:"informix".bei_contratacion
		WHERE empresa = '001'
		AND num_cliente = pNumcte;
		
		--- RECONTRATACION DE SERVICIO DE EMPRESANETPLUS------------------------------------------------------------------------
			
			IF iEstatusCteEmpNet=99 THEN
			
			--EJECUTAR SPL QUE SE ESTA GENERANDO PARA COLOCAR LA INFO EN HISTORICOS
			EXECUTE PROCEDURE bdibei:"informix".sp_gen_hist_servicioplus_bei(pNumcte) into cCodRet;
			
			--MANDAR LLAMAR SPLS PARA REGISTRAR EN HISTORICOS Y BORRAR DE TABLAS
			IF cCodRet <>'00000' THEN
				LET cCodRet='00004'; --Error en el sp_gen_hist_servicioplus_bei
			END IF;
							
			ELSE	
				
				RETURN cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));
						
			END IF;
		--FIN RECONTRATACION-----------------------------------------------------------------------------------------------------

		--OBTIENE EL NUMERO DE CTE APODERADO ASI COMO SU NOMBRE
		SELECT numcteapoderado,nombreapoderado
		INTO cNumcteapoder, cNomapoder
		FROM "informix".si_apoderado
		WHERE empresa = '001'
		AND numcte = TRIM(cNumcte)
		AND secuencia = (SELECT MAX(secuencia) FROM "informix".si_apoderado WHERE empresa = '001');

		--SE OBTIENE EL AUTORIZADO PARA MANEJAR LAS CUENTAS DE REGISTRO FIRMAS:
		SELECT TRIM(NVL(b.apell_paterno,'')),TRIM(NVL(b.apell_materno,'')),TRIM(NVL(b.nombre1,'')),TRIM(NVL(b.nombre2,''))
		INTO cApellPaterFirmantes,cApellMaterFirmantes,cNomb1Firmantes,cNomb2Firmantes
		FROM bdicheq:"informix".sc_firmantes a INNER JOIN "informix".si_cliente b ON(a.numcte = b.numcte)
		WHERE a.empresa = '001'
		AND a.cuenta = TRIM(cCuentaNomina)
		AND a.secuencia = 1;

		--SE OBTIENE EL NOMBRE DE LA SUCURSAL
		SELECT nombre
		INTO cNombreSucursal
        FROM "informix".si_sucursales
        WHERE sucursal = TRIM(cSucursal);

		--SE RETORNA INFORMACION.
	   RETURN 	cCodRet,TRIM(NVL(cRFC,'')),TRIM(NVL(cApellPaterContactoRepLeg,'')),TRIM(NVL(cApellMaterContactoRepLeg,'')),TRIM(NVL(cNomb1ContactoRepLeg,'')),
			            TRIM(NVL(cNomb2ContactoRepLeg,'')),TRIM(NVL(cCalleFiscal,'')),TRIM(NVL(cNumExtCalleFiscal,'')),TRIM(NVL(cColFiscal,'')),
						TRIM(NVL(vNomCiudFiscal,'')),TRIM(NVL(cCodMunFiscal,'')),TRIM(NVL(cNomEstadoFiscal,'')),TRIM(NVL(cNumcte,'')),TRIM(NVL(cNomCorto,'')),
						TRIM(NVL(cPagInternet,'')),TRIM(NVL(cSatFea,'')),TRIM(NVL(cTelContacto,'')),TRIM(NVL(cGiro,'')),TRIM(NVL(cNomGiro,'')),
						TRIM(NVL(cActividadSoc,'')),TRIM(NVL(cDesActObj,'')),TRIM(NVL(cRespStatus,'')),TRIM(NVL(cApellPaterFirmantes,'')),
						TRIM(NVL(cApellMaterFirmantes,'')),TRIM(NVL(cNomb1Firmantes,'')),TRIM(NVL(cNomb2Firmantes,'')),TRIM(NVL(cDesPoder,'')),
						TRIM(NVL(cDesAdmin,'')),TRIM(NVL(cDesOrg,'')),NVL(dFechaIns,DATE(1)),NVL(dFechaCons,DATE(1)),TRIM(NVL(cNac,'')),TRIM(NVL(cDesNacion,'')),
						TRIM(NVL(cNomContacto,'')),TRIM(NVL(cSufijo,'')),TRIM(NVL(cDescSufi,'')),TRIM(NVL(cEscritura,'')),TRIM(NVL(cNombreNot,'')),TRIM(NVL(cNumNot,'')),
						TRIM(NVL(cCdNotarioct,'')),TRIM(NVL(cDesCdNot,'')),TRIM(NVL(cEscrituraPod,'')),TRIM(NVL(cNomNotariopd,'')),TRIM(NVL(cNumNotariopd,'')),
						TRIM(NVL(cCdNotariopd,'')),TRIM(NVL(cDesCdNotpd,'')),TRIM(NVL(cNombreSoc,'')),NVL(dFechaInspd,DATE(1)),TRIM(NVL(cEmailpm,'')),
						TRIM(NVL(cCdfoliomerct,'')),TRIM(NVL(cNumfoliomerct,'')),NVL(iEstatusCteEmpNet, 0),TRIM(NVL(cAuxiliar1, '')),TRIM(NVL(cAuxiliar2, '')),
						TRIM(NVL(cAuxiliar3, '')),TRIM(NVL(cAuxiliar4,'')),TRIM(NVL(cAuxiliar5,'')),TRIM(NVL(cAuxiliar6,'')),TRIM(NVL(cAuxiliar7,'')),
						TRIM(NVL(cAuxiliar8,'')),TRIM(NVL(cAuxiliar9,'')),TRIM(NVL(cAuxiliar10,'')), TRIM(NVL(cTpoPersona,'')),TRIM(NVL(cNumcteapoder,'')),
						TRIM(NVL(cNomapoder,'')),TRIM(NVL(cDocConst,'')),TRIM(NVL(cSucursal,'')),NVL(dFechaAlta,DATE(1)),TRIM(NVL(cAuxiliar11,'')),TRIM(NVL(cPoder,'')),
						TRIM(NVL(cAdmin,'')),TRIM(NVL(cOrg,'')),TRIM(NVL(cNombreSucursal,'')), TRIM(NVL(cValorTpopersonaGop,''));

	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Procedimiento que obtiene la informacion del cliente moral',
'ahora validando de manera general el tipo de persona.',
'AUTOR:  Mireya Reyes',
'FECHA DE CREACION: 22/08/2013',
'VERSION: 20130823.1430',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_actualizarfc_dos()
RETURNING CHAR(5) as codret, CHAR(5) as codret2, CHAR(5) as mensaje;

DEFINE vcodret1         char(5); 
DEFINE vcodret2         char(5);
DEFINE vcodret3         char(50);
DEFINE sql_err          integer;
DEFINE isam_err         integer;
DEFINE desc_err         char(50);
DEFINE vnumcte          char(10);
DEFINE vrfc_calculado   char(13);
DEFINE vcomienza        smallint;
DEFINE ven_transacc     smallint;
DEFINE vcontador1       integer;

LET vcodret1            ='00000';
LET vcodret2            ='0000';
LET vcodret3            ='PROCESO CONCLUIDO SATISFACTORIAMENTE';
LET sql_err             =0;
LET isam_err            =0;
LET desc_err            ='';
LET vcomienza           =-1;
LET ven_transacc        = 0;  
LET vnumcte             ='';
LET vrfc_calculado      ='';
LET vcontador1          =0;



BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/arch_sp_actualizarfc.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;

            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH WITH HOLD
        select  numcte, rfc_calculado INTO vnumcte,  vrfc_calculado from resultadosrfc where rfc_duplicado=0
    
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        UPDATE si_cliente set rfc=vrfc_calculado where numcte=vnumcte and fecha_alta<'10/22/2014';

        LET vcontador1 = vcontador1 + 1;
        

        IF (vcontador1 >= 5000) THEN
            LET vcontador1 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
     END FOREACH;

     IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
     END IF;

END;
RETURN vcodret1, vcodret2, vcodret3; 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarfc_dos()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(9);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='316';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='316';

        set isolation to dirty read;
        FOREACH  
                SELECT a.numcte, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
                INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
                    FROM bdinteg:si_cliente a
                        INNER JOIN bdinteg:si_ctepf b
                            ON a.numcte=b.numcte
                    WHERE a.empresa='001' and length(a.apell_paterno)>2
						AND a.tpo_persona='01'
                        AND a.numcte>=vNumCteIni
                    ORDER BY a.numcte
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado, fecha)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1', '10/28/2014');
                ELSE
                --NO SE ENCONTRARON REGISTROS CON EL MISMO RFC EN RECALCULADOS, SE BUSCA EN si_cliente
                    SELECT count(*) INTO iTotDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo;
                    LET iNumRows = dbinfo("sqlca.sqlerrd2");
                    IF iNumRows>0 AND iTotDupRec>0 THEN
                    --SE ENCONTRARON REGISTROS DUPLICADOS EN si_cliente
                        IF iTotDupRec=1 THEN
                           SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo; 
                        ELSE
                            FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:si_cliente WHERE rfc=cRFCNuevo
                                LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                            END FOREACH;
                        END IF;

                        INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado, fecha)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1', '10/28/2014');
                    ELSE--CUANDO NO SE ENCUENTREN EN LA TABLA DE RECALCULADOS NI EN LA SI_CLIENTES
                        INSERT INTO bdinteg:resultadosrfc (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado, fecha)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1', '10/28/2014');
                    END IF;
                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cnsif_consclientechq(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCUENTA CHAR(20))
							
				returning CHAR(5)  AS Cod_Retorno, 
						  CHAR(20) AS Numero_Cliente, 
						  CHAR(50) AS Nombre, 
						  DATE     AS Fecha_Nacimiento, 
						  CHAR(13) AS RFC, 
						  DATE     AS Fecha_Alta;
												
DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;
							
--VARIABLES
DEFINE cNumeroCta       CHAR(20);
DEFINE cNumeroCliente   CHAR(20);
DEFINE cNombre 	        CHAR(50);
DEFINE dFechaNacimiento	DATE;
DEFINE cRFC 	        CHAR(13);
DEFINE dFechaAlta 	    DATE;

--inicializando variables
LET  iexiste 		 = 0;
LET cCodRet 		 = "00000";
LET iSql_err 		 = 0 ;	
LET cNumeroCta       = '';
LET cNumeroCliente   = '';
LET cNombre	         = "";
LET dFechaNacimiento = "";
LET cRFC	         = "";
LET dFechaAlta	     = "";

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,cNumeroCliente,cNombre, dFechaNacimiento, cRFC, dFechaAlta;						
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_consclientechq.out";
	--TRACE ON;
		
	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMCUENTA   = '' THEN 
		LET cCodRet = "00069";
		RETURN cCodRet,cNumeroCliente,cNombre, dFechaNacimiento, cRFC, dFechaAlta;						
	END IF;	
 
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'30','1')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
		RETURN cCodRet,cNumeroCliente,cNombre, dFechaNacimiento, cRFC, dFechaAlta;						
	END IF;
	-- TERMINA VALIDACION
 
		FOREACH
		SELECT FIRST 1 NVL(COUNT(cuenta),0) INTO iexiste FROM bdicheq:sc_maechq WHERE empresa = '001' AND  cuenta = cNUMCUENTA
		UNION
		SELECT NVL(COUNT(cuenta_tf),0) FROM bditransfer:tf_maecte WHERE empresa = '001' AND  cuenta_tf = cNUMCUENTA
		ORDER BY 1 DESC
		END FOREACH;
		IF iexiste  = 0 THEN 
		LET cCodRet = "00070";
		RETURN cCodRet,cNumeroCliente,cNombre, dFechaNacimiento, cRFC, dFechaAlta;						
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		
		FOREACH 
		 EXECUTE PROCEDURE bdicntchq:sp_consclientechq('001',1,cNUMCUENTA)
		 INTO 		
		 cCodRet, cNumeroCta, cNumeroCliente, cNombre, cRFC, dFechaAlta, dFechaNacimiento
		
		IF LENGTH(cCodRet) = 3 THEN			
			LET cCodRet = '00' || cCodRet;
		END IF;
		
		RETURN 	cCodRet,cNumeroCliente,cNombre, dFechaNacimiento, cRFC, dFechaAlta WITH resume;	
		
		END FOREACH;
		
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información de  Personas Autorizadas asociadas a una Cuenta de Cheques. ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Número de Cuenta",
"FECHA : 27-02-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_cnsif_ideconsultarecofi(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCLIENTE CHAR(20),cPERIODO CHAR(06))
							
			returning   CHAR(5)     AS Cod_Retorno,
						DATE        AS Fecha_Cargo,	      
						CHAR(20)    AS Cuenta,          
						CHAR(06)    AS Periodo,
						MONEY(16,2) AS Importe,
                        CHAR(2)     AS SistemaCuenta;

							
DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;		

DEFINE v_cod_ret    CHAR(5);
DEFINE dFechaCargo  DATE;
DEFINE cNumCuenta   CHAR(20);
DEFINE cPeriodos    CHAR(06);
DEFINE mImporte     MONEY(16,2);
DEFINE Total_Recaudaciones   MONEY(16,2);
DEFINE cSistemaC    CHAR(2);
DEFINE cNumCtePrincipal CHAR(20);
DEFINE iTpo_cliente			INT;
--DEFINE Total_RecauAux        MONEY(16,2);

LET  v_cod_ret    = "00000";
LET dFechaCargo   = "";
LET cNumCuenta    = "";
LET cPeriodos     = "";
LET mImporte      = 0;
LET Total_Recaudaciones = 0;
--LET Total_RecauAux      = 0;

--inicializando variables
LET  iexiste 		 = 0;
LET cCodRet 		 = "00000";
LET iSql_err 		 = 0 ;         
LET cSistemaC        ='00';
LET iTpo_cliente=0;
LET cNumCtePrincipal = "";

BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC;						
		END IF;
	END EXCEPTION;
	--SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_ideconsultarecofi_2.out";
	--TRACE ON;

	IF 	cID_USUARIOC  = '' 	OR
		cID_FUNCIONC  = '' 	OR
		cNUMCLIENTE   = ''	OR
		cPERIODO      = ''  THEN 
		LET cCodRet = "00060";
		RETURN cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC;
	END IF;	
	
	--VALIDACION
	EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCLIENTE,'23','2')
	INTO
	cCodRet;
	IF (cCodRet != '00000')  THEN
	    RETURN cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC;						
	END IF;
	-- TERMINA VALIDACION

	EXECUTE PROCEDURE bdicnweb:"informix".sp_validacte_transfer(cNUMCLIENTE) INTO cCodRet,iTpo_cliente,cNumCtePrincipal;
	IF cNumCtePrincipal IS NOT NULL THEN
		LET cNUMCLIENTE = cNumCtePrincipal;
	END IF;

	FOREACH
	SELECT FIRST 1 NVL(COUNT(numcte),0) INTO iexiste FROM si_cliente WHERE numcte  = cNUMCLIENTE
	UNION
	SELECT NVL(COUNT(numcte_tf),0) FROM  bditransfer:tf_maecte WHERE numcte_tf  = cNUMCLIENTE
	ORDER BY 1 DESC
	END FOREACH;
	IF iexiste  = 0 THEN 
		LET cCodRet = "00062";
		RETURN cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC;
	END IF;

	SELECT NVL(COUNT(num_cte),0) INTO iexiste FROM  bdilide:sl_detlide WHERE num_cte  = cNUMCLIENTE;
	IF iexiste  = 0 THEN 
		LET cCodRet = "00061";
		RETURN cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC;
	END IF;
	
	SET ISOLATION TO DIRTY READ;
	FOREACH
	
		EXECUTE PROCEDURE bdilide:sp_ideconsultarecofi(cNUMCLIENTE, cPERIODO,0)
		INTO
		v_cod_ret, dFechaCargo,cNumCuenta,cPeriodos,mImporte

		IF LENGTH(v_cod_ret) = 3 THEN
			LET  cCodRet = '00' || v_cod_ret;
		ELIF LENGTH(v_cod_ret) = 5 THEN
			LET  cCodRet = v_cod_ret;
		END IF
		IF SUBSTR(TRIM(cNumCuenta),1,1)='3' THEN
            LET cSistemaC='03';
        ELIF SUBSTR(TRIM(cNumCuenta),1,1)='6' THEN
            LET cSistemaC='06';
        ELSE
            LET cSistemaC='01';
        END IF;
        RETURN 	cCodRet,dFechaCargo,cNumCuenta,cPeriodos,mImporte,cSistemaC WITH Resume;
	END FOREACH
	
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener Detalle de Recaudaciones LIDE. ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Número de Cliente.",
"FECHA : 15-03-2012",
"BD    : bdinteg",
"VER   : 1.0";

CREATE PROCEDURE "informix".sp_consultacuentadebito( psNumCuenta CHAR(13), psNumCliente CHAR(20), psNumTarjeta CHAR(16), psEmpresa CHAR(3), piTipoBusqueda SMALLINT )
	RETURNING CHAR(5) AS CodigoRetorno, 
		CHAR(13) AS NumCuenta, CHAR(20) AS NumCliente, CHAR(16) AS NumTarjeta, CHAR(40) AS DescProducto, 
		CHAR(26) AS Nombre1, CHAR(26) AS Nombre2, CHAR(26) AS ApellidoPaterno, CHAR(26) AS ApellidoMaterno, 
		CHAR(30) AS Status;
	
	--Declaración de variables.
	DEFINE sCodigoRetorno 	CHAR(5);
	DEFINE sSqlErr			INTEGER;
	DEFINE sNumCuenta		CHAR(13);
	DEFINE sNumCliente  	CHAR(20);
	DEFINE sNumTarjeta  	CHAR(16);
	DEFINE sCodProducto		CHAR(4);
	DEFINE sDescProducto   	CHAR(40);	
	DEFINE iCont			INTEGER;
	DEFINE iSecuencia   	INTEGER;
	DEFINE sNombre1 		CHAR(26);
	DEFINE sNombre2 		CHAR(25);
	DEFINE sApellidoPaterno CHAR(25);
	DEFINE sApellidoMaterno CHAR(25);
	DEFINE sStatus   		CHAR(30);
	DEFINE iTpo_cliente		INT;
	DEFINE cNumCtePrincipal CHAR(20);
	DEFINE cNumCteTf		CHAR(20);


	--Asignación de valores a variables.
	LET sCodigoRetorno = '00000';
	LET sSqlErr = 0;
	LET sNumCuenta = ''; 
	LET sNumCliente = '';
	LET sNumTarjeta = '';
	LET sDescProducto = '';	
	LET sCodProducto ='';
	LET iCont = 0;
	LET sNombre1 = '';
	LET sNombre2 = '';
	LET sApellidoPaterno = '';
	LET sApellidoMaterno = '';
	LET iSecuencia = 0;
	LET sStatus = '';
	LET iTpo_cliente=0;
	LET cNumCtePrincipal = "";
	LET cNumCteTf = "";
	

	BEGIN
		ON EXCEPTION SET sSqlErr
			IF sSqlErr <> 0 THEN
				LET sCodigoRetorno = sSqlErr;				
				RETURN sCodigoRetorno, 
					sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
					sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
					sStatus;
			END IF;
		END EXCEPTION;

		--SET DEBUG FILE TO "/informix/SIA/sp_consultacuentadebito.out";
		--TRACE ON;

		SET ISOLATION DIRTY READ;
		SET LOCK MODE TO WAIT 3;


		EXECUTE PROCEDURE bdicnweb:"informix".sp_validacte_transfer(psNumCliente) INTO sCodigoRetorno,iTpo_cliente,cNumCtePrincipal;
		IF cNumCtePrincipal IS NOT NULL THEN
			LET psNumCliente = cNumCtePrincipal;
		END IF;
		
		--Búsqueda por número de cuenta.
		IF( piTipoBusqueda = 1 ) THEN
		
			LET psNumCuenta = TRIM( psNumCuenta );
			
			-- Se busca la cuenta en el maestro de cheques.
			--SELECT a.cuenta, NVL( a.num_cte, '' ), NVL( a.status_cta, '' ), b.producto, b.nombre
				--INTO sNumCuenta, sNumCliente, sStatus, sCodProducto, sDescProducto
			FOREACH
			SELECT a.cuenta, NVL( a.num_cte, '' ), b.producto, b.nombre
				INTO sNumCuenta, sNumCliente, sCodProducto, sDescProducto
			FROM bdicheq:"informix".sc_maechq a
				JOIN bdicheq:"informix".sc_producto b ON ( a.producto = b.producto )
			WHERE a.empresa = psEmpresa AND a.cuenta = psNumCuenta
			UNION
			SELECT a.cuenta_tf, CASE WHEN iTpo_cliente = 1 THEN a.numcte_tf ELSE a.numcte END, b.producto, b.nombre
			FROM bditransfer:"informix".tf_maecte a
				JOIN bdicheq:"informix".sc_producto b ON ( a.producto = b.producto )
			WHERE a.empresa = psEmpresa AND a.cuenta_tf = psNumCuenta
			END FOREACH;

			-- Se valida si la cuenta se encontró...
			IF ( sNumCuenta IS NULL ) THEN				

				-- Se busca la cuenta en el maestro de pagarés.
				--SELECT NVL( a.cuenta, '' ), NVL( a.num_cte, '' ), NVL( a.status_cta, '' ), b.nombre
					--INTO sNumCuenta, sNumCliente, sStatus, sDescProducto
				SELECT NVL( a.cuenta, '' ), NVL( a.num_cte, '' ), b.nombre
					INTO sNumCuenta, sNumCliente, sDescProducto
				FROM bdinvers:"informix".sv_maeinv a
					LEFT OUTER JOIN bdinvers:"informix".sv_instrum b ON ( b.cod_instrum = a.cod_instrum )
				WHERE a.empresa = psEmpresa AND a.cuenta = psNumCuenta 
					AND a.secuencia = ( 
						SELECT MAX( secuencia )
						FROM bdinvers:"informix".sv_maeinv
						WHERE empresa = psEmpresa AND cuenta = psNumCuenta );
			
			ELIF ( sCodProducto <> '1100' ) THEN -- Si no es una cuenta de inversión creciente...
			SELECT numcte_tf
				INTO cNumCteTf
				FROM bditransfer:"informix".tf_maecte
				WHERE cuenta_tf = psNumCuenta;
			
			IF cNumCteTf IS NOT NULL THEN
				LET sNumCliente = cNumCteTf;
			END IF;
			FOREACH

				-- Se busca la tarjeta relacionada a la cuenta de débito.
				SELECT NVL( a.numcuenta, '' ), a.numtarjeta
					INTO sNumCuenta, sNumTarjeta
				FROM intercard:"informix".tarjetacuenta a
					LEFT OUTER JOIN bdicheq:"informix".sc_tarjeta b ON ( b.empresa = psEmpresa AND b.num_tarjeta  = a.numtarjeta )
				WHERE b.numcte = sNumCliente AND b.cuenta = psNumCuenta

				
				SELECT UPPER(b.descstatustarjeta)
				INTO sStatus
				FROM intercard:"informix".tarjeta a JOIN intercard:"informix".statustarjeta b
				ON (a.codstatustarjeta = b.codstatustarjeta)
				WHERE a.numtarjeta = sNumTarjeta;
				
				IF ( sNumCuenta <> '' AND sNumCliente <> '' AND sDescProducto <> '' ) THEN
					FOREACH
					SELECT numcte, NVL( nombre1, '' ), NVL( nombre2, '' ), NVL( apell_paterno, '' ), NVL( apell_materno, '' )
						INTO sNumCliente, sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno
					FROM bdinteg:"informix".si_cliente
					WHERE numcte = sNumCliente
					UNION
					SELECT CASE WHEN iTpo_cliente = 1 THEN numcte_tf ELSE numcte END, NVL( nombre1, '' ), NVL( nombre2, '' ), NVL( apell_paterno, '' ), NVL( apell_materno, '' )
					FROM bditransfer:"informix".tf_maecte
					WHERE numcte_tf = sNumCliente
					END FOREACH;
				
					IF ( sNumCliente IS NOT NULL ) THEN 

						LET iCont = 1;
						
						RETURN sCodigoRetorno, 
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
							sStatus WITH RESUME;
						
					END IF;
			    END IF;	
			END FOREACH;	
			END IF;
			
			IF ( sCodProducto = '1100' ) THEN
				--IF ( sNumCuenta <> '' AND sNumCliente <> '' AND sStatus <> '' AND sDescProducto <> '' ) THEN
				IF ( sNumCuenta <> '' AND sNumCliente <> '' AND sDescProducto <> '' ) THEN
				FOREACH
					SELECT numcte, NVL( nombre1, '' ), NVL( nombre2, '' ), NVL( apell_paterno, '' ), NVL( apell_materno, '' )
						INTO sNumCliente, sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno
					FROM bdinteg:"informix".si_cliente
					WHERE numcte = sNumCliente
					
					IF ( sNumCliente IS NOT NULL ) THEN 

						LET iCont = 1;
						
						RETURN sCodigoRetorno, 
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
							sStatus WITH RESUME;
						
					END IF;
				END FOREACH;	
				END IF;	
			END IF;
		
		-- Búsqueda por número de cliente.
		ELIF ( piTipoBusqueda = 2 ) THEN
	
			LET psNumCliente = TRIM( psNumCliente );
			
			-- Se buscan las cuentas de cheques e inversiones crecientes.
			FOREACH
				SELECT cuenta
					INTO sNumCuenta
				FROM bdicheq:"informix".sc_maechq
				WHERE num_cte = psNumCliente
				UNION
				SELECT cuenta_tf 
				FROM bditransfer:tf_maecte
				WHERE CASE WHEN iTpo_cliente = 1 THEN numcte_tf ELSE numcte END = psNumCliente
				FOREACH
					EXECUTE PROCEDURE bdinteg:"informix".sp_consultacuentadebito( sNumCuenta, psNumCliente, psNumTarjeta, psEmpresa, 1 )
						INTO sCodigoRetorno, 
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
							sStatus
						
					IF ( sCodigoRetorno = '00000' ) THEN
					
						LET iCont = iCont + 1;
						
						RETURN sCodigoRetorno,
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto,
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
							sStatus WITH RESUME;
					
					END IF;
				END FOREACH;	
			END FOREACH;
			
			-- Se buscan las cuentas de pagarés.
			FOREACH
				SELECT DISTINCT cuenta
					INTO sNumCuenta
				FROM bdinvers:"informix".sv_maeinv
				WHERE num_cte = psNumCliente
				FOREACH
					EXECUTE PROCEDURE bdinteg:"informix".sp_consultacuentadebito( sNumCuenta, psNumCliente, psNumTarjeta, psEmpresa, 1 )
						INTO sCodigoRetorno, 
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
							sStatus
							
					IF ( sCodigoRetorno = '00000' ) THEN
					
						LET iCont = iCont + 1;
						
						RETURN sCodigoRetorno,
							sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto,
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno,
							sStatus WITH RESUME;
					
					END IF;
				END FOREACH;	
			END FOREACH;			

		-- Búsqueda por número de tarjeta.
		/*ELIF ( piTipoBusqueda = 3 ) THEN
		
			LET psNumTarjeta = TRIM( psNumTarjeta );
			
			-- Se busca la cuenta de la tarjeta.
			SELECT a.cuenta
				INSERT INTO sNumCuenta
			FROM bdicheq:"informix".sc_tarjeta a
				LEFT OUTER JOIN intercard:"informix".tarjeta b ON ( a.num_tarjeta = b.numtarjeta )
				LEFT OUTER JOIN intercard:"informix".statustarjeta c ON ( b.codstatustarjeta = c.codstatustarjeta )
			WHERE a.empresa = psEmpresa AND a.num_tarjeta = psNumTarjeta;

			IF ( NVL( sNumCuenta, '' ) <> '' ) THEN
			
				EXECUTE PROCEDURE bdinteg:"informix".sp_consultacuentadebito( sNumCuenta, psNumCliente, psNumTarjeta, psEmpresa, 1 )
					INTO sCodigoRetorno, 
						sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
						sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, 
						sStatus;
				
				IF ( sCodigoRetorno = '00000' ) THEN
				
					LET iCont = 1;
					
					RETURN sCodigoRetorno,
						sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto,
						sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno,
						sStatus;
				
				END IF;
			END IF;				
		END IF;*/
		ELIF (piTipoBusqueda = 3) THEN
			LET psNumTarjeta = TRIM(psNumTarjeta);
			SELECT a.cuenta, a.numcte, a.num_tarjeta, NVL(c.nombre, '')
			INTO sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto
			FROM bdicheq:"informix".sc_tarjeta a
			LEFT OUTER JOIN bdicheq:"informix".sc_maechq b ON (a.cuenta = b.cuenta) 
			JOIN bdicheq:"informix".sc_producto c ON (b.producto = c.producto)				
			WHERE a.num_tarjeta = psNumTarjeta AND a.empresa = psEmpresa; 
			
			IF (sNumCuenta IS NOT NULL AND sNumCliente IS NOT NULL AND sNumTarjeta IS NOT NULL AND sDescProducto <> '') THEN
				
				SELECT numcte, NVL(nombre1, ''), NVL(nombre2, ''), NVL(apell_paterno, ''), NVL( apell_materno, '')
				INTO sNumCliente, sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno
				FROM bdinteg:"informix".si_cliente WHERE numcte = sNumCliente;
				
					IF (sNumCliente IS NOT NULL) THEN

						SELECT UPPER(b.descstatustarjeta)
						INTO sStatus FROM intercard:"informix".tarjeta a JOIN intercard:"informix".statustarjeta b
						ON (a.codstatustarjeta = b.codstatustarjeta) WHERE a.numtarjeta = sNumTarjeta;
								
						IF (sNumCliente IS NOT NULL) THEN 						
							LET iCont = 1;					
							RETURN sCodigoRetorno, sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto, 
							sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno, sStatus WITH RESUME;							
						END IF;
				    END IF;
			END IF;			
		END IF;
		
		IF ( iCont = 0 ) THEN
		
			LET sCodigoRetorno = '00001'; -- Cliente no tiene cuentas.
			
			RETURN sCodigoRetorno,
				sNumCuenta, sNumCliente, sNumTarjeta, sDescProducto,
				sNombre1, sNombre2, sApellidoPaterno, sApellidoMaterno,
				sStatus;
			
		END IF;
	END;
END PROCEDURE
DOCUMENT
'CREADO:		Francisco Rodríguez Ibarra.',
'FECHA:			30 de abril de 2010.',
'DESCRIPCIÓN:	Obtiene las cuentas de débito , ya sea por numcliente, por cuenta o por numtarjeta',
'RETORNO:		00000 Datos obtenidos satisfactoriamente',
'				00001 Cliente sin cuentas.',

'MODIFICÓ:		Ulises Rodríguez Márquez.',
'FECHA:			Viernes, 31 de Diciembre de 2011.',
'MODIFICACIÓN:	Se reestructuran y optimizan las búsquedas para consultar cuentas de cheques, inversiones y pagarés.',

'MODIFICÓ:		Bernardo Carlos Báez González .',
'FECHA:			10 de Febrero de 2012.',
'PRO./FOLIO:    SIFAuditoria/1249.',
'PAQUETE/CU:    PCU-bdinteg/CU-0162-ConsultarCuentaDebito-SPL.',
'MODIFICACIÓN:	Se Modifican Para que se Retorne el Status de Tarjeta en vez status de la Cuenta.',

'MODIFICÓ:		JOSE ANGEL GAXIOLA GAXIOLA.',
'FECHA:			09 DE OCTUBRE DE 2012 .',
'PRO./FOLIO:    ConsultaAuditoriaSIF/1228.',
'MODIFICACIÓN:	SE MODIFICA AGREGANDOLE FOREACH PARA QUE PUEDA RETORNAR MAS DE UNA TARJETA PARA UNA CUENTA .';

CREATE PROCEDURE "informix".sp_dicta_consanalistadictamen()

	-- RETORNOS DEL PROCEDIMIENTO
	RETURNING 	CHAR(6)  		AS  Codigo,
				CHAR(8)			AS 	Numero,
				CHAR(45)		AS 	Nombre;
				
	--DEFINICION DE VARIABLES
	DEFINE iSqlErr 			INTEGER;
	DEFINE cCodRet 			CHAR(6);
	DEFINE cNumAnalista 	CHAR(8);
	DEFINE cNombreAnalista 	CHAR(45);
	
	--INICIALIZACION DE VARIABLES
	LET iSqlErr 		= 0;
	LET cCodRet 		= '000000';
	LET cNumAnalista 	= '';
	LET cNombreAnalista = '';
	
	--SET DEBUG FILE TO '/informix/cristo/sp_dicta_consanalistadictamen.out';
	--TRACE ON;
	
		BEGIN 				--CONTROL DE ERRORES DE INFORMIX
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;			
				RETURN cCodRet, TRIM(NVL(cNumAnalista,"")), TRIM(NVL(cNombreAnalista,""));
			END IF;
		END EXCEPTION;	

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
			
			-- SE BUSCAN TODOS LOS REGISTROS DE TIPO DE DICTAMEN Y SU DESCRIPCION
			FOREACH   
				SELECT DISTINCT (TRIM(analista_fraudes))
				INTO cNumAnalista
				FROM 'informix'.si_bitacora_comparaciones
				WHERE status_alerta = 3
				
				SELECT nombre
				INTO cNombreAnalista
				FROM 'informix'.si_ejecut
				WHERE ejecutivo = cNumAnalista;
				
				RETURN cCodRet, TRIM(NVL(cNumAnalista,"")), TRIM(NVL(cNombreAnalista,"")) WITH RESUME;				
			END FOREACH
			
			 -- SE VALIDA SI LA CONSULTA NO CONTIENE REGRESA DATOS
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN 
				LET cCodRet = '000001';
				RETURN cCodRet, TRIM(NVL(cNumAnalista,"")), TRIM(NVL(cNombreAnalista,""));
			END IF;
		END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: PROCEDIMIENTO QUE CONSULTA LOS CAMPOS TIPODICTAMEN Y DESCRIPCION DE LA TABLA BDISITESP:SE_CATDICTAMENES ',
'AUTOR: FRANCISCO EDUARDO BENITEZ BAEZ ',
'FECHA: 10 DE SEPTIEMBRE DEL 2014 ',
'VERSION: 201410091730',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_dicta_consultacatdictamen()

	-- RETORNOS DEL PROCEDIMIENTO
	RETURNING 	CHAR(6)  		AS  CODIGO_DE_RETORNO,
				CHAR(1)			AS 	TIPO_DE_DICTAMEN,
				CHAR(100)		AS 	DESCRIPCION
				
	--DEFINICION DE VARIABLES
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRet CHAR(6);
	DEFINE cTipoDictamen CHAR(1);
	DEFINE cDescripcion CHAR(100);
	
	--INICIALIZACION DE VARIABLES
	LET iSqlErr 		= 0;
	LET cCodRet 		= "000000";
	LET cTipoDictamen 	= "";
	LET cDescripcion 	= "";
	
	--SET DEBUG FILE TO '/informix/cristo/sp_dicta_consultacatdictamen.out';
	--TRACE ON;
	
		BEGIN 				--CONTROL DE ERRORES DE INFORMIX
		ON EXCEPTION
			SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;			
				RETURN cCodRet, TRIM(NVL(cTipoDictamen,"")), TRIM(NVL(cDescripcion,""));
			END IF;
		END EXCEPTION;	

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
			
			-- SE BUSCAN TODOS LOS REGISTROS DE TIPO DE DICTAMEN Y SU DESCRIPCION
			FOREACH   
				SELECT tipoDictamen, TRIM(descripcion)
				INTO cTipoDictamen, cDescripcion
				FROM bdisitesp:"informix".se_catdictamenes
				ORDER BY tipoDictamen, descripcion
				RETURN cCodRet, TRIM(NVL(cTipoDictamen,"")), TRIM(NVL(cDescripcion,"")) WITH RESUME;				
			END FOREACH
			
			 -- SE VALIDA SI LA CONSULTA NO CONTIENE REGRESA DATOS
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN 
				LET cCodRet = '000001';
				LET cDescripcion = 'NO EXISTEN REGISTROS CON LA INFORMACION PROPORCIONADA.';
				RETURN cCodRet, TRIM(NVL(cTipoDictamen,"")), TRIM(NVL(cDescripcion,""));
			END IF;
		END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: PROCEDIMIENTO QUE CONSULTA LOS CAMPOS TIPODICTAMEN Y DESCRIPCION DE LA TABLA BDISITESP:SE_CATDICTAMENES ',
'AUTOR: FRANCISCO EDUARDO BENITEZ BAEZ ',
'FECHA: 10 DE SEPTIEMBRE DEL 2014 ',
'VERSION: 201410091730',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_alta_indicadores_2014_prod(fecha_inicial DATE, fecha_final DATE)
RETURNING CHAR(6), CHAR(100);
--VARIABLES DE ERROR
DEFINE cVarDataErr      	VARCHAR(64);
DEFINE iSqlErr          	INTEGER;
DEFINE iSamErr          	INTEGER;
DEFINE vCodRet          	CHAR(6);
--DEFINICION DE VARIABLES		
--DEFINE dFechahoy			DATE;		
DEFINE vcod_param_sms		SMALLINT;
DEFINE vcod_param_cels		SMALLINT;
DEFINE vcod_param_correo	SMALLINT;
DEFINE dmax_fecha_insert	DATE;
DEFINE vsms_val				INTEGER;
DEFINE vsms_total			INTEGER;
DEFINE vsms_no_val			INTEGER;
--DEFINE fecha_inicial		DATE;
--DEFINE  fecha_final	DATE;
DEFINE ivalidos				INTEGER;
DEFINE iinvalidos			INTEGER;
DEFINE isin_validar			INTEGER;
DEFINE mes_inicial 			INTEGER;
DEFINE mes_final 			INTEGER;

--ALTA DE CLIENTES
DEFINE vcod_param_alta_cte	SMALLINT;  
DEFINE cnumcte				CHAR(20);
DEFINE iBanco				INTEGER;
DEFINE icoppel				INTEGER;
DEFINE ibanco_coppel 		INTEGER;
DEFINE isolo_coppel 		INTEGER;
DEFINE isolo_banco			INTEGER;
DEFINE ibca_basica			INTEGER;
DEFINE ibca_avanzada		INTEGER;
DEFINE csucursal			CHAR(4);
DEFINE iprospectos			INTEGER;
DEFINE dfecha_alta			DATE;
DEFINE iTitulares			INTEGER;
DEFINE isinproductos		INTEGER;

--ASIGNACION DE VARIABLES
LET vcod_param_sms=0;
LET vcod_param_cels=0;
LET vcod_param_correo=0;
LET vsms_val=0;				
LET vsms_total=0;	
LET vsms_no_val=0;	
LET ivalidos=0;			
LET iinvalidos=0;
LET isin_validar=0;
LET mes_inicial =0;
LET mes_final =0;
--ALTA DE CLIENTES
LET vcod_param_alta_cte=0;
LET cnumcte='';
LET iBanco=0;
LET icoppel=0;
LET ibanco_coppel=0;
LET isolo_coppel=0;
LET isolo_banco=0;
LET ibca_basica=0;
LET ibca_avanzada=0;
LET csucursal='';
LET iprospectos=0;
LET dfecha_alta='';
LET iTitulares=0;
LET isinproductos=0;

--ASIGNACION DE VARIABLES ERROR
LET vCodRet = '000000';
LET cVarDataErr = 'EL REPORTE DE ESTADISTICAS, FUE GENERADO SATISFACTORIAMENTE';
--SET DEBUG FILE TO '/informix/rmarquez/sp_get_estadisticas_correos_telefonos.out';
--TRACE ON;
BEGIN
	--Manejo del error
	ON EXCEPTION SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
			LET vCodret=iSqlErr;			
			ROLLBACK;
			IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmp_alta_ctes_titulares') THEN
				DROP TABLE tmp_alta_ctes_titulares;
			END IF;	
			RETURN vCodret, iSamErr || ' ' ||cVarDataErr;
		END IF;
	END EXCEPTION;
			
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;	
	---SET pdqpriority 10;	
	--CONSULTA EL VALOR A LA TABLA SI_PARAM
		
	BEGIN WORK;		
	--TABLA TEMPORAL DE CLIENTES TITULARES		
	SELECT {+INDEX (bdinteg:"informix".si_cliente idx_si_clientex )} a.sucursal, a.numcte, b.fecha_alta
	FROM bdinteg:"informix".si_cliente a, bdinteg:"informix".si_cte_huella b 
	WHERE a.numcte=b.numcte AND b.secuencia=1 AND b.fecha_alta between fecha_inicial AND  fecha_final
	AND a.tipo_cliente='1'	
	INTO TEMP tmp_alta_ctes_titulares
	WITH NO LOG; 
	CREATE INDEX "informix".tmp_idx_alta_ctes_titulares ON tmp_alta_ctes_titulares (numcte, fecha_alta, sucursal);
		
--ESTADISTICAS DE ALTA DE CLIENTES		
		
	WHILE  (fecha_inicial <= fecha_final)			
 	
		LET ibanco_coppel = 0;
		LET isolo_coppel = 0;
		LET isolo_banco = 0;
		LET isinproductos = 0;	
		
		--GENERA TOTALES GLOBALES DE ALTA DE CLIENTES.
		SELECT NVL(COUNT(*),0)
		INTO iTitulares
		FROM tmp_alta_ctes_titulares
		WHERE fecha_alta = fecha_inicial;
		
		SELECT {+INDEX (bdinteg:"informix".si_cliente idx_si_clientex )} NVL(COUNT(*),0)
		INTO iProspectos
		FROM bdinteg:si_cliente
		WHERE tipo_cliente = '2'
		AND fecha_alta= fecha_inicial; 
						
		FOREACH --	AGREGAR LA SUCURSAL
			SELECT numcte, sucursal 
			INTO cnumcte, csucursal
			FROM tmp_alta_ctes_titulares
			WHERE fecha_alta= fecha_inicial
			
			LET iBanco = 0;
			LET iCoppel = 0;
			
			IF EXISTS(SELECT num_cte FROM bdicheq:"informix".sc_maechq WHERE num_cte=cnumcte AND sucursal=csucursal ) THEN
				LET iBanco=1;
			ELIF EXISTS(SELECT {+INDEX (bdisolic:"informix".ss_solicitudes idx_numctesolic)} numcte FROM bdisolic:"informix".ss_solicitudes WHERE numcte=cnumcte AND sucursal=csucursal AND tipo_solicitud<>'C') THEN
				LET iBanco=1;			
			ELIF EXISTS(SELECT {+INDEX (bdinvers:"informix".sv_maeinv mai3)} num_cte FROM bdinvers:"informix".sv_maeinv WHERE num_cte=cnumcte AND sucursal=csucursal ) THEN
				LET iBanco=1;
			END IF;			
			IF EXISTS(SELECT {+INDEX (bdisolic:"informix".ss_solicitudes idx_numctesolic)} numcte FROM bdisolic:"informix".ss_solicitudes WHERE numcte=cnumcte AND sucursal=csucursal AND tipo_solicitud='C') THEN
				LET iCoppel=1; 
			END IF;
			--CONTABILIZA LOS TOTALES DE CLIENTES POR PRODUCTO
			IF (iBanco = 0 AND iCoppel=0 ) THEN --EN CASO QUE NO TENGA CUENTA DE BANCO NI DE COPPEL
				LET isinproductos = isinproductos + 1;  
			END IF;	
			IF (iBanco = 1 AND iCoppel=1) THEN
				LET ibanco_coppel = ibanco_coppel + 1;  
			ELSE
				LET isolo_coppel = isolo_coppel + iCoppel; 
				LET isolo_banco = isolo_banco + iBanco; 
			END IF;			
		END FOREACH;
		
		--TOTAL DE CLIENTES TITULARES QUE SE LES DIO EL SERVICIO DE BANCA ELECTRONICA BASICA Y BANCA AVANZADA.	
		SELECT NVL(SUM(bca_basica),0) AS bca_basica, NVL(SUM(bca_avanzada),0) AS bca_avanzada
		INTO ibca_basica, ibca_avanzada
		FROM (TABLE(MULTISET(SELECT {+INDEX (bdinteg:"informix".si_bpiusuarios idx_bpi)} 
							CASE WHEN a.servicio= 1 THEN COUNT(a.numcte) END AS bca_basica,
							CASE WHEN a.servicio= 2 THEN COUNT(a.numcte) END AS bca_avanzada			
							FROM bdinteg:"informix".si_bpiusuarios a, tmp_alta_ctes_titulares b
							WHERE a.numcte=b.numcte
							AND a.suc_registro= b.sucursal 
							AND a.f_registro::DATE=fecha_inicial
							AND b.fecha_alta::DATE=fecha_inicial
							GROUP BY a.servicio)));  
							
		INSERT INTO bdinteg:"informix".si_alta_ctes_indicadores(fecha_proceso, titulares, prospectos, total, tot_prod_coppel, tot_prod_banco, tot_cop_bco, tot_sinproductos, tot_bca_basica, tot_bca_avanzada, user_insert, fecha_insert)
		VALUES (fecha_inicial, NVL(iTitulares,0), NVL(iProspectos,0), NVL(( iTitulares + iProspectos),0), NVL(isolo_coppel,0), NVL(isolo_banco,0) , NVL(ibanco_coppel,0), NVL(isinproductos,0), NVL(ibca_basica,0), NVL(ibca_avanzada,0), USER, CURRENT);
	
		--VALIDA SI NO INSERTO EN LA TABLA
		IF DBINFO ('sqlca.sqlerrd2') = 0 THEN
			INSERT INTO bdinteg:"informix".si_alta_ctes_indicadores(fecha_proceso, titulares, prospectos, total, tot_prod_coppel, tot_prod_banco, tot_cop_bco, tot_sinproductos, tot_bca_basica, tot_bca_avanzada, user_insert, fecha_insert)
			VALUES(fecha_inicial, 0, 0, 0,0,0,0,0, USER, CURRENT);
		END IF;						
	
	LET fecha_inicial= fecha_inicial + 1;	
	END WHILE; 		
	COMMIT WORK;
	
	IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmp_alta_ctes_titulares') THEN
		DROP TABLE tmp_alta_ctes_titulares;
	END IF;	
	RETURN vCodRet,cVarDataErr;		
END;
END PROCEDURE
DOCUMENT
'REALIZA:Estadísticas sobre alta de clientes',
'EQUIPO:Análisis y diseño de Mannto.4',
'FECHA:28/10/2014',
'VERSION:20141028',
'ELABORÓ: Rocio Karina Márquez Coronel',
'DESCRIPCION: Se creo sp para generar información faltante a la tabla de si_alta_ctes indicadores de la base de datos bdinteg.',
'Del 16 al 21 de Octubre de 2014';

CREATE PROCEDURE "informix".sp_buscar_movimientos_cheques_dia_corporativo(p_sNumeroCuenta CHAR(30), p_sFechaInicial DATE, p_sFechaFinal DATE, p_numeroCliente CHAR(20), p_skip INT, p_sTarjeta CHAR(30), p_sEmpresa CHAR(4))

    RETURNING	DATE AS fechaMovimiento, DATETIME HOUR to FRACTION(3) AS horaMovimiento , money(16,2) AS monto, 
                CHAR(30) AS folioSuc, CHAR(40) AS nombreSucursal, CHAR(40) AS tipo, CHAR(1) AS reversado, CHAR(10) AS id, 
                CHAR(20) AS cuenta, CHAR(1) AS naturaleza,CHAR(40) AS referencia ,CHAR(20) AS tarjeta;

	--definicion de variables--	    
	DEFINE resultado_fechaMovimiento 	DATE;
	DEFINE resultado_monto              money(16,2);
	DEFINE resultado_horaMovimiento		DATETIME HOUR to FRACTION(3);
	DEFINE resultado_folioSuc           CHAR(30);
	DEFINE resultado_nombreSucursal     CHAR(40);
    DEFINE resultado_tipo               CHAR(40);
   	DEFINE resultado_reversado          CHAR(1);
	DEFINE resultado_id             	CHAR(10);
   	DEFINE resultado_cuenta             CHAR(20);
    DEFINE resultado_naturaleza         CHAR(1);
    DEFINE resultado_referencia         CHAR(40);
    DEFINE resultado_tarjeta        	CHAR(20);
    
    DEFINE cuenta_temp              	CHAR(20);
	/*VJMP Cuenta Transfer*/
	DEFINE cuenta_temp_tf              	CHAR(20);
    
    DEFINE iSqlErr                  	INTEGER;
     
     -- InicializaciÃ?Â³n de las variables.
	LET resultado_fechaMovimiento = '';
	LET resultado_monto = '';
	LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
	LET resultado_folioSuc = '';
    	LET resultado_nombreSucursal = '';
	LET resultado_tipo = '';
    	LET resultado_reversado = '';
    	LET resultado_id = '';
    	LET resultado_cuenta = '';
    	LET resultado_naturaleza = '';
    	LET resultado_referencia = '';
    	LET resultado_tarjeta = '';

    	SET ISOLATION TO DIRTY READ;

	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_fechaMovimiento = '';
                    LET resultado_monto = '';
                    LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
                    LET resultado_folioSuc = '';
                    LET resultado_nombreSucursal = '';
                    LET resultado_tipo = '';
                    LET resultado_reversado = '';
                    LET resultado_id = '';
                    LET resultado_cuenta = '';
                    LET resultado_naturaleza = '';
                    LET resultado_referencia = '';
                    LET resultado_tarjeta = '';
                    RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, 
                            resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, 
                            resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta;
                END IF;
        END EXCEPTION;

            IF(p_sTarjeta IS NOT NULL AND p_sTarjeta <> '') THEN
				/*Movimientos TRANSFER Tarjeta VJMP Inicio*/
				Select mc.cuenta_tf
					INTO cuenta_temp_tf
					From bditransfer:tf_maecte mc
					Inner Join bdicheq:sc_tarjeta t ON ( t.cuenta = mc.cuenta_tf)
					where t.num_tarjeta = p_sTarjeta;
				IF cuenta_temp_tf IS NOT NULL AND cuenta_temp_tf <> '' THEN
					FOREACH       
						Select SKIP p_skip
							tat.fech_alt, tat.fech_hor_ini, tat.monto, tat.id_transacc_mps, (Select Trim(nombre) from bdinteg:si_sucursales where sucursal = '9747') as nombre,
							Trim(ct.descripcion) as Transaccion, 
							Case tat.id_reverso
								When '00000000000000000000' Then ''
								When Null Then ''
								When '' Then ''
								Else 'S'
							End As Reverso,
							tat.transacc, tat.cuenta, tat.naturaleza, tat.id_transacc_mps, ''
						INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta
						from bditransfer:tf_all_transaction tat
						LEFT JOIN bditransfer:tf_cat_transac_mps ct ON (ct.transac = tat.transacc)
						WHERE tat.cuenta = cuenta_temp_tf
							   AND tat.fech_alt >= p_sFechaInicial 
							   AND tat.fech_alt <= p_sFechaFinal 
							   ORDER BY tat.fech_alt asC, tat.fech_hor_ini asC
						RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta WITH RESUME;
					END FOREACH;
				Else
				/*Movimientos TRANSFER Tarjeta VJMP Fin*/
					select distinct numcuenta
						into cuenta_temp
						from intercard:tarjetacuenta 
						where numtarjeta = p_sTarjeta;

					FOREACH       
						SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, cuenta,bdinteg:si_transacc.naturaleza,referencia, num_tarjeta
						  INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta
						  FROM bdicheq:sc_movdia 
							LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
							LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movdia.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
						  WHERE fech_val <= p_sFechaFinal 
							AND fech_val >= p_sFechaInicial 
							AND num_tarjeta = p_sTarjeta
							AND bdicheq:sc_movdia.empresa = p_sEmpresa
							AND cuenta = cuenta_temp
						  ORDER BY folio_suc asC, fech_val asC
						  RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta WITH RESUME;
					END FOREACH;
				End If;
            ELSE
				/*Movimientos TRANSFER Cuenta VJMP Inicio*/
				Select cuenta_tf
					INTO cuenta_temp_tf
					from bditransfer:tf_maecte 
					where cuenta_tf = p_sNumeroCuenta;
				
				IF cuenta_temp_tf IS NOT NULL AND cuenta_temp_tf <> '' THEN
					FOREACH       
						Select SKIP p_skip
							tat.fech_alt, tat.fech_hor_ini, tat.monto, tat.id_transacc_mps, (Select Trim(nombre) from bdinteg:si_sucursales where sucursal = '9747') as nombre,
							Trim(ct.descripcion) as Transaccion, 
							Case tat.id_reverso
								When '00000000000000000000' Then ''
								When Null Then ''
								When '' Then ''
								Else 'S'
							End As Reverso,
							tat.transacc, tat.cuenta, tat.naturaleza, tat.id_transacc_mps, ''
						INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta
						from bditransfer:tf_all_transaction tat
						LEFT JOIN bditransfer:tf_cat_transac_mps ct ON (ct.transac = tat.transacc)
						WHERE tat.cuenta = cuenta_temp_tf
							   AND tat.fech_alt >= p_sFechaInicial 
							   AND tat.fech_alt <= p_sFechaFinal 
							   ORDER BY tat.fech_alt asC, tat.fech_hor_ini asC
						RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia, resultado_tarjeta WITH RESUME;
					END FOREACH;
				Else
				/*Movimientos TRANSFER Cuenta VJMP Fin*/
					IF (p_sNumeroCuenta IS NOT NULL AND p_sNumeroCuenta <> '') THEN
						FOREACH       
							SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, cuenta,bdinteg:si_transacc.naturaleza,referencia, num_tarjeta
							  INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza, resultado_referencia, resultado_tarjeta
							  FROM bdicheq:sc_movdia 
								LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
								LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movdia.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
							  WHERE fech_val <= p_sFechaFinal 
								AND fech_val >= p_sFechaInicial 
								AND cuenta = p_sNumeroCuenta
								AND bdicheq:sc_movdia.empresa = p_sEmpresa
							  ORDER BY folio_suc asC, fech_val asC
							  RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza, resultado_referencia, resultado_tarjeta WITH RESUME;
						END FOREACH;
					ELSE
						FOREACH       
							SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, bdicheq:sc_maechq.cuenta, bdinteg:si_transacc.naturaleza,referencia,num_tarjeta
							  INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza, resultado_referencia,resultado_tarjeta
							  FROM bdicheq:sc_movdia 
								LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movdia.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
								LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movdia.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
								LEFT JOIN bdicheq:sc_maechq ON (bdicheq:sc_movdia.cuenta = bdicheq:sc_maechq.cuenta AND bdicheq:sc_maechq.empresa = p_sEmpresa)
							  WHERE fech_val <= p_sFechaFinal 
								AND fech_val >= p_sFechaInicial 
								AND num_cte = p_numeroCliente
								AND bdicheq:sc_movdia.empresa = p_sEmpresa
							  ORDER BY folio_suc asC, fech_val asC
							  RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza, resultado_referencia, resultado_tarjeta WITH RESUME;
						END FOREACH;
					END IF;
				End If;
           END IF;
	END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscar_movimientos_cheques_his_corporativo(p_sNumeroCuenta CHAR(30), p_sFechaInicial DATE, p_sFechaFinal DATE, p_numeroCliente CHAR(20), p_skip INT, p_sTarjeta CHAR(30), p_sEmpresa CHAR(4))

     RETURNING	DATE AS fechaMovimiento, DATETIME HOUR to FRACTION(3) AS horaMovimiento , money(16,2) AS monto, 
                CHAR(30) AS folioSuc, CHAR(40) AS nombreSucursal, CHAR(40) AS tipo, CHAR(1) AS reversado, CHAR(10) AS id, 
                CHAR(20) AS cuenta, CHAR(1) AS naturaleza,CHAR(40) AS referencia, CHAR(20) AS tarjeta;

	--definicion de variables--	    
	DEFINE resultado_fechaMovimiento    DATE;
	DEFINE resultado_monto			money(16,2);
	DEFINE resultado_horaMovimiento		DATETIME HOUR to FRACTION(3);
	DEFINE resultado_folioSuc			CHAR(30);
	DEFINE resultado_nombreSucursal     CHAR(40);
	DEFINE resultado_tipo   			CHAR(40);
	DEFINE resultado_reversado          CHAR(1);
	DEFINE resultado_id                 CHAR(10);
	DEFINE resultado_cuenta             CHAR(20);
	DEFINE resultado_naturaleza         CHAR(1);
	DEFINE resultado_referencia         CHAR(40);
	DEFINE resultado_tarjeta            CHAR(20);
	DEFINE cuenta_temp                  CHAR(20);
	DEFINE iSqlErr                      INTEGER;
	
	/*VJMP Cuenta Transfer*/
	DEFINE cuenta_temp_tf              	CHAR(20);
     
     -- InicializaciÃ?Â³n de las variables.
	LET resultado_fechaMovimiento = '';
	LET resultado_monto = '';
	LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
	LET resultado_folioSuc = '';
    LET resultado_nombreSucursal = '';
	LET resultado_tipo = '';
    LET resultado_reversado = '';
    LET resultado_id = '';
    LET resultado_cuenta = '';    
    LET resultado_naturaleza = '';
    LET resultado_referencia = '';
    LET resultado_tarjeta = '';

    SET ISOLATION TO DIRTY READ;

	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_fechaMovimiento = '';
                    LET resultado_monto = '';
                    LET resultado_horaMovimiento = TO_DATE("00:00","%H:%M");
                    LET resultado_folioSuc = '';
                    LET resultado_nombreSucursal = '';
                    LET resultado_tipo = '';
                    LET resultado_reversado = '';
                    LET resultado_id = '';
                    LET resultado_cuenta = '';
                    LET resultado_naturaleza = '';
                    LET resultado_referencia = '';
                    LET resultado_tarjeta = '';
                    RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta;
                END IF;
        END EXCEPTION;

            IF(p_sTarjeta IS NOT NULL AND p_sTarjeta <> '') THEN
					
				/*Elimina Movimientos TRANSFER Tarjeta VJMP Inicio*/
				Select mc.cuenta_tf
					INTO cuenta_temp_tf
					From bditransfer:tf_maecte mc
					Inner Join bdicheq:sc_tarjeta t ON ( t.cuenta = mc.cuenta_tf)
					where t.num_tarjeta = p_sTarjeta;
				
				IF cuenta_temp_tf IS NULL Or cuenta_temp_tf = '' THEN
				/*Elimina Movimientos TRANSFER Tarjeta VJMP Fin*/
                    select distinct numcuenta
                    into cuenta_temp
                    from intercard:tarjetacuenta 
                    where numtarjeta = p_sTarjeta;

                    FOREACH       
                        SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, cuenta,bdinteg:si_transacc.naturaleza,referencia, num_tarjeta
                          INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza,resultado_referencia,resultado_tarjeta
                          FROM bdicheq:sc_movhis 
                            LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movhis.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
                            LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movhis.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
                          WHERE bdicheq:sc_movhis.empresa = p_sEmpresa
                            AND cuenta = cuenta_temp
                            AND fech_val <= p_sFechaFinal 
                            AND fech_val >= p_sFechaInicial 
                            AND num_tarjeta = p_sTarjeta
                          ORDER BY folio_suc asC, fech_val asC
                          RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta WITH RESUME;
                    END FOREACH;
				End If;
            ELSE
				/*Movimientos TRANSFER Cuenta VJMP Inicio*/
				Select cuenta_tf
					INTO cuenta_temp_tf
					from bditransfer:tf_maecte 
					where cuenta_tf = p_sNumeroCuenta;
				
				IF cuenta_temp_tf IS NULL Or cuenta_temp_tf = '' THEN
				/*Elimina Movimientos TRANSFER Cuenta VJMP Fin*/
				
					IF (p_sNumeroCuenta IS NOT NULL AND p_sNumeroCuenta <> '') THEN
						FOREACH       
							SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, cuenta,bdinteg:si_transacc.naturaleza,referencia, num_tarjeta
							  INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta
							  FROM bdicheq:sc_movhis
								LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movhis.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
								LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movhis.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
							  WHERE cuenta = p_sNumeroCuenta
								AND bdicheq:sc_movhis.empresa = p_sEmpresa
								AND fech_val >= p_sFechaInicial 
								AND fech_val <= p_sFechaFinal 
							  ORDER BY folio_suc asC, fech_val asC
							  RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta WITH RESUME;
						END FOREACH;
					ELSE
						FOREACH       
							SELECT SKIP p_skip DISTINCT fech_val, fech_hor, monto_tot, folio_suc, bdinteg:si_sucursales.nombre, bdinteg:si_transacc.descripcion, cancelad, transacc, bdicheq:sc_maechq.cuenta,bdinteg:si_transacc.naturaleza,referencia, num_tarjeta
							  INTO resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta,resultado_naturaleza,resultado_referencia, resultado_tarjeta
							  FROM bdicheq:sc_movhis 
								LEFT JOIN bdinteg:si_sucursales ON (bdinteg:si_sucursales.sucursal = bdicheq:sc_movhis.sucursal AND bdinteg:si_sucursales.empresa = p_sEmpresa) 
								LEFT JOIN bdinteg:si_transacc ON (bdinteg:si_transacc.numero = bdicheq:sc_movhis.transacc AND bdinteg:si_transacc.empresa = p_sEmpresa)
								LEFT JOIN bdicheq:sc_maechq ON (bdicheq:sc_movhis.cuenta = bdicheq:sc_maechq.cuenta AND bdicheq:sc_maechq.empresa = p_sEmpresa)
							  WHERE num_cte = p_numeroCliente
								AND bdicheq:sc_movhis.empresa = p_sEmpresa
								AND fech_val >= p_sFechaInicial 
								AND fech_val <= p_sFechaFinal 
							  ORDER BY folio_suc asC, fech_val asC
							  RETURN resultado_fechaMovimiento, resultado_horaMovimiento, resultado_monto, resultado_folioSuc, resultado_nombreSucursal, resultado_tipo, resultado_reversado, resultado_id, resultado_cuenta, resultado_naturaleza,resultado_referencia,resultado_tarjeta WITH RESUME;
						END FOREACH;
					END IF;
				End If;
           END IF;
	END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscar_tipo_producto(p_sNumeroCuenta CHAR(30), p_sTarjeta CHAR(30), p_sEmpresa CHAR(4))

     RETURNING	CHAR(3) AS tipoProducto;

	--definicion de variables--	    
	DEFINE resultado_tipoProducto   CHAR(3);
    	DEFINE cuenta_temp              CHAR(30);
    	DEFINE iSqlErr                  INTEGER;
     
     -- InicializaciÃ³n de las variables.
	LET resultado_tipoProducto = '';

    SET ISOLATION TO DIRTY READ;

	BEGIN

        /*ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_tipoProducto = '';
                    RETURN resultado_tipoProducto;
                END IF;
        END EXCEPTION;*/

		IF(p_sTarjeta IS NOT NULL AND p_sTarjeta <> '') THEN
			SELECT DISTINCT numcuenta
			INTO cuenta_temp
			FROM intercard:tarjetacuenta 
			WHERE numtarjeta = p_sTarjeta;

			SELECT DISTINCT cuenta
			INTO resultado_tipoProducto
			FROM bdicheq:sc_maechq
			WHERE empresa = p_sEmpresa
			AND cuenta = cuenta_temp;

			IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
				RETURN 'CHQ';
			ELSE
				SELECT DISTINCT num_credito
				INTO resultado_tipoProducto
				FROM bdicred:sd_maecred
				WHERE empresa = p_sEmpresa
				AND num_credito = cuenta_temp;
				
				IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
					RETURN 'CRE';
				ELSE
					Select mc.cuenta_tf--* 
					INTO cuenta_temp
					From bditransfer:tf_maecte mc
					Inner Join bdicheq:sc_tarjeta t ON ( t.cuenta = mc.cuenta_tf)
					where t.num_tarjeta = p_sTarjeta;
					
					Select cuenta_tf
					INTO resultado_tipoProducto
					from bditransfer:tf_maecte 
					where cuenta_tf = cuenta_temp;
					
					IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
						RETURN 'CHQ'; --TRANSFER
					ELSE
						RETURN 'INV';
					END IF;
				END IF;
			END IF;                    
		ELSE 
			SELECT DISTINCT cuenta
			INTO resultado_tipoProducto
			FROM bdicheq:sc_maechq
			WHERE empresa = p_sEmpresa
			AND cuenta = p_sNumeroCuenta;

			IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
				RETURN 'CHQ';
			ELSE
				SELECT DISTINCT num_credito
				INTO resultado_tipoProducto
				FROM bdicred:sd_maecred
				WHERE empresa = p_sEmpresa
				AND num_credito = p_sNumeroCuenta;
				
				IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
					RETURN 'CRE';
				ELSE
					Select cuenta_tf
					INTO resultado_tipoProducto
					from bditransfer:tf_maecte 
					where cuenta_tf = p_sNumeroCuenta;
					
					IF resultado_tipoProducto IS NOT NULL AND resultado_tipoProducto <> '' THEN
						RETURN 'CHQ';
					ELSE
						RETURN 'INV';
					END IF;
				END IF;
			END IF;  
	   END IF;
	END 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscarclientespornombre(
                        pEmpresa CHAR(3),
                        pNombre1 CHAR(30),
                        pNombre2 CHAR(30),
                        pPaterno CHAR(30),
                        pMaterno CHAR(30),
                        pFechaNac DATE,
                        pNo_Rfc CHAR(13),
                        pRazon CHAR(60),
                        pSecuencia SMALLINT)

RETURNING CHAR(20) as num_cliente, CHAR(30) as nombre1, CHAR(30) as nombre2, CHAR(30) as apaterno, CHAR(30) as amaterno;

-- ************************************************************************
-- Definición de variables
-- ************************************************************************

DEFINE sql_err 									  INTEGER;
DEFINE v_longitud,v_ciclo 					      SMALLINT;
DEFINE v_nombre_completo 						  CHAR(63);

--DEFINE v_nombre1, v_nombre2, v_paterno, v_materno CHAR(30);

DEFINE v_nombre1                                  CHAR(30);
DEFINE v_nombre2                                  CHAR(30);
DEFINE v_paterno                                  CHAR(30);
DEFINE v_materno                                  CHAR(30);

DEFINE v_numcte 								  CHAR(20);
DEFINE v_cod_ret 								  CHAR(5);
DEFINE v_razon_soc 								  CHAR(60);
DEFINE v_rfc 									  CHAR(13);

--set debug file to "ConsultarNombreNumCliente.out";
--trace on;

-- ************************************************************************
-- inicialización de variables
-- ************************************************************************

LET v_cod_ret = "00000";
LET v_ciclo = 0;
LET v_nombre_completo = "";

LET v_nombre1 = "";
LET v_nombre2 = "";
LET v_paterno = "";
LET v_materno = "";

LET v_numcte = "0000000000";
LET v_rfc = "";

BEGIN
  ON EXCEPTION SET sql_err
     IF sql_err <> 0 THEN
   	     LET v_cod_ret = sql_err;
	     RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno;
     END IF;
   END EXCEPTION;

IF NVL(pEmpresa,'') = ''  THEN
	LET v_cod_ret = "00001";
	LET v_nombre_completo = 'Parámetros incompletos';
	RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno;
END IF;

SET ISOLATION TO DIRTY READ;

IF pRazon IS NOT NULL AND pRazon !="" THEN
    FOREACH
        SELECT skip pSecuencia limit 21
             razon_social,numcte,rfc
 	    INTO v_razon_soc,v_numcte,v_rfc
        FROM si_cliente
        WHERE razon_social = prazon
           and apell_paterno = ''
	       and apell_materno = ''
        ORDER BY numcte
--        LET v_ciclo = v_ciclo+1;
--        IF v_ciclo <= psecuencia THEN
-- 	        CONTINUE FOREACH;
--        END IF;
        LET v_nombre_completo = v_razon_soc;
        RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno WITH RESUME;
    END FOREACH;
ELSE

    IF pNo_Rfc IS NOT NULL AND pNo_Rfc != "" THEN
        FOREACH
            SELECT skip pSecuencia limit 21 
                 nombre1,nombre2,apell_paterno,apell_materno,pf.numcte,rfc
	        INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
      	    FROM si_ctepf pf, si_cliente cl
      	    WHERE rfc = pno_rfc AND cl.numcte = pf.numcte
      	    ORDER BY pf.numcte
--      	    LET v_ciclo = v_ciclo+1;
--      	    IF v_ciclo <= psecuencia THEN
--                 CONTINUE FOREACH;
--      	    END IF;
	        LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
             || " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
	        RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno WITH RESUME;
        END FOREACH;
    ELSE

   ---VALIDA PARAMETROS

--	IF NVL(pPaterno,'') = '' AND NVL(pMaterno,'') = '' THEN
	IF NVL(pPaterno,'') = ''  THEN
		LET v_cod_ret = "00002";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos apellidos';
		RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno;
--	ELIF NVL(pNombre1,'') = '' AND NVL(pNombre2,'') = '' THEN
	ELIF NVL(pNombre1,'') = '' THEN
		LET v_cod_ret = "00003";
		LET v_nombre_completo = 'Debe capturar al menos uno de los dos nombres';
		RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno;
	ELSE
        if ( pPaterno is null or pPaterno = "" ) then
           let pPaterno = "";
        else
--           let pPaterno = trim(pPaterno)||"*";
           let pPaterno = trim(pPaterno);
        end if;  

        if ( pMaterno is null or pMaterno = "" ) then
           let pMaterno = "";
        else
--           let pMaterno = trim(pMaterno)||"*";
           let pMaterno = trim(pMaterno);
        end if;  

        if ( pNombre1 is null or pNombre1 = "" ) then
           let pNombre1 = "";
        else
           let pNombre1 = trim(pNombre1)||"*";
        end if;  

        if ( pNombre2 is null or pNombre2 = "" ) then
           let pNombre2 = "";
        else
           let pNombre2 = trim(pNombre2)||"*";
        end if;  

--		LET pPaterno = TRIM(pPaterno)||"*";
--		LET pMaterno = TRIM(pMaterno)||"*";
--		LET pNombre1 = TRIM(pNombre1)||"*";
--		LET pNombre2 = TRIM(pNombre2)||"*";

		IF NVL(pFechaNac,'') <> '' THEN
			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,cl.numcte,rfc
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
				FROM si_ctepf pf, si_cliente cl
				WHERE cl.apell_paterno = ppaterno
				AND cl.apell_materno = pmaterno
				AND cl.nombre1 matches pNombre1
				AND cl.nombre2 matches pNombre2
				AND pf.fecha_nac = pFechaNac
				AND cl.numcte = pf.numcte
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo + 1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(v_materno)
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno WITH RESUME;
			END FOREACH;

		ELSE

			FOREACH
				SELECT skip pSecuencia limit 21
                     nombre1,nombre2,apell_paterno,apell_materno,numcte,rfc
				INTO v_nombre1,v_nombre2,v_paterno,v_materno,v_numcte,v_rfc
				FROM si_cliente
				WHERE apell_paterno = ppaterno
				AND apell_materno = pmaterno
				AND nombre1 matches pNombre1
				AND nombre2 matches pNombre2
				ORDER BY apell_paterno, apell_materno, nombre1, nombre2

--				LET v_ciclo = v_ciclo+1;

--				IF v_ciclo <= psecuencia THEN
--					CONTINUE FOREACH;
--				END IF;

				LET v_nombre_completo = TRIM(v_paterno) || " " || TRIM(UPPER(v_materno))
						|| " " || TRIM(v_nombre1) || " " || TRIM(v_nombre2);
				RETURN v_numcte, v_nombre1, v_nombre2, v_paterno, v_materno WITH RESUME;
			END FOREACH;
		END IF;
        END IF;
    END IF;
END IF;

END;
END PROCEDURE


-- ************************************************************************
-- SP modificado, tomando como referencia el SP consnombrenumcte de la BD bdinteg
-- 23/03/2011
-- Sistema de aclaraciones
-- ************************************************************************
;

CREATE PROCEDURE "informix".sp_buscarclientespornumero (p_sNumeroCliente CHAR(30))

     RETURNING	CHAR(20) AS noCliente, CHAR(30) AS primerApellido, CHAR(30) AS segundoApellido, CHAR(30) AS primerNombre, CHAR(30) AS segundoNombre;

	--definicion de variables--	    
	DEFINE resultado_numeroCliente 		CHAR(20);
	DEFINE resultado_primerApellido		CHAR(30);
	DEFINE resultado_segundoApellido	CHAR(30);
    DEFINE resultado_primerNombre		CHAR(30);
    DEFINE resultado_segundoNombre		CHAR(30);
    DEFINE resultado_numerotransfer     CHAR(30);
  
    DEFINE iSqlErr                      INTEGER;
	
     	-- InicializaciÃ³n de las variables.
	LET resultado_numeroCliente = '';
	LET resultado_primerApellido = '';
	LET resultado_segundoApellido = '';
	LET resultado_primerNombre = '';
	LET resultado_segundoNombre = '';
  

    SET ISOLATION TO DIRTY READ;
			
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_numeroCliente = '';
                    LET resultado_primerApellido = '';
                    LET resultado_segundoApellido = '';
                    LET resultado_primerNombre = '';
                    LET resultado_segundoNombre = '';
                   
                    RETURN resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido;
                END IF;
        END EXCEPTION;

	SELECT numcte, nombre1, nombre2, apell_paterno, apell_materno
		INTO resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido
		FROM bdinteg:si_cliente
		WHERE p_sNumeroCliente = numcte;
    

   IF ( resultado_primerNombre IS NULL) THEN 
    
      SELECT bditransfer:tf_maecte.numcte 
      INTO resultado_numerotransfer
         FROM bditransfer:tf_maecte
        WHERE bditransfer:tf_maecte.numcte_tf = p_sNumeroCliente;
      
     SELECT numcte, nombre1, nombre2, apell_paterno, apell_materno
		INTO resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido
		FROM bdinteg:si_cliente
		WHERE resultado_numerotransfer = numcte;
     

    END IF;
      
    

   RETURN resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido;

		

	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscarclientesportelefonotransfer (p_sNumeroTelefonoTransfer CHAR(30))

     RETURNING	CHAR(20) AS noCliente, CHAR(30) AS primerApellido, CHAR(30) AS segundoApellido, CHAR(30) AS primerNombre, CHAR(30) AS segundoNombre;

	--definicion de variables--	    
	DEFINE resultado_numeroCliente 		CHAR(20);
	DEFINE resultado_primerApellido		CHAR(30);
	DEFINE resultado_segundoApellido	CHAR(30);
	DEFINE resultado_primerNombre		CHAR(30);
	DEFINE resultado_segundoNombre		CHAR(30);
	DEFINE telefono_Transfer		CHAR(30);
	DEFINE iSqlErr                     	INTEGER;
	
    -- Inicialización de las variables.
	LET resultado_numeroCliente = '';
	LET resultado_primerApellido = '';
	LET resultado_segundoApellido = '';
	LET resultado_primerNombre = '';
	LET resultado_segundoNombre = '';
	LET telefono_Transfer = '';
	
    SET ISOLATION TO DIRTY READ;
		
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_numeroCliente = '';
                    LET resultado_primerApellido = '';
                    LET resultado_segundoApellido = '';
                    LET resultado_primerNombre = '';
                    LET resultado_segundoNombre = '';
                    RETURN resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido;
                END IF;
        END EXCEPTION;
        
            SELECT numcte
            INTO resultado_numeroCliente
            FROM bditransfer:tf_maecte
            WHERE empresa = '001'
              AND telefono = p_sNumeroTelefonoTransfer;
           
	     
	
		IF ( resultado_numeroCliente IS NULL ) THEN
           let resultado_numeroCliente = '';
        ELSE
            SELECT si_cliente.numcte, nombre1, nombre2, apell_paterno, apell_materno
              INTO resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido
              FROM bdinteg:si_cliente
             WHERE numcte = resultado_numeroCliente;
{
            IF ( resultado_numeroCliente IS NULL ) THEN
               
				LET resultado_numeroCliente = '';
				LET resultado_primerApellido = '';
				LET resultado_segundoApellido = '';
				LET resultado_primerNombre = '';
				LET resultado_segundoNombre = '';
				
            END IF;
}
        END IF;

        RETURN resultado_numeroCliente, resultado_primerNombre, resultado_segundoNombre, resultado_primerApellido, resultado_segundoApellido;

	END
END PROCEDURE;

