	LET resultado_metodoacceso      = '';
	LET resultado_tpoacceso         = '';
	LET resultado_idtransac         = '';
	LET resultado_idreceptor        = '';
	LET resultado_integridad         = '';
	



	

    SET ISOLATION TO DIRTY READ;
			
	BEGIN

        ON EXCEPTION
            SET iSqlErr
            IF iSqlErr <> 0 THEN
             
	
	LET resultado_fechaTransac	    = '';
	LET resultado_horaIniTransac	 =   TO_DATE("00:00","%H:%M");
	LET resultado_horaFinTransac	 =  TO_DATE("00:00","%H:%M");
	LET resultado_secuencia	         = '';
    LET resultado_bancoOrigen	     = '';
   	LET resultado_numeroOrigen	     = '';
	LET resultado_bancoDestino	     = '';
	LET resultado_numeroIdDestino    = '';
	LET resultado_estatusTransac     = '';
	LET resultado_saldoOrigen        = '';
	LET resultado_saldoDestino       = '';
	LET resultado_motivo		     = '';
	LET resultado_referencia    	 = '';
	LET resultado_comision	         = '';
	LET resultado_iva    	         = '';
	LET resultado_idReverso          = '';
	LET resultado_tipoTransac        = '';
	LET resultado_transacMps         = '';
	LET resultado_iddevolucion       = '';
    LET resultado_consecutivo        = '';
	LET resultado_transacc           = '';
	LET resultado_tpoidorigen      = '';
	LET resultado_monto              = '';
	LET resultado_tpoiddestino     = '';
	LET resultado_metodoacceso      = '';
	LET resultado_tpoacceso         = '';
	LET resultado_idtransac         = '';
	LET resultado_idreceptor        = '';
	LET resultado_integridad         = '';
       
 RETURN  resultado_fechaTransac, resultado_horaIniTransac, resultado_horaFinTransac, resultado_secuencia, resultado_bancoOrigen,  resultado_numeroOrigen, resultado_bancoDestino,   resultado_numeroIdDestino, resultado_estatusTransac, resultado_saldoOrigen, resultado_saldoDestino, resultado_motivo, resultado_referencia, resultado_comision, resultado_iva,  resultado_idReverso, resultado_tipoTransac,  resultado_transacMps, resultado_iddevolucion, resultado_consecutivo, resultado_transacc, resultado_tpoidorigen, resultado_monto, resultado_tpoiddestino, resultado_metodoacceso, resultado_tpoacceso, resultado_idtransac, resultado_idreceptor, resultado_integridad;
            
    END IF;
        END EXCEPTION;




	
	       SELECT   bditransfer:tf_all_transaction.fech_alt, bditransfer:tf_all_transaction.fech_hor_ini, bditransfer:tf_all_transaction.fech_hor_fin, bditransfer:tf_all_transaction.secuencia, bdinteg:si_bancos.descripcion, bditransfer:tf_all_transaction.id_cuenta_origen,
					bditransfer:tf_all_transaction.id_banco_destino, bditransfer:tf_all_transaction.id_cuenta_destino, bditransfer:tf_all_transaction.estatus_transac, bditransfer:tf_all_transaction.sdo_cuenta_origen,  
						bditransfer:tf_all_transaction.sdo_cuenta_destino, bditransfer:tf_all_transaction.motivo, bditransfer:tf_all_transaction.referencia, bditransfer:tf_all_transaction.comision, bditransfer:tf_all_transaction.iva, bditransfer:tf_all_transaction.id_reverso, bditransfer:tf_all_transaction.naturaleza, bditransfer:tf_all_transaction.id_transacc_mps,  bditransfer:tf_all_transaction.id_devolucion, bditransfer:tf_all_transaction.consecutivo, bditransfer:tf_all_transaction.transacc, bditransfer:tf_all_transaction.tpo_id_origen,
                         bditransfer:tf_all_transaction.monto, bditransfer:tf_all_transaction.tpo_id_destino, bditransfer:tf_all_transaction.metodo_acceso, bditransfer:tf_all_transaction.tpo_acceso,bditransfer:tf_all_transaction.id_transac,
                         bditransfer:tf_all_transaction.id_receptor, bditransfer:tf_all_transaction.integridad 

				INTO  resultado_fechaTransac, resultado_horaIniTransac, resultado_horaFinTransac, resultado_secuencia, resultado_bancoOrigen,  resultado_numeroOrigen, resultado_bancoDestino,  resultado_numeroIdDestino,  resultado_estatusTransac, resultado_saldoOrigen, resultado_saldoDestino, resultado_motivo, resultado_referencia, resultado_comision, resultado_iva,  resultado_idReverso, resultado_tipoTransac,  resultado_transacMps, resultado_iddevolucion, resultado_consecutivo, resultado_transacc, resultado_tpoidorigen, resultado_monto, resultado_tpoiddestino, resultado_metodoacceso, resultado_tpoacceso, resultado_idtransac, resultado_idreceptor, resultado_integridad

			FROM bditransfer:tf_all_transaction, bdinteg:si_bancos
              WHERE bditransfer:tf_all_transaction.id_transacc_mps = p_sFolioSuc
                AND bditransfer:tf_all_transaction.cuenta = p_sNumeroCuentatransfer
                AND bditransfer:tf_all_transaction.id_banco_origen=bdinteg:si_bancos.banco;
			
 IF ( resultado_fechaTransac IS NULL ) THEN

	
	LET resultado_fechaTransac	     = '';
	LET resultado_horaIniTransac	   = TO_DATE("00:00","%H:%M");
	LET resultado_horaFinTransac	   = TO_DATE("00:00","%H:%M");
	LET resultado_secuencia	         = '';
    LET resultado_bancoOrigen	     = '';
   	LET resultado_numeroOrigen	     = '';
	LET resultado_bancoDestino	     = '';
	LET resultado_numeroIdDestino    = '';
	LET resultado_estatusTransac     = '';
	LET resultado_saldoOrigen        = '';
	LET resultado_saldoDestino       = '';
	LET resultado_motivo		     = '';
	LET resultado_referencia    	 = '';
	LET resultado_comision	         = '';
	LET resultado_iva    	         = '';
	LET resultado_idReverso          = '';
	LET resultado_tipoTransac        = '';
	LET resultado_transacMps         = '';
	LET resultado_iddevolucion       = '';
	LET resultado_consecutivo        = '';
	LET resultado_transacc           = '';
	LET resultado_tpoidorigen      = '';
	LET resultado_monto              = '';
	LET resultado_tpoiddestino     = '';
	LET resultado_metodoacceso      = '';
	LET resultado_tpoacceso         = '';
	LET resultado_idtransac         = '';
	LET resultado_idreceptor        = '';
	LET resultado_integridad         = '';

	END IF;



RETURN  resultado_fechaTransac, resultado_horaIniTransac, resultado_horaFinTransac, resultado_secuencia, resultado_bancoOrigen,  resultado_numeroOrigen, resultado_bancoDestino,  resultado_numeroIdDestino,  resultado_estatusTransac, resultado_saldoOrigen, resultado_saldoDestino, resultado_motivo, resultado_referencia, resultado_comision, resultado_iva, resultado_idReverso, resultado_tipoTransac,  resultado_transacMps,  resultado_iddevolucion, resultado_consecutivo, resultado_transacc, resultado_tpoidorigen, resultado_monto, resultado_tpoiddestino, resultado_metodoacceso, resultado_tpoacceso, resultado_idtransac, resultado_idreceptor, resultado_integridad;
		
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cargaarchivodomcancel_club()
--DATOS A REGRESAR--
RETURNING CHAR(6) AS CodigoRetorno;

--DEFINICION DE VARIABLES--
DEFINE cCodret CHAR(6);
DEFINE cCodRetorno CHAR(6);
DEFINE vMensajeRet VARCHAR(80);
DEFINE iSqlErr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE vErrorInfo VARCHAR(80);
DEFINE vProceso VARCHAR(30);
DEFINE cBanArchivoCifras CHAR(1);
DEFINE cBanArchivoDetalle CHAR(1);
DEFINE cFolio CHAR(16);
DEFINE dFechaHoy DATE;
DEFINE cNombreArchivoCifras CHAR(50);
DEFINE cNombreArchivoDetalle CHAR(50);
DEFINE cFechaArchivo CHAR(8);
DEFINE cRuta CHAR(100);
DEFINE cSql CHAR(1024);
DEFINE vLinea VARCHAR(50);
DEFINE iCantMovDom INTEGER;
DEFINE iCantMovCifras INTEGER;
DEFINE iTotalDomiciliacion INT8;
DEFINE iTotalDomiciliacionCifras INT8;
DEFINE cNumCte CHAR(20);
DEFINE cTipoCliente CHAR(1);
DEFINE cIdDomiciliacion CHAR(20);
DEFINE cFechaPaquete CHAR(10);
DEFINE cProcesado CHAR(1);
DEFINE dtFechaHora DATETIME YEAR TO SECOND;

--INICIALIZACION DE VARIABLES--
LET cCodret = '000';
LET cCodRetorno = '000';
LET vMensajeRet = '';
LET iSqlErr = 0;
LET iIsamErr = 0;
LET vErrorInfo = '';
LET vProceso = 'sp_cargaarchivodomcancel_club';
LET cBanArchivoCifras = 'F';
LET cBanArchivoDetalle = 'F';
LET cFolio = '';
LET dFechaHoy = '';
LET cNombreArchivoCifras = '';
LET cNombreArchivoDetalle = '';
LET cFechaArchivo = '';
LET cRuta = '';
LET cSql = '';
LET vLinea = '';
LET iCantMovDom = 0;
LET iCantMovCifras = 0;
LET iTotalDomiciliacion = 0;
LET iTotalDomiciliacionCifras = 0;
LET cNumCte = '';
LET cTipoCliente = '';
LET cIdDomiciliacion = '';
LET cFechaPaquete = '';
LET cProcesado = '';
LET dtFechaHora = '';

--SET DEBUG FILE TO "/informix/IrisA/sp_cargaarchivodomcancel_club.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
		IF iSqlErr <> 0 OR iIsamErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET vMensajeRet = vErrorInfo;
			INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
				VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
			RETURN cCodret;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 5;

	SELECT fecha_hoy INTO dFechaHoy 
	FROM "informix".si_fechas WHERE empresa = '001';

	IF TRIM(NVL(dFechaHoy,'')) <> '' THEN

		SELECT valor INTO cRuta 
		FROM "informix".si_param 
		WHERE empresa = '001' AND cod_param = 319;

		IF TRIM(NVL(cRuta,'')) <> '' THEN

			LET cFechaArchivo = YEAR(dFechaHoy) || LPAD(MONTH(dFechaHoy),2,'0') || LPAD(DAY(dFechaHoy),2,'0');
			LET cNombreArchivoCifras = 'cifradomiciliacionescanceladas' || TRIM(cFechaArchivo) || '.txt';
			LET cNombreArchivoDetalle = 'domiciliacionescanceladas' || TRIM(cFechaArchivo) || '.txt';

			TRUNCATE TABLE "informix".si_club_domiciliacioncancelada;
			TRUNCATE TABLE "informix".si_club_cifradomiciliacioncancelada;
			
			--- BORRAR LA TABLA DE TEMPORAL DE TRABAJO EN CASO DE QUE EXISTA
			IF EXISTS(SELECT tabname FROM systables WHERE tabname = 'tmp_club_buscaarchivodomcancel') THEN
				DROP TABLE tmp_club_buscaarchivodomcancel;
			END IF

			--- CREAR LA TABLA DE TRABAJO
			CREATE TABLE tmp_club_buscaarchivodomcancel(linea VARCHAR(50));

			--- CORRER EL COMANDO LS PARA OBTENER LOS NOMBRES QUE EXISTEN EN LAS CARPETAS Y METERLOS EN EL ARCHIVO club_buscaarchivodomcancel.unl
			LET cSql = 'ls ' || TRIM(cRuta) || ' > club_buscaarchivodomcancel.unl';
			SYSTEM cSql;

			--- GUARDA EL QUERY DEL LOAD EN EL ARCHIVO *.SQL
			LET cSql = 'echo "LOAD FROM club_buscaarchivodomcancel.unl INSERT INTO tmp_club_buscaarchivodomcancel" > tmp_club_buscaarchivodomcancel.sql';
			SYSTEM cSql;

			--- EJECUTA LAS INSTRUCCIONES QUE ESTAN DENTRO DEL ARCHIVO *.SQL
			LET cSql = 'dbaccess bdinteg tmp_club_buscaarchivodomcancel.sql';
			SYSTEM cSql;

			LET cSql = '';
				LET cSql = "rm club_buscaarchivodomcancel.unl";
			SYSTEM cSql;

			LET cSql = '';
				LET cSql = "rm tmp_club_buscaarchivodomcancel.sql";
			SYSTEM cSql;

			--- CICLO PARA BARRER LA TABLA DE TRABAJO Y BUSCAR EL NOMBRE DEL ARCHIVO
			FOREACH
				SELECT linea INTO vLinea FROM tmp_club_buscaarchivodomcancel

				IF vLinea = cNombreArchivoCifras THEN
					LET cBanArchivoCifras = 'V';
				END IF;

				IF vLinea = cNombreArchivoDetalle THEN
					LET cBanArchivoDetalle = 'V';
				END IF;

				IF NVL(cBanArchivoCifras,'') = 'V' AND NVL(cBanArchivoDetalle,'') = 'V' THEN
					EXIT FOREACH;
				END IF;
			END FOREACH;

			DROP TABLE tmp_club_buscaarchivodomcancel;

			IF NVL(cBanArchivoCifras,'') = 'V' AND NVL(cBanArchivoDetalle,'') = 'V' THEN
				LET cSql = '';
				LET cSql =  'echo "LOAD FROM ' || TRIM(cRuta) || 'domiciliacionescanceladas' || TRIM(cFechaArchivo) || '.txt' ||
							' INSERT INTO si_club_domiciliacioncancelada(num_cliente, flag_tipocliente, idu_domiciliacion, fec_paquete);' ||
							' " > domiciliacionescanceladas.sql';
				SYSTEM cSql;

				LET cSql = '';
				LET cSql = 'dbaccess bdinteg domiciliacionescanceladas.sql';
				SYSTEM cSql;

				LET cSql = '';
				LET cSql = "rm domiciliacionescanceladas.sql";
				SYSTEM cSql;

				LET cSql = '';
				LET cSql =  'echo "LOAD FROM ' || TRIM(cRuta) || 'cifradomiciliacionescanceladas' || TRIM(cFechaArchivo) || '.txt' || 
							' INSERT INTO si_club_cifradomiciliacioncancelada(cant_movimientos, total_domiciliacion, fec_paquete);' ||
							' " > cifradomiciliacionescanceladas.sql';
				SYSTEM cSql;

				LET cSql = '';
				LET cSql = 'dbaccess bdinteg cifradomiciliacionescanceladas.sql';
				SYSTEM cSql;

				LET cSql = '';
				LET cSql = "rm cifradomiciliacionescanceladas.sql";
				SYSTEM cSql;

				UPDATE statistics medium FOR TABLE "informix".si_club_domiciliacioncancelada;
				UPDATE statistics medium FOR TABLE "informix".si_club_cifradomiciliacioncancelada;

				SELECT COUNT(num_cliente) INTO iCantMovDom
				FROM "informix".si_club_domiciliacioncancelada;

				SELECT cant_movimientos INTO iCantMovCifras
				FROM "informix".si_club_cifradomiciliacioncancelada;

				IF NVL(iCantMovDom,0) =  NVL(iCantMovCifras,0) THEN

					FOREACH
						SELECT num_cliente INTO cNumCte 
						FROM "informix".si_club_domiciliacioncancelada

						IF EXISTS(SELECT 1 FROM "informix".si_club_proteccion WHERE numcte_coppel = TRIM(cNumCte)) THEN

							UPDATE "informix".si_club_proteccion SET tipo_pago = '0', num_tarjeta = '', num_cta = '' WHERE numcte_coppel = cNumCte;

							UPDATE "informix".si_club_domiciliacioncancelada SET procesado = '1', fecha_hora = CURRENT YEAR TO SECOND WHERE num_cliente = cNumCte;

						ELSE
							LET cCodRetorno = '001';
							LET vMensajeRet = 'No Existe el Cliente';
							INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
								VALUES(vProceso, cCodRetorno, vMensajeRet, dFechaHoy);
						END IF;
					END FOREACH;

				ELSE
					LET cCodret = '003';
					LET vMensajeRet = 'Las Cantidades de Movimientos son Diferentes';
				END IF;

				IF cCodret = '000' THEN

					FOREACH
						SELECT num_cliente, flag_tipocliente, idu_domiciliacion, fec_paquete, procesado, fecha_hora
						INTO cNumCte, cTipoCliente, cIdDomiciliacion, cFechaPaquete, cProcesado, dtFechaHora
						FROM "informix".si_club_domiciliacioncancelada

						INSERT INTO "informix".si_club_domiciliacioncancelada_hist(num_cliente, flag_tipocliente, idu_domiciliacion, fec_paquete, procesado, fecha_hora)
							VALUES(cNumCte, cTipoCliente, cIdDomiciliacion, cFechaPaquete, cProcesado, dtFechaHora);
					END FOREACH;

					SELECT cant_movimientos, total_domiciliacion, fec_paquete
					INTO iCantMovCifras, iTotalDomiciliacionCifras, cFechaPaquete
					FROM "informix".si_club_cifradomiciliacioncancelada;

					INSERT INTO "informix".si_club_cifradomiciliacioncancelada_hist(cant_movimientos, total_domiciliacion, fec_paquete)
						VALUES(iCantMovCifras, iTotalDomiciliacionCifras, cFechaPaquete);
				END IF;
			ELSE
				LET cCodret = '005';
				LET vMensajeRet = 'No existe el Archivo en la Ruta';
			END IF;
		ELSE
			LET cCodret = '002';
			LET vMensajeRet = 'No Existe Ruta';
		END IF;
	ELSE
		LET cCodret = '001';
		LET vMensajeRet = 'No Existe Fecha';
	END IF;

	IF cCodret <> '000' THEN
		INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
			VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
	END IF;

	IF cCodret = '005' THEN
		LET cCodret = '000';
	END IF;

	RETURN cCodret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_spei_consnumcte(pEmpresa CHAR(3),pNumCte CHAR(9),pNumCta CHAR(12),pNumTarjeta CHAR(16),pTipoBusqueda CHAR(1))

--RETORNO--
RETURNING	CHAR(6),	-- Codigo de Retorno
			CHAR(9),	-- Numero de Cliente
			CHAR(107),	-- Nombre del Cliente
			CHAR(10),	-- Fecha de Nac.
			CHAR(13);	-- RFC.

--DEFINICION DE VARIABLES
DEFINE	iSqlErr 		INTEGER;
DEFINE	cCodRet 		CHAR(6);
DEFINE	cNombreCompleto	CHAR(107);
DEFINE	cFechaNac		CHAR(107);
DEFINE	cBin			CHAR(6);
DEFINE	cTipoTarj		CHAR(1);
DEFINE	cStatusTarj		CHAR(1);
DEFINE	cNombre1		CHAR(26);
DEFINE	cNombre2		CHAR(26);
DEFINE	cApellPat		CHAR(26);
DEFINE	cApellMat		CHAR(26);
DEFINE	cRfc			CHAR(13);

--INICIALIZACION DE VARIABLES
LET iSqlErr 		= 0;
LET cCodRet 		= '000000';
LET	cNombreCompleto	= "";
LET	cFechaNac		= "";
LET	cBin			= "";
LET	cTipoTarj		= "";
LET	cStatusTarj		= "";
LET	cNombre1		= "";
LET	cNombre2		= "";
LET	cApellPat		= "";
LET	cApellMat		= "";
LET	cRfc			= "";

	--SET DEBUG FILE TO '/respaldosdb/Benitez/sp_spei_consnumcte.out';
	--TRACE ON;

BEGIN

	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
           RETURN cCodRet, NVL(pNumCte,''), TRIM(cNombreCompleto), cFechaNac, cRfc;
		END IF
	END EXCEPTION;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
			
	IF (NVL(pEmpresa,'') <> '' AND NVL(pNumCte,'')<> '') OR (NVL(pNumTarjeta,'') <> '' AND NVL(pTipoBusqueda,'')<> '')  OR (NVL(pNumCta,'') <> '' AND NVL(pTipoBusqueda,'')<> '') THEN

		LET pTipoBusqueda =  UPPER(pTipoBusqueda);
		IF NVL(pTipoBusqueda,'') <> "C" AND NVL(pTipoBusqueda,'') <> "D" THEN
			LET cCodRet = '000006';
		ELSE	
			IF NVL(pNumTarjeta,'') <> '' THEN
				LET cBin = SUBSTR(pNumTarjeta,1,6);
				SELECT bin INTO cBin FROM intercard:"informix".bines
				WHERE bin = cBin AND creditodebito = pTipoBusqueda;

				IF DBINFO("sqlca.sqlerrd2") = 0 THEN
					IF NVL(pTipoBusqueda,'') = "C" THEN
						LET cCodRet = '000202';
					ELIF NVL(pTipoBusqueda,'') = "D" THEN
						LET cCodRet = '000245';
					END IF
				ELSE
					IF NVL(pTipoBusqueda,'') = "C" THEN
						SELECT numcte,tipo_tarjeta,status_tar INTO pNumCte,cTipoTarj,cStatusTarj
						FROM bdicred:"informix".sd_tarjeta WHERE num_tarjeta = pNumTarjeta;

						IF DBINFO("sqlca.sqlerrd2") = 0 THEN
							LET cCodRet = '000003';
						ELSE
							IF NVL(cStatusTarj,'') <> "A" THEN
								LET cCodRet = '000398';
							END IF
						END IF
					ELIF NVL(pTipoBusqueda,'') = "D" THEN
						SELECT numcte,tipo_tarjeta,status_tar INTO pNumCte,cTipoTarj,cStatusTarj
						FROM bdicheq:"informix".sc_tarjeta WHERE num_tarjeta = pNumTarjeta;

						IF DBINFO("sqlca.sqlerrd2") = 0 THEN
							LET cCodRet = '000003';
						ELSE
							IF NVL(cStatusTarj,'') <> "A" THEN
								LET cCodRet = '000005';
							END IF
						END IF
					END IF
					IF NVL(cTipoTarj,'') <> "T" AND NVL(cTipoTarj,'') <> '' THEN
						LET cCodRet = '000186';
					END IF
				END IF
			ELIF NVL(pNumCta,'') <> '' THEN

				IF NVL(pTipoBusqueda,'') = "C" THEN
					SELECT numcte INTO pNumCte
					FROM bdicred:"informix".sd_maecred
					WHERE num_credito = pNumCta;

					IF DBINFO("sqlca.sqlerrd2") = 0 THEN
						LET cCodRet = '000002';
					END IF

				ELIF NVL(pTipoBusqueda,'') = "D" THEN
					SELECT num_cte INTO pNumCte
					FROM bdicheq:"informix".sc_maechq
					WHERE cuenta = pNumCta;

					IF DBINFO("sqlca.sqlerrd2") = 0 THEN
						LET cCodRet = '000002';
					END IF
				END IF
			END IF
		END IF

		IF NVL(pNumCte,'') <> '' THEN
			SELECT nombre1, nombre2, apell_paterno, apell_materno, rfc
			INTO cNombre1, cNombre2, cApellPat, cApellMat, cRfc
			FROM bdinteg:"informix".si_cliente
			WHERE numcte = pNumCte;

			LET cNombreCompleto = TRIM(cNombre1) || " " || TRIM(cNombre2) || " " || TRIM(cApellPat) ||" " || TRIM(cApellMat);

			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '000004';
			ELSE
				SELECT LIMIT 1 fecha_nac
				INTO cFechaNac
				FROM bdinteg:"informix".si_ctepf
				WHERE numcte = pNumCte;

				IF  DBINFO("sqlca.sqlerrd2") = 0 THEN
					LET cCodRet = '000004';
				END IF
			END IF
		END IF
	ELSE
		LET cCodRet = '000001';
	END IF

RETURN cCodRet, NVL(pNumCte,''), TRIM(cNombreCompleto), cFechaNac, cRfc;
END
END PROCEDURE
DOCUMENT
'DESCRIPCION: Obtiene nombre completo y fecha de nacimiento, buscando por NumCte,Cuenta o Tarjeta',
'REALIZO: Francisco Eduardo Benitez Baez',
'FOLIO: 1463',
'FECHA: 30/10/2014',
'BD: BDINTEG';

CREATE PROCEDURE "informix".sp_validarfc_paternos()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(15);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='333';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='333';

        set isolation to dirty read;
        FOREACH  
				

				SELECT a.numcte, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
					INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
				FROM bdinteg:si_cliente a inner join bdinteg:si_ctepf b on a.numcte=b.numcte
				WHERE a.numcte>=vNumCteIni
				and a.tpo_persona='01' and length(a.apell_paterno)<=2
				ORDER BY a.numcte
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    INSERT INTO bdinteg:resultadosrfc_paternos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                            VALUES(cNumcte, cRFCOrig, '', 'NO CALC', '', '', '', '1');
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc_paternos WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_paternos WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_paternos WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc_paternos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                ELSE
                        INSERT INTO bdinteg:resultadosrfc_paternos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');

                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizarfc_paternos()
RETURNING CHAR(5) as codret, CHAR(5) as codret2, CHAR(5) as mensaje;

DEFINE vcodret1         char(5); 
DEFINE vcodret2         char(5);
DEFINE vcodret3         char(50);
DEFINE sql_err          integer;
DEFINE isam_err         integer;
DEFINE desc_err         char(50);
DEFINE vnumcte          char(10);
DEFINE vrfc_calculado   char(13);
DEFINE vcomienza        smallint;
DEFINE ven_transacc     smallint;
DEFINE vcontador1       integer;

LET vcodret1            ='00000';
LET vcodret2            ='0000';
LET vcodret3            ='PROCESO CONCLUIDO SATISFACTORIAMENTE';
LET sql_err             =0;
LET isam_err            =0;
LET desc_err            ='';
LET vcomienza           =-1;
LET ven_transacc        = 0;  
LET vnumcte             ='';
LET vrfc_calculado      ='';
LET vcontador1          =0;



BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/arch_sp_actualizarfc.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;

            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH WITH HOLD
        select  numcte, rfc_calculado INTO vnumcte,  vrfc_calculado from bdinteg:resultadosrfc_paternos where rfc_duplicado=0
    
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        UPDATE "informix".si_cliente set rfc=vrfc_calculado where numcte=vnumcte;

        LET vcontador1 = vcontador1 + 1;
        

        IF (vcontador1 >= 5000) THEN
            LET vcontador1 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
     END FOREACH;

     IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
     END IF;

END;
RETURN vcodret1, vcodret2, vcodret3; 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_actualizarfc_prospectos()
RETURNING CHAR(5) as codret, CHAR(5) as codret2, CHAR(5) as mensaje;

DEFINE vcodret1         char(5); 
DEFINE vcodret2         char(5);
DEFINE vcodret3         char(50);
DEFINE sql_err          integer;
DEFINE isam_err         integer;
DEFINE desc_err         char(50);
DEFINE vnumcte          char(10);
DEFINE vrfc_calculado   char(13);
DEFINE vcomienza        smallint;
DEFINE ven_transacc     smallint;
DEFINE vcontador1       integer;

LET vcodret1            ='00000';
LET vcodret2            ='0000';
LET vcodret3            ='PROCESO CONCLUIDO SATISFACTORIAMENTE';
LET sql_err             =0;
LET isam_err            =0;
LET desc_err            ='';
LET vcomienza           =-1;
LET ven_transacc        = 0;  
LET vnumcte             ='';
LET vrfc_calculado      ='';
LET vcontador1          =0;



BEGIN

    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/arch_sp_actualizarfc.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;

            RETURN vcodret1, vcodret2, vcodret3;
        END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

    FOREACH WITH HOLD
        select  numcte, rfc_calculado INTO vnumcte,  vrfc_calculado from bdinteg:resultadosrfc_prospectos where rfc_duplicado=0
    
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
            LET ven_transacc = 1; 
            BEGIN WORK;
        END IF;
        
        UPDATE bdiprospectos:pr_cliente set rfc=vrfc_calculado where numcte_pros=vnumcte;

        LET vcontador1 = vcontador1 + 1;
        

        IF (vcontador1 >= 5000) THEN
            LET vcontador1 = 0;
            COMMIT WORK;
            BEGIN WORK;
        END IF;
        
     END FOREACH;

     IF ven_transacc = 1 THEN
        LET ven_transacc = 0;
        COMMIT WORK;
     END IF;

END;
RETURN vcodret1, vcodret2, vcodret3; 
END PROCEDURE;

CREATE PROCEDURE "informix".sp_validarfc_prospectos()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(15);
DEFINE cApell_Pat   CHAR(25);
DEFINE cApell_Mat   CHAR(25);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(15);
DEFINE cRFCNuevo    CHAR(15);
DEFINE cComp        CHAR(10);
DEFINE iNumRows     INTEGER;
DEFINE iTotDupRec   INTEGER;
DEFINE cCteDupRec   CHAR(15);
DEFINE cCadRFCDup   CHAR(90);
DEFINE vNumCteIni   CHAR(9);


LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cComp        ='';
LET iNumRows     =0;
LET iTotDupRec   =0;
LET cCteDupRec   ='';
LET cCadRFCDup   ='';
LET vNumCteIni   ='';


BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE si_param SET valor=cNumcte WHERE cod_param='332';
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/tmp/sp_calcularrfcout.sql';
		--TRACE ON;
        
        SELECT valor into vNumCteIni from si_param where cod_param='332';

        set isolation to dirty read;
        FOREACH  
				

				SELECT a.numcte_pros, trim(apell_paterno), trim(apell_materno), trim(nombre1)||' '||trim(nombre2), fecha_nac, rfc
					INTO cNumcte, cApell_Pat, cApell_Mat, cNombre, cFecNac, cRFCOrig
				FROM bdiprospectos:pr_cliente a inner join bdiprospectos:pr_ctepf b on a.numcte_pros=b.numcte_pros
				WHERE a.numcte_pros>=vNumCteIni
				ORDER BY a.numcte_pros
                        
             LET cComp='';
             LET cCteDupRec='';
             LET cCadRFCDup='';
             LET iTotDupRec=0;

             EXECUTE PROCEDURE bdinteg:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
    
                if ccodret<>'00000' then
                    --SI EL SP QUE CALCULA EL RFC REGRESA UN ERROR SE CONTINUA CON EL SIGUIENTE REGISTRO
                    INSERT INTO bdinteg:resultadosrfc_prospectos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                            VALUES(cNumcte, cRFCOrig, '', 'NO CALC', '', '', '', '1');
                    CONTINUE FOREACH;
                end if;

            IF TRIM(cRFCOrig)=TRIM(cRFCNuevo) THEN
                --Si el RFC Calculado es igual al que tiene el cliente actualmente, se continua con el ciclo
                CONTINUE FOREACH;
            ELSE
                LET cComp='FALLO';
                
                --SE COMPARA EL RFC RECALCULADO ENTRE TODA LA TABLA DE RECALCULADOS 
                SELECT count(*) INTO iTotDupRec FROM bdinteg:resultadosrfc_prospectos WHERE rfc_calculado=cRFCNuevo;
                LET iNumRows = dbinfo("sqlca.sqlerrd2");
                IF iNumRows > 0 AND iTotDupRec> 0 THEN
                --SE ENCONTRARON REGISTROS CON EL MISMO RFC
                    LET cCadRFCDup='';
                    ---ALMACENAR EN LA BITACORA DE RFCS CALCULADOS
                    IF iTotDupRec=1 THEN
                        SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_prospectos WHERE rfc_calculado=cRFCNuevo;
                    ELSE
                        FOREACH SELECT numcte INTO cCteDupRec FROM bdinteg:resultadosrfc_prospectos WHERE rfc_calculado=cRFCNuevo
                            LET cCadRFCDup=TRIM(cCadRFCDup)||'|'||TRIM(cCteDupRec);
                        END FOREACH;
                    END IF;
                    LET cCadRFCDup=TRIM(cCadRFCDup)||'|      TABLA DE RECALCULO';
                    INSERT INTO bdinteg:resultadosrfc_prospectos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');
                ELSE
                        INSERT INTO bdinteg:resultadosrfc_prospectos (numcte, rfc_original, rfc_calculado, resultado, numcte2, cantidad, numcte_cadena, procesado)
                        VALUES(cNumcte, cRFCOrig, cRFCNuevo, cComp, cCteDupRec, iTotDupRec, cCadRFCDup, '1');

                END IF;
                

            END IF;
            
        END FOREACH;
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultarfcalterno(pempresa char(3),pnumcte char(20))

--VARIABLES A RETORNAR(MOSTRAR)
RETURNING
CHAR(5), -- Codigo de retorno
CHAR(13); -- rfc;

--DEFINIR VARIABLES A UTILIZAR (DEFINE)
DEFINE vcodret char(5);
DEFINE vrfc_alterno char(13);

--INICIALIZAR VARIABLES
LET vcodret ="00000";
LET vrfc_alterno = "";

--SET DEBUG FILE TO '/tmp/sp_consultarrfcalterno.out';
--TRACE ON;

BEGIN

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;

		IF EXISTS (SELECT rfc_alterno FROM bdinteg:"informix".si_cliente WHERE numcte=pnumcte AND empresa=pempresa) THEN

			SELECT rfc_alterno
			INTO vrfc_alterno 
			FROM bdinteg:"informix".si_cliente 
			WHERE numcte=pnumcte
			AND empresa=pempresa;

			IF  NVL(vrfc_alterno,"" ) = ""  THEN
	
			 LET  vcodret = "001";
			 LET  vrfc_alterno = "";
		
			ELSE 
		
		 	LET  vcodret = "000";
		
			END IF
	
			RETURN vcodret, vrfc_alterno;

		END IF;
	
END
END PROCEDURE
