DEFINE dFechaIni			DATE;
DEFINE dFechaFin			DATE;
DEFINE dFechaHoy			DATE;
DEFINE dFechaParaMovhisOld 	DATE;
DEFINE dFechaParaMovhisOld2 DATE;
DEFINE dFecha				DATE;
DEFINE cFechaParaMovhisOld 	CHAR(10);
DEFINE cFechaParaMovhisOld2 CHAR(10);
DEFINE cFechaIni 			CHAR(10);
DEFINE cFechaFin 			CHAR(10);
DEFINE cDia					CHAR(2);
DEFINE cMes					CHAR(2);
DEFINE cAnio				CHAR(4);
DEFINE iSqlErr 				INTEGER;
DEFINE iTotalRows			INTEGER;
DEFINE iFechAnio 			INTEGER;
DEFINE iLinea				INTEGER;
DEFINE dFechaActual			DATE;


LET cCodRet 				= "00000";
LET cCliente 				= "";
LET cFolio 					= "";
LET cHora 					= "";
LET cCuenta 				= "";
LET cUsuario 				= "";
LET cMonto 					= "";
LET cTransaccion 			= "";
LET cSaldo 					= "";
LET cSucursal 				= "";
LET cTransacSuc 			= "";
LET cReferencia 			= "";
LET dFechaIni 				= DATE(1);
LET dFechaFin 				= DATE(1);
LET dFechaHoy 				= DATE(1);
LET dFechaParaMovhisOld		= DATE(1);
LET dFechaParaMovhisOld2 	= DATE(1);
LET dFecha					= DATE(1);
LET iFechAnio 				= 0;
LET iLinea 					= 0;
LET cFechaParaMovhisOld 	= "";
LET cFechaParaMovhisOld2 	= "";
LET cFechaIni 				= "";
LET cFechaFin 				= "";
LET cDia 					= "";
LET cMes 					= "";
LET cAnio 					= "";
LET iTotalRows 				= 0;
LET dFechaActual            = DATE(1);

 
/*----------------*----------------*----------------*----------------*----------------*------------*
/ Se crea procedimiento almacenado para extraer la información requerida para la generación        /
/ del reporte de "Movimientos SPEI" desde la tabla si_rptcaja_aud                                  /
/ Elaborado por: Adilene Lara                                                                      /
/ Fecha: 27/11/2014                                                                                /
/ Solicitado por: Norberto Corona                                                                  /
*----------------*----------------*----------------*----------------*----------------*------------*/

--SET DEBUG FILE TO '/informix/sp_cons_spei_aud.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
			
			LET cCliente 				= "";
			LET cFolio 					= "";
			LET cHora 					= "";
			LET cCuenta 				= "";
			LET cUsuario 				= "";
			LET cMonto 					= "";
			LET cTransaccion 			= "";
			LET cSaldo 					= "";
			LET cSucursal 				= "";
			LET cTransacSuc 			= "";
			LET cReferencia 			= "";
			LET dFecha					= "";
			LET iTotalRows 				= 0;
			RETURN cCodRet,cCliente, cFolio, dFecha, cHora, cCuenta, cMonto, cTransaccion, cSaldo, cSucursal, cTransacSuc, cReferencia, iTotalRows;
			
		END IF;
	END EXCEPTION;
	

	SET LOCK MODE TO WAIT 3;
	SET ISOLATION TO DIRTY READ;
	
			LET cFechaIni = pFechaIni;
			LET cDia = SUBSTRING(cFechaIni FROM 1 FOR 2);
			LET cMes =  SUBSTRING(SUBSTRING(cFechaIni FROM 4 FOR 4) FROM 1 FOR 2);
			LET cAnio = SUBSTRING(cFechaIni FROM 7 FOR 10);
			LET dFechaIni = DATE(TRIM(cMes||'/'||cDia||'/'||cAnio));

			LET cFechaFin = pFechaFin;
			LET cDia = SUBSTRING(cFechaFin FROM 1 FOR 2);
			LET cMes =  SUBSTRING(SUBSTRING(cFechaFin FROM 4 FOR 4) FROM 1 FOR 2);
			LET cAnio = SUBSTRING(cFechaFin FROM 7 FOR 10);
			LET dFechaFin = DATE(TRIM(cMes||'/'||cDia||'/'||cAnio));
			
			SELECT DISTINCT(COUNT(folio))
			INTO iTotalRows
			FROM bdinteg:"informix".si_rptcaja_aud
			WHERE empresa = pEmpresa
			AND sucursal = pSucursal
			AND cod_transacc  IN (SELECT transaccion FROM bdinteg:"informix".si_transacciones_auditar_det WHERE empresa = pEmpresa  AND codigo = pCodigo)
			AND fecha BETWEEN dFechaIni AND dFechaFin
			AND reversado <> 'S';
		
			FOREACH
				SELECT SKIP pSkip LIMIT  pLimite  DISTINCT  cliente,folio,fecha,cuenta,monto,hora,transaccion,saldo, sucursal, transacc_suc, referencia
				INTO cCliente,cFolio,dFecha,cCuenta,cMonto,cHora, cTransaccion,cSaldo, cSucursal, cTransacSuc, cReferencia
				FROM bdinteg:"informix".si_rptcaja_aud
				WHERE empresa = pEmpresa
				AND sucursal = pSucursal
				AND cod_transacc IN (SELECT transaccion FROM bdinteg:"informix".si_transacciones_auditar_det WHERE empresa = pEmpresa  AND codigo = pCodigo)
				AND fecha BETWEEN dFechaIni AND dFechaFin
				AND reversado <> 'S'
				ORDER BY fecha,hora ASC
				
				LET cCodRet = '00000'; --Sin Errores
				
				RETURN cCodRet,cCliente, cFolio, dFecha,cCuenta, cMonto, cHora, cSucursal,cSaldo,cTransaccion,cReferencia, cTransacSuc, iTotalRows WITH RESUME;
			END FOREACH;	
			
				LET pSkip = pSkip + pLimite ;
			
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cnsif_consultanivelesaccesomodulos(pIdUsuario CHAR(8), pIdFuncion CHAR(10), pIdUsuarioC CHAR(8))
        RETURNING CHAR(5) AS codret,
                        CHAR(6) AS idmodulo,
                        SMALLINT AS nivel_acceso;
                        
        DEFINE cCodRet CHAR(5);
        DEFINE iSqlErr INTEGER;
        DEFINE iNivelAcceso SMALLINT;
        DEFINE cIdModulo CHAR(6);
        DEFINE iExiste SMALLINT;
        
        LET cCodRet = '00000';
        LET iSqlErr = 0;
        LET iNivelAcceso = 0;
        LET cIdModulo = '';
        LET iExiste = 0;
        
        BEGIN
        
                ON EXCEPTION SET iSqlErr
                        LET cCodRet = iSqlErr;
                        RETURN cCodRet, cIdModulo, iNivelAcceso;
                END EXCEPTION;
                
                --SET DEBUG FILE TO '/tmp/mfinis/sp_cnsif_consultanivelesaccesomodulos.out';
                --TRACE ON;
                
                IF pIdUsuario = '' OR pIdFuncion = '' OR pIdUsuarioC = '' THEN
                        LET cCodRet = '00003';
                        RETURN cCodRet, cIdModulo, iNivelAcceso;
                END IF;
                
                -- VALIDACIÓN DE ACCESO A LA FUNCIONALIDAD
                EXECUTE PROCEDURE "informix".sp_cnsif_confirmaejecutivo(pIdUsuario, pIdFuncion) INTO cCodRet;
                IF cCodRet <> '00000' THEN
                        RETURN cCodRet, cIdModulo, iNivelAcceso;
                END IF;
                
                SET ISOLATION TO DIRTY READ;
                -- Buscamos si el usuario esta en la tabla de accesos por modulo
                SELECT count(id_usuario)
                INTO iExiste
                FROM bdinteg:si_seg_nivel_acceso_modulo
                WHERE id_usuario = pIdUsuarioC;
                
                IF iExiste = 0 THEN
                        LET cCodRet = '00030';
                        RETURN cCodRet, cIdModulo, iNivelAcceso;
                END IF;
                
                FOREACH 
                        SELECT a.id_modulo, NVL(b.nivel_acceso, 0)
                        INTO cIdModulo, iNivelAcceso
                        FROM bdinteg:si_seg_modulos a LEFT JOIN bdinteg:si_seg_nivel_acceso_modulo b
                                ON b.id_modulo = a.id_modulo AND b.id_usuario = pIdUsuarioC
                        WHERE a.id_modulo NOT IN ('MOD100')
                        ORDER by a.id_modulo
                        
                        RETURN cCodRet, cIdModulo, iNivelAcceso WITH RESUME;
                        
                END FOREACH;

        
        END;
        
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 30/12/2013",
"DESCRIPCION: Consulta los niveles de acceso por modulos para un usuario",
"BD: bdinteg";

CREATE PROCEDURE "informix".sp_cnsif_ideconstancias(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCLIENTE CHAR(20),cPERIODO CHAR(06))

			returning   CHAR(5)     AS Cod_Retorno,
						CHAR(20)    AS Folio,
						CHAR(02)    AS Mes,
						CHAR(04)    AS Ejercicio,
						CHAR(13)    AS RFC,
						CHAR(20)    AS Curp,
						CHAR(26)    AS Apellido_Paterno,
						CHAR(26)    AS Apellido_Materno,
						CHAR(26)    AS Nombre_1,
						CHAR(26)    AS Nombre_2,
						CHAR(60)    AS Razon_Social,
						CHAR(13)    AS RFC_Institucion,
						CHAR(60)    AS Razon_Social_Institucion,
						MONEY(16,2) AS monto_Excedente_IDE,
						MONEY(16,2) AS Monto_Impuesto_Determinado,
						MONEY(16,2) AS Monto_Impuesto_Reca,
						MONEY(16,2) AS Monto_Impuesto_Pend_Reca,
						MONEY(16,2) AS Monto_Remanente_Per_Ant,
						MONEY(16,2) AS Tipo_Cambio;

DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;


DEFINE v_cod_ret    		   CHAR(5);
