            ELSE
                LET cProcedencia="";
                LET cD_Procedencia="";
            END IF;
			
			LET iCont=iCont+1;

			IF cCodfun ='001' AND cCodref in (1,2,3) THEN
				IF iCont>0 THEN
					LET iCont=iCont - 1;
				END IF;

			ELIF cCodfun ='002' AND cCodref =1 THEN
				IF iCont>0 THEN
					LET iCont=iCont - 1;
				END IF;
			ELSE
