DEFINE dFechaActual	DATE;

DEFINE iLinea INTEGER;

DEFINE VJMP CHAR(4);

--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodError = "00000";
LET cCliente = "";
LET cFolio = "";
LET cUsuario = "";
LET cFecha = "";
LET cHora = "";
LET cCuenta = "";
LET cMonto = "";
LET cTransaccion = "";
LET cSaldo = "";
LET cSucursal = "";
LET cTrans_Suc = "";
