LET cTarjeta = "";
LET iTotalRows = 0;

--Para "Fechas"
LET dFechaIni = DATE(1);
LET dFechaFin = DATE(1);
LET dFechaHoy = DATE(1);
LET dFechaMovhisOld = DATE(1);
LET dFechaMovhisOld2 = DATE(1);
