CREATE PROCEDURE "informix".sp_calcula_rfc()
    RETURNING CHAR(5) AS codret;

DEFINE cCodRet      CHAR(5);
DEFINE iSqlErr	    INTEGER;
DEFINE cNumcte      CHAR(20);
DEFINE cApell_Pat   CHAR(26);
DEFINE cApell_Mat   CHAR(26);
DEFINE cNombre      CHAR(55);
DEFINE cFecNac      CHAR(10);
DEFINE cRFCOrig     CHAR(13);
DEFINE cRFCNuevo    CHAR(13);
DEFINE cNombre1		CHAR(26);
DEFINE cNombre2		CHAR(26);
DEFINE cCteDup		CHAR(13);

LET cCodRet      ='00000';
LET iSqlErr		 =0;
LET cNumcte      ='';
LET cApell_Pat   ='';
LET cApell_Mat   ='';
LET cNombre      ='';
LET cFecNac      ='';
LET cRFCOrig     ='';
LET cRFCNuevo    ='';
LET cNombre1	 ='';
LET cNombre2	 ='';
LET cCteDup	     ='';

BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END EXCEPTION;

        --SET DEBUG FILE TO '/informix/VH/soc_fase3/calculo_rfc.out';
		--TRACE ON;
        
        set isolation to dirty read;
        FOREACH  
                
				SELECT numcte
					INTO cNumcte
					from si_rfc_calculados
				
				SELECT c.rfc,trim(c.apell_paterno),trim(c.apell_materno),trim(c.nombre1),trim(c.nombre2),f.fecha_nac,trim(c.nombre1)||' '||trim(c.nombre2)
					INTO cRFCOrig,	cApell_Pat,	cApell_Mat,	cNombre1,cNombre2,cFecNac,cNombre
					from si_cliente c inner join si_ctepf f on c.numcte=f.numcte
					WHERE C.numcte=cNumcte;

				
             EXECUTE PROCEDURE bdicnweb:"informix".sp_calcularrfc(cApell_Pat, cApell_Mat, cNombre, cFecNac)
                INTO cCodRet, cRFCNuevo;
       			   	
					
					SELECT numcte--TRAE EL CLIENTE
					INTO cCteDup
					FROM si_cliente
					WHERE rfc=cRFCNuevo--SE VA A TRAER EL CLIENTE DONDE EL RFC=RFC_NUEVO
					AND	numcte <> cNumcte;
																   

				update bdinteg:si_rfc_calculados
				 set rfc_original=cRFCOrig,
					rfc_calculado=cRFCNuevo,
					apell_paterno=cApell_Pat,
					apell_materno=cApell_Mat,
					nombre1=cNombre1,
					nombre2=cNombre2,
					fecha_nac=cFecNac,
					duplicado=cCteDup
				where numcte=cNumcte;
            							
        END FOREACH;
				
       set isolation to dirty read;
        FOREACH 
				SELECT numcte,rfc_calculado
				INTO cNumcte, cRFCNuevo
				from si_rfc_calculados where duplicado is null --trae el cliente donde se hata encontrado un cliente con el mismo rfc
				update  bdinteg:si_cliente set rfc=cRFCNuevo where numcte=cNumcte;
					
        END FOREACH;		
		
		
		RETURN cCodRet;
	END;
			
END PROCEDURE;

CREATE PROCEDURE "informix".sp_modifica_tipo_cliente()
RETURNING CHAR(6);
	DEFINE cCodRet			CHAR(6);
	DEFINE i_SqlError		INTEGER;
	DEFINE i_iSamError		INTEGER;
	DEFINE vnumcte			CHAR (20);
	DEFINE iTrans_abierta	INTEGER;
	DEFINE iTotalReg		INTEGER;
	DEFINE iProcesados		INTEGER;
	DEFINE MAXTRANSACCION	INTEGER;
	
	LET MAXTRANSACCION = 500;
	LET vnumcte = '';
	LET cCodRet = '000000';
	LET iProcesados = 0;
	LET iTotalReg= 0;
	LET iTrans_abierta= 0;
	
	--SET DEBUG FILE TO "/informix/rmarquez/sp_modifica_tipo_cliente.out";
	--TRACE ON;	
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		ON EXCEPTION SET i_SqlError,i_iSamError
			IF i_SqlError <> 0 THEN	
			
				IF iTrans_abierta = 1 THEN
					ROLLBACK WORK;
				END IF;
				
				LET cCodRet = i_SqlError;
				
				IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpctes_tipoincorrecto') THEN
					DROP TABLE tmpctes_tipoincorrecto;
				END IF;
				
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
						
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpctes_tipoincorrecto') THEN
			DROP TABLE tmpctes_tipoincorrecto;
		END IF;
		
		--Forma la tabla temporal con todos los clientes incorrectos.		
		SELECT DISTINCT a.numcte FROM bdinteg:si_cliente a,
		TABLE(MULTISET(SELECT DISTINCT num_cte AS numcte FROM bdicheq:sc_maechq
               UNION ALL
               SELECT DISTINCT numcte AS numcte FROM bdicred:sd_maecred)) b,
		TABLE(MULTISET(SELECT cliente AS numcte FROM bdidigital@coppelimg_tcp:dg_expediente
                WHERE cod_docto IN (SELECT cod_docto FROM bdidigital@coppelimg_tcp:dg_tipodocumento
                                     WHERE cod_grupo = '001')))c
		WHERE a.tipo_cliente = '2'
		AND a.numcte = b.numcte
		AND b.numcte = c.numcte
		INTO TEMP tmpctes_tipoincorrecto WITH NO LOG;
										   		
		--Cuenta los registros de la tabla temporal
		SELECT COUNT(*) 
		INTO iTotalReg 
		FROM tmpctes_tipoincorrecto;		
						
		IF iTotalReg > 0 THEN		
			FOREACH WITH HOLD
				SELECT numcte 
				INTO vnumcte
				FROM tmpctes_tipoincorrecto
				
				IF iProcesados = 0 THEN
					BEGIN WORK;
					LET iTrans_abierta = 1;
				END IF;				
				
				UPDATE "informix".si_cliente SET tipo_cliente = '1' WHERE numcte= vnumcte;
								
				LET iProcesados = iProcesados + 1;
				
				IF iProcesados >= MAXTRANSACCION THEN
					COMMIT WORK;
					LET iProcesados = 0;					
					LET iTrans_abierta = 0;
				END IF;
			END FOREACH;
			
			IF iProcesados < MAXTRANSACCION AND  iTrans_abierta = 1 THEN
				IF iProcesados > 0 THEN
					COMMIT WORK;
					LET iProcesados = 0;
					LET iTrans_abierta = 0;
				END IF;				
			END IF;
		ELSE
			LET cCodRet = '000001';
		END IF;
				
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpctes_tipoincorrecto') THEN
			DROP TABLE tmpctes_tipoincorrecto;
		END IF;	
		
		RETURN cCodRet;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_insbitsmstel(pnumcte CHAR(9), pejecutivo CHAR(8), psucursal CHAR(5), 
                                pdigito_ver CHAR(4), ptelefono CHAR(10), pteclea_ejecut CHAR(100), pbandera boolean)
RETURNING char(5) as codret 
DEFINE iSqlErr			INTEGER;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr;
			END IF;
		END EXCEPTION;
		
        
        INSERT INTO si_bitsmstels(numcte, ejecutivo, sucursal, digito_ver, telefono, teclea_ejecut, bandera, fecha) 
               VALUES(pnumcte, pejecutivo, psucursal, pdigito_ver, ptelefono, pteclea_ejecut, pbandera, current);

		RETURN '00000';
	END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_calcularrfcpba(pApellidoPaterno CHAR(26), pApellidoMaterno CHAR(26), pNombre CHAR(55), pFechaNacimiento DATE)
        RETURNING CHAR(5) AS codret,
                        CHAR(13) AS rfc;

        DEFINE cCodRet CHAR(5);
        DEFINE iSqlErr INTEGER;
        DEFINE cRfc CHAR(13);
        DEFINE cCaracter CHAR(1);
        DEFINE i SMALLINT;
        DEFINE bBoolValue BOOLEAN;
        DEFINE lPalabra LVARCHAR;
        DEFINE bSalirBucle BOOLEAN;
        -- Variables de RFC
        DEFINE cPrimerLetraApellidoPaterno CHAR(1);
        DEFINE cVocalApellidoPaterno CHAR(1);
        DEFINE cPrimerLetraApellidoMaterno CHAR(1);
        DEFINE cPrimerLetraNombre CHAR(1);
        DEFINE cFechaNacimientos CHAR(6);
        DEFINE cHomoclave CHAR(2);
        DEFINE cDigitoVerificador CHAR(2);
		DEFINE cApellidoMaterno CHAR(26);

    DEFINE iCont INTEGER;
    DEFINE lPalabra2 LVARCHAR;
    LET iCont=0;
    LET lPalabra2 = '';

        LET cCodRet = '00000';
        LET iSqlErr = 0;
        LET cRfc = '';
        LET cCaracter = '';
        LET bBoolValue = 'f';
        LET lPalabra = '';
        LET bSalirBucle = 'f';
        LET cPrimerLetraApellidoPaterno = '';
        LET cVocalApellidoPaterno = '';
        LET cPrimerLetraApellidoMaterno = 'X';
        LET cPrimerLetraNombre = '';
        LET cFechaNacimientos = '';
        LET cHomoclave = '';
        LET cDigitoVerificador = '';
		LET cApellidoMaterno = pApellidoMaterno;

        BEGIN

                ON EXCEPTION SET iSqlErr
                        LET cCodRet = iSqlErr;
                        RETURN cCodRet, cRfc;
                END EXCEPTION;

                SET DEBUG FILE TO 'sp_calcularrfc.out';
                TRACE ON;

                IF pNombre = '' OR pFechaNacimiento IS NULL THEN
                        LET cCodRet = '00003';
                        RETURN cCodRet, cRfc;
                END IF;

                IF pApellidoPaterno = '' AND pApellidoMaterno = '' THEN
                        LET cCodRet = '00003';
                        RETURN cCodRet, cRfc;
                END IF;

                LET pApellidoPaterno = UPPER(pApellidoPaterno);
                LET pApellidoMaterno = UPPER(pApellidoMaterno);
                LET pNombre = UPPER(pNombre);

                FOR i = 0 TO LENGTH(TRIM(pApellidoPaterno))
                        LET cCaracter = SUBSTR(TRIM(pApellidoPaterno), i, 1);
                        EXECUTE FUNCTION "informix".sp_sololetrasnumeros(cCaracter) INTO bBoolValue;

                        IF NOT bBoolValue THEN
                                LET cCodRet = '00221'; -- CARACTER RARO EN EL APELLIDO PATERNO
                                RETURN cCodRet, cRfc;
                        END IF;
                END FOR;

                FOR i = 0 TO LENGTH(TRIM(pApellidoMaterno))
                        LET cCaracter = SUBSTR(TRIM(pApellidoMaterno), i, 1);
                        EXECUTE FUNCTION "informix".sp_sololetrasnumeros(cCaracter) INTO bBoolValue;

                        IF NOT bBoolValue THEN
                                LET cCodRet = '00222'; -- CARACTER RARO EN EL APELLIDO MATERNO
                                RETURN cCodRet, cRfc;
                        END IF;
                END FOR;

                FOR i = 0 TO LENGTH(TRIM(pNombre))
                        LET cCaracter = SUBSTR(TRIM(pNombre), i, 1);
                        EXECUTE FUNCTION "informix".sp_sololetrasnumeros(cCaracter) INTO bBoolValue;

                        IF NOT bBoolValue THEN
                                LET cCodRet = '00223'; -- CARACTER RARO EN EL NOMBRE
                                RETURN cCodRet, cRfc;
                        END IF;
                END FOR;

                -- SI SOLO TIENE UN APELLIDO TOMARLO COMO PATERNO
                IF TRIM(pApellidoPaterno) = '' AND TRIM(pApellidoMaterno) <> '' THEN
                        LET pApellidoPaterno = pApellidoMaterno;
                        LET pApellidoMaterno = '';
                END IF;

                -- Se Obtiene la primera letra y la primer vocal del apellido
                IF TRIM(pApellidoPaterno) <> '' THEN
						--CONTADOR DE APELLIDO
						FOREACH EXECUTE FUNCTION "informix".sp_split_cadena(pApellidoPaterno, ' ') INTO lPalabra2
							Let iCont=iCont+1;
							--RETURN iCont, 'CONTADOR';
						END FOREACH;


                        FOREACH EXECUTE FUNCTION "informix".sp_split_cadena(pApellidoPaterno, ' ') INTO lPalabra

                                -- Verificar que el apellido no este abreviado
                                EXECUTE FUNCTION "informix".sp_esnombre_apellido_abreviado(lPalabra) INTO bBoolValue;
                                IF bBoolValue THEN -- EL APELLIDO ESTA ABREVIADO
                                        LET cCodRet = '00224'; -- APELLIDO PATERNO ABREVIADO
                                        RETURN cCodRet, cRfc;
                                ELSE -- EL APELLIDO PATERNO NO ESTA ABREVIADO
                                        -- SE VALIDA QUE SEA UN APELLIDO VALIDO
								IF iCont>1 THEN
									EXECUTE FUNCTION "informix".sp_esapellido_valido(lPalabra) INTO bBoolValue;
								ELSE
									LET bBoolValue='t';
								END IF;

                                        IF bBoolValue THEN
                                                LET cPrimerLetraApellidoPaterno = SUBSTR(TRIM(lPalabra), 1, 1);
                                                -- SE BUSCA LA PRIMERA VOCAL DEL APELLIDO
                                                IF LENGTH(TRIM(lPalabra)) > 1 THEN
                                                        FOR i = 2 TO LENGTH(TRIM(lPalabra))
                                                                LET cCaracter = SUBSTR(TRIM(lPalabra), i, 1);
                                                                EXECUTE FUNCTION "informix".sp_esvocal(cCaracter) INTO bBoolValue;
                                                                IF bBoolValue THEN
                                                                        LET cVocalApellidoPaterno = cCaracter;
                                                                        LET bSalirBucle = 't';
                                                                        EXIT FOR;
                                                                --ELSE
                                                                --      LET cVocalApellidoPaterno = 'X';
                                                                END IF;
                                                        END FOR;
                                                        LET bSalirBucle = 't';
                                                ELSE
                                                        LET bSalirBucle = 't';
                                                END IF;

                                                IF bSalirBucle THEN
                                                        EXIT FOREACH;
                                                END IF;
                                        END IF;

                                END IF;

                        END FOREACH;
                END IF;
                LET bSalirBucle = 'f';

                -- Se Obtiene la primera letra apellido materno
                IF TRIM(pApellidoMaterno) <> '' THEN
                        FOREACH EXECUTE FUNCTION "informix".sp_split_cadena(pApellidoMaterno, ' ') INTO lPalabra

                                -- Verificar que el apellido no este abreviado
                                EXECUTE FUNCTION "informix".sp_esnombre_apellido_abreviado(lPalabra) INTO bBoolValue;
                                IF bBoolValue THEN -- EL APELLIDO ESTA ABREVIADO
                                        LET cCodRet = '00225'; -- APELLIDO MATERNO ABREVIADO
                                        RETURN cCodRet, cRfc;
                                ELSE -- EL APELLIDO MATERNO NO ESTA ABREVIADO
                                        -- SE VALIDA QUE SEA UN APELLIDO VALIDO
                                        EXECUTE FUNCTION "informix".sp_esapellido_valido(lPalabra) INTO bBoolValue;

                                        IF bBoolValue THEN
                                                LET cPrimerLetraApellidoMaterno = SUBSTR(TRIM(lPalabra), 1, 1);
                                                EXIT FOREACH;
                                        END IF;

                                END IF;

                        END FOREACH;
                END IF;

				--TRACE '-----------------------------------------------------';
				--TRACE '>>>>>'||cPrimerLetraApellidoPaterno||cVocalApellidoPaterno||cPrimerLetraApellidoMaterno||cPrimerLetraNombre;

                -- Se obtiene la primer letra del nombre
                IF TRIM(pNombre) <> '' THEN

                        FOREACH EXECUTE FUNCTION "informix".sp_split_cadena(pNombre, ' ') INTO lPalabra

                                -- Revisar que el nombre no este abreviado
                                EXECUTE FUNCTION "informix".sp_esnombre_apellido_abreviado(lPalabra) INTO bBoolValue;
                                IF bBoolValue THEN
                                        LET cCodRet = '00226'; -- NOMBRE ABREVIADO
                                        RETURN cCodRet, cRfc;
                                ELSE
                                        EXECUTE FUNCTION "informix".sp_esnombre_valido(TRIM(lPalabra)) INTO bBoolValue;

                                        IF bBoolValue THEN
												--TRACE '*********************************';
                                                IF cVocalApellidoPaterno = '' THEN
                                                        LET cVocalApellidoPaterno = cPrimerLetraApellidoMaterno;
                                                        LET cPrimerLetraApellidoMaterno = SUBSTR(TRIM(lPalabra), 1, 1);
                                                        LET cPrimerLetraNombre = SUBSTR(TRIM(lPalabra), 2, 1);
                                                ELSE
                                                        IF TRIM(pApellidoMaterno) = '' THEN
                                                                LET cPrimerLetraApellidoMaterno = SUBSTR(TRIM(lPalabra), 1, 1);
                                                                LET cPrimerLetraNombre = SUBSTR(TRIM(lPalabra), 2, 1);
                                                        ELSE
                                                                LET cPrimerLetraNombre = SUBSTR(TRIM(lPalabra), 1, 1);
                                                        END IF;
                                                END IF;
                                                EXIT FOREACH;
                                        ELSE
                                                IF TRIM(lPalabra) = 'MARIA' OR TRIM(lPalabra) = 'JOSE' OR TRIM(lPalabra) = 'MA' OR TRIM(lPalabra) = 'M' OR TRIM(lPalabra) = 'J' THEN
                                                        IF cVocalApellidoPaterno = '' THEN
                                                                LET cVocalApellidoPaterno = cPrimerLetraApellidoMaterno;
																LET pApellidoMaterno = '';
                                                                LET cPrimerLetraApellidoMaterno = SUBSTR(TRIM(lPalabra), 1, 1);
                                                                LET cPrimerLetraNombre = SUBSTR(TRIM(lPalabra), 2, 1);
                                                        ELSE
                                                                LET cPrimerLetraNombre = SUBSTR(TRIM(lPalabra), 1, 1);
                                                        END IF;
                                                END IF;
                                        END IF;

                                END IF;

                        END FOREACH;

                END IF;

				LET pApellidoMaterno = cApellidoMaterno;

                LET cRfc = cPrimerLetraApellidoPaterno||cVocalApellidoPaterno||cPrimerLetraApellidoMaterno||cPrimerLetraNombre;
                -- Busqueda de palabra Altisonante
                EXECUTE FUNCTION "informix".sp_espalabra_altisonante(TRIM(cRfc)) INTO bBoolValue;
                IF bBoolValue THEN
                        LET cPrimerLetraNombre = 'X';
                END IF;

                LET cFechaNacimientos = TO_CHAR(pFechaNacimiento, '%y%m%d');
                LET cRfc =      cPrimerLetraApellidoPaterno||cVocalApellidoPaterno||cPrimerLetraApellidoMaterno||cPrimerLetraNombre||cFechaNacimientos;

                -- ObtenciÃ³n de la homoclave
                LET lPalabra = UPPER(TRIM(pApellidoPaterno))||' '||UPPER(TRIM(pApellidoMaterno))||' '||UPPER(TRIM(pNombre));
                EXECUTE FUNCTION "informix".sp_obtenerhomoclave(lPalabra) INTO cHomoclave;

                -- ObtenciÃ³n del digito verificador
                LET cRfc = TRIM(cRfc)||cHomoclave;
                EXECUTE FUNCTION "informix".sp_obtienedigitoverificador_rfc(TRIM(cRfc)) INTO cDigitoVerificador;

                LET cRfc =      cPrimerLetraApellidoPaterno||cVocalApellidoPaterno||cPrimerLetraApellidoMaterno||cPrimerLetraNombre||cFechaNacimientos||cHomoclave||cDigitoVerificador;
                RETURN cCodRet, cRfc;
        END;

END PROCEDURE
DOCUMENT
"AUTOR: Oscar Flores Conde",
"FECHA: 05/12/2013",
"DESCRIPCION: Funcion que genera el RFC de un cliente";

CREATE PROCEDURE "informix".sp_esnombre_apellido_abreviado(pPalabra CHAR(26))
	RETURNING BOOLEAN AS es_palabra_abreviada;
	
	DEFINE bEsPalabraAbreviada BOOLEAN;
	DEFINE cPalabra CHAR(26);
	
	LET bEsPalabraAbreviada = 'f';
	LET pPalabra = UPPER(pPalabra);
	LET cPalabra = '';
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		
		SELECT apellido_nombre_abreviado
		INTO cPalabra
		FROM bdinteg:"informix".apellido_nombre_abreviado
		WHERE apellido_nombre_abreviado = pPalabra;
		
		IF cPalabra IS NOT NULL THEN
			LET bEsPalabraAbreviada = 't';
		END IF;
		
		RETURN bEsPalabraAbreviada;
		
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si el parametro de entrada es un nombre o apellido abreviado, deveulve un booleano";

CREATE PROCEDURE "informix".sp_esnombre_valido(pNombre CHAR(26))
	RETURNING BOOLEAN AS es_nombre_valido;
	
	DEFINE bEsNombreValido BOOLEAN;
	DEFINE cNombre CHAR(26);
	
	LET bEsNombreValido = 't';
	LET pNombre = UPPER(pNombre);
	LET cNombre = '';
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		
		SELECT nombre_novalido
		INTO cNombre
		FROM bdinteg:"informix".nombres_novalidos
		WHERE nombre_novalido = pNombre;
		
		IF cNombre IS NOT NULL THEN
			LET bEsNombreValido = 'f';
		END IF;
		
		RETURN bEsNombreValido;
		
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si la palabra de entrada es valida, deveulve un booleano";

CREATE PROCEDURE "informix".sp_espalabra_altisonante(pPalabra CHAR(10))
	RETURNING BOOLEAN AS es_palabra_altisonante;

	DEFINE bEsPalabraAltisonante BOOLEAN;
	DEFINE cPalabra CHAR(10);

	LET bEsPalabraAltisonante = 'f';
	LET pPalabra = UPPER(pPalabra);
	LET cPalabra = '';

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN

		SELECT palabra_incoveniente
		INTO cPalabra
		FROM bdinteg:"informix".palabra_inconveniente
		WHERE palabra_incoveniente = pPalabra;

		IF cPalabra IS NOT NULL THEN
			LET bEsPalabraAltisonante = 't';
		END IF;

		RETURN bEsPalabraAltisonante;

	END;

END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si el parametro de entrada es una palabra altisonante, deveulve un booleano";

CREATE PROCEDURE "informix".sp_esvocal(pLetra CHAR(1))
	RETURNING BOOLEAN as esvocal;
	
	DEFINE bEsVocal BOOLEAN;
	
	LET bEsVocal = 'f';
	LET pLetra = UPPER(pLetra);

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
	
		IF pLetra = 'A' THEN
			LET bEsVocal = 't';
		ELIF pLetra = 'E' THEN
			LET bEsVocal = 't';
		ELIF pLetra = 'I' THEN
			LET bEsVocal = 't';
		ELIF pLetra = 'O' THEN
			LET bEsVocal = 't';
		ELIF pLetra = 'U' THEN
			LET bEsVocal = 't';
		END IF;
	
		RETURN bEsVocal;
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si un caracter es vocal, deveulve un booleano";

CREATE PROCEDURE "informix".sp_obtienedigitoverificador_rfc(pRfc CHAR(13))
        RETURNING CHAR(1) AS digito_verificador;
        
        DEFINE cCaracter CHAR(1);
        DEFINE bBoolValue BOOLEAN;
        DEFINE i SMALLINT;
        DEFINE iCodigoLetra SMALLINT;
        DEFINE iOperacion INTEGER;
        DEFINE iModulo INTEGER;
        
        LET cCaracter = '';
        LET bBoolValue = 'f';
        LET iOperacion = 0;
        LET iModulo = 0;
        
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
        BEGIN
        
                --SET DEBUG FILE TO '/tmp/mfinis/sp_obtienedigitoverificador_rfc.out';
                --TRACE ON;
                
                FOR i = 1 TO LENGTH(TRIM(pRfc))
                        
                        LET cCaracter = SUBSTR(TRIM(pRfc), i, 1);
                        
                        SELECT codigo_letra
                        INTO iCodigoLetra
                        FROM "informix".letras_codigoverificador_rfc
                        WHERE letra = cCaracter;
                        
                        IF iCodigoLetra IS NULL THEN
                                LET bBoolValue = 'f';
                        ELSE
                                LET bBoolValue = 't';
                        END IF;
                        
                        IF NOT bBoolValue THEN
                        
                                IF cCaracter = '' THEN
                                        LET iCodigoLetra = 24;
                                ELSE
                                        IF cCaracter = ' ' THEN
                                                LET iCodigoLetra = 37;
                                        ELSE
                                                IF cCaracter::INTEGER >= 0 AND cCaracter::INTEGER <= 9 AND ASCII(cCaracter) NOT IN (209) THEN
                                                        LET iCodigoLetra = cCaracter::INTEGER;
                                                ELSE
                                                        LET iCodigoLetra = 0;
                                                END IF;
                                        END IF;
                                END IF;
                        END IF;
                        
                        LET iOperacion = iOperacion + (iCodigoLetra * (14 - i));
                        
                END FOR;
                
                LET iModulo = ABS(MOD(iOperacion, 11));
                
                IF iModulo = 0 THEN
                        LET cCaracter = 0;
                ELIF iModulo > 0 THEN--AND iModulo != 10 
                        LET iOperacion = 11 - iModulo;
						IF iOperacion = 10 THEN
							LET cCaracter = 'A';
						ELSE
							LET cCaracter = iOperacion;
						END IF;
                --ELIF iModulo = 10 THEN
                --        LET cCaracter = 'A';
                END IF;
                
                RETURN cCaracter;
                
        END;
        
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 05/12/2013",
"DESCRIPCION: Funcion que obtiene el digito verificador, devuelve un caracter";

CREATE PROCEDURE "informix".sp_sololetrasnumeros(pCaracter CHAR(1))
	RETURNING BOOLEAN AS es_letra_numero;
	
	DEFINE bEsLetraNumero BOOLEAN;
	DEFINE iAscii SMALLINT;
	
	LET bEsLetraNumero = 't';
	LET iAscii = 0;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		LET iAscii = ASCII(pCaracter);
		
		IF NOT ((iAscii >= 97 AND iAscii <= 122)  OR (iAscii >= 65 AND iAscii <= 90) OR (iAscii >= 48 AND iAscii <= 57) OR iAscii = 32 OR iAscii = 209) THEN
			LET bEsLetraNumero = 'f';
		END IF;
		
		RETURN bEsLetraNumero;
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que revisa si el parametro de entrada es un caracter o numero, deveulve un booleano";

CREATE PROCEDURE "informix".sp_split_cadena(pCadena LVARCHAR, pDelimitador CHAR(1))
	RETURNING LVARCHAR AS palabra;
	
	DEFINE tPalabra LVARCHAR;
	DEFINE i INTEGER;
	DEFINE iTamCad INTEGER;
	DEFINE iInicioCadena INTEGER;
	DEFINE iRecuperarCaracteres INTEGER;
	DEFINE cCaracter CHAR(1);
	DEFINE cPalabra LVARCHAR;
	
	LET tPalabra = '';
	LET iTamCad = LENGTH(TRIM(pCadena));
	LET cCaracter = '';
	LET cPalabra = '';
	LET iInicioCadena = 1;
	LET iRecuperarCaracteres = 0;

        --SET DEBUG FILE TO '/tmp/sp_split_cadena.SQL';
		--TRACE ON;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
		
	BEGIN
	
		FOR i IN (1 TO iTamCad) LOOP
		
			LET cCaracter = SUBSTR(TRIM(pCadena), i, 1);
			LET iRecuperarCaracteres = iRecuperarCaracteres + 1;
			
			IF cCaracter = pDelimitador THEN
				LET iRecuperarCaracteres = iRecuperarCaracteres - 1;
				
				--TRACE iInicioCadena||' -> '|| iRecuperarCaracteres;
				LET cPalabra = SUBSTR(TRIM(pCadena), iInicioCadena, iRecuperarCaracteres);
				LET iInicioCadena = i + 1;
				LET iRecuperarCaracteres = 0;
				
				IF cPalabra <> '' THEN
					RETURN cPalabra WITH RESUME;
				END IF;
			END IF;
			
		END LOOP;
		
		LET cPalabra = SUBSTR(TRIM(pCadena), iInicioCadena, iRecuperarCaracteres);
		IF cPalabra <> '' THEN
			RETURN cPalabra;
		END IF;
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 04/12/2013",
"DESCRIPCION: Funcion que separa una cadena de acuerdo a un delimitador indicado";

CREATE PROCEDURE "informix".sp_cifra_archivo_chq_pba( pCodigo CHAR(20) ) 
RETURNING CHAR(5);
    
    DEFINE cCodRet          CHAR(5);
    DEFINE cCodRet2         CHAR(5);
    DEFINE cCodRet3	        CHAR(50);
    DEFINE iSqlErr          INTEGER;
    DEFINE iSamErr          INTEGER;
    DEFINE cDesErr	        CHAR(150);
    DEFINE vUsuario         CHAR(20);
    DEFINE vLLave           CHAR(200);
    DEFINE vNomarch         CHAR(100);
    DEFINE vRutaOrigen      CHAR(100);
    DEFINE vRutaDestino     CHAR(100);
    DEFINE vNomarchSalida   CHAR(100);
    DEFINE vRutaOriginales  CHAR(100);
    DEFINE vNomarch_salida  CHAR(100);
    
    
    LET cCodRet         = '';
    LET cCodRet2        = 0;
    LET cCodRet3        = '';
    LET iSqlErr         = 0;
    LET iSamErr         = 0;
    LET cDesErr         = '';
    LET vUsuario        = '';
    LET vLLave          = '';
    LET vNomarch        = '';
    LET vRutaOrigen     = '';
    LET vRutaDestino    = '';
    LET vNomarchSalida  = '';
    LET vRutaOriginales = '';
    LET vNomarch_salida = '';
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cifra_archivo_chq.err";
        TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            LET cCodRet2 = iSamErr;
            LET cCodRet3 = cDesErr;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;
    
    SET DEBUG FILE TO "/resplogifx/conciliachq/sp_cifra_archivo_chq.out";
    TRACE ON;
    
    FOREACH
        SELECT TRIM(usuario), TRIM(llave), TRIM(nomarch), TRIM(ruta_origen), TRIM(nomarch_salida), TRIM(ruta_destino), TRIM(ruta_originales)
          INTO vUsuario, vLLave, vNomarch, vRutaOrigen, vNomarch_salida, vRutaDestino, vRutaOriginales    
          FROM bdinteg:si_configura_pgp_chq
         WHERE codigo = pCodigo
         ORDER BY secuencia
        
        IF vUsuario <> user THEN
            LET cCodRet = '200';
            RETURN cCodRet;
        END IF;
        
        SYSTEM 'echo "export PATH=/usr/bin:/etc:/usr/sbin:/usr/ucb:/home/'||TRIM(vUsuario)||'/bin:/usr/bin/X11:/sbin:.:/opt/pgp/bin:/informix/bin" > '||TRIM(vRutaOrigen)||'blinda_archivo.sh';
        SYSTEM 'echo "export HOME=/home/'||TRIM(vUsuario)||'" >> '||TRIM(vRutaOrigen)||'blinda_archivo.sh';
        SYSTEM 'echo "/opt/pgp/bin/pgp --encrypt -i '||TRIM(vRutaOrigen)||TRIM(vNomarch)||' -r '||''''||TRIM(vLLave)||''''||" --armor --compression --output "||TRIM(vRutaDestino)||TRIM(vNomarch_salida)||'" >> '||TRIM(vRutaOrigen)||'blinda_archivo.sh';
        SYSTEM '/usr/bin/chmod 777 '||TRIM(vRutaOrigen)||'blinda_archivo.sh';   
        SYSTEM '/usr/bin/sh '||TRIM(vRutaOrigen)||'blinda_archivo.sh';
        SYSTEM '/usr/bin/mv '||TRIM(vRutaOrigen)||TRIM(vNomarch)||' '||vRutaOriginales; 
    END FOREACH;
    
    LET cCodRet = '000';
    
    RETURN cCodRet;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultacajagen()

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Consultamos todas las plazas de la tabla si_plazas_cajagen
--Realizó: Richar 
--Fecha: 28/01/2015
--------------------------------------------------------------------													


 --DATOS A REGRESAR---	
	RETURNING CHAR(5) as codret, 	--codret
			  CHAR(3) as plaza,
			  char(60) as NomPlaza; --perfil
			  
	
--DEFINICION DE VARIABLES--			  
	DEFINE cCodRet 	CHAR(5);
	DEFINE iSqlErr 	INTEGER;	
	DEFINE cVPlaza  char(3);
	DEFINE cVNombre CHAR(60);	
    ---------------------------
	
	--Banderas
	DEFINE v_paso				varchar(50);
	
	--SET DEBUG FILE TO "/home/sysifx/sp_consultacajagen.out";
	--TRACE ON;	

	set isolation to dirty read;
	SET LOCK MODE TO WAIT 3;	

	-- INICIO DEL PROCEDIMIENTO	
	BEGIN
	-- MANEJADOR DE ERRORES	
		ON EXCEPTION SET iSqlErr
			--LET cCodRet = v_paso;
			LET cCodRet = iSqlErr;
			Return cCodRet, 0,''; 
		END EXCEPTION;		
				
			
			FOREACH
			select 
			codigo_plaza, 
			trim(descripcion) as nombre 
			Into cVPlaza,cVNombre
			from si_plazas_cajagen			
			order by descripcion
			
			--LET v_paso='Consul';
			LET cCodRet = '00000' ;
			
			return cCodRet,cVPlaza,cVNombre WITH RESUME;
			
			End FOREACH;
			
			
		
	End;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaperfil(cNumEmpleado CHAR(8))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Consultamos si tiene perfil de caja de general
--Realizó: Richar 
--Fecha: 26/01/2015
--------------------------------------------------------------------													
--cEmpresa = 001
--cCentroc = el numero del centro de costros
--cStatus = estatus de la consulta del CC
--cRegion id de la region de la tabla de catalogos
--cgcb id de la gerencia de la tabla de catalogos

 --DATOS A REGRESAR---	
	RETURNING CHAR(5) as codret, 	--codret
			  integer as perf; --perfil
	
--DEFINICION DE VARIABLES--			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE ivPerfil Integer;
	
    ---------------------------
	
	--Banderas
	DEFINE v_paso				varchar(50);
	
	--SET DEBUG FILE TO "/home/sysifx/sp_consultaperfil.out";
	--TRACE ON;	

	set isolation to dirty read;
	SET LOCK MODE TO WAIT 3;	

	-- INICIO DEL PROCEDIMIENTO	
	BEGIN
	-- MANEJADOR DE ERRORES	
		ON EXCEPTION SET iSqlErr
			--LET cCodRet = v_paso;
			LET cCodRet = iSqlErr;
			Return cCodRet, 0; 
		END EXCEPTION;		
				
			Select Perfil 
			Into ivPerfil
			from si_perfil_ejecut 
			where ejecutivo=cNumEmpleado
			And Perfil=201;
									
			if ivPerfil is null or ivPerfil='' then
			
				LET ivPerfil=0;
			
			End if;
			--LET v_paso='Consul';
			LET cCodRet = '00000' ;		
			
			return cCodRet,ivPerfil;
			
			
		
	End;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaplazaclabe()

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Consultamos todas las plazas de la tabla
--Realizó: Richar 
--Fecha: 27/01/2015
--------------------------------------------------------------------													


 --DATOS A REGRESAR---	
	RETURNING CHAR(5) as codret, 	--codret
			  INTEGER as plaza,
			  char(60) as NomPlaza; --perfil
			  
	
--DEFINICION DE VARIABLES--			  
	DEFINE cCodRet 	CHAR(5);
	DEFINE iSqlErr 	INTEGER;	
	DEFINE iVPlaza  INTEGER;
	DEFINE cVNombre CHAR(60) ;	
    ---------------------------
	
	--Banderas
	DEFINE v_paso				varchar(50);
	
	--SET DEBUG FILE TO "/home/sysifx/sp_consultaplazaclabe.out";
	--TRACE ON;	

	set isolation to dirty read;
	SET LOCK MODE TO WAIT 3;	

	-- INICIO DEL PROCEDIMIENTO	
	BEGIN
	-- MANEJADOR DE ERRORES	
		ON EXCEPTION SET iSqlErr
			--LET cCodRet = v_paso;
			LET cCodRet = iSqlErr;
			Return cCodRet, 0,''; 
		END EXCEPTION;		
				
			
			FOREACH
			select 
			id_plazaclabe, 
			trim(nombre) || ' ' || trim(estado) as nombre 
			Into iVPlaza,cVNombre
			from si_plaza_clabe									
			order by nombre
			
			--LET v_paso='Consul';
			LET cCodRet = '00000' ;
			
			return cCodRet,iVPlaza,cVNombre WITH RESUME;
			
			End FOREACH;
			
			
		
	End;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultaplazaclabecc(vCSucursal char(4))

--------------------------------------------------------------------
--DOCUMENTACIÓN
--Consulta la plaza clabe que pertenece a una sucursal desde la bdicheq
--Realizó: Richar 
--Fecha: 28/01/2015
--------------------------------------------------------------------													


 --DATOS A REGRESAR---	
	RETURNING CHAR(5) as codret, 	--codret
			  INTEGER as idplazaClabe, --Id del catalogo de la plaza clabe
			  char(60) as NomPlaza; --perfil
			  
	
--DEFINICION DE VARIABLES--			  
	DEFINE cCodRet 	CHAR(5);
	DEFINE iSqlErr 	INTEGER;	
	DEFINE cIPlaza  INTEGER;	DEFINE cVNombre CHAR(60);	DEFINE cCPlazaCheq  Char(3);	
    ---------------------------
	
	
	--Banderas
	DEFINE v_paso				varchar(50);
	
	--SET DEBUG FILE TO "/home/sysifx/sp_consultaplazaclabecc.out";
	--TRACE ON;	
	
	LET cCPlazaCheq='';
	LET cIPlaza=0;

	set isolation to dirty read;
	SET LOCK MODE TO WAIT 3;	

	-- INICIO DEL PROCEDIMIENTO	
	BEGIN
	-- MANEJADOR DE ERRORES	
		ON EXCEPTION SET iSqlErr
			--LET cCodRet = v_paso;
			LET cCodRet = iSqlErr;
			Return cCodRet, 0,''; 
		END EXCEPTION;					
					
			select id_plazaclabe,SP.plazaclabe 
			into cIPlaza,cCPlazaCheq
			from
			si_sucursales SS inner join bdicheq:sc_plazaclabe SP
			on SS.sucursal=SP.sucursal
			where SS.sucursal=vCSucursal and SS.empresa='001';
			
			If ((cIPlaza<=0 or cIPlaza is null) and cCPlazaCheq<>'') then		
			
				select first 1 id_plazaclabe,trim(nombre) || ' ' || trim(estado) as nombre 
				INTO cIPlaza,cVNombre
				from si_plaza_clabe where no_plaza=cCPlazaCheq;
				
				Return '0000', cIPlaza,trim(cVNombre); 
				
			ELIF  (cIPlaza>0 and cCPlazaCheq<>'') THEN
			
				select id_plazaclabe,trim(nombre) || ' ' || trim(estado) as nombre 
				INTO cIPlaza,cVNombre
				from si_plaza_clabe where id_plazaclabe=cIPlaza;
				
				Return '0000', cIPlaza,trim(cVNombre); 				
				
			End if;
			
				Return '0001', 999,trim('Sin asignar');  --No encontro informacion
				
	End;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cons_sobrantes_caja_aud(pTipo 	 		  INTEGER,
								                       pCodigo   		  CHAR(4),
													   pEmpresa  		  CHAR(3),
													   pSucursal 		  CHAR(4),
													   pUsuario  		  CHAR(8),
													   pFechIni  		  CHAR(10),
													   pFechFin  		  CHAR(10),
													   pSkip     		  INTEGER,
													   pLimite 	 		  INTEGER,
													   pFecha_Rep 		  CHAR(10),
													   pImporte   		  CHAR(21),
													   pFecha_Eliminacion CHAR(10),
													   pNum_Transaccion   CHAR(4),
													   pOperador          CHAR(8),
													   pLinea			  INTEGER)
										  
	RETURNING CHAR(5) 	AS CodRet,
			  CHAR(10) 	AS Fecha,
			  CHAR(8) 	AS Usuario,
			  CHAR(45) 	AS Nombre,
			  CHAR(21) 	AS Importe,
			  CHAR(10) 	AS Fecha_de_Eliminacion,
			  CHAR(4) 	AS Transaccion,
			  CHAR(4) 	AS Sucursal,
			  CHAR(16)	AS Saldo,
			  CHAR(4) 	AS Trans_Suc,
			  INTEGER  	AS TotRows;
			  
--Definicion de Variables
DEFINE iSqlErr 			INTEGER;
DEFINE cCodRet 			CHAR(5);
DEFINE cFecha 			CHAR(10);
DEFINE cUsuario			CHAR(8);
DEFINE cNombreUsu		CHAR(45);
DEFINE cImporte			CHAR(21);
DEFINE cFechaElimina 	CHAR(10);
DEFINE cTransaccion 	CHAR(4);
DEFINE cSucursal		CHAR(4);
DEFINE cTransSuc		CHAR(4);
DEFINE cNombre			CHAR(45);
DEFINE cEjecutivo		CHAR(8);
DEFINE cFechaInicio		CHAR(10);
DEFINE cFechaFin		CHAR(10);
DEFINE cAnio 	 		CHAR(4);
DEFINE cMes 			CHAR(2);
DEFINE cDia 			CHAR(2);
DEFINE iDiasConsulta	INTEGER;
DEFINE iTotalRows		INTEGER;
DEFINE dFechaIni 		DATE;
DEFINE dFechaFin		DATE;
DEFINE dFechaHoy		DATE;
DEFINE dFecha_Rep       DATE;

DEFINE vEmpresa 		CHAR(3);
DEFINE vSucursal 		CHAR(4);
DEFINE vUsuario 		CHAR(8);
DEFINE vCodigo 			CHAR(4);
DEFINE cCodigo 			CHAR(4);
DEFINE vFechIni 		DATE;
DEFINE vFechFin 		DATE;


--Inicializacion de Variables
LET iSqlErr 		= 0;
LET cCodRet 		= '00000';
LET cFecha 			= '';
LET cUsuario		= '';
LET cNombreUsu 		= '';
LET cImporte 		= '';
LET cFechaElimina 	= '';
LET cTransaccion 	= '';
LET cSucursal 		= '';
LET cTransSuc 		= '';
LET cNombre 		= '';
LET cEjecutivo 		= '';
LET cAnio  			= '';
LET cMes  			= '';
LET cDia 			= '';
LET cFechaInicio	= '';
LET cFechaFin		= '';
LET iDiasConsulta 	= 0;
LET dFechaIni 		= DATE(1);
LET dFechaFin 		= DATE(1);
LET dFechaHoy 		= DATE(1);
LET iTotalRows 		= 0;
LET dFecha_Rep      = DATE(1);
--LET cuenta 		= '';

--SET DEBUG FILE TO "/informix/VJMP/sp_sobrantes"||"_"||""||pTipo||""||".out"; 
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet,'','','','','','','','','',iTotalRows;
			
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	LET cAnio = SUBSTRING(pFechIni FROM 1 FOR 4);
	LET cMes = SUBSTRING(pFechIni FROM 6 FOR 2) ;
	LET cDia = SUBSTRING(pFechIni FROM 9 FOR 2);
	LET dFechaIni = DATE(TRIM(cMes||'/'||cDia||'/'||cAnio));
			
	LET cAnio = SUBSTRING(pFechFin FROM 1 FOR 4);
	LET cMes =  SUBSTRING(pFechFin FROM 6 FOR 2) ;
	LET cDia = SUBSTRING(pFechFin FROM 9 FOR 2);
	LET dFechaFin = DATE(TRIM(cMes||'/'||cDia||'/'||cAnio));
			
	IF pTipo = 1 THEN
	
		IF (pEmpresa IS NULL OR NVL(pEmpresa,'') = '') OR (pUsuario IS NULL OR NVL(pUsuario,'') = '') OR
			(pCodigo IS NULL OR NVL(pCodigo,'') = '') OR (pSucursal IS NULL OR NVL(pSucursal,'') = '') THEN
			LET cCodRet = '00001';
		ELSE
			SELECT fecha_hoy 
			INTO dFechaHoy
			FROM bdinteg:"informix".si_fechas
			WHERE empresa = pEmpresa;
		
			LET iDiasConsulta = (dFechaHoy - 1) - dFechaIni;
		
			IF (iDiasConsulta > 365) OR (dFechaIni >= dFechaHoy OR dFechaFin >= dFechaHoy) THEN 
				--Sobrepasa el año de consulta o esta consultando la fecha hoy 
				LET cCodRet = '00002';
			END IF;	
		END IF;
		RETURN cCodRet,'','','','','','','','','',iTotalRows;
		
	ELIF pTipo = 2 THEN	 
	
		IF (pEmpresa IS NULL OR NVL(pEmpresa,'') = '') OR (pUsuario IS NULL OR NVL(pUsuario,'') = '') OR
			(pFechIni IS NULL OR NVL(pFechIni,'') = '') OR (pFechFin IS NULL OR NVL(pFechFin,'') = '') OR
			(pCodigo IS NULL OR NVL(pCodigo,'') = '') OR (pSucursal IS NULL OR NVL(pSucursal,'') = '') OR
			(pFecha_Rep IS NULL OR NVL(pFecha_Rep,'') = '') OR (pImporte IS NULL OR NVL(pImporte,'') = '') OR
			(pFecha_Eliminacion IS NULL OR NVL(pFecha_Eliminacion,'') = '') OR (pNum_Transaccion IS NULL OR NVL(pNum_Transaccion,'') = '') OR 
			(pOperador IS NULL OR NVL(pOperador,'') = '') OR (pLinea IS NULL OR NVL (pLinea, '') = '') THEN
			LET cCodRet = '00003';
		ELSE
			--PROCESO NUEVO INSERTADO PARA GUARDAR REGISTRO POR REGISTRO
			SELECT TRIM(nombre)
			INTO cNombre
			FROM bdinteg:"informix".si_ejecut 
			WHERE ejecutivo = pOperador;
			
			/*VJMP*/
			LET pNum_Transaccion = LPAD(TRIM(pNum_Transaccion), 4,'0');
			IF pNum_Transaccion = '0019' THEN
				LET pFecha_Eliminacion = DATE(1);
			END IF;
			 /*VJMP*/
			LET cMes  = SUBSTRING(pFecha_Rep FROM 1 FOR 2);
			LET cDia  = SUBSTRING(SUBSTRING(pFecha_Rep FROM 4 FOR 4) FROM 1 FOR 2);
			LET cAnio = SUBSTRING(pFecha_Rep FROM 7 FOR 10);		
			LET dFecha_Rep = DATE(cMes||'/'||cDia||'/'||cAnio);
			IF NOT EXISTS (SELECT cod_transacc FROM bdinteg:"informix".si_rptcaja_aud WHERE cod_transacc = pNum_Transaccion AND fecha = dFecha_Rep AND monto = pImporte AND sucursal = pSucursal AND usuario = pOperador AND fecha_eliminacion = pFecha_Eliminacion) THEN
				INSERT INTO bdinteg:"informix".si_rptcaja_aud (folio_oper,empresa,usuario,cod_transacc,sucursal,fecha,nombre_usuario,monto,fecha_eliminacion,transacc_suc,fecha_insert)
				VALUES (pUsuario,pEmpresa,pOperador,pNum_Transaccion,pSucursal,dFecha_Rep,cNombre,pImporte,pFecha_Eliminacion,pNum_Transaccion,today);
			END IF;
		END IF;	
		RETURN cCodRet,'','','','','','','','','',iTotalRows;
		
	ELIF pTipo = 3 THEN
		
		IF (pEmpresa IS NULL OR NVL(pEmpresa,'') = '') OR (pUsuario IS NULL OR NVL(pUsuario,'') = '') OR
			(pFechIni IS NULL OR NVL(pFechIni,'') = '') OR (pFechFin IS NULL OR NVL(pFechFin,'') = '') OR
			(pCodigo IS NULL OR NVL(pCodigo,'') = '') OR (pSucursal IS NULL OR NVL(pSucursal,'') = '') THEN
			LET cCodRet = '00004';
		ELSE
			/*VJMP*/
			LET vEmpresa = pEmpresa;
			LET	vSucursal = pSucursal;
			LET	vUsuario = pUsuario;
			LET	vCodigo = pCodigo;
			LET vFechIni = dfechaini;
			LET vFechFin = dfechafin;
			 /*VJMP*/
			SELECT COUNT(*)
			INTO iTotalRows
			FROM bdinteg:"informix".si_rptcaja_aud
			WHERE empresa = vEmpresa
				AND sucursal = vSucursal
				AND cod_transacc in (SELECT transaccion FROM bdinteg:"informix".si_transacciones_auditar_det WHERE codigo = vCodigo)
				AND fecha BETWEEN vFechIni  AND vFechFin;
			
			FOREACH
				SELECT SKIP pSkip LIMIT  pLimite 
				usuario,transaccion,sucursal,fecha,monto,transacc_suc,nombre_usuario,transacc_suc,--fecha_eliminacion
					Case 
						When fecha_eliminacion = date(1) Then
							null
					Else
						fecha_eliminacion
					End as fecha_eliminacion
				INTO cUsuario,cCodigo,cSucursal,cFecha,cImporte,cTransaccion,cNombreUsu,cTransSuc,cFechaElimina
				FROM bdinteg:"informix".si_rptcaja_aud
				WHERE empresa = vEmpresa
				AND sucursal = vSucursal
				AND cod_transacc in (SELECT transaccion FROM bdinteg:"informix".si_transacciones_auditar_det WHERE codigo = vCodigo)
				AND fecha BETWEEN vFechIni  AND vFechFin
				
				RETURN cCodRet,cFecha,cUsuario,cNombreUsu,cImporte,REPLACE(TRIM(cFechaElimina),'-','/'),LPAD(TRIM(cTransaccion),4,'0'),cSucursal,cImporte,LPAD(TRIM(cTransSuc),4,'0'),iTotalRows WITH RESUME;
			END FOREACH;
		
			LET pSkip = pSkip + pLimite ;
		
		END IF;	
		RETURN cCodRet,'','','','','','','','','',iTotalRows;
	ELSE
		LET cCodRet = '00005';
		RETURN cCodRet,'','','','','','','','','',iTotalRows;
	END IF;	
END;
END PROCEDURE
DOCUMENT
