CREATE PROCEDURE "informix".grabazonacallexasignar( pTipo SMALLINT, pCiudad SMALLINT, pClave INTEGER,
                                                    pDesc CHAR(30), pRumbo CHAR(40), pCodigoP INTEGER,
                                                    pMunicipio CHAR(27), pPoblacionZona CHAR(30), pUsuario CHAR(8) )
RETURNING CHAR(5);
------------------------------------------------------------------------
--Autor: Julio Cesar Polanco Inzunza
--Actividad: Graba en si_catzonas las zonas que tenian clave por asignar
--Graba en si_catcalles las calles que tenian clave por asignar
--Si el SP regresa 001 es que no tiene los parametros requeridos para grabar

-- ModIFico: José de Jesús Almeida Inzuna
-- Fecha: 5 de enero de 2010
-- Se agregan los campos "f_inserta", "codigopostalzona", "municipiozona", "poblacionzona" a insertar
-- en "si_catzonas" por peticion de el cliente.
-- Se verIFica que la zona o calle no exISta previamente y no pueda ser insertada.

-- ModIFico: José de Jesús Almeida Inzuna
-- Fecha: 7 de enero de 2010
-- Se agrega la validacion al campo nombrezona, para cuANDo este sea 'UNIDAD HABITACIONAL' o 'CONJUNTO HABITACIONAL'
-- Se marque el campo marcaunidadhabitacional con un 'S'

-- ModIFico: José de Jesús Almeida
-- Fecha: 4 de febrero de 2010
-- Se modIFica para que al obtener el tipo de asenta 
-- Solo filtre por el codigo postal y su descripcion.

-- ModIFico: Bernardo Carlos Báez Gonzalez
-- Fecha: 18 de Marzo de 2010
-- Se modIFica para que el campo marcaunidadhabitacional se guarde con 'N' si no es 
-- 'UNIDAD HABITACIONAL' o 'CONJUNTO HABITACIONAL'

--ModIFicó: Abigail Vasavilbazo Cañedo
--Fechas: Mayo 2010
--Versión: 20100519.1340
--Descripción: Se modIFicó para que guardara el usuario que realizaba el alta de la zona en la si_catzonas "usr_modIFica"

--ModIFicó: Saúl Ivanhoe Valdespino Hernández
--Fecha: 26 de Agosto 2010
--Descripción: Se modIFicó para que guardara la fecha y el usuario que realizaba el alta de la calle en la si_catcalles

--Modificó: Felipe urias
--Fecha: 26 de Octubre 2011
--Descripción: Se modificó para agregar una tercer tipo de ejecucion, para actualizar zonas de la si_catzonas.
------------------------------------------------------------------------

--Declaracion de variables
DEFINE chrCodRet			CHAR(5);
DEFINE intCodRet            INTEGER;
DEFINE intNumZona           INTEGER;
DEFINE intNumCobranza       SMALLINT;
DEFINE intCentro            INTEGER;
DEFINE vMarca               CHAR(6);
DEFINE v_d_Tipo_Asenta      CHAR(25);
DEFINE dFechaHoy            DATE;
DEFINE vEmpresa             CHAR(3);

--debug flag
--SET DEBUG FILE TO "/tmp/grabazonacallexasignar.out";
--TRACE ON;

BEGIN

	ON EXCEPTION SET intCodRet
		IF intCodRet <> 0 THEN
			LET chrCodRet=intCodRet;
			RETURN chrCodRet;
		END IF;
    END EXCEPTION;
	
	SET ISOLATION TO CURSOR STABILITY;
	SET LOCK MODE TO WAIT 10;

LET chrCodRet = '000';
LET intCodRet = 0;
LET intNumZona  = 0;
LET intNumCobranza = 0;
LET intCentro = 0;
LET vMarca = 'N';
LET v_d_Tipo_Asenta = '';
LET dFechaHoy='';
LET vEmpresa = '001';

    SELECT {+INDEX(bdinteg:si_fechas idx_si_fechas)} fecha_hoy
    INTO dFechaHoy
    FROM bdinteg:"informix".si_fechas
    WHERE empresa = vEmpresa;
	
	IF pTipo = 1 THEN

	    IF ( pCiudad IS NOT NULL AND pClave IS NOT NULL
	         AND pDesc IS NOT NULL AND pRumbo IS NOT NULL AND
	        pCodigoP IS NOT NULL AND pMunicipio IS NOT NULL AND
	        pPoblacionZona IS NOT NULL ) THEN
	    
			IF NOT EXISTS(SELECT numerociudad FROM bdinteg:"informix".si_catzonas WHERE 
				numerociudad = pCiudad AND UPPER(nombrezona) = UPPER(pDesc) 
				AND UPPER(poblacionzona) = UPPER(pPoblacionZona) AND UPPER(municipiozona) = UPPER(pMunicipio)
				AND codigopostalzona = pCodigoP ) THEN

				SELECT NVL(numerocobranzas,0), NVL(centro,0) INTO intNumCobranza, intCentro
				FROM bdinteg:"informix".si_catzonas
				WHERE numerociudad = pCiudad AND numerocolonia =
				( SELECT MIN(numerocolonia) FROM bdinteg:si_catzonas
				WHERE NVL(numerocobranzas, 0) > 0 AND NVL(centro, 0) > 0 AND NVL(jefegrupozona, 0) > 0
				AND NVL(supervISorzona, 0) > 0 AND numerociudad = pCiudad AND numerocolonia <> 8000 );

				SELECT FIRST 1 d_tipo_asenta 
				INTO   v_d_Tipo_Asenta
				FROM   bdinteg:"informix".si_catsepomex   
				WHERE  d_codigo = CAST(pCodigoP AS CHAR(5)) AND UPPER(TRIM(d_asenta)) = UPPER(TRIM(pDesc)); 
				--AND    UPPER(TRIM(d_mnpio)) = UPPER(TRIM(pMunicipio)) AND UPPER(TRIM(d_ciudad)) = UPPER(TRIM(pPoblacionZona));

				IF (UPPER(TRIM(v_d_Tipo_Asenta)) = 'UNIDAD HABITACIONAL' OR  UPPER(TRIM(v_d_Tipo_Asenta)) = 'CONJUNTO HABITACIONAL') THEN
				LET  vMarca = 'S';
				END IF;
	
				INSERT INTO bdinteg:"informix".si_catzonas ( numerociudad,numerocolonia,nombrezona,rumbozona,numerocobranzas,centro,f_inserta, codigopostalzona, municipiozona, poblacionzona, marcaunidadhabitacional, usr_modIFica )
				VALUES ( pCiudad, pClave, UPPER(pDesc), pRumbo, intNumCobranza, intCentro, CURRENT, pCodigoP, UPPER(pMunicipio), UPPER(pPoblacionZona), vMarca, pUsuario );

			ELSE
			  LET chrCodRet = '002';        
			END IF;             
		ELSE
			LET chrCodRet = '001';
	    END IF;
	   
	ELIF pTipo = 2 THEN

		IF pClave IS NOT NULL AND pDesc IS NOT NULL THEN
			SELECT MAX(numerocalle) + 1 INTO pClave FROM bdinteg:"informix".si_catcalles;
			IF NOT EXISTS (SELECT numerocalle FROM bdinteg:"informix".si_catcalles WHERE nombrecalle = pDesc) THEN
				INSERT INTO bdinteg:"informix".si_catcalles ( numerocalle,nombrecalle, f_inserta, usr_modIFica ) VALUES ( pClave,pDesc,dFechaHoy,pUsuario );
			ELSE
				LET chrCodRet = '003';
			END IF;
		ELSE
			LET chrCodRet = '001';
		END IF;
		
	ELIF pTipo = 3 THEN
	
		IF ( pCiudad IS NOT NULL AND pClave IS NOT NULL AND pDesc IS NOT NULL AND pRumbo IS NOT NULL AND
	    pCodigoP IS NOT NULL AND pMunicipio IS NOT NULL AND pPoblacionZona IS NOT NULL ) THEN
			
			IF EXISTS(SELECT numerociudad FROM bdinteg:"informix".si_catzonas WHERE numerociudad = pCiudad AND
			numerocolonia = pClave ) THEN
			
				UPDATE bdinteg:"informix".si_catzonas SET municipiozona = UPPER(pMunicipio), codigopostalzona = pCodigoP,
				poblacionzona = UPPER(pPoblacionZona), rumbozona = UPPER(pRumbo), f_modifica = dFechaHoy, usr_modifica = pUsuario
				WHERE numerociudad = pCiudad AND numerocolonia = pClave;
				
			ELSE
				LET chrCodRet = '002';
			END IF;	 
		ELSE
			LET chrCodRet = '001';	
		END IF;
		
	END IF;

RETURN chrCodRet;
END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_recalculo_estadisticas_sms(dfecha_ini DATE, dfecha_fin DATE)
RETURNING CHAR(6), CHAR(100);
--VARIABLES DE ERROR
DEFINE cVarDataErr      	CHAR(100);
DEFINE iSqlErr          	INTEGER;
DEFINE iSamErr          	INTEGER;
DEFINE vCodRet          	CHAR(6);
--DEFINICION DE VARIABLES			
DEFINE isms_val				INTEGER;
DEFINE isms_total			INTEGER;
DEFINE isms_no_val			INTEGER;
DEFINE ivalidos				INTEGER;
DEFINE iinvalidos			INTEGER;
DEFINE isin_validar			INTEGER;
--ASIGNACION DE VARIABLES
LET isms_val=0;				
LET isms_total=0;	
LET isms_no_val=0;	
LET ivalidos=0;			
LET iinvalidos=0;
LET isin_validar=0;

--ASIGNACION DE VARIABLES ERROR
LET vCodRet = '000000';
LET cVarDataErr = 'EL RECALCULO DE ESTADISTICAS DE SMS FUE REALIZADO SATISFACTORIAMENTE';
--SET DEBUG FILE TO '/informix/Ingrid/sp_recalculo_estadisticas_sms.out';
--TRACE ON;
BEGIN
	--Manejo del error
	ON EXCEPTION SET iSqlErr, iSamErr, cVarDataErr
        IF iSqlErr <> 0 THEN
			LET vCodret=iSqlErr;			
			ROLLBACK;
						
			RETURN vCodret, iSamErr || ' ' ||cVarDataErr;
		END IF;
	END EXCEPTION;
			
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;	

	
--Estadisticas de SMS
	BEGIN WORK;
		WHILE dfecha_ini <= dfecha_fin
			--SI_TELEFONOS 
			SELECT COUNT(*) AS sms_val
			INTO isms_val 
			FROM bdinteg:si_telefonos WHERE telefono IN (
			SELECT celular_alterno 
			FROM bdimnsj:"informix".mnsjr_trx_online_his 
			WHERE id_mensaje = 'OFI_AVSMS' 
			AND fecha_hora_registro::DATE = dfecha_ini)
			AND tipo_tel='2' AND verificado='V' AND fecha_hora::DATE = dfecha_ini;		
				
			--SI_TELEFONOS_ACTUAL		
			SELECT COUNT(*) AS sms_total
			INTO isms_total 
			FROM bdinteg:si_telefonos_actual WHERE telefono IN (
			SELECT celular_alterno 
			FROM bdimnsj:"informix".mnsjr_trx_online_his 
			WHERE id_mensaje = 'OFI_AVSMS' 
			AND fecha_hora_registro::DATE = dfecha_ini) 
			AND cofetel='V' AND tipo_tel='2' AND fecha_hora::DATE=dfecha_ini; 
			
			LET isms_no_val = isms_total - isms_val;		
			--INSERTA EN LA TABLA DE SMS.
			UPDATE bdinteg:"informix".si_estadistica_sms 
			SET sms_val= isms_val, sms_no_val= isms_no_val, total= isms_total, porc_val = NVL(((NULLIF(isms_val,0)/ NULLIF(isms_total,0))*100),0) , porc_no_val = NVL(((NULLIF(isms_no_val,0)/ NULLIF(isms_total,0))*100),0)
			WHERE fecha = dfecha_ini;
			LET dfecha_ini = dfecha_ini + 1 UNITS DAY;
		END WHILE;
	
	COMMIT WORK;
	
	RETURN vCodRet,cVarDataErr;		
END;
END PROCEDURE
DOCUMENT
'REALIZA:Recalculo de estadisticas de sms',
'EQUIPO:Análisis y diseño de Mannto.4',
'FECHA:02/16/2015',
'SOLICITA:José Ángel López Adams',
'BASE DE DATOS:Bdinteg',
'MODIFICO: Ingrid Pamela Cázarez Villegas',
'DESCRIPCION: Se recalculan las estadisticas de sms de la tabla si_estadistica_sms en el rango de fechas recibido como parametros';

CREATE PROCEDURE "informix".sp_refusiona_telefonos()
RETURNING CHAR(6), CHAR(100);
	DEFINE cCodRet			CHAR(6);
	DEFINE cErrorSQL		CHAR(100);
	DEFINE i_SqlError		INTEGER;
	DEFINE i_iSamError		INTEGER;
	
	DEFINE cCliente_tit		CHAR(20);
	DEFINE cCliente_tras	CHAR(20);
		
	DEFINE iContador		INTEGER;
	DEFINE iContador2		INTEGER;
	DEFINE iMaxSecuencia	INTEGER;
	DEFINE iTrans_abierta	INTEGER;
	DEFINE iTotalReg		INTEGER;
	DEFINE iProcesados		INTEGER;
	DEFINE MAXTRANSACCION	INTEGER;
	
	DEFINE iROWID			INTEGER;
	DEFINE iROWDIDAux		INTEGER;
	DEFINE cTelefono		CHAR(20);
	DEFINE cTelefonoAux		CHAR(20);
	DEFINE iSecuencia		INTEGER;
	DEFINE iSecuenciaAux	INTEGER;
	DEFINE cTipo_tel		CHAR(1);
	DEFINE cTipo_telAux		CHAR(1);
	DEFINE dFecha_Proceso	DATE;
	
	DEFINE c_detalle_mov	CHAR(200);
	
	DEFINE dtFechaInsercion	DATETIME HOUR TO FRACTION;
	
	LET iContador = 0;
	LET iContador2 = 0;
	LET iMaxSecuencia = 0;
	LET cCliente_tit = '';
	LET cCliente_tras = '';
	LET cCodRet = '000000';
	LET MAXTRANSACCION = 3000;	
	LET iProcesados = 0;
	LET iTotalReg= 0;
	LET iTrans_abierta= 0;
	LET cErrorSQL = 'PROCESO TERMINADO SATISFACTORIAMENTE';
	
	--SET DEBUG FILE TO "/informix/josea/sp_refusiona_direcciones.out";
	--TRACE ON;	
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		ON EXCEPTION SET i_SqlError,i_iSamError, cErrorSQL
			IF i_SqlError <> 0 THEN				
				IF iTrans_abierta = 1 THEN
					ROLLBACK WORK;
				END IF;
				
				LET cCodRet = i_SqlError;
				SELECT DBINFO('utc_to_datetime',sh_curtime) INTO dtFechaInsercion FROM sysmaster:"informix".sysshmvals;
				
				LET c_detalle_mov=i_SqlError||'|'||i_iSamError;
				
				INSERT INTO log_fusionclientes(proceso,tabla,cliente_tit,cliente_tras,detalle_mov,fecha_hora,user_insert,fecha_insert)
				VALUES ("TELEFONOS","si_telefonos",cCliente_tit,cCliente_tras,c_detalle_mov,dtFechaInsercion,USER,dtFechaInsercion::DATE);
				
				IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
					DROP TABLE tmpfusionados;
				END IF;	
				
				RETURN cCodRet, cErrorSQL;
			END IF;
		END EXCEPTION;
		
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
			DROP TABLE tmpfusionados;
		END IF;	
		
		SELECT cliente_tit, cliente_tras, fecha_proceso
		FROM bdinteg:si_fusionaut
		WHERE estatus = '1'
		AND cliente_tit IN(SELECT numcte FROM bdinteg:si_telefonos_actual WHERE status_tel = 'C')
		UNION ALL
		SELECT cliente_titular AS cliente_tit, cliente_traspasar AS cliente_tras, fecha_fusion::DATE AS fecha_proceso
		FROM bdinteg:si_fusbitacora
		WHERE fusion = 'SI'
		AND cliente_titular IN(SELECT numcte FROM bdinteg:si_telefonos_actual WHERE status_tel = 'C')
		INTO TEMP tmpfusionados WITH NO LOG;
		
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
			SELECT COUNT(cliente_tit) INTO iTotalReg FROM tmpfusionados;
		END IF;	
				
		IF iTotalReg > 0 THEN		
			FOREACH WITH HOLD
				SELECT DISTINCT cliente_tit, cliente_tras, fecha_proceso
				INTO cCliente_tit, cCliente_tras, dFecha_Proceso
				FROM tmpfusionados
				ORDER BY fecha_proceso
				
				DELETE FROM bdinteg:si_fustelefonos2 
					WHERE numcte = cCliente_tit;
				
				LET iContador = 0;
				LET iContador2 = 0;			
				
				IF iProcesados = 0 THEN
					BEGIN WORK;
					LET iTrans_abierta = 1;
				END IF;				
				
				IF EXISTS (SELECT numcte FROM bdinteg:si_fustelefonos WHERE numcte = cCliente_tras) THEN				
					
					SELECT NVL(MAX(secuencia),0) 
					INTO iMaxSecuencia 
					FROM bdinteg:si_fustelefonos
					WHERE numcte = cCliente_tras;
					
					IF iMaxSecuencia > 0 THEN
						FOREACH
							SELECT ROWID, telefono,tipo_tel,secuencia
							INTO iROWID, cTelefono,cTipo_tel,iSecuencia
							FROM bdinteg:si_fustelefonos
							WHERE numcte = cCliente_tras 
							ORDER BY secuencia
							
							IF iContador = 0 THEN						
								LET cTelefonoAux = cTelefono;
								LET cTipo_telAux = cTipo_tel;
								LET iSecuenciaAux = iSecuencia;
								
								LET iContador = iContador + 1;								
								LET iROWDIDAux = iROWID;
								
								INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
								SELECT empresa, cCliente_tit AS numcte,telefono,tipo_tel,'A',secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel,verificado, marcatel, fecha_actualiza
								FROM bdinteg:si_fustelefonos
								WHERE ROWID = iROWDIDAux
									AND numcte = cCliente_tras 
									AND secuencia = iSecuencia;

							ELSE
								LET cTelefonoAux = cTelefono;
								LET cTipo_telAux = cTipo_tel;
								LET iSecuenciaAux = iSecuencia;
								LET iROWDIDAux = iROWID;
								
								LET iContador2 = iContador2 + 1;

								IF NOT EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit AND telefono = cTelefono AND tipo_tel = cTipo_tel ) THEN
									IF EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit  AND tipo_tel = cTipo_tel) THEN
										UPDATE bdinteg:si_fustelefonos2 SET status_tel = 'C' 
										WHERE numcte = cCliente_tit 
											AND tipo_tel = cTipo_tel;									
									END IF;
									
									INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
									SELECT empresa, cCliente_tit AS numcte,telefono,tipo_tel,'A',(SELECT NVL(MAX(secuencia),0)+1 FROM si_fustelefonos2 WHERE numcte = cCliente_tit ) AS secuencia, extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza       
									FROM bdinteg:si_fustelefonos
									WHERE ROWID = iROWDIDAux
										AND numcte = cCliente_tras 
										AND secuencia = iSecuencia;					
								END IF;

								LET iContador = iContador + 1;
							END IF; --If contador
						END FOREACH; --Consulta telefonos cCliente_tras
						
						LET iContador = 0;
						LET iContador2 = 0;
						
						SET ISOLATION TO DIRTY READ;
						
						FOREACH
							SELECT ROWID, telefono,tipo_tel,secuencia
							INTO iROWID, cTelefono,cTipo_tel,iSecuencia
							FROM bdinteg:si_fustelefonos
							WHERE numcte = cCliente_tit 
							ORDER BY secuencia
							
							IF iContador=0 THEN
								LET iROWDIDAux = iROWID;
								LET cTelefonoAux = cTelefono;
								LET cTipo_telAux = cTipo_tel;
								LET iSecuenciaAux = iSecuencia;								
								
								LET iContador = iContador + 1;
								
								IF NOT EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit AND telefono = cTelefono AND tipo_tel = cTipo_tel) THEN
									IF EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit  AND tipo_tel = cTipo_tel) THEN
										UPDATE bdinteg:si_fustelefonos2 SET status_tel = 'C' 
										WHERE numcte = cCliente_tit 
											AND tipo_tel = cTipo_tel;
									END IF;
								
									INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
									SELECT empresa,numcte,telefono,tipo_tel,'A',(SELECT NVL(MAX(secuencia),0)+1 FROM si_fustelefonos2 WHERE numcte = cCliente_tit ) AS secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza    
									FROM bdinteg:si_fustelefonos
									WHERE ROWID = iROWID
									AND numcte = cCliente_tit 
									AND secuencia = iSecuencia;								
								END IF;
							ELSE
								LET cTelefonoAux = cTelefono;
								LET cTipo_telAux = cTipo_tel;
								LET iSecuenciaAux = iSecuencia;
								LET iROWDIDAux = iROWID;
								
								LET iContador=iContador + 1;
								
								IF NOT EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit AND telefono = cTelefono AND tipo_tel = cTipo_tel) THEN
									IF EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit  AND tipo_tel = cTipo_tel) THEN
										UPDATE bdinteg:si_fustelefonos2 SET status_tel = 'C' 
										WHERE numcte = cCliente_tit 
											AND tipo_tel = cTipo_tel;
									END IF;

									INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
									SELECT empresa,numcte,telefono,tipo_tel,'A',(SELECT NVL(MAX(secuencia),0)+1 FROM si_fustelefonos2 WHERE numcte = cCliente_tit ) AS secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza         
									FROM bdinteg:si_fustelefonos
									WHERE ROWID = iROWDIDAux 
										AND numcte = cCliente_tit 
										AND secuencia = iSecuencia;
									
									LET iContador2 = iContador2 + 1;
								END IF;
							 END IF;
						END FOREACH;
						
						SET ISOLATION TO DIRTY READ;
						
						--Para considerar nuevos telefonos en si_telefonos que no se encuentren en si_fustelefonos
						FOREACH
							SELECT telefono,tipo_tel,secuencia
							INTO cTelefono, cTipo_tel, iSecuencia
							FROM bdinteg:si_telefonos
							WHERE numcte = cCliente_tit 
														
							IF NOT EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit AND telefono = cTelefono AND tipo_tel = cTipo_tel) THEN
								IF EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit  AND tipo_tel = cTipo_tel) THEN
									UPDATE bdinteg:si_fustelefonos2 SET status_tel = 'C' 
									WHERE numcte = cCliente_tit 
										AND tipo_tel = cTipo_tel;
								END IF;
								
								INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
								SELECT empresa,numcte,telefono,tipo_tel,'A',(SELECT NVL(MAX(secuencia),0)+1 FROM si_fustelefonos2 WHERE numcte = cCliente_tit ) AS secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza         
								FROM bdinteg:si_telefonos
								WHERE numcte = cCliente_tit 
									AND telefono = cTelefono 
									AND secuencia = iSecuencia;
							END IF;
						END FOREACH;
						
						DELETE FROM bdinteg:si_telefonos 
							WHERE numcte = cCliente_tit;
							
						DELETE FROM bdinteg:si_telefonos_actual 
							WHERE numcte = cCliente_tit;
						
						INSERT INTO bdinteg:si_telefonos(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
						SELECT empresa,numcte,telefono,tipo_tel,status_tel, secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza         
						FROM bdinteg:si_fustelefonos2
						WHERE numcte = cCliente_tit ;
						
						DELETE FROM si_fustelefonos2 WHERE numcte = cCliente_tit;
												
					END IF;	--Maxima Secuencia
				ELSE
					FOREACH 
						SELECT telefono,tipo_tel,secuencia
						INTO cTelefono, cTipo_tel, iSecuencia
						FROM bdinteg:si_telefonos
						WHERE numcte = cCliente_tit 
						
						IF NOT EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit AND telefono = cTelefono AND tipo_tel = cTipo_tel) THEN
							IF EXISTS (SELECT telefono FROM bdinteg:si_fustelefonos2 WHERE numcte = cCliente_tit  AND tipo_tel = cTipo_tel) THEN
								UPDATE bdinteg:si_fustelefonos2 SET status_tel = 'C' 
								WHERE numcte = cCliente_tit 
									AND tipo_tel = cTipo_tel;
							END IF;
							
							INSERT INTO bdinteg:si_fustelefonos2(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
							SELECT empresa,numcte,telefono,tipo_tel,'A',(SELECT NVL(MAX(secuencia),0)+1 FROM si_fustelefonos2 WHERE numcte = cCliente_tit ) AS secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza         
							FROM bdinteg:si_telefonos
							WHERE numcte = cCliente_tit 
								AND telefono = cTelefono 
								AND secuencia = iSecuencia;
						END IF;
					END FOREACH;	
					DELETE FROM bdinteg:si_telefonos 
						WHERE numcte = cCliente_tit;
						
					DELETE FROM bdinteg:si_telefonos_actual 
						WHERE numcte = cCliente_tit;
					
					INSERT INTO bdinteg:si_telefonos(empresa, numcte, telefono, tipo_tel, status_tel, secuencia, extension, carrier, canal, contacto, cofetel, fecha_hora, user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza)
					SELECT empresa,numcte,telefono,tipo_tel,status_tel, secuencia,extension,carrier,canal,contacto,cofetel,fecha_hora,user_insert, movil_fijo, status_stel, verificado, marcatel, fecha_actualiza         
					FROM bdinteg:si_fustelefonos2
					WHERE numcte = cCliente_tit ;
					
					DELETE FROM si_fustelefonos2 WHERE numcte = cCliente_tit;
				END IF; --If exists cCliente_tras
												
				LET iProcesados = iProcesados + 1;
				
				IF iProcesados >= MAXTRANSACCION THEN
					LET iProcesados = 0;
					COMMIT WORK;
					LET iTrans_abierta = 0;
				END IF;
			END FOREACH;
			
			IF iProcesados < MAXTRANSACCION AND  iTotalReg > 0 THEN
				IF iProcesados > 0 THEN
					COMMIT WORK;
					LET iTrans_abierta = 0;
				END IF;
				LET iProcesados = 0;
			END IF;
		END IF;
		
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
			DROP TABLE tmpfusionados;
		END IF;	

		RETURN cCodRet, cErrorSQL;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_catalogociudad(pIdUsuario CHAR(8), pIdFuncion CHAR(10), pEstado CHAR(2), pTipoConsulta SMALLINT, pConsulta CHAR(30), pRegistros INTEGER, pRecuperacion INTEGER)
        RETURNING CHAR(5) AS codret,
                CHAR(5) AS clave_ciudad,
                CHAR(60) AS nombre_ciudad,
                SMALLINT AS clave_ciudad_coppel;
                
        DEFINE cCodRet CHAR(5);
        DEFINE iSqlErr INTEGER;
        DEFINE cIdCiudad CHAR(5);
        DEFINE cNombreCiudad CHAR(60);
        DEFINE iIdCiudadCoppel SMALLINT;
        DEFINE iExiste INTEGER;
        DEFINE iNoRegistros INTEGER;
        
        LET cCodRet = '00000';
        LET iSqlErr = 0;
        LET cIdCiudad = '';
        LET cNombreCiudad = '';
        LET iIdCiudadCoppel = NULL;
        LET iExiste = 0;
        LET iNoRegistros = 0;
        
        BEGIN
			ON EXCEPTION SET iSqlErr
					LET cCodRet = iSqlErr;
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END EXCEPTION;
			
			----SET DEBUG FILE TO '/tmp/mfinis/sp_catalogociudad.out';
			----TRACE ON;
			
			IF pIdUsuario = '' OR pIdFuncion = '' OR pEstado = '' OR pTipoConsulta IS NULL OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
					LET cCodRet = '00003';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END IF;
			
			-- VALIDACIÃN DE LOS PARAMETROS DE PAGINACIÃN
			IF pRegistros < 0 THEN
					LET cCodRet = '00098';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END IF;
			
			IF pTipoConsulta NOT IN (1,2) THEN
					LET cCodRet = '00044';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END IF;
			
			IF pTipoConsulta = 2 AND pConsulta = '' THEN
					LET cCodRet = '00003';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END IF;
			IF pIdFuncion in ('CLI251', 'CLI252', 'CLI253', 'CLI261', 'CLI262', 'CLI263') THEN
				IF pEstado = '01' THEN
						LET pEstado = '9';
				ELIF pEstado = '02' THEN
						LET pEstado = '4';
				ELIF pEstado = '03' THEN
						LET pEstado = '19';
				ELIF pEstado = '04' THEN
						LET pEstado = '29';
				ELIF pEstado = '05' THEN
						LET pEstado = '6';
				ELIF pEstado = '06' THEN
						LET pEstado = '13';
				ELIF pEstado = '07' THEN
						LET pEstado = '27';
				ELIF pEstado = '08' THEN
						LET pEstado = '7';
				ELIF pEstado = '09' THEN
						LET pEstado = '25';
				ELIF pEstado = '10' THEN
						LET pEstado = '5';
				ELIF pEstado = '11' THEN
						LET pEstado = '14';
				ELIF pEstado = '12' THEN
						LET pEstado = '16';
				ELIF pEstado = '13' THEN
						LET pEstado = '22';
				ELIF pEstado = '14' THEN
						LET pEstado = '10';
				ELIF pEstado = '15' THEN
						LET pEstado = '26';
				ELIF pEstado = '16' THEN
						LET pEstado = '12';
				ELIF pEstado = '17' THEN
						LET pEstado = '21';
				ELIF pEstado = '18' THEN
						LET pEstado = '1';
				ELIF pEstado = '19' THEN
						LET pEstado = '20';
				ELIF pEstado = '20' THEN
						LET pEstado = '31';
				ELIF pEstado = '21' THEN
						LET pEstado = '18';
				ELIF pEstado = '22' THEN
						LET pEstado = '33';
				ELIF pEstado = '23' THEN
						LET pEstado = '28';
				ELIF pEstado = '24' THEN
						LET pEstado = '11';
				ELIF pEstado = '25' THEN
						LET pEstado = '2';
				ELIF pEstado = '26' THEN
						LET pEstado = '3';
				ELIF pEstado = '27' THEN
						LET pEstado = '24';
				ELIF pEstado = '28' THEN
						LET pEstado = '17';
				ELIF pEstado = '29' THEN
						LET pEstado = '32';
				ELIF pEstado = '30' THEN
						LET pEstado = '23';
				ELIF pEstado = '31' THEN
						LET pEstado = '30';
				ELIF pEstado = '32' THEN
						LET pEstado = '15';
				END IF;
					
				SET ISOLATION TO DIRTY READ;
				-- VALIDAMOS QUE LA TABLA TENGA DATOS
				SELECT COUNT(*)
				INTO iExiste
				FROM bdinteg:si_catciudades
				WHERE numeroestado = pEstado;

				IF iExiste = 0 THEN
						LET cCodRet = '00017';
						RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
				END IF;
				
				IF pTipoConsulta = 1 THEN -- Tipo de consulta general
					FOREACH
						SELECT SKIP pRegistros FIRST pRecuperacion numerociudad, nombreciudad, numerociudadcoppel
						INTO cIdCiudad, cNombreCiudad, iIdCiudadCoppel
						FROM bdinteg:si_catciudades 
						WHERE  numerociudad IS NOT NULL AND 
                                                       nombreciudad != '' AND 
                                                       numeroestado = pEstado
						ORDER BY nombreciudad ASC
						LET iNoRegistros = iNoRegistros + 1;
						--RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel WITH RESUME;
						RETURN cCodRet, cIdCiudad, cNombreCiudad, cIdCiudad::SMALLINT WITH RESUME;
					END FOREACH;
							
					IF iNoRegistros = 0 AND pRegistros = 0 THEN
						LET cCodRet = '00017';
						RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
					END IF;
					
					IF iNoRegistros = 0 AND pRegistros > 0 THEN
						LET cCodRet = '1001';
						RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
					END IF;
				ELIF pTipoConsulta = 2 THEN
					FOREACH
						SELECT SKIP pRegistros FIRST pRecuperacion numerociudad, nombreciudad, numerociudadcoppel
						INTO cIdCiudad, cNombreCiudad, iIdCiudadCoppel
						FROM bdinteg:si_catciudades 
						WHERE numerociudad IS NOT NULL AND 
                                                      nombreciudad LIKE '%' || TRIM(pConsulta) || '%' AND
                                                      numeroestado = pEstado 
						ORDER BY nombreciudad ASC
						
						LET iNoRegistros = iNoRegistros + 1;
						--RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel WITH RESUME;
						RETURN cCodRet, cIdCiudad, cNombreCiudad, cIdCiudad::SMALLINT WITH RESUME;
					END FOREACH;
							
					IF iNoRegistros = 0 AND pRegistros = 0 THEN
						LET cCodRet = '00017';
						RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
					END IF;
					
					IF iNoRegistros = 0 AND pRegistros > 0 THEN
						LET cCodRet = '1001';
						RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
					END IF;
				END IF;
			ELSE
			SET ISOLATION TO DIRTY READ;
			-- VALIDAMOS QUE LA TABLA TENGA DATOS
			SELECT COUNT(*)
			INTO iExiste
			FROM bdinteg:si_ciudades;
			
			IF iExiste = 0 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
			END IF;
			
			IF pTipoConsulta = 1 THEN -- Tipo de consulta general
				FOREACH
				SELECT SKIP pRegistros FIRST pRecuperacion ciudad, nombre, ciudad_coppel
				INTO cIdCiudad, cNombreCiudad, iIdCiudadCoppel
				FROM bdinteg:si_ciudades 
				WHERE pais = '001' AND 
                                      estado = pEstado AND 
                                      ciudad != '' AND
                                      nombre != '' 
				ORDER BY nombre ASC
				
				LET iNoRegistros = iNoRegistros + 1;
				RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel WITH RESUME;
				END FOREACH;
				
				IF iNoRegistros = 0 AND pRegistros = 0 THEN
					LET cCodRet = '00017';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
				END IF;
				
				IF iNoRegistros = 0 AND pRegistros > 0 THEN
					LET cCodRet = '1001';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
				END IF;
			ELIF pTipoConsulta = 2 THEN
				FOREACH
				SELECT SKIP pRegistros FIRST pRecuperacion ciudad, nombre, ciudad_coppel 
				INTO cIdCiudad, cNombreCiudad, iIdCiudadCoppel
				FROM bdinteg:si_ciudades 
				WHERE pais = '001' AND 
                                      estado = pEstado AND 
                                      ciudad != '' AND
				      nombre LIKE '%' || TRIM(pConsulta) || '%' 
				ORDER BY nombre ASC
				
				LET iNoRegistros = iNoRegistros + 1;
				RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel WITH RESUME;
				END FOREACH;
				
				IF iNoRegistros = 0 AND pRegistros = 0 THEN
					LET cCodRet = '00017';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
				END IF;
				
				IF iNoRegistros = 0 AND pRegistros > 0 THEN
					LET cCodRet = '1001';
					RETURN cCodRet, cIdCiudad, cNombreCiudad, iIdCiudadCoppel;
				END IF;
			END IF;
		END IF;
        END;
                
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 30/10/2013",
"DESCRIPCION: Consulta el catalogo de las ciudades",
"FECHA: 25/09/2014",
"DESCRIPCION: Se cambia el numero de ciudad coppel por el de ciudad para que funcione correctamente el SP";

CREATE PROCEDURE "c92357113".sp_alfanumerico (cCadena VARCHAR(255))
RETURNING VARCHAR(255) AS ESCRITURA;

DEFINE cCodRet			CHAR(6);
DEFINE cLetra			CHAR(10);
DEFINE cEscritura		VARCHAR(255);
DEFINE iSqlErr			SMALLINT;
DEFINE iCantVueltas		SMALLINT;
DEFINE iNumCaracter		SMALLINT;

LET cCodRet				= '000000';
LET cLetra				= '';
LET cEscritura			= '';
LET iSqlErr				= 0;
LET iCantVueltas		= 0;
LET iNumCaracter		= 0;


BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr != 0 THEN
			LET cCodRet= iSqlErr;
			
			RETURN cEscritura;
		END IF;
	END EXCEPTION;
	
	--SET DEBUG FILE TO "/tmp/Victor/sp_alfanumerico.out";
	--TRACE ON;
	
	LET iCantVueltas = LENGTH(cCadena);
	IF iCantVueltas >= 1 THEN
		FOR iNumCaracter = 1 TO iCantVueltas
			LET cLetra = '';
			LET cLetra = SUBSTR(cCadena,iNumCaracter,1);
			IF (cLetra  BETWEEN 'A' AND 'Z' OR cLetra = 'Ã' ) THEN		
				LET cEscritura = TRIM(cEscritura) || cLetra;
			ELIF cLetra BETWEEN 'a' AND 'z' OR cLetra = 'Ã±' THEN
				LET cEscritura = TRIM(cEscritura) || cLetra;			
			ELIF cLetra = ' ' THEN
				LET cEscritura = TRIM(cEscritura) || '_';
			ELIF cLetra BETWEEN '0' AND '9' THEN
				LET cEscritura = TRIM(cEscritura) || cLetra;
			ELIF cLetra = '-' THEN 
				LET cEscritura = TRIM(cEscritura) || cLetra;
			ELIF cLetra = 'Ã' OR cLetra = 'Ã' OR cLetra = 'Ã' OR cLetra = 'Ã' OR cLetra = 'Ã' THEN
				LET cEscritura = TRIM(cEscritura) || cLetra;
			END IF;
		END FOR;
	END IF;
	
	LET cEscritura = REPLACE (cEscritura, '_',' ');
	
	RETURN cEscritura;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Se crea sp para validar que los caracteres sean alfanumericos', 
'AUTOR: Victor Hugo NuÃ±ez Velazquez ',
'FECHA: 16/02/2015',
'BD: bdinteg',
'VERSION: 20150216.1243';

CREATE PROCEDURE "informix".sp_bit_solicitudessos_sif (pNumCte CHAR(20), 
														   pTipoSol CHAR(20), 
														   pNombreInc CHAR (104), 
														   pFechaNacInc DATE, 
														   pNumCteCorr CHAR(20),
														   pNombreCorr CHAR(104),
														   pFechaNacCorr DATE, 
														   pSucursal CHAR(4), 
														   pNumEmp CHAR(8), 
														   pOrigen CHAR(1)) 
RETURNING CHAR(5) AS CodRetorno;

--Definicion de Variables
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);


--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '00000';

--SET DEBUG FILE TO '/tmp/sp_bit_solicitudessos.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF (pNumCte IS NULL OR pNumCte  = '') OR (pTipoSol IS NULL OR pTipoSol = '')
		OR (pNombreInc  IS NULL OR pNombreInc  = '') 
		OR (pFechaNacInc IS NULL OR pFechaNacInc = '') 
		OR (pNombreCorr IS NULL OR pNombreCorr = '')  
		OR (pFechaNacCorr IS NULL OR pFechaNacCorr = '') 
		OR (pSucursal IS NULL OR pSucursal = '') 
		OR (pNumEmp IS NULL OR pNumEmp = '') 
		OR (pOrigen IS NULL OR pOrigen = '') THEN
		LET cCodRet = '00001';
	ELSE
		SELECT {+avoid("informix".si_bitacora_dictamenes) }first 1 sucursal INTO pSucursal FROM "informix".si_bitacora_dictamenes WHERE  numcte_coinc=pNumCte and date(fecha_insert)=today;
		
		LET pSucursal = NVL(pSucursal,'');
	
		INSERT INTO bdinteg:"informix".si_bitacora_solicitudessos
		(numcte, tipo_sol, nombre_inc, fecha_nac_inc, numcte2, nombre_corr, fecha_nac_corr, sucursal, numemp, origen, fecha_insert)
		VALUES( pNumCte, pTipoSol  , pNombreInc, pFechaNacInc  , pNumCteCorr , pNombreCorr, pFechaNacCorr, pSucursal, pNumEmp, pOrigen,CURRENT);
	END IF	
	RETURN cCodRet;
		
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION:Se crea procedimiento almacenado para llamar sp_bit_solicitudessos el cual guardarà una bitacora de las coincidencias para su posterior procesamiento. ',
'FECHA : 06/03/2014',
'VERSION: ',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_obtienecatalogoregioncc(pNumRegion SMALLINT)
	RETURNING 	CHAR(5)  AS CodigodeRetorno,
				CHAR(50) AS Mensaje,
				CHAR(3)  AS NumRegion,
				CHAR(40) AS NombredeRegion;

---DECLARACIONES
DEFINE iSqlErr	INTEGER;
DEFINE iIsamErr	INTEGER;
DEFINE cCod_ret	CHAR(5);
DEFINE cNumReg	CHAR(3);
DEFINE cNomReg	CHAR(40);
DEFINE cMensaje	CHAR(50);

LET iSqlErr		= 0;
LET iIsamErr	= 0;
LET cCod_ret	= '00000';
LET cNumReg		= '';
LET cNomReg		= '';
LET cMensaje	= 'EJECUCIÓN EXITOSA';

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
          LET cCod_ret = iSqlErr;
          RETURN cCod_ret,cMensaje,NVL(cNumReg,''),NVL(cNomReg,'');
       END IF;
    END EXCEPTION;
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
	--SET DEBUG FILE TO "/respaldosbd/josue/sp_obtienecatalogoregioncc.out";
	--TRACE ON;
	
	
		FOREACH WITH HOLD		
			
			SELECT id_region,region INTO cNumReg,cNomReg
			FROM  "informix".si_catregion_rh
			WHERE id_region = DECODE(NVL(pNumRegion,0),0,id_region,pNumRegion)
		
			RETURN cCod_ret,cMensaje,NVL(cNumReg,''),NVL(cNomReg,'') WITH RESUME;
			
		END FOREACH
		
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN 
			LET cCod_ret = "00002";
			LET cMensaje = "NO EXISTE INFORMACIÓN";
		END IF;
END;
END PROCEDURE
DOCUMENT
'BD: bdinteg',
