CREATE PROCEDURE "informix".sp_bit_solicitudessos (pNumCte CHAR(20), 
														   pTipoSol CHAR(20), 
														   pNombreInc CHAR (104), 
														   pFechaNacInc DATE, 
														   pNombreCorr CHAR(104),
														   pFechaNacCorr DATE, 
														   pSucursal CHAR(4), 
														   pNumEmp CHAR(8), 
														   pOrigen CHAR(1)) 
RETURNING CHAR(5) AS CodRetorno;

--Definicion de Variables
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cFechaNacInc DATE;


--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '00000';
LET cFechaNacInc = DATE(1);

--SET DEBUG FILE TO '/informix/cristo/sp_bit_solicitudessos.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END IF;
	END EXCEPTION;

	SET LOCK MODE TO WAIT 3;
	
	IF (pNumCte IS NULL OR pNumCte  = '') OR (pTipoSol IS NULL OR pTipoSol = '')
		OR (pNombreInc  IS NULL OR pNombreInc  = '') 
		OR (pFechaNacInc IS NULL OR pFechaNacInc = '') 
		OR (pNombreCorr IS NULL OR pNombreCorr = '')  
		OR (pFechaNacCorr IS NULL OR pFechaNacCorr = '') 
		OR (pSucursal IS NULL OR pSucursal = '') 
		OR (pNumEmp IS NULL OR pNumEmp = '') 
		OR (pOrigen IS NULL OR pOrigen = '') THEN
		LET cCodRet = '00001';
	ELSE
		
		SELECT first 1 {+AVOID("informix".si_ctepf)}fecha_nac INTO cFechaNacInc FROM "informix".si_ctepf WHERE numcte=pNumCte;
		
		IF dbinfo("sqlca.sqlerrd2") = 1 THEN 
			LET pFechaNacInc = cFechaNacInc;			
		END IF;
		
		INSERT INTO bdinteg:"informix".si_bitacora_solicitudessos
		(numcte, tipo_sol, nombre_inc, fecha_nac_inc, nombre_corr, fecha_nac_corr, sucursal, numemp, origen, fecha_insert)
		VALUES( pNumCte, pTipoSol  , pNombreInc, pFechaNacInc  , pNombreCorr, pFechaNacCorr, pSucursal, pNumEmp, pOrigen,CURRENT);
	END IF	
	RETURN cCodRet;
		
END;

END PROCEDURE
DOCUMENT
'DESCRIPCION:Se crea procedimiento almacenado para llamar sp_bit_solicitudessos el cual guardara  una bitacora de las coincidencias para su posterior procesamiento. ',
'AUTOR : Leonardo Alfonso Plata Garcia',
'FECHA : 06/09/2013',
'MODIFICACION: Se obtiene fecha de nacimiento del cliente para evitar errores en la convercion de fechas antes del llamado de este procedimiento',
'FECHA: 25/03/2015',
'VERSION: ',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_actualizactebiometria(pTipo CHAR(1), pNumCte CHAR(20))
    RETURNING CHAR(5) AS CodRet;

    --Definicion de Variables
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRet CHAR(5);

    --Inicializacion de Variables
    LET iSqlErr = 0;
    LET cCodRet = '000';

    --SET DEBUG FILE TO '/informix/IrisA/sp_actualizactebiometria.out';
    --TRACE ON;

    BEGIN
        ON EXCEPTION SET iSqlErr
            IF iSqlErr <> 0 THEN
                LET cCodRet = iSqlErr;
                RETURN cCodRet;
            END IF;
        END EXCEPTION;

        SET ISOLATION TO DIRTY READ;
        SET LOCK MODE TO WAIT 3;

		IF pTipo = '1' THEN
			UPDATE "informix".si_cliente SET tpo_biometria = '2' WHERE numcte = pNumCte;
		ELSE
			LET cCodRet = '001'; -- No Existe el Tipo de Consulta
		END IF;

        RETURN cCodRet;
    END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ht_actualizar_resumen()
RETURNING
	CHAR(6) AS cod_ret

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cCodRet			CHAR(6);
	
	DEFINE cFolioArchivo		CHAR(13);
	DEFINE iTotCtes				INT8;
	DEFINE iTotTelsVal 			INT8;
	DEFINE iTotTelsInval 		INT8;
	DEFINE iTotRegsPend			INT8;
	DEFINE iTotTelsAmbos 		INT8;
	DEFINE iTotTelsFijo 		INT8;
	DEFINE iTotTelsCel 			INT8;
	DEFINE iTotTelsFijoVal 		INT8;
	DEFINE iTotTelsFijoInval	INT8;
	DEFINE iTotTelsCelVal		INT8;
	DEFINE iTotTelsCelInval		INT8;

	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cCodRet             = "000000";
	
	LET cFolioArchivo		= "";
	LET iTotCtes			= 0;
	LET iTotTelsVal 		= 0;
	LET iTotTelsInval 		= 0;
	LET iTotRegsPend		= 0;
	LET iTotTelsAmbos 		= 0;
	LET iTotTelsFijo 		= 0;
	LET iTotTelsCel 		= 0;
	LET iTotTelsFijoVal 	= 0;
	LET iTotTelsFijoInval	= 0;
	LET iTotTelsCelVal		= 0;
	LET iTotTelsCelInval	= 0;


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_ht_actualizar_resumen.out';
	--TRACE ON;
	
	-- HACE UN BARRIDO POR ARCHIVO
	FOREACH
		SELECT folio_archivo
		INTO cFolioArchivo
		FROM "informix".si_ht_resumen_ctrl_tels
		WHERE folio_archivo = folio_archivo
		
		-- OBTIENE EL TOTAL DE CLIENTES 
		SELECT COUNT(DISTINCT num_cte)
		INTO iTotCtes
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo;
		
		-- OBTIEN EL TOTAL DE TELS VALIDOS
		SELECT COUNT(DISTINCT TELEFONO) 
		INTO iTotTelsVal
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND valido = "S";
		
		-- OBTIEN EL TOTAL DE TELS INVALIDOS
		SELECT COUNT(DISTINCT TELEFONO) 
		INTO iTotTelsInval
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND valido = "N";

		-- OBTIENE EL TOTAL DE REGS PENDIENTES
		SELECT COUNT(DISTINCT TELEFONO)
		INTO iTotRegsPend
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo AND valido = "P";
		
		-- OBTIENE EL TOTAL DE TELEFONOS FIJOS Y CELULARES
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsAmbos
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel IN (1,2);
		
		-- OBTIENE EL TOTAL DE TELEFONOS FIJOS	
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsFijo
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 1;
		
		-- OBTIENE EL TOTAL DE TELEFONOS FIJOS VALIDOS
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsFijoVal
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 1
		AND valido = "S";
		
		-- OBTIENE EL TOTAL DE TELEFONOS FIJOS INVALIDOS
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsFijoInval
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 1
		AND valido = "N";

		-- OBTIENE EL TOTAL DE TELEFONOS CELULARES
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsCel
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 2;
		
		-- OBTIENE EL TOTAL DE TELEFONOS CELULARES VALIDOS
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsCelVal
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 2
		AND valido = "S";
		
		-- OBTIENE EL TOTAL DE TELEFONOS CELULARES INVALIDOS
		SELECT COUNT(DISTINCT telefono)
		INTO iTotTelsCelInval
		FROM "informix".si_ht_detalle_ctrl_tels 
		WHERE folio_archivo = cFolioArchivo
		AND tipo_tel = 2
		AND valido = "N";

		-- SE ACTUALIZA LA TABLA DE RESUMEN
		UPDATE "informix".si_ht_resumen_ctrl_tels
		SET tot_ctes = iTotCtes, tels_validos = iTotTelsVal, tels_invalidos = iTotTelsInval, tels_pend = iTotRegsPend, 
			tot_telsambos = iTotTelsAmbos, tot_telsfijo = iTotTelsFijo, tot_telscel = iTotTelsCel, 
			tot_telsfijoval = iTotTelsFijoVal, tot_telsfijoinval = iTotTelsFijoInval, tot_telscelval = iTotTelsCelVal, 
			tot_telscelinval = iTotTelsCelInval
		WHERE folio_archivo = cFolioArchivo;
		
	END FOREACH
	
	RETURN cCodRet;
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para actualizar los totales de los telefonos de los archivos de marcatel',
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Febrero 2015';

CREATE PROCEDURE "informix".sp_ht_resumen_ctrl_tels
(
pArchivo	CHAR(13)
)
RETURNING
	CHAR(6)		AS cod_ret,
	CHAR(14)	AS cFolioArchivo,
	SMALLINT	AS iStatus,
	INT8		AS iTotRegs,
	INT8		AS iTotCtes,
	INT8		AS iTelsEnviados,
	INT8		AS iTelsValidos,
	INT8		AS iTelsInvalidos,
	INT8		AS iTotTelsPend,
	INT8		AS iTotTelsAmbos,
	INT8		AS iTotTelsFijo,
	INT8		AS iTotTelsCel,
	INT8 		AS iTotTelsFijoVal,
	INT8		AS iTotTelsFijoInval,
	INT8		AS iTotTelsCelVal,
	INT8 		AS iTotTelsCelInval

	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cCodRet			CHAR(6);
	
	DEFINE cFolioArchivo		CHAR(13);
	DEFINE iStatus				SMALLINT;
	DEFINE iTotRegs				INT8;
	DEFINE iTotCtes				INT8;
	DEFINE iTelsEnviados		INT8;
	DEFINE iTelsValidos			INT8;
	DEFINE iTelsInvalidos		INT8;
	DEFINE iTotTelsPend			INT8;
	DEFINE iTotTelsAmbos		INT8;
	DEFINE iTotTelsFijo			INT8;
	DEFINE iTotTelsCel			INT8;
	DEFINE iTotTelsFijoVal		INT8;
	DEFINE iTotTelsFijoInval	INT8;
	DEFINE iTotTelsCelVal		INT8;
	DEFINE iTotTelsCelInval		INT8;


	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cCodRet             = "000000";
	
	LET cFolioArchivo		= "";
	LET iStatus				= 0;
	LET iTotRegs			= 0;
	LET iTotCtes			= 0;
	LET iTelsEnviados		= 0;
	LET iTelsValidos		= 0;
	LET iTelsInvalidos		= 0;
	LET iTotTelsPend		= 0;
	LET iTotTelsAmbos		= 0;
	LET iTotTelsFijo		= 0;
	LET iTotTelsCel			= 0;
	LET iTotTelsFijoVal		= 0;
	LET iTotTelsFijoInval	= 0;
	LET iTotTelsCelVal		= 0;
	LET iTotTelsCelInval	= 0;
	

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cFolioArchivo, iStatus, iTotRegs, iTotCtes, iTelsEnviados, iTelsValidos, iTelsInvalidos, iTotTelsPend,
				iTotTelsAmbos, iTotTelsFijo, iTotTelsCel, iTotTelsFijoVal, iTotTelsFijoInval, iTotTelsCelVal, iTotTelsCelInval;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/moha/sp_cons_ht_resumen_ctrl_tels.out';
	--TRACE ON;
	
	IF pArchivo IS NULL THEN  --// VALIDA QUE SI ES NULO	
		LET cCodRet = "000001";	
	ELSE
		FOREACH
			--// OBTIENE LOS DATOS DEL RESUMEN
			SELECT folio_archivo,status,tot_reg,tot_ctes,tels_enviados,tels_validos,tels_invalidos,tels_pend,tot_telsambos,
				tot_telsfijo,tot_telscel,tot_telsfijoval,tot_telsfijoinval,tot_telscelval,tot_telscelinval
			INTO cFolioArchivo,iStatus,iTotRegs,iTotCtes,iTelsEnviados,iTelsValidos,iTelsInvalidos,iTotTelsPend,iTotTelsAmbos,
				iTotTelsFijo,iTotTelsCel,iTotTelsFijoVal,iTotTelsFijoInval,iTotTelsCelVal,iTotTelsCelInval
			FROM "informix".si_ht_resumen_ctrl_tels
			WHERE folio_archivo = DECODE(pArchivo,"",folio_archivo,pArchivo)
			
			RETURN cCodRet, cFolioArchivo, iStatus, iTotRegs, iTotCtes, iTelsEnviados, iTelsValidos, iTelsInvalidos, iTotTelsPend,
				iTotTelsAmbos, iTotTelsFijo, iTotTelsCel, iTotTelsFijoVal, iTotTelsFijoInval, iTotTelsCelVal, iTotTelsCelInval WITH RESUME;
		END FOREACH
		--// NO EXISTEN DATOS
		IF dbinfo("sqlca.sqlerrd2") = 0 THEN
			LET cCodRet = "000002";
			RETURN cCodRet, cFolioArchivo, iStatus, iTotRegs, iTotCtes, iTelsEnviados, iTelsValidos, iTelsInvalidos, iTotTelsPend,
				iTotTelsAmbos, iTotTelsFijo, iTotTelsCel, iTotTelsFijoVal, iTotTelsFijoInval, iTotTelsCelVal, iTotTelsCelInval;
		END IF
	END IF
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para consultar el resumen de los teléfonos enviados a marcatel',
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Junio 2014';

CREATE PROCEDURE "informix".sp_ht_grabar_respuesta
(
pArchivo	CHAR(100)
)
RETURNING
	CHAR(6) 	AS cod_ret,
	CHAR(80)	AS desc_ret
---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodRet			CHAR(6);
	DEFINE cDescRet			CHAR(80);

	DEFINE cBandera				CHAR(1);
	DEFINE iNumSerial			INT8;
	DEFINE iRespuesta			SMALLINT;
	DEFINE cTelefono			CHAR(13);
	DEFINE iNumTelsValidos		INT8;
	DEFINE iNumTelsInValidos	INT8;
	DEFINE iTotRegsPend			INT8;
	DEFINE iTotTelsFijoVal 		INT8;
	DEFINE iTotTelsFijoInval 	INT8;
	DEFINE iTotTelsCelVal 		INT8;
	DEFINE iTotTelsCelInval 	INT8;
	DEFINE iTipoTel 			SMALLINT;

	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cErrorInfo          = "";
	LET cCodRet             = "000000";
	LET cDescRet			= "PROCESO EXITOSO";

	LET cBandera			= "0";
	LET iNumSerial			= 0;
	LET iRespuesta			= 0;
	LET cTelefono			= "";
	LET iNumTelsValidos		= 0;
	LET iNumTelsInValidos	= 0;
	LET iTotRegsPend		= 0;
	LET iTotTelsFijoVal 	= 0;
	LET iTotTelsFijoInval 	= 0;
	LET iTotTelsCelVal 		= 0;
	LET iTotTelsCelInval 	= 0;
	LET iTipoTel			= 0;


BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			LET cDescRet = cErrorInfo;
			RETURN cCodRet, cDescRet;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--SET DEBUG FILE TO '/informix/RESPALDOS/sp_ht_grabar_respuesta.out';
	--TRACE ON;
	
	LET pArchivo = TRIM(pArchivo);
	
	--// VALIDA QUE LOS PARAMETROS NO ESTEN VACIOS
	IF NVL(pArchivo,"") = "" THEN 
		LET cCodRet = "000001";
		LET cDescRet = "FALTAN PARAMETROS";
	ELSE
		SELECT LIMIT 1 "1"
		INTO cBandera
		FROM "informix".si_ht_resumen_ctrl_tels
		WHERE folio_archivo = pArchivo;
		
		IF NVL(cBandera,"0") <> "1" THEN
			LET cCodRet = "000002";
			LET cDescRet = "ARCHIVO NO EXISTE";
		ELSE
			FOREACH
				SELECT num_serial, respuesta
				INTO iNumSerial, iRespuesta
				FROM "informix".si_ht_regreso_marcatel
				WHERE folio_archivo = pArchivo

				SELECT telefono, tipo_tel
				INTO cTelefono, iTipoTel
				FROM "informix".si_ht_detalle_ctrl_tels
				WHERE folio_archivo = pArchivo
				AND num_serial = iNumSerial;
					
				IF iRespuesta IN (1,2,3,4) THEN
					UPDATE "informix".si_ht_detalle_ctrl_tels
					SET valido = "S"
					WHERE folio_archivo = pArchivo
					AND telefono = cTelefono;
					
					--// ACTUALIZA EN LA SI_TELEFONOS
					UPDATE "informix".si_telefonos
					SET marcatel = "V", fecha_actualiza = TODAY
					WHERE telefono = cTelefono;
					
					LET iNumTelsValidos	= iNumTelsValidos + 1;
					
					IF iTipoTel = 1 THEN
						LET iTotTelsFijoVal = iTotTelsFijoVal + 1;
					ELIF iTipoTel = 2 THEN
						LET iTotTelsCelVal = iTotTelsCelVal + 1;
					END IF

				ELIF iRespuesta IN (5,6) THEN
					UPDATE "informix".si_ht_detalle_ctrl_tels
					SET valido = "N"
					WHERE folio_archivo = pArchivo
					AND telefono = cTelefono;
					
					--// ACTUALIZA EN LA SI_TELEFONOS
					UPDATE "informix".si_telefonos
					SET marcatel = "F", fecha_actualiza = TODAY
					WHERE telefono = cTelefono;

					LET iNumTelsInValidos = iNumTelsInValidos + 1;
					
					IF iTipoTel = 1 THEN
						LET iTotTelsFijoInval = iTotTelsFijoInval + 1;
					ELIF iTipoTel = 2 THEN
						LET iTotTelsCelInval = iTotTelsCelInval + 1;
					END IF
				END IF
			
			END FOREACH
			
			-- OBTIENE EL TOTAL DE TELS PENDIENTES
			SELECT COUNT(DISTINCT TELEFONO)
			INTO iTotRegsPend
			FROM "informix".si_ht_detalle_ctrl_tels 
			WHERE folio_archivo = pArchivo AND valido = "P";
			
			UPDATE "informix".si_ht_resumen_ctrl_tels
			SET status = 2, tels_validos = iNumTelsValidos, tels_invalidos = iNumTelsInValidos, tels_pend = iTotRegsPend, 
				tot_telsfijoval = iTotTelsFijoVal,tot_telsfijoinval = iTotTelsFijoInval, tot_telscelval = iTotTelsCelVal, tot_telscelinval = iTotTelsCelInval
			WHERE folio_archivo = pArchivo;

		END IF
	END IF
		
	RETURN cCodRet, cDescRet;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Proceso para replicar la respuesta de marcatel en el caso de que un telefono es valido o invalido',
'BD: bdinteg', 
'AUTOR: Mohamed Carreón ',
'FECHA: Junio 2014';

CREATE PROCEDURE "informix".sp_ingresos_movil(pNumSolic char(12))
RETURNING CHAR(5) as codret,
          CHAR(4) as tipo_ing,
          CHAR(4) as periodicidad,
          CHAR(10) as monto

DEFINE iSqlErr		INTEGER;
DEFINE sTipoIng         CHAR(4);
DEFINE sPeriodicidad    CHAR(4);
DEFINE sMonto           CHAR(10);


LET iSqlErr		=0;
LET sTipoIng            ='';
LET sPeriodicidad       ='';
LET sMonto              ='';

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			RETURN iSqlErr, sTipoIng, sPeriodicidad, sMonto;
		END IF;
	END EXCEPTION;


        SELECT tp_ingreso, periodo_ingreso, ingreso_mensual
        INTO sTipoIng, sPeriodicidad, sMonto
        FROM bdisolic:ss_resum_scor_fin 
        WHERE num_solicitud=pNumSolic;
      --AND sec_ingreso =(SELECT MAX(sec_ingreso) FROM bdinteg:si_ingresos WHERE numcte=pNumCte);
              
	RETURN '00000', sTipoIng, sPeriodicidad, sMonto;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_depura_temposoc()
				RETURNING
				CHAR(5)     AS Cod_Retorno,
				CHAR(100)   AS Msj_Retorno;
				
DEFINE cCodRet		CHAR(5);
DEFINE cMsjRetorno	CHAR(100);
DEFINE iSql_err     INT; 


LET cCodRet = "00000";
LET cMsjRetorno = "PROCESO EXITOSO";
LET iSql_err = 0;


BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			LET cMsjRetorno = "ERROR DE BASE DE DATOS";
			RETURN cCodRet, cMsjRetorno;
		END IF;
	END EXCEPTION;
	 
	--SET DEBUG FILE TO "/informix/CHVN/sp_depura_temposoc.out";
	--TRACE ON;
	
	TRUNCATE TABLE "informix".si_tempoamortizaciones;
	TRUNCATE TABLE "informix".si_tempobloqctascred;
	TRUNCATE TABLE "informix".si_tempoconcheques;
	TRUNCATE TABLE "informix".si_tempoconmovfol;
	TRUNCATE TABLE "informix".si_tempoctas;
	TRUNCATE TABLE "informix".si_tempodescprog;
	TRUNCATE TABLE "informix".si_tempodisposiciones;
	TRUNCATE TABLE "informix".si_tempomovofi;
	TRUNCATE TABLE "informix".si_tempomovs;
	TRUNCATE TABLE "informix".si_tempomovtranele;
	TRUNCATE TABLE "informix".si_tempopagosrecibidos;
	TRUNCATE TABLE "informix".si_temporepmovtoside;
	TRUNCATE TABLE "informix".si_temposaldoshist;
	TRUNCATE TABLE "informix".si_temposbcretenido;
	TRUNCATE TABLE "informix".si_tempotarjetas;
	
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempoamortizaciones;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempobloqctascred;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempoconcheques;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempoconmovfol;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempoctas;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempodescprog;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempodisposiciones;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempomovofi;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempomovs;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempomovtranele;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempopagosrecibidos;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_temporepmovtoside;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_temposaldoshist;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_temposbcretenido;
	COMMIT;
	BEGIN;
		UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_tempotarjetas;
	COMMIT;
	
	RETURN cCodRet,cMsjRetorno;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_listaltabancos(pSkip		INTEGER,ptipoconsulta CHAR(1))

	RETURNING  CHAR(5), CHAR(20);   -- codigo retorno

	DEFINE vCodRet  		CHAR(5);
	DEFINE vCodRet2			CHAR(5);
	DEFINE vSqlErr          INTEGER;
	DEFINE vIsamErr			INTEGER;
	DEFINE vclave			CHAR(5);
	DEFINE vbanco			CHAR(20);
	
	LET vCodRet='00000';
	LET vSqlErr=0;
	LET vIsamErr=0;
	LET vclave='';
	LET vbanco='';
	
--	SET DEBUG FILE TO "/informix/Jess/sp_listaltabancos.out";
--  TRACE ON;

    BEGIN
		
		ON EXCEPTION SET vSqlErr, vIsamErr
--			SET DEBUG FILE TO "/informix/Jess/sp_listaltabancos.out";
--			TRACE ON;
			IF vSqlErr != 0 THEN
				LET vCodRet = vSqlErr;
				LET vCodRet2 = vIsamErr;
            RETURN vCodRet, vbanco; 
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF ptipoconsulta = '1' THEN   -- CONSUTA TODOS
		
			FOREACH
			
				SELECT   SKIP pSkip LIMIT 10  cvecesif, vchrnombrecorto 
				INTO vclave, vbanco
				FROM si_bancos
				WHERE cvecesif is not null and cvecesif !=0
				ORDER BY vchrnombrecorto
			
				RETURN vclave, vbanco with resume;
			
			END FOREACH;
			
		ELIF ptipoconsulta = '2' THEN  -- CONSULTA SOLO ACTUALIZADOS
		
		    FOREACH
			
				SELECT  SKIP pSkip LIMIT 10 cvecesif, vchrnombrecorto 
				INTO vclave, vbanco
				FROM si_bancos
				WHERE cvecesif is not null and cvecesif !=0 and flg_spei='1' and fecha_opera = TODAY
				
				RETURN vclave, vbanco with resume;
			
			END FOREACH;
			
		ELIF ptipoconsulta = '3' THEN  -- CONSULTA SOLO BAJAS SPEI
		
		    FOREACH
			
				SELECT   SKIP pSkip LIMIT 10  cvecesif, vchrnombrecorto 
				INTO vclave, vbanco
				FROM si_bancos
				WHERE cvecesif is not null and cvecesif !=0 and flg_spei='0' and fecha_opera = TODAY
				ORDER BY vchrnombrecorto
			
				RETURN vclave, vbanco with resume;
			
			END FOREACH;
			
		ELSE
		   LET vCodRet='001';  -- TIPO DE CONSULTA INCORRECTA
		   LET vbanco='Operacion incorrecta';
		   RETURN vCodRet, vbanco;
		END IF;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ws_consultacoppel (pTipo CHAR(1), -- 1 Consulta todos, 2 Grabar Datos
														  pNumcte CHAR(20),
														  pNombre CHAR(104),
														  pFechaNac CHAR(10),
														  pSituacion CHAR(1),
														  pCausa SMALLINT,
														  pTicket CHAR(20))

RETURNING 	CHAR(5)  AS cCodRet, CHAR(20) AS cNumCte, CHAR(1) AS cEmpresa, CHAR(4) AS cSucursal, CHAR(8) AS cEmpleado, CHAR(20) AS cTicket;


--Definicion de Variables
DEFINE iSqlErr 		INTEGER;
DEFINE cCodRet 		CHAR(5);
DEFINE cNumCte 		CHAR(20);
DEFINE cEmpresa		CHAR(1);
DEFINE cSucursal	CHAR(4);
DEFINE cTicket		CHAR(20);
DEFINE cEmpleado	CHAR(8);


--Inicializacion de Variables
LET iSqlErr 		= 0;
LET cCodRet 		= '00000';
LET cNumCte 		= '';
LET cEmpresa 		= '';
LET cSucursal 		= '0002';
LET cTicket 		= '';
LET cEmpleado		= '';

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, '','','','','';
		END IF;
	END EXCEPTION;

	--SET DEBUG FILE TO '/informix/cristo/sp_ws_empctes_coppel.out';
	--TRACE ON;

	SET LOCK MODE TO WAIT 3;


	IF 	pTipo = '1' THEN-- Obtener los clientes o empleados a consultar en coppel
		FOREACH WITH HOLD

			SELECT {+AVOID_FULL("informix".si_huella_linea_resultado)} distinct(cliente),empresa, ticket
			INTO cNumCte,cEmpresa,cTicket
			FROM "informix".si_huella_linea_resultado
			where fecha=today
			and empresa = '4'
			and num_mensaje = '602'
			and nombre=''
			order by 1 asc


			SELECT {+AVOID("informix".si_huella_linea)} empleado INTO cEmpleado 
			FROM "informix".si_huella_linea WHERE ticket=cTicket AND status_consulta='3';

			RETURN cCodret , TRIM(cNumCte), TRIM(cEmpresa), TRIM(cSucursal),TRIM(cEmpleado),TRIM(cTicket) WITH RESUME;

		END FOREACH;

	ELIF pTipo = '2' THEN  -- Actualizar registro del cliente 
		IF ((pNumcte IS NULL OR pNumcte = '') OR (pNombre IS NULL OR pNombre = '')) THEN
			LET cCodRet = '00001'; --Valor de parametros nulos o no valido
		ELSE
			
			LET pNombre = replace(pNombre,'  ',' ');
			
			UPDATE "informix".si_huella_linea_resultado
			SET nombre = TRIM(pNombre), fecha_nac = TRIM(pFechaNac), situacion = TRIM(pSituacion), causa = pCausa
			WHERE ticket=pTicket and cliente=pNumcte and num_mensaje = '602' and fecha=today;

		END IF;

		RETURN cCodRet, '','','','','';
	ELSE
		LET cCodRet = '00002';	--Valor de parametro pTipo no valido
		RETURN cCodRet, '','','','','';
	END IF;

END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Obtiene los clientes coppel para ser evaluados por webservice wsBanCoppServ',
'permite registrar datos como son nombre, fecha de nacimiento y situacion especial del cliente',
'dentro de la tabla si_huella_linea_resultado, Se aplica replace de doble espacio',
'AUTOR : Cristo Lugo',
'FECHA : 30-04-2015',
'VERSION: 20150330',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_act_dirmovil(pCP CHAR(5), sNumCte CHAR(9))
RETURNING CHAR(5) AS CodRet, CHAR(3)as sPais, CHAR(2)as sEdo, CHAR(5)as sCiudad, CHAR (5) as sCP, CHAR(6)as sNumCiudad, CHAR(6)as sColonia, CHAR(5)as sMpo;
DEFINE iSqlErr 	    INTEGER;
DEFINE cCodRet 	    CHAR(5);
DEFINE sPais        CHAR(3);
DEFINE sEdo         CHAR(2);
DEFINE sCiudad      CHAR(5);
DEFINE sCP          CHAR(5);
DEFINE sNumCiudad   CHAR(6);
DEFINE sColonia     CHAR(6);
DEFINE sMpo         CHAR(5);
LET cCodRet 	 ='00000';
LET sPais        ='';
LET sEdo         ='';
LET sCiudad      ='';
LET sCP          ='';
LET sNumCiudad   ='';
LET sColonia     ='';
LET sMpo         ='00000';
BEGIN
-- ERRORES DE INFORMIX
ON EXCEPTION SET iSqlErr
	IF iSqlErr <> 0 THEN
		LET cCodRet = iSqlErr;
		RETURN cCodRet, sPais, sEdo, sCiudad, sCP, sNumCiudad, sColonia, sMpo;
	END IF;
END EXCEPTION;
 FOREACH
    SELECT limit 1 {+INDEX (bdinteg:si_ciudades ix_2363)}{+INDEX (bdinteg:si_catzonas idx_zona)}
           {+INDEX (bdinteg:si_estados inx_estado)} 
    b.pais, b.estado, b.ciudad, codigopostalzona, numerociudad, numerocolonia
    INTO sPais, sEdo, sCiudad, sCP, sNumCiudad, sColonia
    FROM bdinteg:si_catzonas a inner join bdinteg:si_ciudades b 
      on a.numerociudad=b.ciudad_coppel and a.numerociudad<>0 
    inner join bdinteg:si_estados c on b.estado=c.estado 
    WHERE codigopostalzona=pCP
 END FOREACH;
IF sEdo='09' THEN
    LET sMpo='00'||sCiudad;
END IF;

RETURN cCodRet, sPais, sEdo, sCiudad, sCP, sNumCiudad, sColonia, sMpo;
END 
END PROCEDURE;

create procedure "informix".sp_valida_numero(sCP  char(5))
 RETURNING CHAR(5) as codret, CHAR(1) as pos1, CHAR(1) as pos2, CHAR(1) as pos3, CHAR(1) as pos4, CHAR(1) as pos5;

DEFINE iSqlErr	INTEGER;
DEFINE sCodRet  CHAR(5);
DEFINE sPos1    CHAR(1);
DEFINE sPos2    CHAR(1);
DEFINE sPos3    CHAR(1);
DEFINE sPos4    CHAR(1);
DEFINE sPos5    CHAR(1);

LET iSqlErr	= 0;
LET sCodRet = '00000';
LET sPos1   ='';
LET sPos2   ='';
LET sPos3   ='';
LET sPos4   ='';
LET sPos5   ='';


BEGIN
ON EXCEPTION SET iSqlErr
	IF iSqlErr <> 0 THEN
	   RETURN iSqlErr, sPos1, sPos2, sPos3, sPos4, sPos5;
        END IF;
END EXCEPTION;


IF TRIM(sCP)="" OR LENGTH(sCP)<5  OR sCP="00000" THEN
    RETURN '00006', sPos1, sPos2, sPos3, sPos4, sPos5;
END IF;

--SEPARANDO EL CODIGO POSTAL EN POSICIONES
    SELECT sCP[1],sCP[2],sCP[3], sCP[4], sCP[5]
        INTO sPos1, sPos2, sPos3, sPos4, sPos5
    FROM si_fechas;

--VALIDANDO POSICION 1
    IF (sPos1<>"0" AND sPos1<>"1" AND sPos1<>"2" AND sPos1<>"3" AND sPos1<>"4" AND sPos1<>"5" AND sPos1<>"6" 
        AND sPos1<>"7" AND sPos1<>"8" AND sPos1<>"9" ) THEN
        RETURN '00001', sPos1, sPos2, sPos3, sPos4, sPos5;
    END IF; 

--VALIDANDO POSICION 2
    IF (sPos2<>"0" AND sPos2<>"1" AND sPos2<>"2" AND sPos2<>"3" AND sPos2<>"4" AND sPos2<>"5" AND sPos2<>"6" 
        AND sPos2<>"7" AND sPos2<>"8" AND sPos2<>"9" ) THEN
        RETURN '00002', sPos1, sPos2, sPos3, sPos4, sPos5;
    END IF; 

--VALIDANDO POSICION 3
    IF (sPos3<>"0" AND sPos3<>"1" AND sPos3<>"2" AND sPos3<>"3" AND sPos3<>"4" AND sPos3<>"5" AND sPos3<>"6" 
        AND sPos3<>"7" AND sPos3<>"8" AND sPos3<>"9" ) THEN
        RETURN '00003', sPos1, sPos2, sPos3, sPos4, sPos5;
    END IF; 

--VALIDANDO POSICION 4
    IF (sPos4<>"0" AND sPos4<>"1" AND sPos4<>"2" AND sPos4<>"3" AND sPos4<>"4" AND sPos4<>"5" AND sPos4<>"6" 
        AND sPos4<>"7" AND sPos4<>"8" AND sPos4<>"9" ) THEN
        RETURN '00004', sPos1, sPos2, sPos3, sPos4, sPos5;
    END IF; 

--VALIDANDO POSICION 5
    IF (sPos5<>"0" AND sPos5<>"1" AND sPos5<>"2" AND sPos5<>"3" AND sPos5<>"4" AND sPos5<>"5" AND sPos5<>"6" 
        AND sPos5<>"7" AND sPos5<>"8" AND sPos5<>"9" ) THEN
        RETURN '00005', sPos1, sPos2, sPos3, sPos4, sPos5;
    END IF; 


RETURN sCodRet, sPos1, sPos2, sPos3, sPos4, sPos5;
END
END PROCEDURE;

CREATE PROCEDURE "informix".mesesvalidoscte(pNumcte CHAR(20)) 
RETURNING 
CHAR(6) AS codret,
INTEGER AS mesescte;


---DECLARACION DE VARIABLES
DEFINE cCodRet CHAR(6);
DEFINE iSqlErr INTEGER;
DEFINE error_info CHAR(80);
DEFINE isam_err INTEGER;

DEFINE vlFecha	DATE;

DEFINE iAnios INTEGER;
DEFINE iAniosValidos INTEGER;
DEFINE iMeses INTEGER;


--SET DEBUG FILE TO "/informix/jesus/mesesvalidoscte.out";
--TRACE ON;

---INICIALIZACION DE VARIABLES
LET cCodRet  = '000000';
LET iSqlErr = 0;
LET error_info = '';
LET isam_err = 0;


LET vlFecha = DATE(1);
LET iAnios = 0;
LET iAniosValidos = 0;
LET iMeses = 0;

BEGIN

ON EXCEPTION SET iSqlErr, isam_err, error_info
LET cCodRet = iSqlErr;
	RETURN cCodRet,0;
END EXCEPTION;

--Directiva para lectura de tablas bloqueadas.
SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

SELECT fecha_hoy 
  into vlFecha
 FROM bdicred:"informix".sd_fechas
 WHERE empresa = '001';

 SELECT valor 
  into iAniosValidos
 FROM bdicred:"informix".sd_param 
 WHERE empresa = '001'
 and cod_param = '095';
 
SELECT  YEAR(TODAY) - YEAR(fecha_nac),CASE WHEN MONTH(fecha_nac) = MONTH(TODAY) AND DAY(fecha_nac) <= DAY(TODAY) 
		THEN 0
		ELSE 
			CASE WHEN MONTH(fecha_nac) < MONTH(TODAY) AND DAY(fecha_nac) <= DAY(TODAY) 
			THEN 				
				MONTH(TODAY) - MONTH(fecha_nac) 
			ELSE
				MONTH(TODAY) - MONTH(fecha_nac) -1
			END 
		END 
		INTO iAnios,iMeses
 FROM "informix".si_ctepf 
WHERE numcte = pNumcte;


LET iAnios = iAnios - iAniosValidos;LET iMeses =  (iAnios *  12) + iMeses;
IF iMeses < 0 THEN 
	LET iMeses = 0;
END IF;
	RETURN cCodRet,iMeses;
END
END PROCEDURE
DOCUMENT
'Se realiza procedimiento para obtener numero de de meses de historia validos del cliente de acuerdo a su edad ',
'AUTOR: Jesus manuel aguilar heredia',
'FECHA: 05-27-2015',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_actualizastatususuario_app(pEmpresa char(3), pIdUsuario INTEGER, pUsuario char(50), pStatus integer, pIp char (15),pSuc char (4), pUsuCambio char (8))
returning char(5);
   
   --Modificó: Alejandro Vazquez
   --Actividad: actualiza el status en del usuario y registra ese cambio
   --Solicito: APPS
   --Fecha: 28-05-2015
 
-- ***************************************************************************
-- Define variables
-- ***************************************************************************
   DEFINE cod_ret char(5);
   DEFINE sql_err integer;
   DEFINE vStatus integer;
   DEFINE vNumcte char(20);
-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
   LET cod_ret       = "000";
   LET vStatus = "0";
   LET vNumcte ="";

BEGIN

   ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF ;
   END EXCEPTION ;


    IF pIdUsuario <> 0 THEN
			SELECT bpi.numcte INTO vNumcte
				FROM bdinteg:si_bpiusuarios bpi INNER JOIN bdibpi:bpi_usuario usr ON usr.numcliente=bpi.numcte AND usr.st_portal='activo'  
				WHERE empresa = pEmpresa AND id_usuario = pIdUsuario;
				
        IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND numcte = vNumcte )  THEN
		
			SELECT id_status INTO vStatus FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa and numcte = vNumcte;
							
				INSERT INTO bdinteg:si_cambiostcte (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  VALUES (vNumcte, vStatus, pStatus, pIp, current, pSuc, pUsuCambio);
				
				UPDATE bdinteg:si_bpiusuarios SET id_status = pStatus, f_status = current  WHERE empresa = pEmpresa AND numcte = vNumcte;

				LET cod_ret = '000';  -- Usuario bloqueado

        ELSE

            LET cod_ret = '001';  -- No existe el Cliente

        END IF ;

    ELSE

        IF EXISTS ( SELECT numcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa AND usuario = pUsuario ) THEN
		
			SELECT id_status, numcte INTO vStatus,vNumcte FROM bdinteg:si_bpiusuarios WHERE empresa = pEmpresa and usuario = pUsuario;
			
				 INSERT INTO bdinteg:si_cambiostcte (numcliente, id_statusanterior, id_statusactual, ipusuario, fecha_cambio, suc_cambio, usuario_cambio)  VALUES (vNumcte, vStatus, pStatus, pIp, current, pSuc, pUsuCambio);	
					
				 UPDATE bdinteg:si_bpiusuarios SET id_status = pStatus, f_status = current  WHERE empresa = pEmpresa AND usuario = pUsuario;

				LET cod_ret = '000';  -- Usuario bloqueado
			

        ELSE

            LET cod_ret = '002';  -- No existe el Usuario

        END IF ;

    END IF ;

    RETURN cod_ret;

END

END PROCEDURE ;

CREATE PROCEDURE "informix".sp_altamodificacion_club(pEmpresa CHAR(3),pCliente CHAR(20),pCteCoppel CHAR(20),pNumPoliza CHAR(20),pTipoPlan CHAR(1),pSucAlta CHAR(4),pEjecutivo CHAR(8),pTipopago CHAR(1),pNumtarjeta CHAR(20),pNumcta CHAR(20),pMesesPagar INTEGER,pMontoPagar MONEY(14,2),pMontoMes MONEY(14,2),pMontoTotal MONEY(14,2),pAceptada CHAR(1),pMotivo_rechazo CHAR(50),pFolioOperacion CHAR(16),pOpcion CHAR(1),pSucCambio CHAR(4),pFechaVencimiento DATE,pTipoPlanAnt CHAR(1))
RETURNING CHAR(6) AS codRet;

--DEFINICION DE VARIABLES
DEFINE cCodret CHAR(6);
DEFINE iSqlErr INTEGER;
DEFINE iContador INTEGER;

--INICIALIZACION DE VARIABLES
LET cCodret	= "000000";
LET iSqlErr = 0;
LET iContador = 0;

--SET DEBUG FILE TO '/informix/IrisA/sp_altamodificacion_club.out';
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodret = iSqlErr;
			RETURN cCodret;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 5;

	IF TRIM(NVL(pOpcion,''))='' THEN
		LET cCodret	= "000001";
	ELSE
		IF TRIM(pOpcion) ='1' THEN
			IF TRIM(NVL(pEmpresa,''))='' OR TRIM(NVL(pCliente,''))='' OR TRIM(NVL(pCteCoppel,''))=''
				OR TRIM(NVL(pTipoPlan,''))='' OR TRIM(NVL(pSucAlta,''))='' OR TRIM(NVL(pEjecutivo,''))='' OR TRIM(NVL(pTipopago,''))=''
				OR NVL(pMesesPagar,0)=0 OR NVL(pMontoPagar,0)=0 OR NVL(pMontoMes,0)=0 OR NVL(pMontoTotal,0)=0
				OR TRIM(NVL(pAceptada,''))='' OR TRIM(NVL(pFolioOperacion,''))=''  THEN
				LET cCodret	= "000001";
			ELSE
				IF TRIM(pTipopago)='1' THEN
					IF TRIM(NVL(pNumtarjeta,''))='' AND TRIM(NVL(pNumcta,''))='' OR TRIM(NVL(pNumPoliza,''))=''THEN
						LET cCodret	= "000001";
					END IF
				END IF
				IF TRIM(cCodret)="000000" THEN
					INSERT INTO "informix".si_club_proteccion (empresa,numcte,numcte_coppel,num_poliza,tipo_plan,suc_alta,ejecutivo,tipo_pago,num_tarjeta,num_cta,meses_pagar,monto_pagar,monto_mes,monto_total,aceptada,motivo_rechazo,tipo_mov,pago_mov,foliooperacion,fecha_alta,fecha_cambio,suc_cambio,fecha_vencimiento,tipoplan_ant)
						VALUES (TRIM(pEmpresa),TRIM(pCliente),TRIM(pCteCoppel),TRIM(pNumPoliza),TRIM(pTipoPlan),TRIM(pSucAlta),TRIM(pEjecutivo),TRIM(pTipopago),TRIM(pNumtarjeta),TRIM(pNumcta),pMesesPagar,pMontoPagar,pMontoMes,pMontoTotal,TRIM(pAceptada),'','V','0',TRIM(pFolioOperacion),CURRENT,CURRENT,"",pFechaVencimiento,pTipoPlanAnt);
				END IF
			END IF
		END IF
		IF TRIM(pOpcion)='2'THEN
			IF TRIM(NVL(pEmpresa,''))='' OR TRIM(NVL(pCliente,''))='' OR TRIM(NVL(pNumPoliza,''))='' OR TRIM(NVL(pCteCoppel,''))='' THEN
				LET cCodret	= "000001";
			ELSE
				SELECT COUNT(numcte)
				INTO iContador
				FROM "informix".si_club_proteccion
				WHERE empresa= TRIM(pEmpresa)
				AND numcte= TRIM(pCliente)
				AND numcte_coppel=TRIM(pCteCoppel)
				AND num_poliza=TRIM(pNumPoliza)
				AND aceptada='1';

				IF NVL(iContador,0)>0 THEN
					IF  TRIM(NVL(pTipopago,''))<>"" THEN
						IF TRIM(NVL(pTipopago,''))=0 THEN
							UPDATE "informix".si_club_proteccion
							SET tipo_pago=pTipopago, num_tarjeta='',num_cta='',fecha_cambio=CURRENT
							WHERE empresa= TRIM(pEmpresa)
							AND numcte= TRIM(pCliente)
							AND numcte_coppel=TRIM(pCteCoppel)
							AND num_poliza=TRIM(pNumPoliza)
							AND aceptada='1';
						ELSE 
							IF TRIM(NVL(pTipopago,''))=1 THEN
								IF TRIM(NVL(pNumtarjeta,''))='' AND TRIM(NVL(pNumcta,''))='' THEN
									LET cCodret	= "000001";
								ELSE
									UPDATE "informix".si_club_proteccion
									SET tipo_pago=pTipopago, num_tarjeta=TRIM(pNumtarjeta),num_cta=TRIM(pNumcta),fecha_cambio=CURRENT
									WHERE empresa= TRIM(pEmpresa)
									AND numcte= TRIM(pCliente)
									AND numcte_coppel=TRIM(pCteCoppel)
									AND num_poliza=TRIM(pNumPoliza)
									AND aceptada='1';
								END IF
							END IF
						END IF
					END IF
					IF  TRIM(cCodret)="000000" AND  TRIM(NVL(pTipoPlan,''))<>'' THEN
						IF NVL(pMesesPagar,0)=0 OR NVL(pMontoPagar,0)=0 OR NVL(pMontoMes,0)=0  OR NVL(pMontoTotal,0)=0 OR TRIM(NVL(pSucCambio,''))='' THEN
							LET cCodret	= "000001";
						ELSE
							UPDATE "informix".si_club_proteccion
							SET meses_pagar=pMesesPagar,monto_pagar=pMontoPagar,monto_mes=pMontoMes,
							monto_total=pMontoTotal,tipo_mov='C',pago_mov='0',fecha_cambio=CURRENT,suc_cambio=pSucCambio,
							tipo_plan=TRIM(pTipoPlan),tipoplan_ant=pTipoPlanAnt
							WHERE empresa= TRIM(pEmpresa)
							AND numcte= TRIM(pCliente)
							AND numcte_coppel=TRIM(pCteCoppel)
							AND num_poliza=TRIM(pNumPoliza)
							AND aceptada='1';
						END IF
					END IF
				ELSE
					LET cCodret	= "000002";
				END IF
			END IF
		END IF
		IF TRIM(pOpcion)='3'THEN
			IF TRIM(NVL(pEmpresa,''))='' OR TRIM(NVL(pCliente,''))='' OR TRIM(NVL(pCteCoppel,''))='' OR
				TRIM(NVL(pAceptada,''))='' OR TRIM(NVL(pMotivo_rechazo,''))='' THEN
				LET cCodret	= "000001";
			ELSE
				SELECT COUNT(numcte)
				INTO iContador
				FROM "informix".si_club_proteccion
				WHERE empresa= TRIM(pEmpresa)
				AND numcte= TRIM(pCliente)
				AND numcte_coppel=TRIM(pCteCoppel)
				AND aceptada<>'1';

				IF NVL(iContador,0)>0 THEN
					DELETE FROM "informix".si_club_proteccion
					WHERE empresa= TRIM(pEmpresa)
					AND numcte= TRIM(pCliente)
					AND numcte_coppel=TRIM(pCteCoppel)
					AND aceptada<>1;
				END IF
				INSERT INTO "informix".si_club_proteccion (empresa,numcte,numcte_coppel,num_poliza,tipo_plan,suc_alta,ejecutivo,tipo_pago,num_tarjeta,
					num_cta,meses_pagar,monto_pagar,monto_mes,monto_total,aceptada,motivo_rechazo,tipo_mov,pago_mov,foliooperacion,fecha_alta,fecha_cambio,suc_cambio,fecha_vencimiento,tipoplan_ant)
					VALUES (pEmpresa,pCliente,pCteCoppel,pNumPoliza,pTipoPlan,pSucAlta,pEjecutivo,pTipopago,pNumtarjeta,pNumcta,pMesesPagar,pMontoPagar,pMontoMes,pMontoTotal,pAceptada,pMotivo_rechazo,' ',' ',pFolioOperacion,CURRENT,CURRENT,"",pFechaVencimiento,pTipoPlanAnt);
			END IF
		END IF
	END IF
	RETURN cCodret;
END
END PROCEDURE
