CREATE PROCEDURE "informix".sp_obtienepagosventa_club(pFecha DATE)
--DATOS A REGRESAR--
RETURNING CHAR(6) AS CodigoRetorno;

--DEFINICION DE VARIABLES--
DEFINE cCodret CHAR(6);
DEFINE vMensajeRet VARCHAR(80);
DEFINE iSqlErr INTEGER;
DEFINE iIsamErr INTEGER;
DEFINE vErrorInfo VARCHAR(80);
DEFINE vProceso VARCHAR(30);
DEFINE cSql CHAR(1024);
DEFINE cRuta CHAR(100);
DEFINE dFechaHoy DATE;
DEFINE cFechaArchivo CHAR(8);

--INICIALIZACION DE VARIABLES--
LET cCodret = '000';
LET vMensajeRet = '';
LET iSqlErr = 0;
LET iIsamErr = 0;
LET vErrorInfo = '';
LET vProceso = 'sp_obtienepagosventa_club';
LET cSql = '';
LET cRuta = '';
LET dFechaHoy = '';
LET cFechaArchivo = '';

--SET DEBUG FILE TO "/informix/IrisA/sp_obtienepagosventa_club.out";
--TRACE ON;

BEGIN
	ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
		IF iSqlErr <> 0 OR iIsamErr <> 0 THEN
			LET cCodret = iSqlErr;
			LET vMensajeRet = vErrorInfo;
			INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
				VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
			RETURN cCodret;
		END IF;
	END EXCEPTION;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 5;

	SELECT fecha_hoy INTO dFechaHoy FROM "informix".si_fechas WHERE empresa = '001';

	IF TRIM(NVL(dFechaHoy,'')) <> '' THEN

		SELECT valor INTO cRuta FROM "informix".si_param WHERE empresa = '001' AND cod_param = 319;

		IF TRIM(NVL(cRuta,'')) <> '' THEN

			IF TRIM(NVL(pFecha,'')) = '' THEN

				LET cFechaArchivo = YEAR(dFechaHoy) || LPAD(MONTH(dFechaHoy),2,'0') || LPAD(DAY(dFechaHoy),2,'0');

				LET cSql = '';
				LET cSql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cRuta) || 'club1' || TRIM(cFechaArchivo) || '.txt' || ' DELIMITER ' || '''|''' ||
							' SELECT d.fecha_alta, d.suc_alta, d.ejecutivo, d.numcte, d.tipo_plan ' ||
							' FROM bdisac:"informix".sac_movimientos a ' ||
							' INNER JOIN bdisac:"informix".sac_vta_cambio_seg b ON(b.numcliente = a.referencia1 AND b.recibo = a.referencia2 AND b.tipomovimiento = ''C'') ' ||
							' JOIN bdinteg:"informix".si_club_proteccion d ON(d.num_poliza = b.poliza AND aceptada = 1) ' ||
							' WHERE a.fecha_pago = ''' || dFechaHoy || ''' AND a.transacc_suc = ''8102'' AND a.status_cancelado = ''N'' ' ||
							' ORDER BY d.suc_alta, d.ejecutivo, d.numcte ' || ';' ||
							' " > pagosventaclub.sql';
				SYSTEM cSql; 

			ELSE

				LET cFechaArchivo = YEAR(pFecha) || LPAD(MONTH(pFecha),2,'0') || LPAD(DAY(pFecha),2,'0');

				LET cSql = '';
				LET cSql = 'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO ' || TRIM(cRuta) || 'club1' || TRIM(cFechaArchivo) || '.txt' || ' DELIMITER ' || '''|''' ||
							' SELECT d.fecha_alta, d.suc_alta, d.ejecutivo, d.numcte, d.tipo_plan ' ||
							' FROM bdisac:"informix".sac_movimientoshistorial a ' ||
							' INNER JOIN bdisac:"informix".sac_vta_cambio_seg b ON(b.numcliente = a.referencia1 AND b.recibo = a.referencia2 AND b.tipomovimiento = ''C'') ' ||
							' JOIN bdinteg:"informix".si_club_proteccion d ON(d.num_poliza = b.poliza AND aceptada = 1) ' ||
							' WHERE a.fecha_pago = ''' || pFecha || ''' AND a.transacc_suc = ''8102'' AND a.status_cancelado = ''N'' ' ||
							' ORDER BY d.suc_alta, d.ejecutivo, d.numcte ' || ';' ||
							' " > pagosventaclub.sql';
				SYSTEM cSql; 

			END IF;

			LET cSql = '';
			LET cSql = 'dbaccess bdinteg pagosventaclub.sql';
			SYSTEM cSql; 

			LET cSql = '';
			LET cSql = "sed 's/|$//g' " || TRIM(cRuta) || 'club1' || TRIM(cFechaArchivo) || '.txt' || " > " || TRIM(cRuta) || 'club' || TRIM(cFechaArchivo) || '.txt';
			SYSTEM cSql; 

			LET cSql = '';
			LET cSql = 'rm pagosventaclub.sql';
			SYSTEM cSql; 

			LET cSql = '';
			LET cSql = 'rm ' || TRIM(cRuta) || 'club1' || TRIM(cFechaArchivo) || '.txt';
			SYSTEM cSql; 
		ELSE
			LET cCodret = '002';
			LET vMensajeRet = 'No Existe Ruta';
		END IF;
	ELSE
		LET cCodret = '001';
		LET vMensajeRet = 'No Existe Fecha';
	END IF;

	IF cCodret <> '000' THEN
		INSERT INTO "informix".si_club_bitacoradomiciliacion(proceso, codigoretorno, mensajeretorno, fec_paquete)
			VALUES(vProceso, cCodret, vMensajeRet, dFechaHoy);
	END IF;

	RETURN cCodret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_agregarbitacora_bpipba(pFechaOper datetime year to second, pNumTrans char(4),pNumSuc char(4),pIdUsuario integer,pIpUsuario char(15),pFechaApli date,pCtaOrigen char(12),pCtaDesti char(18),pMonto money,pSecTrans char(16),pCgen1 char(40),pCgen2 char(40),pCgen3 char(40),pCgen4 char(40))
 returning char(5);
 
    -- Realizo   : Javier Alonso Chávez Trujillo
    -- Actividad : Agrega Bitacora
    -- Solicitó  : Mauricio Leon
    -- Fecha     : 25/11/2008
	--//////////////////////////////////////////
	-- Realizo   : Walber Castro
	-- Actividad : se modifica el tipo de dato del parametro de entrada Monto ya que redondeaba las cifras grandes.
	-- Solicitó  : Mauricio Leon
	-- Fecha     : 23/08/2010
	-- ////////////////////////////////////////
	-- Bibiana Gaxiola Verdugo
	-- Se agrega la actualización del movimiento en la tabla de cuentas frecuentes para la caducidad de las mismas.
	-- 21/01/2013
 
 --DEFINICION DE VARIABLES
DEFINE cod_ret char(5);
DEFINE sql_err integer;
DEFINE vCtasFrec CHAR(1);
DEFINE vNumCte CHAR(10);
DEFINE vCveCaducidad CHAR(1);

--INICIALIZA VARIABLES
LET cod_ret  = "000";

--SET DEBUG FILE TO "/home/informix/bibiana/sp_agregarbitacora_bpi.out";
--TRACE ON;

BEGIN
  ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF ;
   END EXCEPTION ;
   
	INSERT INTO si_bpibitacora(fecha_oper,  
			     id_operacion, 
			     sucursal, 
			     id_usuario,
			     ipusuario, 
			     fecha_aplic, 
			     cuenta_origen,
			     destino,
			     monto_oper, 
			     sec_transaccion,
			     cgenerico1,
			     cgenerico2,
			     cgenerico3,
			     cgenerico4) VALUES (pFechaOper,
						  pNumTrans,
						  pNumSuc,
						  pIdUsuario,
						  pIpUsuario,
						  pFechaApli,
						  pCtaOrigen,
						  pCtaDesti,
						  pMonto,
						  pSecTrans,
						  pCgen1,
						  pCgen2,
						  pCgen3,
						  pCgen4);
	--RETURN cod_ret;

		
		SELECT ctas_frec INTO vCtasFrec FROM bdibpi:"informix".bpi_cat_operaciones WHERE id_oper = pNumTrans;
		
		IF (vCtasFrec = '1') THEN --- Significa que son operaciones que involucran cuentas frecuentes
		
			SELECT numcliente INTO vNumCte FROM bdibpi:"informix".bpi_usuario WHERE id_usuario = pIdUsuario AND st_portal = 'activo';
		
			IF (pNumTrans IN ('1016','2100','2017','2020','2021','2022','2023')) THEN
				SELECT cve_caducidad INTO vCveCaducidad FROM bdiprog:"informix".pp_ctasterceros WHERE cuenta = pCtaDesti AND num_cte = vNumCte;

				IF (vCveCaducidad = '3') THEN
					UPDATE bdiprog:"informix".pp_ctasterceros SET fecha_movtos = today WHERE cuenta = pCtaDesti AND num_ctE = vNumCte;
					RETURN cod_ret;
				ELSE
					RETURN cod_ret;
				END IF;
			ELSE
			--IN ('1015','1017','1020','1021','1022','1023','1024','1025')) THEN 
				SELECT cve_caducidad INTO vCveCaducidad FROM bdiprog:"informix".pp_ctasterceros WHERE cuenta = pCgen2 AND num_cte = vNumCte;
			
				IF (vCveCaducidad = '3') THEN
					UPDATE bdiprog:"informix".pp_ctasterceros SET fecha_movtos = today WHERE cuenta = pCgen2 AND num_ctE = vNumCte;
					RETURN cod_ret;
				ELSE
					RETURN cod_ret;
				END IF;
			END IF;
			
		END IF;
		RETURN cod_ret;
	--END IF;
	--RETURN cod_ret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_agregarbitacora_bpi_pba(
