"-- BD............: bdinteg";

CREATE PROCEDURE "informix".sp_relacion_consultainfocte (pNumcte CHAR(20), pOpcion CHAR(1))
	RETURNING
	CHAR(6)  AS COD_RET, 
	CHAR(100) AS MENSAJE_RETORNO,
	CHAR(20) AS NUM_CLIENTE,
	CHAR(107) AS NOMBRE_CLIENTE,
	/*CHAR(10)*/ DATE AS FECHA_NAC,
	SMALLINT  AS TIPO_RELACION,
	CHAR(100)  AS DESCRIPCION_TIPO_RELACION,
	CHAR(107) AS NOMBRE_ANALISTA,
	CHAR(20) AS NUM_CLIENTE_COPPEL,
	CHAR(104) AS NOMBRE_CLIENTE_COPPEL,
	CHAR(10) AS FECHA_NAC_COPPEL,
	CHAR(10) AS FECHA_RELACION,
	DECIMAL(5,2) AS EFICIENCIA,
	SMALLINT AS MESES_HISTORIA,
	CHAR(1) AS PUNTUALIDAD,
	DECIMAL(14,6) AS VENCIDO_UDIS,
	CHAR(1) AS SITUACION_ESPECIAL,
	SMALLINT AS CAUSA_SITESP,
	CHAR(100) AS DESCRIPCION_CAUSA_SITESP,
	CHAR(26) AS nombre1,
	CHAR(26) AS nombre2,
	CHAR(26) AS apell_paterno,
	CHAR(26) AS apell_materno,
	CHAR(4) AS sucursal,
	CHAR(13) AS RFC,
	CHAR(10) AS Fecha_consulta,
	DECIMAL(14,6) AS dabonomes;
	
-- Modificado por: Abrham López López, 26 Marzo 2013 Se modifica el campo FECHA_NAC a DATE 
-- para que ponga correcta la fecha en pantalla con formato dd/mm/aaaa
-- Modificado por Maria Elena Angulo (AAME). 30 Agosto 2013 Se modifica para anexar nuevo campo "dabonomes" para guardar 
-- y retornar el abono Mensual del Cliente.
	
---DECLARACIONES
DEFINE iSqlErr         	  INTEGER;
DEFINE iIsamErr        	  INTEGER;
DEFINE cErrorInfo      	  CHAR(100);
DEFINE cCodRet         	  CHAR(6);
DEFINE cCodRetUDI         CHAR(6);
DEFINE cMensajeRet     	  CHAR(80);

DEFINE cNumcte      	  CHAR(20);
DEFINE cNumSol      	  CHAR(20);
DEFINE cNombreCte      	  CHAR(107);
DEFINE cFechaNac     	  CHAR(10);
DEFINE sTipoRel        	  SMALLINT;
DEFINE cDesTipoRel        CHAR(100);

DEFINE cNomEmpleado       CHAR(107);
DEFINE cNumRef      	  CHAR(20);
DEFINE cNombre_coppel     CHAR(107);
DEFINE cFechaNacCoppel    CHAR(10);
DEFINE cFechaRelacion     CHAR(10);

DEFINE dSituacion_pago    DECIMAL(5,2);
DEFINE sMeses_historia    SMALLINT;
DEFINE cPuntualidad       CHAR(1);
DEFINE dVencidoUdis       DECIMAL(14,2);
DEFINE cSituacion_credito CHAR(1);
DEFINE sCausa 			  SMALLINT;
DEFINE cDesCausa   		  CHAR(100);

DEFINE cNombre1   		  CHAR(26);
DEFINE cNombre2   		  CHAR(26);
DEFINE cApellPaterno   	  CHAR(26);
DEFINE cApellMaterno   	  CHAR(26);

DEFINE cRfc   	          CHAR(13);
DEFINE cSucursal   	      CHAR(4);
DEFINE dcValorUDI         DECIMAL(14,6);
DEFINE dcVencidocoppel    DECIMAL(14,6);
DEFINE dtFechaCons        CHAR(10);
DEFINE dabonomes          DECIMAL(14,6); --AAME. RQM 09 333 Se define variable para el nuevo campo a retornar.
DEFINE cNumcteBco		  CHAR(20);



---INICIALIZACIONES
LET iSqlErr            	= 0;
LET iIsamErr           	= 0;
LET cErrorInfo         	= "";
LET cCodRet            	= "000000";
LET cMensajeRet        	= "PROCESO EXITOSO";   

LET cNumcte      		= "";
LET cNumSol      		= "";
LET cNombreCte      	= "";
LET cFechaNac      	    = "";
LET sTipoRel        	= 0;
LET cDesTipoRel     	= "";
LET cNomEmpleado    	= "";
LET cNumRef      		= "";
LET cNombre_coppel  	= "";
LET cFechaNacCoppel     = "";
LET cFechaRelacion      = "";

LET dSituacion_pago 	= 0;
LET sMeses_historia  	= 0;
LET cPuntualidad     	= "";
LET dVencidoUdis    	= 0;
LET cSituacion_credito  = "0";
LET sCausa 				= 0;
LET cDesCausa   		= "";
LET cNombre1   		    = "";
LET cNombre2   		    = "";
LET cApellPaterno       = "";
LET cApellMaterno       = "";

LET cRfc   	            = "";
LET cSucursal           = "";
LET cCodRetUDI          = '00000';
LET dcValorUDI          = 0.00;
LET dcVencidocoppel     = 0.00;
LET dtFechaCons         = "";
LET dabonomes           = 0.00; --AAME. RQM 09 333 Se inicia variable para el nuevo campo a retornar.
LET cNumcteBco          = '';
	
BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
          LET cCodRet = iSqlErr;
          LET cMensajeRet = cErrorInfo;
          RETURN cCodRet,cMensajeRet,"","","",0,"","","","","","",0,0,"",0,"",0,"","","","","","","","",0.00;
		 
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	--SET DEBUG FILE TO "/informix/jesus/sp_relacion_consultainfocte.out";
	--TRACE ON;
	
	-- VALIDA LOS PARAMETROS DE ENTRADA
	IF NVL(pNumcte,"") = "" AND NVL(pOpcion,"") = "" THEN
		LET cCodRet = '000001';
		LET cMensajeRet = 'Parametros de entrada incompletos,verifique';
	ELSE--obtiene la información del cliente
	
		IF pOpcion = 0 THEN
			LET cNumcteBco = pNumcte;  
		ELIF pOpcion = 1 THEN
			SELECT LIMIT 1 numcte_banco
			INTO cNumcteBco
			FROM bdinteg:"informix".si_relacion_ctebcplcpl
			WHERE cliente = pNumcte;
		END IF;
		
		IF NVL(cNumcteBco,'') <> '' THEN
			SELECT a.numcte,a.nombre1,a.nombre2,a.apell_paterno,a.apell_materno,a.numcte_ref,b.fecha_nac,a.rfc,a.sucursal
				INTO cNumcte,cNombre1,cNombre2,cApellPaterno,cApellMaterno,cNumRef,cFechaNac,cRfc,cSucursal
			FROM bdinteg:"informix".si_cliente a,
				 bdinteg:"informix".si_ctepf b 
			WHERE a.empresa = b.empresa
			AND a.numcte = b.numcte
			AND a.numcte = cNumcteBco;
				
			LET cNombreCte = TRIM(cNombre1)||" "||TRIM(cNombre2)||" "||TRIM(cApellPaterno)||" "||TRIM(cApellMaterno);
			
			IF NVL(cNumcte,"") = "" THEN
				LET cCodRet = '000003';
				LET cMensajeRet = 'Número de cliente no existe, verifique';
			ELIF NVL(cNumRef,"") = "" THEN
				 LET cCodRet = '000002';
				 LET cMensajeRet = 'No se encontro información en Coppel. Favor de Validar el número de Cliente Coppel';
			ELSE	
			
				/*
				IF EXISTS (SELECT nombre_coppel FROM bdisolic:"informix".ss_bitacora_precal WHERE empresa = '001' 	AND num_referencia = cNumRef ) THEN
					
					SELECT nombre_coppel
						INTO cNombre_coppel
					FROM bdisolic:"informix".ss_bitacora_precal 
					WHERE empresa = '001' 
					AND num_referencia = cNumRef 
					AND ROWID = (SELECT MAX(ROWID)
									FROM  bdisolic:"informix".ss_bitacora_precal aux2
									WHERE aux2.empresa = '001' 
									AND aux2.num_referencia = cNumRef);							
				END IF;
				*/
				--
				
				--
				SELECT a.tipo_relacion,b.nombre,a.fecha_insert
					INTO sTipoRel,cNomEmpleado,cFechaRelacion
				FROM bdinteg:"informix".si_relacion_ctebcplcpl a
				LEFT OUTER JOIN bdinteg:"informix".si_ejecut b ON(a.empresa = b.empresa AND a.numempleado =  b.ejecutivo)
				WHERE a.empresa = '001'
				AND numcte_banco = cNumcteBco
				AND a.cliente = cNumRef	;
				
				SELECT valor_alfabetico
					INTO cDesTipoRel
				FROM  bdicobranza:"informix".cb_param_campania
				WHERE grupo_parametro ="TIPO_RELAC"
				AND valor_numerico = NVL(sTipoRel,0);
				
				IF NVL(sTipoRel,0) = 0 THEN
						LET cNomEmpleado 		= '';
						LET cNumRef 			= '';
						LET cFechaRelacion 	= '';
				END IF;
			END IF;		CALL bdicred:"informix".determina_udi("001", TODAY) RETURNING cCodRetUDI, dcValorUDI;
			IF NVL(sTipoRel,0) <> 3 THEN --VALIDACION DEL TIPO DE RELACION.
					 --valida si el cliente cuenta con solicitudes de credito
				 IF EXISTS (SELECT num_solicitud FROM bdisolic:"informix".ss_solicitudes WHERE empresa = '001' 	AND        numcte = cNumcteBco ) THEN
					 SELECT NVL(num_solicitud,"")
					 INTO cNumSol
					 FROM bdisolic:"informix".ss_solicitudes  
					 WHERE empresa = '001'
					 AND numcte = cNumcteBco
					 AND ROWID = (SELECT MAX(ROWID)
					 FROM  bdisolic:"informix".ss_solicitudes aux
					 WHERE aux.empresa = '001'
					 AND aux.numcte = cNumcteBco );		

						--obtiene la información de la ultima consulta a coppel de la solicitud obtenida anteriormente
					SELECT situacion_pago,meses_historia, puntualidad,situacion_credito,causa,(vencidoropa + vencidomuebles + vencidoprestamos),(abonomensualropa + abonomensualmuebles + abonomensualprestamos)
					INTO dSituacion_pago,sMeses_historia, cPuntualidad,cSituacion_credito,sCausa,dcVencidocoppel,dabonomes-- AAME RQM 09 333 Se agrega nuevo campo para anexar el Abono Mensual del cliente 
					FROM  bdisolic:"informix".ss_resum_scor_fin 
					WHERE empresa = '001'
					AND num_solicitud = cNumSol;
				
						--obtiene la descripcion de la causa 
					SELECT {+INDEX(bdisitesp:se_catsitesp idx_catsitesp)} descripcion
					INTO  cDesCausa
					FROM bdisitesp:"informix".se_catsitesp
					WHERE situacion = TRIM(cSituacion_credito)
					AND causa = sCausa;
				 END IF; --FIN DE VALIDA SI EL CLIENTE CUENTA CON SOLICITUDES DE CREDITO	
			ELSE

				SELECT eficiencia,meseshist,puntualidad,sitespecial,causa,(vdoropa+vdomuebles+vdoprestamos),nombrecop,fechanaccop,fecha_consulta,(abonomesropa + abonomesmuebles + abonomesprestamos)
				INTO dSituacion_pago,sMeses_historia, cPuntualidad,cSituacion_credito,sCausa,dcVencidocoppel,cNombre_coppel,cFechaNacCoppel,dtFechaCons,dabonomes -- AAME RQM 09 333 Se agrega nuevo campo para anexar el Abono Mensual del cliente 
				FROM bdisolic:"informix".ss_respuesta_conscoppel
				WHERE empresa = '001'
				AND numcte = cNumcteBco		
				AND numcte_ref = cNumRef;
				
				IF DBINFO("sqlca.sqlerrd2") = 0 THEN
					LET dSituacion_pago ="";
					LET sMeses_historia ="";
					LET cPuntualidad ="";
					LET cSituacion_credito ="";
					LET  sCausa ="";
					LET dcVencidocoppel ="";
					LET cNombre_coppel ="";
					LET cFechaNacCoppel="";
					LET dtFechaCons="";
				ELSE
					IF NVL(cSituacion_credito,'' ) <> '' AND NVL(sCausa,0) <> 0 THEN
				 --obtiene la descripcion de la causa 
						SELECT {+INDEX(bdisitesp:se_catsitesp idx_catsitesp)} descripcion
						INTO  cDesCausa
						FROM bdisitesp:"informix".se_catsitesp
						WHERE situacion = TRIM(cSituacion_credito)
						AND causa = sCausa;						
						
						IF DBINFO("sqlca.sqlerrd2") = 0 THEN
							SELECT descripcion 
							INTO cDesCausa 
							FROM bdicred:"informix".sd_situacion_cred 
							WHERE situacion = TRIM(cSituacion_credito);		
						END IF; --FIN DE SI ARROJO O NO INFORMACION DE LA CAUSA
					END IF; --FIN DE LA OBTENCIÓN DE DESCRIPCION DE LA CAUSA
				END IF;		
			END IF;	--FIN DE VALIDACION DEL TIPO DE RELACION
		ELSE
			LET cCodRet = '000003';
			LET cMensajeRet = 'Número de cliente no existe, verifique';
		END IF;
	END IF;	--FIN DE VALIDACION DE LOS PARAMETROS DE ENTRADA
	LET dVencidoUdis = CASE WHEN dcValorUDI <= 0 THEN 0 ELSE dcVencidocoppel / dcValorUDI END;
		
	RETURN cCodRet,TRIM(cMensajeRet),cNumcteBco,NVL(cNombreCte,""),NVL(cFechaNac,""),NVL(sTipoRel,0),NVL(cDesTipoRel,""),NVL(cNomEmpleado,""),NVL(cNumRef,''),NVL(cNombre_coppel,""),	
        	NVL(cFechaNacCoppel,""),NVL(cFechaRelacion,""),NVL(dSituacion_pago,0),NVL(sMeses_historia,0), NVL(cPuntualidad,""),NVL(dVencidoUdis,0),
			NVL(cSituacion_credito,"0"),NVL(sCausa,0),NVL(cDesCausa,""),NVL(cNombre1,''),NVL(cNombre2,''),NVL(cApellPaterno,''),NVL(cApellMaterno,''),NVL(cSucursal,''),NVL(cRfc,''),NVL(dtFechaCons,''),NVL(dabonomes,0.00);
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Genera una consulta para obtener la información general del cliente en bancoppel y coppel', 
'AUTOR: Jesús Aguilar ',
'FECHA: 26 ABRIL 2012',
'BD: BDINTEG',
'VERSION: 20120426.1641',

'Modificación',
'DESCRIPCION: Se modificó para omitir las consultas a  los campos que son Fecha Nac, Nombre del Cliente', 'Eficiencia, Meses de Historia, Puntualidad, Vencidos UDIS, Situación Especial, Causa y Descripción SE en caso de', 'tener al tipo de relación ?3?', 
'AUTOR: Josué Remberto Zazueta Acosta ',
'FECHA: 28  de Junio 2012',
'BD: BDINTEG',
'VERSION: 20120628.1230',

'Modificación',
'DESCRIPCION: Se modifica para que no regrese nombre del empleado,fecha de relacion y numero de referencia en caso', 'de que la el tipo de relacion sea = 0', 
'AUTOR: Josué Remberto Zazueta Acosta ',
'FECHA: 27  de Julio 2012',
'BD: BDINTEG',
'VERSION: 20120727.0518',

'Modificación',
'DESCRIPCION: se agrega opcion de iniciar la conculta con un numero de cliente coppel', 
'AUTOR: Felipe Urias',
'FECHA: 07  de Enero 2015',
'BD: BDINTEG',
'VERSION: 20150107.1326';

CREATE PROCEDURE "informix".spregresahuellac_pba( ptipo CHAR(1), pnumcte CHAR(20), pfechaini DATE, pfechafin DATE )
RETURNING INTEGER, char(20), SMALLINT, CHAR(1), CHAR(942), CHAR(942), CHAR(8), CHAR(4), DATE, CHAR(8), DATE, CHAR(1), char(20);

    define vcodret INTEGER;
    define vcodret2 INTEGER;
    define vcodret3 CHAR(40);
    define vexiste CHAR(1);
    define vsqlerr INTEGER;
    define visamerr INTEGER;
    define vinfoerr CHAR(40);

    define vcliente char(20);
    define vsecuencia smallint ;
    define vstatus char(1);
    define vmapad  char(942);
    define vmapai  char(942);
    define vusuario char(8);
    define vsucursal char(4);
    define vfechaalta date ;
    define vusuariocambio char(8);
    define vfechacambio date ;
    define vsexo char(1);
    define vclienteref char(20);
    define vfecha_hoy date;
    
    --- SET DEBUG FILE TO "/tmp/spregresahuellac.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET vsqlerr,visamerr,vinfoerr
        IF vsqlerr != 0 THEN
            SET DEBUG FILE TO "/resplogifx/conciliachq/spregresahuellac.err";
            TRACE ON;
            LET vcodret = vsqlerr;
            LET vcodret2 = visamerr;
            LET vcodret3 = vinfoerr;
            RETURN vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref;
        END IF;
    END EXCEPTION;

    LET vcodret = 1;
    LET vcodret2 = 0;
    LET vcodret3 = '';
    LET vexiste = 0;

    LET vcliente = '';
    LET vsecuencia = 0;
    LET vstatus = '';
    LET vmapad = '';
    LET vmapai = '';
    LET vusuario = '';
    LET vsucursal = '';
    LET vfechaalta = '';
    LET vusuariocambio = '';
    LET vfechacambio = '';
    LET vsexo = '';
    LET vclienteref = '';

    set isolation to dirty read;

    /* Verifica recepcion correcta de datos */
    if ptipo is null or Trim(ptipo) = '' then
        let vcodret = 110;
        return vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref ;
    elif pfechaini is null  then
        let vcodret = 120;
        return vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref ;
    elif pfechafin is null  then
        let vcodret = 130;
        return vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref ;
    end if;
    
    create temp table tmp_huellas_ctes(
        numcte          char(20),
        secuencia       smallint,
        estado          char(1),
        dmapa           char(942),
        imapa           char(942),
        usuario         char(8),
        sucursal        char(4),
        fecha_alta      date,
        usuario_camb    char(8),
        fecha_camb      date,
        sexo            char(1),
        numcte_ref      char(20)   
    ) with no log;
begin;
    create index idx_fecalta_tmp on tmp_huellas_ctes(fecha_alta) online;
commit;
begin;
    create index idx_feccamb_tmp on tmp_huellas_ctes(fecha_camb) online;
commit;
    update statistics medium for table tmp_huellas_ctes(fecha_alta,fecha_camb) resolution 1.5;
    
    select fecha_hoy
      into vfecha_hoy
      from si_fechas
     where empresa = '001';
    
    -- // POR FECHA DE ALTA
    if ptipo = '1' then
        foreach
            select {+INDEX(si_cte_huella idx_si_cte_hue2)}
                   nvl(ch.numcte,''), nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''), 
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.fecha_alta > pfechaini
               and ch.fecha_alta <= vfecha_hoy

            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0') 
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;
        
        foreach
            select {+INDEX(bdisolic:ss_solicitudes ix_soln4)}
                   sol.numcte
              into vcliente
              from bdisolic:ss_solicitudes sol
             where sol.fecha_insert > pfechaini
               and sol.fecha_insert <= vfecha_hoy
            
            select {+INDEX(si_cte_huella ix_huellanew)}
                   nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''), 
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.numcte = vcliente
               and ch.secuencia = (select max(secuencia) from si_cte_huella where numcte = vcliente);

            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0') 
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;

    -- // INACTIVAS
    elif ptipo = '2' then

        foreach
            select {+INDEX(si_cte_huella idx_si_cte_hue3)}
                   nvl(ch.numcte,''), nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.fecha_camb >= pfechaini 
               and ch.fecha_camb <= vfecha_hoy
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;
        
        foreach
            select {+INDEX(bdisolic:ss_solicitudes ix_soln4)}
                   sol.numcte
              into vcliente
              from bdisolic:ss_solicitudes sol
             where sol.fecha_insert >= pfechaini
               and sol.fecha_insert <= vfecha_hoy
        
            select {+INDEX(si_cte_huella ix_huellanew)}
                   nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.numcte = vcliente
               and ch.secuencia = (select max(secuencia) from si_cte_huella where numcte = vcliente);
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;

    -- // POR CLIENTE
    elif ptipo = '3' then

        foreach
            select nvl(ch.numcte,''), nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.numcte = trim(pnumcte)
               and ch.estado = "A"
               
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
             
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;

    -- // ENTRE FECHAS
    elif ptipo = '4' then

        foreach
            select {+INDEX(si_cte_huella idx_si_cte_hue2)}
                   nvl(ch.numcte,''), nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.fecha_alta >= pfechaini 
               and ch.fecha_alta <= pfechafin
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;
        
        foreach
            select {+INDEX(bdisolic:ss_solicitudes ix_soln4)}
                   sol.numcte
              into vcliente
              from bdisolic:ss_solicitudes sol
             where sol.fecha_insert >= pfechaini
               and sol.fecha_insert <= pfechafin
        
            select {+INDEX(si_cte_huella ix_huellanew)}
                   nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.numcte = vcliente
               and ch.secuencia = (select max(secuencia) from si_cte_huella where numcte = vcliente);
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;
        
    -- // INACTIVAS ENTRE FECHAS
    elif ptipo = '5' then

        foreach
            select {+INDEX(si_cte_huella idx_si_cte_hue3)}
                   nvl(ch.numcte,''), nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.fecha_camb >= pfechaini 
               and ch.fecha_camb <= pfechafin
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;
        
        foreach
            select {+INDEX(bdisolic:ss_solicitudes ix_soln4)}
                   sol.numcte
              into vcliente
              from bdisolic:ss_solicitudes sol
             where sol.fecha_insert >= pfechaini 
               and sol.fecha_insert <= pfechafin
        
            select {+INDEX(si_cte_huella ix_huellanew)}
                   nvl(ch.secuencia,0), nvl(ch.estado,''), nvl(ch.dmapa,''), nvl(ch.imapa,''), nvl(ch.usuario,''),
                   nvl(ch.sucursal,''), nvl(ch.fecha_alta,mdy(1,1,1900)), nvl(ch.usuario_camb,''), nvl(ch.fecha_camb,mdy(1,1,1900))
              into vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio
              from si_cte_huella ch
             where ch.numcte = vcliente
               and ch.secuencia = (select max(secuencia) from si_cte_huella where numcte = vcliente);
             
            select nvl(cp.sexo,''), nvl(trim(ct.numcte_ref),'0')
              into vsexo, vclienteref
              from si_cliente ct,
                   si_ctepf cp
             where ct.numcte = vcliente
               and cp.numcte = ct.numcte;
               
            insert into tmp_huellas_ctes (numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref)
            values(vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref);
        end foreach;

    end if;
    
    update statistics medium for table tmp_huellas_ctes;
    
    if ptipo in('1','3','4') then 
    
        foreach
            select numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref
              from tmp_huellas_ctes
             order by fecha_alta asc
            
            return vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref with resume;
        end foreach;
        
    elif ptipo in('2','5') then 
    
        foreach
            select numcte, secuencia, estado, dmapa, imapa, usuario, sucursal, fecha_alta, usuario_camb, fecha_camb, sexo, numcte_ref
              into vcliente, vsecuencia, vstatus, vmapad, vmapai, vusuario, vsucursal, vfechaalta, vusuariocambio, vfechacambio, vsexo, vclienteref
              from tmp_huellas_ctes
             order by fecha_camb asc
            
            return vcodret,vcliente,vsecuencia,vstatus,vmapad,vmapai,vusuario,vsucursal,vfechaalta,vusuariocambio,vfechacambio,vsexo,vclienteref with resume;
        end foreach;
    
    end if;

    END;
    
END PROCEDURE

DOCUMENT
"DESCRIPCION: Consulta de huellas de cliente para replicacion ",
"AUTOR : Daniel Zambada ",
"MODIFICO : Daniel Zambada",
"FECHA : 21/01/2008",
"MODIFICO : Saul Ivanhoe",
"FECHA : 01/02/2008",
"BD    : bdinteg",
"VER   : 1.3",
"MODIFICO : JICS",
"FECHA : 14/Marzo/2011",
"BD    : bdinteg",
"VER   : 2.0";

CREATE PROCEDURE "informix".sp_consultadomiciliocajera_pba( pModo SMALLINT, pCliente CHAR(20) )
	--- pModo = 1 - Consulta de Domicilio Personal
	--- pModo = 2 - Consulta de Domicilio del Trabajo
	RETURNING CHAR(6) AS cCodRet ,CHAR(26) AS cApellidoPaterno,CHAR(26) AS cApellidoMaterno,CHAR(26) AS cNombre1,
		CHAR(26) AS cNombre2,CHAR(15) AS cNombreCiudad,CHAR(30) AS cNombreZona,CHAR(10) AS cNumeroExterior,CHAR(10) AS cNumeroInterior,
		CHAR(6) AS cDepto,CHAR(1) AS cRumbo,CHAR(30) AS cNombreCalle,CHAR(5) AS cCodigoPostal,CHAR(80) AS cObservaciones,CHAR(13) AS cTelefonoParticular,
		CHAR(13)AS cTelefonoCelular,CHAR(13) AS cTelefonoTrabajo,CHAR(13) AS cTelefonoReferencia,CHAR(40) AS cEntreCalles,CHAR(2) AS cEstado,
		CHAR(30) AS cNombreEstado,CHAR(60) AS cLugarTrabajo,CHAR(2) AS cUnidad,CHAR(3) AS cCiudad,INTEGER AS iColonia,INTEGER AS iCalle,INTEGER AS iManzana,
		INTEGER AS iOtros,INTEGER AS iAndador,INTEGER AS iEtapa,INTEGER AS iLote,INTEGER AS iEdificio,INTEGER AS iEntrada,INTEGER AS iCiudadCoppel, CHAR(100) AS cEmail;
			  
			  
		DEFINE isqlerr INTEGER;
		DEFINE cCodRet CHAR(6);
		DEFINE cApellidoPaterno CHAR(26);
		DEFINE cApellidoMaterno CHAR(26);
		DEFINE cNombre1 CHAR(26);
		DEFINE cNombre2 CHAR(26);
		DEFINE cNombreCiudad CHAR(15);
		DEFINE cNombreZona CHAR(30);
		DEFINE cNumeroExterior CHAR(10);
		DEFINE cNumeroInterior CHAR(10);
		DEFINE cDepto CHAR(6);
		DEFINE cRumbo CHAR(1);
		DEFINE cNombreCalle CHAR(30);
		DEFINE cCodigoPostal CHAR(5);
		DEFINE cObservaciones CHAR(80);
		DEFINE cTelefonoParticular CHAR(13);
		DEFINE cTelefonoCelular CHAR(13);
		DEFINE cTelefonoReferencia CHAR(13);
		DEFINE cTelefonoTrabajo CHAR(13);
		DEFINE cEntreCalles CHAR(40);
		DEFINE cCiudad CHAR(3);
		DEFINE iColonia INTEGER ;
		DEFINE iCalle INTEGER ;
		DEFINE cUnidad CHAR(2);
		DEFINE iManzana INTEGER ;
		DEFINE iOtros INTEGER ;
		DEFINE iAndador INTEGER ;
		DEFINE iEtapa INTEGER ;
		DEFINE iLote INTEGER ;
		DEFINE iEdificio INTEGER ;
		DEFINE iEntrada INTEGER ;
		DEFINE cEstado CHAR(2);
		DEFINE cNombreEstado CHAR(30);
		DEFINE cLugarTrabajo CHAR(60);
		DEFINE iCiudadCoppel INTEGER ;
		DEFINE cEmail CHAR(100);
		
		DEFINE cNumSolicitud CHAR(20);
		DEFINE cNumSolicitud2 CHAR(20);
		DEFINE dFecha1 DATE;
		DEFINE dFecha2 DATE;
		DEFINE cProducto CHAR(4);

		LET isqlerr = 0;
		LET cCodRet = "";
		LET cApellidoPaterno = " ";
		LET cApellidoMaterno = " ";
		LET cNombre1 = " ";
		LET cNombre2 = " ";
		LET cNombreCiudad = " ";
		LET cNombreZona = " ";
		LET cNumeroExterior = " ";
		LET cNumeroInterior = " ";
		LET cDepto = " ";
		LET cRumbo = " ";
		LET cNombreCalle = " ";
		LET cCodigoPostal = " ";
		LET cObservaciones = " ";
		LET cTelefonoParticular = " ";
		LET cTelefonoCelular = " ";
		LET cTelefonoReferencia = " ";
		LET cTelefonoTrabajo = " ";
		LET cEntreCalles = " ";
		LET cCiudad = "";
		LET iColonia = 0;
		LET iCalle = 0;
		LET cUnidad= "N";
		LET iManzana = 0;
		LET iOtros = 0;
		LET iAndador = 0;
		LET iEtapa = 0;
		LET iLote = 0;
		LET iEdificio = 0;
		LET iEntrada = 0;
		LET cEstado = " ";
		LET cNombreEstado = " ";
		LET cLugarTrabajo = " ";
		LET iCiudadCoppel = 0;
		LET cEmail = " ";

		LET cNumSolicitud = '';
		LET cNumSolicitud2 = '';
		LET dFecha1 = '01/01/1900';
		LET dFecha2 = '01/01/1900';
		LET cProducto = '';

		--SET DEBUG FILE TO "/respaldosbd/AnahiLeyva/sp_consultadomiciliocajera.out";
		--TRACE ON;
		
		BEGIN

		ON EXCEPTION SET isqlerr
			IF isqlerr <> 0 THEN
				LET cCodRet = isqlerr;
				RETURN cCodRet,cApellidoPaterno,cApellidoMaterno,cNombre1,cNombre2,cNombreCiudad,cNombreZona,cNumeroExterior,cNumeroInterior,cDepto,cRumbo,
						cNombreCalle,cCodigoPostal,cObservaciones,cTelefonoParticular,cTelefonoCelular,cTelefonoTrabajo,cTelefonoReferencia,cEntreCalles,
						cEstado,cNombreEstado,cLugarTrabajo,cUnidad,cCiudad,iColonia,iCalle,iManzana,iOtros,iAndador,iEtapa,iLote,iEdificio,iEntrada,iCiudadCoppel,cEmail;
			END IF;
		END EXCEPTION;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;   
		
		--Se obtiene numero de solicitud
			SELECT limit 1 fecha_apertura, num_credito 		
			INTO dFecha1, cNumsolicitud
			FROM bdicred:"informix".sd_maecred 
			WHERE numcte   =  pCliente 
			AND fecha_apertura = (SELECT MAX(fecha_apertura)
								FROM bdicred:"informix".sd_maecred 
								WHERE numcte   =  pCliente );
			
			SELECT  limit 1 fecha_apertura, num_credito, num_producto 
			INTO dFecha2, cNumsolicitud2, cProducto
			FROM bdicred:"informix".sd_maecredcrd
			WHERE numcte = pCliente
			AND  fecha_apertura = (SELECT MAX (fecha_apertura) 
								FROM bdicred:"informix".sd_maecredcrd
								WHERE numcte   =  pCliente );
		
		IF dFecha1 IS NULL OR dFecha1 = "" THEN
			LET dFecha1 = '01/01/1900';
		END IF;
		
		IF dFecha2 IS NULL OR dFecha2 = ""  THEN
			LET dFecha2 = '01/01/1900';
		END IF;
		
		IF dfecha1 < dFecha2 THEN		
			IF cProducto = '6011' THEN
				SELECT num_credito 		
				INTO cNumsolicitud
				FROM bdicred:"informix".sd_maecred 
				WHERE credito_externo =  cNumsolicitud2;
			ELSE
				LET cNumsolicitud = cNumsolicitud2;
			END IF;
		END IF;		
			
		IF NVL(cNumSolicitud, '') <> '' THEN
			--Obtener el numero de telefono		
			SELECT telefono_ref 
			INTO cTelefonoReferencia  
			FROM bdisolic:"informix".ss_refpersonales 
			WHERE numcte = pCliente AND num_solicitud = cNumSolicitud
			AND numcte_ref = 'R1';

			IF NVL(cTelefonoReferencia,'') = '' THEN
				SELECT  first 1 b.telefono1 
				INTO  cTelefonoReferencia 
				FROM bdinteg:"informix".si_refclientes a, bdinteg:"informix".si_refdirecciones b
				WHERE a.empresa = '001'
				  and a.num_solicitud = cNumSolicitud
				  and a.numcte = pCliente
				  AND a.numcte = b.numcte 
				  AND a.secuencia = b.secuencia ;
			END IF;
			let cTelefonoReferencia = nvl(cTelefonoReferencia,'');
			--IF NVL(cTelefonoReferencia,'') <> '' THEN
				SELECT '000',NVL(t1.apell_paterno,''), NVL(t1.apell_materno,''), NVL(t1.nombre1,''), NVL(t1.nombre2,''), 
				NVL(t2.ciudad,0), NVL(t2.numerocolonia,0), NVL(t2.numeroextcalle,''), NVL(t2.numerointcalle,''),NVL(t2.departamento,''), 
				NVL(t2.puntocardinal,''), NVL(t2.numerocalle,0), NVL(t2.cod_postal,''), NVL(t2.observaciones,''), NVL(t2.manzana,0)::INTEGER, 
				NVL(t2.otros,0)::INTEGER, NVL(t2.andador,0)::INTEGER, NVL(t2.etapa,0)::INTEGER, NVL(t2.lote,0)::INTEGER, NVL(t2.edificio,0)::INTEGER,
				NVL(t2.entrada,0)::INTEGER, NVL(t9.telefono,''), NVL(t92.telefono,''), NVL(t93.telefono,''),
				--t7.telefono_ref as referencia, 
				NVL(t3.nombre,''), NVL(t4.nombrecalle,''), NVL(t5.nombrezona,''), NVL(t2.entre_calles,''), NVL(t2.estado,''), NVL(t6.nombre,''),--<--si_estados
				NVL((SELECT nombre_empresa
							FROM "informix".SI_INGRESOS ING1 
							WHERE ING1.tipo_ingreso = 'T'
							AND ING1.sec_ingreso = ( SELECT MAX(ING2.sec_ingreso)
														FROM "informix".si_ingresos ING2 
														WHERE t1.EMPRESA = ING2.EMPRESA 
														AND t1.NUMCTE = ING2.NUMCTE 
														AND ING2.tipo_ingreso = 'T') 
							AND t1.EMPRESA = ING1.EMPRESA 
							AND t1.NUMCTE = ING1.NUMCTE),''),
							NVL(t2.unidadhabitac,'N'), NVL(t3.ciudad_coppel,0)::INTEGER, NVL(t10.correo_elec,'')
				INTO cCodRet ,cApellidoPaterno, cApellidoMaterno, cNombre1, cNombre2, 
				cCiudad, iColonia, cNumeroExterior, cNumeroInterior, cDepto, 
				cRumbo, iCalle, cCodigoPostal, cObservaciones, iManzana, 
				iOtros, iAndador, iEtapa, iLote, iEdificio,
				iEntrada, cTelefonoParticular, cTelefonoCelular, cTelefonoTrabajo, 
				--cTelefonoReferencia, 
				cNombreCiudad, cNombreCalle, cNombreZona, cEntreCalles, cEstado, cNombreEstado, 
				cLugarTrabajo, 
				cUnidad, iCiudadCoppel, cEmail
				FROM "informix".si_cliente t1
				LEFT JOIN "informix".si_direcciones_actual t2 ON (t1.numcte = t2.numcte AND t2.tipo_dir = pModo) --- AND t2.secuencia = (SELECT MAX(t6.secuencia) FROM bdinteg:si_direcciones t6 WHERE t6.numcte = t1.numcte AND t6.tipo_dir = t2.tipo_dir )) 
				LEFT JOIN "informix".si_ciudades t3 ON t2.ciudad = t3.ciudad AND t2.estado = t3.estado
				LEFT JOIN "informix".si_catcalles t4 ON t2.numerocalle = t4.numerocalle
				LEFT JOIN "informix".si_catzonas t5 ON t2.numerociudad = t5.numerociudad AND t2.numerocolonia = t5.numerocolonia
				LEFT JOIN "informix".si_estados t6 ON t2.estado = t6.estado
				--2014/06/09
				--LEFT JOIN bdisolic:"informix".ss_refpersonales t7 ON (t1.numcte = t7.numcte AND t7.numcte_ref = 'R1')
				--JOIN bdicred:"informix".sd_maecred t8 ON (t1.numcte = t8.numcte AND t7.num_solicitud = t8.num_credito)
				LEFT OUTER JOIN "informix".si_telefonos_actual t9 ON ( t9.numcte = t1.numcte AND t9.tipo_tel = 1 )
				LEFT OUTER JOIN "informix".si_telefonos_actual t92 ON ( t92.numcte = t1.numcte AND t92.tipo_tel = 2 )
				LEFT OUTER JOIN "informix".si_telefonos_actual t93 ON ( t93.numcte = t1.numcte AND t93.tipo_tel = 3 )
				LEFT JOIN "informix".si_correos t10 ON ( t10.numcte = t1.numcte 
				AND t10.secuencia = (SELECT MAX(secuencia)
									FROM "informix".si_correos
									WHERE numcte = pCliente
									AND tipo_correo = pModo ))
				WHERE t1.numcte = pCliente;
			--ELSE
				--LET cCodRet = '002' ;  --- No existe el cliente en el catalogo de telefonos
			--END IF;
		ELSE
			LET cCodRet = '001' ;  --- No existe el cliente en el catalogo
		END IF ;
		RETURN cCodRet,cApellidoPaterno,cApellidoMaterno,cNombre1,cNombre2,cNombreCiudad,cNombreZona,cNumeroExterior,cNumeroInterior,cDepto,cRumbo,
			   cNombreCalle,cCodigoPostal,cObservaciones,cTelefonoParticular,cTelefonoCelular,cTelefonoTrabajo,cTelefonoReferencia,cEntreCalles,
			   cEstado,cNombreEstado,cLugarTrabajo,cUnidad,cCiudad,iColonia,iCalle,iManzana,iOtros,iAndador,iEtapa,iLote,iEdificio,iEntrada,iCiudadCoppel, cEmail with resume;
		END
	END PROCEDURE
	DOCUMENT
	'06/Febrero/2008',
	'Walber Castro',
	'Obtiene los datos del domicilio del cliente',
	'*********************************************',
	'17/Junio/2008',
	'Walber Castro',
	'Se corrige como toma el nombre de la empresa por el maximo de secuencia de la si_ingresos.',
	'*********************************************',
	'11/Julio/2008',
	'Walber Castro',
	'Se agrega el parametro de ciudad coppel.',
	'*********************************************',
	'10/Sept/2008',
	'Walber Castro',
	'Se modifica el ON de las tablas si_cliente join di_direcciones',
	'para que se obtengan los datos del cliente aun cuando no haya',
	'informaci?n del domicilio del trabajo.',
	'**********************************************',
	'2009-01-07',
	'Marcos Cuevas',
	'Se agrego la validacion de tipo ingreso en las consulta ala si_ingresos',
	'2011-02-03  Por MACF',
	'*************************************************************************************************************************',
	'Se modifica para obtener el tel?fono de la Referencia, siempre y cuando el Cliente haya ingresado una solicitud de TDC',
	'******************************************************************************************************************************',
	' 2011-07-05 Se modifica para que solo obtenga info de la solicitud y/o credito aprobado - Marco A. Campos',
	'*************************************************************************************************************************',
	' 2013-08-27 Se modifica para a?adir retorno y consulta de email de cte '' Hugo G. Vazquez',
	'*************************************************************************************************************************',
	' 2014-06-09 ',
	' Descripcion: Se sustituye tabla ss_refpersonales',
	' Modifico: Victor Hugo Nu?ez',
	'*************************************************************************************************************************';

CREATE PROCEDURE "informix".sp_cnsif_buscacte_pba(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cTBUSQUEDA CHAR(1),cNOMBRE1 CHAR (26),cNOMBRE2 CHAR(26),cAPATERNO CHAR(26),cAMATERNO CHAR(26),dFNACIMIENTO DATE,cRSOCIAL CHAR(60),pNumRegistro INTEGER,pRecuperacion INTEGER)

    RETURNING CHAR(5)  AS Cod_Retorno,
			  CHAR(20) AS Numero_Cliente,
			  CHAR(13) AS RFC,
			  CHAR(1)  AS Id_Num_Consulta,
			  CHAR(26) AS Nombre_1,
			  CHAR(26) AS Nombre_2,
			  CHAR(26) AS Apellido_Paterno,
			  CHAR(26) AS Apellido_Materno,
			  CHAR(60) AS Razon_Social;
								
	--Variables
	DEFINE iexiste 					INT;
	DEFINE cCodRet 					CHAR(5);
	DEFINE iSql_err 				INT;
	DEFINE cNumero_cliente			CHAR(20);
	DEFINE cNombre1_salida			CHAR(26);
	DEFINE cNombre2_salida			CHAR(26);
	DEFINE cAPaterno1				CHAR(26);
	DEFINE cAMaterno1				char(26);
	DEFINE cRSocial1				CHAR(60);
	DEFINE cRFC1 					CHAR(13);
	DEFINE cId_Nconsulta_cliente	CHAR(1);
    DEFINE iCont                    INTEGER;
    DEFINE cRSOCIAL2                CHAR(60);


	--inicializando variables
	LET iexiste 	= 0;
	LET cCodRet 	= "00000";	
	LET iSql_err 	= 0;
	LET cNumero_cliente	 = "";
	LET cNombre1_salida	 = "";
	LET cNombre2_salida	 = "";
	LET cAPaterno1	 = "";
	LET cAMaterno1	 = "";
	LET cRSocial1	 = "";
	LET cRFC1	 = "";
	LET cId_Nconsulta_cliente	 = '1';
    LET iCont=0;
    LET cRSOCIAL2="";
	
	BEGIN
		ON EXCEPTION SET iSql_err
            IF iSql_err <> 0 THEN
                LET cCodRet = iSql_err;
                RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
                
            END IF;
        END EXCEPTION;
		      --SET DEBUG FILE TO "/informix/CHVN/log/sp_cnsif_buscacte.out";
		      --TRACE ON;

        IF pNumRegistro<0 THEN
            LET cCodRet='00098';
            RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
        ELSE
            IF pRecuperacion<=0 THEN
                LET cCodRet='00098';
                RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
            END IF;
        END IF;    

		IF cTBUSQUEDA <> '1' AND cTBUSQUEDA <> '2' THEN 
			LET cCodRet = "00052";
			RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
		END IF; 	
		
		EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
		INTO cCodRet;

		IF cCodRet = '00028' THEN 
			RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
		END IF;		
		
		IF cTBUSQUEDA = 1 THEN
			IF 		cID_USUARIOC ='' 	OR 
					cID_FUNCIONC = '' 	OR 
					cNOMBRE1 ='' 		OR
					cAPATERNO= ''  		THEN
					LET cCodRet = "00054";
					RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
			END IF;		
			IF cID_FUNCIONC='SKI002' THEN
				IF dFNACIMIENTO IS NULL OR dFNACIMIENTO='' THEN
					LET cCodRet = "00360";
					RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
				END IF;
			END IF;
			IF cNOMBRE2  <> '' THEN
				IF cAMATERNO <> '' THEN
					IF dFNACIMIENTO IS NULL THEN 
						FOREACH
                        SELECT FIRST 1 nvl(Count(numcte),0) INTO iexiste  FROM si_cliente WHERE nombre1 =cNOMBRE1 AND nombre2 =cNOMBRE2 AND apell_paterno = cAPATERNO AND apell_materno = cAMATERNO
						UNION
						SELECT nvl(Count(numcte_tf),0) FROM bditransfer:tf_maecte WHERE nombre1 =cNOMBRE1 AND nombre2 =cNOMBRE2 AND apell_paterno = cAPATERNO AND apell_materno = cAMATERNO
						ORDER BY 1 desc
						END FOREACH;
                        IF iexiste = 0 THEN
                            LET cCodRet = "00053";
                            RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1;
                        END IF;
						set isolation to dirty read;
						FOREACH
							SELECT SKIP pNumRegistro FIRST pRecuperacion CL.numcte,CL.nombre1,CL.nombre2,CL.apell_paterno,CL.apell_materno,CL.rfc_alterno 
							INTO
							cNumero_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRFC1
