							LEFT JOIN si_ctepf PF
							ON PF.numcte = CL.numcte
							WHERE CL.nombre1 = 	cNOMBRE1
							AND CL.nombre2 =	cNOMBRE2
							AND CL.apell_paterno = cAPATERNO
							AND CL.apell_materno = cAMATERNO
