                            END IF;
							
                            LET iCont=iCont+1;	
							RETURN cCodRet,cNumero_cliente,cRFC1,cId_Nconsulta_cliente,cNombre1_salida,cNombre2_salida,cAPaterno1,cAMaterno1,cRSocial1 with resume;
						END FOREACH;
