CREATE PROCEDURE "informix".sp_actualiza_estatus_correos()
RETURNING CHAR(6), CHAR(100);
	DEFINE cCodRet			CHAR(6);
	DEFINE cErrorSQL		CHAR(100);
	DEFINE i_SqlError		INTEGER;
	DEFINE i_iSamError		INTEGER;
	
	DEFINE cNumcte			CHAR(20);
		
	DEFINE iTrans_abierta	INTEGER;
	DEFINE iTotalReg		INTEGER;
	DEFINE iProcesados		INTEGER;
	DEFINE MAXTRANSACCION	INTEGER;
	
	DEFINE cCorreo		CHAR(20);
	DEFINE iMaxSecuencia	INTEGER;
	DEFINE iCantidad		INTEGER;
	DEFINE cTipo_Correo		CHAR(1);
	DEFINE dFecha_Proceso	DATE;
		
	LET iMaxSecuencia = 0;
	LET iProcesados = 0;
	LET cCodRet = '000000';
	LET MAXTRANSACCION = 300;		
	LET iTrans_abierta= 0;
	LET cErrorSQL = 'PROCESO TERMINADO SATISFACTORIAMENTE';
	
	--SET DEBUG FILE TO "/informix/josea/sp_actualiza_estatus_correos.out";
	--TRACE ON;	
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		ON EXCEPTION SET i_SqlError,i_iSamError, cErrorSQL
			IF i_SqlError <> 0 THEN				
				IF iTrans_abierta = 1 THEN
					ROLLBACK WORK;
					LET iTrans_abierta = 0;
				END IF;				
				LET cCodRet = i_SqlError;								
				RETURN cCodRet, cErrorSQL;
			END IF;
		END EXCEPTION;
		
		FOREACH WITH HOLD
			SELECT DISTINCT TRIM(numcte) AS numcte, tipo_correo, COUNT(*) AS cantidad
			INTO cNumcte, cTipo_Correo, iCantidad
			FROM si_correos
			WHERE status_correo = 'A'
			GROUP BY 1,2 HAVING COUNT(*) > 1
			
			IF iProcesados = 0 THEN
				BEGIN WORK;
				LET iTrans_abierta = 1;
			END IF;				
			
			SELECT MAX(secuencia) 
			INTO iMaxSecuencia
			FROM si_correos
			WHERE numcte = cNumcte
			AND tipo_correo = cTipo_Correo;
			
			UPDATE si_correos
			SET status_correo = 'C'
			WHERE numcte = cNumcte
			AND tipo_correo = cTipo_Correo
			AND secuencia < iMaxSecuencia;
			
			UPDATE si_correos
			SET status_correo = 'A'
			WHERE numcte = cNumcte
			AND tipo_correo = cTipo_Correo
			AND secuencia = iMaxSecuencia;
			
			LET iProcesados = iProcesados + 1;
			
			IF iProcesados >= MAXTRANSACCION THEN
				LET iProcesados = 0;
				COMMIT WORK;
				LET iTrans_abierta = 0;
			END IF;
			
		END FOREACH;
					
		IF iProcesados < MAXTRANSACCION THEN
			IF iProcesados > 0 THEN
				COMMIT WORK;
				LET iTrans_abierta = 0;
			END IF;
			LET iProcesados = 0;
		END IF;

		RETURN cCodRet, cErrorSQL;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ipab_obtienectes( pFechaIni DATE, pNumCliente CHAR(20) ) 
RETURNING CHAR(5);
    
    DEFINE iSqlErr  INTEGER;
    DEFINE iSamErr  INTEGER;
    DEFINE cDesErr  CHAR(50);
    DEFINE cCodRet  CHAR(5);
    DEFINE cCodRet2 CHAR(5);
    DEFINE cCodRet3 CHAR(50);
    DEFINE cCteMin  CHAR(20);
    DEFINE cCteMax  CHAR(20);
    
    LET iSqlErr  = 0;
    LET iSamErr  = 0;
    LET cDesErr  = '';
    LET cCodRet  = '000';
    LET cCodRet2 = '';
    LET cCodRet3 = '';
    LET cCteMin  = '';
    LET cCteMax  = '';
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_obtienectes.out';
    --- TRACE ON;
    
    BEGIN

    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_obtienectes.err';
        TRACE ON;
        LET cCodRet  = iSqlErr;
        LET cCodRet2 = iSamErr;
        LET cCodRet3 = cDesErr;
        RETURN cCodRet;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    IF pNumCliente <> '999999999' THEN
    
        INSERT INTO si_clientes_ipab
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicheq:sc_maechq mae,
               bdicheq:sc_maenoc noc
         WHERE cte.numcte = pNumCliente
           AND mae.num_cte = cte.numcte
           AND noc.cuenta = mae.cuenta
           AND mae.producto NOT IN('1100','9900','9901')
           AND noc.fecha_alta <= pFechaIni
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni );
         
        INSERT INTO si_clientes_ipab
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicheq:sc_maechq mae
         WHERE cte.numcte = pNumCliente
           AND mae.num_cte = cte.numcte
           AND mae.producto = '1100'
           AND mae.fecultdep <= pFechaIni
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni );
           
           
        INSERT INTO si_clientes_ipab
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdinvers:sv_maeinv mae
         WHERE cte.numcte = pNumCliente
           AND mae.num_cte = cte.numcte
           AND mae.fecha_alta <= pFechaIni 
           AND mae.fecha_venc > pFechaIni
           AND ( mae.fec_cancelac > pFechaIni or mae.fec_cancelac is null );
           
        /*
        INSERT INTO si_clientes_ipab
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicred:sd_maecred crd
         WHERE cte.numcte = crd.numcte
           AND crd.status_cred IN('AA','BA','BT')
           AND crd.numcte = pNumCliente;
           
        INSERT INTO si_clientes_ipab
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicred:sd_maecredcrd crd
         WHERE cte.numcte = crd.numcte
           AND crd.status_cred IN('VP','AA','BA','BT')
           AND crd.numcte = pNumCliente;
        */
           
        UPDATE STATISTICS HIGH FOR TABLE si_clientes_ipab;
    
        SELECT MIN(numcte), MAX(numcte)
          INTO cCteMin, cCteMax
          FROM si_clientes_ipab;
        
        INSERT INTO si_cliente_ipab
        SELECT UNIQUE numcte
          FROM si_clientes_ipab
         WHERE numcte >= cCteMin 
           AND numcte <= cCteMax;
        
        UPDATE STATISTICS HIGH FOR TABLE si_cliente_ipab;
        
    ELSE
        
        INSERT INTO si_clientes_ipab_comp
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicheq:sc_maechq mae,
               bdicheq:sc_maenoc noc
         WHERE mae.num_cte = cte.numcte
           AND noc.cuenta = mae.cuenta
           AND mae.producto NOT IN('1100','9900','9901')
           AND noc.fecha_alta <= pFechaIni
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni );
         
        INSERT INTO si_clientes_ipab_comp
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicheq:sc_maechq mae
         WHERE mae.num_cte = cte.numcte
           AND mae.producto = '1100'
           AND mae.fecultdep <= pFechaIni
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni );
           
        INSERT INTO si_clientes_ipab_comp
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdinvers:sv_maeinv mae
         WHERE mae.num_cte = cte.numcte
           AND mae.fecha_alta <= pFechaIni 
           AND mae.fecha_venc > pFechaIni
           AND ( mae.fec_cancelac > pFechaIni or mae.fec_cancelac is null );
           
        /*
        INSERT INTO si_clientes_ipab_comp
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicred:sd_maecred crd
         WHERE crd.numcte = cte.numcte
           AND crd.status_cred IN('AA','BA','BT');
           
        INSERT INTO si_clientes_ipab_comp
        SELECT cte.numcte
          FROM bdinteg:si_cliente cte,
               bdicred:sd_maecredcrd crd
         WHERE crd.numcte = cte.numcte
           AND crd.status_cred IN('VP','AA','BA','BT');
        */
           
        UPDATE STATISTICS HIGH FOR TABLE si_clientes_ipab_comp;
    
        SELECT MIN(numcte), MAX(numcte)
          INTO cCteMin, cCteMax
          FROM si_clientes_ipab_comp;
        
        INSERT INTO si_cliente_ipab_comp
        SELECT UNIQUE numcte
          FROM si_clientes_ipab_comp
         WHERE numcte >= cCteMin 
           AND numcte <= cCteMax;
        
        UPDATE STATISTICS HIGH FOR TABLE si_cliente_ipab_comp; 
    END IF;
    
    END;
    
    RETURN cCodRet;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repchequesipab( pNumCliente CHAR(20), 
                                               pFechaIni   DATE, 
                                               pFechaFin   DATE, 
                                               pPorcRetSuj DECIMAL(9,6), 
                                               pAniobase   INTEGER,
                                               pBaseExenta MONEY(18,2),
                                               pIndicador  SMALLINT ) 
RETURNING CHAR(5);
    
    DEFINE cRegFiscal, cOperArit, cTipoPersona, cTasaVar, cRangoFecha CHAR(1);
    DEFINE cTpoCuenta, cMoneda, cCodRetCorte CHAR(2);
    DEFINE cInstbase, cSobretasa CHAR(3); 
    DEFINE cNumProducto, cSucursal CHAR(4);
    DEFINE cCodRet, cCodRet2, cCodRetSdos CHAR(5); 
    DEFINE cFechaCorte, cFechaAlta, cFechaSigcorte CHAR(8);
    DEFINE cTasa CHAR(10);
    DEFINE cNumCuenta CHAR(20); 
    DEFINE cProducto, cCodRet3, cDesErr CHAR(50);
    DEFINE dtFechaCorte, dtFechaSigcorte, dtFecAlta, dtFechaAlta, dtFechaCorte2 DATE;
    DEFINE iTipoTasa, iAnioMes, iMoneda, iPlazo SMALLINT;
    DEFINE iCtaInversion, iSqlErr, iSamErr, iDias_Ini, iDiasProyec INTEGER;
    DEFINE dTasa, dPorcentaje, dPuntos DECIMAL(9,6); 
    DEFINE dImp_isr DECIMAL(14,6); 
    DEFINE mInt_al_Inicio, mbase_gravable, mInt_Proyec, mSdo_Proyec, dImp_Isr_Ini MONEY(18,2); 
    DEFINE mSdo_Prom_Ini, mSdo_Fin, dImp_Isr_Fin, mSdo_Ini, mSdo_Prom_Fin, mSdo_Promedio, mSdo_31, mInt_31 MONEY(18,2); 
    
    LET cRegFiscal = 'N'; LET cOperArit = NULL; LET cTipoPersona = ''; LET cTasaVar  = ''; LET cRangoFecha  = '';
    LET cTpoCuenta = 'CI'; LET cMoneda = ''; LET cCodRetCorte =  ''; 
    LET cInstbase = NULL; LET cSobretasa = NULL; 
    LET cNumProducto = ''; LET cSucursal = ''; 
    LET cCodRet = '000'; LET cCodRet2 = ''; LET iPlazo = NULL; LET cCodRetSdos = '';
    LET cFechaCorte = ''; LET cFechaAlta = ''; LET cFechaSigcorte = ''; 
    LET cTasa = ''; 
    LET cNumCuenta = '';
    LET cProducto = ''; LET cCodRet3 = ''; LET cDesErr = ''; 
    LET dtFechaCorte = ''; LET dtFechaSigcorte =  ''; LET dtFecAlta = ''; LET dtFechaAlta = ''; LET dtFechaCorte2 = ''; 
    LET iTipoTasa = 1; LET iAnioMes = 0; LET iMoneda = 0;
    LET iCtaInversion = 0; LET iSqlErr = 0; LET iSamErr = 0; LET iDias_Ini = 0; LET iDiasProyec = 0; 
    LET dTasa = 0; LET dPorcentaje = 0; LET dPuntos = 0; 
    LET dImp_isr = 0; 
    LET mInt_al_Inicio = 0; LET mbase_gravable = 0; LET mInt_Proyec = 0; LET mSdo_Proyec = 0; LET dImp_Isr_Ini = 0;
    LET mSdo_Prom_Ini = 0; LET mSdo_Fin = 0; LET dImp_Isr_Fin = 0; LET mSdo_Ini = 0; LET mSdo_Prom_Fin = 0; LET mSdo_Promedio = 0; LET mSdo_31 = 0.00; LET mInt_31 = 0.00;         
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_repchequesipab.err';
        TRACE ON;
        LET cCodRet  = iSqlErr;
        LET cCodRet2 = iSamErr;
        LET cCodRet3 = cDesErr;
        RETURN cCodRet;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_repchequesipab.out';
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;

    -- // NUMERO DE DIAS DE LA PROYECCION
    LET iDiasProyec = (pFechaFin - pFechaIni);
    
    -- // FOREACH CUENTAS POR CLIENTE
    FOREACH
        SELECT mae.cuenta, mae.producto, mae.sucursal, noc.fecha_alta, pro.nombre nombre_prod, pro.divisa moneda, pro.tasa, pro.paga_dividendo
          INTO cNumCuenta, cNumProducto, cSucursal, dtFecAlta, cproducto, cMoneda, ctasa, cTasaVar
          FROM bdicheq:sc_maechq mae,
               bdicheq:sc_maenoc noc,
               bdicheq:sc_producto pro
         WHERE mae.num_cte = pNumCliente
           AND noc.cuenta = mae.cuenta
           AND pro.producto = mae.producto
           AND mae.producto NOT IN('1100','9900','9901')
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni )
           AND noc.fecha_alta <= pFechaIni
        UNION ALL
        SELECT mae.cuenta, mae.producto, mae.sucursal, mae.fecultdep, pro.nombre nombre_prod, pro.divisa moneda, pro.tasa, pro.paga_dividendo
          FROM bdicheq:sc_maechq mae,
               bdicheq:sc_maenoc noc,
               bdicheq:sc_producto pro
         WHERE mae.num_cte = pNumCliente
           AND noc.cuenta = mae.cuenta
           AND pro.producto = mae.producto
           AND mae.producto = '1100'
           AND mae.fecultdep <= pFechaIni
           AND ( mae.fecha_proceso >= pFechaIni OR mae.fecha_proceso IS NULL OR mae.status_cta IN('1','3','4','5','6') OR mae.fec_cancelac > pFechaIni )
        
        IF dtFecAlta < pFechaIni THEN
            SELECT COUNT(*)
              INTO iAnioMes
              FROM bdicheq:sc_maehis
             WHERE empresa = '001'
               AND cuenta = cNumCuenta
               AND fechafin <= pFechaIni;
            
            IF iAnioMes = 0 THEN
                -- // SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                INTO cCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                
                LET iDias_Ini = (pFechaIni - dtFecAlta);

                -- // TIPO DE TASA DEL PRODUCTO
                SELECT rangofecha
                  INTO cRangoFecha
                  FROM bdinteg:si_tiptasa
                 WHERE empresa = '001'
                   AND tasa = ctasa;

                -- // VALOR DE LA TASA
                IF cTasaVar = 'N' THEN
                    IF cRangoFecha = 'F' THEN
                        SELECT NVL(valor,0)
                          INTO dTasa
                          FROM bdinteg:si_fechavalor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND fecha = ( SELECT max(fecha) FROM bdinteg:si_fechavalor WHERE empresa = '001' AND tasa = ctasa AND fecha <= pFechaIni );
                    ELIF cRangoFecha = 'R' THEN
                        IF cTipoPersona = 'F' THEN
                            SELECT valorperfis, sobretasafis
                              INTO dPorcentaje, dPuntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        ELSE
                            SELECT valorpermor, sobretasamor
                              INTO dPorcentaje, dPuntos
                              FROM bdinteg:si_tasavlor
                             WHERE empresa = '001'
                               AND tasa = ctasa
                               AND rangomin <= mSdo_Ini
                               AND rangomax >= mSdo_Ini;
                        END IF;
                        LET dTasa = dPorcentaje + dPuntos;
                    END IF;
                ELSE
                    SELECT NVL(valor_tasa,0)
                      INTO dTasa
                      FROM bdinteg:si_tasa_mes
                     WHERE tasa = ctasa
                       AND mes = 1
                       AND tipo_tasa = 'M'
                       AND fecha = ( SELECT MAX(fecha) FROM bdinteg:si_tasa_mes WHERE tasa = ctasa AND mes = 1 AND tipo_tasa = 'M' AND fecha <= pFechaIni );
                END IF;
                
                IF mSdo_Ini >= 0 THEN
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                    
                    -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE PROYECCION
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                    LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                    LET mBase_gravable = mSdo_Prom_Fin - pBaseExenta;

                    IF pPorcRetSuj <> 0 THEN
                        IF cTipoPersona = 'F' THEN
                            IF mBase_gravable > 0 THEN
                                LET dImp_Isr_Fin = (mBase_gravable * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                            ELSE
                                LET dImp_Isr_Fin = 0;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = (mSdo_Prom_Fin * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = 0;
                    END IF;

                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                ELSE
                    LET mSdo_Prom_Ini = mSdo_Ini;
                    LET mInt_al_Inicio = 0.00;
                    LET dImp_Isr_Ini = 0.00;
                    LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                    LET mSdo_Prom_Fin = mSdo_Fin;
                    LET mInt_Proyec = 0.00;
                    LET dImp_Isr_Fin = 0.00;
                    LET mSdo_Promedio = mSdo_Prom_Fin;
                    LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                LET dtFechaAlta = dtFecAlta - 1;
                
                EXECUTE PROCEDURE bdinteg:sp_cortesig(dtFechaAlta, 1) 
                INTO cCodRetCorte,dtFechaSigcorte;
                
                LET dtFechaCorte = dtFechaSigcorte;
            ELSE
                -- // OBTIENE INFORMACON DEL ULTIMO MAEHIS
                SELECT NVL(his.tasabruta, 0), his.fechafin
                  INTO dTasa, dtFechaCorte
                  FROM bdicheq:sc_maehis his
                 WHERE his.empresa = '001'
                   AND his.cuenta = cNumCuenta
                   AND his.aniomes = (SELECT MAX(aniomes) FROM bdicheq:sc_maehis WHERE empresa = '001' AND cuenta = cNumCuenta AND fechafin <= pFechaIni);
                                         
                LET dTasa = dTasa * 100;
                
                LET iDias_Ini = (pFechaIni - dtFechaCorte);

                IF iDias_Ini > 0 THEN
                    -- // OBTIENE EL SALDO SIN INTERESES A LA FECHA INICIAL DE LA PROYECCION
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO cCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    IF mSdo_Ini >= 0 THEN
                        -- // OBTIENE EL SALDO PROMEDIO DE LA FECHA DE CORTE A LA FECHA INICIAL DE LA PROYECCION
                        LET dtFechaCorte2 = dtFechaCorte + 1;
                        LET mSdo_Prom_Ini = mSdo_Ini;

                        -- // CALCULA EL SALDO CON INTERESES A AL FECHA INICIAL DE LA PROYECCION
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;
                        
                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - pBaseExenta;

                        IF pPorcRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;
                ELIF iDias_Ini = 0 THEN
                    -- // OBTIENE EL SALDO DE LA CUENTA
                    EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
                    INTO cCodRetSdos, mSdo_Ini, mInt_al_Inicio;
                    
                    IF mSdo_Ini >= 0 THEN
                        LET mSdo_Prom_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Fin - dImp_Isr_Ini;

                        -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                        LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                        LET mBase_gravable = mSdo_Prom_Fin - pBaseExenta;

                        IF pPorcRetSuj <> 0 THEN
                            IF cTipoPersona = 'F' THEN
                                IF mBase_gravable > 0 THEN
                                    LET dImp_Isr_Fin = (mBase_gravable * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                                ELSE
                                    LET dImp_Isr_Fin = 0;
                                END IF;
                            ELSE
                                LET dImp_Isr_Fin = (mSdo_Prom_Fin * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                            END IF;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;

                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
                    ELSE
                        LET mSdo_Prom_Ini = mSdo_Ini;
                        LET mInt_al_Inicio = 0.00;
                        LET dImp_Isr_Ini = 0.00;
                        LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                        LET mSdo_Prom_Fin = mSdo_Fin;
                        LET mInt_Proyec = 0.00;
                        LET dImp_Isr_Fin = 0.00;
                        LET mSdo_Promedio = mSdo_Prom_Fin;
                        LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
                    END IF;
                END IF;

                -- // OBTIENE LA PROXIMA FECHA DE CORTE
                EXECUTE PROCEDURE bdinteg:sp_CorteSig(dtFechaCorte, 1) 
                INTO cCodRetCorte, dtFechaSigcorte;
            END IF;
        ELIF dtFecAlta = pFechaIni THEN
            -- // OBTIENE EL SALDO DE LA CUENTA
            EXECUTE PROCEDURE bdicheq:sp_capintafecha(cNumCuenta, pFechaIni) 
            INTO cCodRetSdos, mSdo_Ini, mInt_al_Inicio;
            
            LET iDias_Ini = 0;
            
            -- // OBTIENE EL TIPO DE TASA DEL PRODUCTO
            SELECT rangofecha
              INTO cRangoFecha
              FROM bdinteg:si_tiptasa
             WHERE empresa = '001'
               AND tasa = ctasa;

            -- // OBTIENE EL VALOR DE LA TASA
            IF cTasaVar = 'N' THEN
                IF cRangoFecha = 'F' THEN
                    SELECT NVL(valor,0)
                      INTO dTasa
                      FROM bdinteg:si_fechavalor
                     WHERE empresa = '001'
                       AND tasa = ctasa
                       AND fecha = ( SELECT max(fecha) FROM bdinteg:si_fechavalor WHERE empresa = '001' AND tasa = ctasa AND fecha <= pFechaIni );
                ELIF cRangoFecha = 'R' THEN
                    IF cTipoPersona = 'F' THEN
                        SELECT valorperfis, sobretasafis
                          INTO dPorcentaje, dPuntos
                          FROM bdinteg:si_tasavlor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND rangomin <= mSdo_Ini
                           AND rangomax >= mSdo_Ini;
                    ELSE
                        SELECT valorpermor, sobretasamor
                          INTO dPorcentaje, dPuntos
                          FROM bdinteg:si_tasavlor
                         WHERE empresa = '001'
                           AND tasa = ctasa
                           AND rangomin <= mSdo_Ini
                           AND rangomax >= mSdo_Ini;
                    END IF;
                    LET dTasa = dPorcentaje + dPuntos;
                END IF;
            ELSE
                SELECT NVL(valor_tasa,0)
                  INTO dTasa
                  FROM bdinteg:si_tasa_mes
                 WHERE tasa = ctasa
                   AND mes = 1
                   AND tipo_tasa = 'M'
                   AND fecha = ( SELECT MAX(fecha) FROM bdinteg:si_tasa_mes WHERE tasa = ctasa AND mes = 1 AND tipo_tasa = 'M' AND fecha <= pFechaIni );
            END IF;
            
            IF mSdo_Ini >= 0 THEN
                -- // CALCULA EL SALDO CON INTERESES A LA FECHA INICIAL DE LA PROYECCION
                LET mSdo_Prom_Ini = 0.00;
                LET dImp_isr_ini = 0.00;
                LET mSdo_Fin = mSdo_Ini;
                LET mSdo_Prom_Fin = mSdo_Fin;

                -- // CALCULA EL SALDO CON INTERESES A LA FECHA FINAL DE LA PROYECCION
                LET mInt_Proyec = (mSdo_Prom_Fin * (dTasa/100) * iDiasProyec) / 360;
                LET mSdo_Proyec = mSdo_Fin + mInt_Proyec;
                LET mBase_gravable = mSdo_Prom_Fin - pBaseExenta;

                IF pPorcRetSuj <> 0 THEN
                    IF cTipoPersona = 'F' THEN
                        IF mBase_gravable > 0 THEN
                            LET dImp_Isr_Fin = (mBase_gravable * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                        ELSE
                            LET dImp_Isr_Fin = 0;
                        END IF;
                    ELSE
                        LET dImp_Isr_Fin = (mSdo_Prom_Fin * (pPorcRetSuj/100)) * iDiasProyec / pAniobase;
                    END IF;
                ELSE
                    LET dImp_Isr_Fin = 0;
                END IF;

                LET mSdo_Promedio = mSdo_Prom_Fin;
                LET mSdo_Proyec = mSdo_Proyec - dImp_Isr_Fin;
            ELSE
                LET mSdo_Prom_Ini = mSdo_Ini;
                LET mInt_al_Inicio = 0.00;
                LET dImp_Isr_Ini = 0.00;
                LET mSdo_Fin = mSdo_Ini + mInt_al_Inicio;
                LET mSdo_Prom_Fin = mSdo_Fin;
                LET mInt_Proyec = 0.00;
                LET dImp_Isr_Fin = 0.00;
                LET mSdo_Promedio = mSdo_Prom_Fin;
                LET mSdo_Proyec = ( mSdo_Fin + mInt_Proyec ) - dImp_Isr_Fin;
            END IF;

            -- // OBTIENE LA PROXIMA FECHA DE CORTE
            LET dtFechaAlta = dtFecAlta - 1;
            
            EXECUTE PROCEDURE bdinteg:sp_CorteSig(dtFechaAlta, 1) 
            INTO cCodRetCorte, dtFechaSigcorte;
            
            LET dtFechaCorte = dtFechaSigcorte;
        END IF;
        
        IF pFechaFin = pFechaIni THEN
            LET mSdo_Fin = 0.00;
            LET mSdo_Prom_Fin = 0.00;
            LET mInt_Proyec = 0.00;
            LET dImp_Isr_Fin = 0.00;
            LET mSdo_Proyec = mSdo_Ini + mInt_al_Inicio;
        END IF;
        
        LET iMoneda = cMoneda;
        LET cFechaCorte = TO_CHAR(dtFechaCorte, '%Y%m%d');
        LET cFechaAlta = TO_CHAR(dtFecAlta, '%Y%m%d');
        LET cFechaSigcorte = TO_CHAR(dtFechaSigcorte, '%Y%m%d');
        
        IF pIndicador = 0 THEN
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit VALUES
            ( cNumCuenta, iCtaInversion, cNumProducto, cTpoCuenta, cRegFiscal, dPorcentaje, cSucursal, mSdo_Ini, mInt_al_Inicio, dImp_Isr_Ini, 0.00, 
              mSdo_Proyec, iMoneda, cFechaCorte, cFechaAlta, iPlazo, iTipoTasa, dTasa, cInstbase, cSobretasa, cOperArit, cFechaSigcorte, mSdo_Promedio, 
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );
            
            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit VALUES 
            ( cNumCuenta, iCtaInversion, pNumCliente, 100.00 );
        ELSE
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_comp VALUES
            ( cNumCuenta, iCtaInversion, cNumProducto, cTpoCuenta, cRegFiscal, dPorcentaje, cSucursal, mSdo_Ini, mInt_al_Inicio, dImp_Isr_Ini, 0.00, 
              mSdo_Proyec, iMoneda, cFechaCorte, cFechaAlta, iPlazo, iTipoTasa, dTasa, cInstbase, cSobretasa, cOperArit, cFechaSigcorte, mSdo_Promedio, 
              iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDiasProyec, mSdo_Fin, mSdo_Prom_Fin, mInt_Proyec, dImp_Isr_Fin );
            
            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_comp VALUES 
            ( cNumCuenta, iCtaInversion, pNumCliente, 100.00 );
        END IF;
    END FOREACH;
    
    RETURN cCodRet;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_reppagaresipab( pNumCliente CHAR(20), 
                                               pFechaIni   DATE, 
                                               pFechaFin   DATE, 
                                               pPorcRetSuj DECIMAL(9,6), 
                                               pAniobase   INTEGER,
                                               pIndicador  SMALLINT )
RETURNING CHAR(5);
    
    DEFINE cRegFiscal, cOperArit CHAR(1);
    DEFINE cTpoCuenta CHAR(2);    
    DEFINE cInstbase, cSobretasa CHAR(3);   
    DEFINE cNumProducto, cSucursal CHAR(4);
    DEFINE cCodRet, cCodRet2 CHAR(5); 
    DEFINE cFechaContratacion CHAR(8);
    DEFINE cNumCuenta, cCtaInversion CHAR(20);           
    DEFINE cDesErr, cCodRet3 CHAR(50);           
    DEFINE dtFechaCorte, dtFechaSigCorte, dtFechaContratacion DATE;               
    DEFINE iDivisa, iPlazo, iTipoTasa SMALLINT;           
    DEFINE iDias_Proy, iSqlErr, iSamErr, iDias_Ini, iSucursal INTEGER;
    DEFINE dTasa, dTasa2, dPorcentaje, dSdo_PromInv DECIMAL(9,6); 
    DEFINE mISR_Proy, mInt_Proy, mSdo_Inv_Proy, mInt_al_Inicio, mCapital, mSdo_Ini, mSdo_Prom_Ini, dImp_Isr_Ini, mSdo_Prom_Fin MONEY(18,2);
    
    LET cRegFiscal = 'N'; LET iTipoTasa = 1; LET cOperArit = NULL; 
    LET cTpoCuenta = 'CI'; 
    LET cInstbase = NULL; LET cSobretasa = NULL;
    LET cNumProducto = ""; LET cSucursal = "";
    LET cCodRet = "000"; LET cCodRet2 = ""; 
    LET cFechaContratacion = '';
    LET cNumCuenta = ""; LET cCtaInversion = "";
    LET cDesErr = ""; LET cCodRet3 = ""; 
    LET dtFechaCorte = NULL; LET dtFechaSigCorte = NULL; LET dtFechaContratacion = '';
    LET iDivisa = 1; LET iPlazo = ""; 
    LET iDias_Proy = 0; LET iSqlErr = 0; LET iSamErr = 0; LET iDias_Ini = 0; LET iSucursal = 0;
    LET dTasa = 0; LET dTasa2 = 0; LET dPorcentaje = NULL; LET dSdo_PromInv = NULL;
    LET mISR_Proy = 0; LET mInt_Proy = 0; LET mSdo_Inv_Proy = 0; LET mInt_al_Inicio = 0; LET mCapital = 0.00; LET mSdo_Ini = 0; LET mSdo_Prom_Ini = 0; LET dImp_Isr_Ini = 0; LET mSdo_Prom_Fin = 0;
                      
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/sp_reppagaresipab.err';
        TRACE ON;
        LET cCodRet = iSqlErr;
        LET cCodRet2 = iSamErr;
        LET cCodRet3 = cDesErr;
        RETURN cCodRet;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/jivan/sp_reppagaresipab.out';
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    LET pPorcRetSuj = pPorcRetSuj / 100;
    
    FOREACH
        SELECT cta_cheques, cuenta, capital, cod_instrum, sucursal, fecha_alta, tasa, plazo
          INTO cNumCuenta, cCtaInversion, mCapital, cNumProducto, cSucursal, dtFechaContratacion, dTasa, iPlazo
          FROM bdinvers:sv_maeinv 
         WHERE num_cte = pNumCliente
           AND fecha_alta <= pFechaIni 
           AND fecha_venc > pFechaIni
           AND ( fec_cancelac > pFechaIni or fec_cancelac is null )
        
        LET iSucursal = cSucursal;
        LET dTasa2 = dTasa / 100;
        LET cFechaContratacion = TO_CHAR(dtFechaContratacion,'%Y%m%d');
        
        -- // OBTIENE SALDO PROYECTADO A AL FECHA FINAL DE LA PROYECCION
        LET mSdo_Prom_Fin = mCapital;
        LET iDias_Proy = (pFechaFin - dtFechaContratacion) + 1;
        LET mInt_Proy = (mCapital * dTasa2 * iDias_Proy) / 360;
        
        IF pPorcRetSuj <> 0 THEN
            LET mISR_Proy = (((mCapital * pPorcRetSuj) * iDias_Proy) / pAniobase);
        ELSE
            LET mISR_Proy = 0;
        END IF;
        
        IF pFechaIni = pFechaFin THEN
            LET mSdo_Inv_Proy = mCapital + mInt_Proy;
        ELSE
            LET mSdo_Inv_Proy = ( mCapital + mInt_Proy ) - mISR_Proy;
        END IF;
        
        IF pIndicador = 0 THEN
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit VALUES
            ( cNumCuenta, cCtaInversion, cNumProducto, cTpoCuenta, cRegFiscal, dPorcentaje, iSucursal, mSdo_Ini, mInt_al_Inicio, dImp_Isr_Ini, 0.00, 
              mSdo_Inv_Proy, iDivisa, dtFechaCorte, cFechaContratacion, iPlazo, iTipoTasa, dTasa, cInstbase, cSobretasa, cOperArit, dtFechaSigCorte, 
              dSdo_PromInv, iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDias_Proy, mCapital, mSdo_Prom_Fin, mInt_Proy, mISR_Proy );
            
            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit VALUES 
            ( cNumCuenta, cCtaInversion, pNumCliente, 100.00 );
        ELSE
            -- // INSERTA INFORMACION PATRIMONIAL DEL CLIENTE
            INSERT INTO si_infpattit_comp VALUES
            ( cNumCuenta, cCtaInversion, cNumProducto, cTpoCuenta, cRegFiscal, dPorcentaje, iSucursal, mSdo_Ini, mInt_al_Inicio, dImp_Isr_Ini, 0.00, 
              mSdo_Inv_Proy, iDivisa, dtFechaCorte, cFechaContratacion, iPlazo, iTipoTasa, dTasa, cInstbase, cSobretasa, cOperArit, dtFechaSigCorte, 
              dSdo_PromInv, iDias_Ini, mSdo_Ini, mSdo_Prom_Ini, mInt_al_Inicio, dImp_Isr_Ini, iDias_Proy, mCapital, mSdo_Prom_Fin, mInt_Proy, mISR_Proy );
            
            -- // INSERTA CUENTAS ASOCIADAS DEL CLIENTE
            INSERT INTO si_ctaasotit_comp VALUES 
            ( cNumCuenta, cCtaInversion, pNumCliente, 100.00 );
        END IF;
    END FOREACH;
    
    RETURN cCodRet;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ipab_borratablas( pNumCliente CHAR(20) ) 
RETURNING CHAR(5);
    
    DEFINE iSqlErr  INTEGER;
    DEFINE iSamErr  INTEGER;
    DEFINE cDesErr  CHAR(50);
    DEFINE cCodRet  CHAR(5);
    DEFINE cCodRet2 CHAR(5);
    DEFINE cCodRet3 CHAR(50);
    
    LET iSqlErr  = 0;
    LET iSamErr  = 0;
    LET cDesErr  = '';
    LET cCodRet  = '000';
    LET cCodRet2 = '';
    LET cCodRet3 = '';
    
    --- SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_borratablas.out';
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iSamErr, cDesErr
        SET DEBUG FILE TO '/resplogifx/conciliachq/ipab/sp_ipab_borratablas.err';
        TRACE ON;
        LET cCodRet  = iSqlErr;
        LET cCodRet2 = iSamErr;
        LET cCodRet3 = cDesErr;
        RETURN cCodRet;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    IF pNumCliente <> '999999999' THEN
    
        -- // INFORMACIÓN PERSONAL DE LOS TITULARES
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpertit') THEN
            create table "informix".si_infpertit (
                cve_unica       char(18),
                persona         char(1),
                nombre          char(150),
                apell_paterno   char(60),
                apell_materno   char(60),
                callenum        char(90),
                colonia         char(80),
                delmun          char(60),
                ciudad          char(60),
                cod_postal      char(5),
                pais            char(50),
                estado          char(4),
                suj_retencion   char(1),
                por_retencion   decimal(6,2),
                causal_rev      smallint,
                rfc             char(13),
                curp            char(18),
                telefonos       char(30),
                correo          char(50),
                fecha_nac       char(8),
                sdo_compensado  money(15,2),
                clasif_tit      smallint,
                tipo_codpos     char(10)
              ) 
            extent size 32 next size 32 lock mode row;

            create index "informix".idx_infpertit_cve on "informix".si_infpertit(cve_unica) online;
            
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infpertit;
        ELSE
            DELETE FROM "informix".si_infpertit
             WHERE 1 = 1;
        END IF;
        
        -- // INFORMACIÓN PATRIMONIAL DE LOS TITULARES
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpattit') THEN
            create table "informix".si_infpattit (
                numcta          char(35),
                num_inversion   char(25),
                cve_producto    char(20),
                tipo_cta        char(2),
                reg_fiscal      char(1),
                por_retencion   decimal(5,2),
                cve_sucursal    integer,
                sdo_cuenta      decimal(15,2),
                intereses       decimal(15,2),
                ret_impuestos   decimal(15,2),
                otros_accesorio decimal(15,2),
                sdo_neto        decimal(15,2),
                moneda          smallint,
                fecha_corte     char(8),
                fecha_contrata  char(8),
                plazo_opera     integer,
                tipo_tasa       smallint,
                tasa            decimal(6,3),
                inst_base       char(20),
                puntos_porc     decimal(6,3),
                operador        char(1),
                fecha_sig_corte char(8),
                sdo_prom_diario money(15,2),
                dias_ini        integer,
                saldo_ini       money(14,2),
                prom_ini        money(14,2),
                intereses_ini   money(14,2),
                isr_ini         money(14,2),
                dias_fin        integer,
                saldo_fin       money(14,2),
                prom_fin        money(14,2),
                intereses_fin   money(14,2),
                isr_fin         money(14,2) ) 
            extent size 32 next size 32 lock mode row;

            create index "informix".idx_infpattit_cta on "informix".si_infpattit(numcta) online ;
            create index "informix".idx_infpattit_inv on "informix".si_infpattit(num_inversion) online;
            
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infpattit;
        ELSE
            DELETE FROM "informix".si_infpattit
             WHERE 1 = 1;
        END IF;
        
        -- // CUENTAS ASOCIADAS DE LOS TITULARES
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_ctaasotit') THEN
            create table "informix".si_ctaasotit (
                numcta          char(35),
                num_inversion   char(25),
                cve_unica       char(18),
                porcentaje_tit  decimal(5,2) ) 
            extent size 32 next size 32 lock mode row;

            create index "informix".idx_ctaasotit_cta on "informix".si_ctaasotit(numcta) online;
            create index "informix".idx_ctaasotit_inv on "informix".si_ctaasotit(num_inversion) online;
            create index "informix".idx_ctaasotit_cve on "informix".si_ctaasotit(cve_unica) online;
            
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_ctaasotit;
        ELSE
            DELETE FROM "informix".si_ctaasotit
             WHERE 1 = 1;
        END IF;
        
        -- // INFORMACIÓN CREDITICIA DE LOS TITULARES
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infcrdtit') THEN
            create table "informix".si_infcrdtit (
                num_credito     char(20),
                moneda          smallint,
                segmento        smallint,
                tpo_cobranza    smallint,
                cap_vigente     decimal(15,2),
                cap_vencido     decimal(15,2),
                ints_ord_exig   decimal(15,2),
                ints_moratorios decimal(15,2),
                otros_accesorio decimal(15,2) )
            extent size 32 next size 32 lock mode row;

            create index "informix".idx_infcrdtit_crd on "informix".si_infcrdtit(num_credito) online;
            
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infcrdtit;
        ELSE
            DELETE FROM "informix".si_infcrdtit
             WHERE 1 = 1;
        END IF;
        
        -- // CREDITOS ASOCIADOS DE LOS TITULARES
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_crdasotit') THEN
            create table "informix".si_crdasotit (
                num_credito     char(20),
                cve_unica       char(18) ) 
            extent size 32 next size 32 lock mode row;

            create index "informix".idx_crdasotit_crd on "informix".si_crdasotit(num_credito) online;
            create index "informix".idx_crdasotit_cve on "informix".si_crdasotit(cve_unica) online;
            
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_crdasotit;   
        ELSE
            DELETE FROM "informix".si_crdasotit
             WHERE 1 = 1;
        END IF;
        
        -- // TABLA DE CLIENTES IPAB
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_clientes_ipab') THEN
            create table "informix".si_clientes_ipab (
                numcte  char(20) ) 
            extent size 32 next size 32 lock mode row;
            
            create index "informix".idx_clientesipab_cte ON "informix".si_clientes_ipab(numcte) ONLINE;
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_clientes_ipab;
        ELSE
            DELETE FROM "informix".si_clientes_ipab
             WHERE 1 = 1;
        END IF;
        
        -- // TABLA DE CLIENTES IPAB
        IF NOT EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_cliente_ipab') THEN
            create table "informix".si_cliente_ipab (
                numcte  char(20) ) 
            extent size 32 next size 32 lock mode row;
            
            create index "informix".idx_clienteipab_cte ON "informix".si_cliente_ipab(numcte) ONLINE;
            UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_cliente_ipab;
        ELSE
            DELETE FROM "informix".si_cliente_ipab
             WHERE 1 = 1;
        END IF;
        
    ELSE
    
        -- // INFORMACIÓN PERSONAL DE LOS TITULARES
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpertit_comp') THEN
            drop table "informix".si_infpertit_comp;
        END IF;
        
        create raw table "informix".si_infpertit_comp (
            cve_unica       char(18),
            persona         char(1),
            nombre          char(150),
            apell_paterno   char(60),
            apell_materno   char(60),
            callenum        char(90),
            colonia         char(80),
            delmun          char(60),
            ciudad          char(60),
            cod_postal      char(5),
            pais            char(50),
            estado          char(4),
            suj_retencion   char(1),
            por_retencion   decimal(6,2),
            causal_rev      smallint,
            rfc             char(13),
            curp            char(18),
            telefonos       char(30),
            correo          char(50),
            fecha_nac       char(8),
            sdo_compensado  money(15,2),
            clasif_tit      smallint,
            tipo_codpos     char(10)
          ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 1024000 next size 512000 lock mode row;

        create index "informix".idx_infpertitcomp_cve on "informix".si_infpertit_comp(cve_unica) in datos03 online;
        
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infpertit_comp;
        
        -- // INFORMACIÓN PATRIMONIAL DE LOS TITULARES
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infpattit_comp') THEN
            drop table "informix".si_infpattit_comp;
        END IF;
        
        create raw table "informix".si_infpattit_comp (
            numcta          char(35),
            num_inversion   char(25),
            cve_producto    char(20),
            tipo_cta        char(2),
            reg_fiscal      char(1),
            por_retencion   decimal(5,2),
            cve_sucursal    integer,
            sdo_cuenta      decimal(15,2),
            intereses       decimal(15,2),
            ret_impuestos   decimal(15,2),
            otros_accesorio decimal(15,2),
            sdo_neto        decimal(15,2),
            moneda          smallint,
            fecha_corte     char(8),
            fecha_contrata  char(8),
            plazo_opera     integer,
            tipo_tasa       smallint,
            tasa            decimal(6,3),
            inst_base       char(20),
            puntos_porc     decimal(6,3),
            operador        char(1),
            fecha_sig_corte char(8),
            sdo_prom_diario money(15,2),
            dias_ini        integer,
            saldo_ini       money(14,2),
            prom_ini        money(14,2),
            intereses_ini   money(14,2),
            isr_ini         money(14,2),
            dias_fin        integer,
            saldo_fin       money(14,2),
            prom_fin        money(14,2),
            intereses_fin   money(14,2),
            isr_fin         money(14,2) ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 1024000 next size 512000 lock mode row;

        create index "informix".idx_infpattitcomp_cta on "informix".si_infpattit_comp(numcta) in datos03 online ;
        create index "informix".idx_infpattitcomp_inv on "informix".si_infpattit_comp(num_inversion) in datos03 online;
        
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infpattit_comp;
        
        -- // CUENTAS ASOCIADAS DE LOS TITULARES
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_ctaasotit_comp') THEN
            DROP TABLE "informix".si_ctaasotit_comp;
        END IF;
        
        create raw table "informix".si_ctaasotit_comp (
            numcta          char(35),
            num_inversion   char(25),
            cve_unica       char(18),
            porcentaje_tit  decimal(5,2) ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 512000 next size 64000 lock mode row;

        create index "informix".idx_ctaasotitcomp_cta on "informix".si_ctaasotit_comp(numcta) in datos03 online;
        create index "informix".idx_ctaasotitcomp_inv on "informix".si_ctaasotit_comp(num_inversion) in datos03 online;
        create index "informix".idx_ctaasotitcomp_cve on "informix".si_ctaasotit_comp(cve_unica) in datos03 online;
        
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_ctaasotit_comp;
        
        -- // INFORMACIÓN CREDITICIA DE LOS TITULARES
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_infcrdtit_comp') THEN
            DROP TABLE "informix".si_infcrdtit_comp;
        END IF;
        
        create raw table "informix".si_infcrdtit_comp (
            num_credito     char(20),
            moneda          smallint,
            segmento        smallint,
            tpo_cobranza    smallint,
            cap_vigente     decimal(15,2),
            cap_vencido     decimal(15,2),
            ints_ord_exig   decimal(15,2),
            ints_moratorios decimal(15,2),
            otros_accesorio decimal(15,2) )
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 1024000 next size 512000 lock mode row;

        create index "informix".idx_infcrdtitcomp_crd on "informix".si_infcrdtit_comp(num_credito) in datos03 online;
        
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_infcrdtit_comp;
        
        -- // CREDITOS ASOCIADOS DE LOS TITULARES
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_crdasotit_comp') THEN
            DROP TABLE "informix".si_crdasotit_comp;
        END IF;
        
        create raw table "informix".si_crdasotit_comp (
            num_credito     char(20),
            cve_unica       char(18) ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 512000 next size 64000 lock mode row;

        create index "informix".idx_crdasotitcomp_crd on "informix".si_crdasotit_comp(num_credito) in datos03 online;
        create index "informix".idx_crdasotitcomp_cve on "informix".si_crdasotit_comp(cve_unica) in datos03 online;
        
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_crdasotit_comp;   
        
        -- // TABLA DE CLIENTES IPAB
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_clientes_ipab_comp') THEN
            DROP TABLE "informix".si_clientes_ipab_comp;
        END IF;
        
        create raw table "informix".si_clientes_ipab_comp (
            numcte  char(20) ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 256000 next size 32000 lock mode row;
        
        create index "informix".idx_clientesipabcomp_cte ON "informix".si_clientes_ipab_comp(numcte) IN datos03 ONLINE;
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_clientes_ipab_comp;
        
        -- // TABLA DE CLIENTES IPAB
        IF EXISTS (SELECT tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_cliente_ipab_comp') THEN
            DROP TABLE "informix".si_cliente_ipab_comp;
        END IF;
        
        create raw table "informix".si_cliente_ipab_comp (
            numcte  char(20) ) 
        fragment by round robin in datos00 , datos01 , datos02 
        extent size 256000 next size 32000 lock mode row;
        
        create index "informix".idx_clienteipabcomp_cte ON "informix".si_cliente_ipab_comp(numcte) IN datos03 ONLINE;
        UPDATE STATISTICS MEDIUM FOR TABLE "informix".si_cliente_ipab_comp;
    
    END IF;
        
    END;
    
    RETURN cCodRet;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_ipab_rangoctes()
RETURNING CHAR(5);
    
    DEFINE cCodRet      CHAR(5);
    DEFINE cCodRet2     CHAR(5);
    DEFINE cCodRet3     CHAR(50);
    DEFINE iSqlErr      INTEGER;
    DEFINE iSamErr      INTEGER;
    DEFINE iDesErr      CHAR(50);
    DEFINE vpromedio    INTEGER;
    DEFINE vcont        SMALLINT;
    DEFINE vbrinca      INTEGER;
    DEFINE cNumCte      CHAR(20);
    
    LET cCodRet    = "000";
    LET cCodRet2   = "";
    LET cCodRet3   = "";
    LET iSqlErr    = 0;
    LET iSamErr    = 0;
    LET iDesErr    = '';  
    LET vpromedio  = 0;
    LET vcont      = 0;
    LET vbrinca    = 0;
    LET cNumCte    = '';
    
    BEGIN

    ON EXCEPTION SET iSqlErr, iSamErr, iDesErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/sp_ipab_rangoctes.err";
        TRACE ON;
        IF iSqlErr <> 0 THEN
            LET cCodRet = iSqlErr;
            LET cCodRet2 = iSamErr;
            LET cCodRet3 = iDesErr;
            RETURN cCodRet;
        END IF;
    END EXCEPTION;

    ---	SET DEBUG FILE TO "/resplogifx/conciliachq/sp_ipab_rangoctes.out";
    ---	TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    SELECT ROUND(COUNT(*)/20)
      INTO vpromedio
      FROM si_cliente_ipab_comp;
      
    LET vcont = 1;
    
    WHILE vcont <= 21     
    
        IF vcont = 1 THEN
            SELECT MIN(numcte)
              INTO cNumCte
              FROM si_cliente_ipab_comp;
              
            UPDATE si_param
               SET valor = cNumCte
             WHERE cod_param = 200;
        ELIF vcont = 2 THEN
            LET vbrinca = vpromedio;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
             
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 201;
            END FOREACH;
        ELIF vcont = 3 THEN
            LET vbrinca = vpromedio * 2;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 202;
            END FOREACH;
        ELIF vcont = 4 THEN
            LET vbrinca = vpromedio * 3;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 203;
            END FOREACH;
        ELIF vcont = 5 THEN
            LET vbrinca = vpromedio * 4;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 204;
            END FOREACH;
        ELIF vcont = 6 THEN
            LET vbrinca = vpromedio * 5;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 205;
            END FOREACH;
        ELIF vcont = 7 THEN
            LET vbrinca = vpromedio * 6;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 206;
            END FOREACH;
        ELIF vcont = 8 THEN
            LET vbrinca = vpromedio * 7;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 207;
            END FOREACH;
        ELIF vcont = 9 THEN
            LET vbrinca = vpromedio * 8;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 208;
            END FOREACH;
        ELIF vcont = 10 THEN
            LET vbrinca = vpromedio * 9;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 209;
            END FOREACH;
        ELIF vcont = 11 THEN
            LET vbrinca = vpromedio * 10;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 210;
            END FOREACH;
        ELIF vcont = 12 THEN
            LET vbrinca = vpromedio * 11;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 211;
            END FOREACH;
        ELIF vcont = 13 THEN
            LET vbrinca = vpromedio * 12;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 212;
            END FOREACH;
        ELIF vcont = 14 THEN
            LET vbrinca = vpromedio * 13;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 213;
            END FOREACH;
        ELIF vcont = 15 THEN
            LET vbrinca = vpromedio * 14;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 214;
            END FOREACH;
        ELIF vcont = 16 THEN
            LET vbrinca = vpromedio * 15;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 215;
            END FOREACH;
        ELIF vcont = 17 THEN
            LET vbrinca = vpromedio * 16;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 216;
            END FOREACH;
        ELIF vcont = 18 THEN
            LET vbrinca = vpromedio * 17;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 217;
            END FOREACH;
        ELIF vcont = 19 THEN
            LET vbrinca = vpromedio * 18;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 218;
            END FOREACH;
        ELIF vcont = 20 THEN
            LET vbrinca = vpromedio * 19;
            FOREACH
                SELECT SKIP vbrinca FIRST 1 numcte
                  INTO cNumCte
                  FROM si_cliente_ipab_comp
                 ORDER BY numcte
                 
                UPDATE si_param
                   SET valor = cNumCte
                 WHERE cod_param = 219;
            END FOREACH;
        ELIF vcont = 21 THEN
            SELECT MAX(numcte)
              INTO cNumCte
              FROM si_cliente_ipab_comp;
              
            UPDATE si_param
               SET valor = cNumCte
             WHERE cod_param = 220;
        END IF;
        
        LET vcont = vcont + 1;  
        LET cNumCte = '';
    END WHILE;    

    END;
    
    RETURN cCodRet;

END PROCEDURE;

