CREATE PROCEDURE "informix".sp_borra_reenvio_ext_tokens_pba()
	RETURNING CHAR(5) as codRet;

	--************************************************************************************************************************************************
	--Modificó: Manuel Ramos Figueroa.
	--Objetivo: Depurar y cancelar las solicitudes que se encuentren en estatus de reactivada (180) con un periodo de días mayor al valor del campo 
	--			bdibpi:bpi_param.valor donde el valor del campo bdibpi:bpi_param.id_param sea igual a 17.
	--Solicitó: Aida Valenzuela (BanCoppel).
	--Fecha: 2015-07-20.
	--BD:bdinteg.
	--************************************************************************************************************************************************

	DEFINE cod_ret CHAR(5);
	DEFINE sql_err INTEGER;
	DEFINE cDiasDepuracion CHAR(40);
	DEFINE iDiasDepuracion INTEGER;
	DEFINE cDiasVigencia CHAR(40);
	DEFINE iDiasVigencia INTEGER;
	DEFINE cSolicitud CHAR(10);
	DEFINE cStatus SMALLINT;
	DEFINE cNumCte CHAR(9);
	DEFINE cSolicitudesDepuradas CHAR(7);
	DEFINE iSolicitudesDepuradas INTEGER;
	DEFINE cEmailUsuarioAdmToken CHAR(40);

	--Variables de retorno del SP sp_cons_detenvios_token
	DEFINE vCodRet CHAR(5);
	DEFINE vFolioSuc CHAR(16);
	DEFINE vCuenta CHAR(20);
	DEFINE vFecha DATE;
	DEFINE vSucursal CHAR(4);
	DEFINE vCargoTot MONEY(16,2);

	--Variable de retorno del SP sp_registra_evento
	DEFINE vCodRet2 CHAR(5);

	LET cod_ret = '00000';
	LET cDiasDepuracion = '';
	LET iDiasDepuracion = 0;
	LET cDiasVigencia = '';
	LET iDiasVigencia = 0;
	LET cSolicitud = '00000';
	LET cStatus = 0;
	LET cNumCte = '';
	LET cSolicitudesDepuradas = '';
	LET iSolicitudesDepuradas = 0;
	LET cEmailUsuarioAdmToken = '';

	LET vCodRet = '';
	LET vFolioSuc = '';
	LET vCuenta = '';
	LET vSucursal = '';
	LET vCargoTot = 0;

	LET vCodRet2 = '';

	SET DEBUG FILE TO 'sp_borra_reenvio_ext_tokens.out';
	TRACE ON;

	BEGIN
		ON EXCEPTION SET sql_err
			IF sql_err <> 0 THEN
				LET cod_ret = sql_err;
				RETURN cod_ret;
			END IF;
		END EXCEPTION;

		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;

		SELECT valor 
		INTO cDiasDepuracion 
		FROM bdibpi:"informix".bpi_param 
		WHERE id_param = '17';

		SELECT valor 
		INTO cDiasVigencia 
		FROM bdibpi:"informix".bpi_param 
		WHERE id_param = '18';

		LET iDiasDepuracion = TRIM(cDiasDepuracion)::INTEGER;
		LET iDiasVigencia = TRIM(cDiasVigencia)::INTEGER;

		DELETE {+INDEX(bdibpi:"informix".bpi_bitacora_reenvios idx_bitacora_reenvios)} FROM bdibpi:"informix".bpi_bitacora_reenvios WHERE fecha_depuracion < CURRENT YEAR TO SECOND - iDiasVigencia UNITS DAY;

		FOREACH

			SELECT  {+INDEX (bdibpi:"informix".bpi_tokensolicitud idx_bpi_tokensolicitud)}solicitud, id_status, numcte 
			INTO cSolicitud, cStatus, cNumCte 
			FROM bdibpi:"informix".bpi_tokensolicitud 
			WHERE id_status = 180 
			AND f_atencion < CURRENT YEAR TO SECOND - iDiasDepuracion UNITS DAY

			EXECUTE PROCEDURE bdibpi:"informix".sp_cons_detenvios_token('001',cSolicitud)
			INTO vCodRet, vFolioSuc, vCuenta, vFecha, vSucursal, vCargoTot;

			IF TRIM(NVL(vCodRet, '')) = '002' THEN

				INSERT INTO bdibpi:"informix".bpi_bitacora_reenvios(num_solicitud,numcliente,estatus_depuracion,fecha_depuracion) VALUES(cSolicitud,cNumCte,cStatus,current);

				UPDATE bdibpi:"informix".bpi_tokensolicitud SET id_status = 199 WHERE solicitud = cSolicitud;
				
				INSERT INTO bdibpi:"informix".tkn_stasolicitud(solicitud,anterior,actual,f_registro) VALUES(cSolicitud,'180','199',current);

				UPDATE {+INDEX(bdibpi:"informix".tkn_envios idx_tkn_envios_sol)} bdibpi:"informix".tkn_envios SET id_status = 199, comentarios = 'La solicitud fue cancelada' WHERE solicitud = cSolicitud;

				LET iSolicitudesDepuradas = iSolicitudesDepuradas + 1;

			END IF;

		END FOREACH;

		IF iSolicitudesDepuradas > 0 THEN

			LET cSolicitudesDepuradas = iSolicitudesDepuradas::CHAR(7);

			SELECT valor 
			INTO cEmailUsuarioAdmToken 
			FROM bdibpi:"informix".bpi_param 
			WHERE id_param = '16';

			EXECUTE PROCEDURE bdimnsj:"informix".sp_registra_evento('1','PORTAL_BPI','BPI_DRTOKN', '000000000', '','','1', cSolicitudesDepuradas,'','','','', '','','','0','',cEmailUsuarioAdmToken,'',1,0,0,0,0,current,'')
			INTO vCodRet2;

		ELSE

			--No se encontraron solicitudes a depurar.
			LET cod_ret = '00001';

		END IF;

		RETURN cod_ret;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_random() RETURNING INTEGER;
DEFINE GLOBAL seed DECIMAL(10) DEFAULT 1;
DEFINE d DECIMAL(20,0);
DEFINE aux DECIMAL(10);

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;
LET aux=0;

    while aux<1000
        LET d = (seed * 1103515245) + 12345;
        -- MOD function does not handle 20-digit values...  Dammit!!
        LET seed = d - 4294967296 * TRUNC(d / 4294967296);
        LET aux=seed;
    end while;
    
    
RETURN MOD(TRUNC(seed / 65536), 32768);
END PROCEDURE;

CREATE PROCEDURE "informix".sp_resp_param_movil(pGrupo char(3), pElemento char(3), pSolicitud char(13))
RETURNING CHAR(5) as codret, CHAR(100) as pregunta, CHAR(100) as respuesta, char(2) as elemento

DEFINE iSqlErr		INTEGER;
DEFINE sPregunta        CHAR(100);
DEFINE sRespuesta       CHAR(100);
DEFINE sElemento        CHAR(2);


LET iSqlErr         =0;
LET sPregunta       ='';
LET sRespuesta      ='';
LET sElemento       ='';

BEGIN
ON EXCEPTION SET iSqlErr
	IF iSqlErr <> 0 THEN
		RETURN iSqlErr, sPregunta, sRespuesta, sElemento;
	END IF;
END EXCEPTION;


        SELECT c.descripcion, b.descripcion, a.elemento INTO sPregunta, sRespuesta, sElemento
        FROM bdisolic:ss_detalle_scoring a INNER JOIN bdisolic:ss_scoring_element b 
            ON a.grupo=b.grupo AND a.elemento=b.elemento AND a.seccion=b.seccion
         INNER JOIN bdisolic:ss_scoring_grupo c ON b.grupo=c.grupo AND b.seccion=c.seccion 
        WHERE num_solicitud=pSolicitud AND a.grupo=pGrupo;
              

RETURN '00000', sPregunta, sRespuesta, sElemento;

END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_cifra_archivo_pba(pCodigo char(20)) 
returning 
          char(06) as resultado,
          char(80) as mensaje;

--************************ Definicion de variables *****************************
DEFINE cMensajeRet, cMensajeRet2     CHAR(80);

define vEmpresa             char(3);
define iCodRet              integer;
define cCodRet              char(06);
define isam_err             integer;
define visam_err            integer;
define error_info	          char(150);
define verror_info	        char(150);
define vUsuario             char(20);
define vCodigo              char(20);
define vLLave               char(200);
define vNomarch             char(100);
define vRutaOrigen          char(100);
define vRutaDestino         char(100);
define vNomarchSalida       char(100);
define vRutaOriginales      char(100);
define vNomarch_salida      char(100);
define vArmaShellExt        char(5000);
define v_ext_entrada          char(10);
define v_ext_salida           char(10);
define v_retorno_linea        char(1);


define vfecha_hoy           DATE;
define vPri_dia_mes         DATE;
define vDia, vMes           char(2);
define vAnio                char(4);
define vBlinda              char(50);

let cMensajeRet             = 'Proceso Exitoso';
let cMensajeRet2            = '';
let vEmpresa                = '001';
let iCodRet                 = 0;
let cCodRet                 = '000000';
let isam_err                = 0;
let visam_err               = 0;
let error_info              = '';
let verror_info             = '';
let vUsuario                = '';
let vCodigo                 = '';
let vLLave                  = '';
let vNomarch                = '';
let vRutaOrigen             = '';
let vRutaDestino            = '';
let vNomarchSalida          = '';
let vfecha_hoy              = date(1);
let vPri_dia_mes            = date(1);
let vDia                    = '';
let vMes                    = '';
let vAnio                   = '';
let vRutaOriginales         = '';
let vNomarch_salida         = '';
let vBlinda                 = '';
let vArmaShellExt		        = '';
let v_ext_entrada           = '';
let v_ext_salida            = '';
let v_retorno_linea         = '';

--**************************** Control de errores ******************************
begin
    on exception set iCodRet, isam_err, error_info
    	if iCodRet <> 0 then
          	let cCodRet = iCodRet;
            --let cMensajeRet ='Error al blindar archivo >> '|| vNomarch;
            let visam_err = isam_err;
            let verror_info = error_info;
            let cMensajeRet =  visam_err || ' - ' || trim(verror_info);
                	
  			return cCodRet,cMensajeRet ;
      end if;
    end exception;

  --Set debug file to "/home/sysprocs/sp_cifra_archivo.trc";
  --trace on;

    let vCodigo = trim(pCodigo);
    let vBlinda = 'blinda_archivo_' || trim(vCodigo) || '.sh'; 

    FOREACH
      SELECT trim(usuario), trim(llave), trim(nomarch), trim(ruta_origen), trim(nomarch_salida),trim(ruta_destino), trim(ruta_originales), trim(ext_entrada),
             trim(ext_salida), trim(retorno_linea)
        INTO vUsuario, vLLave, vNomarch, vRutaOrigen, vNomarch_salida, vRutaDestino, vRutaOriginales, v_ext_entrada, v_ext_salida, v_retorno_linea
        FROM bdinteg:si_configura_pgp
       WHERE codigo = vCodigo
        order by secuencia
  
      IF vUsuario <>  user THEN
          LET cCodRet = '00200';
          LET cMensajeRet = 'Usuario para cifrado incorrecto';
          return cCodRet,cMensajeRet;
      END IF;
     
      IF TRIM(v_ext_salida) = '' or TRIM(v_ext_salida) IS NULL THEN let v_ext_salida = 'pgp'; END IF;  

      IF TRIM(v_retorno_linea) = 'S' THEN
        --SYSTEM ' echo " for file in '|| trim(vRutaOrigen) || '*.txt; " > ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';  ---MACF  
        --system ' echo " for file in '|| trim(vRutaOrigen) || '*.' || trim(v_ext_entrada) || '; " > ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';
        system ' echo " for file in '|| trim(vRutaOrigen) || trim(vNomarch) || '.' || trim(v_ext_entrada) || '; " > ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';
        system ' echo "  do mv '|| '\$file'||' \$file''.TX''" >> ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh'; 
        system ' echo "  sed ''s/$/\r/g''' ||' \$file''.TX'' >> \$file " >> ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh'; 
        system ' echo "  rm ' || '\$file''.TX'' " >> ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';     
        system ' echo " done' || '">>' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';
        system 'chmod 777 ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';
        system '/usr/bin/sh ' || trim(vRutaOrigen) || 'inserta_cr_' || trim(vCodigo) || '.sh';
      END IF;
    
   
      SYSTEM 'echo "export PATH=/usr/bin:/etc:/usr/sbin:/usr/ucb:/home/' || trim(vUsuario) ||'/bin:/usr/bin/X11:/sbin:.:/opt/pgp/bin:/informix/bin">' || trim(vRutaOrigen) || trim(vBlinda);
      SYSTEM 'echo "export HOME=/home/' || trim(vUsuario) || '">>' || trim(vRutaOrigen) || trim(vBlinda); 
      SYSTEM 'echo "/opt/pgp/bin/pgp --encrypt -i ' || trim(vRutaOrigen) || trim(vNomarch) || ' -r ' || '''' || trim(vLLave) || '''' ||" --armor --compression --output " || trim(vRutaDestino) || trim(vNomarch_salida) || '">>' || trim(vRutaOrigen) || trim(vBlinda) ;
      SYSTEM 'chmod 777 ' || trim(vRutaOrigen) || trim(vBlinda);   
      SYSTEM '/usr/bin/sh ' || trim(vRutaOrigen) || trim(vBlinda);
      SYSTEM 'mv ' || trim(vRutaOrigen) || trim(vNomarch) || ' ' || vRutaOriginales;
     
      
      system ' echo " for file in '|| trim(vRutaDestino) || '*.asc; " > ' || trim(vRutaDestino) || 'cambia_ext_' || trim(vCodigo) || '.sh';  
      --SYSTEM ' echo "  do mv '|| '\$file'||' \`echo \$file | sed ''s/\(.*\.\)asc/\1pgp/''\`;' || ' " >> ' || trim(vRutaDestino) || 'cambia_ext_' || trim(vCodigo) || '.sh'; 
      system ' echo "  do mv '|| '\$file'||' \`echo \$file | sed ''s/\(.*\.\)asc/\1' || trim(v_ext_salida) || '/''\`;' || ' " >> ' || trim(vRutaDestino) || 'cambia_ext_' || trim(vCodigo) || '.sh';
      system ' echo " done' || '">>' || trim(vRutaDestino) || 'cambia_ext_' || trim(vCodigo) || '.sh';
      system '/usr/bin/sh ' || trim(vRutaDestino)  || 'cambia_ext_' || trim(vCodigo) || '.sh';
    
         
    END FOREACH
    
    return cCodRet,cMensajeRet;

end;
end procedure;

CREATE PROCEDURE "informix".sp_generararchivoplanobatch(cTipoMov CHAR(2), pFechaAct DATE)
RETURNING
     CHAR(6); ---cod_ret

    DEFINE v_cod_ret            CHAR(6);
    DEFINE iSqlErr              INTEGER;
    DEFINE iSamErr              INTEGER;
	DEFINE vDesErr              CHAR(60);
	DEFINE vsSQL1 				CHAR (150);
	DEFINE vsSQL2 				CHAR (750) ;
	DEFINE vsSQL3 				CHAR (150) ;
	--DEFINE v_NomArchivo  VARCHAR(50);
	DEFINE vRuta CHAR (90);
	DEFINE vsSQL CHAR (1050) ;
	DEFINE sPreNomArchivoFinal VARCHAR(100);
	DEFINE sNombreArchivoFinal VARCHAR(100);
	-- AAME RQI 27 067 SE AGREGA VARIABLE PARA EL NUEVO ARCHIVO
	DEFINE sAntNomArchivoFinal VARCHAR(100);
	DEFINE sAnterNomArchivoFinal VARCHAR(100);
	DEFINE iCountMovTO INTEGER;
	DEFINE v_TipoMov VARCHAR (20);
	DEFINE cFecha_hoy CHAR(8);
	DEFINE cFechaSistema DATE;
	DEFINE vAux VARCHAR(50,1);
	
	LET vsSQL = '' ;
	LET vsSQL1 = '' ;
	LET vsSQL2 = '' ;
	LET vsSQL3 = '' ;
	LET iCountMovTO = 0;
	LET  v_TipoMov = '';
	LET cFecha_hoy = '19000101';
	LET cFechaSistema = DATE(1);
	LET sPreNomArchivoFinal ='';
	LET sNombreArchivoFinal ='';
	-- AAME RQI 27 067 SE INICIALIZA VARIABLE PARA EL NUEVO ARCHIVO
	LET sAntNomArchivoFinal ='';
	LET sAnterNomArchivoFinal='';
    LET vAux = "||'||'||'|'||1||'||'||-99999||'|'||99999";
	
SET ISOLATION TO COMMITTED READ LAST COMMITTED;	
	---SET LOCK MODE TO WAIT 10;

BEGIN

   ON EXCEPTION
        SET iSqlErr, iSamErr
        IF iSqlErr <> 0 THEN
                LET v_cod_ret = iSqlErr;
                --EXECUTE PROCEDURE  "informix".sp_desc_ret(20, v_cod_ret)
                --INTO v_cod_ret, vDesErr;
        END IF;
        RETURN v_cod_ret;
    END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;

	--SET DEBUG FILE TO "/tmp/sp_GenerarArchivoPlano.out";
	--SET DEBUG FILE TO "/informix/Malena/sp_GenerarArchivoPlano.out";
	--TRACE ON;

	LET v_cod_ret = '000000';
	LET vDesErr = '';
	
	SELECT TRIM(valor)
	INTO vRuta
	FROM "informix".si_param
	WHERE cod_param='193';

	--LET vRuta = '/resplogifx/archivoscartera/altaunica/envios/';
	LET sNombreArchivoFinal = TRIM(vRuta)||'movimientosaltaunicabatch';
	-- INC 27 047 Se cambia el nombrado de los archivos generados a como se encontraban los productivos.
	
	IF cTipoMov IS NULL OR (cTipoMov <> '' AND cTipoMov <> 'TO') THEN
		LET v_cod_ret = '000001';
		RETURN v_cod_ret;
	END IF;
	
	SELECT COUNT(tipomovto) INTO iCountMovTO FROM "informix".si_archivoscopdiario WHERE tipomovto = 'TO' AND fecha_insert = pFechaAct;
	
	SELECT fecha_hoy INTO cFechaSistema FROM bdinteg:"informix".si_fechas;
    
	IF pFechaAct <> mdy(1,1,1900) OR pFechaAct IS NOT NULL THEN	
		IF iCountMovTO > 0 THEN
			IF cTipoMov = '' THEN	---	Se valida el tipo de movimiento
					
				IF EXISTS (SELECT DISTINCT tipomovto FROM "informix".si_archivoscopdiario WHERE tipomovto <> 'TO' AND fecha_insert = pFechaAct) THEN		---	Se valida que que tlpo de movimiento se encuentre en la tabla
					LET cFecha_hoy = YEAR(pFechaAct)||""||LPAD(MONTH(pFechaAct),2,0)||""||LPAD(DAY(pFechaAct),2,0);
					--AAME RQI 27 047 Se renombra el archivo para movimientos alta unica para que no se tome como el productivo
					LET sNombreArchivoFinal = TRIM(vRuta)||'movimientosaltaunicabatch'|| cFecha_hoy || '.txt' ;
					LET sPreNomArchivoFinal = TRIM(vRuta)||'movimientosaltaunica.unl';
					-- AAME RQI 27 067 SE AGREGA EL NOMBRE PARA EL NUEVOS ARCHIVOS DE PASO
					LET sAntNomArchivoFinal = TRIM(vRuta)||'movimientosaltaunica2.unl';
					LET sAnterNomArchivoFinal = TRIM(vRuta)||'movimientosaltaunica3.unl';
					--
					LET vsSQL = ' echo "UNLOAD TO ' ||  TRIM(vRuta)|| 'movimientosaltaunicax.unl' || ' DELIMITER ' || '''|''' || 
								' SELECT trama ' || TRIM(vAux) ||
								' FROM "informix".si_archivoscopdiario '||
								' WHERE tipomovto <> '||'''TO'''||
								' AND fecha_insert = '||''''||pFechaAct||''''||
								' " > ' || TRIM(vRuta)|| 'Ejecutamovimientosaltaunica.sql';
					SYSTEM vsSQL;
					LET vsSQL =  "chmod 777 "||sNombreArchivoFinal||" > "|| TRIM(vRuta)|| "Ejecutamovimientosaltaunica.sql";
					LET vsSQL = '';
					LET vsSQL = 'dbaccess bdinteg ' || TRIM(vRuta)|| 'Ejecutamovimientosaltaunica.sql';
					SYSTEM vsSQL;

					LET vsSQL = '';
					LET vsSQL =  "sed 's/\\//g' " || TRIM(vRuta)|| "movimientosaltaunicax.unl > " || sPreNomArchivoFinal;
					SYSTEM vsSQL;					
					LET vsSQL = '';
					LET vsSQL =  "sed 's/|$//g' " || TRIM(vRuta)|| "movimientosaltaunica.unl > " || sAntNomArchivoFinal;
					SYSTEM vsSQL;
					-- AAME RQI 27 067 SE AGREGA ARCHIVO DE PASO PARA AGREGAR ESPACIOS EN BLANCO A LOS CAMPOS VACÍOS
					LET vsSQL = '';
					LET vsSQL =  "sed 's/||/| |/g' " || TRIM(vRuta)|| "movimientosaltaunica2.unl > " || sAnterNomArchivoFinal;
					SYSTEM vsSQL;				
					LET vsSQL = '';
					LET vsSQL =  "sed 's/||/| |/g' " || TRIM(vRuta)|| "movimientosaltaunica3.unl > " || sNombreArchivoFinal;
					SYSTEM vsSQL;	
					--
					LET vsSQL = '';
					LET vsSQL =  "chmod 777 "||sNombreArchivoFinal||" > "|| TRIM(vRuta)|| "movimientosaltaunicaderechos.txt";
					SYSTEM vsSQL;
					LET vsSQL = '';
					LET vsSQL =  "rm " || TRIM(vRuta)|| "movimientosaltaunicaderechos.txt";
					SYSTEM vsSQL;
					---	RESPALDA LOS DATOS DEL MOVIMIENTO A LA TABLA HISTORICA
					INSERT INTO "informix".si_archivoscophist(empresa,secuencia, identificador,trama,tipomovto,fecha_archivo,fecha_insert)
					SELECT empresa,secuencia,'',trama,tipomovto,fecha_insert, cFechaSistema
					FROM "informix".si_archivoscopdiario
					WHERE tipomovto <> 'TO'
					AND fecha_insert = pFechaAct;
					
					--BORRA LOS MOVIMIENTOS DE LA TABLA DIARIA
					DELETE FROM "informix".si_archivoscopdiario
					WHERE tipomovto <> 'TO' 
					AND fecha_insert = pFechaAct;					
									
				END IF;
			ELIF cTipoMov = 'TO'  THEN --Valida el tipo de movimiento para generar el archivo de totales
				LET v_cod_ret = '000000';
				IF EXISTS (SELECT DISTINCT tipomovto FROM "informix".si_archivoscopdiario WHERE tipomovto = 'TO' AND fecha_insert = pFechaAct) THEN		---	Se valida que que tlpo de movimiento se encuentre en la tabla
					LET cFecha_hoy = YEAR(pFechaAct)||""||LPAD(MONTH(pFechaAct),2,0)||""||LPAD(DAY(pFechaAct),2,0);
					--AAME RQI 27 047 Se renombra el archivo para cifras alta unica para que no se tome como el productivo
					LET sNombreArchivoFinal = TRIM(vRuta)|| 'cifrasaltaunicabatch'|| cFecha_hoy || '.txt';
					LET sPreNomArchivoFinal =  TRIM(vRuta)|| 'cifrasaltaunica.unl';
					-- AAME RQI 27 067 SE AGREGA EL NOMBRE PARA EL NUEVOS ARCHIVOS DE PASO
					LET sAntNomArchivoFinal = TRIM(vRuta)|| 'cifrasaltaunica2.unl';
					LET sAnterNomArchivoFinal = TRIM(vRuta)|| 'cifrasaltaunica3.unl';
					--
					---	GENERA EL ARCHIVO PLANO
					LET vsSQL1 = ' echo "UNLOAD TO ' || TRIM(vRuta)||'cifrasaltaunicax.unl' || ' DELIMITER ' || '''|''';
					LET vsSQL2 = "SELECT  trama FROM  bdinteg:si_archivoscopdiario WHERE  tipomovto = '"||cTipoMov||"' AND fecha_insert ='"||pFechaAct||"';";
					LET vsSQL3 = ' " > '|| TRIM(vRuta) || 'Ejecutacifrasaltaunica.sql'; 
					LET vsSQL = vsSQL1 || vsSQL2 || vsSQL3;
					SYSTEM vsSQL;
				    LET vsSQL =  "chmod 777 "||sNombreArchivoFinal||" > "|| TRIM(vRuta)|| "Ejecutacifrasaltaunica.sql";
					LET vsSQL = '';
					LET vsSQL = 'dbaccess bdinteg '|| TRIM(vRuta)|| 'Ejecutacifrasaltaunica.sql';
					SYSTEM vsSQL;

					LET vsSQL = '';
					LET vsSQL =  "sed 's/\\//g' " || TRIM(vRuta)|| "cifrasaltaunicax.unl > "|| sPreNomArchivoFinal;
					SYSTEM vsSQL;
					LET vsSQL = '';
					LET vsSQL =  "sed 's/|$//g' " || TRIM(vRuta)|| "cifrasaltaunica.unl > "|| sAntNomArchivoFinal;
					SYSTEM vsSQL;
					-- AAME RQI 27 067 SE AGREGA ARCHIVO DE PASO PARA AGREGAR ESPACIOS EN BLANCO A LOS CAMPOS VACÍOS
					LET vsSQL = '';
					LET vsSQL =  "sed 's/||/| |/g' " || TRIM(vRuta)|| "cifrasaltaunica2.unl > " || sAnterNomArchivoFinal;
					SYSTEM vsSQL;	
					LET vsSQL = '';
					LET vsSQL =  "sed 's/||/| |/g' " || TRIM(vRuta)|| "cifrasaltaunica3.unl > " || sNombreArchivoFinal;
					SYSTEM vsSQL;	
					--
					LET vsSQL = '';
					LET vsSQL =  "chmod 777 " || sNombreArchivoFinal || " > "|| TRIM(vRuta)|| "cifrasaltaunicaderechos.txt";
					SYSTEM vsSQL;
					LET vsSQL = '';
					LET vsSQL =  "rm "|| TRIM(vRuta)|| "cifrasaltaunicaderechos.txt";
					SYSTEM vsSQL;
				
					---	RESPALDA LOS DATOS DEL MOVIMIENTO A LA TABLA HISTORICA
					INSERT INTO "informix".si_archivoscophist(empresa,secuencia, identificador,trama,tipomovto,fecha_archivo,fecha_insert)
					SELECT empresa,secuencia,'',trama,tipomovto,fecha_insert, cFechaSistema
					FROM "informix".si_archivoscopdiario
					WHERE tipomovto = 'TO'
					AND fecha_insert = pFechaAct;
					
					--BORRA LOS MOVIMIENTOS DE LA TABLA DIARIA
					DELETE FROM "informix".si_archivoscopdiario
					WHERE tipomovto = 'TO' 
					AND fecha_insert = pFechaAct;							

				END IF;
			END IF;
		ELSE
			LET v_cod_ret = '000002';
		END IF;
	ELSE
		LET v_cod_ret = '000003';
	END IF;
	RETURN v_cod_ret;
END;
--##############################################################################
--## Procedimiento   : "informix".sp_GenerarArchivoPlanobatch
--## Version         : 1.0
--## Creado por      : Maria Elena Angulo
--## Fecha creacion  : Diciembre de 2008
--## Descripcion     : Espejo del procedimiento sp_GenerarArchivoPlano que Realiza la generacion del archivo plano con las 
--## adecuaciones para los nuevos procesos que realizan la generación de archivos batch.
--##############################################################################
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultabanco( 
											pintcvebanco   VARCHAR(5)      -- clave de banco
											)
	RETURNING CHAR(5), CHAR(5), CHAR(60), CHAR(20), CHAR(10), CHAR(1), CHAR(1), CHAR(1), CHAR(1), CHAR(1), CHAR(1), CHAR(1);
	
	DEFINE vCodRet  CHAR(5);
	DEFINE vCodRet2	CHAR(5);
	DEFINE vSqlErr  INTEGER;
	DEFINE vIsamErr	INTEGER;
	DEFINE vclave	CHAR(5);
	DEFINE vnombre1	CHAR(60);
	DEFINE vnombre2 CHAR(20);
	DEFINE vfecha	DATE;
	DEFINE vspei	CHAR(1);
	DEFINE vcheques	CHAR(1);
	DEFINE vnomina	CHAR(1);
	DEFINE vtefr	CHAR(1);
	DEFINE vtefp	CHAR(1);
	DEFINE vdomir	CHAR(1);
	DEFINE vdomip	CHAR(1);
	
	LET vCodRet='000';
	LET vSqlErr=0;
	LET vIsamErr=0;
	LET vclave=TRIM(pintcvebanco);
	LET vnombre1='';
	LET vnombre2='';
	--LET vfecha='';
	LET vspei='0';
	LET vcheques='0';
	LET vnomina='0';
	LET vtefr='0';
	LET vtefp='0';
	LET vdomir='0';
	LET vdomip='0';
	
	--SET DEBUG FILE TO "/informix/Jess/sp_consultabanco.out";
    --TRACE ON;
	
	BEGIN
	   
	    ON EXCEPTION SET vSqlErr, vIsamErr
			--SET DEBUG FILE TO "/informix/Jess/sp_consultabanco.out";
			--TRACE ON;
			IF vSqlErr != 0 THEN
				LET vCodRet = vSqlErr;
				LET vCodRet2 = vIsamErr;
            RETURN vCodRet, vclave, vnombre1, vnombre2, vfecha, vspei, vcheques, vnomina, vtefr, vtefp, vdomir, vdomip; 
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF LENGTH(vclave)>0 THEN 
		
			SELECT descripcion, vchrnombrecorto, fecha_opera, flg_spei, flg_cheq, flg_nomi, flg_tef_r, flg_tef_p, flg_domi_r, flg_domi_p
			INTO vnombre1, vnombre2, vfecha, vspei, vcheques, vnomina, vtefr, vtefp, vdomir, vdomip
			FROM si_bancos
			WHERE cvecesif=vclave;

		ELSE
		
		    LET vCodRet='001';   -- No existe la clave
		
		END IF
	END;
	RETURN vCodRet, vclave, vnombre1, vnombre2, vfecha, vspei, vcheques, vnomina, vtefr, vtefp, vdomir, vdomip;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_bitacora_actividades( pcanal       CHAR(02),
                                                     ptransaccion CHAR(04),
                                                     psucursal    CHAR(04),
                                                     pusuario     CHAR(08),
                                                     pfolio_suc   CHAR(16),
                                                     pctataotro   CHAR(20) )
RETURNING CHAR(5);
    
	DEFINE vcodret1         	CHAR(5);
    DEFINE vcodret2         	CHAR(5);
    DEFINE vcodret3         	CHAR(50);
    DEFINE sql_err          	INTEGER;
    DEFINE isam_err         	INTEGER;
    DEFINE desc_err         	CHAR(50);
    DEFINE vcontador        	INTEGER;
    DEFINE ven_transacc     	SMALLINT; 
	DEFINE vsql             	CHAR(400);
    
	
    LET  vcodret1         		= '000';
    LET  vcodret2         		= '000';
    LET  vcodret3         		= '';
    LET  sql_err	       		= 0 ;
    LET  isam_err         		= 0 ;
    LET  desc_err         		= '';
    LET  vcontador        		= 0 ;
    LET  ven_transacc     		= 0 ;
	LET  vsql             		= '';
    
	
    BEGIN
    
    ON EXCEPTION SET sql_err, isam_err, desc_err
        --SET DEBUG FILE TO "/resplogifx/conciliachq/sp_bitacora_actividades.err";
        --TRACE ON;
        IF sql_err <> 0 THEN
            LET vcodret1 = sql_err;
            LET vcodret2 = isam_err;
            LET vcodret3 = desc_err;
            IF ven_transacc = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vcodret1;
        END IF;
    END EXCEPTION;
  
    --- SET DEBUG FILE TO "/informix/resplogifx/conciliachq/sp_bitacora_actividades.out";
    --- TRACE ON;
	
    IF ( ( SELECT COUNT(*) FROM si_bitacora_actividades WHERE folio_suc = pfolio_suc ) > 0 ) THEN
					SET ISOLATION TO DIRTY READ;
                   UPDATE si_bitacora_actividades 
                   SET valor = pctataotro ,
                   hora_fin = (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdinteg:si_fechas)
                   WHERE folio_suc = pfolio_suc;
        
        
    ELSE
					SET ISOLATION TO DIRTY READ; 
                   INSERT INTO si_bitacora_actividades  
				   VALUES (pcanal,ptransaccion,psucursal,pusuario,pfolio_suc,NULL, (SELECT CURRENT + (fecha_hoy - CURRENT) FROM bdinteg:si_fechas), NULL);
        
    END IF
    
    END;
    
    RETURN vcodret1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_fusion_retroactiva_rel_bancoppel_coppel()
RETURNING CHAR(6), CHAR(100);
	DEFINE cCodRet			CHAR(6);
	DEFINE cErrorSQL		CHAR(100);
	DEFINE i_SqlError		INTEGER;
	DEFINE i_iSamError		INTEGER;
	DEFINE vcont			INTEGER;
	
	DEFINE cCliente_tit		CHAR(20);
	DEFINE cCliente_tras	CHAR(20);
	DEFINE vcnumcte_tf		CHAR(20);
	DEFINE cProceso			CHAR(50);
	DEFINE cTabla			CHAR(30);	
	DEFINE cUsuario			CHAR(8);
		
	DEFINE iTrans_abierta	INTEGER;
	DEFINE iTotalReg		INTEGER;
	DEFINE iProcesados		INTEGER;
	DEFINE MAXTRANSACCION	INTEGER;
	
	DEFINE dFecha_fusion	DATE;
	DEFINE vc_detalle_mov  CHAR(200);
	
	DEFINE dtFechaInsercion	DATETIME HOUR TO FRACTION;
	
	LET cCliente_tit = '';
	LET cCliente_tras = '';
	LET cCodRet = '000000';
	LET MAXTRANSACCION = 3000;	
	LET iProcesados = 0;
	LET iTotalReg= 0;
	LET iTrans_abierta= 0;
	LET cProceso = '';
	LET cTabla = '';
	LET cUsuario = '';

	LET cErrorSQL = 'PROCESO TERMINADO SATISFACTORIAMENTE';
	
	--SET DEBUG FILE TO "/informix/josea/64116/sp_fusiona_relaciones_bancoppel_coppel.out";
	--TRACE ON;	
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	BEGIN
		ON EXCEPTION SET i_SqlError,i_iSamError, cErrorSQL
			IF i_SqlError <> 0 THEN				
				IF iTrans_abierta = 1 THEN
					ROLLBACK WORK;
				END IF;
				
				LET cCodRet = i_SqlError;
				SELECT DBINFO('utc_to_datetime',sh_curtime) INTO dtFechaInsercion FROM sysmaster:"informix".sysshmvals;
				
				LET vc_detalle_mov=i_SqlError||'|'||i_iSamError;
				
				INSERT INTO log_fusionclientes(proceso,tabla,cliente_tit,cliente_tras,detalle_mov,fecha_hora,user_insert,fecha_insert)
				VALUES (cProceso, cTabla,cCliente_tit,cCliente_tras,vc_detalle_mov,dtFechaInsercion,cUsuario,CURRENT::DATE); 
				
				IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
					DROP TABLE tmpfusionados;
				END IF;	
				
				RETURN cCodRet, cErrorSQL;
			END IF;
		END EXCEPTION;
		
		SELECT DISTINCT a.cliente_tit, a.cliente_tras, a.fecha_fusion, a.usuario
		FROM TABLE(MULTISET(SELECT a.cliente_tit, a.cliente_tras, a.fecha_fusion, a.usuario
							FROM TABLE(MULTISET( SELECT cliente_titular AS cliente_tit, cliente_traspasar AS cliente_tras, fecha_fusion::DATE AS fecha_fusion, TRIM(usuario_sif) AS usuario FROM bdinteg:si_fusbitacora WHERE fusion = 'SI'
												 UNION ALL
												 SELECT cliente_tit, cliente_tras, fecha_fusion, TRIM('infoaut') AS usuario FROM bdinteg:si_fusion_solic WHERE estatus = 1
												 UNION ALL
												 SELECT cliente_tit, cliente_tras, fecha_fusion,TRIM('infoaut') AS usuario FROM bdinteg:si_fusionaut WHERE estatus = 1)) a
							LEFT JOIN TABLE(MULTISET(SELECT cliente_tit, cliente_tras FROM si_desfusionctes WHERE estatus = 1)) b
							ON a.cliente_tit = b.cliente_tit AND a.cliente_tras = b.cliente_tras
							WHERE b.cliente_tit IS NULL)) a, bdinteg:si_relacion_ctebcplcpl b, bdinteg:si_fuscliente c
		WHERE a.cliente_tras = b.numcte_banco
		AND numcte_banco = c.numcte
        INTO TEMP tmpfusionados WITH NO LOG;

		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
			SELECT COUNT(cliente_tit) INTO iTotalReg FROM tmpfusionados;
		END IF;	
		
		IF iTotalReg > 0 THEN		
			FOREACH WITH HOLD
				SELECT DISTINCT cliente_tit, cliente_tras, usuario, fecha_fusion
				INTO cCliente_tit, cCliente_tras, cUsuario, dFecha_fusion
				FROM tmpfusionados
				ORDER BY fecha_fusion
												
				IF iProcesados = 0 THEN
					BEGIN WORK;
					LET iTrans_abierta = 1;
				END IF;				
				
				LET cProceso = 'REL CTE BCPL-CPL';
				LET cTabla = 'si_relacion_ctebcplcpl';
				
				IF EXISTS (SELECT 1 FROM bdinteg:si_relacion_ctebcplcpl WHERE empresa = '001' AND numcte_banco = cCliente_tras) THEN
				
					INSERT INTO bdinteg:si_fusrelacion_ctebcplcpl (empresa, numcte_banco, cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp)
					SELECT empresa, numcte_banco, cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp
					FROM bdinteg:si_relacion_ctebcplcpl
					WHERE empresa = '001'
					AND numcte_banco = cCliente_tras;
					
					SELECT cliente
					INTO vcnumcte_tf
					FROM bdinteg:si_relacion_ctebcplcpl
					WHERE empresa = '001'
					AND numcte_banco = cCliente_tras;
					
					IF EXISTS (SELECT 1  FROM bdinteg:si_relacion_ctebcplcpl WHERE empresa = '001' AND numcte_banco = cCliente_tit) THEN
						DELETE FROM bdinteg:si_relacion_ctebcplcpl 
						WHERE empresa = '001' 
						AND numcte_banco = cCliente_tras;
					ELSE
						UPDATE bdinteg:si_relacion_ctebcplcpl 
						SET numcte_banco = cCliente_tit
						WHERE empresa = '001' 
						AND numcte_banco = cCliente_tras;
					END IF;
					
					SELECT DBINFO('utc_to_datetime',sh_curtime) 
					INTO dtFechaInsercion 
					FROM sysmaster:"informix".sysshmvals;
					
					LET vc_detalle_mov = TRIM(cCliente_tit)||'|'||TRIM(cCliente_tras)||'|'||TRIM(vcnumcte_tf);
					
					INSERT INTO bdinteg:log_fusionclientes (proceso,tabla,cliente_tit,cliente_tras,detalle_mov,fecha_hora,user_insert,fecha_insert)
					VALUES (cProceso, cTabla,cCliente_tit,cCliente_tras,vc_detalle_mov,dtFechaInsercion,cUsuario,CURRENT::DATE); 
				END IF;
				--***********************--
				--RELACION CLIENTE BANCOPPEL-COPPEL HISTORICA--
				--***********************--
				LET cProceso = 'REL CTE BCPL-CPL HIST';
				LET cTabla = 'si_relacion_ctebcplcpl_hist';
				
				IF EXISTS (SELECT 1  FROM bdinteg:si_relacion_ctebcplcpl_hist WHERE empresa = '001' AND numcte_banco = cCliente_tras) THEN
					INSERT INTO bdinteg:si_fusrelacion_ctebcplcpl_hist (empresa, numcte_banco, secuencia, cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp)
					SELECT empresa, numcte_banco, secuencia, cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp
					FROM bdinteg:si_relacion_ctebcplcpl_hist
					WHERE empresa = '001'
					AND numcte_banco = cCliente_tras;				

					SELECT DBINFO('utc_to_datetime',sh_curtime) 
					INTO dtFechaInsercion 
					FROM sysmaster:"informix".sysshmvals;
					
					FOREACH 
						SELECT cliente, secuencia
						INTO vcnumcte_tf, vcont
						FROM bdinteg:si_relacion_ctebcplcpl_hist
						WHERE empresa = '001'
						AND numcte_banco = cCliente_tras
						
						LET vc_detalle_mov = TRIM(cCliente_tit)||'|'||TRIM(cCliente_tras)||'|'||TRIM(vcnumcte_tf)||'|'||vcont;
					
						INSERT INTO bdinteg:log_fusionclientes (proceso,tabla,cliente_tit,cliente_tras,detalle_mov,fecha_hora,user_insert,fecha_insert)				
						VALUES (cProceso, cTabla,cCliente_tit,cCliente_tras,vc_detalle_mov,dtFechaInsercion,cUsuario,CURRENT::DATE); 
					END FOREACH;
					
					IF EXISTS (SELECT 1  FROM bdinteg:si_relacion_ctebcplcpl_hist WHERE empresa = '001' AND numcte_banco = cCliente_tit) THEN
						DELETE FROM bdinteg:si_relacion_ctebcplcpl_hist
						WHERE empresa = '001' 
						AND numcte_banco = cCliente_tras;
					ELSE
						UPDATE bdinteg:si_relacion_ctebcplcpl_hist
						SET numcte_banco = cCliente_tit
						WHERE empresa = '001' 
						AND numcte_banco = cCliente_tras;
					END IF;			
				END IF;
												
				LET iProcesados = iProcesados + 1;
				
				IF iProcesados >= MAXTRANSACCION THEN
					LET iProcesados = 0;
					COMMIT WORK;
					LET iTrans_abierta = 0;
				END IF;
			END FOREACH;
			IF iProcesados > 0 THEN
				IF iProcesados < MAXTRANSACCION THEN
					COMMIT WORK;
					LET iTrans_abierta = 0;
				END IF;
				LET iProcesados = 0;
			END IF;
		END IF;
		
		IF EXISTS (SELECT dbsname,tabname FROM sysmaster:"informix".systabnames WHERE tabname = 'tmpfusionados') THEN
			DROP TABLE tmpfusionados;
		END IF;			

		RETURN cCodRet, cErrorSQL;
	END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_agregarbitacora_bpi_app(
pFechaOper datetime year to second,
pNumTrans char(4),
pNumSuc char(4),
pIdUsuario integer,
pIpUsuario char(15),
pFechaApli date,
pCtaOrigen char(12),
pCtaDesti char(20),  
pMonto money,
pSecTrans char(16),
pCgen1 char(100),  
pCgen2 char(200),  
pCgen3 char(60),  
pCgen4 char(60),  
pCgen5 char(60),  
pCgen6 char(100),  
pReferencia char(100),  
pFolio char(16),  
pDispositivo char(10)
)
 returning char(5);

	-- Realizo	 : IREB
	-- Actividad : Copia del SPL sp_agregarbitacora_bpi que apunta a la bitacora en la tabla de bdibpi
	-- Solicitó  : IREB
	-- Fecha	 : Junio/2015
--------------------------------------
    --127.0.0.01 : Android
    --127.0.0.02 : IOS
    --127.0.0.03 : WebApp
--------------------------------------
 --DEFINICION DE VARIABLES
DEFINE cod_ret char(5);
DEFINE sql_err integer;
DEFINE vCtasFrec CHAR(1);
DEFINE vNumCte CHAR(10);
DEFINE vCveCaducidad CHAR(1);
DEFINE vClaveBanco CHAR(60);
DEFINE vIp CHAR(10);

--INICIALIZA VARIABLES
LET cod_ret  = "000";
LET vClaveBanco = pCgen4;

IF pDispositivo = '01' THEN --Android
  LET vIp = '127.0.0.1';
END IF;

IF pDispositivo = '02' THEN --IOS
    LET vIp = '127.0.0.2';
END IF;

IF pDispositivo = '03' THEN --Tablet  
    LET vIp='127.0.0.3';
END IF;


--SET DEBUG FILE TO "/informix/ifg/sp_agregarbitacora_bpi_app.out";
--TRACE ON;

BEGIN
  ON EXCEPTION SET sql_err
      IF sql_err <> 0 THEN
            let cod_ret = sql_err;
            RETURN cod_ret;
      END IF ;
   END EXCEPTION ;

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	IF(pNumTrans IN ('1011','1015','2015','2100') ) THEN
		SELECT FIRST 1 vchrnombrecorto
		INTO pCgen4
		FROM BDINTEG:"informix".si_bancos
		WHERE banco = TRIM(vClaveBanco);
	END IF;

	
	INSERT INTO bdibpi:"informix".bpi_bitacora(fecha_oper,
			     id_operacion,
			     sucursal,
			     id_usuario,
			     ipusuario,
			     fecha_aplic,
			     cuenta_origen,
			     destino,
			     monto_oper,
			     sec_transaccion,
			     cgenerico1,
			     cgenerico2,
			     cgenerico3,
			     cgenerico4,
				 cgenerico5,
				 cgenerico6,
				 referencia,
				 folio) VALUES (pFechaOper,
						  pNumTrans,
						  pNumSuc,
						  pIdUsuario,
						  vIp,
						  pFechaApli,
						  pCtaOrigen,
						  pCtaDesti,
						  pMonto,
						  pSecTrans,
						  pCgen1,
						  pCgen2,
						  pCgen3,
						  pCgen4,
						  pCgen5,
						  pCgen6,
						  pReferencia,
						  pFolio);	

 	/*
	INSERT INTO si_bpibitacora(fecha_oper,
			     id_operacion,
			     sucursal,
			     id_usuario,
			     ipusuario,
			     fecha_aplic,
			     cuenta_origen,
			     destino,
			     monto_oper,
			     sec_transaccion,
			     cgenerico1,
			     cgenerico2,
			     cgenerico3,
			     cgenerico4) VALUES (pFechaOper,
						  pNumTrans,
						  pNumSuc,
						  pIdUsuario,
						  vIp,
						  pFechaApli,
						  pCtaOrigen,
						  pCtaDesti,
						  pMonto,
						  pSecTrans,
						  pCgen1,
						  pCgen2,
						  pCgen3,
						  pCgen4);
	*/

		SELECT ctas_frec INTO vCtasFrec FROM bdibpi:"informix".bpi_cat_operaciones WHERE id_oper = pNumTrans;

		IF (vCtasFrec = '1') THEN --- Significa que son operaciones que involucran cuentas frecuentes

			SELECT numcliente INTO vNumCte FROM bdibpi:"informix".bpi_usuario WHERE id_usuario = pIdUsuario AND st_portal = 'activo';

			SELECT cve_caducidad INTO vCveCaducidad FROM bdiprog:"informix".pp_ctasterceros WHERE cuenta = pCtaDesti AND num_cte = vNumCte;

			IF (vCveCaducidad = '3') THEN
				UPDATE bdiprog:"informix".pp_ctasterceros SET fecha_movtos = today WHERE cuenta = pCtaDesti AND num_ctE = vNumCte;
				RETURN cod_ret;
			ELSE
				RETURN cod_ret;
			END IF;

		END IF;
		RETURN cod_ret;
	--END IF;
	--RETURN cod_ret;
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_activadesactivaproductos(pEmpresa CHAR(3), pTipo CHAR(1), pTipoOrigen CHAR(1), pOrigen CHAR(4), pProducto CHAR(4), pSistema CHAR(2))

RETURNING CHAR(5); -- Código de retorno 

-- Declaración de variables
DEFINE cCodRet					CHAR(5);
DEFINE iSqlErr          		INTEGER;
DEFINE iSamErr         			INTEGER;
DEFINE cErrorInfo       		CHAR(60);
DEFINE cSucursales				CHAR(4);
DEFINE iExiste                  INTEGER;

-- Asignación variables
LET cCodRet        			= "00000";
LET iSqlErr          		= 0;
LET iSamErr            		= 0;
LET cErrorInfo         		= "";
LET cSucursales				= "";
LET iExiste                 = 0;

BEGIN

	ON EXCEPTION SET iSqlErr, iSamErr, cErrorInfo
		LET cCodRet = iSqlErr;
		RETURN cCodRet;
	END EXCEPTION;
   
	--SET DEBUG FILE TO "/tmp/sp_activadesactivaproductos.out";
	--TRACE ON;
    
	IF pTipo = "1" THEN --Activación
		IF pTipoOrigen = "R" THEN --Activacion de productos para Region 
			FOREACH
				SELECT sucursal INTO cSucursales FROM bdinteg:si_sucursales WHERE plaza = pOrigen AND tpo_sucursal = "S"
				IF NOT EXISTS(SELECT sucursal, num_producto FROM bdinteg:si_prod_sucursal WHERE sucursal = cSucursales AND num_producto = pProducto) THEN
                    INSERT INTO bdinteg:si_prod_sucursal (empresa, sucursal, num_producto, sistema)
                    VALUES (pEmpresa, cSucursales, pProducto, pSistema);
                END IF;
			END FOREACH;
		ELIF pTipoOrigen = "S" THEN --Activacion de productos para Sucursal
            SELECT COUNT(num_producto) INTO iExiste FROM bdinteg:si_prod_sucursal WHERE sucursal = pOrigen AND num_producto = pProducto;
            IF iExiste = 0 THEN
                INSERT INTO bdinteg:si_prod_sucursal (empresa, sucursal, num_producto, sistema)
                VALUES (pEmpresa, pOrigen, pProducto, pSistema);
            END IF;

            IF NOT EXISTS(select * from bdisolic:ss_control_parametricos where empresa=pEmpresa and sucursal=pOrigen and num_producto=pProducto) THEN
               /* INSERT INTO bdisolic:ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
                VALUES(pEmpresa, '6001', pOrigen, '2', ' Nuevo modelo paramétrico CRIF', 'informix',today);

                INSERT INTO bdisolic:ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
                VALUES(pEmpresa, '6600', pOrigen, '2', ' Nuevo modelo paramétrico CRIF', 'informix', today);

                INSERT INTO bdisolic:ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
                VALUES(pEmpresa, '6300', pOrigen, '2', ' Nuevo modelo paramétrico CRIF', 'informix', today);*/
				
				INSERT INTO bdisolic:ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
                VALUES(pEmpresa, pProducto, pOrigen, '2', ' Nuevo modelo paramétrico CRIF', 'informix', today);
				
				
            END IF;
		ELIF pTipoOrigen = "T" THEN --Activacion de productos para todas las Sucursales
			FOREACH
				SELECT sucursal INTO cSucursales FROM bdinteg:si_sucursales WHERE tpo_sucursal = "S"
                IF NOT EXISTS(SELECT sucursal, num_producto FROM bdinteg:si_prod_sucursal WHERE sucursal = cSucursales AND num_producto = pProducto) THEN
                    INSERT INTO bdinteg:si_prod_sucursal (empresa, sucursal, num_producto, sistema)
                    VALUES (pEmpresa, cSucursales, pProducto, pSistema);
                END IF;                
			END FOREACH;
		END IF;
	ELIF pTipo = "0" THEN--Desactivacion
		IF pTipoOrigen = "R" THEN --Desactivacion de productos para Region 
			FOREACH
				SELECT sucursal INTO cSucursales FROM bdinteg:si_sucursales WHERE plaza = pOrigen AND tpo_sucursal = "S"
				
				DELETE FROM bdinteg:si_prod_sucursal 
				WHERE empresa = pEmpresa AND sucursal = cSucursales AND num_producto = pProducto AND sistema = pSistema;
			END FOREACH;
		ELIF pTipoOrigen = "S" THEN --Desactivacion de productos para Sucursal
			DELETE FROM bdinteg:si_prod_sucursal 
			WHERE empresa = pEmpresa AND sucursal = pOrigen AND num_producto = pProducto AND sistema = pSistema;
		ELIF pTipoOrigen = "T" THEN --Desactivacion de productos para todas las Sucursales
			FOREACH
				SELECT sucursal INTO cSucursales FROM bdinteg:si_sucursales WHERE tpo_sucursal = "S"
				
				DELETE FROM bdinteg:si_prod_sucursal 
				WHERE empresa = pEmpresa AND sucursal = cSucursales AND num_producto = pProducto AND sistema = pSistema;
			END FOREACH;
		END IF;
	END IF;
	
	RETURN cCodRet;
	
END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_buscar_detalle_tarjeta(p_numeroTarjeta CHAR(16))
			
    RETURNING CHAR(16) AS numeroTarjeta,CHAR(3) AS productoTarjeta, CHAR(1) AS titularTarjeta,DATE AS fechaNacimiento, CHAR(3) AS estatusTarjeta, CHAR(4) AS fechaExpiracion, CHAR(8) AS usuarioModificacion, DATETIME YEAR TO FRACTION AS fechaModificacion, CHAR(8) AS numeroReporte

	--definicion de variables--	    
    DEFINE resultado_numeroTarjeta 	 		VARCHAR(16);
    DEFINE resultado_productoTarjeta 	 	VARCHAR(3);
    DEFINE resultado_titularTarjeta	 		VARCHAR(1);
    DEFINE resultado_fechaNacimiento 	 	DATE;
    DEFINE resultado_estatusTarjeta	 		VARCHAR(3);
    DEFINE resultado_fechaExpiracion 	 	VARCHAR(4);
    DEFINE resultado_usuarioModificacion 	VARCHAR(8);
    DEFINE resultado_fechaModificacion   	DATEtime year to fraction(3);
    DEFINE resultado_numeroReporte       	VARCHAR(8);
    DEFINE iSqlErr                     	 	INTEGER;
		
     -- InicializaciÃ³n de las variables.
    LET resultado_numeroTarjeta 		= '';
	LET resultado_productoTarjeta 		= '';
	LET resultado_titularTarjeta 		= '';
	LET resultado_fechaNacimiento 		= '';
	LET resultado_estatusTarjeta 		= '';
	LET resultado_fechaExpiracion 		= '';
	LET resultado_usuarioModificacion 	= '';
    LET resultado_numeroReporte      	= '';
	--LET resultado_fechaModificacion 	= '';

    SET ISOLATION TO DIRTY READ;
	
	--SET DEBUG FILE TO "/aplicacion/pisabanco/pisa_ftes/syndein/img/InterAct/cfg/sp_buscar_detalle_tarjeta_"||p_numeroTarjeta||".out";
    --TRACE ON;
				
	BEGIN

        ON EXCEPTION
                SET iSqlErr
                IF iSqlErr <> 0 THEN
                    LET resultado_numeroTarjeta 		= '';
                    LET resultado_productoTarjeta 		= '';
					LET resultado_titularTarjeta 		= '';
					LET resultado_fechaNacimiento 		= '';
					LET resultado_estatusTarjeta 		= '';
					LET resultado_fechaExpiracion 		= '';
					LET resultado_usuarioModificacion 	= '';	
					LET resultado_numeroReporte      	= '';	
                    --LET resultado_fechaModificacion 	= '';
                    RETURN resultado_numeroTarjeta,resultado_productoTarjeta,resultado_titularTarjeta,resultado_fechaNacimiento,resultado_estatusTarjeta,resultado_fechaExpiracion,resultado_usuarioModificacion,resultado_fechaModificacion,resultado_numeroReporte;
                END IF;
        END EXCEPTION;
				
	
		SELECT DISTINCT numtarjeta,codproductotarjeta,titular,date(fechanacimiento),codstatustarjeta,fechaexp,usuarioultmodif,fechaultmodif,numreporte
        INTO resultado_numeroTarjeta,resultado_productoTarjeta,resultado_titularTarjeta,resultado_fechaNacimiento,resultado_estatusTarjeta,resultado_fechaExpiracion,resultado_usuarioModificacion,resultado_fechaModificacion,resultado_numeroReporte
        FROM intercard:tarjeta
        WHERE numtarjeta = p_numeroTarjeta;           
        
        RETURN resultado_numeroTarjeta,resultado_productoTarjeta,resultado_titularTarjeta,resultado_fechaNacimiento,resultado_estatusTarjeta,resultado_fechaExpiracion,resultado_usuarioModificacion,resultado_fechaModificacion,resultado_numeroReporte;
	END
END PROCEDURE
