CREATE PROCEDURE "informix".sp_generar_reporte_domi_pp_tdc_servicios(dFechaHoy DATE)
RETURNING CHAR(6), CHAR(100);

--DEFINICION DE VARIABLES
DEFINE vCodRet         	  CHAR(6);
DEFINE cMensCodRet     	  CHAR(100);
DEFINE iNomErr         	  INTEGER;
DEFINE iNanErr		   	  INTEGER;
DEFINE iEnTransaccion 	  SMALLINT;
DEFINE dFechaInicial      DATETIME YEAR TO FRACTION;
DEFINE dFechaFinal        DATETIME YEAR TO FRACTION;
DEFINE dFechaIni          DATE; 
DEFINE dFechaFin          DATE; 
DEFINE dFecha_act         DATE;
DEFINE iTotal1            INTEGER;
DEFINE cRep1              CHAR(300);
DEFINE cComercio          CHAR(60);
DEFINE cEstado1           CHAR(20);
DEFINE cNum_transacciones CHAR(18);
DEFINE dMonto             DECIMAL(16,2);
DEFINE cRep2              CHAR(300);
DEFINE fFecha             DATE;
DEFINE cEstado2           CHAR(20);
DEFINE cNum_pagos         CHAR(10);
DEFINE mMonto             DECIMAL(16,2);
DEFINE cRep3              CHAR(300);
DEFINE fFecha2            DATE;
DEFINE cEstado3           CHAR(20);
DEFINE cNum_domi          CHAR(10);
DEFINE mMonto2            DECIMAL(16,2);
DEFINE cRutaRepor         CHAR(100);
DEFINE cRutaRepor1        CHAR(100);  
DEFINE cRutaRepor2        CHAR(100);
DEFINE cRutaRepor3        CHAR(100);
DEFINE cProceso			  CHAR(100);
DEFINE cEvento			  CHAR(100);
DEFINE cMensaje           CHAR(110);
DEFINE iTotal             INTEGER;
DEFINE iMaxL			  INT;
DEFINE iMaxC              INT;
DEFINE iMaxD              INT;
DEFINE cMes               CHAR(2);
DEFINE cAnio              CHAR(4);

--ASIGNACION DE VARIABLES
LET vCodRet  = '000000';
LET iEnTransaccion = 0;
LET cMensCodRet = 'EL PROCESO DE REPORTES DE DOMICILIACION SE A GENERADO CORRECTAMENTE';
LET cMes = '';
LET cAnio = '';
LET cRutaRepor  = ''; 
LET cRutaRepor1 = ''; 
LET cRutaRepor2 = ''; 
LET cRutaRepor3 = '';
LET cProceso = '';
LET cEvento = '';
LET cMensaje = '';
LET iTotal = 0;
LET iMaxL = 0;
LET iMaxC = 0;
LET iMaxD = 0;


--SET DEBUG FILE TO "/informix/Ingrid/sp_generar_reporte_domi_pp_tdc_servicios.out";
--TRACE ON;

BEGIN
	--Manejo del error
	ON EXCEPTION SET iNomErr, iNanErr, cMensCodRet
		IF iNomErr <> 0 THEN
			LET vCodRet=iNomErr;
			
			IF iEnTransaccion = 1 THEN
				ROLLBACK;
			END IF;
			
			SELECT DBINFO('utc_to_datetime',sh_curtime)
			INTO dFechaFinal
			FROM sysmaster:"informix".sysshmvals;
			
			INSERT INTO si_log_indicadores_sucursal (fecha, proceso, evento, cod_error, mensaje)
			VALUES (dFechaHoy - 1 UNITS DAY, cProceso, cEvento, vCodret, cMensCodRet);
			
			UPDATE "informix".si_controlproc_indicadores 
			SET maxfecha_cargada = dFechaFin , flagfinalizado = 'F', coderror = vCodRet, msgerror =  cMensCodRet, fecha_cargafin =  dFechaFinal
			WHERE id_proc = 9
			AND nombre_proceso = cProceso
			AND fecha_procesoIni = dFechaIni
			AND fecha_procesoFin = dFechafin;
			
			RETURN vCodRet, cMensCodRet;
		END IF;			
	END EXCEPTION;
	
	--OBTENCIÓN DE MES Y AÑO DE LOS REPORTES				
	LET dFechaFin = dFechaHoy - DAY(dFechaHoy);		       
	LET dFechaIni = dFechaFin - (DAY(dFechaFin) -1);	
	LET cMes      = LPAD(MONTH(dFechaFin), 2, 0);
	LET cAnio     = YEAR(dFechaFin);
	
	--GUARDA INFORMACIÓN INICIAL EN LA TABLA si_controlproc_indicadores			
	SELECT DBINFO('utc_to_datetime',sh_curtime)
	INTO dFechaInicial 
	FROM sysmaster:"informix".sysshmvals;
	
	LET cEvento = 'OBTENCION DE PARAMETROS';
	SELECT valor 
	INTO cRutaRepor
	FROM si_param
	WHERE cod_param = '358';
			
	SELECT valor 
	INTO cRutaRepor1
	FROM si_param
	WHERE cod_param = '355';
	
	SELECT valor 
	INTO cRutaRepor2
	FROM si_param
	WHERE cod_param = '356'; 

	SELECT valor 
	INTO cRutaRepor3
	FROM si_param
	WHERE cod_param = '357';		
	
	LET cProceso = 'REPORTE DE DOMICILIACIONES TARJETA DE DEBITO';
	LET cEvento = 'VALIDANDO GENERACION PREVIA DE REPORTE DE DOMICILIACIONES TARJETA DE DEBITO';
	IF NOT EXISTS(SELECT 1 FROM si_controlproc_indicadores WHERE id_proc = 9 AND nombre_proceso = cProceso AND fecha_procesoIni = dFechaIni AND fecha_procesoFin = dFechafin AND flagfinalizado = 'V') THEN
		LET cEvento = 'INSERTA REGISTRO INICIAL EN TABLA DE CONTROL DE PROCESOS';
		INSERT INTO "informix".si_controlproc_indicadores (fecha_procesoIni, fecha_procesoFin, id_proc, nombre_proceso, fecha_cargaini, fecha_cargafin, maxfecha_cargada,
														flagfinalizado, coderror, msgerror)
		VALUES (dFechaIni, dFechaFin, '9', cProceso, dFechaInicial, NULL, NULL, 'F', NULL, NULL );
			
		SELECT MAX(LENGTH(razon_social))
		INTO iMaxC
		FROM bdidomi:dom_cat_servicios;
		
		SELECT MAX(LENGTH(descripcion))
		INTO iMaxD
		FROM bdidomi:dom_status_pago;
		
		BEGIN WORK;
		--GENERA REPORTE DE DOMICILIACIONES TARJETA DE DÉBITO
		LET iEnTransaccion = 1;
		
		--REEMPLAZA LA FECHA EN EL NOMBRE DEL ARCHIVO
		LET cRutaRepor1 = REPLACE (cRutaRepor1, 'AAAA', cAnio);
		LET cRutaRepor1 = REPLACE (cRutaRepor1, 'MM', cMes);
			 
		--CUENTA NUMERO DE REGISTROS 
		LET cEvento = 'OBTIENE CANTIDAD DE REGISTROS DEL REPORTE DE DOMICILIACIONES TARJETA DE DEBITO';
		SELECT COUNT (a.razon_social)
			INTO iTotal 
			FROM bdidomi:dom_cat_servicios a, bdidomi:dom_cce_detalle b, bdidomi:dom_status_pago c  
			WHERE b.rfc_ord = a.rfc
			AND b.cve_estatus = c.cve_status
			AND b.cod_operacion = '30'
			AND b.banco_receptor = '137'
			AND b.tipo_cta_rec IN('03','10','40')
			--AND b.cve_estatus = '01'
			AND b.fecha_aplica BETWEEN YEAR(dFechaIni)||LPAD(MONTH(dFechaIni),2,0)||LPAD(DAY(dFechaIni),2,0) AND YEAR(dFechaFin)||LPAD(MONTH(dFechaFin),2,0)||LPAD(DAY(dFechaFin),2,0);
			 
		LET cEvento = 'GENERA ENCABEZADOS DE REPORTE DE DOMICILIACIONES TARJETA DE DEBITO';
		
		LET cRep1 =  'echo "' || RPAD('COMERCIO',iMaxC,' ') || '|' || RPAD('ESTADO',iMaxD,' ') || '|' || RPAD('NUMERO DE TRANSACCIONES',24, ' ') || '|' || 'MONTO' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
		SYSTEM cRep1;
		
		IF iTotal = 0 THEN
			LET cMensaje = 'NO EXISTE INFORMACION PARA GENERAR REPORTE DE DOMICILIACIONES TARJETA DE DÉBITO';
			LET cRep1 =  'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
			SYSTEM cRep1;
			LET cRep1 =  'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
			SYSTEM cRep1;				
			LET cRep1 =  'echo "' || TRIM(cMensaje) || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
			SYSTEM cRep1;			
		ELSE
			LET cEvento = 'OBTENCION DE REGISTROS DEL REPORTE DE DOMICILIACIONES TARJETA DE DEBITO';
			LET cMensaje = 'REPORTE DE DOMICILIACIONES TARJETA DE DÉBITO GENERADO';
			--IMPRIME 
			--LET cRep1 =   'echo "' || 'ID COMERCIO'|| '|' || 'COMERCIO' || '|' || 'NUMERO DE TRANSACCIONES' || '|' || 'MONTO' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
			FOREACH	
				--SELECT TRIM(b.rfc_ord) AS id_comercio, a.razon_social AS comercio, COUNT(b.rfc_ord) AS num_transacciones, SUM(((b.importe::INTEGER)/100)::DECIMAL(16,2)) AS monto
				--INTO cId_comercio, cComercio, cNum_transacciones, dMonto				
				SELECT a.razon_social AS comercio, UPPER(c.descripcion) AS estado, COUNT(b.rfc_ord) AS num_transacciones, SUM(((b.importe::INTEGER)/100)::DECIMAL(16,2)) AS monto
				INTO cComercio, cEstado1, cNum_transacciones, dMonto
				FROM bdidomi:dom_cat_servicios a, bdidomi:dom_cce_detalle b, bdidomi:dom_status_pago c  
				WHERE b.rfc_ord = a.rfc
				AND b.cve_estatus = c.cve_status
				AND b.cod_operacion = '30'
				AND b.banco_receptor = '137'
				AND b.tipo_cta_rec IN('03','10','40')
				--AND b.cve_estatus = '01'
				AND b.fecha_aplica BETWEEN YEAR(dFechaIni)||LPAD(MONTH(dFechaIni),2,0)||LPAD(DAY(dFechaIni),2,0) AND YEAR(dFechaFin)||LPAD(MONTH(dFechaFin),2,0)||LPAD(DAY(dFechaFin),2,0)
				GROUP BY 1,2
				ORDER BY 1 
						 
				--IMPRIME
				--LET cRep1 =  'echo "' || RPAD(TRIM(cId_comercio),iMaxL,' ')|| '|' ||  RPAD(UPPER(TRIM(cComercio)),iMaxC,' ') || '|' || RPAD(TRIM(cNum_transacciones),18,' ') || '|' || dMonto || '" >> ' || TRIM(cRutaRepor) || cRutaRepor1;
				LET cRep1 =  'echo "' ||  RPAD(UPPER(TRIM(cComercio)),iMaxC,' ') || '|' || RPAD(TRIM(cEstado1),iMaxD,' ') || '|' || RPAD(TRIM(cNum_transacciones),24,' ') || '|' || dMonto || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor1);
				SYSTEM cRep1;				
			END FOREACH;
		END IF;	
		COMMIT;
		LET iEnTransaccion = 0;
	
		SELECT DBINFO('utc_to_datetime',sh_curtime)
		INTO dFechaFinal 
		FROM sysmaster:"informix".sysshmvals;
		
		LET cEvento = 'ACTUALIZACION FINAL DE REGISTRO EN TABLA DE CONTROL DE PROCESOS';	
		
		UPDATE "informix".si_controlproc_indicadores 
		SET maxfecha_cargada = dFechaFin , flagfinalizado = 'V', coderror = vCodRet, msgerror = cMensaje, fecha_cargafin =  dFechaFinal
		WHERE id_proc = 9
		AND nombre_proceso = cProceso
		AND fecha_procesoIni = dFechaIni
		AND fecha_procesoFin = dFechafin;
	END IF;
		
	LET cProceso = 'REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
	--LET cEvento = 'INSERTA REGISTRO EN SI_CONTROLPROC_INDICADORES DE REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
	LET cEvento = 'VALIDANDO GENERACION PREVIA DE REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
	--GENERA REPORTE DE PAGOS PROGRAMADOS EN CUENTAS DE CAPTACIÓN DE TARJETA DE CRÉDITO BANCOPPEL VISA
	IF NOT EXISTS(SELECT 1 FROM si_controlproc_indicadores WHERE id_proc = 9 AND nombre_proceso = cProceso AND fecha_procesoIni = dFechaIni AND fecha_procesoFin = dFechafin AND flagfinalizado = 'V') THEN
		LET cEvento = 'INSERTA REGISTRO INICIAL EN TABLA DE CONTROL DE PROCESOS';
		INSERT INTO "informix".si_controlproc_indicadores (fecha_procesoIni, fecha_procesoFin, id_proc, nombre_proceso, fecha_cargaini, fecha_cargafin, maxfecha_cargada,
													flagfinalizado, coderror, msgerror)
		VALUES (dFechaIni, dFechaFin, '9', cProceso, dFechaInicial, NULL, NULL, 'F', NULL, NULL );
		
		BEGIN WORK;
		
		LET iEnTransaccion = 1;		
		
		--REEMPLAZA LA FECHA EN EL NOMBRE DEL ARCHIVO
		LET cRutaRepor2 = REPLACE (cRutaRepor2, 'AAAA', cAnio);
		LET cRutaRepor2 = REPLACE (cRutaRepor2, 'MM', cMes);
		
		--CUENTA NUMERO DE REGISTROS
		LET cEvento = 'OBTIENE CANTIDAD DE REGISTROS DEL REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
		SELECT COUNT (a.fecha_aplic) 
			INTO iTotal
			FROM bdiprog:pp_pagospend a, bdiprog:pp_pagoprog b, bdiprog:pp_estados c
			WHERE a.cve_pagoprog = b.cve_pagoprog
			AND a.estado = c.cve_estado
			--AND a.estado = '05'
			AND b.cve_pago = '05'
			AND a.fecha_aplic BETWEEN dFechaIni AND dFechaFin;
			
		LET cEvento = 'GENERA ENCABEZADOS DE REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
			
		LET cRep2 =  'echo "' || RPAD('FECHA',12, ' ') || '|' || RPAD('ESTADO',iMaxD, ' ') || '|' || RPAD('NUMERO DE PAGOS',16,' ') || '|' || 'MONTO' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor2);
		SYSTEM cRep2;
		
		IF iTotal = 0 THEN 
			LET cMensaje = 'NO EXISTE INFORMACION PARA GENERAR REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';
			LET cRep2 =  'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor2);
			SYSTEM cRep2;
			LET cRep2 =  'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor2);
			SYSTEM cRep2;
			LET cRep2 =  'echo "' || TRIM(cMensaje) || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor2);
			SYSTEM cRep2;			
		ELSE
			LET cEvento = 'OBTENCION DE REGISTROS DEL REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL';	
			LET cMensaje = 'REPORTE DE PAGOS PROGRAMADOS DE TDC BANCOPPEL GENERADO';
			FOREACH                                                          				
				SELECT a.fecha_aplic AS fecha, UPPER(c.descripcion) AS estado, COUNT(a.cve_pagoprog) AS num_pagos, SUM(((b.importe::INTEGER)/100)::DECIMAL(16,2)) AS monto
				INTO fFecha, cEstado2, cNum_pagos, mMonto
				FROM bdiprog:pp_pagospend a, bdiprog:pp_pagoprog b, bdiprog:pp_estados c
				WHERE a.cve_pagoprog = b.cve_pagoprog
				AND a.estado = c.cve_estado
				--AND a.estado = '05'
				AND b.cve_pago = '05'
				AND a.fecha_aplic BETWEEN dFechaIni AND dFechaFin
				GROUP BY 1,2
				ORDER BY 1
					
				--IMPRIME
				LET cRep2 = 'echo "' || RPAD(fFecha,12, ' ') || '|' || RPAD(cEstado2,iMaxD, ' ') || '|' || RPAD(cNum_pagos,16,' ') || '|' || mMonto || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor2);
				SYSTEM cRep2;

			END FOREACH;
		END IF;
		COMMIT;
		LET iEnTransaccion = 0;
		
		SELECT DBINFO('utc_to_datetime',sh_curtime)
		INTO dFechaFinal
		FROM sysmaster:"informix".sysshmvals;
		
		LET cEvento = 'ACTUALIZACION FINAL DE REGISTRO EN TABLA DE CONTROL DE PROCESOS';
		
		UPDATE "informix".si_controlproc_indicadores 
		SET maxfecha_cargada = dFechaFin , flagfinalizado = 'V', coderror = vCodRet, msgerror =  cMensaje, fecha_cargafin =  dFechaFinal
		WHERE id_proc = 9
		AND nombre_proceso = cProceso
		AND fecha_procesoIni = dFechaIni
		AND fecha_procesoFin = dFechafin;				
		--END IF;
	END IF;
	
	--GENERA REPORTE DE PAGO DE TARJETA DE CRÉDITO BANCOPPEL VISA DOMICILIADOS A OTROS BANCOS
	LET cProceso = 'REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
	LET cEvento = 'VALIDANDO GENERACION PREVIA DE REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
	--LET cEvento = 'INSERTA REGISTRO EN SI_CONTROLPROC_INDICADORES DE REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
	IF NOT EXISTS(SELECT 1 FROM si_controlproc_indicadores WHERE id_proc = 9 AND nombre_proceso = cProceso AND fecha_procesoIni = dFechaIni AND fecha_procesoFin = dFechafin AND flagfinalizado = 'V') THEN
		LET cEvento = 'INSERTA REGISTRO INICIAL EN TABLA DE CONTROL DE PROCESOS';
		INSERT INTO "informix".si_controlproc_indicadores (fecha_procesoIni, fecha_procesoFin, id_proc, nombre_proceso, fecha_cargaini, fecha_cargafin, maxfecha_cargada,
													flagfinalizado, coderror, msgerror)
		VALUES (dFechaIni, dFechaFin, '9', cProceso, dFechaInicial, NULL, NULL, 'F', NULL, NULL );
		
		BEGIN;
		LET iEnTransaccion = 1;
		
		--REEMPLAZA LA FECHA EN EL NOMBRE DEL ARCHIVO
		LET cRutaRepor3 = REPLACE (cRutaRepor3, 'AAAA', cAnio);
		LET cRutaRepor3 = REPLACE (cRutaRepor3, 'MM', cMes);
		
		--CUENTA NUMERO DE REGISTROS
		LET cEvento = 'OBTIENE CANTIDAD DE REGISTROS DEL REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
		SELECT COUNT(a.fecha_aplica) 
			INTO iTotal
			FROM bdidomi:dom_cce_detalle a, bdidomi:dom_status_pago b
			WHERE a.cve_estatus = b.cve_status 
			AND a.banco_receptor <> 137
			AND a.banco_presentador = 137
			AND a.tipo_cta_ord = 05  
			AND a.cod_operacion = 30
			AND a.fecha_aplica BETWEEN YEAR(dFechaIni)||LPAD(MONTH(dFechaIni),2,0)||LPAD(DAY(dFechaIni),2,0) 
							   AND 
							   YEAR(dFechaFin)||LPAD(MONTH(dFechaFin),2,0)||LPAD(DAY(dFechaFin),2,0);
			
		
		LET cEvento = 'GENERA ENCABEZADOS DE REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
		
		LET cRep3 =   'echo "' || RPAD('FECHA',12, ' ') || '|' || RPAD('ESTADO',iMaxD, ' ') || '|' || RPAD('NUMERO DE DOMICILIACIONES',26,' ') || '|' || 'MONTO' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor3);
		SYSTEM cRep3;
		
		IF iTotal = 0 THEN
			LET cMensaje = 'NO EXISTE INFORMACION PARA GENERAR REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
			LET cRep3 =   'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor3);
			SYSTEM cRep3;
			LET cRep3 =   'echo "' || ' ' || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor3);
			SYSTEM cRep3;
			LET cRep3 =   'echo "' || TRIM(cMensaje) || '" >> ' || TRIM(cRutaRepor) || TRIM(cRutaRepor3);
			SYSTEM cRep3;
		
		ELSE
		   LET cEvento = 'OBTENCION DE REGISTROS DEL REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS';
		   LET cMensaje = 'REPORTE DE PAGO DE TARJETA DE CREDITO VISA DOMICILIADOS A OTROS BANCOS GENERADO';
			
			FOREACH 					
				SELECT a.fecha_aplica::DATE AS fecha, UPPER(b.descripcion) AS estado, COUNT(a.rfc_ord) AS numero_domi, SUM(((a.importe::INTEGER)/100)::DECIMAL(16,2)) AS monto
				INTO fFecha2, cEstado3, cNum_domi, mMonto2
				FROM bdidomi:dom_cce_detalle a, bdidomi:dom_status_pago b
				WHERE a.cve_estatus = b.cve_status 
				AND a.banco_receptor <> 137
				AND a.banco_presentador = 137
				AND a.tipo_cta_ord = 05  
				AND a.cod_operacion = 30
				AND a.fecha_aplica BETWEEN YEAR(dFechaIni)||LPAD(MONTH(dFechaIni),2,0)||LPAD(DAY(dFechaIni),2,0) AND YEAR(dFechaFin)||LPAD(MONTH(dFechaFin),2,0)||LPAD(DAY(dFechaFin),2,0)
				GROUP BY 1,2
									
				--IMPRIME
				  LET cRep3 = 'echo "' || RPAD(fFecha2,12,' ') || '|' || RPAD(cEstado3,iMaxD,' ') || '|' || RPAD(cNum_domi,26,' ') || '|' || mMonto2 || '" >> ' || TRIM(cRutaRepor) || cRutaRepor3;
				  SYSTEM cRep3; 		  
			END FOREACH;
		END IF;
		COMMIT;
		LET iEnTransaccion = 0;
	
			SELECT DBINFO('utc_to_datetime',sh_curtime)
			INTO dFechaFinal
			FROM sysmaster:"informix".sysshmvals;
			
			LET cEvento = 'ACTUALIZACION FINAL DE REGISTRO EN TABLA DE CONTROL DE PROCESOS';
			
			UPDATE "informix".si_controlproc_indicadores 
			SET maxfecha_cargada = dFechaFin , flagfinalizado = 'V', coderror = vCodRet, msgerror =  cMensaje, fecha_cargafin =  dFechaFinal
			WHERE id_proc = 9
			AND nombre_proceso = cProceso
			AND fecha_procesoIni = dFechaIni
			AND fecha_procesoFin = dFechafin;	
	END IF;
	RETURN vCodRet, cMensCodRet;
END;
END PROCEDURE
DOCUMENT	
'REALIZA: Reporte de domiciliaciones de tarjeta de débito y pagos programados ',
'EQUIPO:Análisis y diseño de Mannto.4',
'FECHA:24/07/2015',
'VERSION:20150724',
'MODIFICO: Ingrid Pamela Cázarez Villegas',
'DESCRIPCION: Se realizan reportes de Domiciliaciones de tarjeta de débito y pagos programados en cuentas de captación para pagar tarjetas de crédito.',
'FECHA:08/09/2015',
'VERSION:20150908',
'MODIFICO: Ingrid Pamela Cázarez Villegas',
'DESCRIPCION: Se realizan reportes de Domiciliaciones de tarjeta de débito y pagos programados en cuentas de captación para pagar tarjetas de crédito.',
'FECHA:05/10/2015',
'VERSION:20151005',
'MODIFICO: Jose Angel Lopez Adams',
'DESCRIPCION: Se modifica consulta para extraer el archivo PPR.TDCBCPL.OBANCOS.AAAAMM.txt y evitar problemas en la validacion de fechas';

CREATE PROCEDURE "informix".sp_obtengrupocliente_pba(pnumcte CHAR(20)) 
	RETURNING 
	CHAR(5) AS codret,
	--CHAR(80) AS Mensaje,
	Char(1) AS grupoCliente;
	

	---DECLARACION DE VARIABLES
	DEFINE cCodRet CHAR(5);
	DEFINE ptipogrupo CHAR(1);
	DEFINE phit CHAR(6);
	DEFINE VSQL  CHAR(6000);
	DEFINE iSqlErr INTEGER;
	DEFINE dPaso  SMALLINT;
	DEFINE error_info CHAR(80);
	DEFINE isam_err INTEGER;	
	DEFINE vlCteLargo SMALLINT;
	DEFINE vlFecha	DATE;
	DEFINE	vlGrupoCte CHAR(1);
	
	--SET DEBUG FILE TO "/informix/marcov/sp_obtienegrupo.out";
	--TRACE ON;

	---INICIALIZACION DE VARIABLES
	LET cCodRet  = '00000';
	LET ptipogrupo = '';
	LET phit = '';
	LET VSQL = '';
	LET iSqlErr = 0;
	LET dPaso = 0;	
	LET vlCteLargo ='';
	LET	vlFecha = DATE(1);
	LET vlGrupoCte = '';

	BEGIN

	ON EXCEPTION SET iSqlErr, isam_err, error_info
	LET cCodRet = iSqlErr;
		RETURN cCodRet,'';
	END EXCEPTION;
	
	--Directiva para lectura de tablas bloqueadas.
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	
	SELECT fecha_hoy 
	  into vlFecha
	 FROM bdicred:sd_fechas
	 WHERE empresa = '001';
		
	SELECT count(*) into vlCteLargo
	FROM "informix".ss_clienteslargos
	WHERE numcte = pNumCte
	  AND fecha_vig_ini<= vlFecha 
	  AND fecha_vig_fin >= vlFecha
	  AND status ='AC';
	if vlCteLargo is null then let vlCteLargo = 0; end if;  
	if vlCteLargo >0 then  LET vlGrupoCte = '8'; END IF;  

	RETURN cCodRet, vlGrupoCte;

END
END PROCEDURE
DOCUMENT
'Se realiza procedimiento para obtener numero de grupo al que pertenece un cliente',
'AUTOR: Faviola Martinez Juarez',
'FECHA: 09/12/2013',
'BD: BDISOLIC';

CREATE PROCEDURE "informix".sp_cnsif_condetfol(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMFOLIO CHAR(16), cSISTEMACUENTA CHAR(10))
				returning CHAR(5)  AS Cod_Retorno,
                          CHAR(16) AS Folio,
                          CHAR(4)  AS Sucursal,
                          CHAR(08) AS Usuario,
                          DATE     AS Fecha,
                          DATETIME HOUR to FRACTION(3) AS Hora,
                          CHAR(1)  AS Cancelada,
                          CHAR(16) AS Numero_Tarjeta,
                          CHAR(08) AS Usuario_Autoriza,
                          CHAR(3)  AS Plaza,
                          CHAR(2)  AS Divisa,
                          DECIMAL(14,6) AS Tipo_Cambio,
                          CHAR(20) AS RFC_Comercial;

DEFINE iexiste 			INT;
DEFINE cCodRet 			CHAR(5);
DEFINE iSql_err 		INT;							
--VARIABLES
DEFINE cFolio 			CHAR(16);
DEFINE cSucursal 	 	CHAR(4);
DEFINE cUsuario		    CHAR(08);
DEFINE dFecha	 		DATE;
DEFINE dHora 			DATETIME HOUR to FRACTION(3);
DEFINE cCancelada		CHAR(1);
DEFINE cNumtarjeta		CHAR(16);
DEFINE cUsuarioAutoriza CHAR(08);
DEFINE cPlaza           CHAR(03);
DEFINE cDivisa          CHAR(02);
DEFINE dTipoCambio      DECIMAL(14,6);
DEFINE cRfc_Comer       CHAR(20);
DEFINE cSistemaCuenta_1	CHAR(10);
DEFINE sNUMSERIAL       INT8;


--inicializando variables
LET  iexiste = 0;
LET cCodRet = "00000";
LET iSql_err = 0 ;
LET cFolio 			= "";
LET cSucursal 	 	= "";
LET cUsuario	    = "";	
LET dFecha	 		= "";
LET dHora 			= "";
LET cCancelada		= "";
LET cNumtarjeta	    = "";
LET cUsuarioAutoriza    = "";
LET cPlaza          = "";
LET cDivisa         = "";
LET dTipoCambio     = 0;
LET cRfc_Comer      = "";
LET cSistemaCuenta_1	= "";
LET sNUMSERIAL          =  0;



BEGIN
	ON EXCEPTION SET iSql_err
		IF iSql_err <> 0 THEN
			LET cCodRet = iSql_err;
			RETURN 
			cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
		END IF;
	END EXCEPTION;

	
		--  SET DEBUG FILE TO "/tmp/CNSIF/sp_cnsif_condetfol.out";
		--  TRACE ON;

	LET cSISTEMACUENTA = TRIM(cSISTEMACUENTA);


	IF 	cID_USUARIOC = '' 	OR
		cID_FUNCIONC = '' 	OR
		cNUMFOLIO  = ''	OR  
		cSISTEMACUENTA = '' THEN 
		LET cCodRet = "00045";
		RETURN
		cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
	END IF;	

	IF cSISTEMACUENTA <> 'CAPTACION' AND cSISTEMACUENTA <> 'CREDITO'  AND cSISTEMACUENTA <> 'INVERSION' THEN
		LET cCodRet = "00048";
		RETURN 
		cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
	END IF;     	   

	EXECUTE FUNCTION sp_cnsif_confirmaejecutivo (cID_USUARIOC,cID_FUNCIONC)
	INTO cCodRet;
	  
	IF cCodRet = '00028' THEN 
		RETURN cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
	END IF;	

	IF cSISTEMACUENTA = 'CAPTACION' THEN 
			SELECT NVL(COUNT(folio_suc),0)  
			into iexiste
			FROM bdicheq:"informix".sc_movdia 
			WHERE folio_suc  = cNUMFOLIO AND empresa='001';
			IF iexiste  = 0 THEN 
				SELECT NVL(COUNT(folio_suc),0)  
				into iexiste
				FROM bdicheq:"informix".sc_movhis 
				WHERE folio_suc  = cNUMFOLIO AND empresa='001';
				IF iexiste  = 0 THEN
					SELECT NVL(COUNT(folio_suc),0)  
					into iexiste
					FROM bdicheq:"informix".sc_movhis_old 
					WHERE folio_suc  = cNUMFOLIO AND empresa='001';
					IF iexiste  = 0 THEN
						SELECT NVL(COUNT(folio_suc),0)  
						into iexiste
						FROM bdicheq:"informix".sc_movhis_old2 
						WHERE folio_suc  = cNUMFOLIO AND empresa='001';
						IF iexiste  = 0 THEN
							SELECT NVL(COUNT(folio_suc),0)  
							into iexiste
							FROM bdicheq:"informix".sc_movhis_old3 
							WHERE folio_suc  = cNUMFOLIO AND empresa='001';
							IF iexiste  = 0 THEN
								SELECT NVL(COUNT(folio_suc),0)  
								into iexiste
								FROM bdicheq:"informix".sc_movhis_old4 
								WHERE folio_suc  = cNUMFOLIO AND empresa='001';
							END IF;
						END IF;
					END IF;
				END IF;
			END IF;

			IF iexiste  = 0 THEN
				LET cCodRet = "00017";
				RETURN 
				cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
			END IF;

			FOREACH			
			SELECT LIMIT 1 mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
				   NVL(mm.num_tarjeta,''),mm.usuautoriza,mm.num_serial
			INTO 		
			cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,sNUMSERIAL	
				FROM  bdicheq:"informix".sc_movdia mm
				WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
					  mm.num_tarjeta,mm.usuautoriza,mm.num_serial
				  FROM bdicheq:"informix".sc_movhis AS mm
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
					   mm.num_tarjeta,mm.usuautoriza,mm.num_serial
				  FROM bdicheq:"informix".sc_movhis_old AS mm 
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
					   mm.num_tarjeta,mm.usuautoriza,mm.num_serial
				  FROM bdicheq:"informix".sc_movhis_old2 AS mm
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
					mm.num_tarjeta,mm.usuautoriza,mm.num_serial
				  FROM bdicheq:"informix".sc_movhis_old3 AS mm
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,
					   mm.num_tarjeta,mm.usuautoriza,mm.num_serial
				  FROM bdicheq:"informix".sc_movhis_old4 AS mm
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			ORDER BY mm.num_serial

            IF cNumtarjeta="0" THEN
                LET cNumtarjeta="";
            END IF;

			RETURN 
			cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer WITH RESUME;
			END FOREACH;

	ELIF cSISTEMACUENTA = 'CREDITO' THEN 
		SELECT NVL(COUNT(folio_suc),0)  
		into iexiste
		FROM bdicred:sd_movdia 
		WHERE folio_suc = cNUMFOLIO AND empresa='001';
		IF iexiste  = 0 THEN 
			SELECT NVL(COUNT(folio_suc),0)  
			into iexiste
			FROM bdicred:sd_movhis 
			WHERE folio_suc = cNUMFOLIO AND empresa='001';
			IF iexiste  = 0 THEN 
				SELECT NVL(COUNT(folio_suc),0)  
				into iexiste
				FROM bdicred:sd_movhis_new 
				WHERE folio_suc = cNUMFOLIO AND empresa='001';
				IF iexiste  = 0 THEN 
					SELECT NVL(COUNT(folio_suc),0)  
					into iexiste
					FROM bdicred:sd_movdiacrd 
					WHERE folio_suc = cNUMFOLIO AND empresa='001';
					IF iexiste  = 0 THEN 
						SELECT NVL(COUNT(folio_suc),0)  
						into iexiste
						FROM bdicred:sd_movhiscrd 
						WHERE folio_suc = cNUMFOLIO AND empresa='001';					
					END IF;	
				END IF;
			END IF;
		END IF;

		IF iexiste  = 0 THEN 
			LET cCodRet = "00017";
			RETURN 
			cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
		END IF;

		FOREACH
		SELECT LIMIT 1  mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fecha_mov,mm.hora_mov,mm.reversado,
				   NVL(mm.nro_tarjeta,''),mm.plaza,mm.divisa,mm.tipo_cambio,mm.rfc_comer		
			INTO 		
			cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cPlaza,cDivisa,dTipoCambio,cRfc_Comer	 
			FROM bdicred:sd_movdia  as mm
			WHERE mm.folio_suc  = cNUMFOLIO AND mm.empresa='001'			
		UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fecha_mov,mm.hora_mov,mm.reversado,
						  mm.nro_tarjeta,mm.plaza,mm.divisa,mm.tipo_cambio,mm.rfc_comer
				FROM bdicred:sd_movhis  as mm
				WHERE mm.folio_suc  = cNUMFOLIO AND mm.empresa='001'			
		UNION
				SELECT mm.folio_suc as Folio,mm.sucursal,mm.usuario,mm.fecha_mov,mm.hora_mov,mm.reversado,
						  mm.nro_tarjeta,mm.plaza,mm.divisa,mm.tipo_cambio,mm.rfc_comer
				FROM bdicred:sd_movhis_new  as mm
				WHERE mm.folio_suc  = cNUMFOLIO AND mm.empresa='001'		
		UNION 	
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fecha_mov,mm.hora_mov,mm.reversado,
						  mm.nro_tarjeta,mm.plaza,mm.divisa,mm.tipo_cambio,mm.rfc_comer
				FROM   bdicred:sd_movdiacrd    as mm
				WHERE mm.folio_suc  = cNUMFOLIO AND mm.empresa='001'
		UNION
				SELECT mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fecha_mov,mm.hora_mov,mm.reversado,
						  mm.nro_tarjeta,mm.plaza,mm.divisa,mm.tipo_cambio,mm.rfc_comer
				FROM bdicred:sd_movhiscrd as mm
				WHERE mm.folio_suc  = cNUMFOLIO AND mm.empresa='001'

                IF cNumtarjeta="0" THEN
                    LET cNumtarjeta="";
                END IF;

				RETURN 
				cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer WITH RESUME;							
		END FOREACH;
	ELIF cSISTEMACUENTA = 'INVERSION' THEN
		SELECT {+INDEX (bdinvers:sv_movdia ix161_2)} NVL(COUNT(folio_suc),0)  
		into iexiste
		FROM bdinvers:sv_movdia 
		WHERE folio_suc  = cNUMFOLIO AND empresa='001';

		IF iexiste  = 0 THEN 
			SELECT {+INDEX (bdinvers:sv_movhis idx_svfolsuc)} NVL(COUNT(folio_suc),0)  
			into iexiste
			FROM bdinvers:sv_movhis 
			WHERE folio_suc  = cNUMFOLIO AND empresa='001';
			IF iexiste  = 0 THEN
				LET cCodRet = "00017";
				RETURN 
				cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer;
			END IF;
		END IF;

		FOREACH			
			SELECT {+INDEX (bdinvers:sv_movdia ix161_2)} LIMIT 1 mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,mm.plaza,
				   mm.num_serial
			INTO 		
			cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cPlaza,sNUMSERIAL	
				FROM  bdinvers:sv_movdia mm
				WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			UNION
				SELECT {+INDEX (bdinvers:sv_movhis idx_svfolsuc)} mm.folio_suc as Folio,mm.Sucursal,mm.usuario,mm.fech_alt,mm.fech_hor,mm.cancelad,mm.plaza,
					  mm.num_serial
				  FROM bdinvers:sv_movhis AS mm
				 WHERE mm.folio_suc = cNUMFOLIO AND mm.empresa='001'
			ORDER BY mm.num_serial DESC

			RETURN 
			cCodRet,cFolio,cSucursal,cUsuario,dFecha,dHora,cCancelada,cNumtarjeta,cUsuarioAutoriza,cPlaza,cDivisa,dTipoCambio,cRfc_Comer WITH RESUME;
		END FOREACH;

	END IF;
END
END PROCEDURE
DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Obtener la información de Datos Complementarios y Adicionales (para el caso de cuentas de Crédito). ",
"El SP obtendrá la información de la Base de Datos central de Informix, enviando como parámetro el  Folio",
"FECHA : 13-02-2012",
"BD    : bdinteg",
"VER   : 2.0";

CREATE PROCEDURE "informix".sp_obtener_10dias
(
pFecha	DATE
)
RETURNING
	CHAR(6)		AS cod_ret,
	DATE		AS fecha_10dias
	
	---DECLARACIONES
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cCodRet			CHAR(6);
	DEFINE dtFecha10		DATE;
	DEFINE iContador		SMALLINT;
	
	---INICIALIZACIONES
	LET iSqlErr             = 0;
	LET iIsamErr            = 0;
	LET cCodRet             = "000000";
	LET dtFecha10			= NULL;
	LET iContador			= 0;

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, dtFecha10;
			END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	--  SET DEBUG FILE TO "/informix/PORTABILIDAD_NOMINA/sp_obtener_10dias.out";
	--  TRACE ON;
	
	WHILE dtFecha10 IS NULL
	
		LET pFecha = pFecha + 1 UNITS DAY;
		
		IF NOT EXISTS(SELECT fecha FROM bdinteg:"informix".si_feriado 
						WHERE fecha = pFecha AND empresa = '001'AND laborable = 'N') THEN
			
			IF WEEKDAY(pFecha) IN (1,2,3,4,5) THEN
				LET iContador = iContador + 1;
			END IF
			
		END IF
		
		IF iContador = 10 THEN
			LET dtFecha10 = pFecha;
			EXIT WHILE;
		END IF
		
	
	END WHILE
	
	
	RETURN cCodRet, dtFecha10;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: ',
'BD: bdinteg', 
'AUTOR: Alex Villela ',
'FECHA: septiembre 2015';

CREATE PROCEDURE "informix".sp_cnsif_consultamovtosdiarioscta3_pba(cID_USUARIOC char(8),cID_FUNCIONC CHAR(10),cNUMCUENTA CHAR(20),dPERIODOI DATE,dPERIODOF DATE, cSISTEMACUENTA CHAR(20), pUsuario CHAR(8),cSuc CHAR(4),mImporte MONEY(14,2), pNumRegistro INTEGER,pRecuperacion INTEGER)

                    returning CHAR(5)  AS Cod_Retorno,
                                DATE     AS Fecha,
                                DATETIME HOUR to FRACTION(3) AS Hora,
                                CHAR(4)  AS CveTransaccion,
                                CHAR(50) AS Desc_Transaccion,
                                CHAR(16) AS Folio,
                                DATE     AS Periodo_Inicial,
                                MONEY(14,2) AS Monto,
                                DATE     AS Periodo_Final,
                                CHAR(20) AS Sistema_Cuenta,
                                CHAR(1)  AS Naturaleza,
                                CHAR(40) AS Referencia,
                                CHAR(1)  AS Reversos,
                                CHAR(4)  AS Sucursal,
                                CHAR(20) AS CveProcedencia,
                                CHAR(50) AS Desc_Procedencia,
                                MONEY(14,2) AS Saldo,
                                CHAR(20) AS Numero_Tarjeta,
                                CHAR(1)  AS Reversados,
                          CHAR(8)  AS Usuario,
                                CHAR(23) AS Referencia23;

DEFINE iexiste                INT;
DEFINE cCodRet                CHAR(5);
DEFINE iSql_err           INT;                                  
--SISTEMA DE CUENTA 01 VARIABLES
DEFINE dFecha               DATE;
DEFINE dHora                DATETIME HOUR to FRACTION(3);
DEFINE cTransaccion          CHAR(4);
DEFINE cD_Transaccion     CHAR(50);
DEFINE mMonto               MONEY(14,2);
DEFINE cNaturaleza          CHAR(1);
DEFINE mSaldo                MONEY(14,2);
DEFINE cReferencia           CHAR(40);
DEFINE cReversos          CHAR(1);
DEFINE cReversados          CHAR(1);
DEFINE cSucursal           CHAR(4);
DEFINE cFolio                CHAR(16);
DEFINE cProcedencia          CHAR(20);
DEFINE cD_Procedencia     CHAR(50);
DEFINE dPeriodoI_1          DATE;
DEFINE dPeriodoF_1          DATE;
DEFINE sNUMSERIAL       INT8;
DEFINE sNumSecuencia    INT8;
DEFINE cUsuario         CHAR(8);
DEFINE cReferencia23    CHAR(23);
--SISTEMA DE CUENTA 06 VARIABLES
DEFINE cNumtarjeta          CHAR(20);
--VARIABLES PARA FECHAS HISTORICAS
DEFINE cconsmovhis      CHAR(10);
DEFINE cconsmovhisold   CHAR(10);
DEFINE cconsmovhisold2  CHAR(10);
DEFINE cconsmovhisold3  CHAR(10);
DEFINE cconsmovhisold4  CHAR(10);
--VARIABLES DE PAGINACION
DEFINE iCont            INT;
--VARIABLE PARA LA EMPRESA
DEFINE pEmpresa     CHAR(3);
DEFINE cCodfun          CHAR(3);
DEFINE cCodref          INTEGER;
DEFINE iExisteCta       INT;
DEFINE iKiosko			INT;
DEFINE iAbierto			INT;
--inicializando variables
LET  iexiste = 0;
LET cCodRet = "00000";
LET iSql_err = 0 ;    
LET dFecha               = "";
LET dHora                = "";
LET cTransaccion     = "";
LET cD_Transaccion     = "";
LET mMonto               = 0;
LET cNaturaleza          = "";
LET mSaldo                = 0;
LET cReferencia          = "";
LET cReversos          = "";
LET cReversados          = "";
LET cSucursal           = "";
LET cFolio                = "";
LET cProcedencia     = "";
LET cD_Procedencia     = "";
LET dPeriodoI_1          = "";
LET dPeriodoF_1          = "";
LET sNUMSERIAL      =  0;
LET sNumSecuencia     =  0;
LET cUsuario        = "";
LET cReferencia23   = "";
--SISTEMA DE CUENTA 06 VARIABLES
LET cNumtarjeta     = "";
--VARIABLES PARA FECHAS HISTORICAS
LET cconsmovhis     = '';
LET cconsmovhisold  = '';
LET cconsmovhisold2 = '';
LET cconsmovhisold3 = '';
LET cconsmovhisold4 = '';
--VARIABLES DE PAGINACION
LET iCont       = 0;
LET pEmpresa   = '001';
LET cCodfun               ='';
LET cCodref               =0;
LET  iExisteCta = 0;
LET iKiosko               =0;
LET iAbierto              =0;

BEGIN
     ON EXCEPTION SET iSql_err
          IF iSql_err <> 0 THEN
               LET cCodRet = iSql_err;
               RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
               cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
          END IF;
     END EXCEPTION;
                

	SET ISOLATION TO COMMITTED READ LAST COMMITTED;

    --SET DEBUG FILE TO "/informix/CHVN/sp_cnsif_consultamovtosdiarioscta3.out";
    --TRACE ON;
              
     IF cID_USUARIOC = ''      OR
        cID_FUNCIONC = ''      OR
        cNUMCUENTA  = ''     OR
        dPERIODOI   IS NULL OR
        dPERIODOF      IS NULL     OR
        cSISTEMACUENTA = '' THEN
        LET cCodRet = "00036";
        RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
        cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
     END IF;

    IF pNumRegistro<0 THEN
        LET cCodRet='00098';
          RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
          cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;                        
    ELSE
        IF pRecuperacion<=0 THEN
            LET cCodRet='00098';
            RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
            cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
        END IF;
    END IF; 
     IF cSISTEMACUENTA <> 'CAPTACION' AND cSISTEMACUENTA <> 'CREDITO'  AND cSISTEMACUENTA <> 'INVERSIONES' THEN
          LET cCodRet = "00037";
          RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
          cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
     END IF;

     --VALIDACION
	IF cSISTEMACUENTA = 'CAPTACION' THEN
		EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'01','1')
		INTO cCodRet;
	END IF;

	IF cSISTEMACUENTA = 'CREDITO' THEN
		EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'06','1')
		INTO cCodRet;
	END IF;

	IF cSISTEMACUENTA = 'INVERSIONES' THEN
		EXECUTE PROCEDURE sp_cnsif_permisosejecutivo(cID_USUARIOC,cID_FUNCIONC, cNUMCUENTA,'03','1')
		INTO cCodRet;
	END IF;

	IF (cCodRet != '00000')  THEN
		RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
			  cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
	END IF;
     -- TERMINA VALIDACION
	
	IF cSISTEMACUENTA = 'CAPTACION' THEN
	IF pNumRegistro = 0 THEN
		DELETE FROM "informix".si_tempomovs WHERE ejecutivosif = cID_USUARIOC AND no_cuenta = cNUMCUENTA;
        SET ISOLATION TO DIRTY READ;
		SELECT valor
		INTO cconsmovhis
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'fechcon_movhis';

		SELECT valor
		INTO cconsmovhisold
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'FechIniCon_movhis_ol';

		SELECT valor
		INTO cconsmovhisold2
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'FechaIniMovhisOld2';

		SELECT valor
		INTO cconsmovhisold3
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'vfechconmovhisold3';
		
		SELECT valor
		INTO cconsmovhisold4
		FROM bdicheq:"informix".sc_param
		WHERE empresa = pEmpresa
		AND codparam = 'FechaIniMovhisOld4';
		
		LET iAbierto = 1;
		IF dPERIODOF = TODAY THEN
			SET ISOLATION TO DIRTY READ;
			FOREACH WITH HOLD
			SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
			MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
			INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
			cNumtarjeta,cUsuario,cReferencia23
			FROM bdicheq:"informix".sc_movdia MO
			LEFT JOIN bdinteg:si_transacc TR
			ON TR.empresa = '001'
			AND TR.numero = MO.transacc
			AND TR.sistema = '01'
			WHERE MO.fech_alt = dPERIODOF AND MO.empresa='001' AND MO.cuenta = cNUMCUENTA
			AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
			AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
			AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
						
			LET iCont=iCont+1;
			
			INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
				sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
			VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
				mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
			IF iCont >= 1000 THEN
				LET iCont = 0;
				COMMIT WORK;
				BEGIN WORK;
			END IF;
			END FOREACH;
		END IF;

		IF (dPERIODOI < TODAY AND dPERIODOF >= cconsmovhis) THEN
			SET ISOLATION TO DIRTY READ;
			FOREACH WITH HOLD
			SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
			MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
			INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
			cNumtarjeta,cUsuario,cReferencia23
			FROM bdicheq:"informix".sc_movhis MO
			LEFT JOIN bdinteg:si_transacc TR
			ON TR.empresa = '001'
			AND TR.numero = MO.transacc
			AND TR.sistema = '01'
			WHERE MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF AND MO.empresa='001' AND MO.cuenta  = cNUMCUENTA
			AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
			AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
			AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
						
			LET iCont=iCont+1;
			
			INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
				sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
			VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
				mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
			IF iCont >= 1000 THEN
				LET iCont = 0;
				COMMIT WORK;
				BEGIN WORK;
			END IF;
			END FOREACH;
		END IF;
		
		IF (dPERIODOI < cconsmovhis AND dPERIODOF >= cconsmovhisold) THEN
			SET ISOLATION TO DIRTY READ;
			FOREACH WITH HOLD
			SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
			MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
			INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
			cNumtarjeta,cUsuario,cReferencia23
			FROM bdicheq:"informix".sc_movhis_old MO
			LEFT JOIN bdinteg:si_transacc TR
			ON TR.empresa = '001'
			AND TR.numero = MO.transacc
			AND TR.sistema = '01'
			WHERE MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF AND MO.empresa = '001' AND MO.cuenta  = cNUMCUENTA
			AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
			AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
			AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
						
			LET iCont=iCont+1;
			
			INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
				sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
			VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
				mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
			IF iCont >= 1000 THEN
				LET iCont = 0;
				COMMIT WORK;
				BEGIN WORK;
			END IF;
			END FOREACH;
		END IF;
		
		IF (dPERIODOI < cconsmovhisold AND dPERIODOF >= cconsmovhisold2) THEN
			SET ISOLATION TO DIRTY READ;
			FOREACH WITH HOLD
			SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
			MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
			INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
			cNumtarjeta,cUsuario,cReferencia23
			FROM bdicheq:"informix".sc_movhis_old2 MO
			LEFT JOIN bdinteg:si_transacc TR
			ON TR.empresa = '001'
			AND TR.numero = MO.transacc
			AND TR.sistema = '01'
			WHERE MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF AND MO.empresa = '001' AND MO.cuenta  = cNUMCUENTA
			AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
			AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
			AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
			
			LET iCont=iCont+1;
			
			INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
				sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
			VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
				mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
			IF iCont >= 1000 THEN
				LET iCont = 0;
				COMMIT WORK;
				BEGIN WORK;
			END IF;
			END FOREACH;
		END IF;

		SET ISOLATION TO DIRTY READ;
			SELECT {+INDEX (bdicheq:sc_maechq idx_sc_maechq)} NVL(COUNT(cuenta),0) 
			INTO iExisteCta
			FROM bdicheq:sc_maechq 
			WHERE cuenta  = cNUMCUENTA
			AND producto IN ('1200', '9901', '1600', '2200', '2600');
		
		IF iExisteCta = 0 THEN
			IF (dPERIODOI < cconsmovhisold2 AND dPERIODOF >= cconsmovhisold3) THEN
				SET ISOLATION TO DIRTY READ;
				FOREACH WITH HOLD
				SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
				MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
				INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
				cNumtarjeta,cUsuario,cReferencia23
				FROM bdicheq:"informix".sc_movhis_old3 MO
				LEFT JOIN bdinteg:si_transacc TR
				ON TR.empresa = '001'
				AND TR.numero = MO.transacc
				AND TR.sistema = '01'
				WHERE MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF AND MO.empresa='001' AND MO.cuenta  = cNUMCUENTA
				AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
				
				LET iCont=iCont+1;
				
				INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
					sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
				VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
					mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
				IF iCont >= 1000 THEN
					LET iCont = 0;
					COMMIT WORK;
					BEGIN WORK;
				END IF;
				END FOREACH;
			END IF;
			IF (dPERIODOI < cconsmovhisold3 AND dPERIODOF >= cconsmovhisold4) THEN
				SET ISOLATION TO DIRTY READ;
				FOREACH WITH HOLD
				SELECT MO.fech_alt,MO.fech_hor,MO.transacc,TR.descripcion,MO.monto_tot,TR.naturaleza,MO.sdo_cuenta,MO.referencia,MO.cancelad,
				MO.sucursal,MO.folio_suc,MO.num_tarjeta,MO.usuario,MO.referencia_23
				INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
				cNumtarjeta,cUsuario,cReferencia23
				FROM bdicheq:"informix".sc_movhis_old4 MO
				LEFT JOIN bdinteg:si_transacc TR
				ON TR.empresa = '001'
				AND TR.numero = MO.transacc
				AND TR.sistema = '01'
				WHERE MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF AND MO.empresa='001' AND MO.cuenta  = cNUMCUENTA
				AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END
				
				LET iCont=iCont+1;
				
				INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
					sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
				VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
					mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
				IF iCont >= 1000 THEN
					LET iCont = 0;
					COMMIT WORK;
					BEGIN WORK;
				END IF;
				END FOREACH;
			END IF;
		END IF;
		
		IF TRIM(SUBSTRING(cNUMCUENTA FROM 1 FOR 1)) = '8' THEN
			SET ISOLATION TO DIRTY READ;
			FOREACH WITH HOLD
			SELECT MO.fecha_alt as fech_alt,extend(MO.fech_hor_fin,HOUR to FRACTION(3)),MO.transacc,TR.descripcion,MO.monto,DECODE(MO.tpo_mov,"D","A","C","C"),
			MO.sdo_cuenta_origen,MO.referencia,'','',MO.secuencia,'','TRANSFER',''
			INTO dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
			cNumtarjeta,cUsuario,cReferencia23
			FROM bditransfer:tf_success_transac  MO
			LEFT JOIN bditransfer:tf_cat_transac_mps TR
			ON MO.transacc = TR.transac
			WHERE MO.cuenta = cNUMCUENTA
			AND MO.fecha_alt BETWEEN dPERIODOI AND dPERIODOF
			AND MO.monto = CASE WHEN mImporte = 0 THEN MO.monto ELSE mImporte END
			AND MO.fecha_alt < to_date('20/03/2015','%d/%m/%Y')
			
			LET iCont=iCont+1;
			
			INSERT INTO "informix".si_tempomovs (codret, ejecutivosif, no_cuenta, fech_alt, fech_hor, transacc, descripcion, monto_tot, naturaleza, 
				sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_serial, num_tarjeta, usuario, referencia_23) 
			VALUES (cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,
				mSaldo,cReferencia,cReversos,cSucursal,cFolio,sNUMSERIAL,cNumtarjeta,cUsuario,cReferencia23);
			IF iCont >= 1000 THEN
					LET iCont = 0;
					COMMIT WORK;
					BEGIN WORK;
			END IF;
			END FOREACH;
		END IF;
		
		IF iAbierto = 1 THEN
			LET iAbierto = 0;
			COMMIT WORK;
			BEGIN WORK;
		END IF;
		
		LET iCont = 0;
		SET ISOLATION TO DIRTY READ;
		FOREACH
			SELECT SKIP pNumRegistro FIRST pRecuperacion codret, ejecutivosif, no_cuenta, fech_alt, 
			fech_hor, transacc, descripcion, monto_tot, naturaleza, sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_tarjeta, usuario, 
			referencia_23
			INTO cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
				cNumtarjeta,cUsuario,cReferencia23
			FROM "informix".si_tempomovs
			WHERE ejecutivosif = cID_USUARIOC AND no_cuenta = cNUMCUENTA
			ORDER BY fech_alt DESC,fech_hor DESC
			
			IF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE transacc=cTransaccion AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE sucursal=cSucursal AND transacc='')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE sucursal=cSucursal AND transacc='';
			ELSE
				LET cProcedencia="";
				LET cD_Procedencia="";
			END IF;
			
			
			LET iCont=iCont+1;
			
			RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
				  cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23 WITH RESUME;
		END FOREACH;
		IF iCont = 0 THEN
			LET cCodRet = '1001'; 
			RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
				  cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
		END IF;
	ELSE
		FOREACH
			SELECT {+INDEX (bdinteg:"informix".si_tempomovs idx_tempomovs)} SKIP pNumRegistro FIRST pRecuperacion codret, ejecutivosif, no_cuenta, fech_alt, 
			fech_hor, transacc, descripcion, monto_tot, naturaleza, sdo_cuenta, referencia, cancelad, sucursal, folio_suc, num_tarjeta, usuario, 
			referencia_23
			INTO cCodRet,cID_USUARIOC,cNUMCUENTA,dFecha,dHora,cTransaccion,cD_Transaccion,mMonto,cNaturaleza,mSaldo,cReferencia,cReversos,cSucursal,cFolio,
				cNumtarjeta,cUsuario,cReferencia23
			FROM "informix".si_tempomovs
			WHERE ejecutivosif = cID_USUARIOC AND no_cuenta = cNUMCUENTA
			ORDER BY fech_alt DESC,fech_hor DESC
			
			IF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE transacc=cTransaccion AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE sucursal=cSucursal AND transacc='')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia 
				WHERE sucursal=cSucursal AND transacc='';
			ELSE
				LET cProcedencia="";
				LET cD_Procedencia="";
			END IF;
			
			
			LET iCont=iCont+1;
			
			RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
				  cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23 WITH resume;
		END FOREACH;
		IF iCont = 0 THEN
			LET cCodRet = '1001'; 
			RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPERIODOI,mMonto,dPERIODOF,cSISTEMACUENTA,cNaturaleza,
				cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
		END IF
	END IF;
		
	ELIF cSISTEMACUENTA = 'CREDITO' THEN
		SET ISOLATION TO DIRTY READ;
		SELECT NVL(COUNT(num_credito),0) 
		INTO iExisteCta
		FROM bdicred:sd_maecred
		WHERE empresa = '001' AND num_credito = cNUMCUENTA;		

		IF iExisteCta > 0 THEN
			FOREACH
				SELECT SKIP pNumRegistro FIRST pRecuperacion {+INDEX (bdicred:sd_movdia mov4)} MO.codigo_fun,MO.codigo_ref,MO.fecha_mov,MO.hora_mov,MO.nro_tarjeta,MO.folio_suc,  
				MO.transacc_suc,TR.descripcion,MO.referencia,
				MO.monto,TR.sentido,MO.reversado,MO.sucursal,dPERIODOI,dPERIODOF,MO.secuencia,MO.usuario,MO.referencia23
				INTO          
				cCodfun,cCodref,dFecha,dHora,cNumtarjeta,cFolio,cTransaccion,cD_Transaccion,cReferencia,mMonto,cNaturaleza,cReversos,cSucursal,
				dPeriodoI_1,dPeriodoF_1,sNUMSERIAL,cUsuario,cReferencia23
				FROM bdicred:sd_movdia MO
				LEFT JOIN bdicred:sd_transfun TR
				ON TR.empresa = '001' AND TR.codigo_fun = MO.codigo_fun AND TR.codigo_ref = MO.codigo_ref
				WHERE MO.empresa='001' AND MO.num_credito = cNUMCUENTA AND MO.fecha_mov BETWEEN dPERIODOI AND dPERIODOF
				AND MO.monto = CASE WHEN mImporte = 0 THEN MO.monto ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END     
			UNION
				SELECT {+INDEX (bdicred:sd_movhis inx_movhis4)} MO.codigo_fun,MO.codigo_ref,MO.fecha_mov,MO.hora_mov,MO.nro_tarjeta,MO.folio_suc,  
				MO.transacc_suc,TR.descripcion,MO.referencia,
				MO.monto,TR.sentido,MO.reversado,MO.sucursal,dPERIODOI,dPERIODOF,MO.secuencia,MO.usuario,MO.referencia23
				FROM bdicred:sd_movhis  MO
				LEFT JOIN bdicred:sd_transfun TR
				ON TR.empresa = '001' AND TR.codigo_fun = MO.codigo_fun AND TR.codigo_ref = MO.codigo_ref
				WHERE MO.empresa='001' AND MO.num_credito = cNUMCUENTA AND MO.fecha_mov BETWEEN dPERIODOI AND dPERIODOF
				AND MO.monto = CASE WHEN mImporte = 0 THEN MO.monto ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END                    
			ORDER BY MO.secuencia DESC

			IF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE sucursal=cSucursal AND transacc='')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE sucursal=cSucursal AND transacc='';
			ELSE
				LET cProcedencia="";
				LET cD_Procedencia="";
			END IF;
			  
			LET iCont=iCont+1;

			IF cCodfun ='001' AND cCodref in (1,2,3) THEN
				IF iCont>0 THEN
					 LET iCont=iCont - 1;
				END IF;
			ELIF cCodfun ='002' AND cCodref =1 THEN
				IF iCont>0 THEN
					 LET iCont=iCont - 1;
				END IF;
			ELSE
				RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
				cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23 WITH resume;
			END IF;

			END FOREACH;
		ELSE
			FOREACH
				SELECT SKIP pNumRegistro FIRST pRecuperacion MO.codigo_fun,MO.codigo_ref,MO.fecha_mov,MO.hora_mov,MO.nro_tarjeta,MO.folio_suc,  
				MO.transacc_suc,TR.descripcion,MO.referencia,
				MO.monto,TR.sentido,MO.reversado,MO.sucursal,dPERIODOI,dPERIODOF,MO.secuencia,MO.usuario,MO.referencia23
				INTO          
				cCodfun,cCodref,dFecha,dHora,cNumtarjeta,cFolio,cTransaccion,cD_Transaccion,cReferencia,mMonto,cNaturaleza,cReversos,cSucursal,
				dPeriodoI_1,dPeriodoF_1,sNUMSERIAL,cUsuario,cReferencia23
				FROM bdicred:sd_movdiacrd  MO
				LEFT JOIN bdicred:sd_transfun TR
				ON TR.empresa = '001' AND TR.codigo_fun = MO.codigo_fun AND TR.codigo_ref = MO.codigo_ref
				WHERE MO.empresa='001' AND MO.num_credito = cNUMCUENTA AND MO.fecha_mov BETWEEN dPERIODOI AND dPERIODOF
				AND MO.monto = CASE WHEN mImporte = 0 THEN MO.monto ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END     
			UNION
				SELECT MO.codigo_fun,MO.codigo_ref,MO.fecha_mov,MO.hora_mov,MO.nro_tarjeta,MO.folio_suc,  
				MO.transacc_suc,TR.descripcion,MO.referencia,
				MO.monto,TR.sentido,MO.reversado,MO.sucursal,dPERIODOI,dPERIODOF,MO.secuencia,MO.usuario,MO.referencia23
				FROM bdicred:sd_movhiscrd  MO
				LEFT JOIN bdicred:sd_transfun TR
				ON TR.empresa = '001' AND TR.codigo_fun = MO.codigo_fun AND TR.codigo_ref = MO.codigo_ref
				WHERE MO.empresa='001' AND MO.num_credito = cNUMCUENTA AND MO.fecha_mov BETWEEN dPERIODOI AND dPERIODOF
				AND MO.monto = CASE WHEN mImporte = 0 THEN MO.monto ELSE mImporte END
				AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
				AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END     
			ORDER BY MO.secuencia DESC

			IF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE transacc=cTransaccion AND sucursal=cSucursal AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE transacc=cTransaccion AND transacc<>'';
			ELIF (SELECT NVL(COUNT(*),0) FROM si_procedencia WHERE sucursal=cSucursal AND transacc='')>0 THEN
				SELECT LIMIT 1 procedencia,descripcion INTO cProcedencia,cD_Procedencia FROM si_procedencia WHERE sucursal=cSucursal AND transacc='';
			ELSE
				LET cProcedencia="";
				LET cD_Procedencia="";
			END IF;
			  
			LET iCont=iCont+1;

			IF cCodfun ='001' AND cCodref in (1,2,3) THEN
				IF iCont>0 THEN
					 LET iCont=iCont - 1;
				END IF;
			ELIF cCodfun ='002' AND cCodref =1 THEN
				IF iCont>0 THEN
					 LET iCont=iCont - 1;
				END IF;
			ELSE
				RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
				cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23 WITH resume;
			END IF;

			END FOREACH;
		END IF;
						
		IF iCont = 0 AND pNumRegistro=0 THEN
		   LET cCodRet = '00039';
				RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
						cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
		ELIF iCont = 0 THEN
		   LET cCodRet = '1001';
				RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
						cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
	END IF
	ELIF cSISTEMACUENTA = 'INVERSIONES' THEN
	 SET ISOLATION TO DIRTY READ;
	  FOREACH
		   SELECT SKIP pNumRegistro FIRST pRecuperacion     
		   MO.fech_alt,MO.fech_hor,MO.folio_suc,MO.transacc,TR.descripcion,MO.monto_tot,MO.cancelad,dPERIODOI,dPERIODOF,MO.secuencia,MO.sucursal,MO.usuario,MO.num_serial
		   INTO
		   dFecha,dHora,cFolio,cTransaccion,cD_Transaccion,mMonto,cReversados,dPeriodoI_1,dPeriodoF_1,sNumSecuencia,cSucursal,cUsuario,sNUMSERIAL
		   FROM bdinvers:sv_maeinv MC
		   LEFT JOIN bdinvers:sv_movdia MO
		   ON MC.cuenta = MO.cuenta
		   LEFT JOIN bdinteg:si_transacc TR
		   ON MO.transacc = TR.numero 
		   WHERE MO.cuenta = cNUMCUENTA
		   AND MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF
		AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
		AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
		AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END     
		   UNION
		   SELECT MO.fech_alt,MO.fech_hor,MO.folio_suc,MO.transacc,TR.descripcion,MO.monto_tot,MO.cancelad,dPERIODOI,dPERIODOF,MO.secuencia,MO.sucursal,MO.usuario,MO.num_serial
		   FROM bdinvers:sv_maeinv MC
		   LEFT JOIN bdinvers:sv_movhis MO
		   ON MC.cuenta = MO.cuenta
		   LEFT JOIN bdinteg:si_transacc TR
		   ON MO.transacc = TR.numero 
		   WHERE MO.cuenta = cNUMCUENTA
		   AND MO.fech_alt BETWEEN dPERIODOI AND dPERIODOF
		AND MO.monto_tot = CASE WHEN mImporte = 0 THEN MO.monto_tot ELSE mImporte END
		AND MO.sucursal = CASE WHEN cSuc = "" THEN MO.sucursal ELSE cSuc END
		AND MO.usuario = CASE WHEN pUsuario = "" THEN MO.usuario ELSE pUsuario END     
		ORDER BY MO.num_serial DESC

		LET iCont=iCont+1;    
		RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
		cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23 WITH resume;
			   
	  END FOREACH;

	  IF iCont = 0 THEN
	  LET cCodRet = '1001';
		   RETURN cCodRet,dFecha,dHora,cTransaccion,cD_Transaccion,cFolio,dPeriodoI_1,mMonto,dPeriodoF_1,cSISTEMACUENTA,cNaturaleza,
				   cReferencia,cReversos,cSucursal,cProcedencia,cD_Procedencia,mSaldo,cNumtarjeta,cReversados,cUsuario,cReferencia23;
	  END IF
	END IF
END

END PROCEDURE

DOCUMENT
"AutOR : ARTURO CERVANTES PEÑA",
"FUNCIONAMIENTO:Este sp realizara la busqueda por tipo de cuenta, dependiendo de tipo de cuenta regresara los datos correspondientes, para captacion o cuenta de cheques, para cuentas tipo credito 06 que seran de credito y las cuentas tipo 03 que son de  tipo inversiones",
"FECHA : 09-02-2012",
"ACTUALIZO: Victor Hugo Sánchez M.",
"MODIFICACION: Se agregaron los parametros empleado,sucursal e importe para filtrar movimientos",
"FECHA: 04/07/2012",
"ACTUALIZO: Oscar Flores Conde (M-Finis Soluciones y Servicios Financieros)",
"MODIFICACION: Se agregaron el parametro de entrada para filtrar los movimientos reversados, se agrega en los parametros de salida la referencia a 23 posiciones",
"FECHA: 02/12/2013",
"BD    : bdinteg",
"VER   : 3.0";

CREATE PROCEDURE "informix".sp_altamasivaempnet_busca_pba()
RETURNING CHAR(5);
    
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    
    DEFINE vcCodEmpresa     CHAR(3);
    DEFINE vcNombreArchivo  CHAR(30);
    DEFINE vcNumCte         CHAR(9);
    DEFINE vcCodRetAlta     CHAR(5);
    
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET vcDescErr   = '';
    LET vcCodRet    = '000';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    
    LET vcCodEmpresa    = '';
    LET vcNombreArchivo = '';
    LET vcNumCte        = '';
    LET vcCodRetAlta    = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_busca.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_busca.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // PROCESA LOS ARCHIVOS QUE ESTEN PENDIENTES
    FOREACH WITH HOLD 
        SELECT alta.cod_empresa, alta.nombre_archivo, emp.numcte
          INTO vcCodEmpresa, vcNombreArchivo, vcNumCte
          FROM bdinteg:si_altamasivaempnet_ctrl alta,
               bdicheq:sc_nominaempresas emp
         WHERE alta.cod_empresa = emp.codigo
           AND alta.status = '0'
           
        CALL sp_altamasivaempnet_procesa( vcCodEmpresa, vcNumCte, vcNombreArchivo )
        RETURNING vcCodRetAlta;
    END FOREACH;
    
    RETURN vcCodRet;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_altamasivaempnet_procesa_pba( pidempresa CHAR(3), pnumcte CHAR(9), pnombrearchivo CHAR(30) )
RETURNING CHAR(5); 
       
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE vcCodRet4    CHAR(5);
    DEFINE vcCodRet5    CHAR(5);
    DEFINE vcFolio      CHAR(16);
    DEFINE vcMensaje    CHAR(50);
    DEFINE vusuario     CHAR(8);
    DEFINE vcNumEmp     CHAR(3);
    DEFINE viExisteEmp  SMALLINT;
    DEFINE viExisteCte  SMALLINT;
    
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET vcDescErr   = '';
    LET vcCodRet    = '';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    LET vcCodRet4   = '';
    LET vcCodRet5   = '';
    LET vcFolio     = '';
    LET vcMensaje   = '';
    LET vusuario    = USER;
    LET vcNumEmp    = '';
    LET viExisteEmp = 0;
    LET viExisteCte = 0;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_procesa.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_procesa.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
    
    -- // VALIDA EL NUMERO DE EMPRESA
    LET vcNumEmp  = SUBSTR(pNombreArchivo, 2, 3);
        
    IF pidempresa <> vcNumEmp THEN
        LET pidempresa = vcNumEmp;
    END IF;
    
    SELECT COUNT(*)
      INTO viExisteEmp
      FROM bdicheq:sc_nominaempresas 
     WHERE codigo = pidempresa;
     
    IF viExisteEmp = 0 THEN
        LET vcCodRet = '188';
        RETURN vcCodRet;
    END IF;
    
    -- // VALIDA QUE EL CLIENTE SEA PERSONA MORAL
    SELECT COUNT(cte.numcte)
      INTO viExisteCte
      FROM bdinteg:si_cliente cte
     INNER JOIN bdinteg:si_tipper tpo ON cte.tpo_persona = tpo.tpo_persona
     WHERE cte.empresa = '001'
       AND cte.numcte = pnumcte
       AND tpo.es_fisica = "N";
    
    IF viExisteCte = 0 THEN
        LET vcCodRet = '104';
        RETURN vcCodRet;
    END IF;
    
    CALL "informix".sp_altamasivaempnet_carga(pnombrearchivo)
    RETURNING vcCodRet4;
    
    IF vcCodRet4 = '000' THEN        
        CALL "informix".sp_altamasivaempnet_registra(pidempresa, pnumcte, vusuario, pnombrearchivo) 
        RETURNING vcCodRet5, vcMensaje;

        IF vcCodRet5 = '00000' THEN
            LET vcCodRet = '000';
        ELSE
            LET vcCodRet = vcCodRet5;
        END IF
    ELSE
        LET vcCodRet = vcCodRet4;
    END IF;

    RETURN vcCodRet;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_altamasivaempnet_carga_pba( pNombreArchivo CHAR(30) )
RETURNING CHAR(5);
       
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
    DEFINE vRuta            CHAR(50);
    DEFINE cSQL             CHAR(300);
    DEFINE vdFechaHoy       DATE;
    DEFINE vContador1       INTEGER;
    DEFINE vContador2       INTEGER;
    DEFINE vComienza        SMALLINT;
    DEFINE vTrxAbierta      SMALLINT;
    DEFINE vcNumEmp         CHAR(3);
    DEFINE vcExistArch      SMALLINT;
    DEFINE vcve_cte         CHAR(15);
    DEFINE vnombre1         CHAR(30);
    DEFINE vnombre2         CHAR(30);
    DEFINE vape_pat         CHAR(30);
    DEFINE vape_mat         CHAR(30);
    DEFINE vfecha_nac       CHAR(8);
    DEFINE vrfc             CHAR(15);
    DEFINE vcurp            CHAR(30);
    DEFINE vgenero          CHAR(1);
    DEFINE vtipo_id         CHAR(1);
    DEFINE vnum_id          CHAR(30);
    DEFINE vcalle           CHAR(30);
    DEFINE vno_ext          INTEGER;
    DEFINE vno_int          INTEGER;
    DEFINE vcolonia         CHAR(30);
    DEFINE vdel_mun         CHAR(30);
    DEFINE vciudad          CHAR(30);
    DEFINE vestado          CHAR(30);
    DEFINE vcod_pos         CHAR(10);
    DEFINE vpais            CHAR(4);
    DEFINE vocupacion       INTEGER;
    
    DEFINE vcValNulos       CHAR(1);
    DEFINE vcValNumeros     CHAR(1);
    DEFINE vcValFechas      CHAR(1);
    DEFINE vcValLetras      CHAR(1);
    DEFINE vcodretint01     SMALLINT;
    DEFINE vcodretint02     SMALLINT;
    DEFINE vcodretint03     SMALLINT;
    DEFINE vcodretint04     SMALLINT;
    DEFINE vcodretint05     SMALLINT;
    DEFINE vcodretint06     SMALLINT;
    DEFINE vcodretint07     SMALLINT;
    DEFINE vcodretint08     SMALLINT;
    DEFINE vcodretint09     SMALLINT;
    DEFINE vcodretint10     SMALLINT;
    DEFINE vcodretint11     SMALLINT;
    DEFINE vcodretint12     SMALLINT;
    DEFINE vcodretint13     SMALLINT;
    DEFINE viExisteCP       SMALLINT;
    
    DEFINE vArchivoCom          CHAR(15);  
    DEFINE vcNombreArchivoVal   CHAR(30);
    
    LET Sql_Err	    = 0;
    LET Isam_Err    = 0;
    LET Desc_Err    = '';
    LET vCodRet1    = '000';
    LET vCodRet2    = '';
    LET vCodRet3    = '';
    LET vRuta       = '';
    LET cSQL        = '';
    LET vdFechaHoy  = '';
    LET vContador1  = 0;
    LET vContador2  = 0;
    LET vComienza   = -1;
    LET vTrxAbierta = 0;
    LET vcNumEmp    = '';
    LET vcExistArch = 0;
    LET vcve_cte    = '';
    LET vnombre1    = '';
    LET vnombre2    = '';
    LET vape_pat    = '';
    LET vape_mat    = '';
    LET vfecha_nac  = '';
    LET vrfc        = '';
    LET vcurp       = '';
    LET vgenero     = '';
    LET vtipo_id    = '';
    LET vnum_id     = '';
    LET vcalle      = '';
    LET vno_ext     = 0;
    LET vno_int     = 0;
    LET vcolonia    = '';
    LET vdel_mun    = '';
    LET vciudad     = '';
    LET vestado     = '';
    LET vcod_pos    = '';
    LET vpais       = '';
    LET vocupacion  = 0;
    
    LET vcValNulos    = '0';
    LET vcValNumeros  = '0';
    LET vcValFechas   = '0';
    LET vcValLetras   = '0';
    LET vcodretint01  = -1;
    LET vcodretint02  = -1;
    LET vcodretint03  = -1;
    LET vcodretint04  = -1;
    LET vcodretint05  = -1;
    LET vcodretint06  = -1;
    LET vcodretint07  = -1;
    LET vcodretint08  = -1;
    LET vcodretint09  = -1;
    LET vcodretint10  = -1;
    LET vcodretint11  = -1;
    LET vcodretint12  = -1;
    LET vcodretint13  = -1;
    LET viExisteCP    = 0;
    
    LET vArchivoCom = 'quitarctrlm.cmd';
    LET vcNombreArchivoVal = TRIM(pNombreArchivo)||'.val'; 
    
    BEGIN
    
    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_carga.err";
        TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_carga.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ; 
    SET LOCK MODE TO WAIT 5; 
    
    IF EXISTS(SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_altamasivaempnet_tmp') THEN
        DROP TABLE bdinteg:"informix".si_altamasivaempnet_tmp;
    END IF;  
    
    CREATE TABLE bdinteg:"informix".si_altamasivaempnet_tmp  
      ( 
        cve_cte     char(15)    not null,
        nombre1     char(30)    not null,
        nombre2     char(30)            ,
        ape_pat     char(30)    not null,
        ape_mat     char(30)    not null,
        fecha_nac   char(8)     not null,
        rfc         char(15)    not null,
        curp        char(30)            ,
        genero      char(1)     not null,
        tipo_id     char(1)     not null,
        num_id      char(30)    not null,
        calle       char(30)    not null,
        no_ext      integer     not null,
        no_int      integer             ,
        colonia     char(30)    not null,
        del_mun     char(30)    not null,
        ciudad      char(30)    not null,
        estado      char(30)    not null,
        cod_pos     char(10)    not null,
        pais        char(4)     not null,
        ocupacion   integer
      )
    EXTENT SIZE 128 NEXT SIZE 64 LOCK MODE ROW;
    
    SELECT valor
      INTO vRuta
      FROM bdinteg:si_param
     WHERE empresa = '001'
       AND cod_param = 50;
    
    LET cSQL = '';
    LET cSQL = "sed -f "||TRIM(vRuta)||TRIM(vArchivoCom)||" "||TRIM(vRuta)||TRIM(pNombreArchivo)||" > "||TRIM(vRuta)||TRIM(vcNombreArchivoVal);
    SYSTEM cSQL;
    
    LET cSQL = '';
    LET cSQL = 'echo "LOAD FROM '||TRIM(vRuta)||TRIM(vcNombreArchivoVal)||' INSERT INTO si_altamasivaempnet_tmp" > '||TRIM(vRuta)||'altmasempnet.sql';
    SYSTEM cSQL;
    
    LET cSQL = '';
    LET cSQL = '/ifxsif01/bin/dbaccess bdinteg '||TRIM(vRuta)||'altmasempnet.sql';
    SYSTEM cSQL;
    
    CREATE INDEX "informix".idx_tmp_altmas ON "informix".si_altamasivaempnet_tmp(cve_cte) ONLINE; 

    ---UPDATE STATISTICS HIGH FOR TABLE si_altamasivaempnet_tmp;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';
     
    SELECT COUNT(*)
      INTO vContador1
      FROM bdinteg:si_altamasivaempnet_tmp;
      
    IF vContador1 <= 0 THEN
        LET vCodRet1 = '180';
        RETURN vCodRet1;
    END IF;
    
    LET vcNumEmp = SUBSTR(pNombreArchivo, 2, 3);
    
    FOREACH WITH HOLD
        SELECT TRIM(cve_cte), TRIM(nombre1), TRIM(nombre2), TRIM(ape_pat), TRIM(ape_mat), fecha_nac, TRIM(rfc), TRIM(curp), TRIM(genero), tipo_id, 
               TRIM(num_id), TRIM(calle), no_ext, no_int, TRIM(colonia), TRIM(del_mun), TRIM(ciudad), TRIM(estado), TRIM(cod_pos), TRIM(pais), ocupacion 
          INTO vcve_cte, vnombre1, vnombre2, vape_pat, vape_mat, vfecha_nac, vrfc, vcurp, vgenero, vtipo_id,
               vnum_id, vcalle, vno_ext, vno_int, vcolonia, vdel_mun, vciudad, vestado, vcod_pos, vpais, vocupacion 
          FROM bdinteg:si_altamasivaempnet_tmp
          
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
        END IF; 
        
        BEGIN WORK;
        LET vTrxAbierta = 1;
          
        IF ( vno_ext    is null ) OR 
           ( vcve_cte   is null   OR  vcve_cte = ''   ) OR 
           ( vnombre1   is null   OR  vnombre1 = ''   ) OR 
           ( vape_pat   is null   OR  vape_pat = ''   ) OR 
           ( vape_mat   is null   OR  vape_mat = ''   ) OR 
           ( vfecha_nac is null   OR  vfecha_nac = '' ) OR 
           ( vrfc       is null   OR  vrfc = ''       ) OR 
           ( vgenero    is null   OR  vgenero = ''    ) OR 
           ( vtipo_id   is null   OR  vtipo_id = ''   ) OR
           ( vnum_id    is null   OR  vnum_id = ''    ) OR 
           ( vcalle     is null   OR  vcalle = ''     ) OR 
           ( vcolonia   is null   OR  vcolonia = ''   ) OR 
           ( vdel_mun   is null   OR  vdel_mun = ''   ) OR 
           ( vciudad    is null   OR  vciudad = ''    ) OR 
           ( vestado    is null   OR  vestado = ''    ) OR 
           ( vcod_pos   is null   OR  vcod_pos = ''   ) OR 
           ( vpais      is null   OR  vpais = ''      ) THEN 
            LET vcValNulos = '0';
        ELSE
            LET vcValNulos = '1';
        END IF;
        
        CALL bdiprog:isnumeric(vno_ext)  RETURNING vcodretint01;
        
        IF ( vcodretint01 <> 1 ) THEN
            LET vcValNumeros = '0';
        ELSE
            LET vcValNumeros = '1';
        END IF;
        
        IF NOT ( ( SUBSTR(vfecha_nac, 1, 2) > 0    AND SUBSTR(vfecha_nac, 1, 2) < 32 ) AND 
                 ( SUBSTR(vfecha_nac, 3, 2) > 0    AND SUBSTR(vfecha_nac, 3, 2) < 13 ) AND 
                 ( SUBSTR(vfecha_nac, 5, 4) > 1900 AND SUBSTR(vfecha_nac, 5, 4) < 3000 ) ) THEN
            LET vcValFechas = '0';
        ELSE
            LET vcValFechas = '1';
        END IF;
        
        CALL bdiprog:isnumeric(vnombre1) RETURNING vcodretint02;
        CALL bdiprog:isnumeric(vnombre2) RETURNING vcodretint03;
        CALL bdiprog:isnumeric(vape_pat) RETURNING vcodretint04;
        CALL bdiprog:isnumeric(vape_mat) RETURNING vcodretint05;
        CALL bdiprog:isnumeric(vrfc)     RETURNING vcodretint06;
        CALL bdiprog:isnumeric(vgenero)  RETURNING vcodretint07;
        CALL bdiprog:isnumeric(vtipo_id) RETURNING vcodretint08;
        CALL bdiprog:isnumeric(vcalle)   RETURNING vcodretint09;
        CALL bdiprog:isnumeric(vcolonia) RETURNING vcodretint10;
        CALL bdiprog:isnumeric(vdel_mun) RETURNING vcodretint11;
        CALL bdiprog:isnumeric(vciudad)  RETURNING vcodretint12;
        CALL bdiprog:isnumeric(vestado)  RETURNING vcodretint13;
        
        IF ( vcodretint02 <> 0 ) OR ( vcodretint03 <> 0 ) OR ( vcodretint04 <> 0 ) OR ( vcodretint05 <> 0 ) OR ( vcodretint06 <> 0 ) OR ( vcodretint07 <> 0 ) OR 
           ( vcodretint08 <> 0 ) OR ( vcodretint09 <> 0 ) OR ( vcodretint10 <> 0 ) OR ( vcodretint11 <> 0 ) OR ( vcodretint12 <> 0 ) OR ( vcodretint13 <> 0 )  THEN
            LET vcValLetras = '0';
        ELSE
            LET vcValLetras = '1';
        END IF;
        
        SELECT COUNT(*)
          INTO viExisteCP
          FROM bdinteg:si_catsepomex
         WHERE d_codigo = vcod_pos
           AND d_asenta = d_asenta;
        
        IF vcValNulos = '1' AND vcValNumeros = '1' AND vcValFechas = '1' AND vcValLetras = '1' AND viExisteCP > 0 THEN
            INSERT INTO bdinteg:si_altamasivaempnet_det
            ( nombre_archivo, cod_empresa, cve_cte, nombre1, nombre2, ape_pat, ape_mat, fecha_nac, rfc, curp, genero,  
              tipo_id, num_id, calle, no_ext, no_int, colonia, del_mun, ciudad, estado, cod_pos, pais, ocupacion, status, numcte, cuenta, fecha_registro )
            VALUES
            ( pNombreArchivo, vcNumEmp, vcve_cte, vnombre1, vnombre2, vape_pat, vape_mat, vfecha_nac, vrfc, vcurp, vgenero, 
              vtipo_id, vnum_id, vcalle, vno_ext, vno_int, vcolonia, vdel_mun, vciudad, vestado, vcod_pos, vpais, vocupacion, '0', '', '', vdFechaHoy );
        END IF;
          
        COMMIT WORK;
        LET vTrxAbierta = 0;
    END FOREACH;
    
    SELECT COUNT(*)
      INTO vContador2
      FROM bdinteg:si_altamasivaempnet_det
     WHERE cod_empresa = vcNumEmp
       AND nombre_archivo = pNombreArchivo;
      
    IF vContador2 > 0 THEN
        UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '1'
         WHERE cod_empresa = vcNumEmp
           AND nombre_archivo = pNombreArchivo;
    END IF;
    
    END;
    
    RETURN vCodRet1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_altamasivaempnet_registra_pba( pEmpresa CHAR(3), pNumCteMoral CHAR(20), pEjecutivo CHAR(8), pNomArchivo CHAR(30) )
RETURNING CHAR(5), CHAR(100);
    
    DEFINE iSqlErr				INTEGER;
    DEFINE iIsamErr				INTEGER;
    DEFINE iDescErr				CHAR(50);
    DEFINE cCodRet 				CHAR(5);
    DEFINE cCodRet2				CHAR(5);
    DEFINE cCodRet3				CHAR(50);
    DEFINE cCodRetRfc	        CHAR(6);
    DEFINE cCodRetCte	        CHAR(5);
    DEFINE cCodRetDir	        CHAR(5);
    DEFINE cCodRetCta	        CHAR(5);
    DEFINE cMensaje				VARCHAR(100);
    DEFINE iBegin				INTEGER;
    
    DEFINE dFechaHoy 			DATE;
    DEFINE iExiste				INTEGER;
    DEFINE cProducto 			CHAR(4);
    DEFINE cTipoPersona			CHAR(2);
    DEFINE cTipoCliente			CHAR(1);
    DEFINE cSucursal            CHAR(4);
    DEFINE cNumEmpresa			CHAR(3);
    DEFINE cNumEmpleado			CHAR(30);
    DEFINE cNombre1				CHAR(30);
    DEFINE cNombre2				CHAR(30);
    DEFINE cApellPatern			CHAR(30);
    DEFINE cApellMatern			CHAR(30);
    DEFINE cFecNac 				CHAR(8);
    DEFINE cRFC 				CHAR(13);
    DEFINE cSexo 				CHAR(1);
    DEFINE cTipoId              CHAR(1);
    DEFINE cNumId               CHAR(30);
    DEFINE cCalle               CHAR(30);
    DEFINE iNoExt               INTEGER;
    DEFINE iNoInt               INTEGER;
    DEFINE cColonia             CHAR(30);
    DEFINE cDelMun              CHAR(30);
    DEFINE cCiudad              CHAR(30);
    DEFINE cEstado              CHAR(30);
    DEFINE cCodPos              CHAR(10);
    DEFINE cPais                CHAR(4);
    DEFINE cRFCGenerado			CHAR(13);
    DEFINE cNumCliente			CHAR(20);
    DEFINE sSecuencia           SMALLINT;
    DEFINE vcCalle              CHAR(40);
    DEFINE vcColonia            CHAR(60);
    DEFINE vcMunicipio          CHAR(5);
    DEFINE vcEntreCalles        CHAR(40);
    DEFINE vcPais               CHAR(3);
    DEFINE vcEstado             CHAR(2);
    DEFINE vcCiudad             CHAR(3);
    DEFINE vcCod_post           CHAR(5);
    DEFINE vcTipoTel1           CHAR(1);
    DEFINE vcTel1               CHAR(13);
    DEFINE vcTipoTel2           CHAR(1);
    DEFINE vcTel2               CHAR(13);
    DEFINE vcTipoTel3           CHAR(1);
    DEFINE vcTel3               CHAR(13);
    DEFINE vcExtension          CHAR(5);
    DEFINE vcEdo_inegi          CHAR(2);
    DEFINE vcMuni_iegi          CHAR(3);
    DEFINE vcLocal_inegi        CHAR(4);
    DEFINE vsNumCiudad          SMALLINT;
    DEFINE vcNumExtCalle        CHAR(10);
    DEFINE vcNumIntCalle        CHAR(10);
    DEFINE vcDepto              CHAR(6);
    DEFINE viNumCalle           INTEGER;
    DEFINE viNumColonia         INTEGER;
    DEFINE vcPtoCardinal        CHAR(1);
    DEFINE vcUnidad_habit       CHAR(1);
    DEFINE vsManzana            SMALLINT;
    DEFINE vsOtros              SMALLINT;
    DEFINE vsAndador            SMALLINT;
    DEFINE vsEtapa              SMALLINT;
    DEFINE vsLote               SMALLINT;
    DEFINE vsEdificio           SMALLINT;
    DEFINE vsEntrada            SMALLINT;
    DEFINE vcObserva            CHAR(80);
    DEFINE cNumCuenta			CHAR(20);
    DEFINE cCtaClaBe 			CHAR(20);
    DEFINE viRegProcesados      INTEGER;
    DEFINE viRegxProcesar       INTEGER;
    DEFINE dFecNac              DATE;
    DEFINE cCuentaMoral         CHAR(20);
        
    LET iSqlErr		= 0;
    LET iIsamErr	= 0;
    LET iDescErr	= '';
    LET cCodRet 	= '00000';
    LET cCodRet2 	= '';
    LET cCodRet3 	= '';
    LET cCodRetRfc	= '';
    LET cCodRetCte	= '';
    LET cCodRetDir	= '';
    LET cCodRetCta	= '';
    LET cMensaje    = '';
    LET iBegin      = 0;
    
    LET dFechaHoy       = '';
    LET iExiste	        = 0;
    LET cProducto       = '';
    LET cTipoPersona    = '';
    LET cTipoCliente    = '';
    LET cSucursal       = '';
    LET cNumEmpresa     = '';
    LET cNumEmpleado    = '';
    LET cNombre1        = '';
    LET cNombre2        = '';
    LET cApellPatern    = '';
    LET cApellMatern    = '';
    LET cFecNac         = '';
    LET cRFC            = '';
    LET cSexo           = '';
    LET cTipoId         = '';
    LET cNumId          = '';
    LET cCalle          = '';
    LET iNoExt          = 0;
    LET iNoInt          = 0;
    LET cColonia        = '';
    LET cDelMun         = '';
    LET cCiudad         = '';
    LET cEstado         = '';
    LET cCodPos         = '';
    LET cPais           = '';
    LET cRFCGenerado    = '';
    LET cNumCliente     = '';
    LET sSecuencia      = 0;
    LET vcCalle         = '';
    LET vcColonia       = '';
    LET vcMunicipio     = '';
    LET vcEntreCalles   = '';
    LET vcPais          = '';
    LET vcEstado        = '';
    LET vcCiudad        = '';
    LET vcCod_post      = '';
    LET vcTipoTel1      = '';
    LET vcTel1          = '';
    LET vcTipoTel2      = '';
    LET vcTel2          = '';
    LET vcTipoTel3      = '';
    LET vcTel3          = '';
    LET vcExtension     = '';
    LET vcEdo_inegi     = '';
    LET vcMuni_iegi     = '';
    LET vcLocal_inegi   = '';
    LET vsNumCiudad     = 0;
    LET vcNumExtCalle   = '';
    LET vcNumIntCalle   = '';
    LET vcDepto         = '';
    LET viNumCalle      = 0;
    LET viNumColonia    = 0;
    LET vcPtoCardinal   = '';
    LET vcUnidad_habit  = '';
    LET vsManzana       = 0;
    LET vsOtros         = 0;
    LET vsAndador       = 0;
    LET vsEtapa         = 0;
    LET vsLote          = 0;
    LET vsEdificio      = 0;
    LET vsEntrada       = 0;
    LET vcObserva       = '';
    LET cNumCuenta      = '';
    LET cCtaClaBe       = '';
    LET viRegProcesados = 0;
    LET viRegxProcesar  = 0;
    LET dFecNac         = '';
    LET cCuentaMoral    = '';
    
    BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, iDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_registra.err";
        TRACE ON;
        IF iSqlErr != 0 THEN
            LET cCodRet = iSqlErr;
            LET cCodRet2 = iIsamErr;
            LET cCodRet3 = iDescErr;
            LET cMensaje = 'OCURRIO UN ERROR NO CONTROLADO';
            IF iBegin = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN cCodRet, cMensaje;
        END IF;
    END EXCEPTION;

    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_registra.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5; 
    
    -- // OBTIENE LA FECHA DEL SISTEMA
    SELECT fecha_hoy 
      INTO dFechaHoy 
      FROM bdinteg:si_fechas 
     WHERE empresa = '001';
     
    -- // VALIDA REGISTROS A PROCESAR
    SELECT COUNT(*)
      INTO iExiste 
      FROM bdinteg:si_altamasivaempnet_ctrl 
     WHERE cod_empresa = pEmpresa
       AND nombre_archivo = pNomArchivo
       AND status = '1'; 

    IF iExiste IS NULL OR iExiste = '' OR iExiste = 0 THEN
        LET cCodRet = '00001';
        LET cMensaje = 'NO EXISTEN REGISTROS A PROCESAR';
        RETURN cCodRet, cMensaje;
    END IF;
    
    -- // VALIDA LA PERSONA MORAL
    SELECT COUNT(cte.numcte)
      INTO iExiste
      FROM bdinteg:si_cliente cte
     INNER JOIN bdinteg:si_tipper tpo ON cte.tpo_persona = tpo.tpo_persona
     WHERE cte.empresa = '001'
       AND cte.numcte = pNumCteMoral
       AND tpo.es_fisica = "N";
    
    IF iExiste = 0 THEN
        LET cCodRet = "00002";
        RETURN cCodRet, cMensaje;
    END IF;
    
    -- // OBTIENE PARAMETROS PARA EL ALTA
    SELECT TRIM(acepta_producto), cuenta
      INTO cProducto, cCuentaMoral
      FROM bdicheq:sc_nominaempresas 
     WHERE codigo = pEmpresa;
     
    SELECT tpo_persona 
      INTO cTipoPersona 
      FROM bdinteg:si_tipper 
     WHERE tpo_persona = '01';
     
    SELECT tipo_cliente 
      INTO cTipoCliente 
      FROM bdinteg:si_tipocte 
     WHERE empresa = '001' 
       AND tipo_cliente = 2;
       
    SELECT sucursal
      INTO cSucursal
      FROM bdicheq:sc_maechq
     WHERE empresa = '001'
       AND cuenta = cCuentaMoral;
       
    IF cSucursal is null OR cSucursal = '' THEN
        SELECT TRIM(valor) 
          INTO cSucursal 
          FROM bdicheq:sc_param 
         WHERE codparam = 'AMSUCURSAL' 
           AND empresa = '001';
    END IF;

    -- // VALIDA PARAMETROS ENCONTRADOS PARA EL ALTA
    IF cProducto IS NULL OR cTipoPersona IS NULL OR cTipoCliente IS NULL OR cSucursal IS NULL THEN
        LET cCodRet = '00002';
        LET cMensaje = 'NO SE OBTUVIERON LOS PARÁMETROS NECESARIOS';
        RETURN cCodRet, cMensaje;
    END IF;
    
    SELECT COUNT(*)
      INTO viRegxProcesar
      FROM bdinteg:si_altamasivaempnet_det
     WHERE cod_empresa = pEmpresa
       AND nombre_archivo = pNomArchivo
       AND status = '0';
    
    -- // CONSULTA LAS PETICIONES DE APERTURAS DE NÓMINA PARA QUE SEAN PROCESADAS
    FOREACH WITH HOLD
        SELECT cod_empresa, cve_cte, nombre1, nombre2, ape_pat, ape_mat, fecha_nac, rfc, genero, 
               tipo_id, num_id, calle, no_ext, no_int, colonia, del_mun, ciudad, estado, cod_pos, pais 
          INTO cNumEmpresa, cNumEmpleado, cNombre1, cNombre2, cApellPatern, cApellMatern, cFecNac, cRFC, cSexo, 
               cTipoId, cNumId, cCalle, iNoExt, iNoInt, cColonia, cDelMun, cCiudad, cEstado, cCodPos, cPais 
          FROM bdinteg:si_altamasivaempnet_det
         WHERE cod_empresa = pEmpresa
           AND nombre_archivo = pNomArchivo
           AND status = '0'

        BEGIN WORK;
        LET iBegin = 1;
        
        LET dFecNac = SUBSTR(cFecNac,3,2)||SUBSTR(cFecNac,1,2)||SUBSTR(cFecNac,5,4);
        
        IF cNombre2 is null THEN
            LET cNombre2 = '';
        END IF;
        
        IF cApellMatern is null THEN
            LET cApellMatern = '';
        END IF;
        
        -- // CALCULA EL RFC
        CALL bdinteg:sp_calcularfc( '001', cApellPatern, cApellMatern, cNombre1, cNombre2, dFecNac ) 
        RETURNING cCodRetRfc, cMensaje, cRFCGenerado;
        
        IF cCodRetRfc <> '000000' THEN
            LET cCodRet = '00003';
            LET cMensaje = 'FALLÓ EN EL PROCESO AL INTENTAR LA GENERACIÓN DE RFC';
            ROLLBACK WORK;
            LET iBegin = 0;
            CONTINUE FOREACH;
        END IF;
        
        -- // VALIDA QUE EL GENERADO SEA IGUAL AL QUE RECIBIMOS POR EL CLIENTE, SI NO SE TOMA EL QUE NOSOTROS GENERAMOS
        IF TRIM(cRFC) <> TRIM(cRFCGenerado) THEN
            LET cRFC = cRFCGenerado;
        END IF;
        
        -- // ALTA DEL CLIENTE
        EXECUTE PROCEDURE ctefisico( '001',         --- empresa
                                     'A',           --- tipo de funcion
                                     '',            --- no. cliente
                                     cSucursal,     --- sucursal
                                     pEjecutivo,    --- ejecutivo
                                     cTipoPersona,  --- tpo. persona
                                     cTipoCliente,  --- tpo. cliente
                                     cApellPatern,  --- apell. paterno
                                     cApellMatern,  --- apell. materno
                                     cNombre1,      --- nombre 1
                                     cNombre2,      --- nombre 2
                                     cRfc,          --- rfc
                                     '32',          --- sector
                                     '000',         --- segmento
                                     '',            --- actividad
                                     '000',         --- grupo
                                     '000',         --- subgrupo
                                     '1',           --- residencia
                                     '',            --- apell casada
                                     '',            --- no. cte ref
                                     '01',          --- distrito
                                     '',            --- puesto pol exp
                                     '',            --- familiar pol exp
                                     '00000000000', --- actividad esp
                                     dFecNac,       --- fecha nac
                                     '',            --- lugar nac
                                     '001',         --- nacionalidad
                                     '',            --- fm3
                                     '',            --- edo civil
                                     '',            --- regimen mat
                                     '11',          --- profesion
                                     cSexo,         --- sexo
                                     '',            --- curp
                                     cTipoId,       --- cod identificacion
                                     cNumId,        --- no. identificacion
                                     '',            --- no imss
                                     0,             --- dependientes
                                     '',            --- tutor
                                     '',            --- email
                                     '',            --- nom conyuge
                                     '0',           --- seguro def
                                     '',            --- escolaridad
                                     'P',           --- habita en
                                     0,             --- anios hanita
                                     '',            --- nombre prop
                                     0,             --- imp hip renta
                                     '',            --- no. ife
                                     '',            --- no. tutor
                                     '',            --- no. conyuge
                                     USER,          --- autoriza
                                     '',            --- promocion
                                     '' )           --- no. habitantes
        INTO cCodRetCte, cNumCliente;

        IF cCodRetCte <> '000' THEN
            LET cCodRet = "00005";
            LET cMensaje = "Error al dar de alta al cliente.";
            ROLLBACK WORK;
            LET iBegin = 0;
            CONTINUE FOREACH;
        END IF;
        
        -- // GUARDA DIRECCION DEL CLIENTE (TRABAJO)
        SELECT MAX(secuencia)
          INTO sSecuencia
          FROM bdinteg:si_direcciones_actual
         WHERE numcte = pNumCteMoral;
        
        IF sSecuencia IS NULL THEN
            LET cCodRet = "00004";
            LET cMensaje = "No existe dirección para el cliente moral indicado.";
            ROLLBACK WORK;
            LET iBegin = 0;
            CONTINUE FOREACH;
        END IF;
        
        SELECT dir.calle, dir.colonia, dir.municipio, dir.entre_calles, dir.pais, dir.estado, dir.ciudad, dir.cod_postal,
               tel1.tipo_tel, tel1.telefono, tel2.tipo_tel, tel2.telefono, tel3.tipo_tel, tel3.telefono, tel3.extension,
               dir.estado_inegi, dir.municipio_inegi, dir.localidad_inegi, dir.numerociudad, dir.numeroextcalle, dir.numerointcalle,
               dir.departamento, dir.numerocalle, dir.numerocolonia, dir.puntocardinal, dir.unidadhabitac, dir.manzana,
               dir.otros, dir.andador, dir.etapa, dir.lote, dir.edificio, dir.entrada, dir.observaciones
          INTO vcCalle, vcColonia, vcMunicipio, vcEntreCalles, vcPais, vcEstado, vcCiudad, vcCod_post,
               vcTipoTel1, vcTel1, vcTipoTel2, vcTel2, vcTipoTel3, vcTel3, vcExtension,
               vcEdo_inegi, vcMuni_iegi, vcLocal_inegi, vsNumCiudad, vcNumExtCalle, vcNumIntCalle,
               vcDepto, viNumCalle, viNumColonia, vcPtoCardinal, vcUnidad_habit, vsManzana,
               vsOtros, vsAndador, vsEtapa, vsLote, vsEdificio, vsEntrada, vcObserva
          FROM bdinteg:si_direcciones_actual dir
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel1 ON ( tel1.numcte = dir.numcte AND tel1.tipo_tel = 1 )
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel2 ON ( tel2.numcte = dir.numcte AND tel2.tipo_tel = 2 )
          LEFT OUTER JOIN bdinteg:si_telefonos_actual tel3 ON ( tel3.numcte = dir.numcte AND tel3.tipo_tel = 3 )
         WHERE dir.numcte = pNumCteMoral
           AND dir.secuencia = sSecuencia;
        
        EXECUTE PROCEDURE direcciones( '001',           --- empresa
                                       'A',             --- tpo funcion
                                       cNumCliente,     --- no. cliente
                                       0,               --- secuencia
                                       "3",             --- tipo dir
                                       vcCalle,         --- calle
                                       vcColonia,       --- colonia
                                       vcMunicipio,     --- municipio
                                       vcEntreCalles,   --- entre calles
                                       vcPais,          --- pais
                                       vcEstado,        --- entidad
                                       vcCiudad,        --- localidad
                                       vcCod_post,      --- cod postal
                                       vcTipoTel1,      --- tipo tel 1
                                       vcTel1,          --- telefono 1
                                       vcTipoTel2,      --- tipo tel 2
                                       vcTel2,          --- telefono 2
                                       vcTipoTel3,      --- tipo tel 3
                                       vcTel3,          --- telefono 3
                                       vcExtension,     --- extension
                                       vcEdo_inegi,     --- edo inegi
                                       vcMuni_iegi,     --- munic imegi
                                       vcLocal_inegi,   --- localid inegi
                                       vsNumCiudad,     --- no ciudad
                                       vcNumExtCalle,   --- no ext calle
                                       vcNumIntCalle,   --- no int calle
                                       vcDepto,         --- depto
                                       viNumCalle,      --- no calle
                                       viNumColonia,    --- no colonia
                                       vcPtoCardinal,   --- pto cardinal
                                       vcUnidad_habit,  --- unidad hab
                                       vsManzana,       --- manzana
                                       vsOtros,         --- otros
                                       vsAndador,       --- andador
                                       vsEtapa,         --- etapa
                                       vsLote,          --- lote
                                       vsEdificio,      --- edificio
                                       vsEntrada,       --- entrada
                                       vcObserva,       --- observaciones
                                       pejecutivo,      --- ejecutivo
                                       dFechaHoy,       --- fecha alta
                                       cSucursal )      --- sucursal
        INTO cCodRetDir;
        
        IF cCodRetDir <> '000' THEN
            LET cCodRet = "00006";
            LET cMensaje = "Error al registrar la dirección del cliente.";
            ROLLBACK WORK;
            LET iBegin = 0;
            CONTINUE FOREACH;
        END IF;
        
        -- // GUARDA DIRECCION DEL CLIENTE (PERSONAL)
        INSERT INTO bdinteg:si_altamasivaempnet_dircte
        (numcte, calle, no_ext, no_int, colonia, del_mun, ciudad, estado, cod_pos, pais)
        VALUES
        (cNumCliente, cCalle, iNoExt, iNoInt, cColonia, cDelMun, cCiudad, cEstado, cCodPos, cPais);
        
        -- // ALTA DE LA CUENTA DEL CLIENTE
        CALL bdicheq:cuenta2( '001',         --- empresa
                              pEjecutivo,    --- usuario
                              cSucursal,     --- sucursal
                              cProducto,     --- producto
                              cNumCliente,   --- no cliente
                              '02',          --- no cotitular
                              '1',           --- clase cta
                              '3',           --- reg firmas
                              '001',         --- tipo banca
                              pEjecutivo,    --- ejecutivo
                              '1',           --- envio direcc
                              '',            --- cuenta
                              0,             --- direcc envio
                              '',            --- cliente 2
                              '',            --- nombre 
                              '',            --- instrucc cap
                              '',            --- cuenta cap
                              '',            --- instrucc int
                              '',            --- cuenta int
                              0,             --- plazo
                              'N',           --- cobra isr
                              '02',          --- proc apert cta
                              '02',          --- proce mant cta
                              '01',          --- monto mensual
                              '01',          --- cantidad dep
                              '01',          --- monto dep
                              '01',          --- cantidad ret
                              '01',          --- monto ret
                              '',            --- forma apert
                              0.00,          --- monto apert
                              cNumEmpresa,   --- no. empleado 
                              cNumEmpleado ) --- no. nomina
        RETURNING cCodRetCta, cNumCuenta, cCtaClaBe;
        
        IF cCodRetCta = '000' THEN
            UPDATE bdinteg:si_altamasivaempnet_det
               SET numcte = cNumCliente, 
                   cuenta = cNumCuenta,
                   status = '1'
             WHERE cod_empresa = pEmpresa
               AND cve_cte = cNumEmpleado
               AND nombre_archivo = pNomArchivo;
               
            UPDATE bdinteg:si_cliente
               SET string1 = "2"
             WHERE empresa = pempresa
               AND numcte = cNumCliente;
               
            UPDATE bdicheq:sc_maechq
               SET marca_ret = '1'
             WHERE num_cte = cNumCliente
               AND cuenta = cNumCuenta;
               
            COMMIT WORK;
            LET iBegin = 0;
        ELSE
            ROLLBACK WORK;
            LET iBegin = 0;
            CONTINUE FOREACH;
        END IF;
    END FOREACH;
    
    SELECT COUNT(*)
      INTO viRegProcesados
      FROM bdinteg:si_altamasivaempnet_det
     WHERE cod_empresa = pEmpresa
       AND nombre_archivo = pNomArchivo
       AND status = '1';
       
    IF viRegProcesados = 0 THEN
        UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '2', --- NO SE PROCESO NINGUN CLIENTE
               fecha_aplicado = dFechaHoy,
               hora_aplicado = CURRENT HOUR TO SECOND,
               registros_aplic = 0
         WHERE cod_empresa = pEmpresa
           AND nombre_archivo = pNomArchivo;
    ELIF viRegProcesados < viRegxProcesar THEN
        UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '3', --- SE PROCESARON MENOS CLIENTES DEL TOTAL DEL ARCHIVO
               fecha_aplicado = dFechaHoy,
               hora_aplicado = CURRENT HOUR TO SECOND,
               registros_aplic = viRegProcesados
         WHERE cod_empresa = pEmpresa
           AND nombre_archivo = pNomArchivo;
    ELIF viRegProcesados = viRegxProcesar THEN
        UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '4', --- SE PROCESARON TODOS LOS CLIENTES DEL ARCHIVO
               fecha_aplicado = dFechaHoy,
               hora_aplicado = CURRENT HOUR TO SECOND,
               registros_aplic = viRegxProcesar
         WHERE cod_empresa = pEmpresa
           AND nombre_archivo = pNomArchivo;
    END IF;
    
    RETURN cCodRet, cMensaje;
    
    END;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_calcularfc_pba(pEmpresa CHAR(3), 
                                          pApePat VARCHAR(26), 
                                          pApeMat VARCHAR(26), 
                                          pNombre1 VARCHAR(26),  
                                          pNombre2 VARCHAR(26), 
                                          pFechaNac DATE) 

RETURNING CHAR(6)       AS retorno, 
          VARCHAR(100)  AS mensaje, 
          VARCHAR(13)   AS rfc; 

-- Variables del proceso
DEFINE vNombre      VARCHAR(53);
DEFINE vApell_Pat   VARCHAR(26);
DEFINE vApell_Mat   VARCHAR(26);
DEFINE cLetraApePat CHAR(1);
DEFINE cVocalApePat CHAR(1);
DEFINE cLetraapeMat CHAR(1);
DEFINE cLetraNombre CHAR(1);
DEFINE cDia         CHAR(2);
DEFINE cMes         CHAR(2);
DEFINE cAnio        CHAR(2);
DEFINE i,a          INTEGER;
DEFINE cLetra       CHAR(1);
DEFINE cCaracter    CHAR(1);
DEFINE cRfc         VARCHAR(13);
DEFINE cPalabra     VARCHAR(26);
DEFINE cFechaNac    VARCHAR(10);
DEFINE cHomoclave   CHAR(2);
DEFINE cDigito      CHAR(1);

-- Control de errores
DEFINE iSqlErr      INTEGER;
DEFINE iIsamErr     INTEGER;
DEFINE vErrorInfo   VARCHAR(100);
DEFINE vCodRet      CHAR(6);
DEFINE cMensaje     VARCHAR(100);

-- Variables del proceso
LET vNombre         = "";
LET vApell_Pat      = TRIM(UPPER(pApePat));
LET vApell_Mat      = TRIM(UPPER(pApeMat));
LET cLetraApePat    = "";
LET cVocalApePat    = "";
LET cLetraapeMat    = "";
LET cLetraNombre    = "";
LET cDia            = "";
LET cMes            = "";
LET cAnio           = "";
LET i               = 0;
LET a               = 0;
LET cLetra          = "";
LET cCaracter       = "";
LET cRfc            = "";
LET cPalabra        = "";
LET cFechaNac       = pFechaNac;
LET cHomoclave      = "";
LET cDigito         = "";


-- Control de errores
LET iSqlErr         = 0;
LET iIsamErr        = 0;
LET vErrorInfo      = "";
LET vCodRet         = "000000";
LET cMensaje        = "El proceso se realizó con éxito.";

BEGIN

ON EXCEPTION SET iSqlErr, iIsamErr, vErrorInfo
   IF iSqlErr != 0 THEN
      LET vCodRet= iSqlErr;
      LET cMensaje= vErrorInfo;
      RETURN vCodRet, cMensaje,cRfc;
   END IF;
END EXCEPTION; 

  --SET DEBUG FILE TO "/home/sysifx/viridiana/sp_calcularfc.out";
  --TRACE ON;

   IF NVL(pEmpresa,"") = "" THEN
       LET vCodRet = "000001";
       LET cMensaje = "La información de la empresa no es correcta.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   IF NVL(pApePat,"") = "" AND NVL(pApeMat,"") = "" THEN
       LET vCodRet = "000002";
       LET cMensaje = "Es necesario proporcionar al menos un apellido del cliente.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   IF NVL(pNombre1,"") = "" AND NVL(pNombre2,"") = "" THEN
       LET vCodRet = "000003";
       LET cMensaje = "Es necesario proporcionar al menos un nombre del cliente.";
       RETURN vCodRet, cMensaje,cRfc;
   END IF;

   LET cFechaNac = LPAD(YEAR(pFechaNac),4,0) ||"/" || LPAD(MONTH(pFechaNac),2,0) || "/" || LPAD(DAY(pFechaNac),2,0);

   IF NVL(cFechaNac,"") <> "" AND (LENGTH(cFechaNac) = 10) AND SUBSTR(cFechaNac,1,1) <> "0" THEN    

           LET cAnio = SUBSTR(cFechaNac,3,2);
           LET cMes  = SUBSTR(cFechaNac,6,2);
           LET cDia  = SUBSTR(cFechaNac,9,2);       
                 
   ELSE
       LET vCodRet = "000005";
       LET cMensaje = "La fecha de nacimiento del proporcionada no es válida.";
       RETURN vCodRet, cMensaje,cRfc;     
   
   END IF   

   IF  NVL(pApePat,"") = ""  AND NVL(pApeMat,"") <> "" THEN
       LET vApell_Pat = TRIM(UPPER(pApeMat));
       LET vApell_Mat = "";
   END IF; 


   LET vNombre = UPPER(TRIM(pNombre1) ||" "|| TRIM(pNombre2));
   
   EXECUTE PROCEDURE bdinteg:sp_calcularrfc(vApell_Pat, vApell_Mat, vNombre, pFechaNac)
            INTO vCodRet, cRfc;
   
IF vCodRet <> "00000" THEN
    LET vCodRet = "000017";
    LET cMensaje = "Ocurrió un error al calcular el dígito verificador para el RFC.";
    RETURN vCodRet, cMensaje,cRfc;
ELSE
    LET vCodRet = "000000";
END IF;


RETURN vCodRet, cMensaje,cRfc;
END 
END PROCEDURE
DOCUMENT
"Descripción: Procedimiento que realiza el cálculo del RFC de un cliente.",
"BD: bdinteg",
"Fecha: 06-Abril-2010",
"Autor: Viridiana Osobampo Aguilar";

CREATE PROCEDURE "informix".ctefisico_pba( pEmpresa CHAR(3),
                                       pFuncion CHAR(1),
                                       pNumcte CHAR(20),
                                       pSucursal CHAR(4),
                                       pEjecutivo CHAR(8),
                                       pTp_persona CHAR (2),
                                       pTp_cliente CHAR(1),
                                       pPaterno CHAR (26),
                                       pMaterno CHAR (26),
                                       pNombre1 CHAR (26),
                                       pNombre2 CHAR (26),
                                       pRfc CHAR (13),
                                       pSector CHAR (2),
                                       pSegmento CHAR (3),
                                       pActividad_princ CHAR (3),
                                       pGrupo CHAR(3),
                                       pSubgrupo CHAR(3),
                                       pResidencia CHAR(1),
                                       pApell_casada CHAR(20),
                                       pNumcte_ref CHAR(20),
                                       pDistrito CHAR(2),
                                       pPuesto_ppes CHAR(1),
                                       pFamiliar_ppes CHAR(1),
                                       pActividad_esp CHAR(11),
                                       pFecha_nac DATE, -- Inician columnas de Ctepf
                                       pLugar_nac CHAR (2),
                                       pNacionalidad CHAR(3),
                                       pFm3 CHAR(18),
                                       pEstado_civil CHAR(1),
                                       pRegimen_mat CHAR(1),
                                       pProfesion CHAR (3),
                                       pSexo CHAR(1),
                                       pCurp CHAR(20),
                                       pCodidentif CHAR(2),
                                       pNumidentif CHAR(30),
                                       pNo_imss CHAR(12),
                                       pDependientes SMALLINT,
                                       pTutor CHAR(60),
                                       pEmail CHAR(60),
                                       pNom_conyuge CHAR(60),
                                       pSeguro_defunc CHAR(1),
                                       pEscolaridad CHAR(2),
                                       pHabita_en CHAR(20),
                                       pAnios_habita SMALLINT,
                                       pNombre_prop CHAR(60),
                                       pImphiporenta MONEY(14,2),
                                       pNumeroife CHAR(20),
                                       pNumerotutor CHAR(20),
                                       pNumeroconyuge CHAR(20),
                                       pEjecut_autoriza CHAR(8),
                                       pPromocion CHAR(2),
                                       pNumhabitantes CHAR (60) )
RETURNING CHAR(5),CHAR(20);

DEFINE cCodret 				CHAR(5);
DEFINE cCodret2 			CHAR(5);
DEFINE dFecha 				DATE;
DEFINE iSignumcte 			INT;
DEFINE cExiste 				CHAR(1);
DEFINE cEmpresa 			CHAR(3);
DEFINE cNumcte 				CHAR(20);
DEFINE cSucursal 			CHAR(4);
DEFINE cEjecutivo 			CHAR(8);
DEFINE cEjecut_autoriza 	CHAR(8);
DEFINE cTp_persona 			CHAR (2);
DEFINE cTp_cliente 			CHAR(1);
DEFINE cPaterno 			CHAR (26);
DEFINE cMaterno 			CHAR (26);
DEFINE cNombre1 			CHAR (26);
DEFINE cNombre2 			CHAR (26);
DEFINE cRfc 				CHAR (13);
DEFINE cSector 				CHAR (2);
DEFINE cSegmento 			CHAR (3);
DEFINE cAtividad_princ 		CHAR (3);
DEFINE cGrupo 				CHAR(3);
DEFINE cSubgrupo 			CHAR(3);
DEFINE cResidencia 			CHAR(1);
DEFINE cApell_casada 		CHAR(20);
DEFINE cNumcte_referencia	CHAR(20);
DEFINE cDistrito 			CHAR(2);
DEFINE cPuesto_ppes 		CHAR(1);
DEFINE cFamiliar_ppes 		CHAR(1);
DEFINE cActividad_esp 		CHAR(11);
DEFINE dFecha_nac 			DATE; -- Inician columnas de Ctepf
DEFINE cLugar_nac 			CHAR (2);
DEFINE cNacionalidad 		CHAR(3);
DEFINE cFm3 				CHAR(18);
DEFINE cEstado_civil 		CHAR(1);
DEFINE cRegimen_mat 		CHAR(1);
DEFINE cProfesion 			CHAR (3);
DEFINE cSexo 				CHAR(1);
DEFINE cCurp 				CHAR(20);
DEFINE cCodidentif 			CHAR(2);
DEFINE cNumidentif 			CHAR(20);
DEFINE cNo_imss 			CHAR(12);
DEFINE sDependientes 		SMALLINT;
DEFINE cTutor 				CHAR(60);
DEFINE cEmail 				CHAR(60);
DEFINE cNom_conyuge 		CHAR(60);
DEFINE cSeguro_defunc 		CHAR(1);
DEFINE cEscolaridad 		CHAR(2);
DEFINE cHabita_en 			CHAR(20);
DEFINE sAnios_habita 		SMALLINT;
DEFINE cNombre_prop 		CHAR(60);
DEFINE mImphiporenta 		MONEY(14,2);
DEFINE cNumeroife 			CHAR(20);
DEFINE cNumerotutor 		CHAR(20);
DEFINE cNumeroconyuge 		CHAR(20);
DEFINE cTppersona 			CHAR(2);
DEFINE sCont 				SMALLINT;
DEFINE cEsfisica 			CHAR(1);
DEFINE sLongitud		    SMALLINT;
DEFINE sLong_cte 			SMALLINT;
DEFINE iSqlerr				INTEGER;
DEFINE iIsamerr 			INTEGER;
DEFINE cStatus_cte 			CHAR(2);
DEFINE dFecha_alta 			DATE;
DEFINE cRazon_soc 			CHAR(40);
DEFINE sDiferencia			SMALLINT;
DEFINE sI 					SMALLINT;
DEFINE cNumcte_ref 			CHAR(20);
DEFINE cNumhabitantes 		CHAR(60);
DEFINE cSucursalCajaUnica 	CHAR(1);
DEFINE iOrigen 				INTEGER;
DEFINE cTipoRel 			CHAR(1);
DEFINE cCodRet3             CHAR(6);
DEFINE cMensajeRet          CHAR(80);

-- Valida referencia Coppel JOM 20/Abr/2014 INI
DEFINE v_codret_cc          CHAR(5);
DEFINE v_result_cc			CHAR(1);
-- Valida referencia Coppel JOM 20/Abr/2014 FIN

LET cCodret 			= "000";
LET cCodret2 			= '000';
LET cEmpresa 			= pEmpresa;
LET cNumcte 			= " ";
LET cSucursal 			= pSucursal;
LET cTppersona 			= pTp_persona;
LET cNumcte_ref 		= " ";
LET cEjecut_autoriza 	= pEjecut_autoriza;
LET iOrigen 			= 0; --sin informacion
LET cTipoRel			='0';
LET cCodRet3            = "00000";
LET cMensajeRet         = "Se realizÃÂ³ la consulta correctamente";

-- Valida referencia Coppel JOM 20/Abr/2014 INI
LET v_codret_cc      = "00000";
LET v_result_cc		= '';
-- Valida referencia Coppel JOM 20/Abr/2014 FIN

BEGIN
ON EXCEPTION SET iSqlerr,iIsamerr
	IF iSqlerr != 0 THEN
		LET cCodret=iSqlerr;
		RETURN cCodret,cNumcte;
	END IF;
END EXCEPTION;

	--SET DEBUG FILE TO "/respaldosbd/claudio/ctefisico.out";
    --TRACE ON;

SET ISOLATION TO DIRTY READ;
SET LOCK MODE TO WAIT 3;

SELECT fecha_hoy
  INTO dFecha
  FROM bdinteg:"informix".si_fechas
 WHERE empresa = pEmpresa;

    IF pFuncion = "B" THEN
        LET cNumcte = pNumcte;
        SELECT tpo_persona INTO cTppersona
          FROM bdinteg:"informix".si_cliente
         WHERE numero = pnumero;
        IF cTppersona IS NULL THEN
            LET cNumcte = pNumcte;
            LET cCodret = "104";
            RETURN cCodret,cNumcte;
        ELSE
            SELECT es_fisica
              INTO cEsfisica
              FROM bdinteg:"informix".si_tipper
             WHERE tpo_persona = cTppersona;

            IF UPPER(cEsfisica) != "S" THEN
                LET cCodret = "120";
                RETURN cCodret,cNumcte;
            END IF;
        END IF

        SELECT COUNT(*)
          INTO sCont
          FROM bdicheq:"informix".sc_maechq
         WHERE numcte = pNumcte;

        IF sCont > 0 THEN
            LET cCodret = "121";
            RETURN cCodret,cNumcte;
        END IF

        SELECT COUNT(*)
          INTO sCont
          FROM bdisolic:"informix".ss_solicitudes
         WHERE empresa="001"
           AND numcte = pNumcte;

        IF sCont > 0 THEN
            LET cCodret = "121";
            RETURN cCodret,cNumcte;
        END IF

        SELECT COUNT(*)
          INTO sCont
          FROM bdicred:"informix".sd_maecred
         WHERE numcte = pNumcte;

        IF sCont > 0 THEN
            LET cCodret = "121";
            RETURN cCodret,cNumcte;
        END IF

        SELECT COUNT(*)
          INTO sCont
          FROM bdinvers:"informix".sv_maeinv
         WHERE numcte = pNumcte;

        IF sCont > 0 THEN
            LET cCodret = "121";
            RETURN cCodret,cNumcte;
        END IF

        BEGIN

        DELETE FROM bdinteg:"informix".si_direcciones WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_refcomer WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_refbancarias WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_refper WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_ctepf WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_ingresos WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_cterelacionado WHERE empresa = "001" AND numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_cteppes WHERE numcte = pNumcte;
        DELETE FROM bdinteg:"informix".si_cliente WHERE numcte = pNumcte;

        END;

        RETURN cCodret,cNumcte;
    END IF

    IF pFuncion = "C" THEN
        LET cNumcte = pNumcte;

        SELECT empresa,     numcte,       status_cte,     sucursal,     ejecutivo,
               tpo_persona, tipo_cliente, apell_paterno,  apell_materno,
               nombre1,     nombre2,      razon_social,   rfc,
               sectOR,      segmento,     actividad_princ,grupo,
               subgrupo,    residencia,   fecha_alta,     apell_casada,
               distrito,    numcte_ref,   puesto_ppes,    familiar_ppes,
               actividad_princ,ejecut_autoriza, string2
          INTO cEmpresa,   cNumcte,      cStatus_cte,    cSucursal,   cEjecutivo,
               cTppersona,  cTp_cliente,  cPaterno,       cMaterno,
               cNombre1,    cNombre2,     cRazon_soc,     cRfc,
               cSector,     cSegmento,    cAtividad_princ,cGrupo,
               cSubgrupo,   cResidencia,  dFecha_alta,    cApell_casada,
               cDistrito,   cNumcte_ref,  cPuesto_ppes,   cFamiliar_ppes,
               cActividad_esp,cEjecut_autoriza, cNumhabitantes
          FROM bdinteg:"informix".si_cliente
         WHERE numcte = pNumcte;


        IF cNumcte IS NULL THEN
            LET cCodret = "104";
            RETURN cCodret,cNumcte;
        END IF

        IF pEmpresa IS NULL OR pEmpresa = " " THEN
            LET pEmpresa = cEmpresa;
        END IF

        IF pSucursal IS NULL OR pSucursal = " " THEN
            LET pSucursal=cSucursal;
        END IF;

        IF pEjecutivo IS NULL OR pEjecutivo = " " THEN
            LET pEjecutivo=cEjecutivo;
        END IF;

        IF pTp_persona IS NULL OR pTp_persona = " " THEN
            LET pTp_persona=cTppersona;
        END IF;

        IF pTp_cliente IS NULL OR pTp_cliente = " " THEN
            LET pTp_cliente = cTp_cliente;
        END IF;

        IF pTp_cliente = '2' AND cTp_cliente = '1' THEN
            LET pTp_cliente = cTp_cliente;
        END IF;

        IF pPaterno IS NULL OR pPaterno = " " THEN
            LET pPaterno=cPaterno;
        END IF;

        IF pMaterno IS NULL OR pMaterno = " " THEN
            LET pMaterno=cMaterno;
        END IF;

        IF pNombre1 IS NULL OR pNombre1 = " " THEN
            LET pNombre1=cNombre1;
        END IF;

        IF pNombre2 IS NULL OR pNombre2 = " " THEN
            LET pNombre2=cNombre2;
        END IF;

        IF pRfc IS NULL OR pRfc = " " THEN
            LET pRfc=cRfc;
        END IF;

        IF pSector IS NULL OR pSector = " " THEN
            LET pSector=cSector;
        END IF;

        IF pSegmento IS NULL OR pSegmento = " " THEN
            LET pSegmento=cSegmento;
        END IF;

        IF pActividad_princ IS NULL OR pActividad_princ = " " THEN
            LET pActividad_princ=cAtividad_princ;
        END IF;

        IF pGrupo IS NULL OR pGrupo = " " THEN
            LET pGrupo=cGrupo;
        END IF;

        IF pSubgrupo IS NULL OR pSubgrupo = " " THEN
            LET pSubgrupo=cSubgrupo;
        END IF;

        IF pResidencia IS NULL OR pResidencia = " " THEN
            LET pResidencia=cResidencia;
        END IF;

        IF pApell_casada IS NULL OR pApell_casada = " " THEN
            LET pApell_casada = cApell_casada;
        END IF;

        IF pDistrito IS NULL OR pDistrito = " " THEN
            LET pDistrito=cDistrito;
        END IF;

        IF pNumcte_ref IS NULL OR pNumcte_ref = " " THEN
            LET pNumcte_ref=cNumcte_ref;
        END IF;

        IF pPuesto_ppes IS NULL OR pPuesto_ppes = " " THEN
            LET pPuesto_ppes=cPuesto_ppes;
        END IF;

        IF pFamiliar_ppes IS NULL OR pFamiliar_ppes = " " THEN
            LET pFamiliar_ppes=cFamiliar_ppes;
        END IF;

        IF pActividad_esp IS NULL OR pActividad_esp = " " THEN
            LET pActividad_esp=cActividad_esp;
        END IF;

        IF pEjecut_autoriza IS NULL OR pEjecut_autoriza = " " THEN
            LET pEjecut_autoriza=cEjecut_autoriza;
        END IF;

        SELECT numcte,         fecha_nac,       lugar_nac,        nacionalidad,
               no_fm3,         estado_civil,    regim_matrimonio, profesion,
               sexo,           curp,            codidentifi,      numidentifi,
               no_imss,        dependientes,    tutor,
               nom_conyuge,    seguro_defunc,   escolaridad,      habita_en,
               anios_habita,   nombre_prop,     imp_hipo_renta,   numeroife,
               numerotutor,    numeroconyuge
          INTO cNumcte,        dFecha_nac,      cLugar_nac,       cNacionalidad,
               cFm3,           cEstado_civil,   cRegimen_mat,     cProfesion,
               cSexo,          cCurp,           cCodidentif,      cNumidentif,
               cNo_imss,       sDependientes,   cTutor,
               cNom_conyuge,   cSeguro_defunc,  cEscolaridad,     cHabita_en,
               sAnios_habita,  cNombre_prop,    mImphiporenta,    cNumeroife,
               cNumerotutor,   cNumeroconyuge
          FROM bdinteg:"informix".si_ctepf
         WHERE numcte = pNumcte;

        SELECT correo_elec
          INTO cEmail
          FROM "informix".si_correos
         WHERE numcte = pNumcte
           AND tipo_correo = 1
           AND status_correo = 'A'
		   and secuencia = (
			select max(secuencia)
			from "informix".si_correos
			where numcte = pNumcte AND status_correo = 'A' AND tipo_correo = 1);

        IF pFecha_nac IS NULL OR pFecha_nac = " " THEN
            LET pFecha_nac=dFecha_nac;
        END IF;

        IF pLugar_nac IS NULL OR pLugar_nac = " " THEN
            LET pLugar_nac=cLugar_nac;
        END IF;

        IF pNacionalidad IS NULL OR pNacionalidad = " " THEN
            LET pNacionalidad=cNacionalidad;
        END IF;

		-->> 29/10/2014
        --IF pFm3 IS NULL OR pFm3 = " " THEN
        --    LET pFm3 = cFm3;
        --END IF; << 29/10/2014

        IF pEstado_civil IS NULL OR pEstado_civil = " " THEN
            LET pEstado_civil=cEstado_civil;
        END IF;

        IF pRegimen_mat IS NULL OR pRegimen_mat = " " THEN
            LET pRegimen_mat=cRegimen_mat;
        END IF;

        IF pProfesion IS NULL OR pProfesion = " " THEN
            LET pProfesion = cProfesion;
        END IF;

        IF pSexo IS NULL OR pSexo = " " THEN
            LET pSexo=cSexo;
        END IF;

        IF SUBSTRING(cRfc FROM 1 FOR 10) <> SUBSTRING(pCurp FROM 1 FOR 10) THEN
				INSERT INTO bdinteg:"informix".si_bitacora_cambio_curp
                ( numcte, rfc, curp, resultado, fecha )
				VALUES
                ( pNumcte, cRfc, pCurp, '03', CURRENT );

				--LET pCurp = cCurp;
        END IF;

        IF pCodidentif IS NULL OR pCodidentif = " " THEN
            LET pCodidentif = cCodidentif;
        END IF

        IF pNumidentif IS NULL OR pNumidentif = " " THEN
            LET pNumidentif = cNumidentif;
        END IF

        IF pNo_imss IS NULL OR pNo_imss = " " THEN
            LET pNo_imss = cNo_imss;
        END IF

        IF pDependientes IS NULL OR pDependientes = " " THEN
            LET pDependientes = sDependientes;
        END IF

        IF pTutor IS NULL OR pTutor = " " THEN
            LET pTutor = cTutor;
        END IF

        IF pEmail IS NULL OR pEmail = " " THEN
            LET pEmail = cEmail;
        END IF

        IF pNom_conyuge IS NULL OR pNom_conyuge = " " THEN
            LET pNom_conyuge = cNom_conyuge;
        END IF

        /* #####################################################
        IF pseguro_definc IS NULL OR pSeguro_defunc = " " THEN
            LET pSeguro_defunc = cSeguro_defunc;
        END IF
        ##################################################### */

        IF pEscolaridad IS NULL OR pEscolaridad = " " THEN
            LET pEscolaridad = cEscolaridad;
        END IF

        IF pHabita_en IS NULL OR pHabita_en = " " THEN
            LET pHabita_en = cHabita_en;
        END IF

        IF pAnios_habita IS NULL THEN
            LET pAnios_habita = sAnios_habita;
        END IF

        IF pNombre_prop IS NULL OR pNombre_prop = " " THEN
            LET pNombre_prop = cNombre_prop;
        END IF

        IF pImphiporenta IS NULL THEN
            LET pImphiporenta = mImphiporenta;
        END IF

        IF pNumeroife IS NULL OR pNumeroife = " " THEN
            LET pNumeroife = cNumeroife;
        END IF

        IF pNumerotutor IS NULL OR pNumerotutor = " " THEN
            LET pNumerotutor = cNumerotutor;
        END IF

        IF pNumeroconyuge IS NULL OR pNumeroconyuge = " " THEN
            LET pNumeroconyuge = cNumeroconyuge;
        END IF
    END IF

	-- DSB 19/10/2014 >>
	IF NVL(pFuncion,'') = "S" THEN
		IF NVL(pEmpresa,'') = '' OR NVL(pNumcte,'') = '' OR NVL(pEscolaridad,'') = '' THEN
				LET cCodret = "200";
				RETURN cCodret,cNumcte;
		ELSE
			SELECT 1 INTO cExiste
			FROM bdinteg:"informix".si_cliente
			WHERE empresa = pEmpresa AND numcte = pNumcte;

		   IF NVL(cExiste,'') = '1' THEN
				SELECT 1 INTO cExiste
				FROM bdinteg:"informix".si_ctepf
				WHERE empresa = pEmpresa AND numcte = pNumcte;

				IF NVL(cExiste,'') = '1' THEN
					UPDATE bdinteg:"informix".si_ctepf
					SET escolaridad = pEscolaridad
					WHERE empresa = pEmpresa AND numcte = pNumcte;
					RETURN cCodret,cNumcte;
				ELSE
					LET cCodret = "220";
					RETURN cCodret,cNumcte;
			   END IF
			ELSE
				LET cCodret = "210";
				RETURN cCodret,cNumcte;
		   END IF
		END IF;
	END IF -- << DSB 19/10/2014

    --- Verifica recepcion correcta de datos
    IF pSucursal IS NULL OR pEjecutivo IS NULL OR
       pTp_persona IS NULL OR pTp_cliente IS NULL OR
       pPaterno IS NULL OR pNombre1 IS NULL OR pRfc IS NULL OR
       pSector IS NULL OR pSegmento IS NULL OR
       pActividad_princ IS NULL OR pGrupo IS NULL OR
       pSubgrupo IS NULL OR pResidencia IS NULL OR
       pPuesto_ppes IS NULL OR pFamiliar_ppes IS NULL OR
       pFecha_nac IS NULL OR pLugar_nac IS NULL OR
       pNacionalidad IS NULL OR pEstado_civil IS NULL OR
       pProfesion IS NULL OR pSexo IS NULL OR
       pCodidentif IS NULL OR pNumidentif IS NULL OR
       pDependientes IS NULL OR pEscolaridad IS NULL OR
       pHabita_en IS NULL THEN
        LET cCodret = "110";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT es_fisica
      INTO cEsfisica
      FROM bdinteg:"informix".si_tipper
     WHERE tpo_persona = pTp_persona;

    IF UPPER(cEsfisica) != "S" THEN
        LET cCodret = "120";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_sucursales
     WHERE sucursal=pSucursal;

    IF cExiste IS NULL THEN
        LET cCodret = "111";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_ejecut
     WHERE ejecutivo=pEjecutivo;

    IF cExiste IS NULL THEN
        foreach
            SELECT limit 1 1
                INTO cExiste
            FROM bdinteg:"informix".si_usuario_movil
            WHERE ejecutivo=pEjecutivo
        end foreach;

        IF cExiste IS NULL THEN
            LET cCodret = "112";
            RETURN cCodret,cNumcte;
        END IF;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_sector
     WHERE sector=pSector;

    IF cExiste IS NULL THEN
        LET cCodret = "113";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_segment
     WHERE segmento=pSegmento;

    IF cExiste IS NULL THEN
        LET cCodret = "114";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_grupos
     WHERE grupo=pGrupo;

    IF cExiste IS NULL THEN
        LET cCodret = "115";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_subgpos
     WHERE subgrupo=pSubgrupo;

    IF cExiste IS NULL THEN
        LET cCodret = "116";
        RETURN cCodret,cNumcte;
    END IF;

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_nacion
     WHERE nacion=pNacionalidad;

    IF cExiste IS NULL THEN
        LET cCodret = "124";
        RETURN cCodret,cNumcte;
    END IF;

    /* ############################
    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_actesp
     WHERE codigo=pActividad_esp;

    IF cExiste IS NULL THEN
        LET cCodret="125";
        RETURN cCodret,cNumcte;
    END IF;
    ############################ */

	-- DSB 29/10/2014
    /* SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_profesion
     WHERE profesion = pProfesion;

    IF cExiste IS NULL THEN
        LET cCodret = "126";
        RETURN cCodret,cNumcte;
    END IF; */

    LET pRfc = TRIM(pRfc);

    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_cliente
     WHERE rfc = pRfc;

    IF NOT cExiste IS NULL AND pFuncion = "A" THEN
        LET cCodret = "106";
        RETURN cCodret,cNumcte;
    END IF

    /* #################################
    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_escolaridad
     WHERE escolaridad = pEscolaridad;

    IF cExiste IS NULL THEN
        LET cCodret="135";
        RETURN cCodret,cNumcte;
    END IF;
    ################################# */

    IF TRIM(pCodidentif) <> "" THEN
        SELECT 1
          INTO cExiste
          FROM bdinteg:"informix".si_tipoidentif
         WHERE codidentif = pCodidentif;

        IF cExiste IS NULL THEN
            LET cCodret = "133";
            RETURN cCodret,cNumcte;
        END IF
    END IF;

    /* ##############################
    SELECT 1
      INTO cExiste
      FROM bdinteg:"informix".si_habitaen
     WHERE habita_en = pHabita_en;

    IF cExiste IS NULL THEN
        LET cCodret="117";
        RETURN cCodret,cNumcte;
    END IF; --- Revisar MAC
    ############################## */

    IF pTp_cliente = "M" THEN ---MenOR de edad
        IF pTutor IS NULL OR pTutor = "" THEN
            LET cCodret = "144";
            RETURN cCodret,cNumcte;
        END IF

        SELECT 1
          INTO cExiste
          FROM bdinteg:"informix".si_cliente
         WHERE numcte = pTutor;

        IF cExiste IS NULL THEN
            LET cCodret = "145";
            RETURN cCodret,cNumcte;
        END IF
    END IF;

    IF pNumcte IS NULL OR pNumcte = " " THEN
        SELECT valor
          INTO sLong_cte
          FROM bdinteg:"informix".si_param
         WHERE cod_param = 7
           AND empresa = pEmpresa;

        IF sLong_cte IS NULL THEN
            LET cCodret = "105";
            RETURN cCodret,cNumcte;
        ELSE
            SELECT valor
              INTO iSignumcte
              FROM bdinteg:"informix".si_param
             WHERE empresa = pEmpresa
               AND cod_param = 6;

            IF iSignumcte IS NULL THEN
                LET iSignumcte = 1;
            END IF

            LET cNumcte=iSignumcte;
            LET iSignumcte=iSignumcte + 1;

            UPDATE bdinteg:"informix".si_param
               SET (valor) = (iSignumcte)
             WHERE empresa = pEmpresa
               AND cod_param = 6;

            LET sDiferencia = sLong_cte - LENGTH(cNumcte);

            IF sDiferencia > 0 THEN
                FOR sI = 1 TO sDiferencia
                    LET cNumcte = "0" || cNumcte;
                END FOR;
            END IF
        END IF;
    ELSE
        LET cNumcte = pNumcte;
    END IF;

    -- ****************** Actualizacion de Parametros *****************
    IF pFuncion = "A" THEN
        SELECT 1 INTO cExiste
          FROM bdinteg:"informix".si_cliente
         WHERE numcte = cNumcte;

        IF cExiste = "1" THEN
            LET cCodret = "118";
            RETURN cCodret, cNumcte;
        END IF;

        IF NVL(pNumcte_ref,'') <> '' THEN
-- Valida referencia Coppel JOM 20/Abr/2014 INI
            EXECUTE PROCEDURE bdinteg:"informix".sp_cons_ref_cop(pEmpresa, pSucursal, pEjecutivo, cNumcte, pNumcte_ref, pPaterno, pMaterno, pNombre1 ,pNombre2, pRfc)
                         INTO v_codret_cc, v_result_cc;

            IF ( v_result_cc = '1' ) THEN
                LET pNumcte_ref = '';
            END IF;
         END IF;
-- Valida referencia Coppel JOM 20/Abr/2014 FIN

        BEGIN

        INSERT INTO bdinteg:"informix".si_cliente
        ( empresa, numcte, status_cte, sucursal, ejecutivo, tpo_persona, tipo_cliente, apell_paterno, apell_materno, nombre1, nombre2, razon_social,
          rfc, sectOR, segmento, actividad_princ, grupo, subgrupo, residencia, fecha_alta, apell_casada, distrito, numcte_ref, string1, string2,
          numeric1, numeric2, money1, DATE1, puesto_ppes, familiar_ppes, actividad_esp, ejecut_autoriza, user_insert, fecha_insert )
        VALUES
        ( pEmpresa, cNumcte, "AL", pSucursal, pEjecutivo, pTp_persona, pTp_cliente, pPaterno, pMaterno, pNombre1, pNombre2, " ",
          pRfc, pSector, pSegmento, pActividad_princ, pGrupo, pSubgrupo, pResidencia, dFecha, pApell_casada, pDistrito, pNumcte_ref, "", pNumhabitantes,
          0, 0, 0, "", pPuesto_ppes, pFamiliar_ppes, pActividad_esp, pEjecut_autoriza, pEjecutivo, dFecha );

        INSERT INTO bdinteg:"informix".si_ctepf
        ( numcte, fecha_nac, lugar_nac, nacionalidad, no_fm3, estado_civil, regim_matrimonio, profesion, sexo, curp, codidentifi, numidentifi, no_imss,
          dependientes, tutor, nom_conyuge, empresa, seguro_defunc, escolaridad, habita_en, anios_habita, nombre_prop, imp_hipo_renta, string1, sms_cel )
        VALUES
        ( cNumcte, pFecha_nac, pLugar_nac, pNacionalidad, pFm3, pEstado_civil, pRegimen_mat, pProfesion, pSexo, pCurp, pCodidentif, pNumidentif, pNo_imss,
          pDependientes, pTutor, pNom_conyuge, pEmpresa, pSeguro_defunc, pEscolaridad, pHabita_en, pAnios_habita, pNombre_prop, pImphiporenta, pPromocion, '0' );

        SELECT NVL(cajaunica, '')
          INTO cSucursalCajaUnica
          FROM bditarjcop:"informix".sucursalescajaunica
         WHERE cvesucursal = pSucursal;

        IF cSucursalCajaUnica = 'V' THEN
            UPDATE bdinteg:"informix".si_cliente
               SET string1 = '1'
             WHERE numcte = cNumcte;
        END IF;

        IF NVL(pNumcte_ref,"") <> "" THEN ---JMAH se realiza validacion para relacionar al cliente Bancoppel con un Cliente Coppel
			LET iOrigen = 2; --relacion por alta de cliente ; ---JMAH
			LET cTipoRel ='1';
		END IF;		--se agrega llamado para crear relacion de clientes bancoppel-coppel.

		EXECUTE PROCEDURE bdinteg:"informix".sp_relacion_generarelacion (cNumcte,pNumcte_ref,'',cTipoRel,iOrigen)
        INTO cCodRet3,cMensajeRet;

        END;

        IF pEmail IS NOT NULL OR pEmail <> '' THEN
            CALL sp_registra_correos( pEmpresa, cNumcte, pEmail, 1, 1, pEjecutivo )
            RETURNING cCodret2;
        END IF;

        RETURN cCodret, cNumcte;
    ELSE
        SELECT 1
          INTO cExiste
          FROM "informix".si_cliente
         WHERE numcte = cNumcte;

        IF cExiste IS NULL THEN
            LET cCodret = "104";
            RETURN cCodret,cNumcte;
        END IF;

        BEGIN

        IF pSucursal ='0010' OR pSucursal ='0012' OR pSucursal ='0034'
            OR pSucursal ='0131' OR pSucursal ='0164' OR pSucursal ='0623' OR pSucursal ='0638' THEN
            
            IF EXISTS(SELECT * FROM si_solicitud_movil WHERE numcte=cNumcte AND folio_procesado=0) THEN
                SELECT escolaridad, tipo_residencia, pers_domicilio 
                    INTO pEscolaridad, pHabita_en, pNumhabitantes
                    FROM si_solicitud_movil WHERE numcte=cNumcte AND folio_procesado=0;
				
				LET pEscolaridad="0"||pEscolaridad;
				
            END IF;
        END IF;

        -- Se Desactiva por Requerimiento de Bancoppel JLP 18/09/07
        UPDATE bdinteg:"informix".si_cliente
           SET ( ejecutivo, tpo_persona, tipo_cliente, --- apell_paterno, apell_materno, nombre1, nombre2, rfc, sectOR, segmento, actividad_esp,
                 sectOR, segmento, actividad_esp, grupo, subgrupo, residencia, fecha_alta, apell_casada, distrito, string2 ) =
               ( pEjecutivo, pTp_persona, pTp_cliente, --- pPaterno, pMaterno, pNombre1, pNombre2,
                 pSector, pSegmento, pActividad_esp, pGrupo, pSubgrupo, pResidencia, dFecha, pApell_casada, pDistrito, pNumhabitantes)
        WHERE numcte = cNumcte;


        UPDATE bdinteg:"informix".si_ctepf
           SET ( fecha_nac, lugar_nac, nacionalidad, no_fm3, estado_civil, regim_matrimonio, profesion, sexo,
                 curp, codidentifi, numidentifi, no_imss, dependientes, tutor, nom_conyuge,
                 seguro_defunc, escolaridad, habita_en, anios_habita, nombre_prop, imp_hipo_renta, sms_cel ) =
               ( pFecha_nac, pLugar_nac, pNacionalidad, pFm3, pEstado_civil, pRegimen_mat, pProfesion, pSexo,
                 pCurp, pCodidentif, pNumidentif, pNo_imss, pDependientes, pTutor, pNom_conyuge,
                 pSeguro_defunc, pEscolaridad,pHabita_en, pAnios_habita, pNombre_prop, pImphiporenta, '0' )
        WHERE numcte = cNumcte;

        END;

        IF pEmail IS NOT NULL OR pEmail <> '' THEN
            CALL sp_registra_correos( pEmpresa, cNumcte, pEmail, 1, 1, pEjecutivo )
            RETURNING cCodret2;
        END IF;
    END IF;

    RETURN cCodret, cNumcte;

    END;

END PROCEDURE

