"BD    : bdinteg",
"VER   : 1.1",
"MOFIDICÃÂ     : MartÃÂ­n Eduardo Miranda",
"FECHA        : 26/Abril/2013",
"MODIFICACIÃÂN : Se modifica Procedimiento Almacenado para comentar la lÃÂ­nea 'LET pCurp = cCurp'",
"               * Se aplican reglas de programaciÃÂ³n.",
"MOFIDICÃÂ     : Claudio Almodovar",
"FECHA        : 29/10/2014",
"cCodret  200 : parametros vacios para opcion 'S'",
"cCodret  210 : cliente no existe en bdinteg:si_cliente",
"cCodret  220 : cliente no existe en bdinteg:si_ctepf",
"MODIFICACIÃÂN : Se modifica para agregar la opcion 'S' para pFuncion y se comenta donde pFm3 toma valor si es vacio o null";

CREATE PROCEDURE "informix".sp_cons_ref_cop_pba(p_empresa char(3), p_sucursal char(4), p_usuario char(8), p_numcte char(20), p_referencia char(20),p_apellpat char(20),
											p_apellmat char(20),p_nom1 char(20),p_nom2 char(20), p_rfc char(13))
            RETURNING 
            char(5),char(1);

   DEFINE v_codret          char(5);
   DEFINE v_referencia		char(20);
   DEFINE v_apellpat		char(20);
   DEFINE v_apellmat		char(20);
   DEFINE v_nom1			char(20);
   DEFINE v_nom2			char(20);
   DEFINE v_rfc				char(13);
   DEFINE v_result			char(1);
   DEFINE sql_err,isam_err  int;
   DEFINE v_cuantos			int;
 
 -- ****************************************************************************
-- Inicializa variables
-- ****************************************************************************

        let v_codret            = "000";
        let v_referencia        = " ";        
        let v_apellpat          = " ";
		let v_apellmat          = " ";
        let v_nom1         		= " ";
        let v_nom2          	= " ";
		let v_rfc				= " ";
		let v_result			= " ";

--set debug file to "/tmp/sp_cons_ref_cop.txt";
--trace on;

BEGIN
   on exception set sql_err,isam_err
      if sql_err <> 0 or isam_err <> 0 then
         let v_codret = sql_err;
		 let v_result = '1';
         RETURN v_codret,v_result;
      end if;
   end exception;

-- ****************************************************************************
-- Valida la informacion de entrada
-- ****************************************************************************

    IF  p_empresa is null or
        p_referencia is null or 
		p_apellpat is null or
		p_nom1 is null or		
		p_rfc is null
		then
       -- datos de entrada incompletos     
       let v_codret = 110; 
	   let v_result = '1';
       RETURN v_codret,v_result;
    END IF;

-- ****************************************************************************
-- Consultar datos
-- ****************************************************************************

	SELECT COUNT(numcte) INTO v_cuantos FROM bdinteg:si_cliente WHERE numcte_ref = p_referencia;

	IF v_cuantos <= 1 THEN

		IF EXISTS (SELECT numcte_ref FROM bdinteg:si_cliente WHERE numcte_ref = p_referencia) THEN
			SELECT numcte_ref, rfc, nombre1, nombre2, apell_paterno, apell_materno
			INTO v_referencia, v_rfc, v_nom1, v_nom2, v_apellpat, v_apellmat
			FROM bdinteg:si_cliente
			WHERE numcte_ref = p_referencia;
			IF 	TRIM(p_referencia) = TRIM(v_referencia)
				AND TRIM(p_rfc) = TRIM(v_rfc)
				AND TRIM(p_nom1) = TRIM(v_nom1)
				AND TRIM(p_nom2) = TRIM(v_nom2)
				AND TRIM(p_apellpat) = TRIM(v_apellpat)
				AND	TRIM(p_apellmat) = TRIM(v_apellmat)
			THEN
				LET v_codret = '000';
                        LET v_result = '0';
			ELSE
				LET v_codret = '000';
				LET v_result = '1';
				INSERT INTO bdinteg:si_bitacora_refcop(empresa, numcte, numcte_ref, rfc, sucursal, usuario, apell_paterno, apell_materno, nombre1, nombre2, fecha_insert)
					VALUES(p_empresa,p_numcte,p_referencia,p_rfc,p_sucursal, p_usuario,p_apellpat,p_apellmat,p_nom1,p_nom2, CURRENT);
			END IF;
		ELSE
				LET v_codret = '000';
				LET v_result = '0';	
		END IF;
	
	ELSE
		LET v_codret = '000';
		LET v_result = '1';
		INSERT INTO bdinteg:si_bitacora_refcop(empresa, numcte, numcte_ref, rfc, sucursal, usuario, apell_paterno, apell_materno, nombre1, nombre2, fecha_insert)
			VALUES(p_empresa,p_numcte,p_referencia,p_rfc,p_sucursal, p_usuario,p_apellpat,p_apellmat,p_nom1,p_nom2, CURRENT);
	END IF;		
	
	RETURN v_codret,v_result;

END;    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_relacion_generarelacion_pba (pNumCte CHAR(20), pNumCteRef CHAR(20),pNumEmpleado CHAR(10),pTipoRel CHAR(1),pOrigen CHAR(1))
	RETURNING
	CHAR(6)  AS COD_RET, 
	CHAR(80) AS MENSAJE_RETORNO;

-- Modificado por Maria Elena Angulo (AAME). 30 Agosto 2013 Se modifica para comentar la validación que indica que 
--las relaciones por Alta Unica no pueden separarse.	
	
---DECLARACIONES
DEFINE iSqlErr         	INTEGER;
DEFINE iIsamErr        	INTEGER;
DEFINE cErrorInfo      	CHAR(80);
DEFINE cCodRet         	CHAR(6);
DEFINE cMensajeRet     	CHAR(80);

DEFINE cValor     		CHAR(100);
DEFINE iFiltro     		INTEGER;
DEFINE iTipoRel    		INTEGER;
DEFINE iRelacion    	INTEGER;
DEFINE sBanderaAct      SMALLINT;
DEFINE iContador        INTEGER;
DEFINE iSecuencia       INTEGER;

DEFINE cEmpresa         CHAR(3);
DEFINE cNumCteBanco     CHAR(20);  
DEFINE cClienteCoppel   CHAR(20); 
DEFINE cNumEmpleado     CHAR(8);
DEFINE sTipoRelacion    SMALLINT; 
DEFINE cDefinicion      CHAR(10); 
DEFINE cStatus          CHAR(10); 
DEFINE sTipoReIni       SMALLINT; 
DEFINE dFechaInsert     DATE; 
DEFINE cClienteProsp    CHAR(1);
DEFINE cMensaje         CHAR(50);


---INICIALIZACIONES
LET iSqlErr            	= 0;
LET iIsamErr           	= 0;
LET cErrorInfo         	= "";
LET cCodRet            	= "000000";
LET cMensajeRet        	= "PROCESO EXITOSO";   

LET cValor        	= "";   
LET iFiltro        	= 0;   
LET iTipoRel        = 0;   
LET iRelacion       = 0;   
LET sBanderaAct     = 0;
LET iContador       = 0;
LET iSecuencia      = 0;

LET cEmpresa         = "";
LET cNumCteBanco     = "";  
LET cClienteCoppel   = ""; 
LET cNumEmpleado     = ""; 
LET sTipoRelacion    = 0; 
LET cDefinicion      = ""; 
LET cStatus          = ""; 
LET sTipoReIni       = 0; 
LET dFechaInsert     = DATE(1); 
LET cClienteProsp    = "";
LET cMensaje	     = "";
BEGIN
    
    ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
       IF iSqlErr != 0 THEN
          LET cCodRet = iSqlErr;
          LET cMensajeRet = cErrorInfo;
          RETURN TRIM(NVL(cCodRet,'')),TRIM(NVL(cMensajeRet,''));
       END IF;
    END EXCEPTION;

    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;

	--SET DEBUG FILE TO "/respaldosbd/felipe/sp_relacion_generarelacion.out";				 
	--TRACE ON;
	
	-- VALIDA LOS PARAMETROS DE ENTRADA  
	IF NVL(pNumCteRef,"") =  "" AND pTipoRel NOT IN('0','1') THEN
		LET cCodRet = '000001';
		LET cMensajeRet = 'Parametros de entrada incompletos,verifique';
	ELSE
		    IF pTipoRel = '1' AND  pOrigen <> '0' THEN --para obtener si es una relacion 
				LET iFiltro = 43;
				LET iTipoRel = 3;
			ELSE -- o separacion
				LET iFiltro = 44;
				LET iTipoRel = 0;
			END IF;
			IF pOrigen =1 THEN
				LET iTipoRel = 1;
			ELIF pOrigen =3 AND pTipoRel = '1' THEN
				
				SELECT COUNT(cliente)
				INTO iContador
				FROM bdinteg:"informix".si_relacion_ctebcplcpl
				WHERE cliente = pNumCteRef;
				
			END IF;
			IF NVL(iContador,0) = 0 THEN
				
				SELECT  valor 
				INTO cValor
				FROM bdicobranza:"informix".cb_param 
				WHERE empresa = '001' AND descripcion = 'REP_TIPO_RELACION'
				AND cod_param = iFiltro;
			
				SELECT tipo_relacion INTO iRelacion FROM bdinteg:"informix".si_relacion_ctebcplcpl
				WHERE empresa = '001' AND numcte_banco = pNumCte;		
			
				--
				IF iRelacion IS NULL THEN --VALIDACION DEL TIPO DE RELACION SI ES NULA O NO
							INSERT INTO bdinteg:"informix".si_relacion_ctebcplcpl 
							(empresa,numcte_banco,cliente,numempleado,tipo_relacion,definicion,status,tipo_re_ini,fecha_insert)
							VALUES ('001',pNumCte,pNumCteRef,pNumEmpleado,pOrigen,cValor,pTipoRel,0,TODAY);
							LET sBanderaAct = 1;
				ELSE	
						--SE VALIDA SI EL STATUS ES VALIDO PARA REALIZAR LA RELACION
						IF (pTipoRel = '1' AND iRelacion IN (1,2,3))  OR (pTipoRel = '0' AND iRelacion NOT IN (1,2,3)) THEN 
								LET cCodRet = "000002";
								LET cMensajeRet = "Estatus inválido para realizar la consulta";
						ELSE 
							
							/*IF (iRelacion =1) THEN
								LET cCodRet = "000003";
								LET cMensajeRet = "Las relaciones por alta unica no se pueden separar";
							ELSE */ -- AAME. RQM 09 333 Se comenta condicion de que no se pueden separar las relaciones por alta unica 
								IF pOrigen =0 THEN	
									LET pTipoRel = 0;
								END IF;
								
								SELECT MAX(secuencia)
								INTO iSecuencia
								FROM bdinteg:"informix".si_relacion_ctebcplcpl_hist
								WHERE empresa = '001'
								AND numcte_banco = pNumCte;
								
								LET iSecuencia =  NVL(iSecuencia,0) + 1;
								
								SELECT  empresa, numcte_banco,  cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp
								INTO cEmpresa , cNumCteBanco, cClienteCoppel, cNumEmpleado, sTipoRelacion, cDefinicion, cStatus, sTipoReIni, dFechaInsert, cClienteProsp
								FROM bdinteg:"informix".si_relacion_ctebcplcpl
								WHERE empresa = '001'
								AND numcte_banco = pNumCte;
								
								INSERT INTO bdinteg:"informix".si_relacion_ctebcplcpl_hist (empresa, numcte_banco, secuencia, cliente, numempleado, tipo_relacion, definicion, status, tipo_re_ini, fecha_insert, cliente_prosp)
								VALUES (cEmpresa , cNumCteBanco, iSecuencia, cClienteCoppel, cNumEmpleado, sTipoRelacion, cDefinicion, cStatus, sTipoReIni, dFechaInsert, cClienteProsp);
								
								UPDATE  bdinteg:"informix".si_relacion_ctebcplcpl 
									SET numempleado = pNumEmpleado,	
										definicion = cValor,
										status = pTipoRel,
										tipo_re_ini = tipo_relacion,
										tipo_relacion = iTipoRel,
										fecha_insert = TODAY,
										cliente = CASE WHEN pTipoRel = '1' THEN pNumCteRef ELSE "" END
									WHERE empresa = '001'
									AND numcte_banco = pNumCte;	
									LET sBanderaAct = 1;
						  --END IF;	-- AAME. RQM 09 333 Se comenta condicion de que no se pueden separar las relaciones por alta unica 
						END IF;	-- FIN DE VALIDACION DE SI EL STATUS ES VALIDO PARA REALIZAR LA RELACION
				END IF;	--FIN VALIDACION DEL TIPO DE RELACION SI ES NULA O NO
			ELSE
				LET cCodRet = '000003';
				SELECT descripcion INTO cMensaje FROM bdinteg:"informix".si_codret WHERE codigo_retorno = '612' AND sistema = '06'; 
				LET cMensajeRet = TRIM(NVL(cMensaje,''));
			END IF;
	END IF;	--FIN DEL VALIDA LOS PARAMETROS DE ENTRADA
	
	IF sBanderaAct = 1 AND  pOrigen = 3 THEN
		UPDATE bdinteg:"informix".si_cliente SET numcte_ref= CASE WHEN pTipoRel = '1' THEN pNumCteRef ELSE "" END WHERE numcte = pNumCte;	
	END IF;
	
	RETURN TRIM(NVL(cCodRet,'')),TRIM(NVL(cMensajeRet,''));

END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Realiza la Relacion o Separacion de Clientes Coppel con Bancoppel', 
'AUTOR: Jesús Aguilar ',
'FECHA: 26 ABRIL 2012',
'BD: BDINTEG',
'VERSION: 20120426.1641',

'MODIFICACIÓN: Se agregó un UPDATE para que cada vez que se ejecute se actualize la tabla de si_relacion_ctebcplcpl', 'asi como tambien el origen para saber de donde proviene', 
'Modificó: Josué zazueta ',
'FECHA: 11 Junio 2012',
'BD: BDINTEG',
'VERSION: 20120611.1700',

'Modificación',
'DESCRIPCION: Se modifíca para que no regrese nombre del empleado,fecha de relación y numero de referencia en caso', 'de que la el tipo de relacion sea = 0, además  se omite la separación en caso de ser una relación hecha por Alta Única', 
'AUTOR: Josué Remberto Zazueta Acosta ',
'FECHA: 27  de Julio 2012',
'BD: BDINTEG',
'VERSION: 20120727.0518',

'Modificación',
'DESCRIPCION: se agrego consulta de datos del cliente antes de realizar una actualizacion  para guardar un historico de datos del cliente', 
'AUTOR: Felipe Urias ',
'FECHA: 07  de Enero 2015',
'BD: BDINTEG',
'VERSION: 20150107.1538';

CREATE PROCEDURE "informix".sp_reprocesa_cadena_ife() RETURNING	 VARCHAR(5); --Codigo de Retorno

	DEFINE iSqlErr              INTEGER;
    DEFINE sErrParseo           CHAR(5);
    DEFINE iCantReg             INTEGER;
    DEFINE sNumCte              CHAR(9);    
    DEFINE sFecha               DATETIME YEAR TO FRACTION;
    DEFINE sResultado           CHAR(10);
    DEFINE UV_REFLECTANCE       CHAR(4); 
    DEFINE UV_SHAPE             CHAR(4); 
    DEFINE IR_INK               CHAR(4); 
    DEFINE UV_REFLECTANCE_REV   CHAR(4); 
    DEFINE IR_INK_REV           CHAR(4);

    LET iSqlErr             =  0;
    LET sErrParseo          = '';
    LET iCantReg            =  0;
    LET sNumCte             = '';
    LET sFecha              = '';
    LET sResultado          = '';
    LET UV_REFLECTANCE      = '';
    LET UV_SHAPE            = '';
    LET IR_INK              = '';
    LET UV_REFLECTANCE_REV  = '';
    LET IR_INK_REV          = '';

BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr;
			END IF;
		END EXCEPTION;
		
        --SET DEBUG FILE TO '/tmp/anj/sp_reprocesa_cadena_ife.sql';
		--TRACE OFF;

        SELECT trim(valor) INTO iCantReg 
            FROM si_param 
                WHERE cod_param='380';

        FOREACH 
            SELECT LIMIT iCantReg numcte, Fecha 
              INTO sNumCte, sFecha
                FROM si_bitacora_ife
                 where cod_resp_ife='' 
                 --WHERE numcte='038878773'--000001511'
                
--TRACE ON; sp_parsea_cadena_idbx_2
            EXECUTE PROCEDURE sp_parsea_cadena_idbx(sNumCte, sFecha) 
                INTO sErrParseo, sResultado, UV_REFLECTANCE, UV_SHAPE, IR_INK, UV_REFLECTANCE_REV, IR_INK_REV;
--TRACE OFF;
                IF sResultado='Verdadero' THEN
                    UPDATE si_bitacora_ife set cod_resp_ife='1', resultado='Verdadero', causa_rechazo='', test_uv_reflec_anv=UV_REFLECTANCE,
                        test_uv_shape_anv=UV_SHAPE,
                        test_ir_ink_anv=IR_INK,
                        test_uv_reflectance_rev=UV_REFLECTANCE_REV,
                        test_ir_ink_rev=IR_INK_REV
                        WHERE numcte=sNumCte and fecha=sFecha;
                ELIF sResultado='Falso' THEN
                    UPDATE si_bitacora_ife set cod_resp_ife='1', resultado='Falso', causa_rechazo='Menor cantidad de campos en OK', test_uv_reflec_anv=UV_REFLECTANCE,
                        test_uv_shape_anv=UV_SHAPE,
                        test_ir_ink_anv=IR_INK,
                        test_uv_reflectance_rev=UV_REFLECTANCE_REV,
                        test_ir_ink_rev=IR_INK_REV
                        WHERE numcte=sNumCte and fecha=sFecha;
                END IF;
            
        END FOREACH

	RETURN '00000';
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_parsea_cadena_idbx(pnumcte char(9), pFecha DATETIME YEAR TO FRACTION )
	RETURNING CHAR(5) AS CodRet, CHAR(10) AS Resultado,  CHAR(4) AS UV_REFLECTANCE, CHAR(4) AS UV_SHAPE, CHAR(4) AS IR_INK, CHAR(4) AS UV_REFLECTANCE_REV, CHAR(4) AS IR_INK_REV;
--, CHAR(10) AS Resultado,  CHAR(4) AS UV_REFLECTANCE, CHAR(4) AS UV_SHAPE, CHAR(4) AS IR_INK, CHAR(4) AS UV_REFLECTANCE_REV, CHAR(4) AS IR_INK_REV;
	
    DEFINE iSqlErr              INTEGER;	
    DEFINE tPalabra 			LVARCHAR;
	DEFINE i 					INTEGER;
	DEFINE iTamCad 				INTEGER;
	DEFINE iInicioCadena 		INTEGER;
	DEFINE iRecuperarCaracteres INTEGER;
	DEFINE cCaracter 			CHAR(1);	
	DEFINE cPalabra 			LVARCHAR;
	DEFINE sCadena 				CHAR(10000);
	DEFINE sDelimitador 		CHAR(1);
	DEFINE sResultado	 		CHAR(10);
	DEFINE iContOK 				INTEGER;
	DEFINE sMensaje 			CHAR(1000);
    DEFINE sCadenaAux           CHAR(10000);
    DEFINE sCadenaAux2          CHAR(1000);
    DEFINE iAuxParseo           INT;
    DEFINE sCodRet              CHAR(5);
    DEFINE dFecha               DATE;
    DEFINE iVariables           INT;
    DEFINE UV_REFLECTANCE       CHAR(4);
    DEFINE UV_SHAPE             CHAR(4);
    DEFINE IR_INK               CHAR(4);
    DEFINE UV_REFLECTANCE_REV   CHAR(4);
    DEFINE IR_INK_REV           CHAR(4);
	
	LET iSqlErr                      =  0;
    LET tPalabra                     = '';
	LET cCaracter                    = '';
	LET cPalabra                     = '';
	LET iInicioCadena                = 1;
	LET iRecuperarCaracteres         = 0;
	LET sCadena                      ='';
	LET sDelimitador                 ='#';
	LET sResultado                   ='';
	LET iContOK                      =0;
	LET sMensaje                     ='';
    LET sCadenaAux                   ='';
    LET sCadenaAux2                  ='';
    LET iAuxParseo                   =0;
    LET sCodRet                      ='00000';
    LET dFecha                       =current;
    LET iVariables                   = '';
    LET UV_REFLECTANCE               = 'FAIL';
    LET UV_SHAPE                     = 'FAIL';      
    LET IR_INK                       = 'FAIL';      
    LET UV_REFLECTANCE_REV           = 'FAIL';
    LET IR_INK_REV                   = 'FAIL';
	
	BEGIN
		--SET DEBUG FILE TO '/tmp/anj/parsea_idbx.sql';
		--TRACE OFF;
        ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN sCodRet, sResultado, UV_REFLECTANCE, UV_SHAPE, IR_INK, UV_REFLECTANCE_REV, IR_INK_REV;
			END IF;
		END EXCEPTION;

        --INICIA PARSEO CADENA DE ANVERSO
        LET sCadena=(select first 1 cadena_anverso from si_bitacora_ife where numcte=pnumcte and fecha=pFecha);   
		LET iTamCad = LENGTH(TRIM(sCadena));
        
        IF iTamCad>0 THEN
                FOR i IN (1 TO iTamCad) LOOP

                    LET cCaracter = SUBSTR(TRIM(sCadena), i, 1);
                    LET iRecuperarCaracteres = iRecuperarCaracteres + 1;

                    IF cCaracter = sDelimitador THEN
                        LET iRecuperarCaracteres = iRecuperarCaracteres - 1;

                        --TRACE iInicioCadena||' -> '|| iRecuperarCaracteres;
                        LET cPalabra = SUBSTR(TRIM(sCadena), iInicioCadena, iRecuperarCaracteres);
                        LET iInicioCadena = i + 1;
                        LET iRecuperarCaracteres = 0;

                        IF cPalabra <> '' THEN
                            --TRACE ON;
                            IF SUBSTR(TRIM(cpalabra),1,25)='TEST_UV_PAPER_REFLECTANCE' THEN
                                LET iVariables=iVariables+1;
                                IF SUBSTR(TRIM(cpalabra),28,2)="OK" THEN
                                    LET iContOK=iContOK+1;
                                    LET UV_REFLECTANCE='OK';
                                    --UPDATE si_bitacora_ife SET TEST_UV_REFLEC_ANV='OK' WHERE numcte=pnumcte  and fecha=pFecha;
                                ELSE
                                    --UPDATE si_bitacora_ife SET TEST_UV_REFLEC_ANV='FAIL' WHERE numcte=pnumcte  and fecha=pFecha;
                                    LET UV_REFLECTANCE='FAIL';
                                END IF;
                                --TRACE OFF;
                                
                            ELIF SUBSTR(TRIM(cpalabra),1,18)='TEST_UV_TEXT_SHAPE' THEN
                                LET iVariables=iVariables+1;
                                IF SUBSTR(TRIM(cpalabra),21,2)="OK" THEN
                                    LET iContOK=iContOK+1;
                                    LET UV_SHAPE='OK';
                                    --UPDATE si_bitacora_ife SET TEST_UV_SHAPE_ANV='OK' WHERE numcte=pnumcte  and fecha=pFecha;
                                ELSE
                                    --UPDATE si_bitacora_ife SET TEST_UV_SHAPE_ANV='FAIL' WHERE numcte=pnumcte  and fecha=pFecha;
                                    LET UV_SHAPE='FAIL';
                                END IF;
                                
                            ELIF SUBSTR(TRIM(cpalabra),1,11)='TEST_IR_INK' THEN
                                LET iVariables=iVariables+1;
                                IF SUBSTR(TRIM(cpalabra),14,2)="OK" THEN
                                    LET iContOK=iContOK+1;
                                    LET IR_INK='OK';
                                    --UPDATE si_bitacora_ife SET TEST_IR_INK_ANV='OK' WHERE numcte=pnumcte  and fecha=pFecha;
                                ELSE
                                    --UPDATE si_bitacora_ife SET TEST_IR_INK_ANV='FAIL' WHERE numcte=pnumcte  and fecha=pFecha;
                                    LET IR_INK='FAIL';
                                END IF;
                                
                            END IF;
                            --LET sMensaje="EL RESULTADO DE OK ES: " || iContOK;
                            --TRACE OFF;
                        END IF;
                    END IF;

                END LOOP;
                --FIN DEL PARSEO CADENA DE ANVERSO


                --INICIA PARSEO CADENA DE REVERSO
                --TRACE ON;
                LET sCadena=(select first 1 TRIM(cadena_reverso) from si_bitacora_ife where numcte=pnumcte  and fecha=pFecha);
                LET iTamCad = LENGTH(TRIM(sCadena));
                --REINICIANDO VARIABLES
                LET iInicioCadena=1;
                LET iRecuperarCaracteres = 0;
                LET iAuxParseo=0;

                        IF EXISTS(SELECT 1 FROM si_fechas WHERE scadena NOT MATCHES '*:*') THEN
                            FOR i IN (1 TO iTamCad) LOOP 
                                LET cCaracter = SUBSTR(TRIM(sCadena), i, 1);
                                LET iRecuperarCaracteres = iRecuperarCaracteres + 1;

                                IF cCaracter = sDelimitador THEN
                                    LET iRecuperarCaracteres = iRecuperarCaracteres - 1;
                                    LET iAuxParseo=iAuxParseo+1;
                                    --TRACE iInicioCadena||' -> '|| iRecuperarCaracteres;
                                    LET cPalabra = SUBSTR(TRIM(sCadena), iInicioCadena, iRecuperarCaracteres);
                                    LET iInicioCadena = i + 1;
                                    LET iRecuperarCaracteres = 0;

                                    IF iAuxParseo=1 THEN
                                        LET sCadenaAux = 'TYPE: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=2 THEN 
                                        LET sCadenaAux=TRIM(sCadenaAux) || 'SIDE: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=3 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' EXPEDITOR: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=4 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' NATIONALITY: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=5 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' CRC_SECTION: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=6 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' BARCODE_CODE128: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=7 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' TEST_UV_PAPER_REFLECTANCE: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=8 THEN   
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' TEST_IR_INK: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=9 THEN    
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' TEST_IR_FIELDS_VIZ_INK: ' || TRIM(cPalabra) || ' # ';
                                    ELIF iAuxParseo=10 THEN     
                                        LET sCadenaAux=TRIM(sCadenaAux) || ' MODEL_ID: ' || TRIM(cPalabra) || ' # ';
                                    END IF;

                                END IF;

                            END LOOP;
                            
                            LET sCadena=TRIM(sCadenaAux);
                            --TRACE OFF;
                        END IF;


                --LET sCadena=(select first 1 cadena_reverso from si_bitacora_ife where numcte=pnumcte);
                LET iTamCad = LENGTH(TRIM(sCadena));
                FOR i IN (1 TO iTamCad) LOOP

                    LET cCaracter = SUBSTR(TRIM(sCadena), i, 1);
                    LET iRecuperarCaracteres = iRecuperarCaracteres + 1;

                    IF cCaracter = sDelimitador THEN
                        LET iRecuperarCaracteres = iRecuperarCaracteres - 1;

                        --TRACE iInicioCadena||' -> '|| iRecuperarCaracteres;
                        LET cPalabra = SUBSTR(TRIM(sCadena), iInicioCadena, iRecuperarCaracteres);
                        LET iInicioCadena = i + 1;
                        LET iRecuperarCaracteres = 0;

                        IF cPalabra <> '' THEN
                            --TRACE ON;
                            --TEST_UV_PAPER_REFLECTANCE2
                            IF SUBSTR(TRIM(cpalabra),1,25)='TEST_UV_PAPER_REFLECTANCE' THEN
                                LET iVariables=iVariables+1;
                                IF SUBSTR(TRIM(cpalabra),28,2)="OK" THEN
                                    LET iContOK=iContOK+1;
                                    LET UV_REFLECTANCE_REV='OK';
                                    --UPDATE si_bitacora_ife SET TEST_UV_REFLECTANCE_REV='OK' WHERE numcte=pnumcte  and fecha=pFecha;
                                ELSE
                                    --UPDATE si_bitacora_ife SET TEST_UV_REFLECTANCE_REV='FAIL' WHERE numcte=pnumcte  and fecha=pFecha;
                                    LET UV_REFLECTANCE_REV='FAIL';
                                END IF;
                                --TRACE OFF;
                                
                            --TEST_IR_INK2
                            ELIF SUBSTR(TRIM(cpalabra),1,11)='TEST_IR_INK' THEN
                                LET iVariables=iVariables+1;
                                IF SUBSTR(TRIM(cpalabra),14,2)="OK" THEN
                                    LET iContOK=iContOK+1;
                                    LET IR_INK_REV='OK';
                                    --UPDATE si_bitacora_ife SET TEST_IR_INK_REV='OK' WHERE numcte=pnumcte  and fecha=pFecha;
                                ELSE
                                    --UPDATE si_bitacora_ife SET TEST_IR_INK_REV='FAIL' WHERE numcte=pnumcte  and fecha=pFecha;
                                    LET IR_INK_REV='FAIL';
                                END IF;
                                
                            END IF;
                            --LET sMensaje="EL RESULTADO DE OK ES: " || iContOK;
                            --TRACE OFF;
                        END IF;
                    END IF;

                END LOOP;
                --FIN DEL PARSEO CADENA DE REVERSO

                
                IF (iContOK>=3 OR iVariables<5) THEN
                    LET sResultado='Verdadero';
                    /*UPDATE si_bitacora_ife set cod_resp_ife='1', resultado='Verdadero', causa_rechazo='', 
                        test_uv_reflec_anv=UV_REFLECTANCE,
                        test_uv_shape_anv=UV_SHAPE,
                        test_ir_ink_anv=IR_INK,
                        test_uv_reflectance_rev=UV_REFLECTANCE_REV,
                        test_ir_ink_rev=IR_INK_REV
                        WHERE numcte=pnumcte and fecha=pFecha;*/
                    --UPDATE si_bitacora_ife SET resultado='Verdadero', causa_rechazo=''  WHERE numcte=pnumcte  and fecha=pFecha;
                ELSE
                    LET sResultado='Falso';
                    --UPDATE si_bitacora_ife SET resultado='Falso', causa_rechazo='Menor cantidad de campos en OK'  WHERE numcte=pnumcte  and fecha=pFecha;
                END IF;

                /*LET cPalabra = SUBSTR(TRIM(sCadena), iInicioCadena, iRecuperarCaracteres);
                IF cPalabra <> '' THEN
                    
                END IF;*/
        
        END IF;

        RETURN sCodRet, sResultado, UV_REFLECTANCE, UV_SHAPE, IR_INK, UV_REFLECTANCE_REV, IR_INK_REV;
	END;
	
END PROCEDURE;

CREATE PROCEDURE "informix".sp_altamasivaempnet_procesa( pidempresa CHAR(3), pnumcte CHAR(9), pnombrearchivo CHAR(30) )
RETURNING CHAR(5); 
       
    DEFINE viSqlErr     INTEGER;
    DEFINE viIsamErr    INTEGER;
    DEFINE vcDescErr    CHAR(50);
    DEFINE vcCodRet     CHAR(5);
    DEFINE vcCodRet2    CHAR(5);
    DEFINE vcCodRet3    CHAR(50);
    DEFINE vcCodRet4    CHAR(5);
    DEFINE vcCodRet5    CHAR(5);
    DEFINE vcFolio      CHAR(16);
    DEFINE vcMensaje    CHAR(50);
    DEFINE vusuario     CHAR(8);
    DEFINE vcNumEmp     CHAR(3);
    DEFINE viExisteEmp  SMALLINT;
    DEFINE viExisteCte  SMALLINT;
    DEFINE dFechaHoy	DATE;	
    
    LET viSqlErr    = 0;
    LET viIsamErr   = 0;
    LET vcDescErr   = '';
    LET vcCodRet    = '';
    LET vcCodRet2   = '';
    LET vcCodRet3   = '';
    LET vcCodRet4   = '';
    LET vcCodRet5   = '';
    LET vcFolio     = '';
    LET vcMensaje   = '';
    LET vusuario    = USER;
    LET vcNumEmp    = '';
    LET viExisteEmp = 0;
    LET viExisteCte = 0;
    LET dFechaHoy   = '';
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_procesa.out";
    --- TRACE ON;
    
    BEGIN
    
    ON EXCEPTION SET viSqlErr, viIsamErr, vcDescErr
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_procesa.err";
        TRACE ON;
        IF viSqlErr <> 0 THEN
            LET vcCodRet = viSqlErr;
            LET vcCodRet2 = viIsamErr;
            LET vcCodRet3 = vcDescErr;
            RETURN vcCodRet;
        END IF;
    END EXCEPTION;
    
    SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 5;
	
	SELECT fecha_hoy 
      INTO dFechaHoy 
      FROM bdinteg:si_fechas 
     WHERE empresa = '001';
    
    -- // VALIDA EL NUMERO DE EMPRESA
    LET vcNumEmp  = SUBSTR(pNombreArchivo, 2, 3);
        
    IF pidempresa <> vcNumEmp THEN
        LET pidempresa = vcNumEmp;
    END IF;
    
    SELECT COUNT(*)
      INTO viExisteEmp
      FROM bdicheq:sc_nominaempresas 
     WHERE codigo = pidempresa;
     
    IF viExisteEmp = 0 THEN
        LET vcCodRet = '188';
		UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '2', --- NO SE PROCESO NINGUN CLIENTE
               fecha_aplicado = dFechaHoy,
               hora_aplicado = CURRENT HOUR TO SECOND,
               registros_aplic = 0
         WHERE cod_empresa = pidempresa
           AND nombre_archivo = pnombrearchivo;
        RETURN vcCodRet;
    END IF;
    
    -- // VALIDA QUE EL CLIENTE SEA PERSONA MORAL
    SELECT COUNT(cte.numcte)
      INTO viExisteCte
      FROM bdinteg:si_cliente cte
     INNER JOIN bdinteg:si_tipper tpo ON cte.tpo_persona = tpo.tpo_persona
     WHERE cte.empresa = '001'
       AND cte.numcte = pnumcte
       AND tpo.es_fisica = "N";
    
    IF viExisteCte = 0 THEN
		UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '2', --- NO SE PROCESO NINGUN CLIENTE
               fecha_aplicado = dFechaHoy,
               hora_aplicado = CURRENT HOUR TO SECOND,
               registros_aplic = 0
         WHERE cod_empresa = pidempresa
           AND nombre_archivo = pnombrearchivo;
        RETURN vcCodRet;
        LET vcCodRet = '104';
        RETURN vcCodRet;
    END IF;
    
    CALL "informix".sp_altamasivaempnet_carga(pnombrearchivo)
    RETURNING vcCodRet4;
    
    IF vcCodRet4 = '000' THEN        
        CALL "informix".sp_altamasivaempnet_registra(pidempresa, pnumcte, vusuario, pnombrearchivo) 
        RETURNING vcCodRet5, vcMensaje;

        IF vcCodRet5 = '00000' THEN
            LET vcCodRet = '000';
        ELSE
            LET vcCodRet = vcCodRet5;
        END IF
    ELSE
        LET vcCodRet = vcCodRet4;
    END IF;

    RETURN vcCodRet;

    END;

END PROCEDURE;

CREATE PROCEDURE "informix".sp_obt_numcte_status(pEmpresa char(3), pIdUsuario char(20), pUsuario char(50))
                      returning char(5),char(20),smallint;

-- Realizó: Javier Chavez
-- Actividad: Obtener el número y estatus del cliente
-- Solicitó: Mauricio León
-- Fecha:  23/10/2008

--Modificó: Edgar M. Alarcon
--Actividad: valida si recibe id de usuario o numero de cliente
--Solicito: Jose de Jesus
--Fecha: 05-11-15
					
					  
-- ***************************************************************************
-- Define variables
-- ***************************************************************************
   define cod_ret char(5);
   define sql_err integer;
   define v_id_status smallint ;
   define v_num_cte char (20);
   define pNumCte char (20);
-- ***************************************************************************
-- Inicializa variables
-- ***************************************************************************
   let cod_ret       = "000";
   let v_id_status = 0;
   let v_num_cte = "";
   
	--SET DEBUG FILE TO "/home/informix/bibiana/sp_obt_numcte_status.out";
	--TRACE ON;

BEGIN
   on exception set sql_err
      if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret, v_num_cte, v_id_status;
      end if
   end exception;

  IF pIdUsuario <> '' THEN
  
		SELECT numcliente INTO pNumCte FROM bdibpi:"informix".bpi_usuario WHERE id_usuario = pIdUsuario AND st_portal = 'activo'; -- ID_usuario
		
		IF pNumCte = '' OR pNumCte IS NULL THEN
			LET pNumCte = "";
			LET pNumCte = pIdUsuario;
		END IF

        IF EXISTS ( SELECT numcte FROM bdinteg:"informix".si_bpiusuarios  WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN

             SELECT numcte,id_status INTO v_num_cte, v_id_status FROM bdinteg:"informix".si_bpiusuarios WHERE empresa = pEmpresa AND numcte = pNumCte;
			 LET v_num_cte = pNumCte;
             LET cod_ret = '000';

        ELSE

            LET cod_ret = '001';

        END IF ;

  ELSE

        IF EXISTS ( SELECT numcte FROM bdinteg:"informix".si_bpiusuarios  WHERE empresa = pEmpresa AND usuario = pUsuario ) THEN

             SELECT numcte,id_status INTO v_num_cte,v_id_status FROM bdinteg:"informix".si_bpiusuarios WHERE empresa = pEmpresa AND usuario = pUsuario;

             LET cod_ret = '000';

        ELSE

            LET cod_ret = '002';

        END IF ;

  END IF ;
  
  RETURN cod_ret, v_num_cte, v_id_status;

END

END PROCEDURE ;

CREATE PROCEDURE "informix".sps_validapass_bpi(pEmpresa char(3), pIdUsuario char(20))
returning char(5),char(50),smallint,char(26),char(26),char(26),char(26), char(13), char(13), char(13), date, date;

	--Modificó: Edgar M. Alarcon
	--Actividad: valida si recibe id de usuario o numero de cliente
	--Solicito: Jose de Jesus
	--Fecha: 05-11-15
    
    -- ***************************************************************************
    -- Define variables
    -- ***************************************************************************
    define cod_ret char(5);
    define sql_err integer;
    define v_usuario, v_pass, v_pass1, v_pass2, v_pass3 char(50);
    define v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno char(26);
    define v_rfc, v_telefono1, v_telefono2 char(13);
    define v_fecha_nac, v_fecha_actual DATE;
	define sBandera smallint;
	define pNumCte char(20);
	
	--Descripción: Valida Pass
	--22/04/2015
    
    -- ***************************************************************************
    -- Inicializa variables
    -- ***************************************************************************
    let cod_ret = "000";
    let v_usuario = "";
    let v_pass = "";
    let v_pass1 = "";
    let v_pass2 = "";
    let v_pass3 = "";
    let v_nombre1 = "";
    let v_nombre2 = "";
    let v_apell_paterno = "";
    let v_apell_materno = "";
    let v_rfc = "";
    let v_telefono1 = "";
    let v_telefono2 = "";
    let  v_fecha_nac = '01-01-1900';
    let  v_fecha_actual = CURRENT ;
	let sBandera="";
    
	--SET DEBUG FILE TO "/home/informix/bibiana/sps_validapass_bpi.out";
	--TRACE ON;
	
    BEGIN
    
    on exception set sql_err
        if sql_err <> 0 then
            let cod_ret = sql_err;
            return cod_ret, v_usuario, sBandera, v_nombre1, v_nombre2, 
                   v_apell_paterno, v_apell_materno, v_rfc, v_telefono1, v_telefono2,  v_fecha_nac, v_fecha_actual;
        end if
    end exception;
	
	SELECT numcliente INTO pNumCte FROM bdibpi:"informix".bpi_usuario WHERE id_usuario = pIdUsuario AND st_portal = 'activo'; -- ID_usuario
		
		IF pNumCte = '' OR pNumCte IS NULL THEN
			LET pNumCte = "";
			LET pNumCte = pIdUsuario;
		END IF
    
    IF EXISTS ( SELECT numcte FROM bdinteg:"informix".si_bpiusuarios  WHERE empresa = pEmpresa AND numcte = pNumCte ) THEN
        SELECT LIMIT 1 usuario, pass, pass1, pass2, pass3 
          INTO v_usuario, v_pass, v_pass1, v_pass2, v_pass3 
          FROM bdinteg:"informix".si_bpiusuarios 
         WHERE empresa = pEmpresa 
           AND numcte = pNumCte;
		   
		IF (NVL(v_pass1,'') == '' AND NVL(v_pass2,'') == '' AND NVL(v_pass3,'') == '' )THEN
			let sBandera="0";
		ELSE
			let sBandera="1";
		END IF;
		   
        
        SELECT LIMIT 1 nombre1, nombre2, apell_paterno, apell_materno,  rfc
          INTO  v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno, v_rfc
          FROM bdinteg:"informix".si_cliente
         WHERE empresa = pEmpresa
           AND numcte =  pNumCte;

        
        SELECT telefono
          INTO v_telefono1
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 1;
           
        SELECT telefono
          INTO v_telefono2
          FROM bdinteg:"informix".si_telefonos_actual
         WHERE numcte = pNumCte
           AND tipo_tel = 2;
        
        SELECT LIMIT 1 fecha_nac 
          INTO v_fecha_nac 
          FROM bdinteg:"informix".si_ctepf 
         WHERE numcte = pNumCte;
    ELSE
        LET cod_ret = '001';
    END IF;
    
    return cod_ret, nvl(v_usuario,''),sBandera, v_nombre1, v_nombre2, v_apell_paterno, v_apell_materno,
		nvl(v_rfc,''), nvl(v_telefono1,''), nvl(v_telefono2,''),  v_fecha_nac, v_fecha_actual;
    
    END
    
END PROCEDURE
Document
'DESCRIPCION: Sp utilizado en el proceso de validacion de contrasenia en HSM', 
'AUTOR: Ilse Gomez',
'FECHA:26/03/2015',
'BD: BDIBPI';

CREATE PROCEDURE "informix".sp_altamasivaempnet_carga( pNombreArchivo CHAR(30) )
RETURNING CHAR(5);
       
    DEFINE Sql_Err          INTEGER;
    DEFINE Isam_Err         INTEGER;
    DEFINE Desc_Err         CHAR(50);
    DEFINE vCodRet1         CHAR(5);
    DEFINE vCodRet2         CHAR(5);
    DEFINE vCodRet3         CHAR(50);
