    DEFINE vcolonia         CHAR(30);
    DEFINE vdel_mun         CHAR(30);
    DEFINE vciudad          CHAR(30);
    DEFINE vestado          CHAR(30);
    DEFINE vcod_pos         CHAR(10);
    DEFINE vpais            CHAR(4);
    DEFINE vocupacion       CHAR(3);
    
    DEFINE vcValNulos       CHAR(1);
    DEFINE vcValNumeros     CHAR(1);
    DEFINE vcValFechas      CHAR(1);
    DEFINE vcValLetras      CHAR(1);
    DEFINE vcodretint01     SMALLINT;
    DEFINE vcodretint02     SMALLINT;
    DEFINE vcodretint03     SMALLINT;
    DEFINE vcodretint04     SMALLINT;
    DEFINE vcodretint05     SMALLINT;
    DEFINE vcodretint06     SMALLINT;
    DEFINE vcodretint07     SMALLINT;
    DEFINE vcodretint08     SMALLINT;
    DEFINE vcodretint09     SMALLINT;
    DEFINE vcodretint10     SMALLINT;
    DEFINE vcodretint11     SMALLINT;
    DEFINE vcodretint12     SMALLINT;
    DEFINE vcodretint13     SMALLINT;
    DEFINE viExisteCP       SMALLINT;
    
    DEFINE vArchivoCom          CHAR(15);  
    DEFINE vcNombreArchivoVal   CHAR(30);
    
    LET Sql_Err	    = 0;
    LET Isam_Err    = 0;
    LET Desc_Err    = '';
    LET vCodRet1    = '000';
    LET vCodRet2    = '';
    LET vCodRet3    = '';
    LET vRuta       = '';
    LET cSQL        = '';
    LET vdFechaHoy  = '';
    LET vContador1  = 0;
    LET vContador2  = 0;
    LET vComienza   = -1;
    LET vTrxAbierta = 0;
    LET vcNumEmp    = '';
    LET vcExistArch = 0;
    LET vcve_cte    = '';
    LET vnombre1    = '';
    LET vnombre2    = '';
    LET vape_pat    = '';
    LET vape_mat    = '';
    LET vfecha_nac  = '';
    LET vrfc        = '';
    LET vcurp       = '';
    LET vgenero     = '';
    LET vtipo_id    = '';
    LET vnum_id     = '';
    LET vcalle      = '';
    LET vno_ext     = '';
    LET vno_int     = '';
    LET vcolonia    = '';
    LET vdel_mun    = '';
    LET vciudad     = '';
    LET vestado     = '';
    LET vcod_pos    = '';
    LET vpais       = '';
    LET vocupacion  = '';
    
    LET vcValNulos    = '0';
    LET vcValNumeros  = '0';
    LET vcValFechas   = '0';
    LET vcValLetras   = '0';
    LET vcodretint01  = -1;
    LET vcodretint02  = -1;
    LET vcodretint03  = -1;
    LET vcodretint04  = -1;
    LET vcodretint05  = -1;
    LET vcodretint06  = -1;
    LET vcodretint07  = -1;
    LET vcodretint08  = -1;
    LET vcodretint09  = -1;
    LET vcodretint10  = -1;
    LET vcodretint11  = -1;
    LET vcodretint12  = -1;
    LET vcodretint13  = -1;
    LET viExisteCP    = 0;
    
    LET vArchivoCom = 'quitarctrlm.cmd';
    LET vcNombreArchivoVal = TRIM(pNombreArchivo)||'.val'; 
    
    BEGIN
    
    ON EXCEPTION SET Sql_Err, Isam_Err, Desc_Err
        SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_carga.err";
        TRACE ON;
        IF Sql_Err <> 0 THEN
            LET vCodRet1 = Sql_Err;
            LET vCodRet2 = Isam_Err;
            LET vCodRet3 = Desc_Err;
            IF vTrxAbierta = 1 THEN
                ROLLBACK WORK;
            END IF;
            RETURN vCodRet1;
        END IF;
    END EXCEPTION;
    
    --- SET DEBUG FILE TO "/resplogifx/conciliachq/altamasempnet/sp_altamasivaempnet_carga.out";
    --- TRACE ON;
    
    SET ISOLATION TO DIRTY READ; 
    SET LOCK MODE TO WAIT 5; 
    
    IF EXISTS(SELECT dbsname, tabname FROM sysmaster:systabnames WHERE partnum > 0 AND tabname = 'si_altamasivaempnet_tmp') THEN
        DROP TABLE bdinteg:"informix".si_altamasivaempnet_tmp;
    END IF;  
    
    CREATE TABLE bdinteg:"informix".si_altamasivaempnet_tmp  
      ( 
        cve_cte     char(15),
        nombre1     char(30),
        nombre2     char(30),
        ape_pat     char(30),
        ape_mat     char(30),
        fecha_nac   char(8),
        rfc         char(15),
        curp        char(30),
        genero      char(1),
        tipo_id     char(1),
        num_id      char(30),
        calle       char(30),
        no_ext      char(10),
        no_int      char(10),
        colonia     char(30),
        del_mun     char(30),
        ciudad      char(30),
        estado      char(30),
        cod_pos     char(10),
        pais        char(4),
        ocupacion   char(3)
      )
    EXTENT SIZE 128 NEXT SIZE 64 LOCK MODE ROW;
    
    SELECT valor
      INTO vRuta
      FROM bdinteg:si_param
     WHERE empresa = '001'
       AND cod_param = 50;
    
    LET cSQL = '';
    LET cSQL = "sed -f "||TRIM(vRuta)||TRIM(vArchivoCom)||" "||TRIM(vRuta)||TRIM(pNombreArchivo)||" > "||TRIM(vRuta)||TRIM(vcNombreArchivoVal);
    SYSTEM cSQL;
    
    LET cSQL = '';
    LET cSQL = 'echo "LOAD FROM '||TRIM(vRuta)||TRIM(vcNombreArchivoVal)||' INSERT INTO si_altamasivaempnet_tmp" > '||TRIM(vRuta)||'altmasempnet.sql';
    SYSTEM cSQL;
    
    LET cSQL = '';
    LET cSQL = '/ifxsif01/bin/dbaccess bdinteg '||TRIM(vRuta)||'altmasempnet.sql';
    SYSTEM cSQL;
    
    --CREATE INDEX "informix".idx_tmp_altmas ON "informix".si_altamasivaempnet_tmp(cve_cte) ONLINE; 

    ---UPDATE STATISTICS HIGH FOR TABLE si_altamasivaempnet_tmp;
    
    SELECT fecha_hoy
      INTO vdFechaHoy
      FROM bdinteg:si_fechas
     WHERE empresa = '001';
     
    SELECT COUNT(*)
      INTO vContador1
      FROM bdinteg:si_altamasivaempnet_tmp;
      
    IF vContador1 <= 0 THEN
        LET vCodRet1 = '180';
        RETURN vCodRet1;
    END IF;
    
    LET vcNumEmp = SUBSTR(pNombreArchivo, 2, 3);
    
    FOREACH WITH HOLD
        SELECT TRIM(cve_cte), TRIM(nombre1), TRIM(nombre2), TRIM(ape_pat), TRIM(ape_mat), fecha_nac, TRIM(rfc), TRIM(curp), TRIM(genero), tipo_id, 
               TRIM(num_id), TRIM(calle), no_ext, no_int, TRIM(colonia), TRIM(del_mun), TRIM(ciudad), TRIM(estado), TRIM(cod_pos), TRIM(pais), ocupacion 
          INTO vcve_cte, vnombre1, vnombre2, vape_pat, vape_mat, vfecha_nac, vrfc, vcurp, vgenero, vtipo_id,
               vnum_id, vcalle, vno_ext, vno_int, vcolonia, vdel_mun, vciudad, vestado, vcod_pos, vpais, vocupacion 
          FROM bdinteg:si_altamasivaempnet_tmp
          
        IF vcomienza = -1 THEN
            LET vcomienza = 0;
        END IF; 
        
        BEGIN WORK;
        LET vTrxAbierta = 1;
          
        IF ( vno_ext    is null ) OR 
           ( vcve_cte   is null   OR  vcve_cte = ''   ) OR 
           ( vnombre1   is null   OR  vnombre1 = ''   ) OR 
           ( vape_pat   is null   OR  vape_pat = ''   ) OR 
           ( vape_mat   is null   OR  vape_mat = ''   ) OR 
           ( vfecha_nac is null   OR  vfecha_nac = '' ) OR 
           ( vrfc       is null   OR  vrfc = ''       ) OR 
           ( vgenero    is null   OR  vgenero = ''    ) OR 
           ( vtipo_id   is null   OR  vtipo_id = ''   ) OR
           ( vnum_id    is null   OR  vnum_id = ''    ) OR 
           ( vcalle     is null   OR  vcalle = ''     ) OR 
           ( vcolonia   is null   OR  vcolonia = ''   ) OR 
           ( vdel_mun   is null   OR  vdel_mun = ''   ) OR 
           ( vciudad    is null   OR  vciudad = ''    ) OR 
           ( vestado    is null   OR  vestado = ''    ) OR 
           ( vcod_pos   is null   OR  vcod_pos = ''   ) OR 
           ( vpais      is null   OR  vpais = ''      ) THEN 
            LET vcValNulos = '0';
        ELSE
            LET vcValNulos = '1';
        END IF;
        
		IF vcValNulos = '1' THEN
           CALL bdiprog:isnumeric(vno_ext)  RETURNING vcodretint01;
        
           IF ( vcodretint01 <> 1 ) THEN
               LET vcValNumeros = '0';
           ELSE
               LET vcValNumeros = '1';
           END IF;
		END IF;
		
		IF vcValNulos = '1' AND vcValNumeros = '1' THEN
        
           IF NOT ( ( SUBSTR(vfecha_nac, 1, 2) > 0    AND SUBSTR(vfecha_nac, 1, 2) < 32 ) AND 
                  ( SUBSTR(vfecha_nac, 3, 2) > 0    AND SUBSTR(vfecha_nac, 3, 2) < 13 ) AND 
                  ( SUBSTR(vfecha_nac, 5, 4) > 1900 AND SUBSTR(vfecha_nac, 5, 4) < 3000 ) ) THEN
              LET vcValFechas = '0';
           ELSE
              LET vcValFechas = '1';
           END IF;
		END IF;
		
		IF vcValNulos = '1' AND vcValNumeros = '1' AND vcValFechas = '1' THEN
        
           CALL bdiprog:isnumeric(vnombre1) RETURNING vcodretint02;
           CALL bdiprog:isnumeric(vnombre2) RETURNING vcodretint03;
           CALL bdiprog:isnumeric(vape_pat) RETURNING vcodretint04;
           CALL bdiprog:isnumeric(vape_mat) RETURNING vcodretint05;
           CALL bdiprog:isnumeric(vrfc)     RETURNING vcodretint06;
           CALL bdiprog:isnumeric(vgenero)  RETURNING vcodretint07;
           CALL bdiprog:isnumeric(vtipo_id) RETURNING vcodretint08;
           CALL bdiprog:isnumeric(vcalle)   RETURNING vcodretint09;
           CALL bdiprog:isnumeric(vcolonia) RETURNING vcodretint10;
           CALL bdiprog:isnumeric(vdel_mun) RETURNING vcodretint11;
           CALL bdiprog:isnumeric(vciudad)  RETURNING vcodretint12;
           CALL bdiprog:isnumeric(vestado)  RETURNING vcodretint13;
        
           IF ( vcodretint02 <> 0 ) OR ( vcodretint03 <> 0 ) OR ( vcodretint04 <> 0 ) OR ( vcodretint05 <> 0 ) OR ( vcodretint06 <> 0 ) OR ( vcodretint07 <> 0 ) OR 
           ( vcodretint08 <> 0 ) OR ( vcodretint09 <> 0 ) OR ( vcodretint10 <> 0 ) OR ( vcodretint11 <> 0 ) OR ( vcodretint12 <> 0 ) OR ( vcodretint13 <> 0 )  THEN
              LET vcValLetras = '0';
           ELSE
              LET vcValLetras = '1';
           END IF;
		END IF;   
		   
        IF vcValNulos = '1' AND vcValNumeros = '1' AND vcValFechas = '1' AND vcValLetras = '1' THEN
           SELECT COUNT(*)
             INTO viExisteCP
           FROM bdinteg:si_catsepomex
            WHERE d_codigo = vcod_pos
              AND d_asenta = d_asenta;
	    END IF;
        
        IF vcValNulos = '1' AND vcValNumeros = '1' AND vcValFechas = '1' AND vcValLetras = '1' AND viExisteCP > 0 THEN
            INSERT INTO bdinteg:si_altamasivaempnet_det
            ( nombre_archivo, cod_empresa, cve_cte, nombre1, nombre2, ape_pat, ape_mat, fecha_nac, rfc, curp, genero,  
              tipo_id, num_id, calle, no_ext, no_int, colonia, del_mun, ciudad, estado, cod_pos, pais, ocupacion, status, numcte, cuenta, fecha_registro )
            VALUES
            ( pNombreArchivo, vcNumEmp, vcve_cte, vnombre1, vnombre2, vape_pat, vape_mat, vfecha_nac, vrfc, vcurp, vgenero, 
              vtipo_id, vnum_id, vcalle, vno_ext, vno_int, vcolonia, vdel_mun, vciudad, vestado, vcod_pos, vpais, vocupacion, '0', '', '', vdFechaHoy );
        END IF;
          
        COMMIT WORK;
        LET vTrxAbierta = 0;
    END FOREACH;
	
	IF vTrxAbierta = 1 THEN
	   ROLLBACK WORK;
	END IF;
    
    SELECT COUNT(*)
      INTO vContador2
      FROM bdinteg:si_altamasivaempnet_det
     WHERE cod_empresa = vcNumEmp
       AND nombre_archivo = pNombreArchivo;
      
    IF vContador2 > 0 THEN
        UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '1'
         WHERE cod_empresa = vcNumEmp
           AND nombre_archivo = pNombreArchivo;
    ELSE
	    UPDATE bdinteg:si_altamasivaempnet_ctrl
           SET status = '2'
         WHERE cod_empresa = vcNumEmp
           AND nombre_archivo = pNombreArchivo;
    END IF;
    
    END;
    
    RETURN vCodRet1;
    
END PROCEDURE;

CREATE PROCEDURE "informix".sp_msj_ins_huella()
RETURNING VARCHAR(10), varchar(255); 

	DEFINE vfecha	 			DATE;
	DEFINE vfecha_cte 			DATETIME YEAR TO SECOND;
	DEFINE vfecha_tmp 			DATETIME YEAR TO SECOND;
	DEFINE vcuenta_cte			SMALLINT;
	DEFINE vcuenta_tmp			SMALLINT;
	DEFINE vstatus_proc_cte		CHAR(1);
	DEFINE vstatus_proc_tmp		CHAR(1);

	DEFINE vcod_ret              VARCHAR(10); 
	DEFINE sql_err               SMALLINT;
	DEFINE isam_err              SMALLINT;
	DEFINE error_info            CHAR(40);
	
	DEFINE btabla1				CHAR(1);
	DEFINE btabla2				CHAR(1);
	
	DEFINE vreg_ins1			INTEGER;
	DEFINE vreg_ins2			INTEGER;
	DEFINE vreg_ins_tot			INTEGER;
	
	DEFINE vmsgidC				INTEGER;
    DEFINE vmsgidT				INTEGER;
	DEFINE cCodRet              CHAR(5);

	DEFINE vid_cliente 			CHAR(20);
	DEFINE vid_cliente_ulc      CHAR(4);
	
	DEFINE vfecha_pro    		DATETIME YEAR TO FRACTION;
	DEFINE vfecha_pro1    		DATETIME YEAR TO FRACTION;



--Manejo del error
       ON EXCEPTION
		SET sql_err, isam_err, error_info 

		  IF(btabla1 = 'T') THEN DROP TABLE tmp_cte_huella; END IF;	
		  IF(btabla2 = 'T') THEN DROP TABLE tmp_huella_temp; END IF;
		 
           IF sql_err <> 0 THEN
            LET vcod_ret=sql_err;
			
				UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes 
			    	SET(fecha, cod_err, descripcion_err) = (CURRENT, vcod_ret, isam_err||' ' ||error_info)
					WHERE id_sp = '06';  			

            RETURN vcod_ret, isam_err||' ' ||error_info;
           END IF;
       END EXCEPTION;
	   
	--set debug file to "/tmp/sp_msj_ins_huella.out";
	--TRACE ON;		   
	  
	LET vfecha_cte = '';	 
	LET vfecha_tmp = '';
	LET vfecha = '';
	LET	vcuenta_cte = 0;		
	LET	vcuenta_tmp = 0;		
	LET	vstatus_proc_cte = '';	
	LET	vstatus_proc_tmp = '';	

	LET vcod_ret = '000';  
	LET sql_err = 0;   
	LET isam_err = 0;  
	LET error_info = '';
	
	LET btabla1 = 'F';
	LET btabla2 = 'F';
	
	LET vreg_ins1 = 0;	
	LET vreg_ins2 = 0;	
	LET vreg_ins_tot = 0;
	
	LET vmsgidC = 0;
	LET vmsgidT = 0;
	
	LET vid_cliente     = '';
	LET vid_cliente_ulc = '';
	LET vfecha_pro      = '';
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

	SELECT {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } fecha, status_proc 
	  INTO vfecha_cte, vstatus_proc_cte
	  FROM bdinteg:si_ctrl_info_mensajes
	  WHERE id = 'C'
	    AND id_sp = '06';
	  

	SELECT {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } fecha, status_proc 
	  INTO vfecha_tmp, vstatus_proc_tmp
	  FROM bdinteg:si_ctrl_info_mensajes
	  WHERE id = 'T'
		AND  id_sp = '06';  
	
	IF(vstatus_proc_cte = '1' AND vstatus_proc_tmp = '1') THEN
		UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes 
		  SET(fecha, cod_err, descripcion_err) = (CURRENT, vcod_ret, 'PROCESO EN EJECUCION')
		  WHERE id_sp = '06';
	
		RETURN vcod_ret, 'PROCESO EN EJECUCION';
	END IF;
	
	UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes
	  SET status_proc = '1'
	  WHERE  id_sp = '06';

	  
	SELECT {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } sec 
	  INTO vcuenta_cte 
	  FROM bdinteg:si_ctrl_info_mensajes
	  WHERE id = 'C'
		AND id_sp = '06';	
	  
	SELECT {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } sec 
	  INTO vcuenta_tmp 
	  FROM bdinteg:si_ctrl_info_mensajes
	  WHERE id = 'T'
	    AND id_sp = '06';	  

    IF (vcuenta_cte = 0 AND vcuenta_tmp = 0 ) THEN 
			
			LET vfecha = TODAY;
			LET vfecha_cte = TODAY::DATETIME YEAR TO SECOND;
			LET vfecha_tmp = TODAY::DATETIME YEAR TO SECOND;
		
  
	ELSE 
		 SELECT  {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } MAX(fecha)
		   INTO vfecha_cte
		   FROM bdinteg:si_ctrl_info_mensajes
		   WHERE id = 'C'
		     AND id_sp = '06';
		   
		 LET vfecha = vfecha_cte::DATE;  
		 
		 SELECT {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info" ) } (fecha)
		   INTO vfecha_tmp
		   FROM bdinteg:si_ctrl_info_mensajes
		   WHERE id = 'T'
		     AND id_sp = '06';
	END IF	
 
--info si_cte_huella	   
	SELECT
      {+  INDEX(bdinteg:si_cte_huella "ix_huellanew" ) } TRIM(c.numcte) AS id_cliente,  
      NVL(c.fech_ult_camb,c.fecha_alta) AS fecha
	FROM bdinteg:si_cte_huella c
	WHERE  c.numcte is not null
      AND c.secuencia > 1  
      AND c.fecha_alta  >= vfecha 
      AND c.fech_ult_camb >= vfecha_cte 
	  AND c.secuencia = (SELECT MAX(secuencia) FROM bdinteg:si_cte_huella WHERE numcte = c.numcte)	 
	 INTO temp tmp_cte_huella WITH NO LOG; 
	LET btabla1 = 'T';

	
	FOREACH WITH HOLD
	  	SELECT *
	        INTO vid_cliente,vfecha_pro
	        FROM tmp_cte_huella
	  	  WHERE  1=1
			
		LET vid_cliente_ulc = SubStr(vid_cliente,6,10);
		EXECUTE PROCEDURE  bdimnsj:sp_registra_evento 
		( 2,'HUL_MANTTO', vid_cliente,'', '',1, vid_cliente_ulc,'', '', '', '', 0, 0,0, 0, 0, vfecha_pro, '') 
		INTO cCodRet; 
		
         IF (cCodRet = '00000') THEN
		    LET vmsgidC = vmsgidC +1;
		 END IF;
		 
	  	CONTINUE FOREACH;
	  END FOREACH;
  
--info si_huella_temp
	SELECT 
      {+ AVOID_FULL(bdinteg:"informix".si_huella_temp) } TRIM(t.numcte) AS id_cliente,  
      t.fecha_alta AS fecha
	FROM bdinteg:si_huella_temp t	
	WHERE  t.numcte is not null
      AND t.secuencia > 1 
      AND t.fecha_alta >= vfecha_tmp 
	  AND t.secuencia = (SELECT MAX(secuencia) FROM bdinteg:si_huella_temp WHERE numcte = t.numcte)
	ORDER BY fecha_alta ASC
	INTO temp tmp_huella_temp WITH NO LOG;
	LET btabla2 = 'T';
 
 
--generacion de tramas
	FOREACH WITH HOLD
	  	SELECT *
	        INTO vid_cliente,vfecha_pro1
	        FROM tmp_huella_temp
	  	  WHERE  1=1
		
		LET vid_cliente_ulc = SubStr(vid_cliente,6,10);		
		EXECUTE PROCEDURE  bdimnsj:sp_registra_evento 
		( 2,'HUL_MANTTO', vid_cliente,'', '',1, vid_cliente_ulc,'', '', '', '', 0, 0,0, 0, 0, vfecha_pro1, '') 
		INTO cCodRet; 
		
         IF (cCodRet = '00000') THEN
		    LET vmsgidT = vmsgidT +1;
		 END IF;
		 
	  	CONTINUE FOREACH;
	  END FOREACH;


--datos tabla de control
--SELECT MAX(msgid)
--	INTO vmsgid
--	FROM bdinteg:si_ctrl_info_mensajes;
	


SELECT MAX(fecha)
  INTO vfecha_pro
  FROM tmp_cte_huella;
  
	 
SELECT MAX(fecha)
  INTO vfecha_pro1
  FROM tmp_huella_temp;
  
  
 --actualiza tabla de logs
	SELECT COUNT(*) 
	  INTO vreg_ins1
	  FROM tmp_cte_huella;
	  
	SELECT COUNT(*) 
	  INTO vreg_ins2
	  FROM tmp_huella_temp;  
	  
	--LET vreg_ins_tot = vreg_ins1 + vreg_ins2;  
 
	UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes
					SET(fecha, cod_err, descripcion_err,reg_encontrados, reg_enviados) = (CURRENT, vcod_ret, 'PROCESO EXITOSO',vreg_ins1, vmsgidC)
					WHERE id = 'C'
					  AND id_sp = '06';   

	UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes
					SET(fecha, cod_err, descripcion_err,reg_encontrados, reg_enviados) = (CURRENT, vcod_ret, 'PROCESO EXITOSO',vreg_ins2, vmsgidT)
					WHERE id = 'T'
					  AND id_sp = '06'; 					  


		
--borra tablas temporales  
  IF(btabla1 = 'T') THEN DROP TABLE tmp_cte_huella; END IF;	
  IF(btabla2 = 'T') THEN DROP TABLE tmp_huella_temp; END IF;

  
  

					
-- tablas de control  
IF (vfecha_pro IS NOT NULL) THEN
	UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes
		SET (id, fecha, sec, reg_enviados, status_proc) = ('C', vfecha_pro::DATETIME YEAR TO SECOND + INTERVAL (01) SECOND(2) TO SECOND, '1', vmsgidC, '0')
		WHERE id = 'C'
		  AND id_sp = '06';
ELSE 
	UPDATE {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) } bdinteg:si_ctrl_info_mensajes
		SET (status_proc) = ('0'), (fecha) = (vfecha_cte)
		WHERE id = 'C'
		  AND id_sp = '06';
		
END IF;	

IF (vfecha_pro1 IS NOT NULL) THEN  
	UPDATE  {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) }  bdinteg:si_ctrl_info_mensajes
		SET (id, fecha, sec, reg_enviados, status_proc) = ('T', vfecha_pro1::DATETIME YEAR TO SECOND + INTERVAL (01) SECOND(2) TO SECOND, '1', vmsgidT,'0')
		WHERE id = 'T'
		  AND id_sp = '06';
ELSE 
	UPDATE  {+  INDEX(bdinteg:si_ctrl_info_mensajes "idx_id_si_ctrl_info1" ) }  bdinteg:si_ctrl_info_mensajes
		SET (status_proc) = ('0'), (fecha) = (vfecha_tmp)
		WHERE id = 'T'
		  AND id_sp = '06';		
END IF;						


	RETURN vcod_ret, 'PROCESO EXITOSO';
END PROCEDURE;

CREATE PROCEDURE "informix".sp_consultadevcam()
RETURNING CHAR(5)    AS CodigoRetorno,
          CHAR(2)    AS Codigo,
          CHAR(35)   AS Descripcion;
	
    DEFINE cCodRet		CHAR(5);
	DEFINE iSql_Err		INTEGER;
	DEFINE iSam_Err		INTEGER;
	DEFINE cDesc_Err	CHAR(60);
    DEFINE cCodigo		CHAR(2);
    DEFINE cDescripcion	CHAR(35);
	
    LET cCodRet			= "00000";
	LET iSql_Err		= 0;
	LET iSam_Err		= 0;
	LET cDesc_Err		= "";
    LET cCodigo			= "";
    LET cDescripcion	= "";
	
	--SET DEBUG FILE TO "/respaldosbd/IrmaUreta/sp_consultadevcam.out";
	--TRACE ON;
		
	--SET ENVIRONMENT IFX_BATCHEDREAD_INDEX '1';

BEGIN

	ON EXCEPTION SET iSql_Err, iSam_Err, cDesc_Err
		IF iSql_Err <> 0 OR iSam_Err <> 0 THEN
				LET cCodRet = iSql_Err;
				RETURN cCodRet, cCodigo, TRIM(cDescripcion);
		END IF;
	END EXCEPTION;
	
	SET ISOLATION DIRTY READ;
    SET LOCK MODE TO WAIT 3;
	
	-- 
	FOREACH
		SELECT codigo, descripcion INTO cCodigo, cDescripcion
		FROM bdinteg: "informix".si_coddevcam ORDER By codigo ASC
		
		RETURN cCodRet, cCodigo, TRIM(cDescripcion) WITH RESUME;
	END FOREACH;
	
	-- Se verifica si la consulta regreso informacion.
	IF DBINFO("sqlca.sqlerrd2") = 0 THEN
		LET cCodRet = "00001";
		RETURN cCodRet, cCodigo, TRIM(cDescripcion);
	END IF;

END;
END PROCEDURE
DOCUMENT
"AUTOR: Irma Ureta",
"FECHA CREACION: 24 de Diciembre del 2014",
"DESCRIPCION: Consulta código y descripción de devolución.",
"VERSION: 20141221.0317",
"BD: BDINTEG",
"AUTOR: Carolina Verdugo",
"FECHA MODIFICACION : 22/09/2015",
"DESCRIPCION: Se realiza cambió en la consulta para que sea ordenada por el campo código.",
"BD: BDINTEG";

CREATE PROCEDURE "informix".sp_confirmafolio(psucursal CHAR(4), pnumcte CHAR(9), pejecutivo CHAR(8), ptelefono CHAR(10), pRandom CHAR(4))
RETURNING char(5) as codret;
DEFINE iSqlErr			INTEGER;
DEFINE sCodRet          CHAR(5);
DEFINE sNumRnd          INTEGER;
DEFINE sNumRnd2         DECIMAL(10,0);
DEFINE sCodigo          CHAR(4);
DEFINE sCodSp           CHAR(5);

LET sNumRnd     =   0;
LET sNumRnd2    =   0;
LET sCodigo     =   '';
LET sCodRet     =   '';     
LET sCodSp      =   '00000';


BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				RETURN iSqlErr;
			END IF;
    	END EXCEPTION;

    --SET DEBUG FILE TO "/tmp/anj/sp_confirmafolio.SQL";
	--TRACE ON;
	  

      EXECUTE PROCEDURE sp_registra_telefonos('001', pnumcte, ptelefono, 2, '', 0, 1, pejecutivo) INTO sCodRet;

      IF sCodRet="000" THEN
           IF EXISTS(SELECT * FROM si_bitsmstels WHERE numcte<>pnumcte and DATE(fecha)=current) THEN 
               LET sCodRet='00001';
               RETURN sCodRet;
           END IF;

           IF EXISTS(SELECT * FROM si_bitsmstels WHERE numcte=pnumcte AND teclea_ejecut IS NULL) THEN    
                UPDATE si_bitsmstels SET teclea_ejecut='GENERA NUEVO FOLIO', fecha=current where numcte=pnumcte and teclea_ejecut IS NULL;
           END IF;

           INSERT INTO si_bitsmstels(numcte, ejecutivo, sucursal, digito_ver, telefono, fecha) 
                       VALUES(pnumcte, pejecutivo, psucursal, pRandom, ptelefono, current);
           
           EXECUTE PROCEDURE bdimnsj:sp_registra_evento(1,'OFI_AVSMS', 'OFI_CNCEL2','000000000', 'XXXXXXXXXXX','', '1', pRandom, '', pnumcte, '', '', '', '', '', '', '', '', ptelefono, 1, 0, 0, 0, 0,current,current)
               INTO sCodRet;

      ELSE
            RETURN sCodRet;
      END IF;

      RETURN sCodSp;
END
END PROCEDURE;

CREATE PROCEDURE "informix".sp_infosms_cte( pNumCte CHAR(9))
RETURNING CHAR(5) as CodRet, CHAR(9) as NumCte, CHAR(10) as TelCel, CHAR(4) as CodSMS;


DEFINE cCodret   CHAR(5);
DEFINE iSql_err  INTEGER;
DEFINE sNumCte   CHAR(9);
DEFINE sTelCel   CHAR(10);
DEFINE sCodSMS   CHAR(4);

LET cCodret     = '00000';
LET iSql_err    = 0;
LET sNumCte     = '';
LET sTelCel     = '';
LET sCodSMS     = '';


BEGIN
	ON EXCEPTION SET iSql_err
		--LET cCodret = CAST(iSql_err AS CHAR);
		IF iSql_err <> 0 THEN
			LET cCodret = iSql_err;
			RETURN cCodret, sNumCte, sTelCel, sCodSMS;
		END IF;
	END EXCEPTION;	

	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;

    FOREACH
        SELECT FIRST 1 a.numcte, a.telefono, b.digito_ver
          INTO sNumCte, sTelCel, sCodSMS
            FROM bdinteg:si_telefonos_actual a
                LEFT JOIN bdinteg:si_bitsmstels b
                    ON a.numcte=b.numcte AND a.telefono=b.telefono --AND (b.teclea_ejecut IS NULL OR b.bandera='t')
            WHERE a.numcte=pNumCte
                AND a.tipo_tel=2 AND a.status_tel='A'
                ORDER BY b.fecha DESC
    END FOREACH;

	RETURN cCodret, NVL(sNumCte,0), NVL(sTelCel,''), NVL(sCodSMS,'');

END;
END PROCEDURE;

CREATE PROCEDURE "informix".sp_repmttohuella_pba(pFechaIni DATE, pFechaFin DATE, pSucursal CHAR(4), pOpc INT)

RETURNING
--Datos a Regresar--
CHAR(5),    					--Codigo de Retorno
DATETIME YEAR TO SECOND,		--Fecha y Hora de Mantenimiento
CHAR(4),						--No. de Sucursal donde se realizo Mantenimiento
CHAR(9), 						--No. de Cliente al que se realizo mantenimiento
CHAR(108),						--Nombre completo del Cliente (nombre1 + nombre2 + apell_paterno + apell_materno)
CHAR(1),						--Estatus del mantenimiento de la huella
CHAR(20),						--Tipo de identificación con la que se realizo el mantenimiento
CHAR(20),						--Folio de la identificación con la que se realizo el mantenimiento
CHAR(8),						--No. de empleado del promotor que realizo el mantenimiento
CHAR(45),						--Nombre del promotor que realizo el mantenimiento
CHAR(8),						--No. de empleado del Gerente que autorizo el mantenimiento
CHAR(45),						--Nombre del Gerente que autorizo el mantenimiento
CHAR(8),						--No. de empleado del Cajero Principal donde se finaliza el proceso de mantenimiento
CHAR(45),						--Nombre del Cajero Principal donde se finaliza el proceso de mantenimiento
CHAR(40);						--Nombre de Sucursal

--DEFINICION DE VARIABLES--
DEFINE iSql_err 	INTEGER;
DEFINE cCodRet 		CHAR(5);
DEFINE dFechaMtto	DATETIME YEAR TO SECOND;
DEFINE cNumSucur	CHAR(4);
DEFINE cNumCte 		CHAR(9);
DEFINE cNomCte		CHAR(108);
DEFINE cStatus		CHAR(1);
DEFINE cTpoIdent 	CHAR(20);
DEFINE cFolIdent	CHAR(20);
DEFINE cNumProm	 	CHAR(8);
DEFINE cNomProm	 	CHAR(45);
DEFINE cNumGeren 	CHAR(8);
DEFINE cNomGeren	CHAR(45);
DEFINE cNumCajer	CHAR(8);
DEFINE cNomCajer	CHAR(45);
DEFINE cNomSucur	CHAR(40);

--INICIACION DE VARIABLES--
LET iSql_err 	=	0;
LET cCodRet 	=	'0000';
LET dFechaMtto	=	'';
LET cNumSucur	=	'';
LET cNumCte 	=	'';
LET cNomCte		=	'';
LET cStatus		=	'';
LET cTpoIdent 	=	'';
LET cFolIdent	=	'';
LET cNumProm	=	'';
LET cNomProm	=	'';
LET cNumGeren 	=	'';
LET cNomGeren	=	'';
LET cNumCajer	=	'';
LET cNomCajer	=	'';
LET cNomSucur   = 	'';


	--SET DEBUG FILE TO "/tmp/sp_repmttohuella.out";
	--TRACE ON;
	
	BEGIN
	
		ON EXCEPTION SET iSql_err
			IF iSql_err <> 0 THEN
				LET cCodRet = iSql_err;
				RETURN  cCodRet, dFechaMtto, cNumSucur, cNumCte, cNomCte, cStatus, cTpoIdent, cFolIdent, cNumProm,  cNomProm, cNumGeren, cNomGeren, cNumCajer, cNomCajer, cNomSucur;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pOpc = 1 THEN
		
			FOREACH
				SELECT sucursal, nombre INTO cNumSucur, cNomSucur FROM bdinteg:"informix".si_sucursales 
				WHERE tpo_sucursal = 'S' ORDER BY sucursal
				
				LET cCodRet = '0035';
				
				
				RETURN  cCodRet, dFechaMtto, TRIM(NVL(cNumSucur, '')), cNumCte, cNomCte, cStatus, cTpoIdent,  cFolIdent, cNumProm, cNomProm, cNumGeren, cNomGeren, cNumCajer, cNomCajer,  TRIM(NVL(cNomSucur, '')) WITH RESUME;
			
			END FOREACH;
		
		ELSE
				IF TRIM(NVL(pSucursal, '')) = '' THEN
					FOREACH
						
						SELECT {+INDEX(si_huella_temp fecha)} hue.fecha_alta, hue.sucursal, hue.numcte, 
								TRIM(cl.nombre1) || " " || TRIM(cl.nombre2) || " " || TRIM(cl.apell_paterno) || " " || TRIM(cl.apell_materno), 
								hue.status, hue.nueva_ident, hue.num_refer, hue.operador, hue.empleado, hue.usuario3
						INTO dFechaMtto, cNumSucur, cNumCte, cNomCte, cStatus, cTpoIdent, cFolIdent, cNumProm, cNumGeren, cNumCajer
						FROM bdinteg:"informix".si_huella_temp hue, bdinteg:"informix".si_cliente cl
						WHERE hue.numcte=cl.numcte AND hue.fecha_alta::date>=pFechaIni AND hue.fecha_alta::date<=pFechaFin ORDER BY hue.fecha_alta DESC
						
						SELECT nombre 
						INTO cNomProm
						FROM  bdinteg:"informix".si_ejecut  
						WHERE ejecutivo=cNumProm;

						SELECT nombre 
						INTO cNomGeren
						FROM  bdinteg:"informix".si_ejecut 
						WHERE ejecutivo = cNumGeren;

						SELECT nombre 
						INTO cNomCajer
						FROM  bdinteg:"informix".si_ejecut
						WHERE ejecutivo = cNumCajer;
						
						LET cCodRet = '0035';
						
						RETURN  TRIM(NVL(cCodRet, '')), TRIM(NVL(dFechaMtto, '')), TRIM(NVL(cNumSucur, '')), TRIM(NVL(cNumCte, '')), TRIM(NVL(cNomCte, '')), TRIM(NVL(cStatus, '')), TRIM(NVL(cTpoIdent, '')), TRIM(NVL(cFolIdent, '')), TRIM(NVL(cNumProm, '')), TRIM(NVL(cNomProm, '')), TRIM(NVL(cNumGeren, '')), TRIM(NVL(cNomGeren, '')), TRIM(NVL(cNumCajer, '')), TRIM(NVL(cNomCajer, '')), TRIM(NVL(cNomSucur, '')) WITH RESUME;
						
					END FOREACH;
							
				ELSE
					FOREACH
							
						SELECT hue.fecha_alta, hue.sucursal, hue.numcte, 
								TRIM(cl.nombre1) || " " || TRIM(cl.nombre2) || " " || TRIM(cl.apell_paterno) || " " || TRIM(cl.apell_materno), hue.status, hue.nueva_ident, hue.num_refer, hue.operador, hue.empleado, hue.usuario3
						INTO dFechaMtto, cNumSucur, cNumCte, cNomCte, cStatus, cTpoIdent, cFolIdent, cNumProm, cNumGeren, cNumCajer
						FROM bdinteg:"informix".si_huella_temp hue, bdinteg:"informix".si_cliente cl
						WHERE hue.numcte=cl.numcte AND hue.sucursal=pSucursal AND hue.fecha_alta::date>=pFechaIni AND hue.fecha_alta::date<=pFechaFin ORDER BY hue.fecha_alta DESC
						
						SELECT nombre 
						INTO cNomProm
						FROM  bdinteg:"informix".si_ejecut
						WHERE ejecutivo=cNumProm;

						SELECT nombre 
						INTO cNomGeren
						FROM bdinteg:"informix".si_ejecut
						WHERE ejecutivo = cNumGeren;

						SELECT nombre 
						INTO cNomCajer
						FROM bdinteg:"informix".si_ejecut
						WHERE ejecutivo = cNumCajer;
						
						LET cCodRet = '0035';
						
						RETURN  TRIM(NVL(cCodRet, '')), TRIM(NVL(dFechaMtto, '')), TRIM(NVL(cNumSucur, '')), TRIM(NVL(cNumCte, '')), TRIM(NVL(cNomCte, '')), TRIM(NVL(cStatus, '')), TRIM(NVL(cTpoIdent, '')), TRIM(NVL(cFolIdent, '')), TRIM(NVL(cNumProm, '')), TRIM(NVL(cNomProm, '')), TRIM(NVL(cNumGeren, '')), TRIM(NVL(cNomGeren, '')), TRIM(NVL(cNumCajer, '')), TRIM(NVL(cNomCajer, '')), TRIM(NVL(cNomSucur, '')) WITH RESUME;
						
					END FOREACH;
						
				END IF;
		END IF;
		
		IF cCodRet = '0000' THEN
				LET cCodRet = '0001';
				RETURN  TRIM(NVL(cCodRet, '')), TRIM(NVL(dFechaMtto, '')), TRIM(NVL(cNumSucur, '')), TRIM(NVL(cNumCte, '')), TRIM(NVL(cNomCte, '')), TRIM(NVL(cStatus, '')), TRIM(NVL(cTpoIdent, '')), TRIM(NVL(cFolIdent, '')), TRIM(NVL(cNumProm, '')), TRIM(NVL(cNomProm, '')), TRIM(NVL(cNumGeren, '')), TRIM(NVL(cNomGeren, '')), TRIM(NVL(cNumCajer, '')), TRIM(NVL(cNomCajer, '')), TRIM(NVL(cNomSucur, ''));
		END IF;
		

	END


END PROCEDURE
DOCUMENT
'Generacion de un reporte de mantenimiento de huellas por busqueda de sucursal o todas las sucursales',
'Autor : Jesus Horacio Lopez Gonzalez',
'FECHA : 04/06/2013',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_consultaingresoscliente_pba(pTipoOper SMALLINT, pNumCte CHAR(20), pTipoIngres CHAR(1))
	RETURNING 	CHAR(5), CHAR(3), CHAR(20), SMALLINT, CHAR(1), CHAR(60), CHAR (3), CHAR(2), DECIMAL(4,2), CHAR(40), CHAR(60), MONEY(14,2),
				CHAR(8), DATE, INTEGER, INTEGER, INTEGER, INTEGER, INTEGER, INTEGER, INTEGER;

--Definicion de Variables
DEFINE iSqlErr INTEGER;
DEFINE cCodRet CHAR(5);
DEFINE cEmpres CHAR(3);
DEFINE cNumCte CHAR(20);
DEFINE sSecIng SMALLINT;
DEFINE cTipIng CHAR(1);
DEFINE cNomEmp CHAR(60);
DEFINE cPuesto CHAR(3);
DEFINE cPutEsp CHAR(2);
DEFINE dAntigd DECIMAL(4,2);
DEFINE cNomDep CHAR(40);
DEFINE cJefInm CHAR(60);
DEFINE mIngMen MONEY(14,2);
DEFINE cUsrInt CHAR(8);
DEFINE dFecInt DATE;
DEFINE iCvePst INTEGER;
DEFINE iCveOPt INTEGER;
DEFINE iCveSOP INTEGER;
DEFINE iSisCot INTEGER;
DEFINE iNumELa INTEGER;
DEFINE iPerios INTEGER;
DEFINE iTipIEx INTEGER;

--Inicializacion de Variables
LET iSqlErr = 0;
LET cCodRet = '00000';
LET cEmpres = '';
LET cNumCte = '';
LET sSecIng = 0;
LET cTipIng = '';
LET cNomEmp = '';
LET cPuesto = '';
LET cPutEsp = '';
LET dAntigd = 0;
LET cNomDep = '';
LET cJefInm = '';
LET mIngMen = 0;
LET cUsrInt = '';
LET dFecInt = DATE(1);
LET iCvePst = 0;
LET iCveOPt = 0;
LET iCveSOP = 0;
LET iSisCot = 0;
LET iNumELa = 0;
LET iPerios = 0;
LET iTipIEx = 0;

--SET DEBUG FILE TO '/tmp/sp_ConsultaIngresosCliente.out';
--TRACE ON;

BEGIN
	ON EXCEPTION
		SET iSqlErr
		IF iSqlErr <> 0 THEN
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cEmpres, cNumCte, sSecIng, cTipIng, cNomEmp, cPuesto, cPutEsp, dAntigd, cNomDep, cJefInm, mIngMen, cUsrInt, dFecInt, 
			iCvePst, iCveOPt, iCveSOP, iSisCot, iNumELa, iPerios, iTipIEx;
		END IF;
	END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;
	
	IF pNumCte = '' OR pTipoIngres = '' THEN
		LET cCodRet = '00001';
		RETURN cCodRet, cEmpres, cNumCte, sSecIng, cTipIng, cNomEmp, cPuesto, cPutEsp, dAntigd, cNomDep, cJefInm, mIngMen, cUsrInt, dFecInt, 
		iCvePst, iCveOPt, iCveSOP, iSisCot, iNumELa, iPerios, iTipIEx;
	END IF;
	
	
	IF pTipoOper = 1 THEN --Consulta los datos de ingreso del cliente
		IF (SELECT COUNT(sec_ingreso) FROM bdinteg:"informix".si_ingresos WHERE numcte = pNumCte AND tipo_ingreso = pTipoIngres) > 0 THEN
			SELECT empresa, numcte, sec_ingreso, tipo_ingreso, nombre_empresa, puesto, puesto_esp, antiguedad, nombre_depto, jefe_inmediato, ingreso_mensual,
			user_insert, fecha_insert, clavepuesto, claveopcionpuesto, clavesubopcionpuesto, sis_cotiza, num_emp_lab, periosidad, tipo_ingreso_ext
			INTO cEmpres, cNumCte, sSecIng, cTipIng, cNomEmp, cPuesto, cPutEsp, dAntigd, cNomDep, cJefInm, mIngMen, cUsrInt, dFecInt, 
			iCvePst, iCveOPt, iCveSOP, iSisCot, iNumELa, iPerios, iTipIEx
			FROM bdinteg:"informix".si_ingresos 
			WHERE numcte = pNumCte 
			AND sec_ingreso = (SELECT MAX(sec_ingreso) FROM bdinteg:"informix".si_ingresos WHERE numcte = pNumCte AND tipo_ingreso = pTipoIngres)
			AND tipo_ingreso = pTipoIngres;
		ELSE
			LET cCodRet = '00001';
		END IF;
	ELIF pTipoOper = 2 THEN --Colsulta los datos de ingreso del cliente, si no exite, consulta en bitacora.
		IF (SELECT COUNT(sec_ingreso) FROM bdinteg:"informix".si_ingresos WHERE numcte = pNumCte AND tipo_ingreso = pTipoIngres) > 0 THEN
			SELECT empresa, numcte, sec_ingreso, tipo_ingreso, nombre_empresa, puesto, puesto_esp, antiguedad, nombre_depto, jefe_inmediato, ingreso_mensual,
			user_insert, fecha_insert, clavepuesto, claveopcionpuesto, clavesubopcionpuesto, sis_cotiza, num_emp_lab, periosidad, tipo_ingreso_ext
			INTO cEmpres, cNumCte, sSecIng, cTipIng, cNomEmp, cPuesto, cPutEsp, dAntigd, cNomDep, cJefInm, mIngMen, cUsrInt, dFecInt, 
			iCvePst, iCveOPt, iCveSOP, iSisCot, iNumELa, iPerios, iTipIEx
			FROM bdinteg:"informix".si_ingresos 
			WHERE numcte = pNumCte 
			AND sec_ingreso = (SELECT MAX(sec_ingreso) FROM bdinteg:"informix".si_ingresos WHERE numcte = pNumCte AND tipo_ingreso = pTipoIngres)
			AND tipo_ingreso = pTipoIngres;
		ELSE
			SELECT id_act, id_subact INTO iCveOPt, iCveSOP FROM bdinteg:"informix".si_bitacoraapertura 
			WHERE numcte = pNumCte AND id_pregunta = 6
			AND id_secuencia = (SELECT MAX(id_secuencia) FROM bdinteg:"informix".si_bitacoraapertura WHERE numcte = pNumCte AND id_pregunta = 6);
			
			IF NVL(iCveOPt, 0) = 0 OR NVL(iCveSOP, 0) = 0 THEN
				LET iCveOPt = 0;
				LET iCveSOP = 0;
				LET cCodRet = '00001';
			END IF;
		END IF;
		
	END IF;
	
	RETURN cCodRet, cEmpres, cNumCte, sSecIng, cTipIng, cNomEmp, cPuesto, cPutEsp, dAntigd, cNomDep, cJefInm, mIngMen, cUsrInt, dFecInt, 
	iCvePst, iCveOPt, iCveSOP, iSisCot, iNumELa, iPerios, iTipIEx;
	
END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Consulta datos de ingresos del cliente, si no existe informacion consulta en bitacora',
'AUTOR : Adrian Lara I.',
'FECHA : 08 de Julio de 2011',
'VERSION: 20110708.1239',
'BD: bdinteg';

CREATE PROCEDURE "informix".sp_monitor_expediente_ctes_pba2(pEmpresa char(3),  pSucursal CHAR(4),pNumcte CHAR(20),pTipoConsulta SMALLINT,pFechaIni DATE,pFechaFin DATE,pTipoRevision INTEGER, pPaginacion SMALLINT )

RETURNING CHAR(5),    -- Codigo de Retorno
		  CHAR(4),   -- Producto
		  CHAR(20),   -- Numero de Cuenta
          CHAR(20),   -- Nro de Cliente 
		  CHAR(107),  -- Nombre del Cliente
          CHAR(10),   -- Numero de empleado que apertura
		  CHAR(10),   -- Gerente Reviso
		  CHAR(30),   -- Estatus de la revision
		  DATE,       -- Fecha de alta          
          CHAR(250);  -- Observaciones

---DECLARACIONES
DEFINE iSqlErr			INTEGER;
DEFINE iIsamErr			INTEGER;
DEFINE iSecuencia       INTEGER;
DEFINE cErrorInfo		CHAR(80);
DEFINE cCodRet			CHAR(5);
DEFINE cMensajeRet		CHAR(80);

DEFINE cProducto		CHAR(4);
DEFINE cNumCta			CHAR(20);
DEFINE cNumcte			CHAR(20);
DEFINE cNumcteAux		CHAR(20);
DEFINE cNombreCte 		CHAR(120);
DEFINE cEmpAlta 		CHAR(10);
DEFINE cReviso	 		CHAR(10);
DEFINE cStatusRevision 	CHAR(30);
DEFINE dtFechaAlta		DATE;
DEFINE dTFecha			DATE;
DEFINE cObservaciones 	CHAR(100);
DEFINE iBandera 		INTEGER;
DEFINE iDias 		INTEGER;
DEFINE dtFechaHoy 		DATE;
DEFINE dtFechaIni 		DATE;
DEFINE dtFechaFin 		DATE;
DEFINE iStatus 		INTEGER;


---INICIALIZACIONES
LET iSqlErr				= 0;
LET iIsamErr			= 0;
LET iSecuencia			= 0;
LET cErrorInfo			= '';
LET cCodRet				= '00000';
LET cMensajeRet			= 'Proceso Exitoso';

LET cProducto	= '';
LET cNumCta		= '';
LET cNumcte		= '';
LET cNumcteAux	= '';
LET cNombreCte  = '';
LET cEmpAlta    = '';
LET cReviso     = '';
LET cStatusRevision = '';
LET dtFechaAlta		= DATE(1);
LET dTFecha			= DATE(1);
LET cObservaciones  = '';
LET iBandera =  0;
LET iDias =  0;
LET dtFechaHoy =  DATE(1);
LET dtFechaIni =  DATE(1);
LET dtFechaFin =  DATE(1);
LET iStatus =  0;

BEGIN
    ON EXCEPTION SET iSqlErr, iIsamErr
       IF iSqlErr != 0 THEN
          LET cCodRet = iSqlErr;
          RETURN cCodRet, NVL(cProducto,""),NVL(cNumCta,""),NVL(cNumcte,""),NVL(cNombreCte,""),NVL(cEmpAlta,""),NVL(cReviso,"") , NVL(cStatusRevision,""),NVL(dtFechaAlta,DATE(1)),NVL(cObservaciones,"") ;
       END IF;
    END EXCEPTION;
	
	SET LOCK MODE TO WAIT 3;
    SET ISOLATION TO COMMITTED READ LAST COMMITTED;
    
	
SET DEBUG FILE TO "/controlcambios/P-BD-20151221-01/bdinteg/spls/sp_monitor_expediente_ctes_modf.out";
TRACE ON;
    	
	IF NVL(pNumcte,"") <> "" THEN	
		LET pSucursal = "";
	END IF 
	
	
	SELECT fecha_hoy
	INTO dtFechaHoy
	FROM bdicred:"informix".sd_fechas
	WHERE empresa = pEmpresa;
	--consulta todos
	
	SELECT valor
	INTO iDias
	FROM bdicred:"informix".sd_param
	WHERE empresa = pEmpresa
	AND cod_param ='086';
	
	LET dtFechaHoy = dtFechaHoy - iDias;
	
	IF pFechaIni IS NULL THEN
		LET dtFechaIni = dtFechaHoy;
		LET dtFechaFin = TODAY;
	ELSE
		LET dtFechaIni = pFechaIni;
		LET dtFechaFin = pFechaFin;
	END IF;
	
	IF NVL(pSucursal,"") <> "" THEN--va consultar todos los estatus	o el estatus que se mande
		FOREACH WITH HOLD
		SELECT distinct (cte3.numcte),TRIM(cte3.nombre1)||" "||TRIM(cte3.nombre2)||" "||TRIM(cte3.apell_paterno)||" "||TRIM(cte3.apell_materno), cte3.fecha_insert,cte3.user_insert
			INTO cNumcte,cNombreCte,dtFechaAlta,cEmpAlta
			FROM bdinteg:"informix".si_cliente cte3			
			WHERE cte3.empresa = pEmpresa
			AND cte3.numcte >''
			AND cte3.fecha_insert BETWEEN  dtFechaIni and dtFechaFin
			AND cte3.sucursal  = pSucursal
			AND cte3.tipo_cliente = 1
			

			
			LET cReviso     = '';
			LET cStatusRevision = '';
			LET cObservaciones= '';
			LET iStatus= 0;
						
			
			FOREACH WITH HOLD	
				SELECT LIMIT 1 gerente,status_revision, DECODE(status_revision,0,"Sin Revisar",1,"Status OK",2,"Pendiente de Corregir"),observaciones,fecha_insert
				INTO cReviso,iStatus,cStatusRevision,cObservaciones, dTFecha
				FROM bdinteg:"informix".si_reporte_expediente  	
				WHERE empresa = pEmpresa
				AND numcte = cNumcte
				ORDER BY fecha_insert DESC
				
				IF dTFecha < dtFechaHoy THEN
					LET cReviso     = '';
					LET cStatusRevision = '';
				END IF;
				EXIT FOREACH;
			END FOREACH;
			
			IF (iStatus <> pTipoRevision) AND pTipoRevision <> 3  THEN
				CONTINUE FOREACH;
			END IF
			
			IF pTipoConsulta = 1 THEN --CZB
			--Se buscaran las cuentas dadas de alta creditos,Prestamos,debito
				FOREACH WITH HOLD
					SELECT 	sol.num_producto, sol.num_solicitud
						INTO cProducto, cNumCta
					FROM bdisolic:"informix".ss_solicitudes   sol						
					WHERE sol.empresa = pEmpresa
					AND sol.numcte = cNumcte
					AND sol.status_solicitud NOT IN ('PC','AN','AP')
					AND sol.fecha_insert BETWEEN  dtFechaIni and dtFechaFin
					
					LET iBandera = iBandera+1;
				
					IF iBandera <= pPaginacion THEN				
						CONTINUE FOREACH;
					ELSE				
						RETURN cCodRet, NVL(cProducto,""),NVL(cNumCta,""),NVL(cNumcte,""),NVL(cNombreCte,""),NVL(cEmpAlta,""),NVL(cReviso,"") , NVL(cStatusRevision,""),NVL(dtFechaAlta,DATE(1)),NVL(cObservaciones,"") WITH RESUME;
					END IF;	
				END FOREACH 
				FOREACH WITH HOLD--cuentas aperturadas
					SELECT 	sol2.num_producto, sol2.num_solicitud
						INTO cProducto, cNumCta
					FROM bdisolic:"informix".ss_solicitudes   sol2	
					inner join bdinteg:"informix".si_cliente cte4 ON (cte4.empresa = pEmpresa and cte4.numcte = sol2.numcte)						
					WHERE sol2.empresa = pEmpresa
					AND sol2.numcte = cNumcte
					AND sol2.status_solicitud = 'AP'
					AND sol2.sucursal =pSucursal
					AND sol2.num_solicitud IN (SELECT num_solicitud 
										FROM bdisolic:"informix".ss_autorizacion aut
										WHERE  aut.empresa = pEmpresa AND aut.num_solicitud = sol2.num_solicitud AND aut.status_solicitud ='AP' AND aut.fecha_insert BETWEEN  dtFechaIni and dtFechaFin)

										
					LET iBandera = iBandera+1;
				
					IF iBandera <= pPaginacion THEN				
